def _normalize_reason_code(reason: Any, *, default: str = "") -> str:
    try:
        s = str(reason or "").strip().lower()
    except Exception:
        s = ""
    if not s:
        return str(default or "")
    s = s.replace(" ", "_").replace("-", "_").replace(":", "_").replace("/", "_")
    while "__" in s:
        s = s.replace("__", "_")
    return s[:120]

