def _reason_registry_autofill(reason: Any) -> Dict[str, Any]:
    r = _normalize_reason_code(reason)
    if not r:
        return {}
    cur = dict((REASON_REGISTRY or {}).get(r) or {})
    if cur:
        return cur
    spec = dict((_REASON_EXACT_DEFAULTS or {}).get(r) or {})
    if not spec:
        for prefixes, meta in (_REASON_PREFIX_DEFAULTS or []):
            if r.startswith(prefixes):
                spec = dict(meta or {})
                break
    if not spec and r.startswith("planned_and_submitted"):
        spec = {"stage": "EXECUTE", "priority": 1000, "human": "已计划并已提交", "retryable": False}
    if spec:
        spec.setdefault("reason", r)
        try:
            REASON_REGISTRY[r] = dict(spec)
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_1', _e)
            pass
        return dict(spec)
    return {}

def _reason_registry_register(reason: Any, **meta: Any) -> Dict[str, Any]:
    r = _normalize_reason_code(reason)
    if not r:
        return {}
    cur = dict((REASON_REGISTRY or {}).get(r) or {})
    cur.update({k: v for k, v in (meta or {}).items() if v not in (None, "")})
    cur.setdefault("reason", r)
    try:
        REASON_REGISTRY[r] = dict(cur)
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_2', _e)
        pass
    return dict(cur)

def _reason_registry_get(reason: Any) -> Dict[str, Any]:
    r = _normalize_reason_code(reason)
    if not r:
        return {}
    cur = dict((REASON_REGISTRY or {}).get(r) or {})
    if cur:
        return cur
    return _reason_registry_autofill(r)

