def _reason_human_text(reason: Any) -> str:
    try:
        raw = str(reason or "").strip()
    except Exception:
        raw = ""
    if not raw:
        return ""
    norm = _normalize_reason_code(raw)
    if norm == "scan_ok":
        return "扫描完成，数据校验通过"
    reg = _reason_registry_get(norm) if norm else {}
    human = str((reg or {}).get("human") or "").strip()
    if human:
        return human
    if norm in _REASON_ZH_EXTRA:
        return str(_REASON_ZH_EXTRA.get(norm) or "")
    for k, v in (_REASON_ZH_EXTRA or {}).items():
        try:
            if norm.startswith(str(k)):
                return str(v or "")
        except Exception:
            continue
    ru = raw.upper()
    if ru.startswith("A1_REJECT"):
        return "A1最高权限闸门拒绝"
    if ru.startswith("BLOCK_"):
        return "阻断"
    if ru.startswith("SKIP_"):
        return "跳过"
    if ru.startswith("NO_"):
        return "未触发"
    return ""

def _reason_with_zh(reason: Any) -> str:
    try:
        raw = str(reason or "").strip()
    except Exception:
        raw = ""
    if not raw:
        return ""
    if "（" in raw and "）" in raw:
        return raw
    zh = _reason_human_text(raw)
    if not zh:
        return raw
    for sep in (" ", "|", ":"):
        if sep in raw:
            head, tail = raw.split(sep, 1)
            head = str(head or "").strip()
            tail = str(tail or "")
            if head:
                return f"{head}（{zh}）{sep}{tail}"
    return f"{raw}（{zh}）"

def _m9_overclose_human_text(detail: dict | None = None) -> str:
    try:
        d = dict(detail or {})
    except Exception:
        d = {}
    try:
        contract_u = float(d.get('contract_u') or 0.0)
    except Exception:
        contract_u = 0.0
    try:
        actual_u = float(d.get('scope_actual_u') or 0.0)
    except Exception:
        actual_u = 0.0
    try:
        excess_u = float(d.get('scope_delta_excess_u') or max(0.0, actual_u - contract_u))
    except Exception:
        excess_u = max(0.0, actual_u - contract_u)
    layer_id = str(d.get('layer_id') or '').strip()
    grid_id = str(d.get('grid_id') or '').strip()
    tol_u = d.get('tol_u')
    try:
        tol_u_f = float(tol_u) if tol_u is not None else None
    except Exception:
        tol_u_f = None
    parts = [f"【异常】M9检测到越层多平：该次成交不能按正常层平仓记账"]
    if layer_id:
        parts.append(f"层={layer_id}")
    if grid_id:
        parts.append(f"网格={grid_id}")
    parts.append(f"合同={contract_u:.2f}U")
    parts.append(f"实际作用域变化={actual_u:.2f}U")
    parts.append(f"超出={excess_u:.2f}U")
    if tol_u_f is not None:
        parts.append(f"容差={tol_u_f:.2f}U")
    parts.append("请优先检查：layer合同、账本剩余可平值、postcheck作用域")
    return '｜'.join(parts)


def _reason_chain_candidates(obj: Any) -> list[str]:
    try:
        if not isinstance(obj, dict):
            return [str(obj or '').strip()] if str(obj or '').strip() else []
    except Exception:
        return []
    out: list[str] = []
    for key in (
        'final_reason_code', 'final_reason', 'reason_code', 'reason', 'reject_reason', 'block_reason',
        'final_fail_reason', 'queue_reject_reason', 'arb_reject_reason', 'planner_reason', 'trace_reason',
        'detail', 'detail_reason', 'final_code', 'code', 'queue_reject_code'
    ):
        try:
            raw = str(obj.get(key) or '').strip()
        except Exception:
            raw = ''
        norm = _normalize_reason_code(raw)
        if (not raw) or norm in ('', 'unknown', 'none', 'null', 'internal_reason_missing', 'internal_reason_chain_broken') or ('INTERNAL_REASON_CHAIN_BROKEN' in raw.upper()):
            continue
        out.append(raw)
    return out

def _reason_chain_pick_best(*objs: Any) -> str:
    best_raw = ''
    best_pri = -1
    for obj in objs:
        for raw in _reason_chain_candidates(obj):
            pri = _final_reason_priority(raw)
            if pri > best_pri:
                best_raw = str(raw)
                best_pri = pri
    return str(best_raw or '')

def _result_with_zh(result: Any) -> str:
    try:
        raw = str(result or "").strip()
    except Exception:
        raw = ""
    if not raw:
        return ""
    if "（" in raw and "）" in raw:
        return raw
    zh = _reason_human_text(raw)
    if not zh:
        ru = raw.strip().upper()
        result_map = {
            "ACCEPT": "已接受",
            "ACCEPTED": "已接受",
            "REJECT": "已拒绝",
            "REJECTED": "已拒绝",
            "SKIP": "已跳过",
            "SKIPPED": "已跳过",
            "OK": "通过",
            "PASS": "通过",
            "DONE": "完成",
            "SUCCESS": "成功",
            "FAIL": "失败",
            "FAILED": "失败",
            "TRUE": "是",
            "FALSE": "否",
        }
        zh = result_map.get(ru, "")
    return f"{raw}（{zh}）" if zh else raw

def _reason_annotate_for_output(obj: Any):
    try:
        if isinstance(obj, dict):
            out = {}
            reason_keys = {
                "reason", "reject_reason", "final_reason", "block_reason", "queue_reject_reason", "arb_reject_reason",
                "first_block_reason", "req_drop_last_reason", "last_plan_reason", "planner_reason", "trace_reason",
                "reject_code", "queue_reject_code", "arb_reject_code", "reason_code", "code", "final_code",
                "final_block_code", "queue_code", "arb_code", "result_code",
            }
            result_keys = {
                "result", "final_result", "queue_result", "arb_result", "status", "final_status", "exec_status",
                "decision", "outcome", "confirmation_state", "submit_state", "postcheck_state",
            }
            for k, v in obj.items():
                ks = str(k or "")
                if isinstance(v, str) and ks in reason_keys:
                    out[k] = _reason_with_zh(v)
                elif isinstance(v, str) and ks in result_keys:
                    out[k] = _result_with_zh(v)
                else:
                    out[k] = _reason_annotate_for_output(v)
            return out
        if isinstance(obj, list):
            return [_reason_annotate_for_output(x) for x in obj]
        if isinstance(obj, tuple):
            return tuple(_reason_annotate_for_output(x) for x in obj)
    except Exception:
        return obj
    return obj

def _primary_reason_for_output(entry: Any, *, default: str = "NO_REQUEST") -> str:
    """主展示原因只读 final 字段；其他来源仅作极窄兼容兜底。"""
    try:
        d = dict(entry or {}) if isinstance(entry, dict) else {"reason": str(entry or "")}
    except Exception:
        d = {"reason": str(entry or "")}
    for k in ("final_reason_code", "final_reason"):
        try:
            raw = str(d.get(k) or "").strip()
        except Exception:
            raw = ""
        if not raw:
            continue
        norm = _normalize_reason_code(raw)
        if norm and (not norm.startswith("unknown")):
            return norm
    try:
        ev = d.get("execution_evidence") if isinstance(d.get("execution_evidence"), dict) else {}
        ev_reason = _normalize_reason_code((ev or {}).get("final_confirmation_code") or (ev or {}).get("final_state") or "")
        if ev_reason and (not ev_reason.startswith("unknown")):
            return str(ev_reason)
    except Exception as _e:
        _record_swallowed_exception("primary_reason_for_output.execution_evidence", _e)
    try:
        plan_state = str(d.get("plan_state") or "").strip()
    except Exception:
        plan_state = ""
    if _reason_is_explicit_idle(default):
        return str(default)
    if _reason_is_explicit_idle(plan_state):
        return _normalize_reason_code(plan_state, default="idle_skip_not_due")
    try:
        verdict = str(d.get("final_verdict") or "").upper().strip()
    except Exception:
        verdict = ""
    if verdict == "EXECUTED":
        return "confirmed_success"
    if verdict == "PENDING_CONFIRM":
        return "submitted_pending_confirm"
    if verdict == "NO_REQUEST":
        return "NO_REQUEST"
    try:
        raw = str(d.get("reason_code") or d.get("reason") or default or "NO_REQUEST").strip()
    except Exception:
        raw = str(default or "NO_REQUEST")
    norm = _normalize_reason_code(raw, default=str(default or "NO_REQUEST"))
    return str(norm or default or "NO_REQUEST")

def _record_reason_chain_broken(reason: str = "") -> None:
    try:
        rep = globals().setdefault("SELFTEST_REPORT", {})
        rep["reason_chain_broken"] = int(rep.get("reason_chain_broken") or 0) + 1
        if reason:
            rep["last_reason_chain_broken"] = str(reason)[:240]
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_3', _e)
        pass
def _final_fields_for_output(entry: Any, *, default_reason: str = "NO_REQUEST", default_stage: str = "", default_verdict: str = "") -> dict:
    try:
        d = dict(entry or {}) if isinstance(entry, dict) else {}
    except Exception:
        d = {}
    reason = _primary_reason_for_output(d, default=default_reason)
    stage = str(d.get("final_stage") or d.get("stage") or d.get("planner_stage") or default_stage or _reason_stage_guess(reason, default="PLANNER")).upper().strip()
    if d.get("final_verdict") or default_verdict:
        verdict = str(d.get("final_verdict") or default_verdict).upper().strip()
    elif reason in ("selected", "arbitration_accepted"):
        verdict = "ACCEPTED"
    elif reason in ("confirmed_success",) or str(reason).startswith(("confirm_", "confirmed_")):
        verdict = "EXECUTED"
    elif reason in ("submitted_pending_confirm", "fill_seen_pending_confirm", "submitted_unchecked") or str(reason).startswith("planned_and_submitted"):
        verdict = "PENDING_CONFIRM"
    elif reason == "NO_REQUEST":
        verdict = "NO_REQUEST"
    else:
        verdict = "REJECTED"
    return {
        "final_reason": str(reason or default_reason or "NO_REQUEST"),
        "final_reason_code": str(reason or default_reason or "NO_REQUEST"),
        "final_stage": stage,
        "final_verdict": verdict,
    }

def _reason_stage_guess(reason: Any, *, default: str = "PLANNER") -> str:
    r = _normalize_reason_code(reason, default=default)
    if not r:
        return str(default or "PLANNER")
    reg = _reason_registry_get(r)
    if reg.get("stage"):
        return str(reg.get("stage") or default or "PLANNER")
    if r.startswith(("scan_", "data_", "dq_", "m2_", "planner_not_executed_due_to_scan_timeout")):
        return "SCAN"
    if r.startswith(("amount_", "amt_")) or r in ("u_0", "u<=0", "amount_not_mapped", "amount_zero", "amount_invalid"):
        return "AMOUNT"
    if r.startswith(("grid_", "tp_", "trend_")) or r in ("start_loss_not_reached", "no_candidate_generated"):
        return "GRID_GATE" if r.startswith("grid_") else ("TP" if r.startswith("tp_") else ("TREND" if r.startswith("trend_") else "PLANNER"))
    if r.startswith(("rsi_", "adx_", "hardcap_", "round_exec_cap_", "coin_paused", "cold_start_")):
        return "ELIGIBILITY"
    if r.startswith(("planned_and_submitted", "submit_", "submitted_", "execute_", "confirm_", "confirmed_", "fill_seen_")):
        return "EXECUTE"
    if r in ("allowed_leg_seen_but_no_candidate", "no_leg_entered", "no_rsi_allowed_real_leg", "not_planned_yet"):
        return "PLANNER"
    return str(default or "PLANNER")

def _final_reason_priority(reason: Any) -> int:
    r = _normalize_reason_code(reason)
    if not r:
        return 0
    reg = _reason_registry_get(r)
    if reg.get("priority") is not None:
        try:
            return int(reg.get("priority") or 0)
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_4', _e)
            pass
    if r in ("state_source_mismatch", "layer_id_discontinuity", "gap_anchor_mismatch", "first_layer_expected_but_gap_checked",
             "non_first_layer_wrongly_cold_started", "not_cold_start_without_anchor", "cold_start_bypass_missing") or r.startswith(("exec_submit_fail", "submit_failed", "execute_", "confirm_")):
        return 120
    if r.startswith(("scan_", "planner_not_executed_due_to_scan_timeout", "dq_", "data_", "m2_")):
        return 110
    if r.startswith(("hardcap_block", "grid_risk_block", "budget_block", "cooldown_", "coin_paused", "pause_")) or r in ("grid_risk_block_hourly_limit", "grid_risk_block_daily_limit", "grid_risk_block_consec_limit"):
        return 100
    if r in ("non_m9_layer_block", "l1_base_layer_block", "non_grid_source_block"):
        return 95
    if r in ("amount_not_mapped", "amount_zero", "amount_invalid", "u_0", "u<=0") or r.startswith(("amount_", "amt_", "submit_cap_block")):
        return 90
    if r in ("rsi_side_block", "rsi_fetch_fail", "rsi_double_read_mismatch", "rsi_stale_30s") or r.startswith(("rsi_",)):
        return 80
    if r in ("grid_gap_not_reached", "tp_gap_not_reached") or r.startswith(("grid_", "trend_", "tp_")):
        return 70
    if r.startswith("cold_start_"):
        return 60
    if r in ("confirmed_success",) or r.startswith(("confirm_", "confirmed_")):
        return 1005
    if r in ("submitted_pending_confirm", "fill_seen_pending_confirm", "submitted_unchecked") or r.startswith(("planned_and_submitted", "submitted_", "fill_seen_")):
        return 98
    if r in ("allowed_leg_seen_but_no_candidate", "no_candidate_generated", "not_planned_yet", "no_leg_entered", "no_rsi_allowed_real_leg", "no_request", "not_triggered_or_filtered"):
        return 10
    return 50

def _pick_stronger_reason(*reasons: Any) -> str:
    best = ""
    best_p = -1
    for reason in reasons:
        r = _normalize_reason_code(reason)
        if not r:
            continue
        p = _final_reason_priority(r)
        if p > best_p:
            best = str(reason)
            best_p = p
    return best

def _extract_last_plan_for_coin(plans: Any, coin: str) -> dict:
    coin_u = str(coin or "").upper().strip()
    if not isinstance(plans, list) or not coin_u:
        return {}
    last = {}
    for p in plans:
        try:
            if isinstance(p, dict) and str(p.get("coin") or "").upper().strip() == coin_u:
                last = p
        except Exception:
            continue
    return dict(last or {})

def _reason_from_any(val: Any) -> str:
    try:
        if isinstance(val, dict):
            for k in ("final_reason", "reason", "reject_reason", "block_reason", "reason_code", "gate_reason_code", "hardcap_precheck_reason"):
                v = str(val.get(k) or "").strip()
                if v:
                    return v
            return ""
        return str(val or "").strip()
    except Exception:
        return ""

def _reason_is_explicit_idle(reason: Any) -> bool:
    r = _normalize_reason_code(reason)
    if not r:
        return False
    if r in ("idle_skip_not_due", "round_not_due", "scan_not_ready", "trade_disabled", "module_disabled", "not_due", "bootstrap_pending"):
        return True
    return r.startswith(("idle_", "standby:", "skip:"))

def _reason_is_placeholder_fallback(reason: Any) -> bool:
    r = _normalize_reason_code(reason)
    if not r:
        return False
    if r in ("internal_reason_chain_broken", "chain_broken"):
        return True
    return r.startswith(("internal_reason_missing", "internal_reason_chain_broken_"))

def _detect_force_tp_chain_reason(entry: Any, *, plans: Any = None) -> tuple[str, str, str]:
    try:
        d = dict(entry or {}) if isinstance(entry, dict) else {}
    except Exception:
        d = {}
    coin_u = str(d.get("coin") or "").upper().strip()
    last_plan = _extract_last_plan_for_coin(plans, coin_u) if coin_u and plans is not None else (d.get("last_plan") if isinstance(d.get("last_plan"), dict) else {})

    def _inspect(obj: Any, src: str = "") -> tuple[str, str, str]:
        if not isinstance(obj, dict):
            return ("", "", "")
        meta = obj.get("meta") if isinstance(obj.get("meta"), dict) else {}
        rr = _normalize_reason_code(
            obj.get("reason")
            or obj.get("reason_code")
            or obj.get("block_reason")
            or obj.get("reject_reason")
            or meta.get("tp_force_reason")
            or meta.get("reason")
            or meta.get("reason_code")
            or ""
        )
        force_flag = bool(obj.get("force_tp") or obj.get("tp_force") or meta.get("force_tp") or meta.get("tp_force") or meta.get("safe_reduce"))
        if not force_flag and rr not in ("tp_hit_plans_empty_force_decrease", "force_tp_not_enqueued", "force_tp_blocked"):
            return ("", "", "")
        if rr in ("", "NO_REQUEST", "no_request"):
            rr = "tp_hit_plans_empty_force_decrease"
        stage = str(obj.get("stage") or meta.get("stage") or "TP").upper().strip() or "TP"
        return (rr, stage, str(src or "force_tp"))

    for src_name, obj in (("entry", d), ("entry.meta", d.get("meta") if isinstance(d.get("meta"), dict) else {}), ("last_plan", last_plan)):
        rr, stage, src = _inspect(obj, src_name)
        if rr:
            return rr, stage, src
    hist = d.get("reason_history") if isinstance(d.get("reason_history"), list) else []
    for it in hist:
        rr, stage, src = _inspect(it, "reason_history")
        if rr:
            return rr, stage, src
    req_drop_events = d.get("req_drop_events") if isinstance(d.get("req_drop_events"), list) else []
    for it in req_drop_events:
        rr, stage, src = _inspect(it, "req_drop")
        if rr:
            rr = _normalize_reason_code(rr or "") or "force_tp_blocked"
            if rr == "tp_hit_plans_empty_force_decrease":
                rr = "force_tp_blocked"
            return rr, stage or "TP", src
    return ("", "", "")

def _req_is_m10_koujing_group(req_any: Any) -> bool:
    try:
        reqd = _req_get_dict(req_any) if '_req_get_dict' in globals() else (req_any.to_dict() if hasattr(req_any, 'to_dict') else (dict(req_any) if isinstance(req_any, dict) else {}))
    except Exception:
        reqd = {}
    try:
        mod = str((reqd or {}).get('module') or '').upper().strip()
        act = str((reqd or {}).get('action_type') or (reqd or {}).get('action') or '').lower().strip()
    except Exception:
        mod = ''
        act = ''
    return bool(mod == 'M10' and act in ('koujing_a_3step', 'reopen_after_tp'))

def _m10_pack_isolated_executor_rows(rows: Any) -> list:
    src_rows = list(rows or []) if isinstance(rows, list) else []
    if not src_rows:
        return []
    parent = None
    child_rows = []
    for row in src_rows:
        if not isinstance(row, dict):
            continue
        reqd = row.get('req') if isinstance(row.get('req'), dict) else {}
        meta = reqd.get('meta') if isinstance(reqd.get('meta'), dict) else {}
        if bool((meta or {}).get('m10_parent_aggregate_only')):
            parent = dict(row)
            continue
        if bool(row.get('child_step')) or bool((meta or {}).get('m10_step_subrecord')):
            child_rows.append(dict(row))
    if parent is None:
        if len(src_rows) == 1 and isinstance(src_rows[0], dict):
            return [dict(src_rows[0])]
        return src_rows
    try:
        parent_req = parent.get('req') if isinstance(parent.get('req'), dict) else {}
        parent_meta = dict(parent_req.get('meta') or {}) if isinstance(parent_req.get('meta'), dict) else {}
        parent_meta['m10_parent_aggregate_only'] = 1
        parent_meta['m10_child_step_count'] = int(len(child_rows))
        parent_req['meta'] = parent_meta
        parent['req'] = parent_req
    except Exception:
        pass
    try:
        if child_rows:
            parent['m10_step_rows'] = list(child_rows)
            detail = parent.get('detail') if isinstance(parent.get('detail'), dict) else {}
            detail = dict(detail or {})
            detail['m10_step_rows'] = list(child_rows)
            parent['detail'] = detail
    except Exception:
        pass
    return [parent]

def _m10_extract_child_rows(exec_res_list: Any) -> list[dict]:
    out: list[dict] = []
    for row in list(exec_res_list or []):
        if not isinstance(row, dict):
            continue
        reqd = row.get('req') if isinstance(row.get('req'), dict) else {}
        meta = reqd.get('meta') if isinstance(reqd.get('meta'), dict) else {}
        embedded = row.get('m10_step_rows')
        if not isinstance(embedded, list):
            detail = row.get('detail') if isinstance(row.get('detail'), dict) else {}
            embedded = detail.get('m10_step_rows') if isinstance(detail, dict) else []
        if isinstance(embedded, list) and embedded:
            for _idx, child in enumerate(list(embedded or []), start=1):
                if not isinstance(child, dict):
                    continue
                child_d = dict(child)
                try:
                    _rq = child_d.get('req') if isinstance(child_d.get('req'), dict) else {}
                    _rqm = _rq.get('meta') if isinstance(_rq.get('meta'), dict) else {}
                    if not child_d.get('step_no'):
                        child_d['step_no'] = int((_rqm.get('m10_step_no') or _idx) or _idx)
                except Exception:
                    pass
                out.append(child_d)
            continue
        if bool((meta or {}).get('m10_parent_aggregate_only')):
            continue
        if bool(row.get('child_step')) or bool((meta or {}).get('m10_step_subrecord')):
            out.append(dict(row))
    return out

def _record_internal_guard(kind: str, detail: Any = None) -> None:
    try:
        rep = globals().setdefault("SELFTEST_REPORT", {})
        guards = rep.setdefault("internal_guards", {})
        k = str(kind or "unknown").strip() or "unknown"
        guards[k] = int(guards.get(k) or 0) + 1
        if detail not in (None, ""):
            rep["last_internal_guard"] = {"kind": k, "detail": str(detail)[:240]}
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_5', _e)
        pass
def _record_swallowed_exception(kind: str, exc: Any = None, detail: Any = None, **kwargs: Any) -> None:
    try:
        bits = [str(kind or "swallowed_exception").strip() or "swallowed_exception"]
        if exc not in (None, ""):
            bits.append(f"exc={type(exc).__name__}:{str(exc)[:120]}")
        if detail not in (None, ""):
            bits.append(f"detail={str(detail)[:120]}")
        if kwargs:
            try:
                extra = ", ".join(f"{str(k)}={str(v)[:80]}" for k, v in sorted((kwargs or {}).items(), key=lambda kv: str(kv[0])))
            except Exception:
                extra = str(kwargs)[:160]
            if extra:
                bits.append(f"extra={extra}")
        _record_internal_guard("swallowed_exception", " | ".join(bits))
    except Exception:
        pass
def _record_terminal_decision(kind: str, reason: Any = "", stage: Any = "", detail: Any = None) -> None:
    try:
        rr = _normalize_reason_code(reason, default=str(reason or ""))
    except Exception:
        rr = str(reason or "")
    try:
        st = str(stage or _reason_stage_guess(rr, default="SUMMARY") or "SUMMARY").upper().strip()
    except Exception:
        st = str(stage or "SUMMARY").upper().strip() or "SUMMARY"
    payload = f"{str(kind or 'terminal')}|{st}|{str(rr or 'unknown')[:160]}"
    if detail not in (None, ""):
        payload += f"|{str(detail)[:160]}"
    _record_internal_guard("terminal_decision", payload)

def _coerce_positive_float_or_none(val: Any, *, tag: str = "") -> float | None:
    try:
        if val in (None, ""):
            return None
        out = float(val)
        if out != out:
            _record_internal_guard("nan_float_block", tag)
            return None
        return out
    except Exception:
        _record_internal_guard("float_cast_failed", tag)
        return None

def _entry_confirm_truth_reason(entry: Any, *, plans: Any = None) -> str:
    """执行成功真相只认 execution_evidence；其他来源不再反推主真相。"""
    try:
        d = dict(entry or {}) if isinstance(entry, dict) else {}
    except Exception:
        d = {}
    try:
        ev = d.get("execution_evidence") if isinstance(d.get("execution_evidence"), dict) else {}
        ev_state = _normalize_reason_code((ev or {}).get("final_confirmation_code") or (ev or {}).get("final_state") or "")
        if ev_state in ("confirmed_success",) or str(ev_state).startswith(("confirm_", "confirmed_")):
            return str(ev_state or "confirmed_success")
    except Exception as _e:
        _record_swallowed_exception("entry_confirm_truth.execution_evidence", _e)
    return ""

def _entry_submit_truth_reason(entry: Any, *, plans: Any = None) -> str:
    """提交待确认真相只认 execution_evidence；不再从 history/last_plan 反推。"""
    try:
        d = dict(entry or {}) if isinstance(entry, dict) else {}
    except Exception:
        d = {}
    try:
        ev = d.get("execution_evidence") if isinstance(d.get("execution_evidence"), dict) else {}
        ev_state = _normalize_reason_code((ev or {}).get("final_confirmation_code") or (ev or {}).get("final_state") or "")
        if ev_state in ("submitted_pending_confirm", "fill_seen_pending_confirm", "submitted_unchecked") or str(ev_state).startswith(("planned_and_submitted", "submitted_", "fill_seen_")):
            return str(ev_state or "submitted_pending_confirm")
    except Exception as _e:
        _record_swallowed_exception("entry_submit_truth.execution_evidence", _e)
    return ""

def _entry_has_execution_truth(entry: Any, *, plans: Any = None) -> bool:
    try:
        d = dict(entry or {}) if isinstance(entry, dict) else {}
    except Exception:
        d = {}
    ev = d.get("execution_evidence") if isinstance(d.get("execution_evidence"), dict) else {}
    state = _normalize_reason_code((ev or {}).get("final_confirmation_code") or (ev or {}).get("final_state") or "")
    return bool(state in ("confirmed_success",) or str(state).startswith(("confirm_", "confirmed_")))

def _entry_reason_candidates(entry: Any, *, plans: Any = None) -> list[tuple[str, str, str]]:
    """诊断候选池：只保留 final/现场主字段，不再把历史与 last_plan 拉进主裁决。"""
    try:
        d = dict(entry or {}) if isinstance(entry, dict) else {"reason": str(entry or "")}
    except Exception:
        d = {"reason": str(entry or "")}
    out: list[tuple[str, str, str]] = []
    def _push(reason: Any, stage: Any = "", src: str = "") -> None:
        rr = _normalize_reason_code(_reason_from_any(reason))
        if not rr:
            return
        ss = str(stage or _reason_stage_guess(rr)).strip() or _reason_stage_guess(rr)
        item = (rr, ss, str(src or ""))
        if item not in out:
            out.append(item)
    for k in ("final_reason_code", "final_reason", "block_reason", "reason_code", "reason"):
        _push(d.get(k), d.get("final_stage") or d.get("stage") or d.get("planner_stage"), f"entry.{k}")
    try:
        ev = d.get("execution_evidence") if isinstance(d.get("execution_evidence"), dict) else {}
        _push((ev or {}).get("final_confirmation_code") or (ev or {}).get("final_state"), "EXECUTE", "execution_evidence")
    except Exception as _e:
        _record_swallowed_exception("entry_reason_candidates.execution_evidence", _e)
    return out

def _entry_reason_view(entry: Any, *, default: str = "no_request") -> str:
    try:
        d = dict(entry or {}) if isinstance(entry, dict) else {"reason": str(entry or "")}
    except Exception:
        d = {"reason": str(entry or "")}
    resolved = _primary_reason_for_output(d, default=str(default or "NO_REQUEST"))
    if resolved:
        return str(resolved)
    if _reason_is_explicit_idle(default):
        return str(default)
    if _reason_is_explicit_idle(d.get("plan_state")):
        return str(d.get("plan_state") or default)
    if int(d.get("selected") or 0) == 1:
        return "selected"
    return "NO_REQUEST"

def _entry_stage_view(entry: Any, *, default: str = "") -> str:
    try:
        d = dict(entry or {}) if isinstance(entry, dict) else {"stage": str(entry or "")}
    except Exception:
        d = {"stage": str(entry or "")}
    for k in ("final_stage", "stage", "planner_stage"):
        try:
            v = str(d.get(k) or "").strip()
        except Exception:
            v = ""
        if v:
            return v
    return str(default or "")

def _entry_plan_state_view(entry: Any, *, default: str = "") -> str:
    try:
        d = dict(entry or {}) if isinstance(entry, dict) else {}
    except Exception:
        d = {}
    try:
        v = str(d.get("plan_state") or "").strip()
    except Exception:
        v = ""
    return v or str(default or "")

def _compose_internal_reason_missing(entry: Any = None, last_plan: Any = None, *, default_stage: str = "SUMMARY") -> tuple[str, str]:
    try:
        d = dict(entry or {}) if isinstance(entry, dict) else {}
    except Exception:
        d = {}
    try:
        lp = dict(last_plan or {}) if isinstance(last_plan, dict) else {}
    except Exception:
        lp = {}
    mod = str(d.get("mod") or d.get("module") or lp.get("mod") or lp.get("module") or "").strip().upper()
    stage = str(d.get("final_stage") or d.get("stage") or d.get("planner_stage") or lp.get("stage") or default_stage or "SUMMARY").strip().upper() or "SUMMARY"
    act = str(d.get("executed_action") or d.get("action") or d.get("action_type") or lp.get("action") or lp.get("action_type") or "").strip().lower()
    bits = ["internal_reason_missing"]
    if mod:
        bits.append(mod.lower())
    if stage:
        bits.append(stage.lower())
    if act:
        bits.append(act.lower())
    return ("_".join(bits), stage)

def _m9_infer_add_block_reason(entry: Any = None, *, default_stage: str = "ADD_GATE") -> tuple[str, str, dict]:
    try:
        d = dict(entry or {}) if isinstance(entry, dict) else {}
    except Exception:
        d = {}
    obs = dict(d.get("obs") or d.get("observations") or {}) if isinstance(d.get("obs") or d.get("observations"), dict) else {}
    gates = dict(d.get("gates") or obs.get("gates") or {}) if isinstance(d.get("gates") or obs.get("gates"), dict) else {}
    bucket_det = dict(d.get("bucket_det") or obs.get("bucket_det") or {}) if isinstance(d.get("bucket_det") or obs.get("bucket_det"), dict) else {}
    meta = {
        "next_buy_hit": bool(d.get("next_buy_hit") if "next_buy_hit" in d else obs.get("next_buy_hit")),
        "guess_add_u": _safe_float(d.get("guess_add_u") if "guess_add_u" in d else obs.get("guess_add_u"), 0.0),
        "bucket_ok": bool(bucket_det.get("ok")),
    }
    cand_reasons = []
    for src in (d, obs, gates, bucket_det):
        if not isinstance(src, dict):
            continue
        for k in ("final_reason_code", "final_reason", "block_reason", "reason_code", "reason", "gate_reason_code", "hardcap_precheck_reason"):
            rr = _normalize_reason_code(src.get(k) or "")
            if rr and rr not in ("no_request", "master_book_tp_not_hit", "tp_not_hit", "selected", "arbitration_accepted"):
                cand_reasons.append(rr)
    plans = d.get("plans") if isinstance(d.get("plans"), list) else []
    for _p in plans:
        if not isinstance(_p, dict):
            continue
        rr = _normalize_reason_code(_p.get("final_reason") or _p.get("reason") or "")
        if rr and rr not in ("no_request", "master_book_tp_not_hit", "tp_not_hit", "selected", "arbitration_accepted"):
            cand_reasons.append(rr)
    for rr in cand_reasons:
        st = _reason_stage_guess(rr, default=default_stage)
        if st in ("ADD_GATE", "ADD_BUDGET", "ADD_HARDCAP", "ELIGIBILITY", "GRID_GATE", "AMOUNT", "SCAN", "PLANNER"):
            return rr, st, meta
    next_buy_hit = bool(meta["next_buy_hit"])
    guess_add_u = float(meta["guess_add_u"] or 0.0)
    bucket_ok = bool(meta["bucket_ok"])
    ying = gates.get("yingding") if isinstance(gates.get("yingding"), dict) else {}
    m9_limits = gates.get("m9_limits") if isinstance(gates.get("m9_limits"), dict) else {}
    try:
        budget_left_u = _safe_float(m9_limits.get("budget_left_u"), None)
    except Exception:
        budget_left_u = None
    if budget_left_u is not None and float(budget_left_u) < 0:
        return "m9_budget_limit", "ADD_BUDGET", meta
    hc_reason = _normalize_reason_code(d.get("hardcap_precheck_reason") or obs.get("hardcap_precheck_reason") or gates.get("hardcap_precheck_reason") or "")
    if hc_reason and hc_reason not in ("ok", "pass"):
        return hc_reason, _reason_stage_guess(hc_reason, default="ADD_HARDCAP"), meta
    try:
        ying_ok = ying.get("ok", True) if isinstance(ying, dict) else True
    except Exception:
        ying_ok = True
    if ying_ok is False:
        rr = _normalize_reason_code(ying.get("reason") or ying.get("reason_code") or "hardcap_block", default="hardcap_block")
        return rr, _reason_stage_guess(rr, default="ADD_HARDCAP"), meta
    if next_buy_hit and bucket_ok and guess_add_u > 0:
        plans = d.get("plans") if isinstance(d.get("plans"), list) else []
        has_add_plan = any(str((p or {}).get("action") or (p or {}).get("action_type") or "").lower() == "increase" for p in plans if isinstance(p, dict))
        if not has_add_plan:
            return "add_hit_but_plan_missing", "ADD_PLANNER", meta
    if next_buy_hit:
        return "allowed_leg_seen_but_no_candidate", "ADD_PLANNER", meta
    return "", str(default_stage or "ADD_GATE"), meta

_M9_RECENT_EXEC_FAIL_CACHE: dict[str, Any] = {"ts": 0.0, "rows": []}

def _m9_recent_exec_fail_reason(entry: dict) -> tuple[str, str]:
    try:
        e = dict(entry or {}) if isinstance(entry, dict) else {}
    except Exception:
        e = {}
    if not e:
        return '', ''
    def _reason_root(raw: Any) -> tuple[str, str]:
        try:
            s = str(raw or '').strip()
        except Exception:
            s = ''
        if not s:
            return '', ''
        s0 = s.split('（', 1)[0].strip()
        root = _normalize_reason_code(s0.split('|', 1)[0].strip())
        return root, s
    # 先看层 note，避免原生网格层执行失败又被回退成 unmanaged/add_missing
    try:
        for _ly in reversed(list(e.get('layers') or [])):
            if not isinstance(_ly, dict):
                continue
            _note = str(_ly.get('note') or '').strip()
            if not _note:
                continue
            low = _note.lower()
            if 'exec_fail:' in low:
                part = _note[low.rfind('exec_fail:') + len('exec_fail:'):]
                code, raw = _reason_root(part)
                if code:
                    return code, raw
            if 'open_position_false' in low or 'goto_coin_fail' in low or 'context_mismatch' in low:
                code, raw = _reason_root(_note)
                if code:
                    return code, raw
    except Exception:
        pass
    # 再看最近执行结果，兜住“未落层就执行失败”的加仓请求
    try:
        nowv = float(time.time())
    except Exception:
        nowv = 0.0
    cache = globals().setdefault('_M9_RECENT_EXEC_FAIL_CACHE', {"ts": 0.0, "rows": []})
    rows = cache.get('rows') if isinstance(cache, dict) else []
    try:
        need_reload = (not isinstance(rows, list)) or (not rows) or (nowv - float(cache.get('ts') or 0.0) > 1.0)
    except Exception:
        need_reload = True
    if need_reload:
        fps = []
        try:
            for _base in (globals().get('OUT_DIR'), globals().get('PANEL_OUT_DIR')):
                if _base:
                    fps.append(os.path.join(str(_base), 'executor_results.jsonl'))
        except Exception:
            pass
        merged = []
        seen = set()
        for _fp in fps:
            if not _fp or _fp in seen:
                continue
            seen.add(_fp)
            try:
                merged.extend(_grid_ui_read_jsonl_tail(_fp, 800))
            except Exception:
                continue
        rows = [r for r in merged if isinstance(r, dict)]
        cache['rows'] = rows[-800:]
        cache['ts'] = nowv
    coin_u = str(e.get('coin') or '').upper().strip()
    plat_u = str(e.get('platform') or e.get('plat') or '').upper().strip()
    gid_u = str(e.get('grid_id') or '').strip()
    side_u = str(e.get('side') or '').upper().strip()
    want_act = 'decrease' if bool(e.get('next_sell_hit')) else ('increase' if bool(e.get('next_buy_hit')) or str(e.get('detail_state') or '').upper().startswith('COLD_START') else '')
    best = None
    best_ts = -1.0
    for _r in list(rows or [])[::-1]:
        try:
            _req = _r.get('req') if isinstance(_r.get('req'), dict) else {}
            _mod = str(_r.get('module') or _req.get('module') or '').upper().strip()
            if _mod != 'M9':
                continue
            _coin = str(_r.get('coin') or _req.get('coin') or '').upper().strip()
            _plat = str(_r.get('platform') or _r.get('plat') or _req.get('platform') or _req.get('plat') or '').upper().strip()
            if coin_u and _coin != coin_u:
                continue
            if plat_u and _plat != plat_u:
                continue
            _params = _req.get('params') if isinstance(_req.get('params'), dict) else {}
            _params2 = _params.get('params') if isinstance(_params.get('params'), dict) else {}
            _gid = str(_r.get('grid_id') or _params.get('grid_id') or _params2.get('grid_id') or '').strip()
            if gid_u and _gid and _gid != gid_u:
                continue
            _side = str(_r.get('side') or _req.get('side') or _params.get('side') or _params2.get('side') or '').upper().strip()
            if side_u and _side and _side != side_u:
                continue
            _act = str(_r.get('action') or _r.get('action_type') or _req.get('action_type') or _req.get('action') or '').lower().strip()
            if want_act and _act and _act != want_act:
                continue
            _ok = _r.get('ok')
            _reason = str(_r.get('reason') or '').strip()
            if (_ok is True) or (not _reason) or ('fail' not in _reason.lower() and 'open_position_false' not in _reason.lower() and 'goto_coin_fail' not in _reason.lower()):
                continue
            _ts = _safe_float(_r.get('ts'), 0.0)
            if _ts >= best_ts:
                best_ts = float(_ts)
                best = _reason_root(_reason)
        except Exception:
            continue
    if isinstance(best, tuple) and best[0]:
        return best
    return '', ''

def _m9_choose_entry_final_reason(entry: dict, master_sell_source: dict | None = None) -> tuple[str, str, str]:
    d = dict(entry or {}) if isinstance(entry, dict) else {}
    ms = dict(master_sell_source or {}) if isinstance(master_sell_source, dict) else {}
    exec_fail_reason = _normalize_reason_code(d.get('recent_exec_fail_reason') or d.get('exec_fail_reason') or '')
    if not exec_fail_reason:
        exec_fail_reason, _exec_fail_raw = _m9_recent_exec_fail_reason(d)
        if exec_fail_reason:
            d['recent_exec_fail_reason'] = str(exec_fail_reason)
            d['recent_exec_fail_detail'] = str(_exec_fail_raw or '')
    if exec_fail_reason:
        return str(exec_fail_reason), 'EXECUTE', 'REJECTED'
    tp_reason = _normalize_reason_code(ms.get("final_reason") or ms.get("final_reason_code") or ms.get("reason") or ms.get("block_reason") or "")
    tp_stage = str(ms.get("final_stage") or ("TP" if bool(d.get("next_sell_hit")) else "GRID_GATE")).upper().strip() or "GRID_GATE"
    tp_verdict = str(ms.get("final_verdict") or ("ACCEPTED" if bool(ms.get("ok")) else ("REJECTED" if bool(d.get("next_sell_hit")) else "IDLE"))).upper().strip() or "IDLE"
    add_reason, add_stage, _meta = _m9_infer_add_block_reason(d)
    if add_reason:
        choose_add = False
        if not tp_reason:
            choose_add = True
        elif tp_reason in ("master_book_tp_not_hit", "tp_not_hit", "no_request"):
            choose_add = True
        elif _final_reason_priority(add_reason) > _final_reason_priority(tp_reason):
            choose_add = True
        if choose_add:
            add_verdict = "REJECTED"
            if _reason_is_explicit_idle(add_reason):
                add_verdict = "IDLE"
            return add_reason, str(add_stage or "ADD_GATE").upper().strip() or "ADD_GATE", add_verdict
    if tp_reason:
        return tp_reason, tp_stage, tp_verdict
    return "NO_REQUEST", "PLANNER", "NO_REQUEST"

def _verdict_mark(extra_map: dict | None, coin: str, *, reason: str = "", stage: str = "", plan_state: str = "", candidate_mode: str = "", final_verdict: str = "", **fields) -> dict:
    c = str(coin or "").upper().strip()
    if not c:
        return {}
    base = {}
    if isinstance(extra_map, dict):
        try:
            base = dict(extra_map.get(c) or {})
        except Exception:
            base = {}
    base["coin"] = c
    base["touched"] = 1
    history = list(base.get("reason_history") or []) if isinstance(base.get("reason_history"), list) else []
    rr = _normalize_reason_code(reason)
    fv = str(final_verdict or base.get("final_verdict") or "").upper().strip()
    if not rr and fv == "EXECUTED":
        rr = "confirmed_success"
        if not stage:
            stage = "EXECUTE"
    elif not rr and fv == "PENDING_CONFIRM":
        rr = "submitted_pending_confirm"
        if not stage:
            stage = "EXECUTE"
    elif not rr and fv == "NO_REQUEST":
        rr = "NO_REQUEST"
        if not stage:
            stage = str(stage or base.get("stage") or "SUMMARY")
    elif not rr and fv in ("REJECTED", "ABORTED", "FAILED", "EXEC_FAIL"):
        rr, _miss_stage = _compose_internal_reason_missing(base, None, default_stage=str(stage or base.get("stage") or "SUMMARY"))
        if not stage:
            stage = _miss_stage
        _record_internal_guard("verdict_missing_reason", f"{c}:{fv}:{rr}")
    ss = str(stage or _reason_stage_guess(rr or base.get("reason") or "")).strip()
    if rr:
        event = {
            "reason": str(rr),
            "reason_code": str(rr),
            "stage": str(ss or _reason_stage_guess(rr)),
            "ts": now_ts(),
        }
        for k, v in (fields or {}).items():
            if v is not None and k not in ("reason", "stage"):
                event[k] = v
        history.append(event)
        base["reason_history"] = history[-20:]
        if not str(base.get("first_block_reason") or ""):
            base["first_block_reason"] = str(rr)
            base["first_block_reason_code"] = str(rr)
            base["first_block_stage"] = str(ss or _reason_stage_guess(rr))
            base["first_block_source"] = str(fields.get("source") or "verdict_mark") if isinstance(fields, dict) else "verdict_mark"
        prev_final = str(base.get("final_reason_code") or base.get("final_reason") or base.get("reason") or "")
        stronger = _pick_stronger_reason(prev_final, rr)
        final_reason_eff = str(stronger or rr)
        final_stage_eff = str(base.get("final_stage") or "")
        if final_reason_eff == str(rr):
            final_stage_eff = str(ss or _reason_stage_guess(rr))
            base["final_reason_source"] = str(fields.get("source") or "verdict_mark") if isinstance(fields, dict) else "verdict_mark"
        elif not final_stage_eff:
            final_stage_eff = _reason_stage_guess(final_reason_eff)
        base["final_reason_code"] = str(final_reason_eff)
        base["final_reason"] = str(final_reason_eff)
        base["final_stage"] = str(final_stage_eff)
        base["reason_code"] = str(final_reason_eff)
        base["reason"] = str(final_reason_eff)
        base["stage"] = str(final_stage_eff)
    elif stage and not str(base.get("stage") or ""):
        base["stage"] = str(stage)
    if plan_state:
        base["plan_state"] = str(plan_state)
    if candidate_mode:
        base["candidate_mode"] = str(candidate_mode)
    if final_verdict:
        base["final_verdict"] = str(final_verdict)
        try:
            if str(final_verdict).upper().strip() in ("REJECTED", "ABORTED", "FAILED", "EXEC_FAIL", "NO_REQUEST", "PENDING_CONFIRM", "EXECUTED"):
                _record_terminal_decision("verdict_mark", rr or base.get("final_reason") or base.get("reason") or final_verdict, ss or base.get("final_stage") or stage, f"coin={c}|verdict={str(final_verdict).upper().strip()}")
        except Exception as _e:
            _record_swallowed_exception("verdict_mark.audit", _e)
    elif rr and not str(base.get("final_verdict") or ""):
        _rr_norm = _normalize_reason_code(rr)
        if _rr_norm in ("confirmed_success",) or _rr_norm.startswith(("confirm_", "confirmed_")):
            base["final_verdict"] = "EXECUTED"
        elif _rr_norm in ("submitted_pending_confirm", "fill_seen_pending_confirm", "submitted_unchecked") or _rr_norm.startswith(("planned_and_submitted", "submitted_", "fill_seen_")):
            base["final_verdict"] = "PENDING_CONFIRM"
        elif _rr_norm == "NO_REQUEST":
            base["final_verdict"] = "NO_REQUEST"
        else:
            base["final_verdict"] = "REJECTED"
    for k, v in (fields or {}).items():
        if v is not None:
            base[k] = v
    if isinstance(extra_map, dict):
        extra_map[c] = base
    return base

def _finalize_no_req_entry(coin: str, entry: Any, *, plans: Any = None) -> dict:
    """无请求收尾只补 final 字段，不再做第二轮强竞争裁决。"""
    d = dict(entry or {}) if isinstance(entry, dict) else {"reason": str(entry or "")}
    coin_u = str(coin or "").upper().strip()
    d["coin"] = coin_u
    d.setdefault("plan_state", "INIT")
    d.setdefault("candidate_mode", "UNKNOWN")
    d.setdefault("stage", str(d.get("stage") or "PLANNER"))
    last_plan = _extract_last_plan_for_coin(plans, coin_u)
    if last_plan:
        d.setdefault("last_plan", dict(last_plan))
    try:
        ev = d.get("execution_evidence") if isinstance(d.get("execution_evidence"), dict) else {}
        if isinstance(ev, dict) and ev:
            if not d.get("confirmation_state"):
                d["confirmation_state"] = str(ev.get("final_confirmation_code") or ev.get("final_state") or "")
            if d.get("postcheck_ok") is None and ev.get("postcheck_ok") in (True, False):
                d["postcheck_ok"] = ev.get("postcheck_ok")
    except Exception as _e:
        _record_swallowed_exception("finalize_no_req_entry.execution_evidence", _e)

    final_reason = _normalize_reason_code(d.get("final_reason_code") or d.get("final_reason") or "")
    final_stage = str(d.get("final_stage") or d.get("stage") or d.get("planner_stage") or "SUMMARY").upper().strip() or "SUMMARY"
    final_src = str(d.get("final_reason_source") or "")

    if not final_reason:
        confirm_reason = _entry_confirm_truth_reason(d, plans=plans)
        submit_reason = _entry_submit_truth_reason(d, plans=plans)
        force_tp_reason, force_tp_stage, force_tp_src = _detect_force_tp_chain_reason(d, plans=plans)
        if confirm_reason:
            final_reason = _normalize_reason_code(confirm_reason, default="confirmed_success")
            final_stage = "EXECUTE"
            final_src = "execution_evidence.confirm"
        elif submit_reason:
            final_reason = _normalize_reason_code(submit_reason, default="submitted_pending_confirm")
            final_stage = "EXECUTE"
            final_src = "execution_evidence.submit"
        elif force_tp_reason:
            final_reason = _normalize_reason_code(force_tp_reason)
            final_stage = str(force_tp_stage or "TP")
            final_src = str(force_tp_src or "force_tp_chain")
        elif _reason_is_explicit_idle(d.get("plan_state")):
            final_reason = _normalize_reason_code(d.get("plan_state"), default="idle_skip_not_due")
            final_stage = str(d.get("stage") or final_stage or "SUMMARY").upper().strip() or "SUMMARY"
            final_src = "plan_state"
        else:
            add_reason, add_stage, _add_meta = _m9_infer_add_block_reason(d, default_stage="PLANNER")
            if add_reason:
                final_reason = _normalize_reason_code(add_reason, default="NO_REQUEST")
                final_stage = str(add_stage or final_stage or "PLANNER").upper().strip() or "PLANNER"
                final_src = "add_truth_infer"
            else:
                miss_reason, miss_stage = _compose_internal_reason_missing(d, last_plan, default_stage=final_stage)
                final_reason = _normalize_reason_code(miss_reason, default="NO_REQUEST")
                final_stage = str(miss_stage or final_stage or "SUMMARY").upper().strip() or "SUMMARY"
                final_src = "summary_missing_verdict"

    if not d.get("first_block_reason") and final_reason:
        d["first_block_reason_code"] = str(final_reason)
        d["first_block_reason"] = str(final_reason)
        d["first_block_stage"] = str(final_stage or _reason_stage_guess(final_reason))
        d["first_block_source"] = str(final_src or "finalize_no_req_entry")

    d["final_reason_code"] = str(final_reason or "NO_REQUEST")
    d["final_reason"] = str(final_reason or "NO_REQUEST")
    d["final_stage"] = str(final_stage or _reason_stage_guess(final_reason, default="SUMMARY"))
    d["final_reason_source"] = str(final_src or d.get("final_reason_source") or "finalize_no_req_entry")

    norm = _normalize_reason_code(final_reason)
    if norm in ("confirmed_success",) or norm.startswith(("confirm_", "confirmed_")):
        d["final_verdict"] = "EXECUTED"
        d["plan_state"] = "FINALIZED_EXECUTED"
        d["selected"] = 1
    elif norm in ("submitted_pending_confirm", "fill_seen_pending_confirm", "submitted_unchecked") or norm.startswith(("planned_and_submitted", "submitted_", "fill_seen_")):
        d["final_verdict"] = "PENDING_CONFIRM"
        d["plan_state"] = "PENDING_CONFIRM"
        d["selected"] = 1
    elif _reason_is_explicit_idle(norm):
        d["final_verdict"] = "IDLE"
        if str(d.get("plan_state") or "") in ("", "INIT", "SELECTED"):
            d["plan_state"] = "IDLE"
    elif norm in ("NO_REQUEST", "allowed_leg_seen_but_no_candidate", "no_candidate_generated"):
        d["final_verdict"] = "NO_REQUEST"
        if str(d.get("plan_state") or "") in ("", "INIT", "SELECTED"):
            d["plan_state"] = "NO_REQUEST"
    elif norm == "add_hit_but_plan_missing":
        d["final_verdict"] = "REJECTED"
        if str(d.get("plan_state") or "") in ("", "INIT", "SELECTED", "NO_REQUEST"):
            d["plan_state"] = "FINALIZED_MISSING_ADD_PLAN"
    elif _reason_stage_guess(norm) == "SCAN":
        d["final_verdict"] = "ABORTED"
        d["plan_state"] = "ABORTED"
    else:
        d["final_verdict"] = "REJECTED"
        if str(d.get("plan_state") or "") in ("", "INIT", "SELECTED"):
            d["plan_state"] = "FINALIZED"

    last_plan_reason = str((last_plan or {}).get("reason") or "").strip()
    last_plan_action = str((last_plan or {}).get("action") or "").strip()
    if str(d.get("candidate_mode") or "UNKNOWN") == "UNKNOWN":
        if str(final_reason).startswith("cold_start_"):
            d["candidate_mode"] = "COLD_START"
        elif last_plan_action.startswith("increase") or str(final_reason).startswith(("grid_", "trend_", "rsi_", "hardcap_")):
            d["candidate_mode"] = "GRID_ADD"
    if last_plan_action:
        d.setdefault("last_action", last_plan_action)
    if last_plan_reason and (str(d.get("final_reason") or "") != str(last_plan_reason or "")):
        d.setdefault("last_plan_reason", last_plan_reason)
    d["reason_code"] = d.get("final_reason_code")
    d["reason"] = d.get("final_reason")
    d["stage"] = d.get("final_stage")
    d["touched"] = int(d.get("touched") or 1)
    try:
        _record_terminal_decision("finalize_no_req_entry", d.get("final_reason"), d.get("final_stage"), f"coin={coin_u}|verdict={d.get('final_verdict')}")
    except Exception as _e:
        _record_swallowed_exception("finalize_no_req_entry.audit", _e)
    return d

def _m9_trace_finalize_event(ev: dict) -> dict:
    d = dict(ev or {})
    et = str(d.get("etype") or d.get("event") or d.get("status") or "").upper().strip()
    need_reason = et in ("REJECT", "DROP", "SKIP", "EXEC_FAIL")
    code = str(d.get("final_reason_code") or d.get("code") or d.get("reason_code") or "").strip()
    reason = str(d.get("final_reason") or d.get("reason") or "").strip()
    if need_reason and not code:
        code = _compose_internal_reason_missing(d, None, default_stage=str(d.get("stage") or et or "SUMMARY"))[0]
        _record_reason_chain_broken(f"trace_finalize:{et}")
    if need_reason and not reason:
        reason = f"{code}（拒绝事件未写原因链）"
    if code:
        d["code"] = code
        d["reason_code"] = code
    if reason:
        d["reason"] = reason
    return d

def _runtime_state_normalize(*, phase: str = "", state: str = "", mainloop_state: str = "") -> dict:
    ph = str(phase or "").upper().strip()
    st = str(state or "").upper().strip()
    ml = str(mainloop_state or "").upper().strip()
    if not ph:
        if st == "SLEEPING":
            ph = "ROUND_SUMMARY"
        elif ml in {"SCANNING", "RUNNING"}:
            ph = "SCAN_M2"
        elif ml in {"EXECUTING"}:
            ph = "EXECUTE_CONFIRM"
    if not st:
        if ph == "ROUND_SUMMARY":
            st = "SLEEPING"
        elif ph in {"ROUND_BEGIN", "SCAN_M2", "BUILD_REQUESTS", "READINESS_VERDICT", "ARBITRATION", "QUEUE_SUBMIT", "EXECUTE_CONFIRM", "STATE_COMMIT"}:
            st = "RUNNING"
    if ph == "ROUND_SUMMARY":
        st = "SLEEPING"
        ml = "SLEEPING"
    elif ph in {"ROUND_BEGIN", "SCAN_M2", "BUILD_REQUESTS", "READINESS_VERDICT", "ARBITRATION"}:
        ml = "SCANNING"
    elif ph in {"QUEUE_SUBMIT", "EXECUTE_CONFIRM", "STATE_COMMIT"}:
        ml = "EXECUTING"
    elif st == "SLEEPING":
        ml = "SLEEPING"
    elif not ml:
        ml = st or ph or ""
    unified = ph or ("ROUND_SUMMARY" if st == "SLEEPING" else ml)
    return {"round_phase": ph, "round_state": st, "mainloop_state": ml, "unified_state": str(unified or "").upper().strip()}

def _runtime_state_snapshot() -> dict:
    try:
        cur = dict(globals().get("_RUNTIME_STATE") or {})
    except Exception:
        cur = {}
    norm = _runtime_state_normalize(
        phase=str(cur.get("round_phase") or cur.get("phase") or ""),
        state=str(cur.get("round_state") or cur.get("state") or ""),
        mainloop_state=str(cur.get("mainloop_state") or ""),
    )
    out = dict(cur)
    out.update(norm)
    return out

def _worker_runtime_update_allowed() -> bool:
    # Bootstrap/main-thread calls have no lease and retain their normal behavior.
    tracker = globals().get('_WORKER_STATE')
    return tracker is None or not tracker.retired_current()

def _runtime_state_set(*, phase: str | None = None, state: str | None = None, mainloop_state: str | None = None, reason_code: str = "", msg: str = "", err: str | None = None, extra: dict | None = None) -> dict:
    if not _worker_runtime_update_allowed():
        return dict(globals().get('_RUNTIME_STATE') or {})
    try:
        cur = dict(globals().get("_RUNTIME_STATE") or {})
    except Exception:
        cur = {}
    if phase is not None:
        cur["round_phase"] = str(phase or "").upper().strip()
    if state is not None:
        cur["round_state"] = str(state or "").upper().strip()
    if mainloop_state is not None:
        cur["mainloop_state"] = str(mainloop_state or "").upper().strip()
    norm = _runtime_state_normalize(
        phase=str(cur.get("round_phase") or ""),
        state=str(cur.get("round_state") or ""),
        mainloop_state=str(cur.get("mainloop_state") or ""),
    )
    cur.update(norm)
    if (cur.get('reason_code') == 'user_stopped' and mainloop_state is not None
            and str(mainloop_state).upper() not in ('STOPPED', 'STOPPING')):
        cur.pop('reason_code', None)
        cur.pop('msg', None)
    cur["ts"] = float(time.time())
    if reason_code:
        cur["reason_code"] = str(reason_code or "")[:120]
    if msg:
        cur["msg"] = str(msg or "")[:240]
    if err is not None:
        cur["err"] = str(err or "")[:240]
    if isinstance(extra, dict) and extra:
        for k, v in extra.items():
            cur[str(k)] = v
    globals()["_RUNTIME_STATE"] = cur
    return dict(cur)

def _runtime_state_drop_keys(*keys: str) -> dict:
    if not _worker_runtime_update_allowed():
        return {'changed': [], 'runtime_state': dict(globals().get('_RUNTIME_STATE') or {})}
    try:
        cur = dict(globals().get("_RUNTIME_STATE") or {})
    except Exception:
        cur = {}
    changed = []
    try:
        for k in keys:
            ks = str(k or "").strip()
            if (not ks) or (ks not in cur):
                continue
            cur.pop(ks, None)
            changed.append(ks)
    except Exception as _e:
        _record_swallowed_exception('runtime_state_drop_keys', _e)
    if changed:
        try:
            cur["ts"] = float(time.time())
        except Exception:
            pass
        globals()["_RUNTIME_STATE"] = cur
    return {"changed": list(changed), "runtime_state": dict(cur)}

def _runtime_state_clear_recovery_marks(reason: str = "", *, clear_round_recovery_once: bool = False) -> dict:
    _keys = (
        "recovery_pending", "recovery_reason", "recovery_kind", "recovery_source", "recovery_pending_ts",
        "pw_recovering", "pw_recover_reason", "pw_recover_source", "pw_recover_started_ts",
    )
    rep = _runtime_state_drop_keys(*_keys)
    if clear_round_recovery_once:
        try:
            globals()["_ROUND_RECOVERY_ONCE"] = {"active": False, "reason": "", "kind": "", "ts": 0.0}
            rep["round_recovery_once_cleared"] = True
        except Exception as _e:
            _record_swallowed_exception('runtime_state_clear_recovery_marks.round_recovery_once', _e, reason)
            rep["round_recovery_once_cleared"] = False
    try:
        if reason and rep.get("changed"):
            safe_log(lambda: f"[{now_ts()}] [RUNTIME_STATE] clear_recovery_marks reason={str(reason or '')[:120]} keys={','.join(list(rep.get('changed') or [])[:12])}")
    except Exception as _e:
        _record_swallowed_exception('runtime_state_clear_recovery_marks.safe_log', _e, reason)
    return rep

def _runtime_state_apply_to_status(obj: dict | None) -> dict:
    out = dict(obj or {})
    rs = _runtime_state_snapshot()
    if rs:
        out["runtime_state"] = dict(rs)
        out["round_phase"] = str(rs.get("round_phase") or "")
        out["round_state"] = str(rs.get("round_state") or "")
        out["unified_state"] = str(rs.get("unified_state") or "")
        out["mainloop_state"] = str(rs.get("mainloop_state") or out.get("mainloop_state") or "")
        out["runtime_state_source"] = "runtime_state"
        out["round_phase_source"] = "runtime_state_mirror"
        out["round_state_source"] = "runtime_state_mirror"
        out["state_truth_source"] = "runtime_state"
        out["state_truth_consistent"] = True
    return out

def _snapshot_positions_truth_payload(snapshot: dict | None) -> dict:
    try:
        s = dict(snapshot or {}) if isinstance(snapshot, dict) else {}
    except Exception:
        s = {}
    try:
        pos = _pos_root(s) or {}
    except Exception:
        pos = {}
    out = {
        "positions_truth_source": "snapshot.positions",
        "positions_truth_ts": float(s.get("ts") or s.get("snapshot_ts") or 0.0),
        "positions_data_quality": str(s.get("data_quality") or ""),
        "positions_ext_found": 0,
        "positions_var_found": 0,
    }
    try:
        out["positions_ext_found"] = sum(1 for _c, _v in dict(pos.get("EXT") or {}).items() if isinstance(_v, dict) and str(_v.get("reason") or "") == "ok")
        out["positions_var_found"] = sum(1 for _c, _v in dict(pos.get("VAR") or {}).items() if isinstance(_v, dict) and str(_v.get("reason") or "") == "ok")
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_14', _e)
        pass
    return out

def _status_attach_single_source_truth(obj: dict | None, snapshot: dict | None = None) -> dict:
    out = dict(obj or {})
    recovery_states = {}
    recovery_messages = []
    for platform in ('EXT', 'VAR'):
        recovery = globals().get(f'_{platform}_RECOVERY')
        if recovery is None:
            continue
        status = recovery.status()
        recovery_states[platform] = status
        if status.get('message'):
            recovery_messages.append(str(status['message']))
        if recovery.alarm_due():
            safe_log(lambda: f"[{now_ts()}] [{platform}_RECOVERY][MANUAL_ACTION_REQUIRED] {status['message']} last_error={status['last_error']}")
    out['browser_recovery'] = recovery_states
    out['browser_recovery_alert'] = '\n'.join(recovery_messages)
    funding_status = globals().get('_funding_margin_status')
    if callable(funding_status):
        funding = funding_status()
        out['funds_imbalance'] = funding
        out['funds_imbalance_alert'] = str(funding.get('message') or '')
    try:
        out = _runtime_state_apply_to_status(out)
    except Exception as _e:
        _record_swallowed_exception("status_attach.runtime_state", _e)
    snap = snapshot if isinstance(snapshot, dict) else None
    if snap is None:
        try:
            maybe = safe_read_json(str(globals().get("POSITIONS_FP") or Path(str(_get_out_dir())) / "positions.json")) if "safe_read_json" in globals() else None
            snap = maybe if isinstance(maybe, dict) else None
        except Exception as _e:
            _record_swallowed_exception("status_attach.positions_read", _e)
            snap = None
    if isinstance(snap, dict):
        try:
            out.update(_snapshot_positions_truth_payload(snap))
            out["positions_truth_consistent"] = True
            out["positions_truth_runtime_link"] = str(out.get("runtime_state_source") or "runtime_state")
        except Exception as _e:
            _record_swallowed_exception("status_attach.positions_payload", _e)
    else:
        out.setdefault("positions_truth_source", "snapshot.positions_missing")
        out.setdefault("positions_truth_consistent", False)
    return out

def _runtime_state_sync_from_round_watch(rw: dict | None, *, fallback_phase: str = "ROUND", fallback_state: str = "RUNNING", reason_code: str = "", msg: str = "", err: str = "") -> dict:
    try:
        src = dict(rw or {})
    except Exception:
        src = {}
    cur = _runtime_state_snapshot()
    if str((cur or {}).get("round_phase") or "").strip() and str((cur or {}).get("round_state") or "").strip():
        return dict(cur or {})
    phase = str(src.get("stage") or fallback_phase or "ROUND").upper().strip() or "ROUND"
    state = str(src.get("state") or fallback_state or "RUNNING").upper().strip() or "RUNNING"
    rc = _normalize_reason_code(reason_code or str(src.get("reason") or ""), default="ok")
    return _runtime_state_set(phase=phase, state=state, reason_code=rc, msg=str(msg or src.get("msg") or phase), err=str(err or src.get("err") or ""), extra={"runtime_source": "compat_round_watch_bootstrap"})

def _grid_report_runtime_state_from_status(status_obj: dict | None, module_obj: dict | None = None) -> dict:
    status_obj = status_obj if isinstance(status_obj, dict) else {}
    module_obj = module_obj if isinstance(module_obj, dict) else {}
    status_runtime = status_obj.get("runtime_state") if isinstance(status_obj.get("runtime_state"), dict) else {}
    status_rw = status_obj.get("round_watch") if isinstance(status_obj.get("round_watch"), dict) else {}
    module_runtime = module_obj.get("runtime_state") if isinstance(module_obj.get("runtime_state"), dict) else {}
    module_rw = module_obj.get("round_watch") if isinstance(module_obj.get("round_watch"), dict) else {}

    round_phase_src = str((status_runtime or {}).get("round_phase") or status_obj.get("round_phase") or "").upper().strip()
    round_state_src = str((status_runtime or {}).get("round_state") or status_obj.get("round_state") or "").upper().strip()
    mainloop_raw = str(status_obj.get("mainloop_state") or "").upper().strip()
    mainloop_src = str((status_runtime or {}).get("mainloop_state") or mainloop_raw or "").upper().strip()
    norm = _runtime_state_normalize(phase=round_phase_src, state=round_state_src, mainloop_state=mainloop_src)
    status_rw_phase = str((status_rw or {}).get("stage") or "").upper().strip()
    status_rw_state = str((status_rw or {}).get("state") or "").upper().strip()
    legacy_module_phase = str((module_runtime or {}).get("round_phase") or module_obj.get("round_phase") or (module_rw or {}).get("stage") or "").upper().strip()
    legacy_module_state = str((module_runtime or {}).get("round_state") or module_obj.get("round_state") or (module_rw or {}).get("state") or "").upper().strip()
    diag = {
        "runtime_source": "status.runtime_state" if status_runtime else ("status.round_phase" if (status_obj.get("round_phase") or status_obj.get("round_state")) else "status.empty"),
        "round_phase": str(norm.get("round_phase") or "").upper(),
        "round_state": str(norm.get("round_state") or "").upper(),
        "unified_state": str(norm.get("unified_state") or "").upper(),
        "mainloop_state": str(norm.get("mainloop_state") or "").upper(),
        "mainloop_state_raw": mainloop_raw,
        "diag_status_round_watch_phase": status_rw_phase,
        "diag_status_round_watch_state": status_rw_state,
        "legacy_module_round_phase": legacy_module_phase,
        "legacy_module_round_state": legacy_module_state,
        "legacy_module_mainloop_state": str(module_obj.get("mainloop_state") or module_obj.get("state") or "").upper().strip(),
        "status_runtime_present": bool(status_runtime),
        "status_top_mirror_present": bool(status_obj.get("round_phase") or status_obj.get("round_state") or status_obj.get("mainloop_state")),
        "diag_round_watch_present": bool(status_rw_phase or status_rw_state),
        "legacy_module_state_present": bool(legacy_module_phase or legacy_module_state),
        "state_chain_consistent": bool((not status_rw_phase or status_rw_phase == str(norm.get("round_phase") or "").upper()) and (not status_rw_state or status_rw_state == str(norm.get("round_state") or "").upper())),
        "state_chain_conflict": bool((status_rw_phase and status_rw_phase != str(norm.get("round_phase") or "").upper()) or (status_rw_state and status_rw_state != str(norm.get("round_state") or "").upper()) or (legacy_module_phase and legacy_module_phase != str(norm.get("round_phase") or "").upper()) or (legacy_module_state and legacy_module_state != str(norm.get("round_state") or "").upper())),
    }
    return diag

def _runtime_state_diag_payload(status_obj: dict | None = None, module_obj: dict | None = None) -> dict:
    try:
        diag = _grid_report_runtime_state_from_status(status_obj if isinstance(status_obj, dict) else {}, module_obj if isinstance(module_obj, dict) else {})
    except Exception:
        diag = {}
    rt = _runtime_state_snapshot()
    rt = rt if isinstance(rt, dict) else {}
    out = {
        "runtime_state_source": str((diag or {}).get("runtime_source") or (rt.get("runtime_source") if isinstance(rt, dict) else "") or "runtime_state"),
        "runtime_state_round_phase": str((rt or {}).get("round_phase") or "").upper().strip(),
        "runtime_state_round_state": str((rt or {}).get("round_state") or "").upper().strip(),
        "runtime_state_mainloop_state": str((rt or {}).get("mainloop_state") or "").upper().strip(),
        "diag_status_round_watch_phase": str((diag or {}).get("diag_status_round_watch_phase") or ""),
        "diag_status_round_watch_state": str((diag or {}).get("diag_status_round_watch_state") or ""),
        "legacy_module_round_phase": str((diag or {}).get("legacy_module_round_phase") or ""),
        "legacy_module_round_state": str((diag or {}).get("legacy_module_round_state") or ""),
        "status_runtime_present": bool((diag or {}).get("status_runtime_present", False)),
        "status_top_mirror_present": bool((diag or {}).get("status_top_mirror_present", False)),
        "diag_round_watch_present": bool((diag or {}).get("diag_round_watch_present", False)),
        "legacy_module_state_present": bool((diag or {}).get("legacy_module_state_present", False)),
        "state_chain_consistent": bool((diag or {}).get("state_chain_consistent", True)),
        "state_chain_conflict": bool((diag or {}).get("state_chain_conflict", False)),
    }
    out["state_chain_source"] = "runtime_state_primary" if out["runtime_state_round_phase"] or out["runtime_state_round_state"] else str((diag or {}).get("runtime_source") or "status.empty")
    _conflicts = []
    _rt_phase = out.get("runtime_state_round_phase") or ""
    _rt_state = out.get("runtime_state_round_state") or ""
    _rw_phase = out.get("diag_status_round_watch_phase") or ""
    _rw_state = out.get("diag_status_round_watch_state") or ""
    _legacy_phase = out.get("legacy_module_round_phase") or ""
    _legacy_state = out.get("legacy_module_round_state") or ""
    if _rw_phase and _rt_phase and _rw_phase != _rt_phase:
        _conflicts.append(f"round_watch.phase:{_rw_phase}!={_rt_phase}")
    if _rw_state and _rt_state and _rw_state != _rt_state:
        _conflicts.append(f"round_watch.state:{_rw_state}!={_rt_state}")
    if _legacy_phase and _rt_phase and _legacy_phase != _rt_phase:
        _conflicts.append(f"legacy_module.phase:{_legacy_phase}!={_rt_phase}")
    if _legacy_state and _rt_state and _legacy_state != _rt_state:
        _conflicts.append(f"legacy_module.state:{_legacy_state}!={_rt_state}")
    out["state_chain_conflict_items"] = _conflicts
    out["state_chain_conflict_count"] = int(len(_conflicts))
    return out

def _round_phase_touch(stage: str, *, msg: str = "", reason_code: str = "", err: str = "") -> None:
    if not _worker_runtime_update_allowed():
        return None
    st = str(stage or "ROUND").upper().strip() or "ROUND"
    rc = _normalize_reason_code(reason_code, default="ok")
    snap = {}
    try:
        if st != "ROUND_SUMMARY":
            _runtime_state_clear_recovery_marks(f"round_phase_touch:{st}", clear_round_recovery_once=False)
    except Exception as _e:
        _record_swallowed_exception('round_phase_touch.clear_recovery_marks', _e, st)
    try:
        snap = _runtime_state_set(phase=st, state=("SLEEPING" if st == "ROUND_SUMMARY" else "RUNNING"), reason_code=rc, msg=str(msg or st), err=str(err or ""), extra={"runtime_source": "round_phase_touch"})
    except Exception:
        snap = {}
    try:
        globals()["_ROUND_PHASE_STATE"] = {"phase": str((snap or {}).get("round_phase") or st), "reason_code": rc, "msg": str(msg or "")[:240], "err": str(err or "")[:240], "ts": float(time.time()), "source": "runtime_state_mirror"}
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_15', _e)
        pass
    try:
        _round_watch_touch(str((snap or {}).get("round_phase") or st), msg=str(msg or st), reason=rc, err=str(err or ""))
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_16', _e)
        pass
    try:
        panel_update_heartbeat({"phase": "round", "state": str((snap or {}).get("round_state") or st), "stage": str((snap or {}).get("round_phase") or st), "reason": rc, "msg": str(msg or "")[:120], "ts": float(time.time()), "source": "runtime_state_mirror"})
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_17', _e)
        pass
def _round_failure_reset() -> None:
    try:
        globals()["_ROUND_FAILURE_ESCALATION"] = {"count": 0, "last_ts": 0.0, "last_reason": "", "last_kind": ""}
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_18', _e)
        pass
def _round_failure_record(reason: str, *, kind: str = "round_error") -> dict:
    try:
        st = globals().get("_ROUND_FAILURE_ESCALATION") or {}
        nowv = float(time.time())
        prev_ts = float(st.get("last_ts") or 0.0)
        prev_kind = str(st.get("last_kind") or "")
        same_window = (nowv - prev_ts) <= 900.0
        if same_window and str(kind or "") == prev_kind:
            cnt = int(st.get("count") or 0) + 1
        else:
            cnt = 1
        out = {"count": int(cnt), "last_ts": nowv, "last_reason": str(reason or "")[:240], "last_kind": str(kind or "")[:80]}
        globals()["_ROUND_FAILURE_ESCALATION"] = out
        return out
    except Exception:
        return {"count": 1, "last_ts": float(time.time()), "last_reason": str(reason or "")[:240], "last_kind": str(kind or "")[:80]}

def _round_recovery_mark(reason: str, *, kind: str = "round_error") -> None:
    try:
        globals()["_ROUND_RECOVERY_ONCE"] = {"active": True, "reason": str(reason or "")[:240], "kind": str(kind or "")[:80], "ts": float(time.time())}
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_19', _e)
        pass
def _round_recovery_consume() -> dict:
    try:
        obj = dict(globals().get("_ROUND_RECOVERY_ONCE") or {})
    except Exception:
        obj = {}
    try:
        globals()["_ROUND_RECOVERY_ONCE"] = {"active": False, "reason": "", "kind": "", "ts": 0.0}
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_20', _e)
        pass
    return obj

def _round_abort_and_schedule_recovery(reason: str, *, source: str = "SYS", kind: str = "round_abort", panel_state: str = "RECOVERING_UI", stop_exec_runtime: bool = True, rebuild_worker: bool = False, touch_scan: bool = True, clear_watchdog_trip: bool = True) -> dict:
    _reason = str(reason or f"{str(source or 'SYS')}_round_abort")[:240]
    _source = str(source or "SYS")[:80]
    try:
        _round_recovery_mark(_reason, kind=str(kind or "round_abort")[:80])
    except Exception as _e:
        _record_swallowed_exception('round_abort.recovery_mark', _e, _reason)
    try:
        if stop_exec_runtime:
            _exec_runtime_stop(_reason, stop_all=True)
    except Exception as _e:
        _record_swallowed_exception('round_abort.exec_runtime_stop', _e, _reason)
    try:
        _exec_batch_watch_finish("TIMEOUT", msg="执行链已终止，准备恢复到下一轮", reason=_reason)
    except Exception as _e:
        _record_swallowed_exception('round_abort.exec_batch_watch_finish', _e, _reason)
    try:
        _runtime_state_set(phase="ROUND_SUMMARY", state="SLEEPING", mainloop_state="RECOVERING_UI", reason_code=str(kind or "round_abort")[:120], msg=f"本轮已终止，准备恢复到下一轮：{_reason}"[:240], err=_reason[:240], extra={"recovery_pending": True, "recovery_reason": _reason, "recovery_kind": str(kind or 'round_abort')[:80], "recovery_source": _source, "recovery_pending_ts": float(time.time())})
    except Exception as _e:
        _record_swallowed_exception('round_abort.runtime_state_set', _e, _reason)
    try:
        _round_watch_finish("ROUND_SUMMARY", msg="本轮已终止，等待恢复轮", reason=str(kind or "round_abort")[:120], err=_reason, clear_trip=bool(clear_watchdog_trip))
    except Exception as _e:
        _record_swallowed_exception('round_abort.round_watch_finish', _e, _reason)
    try:
        if clear_watchdog_trip:
            _round_watchdog_clear_trip()
    except Exception as _e:
        _record_swallowed_exception('round_abort.watchdog_clear', _e, _reason)
    try:
        panel_set_mainloop_state(str(panel_state or "RECOVERING_UI"), hint=f"本轮已终止，准备恢复到下一轮：{_reason}"[:200], err=_reason[:240])
    except Exception as _e:
        _record_swallowed_exception('round_abort.panel_state', _e, _reason)
    try:
        _pw_runtime_hard_reset(_reason, source=_source, logfp=None, stop_exec_runtime=False, rebuild_worker=bool(rebuild_worker), touch_scan=bool(touch_scan))
    except Exception as _e:
        _record_swallowed_exception('round_abort.pw_runtime_hard_reset', _e, _reason)
    try:
        safe_log(lambda: f"[{now_ts()}] [{_source}] ROUND_ABORT_AND_RECOVERY reason={_reason} kind={str(kind or 'round_abort')} stop_exec={1 if stop_exec_runtime else 0} rebuild_worker={1 if rebuild_worker else 0} touch_scan={1 if touch_scan else 0}")
    except Exception as _e:
        _record_swallowed_exception('round_abort.safe_log', _e, _reason)
    return {"ok": True, "reason": _reason, "source": _source, "kind": str(kind or "round_abort")[:80], "panel_state": str(panel_state or "RECOVERING_UI")[:80]}

def _round_preflight_scrub_stale_state(*, scan_count: int = 0) -> dict:
    _actions: list[str] = []
    try:
        _rs = _runtime_state_snapshot() or {}
    except Exception:
        _rs = {}
    try:
        _rw = _round_watch_snapshot() or {}
    except Exception:
        _rw = {}
    try:
        _recovery = dict(globals().get("_ROUND_RECOVERY_ONCE") or {})
    except Exception:
        _recovery = {}
    try:
        _exec_watch = _exec_batch_watch_snapshot() or {}
    except Exception:
        _exec_watch = {}
    try:
        _scan_watch = _m2_scan_watch_snapshot() or {}
    except Exception:
        _scan_watch = {}
    try:
        _runtime_ready = (not _pw_runtime_is_recovering()) and bool(globals().get("PW_ALIVE", False))
    except Exception:
        _runtime_ready = False
    try:
        _exec_state = str((_exec_watch or {}).get("state") or "").upper().strip()
    except Exception:
        _exec_state = ""
    try:
        _scan_state = str((_scan_watch or {}).get("state") or "").upper().strip()
    except Exception:
        _scan_state = ""
    try:
        _recovery_age = max(0.0, float(time.time()) - float((_recovery or {}).get("ts") or 0.0)) if bool((_recovery or {}).get("active")) else 0.0
    except Exception:
        _recovery_age = 0.0
    try:
        _has_recovery_marks = any(k in (_rs or {}) for k in ("recovery_pending", "pw_recovering", "recovery_pending_ts", "pw_recover_started_ts"))
    except Exception:
        _has_recovery_marks = False
    if _runtime_ready and (bool((_recovery or {}).get("active")) or _has_recovery_marks):
        try:
            _runtime_state_clear_recovery_marks(f"preflight_scrub_ready:scan={int(scan_count or 0)}", clear_round_recovery_once=True)
            _actions.append("recovery_marks_cleared")
        except Exception as _e:
            _record_swallowed_exception('round_preflight.scrub_clear_recovery_marks', _e)
    if bool((_rw or {}).get("active")) and _exec_state in ("TIMEOUT", "ERROR") and (not _exec_runtime_cache_any()):
        try:
            _round_watch_finish("ABORTED", msg="preflight scrub stale round_watch", reason="preflight_scrub_stale_round_watch", err="", clear_trip=True)
            _actions.append(f"round_watch_cleared_after_exec_{_exec_state.lower()}")
        except Exception as _e:
            _record_swallowed_exception('round_preflight.scrub_round_watch', _e)
    if _scan_state == "RECOVERING_UI" and _runtime_ready and (not bool((globals().get("_ROUND_RECOVERY_ONCE") or {}).get("active"))):
        try:
            _m2_scan_watch_finish("IDLE", reason="preflight_scrub_recovering_ui_ready", touch_panel=False)
            _actions.append("scan_watch_recovering_ui_cleared")
        except Exception as _e:
            _record_swallowed_exception('round_preflight.scrub_scan_watch', _e)
    try:
        _ew = _exec_batch_watch_snapshot() or {}
    except Exception:
        _ew = {}
    if (not bool((_ew or {}).get("active"))) and str((_ew or {}).get("state") or "").upper().strip() in ("TIMEOUT", "ERROR"):
        try:
            _exec_batch_watch_finish("IDLE", msg="preflight scrub stale exec batch watch", reason="preflight_scrub_exec_watch")
            _actions.append("exec_batch_watch_idled")
        except Exception as _e:
            _record_swallowed_exception('round_preflight.scrub_exec_watch', _e)
    try:
        _trip = dict(globals().get("_ROUND_WATCHDOG_TRIPPED") or {})
    except Exception:
        _trip = {}
    if bool((_trip or {}).get("active")) and (not bool((_round_watch_snapshot() or {}).get("active"))):
        try:
            _round_watchdog_clear_trip()
            _actions.append("watchdog_trip_cleared")
        except Exception as _e:
            _record_swallowed_exception('round_preflight.scrub_watchdog_trip', _e)
    try:
        if _actions:
            safe_log(lambda: f"[{now_ts()}] [ROUND_PREFLIGHT] scrub scan={int(scan_count or 0)} actions={'|'.join(_actions[:8])} runtime_ready={1 if _runtime_ready else 0} recovery_age={float(_recovery_age):.1f}s")
    except Exception as _e:
        _record_swallowed_exception('round_preflight.scrub_safe_log', _e)
    return {"actions": list(_actions), "runtime_ready": bool(_runtime_ready), "recovery_age": float(_recovery_age)}

def _round_preflight_finalize_previous_round(*, scan_count: int = 0) -> dict:
    _issues: list[str] = []
    try:
        _scrub = _round_preflight_scrub_stale_state(scan_count=int(scan_count or 0))
    except Exception as _e:
        _record_swallowed_exception('round_preflight.scrub_entry', _e)
        _scrub = {"actions": []}
    try:
        _rs = _runtime_state_snapshot() or {}
    except Exception:
        _rs = {}
    try:
        _rw = _round_watch_snapshot() or {}
    except Exception:
        _rw = {}
    try:
        _trip = dict(globals().get("_ROUND_WATCHDOG_TRIPPED") or {})
    except Exception:
        _trip = {}
    try:
        _recovery = dict(globals().get("_ROUND_RECOVERY_ONCE") or {})
    except Exception:
        _recovery = {}
    try:
        _exec_watch = _exec_batch_watch_snapshot() or {}
    except Exception:
        _exec_watch = {}
    try:
        _scan_watch = _m2_scan_watch_snapshot() or {}
    except Exception:
        _scan_watch = {}
    _ml = str((_rs or {}).get("mainloop_state") or "").upper().strip()
    _ph = str((_rs or {}).get("round_phase") or "").upper().strip()
    _st = str((_rs or {}).get("round_state") or "").upper().strip()
    _exec_state = str((_exec_watch or {}).get("state") or "").upper().strip()
    _scan_state = str((_scan_watch or {}).get("state") or "").upper().strip()
    _recovery_age = 0.0
    try:
        _recovery_age = max(0.0, float(time.time()) - float((_recovery or {}).get("ts") or 0.0)) if bool((_recovery or {}).get("active")) else 0.0
    except Exception:
        _recovery_age = 0.0
    if bool((_trip or {}).get("active")):
        _issues.append(f"watchdog_tripped:{str((_trip or {}).get('reason') or '')[:80]}")
    if bool((_rw or {}).get("active")) and _exec_state in ("TIMEOUT", "ERROR"):
        _issues.append(f"round_watch_active_with_exec_{_exec_state.lower()}")
    if _ml == "EXECUTING" and _exec_state == "TIMEOUT":
        _issues.append("executing_timeout_conflict")
    if _scan_state == "RECOVERING_UI" and _recovery_age >= 15.0:
        _issues.append(f"recovering_ui_stale:{_recovery_age:.1f}s")
    if _ph == "STATE_COMMIT" and _st == "RUNNING" and not _exec_runtime_cache_any():
        _issues.append("state_commit_without_live_executor")
    if bool((_recovery or {}).get("active")) and _recovery_age >= 40.0:
        _issues.append(f"recovery_pending_hard_timeout:{_recovery_age:.1f}s")
    if not _issues:
        return {"clean": True, "issues": [], "scrub_actions": list((_scrub or {}).get("actions") or [])}
    _reason = f"preflight_cleanup|scan={int(scan_count or 0)}|{'|'.join(_issues[:6])}"[:240]
    try:
        _round_abort_and_schedule_recovery(_reason, source="ROUND_PREFLIGHT", kind="preflight_cleanup", panel_state="RECOVERING_UI", stop_exec_runtime=True, rebuild_worker=False, touch_scan=True, clear_watchdog_trip=True)
    except Exception as _e:
        _record_swallowed_exception('round_preflight.abort', _e, _reason)
    try:
        globals()["_ROUND_RECOVERY_ONCE"] = {"active": True, "reason": _reason, "kind": "preflight_cleanup", "ts": float(time.time())}
    except Exception as _e:
        _record_swallowed_exception('round_preflight.recovery_override', _e, _reason)
    try:
        safe_log(lambda: f"[{now_ts()}] [ROUND_PREFLIGHT] cleanup scan={int(scan_count or 0)} issues={'|'.join(_issues[:6])}")
    except Exception as _e:
        _record_swallowed_exception('round_preflight.safe_log', _e, _reason)
    return {"clean": False, "issues": list(_issues), "reason": _reason, "scrub_actions": list((_scrub or {}).get("actions") or [])}

def _m9_is_close_action(action_type: str) -> bool:
    try:
        act = str(action_type or '').lower().strip()
    except Exception:
        act = ''
    return act in {'decrease', 'reduce', 'close', 'tp', 'close_pair', 'close_all', 'close_full', 'partial_close', 'close_partial_notional'}

def _m9_is_open_action(action_type: str) -> bool:
    try:
        act = str(action_type or '').lower().strip()
    except Exception:
        act = ''
    return act in {'increase', 'open', 'add'}

def _req_is_protective_or_risk_reducing(req: Any) -> bool:
    try:
        mod = str(getattr(req, 'module', '') or (req.get('module') if isinstance(req, dict) else '') or '').upper().strip()
    except Exception:
        mod = ''
    try:
        act = str(getattr(req, 'action_type', '') or (req.get('action_type') if isinstance(req, dict) else '') or '').lower().strip()
    except Exception:
        act = ''
    if mod == 'M9':
        if _m9_is_close_action(act):
            return True
        if _m9_is_open_action(act):
            return False
    if mod in {'B2', 'S1', 'M10'}:
        return True
    if mod == 'B1':
        return False
    protective_acts = {'close', 'close_all', 'decrease', 'reduce', 'tp', 'trend_tp', 'partial_close', 'close_partial_notional', 'close_pair', 'close_full', 'm10_hard_tp', 'm10_hard_tp_reduce', 'm10_hard_tp_reduce_only'}
    if act in protective_acts:
        return True
    if 'close' in act or 'reduce' in act or 'tp' in act:
        return True
    return False

def _dq_apply_round_gate(snap: dict | None, *, last_good_snapshot: dict | None, last_good_ts: float, max_age_sec: float) -> tuple[dict | None, dict]:
    return _choose_round_snapshot(snap, last_good_snapshot=last_good_snapshot,
                                  last_good_ts=last_good_ts, max_age_sec=max_age_sec, now=time.time())

_GRID_OPEN_RATE_LEDGER: Dict[str, Dict[str, Any]] = {}   # coin -> {consecutive_opens,last_open_ts,open_ts_list}
_GRID_OPEN_RATE_LEDGER_LEG: Dict[str, Dict[str, Any]] = {}  # coin|platform|side -> {open_ts_list,last_open_ts}
_GRID_OPEN_PENDING_LEDGER: Dict[str, Dict[str, Any]] = {}  # req_id/pending_key -> pending meta
_GRID_COIN_PAUSE_LEDGER: Dict[str, Dict[str, Any]] = {}  # coin -> {paused_until, reason, bad_count, pause_set_ts, pause_expire_ts, auto_resume_rule, source_module, last_resume_ts}
_GRID_LEG_PAUSE_LEDGER: Dict[str, Dict[str, Any]] = {}  # coin|platform|side -> {paused_until, reason, bad_count, pause_set_ts, pause_expire_ts, auto_resume_rule, source_module, last_resume_ts}
_GRID_LEDGER_RESTORE_DONE = False
GRID_NEW_LAYER_CLOSE_PROTECT_SEC = 480.0
try:
    _GRID_LEDGER_STATE_FILE = os.path.join(os.path.dirname(__file__), "grid_rate_pause_ledger.json")
except Exception:
    _GRID_LEDGER_STATE_FILE = "grid_rate_pause_ledger.json"

def _grid_ledger_restore_once() -> None:
    global _GRID_LEDGER_RESTORE_DONE
    if _GRID_LEDGER_RESTORE_DONE:
        return
    _GRID_LEDGER_RESTORE_DONE = True
    try:
        if not os.path.exists(_GRID_LEDGER_STATE_FILE):
            return
        obj = safe_read_json(_GRID_LEDGER_STATE_FILE, default={})
        if isinstance(obj.get("open_rate"), dict):
            globals()["_GRID_OPEN_RATE_LEDGER"].update(obj.get("open_rate") or {})
        if isinstance(obj.get("open_rate_leg"), dict):
            globals()["_GRID_OPEN_RATE_LEDGER_LEG"].update(obj.get("open_rate_leg") or {})
        if isinstance(obj.get("open_pending"), dict):
            globals()["_GRID_OPEN_PENDING_LEDGER"].update(obj.get("open_pending") or {})
        if isinstance(obj.get("coin_pause"), dict):
            globals()["_GRID_COIN_PAUSE_LEDGER"].update(obj.get("coin_pause") or {})
        if isinstance(obj.get("leg_pause"), dict):
            globals()["_GRID_LEG_PAUSE_LEDGER"].update(obj.get("leg_pause") or {})
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_23', _e)
        pass
def _grid_ledger_persist() -> None:
    try:
        import json
        tmp = {
            "ts": float(time.time()),
            "open_rate": dict(globals().get("_GRID_OPEN_RATE_LEDGER") or {}),
            "open_rate_leg": dict(globals().get("_GRID_OPEN_RATE_LEDGER_LEG") or {}),
            "open_pending": dict(globals().get("_GRID_OPEN_PENDING_LEDGER") or {}),
            "coin_pause": dict(globals().get("_GRID_COIN_PAUSE_LEDGER") or {}),
            "leg_pause": dict(globals().get("_GRID_LEG_PAUSE_LEDGER") or {}),
        }
        with open(_GRID_LEDGER_STATE_FILE, "w", encoding="utf-8") as f:
            json.dump(tmp, f, ensure_ascii=False)
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_24', _e)
        pass
def _grid_now() -> float:
    try:
        return float(time.time())
    except Exception:
        return 0.0

def _grid_pause_reason_code(reason: Any) -> str:
    try:
        return str(reason or "").upper().strip().replace(" ", "_")[:120]
    except Exception:
        return ""

def _grid_pause_block_preselect_by_reason(reason: Any) -> bool:
    code = _grid_pause_reason_code(reason)
    return code in {
        "GRID_RISK_BLOCK_CONSEC_LIMIT",
        "GRID_RISK_BLOCK_HOURLY_LIMIT",
        "RSI_FETCH_FAIL",
        "SUBMIT_FAIL_PAUSE",
    } or code.startswith("RSI_STALE>")

def _grid_leg_pause_key(coin: str, platform: str, side: str) -> str:
    try:
        return f"{str(coin or '').upper().strip()}|{str(platform or '').upper().strip()}|{str(side or '').upper().strip()}"
    except Exception:
        return ""

def _grid_leg_pause_meta(coin: str, platform: str, side: str) -> Dict[str, Any]:
    key = _grid_leg_pause_key(coin, platform, side)
    if not key:
        return {}
    try:
        _grid_ledger_restore_once()
        obj = dict(_GRID_LEG_PAUSE_LEDGER.get(key) or {})
        obj["leg_key"] = key
        obj.setdefault("coin", str(coin or "").upper().strip())
        obj.setdefault("platform", str(platform or "").upper().strip())
        obj.setdefault("side", str(side or "").upper().strip())
        obj.setdefault("paused_until", float(obj.get("pause_expire_ts") or obj.get("paused_until") or 0.0))
        obj.setdefault("pause_expire_ts", float(obj.get("paused_until") or 0.0))
        obj.setdefault("pause_set_ts", float(obj.get("pause_set_ts") or 0.0))
        obj.setdefault("reason", str(obj.get("reason") or ""))
        obj.setdefault("pause_reason_code", _grid_pause_reason_code(obj.get("pause_reason_code") or obj.get("reason") or ""))
        obj.setdefault("block_preselect", bool(obj.get("block_preselect")) if ("block_preselect" in obj) else _grid_pause_block_preselect_by_reason(obj.get("pause_reason_code") or obj.get("reason") or ""))
        obj.setdefault("auto_resume_rule", str(obj.get("auto_resume_rule") or "expire_only"))
        obj.setdefault("source_module", str(obj.get("source_module") or "M9"))
        obj.setdefault("bad_count", int(obj.get("bad_count") or 0))
        return obj
    except Exception:
        return {}

def _grid_try_resume_leg(coin: str, platform: str, side: str, now_ts: float | None = None, *, force: bool = False) -> bool:
    key = _grid_leg_pause_key(coin, platform, side)
    if not key:
        return False
    try:
        _grid_ledger_restore_once()
        nowv = float(now_ts) if now_ts is not None else _grid_now()
        obj = dict(_GRID_LEG_PAUSE_LEDGER.get(key) or {})
        pu = float(obj.get("paused_until") or obj.get("pause_expire_ts") or 0.0)
        if (not force) and pu > float(nowv):
            return False
        if not obj:
            return True
        obj["last_resume_ts"] = float(nowv)
        obj["last_resume_reason"] = "ttl_expired" if not force else "force_resume"
        obj["paused_until"] = 0.0
        obj["pause_expire_ts"] = 0.0
        obj["reason"] = ""
        _GRID_LEG_PAUSE_LEDGER[key] = obj
        _grid_ledger_persist()
        return True
    except Exception:
        return False

def _grid_is_leg_paused(coin: str, platform: str, side: str, now_ts: float) -> bool:
    try:
        meta = _grid_leg_pause_meta(coin, platform, side)
        pu = float(meta.get("paused_until") or 0.0)
        if pu <= float(now_ts):
            _grid_try_resume_leg(coin, platform, side, now_ts)
            return False
        return True
    except Exception:
        return False

def _grid_pause_leg(coin: str, platform: str, side: str, *args, now_ts: float | None = None, pause_sec: float | None = None, reason: str = '', bad_inc: int = 1, auto_resume_rule: str = 'expire_only', source_module: str = 'M9', block_preselect: bool | None = None) -> None:
    try:
        _grid_ledger_restore_once()
        key = _grid_leg_pause_key(coin, platform, side)
        if not key:
            return
        nowv = float(now_ts) if now_ts is not None else _grid_now()
        dur_raw = pause_sec
        reason_raw = reason
        if len(args) >= 1 and dur_raw is None:
            dur_raw = args[0]
        if len(args) >= 2 and not reason_raw:
            reason_raw = args[1]
        if len(args) >= 2 and isinstance(args[0], (int, float)) and isinstance(args[1], (int, float)) and now_ts is None:
            nowv = float(args[0])
            dur_raw = float(args[1])
        dur = float(dur_raw) if dur_raw is not None else 0.0
        if dur < 0:
            dur = 0.0
        pu = nowv + dur
        obj = _GRID_LEG_PAUSE_LEDGER.get(key) or {}
        bc = int(obj.get("bad_count") or 0)
        bc = min(9999, max(0, bc + int(bad_inc or 1)))
        _reason_code = _grid_pause_reason_code(reason_raw or "")
        _block_preselect = bool(block_preselect) if block_preselect is not None else _grid_pause_block_preselect_by_reason(_reason_code)
        _GRID_LEG_PAUSE_LEDGER[key] = {
            "coin": str(coin or "").upper().strip(),
            "platform": str(platform or "").upper().strip(),
            "side": str(side or "").upper().strip(),
            "paused_until": float(pu),
            "pause_set_ts": float(nowv),
            "pause_expire_ts": float(pu),
            "reason": str(reason_raw or ""),
            "pause_reason_code": str(_reason_code or ""),
            "block_preselect": bool(_block_preselect),
            "bad_count": int(bc),
            "auto_resume_rule": str(auto_resume_rule or "expire_only"),
            "source_module": str(source_module or "M9"),
            "last_resume_ts": float(obj.get("last_resume_ts") or 0.0),
            "last_resume_reason": str(obj.get("last_resume_reason") or ""),
        }
        _grid_ledger_persist()
    except Exception:
        return

