def _grid_rate_state(coin: str) -> Dict[str, Any]:
    _grid_ledger_restore_once()
    c = str(coin or "").upper().strip()
    if not c:
        return {"consecutive_opens": 0, "last_open_ts": 0.0, "open_ts_list": []}
    st = _GRID_OPEN_RATE_LEDGER.get(c)
    if not isinstance(st, dict):
        st = {"consecutive_opens": 0, "last_open_ts": 0.0, "open_ts_list": []}
        _GRID_OPEN_RATE_LEDGER[c] = st
    if not isinstance(st.get("open_ts_list"), list):
        st["open_ts_list"] = []
    return st

def _grid_rate_check(coin: str, now_ts: float, *, max_consecutive: int = 5, max_per_hour: int = 2, consecutive_window_sec: float = 900.0) -> Tuple[bool, str, Dict[str, Any]]:
    """网格开仓限频：
    - 连续开仓次数 <= max_consecutive（默认 5）
    - 最近 1 小时开仓次数 <= max_per_hour（默认 2）
    返回: ok, reason, detail
    """
    c = str(coin or "").upper().strip()
    st = _grid_rate_state(c)
    try:
        ts_list = [float(x) for x in (st.get("open_ts_list") or []) if (x is not None)]
        ts_list = [x for x in ts_list if (float(now_ts) - float(x)) <= 3600.0 + 1e-6]
        st["open_ts_list"] = ts_list
    except Exception:
        st["open_ts_list"] = []
        ts_list = []
    try:
        consec = int(st.get("consecutive_opens") or 0)
    except Exception:
        consec = 0
    try:
        last_open = float(st.get("last_open_ts") or 0.0)
    except Exception:
        last_open = 0.0
    try:
        if last_open <= 0 or (float(now_ts) - float(last_open)) > float(consecutive_window_sec):
            consec = 0
    except Exception:
        consec = 0
    if consec >= int(max_consecutive):
        return False, "GRID_RISK_BLOCK_CONSEC_LIMIT", {"coin": c, "consecutive_opens": consec, "last_open_ts": last_open, "opens_last_hour": len(ts_list)}
    if len(ts_list) >= int(max_per_hour):
        try:
            oldest = min(ts_list) if ts_list else float(now_ts)
            wait = max(0.0, 3600.0 - (float(now_ts) - float(oldest)))
        except Exception:
            wait = 600.0
        return False, "GRID_RISK_BLOCK_HOURLY_LIMIT", {"coin": c, "consecutive_opens": consec, "last_open_ts": last_open, "opens_last_hour": len(ts_list), "wait_sec": wait}
    return True, "ok", {"coin": c, "consecutive_opens": consec, "last_open_ts": last_open, "opens_last_hour": len(ts_list)}

def _grid_rate_mark_open(coin: str, now_ts: float, *, consecutive_window_sec: float = 900.0) -> None:
    """成功开仓后记账。"""
    c = str(coin or "").upper().strip()
    st = _grid_rate_state(c)
    try:
        last_open = float(st.get("last_open_ts") or 0.0)
    except Exception:
        last_open = 0.0
    try:
        consec = int(st.get("consecutive_opens") or 0)
    except Exception:
        consec = 0
    try:
        if last_open > 0 and (float(now_ts) - float(last_open)) <= float(consecutive_window_sec):
            consec += 1
        else:
            consec = 1
    except Exception:
        consec = 1
    st["consecutive_opens"] = int(max(0, consec))
    st["last_open_ts"] = float(now_ts)
    try:
        ts_list = [float(x) for x in (st.get("open_ts_list") or []) if x is not None]
    except Exception:
        ts_list = []
    ts_list.append(float(now_ts))
    try:
        ts_list = [x for x in ts_list if (float(now_ts) - float(x)) <= 3600.0 + 1e-6]
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_25', _e)
        pass
    st["open_ts_list"] = ts_list
    _grid_ledger_persist()

MOD_LEGACY_FIX = "LEGACY_DELETED"
MOD_LOSSADD = "LOSSADD_DELETED"
TXT_LEGACY_FIX = "legacy_deleted"
KEY_LEGACY_FIX_MIN_HEDGE_U = "LEGACY_DELETED_MIN_HEDGE_U"
TAG_LEGACY_FIX = "[LEGACY_DELETED"
ACT_LEGACY_FIX_ONE_SHOT = "LEGACY_DELETED_ONE_SHOT"
ROLE_LEGACY_FIXER = "LEGACY_DELETER"

DELETED_MODULES = frozenset({"X1", "W1", "Z1", MOD_LEGACY_FIX, MOD_LOSSADD})

MODULE_LIFECYCLE_STATIC: Dict[str, str] = {
    _m: "DELETED" for _m in DELETED_MODULES
}

def _module_lifecycle_status(mod: str) -> str:
    try:
        mu = str(mod or "").upper().strip()
    except Exception:
        mu = ""
    if not mu:
        return "ENABLED"
    return str((MODULE_LIFECYCLE_STATIC or {}).get(mu) or "ENABLED")

def _module_is_standby(mod: str) -> bool:
    return str(_module_lifecycle_status(mod) or "").upper() in ("STANDBY", "DISABLED", "DELETED")

def _emit_module_standby(module: str, coin: str = "", *, stage: str = "STANDBY", reason: str = "module_disabled", platform: str = "", action_type: str = "", amount_u=None, push_probe=None) -> None:
    """统一输出模块待命证据：命令行 / probe_extra / 可选 probe_push。"""
    try:
        mod_u = str(module or "").upper().strip()
    except Exception:
        mod_u = str(module or "")
    try:
        coin_u = str(coin or "").upper().strip()
    except Exception:
        coin_u = str(coin or "")
    try:
        plat_u = str(platform or "").upper().strip()
    except Exception:
        plat_u = str(platform or "")
    try:
        act_u = str(action_type or "").lower().strip()
    except Exception:
        act_u = str(action_type or "")
    try:
        safe_log(lambda: f"[{now_ts()}] [STANDBY] module={mod_u} coin={coin_u or '-'} plat={plat_u or '-'} act={act_u or '-'} reason={reason}")
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_26', _e)
        pass
    try:
        probe_extra("module_standby", module=mod_u, coin=coin_u, platform=plat_u, action_type=act_u, reason=str(reason), stage=str(stage), amount_u=amount_u)
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_27', _e)
        pass
    if callable(push_probe):
        try:
            push_probe({
                "module": mod_u,
                "coin": coin_u,
                "platform": plat_u or None,
                "action_type": act_u or None,
                "intent_amount": amount_u,
                "std_amount": amount_u,
                "ok": False,
                "accept": 0,
                "reject": 1,
                "stage": str(stage or "STANDBY"),
                "type": "STANDBY",
                "reject_code": "module_disabled",
                "reject_reason": str(reason or "module_disabled"),
                "reason": str(reason or "module_disabled"),
            })
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_28', _e)
            pass
import math
import random

_GO_LAST_ORDER_AMT_U_BY_PLAT: dict[str, float] = {}
_GRID_LAST_U_HISTORY_BY_KEY: dict[tuple[str, str, str], list[float]] = {}
_AMT_WAVE_HISTORY_BY_KEY: dict[str, list[float]] = {}
FINAL_AMOUNT_FIELDS = ("final_amount_u", "amount_u", "amount_usd", "usd", "u", "amount", "notional_u")

def _coerce_final_amount_u(*vals) -> float:
    for x in vals:
        try:
            if x is None or x == "":
                continue
            v = float(x)
            if math.isfinite(v) and abs(v) > 0:
                return float(v)
        except Exception:
            continue
    return 0.0



def _m9_open_locked_amount_truth(reqd: dict | None, *, params: dict | None = None, meta: dict | None = None) -> tuple[float, str]:
    """M9 increase/open 金额单真相源：一旦锁定金额，就禁止后链覆盖。"""
    try:
        if not isinstance(reqd, dict):
            return 0.0, ''
        params = params if isinstance(params, dict) else (reqd.get('params') if isinstance(reqd.get('params'), dict) else {})
        meta = meta if isinstance(meta, dict) else (reqd.get('meta') if isinstance(reqd.get('meta'), dict) else {})
        mod = str(reqd.get('module') or meta.get('module') or params.get('module') or '').upper().strip()
        act = str(reqd.get('action_type') or params.get('action_type') or reqd.get('action') or '').lower().strip()
        _m9_open_acts = ('increase','add','grid_add','grid_increase','add_leg','open_leg','open_pair','open','open_first','open_single','open_single_leg')
        if mod != 'M9' or act not in _m9_open_acts:
            return 0.0, ''
        _lock_flag = bool(
            (meta.get('amount_locked_no_override') if isinstance(meta, dict) else False)
            or (params.get('amount_locked_no_override') if isinstance(params, dict) else False)
            or (reqd.get('amount_locked_no_override') if isinstance(reqd, dict) else False)
        )
        _lock_source = str(
            (meta.get('amount_locked_source') if isinstance(meta, dict) else '')
            or (params.get('amount_locked_source') if isinstance(params, dict) else '')
            or (reqd.get('amount_locked_source') if isinstance(reqd, dict) else '')
            or 'amount_locked_final_u_no_override'
        )
        _single_chain_locked = str(_lock_source or '').startswith('m9_open_single_chain_base_x_bias_x_trend')
        _locked_u = _coerce_final_amount_u(
            meta.get('amount_locked_final_u') if isinstance(meta, dict) else None,
            params.get('amount_locked_final_u') if isinstance(params, dict) else None,
            reqd.get('amount_locked_final_u') if isinstance(reqd, dict) else None,
            (meta.get('amt_det') or {}).get('final_u') if (isinstance(meta, dict) and isinstance(meta.get('amt_det'), dict)) else None,
            meta.get('amt_final_u') if isinstance(meta, dict) else None,
            (None if _single_chain_locked else (meta.get('open_amount_final_usd') if isinstance(meta, dict) else None)),
            (None if _single_chain_locked else (params.get('open_amount_final_usd') if isinstance(params, dict) else None)),
            (None if _single_chain_locked else (reqd.get('open_amount_final_usd') if isinstance(reqd, dict) else None)),
        )
        if float(_locked_u or 0.0) <= 0.0:
            return 0.0, ''
        if not _lock_flag:
            return 0.0, ''
        return float(_locked_u), _lock_source
    except Exception:
        return 0.0, ''
def _m9_dual_leg_rsi_bias_snapshot() -> dict:
    try:
        snap = globals().get('_BUDGET_LAST_SNAPSHOT') or globals().get('LAST_GOOD_SNAPSHOT') or {}
        return dict(snap or {}) if isinstance(snap, dict) else {}
    except Exception:
        return {}

def _m9_dual_leg_signed_notional_u(ext_pos: dict | None, var_pos: dict | None) -> float:
    def _signed(pos: dict | None) -> float:
        try:
            p = dict(pos or {}) if isinstance(pos, dict) else {}
        except Exception:
            p = {}
        n = abs(float(_pos_notional(p) or 0.0))
        s = str(p.get('side') or '').upper().strip()
        if s == 'LONG':
            return float(n)
        if s == 'SHORT':
            return -float(n)
        return 0.0
    return float(_signed(ext_pos) + _signed(var_pos))

def _m9_apply_dual_leg_rsi_bias(reqd: dict | None, base_amount_u: float, *, params: dict | None = None, meta: dict | None = None) -> tuple[float, dict]:
    det = {'enabled': bool(M9_RSI_DUAL_LEG_BIAS_ENABLE), 'applied': False, 'reason': '', 'mode': ''}
    try:
        if (not isinstance(reqd, dict)) or (not M9_RSI_DUAL_LEG_BIAS_ENABLE):
            det['reason'] = 'disabled_or_invalid_req'
            return float(base_amount_u or 0.0), det
        params = params if isinstance(params, dict) else (reqd.get('params') if isinstance(reqd.get('params'), dict) else {})
        meta = meta if isinstance(meta, dict) else (reqd.get('meta') if isinstance(reqd.get('meta'), dict) else {})
        mod = str(reqd.get('module') or meta.get('module') or params.get('module') or '').upper().strip()
        if not mod.startswith('M9'):
            det['reason'] = 'not_m9'
            return float(base_amount_u or 0.0), det
        act = str(reqd.get('action_type') or params.get('action_type') or reqd.get('action') or '').lower().strip()
        side = str(reqd.get('side') or params.get('side') or meta.get('side') or '').upper().strip()
        coin = str(reqd.get('coin') or params.get('coin') or meta.get('coin') or '').upper().strip()
        rsi_v = None
        for cand in (meta.get('ind_rsi'), ((meta.get('grid_decision_obs') or {}).get('rsi') if isinstance(meta.get('grid_decision_obs'), dict) else None), reqd.get('ind_rsi'), params.get('ind_rsi')):
            try:
                if cand is None or cand == '':
                    continue
                rsi_v = float(cand)
                break
            except Exception:
                continue
        if coin == '' or side not in ('LONG', 'SHORT') or rsi_v is None:
            det['reason'] = 'coin_side_or_rsi_missing'
            return float(base_amount_u or 0.0), det
        desired_sign = 1 if float(rsi_v) > 50.0 else (-1 if float(rsi_v) < 50.0 else 0)
        desired_side = 'LONG' if desired_sign > 0 else ('SHORT' if desired_sign < 0 else '')
        if desired_sign == 0 or side != desired_side:
            det['reason'] = 'request_side_not_biased'
            det['desired_side'] = desired_side
            det['rsi'] = float(rsi_v)
            return float(base_amount_u or 0.0), det
        snap = _m9_dual_leg_rsi_bias_snapshot()
        ext_pos = _get_position(snap, coin, 'EXT') or {}
        var_pos = _get_position(snap, coin, 'VAR') or {}
        ext_n = abs(float(_pos_notional(ext_pos) or 0.0))
        var_n = abs(float(_pos_notional(var_pos) or 0.0))
        total_n = float(ext_n + var_n)
        ext_side = str((ext_pos or {}).get('side') or '').upper().strip()
        var_side = str((var_pos or {}).get('side') or '').upper().strip()
        dual_leg = bool(ext_n > 1.0 and var_n > 1.0 and ext_side in ('LONG','SHORT') and var_side in ('LONG','SHORT') and ext_side != var_side)
        single_leg = bool((ext_n > 1.0) ^ (var_n > 1.0))
        strength = max(0.0, min(1.0, abs(float(rsi_v) - 50.0) / 50.0))
        target_pct = max(float(M9_RSI_DUAL_LEG_TARGET_FLOOR_PCT), min(float(M9_RSI_DUAL_LEG_TARGET_CAP_PCT), float(M9_RSI_DUAL_LEG_TARGET_FLOOR_PCT) + (float(M9_RSI_DUAL_LEG_TARGET_CAP_PCT) - float(M9_RSI_DUAL_LEG_TARGET_FLOOR_PCT)) * float(strength)))
        reduce_like = act in ('decrease', 'reduce', 'trim', 'tp', 'trend_tp', 'partial_close', 'close_partial_notional', 'close')
        desired_notional_u = 0.0
        other_notional_u = 0.0
        if desired_side == 'LONG':
            desired_notional_u = float((ext_n if ext_side == 'LONG' else 0.0) + (var_n if var_side == 'LONG' else 0.0))
            other_notional_u = float((ext_n if ext_side == 'SHORT' else 0.0) + (var_n if var_side == 'SHORT' else 0.0))
        elif desired_side == 'SHORT':
            desired_notional_u = float((ext_n if ext_side == 'SHORT' else 0.0) + (var_n if var_side == 'SHORT' else 0.0))
            other_notional_u = float((ext_n if ext_side == 'LONG' else 0.0) + (var_n if var_side == 'LONG' else 0.0))
        dominance_gap_u = float(desired_notional_u - other_notional_u)
        dominance_ok = bool(float(desired_notional_u) > float(other_notional_u) + float(M9_RSI_DIRECTIONAL_DOMINANCE_BUFFER_U))
        if reduce_like:
            det.update({
                'mode': ('dual_leg' if dual_leg else ('single_leg' if single_leg else 'neutral')),
                'reason': 'decrease_bias_disabled',
                'coin': coin,
                'act': act,
                'side': side,
                'desired_side': desired_side,
                'rsi': float(rsi_v),
                'strength': float(strength),
                'target_pct': float(target_pct),
                'ext_side': ext_side,
                'ext_notional_u': float(ext_n),
                'var_side': var_side,
                'var_notional_u': float(var_n),
                'total_notional_u': float(total_n),
                'desired_notional_u': float(desired_notional_u),
                'other_notional_u': float(other_notional_u),
                'dominance_gap_u': float(dominance_gap_u),
                'dominance_ok': bool(dominance_ok),
                'factor': 1.0,
                'base_amount_u': float(base_amount_u or 0.0),
                'tp_contract_u': float(base_amount_u or 0.0),
                'bias_extra_u': 0.0,
                'adjusted_amount_u': float(base_amount_u or 0.0),
                'human': 'M9 减仓/平仓链已物理切断 RSI 偏置，保持原始合同金额不变',
            })
            return float(base_amount_u or 0.0), det
        if not (dual_leg or single_leg):
            det.update({
                'reason': 'not_dual_or_single_leg',
                'ext_notional_u': float(ext_n),
                'var_notional_u': float(var_n),
                'ext_side': ext_side,
                'var_side': var_side,
                'total_notional_u': float(total_n),
                'desired_notional_u': float(desired_notional_u),
                'other_notional_u': float(other_notional_u),
                'dominance_gap_u': float(dominance_gap_u),
                'dominance_ok': bool(dominance_ok),
                'target_pct': float(target_pct),
                'rsi': float(rsi_v),
                'desired_side': desired_side,
            })
            return float(base_amount_u or 0.0), det
        mode = 'dual_leg' if dual_leg else 'single_leg'
        det['mode'] = mode
        if dominance_ok:
            det.update({
                'reason': 'direction_already_ok',
                'coin': coin,
                'act': act,
                'side': side,
                'desired_side': desired_side,
                'rsi': float(rsi_v),
                'strength': float(strength),
                'target_pct': float(target_pct),
                'ext_side': ext_side,
                'ext_notional_u': float(ext_n),
                'var_side': var_side,
                'var_notional_u': float(var_n),
                'total_notional_u': float(total_n),
                'desired_notional_u': float(desired_notional_u),
                'other_notional_u': float(other_notional_u),
                'dominance_gap_u': float(dominance_gap_u),
                'dominance_ok': True,
                'factor': 1.0,
                'base_amount_u': float(base_amount_u or 0.0),
                'tp_contract_u': float(base_amount_u or 0.0),
                'bias_extra_u': 0.0,
                'adjusted_amount_u': float(base_amount_u or 0.0),
                'human': (f'方向已满足：RSI={float(rsi_v):.2f} 目标方向={desired_side} '
                          f'主方向持仓={float(desired_notional_u):.2f}U 非主方向={float(other_notional_u):.2f}U，本次保持原合同'),
            })
            return float(base_amount_u or 0.0), det
        extra_mult = max(0.0, float(M9_RSI_DIRECTIONAL_EXTRA_OPEN_MULT))
        bias_extra_u = float(_half_up_round(max(10.0, float(base_amount_u or 0.0) * float(extra_mult)), float(M9_RSI_DUAL_LEG_BIAS_ROUND_STEP_U)))
        adjusted_u = float(_half_up_round(max(10.0, float(base_amount_u or 0.0) + float(bias_extra_u)), float(M9_RSI_DUAL_LEG_BIAS_ROUND_STEP_U)))
        factor = float(adjusted_u / float(base_amount_u)) if float(base_amount_u or 0.0) > 0.0 else 1.0
        det.update({
            'applied': True,
            'reason': 'direction_not_dominant_add_extra',
            'coin': coin,
            'act': act,
            'side': side,
            'desired_side': desired_side,
            'rsi': float(rsi_v),
            'strength': float(strength),
            'target_pct': float(target_pct),
            'ext_side': ext_side,
            'ext_notional_u': float(ext_n),
            'var_side': var_side,
            'var_notional_u': float(var_n),
            'total_notional_u': float(total_n),
            'desired_notional_u': float(desired_notional_u),
            'other_notional_u': float(other_notional_u),
            'dominance_gap_u': float(dominance_gap_u),
            'dominance_ok': False,
            'extra_open_mult': float(extra_mult),
            'factor': float(factor),
            'base_amount_u': float(base_amount_u or 0.0),
            'tp_contract_u': float(base_amount_u or 0.0),
            'bias_extra_u': float(bias_extra_u),
            'adjusted_amount_u': float(adjusted_u),
            'target_formula': '若RSI主方向持仓未大于非主方向，则本次开仓=原合同+同额方向补量；后续平仓仍按原合同',
            'human': (f'方向补量: RSI={float(rsi_v):.2f} 目标方向={desired_side} '
                      f'主方向持仓={float(desired_notional_u):.2f}U 非主方向={float(other_notional_u):.2f}U '
                      f'未满足主方向占优，因此原合同={float(base_amount_u or 0.0):.2f}U，额外补量={float(bias_extra_u):.2f}U，'
                      f'本次实际开仓={float(adjusted_u):.2f}U'),
        })
        return float(adjusted_u), det
    except Exception as _e:
        try:
            det['reason'] = 'bias_exception'
            det['exc'] = str(_e)[:240]
        except Exception:
            pass
        return float(base_amount_u or 0.0), det

def _m9_reduce_contract_locked_amount(reqd: dict | None, requested_u: float | None, *, params: dict | None = None, meta: dict | None = None) -> tuple[float, dict]:
    """M9 减仓唯一金额合同：只认目标 layer 真相，禁止退化到整腿/整平台名义。"""
    detail: dict = {}
    try:
        if not isinstance(reqd, dict):
            return 0.0, {'reason': 'invalid_req'}
        params = params if isinstance(params, dict) else (reqd.get('params') if isinstance(reqd.get('params'), dict) else {})
        meta = meta if isinstance(meta, dict) else (reqd.get('meta') if isinstance(reqd.get('meta'), dict) else {})
        mod = str(reqd.get('module') or meta.get('module') or params.get('module') or '').upper().strip()
        act = str(reqd.get('action_type') or params.get('action_type') or reqd.get('action') or '').lower().strip()
        reduce_acts = ('decrease', 'reduce', 'trim', 'tp', 'trend_tp', 'partial_close', 'close_partial_notional', 'close')
        if mod != 'M9' or act not in reduce_acts:
            return float(_safe_float(requested_u, 0.0) or 0.0), {'reason': 'not_m9_reduce'}
        gid = str(meta.get('grid_id') or params.get('grid_id') or reqd.get('grid_id') or '').strip()
        lid = str(meta.get('layer_id') or params.get('layer_id') or reqd.get('layer_id') or '').strip()
        grid_layer = None
        for cand in (
            reqd.get('grid_layer'),
            params.get('grid_layer') if isinstance(params, dict) else None,
            meta.get('grid_layer') if isinstance(meta, dict) else None,
        ):
            if isinstance(cand, dict) and cand:
                grid_layer = dict(cand)
                break
        if (not isinstance(grid_layer, dict) or not grid_layer) and gid and lid:
            try:
                if ('GRID_BOOK' in globals()) and (globals().get('GRID_BOOK') is not None) and hasattr(GRID_BOOK, '_find_layer'):
                    _found = GRID_BOOK._find_layer(str(gid), str(lid))
                    if isinstance(_found, dict) and _found:
                        grid_layer = dict(_found)
            except Exception as _e:
                _record_swallowed_exception('m9_reduce_contract_find_layer', _e)
        if not isinstance(grid_layer, dict) or not grid_layer:
            detail.update({'reason': 'm9_reduce_layer_missing', 'grid_id': gid, 'layer_id': lid, 'requested_u': float(_safe_float(requested_u, 0.0) or 0.0)})
            return 0.0, detail
        cur_px = _safe_float(
            meta.get('cur_px') or params.get('cur_px') or reqd.get('cur_px') or grid_layer.get('cur_px') or grid_layer.get('mark_px') or grid_layer.get('mark'),
            None,
        )
        close_u, truth = _m9_layer_close_truth_u(grid_layer, cur_px=cur_px)
        requested_f = float(_safe_float(requested_u, 0.0) or 0.0)
        truth_close_u = float(_safe_float(close_u, 0.0) or 0.0)
        final_u = float(min(requested_f if requested_f > 0.0 else truth_close_u, truth_close_u)) if truth_close_u > 0.0 else 0.0
        detail.update({
            'reason': 'm9_reduce_layer_truth_locked' if final_u > 0.0 else 'm9_reduce_layer_truth_invalid',
            'grid_id': gid,
            'layer_id': lid or str(grid_layer.get('layer_id') or ''),
            'requested_u': float(requested_f),
            'truth_close_u': float(truth_close_u),
            'final_u': float(final_u),
            'truth_scope': str((truth or {}).get('truth_scope') or 'grid_layer_only'),
            'truth': dict(truth or {}),
            'cur_px': cur_px,
        })
        return float(final_u), detail
    except Exception as _e:
        return 0.0, {'reason': 'm9_reduce_contract_exception', 'exc': str(_e)[:240]}



def _m9_open_single_chain_amount(reqd: dict | None, *, params: dict | None = None, meta: dict | None = None, amount_hint: float | None = None) -> tuple[float, dict]:
    """M9 开仓单链金额合同：先算原计划层合同，再按RSI方向仓型是否占优决定是否补方向仓。"""
    det: dict = {}
    try:
        if not isinstance(reqd, dict):
            return 0.0, {'reason': 'invalid_req'}
        params = params if isinstance(params, dict) else (reqd.get('params') if isinstance(reqd.get('params'), dict) else {})
        meta = meta if isinstance(meta, dict) else (reqd.get('meta') if isinstance(reqd.get('meta'), dict) else {})
        grid_obs = dict((meta.get('grid_decision_obs') or reqd.get('grid_decision_obs') or {}) if isinstance(meta.get('grid_decision_obs') or reqd.get('grid_decision_obs'), dict) else {})
        bucket_det = dict((grid_obs.get('bucket_det') or {}) if isinstance(grid_obs.get('bucket_det'), dict) else {})
        base_u = 0.0
        for cand in (
            meta.get('m9_rsi_bias_base_amount_u'),
            grid_obs.get('amount_u'),
            grid_obs.get('new_coin_grid_final_u'),
            grid_obs.get('amount_after_cap_u'),
            grid_obs.get('amount_post_bucket_cap_u'),
            grid_obs.get('coin_base_amount_u'),
            bucket_det.get('picked_after_new_coin_scale'),
            bucket_det.get('picked'),
            meta.get('m9_amount_map_locked_u'),
            meta.get('open_amount_base_usd'),
            amount_hint,
            reqd.get('final_amount_u'),
            reqd.get('amount_u'),
            reqd.get('amount_usd'),
            params.get('final_amount_u') if isinstance(params, dict) else None,
            params.get('amount_u') if isinstance(params, dict) else None,
            params.get('amount_usd') if isinstance(params, dict) else None,
        ):
            try:
                cand_f = float(cand or 0.0)
            except Exception:
                cand_f = 0.0
            if cand_f > 0.0:
                base_u = float(cand_f)
                break
        base_u = float(_round_usd10(base_u)) if float(base_u or 0.0) > 0.0 else 0.0
        trend_factor = 1.0
        for cand in (
            meta.get('trend_amount_mult_used'),
            grid_obs.get('trend_amount_mult_used'),
            ((meta.get('trend_breakout') or {}) if isinstance(meta.get('trend_breakout'), dict) else {}).get('amount_mult'),
            ((grid_obs.get('trend_breakout_det') or {}) if isinstance(grid_obs.get('trend_breakout_det'), dict) else {}).get('amount_mult'),
        ):
            try:
                cand_f = float(cand or 0.0)
            except Exception:
                cand_f = 0.0
            if cand_f > 0.0:
                trend_factor = float(cand_f)
                break
        if trend_factor <= 0.0:
            trend_factor = 1.0
        plan_u = 0.0
        if float(base_u or 0.0) > 0.0:
            plan_u = float(_round_usd10(max(10.0, float(base_u) * float(trend_factor))))
        bias_det = {}
        final_u = float(plan_u or 0.0)
        if float(plan_u or 0.0) > 0.0:
            try:
                _bias_adj_u, bias_det = _m9_apply_dual_leg_rsi_bias(reqd, float(plan_u), params=params, meta=meta)
            except Exception as _e:
                _record_swallowed_exception('m9_open_single_chain_amount.bias', _e)
                _bias_adj_u, bias_det = float(plan_u), {'reason': 'bias_exception'}
            final_u = float(_round_usd10(max(float(plan_u or 0.0), float(_bias_adj_u or 0.0))))
        bias_det = dict(bias_det or {})
        bias_extra_u = float(max(0.0, float(final_u or 0.0) - float(plan_u or 0.0)))
        bias_factor = float(final_u / plan_u) if float(plan_u or 0.0) > 0.0 else 1.0
        det = {
            'reason': 'm9_open_single_chain_base_x_bias_x_trend',
            'base_amount_u': float(base_u or 0.0),
            'plan_u': float(plan_u or 0.0),
            'tp_contract_u': float(plan_u or 0.0),
            'bias_extra_u': float(bias_extra_u),
            'bias_factor': float(bias_factor),
            'trend_factor': float(trend_factor),
            'final_u': float(final_u or 0.0),
            'bias_detail': dict(bias_det or {}),
            'formula': 'plan_u = round10(base_u × 趋势乘数); final_u = plan_u + 方向补量（仅当RSI主方向未占优时）；后续平仓仍按 plan_u',
        }
        if isinstance(bias_det, dict) and bias_det:
            bias_det['single_chain_formula'] = det['formula']
            bias_det['single_chain_plan_u'] = float(plan_u or 0.0)
            bias_det['single_chain_final_u'] = float(final_u or 0.0)
            bias_det['locked_passthrough'] = False
            bias_det['locked_amount_u'] = float(final_u or 0.0)
            bias_det['locked_source'] = 'm9_open_single_chain_base_x_bias_x_trend'
            bias_det['tp_contract_u'] = float(plan_u or 0.0)
            bias_det['bias_extra_u'] = float(bias_extra_u)
            bias_det['post_lock_adjusted_amount_u'] = float(final_u or 0.0)
        det['bias_detail'] = dict(bias_det or {})
        return float(final_u or 0.0), det
    except Exception as _e:
        return 0.0, {'reason': 'm9_open_single_chain_amount_exception', 'exc': str(_e)[:240]}

