def _apply_final_amount_contract_to_request(req_obj, amount_hint: float | None = None) -> float:
    """把最终金额合同强制写回 Request 对象本身、params、meta，避免 picked>0 但入队/执行读到 0。"""
    try:
        if req_obj is None:
            return 0.0
        params = getattr(req_obj, "params", None)
        if not isinstance(params, dict):
            params = {}
            try:
                setattr(req_obj, "params", params)
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_29', _e)
                pass
        meta = getattr(req_obj, "meta", None)
        if not isinstance(meta, dict):
            meta = {}
            try:
                setattr(req_obj, "meta", meta)
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_30', _e)
                pass
        _mod_u = str(getattr(req_obj, "module", "") or meta.get("module") or params.get("module") or "").upper().strip()
        _is_m9 = bool(_mod_u.startswith("M9"))
        if _is_m9:
            hint = _coerce_final_amount_u(
                amount_hint,
                getattr(req_obj, "final_amount_u", None), getattr(req_obj, "amount_u", None), getattr(req_obj, "amount_usd", None), getattr(req_obj, "usd", None), getattr(req_obj, "u", None), getattr(req_obj, "amount", None), getattr(req_obj, "notional_u", None),
                params.get("final_amount_u"), params.get("amount_u"), params.get("amount_usd"), params.get("usd"), params.get("u"), params.get("amount"), params.get("notional_u"), params.get("add_notional_u"), params.get("close_notional_u"),
                meta.get("final_amount_u"), meta.get("amount_u"), meta.get("amount_usd"), meta.get("usd"), meta.get("u"), meta.get("amount"), meta.get("notional_u"), meta.get("add_notional_u"), meta.get("close_notional_u"),
                ((meta.get("amt_det") or {}).get("final_u") if isinstance(meta.get("amt_det"), dict) else None),
                ((meta.get("amt_det") or {}).get("picked") if isinstance(meta.get("amt_det"), dict) else None),
                ((meta.get("amt_det") or {}).get("u") if isinstance(meta.get("amt_det"), dict) else None),
            )
        else:
            hint = _coerce_final_amount_u(
                amount_hint,
                getattr(req_obj, "final_amount_u", None), getattr(req_obj, "amount_u", None), getattr(req_obj, "amount_usd", None), getattr(req_obj, "usd", None), getattr(req_obj, "u", None), getattr(req_obj, "amount", None), getattr(req_obj, "notional_u", None),
                params.get("final_amount_u"), params.get("amount_u"), params.get("amount_usd"), params.get("usd"), params.get("u"), params.get("amount"), params.get("notional_u"), params.get("add_notional_u"), params.get("close_notional_u"),
                meta.get("final_amount_u"), meta.get("amount_u"), meta.get("amount_usd"), meta.get("usd"), meta.get("u"), meta.get("amount"), meta.get("notional_u"),
                ((meta.get("amt_det") or {}).get("final_u") if isinstance(meta.get("amt_det"), dict) else None),
                ((meta.get("amt_det") or {}).get("picked") if isinstance(meta.get("amt_det"), dict) else None),
                ((meta.get("amt_det") or {}).get("u") if isinstance(meta.get("amt_det"), dict) else None),
            )
        rd = {"module": getattr(req_obj, "module", ""), "params": params, "meta": meta}
        final_u = _apply_final_amount_contract(rd, params=params, meta=meta, amount_hint=hint)
        if final_u > 0:
            act = str(getattr(req_obj, "action_type", "") or "").lower().strip()
            for k in FINAL_AMOUNT_FIELDS + ("intent_amount", "amount_usd_intent"):
                try:
                    setattr(req_obj, k, float(final_u))
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_31', _e)
                    pass
            params["intent_amount"] = float(final_u)
            params["amount_usd_intent"] = float(final_u)
            params["notional_u"] = float(final_u)
            meta["intent_amount"] = float(final_u)
            meta["amount_usd_intent"] = float(final_u)
            meta["notional_u"] = float(final_u)
            if act == "decrease":
                params["close_notional_u"] = float(final_u)
                meta["close_notional_u"] = float(final_u)
            else:
                params["add_notional_u"] = float(final_u)
                meta["add_notional_u"] = float(final_u)
            try:
                _bias_det = dict(meta.get('m9_rsi_leg_bias') or meta.get('m9_rsi_dual_leg_bias') or {}) if isinstance(meta.get('m9_rsi_leg_bias') or meta.get('m9_rsi_dual_leg_bias'), dict) else {}
                if _mod_u.startswith('M9'):
                    safe_log(lambda: f"[{now_ts()}] [M9_RSI_BIAS] coin={str(getattr(req_obj,'coin','') or meta.get('coin') or '').upper()} platform={str(getattr(req_obj,'platform','') or meta.get('platform') or '').upper()} act={act} side={str(getattr(req_obj,'side','') or meta.get('side') or '').upper()} final_u={float(final_u):.2f} applied={1 if _bias_det.get('applied') else 0} mode={str(_bias_det.get('mode') or '')} factor={float(_bias_det.get('factor') or 1.0):.3f} reason={str(_bias_det.get('reason') or '')} rsi={float(_bias_det.get('rsi') or 0.0):.2f} strength={float(_bias_det.get('strength') or 0.0):.3f} target_pct={float(_bias_det.get('target_pct') or 0.0):.4f} current_signed_u={float(_bias_det.get('current_signed_u') or 0.0):.2f} target_signed_u={float(_bias_det.get('target_signed_u') or 0.0):.2f} shortfall_u={float(_bias_det.get('shortfall_u') or 0.0):.2f}")
            except Exception as _e:
                _record_swallowed_exception('m9_dual_leg_rsi_bias_log', _e)
            try:
                setattr(req_obj, "params", params)
                setattr(req_obj, "meta", meta)
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_32', _e)
                pass
        return float(final_u)
    except Exception:
        return 0.0

def _is_b1_new_coin_first_open_req(reqd: dict | None, *, params: dict | None = None, meta: dict | None = None) -> bool:
    """兼容旧函数名：实际判定的是 B1 单腿首开/缺腿补齐请求，而不再只限“新币首开”。

    修复口径：
    - selector_waiting_head_open / normal_no_leg_first_open / missing_leg_first_open
      都属于 B1 单腿首开主链，必须共用同一套金额真相源。
    - 不能再因为“不是动态新币”就跳过金额锁定/硬顶预检输入修复，
      否则像 ZEC 这种老币在 B2 全平后重开，会再次掉进 amount_missing 假硬顶。
    """
    try:
        if not isinstance(reqd, dict):
            return False
        params = params if isinstance(params, dict) else (reqd.get("params") if isinstance(reqd.get("params"), dict) else {})
        meta = meta if isinstance(meta, dict) else (reqd.get("meta") if isinstance(reqd.get("meta"), dict) else {})
        mod = str(reqd.get("module") or meta.get("module") or params.get("module") or "").upper().strip()
        if mod != "B1":
            return False
        act = str(_canon_action_type(reqd.get("action_type") or reqd.get("action") or params.get("action_type") or meta.get("action_type") or "") or reqd.get("action_type") or reqd.get("action") or "").lower().strip()
        if act not in ("open_leg", "open_single_leg", "open_single", "open", "open_first", "open_more"):
            return False
        coin = str(reqd.get("coin") or reqd.get("symbol") or params.get("coin") or meta.get("coin") or "").upper().strip()
        if not coin:
            return False
        plat = str(reqd.get("platform") or params.get("platform") or meta.get("platform") or params.get("B1__platform") or meta.get("B1__platform") or "").upper().strip()
        if plat in ("PAIR", "GROUP", "BOTH"):
            return False
        return True
    except Exception:
        return False

def _b1_first_open_expected_amount_u(reqd: dict | None, *, params: dict | None = None, meta: dict | None = None) -> float:
    try:
        if not isinstance(reqd, dict):
            return 0.0
        params = params if isinstance(params, dict) else (reqd.get("params") if isinstance(reqd.get("params"), dict) else {})
        meta = meta if isinstance(meta, dict) else (reqd.get("meta") if isinstance(reqd.get("meta"), dict) else {})
        if not _is_b1_new_coin_first_open_req(reqd, params=params, meta=meta):
            return 0.0
        return float(_coerce_final_amount_u(
            meta.get("amount_locked_final_u"),
            meta.get("b1_amount_expected_u"),
            params.get("B1__amount_usd"), meta.get("B1__amount_usd"),
            reqd.get("amount_usd_intent"), params.get("amount_usd_intent"), meta.get("amount_usd_intent"),
            reqd.get("intent_amount"), params.get("intent_amount"), meta.get("intent_amount"),
            ((meta.get("extras") or {}).get("amount_usd_intent") if isinstance(meta.get("extras"), dict) else None),
        ) or 0.0)
    except Exception:
        return 0.0

def _lock_b1_first_open_amount_contract(reqd: dict | None, amount_u: float | None, *, source: str = "b1_first_open_scaled_single_source") -> float:
    try:
        if not isinstance(reqd, dict):
            return 0.0
        params = reqd.get("params") if isinstance(reqd.get("params"), dict) else {}
        meta = reqd.get("meta") if isinstance(reqd.get("meta"), dict) else {}
        if not _is_b1_new_coin_first_open_req(reqd, params=params, meta=meta):
            return 0.0
        try:
            amt = float(amount_u or 0.0)
        except Exception:
            amt = 0.0
        if amt <= 0.0:
            return 0.0
        _apply_final_amount_contract(reqd, params=params, meta=meta, amount_hint=float(amt))
        for k in FINAL_AMOUNT_FIELDS + ("intent_amount", "amount_usd_intent"):
            reqd[k] = float(amt)
            params[k] = float(amt)
            meta[k] = float(amt)
        params["B1__amount_usd"] = float(amt)
        meta["B1__amount_usd"] = float(amt)
        meta["b1_amount_expected_u"] = float(amt)
        if isinstance(meta.get("extras"), dict):
            meta["extras"]["amount_usd_intent"] = float(amt)
        meta["b1_amount_locked"] = True
        meta["amount_locked_final_u"] = float(amt)
        meta["amount_locked_source"] = str(source or "b1_first_open_scaled_single_source")
        meta["amount_locked_no_override"] = True
        meta["no_random_amount"] = True
        meta["open_amount_jitter_skip"] = True
        meta["amt_final_u"] = float(amt)
        meta["amt_final_source"] = str(source or "b1_first_open_scaled_single_source")
        meta["m1_std_reason"] = "b1_first_open_scaled_locked"
        meta["m1_std_amt_final"] = float(amt)
        meta["amt_det"] = {
            "ok": 1,
            "reason": str(source or "b1_first_open_scaled_single_source"),
            "picked": float(amt),
            "final_u": float(amt),
            "u": float(amt),
            "final_source": str(source or "b1_first_open_scaled_single_source"),
        }
        reqd["params"] = params
        reqd["meta"] = meta
        return float(amt)
    except Exception:
        return 0.0

def _b1_first_open_amount_contract_sync(reqd: dict | None, *, source: str = "b1_first_open_scaled_single_source") -> tuple[bool, str, dict]:
    detail: dict = {}
    try:
        if not isinstance(reqd, dict):
            return True, "skip:req_not_dict", detail
        params = reqd.get("params") if isinstance(reqd.get("params"), dict) else {}
        meta = reqd.get("meta") if isinstance(reqd.get("meta"), dict) else {}
        if not _is_b1_new_coin_first_open_req(reqd, params=params, meta=meta):
            return True, "skip:not_b1_new_coin_first_open", detail
        expected = float(_b1_first_open_expected_amount_u(reqd, params=params, meta=meta) or 0.0)
        current = float(_coerce_final_amount_u(
            reqd.get("final_amount_u"), reqd.get("amount_u"), reqd.get("amount_usd"), reqd.get("usd"), reqd.get("u"), reqd.get("amount"), reqd.get("notional_u"),
            params.get("final_amount_u"), params.get("amount_u"), params.get("amount_usd"), params.get("usd"), params.get("u"), params.get("amount"), params.get("notional_u"),
            meta.get("final_amount_u"), meta.get("amount_u"), meta.get("amount_usd"), meta.get("usd"), meta.get("u"), meta.get("amount"), meta.get("notional_u"),
            ((meta.get("amt_det") or {}).get("final_u") if isinstance(meta.get("amt_det"), dict) else None),
            ((meta.get("amt_det") or {}).get("picked") if isinstance(meta.get("amt_det"), dict) else None),
        ) or 0.0)
        detail.update({
            "module": str(reqd.get("module") or ""),
            "coin": str(reqd.get("coin") or ""),
            "platform": str(reqd.get("platform") or ""),
            "action_type": str(reqd.get("action_type") or ""),
            "expected_u": float(expected),
            "current_u": float(current),
            "B1__amount_usd": float(_safe_float(params.get("B1__amount_usd") or meta.get("B1__amount_usd"), 0.0)),
            "amount_usd_intent": float(_safe_float(reqd.get("amount_usd_intent") or params.get("amount_usd_intent") or meta.get("amount_usd_intent"), 0.0)),
            "intent_amount": float(_safe_float(reqd.get("intent_amount") or params.get("intent_amount") or meta.get("intent_amount"), 0.0)),
            "amount_usd": float(_safe_float(reqd.get("amount_usd") or params.get("amount_usd") or meta.get("amount_usd"), 0.0)),
        })
        if expected <= 0.0:
            return False, "b1_expected_amount_missing", detail
        legacy_deleteded = False
        if current <= 0.0 or abs(float(current) - float(expected)) > 1e-9:
            legacy_deleteded = bool(_lock_b1_first_open_amount_contract(reqd, expected, source=source) > 0.0)
        after = float(_coerce_final_amount_u(
            reqd.get("final_amount_u"), reqd.get("amount_u"), reqd.get("amount_usd"), reqd.get("usd"), reqd.get("u"), reqd.get("amount"), reqd.get("notional_u"),
            params.get("final_amount_u"), params.get("amount_u"), params.get("amount_usd"), params.get("usd"), params.get("u"), params.get("amount"), params.get("notional_u"),
            meta.get("final_amount_u"), meta.get("amount_u"), meta.get("amount_usd"), meta.get("usd"), meta.get("u"), meta.get("amount"), meta.get("notional_u"),
            ((meta.get("amt_det") or {}).get("final_u") if isinstance(meta.get("amt_det"), dict) else None),
            ((meta.get("amt_det") or {}).get("picked") if isinstance(meta.get("amt_det"), dict) else None),
        ) or 0.0)
        detail["after_u"] = float(after)
        detail["legacy_deleteded"] = bool(legacy_deleteded)
        if after <= 0.0 or abs(float(after) - float(expected)) > 1e-9:
            return False, "b1_amount_conflict_still_present", detail
        return True, ("legacy_deleteded" if legacy_deleteded else "ok"), detail
    except Exception as _e:
        detail["exc"] = repr(_e)
        return False, "b1_amount_contract_exception", detail

def _request_obj_b1_first_open_amount_guard(req_obj: Any, *, source: str = "b1_first_open_scaled_single_source") -> tuple[bool, str, dict]:
    detail: dict = {}
    try:
        if req_obj is None:
            return True, "skip:req_none", detail
        params = getattr(req_obj, "params", None)
        if not isinstance(params, dict):
            params = {}
            setattr(req_obj, "params", params)
        meta = getattr(req_obj, "meta", None)
        if not isinstance(meta, dict):
            meta = {}
            setattr(req_obj, "meta", meta)
        rd = {
            "module": getattr(req_obj, "module", ""),
            "coin": getattr(req_obj, "coin", ""),
            "platform": getattr(req_obj, "platform", ""),
            "action_type": getattr(req_obj, "action_type", ""),
            "params": params,
            "meta": meta,
            "final_amount_u": getattr(req_obj, "final_amount_u", None),
            "amount_u": getattr(req_obj, "amount_u", None),
            "amount_usd": getattr(req_obj, "amount_usd", None),
            "usd": getattr(req_obj, "usd", None),
            "u": getattr(req_obj, "u", None),
            "amount": getattr(req_obj, "amount", None),
            "notional_u": getattr(req_obj, "notional_u", None),
            "intent_amount": getattr(req_obj, "intent_amount", None),
            "amount_usd_intent": getattr(req_obj, "amount_usd_intent", None),
        }
        ok, reason, detail = _b1_first_open_amount_contract_sync(rd, source=source)
        if ok and str(reason or "") == "skip:not_b1_new_coin_first_open":
            return True, str(reason), detail
        if detail:
            try:
                meta["b1_amount_guard_detail"] = dict(detail or {})
            except Exception:
                pass
        if ok:
            expected = float(_b1_first_open_expected_amount_u(rd, params=params, meta=meta) or 0.0)
            if expected > 0.0:
                _lock_b1_first_open_amount_contract(rd, expected, source=source)
                _apply_final_amount_contract_to_request(req_obj, amount_hint=expected)
                for k in FINAL_AMOUNT_FIELDS + ("intent_amount", "amount_usd_intent"):
                    try:
                        setattr(req_obj, k, float(expected))
                    except Exception:
                        pass
                params["B1__amount_usd"] = float(expected)
                meta["B1__amount_usd"] = float(expected)
                meta["b1_amount_locked"] = True
                meta["amount_locked_final_u"] = float(expected)
                meta["amount_locked_source"] = str(source or "b1_first_open_scaled_single_source")
                meta["amount_locked_no_override"] = True
                meta["no_random_amount"] = True
                meta["open_amount_jitter_skip"] = True
                meta["amt_final_source"] = str(source or "b1_first_open_scaled_single_source")
                meta["m1_std_reason"] = "b1_first_open_scaled_locked"
                setattr(req_obj, "params", params)
                setattr(req_obj, "meta", meta)
            return True, str(reason), detail
        return False, str(reason), detail
    except Exception as _e:
        detail["exc"] = repr(_e)
        return False, "b1_request_guard_exception", detail

def _jitter_amt_u_if_repeat(plat: str, amt_u: float, *, act: str = "", coin: str = "") -> float:
    """[HARD] 金额映射=最终下单金额（爸爸硬要求）
    - 禁止在这里做抖动、取整、强制最小值等二次改写
    - 历史上这里用于“同平台连续同金额±10U抖动”，现在完全禁用
    """
    try:
        return float(amt_u)
    except Exception:
        return amt_u

def _pick_wave_amount_10u(
    *,
    base_u: float,
    u_min: float,
    u_max: float,
    history_key: str = "",
    recent_keep: int = 3,
    spread_steps: int = 2,
) -> tuple[float, dict]:
    """[HARD] 金额映射一旦产出就是最终下单金额。
    选择 6A 后，波动选值在源码级永久关闭，只保留基准值裁剪/取整证据。
    """
    det = {"ok": True, "base_u": None, "picked": None, "choices": [], "recent": [], "reason": "hard_disabled_final_amount_contract"}
    try:
        lo = float(min(u_min, u_max))
        hi = float(max(u_min, u_max))
        base = float(_half_up_round(float(base_u), 10.0))
        base = float(max(lo, min(hi, base)))
        det["base_u"] = float(base)
        det["picked"] = float(base)
        det["choices"] = [float(base)]
        det["recent"] = []
        return float(base), det
    except Exception as _e:
        det["ok"] = False
        det["reason"] = f"hard_disabled_exception:{type(_e).__name__}"
        try:
            det["base_u"] = float(base_u)
            det["picked"] = float(_half_up_round(float(base_u), 10.0))
            return float(det["picked"]), det
        except Exception:
            det["picked"] = base_u
            return base_u, det
def _json_default_for_bot(obj):
    try:
        import dataclasses as _dc
        if _dc.is_dataclass(obj):
            try:
                return _dc.asdict(obj)
            except Exception:
                return obj.__dict__
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_33', _e)
        pass
    try:
        if isinstance(obj, (set, tuple)):
            return list(obj)
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_34', _e)
        pass
    try:
        if isinstance(obj, (bytes, bytearray)):
            try:
                return obj.decode("utf-8", errors="ignore")
            except Exception:
                return repr(obj)
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_35', _e)
        pass
    try:
        if hasattr(obj, "__dict__"):
            return dict(obj.__dict__)
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_36', _e)
        pass
    try:
        return str(obj)
    except Exception:
        return repr(obj)

def _json_dumps_bot(obj, **kwargs) -> str:
    kw = dict(kwargs or {})
    kw.setdefault("ensure_ascii", False)
    kw.setdefault("default", _json_default_for_bot)
    try:
        obj = _reason_annotate_for_output(obj)
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_37', _e)
        pass
    try:
        return json.dumps(obj, **kw)
    except Exception:
        def _fallback(o):
            try:
                return _json_default_for_bot(o)
            except Exception:
                return str(o)
        kw["default"] = _fallback
        try:
            obj = _reason_annotate_for_output(obj)
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_38', _e)
            pass
        return json.dumps(obj, **kw)

def _json_dump_bot(obj, fp, **kwargs):
    kw = dict(kwargs or {})
    kw.setdefault("ensure_ascii", False)
    kw.setdefault("default", _json_default_for_bot)
    try:
        obj = _reason_annotate_for_output(obj)
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_39', _e)
        pass
    return json.dump(obj, fp, **kw)

def _log_jsonl(fp: str, obj) -> bool:
    """早期可用的 JSONL 追加器：严格避免 NameError，把日志落盘失败降级为 False。"""
    try:
        _fp = str(fp or '').strip()
        if not _fp:
            return False
        try:
            _dir = os.path.dirname(_fp)
            if _dir:
                os.makedirs(_dir, exist_ok=True)
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_40', _e)
            pass
        with open(_fp, 'a', encoding='utf-8') as _f:
            _f.write(_json_dumps_bot(obj) + "\n")
        try:
            _cleanup_retention_target(_fp)
        except Exception:
            pass
        return True
    except Exception:
        return False

def _env_flag(name: str, default=None):
    """读取环境变量布尔值；未设置/空字符串返回 default。"""
    try:
        _raw = os.getenv(str(name or ''))
    except Exception:
        return default
    if _raw is None:
        return default
    try:
        _s = str(_raw).strip().lower()
    except Exception:
        return default
    if _s == '':
        return default
    if _s in {'1', 'true', 'yes', 'y', 'on'}:
        return True
    if _s in {'0', 'false', 'no', 'n', 'off'}:
        return False
    return default

def _env_int(name: str, default: int = 0) -> int:
    """读取环境变量整数；非法/缺失时回退默认值。"""
    try:
        _raw = os.getenv(str(name or ''))
    except Exception:
        return int(default or 0)
    if _raw is None:
        return int(default or 0)
    try:
        _s = str(_raw).strip()
    except Exception:
        return int(default or 0)
    if _s == '':
        return int(default or 0)
    try:
        return int(float(_s))
    except Exception:
        return int(default or 0)

def _env_float(name: str, default: float = 0.0) -> float:
    """读取环境变量浮点数；非法/缺失时回退默认值。"""
    try:
        _raw = os.getenv(str(name or ''))
    except Exception:
        return float(default or 0.0)
    if _raw is None:
        return float(default or 0.0)
    try:
        _s = str(_raw).strip()
    except Exception:
        return float(default or 0.0)
    if _s == '':
        return float(default or 0.0)
    try:
        return float(_s)
    except Exception:
        return float(default or 0.0)

