    out["all_pass"] = bool(
        out["schema_min_contract_ok"]
        and out["reopen_after_tp_schema_ok"]
        and out["missing_amt_det_reject_ok"]
        and out["with_amt_det_not_reject_amount_not_mapped"]
        and out["close_leg_spec_params_json_safe"]
        and out["coin_block_allow_under_bootstrap_pending"]
        and out["control_poll_partial_json_retry_ok"]
    )
    return out

