def _run_execution_confirm_regression_suite() -> dict:
    """专项回归：执行确认链（pre/post snapshot -> confirm）核心规则。
    说明（人话）：
    - 这里不碰真实 UI，只验证“确认逻辑”的制度：row 消失/qty 变化/notional 变化等是否按预期判定。
    """
    rep = {"cases": {}, "all_pass": False}
    try:
        pre = {"side": "LONG", "notional_u": 120.0, "qty_abs": 0.5}
        ok, ev = _exec_verify_submit_by_row(kind="close_all", side_u="LONG", usd=120.0, pre_row=pre, post_row=None)
        rep["cases"]["close_all_row_disappear_ok"] = bool(ok and int(ev.get("ok_by_row_disappear") or 0) == 1)

        pre = {"side": "SHORT", "notional_u": 100.0, "qty_abs": 2.0}
        post = {"side": "SHORT", "notional_u": 80.0, "qty_abs": 1.4}
        ok, _ = _exec_verify_submit_by_row(kind="close", side_u="SHORT", usd=40.0, pre_row=pre, post_row=post)
        rep["cases"]["close_reduce_qty_ok"] = bool(ok)

        pre = {"side": "NONE", "notional_u": 0.0, "qty_abs": 0.0}
        post = {"side": "LONG", "notional_u": 60.0, "qty_abs": 0.12}
        ok, _ = _exec_verify_submit_by_row(kind="open", side_u="LONG", usd=50.0, pre_row=pre, post_row=post)
        rep["cases"]["open_qty_ok"] = bool(ok)

        pre = {"side": "LONG", "notional_u": 100.0, "qty_abs": 1.0}
        post = {"side": "LONG", "notional_u": 20.0, "qty_abs": 0.5}
        ok, _ = _exec_verify_submit_by_row(kind="close_all", side_u="LONG", usd=100.0, pre_row=pre, post_row=post)
        rep["cases"]["close_all_not_flat_reject"] = bool(not ok)

        pre_pf = {"available": True, "visible_rows": 1, "positions": {"BTC": {"side": "LONG", "notional_u": 100.0, "qty_abs": 1.0}}}
        post_pf_ok = {"available": True, "visible_rows": 0, "positions": {}}
        ok, ev = _exec_verify_submit_dual_evidence(coin="BTC", kind="close_all", side_u="LONG", usd=100.0, pre_row=pre, post_row=None, pre_portfolio=pre_pf, post_portfolio=post_pf_ok)
        rep["cases"]["dual_evidence_agree_ok"] = bool(
            ok
            and str(ev.get("confirm_mode") or "") == "platform_row_truth_only"
            and int(ev.get("row_ok") or 0) == 1
            and int(ev.get("portfolio_bypassed") or 0) == 1
            and int(ev.get("final_ok") or 0) == 1
        )
        post_pf_bad = {"available": True, "visible_rows": 1, "positions": {"BTC": {"side": "LONG", "notional_u": 30.0, "qty_abs": 0.3}}}
        ok, ev = _exec_verify_submit_dual_evidence(coin="BTC", kind="close_all", side_u="LONG", usd=100.0, pre_row=pre, post_row=None, pre_portfolio=pre_pf, post_portfolio=post_pf_bad)
        rep["cases"]["dual_evidence_row_first_soft_ok"] = bool(
            ok
            and int(ev.get("row_ok") or 0) == 1
            and int(ev.get("portfolio_ok") or 0) == 0
            and int(ev.get("portfolio_bypassed") or 0) == 1
            and str(ev.get("reason_code") or "") == "commit_success"
        )

        rep["all_pass"] = all(bool(v) for v in rep["cases"].values())
        return rep
    except Exception as e:
        rep["error"] = repr(e)
        rep["all_pass"] = False
        return rep

def _run_volatility_regression_suite() -> dict:
    rep = {"cases": {}, "all_pass": False}
    _orig_override = dict(globals().get('_COIN_24H_VOL_PCT_OVERRIDE') or {})
    _orig_new = set(globals().get('_COIN_POOL_DYNAMIC_SELECTED') or set())
    try:
        globals()['_COIN_24H_VOL_PCT_OVERRIDE'] = {'BTC': 0.20, 'EDGE': 0.04, 'DOGE': 0.60}
        globals()['_COIN_POOL_DYNAMIC_SELECTED'] = set(list(_orig_new) + ['EDGE'])
        gap_old, det_old = _m9_gap_from_ring('BTC')
        gap_new_floor, det_new_floor = _m9_gap_from_ring('EDGE')
        gap_old_high, det_old_high = _m9_gap_from_ring('DOGE')
        rep['cases']['uses_24h_volatility_x_10pct'] = bool(abs(float(gap_old) - 0.02) < 1e-9 and abs(float(det_old.get('raw_gap') or 0.0) - 0.02) < 1e-9 and '10%' in str(det_old.get('formula') or ''))
        rep['cases']['single_chain_floor_keeps_1pct'] = bool(abs(float(det_old.get('floor') or 0.0) - 0.01) < 1e-9)
        rep['cases']['new_coin_keeps_1pct_floor'] = bool(abs(float(gap_new_floor) - 0.01) < 1e-9 and abs(float(det_new_floor.get('floor') or 0.0) - 0.01) < 1e-9)
        rep['cases']['higher_24h_vol_can_expand_above_2_5pct'] = bool(abs(float(gap_old_high) - 0.06) < 1e-9 and float(det_old_high.get('cap') or 0.0) >= 0.06 and abs(float(det_old_high.get('raw_gap') or 0.0) - 0.06) < 1e-9)
        low_layer = {'tp_pct': 0.01, 'tp_px': 101.0, 'open_ref_px': 100.0, 'grid_pct': 0.01}
        globals()['_COIN_24H_VOL_PCT_OVERRIDE']['BTC'] = 0.009
        _eff_px, _eff_pct, _eff_changed, _eff_det = _m9_layer_effective_tp_px(low_layer, coin='BTC', side='LONG', ref_px=100.0)
        rep['cases']['layer_tp_no_hidden_conservative_floor'] = bool(abs(float(_eff_pct) - 0.01) < 1e-9 and abs(float(low_layer.get('live_tp_pct') or 0.0) - 0.01) < 1e-9 and abs(float((_eff_det or {}).get('tp_floor') or 0.0) - 0.01) < 1e-9)
    except Exception as e:
        rep['error'] = repr(e)
    finally:
        globals()['_COIN_24H_VOL_PCT_OVERRIDE'] = dict(_orig_override or {})
        globals()['_COIN_POOL_DYNAMIC_SELECTED'] = set(_orig_new or set())
    rep['all_pass'] = bool(rep.get('cases')) and all(bool(v) for v in rep['cases'].values())
    return rep


def _summarize_regression_failures(rep: Any) -> dict:
    try:
        cases = dict((rep or {}).get('cases') or {}) if isinstance(rep, dict) else {}
    except Exception:
        cases = {}
    failed = []
    for _k, _v in (cases or {}).items():
        try:
            if not bool(_v):
                failed.append(str(_k))
        except Exception:
            failed.append(str(_k))
    out = {
        'all_pass': bool((rep or {}).get('all_pass')) if isinstance(rep, dict) else False,
        'failed_cases': failed,
        'error': str((rep or {}).get('error') or '') if isinstance(rep, dict) else '',
        'runner': str((rep or {}).get('runner') or '') if isinstance(rep, dict) else '',
        'source': str((rep or {}).get('source') or '') if isinstance(rep, dict) else '',
    }
    try:
        if isinstance(rep, dict) and rep.get('capture'):
            out['capture'] = str(rep.get('capture') or '')[-3000:]
    except Exception:
        pass
    return out


def _run_volatility_regression_suite_isolated(timeout_sec: float = 120.0) -> dict:
    direct_rep = _run_volatility_regression_suite()
    try:
        direct_rep = dict(direct_rep or {})
    except Exception:
        direct_rep = {'cases': {}, 'all_pass': False, 'error': 'direct_rep_not_dict'}
    direct_rep.setdefault('runner', 'direct')
    direct_rep.setdefault('source', 'inprocess')
    try:
        fp = str(globals().get('__file__') or '')
    except Exception:
        fp = ''
    try:
        import os as _os
        if not fp or (not _os.path.exists(fp)):
            direct_rep['isolation_error'] = 'source_file_missing'
            return direct_rep
    except Exception as _e:
        direct_rep['isolation_error'] = repr(_e)
        return direct_rep
    try:
        _code = (
            "import json, runpy, io, contextlib, traceback, sys\n"
            "path = sys.argv[1]\n"
            "buf = io.StringIO()\n"
            "payload = {}\n"
            "try:\n"
            "    with contextlib.redirect_stdout(buf), contextlib.redirect_stderr(buf):\n"
            "        g = runpy.run_path(path, run_name='oaicheck')\n"
            "        rep = g['_run_volatility_regression_suite']()\n"
            "    payload = {'ok': True, 'rep': rep, 'capture': buf.getvalue()[-8000:]}\n"
            "except Exception as e:\n"
            "    payload = {'ok': False, 'error': repr(e), 'traceback': traceback.format_exc()[-8000:], 'capture': buf.getvalue()[-8000:]}\n"
            "print('__OAICHECK_JSON__' + json.dumps(payload, ensure_ascii=False))\n"
        )
        proc = subprocess.run(
            [sys.executable, '-c', _code, fp],
            capture_output=True,
            text=True,
            encoding='utf-8',
            errors='replace',
            timeout=float(timeout_sec or 120.0),
        )
        stdout = str(proc.stdout or '')
        stderr = str(proc.stderr or '')
        marker = '__OAICHECK_JSON__'
        payload_line = ''
        for _line in reversed(stdout.splitlines()):
            if _line.startswith(marker):
                payload_line = _line[len(marker):]
                break
        if not payload_line:
            direct_rep['isolation_error'] = f'payload_missing:returncode={proc.returncode}'
            direct_rep['capture'] = (stdout + '\\n' + stderr)[-3000:]
            return direct_rep
        payload = json.loads(payload_line)
        if not bool((payload or {}).get('ok')):
            direct_rep['isolation_error'] = str((payload or {}).get('error') or f'returncode={proc.returncode}')
            direct_rep['capture'] = str((payload or {}).get('traceback') or (payload or {}).get('capture') or '')[-3000:]
            return direct_rep
        iso_rep = dict((payload or {}).get('rep') or {})
        iso_rep['runner'] = 'isolated_subprocess'
        iso_rep['source'] = 'subprocess_clean_interpreter'
        iso_rep['capture'] = str((payload or {}).get('capture') or '')[-3000:]
        iso_rep['subprocess_returncode'] = int(proc.returncode)
        iso_rep['direct_shadow'] = _summarize_regression_failures(direct_rep)
        return iso_rep
    except Exception as _e:
        direct_rep['isolation_error'] = repr(_e)
        return direct_rep


