def _run_round_watchdog_regression_suite() -> dict:
    rep = {'cases': {}, 'all_pass': False}
    _g = globals()
    _orig_exec_stop = _g.get('_exec_runtime_stop')
    _orig_pw_reset = _g.get('_pw_runtime_hard_reset')
    _orig_worker_rebuild = _g.get('_sync_pw_worker_rebuild')
    _orig_panel_state = _g.get('panel_set_mainloop_state')
    _calls = {'exec_stop': 0, 'pw_reset': 0, 'worker_rebuild': [], 'panel': []}
    try:
        def _stub_exec_stop(reason='', **kwargs):
            _calls['exec_stop'] += 1
        def _stub_pw_reset(reason='', **kwargs):
            _calls['pw_reset'] += 1
            return 1
        def _stub_worker_rebuild(reason='', **kwargs):
            _calls['worker_rebuild'].append({'reason': reason, 'thread_name': kwargs.get('thread_name')})
        def _stub_panel_state(state, hint='', err=''):
            _calls['panel'].append({'state': state, 'hint': hint, 'err': err})
        _g['_exec_runtime_stop'] = _stub_exec_stop
        _g['_pw_runtime_hard_reset'] = _stub_pw_reset
        _g['_sync_pw_worker_rebuild'] = _stub_worker_rebuild
        _g['panel_set_mainloop_state'] = _stub_panel_state
        _round_watchdog_clear_trip()
        _g['_ROUND_WATCHDOG_LAST_TRIP_KEY'] = ''
        _now = float(time.time())
        _g['_MAIN_ROUND_WATCH'] = {
            'active': True,
            'state': 'RUNNING',
            'stage': 'EXECUTOR_WAIT',
            'msg': 'waiting',
            'reason': '',
            'err': '',
            'ts': _now - 8.0,
            'started_ts': _now - 8.0,
            'heartbeat_ts': _now - 8.0,
            'timeout_sec': 1.0,
            'scan_count': 77,
        }
        _trip = _round_watchdog_check_once(nowv=_now)
        rep['cases']['timeout_trip_sets_active_flag'] = bool(isinstance(_trip, dict) and bool((_trip or {}).get('active')))
        rep['cases']['timeout_trip_calls_exec_runtime_stop'] = bool(int(_calls['exec_stop']) >= 1)
        rep['cases']['timeout_trip_calls_pw_reset'] = bool(int(_calls['pw_reset']) >= 1)
        rep['cases']['timeout_trip_rebuilds_workers'] = bool(len(_calls['worker_rebuild']) >= 4)
        rep['cases']['timeout_trip_updates_panel_state'] = bool(any(str(x.get('state')) == 'ROUND_TIMEOUT' for x in (_calls['panel'] or [])))
        try:
            _round_watchdog_raise_if_tripped()
            rep['cases']['trip_raise_path'] = False
        except _RoundWatchdogTripError:
            rep['cases']['trip_raise_path'] = True
        _round_watch_begin(78, timeout_sec=5.0, stage='ROUND_BEGIN', msg='new round')
        _trip2 = _round_watchdog_trip_snapshot()
        rep['cases']['new_round_clears_previous_trip'] = bool(not bool((_trip2 or {}).get('active')))
        _th = _ensure_round_watchdog_thread()
        rep['cases']['watchdog_thread_alive_daemon'] = bool(isinstance(_th, threading.Thread) and _th.is_alive() and bool(_th.daemon))
    except Exception as e:
        rep['error'] = repr(e)
    finally:
        if _orig_exec_stop is not None:
            _g['_exec_runtime_stop'] = _orig_exec_stop
        if _orig_pw_reset is not None:
            _g['_pw_runtime_hard_reset'] = _orig_pw_reset
        if _orig_worker_rebuild is not None:
            _g['_sync_pw_worker_rebuild'] = _orig_worker_rebuild
        if _orig_panel_state is not None:
            _g['panel_set_mainloop_state'] = _orig_panel_state
        _round_watchdog_clear_trip()
        try:
            _round_watch_finish('IDLE', msg='watchdog regression done', reason='selftest')
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_44', _e)
            pass
    rep['all_pass'] = bool(rep.get('cases')) and all(bool(v) for v in rep['cases'].values())
    return rep

