def _run_exec_runtime_isolation_regression_suite() -> dict:
    rep = {'cases': {}, 'all_pass': False}
    _g = globals()
    _orig_exec_caches = dict(_g.get('_EXEC_RUNTIME_CACHES') or {})
    _orig_pw_alive = bool(_g.get('PW_ALIVE', False))
    _orig_recovering = bool(_g.get('_PW_RUNTIME_RECOVERING', False))
    _orig_sessions = _g.get('_PW_SESSIONS')
    _g['_PW_SESSIONS'] = _SessionLiveness()
    try:
        class _FakePW:
            def __init__(self, name: str):
                self.name = str(name or '')
                self.stopped = False
            def stop(self):
                self.stopped = True

        _pw_a = _FakePW('A')
        _pw_b = _FakePW('B')
        class _FakeBrowser:
            def is_connected(self):
                return True
        _browser_a, _browser_b = _FakeBrowser(), _FakeBrowser()
        _g['_PW_SESSIONS'].begin(_browser_b)
        _g['_EXEC_RUNTIME_CACHES'] = {
            'ExecutorSyncPlaywrightWorker': {'pw': _pw_a, 'browser': _browser_a},
            'ExecutorQuanbuSyncPlaywrightWorker': {'pw': _pw_b, 'browser': _browser_b},
        }
        _g['PW_ALIVE'] = True
        _g['_PW_RUNTIME_RECOVERING'] = False
        _exec_runtime_stop('selftest_partial_stop', runtime_key='ExecutorSyncPlaywrightWorker')
        rep['cases']['partial_stop_keeps_other_runtime_cached'] = bool('ExecutorQuanbuSyncPlaywrightWorker' in (_g.get('_EXEC_RUNTIME_CACHES') or {}))
        rep['cases']['partial_stop_does_not_stop_other_runtime'] = bool(not bool(getattr(_pw_b, 'stopped', False)))
        rep['cases']['partial_stop_keeps_pw_alive'] = bool(_g.get('PW_ALIVE', False))
        rep['cases']['partial_stop_does_not_enter_global_recover'] = bool(not bool(_g.get('_PW_RUNTIME_RECOVERING', False)))
        rep['cases']['partial_stop_guard_still_allows_calls'] = bool(_pw_guard(mod='SELFTEST', stage='EXEC_RUNTIME_ISOLATION'))

        _pw_c = _FakePW('C')
        _pw_d = _FakePW('D')
        _g['_EXEC_RUNTIME_CACHES'] = {
            'ExecutorSyncPlaywrightWorker': {'pw': _pw_c},
            'ExecutorQuanbuSyncPlaywrightWorker': {'pw': _pw_d},
        }
        _g['PW_ALIVE'] = True
        _g['_PW_RUNTIME_RECOVERING'] = False
        _exec_runtime_stop('selftest_stop_all', stop_all=True)
        rep['cases']['stop_all_clears_all_runtime_cache'] = bool(not bool(_g.get('_EXEC_RUNTIME_CACHES') or {}))
        rep['cases']['stop_all_turns_pw_alive_off'] = bool(not bool(_g.get('PW_ALIVE', False)))
        rep['cases']['stop_all_enters_global_recover'] = bool(_g.get('_PW_RUNTIME_RECOVERING', False))
        rep['cases']['stop_all_guard_blocks_calls'] = bool(not _pw_guard(mod='SELFTEST', stage='EXEC_RUNTIME_ISOLATION_STOP_ALL'))
    except Exception as e:
        rep['error'] = repr(e)
    finally:
        _g['_EXEC_RUNTIME_CACHES'] = dict(_orig_exec_caches or {})
        _g['PW_ALIVE'] = _orig_pw_alive
        _g['_PW_RUNTIME_RECOVERING'] = _orig_recovering
        _g['_PW_SESSIONS'] = _orig_sessions
    rep['all_pass'] = bool(rep.get('cases')) and all(bool(v) for v in (rep.get('cases') or {}).values())
    return rep

