def _run_m2_runtime_recover_retry_regression_suite() -> dict:
    rep = {"suite": "m2_runtime_recover_retry_regression", "cases": {}}
    _old_env_flag = globals().get('_env_flag')
    _old_timeout = globals().get('_m2_scan_timeout_sec')
    _old_write_jsonl = globals().get('write_jsonl')
    _old_watch_update = globals().get('_m2_scan_watch_update')
    _old_watch_finish = globals().get('_m2_scan_watch_finish')
    _old_run_worker = globals().get('_run_call_in_worker_thread')
    _old_hard_reset = globals().get('_pw_runtime_hard_reset')
    _old_wait_ready = globals().get('_pw_runtime_wait_until_ready')
    _old_fail_snapshot = globals().get('_m2_make_fail_snapshot')
    _old_now_ts = globals().get('now_ts')
    _old_safe_log = globals().get('safe_log')
    _calls = {"worker": 0, "hard_reset": 0, "wait_ready": 0, "fail_snapshot": 0}
    try:
        globals()['_env_flag'] = lambda *args, **kwargs: True
        globals()['_m2_scan_timeout_sec'] = lambda default=90.0: 1.0
        globals()['write_jsonl'] = lambda *args, **kwargs: None
        globals()['_m2_scan_watch_update'] = lambda *args, **kwargs: None
        globals()['_m2_scan_watch_finish'] = lambda *args, **kwargs: None
        globals()['now_ts'] = lambda: 'SELFTEST'
        globals()['safe_log'] = lambda *args, **kwargs: None
        def _fake_hard_reset(reason="", **kwargs):
            _calls['hard_reset'] += 1
            return 1
        def _fake_wait_ready(*args, **kwargs):
            _calls['wait_ready'] += 1
            return False
        def _fake_fail_snapshot(reason, **kwargs):
            _calls['fail_snapshot'] += 1
            return {'data_quality':'fail','reason':str(reason or '')}
        globals()['_pw_runtime_hard_reset'] = _fake_hard_reset
        globals()['_pw_runtime_wait_until_ready'] = _fake_wait_ready
        globals()['_m2_make_fail_snapshot'] = _fake_fail_snapshot

        def _fake_run_worker(fn, **kwargs):
            _calls['worker'] += 1
            if _calls['worker'] == 1:
                raise TimeoutError('M2_worker_timeout:1.0s')
            return {'data_quality':'ok','raw':{'attempts':_calls['worker']}}
        globals()['_run_call_in_worker_thread'] = _fake_run_worker
        _res_timeout = m2_scan('cdp://selftest', ['BTC'], '/tmp/selftest.jsonl', reason='selftest_timeout_retry')
        rep['cases']['timeout_retry_recovers'] = bool(isinstance(_res_timeout, dict) and str((_res_timeout or {}).get('data_quality') or '') == 'ok' and _calls['worker'] == 2)
        rep['cases']['timeout_path_calls_hard_reset'] = bool(_calls['hard_reset'] >= 1)
        rep['cases']['timeout_path_waits_runtime_ready'] = bool(_calls['wait_ready'] >= 1)
        rep['cases']['timeout_path_not_fail_closed_immediately'] = bool(_calls['fail_snapshot'] == 0)

        _calls.update({"worker": 0, "hard_reset": 0, "wait_ready": 0, "fail_snapshot": 0})
        def _fake_run_worker_ui(fn, **kwargs):
            _calls['worker'] += 1
            if _calls['worker'] == 1:
                raise _UiDeadError('PW_PATCH_LOCATOR_COUNT', 'playwright_not_alive')
            return {'data_quality':'ok','raw':{'attempts':_calls['worker']}}
        globals()['_run_call_in_worker_thread'] = _fake_run_worker_ui
        _res_ui = m2_scan('cdp://selftest', ['ETH'], '/tmp/selftest.jsonl', reason='selftest_ui_retry')
        rep['cases']['ui_dead_retry_recovers'] = bool(isinstance(_res_ui, dict) and str((_res_ui or {}).get('data_quality') or '') == 'ok' and _calls['worker'] == 2)
        rep['cases']['ui_dead_path_calls_hard_reset'] = bool(_calls['hard_reset'] >= 1)
        rep['cases']['ui_dead_path_waits_runtime_ready'] = bool(_calls['wait_ready'] >= 1)
        rep['cases']['ui_dead_path_not_fail_closed_immediately'] = bool(_calls['fail_snapshot'] == 0)
    except Exception as _e:
        rep['error'] = f"{type(_e).__name__}:{_e}"
    finally:
        if _old_env_flag is not None:
            globals()['_env_flag'] = _old_env_flag
        if _old_timeout is not None:
            globals()['_m2_scan_timeout_sec'] = _old_timeout
        if _old_write_jsonl is not None:
            globals()['write_jsonl'] = _old_write_jsonl
        if _old_watch_update is not None:
            globals()['_m2_scan_watch_update'] = _old_watch_update
        if _old_watch_finish is not None:
            globals()['_m2_scan_watch_finish'] = _old_watch_finish
        if _old_run_worker is not None:
            globals()['_run_call_in_worker_thread'] = _old_run_worker
        if _old_hard_reset is not None:
            globals()['_pw_runtime_hard_reset'] = _old_hard_reset
        if _old_wait_ready is not None:
            globals()['_pw_runtime_wait_until_ready'] = _old_wait_ready
        if _old_fail_snapshot is not None:
            globals()['_m2_make_fail_snapshot'] = _old_fail_snapshot
        if _old_now_ts is not None:
            globals()['now_ts'] = _old_now_ts
        if _old_safe_log is not None:
            globals()['safe_log'] = _old_safe_log
    rep['all_pass'] = bool(rep.get('cases')) and all(bool(v) for v in (rep.get('cases') or {}).values())
    return rep

def _ensure_page_detached_frame_regression() -> dict:
    class _FakePage:
        def __init__(self, *, fail_first_goto: bool = False, url: str = "") -> None:
            self.url = str(url or "")
            self._closed = False
            self.fail_first_goto = bool(fail_first_goto)
            self.goto_calls = 0
            self.front_calls = 0
            self.reload_calls = 0
            self.context = None
        def is_closed(self):
            return self._closed
        def bring_to_front(self):
            self.front_calls += 1
            return True
        def goto(self, url, timeout=0):
            self.goto_calls += 1
