def _run_executor_timeout_handoff_regression_suite() -> dict:
    rep = {"suite": "executor_timeout_handoff", "cases": {}}
    _old_touch = globals().get('_active_req_touch')
    _old_bind = globals().get('_active_req_bind')
    _old_clear = globals().get('_active_req_clear')
    _old_snapshot = globals().get('_active_req_snapshot')
    _old_rebuild = globals().get('_sync_pw_worker_rebuild')
    _old_recent = globals().get('_executor_recent_timeout_snapshot')
    _old_warm = globals().get('_executor_runtime_cache_is_warm')
    _old_worker = globals().get('_run_call_in_worker_thread')
    _old_has_loop = globals().get('_has_running_asyncio_loop')
    _ctx = {}
    _trace = []
    try:
        def _fake_clear(reason=""):
            _ctx.clear()
            if reason:
                _ctx['clear_reason'] = str(reason)
        def _fake_bind(req_any, *, stage="DEQUEUED"):
            if isinstance(req_any, dict):
                meta = req_any.get('meta') if isinstance(req_any.get('meta'), dict) else {}
                module = str((req_any or {}).get('module') or 'EXEC')
                coin = str((req_any or {}).get('coin') or '')
                platform = str((req_any or {}).get('platform') or '')
                action_type = str((req_any or {}).get('action_type') or '')
            else:
                meta = getattr(req_any, 'meta', {}) if isinstance(getattr(req_any, 'meta', {}), dict) else {}
                module = str(getattr(req_any, 'module', 'EXEC') or 'EXEC')
                coin = str(getattr(req_any, 'coin', '') or '')
                platform = str(getattr(req_any, 'platform', '') or '')
                action_type = str(getattr(req_any, 'action_type', '') or '')
            _ctx.update({
                'req_id': str((meta or {}).get('req_id') or ''),
                'trace_id': str((meta or {}).get('trace_id') or 't_self'),
                'module': module,
                'coin': coin,
                'platform': platform,
                'action_type': action_type,
                'stage': str(stage or ''),
                'last_stage': str(stage or ''),
                'last_reason': 'bind',
                'last_where': 'active_req_bind',
            })
            return dict(_ctx)
        def _fake_touch(stage, reason="", **extra):
            _ctx['last_stage'] = str(stage or '')
            _ctx['last_reason'] = str(reason or '')
            _ctx['last_where'] = str((extra or {}).get('where') or '')
            if (extra or {}).get('worker_key'):
                _ctx['worker_key'] = str((extra or {}).get('worker_key') or '')
            _trace.append({'stage': str(stage or ''), 'where': str((extra or {}).get('where') or ''), 'worker_key': str((extra or {}).get('worker_key') or '')})
            return dict(_ctx)
        def _fake_snapshot():
            return dict(_ctx)
        _rebuild_calls = []
        globals()['_active_req_touch'] = _fake_touch
        globals()['_active_req_bind'] = _fake_bind
        globals()['_active_req_clear'] = _fake_clear
        globals()['_active_req_snapshot'] = _fake_snapshot
        globals()['_sync_pw_worker_rebuild'] = lambda reason="", **kwargs: _rebuild_calls.append({'reason': str(reason or ''), 'thread_name': str(kwargs.get('thread_name') or '')})
        globals()['_executor_runtime_cache_is_warm'] = lambda thread_name='': False
        globals()['_executor_recent_timeout_snapshot'] = lambda max_age_sec=180.0: {'recent': True, 'reason': 'old_timeout', 'worker_key': 'ExecutorSyncPlaywrightWorker_SUI', 'thread_name': 'ExecutorSyncPlaywrightWorker_SUI'}
        globals()['_run_call_in_worker_thread'] = lambda fn, **kwargs: []
        globals()['_has_running_asyncio_loop'] = lambda: True
        class _Req:
            def __init__(self):
                self.coin = 'SUI'
                self.platform = 'VAR'
                self.module = 'M9'
                self.action_type = 'increase'
                self.meta = {'req_id': 'r1', 'trace_id': 't1'}
            def to_dict(self):
                return {'coin': self.coin, 'platform': self.platform, 'module': self.module, 'action_type': self.action_type, 'meta': dict(self.meta or {})}
        _req = _Req()
        executor_run('cdp://selftest', '/tmp/selftest_exec.log', {}, [_req])
        rep['cases']['same_worker_timeout_rebuilds'] = bool(_rebuild_calls) and str((_rebuild_calls[0] or {}).get('thread_name') or '') == 'ExecutorSyncPlaywrightWorker_SUI'
        rep['cases']['prehealth_trace_written'] = any(str((_x or {}).get('stage') or '') == 'EXEC_RUNTIME_PREHEALTH_BEGIN' and str((_x or {}).get('where') or '') == 'executor_run.prehealth_begin' for _x in (_trace or []))
        rep['cases']['dispatch_trace_has_worker_key'] = any(str((_x or {}).get('stage') or '') == 'EXECUTOR_HANDOFF_WAIT' and str((_x or {}).get('worker_key') or '') == 'ExecutorSyncPlaywrightWorker_SUI' for _x in (_trace or []))

        _trace.clear()
        _rebuild_calls.clear()
        globals()['_executor_recent_timeout_snapshot'] = lambda max_age_sec=180.0: {'recent': True, 'reason': 'other_timeout', 'worker_key': 'ExecutorSyncPlaywrightWorker_BTC', 'thread_name': 'ExecutorSyncPlaywrightWorker_BTC'}
        executor_run('cdp://selftest', '/tmp/selftest_exec.log', {}, [_req])
        rep['cases']['other_worker_timeout_not_rebuild'] = bool(not _rebuild_calls)
    except Exception as _e:
        rep['error'] = f"{type(_e).__name__}:{_e}"
    finally:
        if _old_touch is not None:
            globals()['_active_req_touch'] = _old_touch
        if _old_bind is not None:
            globals()['_active_req_bind'] = _old_bind
        if _old_clear is not None:
            globals()['_active_req_clear'] = _old_clear
        if _old_snapshot is not None:
            globals()['_active_req_snapshot'] = _old_snapshot
        if _old_rebuild is not None:
            globals()['_sync_pw_worker_rebuild'] = _old_rebuild
        if _old_recent is not None:
            globals()['_executor_recent_timeout_snapshot'] = _old_recent
        if _old_warm is not None:
            globals()['_executor_runtime_cache_is_warm'] = _old_warm
        if _old_worker is not None:
            globals()['_run_call_in_worker_thread'] = _old_worker
        if _old_has_loop is not None:
            globals()['_has_running_asyncio_loop'] = _old_has_loop
    rep['all_pass'] = bool(rep.get('cases')) and all(bool(v) for v in (rep.get('cases') or {}).values())
    return rep

def _ensure_page_var_mem_recycle_regression() -> dict:
    class _FakePage:
        def __init__(self, *, url: str = '', heap_mb: float = 120.0) -> None:
            self.url = str(url or '')
            self.heap_mb = float(heap_mb)
            self._closed = False
            self.goto_calls = 0
            self.front_calls = 0
            self.reload_calls = 0
            self.wait_calls = []
            self.context = None
        def is_closed(self):
            return self._closed
        def bring_to_front(self):
            self.front_calls += 1
            return True
        def goto(self, url, timeout=0):
            self.goto_calls += 1
            self.url = str(url or '')
            return None
        def reload(self, timeout=0, wait_until=None):
            self.reload_calls += 1
            self.wait_calls.append(int(timeout or 0))
            return None
        def wait_for_timeout(self, ms=0):
            self.wait_calls.append(int(ms or 0))
            return None
        def wait_for_url(self, *args, **kwargs):
            return None
        def title(self):
            return 'VAR'
        def close(self):
            self._closed = True
            return None
        def evaluate(self, js):
            js_s = str(js or '')
            if 'usedJSHeapSize' in js_s:
                return float(self.heap_mb)
            return 'complete'

    class _FakeCtx:
        def __init__(self):
            self.pages = []
        def new_page(self):
            p = _FakePage(url='https://omni.variational.io/perpetual/ETH', heap_mb=120.0)
            p.context = self
            self.pages.append(p)
            return p

    class _FakeBrowser:
        def __init__(self, ctx):
            self.contexts = [ctx]
        def new_context(self):
            ctx = _FakeCtx()
            self.contexts.append(ctx)
            return ctx

    _ctx = _FakeCtx()
    _reuse = _FakePage(url='https://omni.variational.io/perpetual/ETH', heap_mb=980.0)
    _reuse.context = _ctx
    _ctx.pages.append(_reuse)
    _browser = _FakeBrowser(_ctx)

    _old_guard = globals().get('_pw_guard')
    _old_hard_reset = globals().get('_pw_runtime_hard_reset')
    _old_safe_log = globals().get('safe_log')
    _old_write_jsonl = globals().get('write_jsonl')
    _old_now_ts = globals().get('now_ts')
    _old_env_float = globals().get('_env_float')
    _old_env_int = globals().get('_env_int')
    _old_detect_current_coin_var = globals().get('_detect_current_coin_var')
    _old_sleep = globals().get('_ORIG_TIME_SLEEP')
    _old_var_refresh_then_confirm = globals().get('_var_refresh_then_confirm')
    _old_registry = dict(globals().get('_ENSURE_PAGE_SINGLETON_REGISTRY') or {})
    _old_meta = copy.deepcopy(globals().get('_ENSURE_PAGE_SINGLETON_META') or {})
    _old_guard_map = copy.deepcopy(globals().get('_ENSURE_PAGE_RECOVER_GUARD') or {})
    _old_health = copy.deepcopy(globals().get('_ENSURE_PAGE_HEALTH') or {})
    _refresh_calls = {'count': 0}
    try:
        globals()['_pw_guard'] = lambda **kwargs: True
        globals()['_pw_runtime_hard_reset'] = lambda *args, **kwargs: None
        globals()['safe_log'] = lambda *args, **kwargs: None
        globals()['write_jsonl'] = lambda *args, **kwargs: None
        globals()['now_ts'] = lambda: 'SELFTEST'
        globals()['_env_float'] = lambda key, default=0.0: (900.0 if key == 'VAR_PAGE_HEAP_HARD_MB' else (120.0 if key == 'VAR_PAGE_HEAP_GROW_MB_10M' else default))
        globals()['_env_int'] = lambda key, default=0: default
        globals()['_detect_current_coin_var'] = lambda page: 'ETH'
        globals()['_ORIG_TIME_SLEEP'] = lambda s: None
        globals()['_ENSURE_PAGE_SINGLETON_REGISTRY'] = {'VAR': _reuse}
        globals()['_ENSURE_PAGE_SINGLETON_META'] = {}
        globals()['_ENSURE_PAGE_RECOVER_GUARD'] = {}
        globals()['_ENSURE_PAGE_HEALTH'] = {}
        def _refresh_probe(*args, **kwargs):
            _refresh_calls['count'] = int(_refresh_calls.get('count') or 0) + 1
            return True, 'refresh_should_not_be_used'
        globals()['_var_refresh_then_confirm'] = _refresh_probe
        _ensure_page_health_reset_for_page(_reuse, 'VAR', reason='selftest_reuse_seed')
        _hp_key_before = _ensure_page_health_key(_reuse, 'VAR')
        _p = ensure_page(_browser, 'omni.variational.io', 'https://omni.variational.io/perpetual/ETH', bring_to_front=False, do_goto=False)
        _new_key = _ensure_page_health_key(_p, 'VAR')
        _pages = list(_ctx.pages or [])
        _ok = bool(
            _p is not None
            and _p is not _reuse
            and getattr(_reuse, '_closed', False)
            and ('variational.io/perpetual/ETH' in str(getattr(_p, 'url', '') or ''))
            and int(len([pg for pg in _pages if not getattr(pg, '_closed', False)])) == 1
            and int(_refresh_calls.get('count') or 0) == 0
            and (_hp_key_before not in (globals().get('_ENSURE_PAGE_HEALTH') or {}))
            and (_new_key in (globals().get('_ENSURE_PAGE_HEALTH') or {}))
        )
        return {
            'pass': bool(_ok),
            'recovered_new_page': bool(_p is not _reuse),
            'old_page_closed': bool(getattr(_reuse, '_closed', False)),
            'ctx_pages': int(len(_pages)),
            'alive_pages': int(len([pg for pg in _pages if not getattr(pg, '_closed', False)])),
            'result_url': str(getattr(_p, 'url', '') or ''),
            'refresh_calls': int(_refresh_calls.get('count') or 0),
            'health_old_removed': bool(_hp_key_before not in (globals().get('_ENSURE_PAGE_HEALTH') or {})),
            'health_new_exists': bool(_new_key in (globals().get('_ENSURE_PAGE_HEALTH') or {})),
        }
    except Exception as _e:
        return {'pass': False, 'err': f"{type(_e).__name__}:{_e}"}
    finally:
        if _old_guard is not None:
            globals()['_pw_guard'] = _old_guard
        if _old_hard_reset is not None:
            globals()['_pw_runtime_hard_reset'] = _old_hard_reset
        if _old_safe_log is not None:
            globals()['safe_log'] = _old_safe_log
        if _old_write_jsonl is not None:
            globals()['write_jsonl'] = _old_write_jsonl
        if _old_now_ts is not None:
            globals()['now_ts'] = _old_now_ts
        if _old_env_float is not None:
            globals()['_env_float'] = _old_env_float
        if _old_env_int is not None:
            globals()['_env_int'] = _old_env_int
        if _old_detect_current_coin_var is not None:
            globals()['_detect_current_coin_var'] = _old_detect_current_coin_var
        if _old_sleep is not None:
            globals()['_ORIG_TIME_SLEEP'] = _old_sleep
        if _old_var_refresh_then_confirm is not None:
            globals()['_var_refresh_then_confirm'] = _old_var_refresh_then_confirm
        globals()['_ENSURE_PAGE_SINGLETON_REGISTRY'] = _old_registry
        globals()['_ENSURE_PAGE_SINGLETON_META'] = _old_meta
        globals()['_ENSURE_PAGE_RECOVER_GUARD'] = _old_guard_map
        globals()['_ENSURE_PAGE_HEALTH'] = _old_health

def _run_m9_persistence_regression_suite() -> dict:
    rep = {'cases': {}, 'all_pass': False}
    try:
        import tempfile as _tempfile
        _tmp = _tempfile.mkdtemp(prefix='m9_persist_reg_')
        _book_fp = os.path.join(_tmp, 'm9_wangge_zhangben.json')
        _trades_fp = os.path.join(_tmp, 'trades.jsonl')
        _exec_fp = os.path.join(_tmp, 'executor_results.jsonl')
        _err_fp = os.path.join(_tmp, 'go_baocuo.txt')
        gb = GridBook(_book_fp)
        gid = 'BTC_VAR_LONG_M9'
        gb.ensure_grid(gid, 'BTC', 'VAR', 'LONG', start_ts=float(time.time()))
        g = ((gb.data.get('grids') or {}).get(gid) or {})
        g['layers'] = [{
            'layer_id': f'{gid}:2',
            'layer_no': 2,
            'status': 'OPEN',
            'coin': 'BTC',
            'platform': 'VAR',
            'side': 'LONG',
            'open_notional_u': 150.0,
            'amount_u': 150.0,
            'open_ts': float(time.time()),
            'entry_px': 70000.0,
            'source': 'M9_SELF_OPEN',
            'source_module': 'M9',
            'grid_owner_module': 'M9',
            'owner_chain': 'M9_SINGLE_CHAIN',
            'managed_by_grid': True,
            'can_tp_close': True,
            'layer_role': 'GRID_LAYER',
        }]
        gb.data.setdefault('grids', {})[gid] = g
        gb._save()
        rep['cases']['dual_ledger_export_matches_grid_book'] = bool((_m9_verify_dual_ledger_export(_book_fp, gb.data, coin='BTC', platform='VAR', side='LONG') or {}).get('ok'))

        ad = Adapter('','',_trades_fp,_err_fp, executor_fp=_exec_fp)
        _req = {'module': 'M9', 'action_type': 'increase', 'coin': 'BTC', 'platform': 'VAR', 'side': 'LONG', 'meta': {'req_id': 'REQ-PERSIST-001', 'trace_id': 'TRACE-PERSIST-001', 'layer_id': f'{gid}:2'}}
        _rr = {'ok': True, 'submit_ok': True, 'fill_confirmed': True, 'postcheck_ok': True, 'postcheck_state': 'success', 'confirmation_state': 'confirmed_success', 'trade_effective': True, 'req_id': 'REQ-PERSIST-001', 'trace_id': 'TRACE-PERSIST-001', 'req': _req, 'exec_u': 150.0, 'notional_u': 150.0, 'filled_notional_u': 150.0, 'ts': float(time.time())}
        with open(_exec_fp, 'w', encoding='utf-8') as _fexec:
            _fexec.write(json.dumps(_rr, ensure_ascii=False) + "\n")
        ad.append_trades({'ts': float(time.time()), 'positions': {'VAR': {'BTC': {'side': 'LONG', 'notional_u': 150.0}}}}, [_rr])
        rep['cases']['confirmed_m9_trade_must_write_executor_jsonl'] = bool((_m9_verify_executor_results_written(_exec_fp, req_id='REQ-PERSIST-001', trace_id='TRACE-PERSIST-001') or {}).get('ok'))
        rep['cases']['confirmed_m9_trade_must_write_trades_jsonl'] = bool((_m9_verify_trades_written(_trades_fp, req_id='REQ-PERSIST-001', trace_id='TRACE-PERSIST-001') or {}).get('ok'))

        _old_gb = globals().get('GRID_BOOK')
        try:
            globals()['GRID_BOOK'] = gb
            rep['cases']['runtime_persist_verify_must_pass'] = bool((_m9_runtime_persist_verify(req_any=_req, adapter=ad) or {}).get('ok'))
            _dec_req = {'module': 'M9', 'action_type': 'decrease', 'coin': 'BTC', 'platform': 'VAR', 'side': 'LONG', 'grid_id': gid, 'layer_id': f'{gid}:2', 'meta': {'grid_id': gid, 'layer_id': f'{gid}:2'}}
            _gate_ok, _gate_reason, _gate_detail = _m9_book_can_emit_close_req(_dec_req)
            rep['cases']['grid_book_open_layer_can_emit_close_req'] = bool(_gate_ok and str(_gate_reason or '') == 'ok' and str((_gate_detail or {}).get('layer_status') or '') == 'OPEN')
            g2 = ((gb.data.get('grids') or {}).get(gid) or {})
            for _ly in list(g2.get('layers') or []):
                if str(_ly.get('layer_id') or '') == f'{gid}:2':
                    _ly['status'] = 'CLOSED'
                    _ly['close_ts'] = float(time.time())
            gb.data.setdefault('grids', {})[gid] = g2
            gb._save()
            _gate2_ok, _gate2_reason, _gate2_detail = _m9_book_can_emit_close_req(_dec_req)
            rep['cases']['grid_book_closed_layer_must_block_close_req'] = bool((not _gate2_ok) and (('layer_not_open' in str(_gate2_reason or '')) or ('layer_not_found' in str(_gate2_reason or ''))))
        finally:
            if _old_gb is not None:
                globals()['GRID_BOOK'] = _old_gb
            else:
                globals().pop('GRID_BOOK', None)
    except Exception as _e:
        rep['exception'] = repr(_e)
    rep['all_pass'] = bool(rep.get('cases')) and all(bool(v) for v in (rep.get('cases') or {}).values())
    return rep


def _run_tp_m10_truth_source_regression_suite() -> dict:
    rep = {'name': 'tp_m10_truth_source_regression', 'all_pass': True, 'checks': {}}
    try:
        snap = {'data_quality': 'ok', 'positions': {'EXT': {'HYPE': {'side': 'LONG', 'notional_u': 2316.08, 'upnl_u': 27.77, 'has_position': True}}, 'VAR': {'HYPE': {'position_amt': -5.0, 'mark_price': 508.28, 'notional_u': 2541.40, 'upnl_u': -290.09, 'has_position': True}}}}
        st, det = classify_state_detail(snap, 'HYPE')
        ok1 = bool(st == 'HEDGE_OK' and det.get('ext_side') == 'LONG' and det.get('var_side') == 'SHORT')
        rep['checks']['classify_state_detail_uses_unified_leg_truth'] = ok1
        st2 = _postcheck_extract_coin_state(snap, 'HYPE')
        ok2 = bool(st2.get('ext_side') == 'LONG' and st2.get('var_side') == 'SHORT' and st2.get('ext_has') and st2.get('var_has'))
        rep['checks']['postcheck_extract_uses_unified_leg_truth'] = ok2
        rep['all_pass'] = bool(ok1 and ok2)
    except Exception as e:
        rep['all_pass'] = False
        rep['error'] = repr(e)
    return rep

