def _round_maybe_enqueue_profit_lock_early(q, snapshot, coins, fp_human=""):
    """前向包装（早期别名版）：真正实现定义在后文；若尚未定义，不再静默当成功，而是明确落证据。"""
    try:
        _real = globals().get("__REAL_round_maybe_enqueue_profit_lock") or globals().get("_round_maybe_enqueue_profit_lock_impl")
        if callable(_real):
            return _real(q, snapshot, coins, fp_human=fp_human)
    except Exception as _e:
        try:
            _log_exc_level(mod="S1", stage="CRITICAL_IMPL_LOOKUP", level="A", e=_e)
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_46', _e)
            pass
    try:
        _pin("CRITICAL_IMPL_MISSING", mod="S1", coin="*", ok=0,
             reason="profit_lock_impl_not_defined_yet", plat="", act="profit_lock", stage="ROUND_DISPATCH")
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_47', _e)
        pass
