import re as _re

import threading
from types import SimpleNamespace
import argparse
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

sync_playwright = None  # type: ignore
try:
    from playwright.sync_api import sync_playwright as _sync_playwright  # type: ignore
    sync_playwright = _sync_playwright  # type: ignore
except Exception:
    sync_playwright = None

# [PATCH] Extended 已改版：/perp/<COIN>-USD -> /trade/<COIN>-USD（旧链接会自动跳转）。
# 全部 EXT 识别逻辑都按 /perp 写死，这里在 page.url / frame.url 读取口把新路径映射回旧路径。
def _ext_url_compat(_u: Any) -> Any:
    try:
        if isinstance(_u, str) and 'extended.exchange/trade' in _u:
            return _u.replace('extended.exchange/trade', 'extended.exchange/perp', 1)
    except Exception:
        pass
    return _u

try:
    from playwright.sync_api import Page as _PWPage, Frame as _PWFrame  # type: ignore
    for _pw_cls in (_PWPage, _PWFrame):
        _orig_url_prop = getattr(_pw_cls, 'url', None)
        if isinstance(_orig_url_prop, property) and not getattr(_orig_url_prop.fget, '_ext_compat', False):
            def _mk_url_getter(_fget):
                def _url_getter(self):
                    return _ext_url_compat(_fget(self))
                _url_getter._ext_compat = True  # type: ignore[attr-defined]
                return _url_getter
            setattr(_pw_cls, 'url', property(_mk_url_getter(_orig_url_prop.fget)))
except Exception:
    pass

PW_ALIVE = False  # Compatibility/diagnostic summary, not a cross-thread permission flag.
_PW_SESSIONS = _SessionLiveness()


@contextmanager
def _owned_playwright_session():
    try:
        with sync_playwright() as driver:
            _PW_SESSIONS.begin()
            yield driver
    finally:
        # The original context manager still stops this owner's driver exactly once.
        _PW_SESSIONS.end()
        globals()['PW_ALIVE'] = _PW_SESSIONS.any_ready()

_HTTPD = None          # type: ignore
_HTTPD_THREAD = None   # type: ignore

_PW_RUNTIME_GEN = 0
_SNAPSHOT_COMMIT_LOCK = threading.RLock()
_PW_RUNTIME_LAST_RESET_TS = 0.0
_PW_RUNTIME_LAST_READY_TS = 0.0
_PW_RUNTIME_LAST_RESET_REASON = ""
_PW_RUNTIME_RECOVERING = False
_PW_RUNTIME_RECOVERING_SCOPE = {"ALL": False, "EXT": False, "VAR": False}

def _pw_runtime_scope_normalize(plat: Any = "") -> str:
    try:
        s = str(plat or "").upper().strip()
    except Exception:
        s = ""
    if s in ("EXT", "VAR", "ALL"):
        return s
    if s in ("GROUP", "PAIR", "BOTH", "M10"):
        return "ALL"
    return ""

def _pw_runtime_scope_from_reason(reason: Any = "", plat: Any = "") -> str:
    _norm = _pw_runtime_scope_normalize(plat)
    if _norm:
        return _norm
    try:
        txt = str(reason or "").upper()
    except Exception:
        txt = ""
    if ("EXT" in txt) and ("VAR" not in txt):
        return "EXT"
    if ("VAR" in txt) and ("EXT" not in txt):
        return "VAR"
    return "ALL"

def _pw_runtime_auto_release_if_stale(plat: Any = '', *, nowv: float | None = None) -> bool:
    if not _worker_runtime_update_allowed():
        return False
    try:
        _now = float(nowv if nowv is not None else time.time())
    except Exception:
        _now = float(time.time())
    try:
        _timeout = max(2.0, float(globals().get('RUNTIME_RECOVERING_TIMEOUT_SEC', RUNTIME_RECOVERING_TIMEOUT_SEC) or RUNTIME_RECOVERING_TIMEOUT_SEC))
    except Exception:
        _timeout = float(RUNTIME_RECOVERING_TIMEOUT_SEC)
    try:
        _last_reset = float(globals().get('_PW_RUNTIME_LAST_RESET_TS', 0.0) or 0.0)
    except Exception:
        _last_reset = 0.0
    try:
        _last_ready = float(globals().get('_PW_RUNTIME_LAST_READY_TS', 0.0) or 0.0)
    except Exception:
        _last_ready = 0.0
    try:
        _scope = _pw_runtime_scope_normalize(plat)
    except Exception:
        _scope = 'ALL'
    try:
        _scopes = dict(globals().get('_PW_RUNTIME_RECOVERING_SCOPE', {}) or {})
    except Exception:
        _scopes = {}
    _active = bool(globals().get('_PW_RUNTIME_RECOVERING', False))
    if _scope == 'ALL':
        _active = bool(_active or _scopes.get('ALL') or _scopes.get('EXT') or _scopes.get('VAR'))
    elif _scope in ('EXT', 'VAR'):
        _active = bool(_scopes.get('ALL') or _scopes.get(_scope))
    if (not _active) or (_last_reset <= 0.0) or (_last_ready >= _last_reset):
        return False
    if (_now - _last_reset) < _timeout:
        return False
    try:
        _pw_runtime_mark_ready(reason='runtime_rebuilding_timeout_release', plat=_scope)
    except Exception:
        try:
            globals()['_PW_RUNTIME_RECOVERING'] = False
            globals()['_PW_RUNTIME_RECOVERING_SCOPE'] = {'ALL': False, 'EXT': False, 'VAR': False}
            _pw_set_alive(True)
        except Exception:
            pass
    try:
        safe_log(lambda: f"[{now_ts()}] [SYS] PW_RUNTIME_TIMEOUT_RELEASE plat={_scope} timeout={_timeout:.1f}s since_reset={max(0.0, _now - _last_reset):.1f}s")
    except Exception:
        pass
    return True

def _pw_runtime_is_recovering(plat: Any = "") -> bool:
    if bool(globals().get('UI_DISABLE_RUNTIME_RECOVERING_GATE', False)):
        return False
    try:
        _pw_runtime_auto_release_if_stale(plat)
    except Exception:
        pass
    try:
        _scope = _pw_runtime_scope_normalize(plat)
        if not _scope:
            return bool(globals().get("_PW_RUNTIME_RECOVERING", False))
        _scopes = dict(globals().get("_PW_RUNTIME_RECOVERING_SCOPE", {}) or {})
        if _scope == "ALL":
            return bool(globals().get("_PW_RUNTIME_RECOVERING", False)) or bool(_scopes.get("ALL"))
        return bool(_scopes.get("ALL")) or bool(_scopes.get(_scope))
    except Exception:
        return False

def _pw_runtime_begin_recover(reason: str = "", plat: Any = "") -> int:
    if not _worker_runtime_update_allowed():
        return int(globals().get('_PW_RUNTIME_GEN', 0) or 0)
    with _SNAPSHOT_COMMIT_LOCK:
        if not _worker_runtime_update_allowed():
            return int(globals().get('_PW_RUNTIME_GEN', 0) or 0)
        try:
            globals()["_PW_RUNTIME_GEN"] = int(globals().get("_PW_RUNTIME_GEN", 0) or 0) + 1
        except Exception:
            globals()["_PW_RUNTIME_GEN"] = 1
    try:
        globals()["_PW_RUNTIME_LAST_RESET_TS"] = float(time.time())
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_64', _e)
        pass
    try:
        globals()["_PW_RUNTIME_LAST_RESET_REASON"] = str(reason or "")[:240]
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_65', _e)
        pass
    try:
        _scope = _pw_runtime_scope_from_reason(reason, plat)
        _scopes = dict(globals().get("_PW_RUNTIME_RECOVERING_SCOPE", {}) or {})
        if _scope == "ALL":
            _scopes["ALL"] = True
            _scopes["EXT"] = True
            _scopes["VAR"] = True
        elif _scope in ("EXT", "VAR"):
            _scopes[_scope] = True
        else:
            _scopes["ALL"] = True
        globals()["_PW_RUNTIME_RECOVERING_SCOPE"] = _scopes
        globals()["_PW_RUNTIME_RECOVERING"] = bool(_scopes.get("ALL") or _scopes.get("EXT") or _scopes.get("VAR"))
        if not bool(globals().get("_PW_RUNTIME_RECOVERING", False)):
            globals()["_PW_RUNTIME_RECOVERING_OWNER"] = ''
            globals()["_PW_RUNTIME_RECOVERING_REASON"] = ''
            globals()["_PW_RUNTIME_RECOVERING_DEADLINE_TS"] = 0.0
        globals()["_PW_RUNTIME_RECOVERING_OWNER"] = str(_scope or 'ALL')
        globals()["_PW_RUNTIME_RECOVERING_REASON"] = str(reason or '')[:240]
        globals()["_PW_RUNTIME_RECOVERING_DEADLINE_TS"] = float(time.time()) + max(2.0, float(globals().get('RUNTIME_RECOVERING_TIMEOUT_SEC', RUNTIME_RECOVERING_TIMEOUT_SEC) or RUNTIME_RECOVERING_TIMEOUT_SEC))
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_66', _e)
        try:
            globals()["_PW_RUNTIME_RECOVERING"] = True
        except Exception:
            pass
    try:
        _pw_set_alive(False)
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_67', _e)
        pass
    return int(globals().get("_PW_RUNTIME_GEN", 0) or 0)

def _pw_runtime_mark_ready(reason: str = "", plat: Any = "") -> int:
    if not _worker_runtime_update_allowed():
        return int(globals().get('_PW_RUNTIME_GEN', 0) or 0)
    try:
        globals()["_PW_RUNTIME_LAST_READY_TS"] = float(time.time())
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_68', _e)
        pass
    try:
        _scope = _pw_runtime_scope_normalize(plat)
        _scopes = dict(globals().get("_PW_RUNTIME_RECOVERING_SCOPE", {}) or {})
        if not _scope or _scope == "ALL":
            _scopes = {"ALL": False, "EXT": False, "VAR": False}
        elif _scope in ("EXT", "VAR"):
            _scopes[_scope] = False
        globals()["_PW_RUNTIME_RECOVERING_SCOPE"] = _scopes
        globals()["_PW_RUNTIME_RECOVERING"] = bool(_scopes.get("ALL") or _scopes.get("EXT") or _scopes.get("VAR"))
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_69', _e)
        try:
            globals()["_PW_RUNTIME_RECOVERING"] = False
        except Exception:
            pass
    try:
        if not bool(globals().get("_PW_RUNTIME_RECOVERING", False)):
            _pw_set_alive(True)
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_70', _e)
        pass
    try:
        if reason:
            globals()["_PW_RUNTIME_LAST_RESET_REASON"] = str(reason or "")[:240]
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_71', _e)
        pass
    try:
        _runtime_state_clear_recovery_marks(f"pw_runtime_mark_ready:{str(reason or '')[:80]}", clear_round_recovery_once=True)
    except Exception as _e:
        _record_swallowed_exception('pw_runtime_mark_ready.clear_recovery_marks', _e, reason)
        pass
    try:
        _exec_dispatch_claim_release_scope(plat=plat, reason=f'pw_runtime_mark_ready:{str(reason or '')[:80]}')
    except Exception as _e:
        _record_swallowed_exception('pw_runtime_mark_ready.release_scope', _e, reason)
        pass
    return int(globals().get("_PW_RUNTIME_GEN", 0) or 0)

def _pw_runtime_wait_until_ready(timeout_sec: float = 3.0, poll_sec: float = 0.10, *, reason: str = "", logfp: Any = None, mod: str = "SYS") -> bool:
    """等待 Playwright 运行时恢复窗口结束。
    人话：hard reset / rebuild 之后给运行时一个短暂恢复窗；若仍未 ready，也不在这里卡死主链，只返回 False 交给上层决定是否继续重试。
    """
    try:
        _budget = max(0.0, float(timeout_sec or 0.0))
    except Exception:
        _budget = 0.0
    try:
        _poll = min(0.5, max(0.05, float(poll_sec or 0.10)))
    except Exception:
        _poll = 0.10
    _started = float(time.time())
    while True:
        try:
            if (not _pw_runtime_is_recovering()) and bool(globals().get("PW_ALIVE", False)):
                return True
        except Exception:
            pass
        try:
            _elapsed = max(0.0, float(time.time() - _started))
        except Exception:
            _elapsed = 0.0
        if _elapsed >= _budget:
            break
        try:
            time.sleep(_poll)
        except Exception:
            break
    try:
        write_jsonl(logfp, {
            "ts": now_ts(),
            "mod": str(mod or "SYS"),
            "type": "pw_runtime_wait_timeout",
            "reason": str(reason or ""),
            "timeout_sec": float(_budget),
            "recovering": bool(_pw_runtime_is_recovering()),
            "pw_alive": bool(globals().get("PW_ALIVE", False)),
        })
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_71b', _e)
        pass
    return bool((not _pw_runtime_is_recovering()) and bool(globals().get("PW_ALIVE", False)))


def _m2_runtime_critical_enter(stage: str = '') -> None:
    if not _worker_runtime_update_allowed():
        return None
    st = dict(globals().get('_M2_RUNTIME_CRITICAL_STATE', {}) or {})
    tracker = globals().get('_WORKER_STATE')
    if tracker is not None:
        previous_key = str(st.get('worker_key') or '')
        if previous_key and st.get('worker_generation') != tracker.generation(previous_key):
            st = {}
        worker_key = str(getattr(tracker.local, 'worker_key', '') or '')
        if worker_key:
            st.update(worker_key=worker_key, worker_generation=tracker.generation(worker_key),
                      run_token=getattr(tracker.local, 'run_token', None))
    st['depth'] = int(st.get('depth') or 0) + 1
    st['active'] = True
    st['stage'] = str(stage or '')
    st['ts'] = float(time.time())
    globals()['_M2_RUNTIME_CRITICAL_STATE'] = st


def _m2_runtime_critical_exit(stage: str = '') -> None:
    if not _worker_runtime_update_allowed():
        return None
    st = dict(globals().get('_M2_RUNTIME_CRITICAL_STATE', {}) or {})
    tracker = globals().get('_WORKER_STATE')
    token = getattr(tracker.local, 'run_token', None) if tracker is not None else None
    if token and st.get('run_token') not in (None, token):
        return
    depth = max(0, int(st.get('depth') or 0) - 1)
    st['depth'] = depth
    st['stage'] = str(stage or st.get('stage') or '')
    st['active'] = bool(depth > 0)
    globals()['_M2_RUNTIME_CRITICAL_STATE'] = st
    if depth > 0:
        return
    pending = dict(globals().get('_M2_RUNTIME_CRITICAL_PENDING_RESET', {}) or {})
    globals()['_M2_RUNTIME_CRITICAL_PENDING_RESET'] = {}
    if not pending:
        return
    try:
        _pw_runtime_hard_reset(
            str(pending.get('reason') or 'm2_runtime_pending_reset'),
            source=str(pending.get('source') or 'SYS'),
            logfp=pending.get('logfp'),
            stop_exec_runtime=bool(pending.get('stop_exec_runtime', True)),
            rebuild_worker=bool(pending.get('rebuild_worker', False)),
            touch_scan=bool(pending.get('touch_scan', False)),
        )
    except Exception as _e:
        _record_swallowed_exception('m2_runtime_pending_reset_flush', _e)


def _pw_runtime_hard_reset(reason: str = "", *, source: str = "SYS", logfp: Any = None, stop_exec_runtime: bool = True, rebuild_worker: bool = False, touch_scan: bool = False) -> int:
    """统一 Playwright 运行时硬重置。
    口径：一旦确认 UI_DEAD / worker_timeout / owner_thread_mismatch，就先整体判死旧 UI 句柄，
    再让上层走重连/重建；避免旧 locator/page 在恢复窗口继续被拿来用。
    """
    if not _worker_runtime_update_allowed():
        return int(globals().get('_PW_RUNTIME_GEN', 0) or 0)
    _reason = str(reason or "pw_runtime_reset")[:240]
    try:
        _critical = dict(globals().get('_M2_RUNTIME_CRITICAL_STATE', {}) or {})
    except Exception:
        _critical = {}
    tracker = globals().get('_WORKER_STATE')
    critical_key = str(_critical.get('worker_key') or '')
    if tracker is not None and critical_key and _critical.get('worker_generation') != tracker.generation(critical_key):
        _critical = {}
    if bool(_critical.get('active')) and str(source or 'SYS') != 'M2':
        globals()['_M2_RUNTIME_CRITICAL_PENDING_RESET'] = {
            'reason': _reason,
            'source': str(source or 'SYS'),
            'logfp': logfp,
            'stop_exec_runtime': bool(stop_exec_runtime),
            'rebuild_worker': bool(rebuild_worker),
            'touch_scan': bool(touch_scan),
            'deferred_stage': str(_critical.get('stage') or ''),
            'deferred_ts': float(time.time()),
        }
        try:
            safe_log(lambda: f"[{now_ts()}] [{str(source or 'SYS')}] PW_RUNTIME_HARD_RESET_DEFERRED reason={_reason} stage={str(_critical.get('stage') or '')}")
        except Exception as _e:
            _record_swallowed_exception('pw_runtime_hard_reset_deferred_log', _e)
        return int(globals().get('_PW_RUNTIME_GEN', 0) or 0)
    _gen = _pw_runtime_begin_recover(_reason)
    try:
        _exec_dispatch_claim_release_scope(plat=_pw_runtime_scope_from_reason(_reason, source), reason=f'pw_runtime_hard_reset:{_reason[:80]}')
    except Exception as _e:
        _record_swallowed_exception('pw_runtime_hard_reset.release_scope', _e, _reason)
    try:
        globals()["IND_FORCE_PAGE"] = None
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_72', _e)
        pass
    try:
        globals()["_M2_SCAN_CACHE"]["ts"] = 0.0
        globals()["_M2_SCAN_CACHE"]["snap"] = None
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_73', _e)
        pass
    try:
        globals()["_UI_DEAD_TS"] = float(time.time())
        globals()["_UI_DEAD_MOD"] = str(source or "SYS")
        globals()["_UI_DEAD_STAGE"] = "PW_RUNTIME_HARD_RESET"
        globals()["_UI_DEAD_ERR"] = _reason
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_74', _e)
        pass
    if touch_scan:
        try:
            _pct = int((_m2_scan_watch_snapshot() or {}).get("pct") or 0)
            _m2_scan_watch_update("recovering_ui", _pct, "UI 运行时重置中", reason=_reason, state="RECOVERING_UI", touch_panel=True)
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_75', _e)
            pass
    try:
        _runtime_state_set(phase="ROUND_SUMMARY", state="SLEEPING", mainloop_state="RECOVERING_UI", reason_code="pw_runtime_hard_reset", msg=f"UI 运行时重置：{_reason}"[:240], err=_reason[:240], extra={"pw_recovering": True, "pw_recover_reason": _reason, "pw_recover_source": str(source or 'SYS')[:80], "pw_recover_started_ts": float(time.time())})
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_76a', _e)
        pass
    try:
        panel_set_mainloop_state("RECOVERING_UI", hint=f"UI 运行时重置：{_reason}"[:200], err=_reason[:240])
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_76', _e)
        pass
    if stop_exec_runtime:
        try:
            if _exec_runtime_cache_any():
                _exec_runtime_stop(f"pw_runtime_hard_reset:{_reason}", stop_all=True)
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_77', _e)
            pass
    if rebuild_worker:
        try:
            _sync_pw_worker_rebuild(f"pw_runtime_hard_reset:{_reason}", logfp=logfp, mod=str(source or "SYS"), thread_name="M2SyncPlaywrightWorker")
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_78', _e)
            pass
    try:
        safe_log(lambda: f"[{now_ts()}] [{str(source or 'SYS')}] PW_RUNTIME_HARD_RESET gen={_gen} reason={_reason}")
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_79', _e)
        pass
    try:
        _pin("PW_RUNTIME_HARD_RESET", mod=str(source or "SYS"), coin="", ok=0, reason=_reason, plat="", act="", stage="PW_RUNTIME_RESET")
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_80', _e)
        pass
    return _gen

def _pw_set_alive(v: bool) -> None:
    if not _worker_runtime_update_allowed():
        return None
    global PW_ALIVE
    try:
        _PW_SESSIONS.set_ready(bool(v))
        PW_ALIVE = _PW_SESSIONS.any_ready()
    except Exception:
        PW_ALIVE = False

def _pw_guard(*, mod: str = "SYS", coin: str = "", plat: str = "", act: str = "", stage: str = "PW_GUARD") -> bool:
    """任何 Playwright 调用前都应先过这里；若 stop 后仍调用，直接拒绝并打针。"""
    _reason = ""
    try:
        if not _worker_runtime_update_allowed():
            _reason = 'worker_generation_retired'
        elif _pw_runtime_is_recovering(plat):
            _reason = "runtime_recovering"
        elif _PW_SESSIONS.current_alive():
            if globals().get('_EXEC_WORKER_LOCAL') is not None:
                _EXEC_WORKER_LOCAL.pw_guard_reason = ''
            return True
        else:
            _reason = "playwright_not_alive"
    except Exception:
        _reason = "playwright_not_alive"
    if globals().get('_EXEC_WORKER_LOCAL') is not None:
        _EXEC_WORKER_LOCAL.pw_guard_reason = _reason
    try:
        _pin("PW_ALIVE_BLOCK", mod=str(mod or ""), coin=str(coin or ""), ok=0,
             reason=str(_reason or "playwright_not_alive"), plat=str(plat or ""), act=str(act or ""), stage=str(stage or ""))
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_81', _e)
        pass
    return False

def _m2_runtime_short_circuit(*, stage: str = '', plat: str = '', coin: str = '', act: str = '', logfp: Any = None) -> None:
    """M2 主扫描硬短路：运行时已死/恢复中时，立刻抛出 UI_DEAD，禁止继续做假扫描。"""
    if _pw_guard(mod='M2', coin=str(coin or ''), plat=str(plat or ''), act=str(act or ''), stage=str(stage or 'M2_RUNTIME_SHORT_CIRCUIT')):
        return
    _reason = 'runtime_recovering' if _pw_runtime_is_recovering(plat) else 'playwright_not_alive'
    try:
        write_jsonl(logfp, {
            'ts': now_ts(),
            'mod': 'M2',
            'type': 'm2_runtime_short_circuit',
            'stage': str(stage or ''),
            'platform': str(plat or ''),
            'coin': str(coin or ''),
            'action': str(act or ''),
            'reason': str(_reason or ''),
        })
    except Exception as _e:
        _record_swallowed_exception('m2_runtime_short_circuit_jsonl', _e)
    raise _UiDeadError(str(stage or 'm2_runtime_short_circuit'), str(_reason or 'playwright_not_alive'))

def _log_exc_level(mod: str = "SYS", stage: str = "EXC", level: str = "C", e: Exception = None, **kw):
    """异常分级记录：A=硬错误，B=当前币/当前动作失败，C=仅观测失败。"""
    try:
        kw2 = dict(kw or {})
        kw2["level"] = str(level or "C")
        _log_exc(mod=mod, stage=stage, e=e, **kw2)
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_82', _e)
        pass
    try:
        _pin("EXC_LEVEL", mod=str(mod or ""), coin=str(kw.get("coin") or ""), ok=0,
             reason=f"level={str(level or 'C')}|{type(e).__name__ if e else 'Exception'}:{str(e)[:120] if e else ''}",
             plat=str(kw.get("plat") or ""), act=str(kw.get("act") or ""), stage=str(stage or ""))
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_83', _e)
        pass
def _pw_call_or_raise_ui_dead(fn, *, mod: str = "SYS", coin: str = "", plat: str = "", act: str = "", stage: str = "PW_CALL"):
    """统一 Playwright 调用壳：先过活性守卫；若 UI 已死则上抛 _UiDeadError。"""
    if not _pw_guard(mod=mod, coin=coin, plat=plat, act=act, stage=stage):
        raise _UiDeadError("playwright_not_alive")
    try:
        return fn()
    except Exception as _e:
        if _is_ui_dead_exc(_e):
            raise _UiDeadError(str(_e)) from _e
        raise

def _stop_httpd_if_any() -> None:
    """确保：先停 HTTPServer/后台线程，再停 Playwright（即便当前版本未启用 httpd 也安全）。"""
    global _HTTPD, _HTTPD_THREAD
    _stop_ok = True
    try:
        httpd = globals().get("_HTTPD", None)
        th = globals().get("_HTTPD_THREAD", None)
        if httpd is not None:
            try:
                httpd.shutdown()
            except Exception as _e:
                _stop_ok = False
                _log_exc_level(mod="SYS", stage="HTTPD_SHUTDOWN", level="A", e=_e)
            try:
                httpd.server_close()
            except Exception as _e:
                _stop_ok = False
                _log_exc_level(mod="SYS", stage="HTTPD_SERVER_CLOSE", level="A", e=_e)
        if th is not None:
            try:
                th.join(timeout=3.0)
            except Exception as _e:
                _stop_ok = False
                _log_exc_level(mod="SYS", stage="HTTPD_THREAD_JOIN", level="A", e=_e)
    except Exception as _e:
        _stop_ok = False
        _log_exc_level(mod="SYS", stage="HTTPD_STOP_FATAL", level="A", e=_e)
    finally:
        try:
            globals()["_HTTPD"] = None
            globals()["_HTTPD_THREAD"] = None
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_84', _e)
            pass
        try:
            _pin("HTTPD_STOP_OK" if _stop_ok else "HTTPD_STOP_PARTIAL_FAIL", mod="SYS", coin="", ok=1 if _stop_ok else 0,
                 reason="httpd_stopped" if _stop_ok else "httpd_stop_partial_fail", plat="", act="", stage="HTTPD_STOP")
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_85', _e)
            pass

_PwTargetClosedError = None  # type: ignore
_PW_ERR_IMPORT_ATTEMPTED = False
def _lazy_get_pw_target_closed_error():
    global _PwTargetClosedError, _PW_ERR_IMPORT_ATTEMPTED
    if _PwTargetClosedError is not None:
        return _PwTargetClosedError
    if _PW_ERR_IMPORT_ATTEMPTED:
        return None
    _PW_ERR_IMPORT_ATTEMPTED = True
    try:
        from playwright._impl._errors import TargetClosedError as _TCE  # type: ignore
        _PwTargetClosedError = _TCE  # type: ignore
        return _PwTargetClosedError
    except Exception:
        return None

def _log_exc_early(mod: str = "SYS", stage: str = "EXC", e: Exception = None, **kw):
    try:
        import sys as _sys
        import traceback as _tb
        _msg = f"[EARLY_LOG_EXC] mod={mod} stage={stage} e={repr(e)} kw={kw}"
        try:
            _sys.stderr.write(_msg + "\n")
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_86', _e)
            pass
        try:
            _tb.print_exc()
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_87', _e)
            pass
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_88', _e)
        pass
