def _has_small_leg_u(u: float, eps_u: float | None = None) -> bool:
    """small-leg：历史兼容接口（已收敛为“全链路一致”）。
    现在不再把 <20U 直接当无腿；是否算有腿，只看 _has_leg_u 的统一口径。
    因此 small-leg 与 _has_leg_u 完全等价，仅保留函数名避免旧调用点 NameError。
    """
    return _has_leg_u(u, eps_u=eps_u)

def _small_leg_ratio(a_u: float, b_u: float) -> float:
    try:
        a = float(abs(float(a_u or 0.0)))
        b = float(abs(float(b_u or 0.0)))
        mx = max(a, b, 1e-12)
        mn = min(a, b)
        return float(mn / mx)
    except Exception:
        return 0.0

def _has_leg_u(u: float, eps_u: float | None = None) -> bool:
    try:
        uu = float(abs(float(u or 0.0)))
    except Exception:
        uu = 0.0
    try:
        thr = float(B1_NO_LEG_EPS_U if eps_u is None else eps_u)
    except Exception:
        thr = 20.0
    return uu > (thr + 1e-12)

def _norm_leg_u(u: float, eps_u: float | None = None) -> float:
    """把 <= 阈值 的尘埃腿归零（用于门禁/分类/候选筛选），不影响原始快照字段。"""
    try:
        uu = float(abs(float(u or 0.0)))
    except Exception:
        uu = 0.0
    return uu if _has_leg_u(uu, eps_u=eps_u) else 0.0

def _get_coin_indicators(snapshot: dict | None, coin: str):
    """统一币种指标输出口径：返回 (rsi, adx, reason)。
    这里专门给 round summary / trend digest 用，避免直接调用 _legacy_deleted_get_adx_rsi 时把顺序拿反。"""
    try:
        adx, rsi, reason = _legacy_deleted_get_adx_rsi(snapshot or {}, str(coin or '').upper().strip())
        return rsi, adx, reason
    except Exception as _e:
        try:
            _log_exc_level(mod="SUMMARY", stage="ROUND_SUMMARY_BROKEN", level="A", e=_e, coin=str(coin or '').upper().strip())
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_89', _e)
            pass
        return None, None, f"indicator_exc:{type(_e).__name__}"

def _trend_field_selfcheck(coin: str, platform: str, trend_view: dict | None) -> None:
    """趋势观测字段完整性自检：缺字段时统一补默认值，再落证据。
    人话：谁生产趋势视图，谁把字段补齐；下游别再一边拿到字段、一边拿不到。"""
    try:
        defaults = {
            'trend_side': 'NONE',
            'trend_reason': '',
            'cover_ratio': 0.0,
            'trend_layers_open': 0,
            'trend_layers_cap': 0,
            'freeze_loss_leg_new_grid': False,
            'trend_policy_block_new_grid': False,
            'trend_policy_allow': True,
            'trend_state': 'NORMAL',
            'trend_alpha': 0,
            'opp_side_frozen': 0,
            'runner_protect': 0,
        }
        tv = trend_view if isinstance(trend_view, dict) else {}
        missing = []
        for _k, _v in defaults.items():
            if (_k not in tv) or (tv.get(_k) is None):
                tv[_k] = copy.deepcopy(_v)
                missing.append(_k)
        if missing and bool(globals().get('TRACE_TREND_FIELD_FILLED', False)):
            safe_log(lambda: f"[{now_ts()}] TREND_FIELD_FILLED coin={str(coin or '').upper()} plat={str(platform or '').upper()} filled={','.join(missing)}")
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_90', _e)
        pass

def _trend_observe_coin_pool(snapshot: dict | None = None, coins: list[str] | None = None) -> list[str]:
    """趋势观察统一取币池：老八币 + 当前活跃持仓 + 候补宇宙 + snapshot 持仓/指标。
    人话：趋势观察不再只盯 MAIN_COINS，所有当前正在持有或正在候选的币都要进观察池。"""
    out: list[str] = []
    try:
        out.extend([str(x or '').upper().strip() for x in list(coins or []) if str(x or '').strip()])
    except Exception:
        pass
    try:
        out.extend([str(x or '').upper().strip() for x in list(globals().get('MAIN_COINS') or []) if str(x or '').strip()])
    except Exception:
        pass
    try:
        pos_root = _pos_root(snapshot or {}) if callable(globals().get('_pos_root')) else {}
    except Exception:
        pos_root = {}
    try:
        for _plat_rows in list((pos_root or {}).values()):
            if isinstance(_plat_rows, dict):
                for _coin0 in list(_plat_rows.keys()):
                    _cu0 = _ext_canonical_coin(_coin0)
                    if _cu0:
                        out.append(_cu0)
    except Exception:
        pass
    try:
        _pool_st = _coin_pool_state_load(force=False)
        for _coin0 in list((_pool_st or {}).get('active_holding_coins') or []):
            _cu0 = _ext_canonical_coin(_coin0)
            if _cu0:
                out.append(_cu0)
        for _coin0 in list((_pool_st or {}).get('waiting_queue') or []):
            _cu0 = _ext_canonical_coin(_coin0)
            if _cu0:
                out.append(_cu0)
        for _row0 in list((_pool_st or {}).get('ranked_openable_universe') or []):
            if isinstance(_row0, dict):
                _cu0 = _ext_canonical_coin(_row0.get('coin'))
                if _cu0:
                    out.append(_cu0)
    except Exception:
        pass
    try:
        _inds = (snapshot or {}).get('indicators') or {}
        if isinstance(_inds, dict):
            for _coin0 in list(_inds.keys()):
                _cu0 = _ext_canonical_coin(_coin0)
                if _cu0:
                    out.append(_cu0)
    except Exception:
        pass
    return list(dict.fromkeys([str(x or '').upper().strip() for x in out if str(x or '').strip()]))

def _trend_observe_compact(snapshot: dict | None = None, coins: list[str] | None = None, *, limit: int = 8) -> dict:
    """给日志/面板输出一份简洁的趋势观测快照。
    人话：把“当前哪些币进了 TREND、哪条腿被冻结、为什么 B2/M10 被拦”压成一眼能看的摘要。
    现在会按：主趋势币 / 候补趋势币 / 退出态币 分组，方便先看最重要的币。"""
    out = {
        'rows': [], 'head': [], 'alpha_coins': [], 'blocked_coins': [], 'ts': float(time.time()),
        'groups': {'alpha': [], 'candidate': [], 'exit_only': [], 'normal': []},
        'group_counts': {'alpha': 0, 'candidate': 0, 'exit_only': 0, 'normal': 0},
    }
    try:
        snap = snapshot if isinstance(snapshot, dict) and snapshot else (globals().get('LAST_GOOD_SNAPSHOT') if isinstance(globals().get('LAST_GOOD_SNAPSHOT'), dict) else {})
        coin_list = _trend_observe_coin_pool(snap, list(coins or []))
        seen = set()
        for c in coin_list:
            if c in seen:
                continue
            seen.add(c)
            try:
                rsi_v, adx_v, _ = _get_coin_indicators(snap or {}, c)
            except Exception:
                rsi_v, adx_v = None, None
            try:
                tv_ext = _m9_payload_trend_view(snap or {}, c, 'EXT', rsi_v, adx_v) or {}
                tv_var = _m9_payload_trend_view(snap or {}, c, 'VAR', rsi_v, adx_v) or {}
            except Exception:
                tv_ext, tv_var = {}, {}
            tv = tv_ext if str(tv_ext.get('trend_side') or '') else tv_var
            guard = {}
            try:
                guard = _trend_alpha_guard_for_b2_m10(snap or {}, c) or {}
            except Exception:
                guard = {}
            row = {
                'coin': c,
                'trend_side': str((tv.get('trend_side') or guard.get('trend_side') or '') or ''),
                'trend_state': str((tv.get('trend_state') or guard.get('trend_state') or 'NORMAL') or 'NORMAL'),
                'trend_alpha': int(bool(tv.get('trend_alpha') or guard.get('trend_alpha'))),
                'opp_side_frozen': int(bool(tv.get('opp_side_frozen') or guard.get('opp_side_frozen'))),
                'runner_protect': int(bool(tv.get('runner_protect') or guard.get('runner_protect'))),
                'freeze_ext': int(tv_ext.get('freeze_loss_leg_new_grid') or 0),
                'freeze_var': int(tv_var.get('freeze_loss_leg_new_grid') or 0),
                'trend_reason': str((tv.get('trend_reason') or guard.get('reason') or '-') or '-'),
                'same_upnl_u': float((tv.get('same_upnl_u') or guard.get('same_upnl_u') or 0.0) or 0.0),
                'opp_upnl_u': float((tv.get('opp_upnl_u') or guard.get('opp_upnl_u') or 0.0) or 0.0),
                'rsi': _safe_float(rsi_v, None),
                'b2_guard': 'ON' if str(guard.get('trend_state') or '') == 'TREND_ALPHA' and int(bool(guard.get('trend_alpha'))) == 1 else 'OFF',
                'm10_guard': 'ON' if str(guard.get('trend_state') or '') in ('TREND_ALPHA','TREND_EXIT_ONLY') and int(bool(guard.get('runner_protect'))) == 1 else 'OFF',
            }
            out['rows'].append(row)
        def _sort_key(r):
            state = str(r.get('trend_state') or '')
            grp_rank = 0 if int(r.get('trend_alpha') or 0) == 1 else (1 if state == 'TREND_CANDIDATE' else (2 if state == 'TREND_EXIT_ONLY' else 3))
            return (grp_rank, -abs(float(r.get('same_upnl_u') or 0.0)), str(r.get('coin') or ''))
        out['rows'] = sorted(out['rows'], key=_sort_key)[:max(1, int(limit or 8))]
        out['alpha_coins'] = [str(r.get('coin') or '') for r in out['rows'] if int(r.get('trend_alpha') or 0) == 1]
        out['blocked_coins'] = [str(r.get('coin') or '') for r in out['rows'] if int(r.get('opp_side_frozen') or 0) == 1 or str(r.get('trend_state') or '') == 'TREND_EXIT_ONLY']
        def _row_line(r):
            return f"{r.get('coin')}|{r.get('trend_side') or '-'}|{r.get('trend_state') or 'NORMAL'}|冻EXT={int(r.get('freeze_ext') or 0)}/VAR={int(r.get('freeze_var') or 0)}|B2={r.get('b2_guard')}|M10={r.get('m10_guard')}|因={r.get('trend_reason') or '-'}"
        for r in out['rows']:
            state = str(r.get('trend_state') or 'NORMAL')
            if int(r.get('trend_alpha') or 0) == 1:
                out['groups']['alpha'].append(r)
            elif state == 'TREND_CANDIDATE':
                out['groups']['candidate'].append(r)
            elif state == 'TREND_EXIT_ONLY':
                out['groups']['exit_only'].append(r)
            else:
                out['groups']['normal'].append(r)
        for k in list((out.get('groups') or {}).keys()):
            out['group_counts'][k] = len(list((out.get('groups') or {}).get(k) or []))
        group_specs = [
            ('alpha', '主趋势币'),
            ('candidate', '候补趋势币'),
            ('exit_only', '退出态币'),
        ]
        grouped_head = []
        for key, title in group_specs:
            rows = list((out.get('groups') or {}).get(key) or [])
            if not rows:
                continue
            grouped_head.append(f"{title}[{len(rows)}]")
            for r in rows[:max(1, int(limit or 8))]:
                grouped_head.append(_row_line(r))
        if not grouped_head:
            grouped_head = [_row_line(r) for r in out['rows']]
        out['head'] = grouped_head
        out['head_alpha'] = [_row_line(r) for r in list((out.get('groups') or {}).get('alpha') or [])]
        out['head_candidate'] = [_row_line(r) for r in list((out.get('groups') or {}).get('candidate') or [])]
        out['head_exit_only'] = [_row_line(r) for r in list((out.get('groups') or {}).get('exit_only') or [])]
        out['head_normal'] = [_row_line(r) for r in list((out.get('groups') or {}).get('normal') or [])]
        out['panel_sections'] = {
            'alpha_title': f"主趋势币[{len(list((out.get('groups') or {}).get('alpha') or []))}]",
            'candidate_title': f"候补趋势币[{len(list((out.get('groups') or {}).get('candidate') or []))}]",
            'exit_only_title': f"退出态币[{len(list((out.get('groups') or {}).get('exit_only') or []))}]",
            'normal_title': f"普通币[{len(list((out.get('groups') or {}).get('normal') or []))}]",
            'alpha_lines': list(out.get('head_alpha') or []),
            'candidate_lines': list(out.get('head_candidate') or []),
            'exit_only_lines': list(out.get('head_exit_only') or []),
            'normal_lines': list(out.get('head_normal') or []),
        }
        out['panel_sections_text'] = {
            'alpha': '\n'.join([str((out.get('panel_sections') or {}).get('alpha_title') or '')] + list(out.get('head_alpha') or [])) if list(out.get('head_alpha') or []) else str((out.get('panel_sections') or {}).get('alpha_title') or '主趋势币[0]'),
            'candidate': '\n'.join([str((out.get('panel_sections') or {}).get('candidate_title') or '')] + list(out.get('head_candidate') or [])) if list(out.get('head_candidate') or []) else str((out.get('panel_sections') or {}).get('candidate_title') or '候补趋势币[0]'),
            'exit_only': '\n'.join([str((out.get('panel_sections') or {}).get('exit_only_title') or '')] + list(out.get('head_exit_only') or [])) if list(out.get('head_exit_only') or []) else str((out.get('panel_sections') or {}).get('exit_only_title') or '退出态币[0]'),
            'normal': '\n'.join([str((out.get('panel_sections') or {}).get('normal_title') or '')] + list(out.get('head_normal') or [])) if list(out.get('head_normal') or []) else str((out.get('panel_sections') or {}).get('normal_title') or '普通币[0]'),
        }
        out['panel_blocks'] = [
            {'key': 'alpha', 'title': str((out.get('panel_sections') or {}).get('alpha_title') or ''), 'lines': list(out.get('head_alpha') or [])},
            {'key': 'candidate', 'title': str((out.get('panel_sections') or {}).get('candidate_title') or ''), 'lines': list(out.get('head_candidate') or [])},
            {'key': 'exit_only', 'title': str((out.get('panel_sections') or {}).get('exit_only_title') or ''), 'lines': list(out.get('head_exit_only') or [])},
            {'key': 'normal', 'title': str((out.get('panel_sections') or {}).get('normal_title') or ''), 'lines': list(out.get('head_normal') or [])},
        ]
    except Exception as _e:
        out['error'] = f'trend_observe_exc:{type(_e).__name__}'
    return out

def _selection_observe_compact(*, limit: int = 30) -> dict:
    """给面板输出一份选币观察快照。
    人话：把“EXT∩VAR共享池排名 -> 最终候补/入选 -> 计算方式说明”压成一页能看的摘要。"""
    out = {
        'rows': [], 'ts': float(time.time()), 'meta': {},
        'groups': {'binance': [], 'merged': [], 'final': [], 'calc': []},
        'group_counts': {'binance': 0, 'merged': 0, 'final': 0, 'calc': 0},
    }
    try:
        st = _coin_pool_state_load(force=False)
        diag = dict((st or {}).get('last_refresh_diag') or {}) if isinstance(st, dict) else {}
        raw_rows = []
        for src_key in ('selection_detail_rows', 'last_selection_detail_rows'):
            for row in list(diag.get(src_key) or []):
                if isinstance(row, dict):
                    raw_rows.append(dict(row))
        if not raw_rows:
            for row in list((st or {}).get('ranked_openable_universe') or []):
                if isinstance(row, dict):
                    raw_rows.append(dict(row))
        detail_rows = []
        seen = set()
        for row in raw_rows:
            try:
                det = _coin_pool_selection_detail_row(row if isinstance(row, dict) else {})
                coin = str(det.get('coin') or '').upper().strip()
                if not coin or coin in seen:
                    continue
                seen.add(coin)
                detail_rows.append(det)
            except Exception:
                continue
        detail_rows = sorted(detail_rows, key=lambda r: (999999 if int(r.get('binance_rank_all') or 0) <= 0 else int(r.get('binance_rank_all') or 0), -float(r.get('score') or 0.0), str(r.get('coin') or '')))[:max(10, int(limit or 30))]
        out['rows'] = list(detail_rows)
        def _line(r: dict) -> str:
            return (
                f"{int(r.get('binance_rank_all') or 0):>2}.{str(r.get('coin') or '-')} | 分={float(r.get('score') or 0.0):.4f} | "
                f"EXT={str(r.get('in_ext') or '?')} VAR={str(r.get('in_var') or '?')} | 最终={int(r.get('final_rank') or 0)} | 结果={str(r.get('result') or '-') }"
            )
        binance_rows = [r for r in detail_rows if int(r.get('binance_rank_all') or 0) > 0]
        merged_rows = [r for r in detail_rows if int(r.get('metric_ok') or 0) == 1 and str(r.get('in_ext') or '') == 'Y' and str(r.get('in_var') or '') == 'Y']
        final_rows = [r for r in detail_rows if int(r.get('final_rank') or 0) > 0 or int(r.get('in_waiting_queue') or 0) == 1]
        calc_lines = []
        calc_lines.append('共享池范围：EXT∩VAR 共有币，不再先走币安合约 top30')
        calc_lines.append('综合分公式：score = 成交额分×0.65 + 波动率分×0.20 + 趋势分×0.15')
        calc_lines.append('平台交集规则：候选池固定为 EXT∩VAR，共享池外直接不参与排名')
        calc_lines.append('最终候补规则：共享池指标就绪后，再扣除已持仓/禁重开/名额限制，保留最终候补队列')
        if str(diag.get('selection_steps') or '').strip():
            try:
                for s in list(diag.get('selection_steps') or [])[:8]:
                    if str(s or '').strip():
                        calc_lines.append(f"步骤：{str(s)}")
            except Exception:
                pass
        if str(diag.get('selection_reason') or '').strip():
            calc_lines.append(f"本轮口径：{str(diag.get('selection_reason') or '')}")
        out['groups']['binance'] = list(binance_rows[:max(8, int(limit or 30))])
        out['groups']['merged'] = list(merged_rows[:max(8, int(limit or 30))])
        out['groups']['final'] = list(final_rows[:max(8, int(limit or 30))])
        out['groups']['calc'] = [{'detail': x} for x in calc_lines]
        for k in ('binance','merged','final','calc'):
            out['group_counts'][k] = len(list(out['groups'].get(k) or []))
        out['head_binance'] = [_line(r) for r in out['groups']['binance']]
        out['head_merged'] = [_line(r) for r in out['groups']['merged']]
        out['head_final'] = [_line(r) for r in out['groups']['final']]
        out['head_calc'] = list(calc_lines)
        out['panel_sections'] = {
            'binance_title': f"共享池综合排名[{len(out['groups']['binance'])}]",
            'merged_title': f"交集后排名[{len(out['groups']['merged'])}]",
            'final_title': f"最终候补/入选[{len(out['groups']['final'])}]",
            'calc_title': f"计算方式和数据[{len(calc_lines)}]",
            'binance_lines': list(out['head_binance']),
            'merged_lines': list(out['head_merged']),
            'final_lines': list(out['head_final']),
            'calc_lines': list(out['head_calc']),
        }
        out['panel_sections_text'] = {
            'binance': '\n'.join([out['panel_sections']['binance_title']] + list(out['head_binance'])) if out['head_binance'] else out['panel_sections']['binance_title'],
            'merged': '\n'.join([out['panel_sections']['merged_title']] + list(out['head_merged'])) if out['head_merged'] else out['panel_sections']['merged_title'],
            'final': '\n'.join([out['panel_sections']['final_title']] + list(out['head_final'])) if out['head_final'] else out['panel_sections']['final_title'],
            'calc': '\n'.join([out['panel_sections']['calc_title']] + list(out['head_calc'])) if out['head_calc'] else out['panel_sections']['calc_title'],
        }
        out['panel_blocks'] = [
            {'key': 'binance', 'title': out['panel_sections']['binance_title'], 'lines': list(out['head_binance'])},
            {'key': 'merged', 'title': out['panel_sections']['merged_title'], 'lines': list(out['head_merged'])},
            {'key': 'final', 'title': out['panel_sections']['final_title'], 'lines': list(out['head_final'])},
            {'key': 'calc', 'title': out['panel_sections']['calc_title'], 'lines': list(out['head_calc'])},
        ]
        out['meta'] = {
            'selection_scope': str(diag.get('selection_scope') or ''),
            'selection_reason': str(diag.get('selection_reason') or ''),
            'queue_head': str(diag.get('queue_head') or ''),
            'queue_preview': list(diag.get('queue_preview') or []),
            'topn_limit': int(_coin_pool_binance_topn()),
            'rank_rule': 'score=24h_coin_quote_volume_rank*0.60+24h_1h_tr_volatility_rank*0.40',
            'updated_at': float((st or {}).get('ts') or time.time()),
        }
    except Exception as _e:
        out['error'] = f'selection_observe_exc:{type(_e).__name__}'
    return out

