_READINESS_LOCK = threading.Lock()
_READINESS = {
    "trade_enabled": False,    # 默认先关闸；三路 readiness 连续达标后再开
    "pos": {"status": "UNKNOWN", "ts": 0.0, "reason": "bootstrap_pending", "ok_streak": 0, "source": "bootstrap", "scope": "global"},
    "ind": {"status": "UNKNOWN", "ts": 0.0, "reason": "bootstrap_pending", "ok_streak": 0, "source": "bootstrap", "scope": "global"},
    "gate": {"status": "UNKNOWN", "ts": 0.0, "reason": "bootstrap_pending", "ok_streak": 0, "source": "bootstrap", "scope": "global"},
    "last_block_reason": "bootstrap_pending",
    "source": "bootstrap",
    "scope": "global",
    "last_update_ts": 0.0,
}
_READINESS_LOCAL_OBS = {
    "pos": {"status": "UNKNOWN", "ts": 0.0, "reason": "", "source": "", "scope": "local"},
    "ind": {"status": "UNKNOWN", "ts": 0.0, "reason": "", "source": "", "scope": "local"},
    "gate": {"status": "UNKNOWN", "ts": 0.0, "reason": "", "source": "", "scope": "local"},
}

_GATE_HEARTBEAT_LOCK = threading.Lock()
_GATE_HEARTBEAT = {
    "ts": 0.0,
    "source": "",
    "reason": "",
    "req_id": "",
    "round_id": "",
}

_READY_OK_STREAK_TO_OPEN = 2

def _gate_heartbeat_touch(source: str, reason: str = "", req=None, round_id: str = "") -> None:
    try:
        nowv = float(time.time())
        src = str(source or "")[:64]
        rs = str(reason or "")[:160]
        rid = ""
        if isinstance(req, dict):
            try:
                rid = str(req.get("req_id") or req.get("id") or req.get("request_id") or "")[:96]
            except Exception:
                rid = ""
        with _GATE_HEARTBEAT_LOCK:
            _GATE_HEARTBEAT["ts"] = nowv
            _GATE_HEARTBEAT["source"] = src
            _GATE_HEARTBEAT["reason"] = rs
            _GATE_HEARTBEAT["req_id"] = rid
            _GATE_HEARTBEAT["round_id"] = str(round_id or "")[:96]
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_91', _e)
        pass
def _gate_heartbeat_snapshot() -> dict:
    try:
        with _GATE_HEARTBEAT_LOCK:
            return dict(_GATE_HEARTBEAT)
    except Exception:
        return {"ts": 0.0, "source": "", "reason": "", "req_id": "", "round_id": ""}

def _readiness_set(kind: str, status: str, reason: str = "", *, scope: str = "global", source: str = "") -> None:
    if not _worker_runtime_update_allowed():
        return None
    kind = str(kind or "").lower().strip()
    st = str(status or "").upper().strip()
    rs = str(reason or "")[:240]
    scope_u = str(scope or "global").lower().strip() or "global"
    src = str(source or ("full_scan_only" if scope_u == "global" else "local_observation"))[:64]
    nowv = float(time.time())
    with _READINESS_LOCK:
        if kind not in ("pos", "ind", "gate"):
            return
        if scope_u != "global":
            node = _READINESS_LOCAL_OBS.get(kind, {})
            if not isinstance(node, dict):
                node = {}
            node.update({"status": st, "ts": nowv, "reason": rs, "source": src, "scope": scope_u})
            _READINESS_LOCAL_OBS[kind] = node
            return
        node = _READINESS.get(kind, {})
        if not isinstance(node, dict):
            node = {}
            _READINESS[kind] = node
        _prev_block_reason = str(_READINESS.get("last_block_reason") or "")
        node["status"] = st
        node["ts"] = nowv
        node["reason"] = rs
        node["source"] = src
        node["scope"] = "global"
        if st == "OK":
            node["ok_streak"] = int(node.get("ok_streak") or 0) + 1
        else:
            node["ok_streak"] = 0
        _READINESS["source"] = src
        _READINESS["scope"] = "global"
        _READINESS["last_update_ts"] = nowv

        if st == "FAIL":
            _READINESS["trade_enabled"] = False
            _READINESS["last_block_reason"] = f"{kind}:{rs}"
            try:
                pos_fail = (str((_READINESS.get("pos") or {}).get("status") or "").upper() == "FAIL")
                ind_fail = (str((_READINESS.get("ind") or {}).get("status") or "").upper() == "FAIL")
                gate_fail = (str((_READINESS.get("gate") or {}).get("status") or "").upper() == "FAIL")
                if pos_fail and ind_fail and gate_fail:
                    _request_soft_restart('READINESS_ALL_FAIL', {
                        'kind': kind,
                        'reason': rs,
                        'last_block_reason': str(_READINESS.get('last_block_reason') or ''),
                    }, source='READINESS')
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_92', _e)
                pass
        else:
            try:
                _pos_status = str((_READINESS.get("pos") or {}).get("status") or "").upper()
                _ind_status = str((_READINESS.get("ind") or {}).get("status") or "").upper()
                _gate_status = str((_READINESS.get("gate") or {}).get("status") or "").upper()
                _pos_reason = str((_READINESS.get("pos") or {}).get("reason") or "")
                _ind_reason = str((_READINESS.get("ind") or {}).get("reason") or "")
                _gate_reason = str((_READINESS.get("gate") or {}).get("reason") or "")
                _pos_streak = int((_READINESS.get("pos") or {}).get("ok_streak") or 0)
                _ind_streak = int((_READINESS.get("ind") or {}).get("ok_streak") or 0)
                _gate_streak = int((_READINESS.get("gate") or {}).get("ok_streak") or 0)
                pos_ok = (_pos_status == "OK" and _pos_streak >= _READY_OK_STREAK_TO_OPEN)
                ind_ok = (_ind_status == "OK" and _ind_streak >= _READY_OK_STREAK_TO_OPEN)
                gate_ok = (_gate_status == "OK" and _gate_streak >= _READY_OK_STREAK_TO_OPEN)
                ind_cache_degraded = (
                    _ind_status == "DEGRADED"
                    and (
                        ("cache_ok=" in _ind_reason)
                        or ("indicators_all_missing_but_cache_ok=" in _ind_reason)
                        or ("ind_partial_ok=" in _ind_reason)
                    )
                )
                degrade_release = (
                    _pos_status == "OK"
                    and _gate_status == "OK"
                    and ind_cache_degraded
                    and (
                        ("ind_partial_ok=" in _ind_reason)
                        or ("cache_ok=" in _ind_reason)
                        or ("indicators_all_missing_but_cache_ok=" in _ind_reason)
                    )
                )
                bootstrap_release = (
                    _prev_block_reason == "bootstrap_pending"
                    and _pos_status == "OK"
                    and _ind_status == "OK"
                    and _gate_status == "OK"
                    and _pos_streak >= 1
                    and _ind_streak >= 1
                    and _gate_streak >= 1
                )
                if pos_ok and ind_ok and gate_ok:
                    _READINESS["trade_enabled"] = True
                    _READINESS["last_block_reason"] = ""
                elif degrade_release:
                    _READINESS["trade_enabled"] = True
                    _READINESS["last_block_reason"] = f"ind:{_ind_reason or 'degraded_cache_ok'}"
                    try:
                        _READINESS["degraded_release_ts"] = nowv
                        _READINESS["degraded_release_reason"] = str(_ind_reason or '')[:240]
                    except Exception as _e:
                        _record_swallowed_exception('except_pass_line_93', _e)
                        pass
                elif bootstrap_release:
                    _READINESS["trade_enabled"] = True
                    _READINESS["last_block_reason"] = ""
                    try:
                        _READINESS["bootstrap_release_ts"] = nowv
                    except Exception as _e:
                        _record_swallowed_exception('except_pass_line_94', _e)
                        pass
                elif not bool(_READINESS.get("trade_enabled", False)):
                    if _pos_status == "FAIL":
                        _READINESS["last_block_reason"] = f"pos:{_pos_reason}"
                    elif _gate_status == "FAIL":
                        _READINESS["last_block_reason"] = f"gate:{_gate_reason}"
                    elif _ind_status == "FAIL":
                        _READINESS["last_block_reason"] = f"ind:{_ind_reason}"
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_95', _e)
                pass
    try:
        _log_jsonl(os.path.join(str(globals().get("OUT_DIR") or "out"), "readiness_audit.jsonl"), {
            "ts": nowv, "kind": kind, "status": st, "reason": rs, "scope": scope_u, "source": src,
            "trade_enabled": bool(_READINESS.get("trade_enabled", False)),
            "last_block_reason": str(_READINESS.get("last_block_reason") or ""),
        })
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_96', _e)
        pass
def _derive_readiness_blocker_snapshot(snap: dict | None = None) -> dict:
    snap = snap if isinstance(snap, dict) else {}
    try:
        block_reason = str(snap.get("last_block_reason") or "").strip()
    except Exception:
        block_reason = ""
    try:
        pos_status = snap.get("pos_status") if isinstance(snap.get("pos_status"), dict) else {}
    except Exception:
        pos_status = {}
    try:
        ind_status = snap.get("ind_status") if isinstance(snap.get("ind_status"), dict) else {}
    except Exception:
        ind_status = {}
    try:
        gate_status = snap.get("gate_status") if isinstance(snap.get("gate_status"), dict) else {}
    except Exception:
        gate_status = {}
    try:
        hb = snap.get("gate_heartbeat") if isinstance(snap.get("gate_heartbeat"), dict) else {}
    except Exception:
        hb = {}
    reason_chain = []
    for _name, _obj in (("pos", pos_status), ("ind", ind_status), ("gate", gate_status)):
        try:
            _st = str((_obj or {}).get("status") or "").upper().strip()
            _rs = str((_obj or {}).get("reason") or "").strip()
            if _st and _st != "OK":
                reason_chain.append({"kind": _name, "status": _st, "reason": _rs})
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_97', _e)
            pass
    main_reason = block_reason or (reason_chain[0]["reason"] if reason_chain else "trade_enabled")
    main_stage = reason_chain[0]["kind"] if reason_chain else ("global" if block_reason else "ready")
    return {
        "trade_enabled": bool(snap.get("trade_enabled", False)),
        "main_reason": str(main_reason or "trade_enabled"),
        "main_stage": str(main_stage or "ready"),
        "reason_chain": reason_chain,
        "gate_heartbeat_reason": str((hb or {}).get("reason") or ""),
        "gate_heartbeat_source": str((hb or {}).get("source") or ""),
        "gate_heartbeat_round_id": str((hb or {}).get("round_id") or ""),
        "boot_block_reason": str(globals().get("_BOOT_PREFLIGHT_BLOCK_REASON", "") or ""),
        "boot_report": dict(globals().get("_BOOT_PREFLIGHT_LAST", {}) or {}),
    }

def _readiness_snapshot_fields() -> dict:
    with _READINESS_LOCK:
        snap = {
            "trade_enabled": bool(_READINESS.get("trade_enabled", False)),
            "pos_status": dict(_READINESS.get("pos") or {}),
            "ind_status": dict(_READINESS.get("ind") or {}),
            "gate_status": dict(_READINESS.get("gate") or {}),
            "local_pos_status": dict((_READINESS_LOCAL_OBS or {}).get("pos") or {}),
            "local_ind_status": dict((_READINESS_LOCAL_OBS or {}).get("ind") or {}),
            "local_gate_status": dict((_READINESS_LOCAL_OBS or {}).get("gate") or {}),
            "last_block_reason": str(_READINESS.get("last_block_reason") or ""),
            "gate_version": str(GATE_VERSION),
            "readiness_source": str(_READINESS.get("source") or ""),
            "readiness_scope": str(_READINESS.get("scope") or "global"),
            "readiness_updated_ts": float(_READINESS.get("last_update_ts") or 0.0),
        }
    try:
        snap["gate_heartbeat"] = _gate_heartbeat_snapshot()
    except Exception:
        snap["gate_heartbeat"] = {"ts": 0.0, "source": "", "reason": "", "req_id": "", "round_id": ""}
    try:
        snap["blocker_snapshot"] = _derive_readiness_blocker_snapshot(snap)
    except Exception:
        snap["blocker_snapshot"] = {"trade_enabled": bool(snap.get("trade_enabled", False)), "main_reason": str(snap.get("last_block_reason") or ""), "main_stage": "global", "reason_chain": []}
    return snap

def _readiness_block_reason() -> str:
    with _READINESS_LOCK:
        if bool(_READINESS.get("trade_enabled", False)):
            return ""
        return str(_READINESS.get("last_block_reason") or "blocked")

def _readiness_coin_individual_allow(reqd: dict, reqn: dict | None = None, blk: str = "") -> tuple[bool, str, dict]:
    """单币放行：当全局因 bootstrap/指标局部退化关闸时，只放行“本币指标新鲜且 gate/pos 没硬失败”的请求。

    人话：某一个币指标读坏，不该把其它币一起拖死。
    """
    det = {"coin": "", "block": str(blk or ""), "mode": "", "ind_reason": "", "gate_status": "", "pos_status": ""}
    try:
        reqn = reqn or _normalize_req_for_gate(reqd)
        coin = str((reqn or {}).get("coin") or "").upper().strip()
        mod = str((reqn or {}).get("mod") or "").upper().strip()
        act = str((reqn or {}).get("act") or "").lower().strip()
        det["coin"] = coin
        if not coin:
            det["mode"] = "bad_coin"
            return False, "", det
        if not str(blk or ""):
            det["mode"] = "no_block"
            return False, "", det
        blk_u = str(blk or "").lower().strip()
        if not (blk_u == 'bootstrap_pending' or blk_u.startswith('ind:') or blk_u.startswith('bootstrap_pending:') or blk_u.startswith('ind_partial:')):
            det["mode"] = "non_indicator_block"
            return False, "", det
        gate_status = str(((_READINESS.get("gate") or {}).get("status") or "UNKNOWN")).upper().strip()
        pos_status = str(((_READINESS.get("pos") or {}).get("status") or "UNKNOWN")).upper().strip()
        det["gate_status"] = gate_status
        det["pos_status"] = pos_status
        if gate_status == 'FAIL' or pos_status == 'FAIL':
            det["mode"] = "hard_fail_present"
            return False, "", det

        meta = (reqn.get("meta") if isinstance(reqn.get("meta"), dict) else {}) or {}
        need_ind = bool(_need_ind_for_action(reqd, reqn))
        if not need_ind:
            det["mode"] = "need_ind_false"
            return False, "", det

        adx = meta.get("ind_adx")
        rsi = meta.get("ind_rsi")
        ind_reason = str(meta.get("ind_reason") or "")
        used_last_good = bool(meta.get("ind_used_last_good"))
        age_sec = None
        val_ts = None
        if adx is None or rsi is None:
            try:
                adx, rsi, val_ts, age_sec, ind_reason = _ind_require_adx_rsi(coin, time.time(), ttl_sec=float(IND_STALE_SEC_TRADE), allow_force=True)
                meta["ind_adx"] = float(adx)
                meta["ind_rsi"] = float(rsi)
                meta["ind_ts"] = float(time.time())
                meta["ind_val_ts"] = (float(val_ts) if val_ts is not None else None)
                meta["ind_fetch_ts"] = float(time.time())
                meta["ind_age_sec"] = (float(age_sec) if age_sec is not None else None)
                meta["ind_reason"] = str(ind_reason or "")
                meta["ind_used_last_good"] = int(str(ind_reason or "").startswith("last_good:"))
                reqd["meta"] = meta
                reqn["meta"] = meta
                used_last_good = bool(meta.get("ind_used_last_good"))
            except Exception as _e_ind:
                det["mode"] = f"ind_require_fail:{type(_e_ind).__name__}"
                return False, "", det
        try:
            ist = _indicator_meta_state(meta, now_ts=time.time(), ttl_sec=float(IND_STALE_SEC_TRADE))
        except Exception:
            ist = {}
        det["ind_reason"] = str(meta.get("ind_reason") or ind_reason or "")
        det["ind_fresh"] = int(bool(ist.get("fresh")))
        det["ind_used_last_good"] = int(bool(ist.get("used_last_good") or used_last_good))
        det["ind_age_sec"] = ist.get("age_sec")
        if not bool(ist.get("fresh")):
            det["mode"] = "indicator_not_fresh"
            return False, "", det

        action_class = _classify_req_action(reqd, reqn)
        if str(action_class or "").upper() not in ("OPEN", "ADD", MOD_LEGACY_FIX, "SELF_HEAL", "CLOSE", "REDUCE", "RISK_ADD", "RISK_REDUCE"):
            det["mode"] = f"action_class_skip:{action_class}"
            return False, "", det
        det["mode"] = "coin_indicator_fresh"
        return True, ("allow_coin_last_good_under_global_ind_block" if bool(ist.get("used_last_good") or used_last_good) else "allow_coin_fresh_under_global_ind_block"), det
    except Exception as _e:
        det["mode"] = f"exception:{type(_e).__name__}"
        det["exc"] = repr(_e)
        return False, "", det

def _req_is_legacy_fix_like(reqd: dict, mod: str = "", act: str = "") -> bool:
    """识别“修复/补腿/对冲补齐/减风险”类请求，用于全链路插针聚焦。
    注意：这里只做分类，不做放行/风控判断。
    """
    try:
        mod_u = str(mod or (reqd.get("module") if isinstance(reqd, dict) else "") or "").upper()
        at = str(act or (reqd.get("action_type") if isinstance(reqd, dict) else "") or (reqd.get("action") if isinstance(reqd, dict) else "") or "").lower()
        meta = reqd.get("meta") if isinstance(reqd, dict) and isinstance(reqd.get("meta"), dict) else {}
        params = reqd.get("params") if isinstance(reqd, dict) and isinstance(reqd.get("params"), dict) else {}
        if bool(meta.get("safe_legacy_fix")) or bool(meta.get("safe_reduce")) or bool(params.get("safe_legacy_fix")) or bool(params.get("safe_reduce")):
            return True
        if mod_u in (MOD_LEGACY_FIX, "X1", ROLE_LEGACY_FIXER):
            return True
        hay = f"{at} {str(params.get('why') or meta.get('why') or meta.get('reason') or '')}".lower()
        return any(k in hay for k in (TXT_LEGACY_FIX, "fill_missing", "missing_leg", "hedge", "补腿", "修复", "对冲", "balance", "减仓", "reduce", "close", "flatten"))
    except Exception:
        return False

def _pin_legacy_flow(reqd: dict, stage: str, ok: int = 1, reason: str = "", **kv) -> None:
    """旧补腿链路专用插针：保证不因插针影响主流程。"""
    try:
        if not isinstance(reqd, dict):
            return
        mod = str(reqd.get("module") or "").upper()
        act = str(reqd.get("action_type") or reqd.get("action") or "").lower()
        coin = str(reqd.get("coin") or reqd.get("symbol") or reqd.get("asset") or "").upper().strip()
        if not _req_is_legacy_fix_like(reqd, mod=mod, act=act):
            return
        meta = reqd.get("meta") if isinstance(reqd.get("meta"), dict) else {}
        params = reqd.get("params") if isinstance(reqd.get("params"), dict) else {}
        snap = {}
        try:
            snap = _readiness_snapshot_fields()
        except Exception:
            snap = {}
        _pin(mod if mod else MOD_LEGACY_FIX,
             coin=coin, stage=str(stage), ok=int(ok or 0), reason=str(reason or ""),
             act=act,
             plat=str(reqd.get("platform") or reqd.get("plat") or params.get("platform") or params.get("plat") or ""),
             amt=str(reqd.get("amount_u") or reqd.get("amount") or params.get("amount_u") or params.get("amount") or ""),
             ind_rsi=meta.get("ind_rsi"),
             ind_adx=meta.get("ind_adx"),
             ind_age=meta.get("ind_age_sec"),
             ind_reason=str(meta.get("ind_reason") or ""),
             safe_reduce=int(bool(meta.get("safe_reduce") or params.get("safe_reduce"))),
             safe_legacy_fix=int(bool(meta.get("safe_legacy_fix") or params.get("safe_legacy_fix"))),
             trade_enabled=int(bool(snap.get("trade_enabled"))),
             last_block=str(snap.get("last_block_reason") or ""),
             pos_status=(snap.get("pos_status") or {}).get("status"),
             ind_status=(snap.get("ind_status") or {}).get("status"),
             gate_status=(snap.get("gate_status") or {}).get("status"),
             **kv)
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_98', _e)
        pass
def _normalize_req_for_gate(reqd: dict) -> dict:
    try:
        meta = reqd.get("meta") if isinstance(reqd.get("meta"), dict) else {}
    except Exception:
        meta = {}
    try:
        params = reqd.get("params") if isinstance(reqd.get("params"), dict) else {}
    except Exception:
        params = {}
    mod = str(reqd.get("module") or "").upper().strip()
    act = str(reqd.get("action_type") or reqd.get("action") or "").lower().strip()
    coin = str(reqd.get("coin") or reqd.get("symbol") or reqd.get("asset") or "").upper().strip()
    plat = str(reqd.get("platform") or reqd.get("plat") or "").upper().strip()
    side = str(reqd.get("side") or params.get("side") or params.get("pos_side") or params.get("direction") or meta.get("side") or "").upper().strip()
    if ("BUY" in side) or ("LONG" in side) or ("多" in side):
        side = "LONG"
    elif ("SELL" in side) or ("SHORT" in side) or ("空" in side):
        side = "SHORT"
    try:
        intent_u = float(reqd.get("final_amount_u") or reqd.get("intent_u") or reqd.get("usd") or reqd.get("u") or reqd.get("amount_usd") or reqd.get("notional_u") or 0.0)
    except Exception:
        intent_u = 0.0
    _apply_final_amount_contract(reqd, params=params, meta=meta, amount_hint=intent_u)
    return {"mod": mod, "act": act, "coin": coin, "plat": plat, "side": side, "meta": meta, "params": params, "intent_u": intent_u}

def _classify_req_action(reqd: dict, reqn: dict | None = None) -> str:
    reqn = reqn or _normalize_req_for_gate(reqd)
    mod = str(reqn.get("mod") or "")
    act = str(reqn.get("act") or "")
    if mod in ("SYS", "M2") or act in ("refresh", "reconnect", "healthcheck"):
        return "SELF_HEAL"
    if _req_is_safe_reduce_only(reqd) or _is_reduce_action(act):
        return "RISK_REDUCE"
    if _req_is_safe_legacy_fix_min(reqd):
        return MOD_LEGACY_FIX
    meta = reqn.get("meta") if isinstance(reqn.get("meta"), dict) else {}
    if bool((meta or {}).get("safe_legacy_fix") or (meta or {}).get("hard_missing_leg") or (meta or {}).get("missing_leg")):
        return MOD_LEGACY_FIX
    if any(k in act for k in ("legacy_deleted", "fill_leg", "add_leg", "open_leg", "open_pair", "openpair", "fill_missing", "hedge_fill")):
        return MOD_LEGACY_FIX
    return "RISK_ADD"

def _need_ind_for_action(reqd: dict, reqn: dict | None = None) -> bool:
    reqn = reqn or _normalize_req_for_gate(reqd)
    mod = str(reqn.get("mod") or "")
    act = str(reqn.get("act") or "")
    meta = reqn.get("meta") if isinstance(reqn.get("meta"), dict) else {}
    params = reqn.get("params") if isinstance(reqn.get("params"), dict) else {}
    if mod in ("SYS", "M2"):
        return False
    if mod != "M9":
        return False
    action_class = _classify_req_action(reqd, reqn)
    if action_class != "RISK_ADD":
        return False
    if act not in ("increase", "add", "grid_add", "grid_increase", "add_leg", "open_leg", "open_pair"):
        return False
    try:
        is_hard_tp = bool((params or {}).get("hard_tp") or (meta or {}).get("hard_tp") or (meta or {}).get("ind_optional") or (act in ("hard_tp", "tp_hard", "reduce_only_tp", "tp_reduce_only", "m10_hard_tp", "m10_hard_tp_reduce", "m10_hard_tp_reduce_only")))
    except Exception:
        is_hard_tp = False
    if is_hard_tp:
        return False
    try:
        hard_missing = bool((meta or {}).get("hard_missing_leg") or (meta or {}).get("missing_leg") or ((meta or {}).get("state") in ("MISSING_LEG","MISSING_LEG_HARD","MISSING_LEG_BIG")))
        min_hedge_u = float(cfg_gets_runtime(KEY_LEGACY_FIX_MIN_HEDGE_U, "20") or 20.0)
        if hard_missing and abs(float(reqn.get("intent_u") or 0.0) - min_hedge_u) < 1e-6:
            return False
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_99', _e)
        pass
    return True

def _audit_rsi_direction(reqd: dict, reqn: dict | None = None) -> tuple[bool, str]:
    reqn = reqn or _normalize_req_for_gate(reqd)
    mod = str(reqn.get("mod") or "")
    act = str(reqn.get("act") or "")
    if mod != "M9":
        return True, ""
    if _classify_req_action(reqd, reqn) != "RISK_ADD":
        return True, ""
    if act not in ("increase", "add", "grid_add", "grid_increase", "add_leg", "open_leg", "open_pair"):
        return True, ""
    meta = reqn.get("meta") if isinstance(reqn.get("meta"), dict) else {}
    coin = str(reqn.get("coin") or "")
    side = str(reqn.get("side") or "")
    rsi = meta.get("ind_rsi")
    if rsi is None:
        return False, "reject_ind_missing:rsi_none"
    try:
        rv = float(rsi)
    except Exception:
        return False, "reject_ind_missing:rsi_bad"
    if abs(rv - 50.0) < 1e-9:
        return False, "rsi_pivot_block"
    allow = "SHORT" if rv < 50.0 else "LONG"
    if side not in ("LONG", "SHORT"):
        return False, "rsi_side_missing"
    if side != allow:
        try:
            _pin(str(reqn.get("mod") or "RSI_AUDIT"), coin=coin, stage="RSI_FINAL_REJECT", ok=0,
                 reason=f"rsi_side_block:rsi={rv:.2f} allow={allow} req_side={side}",
                 act=str(reqn.get("act") or ""), plat=str(reqn.get("plat") or ""),
                 ind_rsi=rv, ind_adx=meta.get("ind_adx"))
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_100', _e)
            pass
        return False, f"rsi_side_block:{allow}"
    return True, ""

def _audit_amount_mapping(reqd: dict, reqn: dict | None = None) -> tuple[bool, str]:
    reqn = reqn or _normalize_req_for_gate(reqd)
    if _classify_req_action(reqd, reqn) != "RISK_ADD":
        return True, ""
    meta = reqn.get("meta") if isinstance(reqn.get("meta"), dict) else {}
    mod = str(reqn.get("mod") or "").upper().strip()
    if False:
        explicit_u = _coerce_final_amount_u(
            reqn.get("intent_u"),
            reqd.get("final_amount_u"),
            reqd.get("amount_u"),
            reqd.get("amount_usd"),
            reqd.get("usd"),
            reqd.get("amount"),
            reqd.get("u"),
            reqd.get("notional_u"),
            (reqn.get("params") or {}).get("final_amount_u") if isinstance(reqn.get("params"), dict) else None,
            (reqn.get("params") or {}).get("amount_u") if isinstance(reqn.get("params"), dict) else None,
            (reqn.get("params") or {}).get("amount_usd") if isinstance(reqn.get("params"), dict) else None,
            (reqn.get("params") or {}).get("usd") if isinstance(reqn.get("params"), dict) else None,
            (reqn.get("params") or {}).get("amount") if isinstance(reqn.get("params"), dict) else None,
            (meta or {}).get("final_amount_u"),
            (meta or {}).get("amount_u"),
            (meta or {}).get("amount_usd"),
            (meta or {}).get("usd"),
            (meta or {}).get("amount"),
        )
        if explicit_u > 0.0:
            if not (isinstance((meta or {}).get("amt_det"), dict) and int(((meta or {}).get("amt_det") or {}).get("ok", 0)) == 1):
                meta["amt_det"] = {
                    "ok": 1,
                    "reason": "bu1_explicit_amount",
                    "picked": float(explicit_u),
                    "final_u": float(explicit_u),
                    "u": float(explicit_u),
                    "final_source": "bu1_explicit_amount",
                }
                reqd["meta"] = meta
            _apply_final_amount_contract(reqd, params=reqn.get("params"), meta=meta, amount_hint=float(explicit_u))
            return True, ""
        return False, "amount_missing_or_nonpos"
    try:
        hard_missing = bool((meta or {}).get("hard_missing_leg") or (meta or {}).get("missing_leg") or ((meta or {}).get("state") in ("MISSING_LEG","MISSING_LEG_HARD","MISSING_LEG_BIG")))
        min_hedge_u = float(cfg_gets_runtime(KEY_LEGACY_FIX_MIN_HEDGE_U, "20") or 20.0)
        iu = float(reqn.get("intent_u") or 0.0)
        if hard_missing and (iu > 0) and abs(iu - min_hedge_u) < 1e-6:
            if not (isinstance((meta or {}).get("amt_det"), dict) and int(((meta or {}).get("amt_det") or {}).get("ok", 0)) == 1):
                meta["amt_det"] = {"ok": 1, "rule": "min_hedge_fixed", "u": iu}
                reqd["meta"] = meta
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_101', _e)
        pass
    ad = (meta or {}).get("amt_det") if isinstance(meta, dict) else None
    if isinstance(ad, dict) and int(ad.get("ok", 0)) == 1:
        _apply_final_amount_contract(reqd, params=reqn.get("params"), meta=meta, amount_hint=_coerce_final_amount_u(ad.get("final_u"), ad.get("picked"), ad.get("u"), reqn.get("intent_u")))
    if not (isinstance(ad, dict) and int(ad.get("ok", 0)) == 1):
        if not bool((meta or {}).get("selfcheck_silent")):
            try:
                _pin(str(reqn.get("mod") or "AMT_AUDIT"), coin=str(reqn.get("coin") or ""), stage="AMT_DET_REJECT", ok=0,
                     reason="amount_not_mapped", act=str(reqn.get("act") or ""), plat=str(reqn.get("plat") or ""),
                     ind_rsi=(meta or {}).get("ind_rsi"), ind_adx=(meta or {}).get("ind_adx"), amt_det=ad)
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_102', _e)
                pass
        return False, "amount_not_mapped"
    return True, ""

def _allow_b1_first_open_no_position_only(reqn: dict, blk: str) -> tuple[bool, str]:
    mod = str(reqn.get("mod") or "")
