_EXECUTOR_ACTION_AUDIT_SEEN: dict[str, float] = {}

def _executor_action_audit_key(rec: dict | None = None) -> str:
    try:
        obj = rec if isinstance(rec, dict) else {}
        event_id = str(obj.get("event_id") or "").strip()
        if event_id:
            return f"event:{event_id}"
        req_id = str(obj.get("req_id") or "").strip()
        trace_id = str(obj.get("trace_id") or "").strip()
        mod = str(obj.get("req_mod") or obj.get("module") or "").upper().strip()
        act = str(obj.get("req_act") or obj.get("action_type") or obj.get("action") or "").lower().strip()
        coin = str(obj.get("coin") or "").upper().strip()
        plat = str(obj.get("platform") or obj.get("plat") or "").upper().strip()
        reason = str(obj.get("reason") or "").strip()
        if req_id or trace_id:
            return f"req:{mod}|{act}|{coin}|{plat}|{req_id}|{trace_id}|{reason}"
        return f"fallback:{mod}|{act}|{coin}|{plat}|{reason}"
    except Exception:
        return ""

def _executor_action_audit_should_skip(rec: dict | None = None, *, dedup_sec: float = 900.0) -> bool:
    try:
        key = _executor_action_audit_key(rec)
        if not key:
            return False
        nowv = float(time.time())
        try:
            stale_keys = [k for k, ts in list((_EXECUTOR_ACTION_AUDIT_SEEN or {}).items()) if (nowv - float(ts or 0.0)) > float(max(30.0, dedup_sec))]
            for k in stale_keys:
                _EXECUTOR_ACTION_AUDIT_SEEN.pop(k, None)
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_103', _e)
            pass
        prev = float((_EXECUTOR_ACTION_AUDIT_SEEN or {}).get(key, 0.0) or 0.0)
        if prev > 0.0 and (nowv - prev) <= float(max(1.0, dedup_sec)):
            return True
        _EXECUTOR_ACTION_AUDIT_SEEN[key] = nowv
        return False
    except Exception:
        return False

def _executor_action_audit_append(rec: dict | None = None) -> bool:
    try:
        if not isinstance(rec, dict):
            return False
        if _executor_action_audit_should_skip(rec):
            return False
        for _base in (globals().get("LOGS_DIR"), globals().get("OUT_DIR")):
            try:
                if not _base:
                    continue
                fp = os.path.join(str(_base), "executor_actions.jsonl")
                os.makedirs(os.path.dirname(os.path.abspath(fp)) or ".", exist_ok=True)
                with open(fp, "a", encoding="utf-8") as f:
                    f.write(_json_dumps_bot(rec) + "\n")
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_104', _e)
                pass
        return True
    except Exception:
        return False

def _allow_under_block(reqd: dict, reqn: dict | None = None, blk: str = "") -> tuple[bool, str]:
    reqn = reqn or _normalize_req_for_gate(reqd)
    mod = str(reqn.get("mod") or "")
    meta = reqn.get("meta") if isinstance(reqn.get("meta"), dict) else {}
    params = reqn.get("params") if isinstance(reqn.get("params"), dict) else {}
    act = str(reqn.get("act") or "")
    gate_st = "UNKNOWN"
    try:
        gate_st = str((_READINESS.get("gate") or {}).get("status") or "UNKNOWN").upper()
    except Exception:
        gate_st = "UNKNOWN"
    if gate_st == "FAIL":
        return False, ""
    action_class = _classify_req_action(reqd, reqn)
    if action_class == "SELF_HEAL":
        return True, str((BLOCK_ALLOW_MATRIX.get("SELF_HEAL") or {}).get("reason") or "allow_selfheal")
    if mod == "LEGACY_DELETED" and bool((params or {}).get("post_m10_force") or (meta or {}).get("post_m10_force")):
        return True, str((BLOCK_ALLOW_MATRIX.get("STRUCT_BALANCE_POST_M10_FORCE") or {}).get("reason") or "allow_struct_balance_post_m10_force_under_block")
    try:
        is_hard_tp = bool((params or {}).get("hard_tp") or (meta or {}).get("hard_tp") or (meta or {}).get("ind_optional") or (act in ("hard_tp", "tp_hard", "reduce_only_tp", "tp_reduce_only", "m10_hard_tp", "m10_hard_tp_reduce", "m10_hard_tp_reduce_only")))
    except Exception:
        is_hard_tp = False
    if mod == "M10" and is_hard_tp:
        return True, str((BLOCK_ALLOW_MATRIX.get("M10_HARD_TP") or {}).get("reason") or "allow_m10_hard_tp_under_block")
    ok_b1, rsn_b1 = _allow_b1_first_open_no_position_only(reqn, blk)
    if ok_b1:
        return True, str((BLOCK_ALLOW_MATRIX.get("B1_FIRST_OPEN_NO_POSITION") or {}).get("reason") or rsn_b1 or "allow_b1_first_open_no_position_only")
    if _req_is_safe_reduce_only(reqd):
        _rsn = str((BLOCK_ALLOW_MATRIX.get("SAFE_REDUCE_ONLY") or {}).get("reason") or "allow_safe_reduce_only_under_block")
        return True, f"{_rsn}:{blk or 'blocked'}"
    if _req_is_safe_legacy_fix_min(reqd):
        _rsn = str((BLOCK_ALLOW_MATRIX.get("SAFE_LEGFIX_MIN") or {}).get("reason") or "allow_safe_legfix_min_under_block")
        return True, f"{_rsn}:{blk or 'blocked'}"
    return False, ""

def _grid_prepare_layer_identity(meta_any: Any, layer_id: str = "", *, allow_create: bool = False, open_ts: float | None = None) -> tuple[dict, str]:
    meta = dict(meta_any or {}) if isinstance(meta_any, dict) else {}
    lid = str(layer_id or meta.get("layer_id") or "").strip()
    iid = ""
    try:
        iid = _grid_resolve_layer_instance_id(meta, lid, allow_create=bool(allow_create), open_ts=open_ts)
    except Exception as _e:
        _record_swallowed_exception('grid_prepare_layer_identity.resolve', _e, lid)
        iid = ""
    if iid:
        try:
            meta["layer_instance_id"] = str(iid)
            meta["instance_id"] = str(iid)
            if lid:
                meta["layer_id"] = str(lid)
        except Exception as _e:
            _record_swallowed_exception('grid_prepare_layer_identity.meta', _e, lid)
    return meta, str(iid or "")

def _grid_resolve_layer_instance_id(meta_any: Any, layer_id: str = "", *, allow_create: bool = False, open_ts: float | None = None) -> str:
    """统一 layer_instance_id 口径：
    - 真实新开层时只允许生成一次
    - 非开层链路优先透传；若历史链路缺失，只允许从主账本继承，不再读取旧账本补号
    """
    try:
        meta = meta_any if isinstance(meta_any, dict) else {}
    except Exception:
        meta = {}
    try:
        iid = str(meta.get("layer_instance_id") or meta.get("instance_id") or "").strip()
    except Exception:
        iid = ""
    if iid:
        return iid
    try:
        lid = str(layer_id or meta.get("layer_id") or "").strip()
    except Exception:
        lid = str(layer_id or "").strip()
    if not lid:
        return ""

    def _legacy_lookup() -> str:
        try:
            gid = str(meta.get("grid_id") or "").strip()
        except Exception:
            gid = ""
        try:
            if gid and ('GRID_BOOK' in globals()) and (globals().get('GRID_BOOK') is not None) and hasattr(GRID_BOOK, '_find_layer'):
                ly = GRID_BOOK._find_layer(str(gid), str(lid))
                if isinstance(ly, dict):
                    _iid = str(ly.get('layer_instance_id') or ly.get('instance_id') or '').strip()
                    if _iid:
                        return _iid
        except Exception as _e:
            _record_swallowed_exception('grid_resolve_layer_instance_id.grid_book_lookup', _e, lid)
        return ''

    if not allow_create:
        iid = _legacy_lookup()
        if iid:
            try:
                meta['layer_instance_id'] = str(iid)
                meta['instance_id'] = str(iid)
                meta['layer_instance_id_source'] = str(meta.get('layer_instance_id_source') or 'legacy_inherit')
            except Exception:
                pass
            return str(iid)
        return ""
    try:
        ots = float(open_ts if open_ts is not None else time.time())
    except Exception:
        ots = float(time.time())
    iid = f"{lid}#{int(ots * 1000)}"
    try:
        meta["layer_instance_id"] = str(iid)
        meta["instance_id"] = str(iid)
        meta["layer_instance_id_source"] = str(meta.get("layer_instance_id_source") or "created_at_open")
    except Exception:
        pass
    return str(iid)

def _m9_owned_layer_exists(req_any: dict) -> tuple[bool, str, dict]:
    """严格网格所有权校验：M9 decrease 只能平“网格自己开出来的层”。
    单一真相源：只允许 GRID_BOOK 放行；_GRID_LEDGER 只做诊断，不再作为 ownership 放行依据。
    """
    detail = {'grid_id': '', 'layer_id': '', 'layer_instance_id': '', 'owner_src': '', 'state': '', 'reason': '', 'local_owner_src': '', 'local_state': '', 'local_layer_instance_id': ''}
    try:
        if not isinstance(req_any, dict):
            return True, '', detail
        mod = str(req_any.get('module') or '').upper().strip()
        act = str(req_any.get('action_type') or req_any.get('action') or '').lower().strip()
        if mod != 'M9' or act not in ('decrease', 'reduce'):
            return True, '', detail
        params = req_any.get('params') if isinstance(req_any.get('params'), dict) else {}
        meta = req_any.get('meta') if isinstance(req_any.get('meta'), dict) else {}
        gid = str(req_any.get('grid_id') or params.get('grid_id') or meta.get('grid_id') or '').strip()
        lid, _ltag, _lno = _executor_get_layer_info(req_any)
        lid = str(lid or '').strip()
        iid = _grid_resolve_layer_instance_id(meta, lid, allow_create=False)
        if not iid:
            iid = str(req_any.get('layer_instance_id') or params.get('layer_instance_id') or params.get('instance_id') or meta.get('layer_instance_id') or meta.get('instance_id') or '').strip()
        detail['grid_id'] = gid
        detail['layer_id'] = lid
        detail['layer_instance_id'] = iid
        if (not gid) or (not lid):
            detail['reason'] = 'missing_grid_or_layer_id'
            return False, 'reject_m9_decrease_not_owned_layer', detail

        lid = _grid_canonical_layer_id(gid, _lno, lid)
        detail['layer_id'] = lid

        ly = None
        try:
            if ('GRID_BOOK' in globals()) and (globals().get('GRID_BOOK') is not None) and hasattr(GRID_BOOK, '_find_layer'):
                ly = GRID_BOOK._find_layer(str(gid), str(lid))
                if not isinstance(ly, dict) and lid:
                    try:
                        _lno_find = int(_lno or _grid_layer_no(lid) or 0)
                    except Exception:
                        _lno_find = 0
                    if _lno_find > 0:
                        for _cand in list(GRID_BOOK.get_open_layers(str(gid)) or []):
                            try:
                                _clid = _grid_canonical_layer_id(gid, (_cand or {}).get('layer_no'), (_cand or {}).get('layer_id') or '')
                                if _clid == lid:
                                    ly = dict(_cand or {})
                                    break
                            except Exception:
                                continue
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_105', _e)
            ly = None

        if isinstance(ly, dict):
            st = str(ly.get('status') or ly.get('state') or '').upper().strip()
            live_iid = str(ly.get('layer_instance_id') or ly.get('instance_id') or '').strip()
            detail['owner_src'] = 'GRID_BOOK'
            detail['state'] = st
            detail['grid_book_layer_instance_id'] = live_iid
            if iid and live_iid and iid != live_iid:
                detail['reason'] = f'grid_book_instance_mismatch:req={iid},live={live_iid}'
                return False, 'reject_m9_decrease_instance_mismatch', detail
            if st in ('OPEN','ACTIVE','CLOSE_PENDING','PENDING_CLOSE','CLOSING'):
                detail['layer_instance_id'] = str(live_iid or iid or '')
                return True, 'allow_m9_decrease_by_exact_grid_layer', detail
            detail['reason'] = f'grid_layer_not_open:{st.lower() or "unknown"}'
            return False, 'reject_m9_decrease_not_owned_layer', detail

        try:
            if ('_GRID_LEDGER' in globals()) and (globals().get('_GRID_LEDGER') is not None):
                items = ((_GRID_LEDGER._data if hasattr(_GRID_LEDGER, '_data') else {}) or {}).get('items') or []
                for it in items:
                    if not isinstance(it, dict):
                        continue
                    _it_gid = str(it.get('grid_id') or it.get('id') or '').strip()
                    _it_lid = _grid_canonical_layer_id((_it_gid or gid), it.get('layer_no'), it.get('layer_id') or '')
                    if _it_gid != gid or str(_it_lid or '').strip() != lid:
                        continue
                    detail['local_owner_src'] = 'LEGACY_LOCAL_GRID_VIEW'
                    detail['local_state'] = str(it.get('state') or it.get('status') or '').upper().strip()
                    detail['local_layer_instance_id'] = str(it.get('layer_instance_id') or it.get('instance_id') or '').strip()
                    break
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_107', _e)
            pass
        detail['reason'] = 'grid_layer_not_found_in_grid_book'
        return False, 'reject_m9_decrease_not_owned_layer', detail
    except Exception as _e:
        try:
            detail['reason'] = f'ownership_exception:{repr(_e)}'
        except Exception:
            pass
        return False, 'm9_owned_layer_check_exception', detail

def _check_m9_ownership_before_enqueue(req_any: dict) -> tuple[bool, str]:
    try:
        if not isinstance(req_any, dict):
            return True, ""
        mod = str(req_any.get('module') or '').upper()
        act = str(req_any.get('action_type') or req_any.get('action') or '').lower()
        coin = str(req_any.get('coin') or '').upper()
        plat = str(req_any.get('platform') or req_any.get('plat') or '').upper()
        side = str(req_any.get('side') or ((req_any.get('params') or {}).get('side') if isinstance(req_any.get('params'), dict) else '') or ((req_any.get('meta') or {}).get('side') if isinstance(req_any.get('meta'), dict) else '') or '').upper().strip()
        if mod != 'M9' or act not in ('decrease', 'reduce'):
            return True, ""
        req_any['reduce_only'] = True
        if not bool(globals().get('M9_DECREASE_REQUIRE_OWNED', True)):
            return True, ""
        ok_owned, rsn_owned, detail = _m9_owned_layer_exists(req_any)
        if ok_owned:
            return True, rsn_owned
        gid = str((detail or {}).get('grid_id') or '')
        lid = str((detail or {}).get('layer_id') or '')
        reason_detail = str((detail or {}).get('reason') or rsn_owned or 'not_owned_layer')
        try:
            _pin_decision(mod='M9', coin=coin, plat=plat, act=act, side=side, ok=0, reason='reject_m9_decrease_not_owner')
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_109', _e)
            pass
        try:
            _append_jsonl_safe(get_out_path('executor_actions.jsonl'), {
                'ts': float(time.time()), 'event': 'reject', 'module': 'M9', 'coin': coin,
                'platform': plat, 'action_type': str(req_any.get('action_type') or ''),
                'action': str(req_any.get('action') or ''), 'side': side,
                'reason': 'M9_DECREASE_REQUIRE_OWNED_LAYER', 'detail': reason_detail,
                'grid_id': gid, 'layer_id': lid,
            })
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_110', _e)
            pass
        _reject_code = str(rsn_owned or 'reject_m9_decrease_not_owner').strip() or 'reject_m9_decrease_not_owner'
        return False, _reject_code
    except Exception as _e:
        try:
            _log_exc_level(mod='M9', stage='OWNERSHIP_PRECHECK', level='B', e=_e)
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_111', _e)
            pass
        return False, 'm9_ownership_check_exception'

def _m9_recent_same_layer_pending_or_uncertain(req_any: dict, *, max_age_sec: int = 900) -> tuple[bool, dict]:
    """同 grid/layer 若近期已出现 pending_unconfirmed / uncertain_success / 已有成交证据但未落活层，硬阻断再次开同层。"""
    try:
        if not isinstance(req_any, dict):
            return False, {}
        mod = str(req_any.get('module') or '').upper().strip()
        act = str(req_any.get('action_type') or req_any.get('action') or '').lower().strip()
        if mod != 'M9' or act not in ('increase', 'add', 'open'):
            return False, {}
        params = req_any.get('params') if isinstance(req_any.get('params'), dict) else {}
        meta = req_any.get('meta') if isinstance(req_any.get('meta'), dict) else {}
        gid = str(req_any.get('grid_id') or params.get('grid_id') or meta.get('grid_id') or '').strip()
        lid, _ltag, lno = _executor_get_layer_info(req_any)
        lid = _grid_canonical_layer_id(gid, lno, lid)
        try:
            lno = int(lno or _grid_layer_no(lid) or 0)
        except Exception:
            lno = int(_grid_layer_no(lid) or 0)
        coin = str(req_any.get('coin') or '').upper().strip()
        plat = str(req_any.get('platform') or req_any.get('plat') or '').upper().strip()
        side = str(req_any.get('side') or params.get('side') or meta.get('side') or '').upper().strip()
        if not gid or lno <= 0:
            return False, {}
        now_ts = float(time.time())
        fps = [
            os.path.join(str(OUT_DIR), 'executor_results.jsonl'),
            os.path.join(str(LOGS_DIR), 'executor_results.jsonl'),
        ]
        seen = set()
        for fp in fps:
            try:
                fp = os.path.abspath(fp)
                if fp in seen or (not os.path.exists(fp)):
                    continue
                seen.add(fp)
                with open(fp, 'r', encoding='utf-8') as f:
                    lines = f.readlines()[-3000:]
            except Exception:
                continue
            for line in reversed(lines):
                try:
                    row = json.loads(line)
                except Exception:
                    continue
                if not isinstance(row, dict):
                    continue
                ts = float(row.get('ts') or 0.0)
                if ts > 0 and max_age_sec > 0 and (now_ts - ts) > float(max_age_sec):
                    continue
                rr = row
                req = rr.get('req') if isinstance(rr.get('req'), dict) else {}
                req_meta = req.get('meta') if isinstance(req.get('meta'), dict) else {}
                det = rr.get('det') if isinstance(rr.get('det'), dict) else {}
                det_meta = det.get('meta') if isinstance(det.get('meta'), dict) else {}
                rmod = str(req.get('module') or rr.get('module') or '').upper().strip()
                ract = str(req.get('action_type') or req.get('action') or rr.get('action_type') or '').lower().strip()
                if rmod != 'M9' or ract not in ('increase', 'add', 'open'):
                    continue
                rgid = str(req.get('grid_id') or req_meta.get('grid_id') or det.get('grid_id') or det_meta.get('grid_id') or '').strip()
                rlid, _rtag, rlno = _executor_get_layer_info(req if req else rr)
                rlid = _grid_canonical_layer_id(rgid, rlno, rlid)
                try:
                    rlno = int(rlno or _grid_layer_no(rlid) or 0)
                except Exception:
                    rlno = int(_grid_layer_no(rlid) or 0)
                if rgid != gid or rlno != lno:
                    continue
                rcoin = str(req.get('coin') or rr.get('coin') or '').upper().strip()
                rplat = str(req.get('platform') or rr.get('platform') or '').upper().strip()
                rside = str(req.get('side') or req_meta.get('side') or rr.get('side') or '').upper().strip()
                if coin and rcoin and rcoin != coin:
                    continue
                if plat and rplat and rplat != plat:
                    continue
                if side and rside and rside != side:
                    continue
                post_state = str(rr.get('postcheck_state') or req_meta.get('postcheck_state') or '').lower().strip()
                post_reason = str(rr.get('postcheck_reason') or rr.get('reason') or '').lower().strip()
                pending = bool(rr.get('pending')) or bool(req_meta.get('pending_unconfirmed'))
                fill_seen = bool(rr.get('fill_confirmed')) or bool(rr.get('verified')) or bool(_result_has_fill_evidence(rr))
                uncertain = post_state in ('uncertain_success', 'pending_confirm', 'submitted_pending_confirm', 'submitted_unchecked', 'fill_seen_pending_confirm') or 'pending_unconfirmed' in post_reason or 'receipt_timeout_pending_unconfirmed' in post_reason or 'uncertain' in post_reason
                if pending or uncertain or fill_seen:
                    return True, {
                        'grid_id': gid,
                        'layer_id': lid,
                        'layer_no': lno,
                        'reason': 'reject_m9_open_duplicate_layer_pending_or_uncertain',
                        'source_fp': fp,
                        'source_ts': ts,
                        'matched_reason': str(rr.get('reason') or ''),
                        'matched_postcheck_state': post_state,
                        'matched_fill_seen': int(fill_seen),
                        'matched_pending': int(pending),
                    }
        return False, {}
    except Exception:
        return False, {}

def _check_m9_duplicate_open_before_enqueue(req_any: dict) -> tuple[bool, str]:
    """M9 increase 前置硬拒绝：同腿同层号只允许一个活层；存在 CLOSE_PENDING 时先清旧层。"""
    try:
        if not isinstance(req_any, dict):
            return True, ''
        mod = str(req_any.get('module') or '').upper().strip()
        act = str(req_any.get('action_type') or req_any.get('action') or '').lower().strip()
        if mod != 'M9' or act not in ('increase', 'add', 'open'):
            return True, ''
        params = req_any.get('params') if isinstance(req_any.get('params'), dict) else {}
        meta = req_any.get('meta') if isinstance(req_any.get('meta'), dict) else {}
        gid = str(req_any.get('grid_id') or params.get('grid_id') or meta.get('grid_id') or '').strip()
        lid, _ltag, lno = _executor_get_layer_info(req_any)
        lid = _grid_canonical_layer_id(gid, lno, lid)
        try:
            lno = int(lno or _grid_layer_no(lid) or 0)
        except Exception:
            lno = int(_grid_layer_no(lid) or 0)
        if not gid:
            return True, ''
        if _grid_has_close_pending_layer(gid):
            return False, 'reject_m9_open_close_pending_exists'
        if lno > 0 and _grid_has_alive_layer_no(gid, lno, include_close_pending=True):
            return False, 'reject_m9_open_duplicate_layer_no_alive'
        if lno > 0:
            _dup_pending, _dup_pending_detail = _grid_pending_open_has_same_layer(req_any, include_confirmed=True)
            if _dup_pending:
                try:
                    if isinstance(meta, dict):
                        meta.update(dict(_dup_pending_detail or {}))
                        req_any['meta'] = meta
                except Exception:
                    pass
                return False, str((_dup_pending_detail or {}).get('reason') or 'reject_m9_open_duplicate_layer_pending_exists')
            _dup_recent, _dup_detail = _m9_recent_same_layer_pending_or_uncertain(req_any)
            if _dup_recent:
                try:
                    if isinstance(meta, dict):
                        meta.update(dict(_dup_detail or {}))
                        req_any['meta'] = meta
                except Exception:
                    pass
                return False, str((_dup_detail or {}).get('reason') or 'reject_m9_open_duplicate_layer_pending_or_uncertain')
        return True, ''
    except Exception:
        return False, 'm9_duplicate_open_check_exception'

def _check_m9_duplicate_close_before_enqueue(req_any: dict) -> tuple[bool, str]:
    """M9 源模块前置硬拒绝：同层重复平 / pending 锁定 / 已关闭层，禁止再次入队。"""
    try:
        if not isinstance(req_any, dict):
            return True, ""
        mod = str(req_any.get('module') or '').upper().strip()
        act = str(req_any.get('action_type') or req_any.get('action') or '').lower().strip()
        if mod != 'M9' or act not in ('decrease', 'reduce'):
            return True, ""
        meta = req_any.get('meta') if isinstance(req_any.get('meta'), dict) else {}
        params = req_any.get('params') if isinstance(req_any.get('params'), dict) else {}
        gid = str(req_any.get('grid_id') or params.get('grid_id') or meta.get('grid_id') or '').strip()
        lid, _ltag, _lno = _executor_get_layer_info(req_any)
        if (not gid) or (not lid) or ('GRID_BOOK' not in globals()) or (globals().get('GRID_BOOK') is None) or (not hasattr(GRID_BOOK, '_find_layer')):
            return True, ""
        ly = GRID_BOOK._find_layer(str(gid), str(lid))
        if not isinstance(ly, dict):
            return True, ""
        st = str(ly.get('status') or '').upper().strip()
        if st == 'CLOSED':
            try:
                meta['duplicate_close_skip'] = 1
                meta['duplicate_close_reason'] = 'layer_already_closed'
                meta['layer_status'] = st
                req_any['meta'] = meta
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_112', _e)
                pass
            try:
                _append_jsonl_safe(get_out_path('executor_actions.jsonl'), {
                    'ts': float(time.time()), 'event': 'reject', 'module': 'M9', 'coin': str(req_any.get('coin') or '').upper(),
                    'platform': str(req_any.get('platform') or req_any.get('plat') or '').upper(),
                    'action_type': str(req_any.get('action_type') or ''), 'action': str(req_any.get('action') or ''),
                    'side': str(req_any.get('side') or params.get('side') or meta.get('side') or '').upper(),
                    'reason': 'grid_duplicate_tp_reject:layer_already_closed', 'grid_id': gid, 'layer_id': lid
                })
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_113', _e)
                pass
            return False, 'grid_duplicate_tp_reject:layer_already_closed'
        if bool(ly.get('close_pending') or 0):
            try:
                meta['duplicate_close_skip'] = 1
                meta['duplicate_close_reason'] = 'layer_close_pending'
                meta['layer_status'] = st or 'OPEN'
                req_any['meta'] = meta
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_114', _e)
                pass
            try:
                _append_jsonl_safe(get_out_path('executor_actions.jsonl'), {
                    'ts': float(time.time()), 'event': 'reject', 'module': 'M9', 'coin': str(req_any.get('coin') or '').upper(),
                    'platform': str(req_any.get('platform') or req_any.get('plat') or '').upper(),
                    'action_type': str(req_any.get('action_type') or ''), 'action': str(req_any.get('action') or ''),
                    'side': str(req_any.get('side') or params.get('side') or meta.get('side') or '').upper(),
                    'reason': 'grid_duplicate_tp_reject:layer_close_pending', 'grid_id': gid, 'layer_id': lid,
                    'close_pending_req_id': str(ly.get('close_pending_req_id') or ''),
                    'close_pending_trace_id': str(ly.get('close_pending_trace_id') or ''),
                })
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_115', _e)
                pass
            return False, 'grid_duplicate_tp_reject:layer_close_pending'
        if st and st != 'OPEN':
            try:
                meta['duplicate_close_skip'] = 1
                meta['duplicate_close_reason'] = f'layer_not_open:{st.lower()}'
                meta['layer_status'] = st
                req_any['meta'] = meta
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_116', _e)
                pass
            return False, f'grid_duplicate_tp_reject:layer_not_open:{st.lower()}'
        return True, ""
    except Exception as _e:
        try:
            _log_exc_level(mod='M9', stage='DUPLICATE_CLOSE_PRECHECK', level='B', e=_e)
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_117', _e)
            pass
        return False, 'grid_duplicate_tp_precheck_exception'


def _m9_book_can_emit_close_req(req_any: dict, *, allow_close_pending: bool = False) -> tuple[bool, str, dict]:
    """M9 平仓生成前主闸门：只能依据 GRID_BOOK 当前层状态决定是否允许生成/提交平仓请求。
    用户口径：上一轮记账后，下一轮必须重新看账本；层已平就绝不能再生成平这层的请求。"""
    detail = {'grid_id': '', 'layer_id': '', 'layer_status': '', 'managed_by_grid': False, 'can_tp_close': False, 'owner_chain': '', 'reason': ''}
    try:
        if not isinstance(req_any, dict):
            return False, 'm9_book_gate_bad_req', detail
        mod = str(req_any.get('module') or '').upper().strip()
        act = str(req_any.get('action_type') or req_any.get('action') or '').lower().strip()
        if mod != 'M9' or act not in ('decrease', 'reduce'):
            return True, 'not_m9_decrease', detail
        meta = req_any.get('meta') if isinstance(req_any.get('meta'), dict) else {}
        params = req_any.get('params') if isinstance(req_any.get('params'), dict) else {}
        gid = str(req_any.get('grid_id') or params.get('grid_id') or meta.get('grid_id') or '').strip()
        lid, _ltag, _lno = _executor_get_layer_info(req_any)
        detail['grid_id'] = str(gid)
        detail['layer_id'] = str(lid or '')
        if (not gid) or (not lid):
            detail['reason'] = 'missing_grid_or_layer_id'
            return False, 'm9_book_gate_missing_grid_or_layer_id', detail
        if ('GRID_BOOK' not in globals()) or (globals().get('GRID_BOOK') is None) or (not hasattr(GRID_BOOK, '_find_layer')):
            detail['reason'] = 'grid_book_unavailable'
            return False, 'm9_book_gate_grid_book_unavailable', detail
        ly = GRID_BOOK._find_layer(str(gid), str(lid))
        if not isinstance(ly, dict):
            detail['reason'] = 'layer_not_found_in_grid_book'
            return False, 'm9_book_gate_layer_not_found', detail
        st = str(ly.get('status') or ly.get('state') or '').upper().strip()
        detail['layer_status'] = st
        _flags = _m9_layer_management_flags(ly)
        detail['managed_by_grid'] = bool(_flags.get('managed_by_grid'))
        detail['can_tp_close'] = bool(_flags.get('can_tp_close'))
        detail['owner_chain'] = str(_flags.get('owner_chain') or '')
        if st not in ('OPEN', 'ACTIVE'):
            detail['reason'] = f'layer_not_open:{st.lower() or "unknown"}'
            return False, f'm9_book_gate_layer_not_open:{st.lower() or "unknown"}', detail
        if bool(ly.get('close_pending') or 0) and (not allow_close_pending):
            detail['reason'] = 'layer_close_pending'
            return False, 'm9_book_gate_layer_close_pending', detail
        if not bool(_flags.get('managed_by_grid')):
            detail['reason'] = 'layer_not_managed_by_grid'
            return False, 'm9_book_gate_layer_not_managed_by_grid', detail
        if not bool(_flags.get('can_tp_close')):
            detail['reason'] = 'layer_can_tp_close_false'
            return False, 'm9_book_gate_layer_can_tp_close_false', detail
        if str(_flags.get('owner_chain') or '') != 'M9_SINGLE_CHAIN':
            detail['reason'] = 'owner_chain_not_m9_single_chain'
            return False, 'm9_book_gate_owner_chain_invalid', detail
        detail['reason'] = 'ok'
        return True, 'ok', detail
    except Exception as _e:
        try:
            _log_exc_level(mod='M9', stage='BOOK_CLOSE_GATE', level='B', e=_e)
        except Exception:
            pass
        detail['reason'] = 'book_gate_exception'
        return False, 'm9_book_gate_exception', detail

def _readiness_verdict(reqd: dict) -> dict:
    """统一裁决结果：所有交易请求先归一成结构化 verdict，再决定是否允许入队。"""
    verdict = {
        "allow": False,
        "reason_code": "readiness_init",
        "gate_stage": "INIT",
        "action_class": "UNKNOWN",
        "mod": "",
        "coin": "",
        "plat": "",
        "act": "",
        "need_ind": False,
        "ind_healed": False,
        "details": {},
    }
    try:
        if not isinstance(reqd, dict):
            verdict.update({"reason_code": "req_not_dict", "gate_stage": "REQ_VALIDATE"})
            return verdict
        _gate_heartbeat_touch("readiness_verdict", "enter", req=reqd)
        reqn = _normalize_req_for_gate(reqd)
        mod = str(reqn.get("mod") or "")
        coin = str(reqn.get("coin") or "")
        plat = str(reqn.get("plat") or "")
        act = str(reqn.get("act") or "")
        meta = reqn.get("meta") if isinstance(reqn.get("meta"), dict) else {}
        params = reqn.get("params") if isinstance(reqn.get("params"), dict) else {}
        need_ind = _need_ind_for_action(reqd, reqn)
        action_class = _classify_req_action(reqd, reqn)
        verdict.update({"mod": mod, "coin": coin, "plat": plat, "act": act, "need_ind": bool(need_ind), "action_class": action_class})
        try:
            is_hard_tp = bool((params or {}).get("hard_tp") or (meta or {}).get("hard_tp") or (meta or {}).get("ind_optional") or (act in ("hard_tp", "tp_hard", "reduce_only_tp", "tp_reduce_only", "m10_hard_tp", "m10_hard_tp_reduce", "m10_hard_tp_reduce_only")))
        except Exception:
            is_hard_tp = False
        if mod == "M10" and is_hard_tp:
            meta["ind_optional"] = True
            meta["hard_tp"] = True
            reqd["meta"] = meta
            reqn["meta"] = meta
        ind_healed = False
        if need_ind:
            if (meta.get("ind_rsi") is None) or (meta.get("ind_adx") is None):
                if not coin:
                    verdict.update({"reason_code": "reject_ind_missing:bad_coin", "gate_stage": "IND_REQUIRE", "details": {"bad_coin": 1}})
                    return verdict
                try:
                    adx, rsi, ts, age, rsn = _ind_require_adx_rsi(coin, time.time(), ttl_sec=float(IND_STALE_SEC_TRADE), allow_force=True)
                    meta["ind_rsi"] = float(rsi)
                    meta["ind_adx"] = float(adx)
                    meta["ind_ts"] = float(time.time())
                    meta["ind_val_ts"] = (float(ts) if ts is not None else None)
                    meta["ind_fetch_ts"] = float(time.time())
                    meta["ind_age_sec"] = (float(age) if age is not None else None)
                    meta["ind_reason"] = str(rsn)
                    meta["ind_used_last_good"] = int(str(rsn or "").startswith("last_good:"))
                    meta["ind_healed"] = True
                    reqd["meta"] = meta
                    reqn["meta"] = meta
                    ind_healed = True
                except Exception as _e:
                    try:
                        _go_baocuo_write({"ts": now_ts(), "mod": str(mod), "coin": str(coin), "stage": "IND_REQUIRED_MISSING", "ok": 0, "reason": f"{type(_e).__name__}:{str(_e)[:160]}"})
                    except Exception as _e:
                        _record_swallowed_exception('except_pass_line_118', _e)
                        pass
                    verdict.update({"reason_code": "reject_ind_missing", "gate_stage": "IND_REQUIRE", "details": {"exc": repr(_e)}})
                    return verdict
            try:
                _ist0 = _indicator_meta_state(meta, now_ts=time.time(), ttl_sec=float(IND_STALE_SEC_TRADE))
                if coin and ((not bool(_ist0.get("fresh"))) or bool(_ist0.get("used_last_good"))):
                    adx, rsi, ts, age, rsn = _ind_require_adx_rsi(coin, time.time(), ttl_sec=float(IND_STALE_SEC_TRADE), allow_force=True)
                    meta["ind_rsi"] = float(rsi)
                    meta["ind_adx"] = float(adx)
                    meta["ind_ts"] = float(time.time())
                    meta["ind_val_ts"] = (float(ts) if ts is not None else None)
                    meta["ind_fetch_ts"] = float(time.time())
                    meta["ind_age_sec"] = (float(age) if age is not None else None)
                    meta["ind_reason"] = str(rsn)
                    meta["ind_used_last_good"] = int(str(rsn or "").startswith("last_good:"))
                    meta["ind_healed"] = True
                    reqd["meta"] = meta
                    reqn["meta"] = meta
                    ind_healed = True
                _ist1 = _indicator_meta_state(meta, now_ts=time.time(), ttl_sec=float(IND_STALE_SEC_TRADE))
                _pin_ind_signature_unified(reqd, stage="READINESS_IND_FRESHNESS", ok=1 if bool(_ist1.get("fresh")) else 0, reason=("used_last_good" if bool(_ist1.get("used_last_good")) else ("fresh" if bool(_ist1.get("fresh")) else "stale")))
                if not bool(_ist1.get("fresh")):
                    if _req_is_protective_or_risk_reducing(reqd):
                        try:
                            verdict.setdefault('details', {}).update({"ind_freshness_bypass": "protective_or_reduce", "age_sec": _ist1.get("age_sec"), "val_ts": _ist1.get("val_ts"), "fetch_ts": _ist1.get("fetch_ts")})
                        except Exception as _e:
                            _record_swallowed_exception('except_pass_line_119', _e)
                            pass
                    else:
                        verdict.update({"reason_code": "reject_ind_stale", "gate_stage": "IND_FRESHNESS", "details": {"age_sec": _ist1.get("age_sec"), "val_ts": _ist1.get("val_ts"), "fetch_ts": _ist1.get("fetch_ts")}})
                        return verdict
            except Exception as _e_ind_refresh:
                verdict.update({"reason_code": "reject_ind_stale", "gate_stage": "IND_FRESHNESS", "details": {"exc": repr(_e_ind_refresh)}})
                return verdict

        verdict["ind_healed"] = bool(ind_healed)
        ok_dir, rsn_dir = _audit_rsi_direction(reqd, reqn)
        if not ok_dir:
            verdict.update({"reason_code": str(rsn_dir or "rsi_dir_reject"), "gate_stage": "RSI_FINAL_AUDIT"})
            return verdict
        if _req_is_protective_or_risk_reducing(reqd):
            try:
                verdict.setdefault('details', {})['protective_amt_bypass'] = True
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_120', _e)
                pass
            ok_amt, rsn_amt = True, ''
        else:
            ok_amt, rsn_amt = _audit_amount_mapping(reqd, reqn)
        if not ok_amt:
            verdict.update({"reason_code": str(rsn_amt or "amount_not_mapped"), "gate_stage": "AMT_DET_HARD_AUDIT"})
            return verdict
        if bool(_READINESS.get("trade_enabled", False)):
            _gate_heartbeat_touch("readiness_verdict", "allow_trade_enabled", req=reqd)
            verdict.update({"allow": True, "reason_code": "allow_trade_enabled", "gate_stage": "READINESS_OK"})
            return verdict
        blk = _readiness_block_reason()
        ok_coin_blk, rsn_coin_blk, det_coin_blk = _readiness_coin_individual_allow(reqd, reqn, blk)
        if ok_coin_blk:
            try:
                verdict["details"]["coin_block_allow"] = dict(det_coin_blk or {})
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_121', _e)
                pass
            _gate_heartbeat_touch("readiness_verdict", str(rsn_coin_blk or "allow_coin_under_block"), req=reqd)
            verdict.update({"allow": True, "reason_code": str(rsn_coin_blk or "allow_coin_under_block"), "gate_stage": "COIN_BLOCK_ALLOW"})
            return verdict
        ok_blk, rsn_blk = _allow_under_block(reqd, reqn, blk)
        if ok_blk:
            _gate_heartbeat_touch("readiness_verdict", str(rsn_blk or "allow_under_block"), req=reqd)
            verdict.update({"allow": True, "reason_code": str(rsn_blk or "allow_under_block"), "gate_stage": "BLOCK_ALLOW"})
            return verdict
        _gate_heartbeat_touch("readiness_verdict", str(blk or "blocked"), req=reqd)
        verdict.update({"reason_code": str(blk or "blocked"), "gate_stage": "READINESS_BLOCK"})
        return verdict
    except Exception as _e:
        _gate_heartbeat_touch("readiness_verdict", f"exception:{type(_e).__name__}", req=reqd)
        verdict.update({"allow": False, "reason_code": "readiness_exception", "gate_stage": "EXCEPTION", "details": {"exc": repr(_e)}})
        return verdict

def _readiness_allow_trade_for_req(reqd: dict) -> tuple[bool, str]:
    """兼容旧调用：内部统一走 _readiness_verdict，外部仍返回 (allow, reason_code)。"""
    try:
        verdict = _readiness_verdict(reqd)
        ok = bool((verdict or {}).get("allow", False))
        reason = str((verdict or {}).get("reason_code") or ("" if ok else "blocked"))
        try:
            if isinstance(reqd, dict):
                meta = reqd.get("meta") if isinstance(reqd.get("meta"), dict) else {}
                meta["gate_reason_code"] = reason
                meta["action_class"] = str((verdict or {}).get("action_class") or "")
                meta["gate_stage"] = str((verdict or {}).get("gate_stage") or "")
                meta["need_ind"] = int(bool((verdict or {}).get("need_ind", False)))
                meta["ind_healed"] = int(bool((verdict or {}).get("ind_healed", False)))
                reqd["meta"] = meta
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_122', _e)
            pass
        try:
            if not ok:
                _pin_legacy_flow(reqd, stage="LEGACY_GUARD_REJECT", ok=0, reason=reason, gate_stage=str((verdict or {}).get("gate_stage") or ""), action_class=str((verdict or {}).get("action_class") or ""))
            else:
                _pin_legacy_flow(reqd, stage="LEGACY_GUARD_ALLOW", ok=1, reason=reason, gate_stage=str((verdict or {}).get("gate_stage") or ""), action_class=str((verdict or {}).get("action_class") or ""))
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_123', _e)
            pass
        return ok, reason
    except Exception:
        try:
            _pin_legacy_flow(reqd, stage="LEGACY_GUARD_REJECT", ok=0, reason="readiness_exception")
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_124', _e)
            pass
        return False, "readiness_exception"

_SAFE_REDUCE_ONLY_ACTION_KW = (
    "close", "reduce", "decrease", "flatten", "take_profit", "tp", "tp_", "stop_profit", "全平", "止盈", "减仓"
)
_SAFE_LEGFIX_ACTION_KW = (
    "fill_missing", "missing_leg", "hedge_fill", "add_leg", "fill_leg", "补腿", "修复", "legacy_deleted", "balance", "legacy_deleted"
)

def _req_has_reduce_step_intent(reqd: dict) -> bool:
    """父请求动作名不够准时，继续从 steps/legs 里识别是否本质是减仓/平仓。"""
    try:
        if not isinstance(reqd, dict):
            return False
        meta = reqd.get("meta") if isinstance(reqd.get("meta"), dict) else {}
        params = reqd.get("params") if isinstance(reqd.get("params"), dict) else {}
        extras = meta.get('extras') if isinstance(meta.get('extras'), dict) else {}

        def _iter_step_lists() -> list:
            out = []
            for holder in (params, meta, extras):
                if not isinstance(holder, dict):
                    continue
                for key in ('steps', 'legs'):
                    rows = holder.get(key)
                    if isinstance(rows, list) and rows:
                        out.append(list(rows))
            return out

        def _step_is_reduce(step: Any) -> bool:
            if not isinstance(step, dict):
                return False
            bits = [
                step.get('action'), step.get('action_type'), step.get('kind'), step.get('mode'),
                step.get('reason'), step.get('tag'), step.get('label'),
            ]
            hay = ' '.join(str(x or '') for x in bits).lower()
            return any(k in hay for k in _SAFE_REDUCE_ONLY_ACTION_KW)

        return any(_step_is_reduce(st) for rows in _iter_step_lists() for st in rows)
    except Exception:
        return False

def _req_is_safe_reduce_only(reqd: dict) -> bool:
    try:
        if not isinstance(reqd, dict):
            return False
        meta = reqd.get("meta") if isinstance(reqd.get("meta"), dict) else {}
        params = reqd.get("params") if isinstance(reqd.get("params"), dict) else {}
        if bool(meta.get("safe_reduce_only")) or bool(params.get("safe_reduce_only")):
            return True
        if bool(meta.get("reduce_only")) or bool(params.get("reduce_only")) or bool(reqd.get("reduce_only")):
            return True
        at = str(reqd.get("action_type") or reqd.get("action") or "").lower()
        why = ""
        try:
            why = str(params.get("why") or meta.get("why") or meta.get("reason") or "")
        except Exception:
            why = ""
        hay = f"{at} {why}".lower()
        if any(k in hay for k in _SAFE_REDUCE_ONLY_ACTION_KW):
            return True
        if _req_has_reduce_step_intent(reqd):
            return True
        return False
    except Exception:
        return False

def _req_is_safe_legacy_fix_min(reqd: dict) -> bool:
    """仅允许缺腿最小对冲腿穿透（默认 20U）。"""
    try:
        if not isinstance(reqd, dict):
            return False
        meta = reqd.get("meta") if isinstance(reqd.get("meta"), dict) else {}
        params = reqd.get("params") if isinstance(reqd.get("params"), dict) else {}
        if bool(meta.get("safe_legacy_fix_min")) or bool(params.get("safe_legacy_fix_min")):
            return True
        at = str(reqd.get("action_type") or reqd.get("action") or "").lower()
        if not any(k in at for k in ("add_leg", "fill_leg", "open_leg", "fill_missing", "legacy_deleted", "legacy_deleted")):
            return False
        hard_missing = bool(meta.get("hard_missing_leg") or meta.get("missing_leg") or (meta.get("state") in ("MISSING_LEG","MISSING_LEG_HARD","MISSING_LEG_BIG")) or (params.get("state") in ("MISSING_LEG","MISSING_LEG_HARD","MISSING_LEG_BIG")))
        if not hard_missing:
            return False
        iu = float(reqd.get("intent_u") or reqd.get("usd") or reqd.get("u") or params.get("usd") or 0.0)
        min_u = float(cfg_gets_runtime(KEY_LEGACY_FIX_MIN_HEDGE_U, "20") or 20.0)
        if iu <= 0:
            return False
        if abs(iu - min_u) > 1e-6:
            return False
        return True
    except Exception:
        return False

def _req_is_safe_reduce(reqd: dict) -> bool:
    return bool(_req_is_safe_reduce_only(reqd) or _req_is_safe_legacy_fix_min(reqd))

class _UiDeadError(RuntimeError):
    def __init__(self, where: str, detail: str = "") -> None:
        super().__init__(f"UI_DEAD|{where}|{detail}")
        self.where = str(where or "")
        self.detail = str(detail or "")

class _UiLinkError(RuntimeError):
    """UI 链接/导航类错误（可恢复）：DNS/超时/连接重置/导航失败/被拦截等。
    设计目标：不允许被 EXC_PASS 吞掉后继续跑“假扫描/假决策”；必须触发刷新/重建/重启链路。
    """
    def __init__(self, where: str, detail: str = "") -> None:
        super().__init__(f"UI_LINK|{where}|{detail}")
        self.where = str(where or "")
        self.detail = str(detail or "")

class _UiRecoverTimeoutError(_UiLinkError):
    """UI 恢复链超时：用于把“页面恢复磨死 worker”快速转成明确失败。"""
    def __init__(self, where: str, detail: str = "") -> None:
        super().__init__(where, f"UI_RECOVER_TIMEOUT|{detail}")

_UI_LINK_ERR_HITS: int = 0
_UI_LINK_ERR_LAST_TS: float = 0.0
_UI_LINK_ERR_LAST: str = ""

def _is_link_error_exc(e: Exception) -> bool:
    """判断是否属于“链接/导航/网络”类错误。

    关键修复：
    - 不能把普通 locator/text_content 超时当成 UI_LINK（否则会误触发 RESTARTING）
    - 只有“网络/导航/协议/连接”语义的 timeout 才算 UI_LINK
    """
    try:
        msg = str(e) or ""
    except Exception:
        msg = ""
    try:
        name = getattr(e, "__class__", type(e)).__name__ or ""
    except Exception:
        name = ""
    s = (name + " " + msg).lower()

    deny_keys = [
        "locator.inner_text", "locator.text_content", "locator.count", "locator.wait_for",
        "locator(" , "element is not attached", "strict mode violation",
        "waiting for selector", "waiting for locator", "text_content", "inner_text",
        "timeout 1500ms exceeded", "timeout 1200ms exceeded", "timeout 1000ms exceeded",
        "timeout 800ms exceeded", "timeout 500ms exceeded",
    ]
    if any(k in s for k in deny_keys):
        return False

    hard_keys = [
        "net::err_", "err_name_not_resolved", "err_connection_reset", "err_connection_timed_out",
        "err_internet_disconnected", "err_ssl", "err_cert", "navigation", "protocol error",
        "failed to fetch", "dns", "socket", "connection refused", "temporarily unavailable",
        "name resolution", "tls", "ssl", "access denied", "forbidden",
        "browser disconnected", "target crashed", "websocket", "connection closed",
    ]
    if any(k in s for k in hard_keys):
        return True

    if ("timeout" in s or "timed out" in s):
        timeout_ctx = [
            "goto(", "page.goto", "navigation", "wait_for_url", "wait_for_load_state",
            "request", "response", "fetch", "network", "socket", "connect", "cdp",
        ]
        if any(k in s for k in timeout_ctx):
            return True
        return False

    if ("429" in s) or ("too many requests" in s):
        return True
    if ("403" in s) and ("locator" not in s):
        return True
    return False

def _ui_link_err_hit(where: str, e: Exception) -> None:
    global _UI_LINK_ERR_HITS, _UI_LINK_ERR_LAST_TS, _UI_LINK_ERR_LAST
    try:
        _UI_LINK_ERR_HITS = int(_UI_LINK_ERR_HITS) + 1
    except Exception:
        _UI_LINK_ERR_HITS = 1
    try:
        _UI_LINK_ERR_LAST_TS = float(time.time())
    except Exception:
        _UI_LINK_ERR_LAST_TS = 0.0
    try:
        _UI_LINK_ERR_LAST = f"{where}|{repr(e)}"
    except Exception:
        _UI_LINK_ERR_LAST = f"{where}|UI_LINK_ERR"

def _is_target_closed_exc(e: Exception) -> bool:
    try:
        _tce = _lazy_get_pw_target_closed_error()
        if _tce is not None and isinstance(e, _tce):  # type: ignore
            return True
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_125', _e)
        pass
    try:
        name = getattr(e, "__class__", type(e)).__name__
    except Exception:
        name = ""
    try:
        msg = str(e)
    except Exception:
        msg = ""
    _msg_l = str(msg or "").lower()
    if "TargetClosedError" in (name or ""):
        return True
    if "Target page, context or browser has been closed" in msg:
        return True
    if "Browser has been closed" in msg:
        return True
    if "Page closed" in msg or "Page is closed" in msg:
        return True
    if "frame has been detached" in _msg_l:
        return True
    if "execution context was destroyed" in _msg_l and "navigation" in _msg_l:
        return True
    return False

def _pw_is_closed(page: Any) -> bool:
    try:
        if page is None:
            return True
        fn = getattr(page, "is_closed", None)
        if callable(fn):
            return bool(fn())
    except Exception:
        return True
    return False

def _pw_require_page(page: Any, where: str) -> None:
    if not _pw_guard(mod="SYS", coin="", plat="", act="", stage=str(where or "PW_REQUIRE_PAGE")):
        raise _UiDeadError(where, getattr(globals().get('_EXEC_WORKER_LOCAL'), 'pw_guard_reason', '') or ("runtime_recovering" if _pw_runtime_is_recovering() else "playwright_not_alive"))
    if _pw_is_closed(page):
        try:
            if getattr(globals().get('_close_flow'), 'current', lambda: None)() is None:
                _pw_runtime_hard_reset(f"{str(where or 'PW_REQUIRE_PAGE')}|page_is_closed_or_none", source="SYS", touch_scan=False)
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_126', _e)
            pass
        raise _UiDeadError(where, "page_is_closed_or_none")

def _exec_active_stage_touch(stage: str, desc: str = "", **extra) -> None:
    try:
        _reason = str(desc or "")[:180]
    except Exception:
        _reason = ""
    try:
        _active_req_touch(str(stage or "EXEC_STEP"), reason=_reason, **extra)
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_127', _e)
        pass
    try:
        _worker_heartbeat_touch(stage=str(stage or "EXEC_STEP"), where=str(desc or ""), **extra)
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_128', _e)
        pass
def _pw_call_timeout_ms(where: str = "", fn: Any = None, kwargs: dict | None = None) -> int | None:
    """给常见 Playwright 调用自动补一个较短超时，避免在 worker 里整段黑箱卡死。"""
    try:
        kw = kwargs if isinstance(kwargs, dict) else {}
        if 'timeout' in kw and kw.get('timeout') not in (None, '', 0, 0.0):
            return None
    except Exception:
        kw = {}
    try:
        name = str(getattr(fn, '__name__', '') or '').strip().lower()
    except Exception:
        name = ''
    try:
        where_l = str(where or '').strip().lower()
    except Exception:
        where_l = ''
    try:
        if name in ('wait_for_timeout', 'bring_to_front', 'evaluate', 'send'):
            return None
        if name in ('goto',):
            return 12000
        if name in ('click', 'dblclick', 'check', 'uncheck', 'tap', 'hover', 'press', 'fill', 'type', 'select_option'):
            return 4500
        if name in ('wait_for', 'wait_for_selector', 'wait_for_url', 'wait_for_function', 'wait_for_load_state', 'expect_navigation'):
            return 5000
        if name in ('count', 'is_enabled', 'is_disabled', 'is_checked', 'all_inner_texts', 'all_text_contents', 'all', 'evaluate_all'):
            return None
        if name in ('inner_text', 'text_content', 'input_value', 'get_attribute'):
            return 3000
        if 'goto' in where_l or 'navigate' in where_l:
            return 12000
        if 'wait' in where_l or 'dialog' in where_l or 'confirm' in where_l:
            return 5000
        if 'click' in where_l or 'submit' in where_l or 'close' in where_l or 'open' in where_l:
            return 4500
    except Exception:
        return None
    return None

def _exec_apply_page_timeouts(page: Any, *, nav_timeout_ms: int = 12000, action_timeout_ms: int = 4500, source: str = 'EXEC') -> None:
    """统一给执行页/上下文补默认超时，避免某个单步调用无限拖长。"""
    if page is None:
        return
    try:
        page.set_default_timeout(int(action_timeout_ms))
    except Exception:
        pass
    try:
        page.set_default_navigation_timeout(int(nav_timeout_ms))
    except Exception:
        pass
    try:
        ctx = getattr(page, 'context', None)
        if ctx is not None:
            try:
                ctx.set_default_timeout(int(max(action_timeout_ms, 5000)))
            except Exception:
                pass
            try:
                ctx.set_default_navigation_timeout(int(nav_timeout_ms))
            except Exception:
                pass
    except Exception:
        pass

def _exec_where_tag(where: Any, max_len: int = 72) -> str:
    try:
        raw = str(where or '').strip()
    except Exception:
        raw = ''
    if not raw:
        return ''
    try:
        tag = re.sub(r'[^A-Za-z0-9_.:-]+', '_', raw)
    except Exception:
        try:
            import re as _re
            tag = _re.sub(r'[^A-Za-z0-9_.:-]+', '_', raw)
        except Exception:
            tag = raw.replace(' ', '_')
    while '__' in tag:
        tag = tag.replace('__', '_')
    return str(tag[:max_len]).strip('._:-')

def _exec_stage_label(prefix: str, where: Any = '') -> str:
    try:
        base = str(prefix or '').strip() or 'EXEC_STAGE'
    except Exception:
        base = 'EXEC_STAGE'
    tag = _exec_where_tag(where, max_len=max(12, 96 - len(base)))
    return f"{base}|{tag}" if tag else base

def _should_skip_scan_probe_log(stage: str, where: str = '') -> bool:
    try:
        if not bool(globals().get('SCAN_NOISE_LOG_REDUCE', True)):
            return False
        st = str(stage or '').upper().strip()
        wh = str(where or '').strip()
        if st not in ('PW_CALL_BEGIN', 'PW_CALL_OK'):
            return False
        noisy_keys = (
            'read_coin_row_basic.rows_locator',
            'read_coin_row_basic.rows_count',
            '_var_diag_snapshot.evaluate',
            'var_diag_snapshot.evaluate',
            'var_bulk_positions_scan.evaluate',
            'ensure_page.ext_crash_page.',
            'ensure_page.ext_temp_unavailable.',
            'ensure_page.ext_health.',
            'ensure_page.var_health.',
        )
        return any(k in wh for k in noisy_keys)
    except Exception:
        return False

def _m10_no_request_enrich_from_snapshot(diag: dict | None, snapshot: dict | None = None, coin: str = '') -> dict:
    d = dict(diag or {})
    try:
        snap = snapshot if isinstance(snapshot, dict) else None
        cu = str(coin or d.get('coin') or '').upper().strip()
        if (not cu) or (snap is None):
            return d
        builder = globals().get('_z1_tp_build_request')
        if callable(builder):
            _req, _summary = builder(snap, cu)
            if isinstance(_summary, dict):
                d['z1_branch'] = str(_summary.get('branch') or '')
                d['z1_reason'] = str(_summary.get('reason') or '')
                d['z1_req_module'] = str(_summary.get('req_module') or '')
                d['z1_struct_state'] = str(_summary.get('struct_state') or '')
                d['z1_fail_reason'] = str(_summary.get('fail_reason') or '')
                for _k in ('profit_u', 'loss_u', 'm10_threshold', 'small_leg_ratio', 'ext_side', 'var_side', 'ext_has', 'var_has'):
                    if _k in _summary and _k not in d:
                        d[_k] = _summary.get(_k)
                if isinstance(_req, dict) and str(_req.get('module') or '').upper() == 'B2':
                    d['z1_req_module'] = 'B2'
                elif isinstance(_req, dict) and str(_req.get('module') or '').upper() == 'M10':
                    d['z1_req_module'] = 'M10'
    except Exception as _e:
        d['z1_summary_exc'] = f"{type(_e).__name__}:{str(_e)[:80]}"
    return d

def _m10_no_request_reason_from_diag(diag: dict | None) -> str:
    d = dict(diag or {})
    try:
        if int(d.get('snap_no_leg') or 0) == 1:
            return 'reject_tp_missing_both_legs'
    except Exception:
        pass
    try:
        ext_n = float(d.get('snap_ext_n') or 0.0)
        var_n = float(d.get('snap_var_n') or 0.0)
        eps_u = float(globals().get('B1_NO_LEG_EPS_U', 0.0) or 0.0)
        ext_has = abs(ext_n) > eps_u
        var_has = abs(var_n) > eps_u
        if bool(ext_has) ^ bool(var_has):
            return 'reject_tp_missing_counter_leg'
    except Exception:
        pass
    try:
        if int(d.get('readiness_allow') or 0) == 0:
            rr = str(d.get('readiness_reason') or d.get('readiness_blk') or '').strip()
            if rr:
                return rr
    except Exception:
        pass
    try:
        if int(d.get('snap_ext_stale') or 0) == 1 or int(d.get('snap_var_stale') or 0) == 1:
            return 'reject_tp_snapshot_stale'
    except Exception:
        pass
    try:
        if str(d.get('z1_req_module') or '').upper() == 'B2':
            return 'b2_selected_over_m10'
        if str(d.get('z1_req_module') or '').upper() == 'M10':
            return 'm10_req_built_not_emitted'
    except Exception:
        pass
    try:
        zr = str(d.get('z1_reason') or '').strip()
        zf = str(d.get('z1_fail_reason') or '').strip()
        if zr == 'm10_runner_protected':
            return 'm10_runner_protected'
        if zr == 'b2_blocked_by_trend_alpha':
            return 'b2_blocked_by_trend_alpha'
        if zr == 'tp_lock_cooldown':
            return 'tp_lock_cooldown'
        if zr.startswith('struct_fail:'):
            if zf == 'same_dir':
                return 'reject_tp_same_direction_legs'
            if zf == 'both_tiny_leg':
                return 'reject_tp_both_legs_too_small'
            if zf == 'missing_side':
                return 'reject_tp_side_missing'
            if zf.startswith('classify_exc'):
                return 'reject_tp_struct_classify_exc'
        if zr == 'no_hit':
            profit_u = float(d.get('profit_u') or 0.0)
            loss_u = float(d.get('loss_u') or 0.0)
            thr = float(max(0.0, _safe_float(d.get('m10_profit_min_u', d.get('m10_threshold')), 1.0)))
            struct_mode = str(d.get('struct_mode') or d.get('z1_struct_state') or '').upper().strip()
            soft_ratio = float(d.get('small_leg_ratio') or 0.0)
            soft_min = float(globals().get('B2M10_SMALL_LEG_MIN_RATIO', 0.05) or 0.05)
            if profit_u <= 0.0:
                return 'reject_tp_no_profit_leg'
            if loss_u >= 0.0:
                return 'reject_tp_no_loss_leg'
            if profit_u <= thr + 1e-9:
                return 'reject_tp_profit_below_threshold'
            if ('SOFT' in struct_mode) and (soft_ratio + 1e-12 < soft_min):
                return 'reject_tp_small_leg_ratio_too_small'
    except Exception:
        pass
    return 'm10_no_explicit_reject_trace'

def _exec_stage_probe(stage: str, where: str = '', **extra) -> None:
    _stage = _exec_stage_label(stage, where)
    try:
        _worker_heartbeat_touch(stage=_stage, where=str(where or '')[:240], **(dict(extra or {})))
    except Exception as _e:
        _record_swallowed_exception('exec_stage_probe.worker', _e, detail=_stage)
    if _WORKER_STATE.retired_current():
        return
    try:
        if _should_skip_scan_probe_log(stage, where):
            return
    except Exception:
        pass
    try:
        _active_req_touch(_stage, reason=str(where or '')[:160], **(dict(extra or {})))
    except Exception as _e:
        _record_swallowed_exception('exec_stage_probe.active_req', _e, detail=_stage)

def _pw_call(where: str, fn, *args, **kwargs):
    # A timed-out call already in flight cannot be interrupted;
    # prohibit every subsequent wrapped UI operation from that retired task.
    _WORKER_STATE.assert_live()
    _close_ctx = getattr(globals().get('_close_flow'), 'current', lambda: None)()
    if _close_ctx is not None:
        _close_ctx.check()
    if not _pw_guard(mod="SYS", coin="", plat="", act="", stage=str(where or "PW_CALL")):
        raise _UiDeadError(where, getattr(globals().get('_EXEC_WORKER_LOCAL'), 'pw_guard_reason', '') or ("runtime_recovering" if _pw_runtime_is_recovering() else "playwright_not_alive"))
    _operation_timeout_ms = int(kwargs.pop('_operation_timeout_ms', 0) or 0)
    try:
        _timeout_auto = _pw_call_timeout_ms(where=str(where or ''), fn=fn, kwargs=kwargs)
        if _timeout_auto not in (None, '', 0, 0.0):
            kwargs = dict(kwargs or {})
            kwargs.setdefault('timeout', int(_timeout_auto))
    except Exception:
        pass
    if _close_ctx is not None and 'timeout' in kwargs:
        kwargs['timeout'] = _close_ctx.timeout_ms(kwargs['timeout'])
    try:
        kwargs = _browser_supported_kwargs(fn, kwargs)
        import inspect as _inspect
        _sig = _inspect.signature(fn)
        _params = _sig.parameters if _sig else {}
        _accept_var_kw = any(getattr(_p, 'kind', None) == _inspect.Parameter.VAR_KEYWORD for _p in _params.values()) if _params else False
        if isinstance(kwargs, dict) and kwargs and (not _accept_var_kw):
            _drop = []
            _filt = {}
            for _k, _v in kwargs.items():
                if _k in _params:
                    _filt[_k] = _v
                else:
                    _drop.append(str(_k))
            kwargs = _filt
            if _drop:
                try:
                    _log_jsonl(EXEC_DECISION_LOG, {"ts": time.time(), "mod": "SYS", "event": "pw_call_kwargs_dropped", "where": str(where or "")[:160], "fn": str(getattr(fn, '__name__', '') or ''), "dropped": _drop})
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_130a', _e)
                    pass
    except Exception:
        pass
    try:
        _timeout_ms = max(_operation_timeout_ms, int(kwargs.get('timeout') or 0))
    except Exception:
        _timeout_ms = 0
    _exec_stage_probe("PW_CALL_BEGIN", str(where or ""), timeout_ms=_timeout_ms)
    try:
        _ret = fn(*args, **kwargs)
        _WORKER_STATE.assert_live()
        _exec_stage_probe("PW_CALL_OK", str(where or ""))
        return _ret
    except Exception as e:
        # Late TargetClosed/UI errors must not reset the successor runtime.
        _WORKER_STATE.assert_live()
        _exec_stage_probe("PW_CALL_FAIL", str(where or ""), err=f"{type(e).__name__}:{e}"[:240])
        if _is_target_closed_exc(e) and _close_ctx is None:
            try:
                _pw_runtime_hard_reset(f"{str(where or 'PW_CALL')}|target_closed", source="SYS", touch_scan=False)
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_133', _e)
                pass
            raise _UiDeadError(where, repr(e)) from e
        if _is_link_error_exc(e):
            try:
                if _close_ctx is None:
                    _ui_link_err_hit(where, e)
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_134', _e)
                pass
            raise _UiLinkError(where, repr(e)) from e
        raise

def _pw_front(page: Any, where: str) -> bool:
    _pw_require_page(page, where)
    try:
        _pw_call(where, page.bring_to_front)
        return True
    except _UiDeadError:
        raise
    except Exception as _e:
        _log_exc_level(mod="SYS", stage="PW_FRONT_FAIL", level="B", e=_e)
        return False

_EXEC_FRONT_STATE: dict[str, dict] = {}
_EXEC_GOTO_STATE: dict[str, dict] = {}
_EXEC_POST_REFRESH_STATE: dict[str, dict] = {}

def _exec_front_if_needed(page: Any, where: str, *, label: str = '', plat: str = '', coin: str = '', min_interval_sec: float = 1.2, force: bool = False) -> bool:
    """执行链置前去重：同一页面/同平台/同币种在短时间内不重复 BringToFront。
    目的：减少你看到的“页面明明正常，却在下单前又切一次标签页”的冗余动作。
    注意：跨平台步骤（EXT->VAR->EXT）仍会置前；这里只砍同链路内的重复置前。
    """
    _pw_require_page(page, where)
    try:
        nowv = float(time.time())
    except Exception:
        nowv = 0.0
    try:
        page_id = str(id(page))
    except Exception:
        page_id = str(where or 'EXEC_FRONT')
    try:
        cur_url = str(getattr(page, 'url', '') or '')
    except Exception:
        cur_url = ''
    key = str(plat or '').upper().strip() or 'GLOBAL'
    try:
        st = dict(_EXEC_FRONT_STATE.get(key) or {})
    except Exception:
        st = {}
    same_page = str(st.get('page_id') or '') == page_id
    same_coin = str(st.get('coin') or '').upper().strip() == str(coin or '').upper().strip()
    age = nowv - float(st.get('ts') or 0.0)
    if (not force) and same_page and same_coin and age >= 0 and age < max(0.15, float(min_interval_sec or 1.2)):
        try:
            safe_log(lambda: f"[{now_ts()}] EXEC_FRONT_SKIP（执行前置前跳过） plat={str(plat or '').upper() or '-'} coin={str(coin or '').upper() or '-'} age={age:.3f}s label={str(label or where or '-')[:80]}")
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_135', _e)
            pass
        st.update({'ts': nowv, 'label': str(label or where or ''), 'url': cur_url, 'page_id': page_id, 'plat': str(plat or '').upper().strip(), 'coin': str(coin or '').upper().strip()})
        _EXEC_FRONT_STATE[key] = st
        return True
    ok = _pw_front(page, where)
    _EXEC_FRONT_STATE[key] = {'ts': nowv, 'label': str(label or where or ''), 'url': cur_url, 'page_id': page_id, 'plat': str(plat or '').upper().strip(), 'coin': str(coin or '').upper().strip()}
    return bool(ok)

def _exec_mark_goto_ok(page: Any, *, plat: str = '', coin: str = '', label: str = '') -> None:
    try:
        key = str(plat or '').upper().strip() or 'GLOBAL'
        _EXEC_GOTO_STATE[key] = {
            'ts': float(time.time()),
            'page_id': str(id(page)),
            'plat': str(plat or '').upper().strip(),
            'coin': str(coin or '').upper().strip(),
            'label': str(label or ''),
            'url': str(getattr(page, 'url', '') or ''),
        }
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_136', _e)
        pass
def _exec_goto_recent_ok(page: Any, *, plat: str = '', coin: str = '', max_age_sec: float = 1.8) -> bool:
    try:
        if not _goto_switch_rate_limit_enabled():
            return False
        key = str(plat or '').upper().strip() or 'GLOBAL'
        st = dict(_EXEC_GOTO_STATE.get(key) or {})
        if str(st.get('page_id') or '') != str(id(page)):
            return False
        if str(st.get('coin') or '').upper().strip() != str(coin or '').upper().strip():
            return False
        age = float(time.time()) - float(st.get('ts') or 0.0)
        return age >= 0 and age < max(0.20, float(max_age_sec or 1.8))
    except Exception:
        return False

def _post_exec_refresh_recent(coin: str, platform: str, action: str, *, max_age_sec: float = 1.2) -> bool:
    try:
        key = f"{str(coin or '').upper().strip()}|{str(platform or '').upper().strip()}|{str(action or '').lower().strip()}"
        st = dict(_EXEC_POST_REFRESH_STATE.get(key) or {})
        age = float(time.time()) - float(st.get('ts') or 0.0)
        return age >= 0 and age < max(0.20, float(max_age_sec or 1.2))
    except Exception:
        return False

