def _platform_access_probe(page: Any, platform: str) -> dict:
    try:
        body = _pw_call(f'access_probe.{platform}.body', page.locator, 'body')
        text = _pw_call(f'access_probe.{platform}.text', body.inner_text, timeout=2500)
        return _inspect_platform_access(platform, text)
    except Exception:
        return {'blocked': True, 'reason': str(platform).lower() + '_page_text_unavailable', 'user_action_required': False}

def _m2_ext_should_reload_after_zero_rows(page: Any, *, snapshot: dict | None = None, coins: list[str] | tuple[str, ...] | None = None) -> tuple[bool, str, dict]:
    """EXT 二次复扫后仍 0 行时，是否真的需要 reload。

    收口口径：
    - 空仓/空列表页面：不刷新；
    - 单轮 0 行：不刷新；
    - 必须命中明确异常（TEMP_UNAVAILABLE/路由异常）或连续多轮 0 行，才允许 reload；
    - reload 受冷却控制，避免每轮都刷。
    """
    detail: dict = {}
    try:
        state = _EXT_ZERO_ROWS_RELOAD_STATE if isinstance(_EXT_ZERO_ROWS_RELOAD_STATE, dict) else {"streak": 0.0, "last_reload_ts": 0.0}
        access = _platform_access_probe(page, 'EXT')
        if access.get('blocked'):
            state['streak'] = 0.0
            detail.update(access=access, decision='wait_for_platform_access_no_reload')
            return False, str(access['reason']), detail
        nowv = float(time.time())
        try:
            empty, empty_reason, empty_detail = _scan_detect_positions_empty_state(page, EXT, platform='EXT')
        except Exception as e:
            empty, empty_reason, empty_detail = False, '', {'empty_detect_error': f'{type(e).__name__}:{e}'}
        detail['empty_reason'] = str(empty_reason or '')
        if isinstance(empty_detail, dict) and empty_detail:
            detail['empty_detail'] = dict(empty_detail)
        if empty:
            state['streak'] = 0.0
            detail['decision'] = 'skip_reload_on_empty_view'
            return False, f'empty_view:{empty_reason or "unknown"}', detail

        try:
            det = _ext_temp_unavailable_detect(page, 'm2_zero_rows_reload_gate')
        except Exception as e:
            det = {'detect_error': f'{type(e).__name__}:{e}'}
        if isinstance(det, dict):
            detail['temp_unavailable'] = dict(det)
            if bool(det.get('detected')) or bool(det.get('has_code')) or bool(det.get('has_desc')):
                state['streak'] = 0.0
                detail['decision'] = 'reload_temp_unavailable'
                return True, 'temp_unavailable', detail

        try:
            cur_url = str(getattr(page, 'url', '') or '')
        except Exception:
            cur_url = ''
        detail['url'] = cur_url[:200]
        if cur_url and not _ext_url_is_perp(cur_url):
            state['streak'] = 0.0
            detail['decision'] = 'reload_bad_route'
            return True, 'bad_route', detail

        streak = int(float(state.get('streak') or 0.0)) + 1
        state['streak'] = float(streak)
        detail['streak'] = streak
        need_streak = max(2, int(EXT_ZERO_ROWS_RELOAD_STREAK_NEED or 2))
        detail['need_streak'] = need_streak
        if streak < need_streak:
            detail['decision'] = 'skip_reload_wait_streak'
            return False, 'single_round_zero_rows', detail

        cd = max(10.0, float(EXT_ZERO_ROWS_RELOAD_COOLDOWN_SEC or 90.0))
        last_reload_ts = float(state.get('last_reload_ts') or 0.0)
        since = float(nowv - last_reload_ts) if last_reload_ts > 0 else 1e18
        detail['cooldown_sec'] = cd
        detail['since_last_reload_sec'] = round(since, 3) if since < 1e17 else None
        if last_reload_ts > 0 and since < cd:
            detail['decision'] = 'skip_reload_in_cooldown'
            return False, 'reload_cooldown', detail

        detail['decision'] = 'reload_on_consecutive_zero_rows'
        return True, 'consecutive_zero_rows', detail
    except Exception as e:
        detail['gate_error'] = f'{type(e).__name__}:{e}'
        return False, 'gate_exception_skip_reload', detail

def _m2_ext_mark_zero_rows_recovered(*, reloaded: bool = False) -> None:
    try:
        state = _EXT_ZERO_ROWS_RELOAD_STATE if isinstance(_EXT_ZERO_ROWS_RELOAD_STATE, dict) else None
        if not isinstance(state, dict):
            return
        state['streak'] = 0.0
        if reloaded:
            state['last_reload_ts'] = float(time.time())
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_145', _e)
        pass
def _ext_temp_unavailable_detect(page: Any, where: str) -> dict:
    """识别 EXT 前端的 GLOBAL.TEMPORARILY_UNAVAILABLE 错误页。"""
    out = {
        "active": False,
        "has_code": False,
        "has_desc": False,
        "has_try_again": False,
    }
    try:
        _pw_require_page(page, where)
    except Exception:
        return out

    checks = [
        ("has_code", "text=GLOBAL.TEMPORARILY_UNAVAILABLE"),
        ("has_desc", "text=Error with GLOBAL.TEMPORARILY_UNAVAILABLE code occurred"),
        ("has_try_again", "button:has-text('Try again')"),
    ]
    for key, sel in checks:
        try:
            loc = _pw_call(f"{where}.locator.{key}", page.locator, sel)
            cnt = int(_pw_call(f"{where}.count.{key}", loc.count) or 0)
            out[key] = bool(cnt > 0)
        except Exception:
            out[key] = False
    out["active"] = bool(out.get("has_code") or out.get("has_desc"))
    return out

def _ext_temp_unavailable_try_again(page: Any, where: str, *, timeout_ms: int = 2500) -> bool:
    try:
        loc = _pw_call(f"{where}.try_again.locator", page.locator, "button:has-text('Try again')")
        cnt = int(_pw_call(f"{where}.try_again.count", loc.count) or 0)
        if cnt <= 0:
            return False
        _pw_call(f"{where}.try_again.click", loc.first.click, timeout=int(timeout_ms))
        try:
            _pw_wait_ms(page, 1800, f"{where}.try_again.wait")
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_146', _e)
            pass
        return True
    except Exception:
        return False

_ENSURE_PAGE_PLATFORM_RECOVERY: Dict[str, Dict[str, Any]] = {}

def _ensure_page_recovery_snapshot(platform_key: str = '') -> dict:
    pk = str(platform_key or '').upper().strip()
    if not pk:
        return {}
    try:
        return dict(_ENSURE_PAGE_PLATFORM_RECOVERY.get(pk) or {})
    except Exception:
        return {}

def _ensure_page_recovery_begin(platform_key: str = '', *, stage: str = '', reason: str = '', owner: str = '') -> str:
    pk = str(platform_key or '').upper().strip()
    if not pk:
        return ''
    try:
        token = f"{pk}:{int(time.time()*1000)}:{hex(id(reason))}"
    except Exception:
        token = f"{pk}:{int(time.time()*1000)}"
    row = {
        'active': True,
        'token': str(token),
        'stage': str(stage or '')[:120],
        'reason': str(reason or '')[:240],
        'owner': str(owner or '')[:160],
        'start_ts': float(time.time()),
        'update_ts': float(time.time()),
    }
    _ENSURE_PAGE_PLATFORM_RECOVERY[pk] = row
    return str(token)

def _ensure_page_recovery_touch(platform_key: str = '', *, token: str = '', stage: str = '', reason: str = '') -> None:
    pk = str(platform_key or '').upper().strip()
    if not pk:
        return
    row = dict(_ENSURE_PAGE_PLATFORM_RECOVERY.get(pk) or {})
    if not row:
        return
    if token and str(row.get('token') or '') != str(token):
        return
    if stage:
        row['stage'] = str(stage)[:120]
    if reason:
        row['reason'] = str(reason)[:240]
    row['update_ts'] = float(time.time())
    _ENSURE_PAGE_PLATFORM_RECOVERY[pk] = row

def _ensure_page_recovery_end(platform_key: str = '', *, token: str = '', result: str = '') -> None:
    pk = str(platform_key or '').upper().strip()
    if not pk:
        return
    row = dict(_ENSURE_PAGE_PLATFORM_RECOVERY.get(pk) or {})
    if token and row and str(row.get('token') or '') != str(token):
        return
    if row:
        row['active'] = False
        row['result'] = str(result or '')[:240]
        row['end_ts'] = float(time.time())
    _ENSURE_PAGE_PLATFORM_RECOVERY.pop(pk, None)

def _ensure_page_wait_platform_recovery(platform_key: str = '', *, where: str = '', max_wait_ms: int = 6000) -> tuple[bool, str]:
    pk = str(platform_key or '').upper().strip()
    if not pk:
        return True, 'no_platform'
    if bool(globals().get('UI_SINGLE_CHAIN_ENABLE', False)):
        try:
            row = _ensure_page_recovery_snapshot(pk)
            if bool((row or {}).get('active')):
                safe_log(lambda: f"[{now_ts()}] [ENSURE_PAGE][RECOVERY_MARK_SCRUB] plat={pk} where={str(where or '')[:120]} stage={str((row or {}).get('stage') or '')[:80]} reason={str((row or {}).get('reason') or '')[:160]}")
        except Exception:
            pass
        try:
            _ensure_page_recovery_end(pk, result='single_chain_bypass')
        except Exception:
            _ENSURE_PAGE_PLATFORM_RECOVERY.pop(pk, None)
        return True, 'single_chain_bypass'
    try:
        wait_ms = max(0, int(max_wait_ms or 0))
    except Exception:
        wait_ms = 0
    if wait_ms <= 0:
        row = _ensure_page_recovery_snapshot(pk)
        if bool(row.get('active')):
            return False, str(row.get('reason') or 'platform_recovery_active')
        return True, 'ok'
    deadline = float(time.time()) + (float(wait_ms) / 1000.0)
    loops = 0
    while True:
        loops += 1
        row = _ensure_page_recovery_snapshot(pk)
        if not bool(row.get('active')):
            return True, 'ok'
        try:
            left_ms = int(max(0.0, (deadline - float(time.time())) * 1000.0))
        except Exception:
            left_ms = 0
        if left_ms <= 0:
            return False, str(row.get('reason') or 'platform_recovery_active')
        step = min(250, max(80, left_ms))
        try:
            if loops == 1 or loops % 4 == 0:
                safe_log(lambda: f"[{now_ts()}] [ENSURE_PAGE][RECOVERY_WAIT] plat={pk} where={str(where or '')[:120]} left_ms={int(left_ms)} stage={str(row.get('stage') or '')[:80]} reason={str(row.get('reason') or '')[:120]}")
        except Exception:
            pass
        try:
            _ORIG_TIME_SLEEP(float(step) / 1000.0)
        except Exception:
            break
    return False, 'platform_recovery_active'

def _ext_same_tab_reload_recover(page: Any, where: str, *, reason: str = '', total_budget_ms: int = 18000, max_reload_attempts: int = 2) -> bool:
    """EXT 崩溃/OOM/高内存时，优先走同页重新加载恢复。

    口径统一：
    - 先尝试崩溃页按钮【重新加载】；
    - 若仍未恢复，再做同页 reload；
    - 每次 reload 后都重新做健康检查 + recycle 检查；
    - 成功后重置该页健康账本，避免旧的高内存统计继续污染新链路。
    """
    try:
        _pw_require_page(page, where)
    except Exception:
        return False
    try:
        deadline = float(time.time()) + max(1.0, float(int(total_budget_ms or 0)) / 1000.0)
    except Exception:
        deadline = float(time.time()) + 18.0

    def _left_ms() -> int:
        try:
            return max(1, int((deadline - float(time.time())) * 1000.0))
        except Exception:
            return 1

    try:
        safe_log(lambda: f"[{now_ts()}] [EXT_RECOVER][SAME_TAB_BEGIN] where={str(where)[:120]} reason={str(reason or '')[:160]} budget_ms={_left_ms()} attempts={int(max_reload_attempts or 0)}")
    except Exception:
        pass

    try:
        _crash_ok = _ext_crash_page_self_heal(
            page,
            f"{where}.crash_heal",
            strict=False,
            total_budget_ms=min(14000, max(4000, _left_ms())),
            allow_same_tab_goto=False,
            force=True,
        )
    except Exception as _e:
        _record_swallowed_exception('ext_same_tab_reload_recover.crash_heal', _e)
        _crash_ok = False
    if _crash_ok:
        try:
            _ensure_page_health_reset_for_page(page, 'EXT', reason='same_tab_reload_ok')
            _ensure_page_health_touch(page, 'EXT', event='same_tab_reload_ok', force_probe=True)
        except Exception as _e_reset:
            _record_swallowed_exception('ext_same_tab_reload_recover.reset_after_crash', _e_reset)
        try:
            _recycle, _recycle_reason, _recycle_detail = _ensure_page_should_recycle(page, 'EXT', event='check:same_tab_reload_ok')
        except Exception as _e_chk:
            _record_swallowed_exception('ext_same_tab_reload_recover.recycle_after_crash', _e_chk)
            _recycle, _recycle_reason, _recycle_detail = False, '', {}
        if not _recycle and _ext_page_looks_healthy(page, f"{where}.after_crash_heal"):
            try:
                safe_log(lambda: f"[{now_ts()}] [EXT_RECOVER][SAME_TAB_OK] where={str(where)[:120]} recovered_by=crash_reload_button budget_left_ms={_left_ms()}")
            except Exception:
                pass
            return True
        try:
            safe_log(lambda: f"[{now_ts()}] [EXT_RECOVER][SAME_TAB_CONTINUE] where={str(where)[:120]} reason=post_crash_heal_still_recycle recycle_reason={str(_recycle_reason or '')[:120]} heap_mb={round(float((_recycle_detail or {}).get('heap_mb') or -1.0), 3)}")
        except Exception:
            pass

    _attempt = 0
    while _attempt < max(1, int(max_reload_attempts or 1)):
        _attempt += 1
        if _left_ms() <= 0:
            try:
                safe_log(lambda: f"[{now_ts()}] [EXT_RECOVER][SAME_TAB_TIMEOUT] where={str(where)[:120]} reason={str(reason or '')[:120]} attempt={int(_attempt)}")
            except Exception:
                pass
            return False
        try:
            reload_timeout = min(max(5000, int(_left_ms() * 0.55)), 15000)
        except Exception:
            reload_timeout = 10000
        try:
            post_wait_ms = min(max(2500, int(_left_ms() * 0.25)), 8000)
        except Exception:
            post_wait_ms = 3500
        try:
            safe_log(lambda: f"[{now_ts()}] [EXT_RECOVER][SAME_TAB_RELOAD] where={str(where)[:120]} attempt={int(_attempt)} reload_timeout_ms={int(reload_timeout)} wait_ms={int(post_wait_ms)} reason={str(reason or '')[:120]}")
        except Exception:
            pass
        try:
            _pw_reload(page, f"{where}.same_tab_reload.{_attempt}", timeout=int(reload_timeout), evidence='EXT_RECOVER')
        except Exception as _e:
            _record_swallowed_exception('ext_same_tab_reload_recover.reload', _e, attempt=_attempt, where=where)
        try:
            _pw_wait_ms(page, int(post_wait_ms), f"{where}.same_tab_reload_wait.{_attempt}")
        except Exception as _e:
            _record_swallowed_exception('ext_same_tab_reload_recover.wait', _e, attempt=_attempt, where=where)
        try:
            _ensure_page_health_reset_for_page(page, 'EXT', reason=f'same_tab_reload_attempt_{_attempt}')
            _ensure_page_health_touch(page, 'EXT', event=f'same_tab_reload_attempt_{_attempt}', force_probe=True)
            _recycle, _recycle_reason, _recycle_detail = _ensure_page_should_recycle(page, 'EXT', event=f'check:same_tab_reload_attempt_{_attempt}')
        except Exception as _e_chk:
            _record_swallowed_exception('ext_same_tab_reload_recover.health', _e_chk, attempt=_attempt, where=where)
            _recycle, _recycle_reason, _recycle_detail = False, '', {}
        _healthy = False
        try:
            _healthy = bool(_ext_page_looks_healthy(page, f"{where}.same_tab_after_reload.{_attempt}"))
        except Exception as _e_h:
            _record_swallowed_exception('ext_same_tab_reload_recover.healthy', _e_h, attempt=_attempt, where=where)
            _healthy = False
        if _healthy and (not _recycle):
            try:
                safe_log(lambda: f"[{now_ts()}] [EXT_RECOVER][SAME_TAB_OK] where={str(where)[:120]} recovered_by=reload attempt={int(_attempt)} budget_left_ms={_left_ms()}")
            except Exception:
                pass
            return True
        try:
            safe_log(lambda: f"[{now_ts()}] [EXT_RECOVER][SAME_TAB_NOT_OK] where={str(where)[:120]} attempt={int(_attempt)} healthy={int(bool(_healthy))} recycle={int(bool(_recycle))} recycle_reason={str(_recycle_reason or '')[:120]} heap_mb={round(float((_recycle_detail or {}).get('heap_mb') or -1.0), 3)} budget_left_ms={_left_ms()}")
        except Exception:
            pass
    return False

def _ext_recover_error_code_from_exc(exc: Any, *, after_quiesce: bool = False) -> str:
    try:
        txt = str(exc or '').lower()
    except Exception:
        txt = ''
    if ('about:blank' in txt) and after_quiesce:
        return 'ext_same_tab_recover_blank_after_quiesce'
    if ('timeout' in txt) and after_quiesce:
        return 'ext_same_tab_recover_timeout_after_quiesce'
    if ('about:blank' in txt):
        return 'ext_same_tab_recover_blank_page'
    if 'timeout' in txt:
        return 'ext_same_tab_recover_timeout'
    if 'pre_open_budget_exhausted' in txt:
        return 'ext_same_tab_recover_blocked_by_runtime_pressure'
    if 'recycle_required' in txt:
        return 'ext_recycle_required'
    if 'page_crashed' in txt or 'out_of_memory' in txt or 'aw_snap' in txt or 'reload_crash_page' in txt:
        return 'ext_crash_page_active'
    return 'ext_same_tab_recover_failed'

def _ext_recovery_quiesce_wait(where: str, *, reason: str = '', wait_ms: int = 1800) -> None:
    try:
        wait_eff = max(0, int(wait_ms or 0))
    except Exception:
        wait_eff = 0
    if wait_eff <= 0:
        return
    try:
        safe_log(lambda: f"[{now_ts()}] [EXT_RECOVER][QUIESCE] where={str(where)[:120]} wait_ms={int(wait_eff)} reason={str(reason or '')[:160]}")
    except Exception:
        pass
    try:
        _ORIG_TIME_SLEEP(float(wait_eff) / 1000.0)
    except Exception:
        pass

def _ext_crash_page_detect(page: Any, where: str, *, sample_chars: int = 1200) -> dict:
    """识别 EXT 的崩溃页 / OOM（内存不足）页 / aw,snap 崩溃页。"""
    out = {
        "active": False,
        "crashed": False,
        "reason": "",
        "title": "",
        "body_excerpt": "",
        "has_reload_button": False,
    }
    try:
        _pw_require_page(page, where)
    except Exception:
        return out
    try:
        det = _ui_page_crash_probe(page, coin='', platform='EXT', sample_chars=max(400, int(sample_chars or 1200)))
    except Exception as _e:
        det = {'crashed': False, 'reason': f'probe_exc:{type(_e).__name__}'}
    try:
        out['crashed'] = bool((det or {}).get('crashed'))
        out['reason'] = str((det or {}).get('reason') or '')[:200]
        out['title'] = str((det or {}).get('title') or '')[:200]
        out['body_excerpt'] = str((det or {}).get('body_excerpt') or '')[:max(400, int(sample_chars or 1200))]
    except Exception:
        pass
    _rsn = str(out.get('reason') or '').lower()
    if bool(out.get('crashed')) and any(k in _rsn for k in ('out_of_memory', 'aw_snap', 'page_crashed', 'reload_crash_page', 'dead_jim', 'ui_dead')):
        out['active'] = True
    for _sel in (
        "button:has-text('重新加载')",
        "button:has-text('Reload')",
        "button:has-text('重新载入')",
        "button:has-text('重新整理')",
    ):
        try:
            _loc = _pw_call(f"{where}.reload_btn.locator", page.locator, _sel)
            _cnt = int(_pw_call(f"{where}.reload_btn.count", _loc.count) or 0)
            if _cnt > 0:
                out['has_reload_button'] = True
                break
        except Exception:
            continue
    return out

def _ext_crash_page_click_reload(page: Any, where: str, *, timeout_ms: int = 2500, post_wait_ms: int = 6500) -> bool:
    for _sel in (
        "button:has-text('重新加载')",
        "button:has-text('Reload')",
        "button:has-text('重新载入')",
        "button:has-text('重新整理')",
    ):
        try:
            _loc = _pw_call(f"{where}.reload_btn.locator", page.locator, _sel)
            _cnt = int(_pw_call(f"{where}.reload_btn.count", _loc.count) or 0)
            if _cnt <= 0:
                continue
            _pw_call(f"{where}.reload_btn.click", _loc.first.click, timeout=int(timeout_ms))
            try:
                _wait_eff = max(1800, int(post_wait_ms or 0))
            except Exception:
                _wait_eff = 6500
            try:
                _pw_wait_ms(page, int(_wait_eff), f"{where}.reload_btn.wait")
            except Exception as _e:
                _record_swallowed_exception('ext_crash_page_click_reload.wait', _e)
            return True
        except Exception:
            continue
    return False

def _ext_crash_page_self_heal(page: Any, where: str, *, target_url: str = "", force: bool = False,
                              strict: bool = False, total_budget_ms: int = 15000, allow_same_tab_goto: bool = False) -> bool:
    """EXT 崩溃页自愈：优先点崩溃页【重新加载】，再走同页 reload，最后交给外层 new tab。"""
    try:
        _pw_require_page(page, where)
    except Exception:
        return False

    try:
        _deadline = float(time.time()) + max(0.8, float(int(total_budget_ms or 0)) / 1000.0)
    except Exception:
        _deadline = float(time.time()) + 15.0

    def _budget_left_ms() -> int:
        try:
            return max(0, int((_deadline - float(time.time())) * 1000.0))
        except Exception:
            return 1

    def _touch(_stage: str, _reason: str = "") -> None:
        try:
            _active_req_touch(_stage, reason=(_reason or where), where=where)
        except Exception as _e:
            _record_swallowed_exception('ext_crash_page_self_heal.touch', _e)

    def _raise_if_budget_exhausted(_stage: str) -> None:
        if _budget_left_ms() > 0:
            return
        _touch('EXT_CRASH_HEAL_TIMEOUT', _stage)
        raise _UiRecoverTimeoutError(where, f"ext_crash_heal_budget_exhausted:{_stage}")

    try:
        nowv = float(time.time())
    except Exception:
        nowv = 0.0
    try:
        page_key = int(id(page))
    except Exception:
        page_key = 0
    try:
        cd = float(EXT_TEMP_UNAVAILABLE_HEAL_COOLDOWN_SEC or 2.5)
    except Exception:
        cd = 2.5
    _last_heal = globals().setdefault('_EXT_CRASH_PAGE_LAST_HEAL', {})
    if (not force) and page_key:
        last = float((_last_heal or {}).get(page_key) or 0.0)
        if (nowv - last) < cd:
            return False

    _touch('EXT_CRASH_HEAL_BEGIN', 'detect')
    det = _ext_crash_page_detect(page, f"{where}.detect")
    if not bool((det or {}).get('active')):
        return False

    if page_key:
        _last_heal[page_key] = nowv

    try:
        safe_log(lambda: f"[{now_ts()}] [EXT_CRASH_HEAL][DETECT] where={str(where)[:120]} reason={str((det or {}).get('reason') or '')[:120]} reload_btn={int(bool((det or {}).get('has_reload_button')))} budget_ms={_budget_left_ms()} strict={1 if strict else 0}")
    except Exception as _e:
        _record_swallowed_exception('ext_crash_page_self_heal.detect_log', _e)

    if bool((det or {}).get('has_reload_button')):
        _raise_if_budget_exhausted('before_reload_button')
        try:
            _clicked = _ext_crash_page_click_reload(page, f"{where}.reload_button", timeout_ms=min(3000, _budget_left_ms()), post_wait_ms=min(8000, max(2500, _budget_left_ms())))
        except Exception:
            _clicked = False
        if _clicked:
            _touch('EXT_CRASH_HEAL_RELOAD_BUTTON', 'clicked')
            det_after_btn = _ext_crash_page_detect(page, f"{where}.after_reload_button")
            if not bool((det_after_btn or {}).get('active')):
                try:
                    safe_log(lambda: f"[{now_ts()}] [EXT_CRASH_HEAL][OK] recovered_by=reload_button where={str(where)[:120]}")
                except Exception as _e:
                    _record_swallowed_exception('ext_crash_page_self_heal.reload_btn_ok_log', _e)
                _touch('EXT_CRASH_HEAL_OK', 'reload_button')
                return True

    _raise_if_budget_exhausted('before_reload')
    try:
        safe_log(lambda: f"[{now_ts()}] [EXT_CRASH_HEAL][ACT] step=reload where={str(where)[:120]} budget_ms={_budget_left_ms()}")
    except Exception as _e:
        _record_swallowed_exception('ext_crash_page_self_heal.reload_log', _e)
    try:
        _pw_reload(page, f"{where}.reload", timeout=min(12000, max(5000, _budget_left_ms())), evidence="CRASH")
        try:
            _pw_wait_ms(page, min(6000, max(2500, _budget_left_ms())), f"{where}.reload.wait")
        except Exception as _e:
            _record_swallowed_exception('ext_crash_page_self_heal.reload_wait', _e)
    except Exception as _e:
        _record_swallowed_exception('ext_crash_page_self_heal.reload', _e)
    _touch('EXT_CRASH_HEAL_RELOAD_DONE', 'after_reload')
    det_after_reload = _ext_crash_page_detect(page, f"{where}.after_reload")
    if not bool((det_after_reload or {}).get('active')):
        try:
            safe_log(lambda: f"[{now_ts()}] [EXT_CRASH_HEAL][OK] recovered_by=reload where={str(where)[:120]}")
        except Exception as _e:
            _record_swallowed_exception('ext_crash_page_self_heal.reload_ok_log', _e)
        _touch('EXT_CRASH_HEAL_OK', 'reload')
        return True

    if allow_same_tab_goto and str(target_url or '').strip():
        _raise_if_budget_exhausted('before_goto')
        try:
            safe_log(lambda: f"[{now_ts()}] [EXT_CRASH_HEAL][ACT] step=goto where={str(where)[:120]} url={str(target_url)[:120]} budget_ms={_budget_left_ms()}")
        except Exception as _e:
            _record_swallowed_exception('ext_crash_page_self_heal.goto_log', _e)
        try:
            _pw_goto(page, str(target_url), f"{where}.goto", timeout=min(5000, _budget_left_ms()))
            try:
                _pw_wait_ms(page, min(1200, max(200, _budget_left_ms())), f"{where}.goto.wait")
            except Exception as _e:
                _record_swallowed_exception('ext_crash_page_self_heal.goto_wait', _e)
        except Exception as _e:
            _record_swallowed_exception('ext_crash_page_self_heal.goto', _e)
        _touch('EXT_CRASH_HEAL_GOTO_DONE', 'after_goto')
        det_after_goto = _ext_crash_page_detect(page, f"{where}.after_goto")
        if not bool((det_after_goto or {}).get('active')):
            try:
                safe_log(lambda: f"[{now_ts()}] [EXT_CRASH_HEAL][OK] recovered_by=goto where={str(where)[:120]}")
            except Exception as _e:
                _record_swallowed_exception('ext_crash_page_self_heal.goto_ok_log', _e)
            _touch('EXT_CRASH_HEAL_OK', 'goto')
            return True

    try:
        safe_log(lambda: f"[{now_ts()}] [EXT_CRASH_HEAL][FAIL] where={str(where)[:120]} reason={str((det_after_reload or {}).get('reason') or (det or {}).get('reason') or '')[:120]} budget_left_ms={_budget_left_ms()} strict={1 if strict else 0}")
    except Exception as _e:
        _record_swallowed_exception('ext_crash_page_self_heal.fail_log', _e)
    _touch('EXT_CRASH_HEAL_FAIL', 'still_active')
    if strict:
        raise _UiLinkError(where, f"ext_crash_page_still_active:{str((det_after_reload or {}).get('reason') or (det or {}).get('reason') or '')[:120]}")
    return False

def _ext_temp_unavailable_self_heal(page: Any, where: str, *, target_url: str = "", force: bool = False,
                                    strict: bool = False, total_budget_ms: int = 8000, allow_same_tab_goto: bool = False) -> bool:
    """EXT 出现 GLOBAL.TEMPORARILY_UNAVAILABLE 时，先点 Try again，再刷新当前页；若仍失败，则交给外层新开标签页恢复。

    关键修复：
    - 给自愈链增加总预算，避免 reload/goto/探测把 worker 一直磨到外层 watchdog 超时；
    - strict=True 时，如果确认错误页仍然存在或预算耗尽，直接抛 _UiLinkError/_UiRecoverTimeoutError，快速失败。
    """
    try:
        _pw_require_page(page, where)
    except Exception:
        return False

    try:
        _deadline = float(time.time()) + max(0.8, float(int(total_budget_ms or 0)) / 1000.0)
    except Exception:
        _deadline = float(time.time()) + 8.0

    def _budget_left_ms() -> int:
        try:
            return max(1, int((_deadline - float(time.time())) * 1000.0))
        except Exception:
            return 1

    def _touch(_stage: str, _reason: str = "") -> None:
        try:
            _active_req_touch(_stage, reason=(_reason or where), where=where)
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_146a', _e)
            pass

    def _raise_if_budget_exhausted(_stage: str) -> None:
        if _budget_left_ms() > 0:
            return
        _touch('EXT_HEAL_TIMEOUT', _stage)
        raise _UiRecoverTimeoutError(where, f"ext_heal_budget_exhausted:{_stage}")

    try:
        nowv = float(time.time())
    except Exception:
        nowv = 0.0
    try:
        page_key = int(id(page))
    except Exception:
        page_key = 0
    try:
        cd = float(EXT_TEMP_UNAVAILABLE_HEAL_COOLDOWN_SEC or 2.5)
    except Exception:
        cd = 2.5
    if (not force) and page_key:
        last = float((_EXT_TEMP_UNAVAILABLE_LAST_HEAL or {}).get(page_key) or 0.0)
        if (nowv - last) < cd:
            return False

    _touch('EXT_HEAL_BEGIN', 'detect')
    det = _ext_temp_unavailable_detect(page, f"{where}.detect")
    if not bool((det or {}).get("active")):
        return False

    if page_key:
        _EXT_TEMP_UNAVAILABLE_LAST_HEAL[page_key] = nowv

    try:
        safe_log(lambda: f"[{now_ts()}] [EXT_HEAL][DETECT] where={str(where)[:120]} code={int(bool(det.get('has_code')))} desc={int(bool(det.get('has_desc')))} try_again={int(bool(det.get('has_try_again')))} budget_ms={_budget_left_ms()} strict={1 if strict else 0}")
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_147', _e)
        pass
    _raise_if_budget_exhausted('before_try_again')
    try:
        clicked = _ext_temp_unavailable_try_again(page, f"{where}.step1", timeout_ms=min(2500, _budget_left_ms()))
    except Exception:
        clicked = False
    if clicked:
        _touch('EXT_HEAL_TRY_AGAIN', 'clicked')
        det_after_click = _ext_temp_unavailable_detect(page, f"{where}.after_click")
        if not bool((det_after_click or {}).get("active")):
            try:
                safe_log(lambda: f"[{now_ts()}] [EXT_HEAL][OK] recovered_by=try_again where={str(where)[:120]}")
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_148', _e)
                pass
            _touch('EXT_HEAL_OK', 'try_again')
            return True

    _raise_if_budget_exhausted('before_reload')
    try:
        safe_log(lambda: f"[{now_ts()}] [EXT_HEAL][ACT] step=reload where={str(where)[:120]} budget_ms={_budget_left_ms()}")
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_149', _e)
        pass
    try:
        _pw_reload(page, f"{where}.reload", timeout=min(6000, _budget_left_ms()), evidence="CRASH")
        try:
            _pw_wait_ms(page, min(1200, max(200, _budget_left_ms())), f"{where}.reload.wait")
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_150', _e)
            pass
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_151', _e)
        pass
    _touch('EXT_HEAL_RELOAD_DONE', 'after_reload')
    det_after_reload = _ext_temp_unavailable_detect(page, f"{where}.after_reload")
    if not bool((det_after_reload or {}).get("active")):
        try:
            safe_log(lambda: f"[{now_ts()}] [EXT_HEAL][OK] recovered_by=reload where={str(where)[:120]}")
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_152', _e)
            pass
        _touch('EXT_HEAL_OK', 'reload')
        return True

    if allow_same_tab_goto and str(target_url or "").strip():
        _raise_if_budget_exhausted('before_goto')
        try:
            safe_log(lambda: f"[{now_ts()}] [EXT_HEAL][ACT] step=goto where={str(where)[:120]} url={str(target_url)[:120]} budget_ms={_budget_left_ms()}")
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_153', _e)
            pass
        try:
            _pw_goto(page, str(target_url), f"{where}.goto", timeout=min(5000, _budget_left_ms()))
            try:
                _pw_wait_ms(page, min(1200, max(200, _budget_left_ms())), f"{where}.goto.wait")
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_154', _e)
                pass
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_155', _e)
            pass
        _touch('EXT_HEAL_GOTO_DONE', 'after_goto')
        det_after_goto = _ext_temp_unavailable_detect(page, f"{where}.after_goto")
        if not bool((det_after_goto or {}).get("active")):
            try:
                safe_log(lambda: f"[{now_ts()}] [EXT_HEAL][OK] recovered_by=goto where={str(where)[:120]}")
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_156', _e)
                pass
            _touch('EXT_HEAL_OK', 'goto')
            return True

    try:
        safe_log(lambda: f"[{now_ts()}] [EXT_HEAL][FAIL] where={str(where)[:120]} keep_error=1 budget_left_ms={_budget_left_ms()} strict={1 if strict else 0}")
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_157', _e)
        pass
    _touch('EXT_HEAL_FAIL', 'still_active')
    if strict:
        raise _UiLinkError(where, 'ext_temp_unavailable_still_active')
    return False

def _pw_goto(page: Any, url: str, where: str, *, timeout: int = 60000) -> None:
    try:
        if ('variational.io' in str(url or '')) and bool((_platform_human_verify_active('VAR'))):
            _st = _platform_human_verify_guard('VAR', page, where=f'{where}.pre_goto')
            if bool((_st or {}).get('active')):
                try:
                    safe_log(lambda: f"[{now_ts()}] [PW][GOTO_SKIP] where={where} url={str(url or '')[:120]} reason=human_verify_active")
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_158', _e)
                    pass
                return
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_159', _e)
        pass
    """安全 goto：链接/导航类错误不允许吞（必须触发上层刷新/重建/重启）。"""
    _pw_require_page(page, where)
    try:
        _pw_call(where, page.goto, url, timeout=int(timeout))
    except (_UiDeadError, _UiLinkError):
        raise
    except Exception as _e:
        raise

