_M2_COIN_PLATFORM_FAULTS: Dict[str, Dict[str, Any]] = {}

def _m2_coin_platform_fault_key(platform: str, coin: str) -> str:
    try:
        return f"{str(platform or '').upper().strip()}|{str(coin or '').upper().strip()}"
    except Exception:
        return f"{platform}|{coin}"

def _m2_indicator_stage_budget(coin: str = "", snapshot: dict | None = None) -> dict:
    try:
        prof = _ind_refresh_profile_for_coin(str(coin or '').upper().strip(), snapshot or {}, now_ts=time.time())
    except Exception:
        prof = {}
    bucket = str((prof or {}).get('bucket') or 'warm')
    try:
        sw = int(M2_IND_SWITCH_TIMEOUT_MS)
    except Exception:
        sw = 12000
    try:
        lg = int(M2_IND_LEGEND_TIMEOUT_MS)
    except Exception:
        lg = 12000
    try:
        st = float(M2_IND_SETTLE_MAX_SEC)
    except Exception:
        st = 1.5
    try:
        dl = float(M2_IND_PER_COIN_DEADLINE_SEC)
    except Exception:
        dl = 6.5
    if bucket == 'hot':
        sw = max(2400, min(sw, 3600))
        lg = max(1800, min(lg, 2600))
        st = min(max(st, 0.75), 0.95)
        dl = min(max(dl, 6.2), 7.2)
    elif bucket == 'cold':
        sw = max(3200, min(sw, 4800))
        lg = max(2200, min(lg, 3200))
        st = min(max(st, 0.95), 1.25)
        dl = min(max(dl, 7.0), 8.8)
    else:
        sw = max(2800, min(sw, 4200))
        lg = max(2000, min(lg, 2600))
        st = min(max(st, 0.85), 1.10)
        dl = min(max(dl, 6.6), 8.0)
    return {
        'switch_timeout_ms': int(sw),
        'legend_timeout_ms': int(lg),
        'settle_max_sec': float(st),
        'per_coin_deadline_sec': float(dl),
        'bucket': bucket,
    }

def _m2_indicator_deadline_left_ms(deadline_ts: float | None, *, reserve_ms: int = 0, floor_ms: int = 250) -> int:
    if _module_timeouts_disabled('M2'):
        return int(24 * 3600 * 1000)
    if not deadline_ts:
        return int(max(0, floor_ms))
    try:
        left = int(max(0.0, (float(deadline_ts) - float(time.monotonic())) * 1000.0)) - int(max(0, reserve_ms))
    except Exception:
        left = 0
    return int(max(0, left if left > 0 else 0)) if floor_ms <= 0 else int(max(0, left))

def _m2_indicator_deadline_left_sec(deadline_ts: float | None, *, reserve_sec: float = 0.0) -> float:
    if _module_timeouts_disabled('M2'):
        return float(24 * 3600)
    if not deadline_ts:
        return 0.0
    try:
        return max(0.0, float(deadline_ts) - float(time.monotonic()) - max(0.0, float(reserve_sec or 0.0)))
    except Exception:
        return 0.0

def _m2_indicator_phase_budget(snapshot: dict | None = None, coins: list[str] | None = None, *, reason: str = '') -> dict:
    """M2 指标阶段预算：按缓存窗口/过期驱动刷新，不再每轮强制全量扫描所有目标币。"""
    _coins = [str(x).upper() for x in list(coins or []) if str(x).strip()]
    _coins_cnt = int(len(_coins))
    max_batch = int(_coins_cnt) if _coins_cnt > 0 else 0
    try:
        phase_budget_sec = float(cfg_getf_runtime('M2_INDICATOR_PHASE_BUDGET_SEC', max(24.0, float(max_batch) * 6.0)) or max(24.0, float(max_batch) * 6.0))
    except Exception:
        phase_budget_sec = max(24.0, float(max_batch) * 6.0)
    if _module_timeouts_disabled('M2'):
        phase_budget_sec = float(24 * 3600)
    else:
        phase_budget_sec = max(8.0, min(90.0, float(phase_budget_sec)))
    tail_budget_sec = 0.0
    return {
        'max_batch': int(max_batch),
        'phase_budget_sec': float(phase_budget_sec),
        'tail_budget_sec': float(tail_budget_sec),
        'reason': str(reason or ''),
        'coins_cnt': int(_coins_cnt),
        'force_full_scan': False,
        'force_full_reason': 'stale_window_refresh' if _coins_cnt > 0 else '',
    }

def _m2_indicator_snapshot_from_cache(coin: str, now_ts_v: float, *, reason: str = '', extra: dict | None = None) -> dict:
    """统一把缓存里的最近指标写进 snapshot；没有缓存也返回空值，避免指标尾链拖死主扫描。"""
    try:
        latest = ((_ind_cache_latest_dict() or {}).get(str(coin).upper()) or {})
    except Exception:
        latest = {}
    _latest_val_ts = None
    _latest_fetch_ts = None
    _latest_age_sec = None
    try:
        if isinstance(latest, dict):
            _vt = latest.get('val_ts')
            _ft = latest.get('fetch_ts')
            _latest_val_ts = (float(_vt) if _vt is not None else None)
            _latest_fetch_ts = (float(_ft) if _ft is not None else None)
            if _latest_val_ts is not None:
                _latest_age_sec = max(0.0, float(now_ts_v) - float(_latest_val_ts))
    except Exception:
        _latest_val_ts = None
        _latest_fetch_ts = None
        _latest_age_sec = None
    _display_invalid = bool((latest or {}).get('display_invalid')) if isinstance(latest, dict) else False
    _display_invalid_reason = str((latest or {}).get('display_invalid_reason') or (latest or {}).get('last_public_fail_reason') or '') if isinstance(latest, dict) else ''
    row = {
        'adx': (None if _display_invalid else (latest.get('adx') if isinstance(latest, dict) else None)),
        'rsi': (None if _display_invalid else (latest.get('rsi') if isinstance(latest, dict) else None)),
        'reason': str((_display_invalid_reason or reason or '') if _display_invalid else (reason or '')),
        'ts': float(now_ts_v),
        'fetch_ts': float(now_ts_v),
        'ind_ts': float(_latest_fetch_ts if _latest_fetch_ts is not None else now_ts_v),
        'val_ts': float(_latest_val_ts) if _latest_val_ts is not None else None,
        'ind_age_sec': float(_latest_age_sec) if _latest_age_sec is not None else None,
        'ind_used_last_good': int(bool((latest or {}).get('used_last_good'))) if isinstance(latest, dict) else 0,
        'source': str((latest or {}).get('source') or (latest or {}).get('source_kind') or '') if isinstance(latest, dict) else '',
        'source_kind': str((latest or {}).get('source_kind') or '') if isinstance(latest, dict) else '',
        'source_symbol': str((latest or {}).get('source_symbol') or '') if isinstance(latest, dict) else '',
        'source_interval': str((latest or {}).get('source_interval') or '') if isinstance(latest, dict) else '',
        'calc_ts': float((latest or {}).get('calc_ts') or (_latest_fetch_ts if _latest_fetch_ts is not None else now_ts_v)) if isinstance(latest, dict) else float(now_ts_v),
        'calc_time': _ind_display_time_text((latest or {}).get('calc_ts') if isinstance(latest, dict) else now_ts_v),
        'bar_close_ts': float((latest or {}).get('bar_close_ts') or 0.0) if isinstance(latest, dict) else 0.0,
        'bar_close_time': _ind_display_time_text((latest or {}).get('bar_close_ts') if isinstance(latest, dict) else 0.0),
        'ui_fallback_used': int(bool((latest or {}).get('ui_fallback_used'))) if isinstance(latest, dict) else 0,
        'ui_fallback_reason': str((latest or {}).get('ui_fallback_reason') or '') if isinstance(latest, dict) else '',
        'display_source': str((latest or {}).get('source') or (latest or {}).get('source_kind') or '') if isinstance(latest, dict) else '',
        'display_update_ts': float((latest or {}).get('calc_ts') or (_latest_fetch_ts if _latest_fetch_ts is not None else now_ts_v)) if isinstance(latest, dict) else float(now_ts_v),
        'display_update_time': _ind_display_time_text((latest or {}).get('calc_ts') if isinstance(latest, dict) else now_ts_v),
        'display_ui_fallback_text': ('是' if bool((latest or {}).get('ui_fallback_used')) else '否') if isinstance(latest, dict) else '否',
        'display_invalid': int(bool(_display_invalid)),
        'display_invalid_reason': str(_display_invalid_reason or ''),
        'display_invalid_ts': float((latest or {}).get('display_invalid_ts') or 0.0) if isinstance(latest, dict) else 0.0,
        'display_invalid_time': _ind_display_time_text((latest or {}).get('display_invalid_ts') if isinstance(latest, dict) else 0.0),
    }
    if isinstance(latest, dict):
        try:
            _nri = latest.get('next_refresh_in_sec')
            if _nri is not None:
                row['next_refresh_in'] = int(float(_nri))
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_160', _e)
            pass
        try:
            _b = latest.get('bucket') or latest.get('refresh_bucket')
            if _b:
                row['refresh_bucket'] = str(_b)
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_161', _e)
            pass
    if isinstance(extra, dict) and extra:
        try:
            row.update(dict(extra))
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_162', _e)
            pass
    return row

def _m2_coin_platform_mark_fail(platform: str, coin: str, *, reason: str = "", fault_kind: str = "", now_ts_v: float | None = None) -> dict:
    nowv = float(now_ts_v if now_ts_v is not None else time.time())
    key = _m2_coin_platform_fault_key(platform, coin)
    cur = dict((_M2_COIN_PLATFORM_FAULTS or {}).get(key) or {})
    streak = int(cur.get('fail_streak') or 0) + 1
    cur.update({
        'platform': str(platform or '').upper().strip(),
        'coin': str(coin or '').upper().strip(),
        'fail_streak': int(streak),
        'last_fail_ts': float(nowv),
        'last_reason': str(reason or ''),
        'last_fault_kind': str(fault_kind or ''),
    })
    if str(fault_kind or '') in ('page_crashed', 'oom', 'ui_dead', 'target_closed'):
        streak = max(streak, int(M2_IND_FUSE_FAIL_STREAK))
        cur['fail_streak'] = int(streak)
    if str(platform or '').upper().strip() == 'VAR' and str(coin or '').upper().strip() == 'SUI' and str(fault_kind or '') in ('legend_not_ready', 'coin_not_confirmed', 'indicator_partial', 'switch_fail', 'refresh_exc'):
        if streak >= max(2, int(M2_IND_FUSE_FAIL_STREAK) - 1):
            streak = max(streak, int(M2_IND_FUSE_FAIL_STREAK))
            cur['fail_streak'] = int(streak)
    if streak >= int(M2_IND_FUSE_FAIL_STREAK):
        mult = min(4, max(1, streak - int(M2_IND_FUSE_FAIL_STREAK) + 1))
        fuse_sec = min(int(M2_IND_FUSE_MAX_SEC), int(M2_IND_FUSE_BASE_SEC) * int(mult))
        cur['fused_until_ts'] = float(nowv) + float(fuse_sec)
        cur['fuse_sec'] = int(fuse_sec)
    _M2_COIN_PLATFORM_FAULTS[key] = cur
    return dict(cur)

def _m2_coin_platform_mark_ok(platform: str, coin: str) -> None:
    try:
        key = _m2_coin_platform_fault_key(platform, coin)
        (_M2_COIN_PLATFORM_FAULTS or {}).pop(key, None)
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_163', _e)
        pass
def _m2_coin_platform_should_skip(platform: str, coin: str, *, now_ts_v: float | None = None) -> dict:
    nowv = float(now_ts_v if now_ts_v is not None else time.time())
    key = _m2_coin_platform_fault_key(platform, coin)
    cur = dict((_M2_COIN_PLATFORM_FAULTS or {}).get(key) or {})
    try:
        until = float(cur.get('fused_until_ts') or 0.0)
    except Exception:
        until = 0.0
    left = max(0.0, until - nowv)
    return {
        'skip': bool(left > 0.0),
        'left_sec': int(left),
        'fail_streak': int(cur.get('fail_streak') or 0),
        'last_reason': str(cur.get('last_reason') or ''),
        'fault_kind': str(cur.get('last_fault_kind') or ''),
        'fused_until_ts': float(until),
    }

def _ui_page_crash_probe(page: Any, *, coin: str = "", platform: str = "VAR", sample_chars: int = 800) -> dict:
    out = {'crashed': False, 'reason': '', 'title': '', 'url': '', 'body_excerpt': ''}
    try:
        if page is None or _pw_is_closed(page):
            out['crashed'] = True
            out['reason'] = 'page_closed'
            return out
    except Exception:
        out['crashed'] = True
        out['reason'] = 'page_closed'
        return out
    try:
        out['url'] = str(getattr(page, 'url', '') or '')
    except Exception:
        out['url'] = ''
    try:
        try:
            out['title'] = str(page.title() or '')[:200]
        except Exception:
            out['title'] = str(_pw_call(f"ui.crash_probe.title.{str(platform or '').upper()}.{str(coin or '').upper()}", page.title) or '')[:200]
    except _UiDeadError:
        out['crashed'] = True
        out['reason'] = 'ui_dead_on_title'
        return out
    except Exception:
        out['title'] = ''
    try:
        js = f"() => {{ try {{ const t = (document && document.body && document.body.innerText) ? document.body.innerText : ''; return String(t || '').slice(0, {int(sample_chars)}); }} catch (e) {{ return ''; }} }}"
        try:
            out['body_excerpt'] = str(page.evaluate(js) or '')
        except Exception:
            out['body_excerpt'] = str(_pw_call(f"ui.crash_probe.body.{str(platform or '').upper()}.{str(coin or '').upper()}", page.evaluate, js) or '')
    except _UiDeadError:
        out['crashed'] = True
        out['reason'] = 'ui_dead_on_body'
        return out
    except Exception:
        out['body_excerpt'] = ''
    txt = ((out.get('title') or '') + '\n' + (out.get('body_excerpt') or '')).lower()
    hits = []
    for pat, rsn in (
        ('out of memory', 'out_of_memory'),
        ('aw, snap', 'aw_snap'),
        ('崩溃啦', 'page_crashed_zh'),
        ('重新加载', 'reload_crash_page'),
        ("he's dead jim", "dead_jim"),
    ):
        if pat in txt:
            hits.append(rsn)
    if hits:
        out['crashed'] = True
        out['reason'] = '+'.join(hits)
        return out
    try:
        _hv = _ui_human_verify_probe(page, platform=platform, coin=coin, sample_chars=min(1600, max(300, int(sample_chars))))
        if bool((_hv or {}).get('active')):
            out['reason'] = f"human_verify:{str((_hv or {}).get('reason') or '')}"
            out['title'] = str((_hv or {}).get('title') or out.get('title') or '')[:200]
            out['url'] = str((_hv or {}).get('url') or out.get('url') or '')
            out['body_excerpt'] = str((_hv or {}).get('excerpt') or out.get('body_excerpt') or '')[:sample_chars]
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_164', _e)
        pass
    return out

def _browser_close_page(page, *, reason='', platform=''):
    """Audit every close request; recovery cannot close managed exchange tabs."""
    _WORKER_STATE.assert_live()
    if page is None:
        return False
    pk = _ensure_page_health_platform(page, platform)
    caller = sys._getframe(1)
    detail = dict(platform=pk, page_id=hex(id(page)), thread_id=threading.get_ident(),
                  caller=caller.f_code.co_name, line=caller.f_lineno, reason=str(reason),
                  url=_browser_safe_url(getattr(page, 'url', '')))
    try:
        detail['target_id'] = _PAGE_IDENTITIES.key(page, pk, _pw_call).split(':', 1)[-1]
    except Exception:
        detail['target_id'] = 'unknown'
    _ext_recovery_log('PAGE_CLOSE_REQUEST', **detail)
    retained = any(getattr(globals().get(f'_{p}_RECOVERY'), 'candidate_id', None) == detail['target_id']
                   for p in ('EXT', 'VAR'))
    if pk in ('EXT', 'VAR') or retained:
        _ext_recovery_log('PAGE_CLOSE_BLOCKED', **detail, policy='preserve_exchange_target')
        return False
    try:
        page.close()
        _ext_recovery_log('PAGE_CLOSE_RESULT', **detail, ok=True)
        _ensure_page_health_forget(page)
        return True
    except Exception as exc:
        _ext_recovery_log('PAGE_CLOSE_RESULT', **detail, ok=False, error=type(exc).__name__)
        return False


def _page_safe_close(page: Any) -> None:
    _WORKER_STATE.assert_live()
    try:
        if page is None:
            return
        if _pw_is_closed(page):
            return
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_165', _e)
        pass
    try:
        _browser_close_page(page, reason='page_safe_close:' + sys._getframe(1).f_code.co_name)
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_166', _e)
        pass
def _page_health_check(page: Any, *, coin: str = "", platform: str = "", expected_url_keywords: list[str] | tuple[str, ...] | None = None, title_sample_chars: int = 200) -> dict:
    out = {
        'ok': False,
        'reason': '',
        'detail': '',
        'url': '',
        'title': '',
        'crashed': False,
        'page_closed': False,
        'url_mismatch': False,
    }
    if page is None:
        out['reason'] = 'page_missing'
        return out
    try:
        if _pw_is_closed(page):
            out['reason'] = 'page_closed'
            out['page_closed'] = True
            return out
    except Exception:
        out['reason'] = 'page_closed'
        out['page_closed'] = True
        return out
    try:
        det = _ui_page_crash_probe(page, coin=str(coin or '').upper(), platform=str(platform or '').upper())
    except Exception as e:
        det = {'crashed': False, 'reason': f'crash_probe_exc:{type(e).__name__}'}
    if bool((det or {}).get('crashed')):
        out['reason'] = str((det or {}).get('reason') or 'page_crashed')
        out['detail'] = str((det or {}).get('body_excerpt') or '')[:240]
        out['url'] = str((det or {}).get('url') or '')
        out['title'] = str((det or {}).get('title') or '')[:title_sample_chars]
        out['crashed'] = True
        return out
    try:
        out['url'] = str(getattr(page, 'url', '') or '')
    except Exception:
        out['url'] = ''
    try:
        out['title'] = str(page.title() or '')[:title_sample_chars]
    except Exception:
        out['title'] = ''
    kws = [str(x or '').lower().strip() for x in (expected_url_keywords or []) if str(x or '').strip()]
    if kws:
        u = str(out.get('url') or '').lower()
        _plat_u = str(platform or '').upper().strip()
        _ext_join_ok = bool(_plat_u == 'EXT' and ('extended.exchange' in u) and (('/perp/' in u) or ('/join/' in u)))
        if (not _ext_join_ok) and (not any(k in u for k in kws)):
            out['reason'] = 'url_mismatch'
            out['url_mismatch'] = True
            out['detail'] = u[:240]
            return out
    try:
        _ = page.evaluate('() => document.readyState')
    except Exception as e:
        if _is_ui_dead_exc(e):
            out['reason'] = 'ui_dead_eval'
            out['detail'] = f'{type(e).__name__}:{e}'[:240]
            return out
    out['ok'] = True
    return out

def _rebuild_single_page_in_context(context: Any, *, target_url: str, platform: str = '', coin: str = '', expected_url_keywords: list[str] | tuple[str, ...] | None = None, timeout_ms: int = 15000) -> tuple[Any | None, str]:
    if str(platform).upper() in ('EXT', 'VAR'):
        pk = str(platform).upper()
        try:
            browser = getattr(context, 'browser', None)
            if browser is None or not browser.is_connected():
                return None, f'{pk.lower()}_browser_connection_unavailable'
            page = ensure_page(browser, 'app.extended.exchange' if pk == 'EXT' else 'omni.variational.io', target_url)
            health = _page_health_check(page, coin=coin, platform=pk, expected_url_keywords=expected_url_keywords)
            return (page, '') if health.get('ok') else (None, f'{pk.lower()}_recovery_health_unknown:' + str(health.get('reason')))
        except Exception as exc:
            return None, f'{pk.lower()}_preserved_recovery_failed:{type(exc).__name__}:{exc}'
    try:
        pages = list(getattr(context, 'pages', []) or []) if context is not None else []
    except Exception:
        pages = []
    for oldp in pages:
        try:
            _u = str(getattr(oldp, 'url', '') or '').lower()
        except Exception:
            _u = ''
        try:
            if platform and platform.upper() == 'VAR' and ('variational' in _u or '/perpetual/' in _u):
                _page_safe_close(oldp)
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_167', _e)
            pass
    try:
        newp = context.new_page()
    except Exception as e:
        return None, f'new_page_fail:{type(e).__name__}:{e}'
    try:
        _pw_front(newp, f"rebuild_page.front.{str(platform or '').upper()}.{str(coin or '').upper()}")
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_168', _e)
        pass
    try:
        _pw_goto(newp, str(target_url or ''), f"rebuild_page.goto.{str(platform or '').upper()}.{str(coin or '').upper()}", timeout=int(timeout_ms or 15000))
    except Exception as e:
        try:
            newp.goto(str(target_url or ''), timeout=int(timeout_ms or 15000), wait_until='domcontentloaded')
        except Exception:
            _page_safe_close(newp)
            return None, f'goto_fail:{type(e).__name__}:{e}'
    hc = _page_health_check(newp, coin=coin, platform=platform, expected_url_keywords=expected_url_keywords)
    if not bool((hc or {}).get('ok')):
        _page_safe_close(newp)
        return None, str((hc or {}).get('reason') or 'page_health_fail')
    return newp, ''

def _ensure_executor_pages_healthy(rt: dict[str, Any], *, cdp: str = '', logfp: Any = None) -> tuple[dict[str, Any], bool, str]:
    if not isinstance(rt, dict):
        return {}, False, 'runtime_missing'
    rt = dict(rt)
    rt['page_health_ok'] = False
    legacy_deleteded = False
    reason_parts: list[str] = []
    context = rt.get('context')
    browser = rt.get('browser')
    if context is None:
        try:
            if not browser or not browser.contexts:
                return rt, False, 'existing_browser_context_missing'
            context = browser.contexts[0]
            rt['context'] = context
            legacy_deleteded = True
        except Exception as e:
            return rt, legacy_deleteded, f'context_missing:{type(e).__name__}:{e}'
    checks = [
        ('ext_page', 'EXT', _ext_effective_open_url(default_url=str(EXT.get('open_url') or EXT_NORMAL_OPEN_URL), page=rt.get('ext_page'), pages=getattr(context, 'pages', []) if context is not None else [], source='ensure_executor_pages_healthy'), ['extended.exchange', '/perp/']),
        ('var_page', 'VAR', 'https://omni.variational.io/perpetual/BTC', ['variational.io', '/perpetual/']),
    ]
    for page_key, plat, fallback_url, kws in checks:
        page = rt.get(page_key)
        hc = _page_health_check(page, platform=plat, expected_url_keywords=kws)
        if bool((hc or {}).get('ok')):
            continue
        reason_parts.append(f'{page_key}:{str((hc or {}).get("reason") or "bad")}' )
        try:
            legacy_deleteded_page, rsn = _rebuild_single_page_in_context(context, target_url=fallback_url, platform=plat, coin='BTC', expected_url_keywords=kws, timeout_ms=15000)
        except Exception as e:
            legacy_deleteded_page, rsn = None, f'rebuild_exc:{type(e).__name__}:{e}'
        if legacy_deleteded_page is None:
            rt[page_key] = None
            rt['ext_exe' if plat == 'EXT' else 'var_exe'] = None
            return rt, legacy_deleteded, f'{page_key}_legacy_deleted_fail:{rsn or str((hc or {}).get("reason") or "unknown")}'
        rt[page_key] = legacy_deleteded_page
        legacy_deleteded = True
    try:
        rt['pages'] = list(getattr(context, 'pages', []) or [])
    except Exception:
        rt['pages'] = []
    try:
        rt['ext_exe'] = _ExtExecutor(rt.get('ext_page'), timeout_ms=15000) if rt.get('ext_page') is not None else None
        rt['var_exe'] = _VarExecutor(rt.get('var_page'), timeout_ms=15000) if rt.get('var_page') is not None else None
    except Exception as e:
        return rt, legacy_deleteded, f'executor_rebind_fail:{type(e).__name__}:{e}'
    if rt.get('ext_page') is None or rt.get('var_page') is None:
        return rt, legacy_deleteded, 'page_still_missing'
    rt['page_health_ok'] = True
    return rt, legacy_deleteded, ('|'.join(reason_parts) if reason_parts else '')

def _ensure_m2_pages_healthy(browser: Any, ext_page: Any, var_page: Any, *, logfp: Any = None, stage: str = '', coin: str = '', platforms: tuple[str, ...] = ('EXT', 'VAR')) -> tuple[Any, Any, bool, str]:
    legacy_deleteded = False
    reasons: list[str] = []
    try:
        context = browser.contexts[0] if browser and getattr(browser, 'contexts', None) else None
    except Exception:
        context = None
    if context is None:
        return None, None, legacy_deleteded, 'context_missing'
    checks = []
    if 'EXT' in tuple(platforms or ()):
        checks.append(('EXT', ext_page, _ext_effective_open_url(default_url=str(EXT.get('open_url') or EXT_NORMAL_OPEN_URL), page=ext_page, pages=getattr(context, 'pages', []) if context is not None else [], source='ensure_m2_pages_healthy'), ['extended.exchange', '/perp/']))
    if 'VAR' in tuple(platforms or ()):
        checks.append(('VAR', var_page, str(VAR.get('open_url') or 'https://omni.variational.io/perpetual/BTC'), ['variational.io', '/perpetual/']))
    new_ext, new_var = ext_page, var_page
    for plat, page, fallback_url, kws in checks:
        hc = _page_health_check(page, coin=str(coin or ''), platform=plat, expected_url_keywords=kws)
        if bool((hc or {}).get('ok')):
            continue
        rsn = str((hc or {}).get('reason') or 'bad_page')
        reasons.append(f'{plat}:{rsn}')
        try:
            if logfp:
                write_jsonl(logfp, {'ts': now_ts(), 'mod': 'M2', 'type': 'page_health_legacy_deleted', 'stage': str(stage or ''), 'plat': plat, 'coin': str(coin or '').upper(), 'reason': rsn, 'detail': str((hc or {}).get('detail') or '')[:240], 'url': str((hc or {}).get('url') or '')[:240]})
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_169', _e)
            pass
        try:
            rebuilt, rebuild_rsn = _rebuild_single_page_in_context(context, target_url=fallback_url, platform=plat, coin=str(coin or '').upper(), expected_url_keywords=kws, timeout_ms=15000)
        except Exception as e:
            rebuilt, rebuild_rsn = None, f'rebuild_exc:{type(e).__name__}:{e}'
        if rebuilt is None:
            return (None if plat == 'EXT' else new_ext), (None if plat == 'VAR' else new_var), legacy_deleteded, f'{plat}_legacy_deleted_fail:{rebuild_rsn or rsn}'
        if plat == 'EXT':
            new_ext = rebuilt
        else:
            new_var = rebuilt
        legacy_deleteded = True
        try:
            if logfp:
                write_jsonl(logfp, {'ts': now_ts(), 'mod': 'M2', 'type': 'page_health_legacy_deleted_ok', 'stage': str(stage or ''), 'plat': plat, 'coin': str(coin or '').upper(), 'reason': rsn, 'new_url': str(getattr(rebuilt, 'url', '') or '')[:240]})
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_170', _e)
            pass
    return new_ext, new_var, legacy_deleteded, '|'.join(reasons)

