_last_exec_res = globals().get("_last_exec_res", {}) if isinstance(globals().get("_last_exec_res", {}), dict) else {}

def wall_mark() -> float:
    return float(time.time())

def wall_ms(t0: float) -> int:
    try:
        return int(max(0.0, (time.time() - float(t0))) * 1000.0)
    except Exception:
        return 0

def _to_epoch_ts(x: object, *, default: float | None = None) -> float:
    """把各种时间口径（epoch/字符串/datetime）统一到 epoch(float)。"""
    if default is None:
        default = time.time()
    try:
        if x is None:
            return float(default)
        if isinstance(x, (int, float)):
            return float(x)
        try:
            import datetime as _dt
            if isinstance(x, _dt.datetime):
                return float(x.timestamp())
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_177', _e)
            pass
        s = str(x).strip()
        if not s:
            return float(default)
        try:
            return float(s)
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_178', _e)
            pass
        try:
            import datetime as _dt
            return float(_dt.datetime.strptime(s, "%Y-%m-%d %H:%M:%S").timestamp())
        except Exception:
            try:
                import datetime as _dt
                return float(_dt.datetime.strptime(s, "%Y/%m/%d %H:%M:%S").timestamp())
            except Exception:
                return float(default)
    except Exception:
        return float(default)

_RAND_LAST_U: dict[str, int] = {}
def _rand_u_avoid_last(tag: str, plat: str, lo: int, hi: int, *, step: int = 10) -> int:
    try:
        lo_i = int(lo); hi_i = int(hi)
        if hi_i < lo_i:
            lo_i, hi_i = hi_i, lo_i
        if step <= 0:
            step = 1
        lo_i = int(math.floor(lo_i / step) * step)
        hi_i = int(math.floor(hi_i / step) * step)
        if hi_i < lo_i:
            hi_i = lo_i
        key = f"{str(tag)}|{str(plat).upper()}|{lo_i}|{hi_i}|{step}"
        last = _RAND_LAST_U.get(key)
        choices = list(range(lo_i, hi_i + 1, step))
        if not choices:
            pick = lo_i
        elif len(choices) == 1:
            pick = choices[0]
        else:
            pick = random.choice(choices)
            if last is not None and int(pick) == int(last):
                for _ in range(3):
                    p2 = random.choice(choices)
                    if int(p2) != int(last):
                        pick = p2
                        break
        _RAND_LAST_U[key] = int(pick)
        return int(pick)
    except Exception:
        try:
            return int(lo)
        except Exception:
            _set_main_quanbu_exit_reason("daily_review_selftest_end")
            return 0

_EXEC_PENDING: dict[tuple[str, ...], float] = {}  # open=(PLAT,COIN,SIDE); close adds 'close'
_EXEC_PENDING_TTL_SEC: int = 90

_EXEC_PENDING_INFO: dict[tuple[str, ...], dict] = {}  # Same operation-scoped keys as _EXEC_PENDING

_EXEC_LAST_UNCONFIRMED: dict | None = None

def _exec_set_last_unconfirmed(kind: str, plat: str, coin: str, side: str, detail: dict | None = None, info: dict | None = None) -> None:
    """记录最近一次 unconfirmed（提交后超时未确认）。kind: open/close."""
    global _EXEC_LAST_UNCONFIRMED
    try:
        _EXEC_LAST_UNCONFIRMED = {
            "ts": time.time(),
            "kind": str(kind or ""),
            "plat": str(plat or "").upper(),
            "coin": str(coin or "").upper(),
            "side": str(side or "").upper(),
            "detail": (detail or {}),
            "info": (info or {}),
        }
    except Exception:
        _EXEC_LAST_UNCONFIRMED = None

def _exec_clear_last_unconfirmed() -> None:
    global _EXEC_LAST_UNCONFIRMED
    _EXEC_LAST_UNCONFIRMED = None

def _exec_last_unconfirmed_match(plat: str, coin: str, side: str, *, max_age_sec: float = 180.0) -> tuple[bool, dict]:
    """判断最近 unconfirmed 是否匹配当前请求（用于写更准确 reason）。"""
    try:
        u = _EXEC_LAST_UNCONFIRMED or None
        if not isinstance(u, dict):
            return False, {}
        if str(u.get("plat","")).upper() != str(plat or "").upper():
            return False, {}
        if str(u.get("coin","")).upper() != str(coin or "").upper():
            return False, {}
        if str(u.get("side","")).upper() != str(side or "").upper():
            return False, {}
        ts = float(u.get("ts") or 0.0)
        if ts <= 0:
            return False, {}
        if (time.time() - ts) > float(max_age_sec or 180.0):
            return False, {}
        return True, u
    except Exception:
        return False, {}

def _exec_row_side_notional(row: Any) -> tuple[str, float]:
    """从 read_coin_row_basic 的 row 中抽取 side/notional_u。失败则返回 ('NONE',0)."""
    try:
        if not isinstance(row, dict):
            return "NONE", 0.0
        s = str(row.get("side") or "NONE").upper().strip()
        n = float(row.get("notional_u") or 0.0)
        return s, n
    except Exception:
        return "NONE", 0.0

def _exec_record_timeout_pending_unconfirmed(*, plat: str, coin: str, order: Any, side: str, usd: float, kind: str, det: dict, ev: dict) -> None:
    """[PATCH][P0] 回执超时且二次核验暂未确认（UNCONFIRMED）时：
    - 不把它当作失败（避免模块计入 fail 并重复下单）
    - 但仍落盘到 executor_results.jsonl 供你审计（标记 pending/unconfirmed）

    注意：该记录不写入 trades.jsonl（避免面板把“未确认”当成已成交）。
    """
    try:
        p = str(plat or "").upper().strip()
        c = str(coin or "").upper().strip()
        det_d = _as_dict(det, mod="EXEC", coin=c, ctx="timeout_unconfirmed.det")
        ev_d = _as_dict(ev, mod="EXEC", coin=c, ctx="timeout_unconfirmed.ev")
        s = str(side or "").lower().strip()
        u = float(usd or 0.0)
        reduce_only = bool(getattr(order, "reduce_only", False))
        act = "decrease" if (reduce_only or str(kind or "").lower().startswith("close")) else "increase"

        note = ""
        try:
            note = str(getattr(order, "guard_note", "") or "")
        except Exception:
            note = ""
        if not note:
            note = "UNCONFIRMED_TIMEOUT"

        _order_meta = getattr(order, 'meta', {}) if isinstance(getattr(order, 'meta', None), dict) else {}
        _gid = str(getattr(order, 'grid_id', '') or det_d.get('grid_id') or _order_meta.get('grid_id') or '').strip()
        _lid = str(getattr(order, 'layer_id', '') or det_d.get('layer_id') or _order_meta.get('layer_id') or '').strip()
        _lno = int(getattr(order, 'layer_no', 0) or det_d.get('layer_no') or _grid_layer_no(_lid) or 0)
        req = {
            "platform": p,
            "module": (str(getattr(order, 'module', '') or (det_d.get('module') or '') or '').upper().strip()),
            "coin": c,
            "side": s,
            "action_type": act,
            "amount_usd": u,
            "amount_u": u,
            "reduce_only": bool(reduce_only),
            "grid_id": _gid,
            "layer_id": _lid,
            "layer_no": _lno,
            "meta": {
                "grid_id": _gid,
                "layer_id": _lid,
                "layer_no": _lno,
                "from": note,
                "trace_id": (str(getattr(order, 'trace_id', '') or getattr(order, 'tid', '') or '')),
                "orig_module": (str(getattr(order, 'module', '') or '').upper().strip()),
                "orig_action_type": (str(getattr(order, 'action_type', '') or kind or '').lower().strip()),
                "ind_rsi": ((getattr(order, "meta", {}) or {}).get("ind_rsi") if isinstance(getattr(order, "meta", None), dict) else None),
                "ind_adx": ((getattr(order, "meta", {}) or {}).get("ind_adx") if isinstance(getattr(order, "meta", None), dict) else None),
                "ind_ts": ((getattr(order, "meta", {}) or {}).get("ind_ts") if isinstance(getattr(order, "meta", None), dict) else None),
                "ind_age_sec": ((getattr(order, "meta", {}) or {}).get("ind_age_sec") if isinstance(getattr(order, "meta", None), dict) else None),
                "pending_unconfirmed": True,
                "verify": ev_d,
            },
        }
        try:
            req = _exec_enrich_req_price_fields(req, order, det_d)
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_179', _e)
            pass
        try:
            req = _executor_enrich_request_contract(req)
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_180', _e)
            pass
        try:
            _pf0 = _estimate_profit_u_for_req(req)
            if _pf0 is not None:
                req.setdefault('meta', {})
                if isinstance(req.get('meta'), dict):
                    req['meta']['est_profit_u'] = float(_pf0)
                    req['meta']['est_realized_pnl_u'] = float(_pf0)
                    req['meta']['fill_reconcile_state'] = 'pending_fill'
                    req['meta']['actual_fill_required'] = True
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_181', _e)
            pass
        res = {
            "ok": True,
            "reason": "submitted_pending_confirm",
            "submit_ok": True, "pending_confirm": True, "confirmed_success": False,
            "confirmation_state": "submitted_pending_confirm", "trade_effective": False,
            "verified": False,
            "pending": True,
            "ts": float(time.time()),
            "req": req,
            "det": det_d,
            "verify": ev_d,
            "exec_u": u,
            "notional_u": u,
        }
        try:
            fp1 = os.path.join(LOGS_DIR, "executor_results.jsonl")
            os.makedirs(os.path.dirname(os.path.abspath(fp1)) or ".", exist_ok=True)
            with open(fp1, "a", encoding="utf-8") as f:
                f.write(_json_dumps_bot({"ts": time.time(), "kind": "executor_result", **res}) + "\n")
        except Exception as _e:
            _log_exc_level(mod="EXEC", stage="EXEC_CONFIRM_PIN_FAIL", level="C", e=_e)
        try:
            fp2 = os.path.join(str(OUT_DIR), "executor_results.jsonl")
            os.makedirs(os.path.dirname(os.path.abspath(fp2)) or ".", exist_ok=True)
            with open(fp2, "a", encoding="utf-8") as f:
                f.write(_json_dumps_bot({"ts": time.time(), "kind": "executor_result", **res}) + "\n")
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_182', _e)
            pass
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_183', _e)
        pass
def _exec_refresh_indicators_for_order(order: Any, coin: str, *, why: str = "") -> None:
    """执行器下单前补指标，但默认不再为了补指标去硬切页/硬刷新。

    旧口径的问题：
    - 只要 age > IND_EXEC_REFRESH_STALE_SEC，就 allow_force=True 直接去 VAR 页面强刷。
    - 这会在‘页面明明正常’时也制造一次额外切页/前台抢占，看起来就像下单前又刷新了一轮。

    新口径：
    1) 先只读缓存/最近快照，不动 UI；
    2) 若执行器此刻正占着页面，明确禁止为了补指标去强刷；
    3) 只有显式打开 EXEC_ORDER_ALLOW_FORCE_IND_FETCH=1 时，才允许最后兜底强刷。
    """
    try:
        if not coin:
            return
        meta = getattr(order, "meta", None)
        if not isinstance(meta, dict):
            meta = {}
            try:
                setattr(order, "meta", meta)
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_184', _e)
                pass
        age = meta.get("ind_age_sec")
        if age is None:
            return
        age_f = float(age)
        stale_sec = float(IND_EXEC_REFRESH_STALE_SEC)
        if age_f <= stale_sec:
            return
        coin_u = str(coin).upper().strip()
        plat_u = str(getattr(order, "platform", "") or meta.get("platform") or "VAR").upper().strip()
        if not plat_u:
            plat_u = "VAR"
        busy = _exec_ui_busy_state(platform=plat_u, coin=coin_u)
        try:
            allow_force = bool(int(float(os.getenv("EXEC_ORDER_ALLOW_FORCE_IND_FETCH", "0") or 0)))
        except Exception:
            allow_force = False
        ttl_soft = max(stale_sec, float(globals().get("IND_TTL_SEC_DEFAULT") or stale_sec), 1800.0)
        _adx = _rsi = _ts = _age = None
        _rsn = ""
        try:
            _adx, _rsi, _ts, _age, _rsn = _ind_require_adx_rsi(coin_u, time.time(), ttl_sec=ttl_soft, allow_force=False)
        except Exception as _e_soft:
            _rsn = f"soft_refresh_fail:{type(_e_soft).__name__}"
        if (_adx is None or _rsi is None) and allow_force and not isinstance(busy, dict):
            try:
                _adx, _rsi, _ts, _age, _rsn = _ind_require_adx_rsi(coin_u, time.time(), ttl_sec=stale_sec, allow_force=True)
            except Exception as _e_force:
                _rsn = f"force_refresh_fail:{type(_e_force).__name__}"
        if _adx is not None and _rsi is not None:
            meta["ind_rsi"] = float(_rsi)
            meta["ind_adx"] = float(_adx)
            meta["ind_ts"] = float(_ts) if _ts is not None else float(time.time())
            meta["ind_age_sec"] = float(_age) if _age is not None else 0.0
            meta["ind_reason"] = str(_rsn)
            if why:
                meta["ind_refresh_why"] = str(why)
            try:
                _exec_log(f"EXEC（执行器）执行前指标软补齐 coin={coin_u} age={age_f} new_age={meta.get('ind_age_sec')} rsi={meta.get('ind_rsi')} adx={meta.get('ind_adx')} reason={meta.get('ind_reason')}", coin=coin_u)
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_185', _e)
                pass
            return
        try:
            if why:
                meta["ind_refresh_why"] = str(why)
            if isinstance(busy, dict):
                meta["ind_reason"] = f"skip_force_refresh_busy:{str((busy or {}).get('source') or 'exec_ui')}:{str((busy or {}).get('stage') or (busy or {}).get('label') or '')}"
                _exec_log(f"EXEC（执行器）执行前指标已过期，但当前页面正被执行器占用，跳过强刷 coin={coin_u} age={age_f} busy={str((busy or {}).get('source') or '')}/{str((busy or {}).get('stage') or (busy or {}).get('label') or '')}", coin=coin_u)
            else:
                meta["ind_reason"] = str(_rsn or 'skip_force_refresh_no_fresh_indicator')
                _exec_log(f"EXEC（执行器）执行前指标已过期，但按新口径不再默认强刷页面 coin={coin_u} age={age_f} reason={meta.get('ind_reason')}", coin=coin_u)
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_186', _e)
            pass
    except Exception:
        return

def _exec_input_readback_match(want: Any, got: Any, *, tol_abs: float = 1.0, tol_ratio: float = 0.05) -> tuple[bool, dict]:
    """金额输入读回硬校验。
    人话：
    - 目标 2080，读回 208，这种不是“格式差异”，而是严重缩量，必须拦。
    - 允许极小误差（格式化 / 小数舍入），但不允许数量级错位。
    返回: (ok, detail)
    """
    detail = {"ok": False, "want": want, "got": got, "want_num": None, "got_num": None, "abs_diff": None, "ratio": None, "reason": ""}
    try:
        def _to_num(v):
            if v is None:
                return None
            try:
                if isinstance(v, (int, float)):
                    return float(v)
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_187', _e)
                pass
            try:
                s = str(v).strip()
            except Exception:
                return None
            if not s:
                return None
            try:
                return float(clean_num(s))
            except Exception:
                try:
                    s2 = s.replace(",", "").replace("$", "").replace("USD", "").replace("USDT", "").strip()
                    return float(s2) if s2 else None
                except Exception:
                    return None

        want_num = _to_num(want)
        got_num = _to_num(got)
        detail["want_num"] = want_num
        detail["got_num"] = got_num
        if want_num is None or want_num <= 0:
            detail["reason"] = "want_invalid"
            return False, detail
        if got_num is None or got_num <= 0:
            detail["reason"] = "got_invalid"
            return False, detail
        abs_diff = abs(float(got_num) - float(want_num))
        ratio = float(got_num) / float(want_num) if float(want_num) > 0 else 0.0
        detail["abs_diff"] = abs_diff
        detail["ratio"] = ratio
        ok = bool(abs_diff <= max(float(tol_abs), abs(float(want_num)) * float(tol_ratio)))
        if not ok:
            ok = bool(0.95 <= ratio <= 1.05)
        detail["ok"] = bool(ok)
        detail["reason"] = "ok" if ok else "mismatch"
        return bool(ok), detail
    except Exception as _e:
        detail["reason"] = f"exception:{type(_e).__name__}"
        return False, detail

