def _exec_read_position_truth(page, cfg, coin):
    try:
        row = read_coin_row_basic(page, cfg, coin)
    except Exception:
        return {'position_state': 'UNAVAILABLE'}
    read = _safety_normalize_position_read(row)
    if read.get('state') == 'FOUND':
        result = dict(read.get('row') or {})
        result['position_state'] = 'FOUND'
        _safety_resolve_submission(str(cfg.get('name') or ''), coin, result)
        return result
    if read.get('state') == 'CONFIRMED_EMPTY' or _exec_positions_confirmed_empty(page, cfg):
        result = {'position_state': 'CONFIRMED_EMPTY', 'side': 'NONE', 'qty_abs': 0.0, 'notional_u': 0.0}
        _safety_resolve_submission(str(cfg.get('name') or ''), coin, result)
        return result
    return {'position_state': 'UNAVAILABLE'}

def _exec_portfolio_coin_truth(portfolio, coin):
    pf = portfolio if isinstance(portfolio, dict) else {}
    if not pf.get('available'):
        return {'position_state': 'UNAVAILABLE'}
    row = (pf.get('positions') or {}).get(str(coin or '').upper())
    if row is not None:
        return row
    if pf.get('position_state') == 'CONFIRMED_EMPTY':
        return {'position_state': 'CONFIRMED_EMPTY'}
    return {'position_state': 'UNAVAILABLE'}

def _safety_submission_records():
    # Lazy load only at runtime. Corrupt/missing-identity state fails closed.
    from bot_core import submission_scope as scope
    with _SYNC_PW_WORKER_LOCK:
        if '_SAFETY_SUBMISSION_RECORDS' not in globals():
            import json
            path = os.path.join(str(OUT_DIR), 'state', 'execution_unconfirmed.json')
            records = {}
            try:
                if os.path.exists(path):
                    with open(path, 'r', encoding='utf-8') as fp:
                        data = json.load(fp)
                    if not isinstance(data, dict) or not isinstance(data.get('records'), dict):
                        raise ValueError('invalid unconfirmed-order journal')
                    records = scope.index_records(data['records'])
            except Exception as exc:
                globals()['_SAFETY_SUBMISSION_FAULT'] = True
                globals()['_SAFETY_SUBMISSION_FAULT_DETAIL'] = f'journal_read:{type(exc).__name__}:{exc}'
            globals()['_SAFETY_SUBMISSION_RECORDS'] = records
        return globals()['_SAFETY_SUBMISSION_RECORDS']

def _safety_submission_save():
    if globals().get('_SAFETY_SUBMISSION_FAULT'):
        return False  # Preserve corrupt evidence; never overwrite it as empty.
    path = os.path.join(str(OUT_DIR), 'state', 'execution_unconfirmed.json')
    try:
        import json
        os.makedirs(os.path.dirname(path), exist_ok=True)
        payload = {'version': 2, 'records': _safety_submission_records()}
        result = safe_write_json(path, payload, indent=2)
        if result is False:
            raise OSError('unconfirmed-order journal write failed')
        with open(path, 'r', encoding='utf-8') as fp:
            if json.load(fp) != payload:
                raise OSError('unconfirmed-order journal readback mismatch')
        return True
    except Exception as exc:
        globals()['_SAFETY_SUBMISSION_FAULT'] = True
        globals()['_SAFETY_SUBMISSION_FAULT_DETAIL'] = f'journal_save:{type(exc).__name__}:{exc}'
        try:
            safe_log(lambda: f"[{now_ts()}] [SUBMISSION_JOURNAL_ERROR] reason={globals()['_SAFETY_SUBMISSION_FAULT_DETAIL']}")
        except Exception:
            pass  # Logging failure must not change the fail-closed save result.
        return False

def _safety_pending_scope(plat, coin, kind='open', side=''):
    from bot_core import submission_scope as scope
    records = _safety_submission_records()
    if globals().get('_SAFETY_SUBMISSION_FAULT'):
        return {'state': 'UNAVAILABLE', 'reason': 'submission_journal_unavailable',
                'fault_detail': globals().get('_SAFETY_SUBMISSION_FAULT_DETAIL', 'journal_integrity_unverified')}
    p, c = str(plat or '').upper(), str(coin or '').upper()
    for record in list(records.values()):
        if scope.blocks(record, p, c, kind, side):
            return dict(record)
    return {}

def _safety_reserve_submission(plat, coin, side, kind, pre_position, usd, reason='submitted_pending_confirm', *, allow_existing=False, submission_attempt_id='', module=''):
    from bot_core import submission_scope as scope
    p, c = str(plat or '').upper(), str(coin or '').upper()
    if p not in ('EXT', 'VAR') or not c:
        return
    with _SYNC_PW_WORKER_LOCK:
        records = _safety_submission_records()
        if globals().get('_SAFETY_SUBMISSION_FAULT'):
            raise RuntimeError('submission_journal_unavailable_no_submit')
        key = scope.key(p, c, kind, side)
        old = records.get(key) or {}
        blocker = _safety_pending_scope(p, c, kind, side)
        if blocker:
            if (not allow_existing or not _safety_pending_blocks(old)
                    or scope.family(old.get('kind')) != scope.family(kind)
                    or (scope.side(old.get('side')) and scope.side(side) and scope.side(old.get('side')) != scope.side(side))):
                raise RuntimeError('unconfirmed_submission_claim_conflict_no_submit')
            if not old.get('side') and side:
                old['side'] = str(side).upper()
                if not _safety_submission_save():
                    raise RuntimeError('submission_journal_not_durable_no_submit')
            return  # Never overwrite original pre-submit evidence on a retry.
        records[key] = {'state': 'PENDING_CONFIRM', 'platform': p, 'coin': c,
            'submission_attempt_id': str(submission_attempt_id), 'module': str(module),
            'side': str(side or '').upper(), 'kind': str(kind or 'open'),
            'pre_position': dict(pre_position) if isinstance(pre_position, dict) else None,
            'intent_usd': float(usd or 0.0), 'ts': time.time(), 'reason': str(reason),
            'tolerance_usd': float(globals().get('M9_EXT_POSTCHECK_DELTA_TOL_U', 10.0) or 10.0)}
        if not _safety_submission_save():
            raise RuntimeError('submission_journal_not_durable_no_submit')


def _submission_blocker_detail(record, req=None):
    from bot_core.submission_diagnostics import describe
    detail = describe(record, now=float(time.time()))
    if req is not None:
        _req_ensure_meta(req)['submission_blocker'] = detail
    safe_log(lambda: f"[{now_ts()}] [SUBMISSION_BLOCKED] code={detail['code']} "
             f"scope={detail['scope']} submit_attempted=0 explanation={detail['message']}")
    return detail

def _safety_resolve_submission(plat, coin, row, *, kind=None):
    from bot_core import submission_scope as scope
    with _SYNC_PW_WORKER_LOCK:
        records = _safety_submission_records()
        if globals().get('_SAFETY_SUBMISSION_FAULT'):
            return False
        resolved, changed = True, False
        for record in list(records.values()):
            if (record.get('platform') != str(plat or '').upper() or record.get('coin') != str(coin or '').upper()
                    or (kind is not None and scope.family(record.get('kind')) != scope.family(kind))
                    or not _safety_pending_blocks(record)):
                continue
            ok, evidence = _safety_verify_pending_settlement(record, row)
            if ok:
                record.update(state='CONFIRMED_SUCCESS', evidence=evidence, resolved_ts=time.time())
                changed = True
            else:
                resolved = False
        if changed and not _safety_submission_save():
            return False
        return resolved

def _safety_confirm_flat_scope(plat):
    from bot_core import submission_scope as scope
    with _SYNC_PW_WORKER_LOCK:
        changed = False
        for rec in list(_safety_submission_records().values()):
            if rec.get('platform') == str(plat or '').upper() and scope.family(rec.get('kind')) == 'close' and _safety_pending_blocks(rec):
                rec.update(state='CONFIRMED_SUCCESS', resolved_ts=time.time(), evidence={'reason':'visible_explicit_empty'})
                changed = True
        if changed:
            _safety_submission_save()

def _safety_click_submit_once(locator, timeout_ms, desc, *, before_click=None, on_result=None, ready_wait_ms=0, on_blocked=None):
    try:
        _pw_call('safety.submit.wait_visible:' + str(desc), locator.wait_for, state='visible', timeout=timeout_ms)
        if callable(getattr(locator, 'is_enabled', None)):
            if ready_wait_ms > 0:
                from bot_core import close_flow
                ready, detail = close_flow.wait_ready(locator, _pw_call,
                    timeout_ms=min(timeout_ms, ready_wait_ms),
                    assert_live=lambda: globals()['_WORKER_STATE'].assert_live() if globals().get('_WORKER_STATE') else None,
                    sample=lambda: _pw_call('close.ready.sample', locator.evaluate, close_flow.CLOSE_DIALOG_SAMPLE_JS, timeout=800))
                if not ready:
                    if on_blocked is not None:
                        on_blocked(detail)
                    return False
            elif not _pw_call('safety.submit.enabled:' + str(desc), locator.is_enabled, timeout=timeout_ms):
                return False
        def dispatch(**kwargs):
            # No durable pending record until all pre-click checks and the
            # Playwright/worker guard have passed for this actual dispatch.
            if before_click is not None and before_click() is False:
                return False
            try:
                locator.click(**kwargs)
            except Exception:
                if on_result is not None:
                    on_result(False)
                raise
            if on_result is not None:
                on_result(True)
            return True
        return _pw_call('safety.submit.click_once:' + str(desc), dispatch, timeout=timeout_ms) is True
    except Exception:
        return False  # A click exception is ambiguous. Never force/replay it.


def _exec_global_close_report(exe, platform, reported_ok, *, coins=(), error=''):
    """Require visible flat evidence; expose failures without assuming missing rows are flat."""
    from bot_core import submission_scope as scope
    report = {'platform': platform, 'reported_ok': bool(reported_ok), 'ok': False,
              'flat_confirmed': False, 'remaining_coins': [], 'unverified_coins': [],
              'blocked_close_records': [], 'error': str(error or '')}
    cfg = EXT if platform == 'EXT' else VAR
    page = getattr(exe, 'page', None)
    try:
        if page is not None and not error:
            report['flat_confirmed'] = bool(_exec_positions_confirmed_empty(page, cfg))
            if not report['flat_confirmed']:
                pf = _exec_read_portfolio_snapshot(page, cfg, stop_when_found=False)
                if pf.get('available'):
                    report['remaining_coins'] = sorted(str(c) for c in (pf.get('positions') or {}))
                report['position_read_available'] = bool(pf.get('available'))
    except Exception as exc:
        report['error'] = repr(exc)
    for record in _safety_submission_records().values():
        if scope.blocks(record, platform, 'ALL', 'close_all'):
            report['blocked_close_records'].append({k: record.get(k) for k in
                ('coin', 'side', 'kind', 'reason', 'submission_attempt_id')})
    if not report['flat_confirmed']:
        report['unverified_coins'] = sorted(set(str(c).upper() for c in coins)
            - set(report['remaining_coins'])) or ([] if report['remaining_coins'] else ['ALL'])
    report['ok'] = bool(reported_ok and report['flat_confirmed'])
    report['reason'] = ('confirmed_empty' if report['ok'] else
        'close_pending_blocked' if report['blocked_close_records'] else
        'positions_remain' if report['remaining_coins'] else
        'executor_failed' if report['flat_confirmed'] else 'flat_not_confirmed')
    if not report['ok']:
        safe_log(lambda: f"[{now_ts()}] [FULL_CLOSE_INCOMPLETE] platform={platform} "
            f"reason={report['reason']} remaining_coins={report['remaining_coins']} "
            f"unverified_coins={report['unverified_coins']} blocked_close_records={report['blocked_close_records']} "
            f"error={report['error']} anchor_unchanged=1")
    return report


def _submit_attempt_begin(order):
    import uuid
    attempt = {'id': uuid.uuid4().hex, 'state': 'NOT_ATTEMPTED', 'reason': '',
               'platform': str(getattr(order, 'platform', '') or '').upper(),
               'coin': str(getattr(order, 'coin', '') or '').upper(), 'ts': float(time.time())}
    setattr(order, '_submission_attempt', attempt)
    req = getattr(order, '_exec_req_ref', None)
    if req is not None:
        meta = _req_ensure_meta(req)
        meta.setdefault('_submission_attempts', []).append(attempt)
    return attempt


def _submit_attempt_set(order, state, reason='', **detail):
    attempt = getattr(order, '_submission_attempt', None)
    if not isinstance(attempt, dict):
        attempt = _submit_attempt_begin(order)
    attempt.update(state=state, reason=str(reason), **detail)
    ctx = getattr(order, '_close_flow_context', None)
    if ctx is not None:
        ctx.record_attempt(attempt)
    return attempt


_FUNDING_MARGIN_ALERTS = {}
_FUNDING_MARGIN_LOCK = threading.RLock()


def _funding_margin_status():
    with _FUNDING_MARGIN_LOCK:
        rows = copy.deepcopy(_FUNDING_MARGIN_ALERTS)
    messages = []
    for platform, row in rows.items():
        stamp = time.strftime('%H:%M:%S', time.localtime(float(row['ts'])))
        messages.append(f"资金分配提醒：{platform} {row['coin']} 可用保证金 {row['available_u']:.2f}U，需 {row['required_u']:.2f}U，差 {row['shortfall_u']:.2f}U；已跳过。上次读取 {stamp}")
    return {'platforms': rows, 'message': '\n'.join(messages)}


def _submit_margin_precheck(locator, order, platform):
    module = str(getattr(order, 'module', '') or '').upper()
    action = str(getattr(order, 'action_type', '') or 'open').lower()
    if (module != 'B1' and not module.startswith('M9')) or bool(getattr(order, 'reduce_only', False)) or action in ('decrease', 'reduce', 'close', 'close_all', 'close_pair'):
        return True
    try:
        evidence = _pw_call(f'margin_quote.{platform}', locator.evaluate, _margin_guard.READ_QUOTE_JS,
                            timeout=1500, _operation_timeout_ms=1800)
        allow, detail = _margin_guard.decide(evidence)
    except Exception as exc:
        allow, detail = True, {'reason': 'available_margin_or_cost_unreadable', 'error': type(exc).__name__}
    coin = str(getattr(order, 'coin', '') or '').upper()
    detail.update(platform=platform, coin=coin, module=module, ts=float(time.time()))
    if not allow:
        _submit_attempt_set(order, 'BLOCKED', 'insufficient_available_margin', margin=detail)
        with _FUNDING_MARGIN_LOCK:
            _FUNDING_MARGIN_ALERTS[platform] = detail
        safe_log(lambda: f"[{now_ts()}] [FUNDING_IMBALANCE] code=insufficient_available_margin platform={platform} coin={coin} module={module} available_u={detail['available_u']} required_u={detail['required_u']} shortfall_u={detail['shortfall_u']} submit_attempted=0")
        return False
    if detail.get('reason') == 'available_margin_ok':
        with _FUNDING_MARGIN_LOCK:
            old = _FUNDING_MARGIN_ALERTS.get(platform) or {}
            if not old or float(detail['available_u']) >= float(old.get('required_u') or 0):
                _FUNDING_MARGIN_ALERTS.pop(platform, None)
    else:
        safe_log(lambda: f"[{now_ts()}] [MARGIN_PRECHECK] platform={platform} coin={coin} reason=available_margin_or_cost_unreadable behavior=unchanged")
    return True


def _submit_order_click(locator, order, platform, side, pre_row, usd, timeout_ms, desc):
    """Bind durable pending and UI evidence to this request, immediately at click."""
    attempt = getattr(order, '_submission_attempt', None)
    if not isinstance(attempt, dict):
        attempt = _submit_attempt_begin(order)
    if not _submit_margin_precheck(locator, order, platform):
        return False
    def reserve():
        try:
            _safety_reserve_submission(platform, getattr(order, 'coin', ''), side,
                getattr(order, '_submission_kind', None) or ('close' if bool(getattr(order, 'reduce_only', False)) else 'open'), pre_row, usd,
                reason='submit_click_dispatched', submission_attempt_id=attempt['id'],
                module=str(getattr(order, 'module', '') or ''))
        except Exception as exc:
            _submit_attempt_set(order, 'BLOCKED', 'submission_claim_blocked_no_submit', error=type(exc).__name__)
            return False
        _submit_attempt_set(order, 'CLICK_STARTED', 'submit_click_dispatched')
        return True
    def completed(ok):
        _submit_attempt_set(order, 'CLICKED' if ok else 'CLICK_UNKNOWN',
            'submit_clicked' if ok else 'submit_click_outcome_unknown')
    def blocked(detail):
        _submit_attempt_set(order, 'BLOCKED', detail.get('reason') or 'close_button_not_ready', readiness=detail)
        safe_log(lambda: f"[{now_ts()}] [CLOSE_NOT_SUBMITTED] platform={platform} coin={getattr(order, 'coin', '')} detail={detail}")
    ok = _safety_click_submit_once(locator, timeout_ms, desc, before_click=reserve, on_result=completed,
        ready_wait_ms=int(getattr(order, '_close_ready_wait_ms', 0) or 0), on_blocked=blocked)
    if not ok and attempt.get('state') == 'NOT_ATTEMPTED':
        _submit_attempt_set(order, 'BLOCKED', 'submit_click_fail')
    return ok

def _submit_close_click(locator, platform, coin, side, pre_row, usd, timeout_ms, desc):
    """Same evidence boundary for close buttons, without adding a margin gate."""
    from types import SimpleNamespace
    req = getattr(globals().get('_ACTIVE_EXEC_CTX'), 'req_ref', None)
    rd = _req_get_dict(req) if req is not None else {}
    close_ctx = getattr(globals().get('_close_flow'), 'current', lambda: None)()
    tracking = SimpleNamespace(platform=platform, coin=coin, side=side, usd=usd,
        module=str(rd.get('module') or 'EXEC'), action_type='close_all', reduce_only=True,
        _exec_req_ref=req, _submission_kind='close_all',
        _close_flow_context=close_ctx, _close_ready_wait_ms=3000 if close_ctx is not None else 0)
    _submit_attempt_begin(tracking)
    return _submit_order_click(locator, tracking, platform, side, pre_row, usd, timeout_ms, desc)


def _full_close_read_var_coins(exe):
    _WORKER_STATE.assert_live()
    _exec_ensure_active_page(exe.page, 'VAR full close positions')
    _var_prepare_positions_view(exe.page, force=True)
    rows = exe.page.locator(VAR['rows'])
    count = int(_pw_call('full_close.VAR.rows_count', rows.count))
    if count == 0:
        if _exec_positions_confirmed_empty(exe.page, VAR):
            return []
        raise RuntimeError('VAR_positions_unavailable_zero_without_empty_evidence')
    hrefs = _pw_call('full_close.VAR.markets',
        exe.page.locator(f"{VAR['rows']} a.link-instrument").evaluate_all,
        "els => els.map(e => e.getAttribute('href') || '')", timeout=1500)
    found = []
    for href in hrefs:
        match = re.search(r'/perpetual/([A-Za-z0-9_-]+)(?:[/?#]|$)', str(href))
        if match and match[1].upper() not in found:
            found.append(match[1].upper())
    if not found or len(found) != count:
        raise RuntimeError(f'VAR_positions_coverage_unavailable:rows={count}|coins={len(found)}')
    return found


def _full_close_confirm_var_absence(exe, coin, flow):
    """Confirm a submitted coin disappeared from two complete platform reads."""
    samples = []
    for attempt in range(2):
        flow.check()
        current = sorted(_full_close_read_var_coins(exe))
        if str(coin).upper() in current:
            return False
        samples.append(current)
        if attempt == 0:
            time.sleep(.25)
    if samples[0] != samples[1]:
        return False  # A changing/partial table needs another independent observation.
    flow.check()
    empty = {'position_state': 'CONFIRMED_EMPTY', 'side': 'NONE', 'qty_abs': 0.0,
             'notional_u': 0.0, 'reason': 'two_complete_var_tables_coin_absent'}
    if not _safety_resolve_submission('VAR', coin, empty, kind='close_all'):
        return False
    flow.mark_result('VAR', coin, True, 'two_complete_var_tables_coin_absent')
    safe_log(lambda: f"[{now_ts()}] [FULL_CLOSE_COIN_CONFIRMED] platform=VAR coin={coin} "
             f"reason=two_complete_var_tables_coin_absent remaining_coins={samples[-1]} resubmitted=0")
    return True


def _full_close_dismiss_dialog(page, coin, flow):
    """Cancel only the unsubmitted close dialog; never send a global Escape."""
    if not flow.can_resubmit('VAR', coin) or _safety_pending_scope('VAR', coin, 'close_all'):
        return False
    dialogs = page.locator('dialog[open], [role="dialog"]')
    if int(_pw_call('full_close.VAR.dialogs', dialogs.count)) == 0:
        return True
    owned = dialogs.filter(has=page.locator('button[data-testid="close-position-button"]'))
    if int(_pw_call('full_close.VAR.close_dialogs', owned.count)) != 1:
        return False
    dialog = owned.first
    cancel = dialog.get_by_role('button', name=re.compile(r'^(Cancel|取消)$', re.I))
    if int(_pw_call('full_close.VAR.cancel_count', cancel.count)) != 1:
        return False
    _pw_call('full_close.VAR.cancel_unsubmitted_dialog', cancel.click, timeout=800)
    _pw_call('full_close.VAR.cancel_hidden', dialog.wait_for, state='hidden', timeout=1000)
    return True


def _full_close_recover_page(exe, platform, coin, flow):
    """Recovery stays on the live owning worker and preserves the existing browser."""
    flow.check()
    if not flow.can_resubmit(platform, coin) or _safety_pending_scope(platform, coin, 'close_all'):
        return False
    rt = _exec_runtime_cache_get()
    if not _exec_runtime_connection_alive(rt):
        return False  # A retired worker or dead connection cannot be revived here.
    _PW_SESSIONS.begin(rt['browser'])
    page = exe.page
    try:
        if not page.is_closed():
            _pw_call('full_close.recover.' + platform, page.reload,
                     wait_until='domcontentloaded', timeout=flow.timeout_ms(10000))
        else:
            cfg = EXT if platform == 'EXT' else VAR
            url = (str(cfg.get('open_url') or EXT_NORMAL_OPEN_URL) if platform == 'EXT'
                   else 'https://omni.variational.io/perpetual/' + (coin if coin != 'ALL' else 'BTC'))
            page, reason = _rebuild_single_page_in_context(rt['context'], target_url=url,
                platform=platform, coin=coin, expected_url_keywords=[('extended.exchange' if platform == 'EXT' else 'variational.io')],
                timeout_ms=flow.timeout_ms(15000))
            if page is None:
                raise RuntimeError(reason or 'close_page_recovery_failed')
        flow.check()
        exe.page = page
        rt[platform.lower() + '_page'] = page
        rt[platform.lower() + '_exe'] = exe
        _exec_runtime_cache_set(rt)
        safe_log(lambda: f"[{now_ts()}] EXEC_INROUND_RETRY platform={platform} coin={coin} reason=confirmed_no_submit_page_recovered attempt=1")
        return True
    except Exception as exc:
        flow.assert_owner_live()
        safe_log(lambda: f"[{now_ts()}] [FULL_CLOSE_RECOVERY_FAIL] platform={platform} coin={coin} error={exc!r} retry_exhausted=1")
        return False


def _var_full_close_guarded(exe, dry_run=False):
    flow = _close_flow.current()
    if flow is None:
        with _close_flow.scope(_close_flow.CloseFlow(assert_live=_WORKER_STATE.assert_live)):
            return _var_full_close_guarded(exe, dry_run=dry_run)
    flow.begin('VAR', 'ALL')
    from bot_core import submission_scope as scope
    blocker = _safety_pending_scope('VAR', 'ALL', 'close_all')
    pending = [dict(r) for r in _safety_submission_records().values()
               if scope.blocks(r, 'VAR', 'ALL', 'close_all')]
    if blocker and (not pending or any(r.get('coin') == 'ALL' for r in pending)):
        if _exec_positions_confirmed_empty(exe.page, VAR):
            return True
        flow.mark_unknown('VAR', 'ALL', 'existing_close_unconfirmed')
        return False
    for record in pending:
        flow.mark_unknown('VAR', record['coin'], 'existing_coin_close_unconfirmed')
    try:
        coins = _full_close_read_var_coins(exe)
    except Exception as exc:
        flow.assert_owner_live()
        if not flow.recover_once('VAR', 'ALL', lambda: _full_close_recover_page(exe, 'VAR', 'ALL', flow)):
            raise
        coins = _full_close_read_var_coins(exe)
    flow.coins['VAR'] = list(coins)
    if dry_run:
        return True
    for record in pending:
        if record['coin'] not in coins:
            try:
                _full_close_confirm_var_absence(exe, record['coin'], flow)
            except Exception:
                flow.assert_owner_live()  # Unavailable evidence never releases a claim.
    for coin in coins:
        flow.check()
        flow.begin('VAR', coin)
        if _safety_pending_scope('VAR', coin, 'close_all') or flow.submitted('VAR', coin):
            flow.mark_unknown('VAR', coin, 'close_already_submitted_no_retry')
            continue
        ok, error = False, ''
        try:
            ok = bool(exe.close_all(coin))
        except Exception as exc:
            flow.assert_owner_live()
            error = repr(exc)
        if not ok and flow.submitted('VAR', coin):
            try:
                ok = _full_close_confirm_var_absence(exe, coin, flow)
            except Exception as exc:
                flow.assert_owner_live()
                error = error or repr(exc)
        if not ok and _safety_pending_scope('VAR', coin, 'close_all'):
            flow.mark_unknown('VAR', coin, 'existing_close_unconfirmed_no_retry')
        if not ok and flow.can_resubmit('VAR', coin):
            dismissed = False
            try:
                dismissed = _full_close_dismiss_dialog(exe.page, coin, flow)
            except Exception as exc:
                flow.assert_owner_live()
                error = error or repr(exc)
            if flow.recover_once('VAR', coin, lambda: _full_close_recover_page(exe, 'VAR', coin, flow)):
                # Recheck the durable close claim after recovery, before re-entering.
                if not _safety_pending_scope('VAR', coin, 'close_all'):
                    try:
                        ok = bool(exe.close_all(coin))
                    except Exception as exc:
                        flow.assert_owner_live()
                        error = repr(exc)
                if not ok and flow.can_resubmit('VAR', coin):
                    try:
                        dismissed = _full_close_dismiss_dialog(exe.page, coin, flow)
                    except Exception:
                        dismissed = False
            if not ok and _safety_pending_scope('VAR', coin, 'close_all'):
                flow.mark_unknown('VAR', coin, 'existing_close_unconfirmed_no_retry')
            if not ok and not dismissed:
                flow.mark_result('VAR', coin, False, error or 'unsubmitted_close_dialog_still_open')
                break  # Do not navigate through an unresolved modal six times.
        flow.mark_result('VAR', coin, ok, error or ('confirmed_empty' if ok else 'close_not_confirmed'))
        if not ok and flow.submitted('VAR', coin):
            break  # Delivery is uncertain: observe later, never replay this order.
    flow.check()
    return bool(_exec_positions_confirmed_empty(exe.page, VAR))


def _run_full_close_transaction(ext_exe, var_exe, req, coins):
    """Only this request's current worker may submit; final evidence gates the anchor."""
    flow = _close_flow.current()
    if flow is None:
        with _close_flow.scope(_close_flow.CloseFlow(clock=getattr(time, 'monotonic', time.time), assert_live=_WORKER_STATE.assert_live)):
            return _run_full_close_transaction(ext_exe, var_exe, req, coins)
    _active_req_bind(req, stage='FULL_CLOSE_BEGIN')
    done, errors = {'EXT': False, 'VAR': False}, {'EXT': '', 'VAR': ''}
    for platform, exe in (('EXT', ext_exe), ('VAR', var_exe)):
        try:
            flow.begin(platform, 'ALL')
            done[platform] = bool(exe.close_all_global())
            if not done[platform] and flow.can_resubmit(platform, 'ALL'):
                if flow.recover_once(platform, 'ALL', lambda: _full_close_recover_page(exe, platform, 'ALL', flow)):
                    done[platform] = bool(exe.close_all_global())
        except Exception as exc:
            flow.assert_owner_live()
            errors[platform] = repr(exc)
            if not flow.submitted(platform, 'ALL') and flow.remaining() > 3:
                try:
                    if flow.recover_once(platform, 'ALL', lambda: _full_close_recover_page(exe, platform, 'ALL', flow)):
                        done[platform] = bool(exe.close_all_global())
                        errors[platform] = ''
                except Exception as retry_exc:
                    flow.assert_owner_live()
                    errors[platform] = repr(retry_exc)
    flow.final_verification = True
    flow.assert_owner_live()
    reports = {}
    for platform, exe in (('EXT', ext_exe), ('VAR', var_exe)):
        if flow.remaining() <= 0:
            errors[platform] = errors[platform] or 'full_close_deadline_exhausted'
        reports[platform] = _exec_global_close_report(exe, platform, done[platform],
            coins=flow.coins[platform] or coins, error=errors[platform])
        if reports[platform]['ok']:
            flow.mark_result(platform, 'ALL', True, 'fresh_platform_empty')
        reports[platform]['close_attempts'] = flow.details(platform)
        reports[platform]['recovery_used'] = platform in flow.recovered
    flow.assert_owner_live()
    if flow.remaining() <= 0:
        for report in reports.values():
            report.update(ok=False, reason='full_close_deadline_exhausted')
    return reports

def _extract_position_snapshot_from_text(*, platform_name: str, market_txt: str = '', side_txt: str = '', value_txt: str = '') -> dict:
    """把平台行文本统一解析成 coin/side/qty_abs/notional_u。
    人话：
    - EXT：方向看 Long/Short；数量在 VALUE / SIZE 的第二行；名义在第一行 USD
    - VAR：方向看 Quantity 正负号；数量就是 Quantity；名义在 Value 列
    这样后面的 portfolio snapshot / postcheck / 对冲对账都用同一口径。
    """
    plat = str(platform_name or '').upper().strip()
    coin_u = ''
    try:
        coin_u = norm_coin_symbol(market_txt)
    except Exception:
        coin_u = ''
    side = 'NONE'
    qty_abs = 0.0
    notional_u = 0.0
    raw_side = str(side_txt or '').strip()
    raw_value = str(value_txt or '').strip()

    def _line_nums(s: str) -> list[float]:
        vals = []
        for part in str(s or '').splitlines():
            v = clean_num(part)
            try:
                if v is not None:
                    vals.append(float(v))
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_188', _e)
                pass
        return vals

    if plat == 'EXT':
        su = raw_side.upper()
        if ('LONG' in su) or ('多' in su):
            side = 'LONG'
        elif ('SHORT' in su) or ('空' in su):
            side = 'SHORT'
        nums = _line_nums(raw_value)
        if nums:
            try:
                notional_u = abs(float(nums[0] or 0.0))
            except Exception:
                notional_u = 0.0
        if len(nums) >= 2:
            try:
                qty_abs = abs(float(nums[1] or 0.0))
            except Exception:
                qty_abs = 0.0
        elif nums:
            qty_abs = 0.0
    elif plat == 'VAR':
        sv = clean_num(raw_side)
        try:
            svf = float(sv) if sv is not None else 0.0
        except Exception:
            svf = 0.0
        if svf > 0:
            side = 'LONG'
        elif svf < 0:
            side = 'SHORT'
        qty_abs = abs(float(svf or 0.0))
        vv = clean_num(raw_value)
        try:
            notional_u = abs(float(vv or 0.0))
        except Exception:
            notional_u = 0.0
    else:
        su = raw_side.upper()
        if ('LONG' in su) or ('多' in su):
            side = 'LONG'
        elif ('SHORT' in su) or ('空' in su):
            side = 'SHORT'
        else:
            sv = clean_num(raw_side)
            try:
                svf = float(sv) if sv is not None else 0.0
            except Exception:
                svf = 0.0
            if svf > 0:
                side = 'LONG'
            elif svf < 0:
                side = 'SHORT'
            qty_abs = abs(float(svf or 0.0))
        vv = clean_num(raw_value)
        try:
            notional_u = abs(float(vv or 0.0))
        except Exception:
            notional_u = 0.0
    return {
        'coin': str(coin_u or '').upper(),
        'side': side,
        'qty_abs': float(qty_abs or 0.0),
        'notional_u': float(notional_u or 0.0),
        'platform': plat,
        'raw_market': str(market_txt or ''),
        'raw_side': raw_side,
        'raw_value': raw_value,
    }

def _evaluate_dual_platform_hedge_health(ext_positions: dict | None, var_positions: dict | None) -> dict:
    """双平台对冲健康检查：方向是否相反、名义差额是否过大。"""
    ext_pos = ((ext_positions or {}).get('positions') or {}) if isinstance(ext_positions, dict) else {}
    var_pos = ((var_positions or {}).get('positions') or {}) if isinstance(var_positions, dict) else {}
    coins = sorted(set([str(k).upper() for k in ext_pos.keys()]) | set([str(k).upper() for k in var_pos.keys()]))
    details = {}
    ok_all = True
    for coin in coins:
        e = ext_pos.get(coin) or {}
        v = var_pos.get(coin) or {}
        es = str(e.get('side') or 'NONE').upper()
        vs = str(v.get('side') or 'NONE').upper()
        en = abs(float(e.get('notional_u') or 0.0))
        vn = abs(float(v.get('notional_u') or 0.0))
        opposite = bool((es == 'LONG' and vs == 'SHORT') or (es == 'SHORT' and vs == 'LONG'))
        mx = max(en, vn, 1e-9)
        diff_ratio = abs(en - vn) / mx if mx > 0 else 0.0
        healthy = bool(opposite and diff_ratio <= 0.35)
        details[coin] = {
            'ext_side': es, 'var_side': vs,
            'ext_notional_u': en, 'var_notional_u': vn,
            'opposite_ok': opposite,
            'notional_diff_ratio': round(float(diff_ratio), 6),
            'healthy': healthy,
        }
        ok_all = bool(ok_all and healthy)
    return {'coins': details, 'all_healthy': ok_all, 'coin_count': len(details)}

_EXEC_BATCH_VERIFY_CTX: Dict[str, Any] = {
    "active": False,
    "mode": "",
    "coins_by_platform": {"EXT": [], "VAR": []},
    "pre": {},
    "post": {},
    "reason": "",
}

def _exec_batch_platform_name(platform_obj: Any) -> str:
    try:
        if isinstance(platform_obj, dict):
            return str(platform_obj.get('name') or '').upper().strip()
        return str(getattr(platform_obj, 'name', '') or getattr(platform_obj, '__name__', '') or '').upper().strip()
    except Exception:
        return ''

def _exec_batch_req_to_dict(req_any: Any) -> dict:
    try:
        if isinstance(req_any, dict):
            return dict(req_any)
        if hasattr(req_any, 'to_dict'):
            d = req_any.to_dict()
            return dict(d) if isinstance(d, dict) else {}
        return {
            'module': str(getattr(req_any, 'module', '') or ''),
            'coin': str(getattr(req_any, 'coin', '') or ''),
            'platform': str(getattr(req_any, 'platform', '') or ''),
            'action_type': str(getattr(req_any, 'action_type', getattr(req_any, 'action', '')) or ''),
            'params': dict(getattr(req_any, 'params', {}) or {}),
            'meta': dict(getattr(req_any, 'meta', {}) or {}),
        }
    except Exception:
        return {}

def _exec_batch_collect_focus_coins(requests: Any) -> dict:
    out = {'EXT': [], 'VAR': []}
    seen = {'EXT': set(), 'VAR': set()}
    for req_any in (requests or []):
        rd = _exec_batch_req_to_dict(req_any)
        plat = str(rd.get('platform') or rd.get('plat') or '').upper().strip()
        coin = str(rd.get('coin') or '').upper().strip()
        if plat not in ('EXT', 'VAR') or (not coin):
            continue
        if coin in seen[plat]:
            continue
        seen[plat].add(coin)
        out[plat].append(coin)
    return out

def _exec_batch_verify_reset(reason: str = '') -> None:
    try:
        _EXEC_BATCH_VERIFY_CTX.clear()
        _EXEC_BATCH_VERIFY_CTX.update({
            'active': False,
            'mode': '',
            'coins_by_platform': {'EXT': [], 'VAR': []},
            'pre': {},
            'post': {},
            'reason': str(reason or ''),
        })
    except Exception:
        pass

def _exec_batch_verify_begin(*, requests: Any = None, ext_page: Any = None, var_page: Any = None, ext_cfg: Any = None, var_cfg: Any = None) -> dict:
    """单币即时复检初始化。

    最新口径：一次扫描拿完信息后直接下单；
    下单后只对当前下单币做即时复检，彻底停用“批量统一复检 / deferred verify”。
    """
    _exec_batch_verify_reset('single_coin_postcheck_only')
    coins_by_platform = _exec_batch_collect_focus_coins(requests)
    try:
        _EXEC_BATCH_VERIFY_CTX['active'] = False
        _EXEC_BATCH_VERIFY_CTX['mode'] = 'single_coin_postcheck_only'
        _EXEC_BATCH_VERIFY_CTX['coins_by_platform'] = dict(coins_by_platform or {'EXT': [], 'VAR': []})
        _EXEC_BATCH_VERIFY_CTX['pre'] = {
            'EXT': {'available': False, 'reason': 'single_coin_postcheck_only', 'platform': 'EXT'},
            'VAR': {'available': False, 'reason': 'single_coin_postcheck_only', 'platform': 'VAR'},
        }
    except Exception:
        pass
    return dict(_EXEC_BATCH_VERIFY_CTX)

def _exec_batch_should_defer_verify() -> bool:
    return False

def _exec_batch_get_pre_portfolio(platform_obj: Any, *, page: Any = None) -> dict:
    plat = _exec_batch_platform_name(platform_obj)
    try:
        snap = ((_EXEC_BATCH_VERIFY_CTX or {}).get('pre') or {}).get(plat)
    except Exception:
        snap = None
    if isinstance(snap, dict):
        return dict(snap)
    return {'available': False, 'reason': 'exec_pre_scan_disabled', 'platform': plat}

def _exec_batch_get_pre_row(platform_obj: Any, coin: str, *, page: Any = None) -> Any:
    snap = _exec_batch_get_pre_portfolio(platform_obj, page=page)
    row = _exec_portfolio_coin_truth(snap, coin)
    if _safety_position_read(row)[0] != 'UNAVAILABLE':
        return row
    if page is not None:
        return _exec_read_position_truth(page, platform_obj, coin)
    return {'position_state': 'UNAVAILABLE'}

def _exec_batch_get_post_portfolio(platform_obj: Any, *, page: Any = None) -> dict:
    plat = _exec_batch_platform_name(platform_obj)
    try:
        snap = ((_EXEC_BATCH_VERIFY_CTX or {}).get('post') or {}).get(plat)
    except Exception:
        snap = None
    if isinstance(snap, dict):
        return dict(snap)
    if page is not None:
        try:
            focus = (((_EXEC_BATCH_VERIFY_CTX or {}).get('coins_by_platform') or {}).get(plat) or [])
            snap = _exec_read_portfolio_snapshot(page, platform_obj, focus_coins=focus or None)
            (_EXEC_BATCH_VERIFY_CTX.setdefault('post', {}))[plat] = dict(snap or {})
            return dict(snap or {})
        except Exception as _e:
            return {'available': False, 'error': repr(_e), 'platform': plat}
    return {'available': False, 'platform': plat}

def _exec_batch_kind_from_req(reqd: dict | None = None) -> str:
    rd = reqd if isinstance(reqd, dict) else {}
    action = str(rd.get('action_type') or rd.get('action') or '').lower().strip()
    module = str(rd.get('module') or '').lower().strip()
    if any(k in action for k in ('close', 'decrease', 'reduce', 'tp', 'partial', 'koujing')):
        return 'close'
    if module in ('b2', 'm10', 'm10_tp', 'trend_tp'):
        return 'close'
    return 'open'

def _exec_batch_side_from_req(reqd: dict | None = None, *, pre_pos: Any = None, post_pos: Any = None, kind: str = '') -> str:
    rd = reqd if isinstance(reqd, dict) else {}
    if str(kind or '').lower().strip() == 'close':
        try:
            return str(((pre_pos or {}).get('side') or '')).upper().strip()
        except Exception:
            return ''
    params = rd.get('params') if isinstance(rd.get('params'), dict) else {}
    for key in ('pos_side', 'side_u', 'side', 'direction'):
        val = str(params.get(key) or rd.get(key) or '').upper().strip()
        if val in ('LONG', 'SHORT'):
            return val
    bs = str(params.get('side') or rd.get('side') or '').lower().strip()
    if bs.startswith('buy'):
        return 'LONG'
    if bs.startswith('sell'):
        return 'SHORT'
    try:
        return str(((post_pos or {}).get('side') or '')).upper().strip()
    except Exception:
        return ''

def _exec_batch_usd_from_req(reqd: dict | None = None) -> float:
    rd = reqd if isinstance(reqd, dict) else {}
    params = rd.get('params') if isinstance(rd.get('params'), dict) else {}
    vals = [
        params.get('amount_usd'), params.get('usd'), params.get('amount'), params.get('notional_u'),
        rd.get('amount_usd'), rd.get('usd'), rd.get('amount'), rd.get('notional_u')
    ]
    for v in vals:
        try:
            fv = float(v)
            if fv > 0:
                return fv
        except Exception:
            continue
    return 0.0

def _exec_batch_result_needs_postcheck(rr: Any) -> bool:
    try:
        if not isinstance(rr, dict):
            return False
        reqd = rr.get('req') if isinstance(rr.get('req'), dict) else {}
        plat = str(reqd.get('platform') or reqd.get('plat') or '').upper().strip()
        coin = str(reqd.get('coin') or '').upper().strip()
        if plat not in ('EXT', 'VAR') or (not coin):
            return False
        if bool(rr.get('verified')):
            return False
        reason = str(rr.get('reason') or '').strip().lower()
        state = str(rr.get('confirmation_state') or '').strip().lower()
        if reason in ('submit_fail', 'confirmed_fail', 'batch_postcheck_ok'):
            return False
        if state in ('confirmed_success', 'submit_fail', 'confirmed_fail'):
            return False
        if str(rr.get('batch_postcheck_skipped_reason') or '').strip().lower() == 'side_missing':
            return False
        pending_hits = (
            'pending' in reason
            or 'timeout' in reason
            or 'uncertain' in reason
            or 'postcheck_fail' in reason
            or 'confirm_failed' in reason
            or 'submitted' in state
            or 'uncertain' in state
        )
        if pending_hits:
            return True
        if not bool(rr.get('ok')):
            return True
        return bool(not rr.get('postcheck_skipped'))
    except Exception:
        return False

def _exec_batch_collect_postcheck_focus(results: Any) -> dict:
    out = {'EXT': [], 'VAR': []}
    seen = {'EXT': set(), 'VAR': set()}
    for rr in (results or []):
        if not _exec_batch_result_needs_postcheck(rr):
            continue
        try:
            reqd = rr.get('req') if isinstance(rr.get('req'), dict) else {}
            plat = str(reqd.get('platform') or reqd.get('plat') or '').upper().strip()
            coin = str(reqd.get('coin') or '').upper().strip()
        except Exception:
            plat, coin = '', ''
        if plat not in ('EXT', 'VAR') or (not coin) or coin in seen[plat]:
            continue
        seen[plat].add(coin)
        out[plat].append(coin)
    return out

def _exec_batch_apply_postcheck(results: Any, *, ext_page: Any = None, var_page: Any = None, ext_cfg: Any = None, var_cfg: Any = None) -> int:
    if not _exec_batch_should_defer_verify():
        return 0
    changed = 0
    focus_by_platform = _exec_batch_collect_postcheck_focus(results)
    if (not ((focus_by_platform or {}).get('EXT') or [])) and (not ((focus_by_platform or {}).get('VAR') or [])):
        return 0
    try:
        if ext_page is not None and ext_cfg is not None and ((focus_by_platform or {}).get('EXT') or []):
            (_EXEC_BATCH_VERIFY_CTX.setdefault('post', {}))['EXT'] = _exec_read_portfolio_snapshot(ext_page, ext_cfg, focus_coins=((focus_by_platform or {}).get('EXT') or None))
    except Exception:
        pass
    try:
        if var_page is not None and var_cfg is not None and ((focus_by_platform or {}).get('VAR') or []):
            (_EXEC_BATCH_VERIFY_CTX.setdefault('post', {}))['VAR'] = _exec_read_portfolio_snapshot(var_page, var_cfg, focus_coins=((focus_by_platform or {}).get('VAR') or None))
    except Exception:
        pass
    for rr in (results or []):
        if not isinstance(rr, dict):
            continue
        if not _exec_batch_result_needs_postcheck(rr):
            continue
        reqd = rr.get('req') if isinstance(rr.get('req'), dict) else {}
        plat = str(reqd.get('platform') or reqd.get('plat') or '').upper().strip()
        coin = str(reqd.get('coin') or '').upper().strip()
        if plat not in ('EXT', 'VAR') or (not coin):
            continue
        pre_pf = (((_EXEC_BATCH_VERIFY_CTX or {}).get('pre') or {}).get(plat) or {})
        post_pf = (((_EXEC_BATCH_VERIFY_CTX or {}).get('post') or {}).get(plat) or {})
        pre_pos = _exec_portfolio_coin_truth(pre_pf, coin)
        post_pos = _exec_portfolio_coin_truth(post_pf, coin)
        kind = _exec_batch_kind_from_req(reqd)
        side_u = _exec_batch_side_from_req(reqd, pre_pos=pre_pos, post_pos=post_pos, kind=kind)
        if side_u not in ('LONG', 'SHORT'):
            rr['batch_postcheck_skipped_reason'] = 'side_missing'
            continue
        usd = _exec_batch_usd_from_req(reqd)
        try:
            ok_pf, ev_pf = _exec_verify_submit_by_row(kind=kind, side_u=side_u, usd=float(usd or 0.0), pre_row=pre_pos, post_row=post_pos)
        except Exception as _e:
            rr['batch_postcheck_ok'] = False
            rr['batch_postcheck_error'] = repr(_e)
            continue
        rr['batch_verify_path'] = 'round_unified_postcheck'
        rr['batch_postcheck_ok'] = bool(ok_pf)
        rr['batch_postcheck_evidence'] = dict(ev_pf or {}) if isinstance(ev_pf, dict) else {'detail': ev_pf}
        if ok_pf:
            rr['verified'] = True
            rr['confirmation_state'] = 'confirmed_success'
            _reason0 = str(rr.get('reason') or '').strip().lower()
            if (not bool(rr.get('ok'))) or _reason0 in ('submitted_pending_confirm', 'submitted_unchecked', 'fill_seen_pending_confirm', 'unknown', 'timeout', 'confirm_failed', 'postcheck_fail'):
                rr['ok'] = True
                rr['reason'] = 'batch_postcheck_ok'
            changed += 1
        else:
            _r0 = str(rr.get('reason') or '').strip().lower()
            _c0 = str(rr.get('confirmation_state') or '').strip().lower()
            if _c0 not in ('confirmed_fail', 'submit_fail'):
                rr['confirmation_state'] = 'submitted_pending_confirm'
            if _r0 not in ('submit_fail', 'confirmed_fail', 'batch_postcheck_ok'):
                rr['reason'] = 'batch_postcheck_pending'
    return int(changed)

def _exec_read_portfolio_snapshot(page, platform_obj, *, focus_coins: Any = None, stop_when_found: bool = True) -> dict:
    """轻量读取当前可见持仓表，作为第二证据。

    提速口径（人话）：
    - 默认允许传 focus_coins，只抽取需要复检的目标币；
    - 命中全部目标币后可提前结束，不再把整张 positions 表全读完；
    - 读不到时返回 {'available': False}。
    """
    out = {"available": False, "positions": {}, "visible_rows": 0, "platform": str(getattr(platform_obj, "name", "") or getattr(platform_obj, "__name__", "") or "").upper()}
    try:
        cfg = platform_obj if isinstance(platform_obj, dict) else {}
        if not isinstance(cfg, dict) or (not cfg.get("rows")):
            return out
        focus_set = set()
        try:
            if isinstance(focus_coins, (list, tuple, set)):
                focus_set = {str(x or '').upper().strip() for x in focus_coins if str(x or '').strip()}
            elif str(focus_coins or '').strip():
                focus_set = {str(focus_coins or '').upper().strip()}
        except Exception:
            focus_set = set()
        if str(cfg.get("name") or "").upper() == "EXT":
            try:
                _ext_prepare_positions_view(page)
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_189', _e)
                pass
        rows = _pw_call('exec.portfolio.rows_locator', page.locator, cfg["rows"])
        n = int(_pw_call('exec.portfolio.rows_count', rows.count) or 0)
        out["visible_rows"] = n
        if focus_set:
            try:
                out['focus_coins'] = sorted(focus_set)
            except Exception:
                out['focus_coins'] = list(focus_set)
        pos = {}
        found = set()
        for i in range(max(0, n)):
            try:
                row = rows.nth(i)
                mk = (row.locator(cfg["col_market"]).inner_text(timeout=450) or '').strip()
            except Exception:
                mk = ''
            coin_u = ''
            try:
                coin_u = norm_coin_symbol(mk)
            except Exception:
                coin_u = ''
            if not coin_u:
                continue
            coin_key = str(coin_u).upper()
            if focus_set and coin_key not in focus_set:
                continue
            try:
                side_txt = (row.locator(cfg["col_side"]).inner_text(timeout=450) or '').strip()
            except Exception:
                side_txt = ''
            try:
                value_txt = (row.locator(cfg["col_value"]).inner_text(timeout=450) or '').strip()
            except Exception:
                value_txt = ''
            parsed = _extract_position_snapshot_from_text(platform_name=str(cfg.get('name') or ''), market_txt=mk, side_txt=side_txt, value_txt=value_txt)
            pos[coin_key] = {
                "coin": coin_key,
                "side": str(parsed.get('side') or 'NONE').upper(),
                "notional_u": float(parsed.get('notional_u') or 0.0),
                "qty_abs": float(parsed.get('qty_abs') or 0.0),
            }
            if focus_set:
                found.add(coin_key)
                if bool(stop_when_found) and found >= focus_set:
                    out['early_stop'] = 1
                    break
        out["positions"] = pos
        out["available"] = bool(pos)
        if n == 0 and _exec_positions_confirmed_empty(page, cfg):
            out['available'] = True
            out['position_state'] = 'CONFIRMED_EMPTY'
        elif not pos:
            out['position_state'] = 'UNAVAILABLE'
        return out
    except Exception as e:
        out["error"] = repr(e)
        return out

def _scan_detect_positions_empty_state(page: Any, cfg: Dict[str, Any], *, platform: str = "") -> tuple[bool, str, dict]:
    plat = str(platform or (cfg or {}).get('name') or '').upper()
    detail = {'platform': plat, 'rows_count': None, 'confirmed_empty': False}
    access = _platform_access_probe(page, plat)
    if access.get('blocked'):
        detail['access'] = access
        return False, str(access['reason']), detail
    try:
        _pw_require_page(page, f'scan.empty.{plat}')
        if plat == 'EXT':
            _ext_prepare_positions_view(page)
        elif plat == 'VAR':
            _var_prepare_positions_view(page)
        rows = _pw_call('scan.empty.rows_locator', page.locator, cfg['rows'])
        count = int(_pw_call('scan.empty.rows_count', rows.count))
        detail['rows_count'] = count
        if count:
            return False, 'positions_present', detail
        selectors = (
            (r'text=/^No open positions\.?$/i', 'no_open_positions'),
            (r'text=/^No positions\.?$/i', 'no_positions'),
            (r'text=/^You have no (?:open )?positions\.?$/i', 'you_have_no_positions'),
        )
        for selector, reason in selectors:
            hint = page.locator(selector)
            for index in range(min(int(hint.count()), 10)):
                if _pw_call('scan.empty.hint_visible', hint.nth(index).is_visible):
                    detail.update(confirmed_empty=True, empty_hint=reason, empty_hint_selector=selector)
                    return True, reason, detail
        return False, 'zero_rows_unconfirmed', detail
    except Exception as exc:
        if _is_target_closed_exc(exc) or isinstance(exc, _UiDeadError):
            raise _UiDeadError(f'scan.empty.{plat}', repr(exc)) from exc
        detail['error'] = f'{type(exc).__name__}:{exc}'
        return False, 'positions_view_unavailable', detail

def _exec_verify_submit_by_portfolio(*, coin: str, kind: str, side_u: str, usd: float, pre_portfolio: dict | None, post_portfolio: dict | None) -> tuple[bool, dict]:
    coin_u = str(coin or '').upper().strip()
    pre_pos = _exec_portfolio_coin_truth(pre_portfolio, coin_u)
    post_pos = _exec_portfolio_coin_truth(post_portfolio, coin_u)
    ok, ev = _exec_verify_submit_by_row(kind=kind, side_u=side_u, usd=float(usd or 0.0), pre_row=pre_pos, post_row=post_pos)
    if not isinstance(ev, dict):
        ev = {}
    ev.update({
        'evidence': 'portfolio_snapshot',
        'coin': coin_u,
        'pre_visible_rows': int(((pre_portfolio or {}).get('visible_rows') or 0) if isinstance(pre_portfolio, dict) else 0),
        'post_visible_rows': int(((post_portfolio or {}).get('visible_rows') or 0) if isinstance(post_portfolio, dict) else 0),
        'portfolio_available': int(bool(isinstance(post_portfolio, dict) and post_portfolio.get('available'))),
    })
    return bool(ok), ev

def _exec_read_coin_page_position_snapshot(page, platform_obj, *, coin: str) -> dict:
    """优先从当前币种页读取该币持仓证据；只有币种页证据不可用时，后续才回退到总持仓列表。"""
    coin_u = str(coin or '').upper().strip()
    out = {
        'available': False,
        'coin': coin_u,
        'platform': str(getattr(platform_obj, 'name', '') or getattr(platform_obj, '__name__', '') or '').upper(),
        'detected_coin': '',
        'on_target_coin_page': 0,
        'row_found': 0,
        'confirm_source': 'coin_page_position',
    }
    try:
        cfg = platform_obj if isinstance(platform_obj, dict) else {}
        plat_name = str((cfg or {}).get('name') or out.get('platform') or '').upper().strip()
        out['platform'] = plat_name
        det_coin = ''
        try:
            if plat_name == 'VAR':
                det_coin = str(_detect_current_coin_var(page) or '').upper().strip()
            elif plat_name == 'EXT':
                det_coin = str(_detect_current_coin_ext(page) or '').upper().strip()
        except Exception as _e:
            out['detect_exc'] = repr(_e)
            det_coin = ''
        out['detected_coin'] = det_coin
        on_target = bool(coin_u and det_coin and det_coin == coin_u)
        out['on_target_coin_page'] = int(on_target)
        if not on_target:
            out['reason'] = 'coin_page_not_confirmed'
            return out
        try:
            row = _exec_read_position_truth(page, cfg, coin_u)
        except Exception as _e:
            out['read_exc'] = repr(_e)
            row = None
        out['available'] = _safety_position_read(row)[0] != 'UNAVAILABLE'
        if not out['available']:
            out['reason'] = 'coin_page_truth_unavailable'
            return out
        if isinstance(row, dict):
            out['row_found'] = 1
            out['row'] = dict(row)
            try:
                _side, _notional = _exec_row_side_notional(row)
            except Exception:
                _side, _notional = '', 0.0
            out['side'] = str(_side or '')
            out['notional_u'] = float(_notional or 0.0)
            return out
        out['row_found'] = 0
        out['row'] = None
        out['side'] = 'NONE'
        out['notional_u'] = 0.0
        out['reason'] = out.get('reason') or 'coin_page_row_missing'
        return out
    except Exception as _e:
        out['error'] = repr(_e)
        return out

def _exec_submit_timeout_for_kind(platform_name: str, kind: str, *, reduce_only: bool = False) -> float:
    """第二阶段修复：提交确认超时按动作分流，避免所有动作都死等同一口径。"""
    try:
        plat = str(platform_name or '').upper().strip()
    except Exception:
        plat = ''
    try:
        kind_l = str(kind or '').lower().strip()
    except Exception:
        kind_l = ''
    is_reduce = bool(reduce_only) or kind_l in ('close','close_all','decrease','reduce','tp','trend_tp','partial_close','koujing_a_3step','close_partial_notional')
    try:
        if is_reduce:
            base = float(_exec_cfg_float('EXEC_SUBMIT_TIMEOUT_REDUCE_SEC', 1.0 if plat == 'VAR' else 1.2))
        elif kind_l in ('open','increase','add','add_leg','open_leg','open_pair','open_full'):
            base = float(_exec_cfg_float('EXEC_SUBMIT_TIMEOUT_OPEN_SEC', 1.3 if plat == 'VAR' else 1.5))
        else:
            base = float(_exec_cfg_float('EXEC_SUBMIT_TIMEOUT_DEFAULT_SEC', 1.5 if plat == 'VAR' else 1.8))
    except Exception:
        base = 1.2 if is_reduce else 1.5
    try:
        return max(0.6, float(base))
    except Exception:
        return 1.2 if is_reduce else 1.5

def _exec_verify_submit_fast_row_only(*, coin: str, kind: str, side_u: str, usd: float, pre_row: Any, post_row: Any) -> tuple[bool, dict]:
    ok_row, ev_row = _exec_verify_submit_by_row(kind=kind, side_u=side_u, usd=float(usd or 0.0), pre_row=pre_row, post_row=post_row)
    out = {'coin': str(coin or '').upper(), 'kind': str(kind or ''), 'row_ok': int(bool(ok_row)), 'portfolio_ok': 0, 'confirm_mode': 'row_only_fast'}
    if isinstance(ev_row, dict):
        out['row_evidence'] = dict(ev_row)
    return bool(ok_row), out

def _exec_should_skip_portfolio_verify(kind: str, *, elapsed_s: float = 0.0, round_idx: int = 0) -> bool:
    """第二阶段修复：早期确认优先看 row，不让 portfolio 读取拖住 worker。"""
    try:
        kind_l = str(kind or '').lower().strip()
    except Exception:
        kind_l = ''
    try:
        fast_rounds = int(_exec_cfg_float('EXEC_VERIFY_FAST_ROW_ONLY_ROUNDS', 2))
    except Exception:
        fast_rounds = 2
    try:
        skip_initial_sec = float(_exec_cfg_float('EXEC_VERIFY_SKIP_PORTFOLIO_INITIAL_SEC', 0.9))
    except Exception:
        skip_initial_sec = 0.9
    try:
        reduce_fast_rounds = int(_exec_cfg_float('EXEC_VERIFY_REDUCE_FAST_ROW_ONLY_ROUNDS', 2))
    except Exception:
        reduce_fast_rounds = 2
    try:
        reduce_skip_initial_sec = float(_exec_cfg_float('EXEC_VERIFY_REDUCE_SKIP_PORTFOLIO_INITIAL_SEC', 0.65))
    except Exception:
        reduce_skip_initial_sec = 0.65
    reduce_like = kind_l in ('close','close_all','decrease','reduce','tp','trend_tp','partial_close','koujing_a_3step','close_partial_notional')
    open_like = kind_l in ('open','increase','add','add_leg','open_leg','open_pair','open_full')
    if reduce_like:
        if (int(round_idx or 0) <= max(1, reduce_fast_rounds)) and (float(elapsed_s or 0.0) <= max(0.35, reduce_skip_initial_sec)):
            return True
        return False
    if open_like and ((int(round_idx or 0) <= max(1, fast_rounds)) or (float(elapsed_s or 0.0) <= max(0.3, skip_initial_sec))):
        return True
    return False

def _exec_verify_submit_dual_evidence(*, coin: str, kind: str, side_u: str, usd: float, pre_row: Any, post_row: Any, pre_portfolio: dict | None = None, post_portfolio: dict | None = None, skip_portfolio: bool = False) -> tuple[bool, dict]:
    """复检单链化：只认平台当前币当前腿的真实持仓变化。

    人话：
    - 不再把 portfolio 当成单笔提交后的主判官；
    - 不再做 row + portfolio 双裁决；
    - 单笔提交后只看当前币页面/持仓行是否发生真实变化；
    - 看不到就返回未确认，交给 pending / 下轮统一复检。
    """
    ok_row, ev_row = _exec_verify_submit_by_row(kind=kind, side_u=side_u, usd=float(usd or 0.0), pre_row=pre_row, post_row=post_row)
    out = {
        'coin': str(coin or '').upper(),
        'kind': str(kind or ''),
        'row_ok': int(bool(ok_row)),
        'portfolio_ok': 0,
        'exchange_effect_ok': int(bool(ok_row)),
        'confirm_mode': 'platform_row_truth_only',
        'reason_code': ('commit_success' if bool(ok_row) else 'exchange_effect_unconfirmed'),
        'commit_ok': int(bool(ok_row)),
        'final_ok': int(bool(ok_row)),
        'portfolio_bypassed': 1,
    }
    if isinstance(ev_row, dict):
        out['row_evidence'] = dict(ev_row)
    if bool(skip_portfolio):
        out['confirm_mode'] = 'platform_row_truth_only_fast'
        out['portfolio_skipped_fast'] = 1
    return bool(ok_row), out

def _exec_poll_submit_verify_by_row(page, platform_obj, *, coin: str, kind: str, side_u: str, usd: float, pre_row: Any, pre_portfolio: dict | None = None, label: str = "") -> tuple[bool, dict]:
    try:
        kind_l = str(kind or '').lower().strip()
    except Exception:
        kind_l = ''
    reduce_like = kind_l in ('close','close_all','decrease','reduce','tp','trend_tp','partial_close','koujing_a_3step','close_partial_notional')
    try:
        if reduce_like:
            schedule = [0.18, 0.35, 0.60, 1.00, 1.60]
        else:
            schedule = [0.12, 0.18, 0.28, 0.45]
    except Exception:
        schedule = [0.18, 0.35, 0.60, 1.00, 1.60] if reduce_like else [0.12, 0.18, 0.28, 0.45]
    last_ev = {"kind": str(kind or ""), "reason": "poll_not_started"}
    _perf_t0 = _exec_perf_now()
    try:
        _plat_name = (getattr(platform_obj, "name", "") or getattr(platform_obj, "__name__", "") or "") if platform_obj is not None else ""
    except Exception:
        _plat_name = ""
    for idx, wait_s in enumerate(schedule, 1):
        try:
            _exec_step_sleep(float(wait_s), f"POST_SUBMIT_POLL:{label}:#{idx}")
        except Exception:
            try:
                time.sleep(float(wait_s))
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_193', _e)
                pass
        _coin_page_snap = {"available": False, "confirm_source": "coin_page_position"}
        try:
            _coin_page_snap = _exec_read_coin_page_position_snapshot(page, platform_obj, coin=coin)
        except Exception:
            _coin_page_snap = {"available": False, "confirm_source": "coin_page_position"}
        try:
            post_row = (_coin_page_snap.get('row') if bool((_coin_page_snap or {}).get('available')) else None)
            if (not bool((_coin_page_snap or {}).get('available'))):
                post_row = _exec_read_position_truth(page, platform_obj, coin)
        except Exception:
            post_row = None
        ok2, ev = _exec_verify_submit_dual_evidence(coin=coin, kind=kind, side_u=side_u, usd=float(usd or 0.0), pre_row=pre_row, post_row=post_row, pre_portfolio=pre_portfolio, post_portfolio=None, skip_portfolio=True)
        try:
            if isinstance(ev, dict):
                ev.setdefault('poll_round', int(idx))
                ev.setdefault('portfolio_skipped_fast', 1)
                ev.setdefault('portfolio_bypassed', 1)
                ev.setdefault('row_source', str((_coin_page_snap or {}).get('confirm_source') or ('coin_page_position' if bool((_coin_page_snap or {}).get('available')) else 'positions_list')))
                ev.setdefault('coin_page_available', int(bool((_coin_page_snap or {}).get('available'))))
                ev.setdefault('coin_page_row_found', int(bool((_coin_page_snap or {}).get('row_found'))))
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_194', _e)
            pass
        try:
            safe_log(lambda: f"[{_exec_ts()}] [EXECUTOR（执行器）] POST_SUBMIT_POLL: {label} | round={idx} ok={1 if ok2 else 0} truth=row_only ev={ev}")
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_195', _e)
            pass
        last_ev = dict(ev or {})
        if ok2:
            _exec_perf_log_safe("submit_verify_poll_done", plat=_plat_name, coin=coin, label=label, result="ok", total_ms=_exec_perf_ms(_perf_t0), round=idx, verify_kind=((last_ev or {}).get("kind") or ""), portfolio_skipped_fast=1)
            return True, last_ev
    _exec_perf_log_safe("submit_verify_poll_done", plat=_plat_name, coin=coin, label=label, result="fail", total_ms=_exec_perf_ms(_perf_t0), rounds=len(schedule), verify_kind=((last_ev or {}).get("kind") or ""))
    return False, last_ev

def _exec_perf_now() -> float:
    try:
        return float(time.time())
    except Exception:
        return 0.0

def _exec_perf_ms(t0: float, t1: float | None = None) -> float:
    try:
        if t1 is None:
            t1 = _exec_perf_now()
        return round(max(0.0, (float(t1) - float(t0)) * 1000.0), 1)
    except Exception:
        return 0.0

def _exec_perf_log(stage: str, *, plat: str = "", coin: str = "", label: str = "", side: str = "", result: str = "", **kwargs) -> None:
    """执行器全流程耗时日志：直接看慢在按钮/提交/toast/持仓/双平台间隔哪里。"""
    try:
        parts = [f"stage={str(stage or '')}"]
        if plat:
            parts.append(f"plat={str(plat or '').upper()}")
        if coin:
            parts.append(f"coin={str(coin or '').upper()}")
        if label:
            parts.append(f"label={str(label)}")
        if side:
            parts.append(f"side={str(side)}")
        if result:
            parts.append(f"result={str(result)}")
        for k, v in (kwargs or {}).items():
            if v is None:
                continue
            try:
                if isinstance(v, float):
                    parts.append(f"{k}={v:.1f}")
                else:
                    parts.append(f"{k}={v}")
            except Exception:
                parts.append(f"{k}={repr(v)}")
        safe_log(lambda: f"[{_exec_ts()}] [EXEC_PERF（执行耗时）] " + " | ".join(parts))
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_196', _e)
        pass
def _exec_perf_log_safe(stage: str, *, plat: str = "", coin: str = "", label: str = "", side: str = "", result: str = "", **kwargs) -> None:
    """perf 日志只能尽力记录，不能反噬交易主链。"""
    try:
        _exec_perf_log(stage, plat=plat, coin=coin, label=label, side=side, result=result, **kwargs)
    except Exception as _e:
        try:
            _log_exc_level(mod="EXEC", stage="PERF_LOG_FAIL", level="B", e=_e, plat=str(plat or ""), coin=str(coin or ""), msg=str(stage or ""))
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_197', _e)
            pass
def _exec_clear_pending(plat: str, coin: str, side: str, *, kind=None) -> None:
    from bot_core import submission_scope as scope
    try:
        records = _safety_submission_records()
        if globals().get('_SAFETY_SUBMISSION_FAULT'):
            return
        prefix = scope.memory_key(plat, coin, side)
        for k in set(_EXEC_PENDING) | set(_EXEC_PENDING_INFO):
            operation = scope.memory_kind(k, _EXEC_PENDING_INFO.get(k))
            if k[:3] != prefix or (kind is not None and operation != scope.family(kind)):
                continue
            if any(scope.family(rec.get('kind')) == operation and scope.blocks(rec, plat, coin, operation, side)
                   for rec in records.values()):
                continue
            _EXEC_PENDING.pop(k, None)
            _EXEC_PENDING_INFO.pop(k, None)
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_198', _e)
        pass
def _exec_enrich_req_price_fields(req: dict, order: Any, det_d: dict | None = None) -> dict:
    """统一把 request/exec/fill 价格补进 req/meta，避免回执/摘要口径失真。"""
    try:
        if not isinstance(req, dict):
            return req
        meta = req.get("meta") if isinstance(req.get("meta"), dict) else {}
        req["meta"] = meta
        try:
            if isinstance(getattr(order, "meta", None), dict):
                for _k in ("req_id", "trace_id", "request_price", "fill_price", "avg_fill_price", "exec_price", "fill_price_source"):
                    _v = getattr(order, "meta", {}).get(_k)
                    if _v not in (None, ""):
                        meta[_k] = _v
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_199', _e)
            pass
        try:
            for _k in ("fill_price", "avg_fill_price", "exec_price"):
                _v = getattr(order, _k, None)
                if _v not in (None, ""):
                    meta[_k] = _v
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_200', _e)
            pass
        try:
            _req_px = _exec_request_price_from_order(order)
        except Exception:
            _req_px = None
        if _req_px not in (None, ""):
            meta.setdefault("request_price", _req_px)
        try:
            _reqd = None
            if isinstance(det_d, dict):
                _reqd = det_d.get("req") if isinstance(det_d.get("req"), dict) else det_d
            _px2 = _extract_exec_price_from_req(_reqd) if isinstance(_reqd, dict) else None
        except Exception:
            _px2 = None
        if _px2 not in (None, ""):
            meta.setdefault("exec_price", _px2)
        try:
            if meta.get("fill_price") not in (None, ""):
                req["fill_price"] = meta.get("fill_price")
            if meta.get("avg_fill_price") not in (None, ""):
                req["avg_fill_price"] = meta.get("avg_fill_price")
            if meta.get("request_price") not in (None, ""):
                req["request_price"] = meta.get("request_price")
            if meta.get("exec_price") not in (None, ""):
                req["exec_price"] = meta.get("exec_price")
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_201', _e)
            pass
        return req
    except Exception:
        return req

def _exec_record_verified_timeout_success(*, plat: str, coin: str, order: Any, side: str, usd: float, kind: str, det: dict, ev: dict) -> None:
    """[PATCH][A] 回执超时但二次核验确认“持仓已变化”时：强制把这笔“视为成功”的动作落盘到
    1) logs/executor_results.jsonl（执行器结果）
    2) trades.jsonl（面板摘要唯一数据源）
    并尽量回写本地 ledger（用于网格/止盈后续核销）。
    """
    try:
        p = str(plat or "").upper().strip()
        c = str(coin or "").upper().strip()
        det_d = _as_dict(det, mod="EXEC", coin=c, ctx="verified_timeout.det")
        ev_d = _as_dict(ev, mod="EXEC", coin=c, ctx="verified_timeout.ev")
        _req0 = det_d.get("req")
        req_d = _req0 if isinstance(_req0, dict) else {}
        s = str(side or "").lower().strip()
        u = float(usd or 0.0)
        reduce_only = bool(getattr(order, "reduce_only", False))
        act = "decrease" if (reduce_only or str(kind or "").lower().startswith("close")) else "increase"

        note = ""
        try:
            note = str(getattr(order, "guard_note", "") or "")
        except Exception:
            note = ""
        if not note:
            note = "VERIFIED_TIMEOUT"

        _order_meta = dict(getattr(order, "meta", {}) or {}) if isinstance(getattr(order, "meta", None), dict) else {}
        req = {
            "platform": p,
            "module": (str(getattr(order, 'module', '') or (det_d.get('module') or '') or ((req_d or {}) if isinstance(req_d, dict) else {}).get('module') or '').upper().strip()),
            "coin": c,
            "side": s,
            "action_type": act,
            "amount_usd": u,
            "amount_u": u,  # 口径：面板摘要用 U（USD notional）
            "reduce_only": bool(reduce_only),
            "meta": {
                **_order_meta,
                "from": note,
                "trace_id": (str(getattr(order, 'trace_id', '') or getattr(order, 'tid', '') or ((req_d or {}) if isinstance(req_d, dict) else {}).get('trace_id') or '')),
                "orig_module": (str(getattr(order, 'module', '') or '').upper().strip()),
                "orig_action_type": (str(getattr(order, 'action_type', '') or kind or '').lower().strip()),
                "ind_rsi": (_order_meta.get("ind_rsi") if isinstance(_order_meta, dict) else None),
                "ind_adx": (_order_meta.get("ind_adx") if isinstance(_order_meta, dict) else None),
                "ind_ts": (_order_meta.get("ind_ts") if isinstance(_order_meta, dict) else None),
                "ind_age_sec": (_order_meta.get("ind_age_sec") if isinstance(_order_meta, dict) else None),
                "verified_timeout": True,
                "verify": ev_d,
            },
        }
        try:
            req = _exec_enrich_req_price_fields(req, order, det_d)
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_202', _e)
            pass
        res = {
            "ok": True,
            "reason": "receipt_timeout_but_verified",
            "verified": True,
            "ts": float(time.time()),
            "req": req,
            "det": det_d,
            "verify": ev_d,
            "exec_u": u,
            "notional_u": u,
        }

        try:
            if hasattr(order, "meta") and isinstance(getattr(order, "meta", None), dict):
                getattr(order, "meta")["verified_timeout_success"] = True
                getattr(order, "meta")["verified_timeout_reason"] = "receipt_timeout_but_verified"
                getattr(order, "meta")["verified_timeout_verify"] = ev_d
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_203', _e)
            pass
    except Exception as _e:
        _log_exc_level(mod="EXEC", stage="WAIT_BTN_LOOP_FAIL", level="C", e=_e)

def _exec_mark_pending_info(plat: str, coin: str, side: str, *, kind: str = "open", pre_row: Any = None, usd: float = 0.0, detail: dict | None = None) -> None:
    """写入 pending + 详细信息（对账用）。"""
    from bot_core import submission_scope as scope
    try:
        k = scope.memory_key(plat, coin, side, kind)
        pre_s, pre_n = _exec_row_side_notional(pre_row)
        _safety_reserve_submission(plat, coin, side, kind, pre_row, usd, allow_existing=True)
        _EXEC_PENDING.setdefault(k, float(time.time()))
        _EXEC_PENDING_INFO.setdefault(k, {
            "pre_position": dict(pre_row) if isinstance(pre_row, dict) else None,
            "ts": float(_EXEC_PENDING[k]),
            "kind": str(kind or "open"),
            "intent_usd": float(usd or 0.0),
            "before_side": pre_s,
            "before_notional_u": float(pre_n or 0.0),
            "detail": (detail or {}),
        })
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_204', _e)
        pass
def _exec_reconcile_pending_by_row(plat: str, coin: str, row: Any) -> None:
    """在扫描持仓时对账 pending：一旦观察到符合预期的持仓变化，自动清除 pending。"""
    try:
        p = str(plat or "").upper().strip()
        c = str(coin or "").upper().strip()
        if p not in ("EXT","VAR") or not c:
            return
        _safety_resolve_submission(p, c, row)
        post_s, post_n = _exec_row_side_notional(row)
        from bot_core import submission_scope as scope
        for k in list(_EXEC_PENDING):
            if k[:2] != (p, c):
                continue
            s = k[2]
            info = _EXEC_PENDING_INFO.get(k) or {}
            kind = str(info.get("kind") or scope.memory_kind(k, info))
            _exec_clear_pending(p, c, s, kind=kind)
            if k not in _EXEC_PENDING:
                continue
            usd = float(info.get("intent_usd") or 0.0)
            pre_row = info.get("pre_position")
            ok, ev = _exec_verify_submit_by_row(kind=kind, side_u=s, usd=usd, pre_row=pre_row, post_row=row)
            if ok:
                try:
                    _pin("EXEC_PENDING_RESOLVED", mod="EXEC", plat=p, coin=c, side=s, ok=1,
                         reason="reconciled_by_position", kind=kind, intent_usd=usd,
                         pre_side=str(ev.get("pre_side","")), pre_notional=float(ev.get("pre_notional") or 0.0),
                         post_side=str(ev.get("post_side","")), post_notional=float(ev.get("post_notional") or 0.0))
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_205', _e)
                    pass
                _safety_resolve_submission(p, c, row)
                _exec_clear_pending(p, c, s, kind=kind)
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_206', _e)
        pass
def _exec_mark_pending(plat: str, coin: str, side: str, *, ts: float | None = None, kind='open') -> None:
    from bot_core import submission_scope as scope
    try:
        k = scope.memory_key(plat, coin, side, kind)
        _EXEC_PENDING[k] = float(ts or time.time())
    except Exception:
        return

def _exec_pending_active(plat: str, coin: str, side: str, *, now: float | None = None, ttl_sec: int | None = None, kind='open') -> bool:
    from bot_core import submission_scope as scope
    if _safety_pending_scope(plat, coin, kind, side):
        return True
    return any(scope.blocks({'platform': k[0], 'coin': k[1], 'side': k[2],
                             'kind': scope.memory_kind(k, _EXEC_PENDING_INFO.get(k)), 'state': 'PENDING_CONFIRM'},
                            plat, coin, kind, side) for k in list(_EXEC_PENDING))

_RSI_LAST_PICK_U: dict[tuple[str, str, str], float] = {}

def _pending_side_coins(plat: str, side: str, *, now: float | None = None, ttl_sec: int | None = None) -> list[str]:
    p, s = str(plat or '').upper(), str(side or '').upper()
    coins = {str(k[1]) for k in list(_EXEC_PENDING) if k[0] == p and k[2] == s}
    for rec in _safety_submission_records().values():
        if rec.get('platform') == p and rec.get('side') == s and _safety_pending_blocks(rec):
            coins.add(str(rec.get('coin') or ''))
    return sorted(c for c in coins if c)

def _pos_side(pos: dict) -> str:
    """统一抽取持仓方向：LONG/SHORT/''。
    说明：历史版本里 _pos_side 可能被占位 lambda 覆盖，导致 4v4 统计永远为 0（穿顶根因之一）。
    这里强制在全局定义一次，供所有模块使用。
    """
    try:
        if not isinstance(pos, dict):
            return ""
        s = pos.get("side") or pos.get("pos_side") or pos.get("position_side") or pos.get("direction")
        s = str(s or "").upper().strip()
        return s if s in ("LONG", "SHORT") else ""
    except Exception:
        return ""

try:
    _POS_DISK_CACHE  # type: ignore
except Exception:
    _POS_DISK_CACHE = {"ts": 0.0, "data": None, "path": ""}

def _load_positions_from_disk_fallback() -> dict:
    """兜底从磁盘读取最近一次 positions.json。

    你遇到的“日志里一直在读数据，但落盘不更新/决策不按最新数据”，最常见根因是：
    - Windows 下文件被面板短暂占用导致 _safe_write_json 写入失败，最新内容会落在 *.pending；
    - 旧版本读取端只读 positions.json，不读 positions.json.pending，结果一直用旧数据决策/展示。
    这里做两件事：
    1) 读取时优先选择“mtime 更新”的那个（positions.json vs positions.json.pending）；
    2) 同时覆盖 PANEL_OUT_DIR 与 OUT_DIR 两套路径，避免目录口径不一致。
    """
    try:
        now = time.time()
    except Exception:
        now = 0.0

    try:
        cache = globals().get("_POS_DISK_CACHE") or {}
    except Exception:
        cache = {}
    try:
        if float(cache.get("ts") or 0.0) and (now - float(cache.get("ts") or 0.0) < 1.0):
            d = cache.get("data")
            return d if isinstance(d, dict) else {}
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_210', _e)
        pass
    def _mtime(p: str) -> float:
        try:
            return float(os.path.getmtime(p))
        except Exception:
            return -1.0

    def _best(p: str) -> list:
        """返回候选 [pending, main] 中更“新”的优先顺序（只返回存在的）。"""
        out = []
        if not p:
            return out
        pend = p + ".pending"
        try:
            if os.path.exists(pend):
                out.append((pend, _mtime(pend)))
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_211', _e)
            pass
        try:
            if os.path.exists(p):
                out.append((p, _mtime(p)))
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_212', _e)
            pass
        out.sort(key=lambda x: x[1], reverse=True)
        return [x[0] for x in out]

    cand = []
    try:
        for p in _best(str(globals().get("POSITIONS_FP") or "")):
            cand.append(p)
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_213', _e)
        pass
    try:
        for p in _best(str(globals().get("POSITIONS_FP_FALLBACK") or "")):
            cand.append(p)
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_214', _e)
        pass
    try:
        od = globals().get("OUT_DIR") or ""
        if od:
            for p in _best(os.path.join(str(od), "positions.json")):
                cand.append(p)
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_215', _e)
        pass
    try:
        for p in _best(os.path.join(os.path.dirname(__file__), "out", "positions.json")):
            cand.append(p)
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_216', _e)
        pass
    _seen = set()
    cand2 = []
    for p in cand:
        ap = os.path.abspath(str(p))
        if ap in _seen:
            continue
        _seen.add(ap)
        cand2.append(ap)

    data = {}
    used = ""
    for p in cand2:
        try:
            obj = safe_read_json(p, default=None, retries=2)
            if isinstance(obj, dict) and obj:
                data = obj
                used = p
                break
        except Exception:
            continue

    try:
        globals()["_POS_DISK_CACHE"] = {"ts": now, "data": data if isinstance(data, dict) else {}, "path": used}
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_217', _e)
        pass
    return data if isinstance(data, dict) else {}

def _snap_get_pos_any(snapshot: dict, platform: str, coin: str, side: str = "") -> dict:
    """从 snapshot / positions.json 中按平台+币(+方向)读取单腿持仓。"""
    def _norm_side(v: str) -> str:
        s = str(v or '').strip().upper()
        if s in ('BUY', 'LONGS'):
            return 'LONG'
        if s in ('SELL', 'SHORTS'):
            return 'SHORT'
        return s

    def _coin_variants(coin_u: str, plat_u: str) -> list[str]:
        out: list[str] = []
        try:
            base = str(coin_u or '').upper().strip()
        except Exception:
            base = ''
        if base:
            out.append(base)
        if str(plat_u or '').upper().strip() == 'EXT':
            try:
                canon = _ext_canonical_coin(base)
            except Exception:
                canon = base
            try:
                for _alias in _ext_coin_aliases(canon):
                    aa = str(_alias or '').upper().strip()
                    if aa and aa not in out:
                        out.append(aa)
            except Exception:
                pass
        return out

    def _row_coin(row: dict, plat_u: str = '') -> str:
        raw = str(row.get('coin') or row.get('symbol') or row.get('asset') or '').upper().strip()
        if str(plat_u or '').upper().strip() == 'EXT':
            try:
                return _ext_canonical_coin(raw) or raw
            except Exception:
                return raw
        return raw

    def _row_plat(row: dict, default: str = '') -> str:
        return str(row.get('platform') or row.get('plat') or row.get('exchange') or default or '').upper().strip()

    def _pick_dict_pos(node: dict, variants: list[str], plat_u: str, side_u: str) -> dict:
        if not isinstance(node, dict):
            return {}
        for _k in variants:
            try:
                pos = node.get(_k) or node.get(str(_k or '').lower())
            except Exception:
                pos = None
            if isinstance(pos, dict):
                _norm = _normalize_snapshot_position_row(pos, coin=(variants[0] if variants else ''), platform=plat_u, side=side_u)
                return _norm or pos
            if isinstance(pos, list):
                got = _pick_from_list(pos, variants, plat_u, side_u)
                if got:
                    return got
        return {}

    def _pick_from_list(rows, variants: list[str], plat_u: str, side_u: str) -> dict:
        if not isinstance(rows, list):
            return {}
        hits = []
        canon_variants = set()
        for _v in list(variants or []):
            vv = str(_v or '').upper().strip()
            if not vv:
                continue
            canon_variants.add(vv)
            if plat_u == 'EXT':
                try:
                    canon_variants.add(_ext_canonical_coin(vv) or vv)
                except Exception:
                    pass
        for row in rows:
            if not isinstance(row, dict):
                continue
            rc_raw = str(row.get('coin') or row.get('symbol') or row.get('asset') or '').upper().strip()
            rc_cmp = _row_coin(row, plat_u)
            if canon_variants and rc_cmp and rc_cmp not in canon_variants and rc_raw not in canon_variants:
                continue
            rp = _row_plat(row, plat_u)
            if plat_u and rp and rp != plat_u:
                continue
            hits.append(row)
        if not hits:
            return {}
        if side_u:
            for row in hits:
                if _norm_side(row.get('side') or row.get('positionSide') or row.get('direction') or '') == side_u:
                    return row
        return hits[0] if hits else {}

    try:
        s = snapshot or {}
        try:
            if not (isinstance(s, dict) and (s.get('positions') or s.get('by_coin') or s.get('coins') or s.get('EXT') or s.get('VAR') or s.get('ext') or s.get('var'))):
                _disk = _load_positions_from_disk_fallback()
                if isinstance(_disk, dict) and _disk:
                    if isinstance(_disk.get('positions'), (dict, list)):
                        s = {'positions': (_disk.get('positions') or {})}
                    elif any(k in _disk for k in ('EXT', 'VAR', 'ext', 'var')):
                        s = {'positions': _disk}
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_218', _e)
            pass
        cu = str(coin or '').upper().strip()
        pu = str(platform or '').upper().strip()
        su = _norm_side(side)
        if not cu or not pu:
            return {}
        variants = _coin_variants(cu, pu)
        try:
            _positions = (s.get('positions') if isinstance(s, dict) else None)
            if isinstance(_positions, dict):
                pnode = _positions.get(pu) or _positions.get(pu.lower())
                if isinstance(pnode, dict):
                    got = _pick_dict_pos(pnode, variants, pu, su)
                    if got:
                        return got
                elif isinstance(pnode, list):
                    got = _pick_from_list(pnode, variants, pu, su)
                    if got:
                        return got
            elif isinstance(_positions, list):
                got = _pick_from_list(_positions, variants, pu, su)
                if got:
                    return got
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_219', _e)
            pass
        try:
            if isinstance(s, dict):
                for _vk in variants:
                    pos = (((s.get('by_coin') or {}).get(_vk) or {}).get(pu))
                    if isinstance(pos, dict):
                        _norm = _normalize_snapshot_position_row(pos, coin=cu, platform=pu, side=su)
                        return _norm or pos
                    if isinstance(pos, list):
                        got = _pick_from_list(pos, variants, pu, su)
                        if got:
                            return got
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_220', _e)
            pass
        try:
            cc = {}
            if isinstance(s, dict):
                for _vk in variants:
                    cc = ((s.get('coins') or {}).get(_vk) or {})
                    if isinstance(cc, dict) and cc:
                        break
            if isinstance(cc, dict):
                if pu == 'EXT':
                    pos = cc.get('EXT') or cc.get('ext')
                else:
                    pos = cc.get('VAR') or cc.get('var')
                if isinstance(pos, dict):
                    _norm = _normalize_snapshot_position_row(pos, coin=cu, platform=pu, side=su)
                    return _norm or pos
                if isinstance(pos, list):
                    got = _pick_from_list(pos, variants, pu, su)
                    if got:
                        return got
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_221', _e)
            pass
        try:
            if isinstance(s, dict):
                root_node = s.get(pu) or s.get(pu.lower())
                if isinstance(root_node, dict):
                    got = _pick_dict_pos(root_node, variants, pu, su)
                    if got:
                        return got
                elif isinstance(root_node, list):
                    got = _pick_from_list(root_node, variants, pu, su)
                    if got:
                        return got
                raw_root = s.get('raw_positions') or s.get('raw_pos')
                if isinstance(raw_root, dict):
                    pnode = raw_root.get(pu) or raw_root.get(pu.lower())
                    if isinstance(pnode, dict):
                        got = _pick_dict_pos(pnode, variants, pu, su)
                        if got:
                            return got
                    elif isinstance(pnode, list):
                        got = _pick_from_list(pnode, variants, pu, su)
                        if got:
                            return got
            elif isinstance(s, list):
                got = _pick_from_list(s, variants, pu, su)
                if got:
                    return got
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_222', _e)
            pass
        try:
            _disk = _load_positions_from_disk_fallback()
            if isinstance(_disk, dict) and _disk:
                _disk_s = {'positions': (_disk.get('positions') or {}), 'raw_positions': (_disk.get('raw_positions') or {}), 'EXT': _disk.get('EXT'), 'VAR': _disk.get('VAR')}
                if _disk_s != s:
                    got = _snap_get_pos_any(_disk_s, pu, cu, su)
                    if isinstance(got, dict) and got:
                        return got
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_222b', _e)
            pass
        return {}
    except Exception:
        return {}

def _platform_side_coins_union(snapshot: dict, platform: str, *, return_debug: bool = False):
    """合并多个结构得到平台 LONG/SHORT 的币种集合（union，严格防漏算）。

    返回：(long_set, short_set, debug_dict)
    debug_dict 用于判案：包含 positions_only 与 union 的差异。
    """
    p = str(platform or "").upper()
    long_set: set[str] = set()
    short_set: set[str] = set()

    keys: set[str] = set()
    try:
        keys |= set((((snapshot or {}).get("positions") or {}).get(p) or {}).keys())
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_223', _e)
        pass
    try:
        keys |= set((((snapshot or {}).get("by_coin") or {}) or {}).keys())
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_224', _e)
        pass
    try:
        keys |= set((((snapshot or {}).get("coins") or {}) or {}).keys())
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_225', _e)
        pass
    pos_only_l: set[str] = set()
    pos_only_s: set[str] = set()
    try:
        pos_all = (((snapshot or {}).get("positions") or {}).get(p) or {})
        if isinstance(pos_all, dict):
            for c, pd in pos_all.items():
                cu = str(c or "").upper()
                if not cu:
                    continue
                try:
                    if _has_pos(pd or {}):
                        sd = _pos_side(pd or {})
                        if sd == "LONG":
                            pos_only_l.add(cu)
                        elif sd == "SHORT":
                            pos_only_s.add(cu)
                except Exception:
                    continue
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_226', _e)
        pass
    for c in list(keys):
        cu = str(c or "").upper()
        if not cu:
            continue
        pd = _snap_get_pos_any(snapshot or {}, p, cu)
        try:
            if _has_pos(pd or {}):
                sd = _pos_side(pd or {})
                if sd == "LONG":
                    long_set.add(cu)
                elif sd == "SHORT":
                    short_set.add(cu)
        except Exception:
            continue

    dbg = {}
    try:
        if return_debug:
            dbg = {
                "platform": p,
                "pos_only_long": sorted(list(pos_only_l))[:64],
                "pos_only_short": sorted(list(pos_only_s))[:64],
                "union_long": sorted(list(long_set))[:64],
                "union_short": sorted(list(short_set))[:64],
                "mismatch": bool((pos_only_l != long_set) or (pos_only_s != short_set)),
            }
            if dbg.get("mismatch"):
                try:
                    if "_pin" in globals():
                        globals()["_pin"]("SNAP_4V4_MISMATCH", mod="SYS", coin="*", plat=p, ok=0,
                                         reason="positions_vs_union_mismatch",
                                         pos_only_long=len(pos_only_l), pos_only_short=len(pos_only_s),
                                         union_long=len(long_set), union_short=len(short_set),
                                         pos_only_long_coins=dbg["pos_only_long"],
                                         pos_only_short_coins=dbg["pos_only_short"],
                                         union_long_coins=dbg["union_long"],
                                         union_short_coins=dbg["union_short"])
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_227', _e)
                    pass
    except Exception:
        dbg = {}

    return long_set, short_set, dbg

def _count_platform_ls_from_snapshot(snapshot: dict, platform: str) -> tuple[int, int, list[str]]:
    """从 snapshot 中统计平台【实际已开】的多/空“币种腿数”（严格防漏算）。

    历史根因：不同模块使用的快照结构不一致（positions/by_coin/coins.ext|var），导致 4v4 统计偏小从而穿顶。
    本实现采用“多源合并（union）”策略：只要任一结构里判定为有仓，就计入名额（宁可多拦截，绝不漏拦截）。
    返回 (long_cnt, short_cnt, coins_list)。
    """
    try:
        p = str(platform or "").upper()
        longs, shorts, _dbg = _platform_side_coins_union(snapshot or {}, p, return_debug=True)
        coins = sorted(list(longs | shorts))[:64]
        return int(len(longs)), int(len(shorts)), coins
    except Exception:
        return 0, 0, []

def _platform_side_coins_from_snapshot(snapshot: dict, platform: str) -> tuple[set[str], set[str]]:
    """返回平台上【实际已开】的 LONG/SHORT 币种集合（按 coin 计数，严格防漏算）。"""
    try:
        longs, shorts, _ = _platform_side_coins_union(snapshot or {}, str(platform or "").upper(), return_debug=False)
        return longs, shorts
    except Exception:
        return set(), set()

def _platform_budget_4v4(snapshot: dict, platform: str) -> dict:
    """按“单平台 4多4空”计算剩余名额（口径：**不扣 pending**）。

    说明：
    - pending 重复下单由 A1 的 `_exec_pending_active()` 统一拦截；
    - 这里的 budget 只反映“当前持仓已占用的腿数”，避免与单轮手动扣减/入队去重产生双重扣减口径冲突。
    """
    try:
        p = str(platform or "").upper()
        act_l_set, act_s_set = _platform_side_coins_from_snapshot(snapshot, p)
        pend_l = _pending_side_coins(p, "LONG")
        pend_s = _pending_side_coins(p, "SHORT")
        pend_l_eff = len(set(pend_l) - set(act_l_set))
        pend_s_eff = len(set(pend_s) - set(act_s_set))
        act_l = len(act_l_set)
        act_s = len(act_s_set)
        return {
            "act_long": int(act_l),
            "act_short": int(act_s),
            "pend_long": int(pend_l_eff),
            "pend_short": int(pend_s_eff),
            "budget_long": int(max(0, 4 - act_l)),
            "budget_short": int(max(0, 4 - act_s)),
            "act_long_coins": sorted(list(act_l_set))[:64],
            "act_short_coins": sorted(list(act_s_set))[:64],
            "pend_long_coins": sorted(list(set(pend_l) - set(act_l_set)))[:64],
            "pend_short_coins": sorted(list(set(pend_s) - set(act_s_set)))[:64],
        }
    except Exception:
        return {"act_long": 0, "act_short": 0, "pend_long": 0, "pend_short": 0, "budget_long": 4, "budget_short": 4}

def _base_dir() -> str:
    try:
        return os.path.dirname(os.path.abspath(__file__))
    except Exception:
        try:
            return os.getcwd()
        except Exception:
            return "."

_DEFAULT_BASE_DIR = _base_dir()
_DEFAULT_OUT_DIR = os.path.join(_DEFAULT_BASE_DIR, "out")

from collections import OrderedDict as _OD
_TRADES_DEDUP_CACHE = _OD()
_TRADES_DEDUP_MAX = 5000
_TRADES_HARD_DEDUP_FILE_CACHE = _OD()
_TRADES_HARD_DEDUP_FILE_MAX = 20000
_REQ_EXEC_ONCE_CACHE = _OD()
_REQ_EXEC_ONCE_MAX = 20000
_REQ_EXEC_ONCE_ACTIVE_STATES = {"EXEC_START", "RUNNING", "SUBMITTED", "PENDING_CONFIRM", "CONFIRMED_SUCCESS", "COMMITTED", "TRADE_EFFECTIVE"}
_REQ_EXEC_ONCE_TERMINAL_STATES = {"CONFIRMED_SUCCESS", "COMMITTED", "TRADE_EFFECTIVE", "DONE", "SKIPPED_DUPLICATE_EXEC", "FAILED_NO_RETRY"}


def _od_put_capped(_mp: _OD, key: str, value: Any, max_n: int) -> None:
    try:
        _mp[str(key)] = value
        try:
            _mp.move_to_end(str(key))
        except Exception:
            pass
        while len(_mp) > int(max_n):
            _mp.popitem(last=False)
    except Exception:
        return None


def _req_exec_once_key(req_any: Any) -> str:
    try:
        if isinstance(req_any, dict):
            _rd = dict(req_any or {})
        elif hasattr(req_any, 'to_dict'):
            _rd = req_any.to_dict()
        elif hasattr(req_any, '__dict__'):
            _rd = dict(req_any.__dict__ or {})
        else:
            _rd = {}
    except Exception:
        _rd = {}
    try:
        _meta = _rd.get('meta') if isinstance(_rd.get('meta'), dict) else {}
    except Exception:
        _meta = {}
    try:
        _mod = str(_rd.get('module') or '').upper().strip()
        _act = str(_rd.get('action_type') or _rd.get('action') or '').lower().strip()
        _coin = str(_rd.get('coin') or '').upper().strip()
        _plat = str(_rd.get('platform') or '').upper().strip()
        _side = str(_rd.get('side') or '').upper().strip()
        _gid = str((_meta.get('grid_id') if isinstance(_meta, dict) else '') or _rd.get('grid_id') or '').strip()
        _lid = str((_meta.get('layer_id') if isinstance(_meta, dict) else '') or (_meta.get('tp_layer_id') if isinstance(_meta, dict) else '') or _rd.get('layer_id') or _rd.get('tp_layer_id') or '').strip()
        _req_id = str((_meta.get('req_id') if isinstance(_meta, dict) else '') or _rd.get('req_id') or '').strip()
        _trace_id = str((_meta.get('trace_id') if isinstance(_meta, dict) else '') or _rd.get('trace_id') or '').strip()
        if _req_id or _trace_id:
            return f"REQONCE|{_mod}|{_act}|{_coin}|{_plat}|{_side}|{_gid}|{_lid}|{_req_id}|{_trace_id}"
        _iid = str((_meta.get('layer_instance_id') if isinstance(_meta, dict) else '') or (_meta.get('instance_id') if isinstance(_meta, dict) else '') or '').strip()
        if _mod and _act and _coin and _plat and (_gid or _lid or _iid):
            return f"REQONCE|{_mod}|{_act}|{_coin}|{_plat}|{_side}|{_gid}|{_lid}|{_iid}"
    except Exception:
        return ''
    return ''


def _req_exec_once_guard_enabled(req_any: Any) -> bool:
    try:
        if isinstance(req_any, dict):
            _rd = dict(req_any or {})
        elif hasattr(req_any, 'to_dict'):
            _rd = req_any.to_dict()
        elif hasattr(req_any, '__dict__'):
            _rd = dict(req_any.__dict__ or {})
        else:
            _rd = {}
        _mod = str(_rd.get('module') or '').upper().strip()
        _act = str(_rd.get('action_type') or _rd.get('action') or '').lower().strip()
        return bool(_mod == 'M9' and _act in ('decrease', 'reduce', 'close', 'tp', 'trend_tp', 'partial_close', 'close_partial_notional'))
    except Exception:
        return False


def _req_exec_once_get(req_any: Any) -> dict:
    try:
        _k = _req_exec_once_key(req_any)
        if not _k:
            return {}
        _it = _REQ_EXEC_ONCE_CACHE.get(_k)
        return dict(_it or {}) if isinstance(_it, dict) else {}
    except Exception:
        return {}


def _req_exec_once_mark(req_any: Any, state: str, reason: str = '', **extra: Any) -> dict:
    try:
        if not _req_exec_once_guard_enabled(req_any):
            return {}
        _k = _req_exec_once_key(req_any)
        if not _k:
            return {}
        _it = dict(_REQ_EXEC_ONCE_CACHE.get(_k) or {})
        _it['key'] = _k
        _it['state'] = str(state or '').upper().strip()
        _it['reason'] = str(reason or '')[:200]
        _it['ts'] = float(time.time())
        if extra:
            try:
                _it.update(dict(extra or {}))
            except Exception:
                pass
        _od_put_capped(_REQ_EXEC_ONCE_CACHE, _k, _it, int(_REQ_EXEC_ONCE_MAX))
        return dict(_it)
    except Exception:
        return {}


def _req_exec_once_clear(req_any: Any, *, allow_states: tuple[str, ...] = ()) -> bool:
    try:
        _k = _req_exec_once_key(req_any)
        if not _k:
            return False
        _it = dict(_REQ_EXEC_ONCE_CACHE.get(_k) or {})
        _st = str(_it.get('state') or '').upper().strip()
        if allow_states and _st not in tuple(str(x or '').upper().strip() for x in allow_states):
            return False
        _REQ_EXEC_ONCE_CACHE.pop(_k, None)
        return True
    except Exception:
        return False


def _req_exec_once_should_skip(req_any: Any) -> tuple[bool, str, dict]:
    try:
        if not _req_exec_once_guard_enabled(req_any):
            return False, '', {}
        _it = _req_exec_once_get(req_any)
        if not _it:
            return False, '', {}
        _st = str(_it.get('state') or '').upper().strip()
        if _st in _REQ_EXEC_ONCE_ACTIVE_STATES or _st in _REQ_EXEC_ONCE_TERMINAL_STATES:
            return True, str(_it.get('reason') or _st.lower() or 'req_exec_once_guard'), _it
        return False, '', _it
    except Exception:
        return False, '', {}


def _trades_hard_dedup_key_from_line(line: dict | None) -> str:
    try:
        if not isinstance(line, dict):
            return ''
        _mod = str(line.get('module') or '').upper().strip()
        _act = str(line.get('action_type') or '').lower().strip()
        _coin = str(line.get('coin') or '').upper().strip()
        _plat = str(line.get('platform') or '').upper().strip()
        _side = str(line.get('side') or '').upper().strip()
        _req_id = str(line.get('req_id') or '').strip()
        _trace_id = str(line.get('trace_id') or '').strip()
        _lid = str(line.get('layer_id') or '').strip()
        if _mod == 'M9' and _act in ('decrease', 'reduce', 'close', 'tp', 'trend_tp', 'partial_close', 'close_partial_notional') and (_req_id or _trace_id):
            return f"TRD|{_mod}|{_act}|{_coin}|{_plat}|{_side}|{_lid}|{_req_id}|{_trace_id}"
        return ''
    except Exception:
        return ''


def _trades_hard_dedup_seen_or_add(line: dict | None) -> bool:
    try:
        _k = _trades_hard_dedup_key_from_line(line)
        if not _k:
            return False
        if _k in _TRADES_HARD_DEDUP_FILE_CACHE:
            try:
                _TRADES_HARD_DEDUP_FILE_CACHE.move_to_end(_k)
            except Exception:
                pass
            return True
        _fp = os.path.join(_get_out_dir(), 'trades.jsonl')
        try:
            if os.path.exists(_fp):
                with open(_fp, 'r', encoding='utf-8') as _f:
                    for _ln in _f:
                        _ln = str(_ln or '').strip()
                        if not _ln:
                            continue
                        try:
                            _row = json.loads(_ln)
                        except Exception:
                            continue
                        _row_k = _trades_hard_dedup_key_from_line(_row)
                        if _row_k:
                            _od_put_capped(_TRADES_HARD_DEDUP_FILE_CACHE, _row_k, 1, int(_TRADES_HARD_DEDUP_FILE_MAX))
                if _k in _TRADES_HARD_DEDUP_FILE_CACHE:
                    return True
        except Exception:
            pass
        _od_put_capped(_TRADES_HARD_DEDUP_FILE_CACHE, _k, 1, int(_TRADES_HARD_DEDUP_FILE_MAX))
        return False
    except Exception:
        return False


def _trades_dedup_seen(key: str) -> bool:
    try:
        k = str(key or '').strip()
        if not k:
            return False
        if k in _TRADES_DEDUP_CACHE:
            try:
                _TRADES_DEDUP_CACHE.move_to_end(k)
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_228', _e)
                pass
            return True
        _TRADES_DEDUP_CACHE[k] = 1
        try:
            if len(_TRADES_DEDUP_CACHE) > int(_TRADES_DEDUP_MAX):
                _TRADES_DEDUP_CACHE.popitem(last=False)
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_229', _e)
            pass
        return False
    except Exception:
        return False

