def safe_open(path: str, mode: str = "a", *, encoding: str = "utf-8", errors: str = "ignore", buffering: int = 1):
    """安全 open：自动创建父目录；失败会把 path 打到 _log_exc（若已存在）。"""
    p = str(path)
    try:
        _makedirs(os.path.dirname(p))
        return open(p, mode=mode, encoding=encoding, errors=errors, buffering=buffering)
    except Exception as _e:
        try:
            if "_log_exc" in globals():
                globals()["_log_exc"](mod="IO", stage="WRITE_FAIL", e=_e, path=p, mode=mode)  # type: ignore
            else:
                print(f"[PIN][IO][WRITE_FAIL] path={p} mode={mode} err={repr(_e)}")
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_232', _e)
            pass
        raise

