def safe_write_json(path: str, obj, *, encoding: str = "utf-8", indent: int = 2) -> bool:
    """JSON 安全原子写。
    优先复用后文统一的 _atomic_write_json / _safe_atomic_write_bytes；
    若这些符号尚未定义（例如启动早期），再退回本地唯一 tmp + replace。
    """
    p = str(path)
    try:
        import threading as _th
        import uuid as _uuid

        if "_IO_JSON_LOCKS" not in globals():
            globals()["_IO_JSON_LOCKS"] = {}
        if "_IO_JSON_LOCKS_GUARD" not in globals():
            globals()["_IO_JSON_LOCKS_GUARD"] = _th.Lock()

        def _get_lock(_p: str):
            try:
                g = globals()["_IO_JSON_LOCKS_GUARD"]
                d = globals()["_IO_JSON_LOCKS"]
                with g:
                    lk = d.get(_p)
                    if lk is None:
                        lk = _th.Lock()
                        d[_p] = lk
                    return lk
            except Exception:
                return None

        _makedirs(os.path.dirname(p))
        lk = _get_lock(p)
        if lk is not None:
            lk.acquire()
        try:
            aw = globals().get('_atomic_write_json')
            if callable(aw):
                aw(p, obj)
                return True

            payload = json.dumps(obj, ensure_ascii=False, indent=indent, default=globals().get('_json_default_for_bot')).encode(encoding)
            awb = globals().get('_safe_atomic_write_bytes')
            if callable(awb):
                return bool(awb(p, payload, mode_tag='json', retries=8, keep_pending=True))

            base = os.path.basename(p) or "state"
            ddir = os.path.dirname(os.path.abspath(p)) or "."
            _makedirs(ddir)
            tmp = os.path.join(ddir, f".{base}.tmp.{os.getpid()}.{_uuid.uuid4().hex}")
            with open(tmp, "wb") as f:
                f.write(payload)
                try:
                    f.flush()
                    os.fsync(f.fileno())
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_237', _e)
                    pass
            os.replace(tmp, p)
            return True
        finally:
            try:
                if lk is not None:
                    lk.release()
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_238', _e)
                pass
    except Exception as _e:
        try:
            if "_pin" in globals():
                try:
                    globals()["_pin"]("IO_JSON_WRITE_FAIL", mod="IO", ok=0, path=p, err=repr(_e))
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_239', _e)
                    pass
            if "_log_exc" in globals():
                globals()["_log_exc"](mod="IO", stage="WRITE_FAIL", e=_e, path=p, op="write_json")  # type: ignore
            else:
                print(f"[PIN][IO][WRITE_FAIL] path={p} op=write_json err={repr(_e)}")
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_240', _e)
            pass
        return False

def safe_read_json(path: str, default=None, *, encoding: str = "utf-8", retries: int = 5, jitter_ms: tuple = (50, 150), silent: bool = False):
    """JSON 读（带重试 + 取证）
    - JSONDecodeError/UnicodeError/半写入/空文件：短重试
    - 失败时插针：记录坏文件前 200 字节（text + hex）
    - silent=True：用于 control.json 这类高频轮询文件，允许把“半写入”当瞬时态静默吞掉，避免预期内噪音刷屏
    """
    p = str(path)

    def _bad_head200(_p: str) -> dict:
        out = {"path": _p}
        try:
            st = os.stat(_p)
            out["size"] = int(getattr(st, "st_size", 0) or 0)
            out["mtime"] = float(getattr(st, "st_mtime", 0.0) or 0.0)
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_241', _e)
            pass
        try:
            with open(_p, "rb") as fb:
                b = fb.read(200)
            out["head200_text"] = b.decode("utf-8", errors="replace")
            out["head200_hex"] = b.hex()
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_242', _e)
            pass
        return out

    try:
        if not p or (not os.path.exists(p)):
            return default
    except Exception:
        return default

    import random as _random
    _rt = max(1, int(retries or 1))
    for i in range(_rt):
        try:
            with open(p, "r", encoding=encoding) as f:
                _raw = f.read()
            if _raw is None:
                return default
            _raw_s = str(_raw).strip()
            if not _raw_s:
                return default
            return json.loads(_raw_s)
        except Exception as _e:
            if i >= _rt - 1:
                try:
                    bad = _bad_head200(p)
                    if not silent and "_pin" in globals():
                        try:
                            globals()["_pin"](
                                "IO_JSON_BAD_FILE", mod="IO", ok=0, err=repr(_e),
                                path=str(bad.get("path") or p),
                                size=int(bad.get("size") or 0),
                                mtime=float(bad.get("mtime") or 0.0),
                                head200=str(bad.get("head200_text") or "")[:200],
                                head200_hex=str(bad.get("head200_hex") or "")[:400],
                            )
                        except Exception as _e:
                            _record_swallowed_exception('except_pass_line_243', _e)
                            pass
                    if (not silent) and "_log_exc" in globals():
                        globals()["_log_exc"](mod="IO", stage="READ_FAIL", e=_e, path=p, op="read_json", bad_head200=bad)  # type: ignore
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_244', _e)
                    pass
                return default

            try:
                lo, hi = jitter_ms
                lo = float(lo) if lo is not None else 50.0
                hi = float(hi) if hi is not None else 150.0
                slp = _random.uniform(max(0.0, lo/1000.0), max(0.0, hi/1000.0))
                time.sleep(slp)
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_245', _e)
                pass
            continue

    return default

def _startup_io_selfcheck() -> None:
    """启动自检：确认 OUT_DIR/LOGS_DIR 可写 + 关键文件可创建。"""
    od = _get_out_dir()
    ld = _get_logs_dir()
    _makedirs(od)
    _makedirs(ld)

    def _probe_write(dirp: str) -> str:
        try:
            fp = os.path.join(dirp, "_io_selfcheck.tmp")
            _makedirs(os.path.dirname(fp))
            with open(fp, "w", encoding="utf-8") as f:
                f.write("ok")
            try:
                os.remove(fp)
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_246', _e)
                pass
            return "OK"
        except Exception as _e:
            return f"FAIL:{repr(_e)}"

    out_ok = _probe_write(od)
    log_ok = _probe_write(ld)

    key_files = [
        _out_path("bot_console.txt"),
        _out_path("grid_local_ledger.json"),
        _out_path("go_baocuo.txt"),
        _logs_path("bot_run.jsonl"),
        _logs_path("bot_error.txt"),
    ]
    for fp in key_files:
        try:
            _makedirs(os.path.dirname(fp))
            if os.path.basename(str(fp)) == 'grid_local_ledger.json':
                _need_init = (not os.path.exists(fp)) or (os.path.getsize(fp) <= 0)
                if not _need_init:
                    try:
                        _obj0 = safe_read_json(fp, default=None)
                        if not isinstance(_obj0, dict):
                            _need_init = True
                    except Exception:
                        _need_init = True
                if _need_init:
                    safe_write_json(fp, {"version": 1, "ts": time.time(), "items": []})
            else:
                with open(fp, "a", encoding="utf-8") as f:
                    pass
        except Exception as _e:
            try:
                if "_log_exc" in globals():
                    globals()["_log_exc"](mod="IO", stage="SELFCHK_FAIL", e=_e, path=str(fp))  # type: ignore
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_247', _e)
                pass
    try:
        msg = f"[PIN][IO][SELFCHK] OUT_DIR={od} ({out_ok}) | LOGS_DIR={ld} ({log_ok})"
        try:
            if "cprint" in globals():
                globals()["cprint"](msg)  # type: ignore
            else:
                print(msg)
        except Exception:
            print(msg)
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_248', _e)
        pass

_LEGACY_ONLY_STATE = {
    "enabled": False,
    "reason": "",
    "ts": 0.0,
}

_M10_REOPEN_PENDING: Dict[str, Dict[str, Any]] = {}
_M10_REOPEN_CLEAR_TOMBSTONE: Dict[str, Dict[str, Any]] = {}


def _m10_record_recovery_required(coin, platform, side, amount_u, pre, evidence, *, reason):
    """Persist an uncompleted restore on the REAL close record; do not invent an order."""
    from bot_core.submission_scope import key
    _m10_reopen_mark_pending(coin, platform=platform, side=side, amount_u=amount_u,
        reason=reason, state='recovery_required', pending_kind='recovery_required',
        blocking=True, owner='verified_close_recovery')
    with _SYNC_PW_WORKER_LOCK:
        record = _safety_submission_records().get(key(platform, coin, 'close_all', side))
        if not record:
            safe_log(lambda: f'[M10][RECOVERY_REQUIRED] coin={coin} platform={platform} reason=close_journal_missing_no_automatic_restore')
            return
        record['m10_recovery'] = {'state': 'recovery_required', 'platform': platform,
            'coin': coin, 'side': side, 'amount_u': float(amount_u or 0),
            'pre_position': copy.deepcopy(pre), 'close_evidence': copy.deepcopy(evidence),
            'ts': float(time.time()), 'reason': str(reason)}
        if not _safety_submission_save():
            raise RuntimeError('m10_recovery_record_not_durable')


def _m10_recovery_reconcile(coin, rec, snapshot):
    """Observe a failed restore; never guess a fill or call the removed repair engine."""
    from bot_core.submission_scope import key
    platform = str(rec.get('platform') or '').upper()
    record = _safety_submission_records().get(key(platform, coin, 'close_all', rec.get('side'))) or {}
    recovery = record.get('m10_recovery') or {}
    snap = snapshot if isinstance(snapshot, dict) else {}
    if not recovery or not _snapshot_positions_verified(snap) or float(snap.get('ts') or 0) <= float(recovery.get('ts') or 0):
        return False, 'recovery_wait_fresh_evidence', rec
    post = _get_snapshot_coin_leg(snap, coin, platform) or {}
    pre = recovery.get('pre_position') or {}
    restored = (post.get('side') == pre.get('side') and float(_position_quantity(pre) or 0) > 0
                and float(_position_quantity(post) or 0) >= float(_position_quantity(pre)))
    flat = all(_safety_normalize_position_read(_get_snapshot_coin_leg(snap, coin, plat) or {}).get('state') == 'CONFIRMED_EMPTY'
               for plat in ('EXT', 'VAR'))
    if not (restored or flat):
        return False, 'verified_close_restore_still_required', rec
    why = 'recovery_quantity_restored' if restored else 'recovery_pair_resolved_flat'
    with _SYNC_PW_WORKER_LOCK:
        record['m10_recovery'] = dict(recovery, resolved_ts=float(time.time()), state=why)
        if not _safety_submission_save():
            return False, 'recovery_journal_not_durable', rec
    _m10_reopen_clear(coin, reason=why, healed=restored)
    return True, why, rec


def _m10_step3_track_unconfirmed(platform, coin, side, amount_u, pre_position):
    """Attach M10's original quantity baseline to the existing submission journal."""
    _safety_reserve_submission(platform, coin, side, 'open', pre_position, amount_u,
                               reason='m10_step3_unconfirmed', allow_existing=True)
    key = str(platform).upper() + '|' + str(coin).upper()
    with _SYNC_PW_WORKER_LOCK:
        record = _safety_submission_records()[key]
        previous = record.get('m10_step3_confirmation') or {}
        if not previous or previous.get('resolved_ts'):
            record['m10_step3_confirmation'] = {
                'kind': 'open', 'side': str(side).upper(), 'intent_usd': float(amount_u),
                'pre_position': copy.deepcopy(pre_position), 'ts': float(time.time()),
                'tolerance_usd': 10.0,
            }
        if not _safety_submission_save():
            raise RuntimeError('m10_step3_confirmation_not_durable')
    return key


def _m10_step3_restore_unconfirmed(focus_coin=''):
    """Rebuild only M10's pending view after restart; never submit another order."""
    for record in list(_safety_submission_records().values()):
        if not isinstance(record, dict):
            continue
        pending = record.get('m10_step3_confirmation') or {}
        coin = str(record.get('coin') or '').upper()
        recovery = record.get('m10_recovery') or {}
        if (recovery and not recovery.get('resolved_ts') and coin not in _M10_REOPEN_PENDING
                and (not focus_coin or coin == str(focus_coin).upper())):
            _m10_reopen_mark_pending(coin, platform=record.get('platform', ''),
                side=recovery.get('side', ''), amount_u=recovery.get('amount_u', 0),
                reason=recovery.get('reason', 'verified_close_restore_required'),
                state='recovery_required', pending_kind='recovery_required', blocking=True,
                owner='verified_close_recovery')
        if not isinstance(pending, dict) or not pending or pending.get('resolved_ts') or (focus_coin and coin != str(focus_coin).upper()):
            continue
        if coin in _M10_REOPEN_PENDING:
            continue
        _m10_reopen_mark_pending(coin, platform=record.get('platform', ''), side=pending.get('side', ''),
            amount_u=pending.get('intent_usd', 0), reason='m10_step3_unconfirmed',
            state='step3_unconfirmed', pending_kind='step3_unconfirmed',
            blocking=True, ttl_sec=180.0, owner='step3_unconfirmed')


def _m10_step3_reconcile_unconfirmed(coin, rec, snapshot):
    """Only a fresh quantity delta may heal an unconfirmed M10 reopen."""
    platform = str(rec.get('platform') or '').upper()
    key = platform + '|' + str(coin).upper()
    record = _safety_submission_records().get(key) or {}
    pending = record.get('m10_step3_confirmation') or {}
    snap = snapshot if isinstance(snapshot, dict) else {}
    if not pending or snap.get('data_quality') != 'ok' or float(snap.get('ts') or 0) <= float(pending.get('ts') or 0):
        return False, 'step3_unconfirmed_wait_fresh_position', dict(rec)
    post = _get_snapshot_coin_leg(snap, coin, platform) or {}
    confirmed, evidence = _safety_verify_pending_settlement(pending, post)
    if not confirmed:
        return False, 'step3_unconfirmed:' + str(evidence.get('reason') or 'pending'), dict(rec)
    if not _safety_resolve_submission(platform, coin, post):
        return False, 'step3_unconfirmed_journal_not_resolved', dict(rec)
    with _SYNC_PW_WORKER_LOCK:
        record = _safety_submission_records().get(key) or {}
        record['m10_step3_confirmation'] = dict(pending, resolved_ts=float(time.time()), evidence=evidence)
        if not _safety_submission_save():
            return False, 'step3_unconfirmed_journal_not_durable', dict(rec)
    _m10_reopen_clear(coin, reason='m10_step3_quantity_delta_confirmed', healed=True)
    return True, 'step3_confirmed', dict(rec)


def _m10_step3_reconcile_scan(snapshot):
    """Reconcile after every accepted scan, including rounds with no trade requests."""
    _m10_step3_restore_unconfirmed()
    if _snapshot_positions_verified(snapshot):
        for record in list(_safety_submission_records().values()):
            if (record.get('module') == 'M10' and _safety_pending_blocks(record)
                    and str(record.get('kind') or '').startswith('close')
                    and float(snapshot.get('ts') or 0) > float(record.get('ts') or 0)):
                platform, coin = record.get('platform'), record.get('coin')
                post = _get_snapshot_coin_leg(snapshot, coin, platform) or {}
                if _safety_resolve_submission(platform, coin, post, kind='close'):
                    safe_log(lambda: f'[M10][CLOSE_CONFIRMED_SCAN] coin={coin} platform={platform} basis=quantity_delta resubmitted=0')
    for coin, rec in list(_M10_REOPEN_PENDING.items()):
        if rec.get('pending_kind') == 'recovery_required':
            _m10_recovery_reconcile(coin, rec, snapshot)
        elif rec.get('pending_kind') == 'step3_unconfirmed':
            _m10_step3_reconcile_unconfirmed(coin, rec, snapshot)


def _m10_reopen_pending_get(coin: str) -> Dict[str, Any]:
    try:
        return dict((_M10_REOPEN_PENDING or {}).get(str(coin or '').upper().strip()) or {})
    except Exception:
        return {}

def _m10_reopen_pending_is_expired(rec: Dict[str, Any] | None) -> bool:
    try:
        r = dict(rec or {})
        if not r:
            return False
        if r.get('pending_kind') in ('step3_unconfirmed', 'recovery_required'):
            return False  # 180s is a waiting deadline, never evidence of rejection.
        ttl = float(r.get('ttl_sec') or 0.0)
        ts0 = float(r.get('updated_ts') or r.get('ts') or 0.0)
        if ttl <= 0.0 or ts0 <= 0.0:
            return False
        return bool((time.time() - ts0) >= ttl)
    except Exception:
        return False

def _m10_reopen_pending_should_block(coin: str, *, platform: str = '', side: str = '', mod: str = '', action_type: str = '', snapshot: dict | None = None, req: dict | None = None) -> tuple[bool, str, Dict[str, Any]]:
    try:
        _m10_step3_restore_unconfirmed(coin)
        cu = str(coin or '').upper().strip()
        rec = dict((_M10_REOPEN_PENDING or {}).get(cu) or {})
    except Exception:
        cu, rec = '', {}
    if not cu or not rec:
        return False, 'no_pending', {}
    if rec.get('pending_kind') == 'recovery_required':
        done, why, _ = _m10_recovery_reconcile(cu, rec, snapshot)
        if done:
            return False, why, {}
        return (False, 'allow_safe_reduce', rec) if _req_is_safe_reduce({'module': mod, 'action_type': action_type}) else (True, why, rec)
    if rec.get('pending_kind') == 'step3_unconfirmed':
        done, why, _ = _m10_step3_reconcile_unconfirmed(cu, rec, snapshot)
        if done:
            return False, why, {}
        if _req_is_safe_reduce({'module': mod, 'action_type': action_type}):
            return False, 'allow_safe_reduce', rec
        return True, why, rec
    try:
        if _m10_reopen_pending_is_expired(rec):
            _m10_reopen_clear(cu, reason='pending_expired_auto_clear', healed=False)
            return False, 'expired_auto_clear', {}
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_249a', _e)
    try:
        _reason_l = str(rec.get('reason') or '').strip().lower()
        _src_mod_l = str(rec.get('source_mod') or '').strip().lower()
        _req_id_u = str(rec.get('req_id') or '').strip().upper()
        _trace_id_u = str(rec.get('trace_id') or '').strip().upper()
        _synthetic_rec = bool(
            _reason_l in ('synthetic_event', 'selfcheck_event', 'regression_event', 'placeholder_event')
            or _src_mod_l in ('selftest', 'regression')
            or _req_id_u.startswith(('REG-', 'SELFTEST-', 'TEG-', 'TRACE-SELFTEST-'))
            or _trace_id_u.startswith(('TEG-', 'SELFTEST-', 'TRACE-SELFTEST-', 'REG-'))
        )
        if _synthetic_rec:
            _m10_reopen_clear(cu, reason='synthetic_pending_auto_clear', healed=False)
            return False, 'synthetic_pending_auto_clear', {}
    except Exception as _e:
        _record_swallowed_exception('m10_reopen_pending_synthetic_check', _e)
    try:
        snap = dict(snapshot or {}) if isinstance(snapshot, dict) else {}
    except Exception:
        snap = {}
    try:
        if snap:
            _m10_reopen_reconcile_all_pending(snap, focus_coin=cu, reason='gate_precheck')
            rec = dict((_M10_REOPEN_PENDING or {}).get(cu) or {})
            if not rec:
                try:
                    safe_log(lambda: f"[{now_ts()}] [M10_REOPEN_GATE_RELEASE] coin={cu} reason=gate_pending_reconcile_released")
                except Exception:
                    pass
                return False, 'gate_pending_reconcile_released', {}
    except Exception as _e:
        _record_swallowed_exception('m10_reopen_pending_gate_reconcile', _e)
    state = str(rec.get('state') or 'pending').strip().lower()
    blocking = bool(rec.get('blocking', True))
    if state not in ('pending', 'retrying', 'retry_step2_then_step3', 'step3_reopen', 'missing_leg_b1'):
        return False, f'state_not_blocking:{state or "none"}', rec
    if not blocking:
        return False, 'non_blocking_pending', rec
    mmu = str(mod or '').upper().strip()
    act = str(action_type or '').lower().strip()
    plat_req = str(platform or '').upper().strip()
    side_req = str(side or '').upper().strip()
    plat_p = str(rec.get('platform') or '').upper().strip()
    side_p = str(rec.get('side') or '').upper().strip()
    if mmu.startswith('LEGACY_DELETED') or mmu.startswith('LEGACY_DELETED'):
        return False, 'allow_legacy_fix_family', rec
    if mmu == 'M10' or mmu.startswith('M10_') or act == 'koujing_a_3step':
        return False, 'allow_m10_self_reopen', rec
    if mmu == 'M9' and act in ('increase', 'open', 'add', 'add_leg', 'open_leg', 'open_more'):
        if plat_req and side_req and plat_req == plat_p and side_req == side_p:
            return False, 'allow_m9_same_leg_legacy_fix', rec
    if _req_is_safe_reduce({'module': mmu, 'action_type': act}):
        return False, 'allow_safe_reduce', rec
    try:
        _age = max(0.0, float(time.time()) - float(rec.get('updated_ts') or rec.get('ts') or 0.0))
    except Exception:
        _age = 0.0
    try:
        _fail_n = int(rec.get('fail_count') or 0)
    except Exception:
        _fail_n = 0
    if mmu == 'M9' and act in ('increase', 'open', 'add', 'add_leg', 'open_leg', 'open_more') and _age >= 120.0 and _fail_n >= 2:
        try:
            rec['blocking'] = 0
            rec['state'] = 'degraded'
            rec['updated_ts'] = float(time.time())
            rec['release_reason'] = 'gate_timeout_auto_degrade'
            rec['release_detail'] = f'age={_age:.1f};fail_count={_fail_n}'
            _M10_REOPEN_PENDING[cu] = rec
            safe_log(lambda: f"[{now_ts()}] [M10_REOPEN_GATE_RELEASE] coin={cu} reason=gate_timeout_auto_degrade age={_age:.1f}s fail_count={_fail_n}")
        except Exception:
            pass
        return False, 'gate_timeout_auto_degrade', rec
    return True, 'blocking_pending', rec

def _m10_reopen_reconcile_all_pending(snapshot: dict | None = None, *, focus_coin: str = '', reason: str = 'gate_precheck') -> dict:
    _m10_step3_restore_unconfirmed(focus_coin)
    try:
        snap = dict(snapshot or {}) if isinstance(snapshot, dict) else {}
    except Exception:
        snap = {}
    try:
        pend = dict(_M10_REOPEN_PENDING or {})
    except Exception:
        pend = {}
    out = {'checked': 0, 'released': 0, 'degraded': 0, 'forced': 0, 'focus_coin': str(focus_coin or '').upper().strip(), 'reason': str(reason or '')}
    for _coin, _rec in list((pend or {}).items()):
        try:
            cu = str(_coin or '').upper().strip()
            if not cu:
                continue
            if out['focus_coin'] and cu != out['focus_coin']:
                continue
            out['checked'] += 1
            _before = dict((_M10_REOPEN_PENDING or {}).get(cu) or {})
            if not _before:
                continue
            _handled, _rsn, _rec_after = _m10_recover_reconcile_no_request(cu, snapshot=snap, reason=f'{reason}_pending_reconcile', detail='gate_precheck_snapshot')
            _after_live = dict((_M10_REOPEN_PENDING or {}).get(cu) or {})
            if not _after_live:
                out['released'] += 1
                try:
                    safe_log(lambda: f"[{now_ts()}] [M10_REOPEN_SWEEP] coin={cu} action=release reason={str(_rsn or '-')}")
                except Exception:
                    pass
                continue
            _state = str((_after_live or {}).get('state') or '').strip().lower()
            if _state == 'degraded' or not bool((_after_live or {}).get('blocking', 1)):
                out['degraded'] += 1
            if str(_rsn or '').startswith('force_submit_') or str((_after_live or {}).get('last_force_submit_reason') or ''):
                out['forced'] += 1
        except Exception as _e:
            _record_swallowed_exception('m10_reopen_reconcile_all_pending.loop', _e)
            continue
    try:
        if int(out.get('checked') or 0) > 0:
            safe_log(lambda: f"[{now_ts()}] [M10_REOPEN_SWEEP] checked={int(out.get('checked') or 0)} released={int(out.get('released') or 0)} degraded={int(out.get('degraded') or 0)} forced={int(out.get('forced') or 0)} focus={str(out.get('focus_coin') or '-')}")
    except Exception:
        pass
    return out

def _m10_reopen_pending_is_on(coin: str) -> bool:
    try:
        block, _, _ = _m10_reopen_pending_should_block(str(coin or '').upper().strip())
        return bool(block)
    except Exception:
        return False

def _m10_reopen_mark_pending(coin: str, *, platform: str = '', side: str = '', amount_u: float = 0.0,
                             reason: str = '', source_mod: str = 'M10', req_id: str = '', trace_id: str = '',
                             pending_kind: str = '', blocking: bool = True, ttl_sec: float = 180.0,
                             state: str = 'pending', last_fail_reason: str = '', owner: str = '') -> None:
    try:
        cu = str(coin or '').upper().strip()
        if not cu:
            return
        try:
            _reason_l = str(reason or '').strip().lower()
            _src_mod_l = str(source_mod or '').strip().lower()
            _req_id_u = str(req_id or '').strip().upper()
            _trace_id_u = str(trace_id or '').strip().upper()
            _synthetic_call = bool(
                _selftest_context_active()
                or _reason_l in ('synthetic_event', 'selfcheck_event', 'regression_event', 'placeholder_event')
                or _src_mod_l in ('selftest', 'regression')
                or _req_id_u.startswith(('REG-', 'SELFTEST-', 'TEG-', 'TRACE-SELFTEST-'))
                or _trace_id_u.startswith(('TEG-', 'SELFTEST-', 'TRACE-SELFTEST-', 'REG-'))
            )
        except Exception:
            _synthetic_call = False
        if _synthetic_call:
            try:
                if cu in _M10_REOPEN_PENDING:
                    _M10_REOPEN_PENDING.pop(cu, None)
            except Exception:
                pass
            try:
                safe_log(lambda: f"[{now_ts()}] [M10_REOPEN_SKIP_SYNTHETIC] coin={cu} plat={str(platform or '-')} side={str(side or '-')} amount_u={float(amount_u or 0.0):.2f} reason={str(reason or '-')} req_id={str(req_id or '-')} trace_id={str(trace_id or '-')}")
            except Exception as _e:
                _record_swallowed_exception('m10_reopen_skip_synthetic_log', _e)
            return
        prev = dict((_M10_REOPEN_PENDING or {}).get(cu) or {})
        _tsm = dict((_M10_REOPEN_CLEAR_TOMBSTONE or {}).get(cu) or {})
        try:
            _recent_clear = bool(_tsm and (time.time() - float(_tsm.get('ts') or 0.0) <= max(60.0, float(ttl_sec or 0.0))))
        except Exception:
            _recent_clear = False
        try:
            _same_leg = (str(platform or prev.get('platform') or '').upper().strip() == str(_tsm.get('platform') or '').upper().strip() and str(side or prev.get('side') or '').upper().strip() == str(_tsm.get('side') or '').upper().strip())
            _amt_new = float(amount_u or prev.get('amount_u') or 0.0)
            _amt_old = float(_tsm.get('amount_u') or 0.0)
            _same_amount = bool(abs(_amt_new - _amt_old) <= max(20.0, _amt_old * 0.10))
            _same_req = bool((str(req_id or '').strip() and str(req_id or '').strip() == str(_tsm.get('req_id') or '').strip()) or (str(trace_id or '').strip() and str(trace_id or '').strip() == str(_tsm.get('trace_id') or '').strip()))
        except Exception:
            _same_leg, _same_amount, _same_req = False, False, False
        if pending_kind not in ('step3_unconfirmed', 'recovery_required') and _recent_clear and _same_leg and (_same_req or _same_amount):
            try:
                safe_log(lambda: f"[{now_ts()}] [M10_REOPEN_SKIP_RECLEAR] coin={cu} plat={str(platform or prev.get('platform') or '-').upper()} side={str(side or prev.get('side') or '-').upper()} amount_u={float(amount_u or prev.get('amount_u') or 0.0):.2f} reason={str(reason or '-')} clear_reason={str(_tsm.get('reason') or '-')} req_id={str(req_id or '-') or '-'} trace_id={str(trace_id or '-') or '-'}")
            except Exception as _e:
                _record_swallowed_exception('m10_reopen_skip_reclear.log', _e)
            return
        fail_count = int(prev.get('fail_count') or 0) + (0 if pending_kind == 'step3_unconfirmed' else 1)
        _kind = str(pending_kind or prev.get('pending_kind') or 'step3_reopen').strip().lower() or 'step3_reopen'
        _owner = str(owner or prev.get('owner') or _kind or state or 'step3_reopen').strip().lower() or 'step3_reopen'
        _blocking = bool(blocking)
        _state = str(state or _kind or 'pending').strip().lower() or 'pending'
        nowv = float(time.time())
        rec = {
            'coin': cu,
            'platform': str(platform or prev.get('platform') or '').upper().strip(),
            'side': str(side or prev.get('side') or '').upper().strip(),
            'amount_u': float(amount_u or prev.get('amount_u') or 0.0),
            'reason': str(reason or prev.get('reason') or ''),
            'last_fail_reason': '' if pending_kind == 'step3_unconfirmed' else str(last_fail_reason or reason or prev.get('last_fail_reason') or ''),
            'source_mod': str(source_mod or prev.get('source_mod') or 'M10').upper().strip() or 'M10',
            'req_id': str(req_id or prev.get('req_id') or ''),
            'trace_id': str(trace_id or prev.get('trace_id') or ''),
            'fail_count': int(fail_count),
            'ts': float(prev.get('ts') or nowv),
            'updated_ts': nowv,
            'state': _state,
            'pending_kind': _kind,
            'owner': _owner,
            'blocking': int(1 if _blocking else 0),
            'ttl_sec': float(ttl_sec or prev.get('ttl_sec') or 180.0),
            'next_retry_ts': float(nowv),
        }
        _M10_REOPEN_PENDING[cu] = rec
        try:
            safe_log(lambda: f"[{now_ts()}] [M10_REOPEN_PENDING] coin={cu} plat={rec['platform'] or '-'} side={rec['side'] or '-'} amount_u={float(rec['amount_u'] or 0.0):.2f} fail_count={int(fail_count)} state={str(rec.get('state') or '-')} kind={str(rec.get('pending_kind') or '-')} blocking={int(rec.get('blocking') or 0)} ttl={float(rec.get('ttl_sec') or 0.0):.0f}s reason={str(reason or '-')}" )
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_249', _e)
            pass
        try:
            _pin('M10_REOPEN', coin=cu, ok=0, stage='PENDING_SET', reason=str(reason or 'm10_step3_fail'), plat=str(rec['platform'] or ''), side=str(rec['side'] or ''), amount_u=float(rec['amount_u'] or 0.0), fail_count=int(fail_count), src_mod=str(rec['source_mod'] or 'M10'), req_id=str(req_id or ''), trace_id=str(trace_id or ''), pending_kind=str(rec.get('pending_kind') or ''), owner=str(rec.get('owner') or ''), blocking=int(rec.get('blocking') or 0), ttl_sec=float(rec.get('ttl_sec') or 0.0), state=str(rec.get('state') or ''))
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_250', _e)
            pass
    except Exception as _e:
        _log_exc(mod='SYS', stage='EXC_PASS', e=_e)

def _m10_reopen_force_submit_from_pending(snapshot: dict | None, coin: str, rec: Dict[str, Any] | None, *, reason: str = 'm10_pending_force_reopen') -> tuple[bool, str, Dict[str, Any]]:
    """M10 断链自动纠错：当 step1 已真实平掉、step3 未补回时，直接按 pending 记录回补目标腿。
    人话：不要再等普通策略自己想起来，下一轮发现目标腿缺失/严重偏小就立刻补回。
    """
    try:
        cu = str(coin or '').upper().strip()
        rec0 = dict(rec or {}) if isinstance(rec, dict) else {}
        if not cu or not rec0:
            return False, 'pending_missing', {}
        plat = str(rec0.get('platform') or '').upper().strip()
        side = str(rec0.get('side') or '').upper().strip()
        amt = float(rec0.get('amount_u') or 0.0)
        if plat not in ('EXT', 'VAR') or side not in ('LONG', 'SHORT') or amt <= 0.0:
            return False, 'pending_target_invalid', {}
        snap = dict(snapshot or {}) if isinstance(snapshot, dict) else {}
        try:
            st = _calc_coin_structure_state(snap or {}, cu) or {}
        except Exception:
            st = {}
        try:
            eps = float(globals().get('B1_NO_LEG_EPS_U', 0.0) or 0.0)
        except Exception:
            eps = 0.0
        eps = max(0.0, float(eps))

        def _leg_view(p: str) -> dict:
            p = str(p or '').upper().strip()
            d = ((st or {}).get('ext') if p == 'EXT' else (st or {}).get('var')) or {}
            try:
                notional = abs(float((d or {}).get('notional_u') or (d or {}).get('value_usd') or 0.0))
            except Exception:
                notional = 0.0
            try:
                side0 = str((d or {}).get('side') or '').upper().strip()
            except Exception:
                side0 = ''
            has0 = bool(notional > eps and side0 in ('LONG', 'SHORT'))
            return {'notional_u': float(notional), 'side': side0, 'has_position': bool(has0)}

        tgt = _leg_view(plat)
        oth = _leg_view('VAR' if plat == 'EXT' else 'EXT')
        tgt_u = float(tgt.get('notional_u') or 0.0)
        oth_u = float(oth.get('notional_u') or 0.0)
        tgt_side = str(tgt.get('side') or '').upper().strip()
        if tgt_u >= max(eps, float(amt) * 0.60) and tgt_side == side:
            return False, 'target_leg_already_restored', {'target_leg_u': float(tgt_u), 'other_leg_u': float(oth_u)}
        imbalance_abs = abs(oth_u - tgt_u)
        should_force = bool((oth_u > eps and tgt_u <= eps) or (oth_u > eps and imbalance_abs >= max(100.0, float(amt) * 0.35)))
        if not should_force:
            return False, 'force_reopen_not_due', {'target_leg_u': float(tgt_u), 'other_leg_u': float(oth_u), 'imbalance_abs': float(imbalance_abs)}
        submit_u = float(max(20.0, _round_usd10(amt)))
        try:
            _prio_m10 = int(PRIORITY.get('M10_REOPEN') or PRIORITY.get('M10') or PRIORITY.get('LEGACY_DELETED') or 9)
        except Exception:
            _prio_m10 = 9
        _prio_m10 = max(9, int(_prio_m10))
        req = {
            'module': 'M10',
            'coin': cu,
            'platform': plat,
            'action_type': 'reopen_after_tp',
            'side': side,
            'amount_usd': float(submit_u),
            'priority': int(_prio_m10),
            'meta': {
                'legacy_fix_mode': True,
                'auto_legacy_fix': True,
                'm10_reopen_reopen': True,
                'm10_pending_force_submit': True,
                'm10_reopen_fast_lane': True,
                'reopen_action': 'reopen_after_tp',
                'legacy_fix_priority': 'HIGH',
                'pending_kind': str(rec0.get('pending_kind') or ''),
                'pending_state': str(rec0.get('state') or ''),
                'pending_reason': str(rec0.get('reason') or ''),
                'source_mod': 'M10_REOPEN',
                'fail_reason': str(reason or rec0.get('last_fail_reason') or rec0.get('reason') or 'm10_pending_force_reopen'),
                'planned_notional': float(submit_u),
                'target_leg_u_before': float(tgt_u),
                'other_leg_u_before': float(oth_u),
                'imbalance_abs': float(imbalance_abs),
                'req_id': str(rec0.get('req_id') or ''),
                'trace_id': str(rec0.get('trace_id') or ''),
            }
        }
        rid = _legacy_deleted_submit(req, mod='M10', gate_on_fail='M10_REOPEN_GUARD', note='m10_reopen_force_submit_from_pending')
        if not str(rid or '').strip():
            return False, 'legacy_fix_submit_empty', {'request': req, 'target_leg_u': float(tgt_u), 'other_leg_u': float(oth_u), 'imbalance_abs': float(imbalance_abs)}
        try:
            rec1 = dict((_M10_REOPEN_PENDING or {}).get(cu) or rec0)
            rec1['updated_ts'] = float(time.time())
            rec1['next_retry_ts'] = float(time.time())
            rec1['last_submit_rid'] = str(rid or '')
            rec1['last_submit_reason'] = str(reason or '')
            rec1['last_submit_amount_u'] = float(submit_u)
            rec1['last_submit_target_leg_u'] = float(tgt_u)
            rec1['last_submit_other_leg_u'] = float(oth_u)
            rec1['last_submit_imbalance_abs'] = float(imbalance_abs)
            rec1['blocking'] = 1
            rec1['state'] = str(rec1.get('state') or 'pending')
            _M10_REOPEN_PENDING[cu] = rec1
        except Exception as _e:
            _record_swallowed_exception('m10_reopen_force_submit.pending_write', _e)
        try:
            safe_log(lambda: f"[{now_ts()}] [M10_REOPEN_FORCE_SUBMIT] coin={cu} plat={plat} side={side} submit_u={float(submit_u):.2f} target_leg_u={float(tgt_u):.2f} other_leg_u={float(oth_u):.2f} imbalance_abs={float(imbalance_abs):.2f} rid={str(rid or '-')} reason={str(reason or '-')} kind={str(rec0.get('pending_kind') or '-')} state={str(rec0.get('state') or '-')}" )
        except Exception as _e:
            _record_swallowed_exception('m10_reopen_force_submit.log', _e)
        try:
            _pin('M10_REOPEN', coin=cu, ok=1, stage='FORCE_SUBMIT', reason=str(reason or 'm10_pending_force_reopen'), plat=str(plat), side=str(side), amount_u=float(submit_u), target_leg_u=float(tgt_u), other_leg_u=float(oth_u), imbalance_abs=float(imbalance_abs), pending_kind=str(rec0.get('pending_kind') or ''), pending_state=str(rec0.get('state') or ''), rid=str(rid or ''))
        except Exception as _e:
            _record_swallowed_exception('m10_reopen_force_submit.pin', _e)
        return True, 'legacy_fix_submitted', {'rid': str(rid or ''), 'request': req, 'target_leg_u': float(tgt_u), 'other_leg_u': float(oth_u), 'imbalance_abs': float(imbalance_abs)}
    except Exception as _e:
        _log_exc(mod='SYS', stage='EXC_PASS', e=_e)
        return False, 'legacy_fix_submit_exception', {'err': repr(_e)}

def _m10_reopen_clear(coin: str, *, reason: str = '', healed: bool = True) -> None:
    try:
        cu = str(coin or '').upper().strip()
        if not cu:
            return
        prev = dict((_M10_REOPEN_PENDING or {}).get(cu) or {})
        if cu in _M10_REOPEN_PENDING:
            _M10_REOPEN_PENDING.pop(cu, None)
        try:
            _M10_REOPEN_CLEAR_TOMBSTONE[cu] = {
                'ts': float(time.time()),
                'reason': str(reason or ''),
                'healed': int(1 if healed else 0),
                'platform': str(prev.get('platform') or '').upper().strip(),
                'side': str(prev.get('side') or '').upper().strip(),
                'amount_u': float(prev.get('amount_u') or 0.0),
                'req_id': str(prev.get('req_id') or ''),
                'trace_id': str(prev.get('trace_id') or ''),
                'pending_kind': str(prev.get('pending_kind') or ''),
                'state': str(prev.get('state') or ''),
            }
        except Exception as _e:
            _record_swallowed_exception('m10_reopen_clear.tombstone_write', _e)
        try:
            safe_log(lambda: f"[{now_ts()}] [M10_REOPEN_CLEAR] coin={cu} healed={int(1 if healed else 0)} reason={str(reason or '-')} prev_reason={str(prev.get('reason') or '-')} prev_state={str(prev.get('state') or '-')} prev_kind={str(prev.get('pending_kind') or '-')} prev_blocking={int(prev.get('blocking') or 0)}" )
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_251', _e)
            pass
        try:
            _pin('M10_REOPEN', coin=cu, ok=int(1 if healed else 0), stage='PENDING_CLEAR', reason=str(reason or 'legacy_fix_cleared'), prev_reason=str(prev.get('reason') or ''), fail_count=int(prev.get('fail_count') or 0), pending_kind=str(prev.get('pending_kind') or ''), blocking=int(prev.get('blocking') or 0), state=str(prev.get('state') or ''))
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_252', _e)
            pass
    except Exception as _e:
        _log_exc(mod='SYS', stage='EXC_PASS', e=_e)

def _m10_recover_reconcile_no_request(coin: str, *, snapshot: dict | None = None, reason: str = 'm10_no_request', detail: str = '') -> tuple[bool, str, Dict[str, Any]]:
    try:
        _m10_step3_restore_unconfirmed(coin)
        cu = str(coin or '').upper().strip()
        rec = dict((_M10_REOPEN_PENDING or {}).get(cu) or {})
        if not cu or not rec:
            return False, 'no_pending', {}
        if rec.get('pending_kind') == 'recovery_required':
            return _m10_recovery_reconcile(cu, rec, snapshot)
        if rec.get('pending_kind') == 'step3_unconfirmed':
            return _m10_step3_reconcile_unconfirmed(cu, rec, snapshot)
        if _m10_reopen_pending_is_expired(rec):
            _m10_reopen_clear(cu, reason='pending_expired_before_no_request_reconcile', healed=False)
            return True, 'expired_auto_clear', {}
        if not bool(rec.get('blocking', True)):
            return False, 'already_non_blocking', rec
        nowv = float(time.time())
        prev_state = str(rec.get('state') or 'pending').strip().lower() or 'pending'
        try:
            _pin('M10_REOPEN', coin=cu, ok=1, stage='PENDING_RECONCILE_BEGIN', reason=str(reason or 'm10_no_request'), pending_kind=str(rec.get('pending_kind') or ''), blocking=int(rec.get('blocking') or 0), plat=str(rec.get('platform') or ''), side=str(rec.get('side') or ''), amount_u=float(rec.get('amount_u') or 0.0))
        except Exception as _e:
            _record_swallowed_exception('m10_reopen_reconcile.begin_pin', _e)
        prev_kind = str(rec.get('pending_kind') or '').strip().lower()
        prev_owner = str(rec.get('owner') or prev_kind or '').strip().lower()
        snap = dict(snapshot or {}) if isinstance(snapshot, dict) else {}
        try:
            _st = _calc_coin_structure_state(snap or {}, cu)
        except Exception:
            _st = {}
        _ext_u = abs(float((((_st or {}).get('ext') or {}).get('notional_u') or 0.0)))
        _var_u = abs(float((((_st or {}).get('var') or {}).get('notional_u') or 0.0)))
        try:
            _eps = float(globals().get('B1_NO_LEG_EPS_U', 0.0) or 0.0)
        except Exception:
            _eps = 0.0
        _plat_target = str(rec.get('platform') or '').upper().strip()
        _target_u = float(_ext_u if _plat_target == 'EXT' else (_var_u if _plat_target == 'VAR' else 0.0))
        _other_u = float(_var_u if _plat_target == 'EXT' else (_ext_u if _plat_target == 'VAR' else 0.0))
        _snap_no_leg = bool(_ext_u <= _eps and _var_u <= _eps)
        _target_missing = bool(_plat_target in ('EXT', 'VAR') and _target_u <= _eps)
        _severe_imbalance = bool(_plat_target in ('EXT', 'VAR') and _other_u > _eps and abs(_other_u - _target_u) >= max(100.0, float(rec.get('amount_u') or 0.0) * 0.35))
        _target_side_now = str((((_st or {}).get('ext') or {}).get('side') if _plat_target == 'EXT' else (((_st or {}).get('var') or {}).get('side') if _plat_target == 'VAR' else '')) or '').upper().strip()
        _target_restored = bool(_plat_target in ('EXT', 'VAR') and _target_u > max(_eps, float(rec.get('amount_u') or 0.0) * 0.35) and _target_side_now == str(rec.get('side') or '').upper().strip())
        if _target_restored and (not _severe_imbalance):
            _m10_reopen_clear(cu, reason='m10_pending_target_leg_restored', healed=True)
            return True, 'target_leg_restored_auto_clear', dict(rec)
        if _snap_no_leg:
            try:
                _grid_force_clear_leg_history(cu, str(rec.get('platform') or '').upper().strip(), str(rec.get('side') or '').upper().strip(), reason='m10_step1_confirmed_full_close_next_scan', src_mod='M10', src_act='koujing_a_3step', apply_round_block=True)
            except Exception:
                pass
            try:
                if float(rec.get('amount_u') or 0.0) > 0.0:
                    safe_log(lambda: f"[M10][RECOVERY_REQUIRED] coin={cu} platform={str(rec.get('platform') or '').upper().strip()} side={str(rec.get('side') or '').upper().strip()} amount_u={float(rec.get('amount_u') or 0.0):.2f} reason=m10_reopen_missing_after_confirmed_full_close no_automatic_submit=1")
                    rec['state'] = 'missing_leg_b1'
                    rec['pending_kind'] = 'missing_leg_b1'
                    rec['blocking'] = 1
                    rec['updated_ts'] = nowv
                    rec['next_retry_ts'] = nowv
                    rec['release_reason'] = 'm10_step1_confirmed_full_close_next_scan'
                    rec['release_detail'] = str(detail or 'next_scan_no_leg_confirmed')
                    rec['last_fail_reason'] = 'm10_reopen_missing_after_confirmed_full_close'
                    _M10_REOPEN_PENDING[cu] = rec
                    return True, 'confirmed_full_close_reopen_enqueued', rec
            except Exception:
                pass
            _m10_reopen_clear(cu, reason='m10_step1_confirmed_full_close_next_scan', healed=True)
            return True, 'confirmed_full_close_next_scan', rec
        if _target_missing or _severe_imbalance:
            try:
                if prev_owner in ('step3_fail', 'step2_fail', 'retry_step2_then_step3', 'step3_reopen'):
                    rec['owner'] = prev_owner
                elif _target_missing:
                    rec['owner'] = 'no_request_reconcile_missing_leg'
                else:
                    rec['owner'] = str(rec.get('owner') or 'no_request_reconcile_severe_imbalance')
                rec['state'] = ('missing_leg_b1' if _target_missing else str(rec.get('state') or 'pending'))
                rec['pending_kind'] = ('missing_leg_b1' if _target_missing else str(rec.get('pending_kind') or 'step3_reopen'))
                rec['blocking'] = 1
                rec['updated_ts'] = nowv
                rec['next_retry_ts'] = nowv
                rec['release_reason'] = str(reason or 'm10_pending_reconcile_force_submit')
                rec['release_detail'] = str(detail or '')
                _M10_REOPEN_PENDING[cu] = rec
            except Exception:
                pass
            _submitted, _submit_reason, _submit_detail = _m10_reopen_force_submit_from_pending(
                snap or {}, cu, rec,
                reason=('m10_pending_missing_leg_force_reopen' if _target_missing else 'm10_pending_severe_imbalance_force_reopen')
            )
            if _submitted:
                rec = dict((_M10_REOPEN_PENDING or {}).get(cu) or rec)
                rec['last_force_submit_reason'] = str(_submit_reason or '')
                rec['last_force_submit_detail'] = dict(_submit_detail or {}) if isinstance(_submit_detail, dict) else {'detail': _submit_detail}
                _M10_REOPEN_PENDING[cu] = rec
                return True, ('force_submit_missing_leg' if _target_missing else 'force_submit_severe_imbalance'), rec
        rec['blocking'] = 0
        rec['state'] = 'degraded'
        rec['updated_ts'] = nowv
        rec['next_retry_ts'] = nowv
        rec['release_reason'] = str(reason or 'm10_no_request')
        rec['release_detail'] = str(detail or '')
        rec['last_fail_reason'] = str(detail or reason or rec.get('last_fail_reason') or rec.get('reason') or '')
        _M10_REOPEN_PENDING[cu] = rec
        try:
            safe_log(lambda: f"[{now_ts()}] [M10_REOPEN_DEGRADE] coin={cu} reason={str(reason or '-')} detail={str(detail or '-')} prev_state={prev_state or '-'} prev_kind={prev_kind or '-'} blocking=0 target_u={float(_target_u):.2f} other_u={float(_other_u):.2f}")
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_252a', _e)
            pass
        try:
            _pin('M10_REOPEN', coin=cu, ok=1, stage='PENDING_DEGRADE_NO_REQUEST', reason=str(reason or 'm10_no_request'), detail=str(detail or ''), prev_state=str(prev_state or ''), pending_kind=str(prev_kind or ''), blocking=0, fail_count=int(rec.get('fail_count') or 0), plat=str(rec.get('platform') or ''), side=str(rec.get('side') or ''), amount_u=float(rec.get('amount_u') or 0.0), target_leg_u=float(_target_u), other_leg_u=float(_other_u))
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_252b', _e)
            pass
        return True, 'degraded_no_request', rec
    except Exception as _e:
        _log_exc(mod='SYS', stage='EXC_PASS', e=_e)
        return False, 'reconcile_exception', {}

def _m10_reopen_post_state_healed(post: Dict[str, Any] | None, *, min_leg_u: float = 10.0) -> bool:
    try:
        st = dict(post or {})
        ext_has = bool(st.get('ext_has'))
        var_has = bool(st.get('var_has'))
        ext_side = str(st.get('ext_side') or '').upper().strip()
        var_side = str(st.get('var_side') or '').upper().strip()
        ext_u = abs(float(st.get('ext_notional_u', 0.0) or 0.0))
        var_u = abs(float(st.get('var_notional_u', 0.0) or 0.0))
        _thr = max(float(min_leg_u or 0.0), 10.0)
        return bool(ext_has and var_has and ext_side and var_side and (ext_side != var_side) and ext_u >= _thr and var_u >= _thr)
    except Exception:
        return False

def _grid_force_clear_leg_history(coin: str, platform: str = '', side: str = '', *, reason: str = 'scan_leg_missing_reset', src_mod: str = 'SYS', src_act: str = 'scan_reconcile', apply_round_block: bool = False) -> dict:
    c = str(coin or '').upper().strip()
    p = str(platform or '').upper().strip()
    sd = str(side or '').upper().strip()
    rep = {'coin': c, 'platform': p, 'side': sd, 'reason': str(reason or ''), 'grid_changed': 0, 'a1_changed': False, 'bucket_reset_called': False, 'round_block_applied': False}
    if not c:
        rep['skip'] = 'coin_missing'
        return rep
    try:
        if 'GRID_BOOK' in globals() and GRID_BOOK:
            _gb = GRID_BOOK.force_flat_scope(c, p or None, reason=f'{src_mod}_FORCE_RESET:{reason}')
            rep['grid_changed'] = int((_gb or {}).get('changed') or 0)
    except Exception as _e:
        _log_exc(mod='SYS', stage='EXC_PASS', e=_e)
    try:
        _plats = [p] if p else ['EXT', 'VAR']
        _sides = [sd] if sd else ['LONG', 'SHORT']
        for _pp in _plats:
            for _ss in _sides:
                try:
                    _grid_leg_reset_marker_set(c, _pp, _ss, reason=str(reason or ''), src_mod=str(src_mod or ''), src_act=str(src_act or ''))
                except Exception:
                    pass
                try:
                    _purge_rep = _purge_m9_leg_records_after_full_close(c, _pp, _ss, reason=str(reason or ''))
                    rep['grid_changed'] = int(rep.get('grid_changed') or 0) + int((_purge_rep or {}).get('grid_book_removed') or 0) + int((_purge_rep or {}).get('legacy_items_removed') or 0)
                except Exception:
                    pass
    except Exception as _e:
        _log_exc(mod='SYS', stage='EXC_PASS', e=_e)
    try:
        _grid_ledger_restore_once()
        _pending_changed = 0
        for _lid, _row in list((_GRID_OPEN_PENDING_LEDGER or {}).items()):
            try:
                _rc = str((_row or {}).get('coin') or '').upper().strip()
                _rp = str((_row or {}).get('platform') or '').upper().strip()
                _rs = str((_row or {}).get('side') or '').upper().strip()
                if c and _rc != c:
                    continue
                if p and _rp != p:
                    continue
                if sd and _rs != sd:
                    continue
                _GRID_OPEN_PENDING_LEDGER.pop(_lid, None)
                _pending_changed += 1
            except Exception:
                continue
        if _pending_changed:
            _grid_ledger_persist()
            rep['grid_changed'] = int(rep.get('grid_changed') or 0) + int(_pending_changed)
    except Exception as _e:
        _log_exc(mod='SYS', stage='EXC_PASS', e=_e)
    try:
        _m9_reset_bucket_on_coin_flat(c, reason=f'{src_mod}_FORCE_RESET:{reason}')
        rep['bucket_reset_called'] = True
    except Exception:
        pass
    if apply_round_block:
        try:
            _m10_set_block(c, p, sd, reason=reason, src_mod=src_mod, src_act=src_act)
            rep['round_block_applied'] = True
        except Exception:
            pass
    try:
        safe_log(lambda: f"[{now_ts()}] [GRID_FORCE_CLEAR_LEG] coin={c} plat={p or '-'} side={sd or '-'} reason={str(reason or '-')} changed={int(rep.get('grid_changed') or 0)} src_mod={src_mod} src_act={src_act}")
    except Exception:
        pass
    return rep

def _scan_reconcile_grid_and_missing_leg(snapshot: dict | None, coin: str = '') -> dict:
    if not _snapshot_positions_verified(snapshot):
        return {'skip': 'position_truth_unavailable', 'grid_clears': 0, 'legacy_deleted_routes': 0}
    try:
        snap = dict(snapshot or {}) if isinstance(snapshot, dict) else {}
    except Exception:
        snap = {}
    c = str(coin or '').upper().strip()
    nowv = float(time.time())
    try:
        st_map = globals().setdefault('_GRID_SCAN_RECONCILE_TS', {})
    except Exception:
        st_map = {}
        globals()['_GRID_SCAN_RECONCILE_TS'] = st_map
    key = c or '*'
    if (nowv - float(st_map.get(key) or 0.0)) < 2.0:
        return {'skip': 'ttl'}
    st_map[key] = nowv
    try:
        eps_u = float(globals().get('B1_NO_LEG_EPS_U', 0.0) or 0.0)
    except Exception:
        eps_u = 0.0
    out = {'grid_clears': 0, 'legacy_deleted_routes': 0}
    try:
        grids = ((getattr(globals().get('GRID_BOOK'), 'data', {}) or {}).get('grids', {})) if ('GRID_BOOK' in globals() and globals().get('GRID_BOOK') is not None) else {}
        if isinstance(grids, dict):
            for _gid, _g in list(grids.items()):
                if not isinstance(_g, dict):
                    continue
                _coin = str((_g or {}).get('coin') or '').upper().strip()
                if c and _coin != c:
                    continue
                _plat = str((_g or {}).get('platform') or '').upper().strip()
                _side = str((_g or {}).get('side') or '').upper().strip()
                _layers = [ly for ly in list((_g or {}).get('layers') or []) if isinstance(ly, dict) and str((ly or {}).get('state') or (ly or {}).get('status') or '').upper().strip() not in ('CLOSED','CLOSE','DONE')]
                if not _coin or not _plat or not _side or not _layers:
                    continue
                try:
                    _pos = _get_position(snap or {}, _coin, _plat) or {}
                    if _position_read_truth(_pos)['state'] == 'UNAVAILABLE':
                        continue
                    _has = bool(_has_pos(_pos))
                    _side_now = str((_pos or {}).get('side') or '').upper().strip()
                    _nu = abs(float(_pos_notional(_pos) or 0.0))
                except Exception:
                    _has, _side_now, _nu = False, '', 0.0
                _observed_state = _position_read_truth(_pos)['state']
                if (_observed_state == 'CONFIRMED_EMPTY'
                        or (_observed_state == 'FOUND' and _side_now in ('LONG', 'SHORT') and _side_now != _side)):
                    _rep = _grid_force_clear_leg_history(_coin, _plat, _side, reason='scan_leg_missing_reset', src_mod='M9', src_act='scan_reconcile', apply_round_block=False)
                    out['grid_clears'] = int(out.get('grid_clears') or 0) + int((_rep or {}).get('grid_changed') or 0)
    except Exception as _e:
        _log_exc(mod='SYS', stage='EXC_PASS', e=_e)
    try:
        coins = [c] if c else []
        if not coins:
            try:
                coins = sorted({str((_g or {}).get('coin') or '').upper().strip() for _g in list((grids or {}).values()) if isinstance(_g, dict) and str((_g or {}).get('coin') or '').strip()})
            except Exception:
                coins = []
        for _coin in coins:
            try:
                _pe = _get_position(snap or {}, _coin, 'EXT') or {}
                _pv = _get_position(snap or {}, _coin, 'VAR') or {}
                _eh = bool(_has_pos(_pe)) and abs(float(_pos_notional(_pe) or 0.0)) > float(eps_u)
                _vh = bool(_has_pos(_pv)) and abs(float(_pos_notional(_pv) or 0.0)) > float(eps_u)
                if _eh and (not _vh) and float((_pe or {}).get('upnl_u') or 0.0) < 0.0:
                    _n = abs(float(_pos_notional(_pe) or 0.0))
                    if _n > float(eps_u):
                        _legacy_deleted_after_failure(snap or {}, _coin, 'VAR', ('SHORT' if str((_pe or {}).get('side') or '').upper().strip() == 'LONG' else 'LONG'), float(_n), 'loss_leg_counterpart_legacy_deleted', source_mod='LEGACY_DELETED')
                        out['legacy_deleted_routes'] = int(out.get('legacy_deleted_routes') or 0) + 1
                elif _vh and (not _eh) and float((_pv or {}).get('upnl_u') or 0.0) < 0.0:
                    _n = abs(float(_pos_notional(_pv) or 0.0))
                    if _n > float(eps_u):
                        _legacy_deleted_after_failure(snap or {}, _coin, 'EXT', ('SHORT' if str((_pv or {}).get('side') or '').upper().strip() == 'LONG' else 'LONG'), float(_n), 'loss_leg_counterpart_legacy_deleted', source_mod='LEGACY_DELETED')
                        out['legacy_deleted_routes'] = int(out.get('legacy_deleted_routes') or 0) + 1
            except Exception:
                continue
    except Exception as _e:
        _log_exc(mod='SYS', stage='EXC_PASS', e=_e)
    return out

