def _exec_ui_not_started_timeout_sec() -> float:
    try:
        return max(1.0, float(os.getenv("EXEC_UI_NOT_STARTED_TIMEOUT_SEC", "3") or 3.0))
    except Exception:
        return 3.0

def _exec_ui_nav_timeout_sec() -> float:
    try:
        return max(_exec_ui_not_started_timeout_sec(), float(os.getenv("EXEC_UI_NAV_TIMEOUT_SEC", "5") or 5.0))
    except Exception:
        return 5.0

def _exec_submit_timeout_sec() -> float:
    try:
        return max(3.0, float(os.getenv("EXEC_SUBMIT_TIMEOUT_SEC", "10") or 10.0))
    except Exception:
        return 10.0

def _req_identity_key_from_dict(rd: dict | None) -> str:
    try:
        if not isinstance(rd, dict):
            return ""
        meta = rd.get("meta") if isinstance(rd.get("meta"), dict) else {}
        req_id = str(meta.get("req_id") or rd.get("req_id") or rd.get("id") or "").strip()
        trace_id = str(meta.get("trace_id") or rd.get("trace_id") or rd.get("trace") or "").strip()
        module = str(rd.get("module") or "").upper().strip()
        coin = str(rd.get("coin") or "").upper().strip()
        platform = str(rd.get("platform") or rd.get("plat") or "").upper().strip()
        action_type = str(rd.get("action_type") or rd.get("action") or "").lower().strip()
        return "|".join([req_id, trace_id, module, coin, platform, action_type])
    except Exception:
        return ""


_EXEC_DISPATCH_CLAIMS: dict[str, dict[str, Any]] = {}
_EXEC_DISPATCH_CLAIMS_LOCK = threading.RLock()
_EXEC_DISPATCH_ACTIVE_STATES = {"DISPATCHED", "HANDOFFED", "RUNNING", "LOCAL_REBUILDING", "POSTCHECK"}


def _exec_dispatch_claim_key(req_any: Any) -> str:
    try:
        rd = _req_get_dict(req_any)
    except Exception:
        rd = req_any if isinstance(req_any, dict) else {}
    try:
        if not isinstance(rd, dict):
            return ''
        meta = rd.get('meta') if isinstance(rd.get('meta'), dict) else {}
    except Exception:
        meta = {}
    try:
        req_id = str((meta.get('req_id') if isinstance(meta, dict) else '') or rd.get('req_id') or rd.get('id') or '').strip()
        trace_id = str((meta.get('trace_id') if isinstance(meta, dict) else '') or rd.get('trace_id') or rd.get('trace') or '').strip()
        if req_id or trace_id:
            return f"DISPATCH|{req_id}|{trace_id}"
    except Exception:
        pass
    try:
        ident = str(_req_identity_key_from_dict(rd) or '').strip()
    except Exception:
        ident = ''
    return f"DISPATCH|{ident}" if ident else ''


def _exec_dispatch_claim_peek(req_or_key: Any) -> dict[str, Any]:
    key = str(req_or_key or '').strip() if isinstance(req_or_key, str) else _exec_dispatch_claim_key(req_or_key)
    if not key:
        return {}
    with _EXEC_DISPATCH_CLAIMS_LOCK:
        return dict(_EXEC_DISPATCH_CLAIMS.get(key) or {})

def _exec_dispatch_claim_release_scope(plat: Any = '', *, reason: str = '', final_state: str = 'RELEASED') -> int:
    try:
        _scope = _pw_runtime_scope_normalize(plat)
    except Exception:
        _scope = 'ALL'
    removed = 0
    with _EXEC_DISPATCH_CLAIMS_LOCK:
        for _k, _v in list((_EXEC_DISPATCH_CLAIMS or {}).items()):
            try:
                _plat = str((_v or {}).get('platform') or '').upper().strip()
            except Exception:
                _plat = ''
            if _scope not in ('ALL', '') and _plat and _plat != _scope:
                continue
            _EXEC_DISPATCH_CLAIMS.pop(_k, None)
            removed += 1
    if removed:
        try:
            safe_log(lambda: f"[{now_ts()}] [EXEC] DISPATCH_RELEASE_SCOPE plat={_scope} removed={removed} reason={str(reason or '')[:80]}")
        except Exception:
            pass
    return int(removed)

def _exec_dispatch_claim_begin(req_any: Any, *, worker_key: str = '', source: str = '') -> tuple[bool, dict[str, Any]]:
    key = _exec_dispatch_claim_key(req_any)
    if not key:
        return True, {'key': '', 'state': 'NO_KEY', 'worker_key': str(worker_key or '')}
    nowv = float(time.time())
    try:
        rd = _req_get_dict(req_any)
    except Exception:
        rd = req_any if isinstance(req_any, dict) else {}
    try:
        meta = rd.get('meta') if isinstance(rd.get('meta'), dict) else {}
    except Exception:
        meta = {}
    fresh = {
        'key': key,
        'state': 'DISPATCHED',
        'worker_key': str(worker_key or ''),
        'source': str(source or ''),
        'ts': nowv,
        'updated_ts': nowv,
        'req_id': str((meta.get('req_id') if isinstance(meta, dict) else '') or rd.get('req_id') or ''),
        'trace_id': str((meta.get('trace_id') if isinstance(meta, dict) else '') or rd.get('trace_id') or rd.get('trace') or ''),
        'module': str(rd.get('module') or '').upper().strip(),
        'coin': str(rd.get('coin') or '').upper().strip(),
        'platform': str(rd.get('platform') or rd.get('plat') or '').upper().strip(),
        'action_type': str(rd.get('action_type') or rd.get('action') or '').lower().strip(),
        'req_key': str(_req_identity_key_from_dict(rd) or ''),
        'reason': 'dispatch_begin',
    }
    with _EXEC_DISPATCH_CLAIMS_LOCK:
        cur = dict(_EXEC_DISPATCH_CLAIMS.get(key) or {})
        cur_state = str(cur.get('state') or '').upper().strip()
        if cur and cur_state in _EXEC_DISPATCH_ACTIVE_STATES:
            try:
                cur['age_sec'] = max(0.0, nowv - float(cur.get('updated_ts') or cur.get('ts') or nowv))
            except Exception:
                cur['age_sec'] = 0.0
            _stale_timeout = max(4.0, float(globals().get('EXEC_DISPATCH_STALE_TIMEOUT_SEC', EXEC_DISPATCH_STALE_TIMEOUT_SEC) or EXEC_DISPATCH_STALE_TIMEOUT_SEC))
            _stale = bool(float(cur.get('age_sec') or 0.0) >= _stale_timeout)
            _local_rebuild_stale = bool(cur_state == 'LOCAL_REBUILDING' and (not _pw_runtime_is_recovering(str(cur.get('platform') or ''))) and float(cur.get('age_sec') or 0.0) >= min(_stale_timeout, 6.0))
            # [PATCH] 自我重入：执行线程启动时先把本请求标成 LOCAL_REBUILDING，随后线程内再次进入 executor_run 又来 claim，
            # 被自己刚打的标记拦成 duplicate_dispatch_blocked，且每轮重复 → 该币永久卡死。同一 worker + 同一请求视为同一次派发，放行。
            _self_reentry = bool(
                cur_state == 'LOCAL_REBUILDING'
                and str(cur.get('worker_key') or '') == str(worker_key or '')
                and str(worker_key or '')
                and str(cur.get('req_key') or '') == str(fresh.get('req_key') or '')
            )
            if _self_reentry:
                try:
                    cur['reentry_allowed'] = True
                except Exception:
                    pass
                _EXEC_DISPATCH_CLAIMS[key] = dict(fresh, reentry_of=str(cur.get('reason') or ''))
                return True, dict(fresh)
            if _stale or _local_rebuild_stale:
                try:
                    cur['auto_released'] = True
                    cur['auto_release_reason'] = 'dispatch_claim_timeout_release' if _stale else 'local_rebuilding_timeout_release'
                except Exception:
                    pass
                _EXEC_DISPATCH_CLAIMS.pop(key, None)
            else:
                return False, cur
        _EXEC_DISPATCH_CLAIMS[key] = dict(fresh)
    return True, dict(fresh)


def _exec_dispatch_claim_touch(req_or_key: Any, state: str, reason: str = '', **extra: Any) -> dict[str, Any]:
    key = str(req_or_key or '').strip() if isinstance(req_or_key, str) else _exec_dispatch_claim_key(req_or_key)
    if not key:
        return {}
    nowv = float(time.time())
    with _EXEC_DISPATCH_CLAIMS_LOCK:
        cur = dict(_EXEC_DISPATCH_CLAIMS.get(key) or {})
        cur['key'] = key
        cur['state'] = str(state or '').upper().strip()
        cur['reason'] = str(reason or '')[:200]
        cur['updated_ts'] = nowv
        if extra:
            try:
                cur.update({k: v for k, v in dict(extra or {}).items() if v not in (None, '')})
            except Exception:
                pass
        _EXEC_DISPATCH_CLAIMS[key] = dict(cur)
        return dict(cur)


def _exec_dispatch_claim_release(req_or_key: Any, *, final_state: str = 'DONE', reason: str = '', **extra: Any) -> dict[str, Any]:
    key = str(req_or_key or '').strip() if isinstance(req_or_key, str) else _exec_dispatch_claim_key(req_or_key)
    if not key:
        return {}
    nowv = float(time.time())
    with _EXEC_DISPATCH_CLAIMS_LOCK:
        cur = dict(_EXEC_DISPATCH_CLAIMS.pop(key, {}) or {})
    cur['key'] = key
    cur['state'] = str(final_state or 'DONE').upper().strip()
    cur['reason'] = str(reason or '')[:200]
    cur['released_ts'] = nowv
    if extra:
        try:
            cur.update({k: v for k, v in dict(extra or {}).items() if v not in (None, '')})
        except Exception:
            pass
    return dict(cur)


def _executor_duplicate_dispatch_skip_results(requests: list | None, *, reason: str, holder: dict | None = None, batch_name: str = 'EXECUTOR') -> list:
    out = []
    holder = dict(holder or {}) if isinstance(holder, dict) else {}
    for _req in (requests or []):
        _detail = {
            'batch_name': str(batch_name or 'EXECUTOR'),
            'fail_reason': str(reason or 'duplicate_dispatch_blocked')[:200],
            'holder_state': str(holder.get('state') or ''),
            'holder_worker_key': str(holder.get('worker_key') or ''),
            'holder_reason': str(holder.get('reason') or ''),
            'holder_age_sec': safe_float(holder.get('age_sec'), default=None),
            'holder_trace_id': str(holder.get('trace_id') or ''),
            'holder_req_id': str(holder.get('req_id') or ''),
            'last_stage': 'EXECUTOR_HANDOFF_WAIT',
            'last_step': 'dispatch_claim_duplicate',
            'fail_step': 'duplicate_dispatch_blocked',
        }
        rr = _executor_contract_reject_record(_req, phase='duplicate_dispatch_guard', reason=str(reason or 'duplicate_dispatch_blocked'), detail=_detail)
        try:
            rr['duplicate_dispatch_blocked'] = True
        except Exception:
            pass
        out.append(rr)
    return out

def _handoff_guard_clear() -> None:
    try:
        _HANDOFF_TRACE_GUARD.last_sig = ""
        _HANDOFF_TRACE_GUARD.last_ts = 0.0
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_254', _e)
        pass
def _handoff_guard_allow(mod: str, note: str, reason: str, *, dedup_window_sec: float = 1.2) -> bool:
    try:
        sig = f"{str(mod or '').upper().strip()}|{str(note or '').strip()}|{str(reason or '').strip()}"
        nowv = float(time.time())
        last_sig = str(getattr(_HANDOFF_TRACE_GUARD, 'last_sig', '') or '')
        last_ts = float(getattr(_HANDOFF_TRACE_GUARD, 'last_ts', 0.0) or 0.0)
        _HANDOFF_TRACE_GUARD.last_sig = sig
        _HANDOFF_TRACE_GUARD.last_ts = nowv
        if sig and sig == last_sig and (nowv - last_ts) <= float(dedup_window_sec):
            return False
        return True
    except Exception:
        return True

    _tracker = globals().get('_WORKER_STATE')
    if _tracker is not None and _tracker.retired_current():
        return None
def _active_req_clear(reason: str = "") -> None:
    try:
        _ACTIVE_EXEC_CTX.req_ref = None
        _ACTIVE_EXEC_CTX.req = {}
        _ACTIVE_EXEC_CTX.ts = 0.0
        _ACTIVE_EXEC_CTX.last_stage = ""
        _ACTIVE_EXEC_CTX.last_reason = str(reason or "")
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_255', _e)
        pass
    try:
        with _ACTIVE_EXEC_SHARED_LOCK:
            _ACTIVE_EXEC_SHARED.clear()
            if reason:
                _ACTIVE_EXEC_SHARED['last_reason'] = str(reason or "")
                _ACTIVE_EXEC_SHARED['last_stage'] = "ACTIVE_REQ_CLEAR"
                _ACTIVE_EXEC_SHARED['last_ts'] = float(time.time())
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_255a', _e)
        pass
    try:
        _set_current_trace_id("")
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_256', _e)
        pass
    try:
        _handoff_guard_clear()
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_257', _e)
        pass
    try:
        if reason:
            _pin("ACTIVE_REQ_CLEAR_OK", mod="EXEC", coin="-", ok=1, reason=str(reason)[:120], stage="ACTIVE_REQ_CLEAR", trace="")
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_258', _e)
        pass
def _active_req_snapshot() -> dict:
    try:
        req = getattr(_ACTIVE_EXEC_CTX, "req", {})
        if isinstance(req, dict) and req:
            return dict(req or {})
    except Exception:
        pass
    try:
        with _ACTIVE_EXEC_SHARED_LOCK:
            req = dict(_ACTIVE_EXEC_SHARED or {})
        if not isinstance(req, dict):
            return {}
        try:
            _stage = str(req.get("last_stage") or "").upper().strip()
            _req_id = str(req.get("req_id") or "").strip()
            _trace_id = str(req.get("trace_id") or "").strip()
            _module = str(req.get("module") or "").strip()
            if (_stage == "ACTIVE_REQ_CLEAR") and (not _req_id) and (not _trace_id) and (not _module):
                return {}
        except Exception:
            pass
        return req
    except Exception:
        return {}

def _active_req_bind(req_any: object, *, stage: str = "DEQUEUED") -> dict:
    if not _worker_runtime_update_allowed():
        return _active_req_snapshot()
    _ACTIVE_EXEC_CTX.req_ref = req_any  # Thread-local only; never borrow another worker's request.
    rd = {}
    try:
        rd = _req_get_dict(req_any)
    except Exception:
        rd = req_any if isinstance(req_any, dict) else {}
    try:
        meta = rd.get("meta") if isinstance(rd.get("meta"), dict) else {}
    except Exception:
        meta = {}
    req_id = str(meta.get("req_id") or rd.get("req_id") or rd.get("id") or "").strip()
    trace_id = str(meta.get("trace_id") or rd.get("trace_id") or rd.get("trace") or "").strip()
    if not trace_id:
        try:
            trace_id = str(_trace_make(str(rd.get("module") or "EXEC"), str(rd.get("coin") or "")))
        except Exception:
            trace_id = req_id
    _bind_now = float(time.time())
    try:
        _bind_worker_key = str(_EXEC_WORKER_LOCAL.worker_key or _exec_runtime_worker_key() or "").strip()
    except Exception:
        _bind_worker_key = ""
    ctx = {
        "req_id": req_id,
        "trace_id": trace_id,
        "module": str(rd.get("module") or "").upper().strip(),
        "coin": str(rd.get("coin") or "").upper().strip(),
        "platform": str(rd.get("platform") or "").upper().strip(),
        "action_type": str(rd.get("action_type") or rd.get("action") or "").lower().strip(),
        "bind_ts": _bind_now,
        "last_ts": _bind_now,
        "stage": str(stage or "DEQUEUED"),
        "last_stage": str(stage or "DEQUEUED"),
        "last_reason": "bind",
        "where": "active_req_bind",
        "last_where": "active_req_bind",
        "worker_key": _bind_worker_key,
        "req_key": _req_identity_key_from_dict(rd),
    }
    try:
        _ACTIVE_EXEC_CTX.req = ctx
        _ACTIVE_EXEC_CTX.ts = float(ctx["bind_ts"])
        _ACTIVE_EXEC_CTX.last_stage = str(stage or "DEQUEUED")
        _ACTIVE_EXEC_CTX.last_reason = ""
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_259', _e)
        pass
    try:
        with _ACTIVE_EXEC_SHARED_LOCK:
            _ACTIVE_EXEC_SHARED.clear()
            _ACTIVE_EXEC_SHARED.update(dict(ctx or {}))
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_259a', _e)
        pass
    try:
        _set_current_trace_id(trace_id)
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_260', _e)
        pass
    try:
        _pin("ACTIVE_REQ_BIND_OK", mod=str(ctx.get("module") or "EXEC"), coin=str(ctx.get("coin") or "-"), ok=1,
             reason=f"req_id={req_id or '-'}", trace=trace_id, plat=str(ctx.get("platform") or ""),
             act=str(ctx.get("action_type") or ""), stage=str(stage or "DEQUEUED"))
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_261', _e)
        pass
    return ctx

def _exec_ui_busy_state(*, platform: str = "", coin: str = "") -> dict | None:
    """统一给 M2 / 指标链看的‘执行器正在占页面’状态。

    人话：
    - 以前只在‘提交后确认阶段’拦 M2 抢页面；范围太窄。
    - 现在扩到‘执行器整段 UI 操作期’：只要最近几秒内执行器正在某平台跑 UI，
      M2 就不要再 bring_to_front / 切币 / 读指标，避免你看到“下单前后页面来回跳/刷新”。
    """
    try:
        st = _exec_confirm_state_busy(platform=platform, coin=coin)
    except Exception:
        st = None
    if isinstance(st, dict):
        try:
            out = dict(st)
        except Exception:
            out = {"active": True}
        out["source"] = out.get("source") or "exec_confirm"
        return out
    try:
        max_age = float(os.getenv("EXEC_UI_BUSY_MAX_AGE_SEC", "8") or 8.0)
    except Exception:
        max_age = 8.0
    try:
        nowv = float(time.time())
    except Exception:
        nowv = 0.0
    try:
        cur = _active_req_snapshot() or {}
    except Exception:
        cur = {}
    if not isinstance(cur, dict) or not cur:
        return None
    try:
        plat0 = str(platform or "").upper().strip()
        coin0 = str(coin or "").upper().strip()
        cur_plat = str(cur.get("platform") or "").upper().strip()
        cur_coin = str(cur.get("coin") or "").upper().strip()
        if plat0 and cur_plat not in ("", plat0):
            return None
        if coin0 and cur_coin not in ("", coin0):
            return None
        tsv = float(cur.get("last_ts") or cur.get("bind_ts") or 0.0)
        age = max(0.0, float(nowv - tsv)) if tsv > 0 else 999999.0
        if age > float(max_age):
            return None
        stage = str(cur.get("last_stage") or cur.get("stage") or "").upper().strip()
        if stage in ("", "DEQUEUED", "DONE", "IDLE", "ACTIVE_REQ_CLEAR"):
            return None
        return {
            "active": True,
            "platform": cur_plat,
            "coin": cur_coin,
            "label": str(cur.get("action_type") or cur.get("module") or "exec_ui")[:80],
            "holder": str(cur.get("trace_id") or cur.get("req_id") or "")[:120],
            "started_ts": float(cur.get("bind_ts") or tsv or nowv),
            "until": float(tsv + max_age) if tsv > 0 else 0.0,
            "age_sec": float(age),
            "source": "active_req",
            "stage": stage,
        }
    except Exception:
        return None
    _tracker = globals().get('_WORKER_STATE')
    if _tracker is not None and _tracker.retired_current():
        return _active_req_snapshot()
def _active_req_touch(stage: str, reason: str = "", **extra) -> dict:
    ctx = _active_req_snapshot()
    if not ctx:
        ctx = {"module": "EXEC", "coin": "", "platform": "", "action_type": "", "trace_id": str(_get_current_trace_id() or "")}
    nowv = float(time.time())
    data = dict(extra or {})
    _where = str((data.get("where") or "")).strip()
    try:
        _worker_key = str((data.get("worker_key") or _EXEC_WORKER_LOCAL.worker_key or ctx.get("worker_key") or _exec_runtime_worker_key() or "")).strip()
    except Exception:
        _worker_key = str((data.get("worker_key") or ctx.get("worker_key") or "")).strip()
    for _src, _dst in (("coin", "coin"), ("platform", "platform"), ("plat", "platform"), ("module", "module"), ("mod", "module"), ("action_type", "action_type"), ("act", "action_type"), ("req_id", "req_id"), ("trace_id", "trace_id"), ("trace", "trace_id")):
        try:
            _val = data.get(_src)
        except Exception:
            _val = None
        if _val not in (None, ""):
            if _dst in ("coin", "platform", "module"):
                ctx[_dst] = str(_val or "").upper().strip()
            elif _dst == "action_type":
                ctx[_dst] = str(_val or "").lower().strip()
            else:
                ctx[_dst] = str(_val or "").strip()
    ctx["last_stage"] = str(stage or "")
    ctx["last_reason"] = str(reason or "")
    ctx["last_ts"] = nowv
    ctx["last_where"] = _where
    if _where:
        ctx["where"] = _where
    if _worker_key:
        ctx["worker_key"] = _worker_key
    try:
        _ACTIVE_EXEC_CTX.req = ctx
        _ACTIVE_EXEC_CTX.last_stage = str(stage or "")
        _ACTIVE_EXEC_CTX.last_reason = str(reason or "")
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_262', _e)
        pass
    try:
        with _ACTIVE_EXEC_SHARED_LOCK:
            _ACTIVE_EXEC_SHARED.clear()
            _ACTIVE_EXEC_SHARED.update(dict(ctx or {}))
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_262a', _e)
        pass
    try:
        _ctx_trace = str(ctx.get("trace_id") or "").strip()
        _cur_trace = str(_get_current_trace_id() or "").strip()
        if _ctx_trace and _ctx_trace != _cur_trace:
            _set_current_trace_id(_ctx_trace)
            _cur_trace = _ctx_trace
    except Exception:
        _cur_trace = str(ctx.get("trace_id") or "")
    try:
        payload = {"stage": str(stage or ""), "reason": str(reason or "")}
        payload.update({k: v for k, v in dict(extra or {}).items() if v not in (None, "")})
        _pin("ACTIVE_REQ_TOUCH", mod=str(ctx.get("module") or "EXEC"), coin=str(ctx.get("coin") or "-"), ok=1,
             reason=_json_dumps_bot(payload, ensure_ascii=False)[:180], trace=str(_cur_trace or ctx.get("trace_id") or ""),
             plat=str(ctx.get("platform") or ""), act=str(ctx.get("action_type") or ""), stage=str(stage or ""))
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_263', _e)
        pass
    return ctx

def _active_req_ensure_consistent(req_any: object, *, stage: str = "EXEC_REQ_CTX_CHECK", reason: str = "") -> dict:
    try:
        rd = _req_get_dict(req_any)
    except Exception:
        rd = req_any if isinstance(req_any, dict) else {}
    bound = _active_req_snapshot() or {}
    req_key = _req_identity_key_from_dict(rd)
    req_trace = ""
    try:
        meta = rd.get("meta") if isinstance(rd.get("meta"), dict) else {}
        req_trace = str(meta.get("trace_id") or rd.get("trace_id") or rd.get("trace") or "").strip()
    except Exception:
        req_trace = ""
    if not req_trace:
        req_trace = str(bound.get("trace_id") or "").strip()
    cur_trace = str(_get_current_trace_id() or "").strip()
    bound_key = str(bound.get("req_key") or "").strip()
    mismatch_parts = []
    if req_key and bound_key and req_key != bound_key:
        mismatch_parts.append("req_key")
    if req_trace and cur_trace and req_trace != cur_trace:
        mismatch_parts.append("trace")
    if mismatch_parts or not bound:
        try:
            _active_req_clear("ctx_rebind_before_exec")
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_264', _e)
            pass
        rebound = _active_req_bind(req_any, stage=stage)
        try:
            _pin("ACTIVE_REQ_REBIND", mod=str(rebound.get("module") or rd.get("module") or "EXEC"), coin=str(rebound.get("coin") or rd.get("coin") or "-"), ok=1,
                 reason=f"{'/'.join(mismatch_parts) if mismatch_parts else 'empty_ctx'}|{str(reason or 'ctx_rebind')[:120]}",
                 trace=str(rebound.get("trace_id") or req_trace or ""), plat=str(rebound.get("platform") or rd.get("platform") or ""),
                 act=str(rebound.get("action_type") or rd.get("action_type") or rd.get("action") or ''), stage=str(stage or "EXEC_REQ_CTX_CHECK"))
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_265', _e)
            pass
        return rebound
    if req_trace and (not cur_trace):
        try:
            _set_current_trace_id(req_trace)
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_266', _e)
            pass
    try:
        _pin("ACTIVE_REQ_CTX_OK", mod=str(bound.get("module") or rd.get("module") or "EXEC"), coin=str(bound.get("coin") or rd.get("coin") or "-"), ok=1,
             reason=str(reason or "ctx_ok")[:120], trace=str(req_trace or bound.get("trace_id") or ""), plat=str(bound.get("platform") or rd.get("platform") or ""),
             act=str(bound.get("action_type") or rd.get("action_type") or rd.get("action") or ""), stage=str(stage or "EXEC_REQ_CTX_CHECK"))
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_267', _e)
        pass
    return bound

def _active_req_fail_fast(reason: str, *, stage: str = "EXEC_FAIL_FAST", **detail) -> tuple[bool, str, dict]:
    ctx = _active_req_touch(stage, str(reason or ""), **detail)
    det = {"active_req": dict(ctx or {})}
    try:
        det.update({k: v for k, v in dict(detail or {}).items()})
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_268', _e)
        pass
    return False, str(reason or "exec_fail_fast"), det

def _executor_preflight_before_open(exe: object, *, plat: str, coin: str, side: str, act: str) -> tuple[bool, str, dict]:
    plat_u = str(plat or "").upper().strip()
    coin_u = str(coin or "").upper().strip()
    side_u = str(side or "").upper().strip()
    act_l = str(act or "").lower().strip()
    try:
        page = getattr(exe, "page", None)
    except Exception:
        page = None
    if page is None:
        return _active_req_fail_fast(f"{plat_u.lower()}_page_missing", stage="UI_PREFLIGHT", platform=plat_u, coin=coin_u)
    try:
        _pw_require_page(page, f"EXEC_PREFLIGHT:{plat_u}:{coin_u}")
    except Exception as e:
        return _active_req_fail_fast(f"ui_page_dead:{type(e).__name__}", stage="UI_PREFLIGHT", platform=plat_u, coin=coin_u)
    _active_req_touch("UI_FLOW_BEGIN", f"{plat_u}:{coin_u}:{act_l or 'open'}", side=side_u)
    try:
        _exec_front_if_needed(page, f"exec_preflight.front.{plat_u.lower()}.{coin_u}", label=f"EXEC_PREFLIGHT:{plat_u}:{coin_u}", plat=plat_u, coin=coin_u, min_interval_sec=float(_exec_cfg_float("EXEC_FRONT_DEDUPE_SEC", 1.25)))
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_269', _e)
        pass
    start_ts = float(time.time())
    try:
        if plat_u == "VAR":
            _pw_call(f"exec_preflight.var.body_visible.{coin_u}", page.wait_for_selector, "body", timeout=int(_exec_ui_not_started_timeout_sec() * 1000.0))
            try:
                _pw_call(f"exec_preflight.var.body_click.{coin_u}", page.click, "body", timeout=1200)
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_270', _e)
                pass
            if side_u == "BUY":
                btn = page.locator(VAR_TRADE.get("btn_buy_toggle")).first
            elif side_u == "SELL":
                btn = page.locator(VAR_TRADE.get("btn_sell_toggle")).first
            else:
                btn = page.locator(VAR_TRADE.get("submit_button")).first
            _pw_call(f"exec_preflight.var.btn_wait.{coin_u}", btn.wait_for, state="visible", timeout=int(_exec_ui_nav_timeout_sec() * 1000.0))
        elif plat_u == "EXT":
            _pw_call(f"exec_preflight.ext.body_visible.{coin_u}", page.wait_for_selector, "body", timeout=int(_exec_ui_not_started_timeout_sec() * 1000.0))
            try:
                inp = exe.loc_value_input().first
            except Exception:
                inp = None
            if inp is not None:
                _pw_call(f"exec_preflight.ext.input_wait.{coin_u}", inp.wait_for, state="visible", timeout=int(_exec_ui_nav_timeout_sec() * 1000.0))
        else:
            return _active_req_fail_fast(f"bad_platform:{plat_u}", stage="UI_PREFLIGHT", platform=plat_u, coin=coin_u)
    except Exception as e:
        return _active_req_fail_fast(f"ui_not_started:{type(e).__name__}", stage="UI_PREFLIGHT", platform=plat_u, coin=coin_u, elapsed_sec=round(time.time()-start_ts, 3))
    return True, "ok", {"elapsed_sec": round(time.time()-start_ts, 3), "platform": plat_u, "coin": coin_u, "side": side_u}

def _trace_make(mod: str, coin: str | None = None) -> str:
    """生成稳定、可 grep 的短 trace_id：MOD-COIN-xxxxxx"""
    try:
        mm = str(mod or "NA").upper().strip() or "NA"
    except Exception:
        mm = "NA"
    try:
        cc = str(coin or "*").upper().strip() or "*"
    except Exception:
        cc = "*"
    try:
        return f"{mm}-{cc}-{uuid.uuid4().hex[:6]}"
    except Exception:
        try:
            return str(uuid.uuid4())
        except Exception:
            return "TRACE"

def _trace_set_for(mod: str, coin: str | None = None) -> str:
    """设置当前线程 trace_id，并返回该 trace_id。"""
    tid = ""
    try:
        tid = _trace_make(mod, coin)
        _set_current_trace_id(tid)
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_271', _e)
        pass
    return tid

_REQ_CANON_KEYS = {
    "module","coin","platform","action_type","submodule","params","meta","priority","ts",
    "trace_id","side","amount_usd","amount","price",
    # M10 组三步请求必须物理保留这些顶层键，不能再被 strip_unknown 洗进 meta.extras
    "steps","plan","group_request","group_id","request_id",
}

def _ensure_meta_trace(meta: dict | None, trace_id: str = "") -> dict:
    """确保 meta 是 dict 且包含 trace_id（若缺失则尝试用 thread-local 当前 trace）。"""
    try:
        m = meta if isinstance(meta, dict) else {}
        tid = str(trace_id or m.get("trace_id") or "").strip()
        if not tid:
            try:
                tid = str(_get_current_trace_id() or "").strip()
            except Exception:
                tid = ""
        if tid and (not str(m.get("trace_id") or "").strip()):
            m["trace_id"] = tid
        return m
    except Exception:
        return meta if isinstance(meta, dict) else {}

def _canon_req_dict(rd0: dict, *, strip_unknown: bool = False) -> dict:
    """请求契约收敛（v5）：
    - 统一：module/coin/platform/action_type/submodule/params/meta/trace_id
    - 折叠：action->action_type, plat->platform, t->trace_id 等常见别名
    - 兜底：amount_usd/side/price 顶层口径（从 params/meta/别名推断）
    - 可选：strip_unknown=True 时，把未知顶层字段移入 meta.extras（避免“暗字段/口径漂移”）
    """
    try:
        if not isinstance(rd0, dict):
            return rd0
        rd = dict(rd0)
        meta = rd.get("meta")
        if not isinstance(meta, dict):
            meta = {}
        params = rd.get("params")
        if not isinstance(params, dict):
            params = {}

        try:
            if (not rd.get("platform")) and rd.get("plat"):
                rd["platform"] = rd.get("plat")
            if (not rd.get("action_type")):
                if rd.get("action"):
                    rd["action_type"] = rd.get("action")
                elif rd.get("act"):
                    rd["action_type"] = rd.get("act")
            if (not rd.get("submodule")) and rd.get("sub_mod"):
                rd["submodule"] = rd.get("sub_mod")
            if (not rd.get("trace_id")):
                if rd.get("t"):
                    rd["trace_id"] = rd.get("t")
                elif rd.get("trace"):
                    rd["trace_id"] = rd.get("trace")
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_272', _e)
            pass
        try:
            rd["module"] = str(rd.get("module") or "").strip()
        except Exception:
            rd["module"] = ""
        try:
            rd["coin"] = str(rd.get("coin") or "").strip().upper()
        except Exception:
            rd["coin"] = ""
        try:
            rd["platform"] = str(rd.get("platform") or "").strip().upper()
        except Exception:
            rd["platform"] = ""
        try:
            rd["action_type"] = str(rd.get("action_type") or "").strip()
        except Exception:
            rd["action_type"] = ""
        try:
            if rd.get("submodule") is None:
                rd["submodule"] = ""
            rd["submodule"] = str(rd.get("submodule") or "").strip()
        except Exception:
            rd["submodule"] = ""

        try:
            tid = str(rd.get("trace_id") or "").strip()
            if not tid:
                tid = str(meta.get("trace_id") or meta.get("trace") or "").strip()
            if not tid:
                tid = str(params.get("trace_id") or params.get("trace") or "").strip()
            meta = _ensure_meta_trace(meta, tid)
            tid2 = str(meta.get("trace_id") or "").strip()
            if tid2:
                rd["trace_id"] = tid2
            else:
                try:
                    rd["trace_id"] = str(_trace_make(rd.get("module") or "REQ", rd.get("coin") or ""))[:64]
                    meta = _ensure_meta_trace(meta, rd["trace_id"])
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_273', _e)
                    pass
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_274', _e)
            pass
        def _pick_num(*xs):
            for x in xs:
                try:
                    if x is None or x == "":
                        continue
                    v = float(x)
                    if math.isfinite(v) and abs(v) > 0:
                        return v
                except Exception:
                    continue
            return 0.0

        try:
            amt_u = _coerce_final_amount_u(
                rd.get("final_amount_u"),
                params.get("final_amount_u"),
                meta.get("final_amount_u"),
                rd.get("amount_usd"), rd.get("amount_u"), rd.get("notional_u"), rd.get("value_u"),
                params.get("amount_usd"), params.get("amount_u"), params.get("notional_u"), params.get("value_u"),
                params.get("usd"), params.get("usdt"), params.get("notional"), params.get("value"),
                meta.get("amount_usd"), meta.get("amount_u"), meta.get("notional_u"), meta.get("value_u"),
            )
            if amt_u > 0:
                _apply_final_amount_contract(rd, params=params, meta=meta, amount_hint=amt_u)
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_275', _e)
            pass
        try:
            side_top = str(rd.get("side") or "").strip().upper()
            side_params = str(params.get("side") or "").strip().upper()
            side_meta = str(meta.get("side") or "").strip().upper()
            side = side_top or side_params or side_meta
            if side:
                rd["side"] = side
                if side_params and side_params != side:
                    meta["side_mismatch__params"] = f"{side_params}->{side}"
                    params["side"] = side
                elif not side_params:
                    params["side"] = side
                if side_meta and side_meta != side:
                    meta["side_mismatch__meta"] = f"{side_meta}->{side}"
                    meta["side"] = side
                elif not side_meta:
                    meta["side"] = side
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_277', _e)
            pass
        try:
            px = _pick_num(rd.get("price"), rd.get("px"), params.get("price"), params.get("px"), meta.get("price"), meta.get("px"))
            if px > 0:
                rd["price"] = float(px)
                if not _pick_num(params.get("price")):
                    params["price"] = float(px)
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_278', _e)
            pass
        rd["params"] = params
        rd["meta"] = meta

        if strip_unknown:
            try:
                extras = meta.get("extras")
                if not isinstance(extras, dict):
                    extras = {}
                for k in list(rd.keys()):
                    if k in _REQ_CANON_KEYS:
                        continue
                    if k in ("plat", "action", "act", "t", "trace"):
                        continue
                    if k.startswith("exec_") or k.startswith("filled_") or k in ("order_id","oid","err","detail"):
                        continue
                    extras[k] = rd.get(k)
                    rd.pop(k, None)
                if extras:
                    meta["extras"] = extras
                    rd["meta"] = meta
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_279', _e)
                pass
        return rd
    except Exception:
        return rd0

def _result_has_fill_evidence(rr_any: Any) -> bool:
    return _safety_has_fill_evidence(rr_any)

def _result_is_trade_effective(rr_any: Any) -> bool:
    return _safety_confirmation_state(rr_any) == 'confirmed_success'

def _result_confirmation_state(rr_any: Any) -> str:
    return _safety_confirmation_state(rr_any)

def _result_apply_confirmation_fields(rr: dict) -> dict:
    if isinstance(rr, dict):
        rr.update(_safety_apply_confirmation_fields(rr))
    return rr

def _build_execution_evidence(*, req_any: Any = None, exec_res_list: list | None = None, pre_state: dict | None = None, post_state: dict | None = None, snapshot: dict | None = None, ok: Any = None, reason: str = '', detail: Any = None) -> dict:
    try:
        reqd = _req_get_dict(req_any)
    except Exception:
        reqd = {}
    meta = reqd.get('meta') if isinstance(reqd.get('meta'), dict) else {}
    rows = [r for r in list(exec_res_list or []) if isinstance(r, dict)]
    submit_ok = any(bool(r.get('submit_ok') or r.get('ok')) for r in rows)
    fill_seen = any(bool(r.get('fill_confirmed')) or bool(_result_has_fill_evidence(r)) for r in rows)
    postcheck_ok = any(r.get('postcheck_ok') is True for r in rows)
    postcheck_fail = any(r.get('postcheck_ok') is False for r in rows)
    trade_effective_count = sum(1 for r in rows if _result_is_trade_effective(r))
    mod_u = str(reqd.get('module') or '').upper().strip()
    act_l = str(reqd.get('action_type') or reqd.get('action') or '').lower().strip()
    is_m9_open = (mod_u == 'M9' and act_l in ('increase', 'add', 'open'))
    confirmation_states = []
    for r in rows:
        try:
            st = str(r.get('confirmation_state') or _result_confirmation_state(r) or '').strip()
        except Exception:
            st = str(r.get('confirmation_state') or '').strip()
        if st:
            confirmation_states.append(st)
    _pending_timeout_sec = 20.0
    try:
        _pending_timeout_sec = float(globals().get('EXEC_CONFIRM_PENDING_TIMEOUT_SEC', 20.0) or 20.0)
    except Exception:
        _pending_timeout_sec = 20.0
    _now_ts_ev = float(time.time())
    _req_submit_ts = 0.0
    for _v in [
        reqd.get('submit_ts'), reqd.get('exec_submit_ts'), reqd.get('ts'),
        (meta.get('submit_ts') if isinstance(meta, dict) else None),
        (meta.get('exec_submit_ts') if isinstance(meta, dict) else None),
        (meta.get('request_ts') if isinstance(meta, dict) else None),
        (snapshot or {}).get('ts') if isinstance(snapshot, dict) else None,
    ]:
        try:
            _fv = float(_v or 0.0)
        except Exception:
            _fv = 0.0
        if _fv > _req_submit_ts:
            _req_submit_ts = _fv
    _latest_submit_ts = 0.0
    for _r in rows:
        try:
            _ts_candidates = [
                _r.get('submit_ts'), _r.get('exec_submit_ts'), _r.get('ts'),
                (_r.get('execution_evidence') or {}).get('submit_ts') if isinstance(_r.get('execution_evidence'), dict) else None,
                (_r.get('execution_evidence') or {}).get('snapshot_ts') if isinstance(_r.get('execution_evidence'), dict) else None,
            ]
            for _v in _ts_candidates:
                try:
                    _fv = float(_v or 0.0)
                except Exception:
                    _fv = 0.0
                if _fv > _latest_submit_ts:
                    _latest_submit_ts = _fv
        except Exception:
            continue
    if _latest_submit_ts <= 0 and _req_submit_ts > 0:
        _latest_submit_ts = float(_req_submit_ts)
        for _r in rows:
            try:
                if not isinstance(_r, dict):
                    continue
                if not _r.get('submit_ts'):
                    _r['submit_ts'] = float(_latest_submit_ts)
                if not _r.get('exec_submit_ts'):
                    _r['exec_submit_ts'] = float(_latest_submit_ts)
            except Exception:
                continue
    _pending_timed_out = bool(submit_ok) and (not postcheck_ok) and (not postcheck_fail) and (_latest_submit_ts > 0) and ((_now_ts_ev - _latest_submit_ts) >= _pending_timeout_sec)
    if postcheck_ok:
        final_state = 'confirmed_success'
    elif postcheck_fail:
        if is_m9_open and fill_seen:
            final_state = 'fill_seen_postcheck_fail_recovering'
        elif is_m9_open and submit_ok:
            final_state = 'submit_seen_postcheck_fail_recovering'
        else:
            final_state = 'confirmed_fail'
    elif _pending_timed_out:
        final_state = 'submitted_pending_confirm'
    elif fill_seen:
        final_state = 'fill_seen_pending_confirm'
    elif submit_ok:
        final_state = 'submitted_pending_confirm'
    else:
        final_state = 'submit_fail' if ok is False else 'unknown'
    final_confirmation_code = str(final_state)
    out = {
        'req_id': str(reqd.get('req_id') or meta.get('req_id') or ''),
        'trace_id': str(reqd.get('trace_id') or meta.get('trace_id') or ''),
        'module': str(reqd.get('module') or '').upper().strip(),
        'coin': str(reqd.get('coin') or '').upper().strip(),
        'platform': str(reqd.get('platform') or reqd.get('plat') or '').upper().strip(),
        'action_type': str(reqd.get('action_type') or reqd.get('action') or '').lower().strip(),
        'side': str((meta.get('side') if isinstance(meta, dict) else '') or (reqd.get('side') or '')).upper().strip(),
        'snapshot_ts': safe_float((snapshot or {}).get('ts'), default=None),
        'pre_state_present': isinstance(pre_state, dict),
        'post_state_present': isinstance(post_state, dict),
        'submit_ok': bool(submit_ok),
        'fill_seen': bool(fill_seen),
        'postcheck_ok': True if postcheck_ok else (False if postcheck_fail else None),
        'trade_effective_count': int(trade_effective_count),
        'final_state': str(final_state),
        'final_confirmation_code': str(final_state),
        'final_confirmation_code': str(final_confirmation_code),
        'reason': str(reason or ''),
        'detail': detail if isinstance(detail, dict) else ({'detail': detail} if detail not in (None, '') else {}),
        'rows': int(len(rows)),
        'confirmation_states': confirmation_states[:8],
        'effective': bool(trade_effective_count > 0 or postcheck_ok),
        'pending_timeout_sec': float(_pending_timeout_sec),
        'latest_submit_ts': (_latest_submit_ts if _latest_submit_ts > 0 else None),
        'pending_timed_out': bool(_pending_timed_out),
    }
    return out

def _attach_execution_evidence(exec_res_list: list | None, evidence: dict | None) -> None:
    try:
        ev = dict(evidence or {})
    except Exception:
        ev = {}
    if not ev:
        return
    for _rr in list(exec_res_list or []):
        if isinstance(_rr, dict):
            try:
                _rr['execution_evidence'] = dict(ev)
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_281', _e)
                pass
def _mark_exec_results_postcheck(exec_results: Any, *, ok: bool, reason: str = "", detail: Any = None) -> list:
    """把 POSTCHECK 结论回写到执行结果，统一摘要/审计口径。"""
    def _mark_nested_child_rows(holder: dict) -> None:
        try:
            child_rows = holder.get('m10_step_rows') if isinstance(holder.get('m10_step_rows'), list) else []
        except Exception:
            child_rows = []
        try:
            _detail = holder.get('detail') if isinstance(holder.get('detail'), dict) else {}
            if not child_rows and isinstance(_detail.get('m10_step_rows'), list):
                child_rows = _detail.get('m10_step_rows') or []
        except Exception:
            child_rows = child_rows or []
        for _idx, _child in enumerate(list(child_rows or [])):
            if not isinstance(_child, dict):
                continue
            try:
                _marked_child = _canon_exec_result(_child)
                _orig_submit_ok = bool(_marked_child.get("submit_ok") or _marked_child.get("ok"))
                _orig_fill_seen = bool(_marked_child.get("fill_confirmed")) or bool(_result_has_fill_evidence(_marked_child))
                _marked_child["ok"] = (True if bool(ok) else bool(_orig_submit_ok))
                _marked_child["submit_ok"] = bool(_orig_submit_ok)
                _marked_child["fill_confirmed"] = bool(_orig_fill_seen)
                _marked_child["postcheck_ok"] = bool(ok)
                _marked_child["postcheck_state"] = ("success" if bool(ok) else "fail")
                _marked_child["postcheck_reason"] = str(reason or "")
                if detail is not None:
                    _marked_child["postcheck_detail"] = detail
                if bool(ok):
                    _marked_child["trade_effective"] = bool(_result_is_trade_effective(_marked_child))
                else:
                    _marked_child["trade_effective"] = False
                _marked_child = _result_apply_confirmation_fields(_marked_child)
                _child.clear()
                _child.update(_marked_child)
                child_rows[_idx] = _child
            except Exception as _e:
                _record_swallowed_exception('mark_exec_results_postcheck.child_rows', _e)
                continue
        try:
            if isinstance(holder.get('m10_step_rows'), list):
                holder['m10_step_rows'] = child_rows
        except Exception:
            pass
        try:
            _detail = holder.get('detail') if isinstance(holder.get('detail'), dict) else None
            if isinstance(_detail, dict) and isinstance(_detail.get('m10_step_rows'), list):
                _detail['m10_step_rows'] = child_rows
        except Exception:
            pass
    out = []
    try:
        items = exec_results if isinstance(exec_results, list) else list(exec_results or [])
    except Exception:
        items = []
    for rr0 in items:
        try:
            rr = _canon_exec_result(rr0 if isinstance(rr0, dict) else {})
            _orig_submit_ok = bool(rr.get("submit_ok") or rr.get("ok"))
            _orig_fill_seen = bool(rr.get("fill_confirmed")) or bool(_result_has_fill_evidence(rr))
            rr["ok"] = (True if bool(ok) else bool(_orig_submit_ok))
            rr["submit_ok"] = bool(_orig_submit_ok)
            rr["fill_confirmed"] = bool(_orig_fill_seen)
            rr["postcheck_ok"] = bool(ok)
            rr["postcheck_state"] = ("success" if bool(ok) else "fail")
            rr["postcheck_reason"] = str(reason or "")
            if detail is not None:
                rr["postcheck_detail"] = detail
            if bool(ok):
                rr["trade_effective"] = bool(_result_is_trade_effective(rr))
            else:
                rr["trade_effective"] = False
            rr = _result_apply_confirmation_fields(rr)
            _mark_nested_child_rows(rr)
            if isinstance(rr0, dict):
                rr0.clear()
                rr0.update(rr)
                out.append(rr0)
            else:
                out.append(rr)
        except Exception:
            if isinstance(rr0, dict):
                try:
                    _orig_submit_ok = bool(rr0.get("submit_ok") or rr0.get("ok"))
                    _orig_fill_seen = bool(rr0.get("fill_confirmed")) or bool(_result_has_fill_evidence(rr0))
                    rr0["ok"] = (True if bool(ok) else bool(_orig_submit_ok))
                    rr0["submit_ok"] = bool(_orig_submit_ok)
                    rr0["fill_confirmed"] = bool(_orig_fill_seen)
                    rr0["postcheck_ok"] = bool(ok)
                    rr0["postcheck_state"] = ("success" if bool(ok) else "fail")
                    rr0["postcheck_reason"] = str(reason or "")
                    if detail is not None:
                        rr0["postcheck_detail"] = detail
                    rr0["trade_effective"] = bool(rr0.get("ok")) and bool(_result_has_fill_evidence(rr0)) if bool(ok) else False
                    _result_apply_confirmation_fields(rr0)
                    _mark_nested_child_rows(rr0)
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_282', _e)
                    pass
                out.append(rr0)
    return out

def _exec_results_write_updates(exec_results: list, *, kind: str = "executor_result_update", when_ts: float | None = None, extra: dict | None = None) -> int:
    """把“复检后的最终结论”同步写回 executor_results.jsonl。
    人话：
    - 之前 submit 时会写一条 executor_result（可能还是 pending_confirm）
    - 这里把 postcheck_ok=True/False 的最终结论再写一条 update
    - 运行汇报/面板统计必须以“最新结论”为准，否则会出现：明明成交了却一直 pending_confirm/timeout。
    """
    try:
        rows = list(exec_results or [])
        if not rows:
            return 0
        nowv = float(when_ts if when_ts is not None else time.time())
        out_dir = str(globals().get("OUT_DIR") or "out")
        logs_dir = str(globals().get("LOGS_DIR") or "logs")
        fps = []
        try:
            fps.append(os.path.join(str(out_dir), "executor_results.jsonl"))
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_283', _e)
            pass
        try:
            fps.append(os.path.join(str(logs_dir), "executor_results.jsonl"))
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_284', _e)
            pass
        fps = [fp for fp in fps if fp]
        wrote = 0
        for rr0 in rows:
            if not isinstance(rr0, dict):
                continue
            rr = dict(rr0)
            try:
                rr = _result_apply_confirmation_fields(rr)
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_285', _e)
                pass
            try:
                req = rr.get("req") if isinstance(rr.get("req"), dict) else {}
                meta = req.get("meta") if isinstance(req.get("meta"), dict) else {}
                req_id = str(rr.get("req_id") or meta.get("req_id") or "").strip()
                trace_id = str(rr.get("trace_id") or meta.get("trace_id") or "").strip()
                order_id = str(rr.get("order_id") or rr.get("oid") or "").strip()
            except Exception:
                req_id = trace_id = order_id = ""
            if not (req_id or trace_id or order_id):
                continue
            rec = {
                "ts": nowv,
                "kind": str(kind or "executor_result_update"),
                "req_id": req_id or None,
                "trace_id": trace_id or None,
                "order_id": order_id or None,
                "module": str(rr.get("module") or (rr.get("req", {}) or {}).get("module") or ""),
                "action_type": str(rr.get("action_type") or (rr.get("req", {}) or {}).get("action_type") or (rr.get("req", {}) or {}).get("action") or ""),
                "coin": str(rr.get("coin") or (rr.get("req", {}) or {}).get("coin") or ""),
                "platform": str(rr.get("platform") or (rr.get("req", {}) or {}).get("platform") or ""),
                "side": str(rr.get("side") or (rr.get("req", {}) or {}).get("side") or ""),
                "ok": bool(rr.get("ok", False)),
                "submit_ok": bool(rr.get("submit_ok") or rr.get("ok")),
                "postcheck_ok": rr.get("postcheck_ok"),
                "postcheck_state": rr.get("postcheck_state"),
                "postcheck_reason": rr.get("postcheck_reason"),
                "postcheck_detail": rr.get("postcheck_detail"),
                "fill_confirmed": bool(rr.get("fill_confirmed")) if rr.get("fill_confirmed") is not None else None,
                "pending_confirm": bool(rr.get("pending_confirm")) if rr.get("pending_confirm") is not None else None,
                "status_label": str(rr.get("status_label") or ""),
                "confirmation_state": str(rr.get("confirmation_state") or ""),
            }
            if isinstance(extra, dict) and extra:
                try:
                    rec["extra"] = dict(extra)
                except Exception:
                    rec["extra"] = {"extra": str(extra)}
            for fp in fps:
                try:
                    os.makedirs(os.path.dirname(os.path.abspath(fp)) or ".", exist_ok=True)
                    with open(fp, "a", encoding="utf-8") as f:
                        f.write(_json_dumps_bot(rec) + "\n")
                    wrote += 1
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_286', _e)
                    pass
        return int(wrote)
    except Exception:
        return 0

def _result_amounts_unified(rr: dict) -> tuple[float | None, float | None, float | None]:
    """统一提取：计划金额 / 最终执行金额 / 展示金额。
    - 计划金额：优先认 meta 里未乘倍数前的计划值
    - 最终执行金额：优先认 exec/fill 后的真实金额
    - 展示金额：默认认最终执行金额；没有再回退计划金额
    """
    def _pick_nonempty(*vals):
        _zero = None
        for _v0 in vals:
            try:
                if _v0 is None or str(_v0) == "":
                    continue
                _v = float(_v0)
                if abs(_v) > 1e-9:
                    return _v
                if _zero is None:
                    _zero = _v
            except Exception:
                continue
        return _zero
    try:
        rr = rr if isinstance(rr, dict) else {}
        req = rr.get("req") if isinstance(rr.get("req"), dict) else {}
        meta = req.get("meta") if isinstance(req.get("meta"), dict) else {}
        params = req.get("params") if isinstance(req.get("params"), dict) else {}
        extras = meta.get("extras") if isinstance(meta.get("extras"), dict) else {}
        amt_det = meta.get("amt_det") if isinstance(meta.get("amt_det"), dict) else {}

        plan_u = _pick_nonempty(
            meta.get("amt_final_u"), meta.get("m1_std_amt_final"), extras.get("amount_u"), extras.get("usd"),
            amt_det.get("picked_before_multiplier"), amt_det.get("mapped_u"), amt_det.get("base_u"),
            params.get("add_notional_u"), params.get("close_notional_u"), req.get("intent_amount"), req.get("std_amount"),
            req.get("amount_u"), req.get("amount_usd"), req.get("notional_u")
        )
        final_u = _pick_nonempty(
            rr.get("filled_notional_u"), rr.get("exec_u"), rr.get("exec_notional_u"), rr.get("notional_u"),
            rr.get("amount_u"), rr.get("amount_usd"), rr.get("intent_notional_u"), meta.get("multiplier_applied_u"),
            amt_det.get("final_u"), req.get("amount_u"), req.get("amount_usd"), req.get("notional_u")
        )
        display_u = _pick_nonempty(final_u, plan_u)
        return plan_u, final_u, display_u
    except Exception:
        return None, None, None

def _canon_exec_result(rr0: dict) -> dict:
    """执行器回报 schema 固化（v5）：确保每条结果都可判案、可统计、可落账本。"""
    try:
        if not isinstance(rr0, dict):
            return rr0
        rr = dict(rr0)
        reqd = rr.get("req")
        if isinstance(reqd, Request):
            reqd = reqd.to_dict()
        if not isinstance(reqd, dict):
            reqd = {}
        try:
            reqd = _canon_req_dict(reqd, strip_unknown=False)
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_287', _e)
            pass
        rr["req"] = reqd

        meta = reqd.get("meta") if isinstance(reqd.get("meta"), dict) else {}
        tid = str(rr.get("trace_id") or reqd.get("trace_id") or meta.get("trace_id") or "").strip()
        if not tid:
            try:
                tid = str(_get_current_trace_id() or "").strip()
            except Exception:
                tid = ""
        if tid:
            rr["trace_id"] = tid

        rr.setdefault("module", str(reqd.get("module") or ""))
        rr.setdefault("coin", str(reqd.get("coin") or "").upper())
        rr.setdefault("platform", str(reqd.get("platform") or "").upper())
        rr.setdefault("action_type", str(reqd.get("action_type") or ""))

        if "exec_notional_u" not in rr:
            rr["exec_notional_u"] = float(rr.get("filled_notional_u") or rr.get("notional_u") or 0.0)
        _plan_u, _final_u, _display_u = _result_amounts_unified(rr)
        if _plan_u is not None:
            rr["plan_notional_u"] = float(_plan_u)
        if _final_u is not None:
            rr["final_exec_notional_u"] = float(_final_u)
            rr["exec_notional_u"] = float(_final_u)
        if _display_u is not None:
            rr["display_notional_u"] = float(_display_u)
        rr.setdefault("filled_qty", None)  # Request qty is not a fill receipt.
        rr.setdefault("filled_notional_u", float(rr.get("filled_notional_u") or 0.0))
        rr.setdefault("px", float(rr.get("px") or rr.get("avg_px") or rr.get("price") or 0.0))
        rr.setdefault("order_id", str(rr.get("order_id") or rr.get("oid") or ""))

        rr.setdefault("err", rr.get("err") if rr.get("err") is not None else "")
        rr.setdefault("detail", rr.get("detail") if rr.get("detail") is not None else "")
        rr.setdefault("reason", rr.get("reason") if rr.get("reason") is not None else "")

        rr.setdefault("t_sec", float(rr.get("t_sec") or 0.0))
        rr.setdefault("wait_sec", float(rr.get("wait_sec") or 0.0))
        rr.setdefault("total_sec", float(rr.get("total_sec") or 0.0))
        rr.setdefault("ts", float(rr.get("ts") or time.time()))
        rr.setdefault("submit_ok", bool(rr.get("ok")))
        rr.setdefault("fill_confirmed", bool(_result_has_fill_evidence(rr)))
        if "trade_effective" not in rr:
            rr["trade_effective"] = bool(_result_is_trade_effective(rr))
        rr = _result_apply_confirmation_fields(rr)
        return rr
    except Exception:
        return rr0

_TRACE_STATS: Dict[str, Dict[str, Any]] = {}

def _trace_stat_touch(trace_id: str) -> Dict[str, Any]:
    try:
        tid = str(trace_id or "")
        if not tid:
            return {}
        st = _TRACE_STATS.get(tid)
        if not isinstance(st, dict):
            st = {}
            _TRACE_STATS[tid] = st
        return st
    except Exception:
        return {}

def _trace_stat_update(trace_id: str, *, stage: str = "", ok: int | None = None, reason: str = "", step: str = "") -> None:
    try:
        tid = str(trace_id or "")
        if not tid:
            return
        st = _trace_stat_touch(tid)
        if not st:
            return
        now = time.time()
        st["last_ts"] = now
        if stage:
            st["last_stage"] = str(stage)
        if stage == "EXEC_EXEC_BEGIN":
            st["begin_ts"] = now
        if stage == "EXEC_EXEC_END":
            st["end_ts"] = now
            if ok is not None:
                st["end_ok"] = int(ok)
            if reason:
                st["end_reason"] = str(reason)[:240]

            try:
                _trace_pending_done(tid, status="EXEC_END", reason=str(reason or ""))
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_288', _e)
                pass
        if stage == "EXEC_STEP":
            if step:
                st["last_step"] = str(step)[:120]
            if ok is not None:
                st["last_step_ok"] = int(ok)
            if reason:
                st["last_step_reason"] = str(reason)[:240]
            if step and not st.get("first_step"):
                st["first_step"] = str(step)[:120]
            if ok is not None and int(ok) == 0 and step:
                if not st.get("fail_step"):
                    st["fail_step"] = str(step)[:120]
                    if reason:
                        st["fail_reason"] = str(reason)[:240]
                elif reason and not st.get("fail_reason"):
                    st["fail_reason"] = str(reason)[:240]
    except Exception:
        return

GRID_LEDGER_PATH = os.devnull  # 单账本版：彻底停用旧 local ledger 文件
GRID_LEDGER_LEGACY_FIX_LOG_PATH = _out_path("ledger_legacy_fix.jsonl")

class LocalGridLedger:
    """轻量本地网格账本（JSON 单文件）。记录每个“格子”的开仓成本与止盈目标，扫描命中则生成市价减仓请求。"""

    def __init__(self, path: str):
        self.path = str(path)
        self._lock = threading.Lock()
        self._data = {"version": 1, "ts": time.time(), "items": []}  # items: list[dict]
        self._loaded = False

    def _ensure_dir(self):
        try:
            d = os.path.dirname(self.path)
            if d:
                os.makedirs(d, exist_ok=True)
        except Exception as _e:
            _log_exc_level(mod="EXEC", stage="WAIT_BTN_LOOP_FAIL", level="C", e=_e)

    def _append_legacy_fix_log(self, rec: dict) -> None:
        try:
            fp = str(globals().get("GRID_LEDGER_LEGACY_FIX_LOG_PATH") or _out_path("ledger_legacy_fix.jsonl"))
            os.makedirs(os.path.dirname(fp) or ".", exist_ok=True)
            with open(fp, "a", encoding="utf-8") as f:
                f.write(json.dumps(rec or {}, ensure_ascii=False) + "\n")
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_289', _e)
            pass
    def _legacy_fix_loaded_items(self) -> bool:
        legacy_deleteded = False
        def _to_pos(v):
            try:
                if v is None:
                    return None
                fv = float(v)
                return float(fv) if fv > 0 else None
            except Exception:
                return None
        def _price_scale_ok(v, ref_px):
            try:
                vv = _to_pos(v)
                rr = _to_pos(ref_px)
                if vv is None:
                    return False
                if rr is None:
                    return True
                _ratio = max(float(vv), float(rr)) / max(min(float(vv), float(rr)), 1e-12)
                return bool(_ratio <= 50.0)
            except Exception:
                return False
        try:
            items = list((self._data or {}).get("items") or [])
        except Exception:
            items = []
        if not isinstance(items, list) or not items:
            return False
        groups: dict[str, list[tuple[int, dict]]] = {}
        for idx, it in enumerate(items):
            if not isinstance(it, dict):
                continue
            gid = str(it.get("grid_id") or "").strip()
            if not gid:
                continue
            st = str(it.get("state") or it.get("status") or "OPEN").upper().strip()
            if st not in ("OPEN", "ACTIVE", "CLOSE_PENDING", "CLOSED"):
                continue
            groups.setdefault(gid, []).append((idx, it))
        for gid, rows in groups.items():
            try:
                rows = sorted(rows, key=lambda x: (float((x[1] or {}).get("open_ts") or 0.0), x[0]))
            except Exception:
                rows = list(rows)
            next_no = 1
            seen_live: set[int] = set()
            for _, it in rows:
                if not isinstance(it, dict):
                    continue
                st = str(it.get("state") or it.get("status") or "OPEN").upper().strip()
                try:
                    old_no = it.get("layer_no")
                    if old_no is None:
                        old_no = _grid_layer_no(str(it.get("layer_id") or ""))
                    old_no = int(old_no) if old_no is not None else None
                except Exception:
                    old_no = None
                want_no = old_no
                if old_no is None or old_no <= 0:
                    want_no = next_no
                elif st in ("OPEN", "ACTIVE", "CLOSE_PENDING") and old_no in seen_live:
                    want_no = next_no
                elif old_no < next_no:
                    want_no = next_no
                if want_no is None or int(want_no) <= 0:
                    want_no = next_no
                want_no = int(want_no)
                old_layer_id = str(it.get("layer_id") or "").strip()
                want_layer_id = f"{gid}:{want_no}"
                want_layer_tag = f"L{want_no}"
                if old_no != want_no or old_layer_id != want_layer_id or str(it.get("layer_tag") or "") != want_layer_tag:
                    legacy_deleteded = True
                    meta = dict(it.get("meta") or {}) if isinstance(it.get("meta"), dict) else {}
                    meta.setdefault("layer_no_input", old_no)
                    meta.setdefault("layer_id_input", old_layer_id)
                    meta["layer_no"] = int(want_no)
                    meta["layer_id"] = str(want_layer_id)
                    meta["layer_tag"] = str(want_layer_tag)
                    meta["final_layer_no"] = int(want_no)
                    meta["final_layer_id"] = str(want_layer_id)
                    meta["ledger_legacy_deleteded_ts"] = float(time.time())
                    meta["ledger_recover_reason"] = "duplicate_or_invalid_layer_no"
                    it["layer_no"] = int(want_no)
                    it["layer_id"] = str(want_layer_id)
                    it["layer_tag"] = str(want_layer_tag)
                    it["meta"] = meta
                    self._append_legacy_fix_log({
                        "ts": time.time(),
                        "kind": "grid_layer_legacy_deleted",
                        "grid_id": gid,
                        "item_id": str(it.get("id") or ""),
                        "coin": str(it.get("coin") or ""),
                        "platform": str(it.get("platform") or ""),
                        "side": str(it.get("side") or ""),
                        "state": st,
                        "old_layer_no": old_no,
                        "new_layer_no": int(want_no),
                        "old_layer_id": old_layer_id,
                        "new_layer_id": str(want_layer_id),
                        "reason": "duplicate_or_invalid_layer_no",
                    })
                if st in ("OPEN", "ACTIVE", "CLOSE_PENDING"):
                    _meta_live = dict(it.get("meta") or {}) if isinstance(it.get("meta"), dict) else {}
                    _cur_open = _to_pos(it.get("open_ref_px") or it.get("layer_open_px") or it.get("entry_price") or _meta_live.get("open_ref_px") or _meta_live.get("layer_open_px") or _meta_live.get("entry_price"))
                    _pos_avg = _to_pos(it.get("position_avg_entry_px") or _meta_live.get("position_avg_entry_px"))
                    _mark_px = _to_pos(it.get("position_mark_px") or _meta_live.get("position_mark_px") or it.get("mark_px") or _meta_live.get("mark_px") or it.get("cur_px") or _meta_live.get("cur_px"))
                    _needs_scale_legacy_deleted = bool(_cur_open is not None and ((_pos_avg is not None and not _price_scale_ok(_cur_open, _pos_avg)) or (_mark_px is not None and not _price_scale_ok(_cur_open, _mark_px))))
                    if _needs_scale_legacy_deleted:
                        _legacy_deleted_px = None
                        _legacy_deleted_src = ''
                        if _pos_avg is not None and (_mark_px is None or _price_scale_ok(_pos_avg, _mark_px)):
                            _legacy_deleted_px = float(_pos_avg)
                            _legacy_deleted_src = 'pos_avg_legacy_deleted_loaded_item'
                        elif _mark_px is not None:
                            _legacy_deleted_px = float(_mark_px)
                            _legacy_deleted_src = 'mark_px_legacy_deleted_loaded_item'
                        if _legacy_deleted_px is not None and _legacy_deleted_px > 0:
                            legacy_deleteded = True
                            _old_open = _cur_open
                            it["entry_price"] = float(_legacy_deleted_px)
                            it["open_ref_px"] = float(_legacy_deleted_px)
                            it["layer_open_px"] = float(_legacy_deleted_px)
                            it["entry_price_source"] = str(_legacy_deleted_src)
                            it["layer_price_source"] = str(_legacy_deleted_src)
                            _meta_live["open_ref_px"] = float(_legacy_deleted_px)
                            _meta_live["layer_open_px"] = float(_legacy_deleted_px)
                            _meta_live["entry_price"] = float(_legacy_deleted_px)
                            _meta_live["entry_price_source"] = str(_legacy_deleted_src)
                            _meta_live["layer_price_source"] = str(_legacy_deleted_src)
                            _meta_live["ledger_legacy_deleteded_ts"] = float(time.time())
                            _meta_live["ledger_recover_reason"] = 'cross_scale_open_price_legacy_deleteded'
                            _meta_live["legacy_deleteded_from_open_px"] = float(_old_open) if _old_open is not None else None
                            _meta_live["legacy_deleteded_using_pos_avg_px"] = float(_pos_avg) if _pos_avg is not None else None
                            _meta_live["legacy_deleteded_using_mark_px"] = float(_mark_px) if _mark_px is not None else None
                            it["meta"] = _meta_live
                            self._append_legacy_fix_log({
                                "ts": time.time(),
                                "kind": "grid_open_price_scale_legacy_deleted",
                                "grid_id": gid,
                                "item_id": str(it.get("id") or ""),
                                "coin": str(it.get("coin") or ""),
                                "platform": str(it.get("platform") or ""),
                                "side": str(it.get("side") or ""),
                                "state": st,
                                "layer_id": str(it.get("layer_id") or ""),
                                "old_open_px": (float(_old_open) if _old_open is not None else None),
                                "new_open_px": float(_legacy_deleted_px),
                                "position_avg_entry_px": (float(_pos_avg) if _pos_avg is not None else None),
                                "position_mark_px": (float(_mark_px) if _mark_px is not None else None),
                                "reason": "cross_scale_open_price_legacy_deleteded",
                                "source": str(_legacy_deleted_src),
                            })
                    seen_live.add(int(want_no))
                    next_no = int(want_no) + 1
        return bool(legacy_deleteded)

    def load(self) -> None:
        with self._lock:
            if self._loaded:
                return
            self._ensure_dir()
            _need_legacy_deleted = False
            try:
                if os.path.exists(self.path):
                    try:
                        if os.path.getsize(self.path) <= 0:
                            raise ValueError("empty_ledger_file")
                    except Exception:
                        raise
                    self._data = safe_read_json(self.path, default={"version": 1, "ts": time.time(), "items": []}) or {"version": 1, "ts": time.time(), "items": []}
                    if not isinstance(self._data, dict):
                        raise ValueError("ledger_not_dict")
                else:
                    self._data = {"version": 1, "ts": time.time(), "items": []}
                    _need_legacy_deleted = True
            except Exception:
                self._data = {"version": 1, "ts": time.time(), "items": []}
                _need_legacy_deleted = True
            try:
                if not isinstance((self._data or {}).get("items"), list):
                    self._data["items"] = []
                    _need_legacy_deleted = True
            except Exception:
                self._data = {"version": 1, "ts": time.time(), "items": []}
                _need_legacy_deleted = True
            try:
                if self._legacy_fix_loaded_items():
                    _need_legacy_deleted = True
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_290', _e)
                pass
            if _need_legacy_deleted:
                try:
                    safe_write_json(self.path, self._data)
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_291', _e)
                    pass
            self._loaded = True

    def save(self) -> None:
        with self._lock:
            self._ensure_dir()
            try:
                self._data["ts"] = time.time()
                safe_write_json(self.path, self._data)
            except Exception as _e:
                _log_exc_level(mod="EXEC", stage="VAR_TOGGLE_STATE_FAIL", level="C", e=_e)

    def add_grid_item(
        self,
        *,
        coin: str,
        platform: str,
        side: str,
        amount_u: float,
        entry_price: float,
        tp_pct: float,
        source: str = "W1",
        meta: Optional[dict] = None,
        open_notional_u: Optional[float] = None,
        layer_open_px: Optional[float] = None,
        layer_request_px: Optional[float] = None,
        layer_fill_px: Optional[float] = None,
        position_avg_entry_px: Optional[float] = None,
        position_mark_px: Optional[float] = None,
        price_source: str = "legacy",
    ) -> str:
        """新增一个“格子”。side=LONG/SHORT（代表该平台该腿方向）。"""
        self.load()

        def _grid_truth_open_px_and_source(*, fill_px=None, pos_avg_px=None, req_px=None, fallback_px=None, mark_px=None, declared_source: str = "") -> tuple[float | None, str]:
            def _to_pos(v):
                try:
                    if v is None:
                        return None
                    fv = float(v)
                    return float(fv) if fv > 0 else None
                except Exception:
                    return None

            def _price_scale_ok(v, ref_px):
                try:
                    vv = _to_pos(v)
                    rr = _to_pos(ref_px)
                    if vv is None:
                        return False
                    if rr is None:
                        return True
                    _ratio = max(float(vv), float(rr)) / max(min(float(vv), float(rr)), 1e-12)
                    return bool(_ratio <= 50.0)
                except Exception:
                    return False

            _mark_px = _to_pos(mark_px)
            _pairs = [
                (fill_px, 'fill'),
                (pos_avg_px, 'pos_avg'),
                (req_px, 'request'),
                (fallback_px, str(declared_source or 'fallback')),
            ]
            _first_positive = None
            _first_positive_src = str(declared_source or 'missing')
            _scale_rejected = []
            for _v, _src in _pairs:
                _fv = _to_pos(_v)
                if _fv is None:
                    continue
                if _first_positive is None:
                    _first_positive = float(_fv)
                    _first_positive_src = str(_src or 'unknown')
                if _mark_px is not None and not _price_scale_ok(_fv, _mark_px):
                    _scale_rejected.append((float(_fv), str(_src or 'unknown')))
                    continue
                return float(_fv), str(_src or 'unknown')
            if _mark_px is not None and _scale_rejected:
                return None, 'scale_reject'
            if _first_positive is not None:
                return float(_first_positive), str(_first_positive_src or 'unknown')
            return None, str(declared_source or 'missing')

        def _grid_live_layer_no_for_grid(grid_id: str) -> int:
            _mx = -1
            try:
                for _it in (self.items or []):
                    if not isinstance(_it, dict):
                        continue
                    if str(_it.get("grid_id") or "").strip() != str(grid_id or "").strip():
                        continue
                    _st = str(_it.get("state") or _it.get("status") or "OPEN").upper().strip()
                    if _st not in ("OPEN", "ACTIVE", "CLOSE_PENDING"):
                        continue
                    try:
                        _n = _it.get("layer_no")
                        if _n is None:
                            _lid = str(_it.get("layer_id") or "").strip()
                            _n = _grid_layer_no(_lid)
                        if _n is None:
                            continue
                        _mx = max(_mx, int(_n))
                    except Exception:
                        continue
            except Exception:
                _mx = -1
            return int(_mx)
        try:
            _trace_id = ""
            if isinstance(meta, dict):
                _trace_id = str(meta.get("trace_id") or "")
            if _trace_id:
                with self._lock:
                    for it in (self._data.get("items") or []):
                        try:
                            _m = it.get("meta") if isinstance(it.get("meta"), dict) else {}
                            if (str(_m.get("trace_id") or "") == _trace_id and
                                    str(it.get("coin") or "").upper() == str(coin or "").upper() and
                                    str(it.get("platform") or "").upper() == str(platform or "").upper() and
                                    str(it.get("side") or "").upper() == str(side or "").upper() and
                                    str(it.get("state") or "") in ("OPEN", "CLOSE_PENDING")):
                                try: it["amount_u"] = float(amount_u)
                                except Exception as _e:
                                    _record_swallowed_exception("grid_ledger.amount_u_cast", _e, amount_u)
                                try:
                                    _layer_open_px = float(layer_open_px) if layer_open_px is not None else None
                                except Exception:
                                    _layer_open_px = None
                                try:
                                    _layer_request_px = float(layer_request_px) if layer_request_px is not None else None
                                except Exception:
                                    _layer_request_px = None
                                try:
                                    _layer_fill_px = float(layer_fill_px) if layer_fill_px is not None else None
                                except Exception:
                                    _layer_fill_px = None
                                try:
                                    _position_avg_entry_px = float(position_avg_entry_px) if position_avg_entry_px is not None else None
                                except Exception:
                                    _position_avg_entry_px = None
                                try:
                                    _position_mark_px = float(position_mark_px) if position_mark_px is not None else None
                                except Exception:
                                    _position_mark_px = None
                                _truth_open_px, _truth_price_source = _grid_truth_open_px_and_source(
                                    fill_px=_layer_fill_px,
                                    pos_avg_px=_position_avg_entry_px,
                                    req_px=_layer_request_px,
                                    fallback_px=entry_price,
                                    mark_px=_position_mark_px,
                                    declared_source=price_source,
                                )
                                try: it["entry_price"] = float(_truth_open_px) if _truth_open_px is not None else float(entry_price)
                                except Exception as _e:
                                    _record_swallowed_exception("grid_ledger.entry_price_cast", _e, f"truth={_truth_open_px}|entry={entry_price}")
                                try:
                                    if _truth_open_px is not None and float(_truth_open_px) > 0:
                                        it["open_ref_px"] = float(_truth_open_px)
                                        it["layer_open_px"] = float(_truth_open_px)
                                except Exception as _e:
                                    _record_swallowed_exception('except_pass_line_292', _e)
                                    pass
                                try:
                                    it["entry_price_source"] = str(_truth_price_source or price_source or "missing")
                                    it["layer_price_source"] = str(_truth_price_source or price_source or "missing")
                                except Exception as _e:
                                    _record_swallowed_exception('except_pass_line_293', _e)
                                    pass
                                try:
                                    if _layer_request_px is not None and float(_layer_request_px) > 0:
                                        it["layer_request_px"] = float(_layer_request_px)
                                except Exception as _e:
                                    _record_swallowed_exception('except_pass_line_294', _e)
                                    pass
                                try:
                                    if _layer_fill_px is not None and float(_layer_fill_px) > 0:
                                        it["layer_fill_px"] = float(_layer_fill_px)
                                except Exception as _e:
                                    _record_swallowed_exception('except_pass_line_295', _e)
                                    pass
                                try:
                                    if _position_avg_entry_px is not None and float(_position_avg_entry_px) > 0:
                                        it["position_avg_entry_px"] = float(_position_avg_entry_px)
                                except Exception as _e:
                                    _record_swallowed_exception('except_pass_line_296', _e)
                                    pass
                                try:
                                    if _position_mark_px is not None and float(_position_mark_px) > 0:
                                        it["position_mark_px"] = float(_position_mark_px)
                                except Exception as _e:
                                    _record_swallowed_exception('except_pass_line_297', _e)
                                    pass
                                try:
                                    if isinstance(_m, dict):
                                        _m["layer_price_source"] = str(_truth_price_source or price_source or "missing")
                                        _m["entry_price_source"] = str(_truth_price_source or price_source or "missing")
                                        if _layer_request_px is not None and float(_layer_request_px) > 0:
                                            _m["layer_request_px"] = float(_layer_request_px)
                                        if _layer_fill_px is not None and float(_layer_fill_px) > 0:
                                            _m["layer_fill_px"] = float(_layer_fill_px)
                                        if _position_avg_entry_px is not None and float(_position_avg_entry_px) > 0:
                                            _m["position_avg_entry_px"] = float(_position_avg_entry_px)
                                        if _position_mark_px is not None and float(_position_mark_px) > 0:
                                            _m["position_mark_px"] = float(_position_mark_px)
                                        it["meta"] = _m
                                except Exception as _e:
                                    _record_swallowed_exception('except_pass_line_298', _e)
                                    pass
                                try: it["tp_pct"] = float(tp_pct)
                                except Exception as _e:
                                    _record_swallowed_exception("grid_ledger.tp_pct_cast", _e, tp_pct)
                                try:
                                    _step_pct_meta = (_m.get("step_pct") if isinstance(_m, dict) else None)
                                    if _step_pct_meta is None and isinstance(_m, dict):
                                        _step_pct_meta = _m.get("grid_pct")
                                    if _step_pct_meta is not None and float(_step_pct_meta) > 0:
                                        it["step_pct"] = float(_step_pct_meta)
                                        it["grid_pct"] = float(_step_pct_meta)
                                except Exception as _e:
                                    _record_swallowed_exception('except_pass_line_299', _e)
                                    pass
                                try:
                                    it["step_source"] = str(((_m.get("step_source") if isinstance(_m, dict) else None) or (((_m.get("step_det") or {}).get("src")) if isinstance(_m, dict) and isinstance(_m.get("step_det"), dict) else "") or ""))
                                except Exception as _e:
                                    _record_swallowed_exception('except_pass_line_300', _e)
                                    pass
                                try:
                                    it["tp_source"] = str(((_m.get("tp_source") if isinstance(_m, dict) else None) or (((_m.get("tp_det") or {}).get("src")) if isinstance(_m, dict) and isinstance(_m.get("tp_det"), dict) else "") or ""))
                                except Exception as _e:
                                    _record_swallowed_exception('except_pass_line_301', _e)
                                    pass
                                try:
                                    if str(side or "").upper() == "LONG":
                                        it["tp_price"] = float(entry_price) * (1.0 + float(tp_pct))
                                    else:
                                        it["tp_price"] = float(entry_price) * (1.0 - float(tp_pct))
                                    it["tp_px"] = float(it.get("tp_price") or 0.0)
                                except Exception as _e:
                                    _record_swallowed_exception('except_pass_line_302', _e)
                                    pass
                                try:
                                    if open_notional_u is not None:
                                        it["open_notional_u"] = float(open_notional_u)
                                except Exception as _e:
                                    _record_swallowed_exception('except_pass_line_303', _e)
                                    pass
                                self.save()
                                return str(it.get("id"))
                        except Exception:
                            continue
        except Exception as _e:
            _log_exc_level(mod="EXEC", stage="VAR_TOGGLE_WAIT_FAIL", level="B", e=_e)

        gid = uuid.uuid4().hex
        coin = str(coin or "").upper()
        platform = str(platform or "").upper()
        side = str(side or "").upper()
        try:
            amount_u = float(amount_u)
        except Exception:
            amount_u = 0.0
        try:
            entry_price = float(entry_price)
        except Exception:
            entry_price = 0.0
        tp_pct = float(tp_pct or 0.0)
        try:
            layer_open_px = float(layer_open_px) if layer_open_px is not None else None
        except Exception:
            layer_open_px = None
        try:
            layer_request_px = float(layer_request_px) if layer_request_px is not None else None
        except Exception:
            layer_request_px = None
        try:
            layer_fill_px = float(layer_fill_px) if layer_fill_px is not None else None
        except Exception:
            layer_fill_px = None
        try:
            position_avg_entry_px = float(position_avg_entry_px) if position_avg_entry_px is not None else None
        except Exception:
            position_avg_entry_px = None
        try:
            position_mark_px = float(position_mark_px) if position_mark_px is not None else None
        except Exception:
            position_mark_px = None
        _truth_open_px, _truth_price_source = _grid_truth_open_px_and_source(
            fill_px=layer_fill_px,
            pos_avg_px=position_avg_entry_px,
            req_px=layer_request_px,
            fallback_px=entry_price,
            mark_px=position_mark_px,
            declared_source=price_source,
        )
        if _truth_open_px is not None and float(_truth_open_px) > 0:
            entry_price = float(_truth_open_px)
        tp_price = 0.0
        try:
            if entry_price > 0 and tp_pct > 0:
                if side == "LONG":
                    tp_price = entry_price * (1.0 + tp_pct)
                elif side == "SHORT":
                    tp_price = entry_price * (1.0 - tp_pct)
        except Exception:
            tp_price = 0.0

        _meta = dict(meta or {}) if isinstance(meta, dict) else {}
        _grid_id = str(_meta.get("grid_id") or gid).strip() or str(gid)
        _provided_layer_no = _meta.get("layer_no")
        _orig_layer_id = ""
        _orig_layer_no_from_id = None
        try:
            _orig_layer_id = str(_meta.get("layer_id") or "").strip()
        except Exception:
            _orig_layer_id = ""
        try:
            _orig_layer_no_from_id = _grid_layer_no(_orig_layer_id) if _orig_layer_id else None
        except Exception:
            _orig_layer_no_from_id = None
        if _provided_layer_no in (None, "") and _orig_layer_no_from_id is not None:
            _provided_layer_no = _orig_layer_no_from_id
        _live_max_layer_no = _grid_live_layer_no_for_grid(_grid_id)
        try:
            _provided_layer_no = int(_provided_layer_no) if _provided_layer_no is not None else None
        except Exception:
            _provided_layer_no = None
        try:
            if _live_max_layer_no >= 0:
                _layer_no = int(_live_max_layer_no + 1)
            elif _provided_layer_no is not None and int(_provided_layer_no) > 0:
                _layer_no = int(_provided_layer_no)
            else:
                _layer_no = 0
        except Exception:
            _layer_no = int(_provided_layer_no or 0)

        _layer_tag = f"L{int(_layer_no)}"
        _layer_id = f"{_grid_id}:{int(_layer_no)}"
        try:
            if _orig_layer_id and str(_grid_id or '').strip() and str(_orig_layer_id).startswith(f"{_grid_id}_") and (_orig_layer_no_from_id == int(_layer_no)):
                _layer_id = str(_orig_layer_id)
            elif _orig_layer_id and (_orig_layer_no_from_id == int(_layer_no)):
                _layer_id = str(_orig_layer_id)
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_304', _e)
            pass
        if _orig_layer_id and _orig_layer_id != _layer_id:
            _meta["layer_id_input"] = _orig_layer_id
            _meta["layer_no_input"] = _provided_layer_no
            _meta["layer_id_rewritten"] = True
        try:
            _meta["grid_id"] = str(_grid_id)
            _meta["layer_no"] = int(_layer_no)
            _meta["layer_tag"] = str(_layer_tag)
            _meta["layer_id"] = str(_layer_id)
            _meta["final_layer_no"] = int(_layer_no)
            _meta["final_layer_id"] = str(_layer_id)
            _meta["live_max_layer_no_before_open"] = (int(_live_max_layer_no) if _live_max_layer_no >= 0 else None)
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_305', _e)
            pass
        try:
            _meta["entry_price_source"] = str(_truth_price_source or price_source or "missing")
            _meta["layer_price_source"] = str(_truth_price_source or price_source or "missing")
            if layer_request_px is not None and float(layer_request_px) > 0:
                _meta["layer_request_px"] = float(layer_request_px)
            if layer_fill_px is not None and float(layer_fill_px) > 0:
                _meta["layer_fill_px"] = float(layer_fill_px)
            if position_avg_entry_px is not None and float(position_avg_entry_px) > 0:
                _meta["position_avg_entry_px"] = float(position_avg_entry_px)
            if position_mark_px is not None and float(position_mark_px) > 0:
                _meta["position_mark_px"] = float(position_mark_px)
            try:
                _step_pct_meta = _meta.get("step_pct")
                if _step_pct_meta is not None and float(_step_pct_meta) > 0:
                    _meta["step_pct"] = float(_step_pct_meta)
                    _meta.setdefault("grid_pct", float(_step_pct_meta))
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_306', _e)
                pass
            try:
                _meta["tp_pct"] = float(tp_pct)
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_307', _e)
                pass
            try:
                _meta["step_source"] = str((_meta.get("step_source") or ((_meta.get("step_det") or {}).get("src") if isinstance(_meta.get("step_det"), dict) else "") or ""))
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_308', _e)
                pass
            try:
                _meta["tp_source"] = str((_meta.get("tp_source") or ((_meta.get("tp_det") or {}).get("src") if isinstance(_meta.get("tp_det"), dict) else "") or ""))
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_309', _e)
                pass
            _meta["open_ref_px"] = float(entry_price) if float(entry_price) > 0 else None
            _meta["layer_open_px"] = float(entry_price) if float(entry_price) > 0 else None
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_310', _e)
            pass
        _open_ts_now = float(time.time())
        _meta, _layer_instance_id = _grid_prepare_layer_identity(_meta, _layer_id, allow_create=True, open_ts=_open_ts_now)
        if not _layer_instance_id:
            try:
                _legacy_trace = str(_meta.get("trace_id") or "").strip()
            except Exception:
                _legacy_trace = ""
            try:
                safe_log(lambda: f"[{now_ts()}] [LOCAL_GRID][LEGACY_INSTANCE_ID_MISS] coin={coin} plat={platform} side={side} grid_id={_grid_id} layer_id={_layer_id} trace_id={_legacy_trace} -> reject_write")
            except Exception as _e:
                _record_swallowed_exception('local_grid.legacy_instance_log', _e, _layer_id)
            raise RuntimeError(f"LOCAL_GRID_MISSING_LAYER_INSTANCE_ID:{_layer_id}")
        item = {
            "id": gid,
            "grid_id": _grid_id or gid,
            "layer_id": _layer_id,
            "layer_instance_id": _layer_instance_id,
            "instance_id": _layer_instance_id,
            "layer_tag": _layer_tag,
            "layer_no": _layer_no,
            "coin": coin,
            "platform": platform,
            "side": side,
            "amount_u": float(amount_u),
            "entry_price": float(entry_price),
            "open_ref_px": float(entry_price),
            "layer_open_px": float(entry_price),
            "layer_request_px": (float(layer_request_px) if layer_request_px is not None and float(layer_request_px) > 0 else None),
            "layer_fill_px": (float(layer_fill_px) if layer_fill_px is not None and float(layer_fill_px) > 0 else None),
            "layer_price_source": str(_truth_price_source or price_source or "missing"),
            "entry_price_source": str(_truth_price_source or price_source or "missing"),
            "position_avg_entry_px": (float(position_avg_entry_px) if position_avg_entry_px is not None and float(position_avg_entry_px) > 0 else None),
            "position_mark_px": (float(position_mark_px) if position_mark_px is not None and float(position_mark_px) > 0 else None),
            "step_pct": (_safe_float(_meta.get("step_pct"), None) if (_meta.get("step_pct") is not None) else _safe_float(_meta.get("grid_pct"), None)),
            "grid_pct": (_safe_float(_meta.get("grid_pct"), None) if (_meta.get("grid_pct") is not None) else _safe_float(_meta.get("step_pct"), None)),
            "step_source": str(_meta.get("step_source") or (((_meta.get("step_det") or {}).get("src")) if isinstance(_meta.get("step_det"), dict) else "") or ""),
            "tp_source": str(_meta.get("tp_source") or (((_meta.get("tp_det") or {}).get("src")) if isinstance(_meta.get("tp_det"), dict) else "") or ""),
            "tp_pct": float(tp_pct),
            "tp_price": float(tp_price),
            "tp_px": float(tp_price),
            "state": "OPEN",  # OPEN / CLOSE_PENDING / CLOSED
            "status": "OPEN",
            "open_ts": _open_ts_now,
            "close_ts": None,
            "close_reason": "",
            "close_price": None,
            "close_notional_u": None,
            "close_trigger_mark": None,
            "close_trace_id": "",
            "close_result_state": "",
            "close_pending_state": "",
            "close_pending": 0,
            "close_pending_req_id": "",
            "close_pending_trace_id": "",
            "close_pending_u": None,
            "close_pending_ts": None,
            "close_try": 0,
            "last_try_ts": 0.0,
            "source": str(source or ""),
            "open_notional_u": (float(open_notional_u) if open_notional_u is not None else None),
            "meta": _meta,
        }
        with self._lock:
            self._data.setdefault("items", [])
            self._data["items"].append(item)
        self.save()
        return gid

    def iter_open_items(self) -> List[dict]:
        self.load()
        with self._lock:
            items = list(self._data.get("items") or [])
        return [it for it in items if str(it.get("state")) in ("OPEN", "CLOSE_PENDING")]

    def clear_same_layer_old_instance_suspects(self, gid: str, layer_id: str, keep_instance_id: str) -> int:
        """新开同层号实例后，清理旧实例残留的 close/sync 怀疑态，防止旧关层链串到新实例。"""
        self.load()
        gid_s = str(gid or "").strip()
        lid_s = str(layer_id or "").strip()
        keep_iid = str(keep_instance_id or "").strip()
        if not gid_s or not lid_s or not keep_iid:
            return 0
        changed = 0
        with self._lock:
            for it in list(self._data.get("items") or []):
                try:
                    if str(it.get("id") or "").strip() != gid_s:
                        continue
                    if str(it.get("layer_id") or "").strip() != lid_s:
                        continue
                    iid = str(it.get("layer_instance_id") or it.get("instance_id") or "").strip()
                    if not iid or iid == keep_iid:
                        continue
                    dirty = False
                    for k, v in {
                        "close_suspect": False,
                        "close_suspect_reason": "",
                        "close_suspect_count": 0,
                        "close_suspect_first_ts": 0.0,
                        "close_suspect_last_ts": 0.0,
                        "sync_close_suspect": False,
                        "sync_close_suspect_reason": "",
                        "sync_close_first_ts": 0.0,
                        "sync_close_last_ts": 0.0,
                        "sync_close_count": 0,
                    }.items():
                        if it.get(k) != v:
                            it[k] = v
                            dirty = True
                    if dirty:
                        changed += 1
                        try:
                            self._local_grid_audit("clear_same_layer_old_instance_suspects", gid=gid_s, layer_id=lid_s,
                                                   old_instance_id=iid, keep_instance_id=keep_iid,
                                                   coin=str(it.get("coin") or ""), platform=str(it.get("platform") or ""), side=str(it.get("side") or ""))
                        except Exception:
                            pass
                except Exception:
                    continue
        if changed:
            self.save()
        return changed

    def clear_open_scope(self, *, coin: str = "", platform: str = "", side: str = "", reason: str = "") -> int:
        """全平后清空该腿所有开放层；单层利润已逐层落账，这里只负责把未关闭层收口。"""
        self.load()
        changed = 0
        c = str(coin or "").upper().strip()
        p = str(platform or "").upper().strip()
        s = str(side or "").upper().strip()
        with self._lock:
            items = list(self._data.get("items") or [])
            for it in items:
                try:
                    if not isinstance(it, dict):
                        continue
                    if c and str(it.get("coin") or "").upper().strip() != c:
                        continue
                    if p and str(it.get("platform") or "").upper().strip() != p:
                        continue
                    if s and str(it.get("side") or "").upper().strip() != s:
                        continue
                    st = str(it.get("state") or it.get("status") or "OPEN").upper().strip()
                    if st not in ("OPEN", "ACTIVE", "CLOSE_PENDING", "PENDING_CLOSE", "CLOSING"):
                        continue
                    if str(reason) == "notional_delta_exact_confirmed":
                        try:
                            self._local_grid_audit("grid_close_suspect_confirmed", gid=str(it.get("id") or ""), layer_id=str(it.get("layer_id") or ""), coin=coin, platform=plat, side=side, cur_notional=cur_notional, open_notional=open_notional_f, pending_u=pending_u, suspect_count=int(it.get("close_suspect_count") or 0))
                        except Exception as _e:
                            _record_swallowed_exception('except_pass_line_312', _e)
                            pass
                    it["state"] = "CLOSED"
                    it["status"] = "CLOSED"
                    if not it.get("close_ts"):
                        it["close_ts"] = time.time()
                    if not str(it.get("close_reason") or "").strip():
                        it["close_reason"] = str(reason or "flat_scope_reset")
                    it["close_pending"] = 0
                    it["close_pending_req_id"] = ""
                    it["close_pending_trace_id"] = ""
                    it["close_pending_u"] = None
                    changed += 1
                except Exception:
                    continue
        if changed:
            self.save()
            try:
                self._local_grid_audit("clear_open_scope", coin=c, platform=p, side=s, reason=str(reason or ""), changed=int(changed))
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_313', _e)
                pass
        return int(changed)

    def _local_grid_audit(self, event: str, **kwargs) -> None:
        try:
            payload = {"ts": time.time(), "event": str(event or "")}
            if kwargs:
                payload.update(kwargs)
            _log_jsonl(os.path.join("out", "local_grid_close_audit.jsonl"), payload)
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_314', _e)
            pass
    def _find_item_exact(self, gid: str, *, layer_id: Optional[str] = None, trace_id: Optional[str] = None) -> Optional[dict]:
        gid_s = str(gid or "").strip()
        lid_s = str(layer_id or "").strip()
        tid_s = str(trace_id or "").strip()
        if not gid_s:
            return None
        items = list(self._data.get("items") or [])
        exact = []
        fallback = []

        def _state_rank(v: object) -> int:
            s = str(v or "").upper().strip()
            if s == "OPEN":
                return 50
            if s == "CLOSE_PENDING":
                return 40
            if s in ("ACTIVE", "PENDING_CLOSE", "CLOSING"):
                return 30
            if s == "CLOSED":
                return 10
            return 0

        def _sort_key(it: dict):
            try:
                ots = float(it.get("open_ts") or 0.0)
            except Exception:
                ots = 0.0
            try:
                cts = float(it.get("close_ts") or 0.0)
            except Exception:
                cts = 0.0
            iid = str(it.get("layer_instance_id") or it.get("instance_id") or "")
            return (_state_rank(it.get("state") or it.get("status")), ots, cts, iid)

        for it in items:
            if not isinstance(it, dict):
                continue
            if str(it.get("id") or "").strip() != gid_s:
                continue
            fallback.append(it)
            it_lid = str(it.get("layer_id") or "").strip()
            it_tid = str(it.get("close_trace_id") or it.get("trace_id") or "").strip()
            if lid_s and it_lid and it_lid == lid_s:
                exact.append(it)
                continue
            if tid_s and it_tid and it_tid == tid_s:
                exact.append(it)
                continue
        if exact:
            return sorted(exact, key=_sort_key)[-1]
        if fallback:
            return sorted(fallback, key=_sort_key)[-1]
        return None

    def _rollback_close_pending_exact(self, gid: str, *, layer_id: Optional[str] = None, trace_id: Optional[str] = None, reason: str = "", rr: Optional[dict] = None) -> Optional[dict]:
        self.load()
        with self._lock:
            it = self._find_item_exact(gid, layer_id=layer_id, trace_id=trace_id)
            if not isinstance(it, dict):
                return None
            prev_state = str(it.get("state") or "")
            if prev_state == "CLOSE_PENDING":
                it["state"] = "OPEN"
                it["status"] = "OPEN"
            it["close_last_fail_ts"] = float(time.time())
            it["close_last_fail_reason"] = str(reason or (rr or {}).get("reason") or "")
            if isinstance(rr, dict):
                it["close_last_fail"] = rr
            self._local_grid_audit("rollback", gid=str(gid or ""), layer_id=str(layer_id or ""), trace_id=str(trace_id or ""), prev_state=prev_state, reason=str(reason or ""))
        self.save()
        return it

    def mark_closed(self, gid: str, *, layer_id: Optional[str] = None, trace_id: Optional[str] = None, reason: str = "", realized_u: Optional[float] = None, close_price: Optional[float] = None, close_notional_u: Optional[float] = None) -> None:
        self.load()
        with self._lock:
            it = self._find_item_exact(gid, layer_id=layer_id, trace_id=trace_id)
            if isinstance(it, dict):
                it["state"] = "CLOSED"
                it["status"] = "CLOSED"
                it["close_ts"] = time.time()
                it["close_reason"] = str(reason or "")
                if close_price is not None:
                    try:
                        it["close_price"] = float(close_price)
                    except Exception as _e:
                        _record_swallowed_exception('except_pass_line_315', _e)
                        pass
                if close_notional_u is not None:
                    try:
                        it["close_notional_u"] = float(close_notional_u)
                    except Exception as _e:
                        _record_swallowed_exception('except_pass_line_316', _e)
                        pass
                if realized_u is not None:
                    try:
                        it["realized_u"] = float(realized_u)
                    except Exception as _e:
                        _log_exc_level(mod="EXEC", stage="VAR_FLOW_PIN_FAIL", level="C", e=_e)
                self._local_grid_audit("mark_closed", gid=str(gid or ""), layer_id=str(layer_id or ""), trace_id=str(trace_id or ""), reason=str(reason or ""), close_price=close_price, close_notional_u=close_notional_u, realized_u=realized_u)
        self.save()

    def bump_close_pending(self, gid: str, *, trace_id: Optional[str] = None, trigger_mark: Optional[float] = None, trigger_ts: Optional[float] = None) -> None:
        """把格子标为 CLOSE_PENDING，并记录触发信息（用于后续核销/对账）。"""
        self.load()
        with self._lock:
            target = None
            items = list(self._data.get("items") or [])
            live = []
            fallback = []
            for it in items:
                if str(it.get("id")) != str(gid):
                    continue
                fallback.append(it)
                st = str(it.get("state") or it.get("status") or "").upper()
                if st in ("OPEN", "CLOSE_PENDING", "ACTIVE", "PENDING_CLOSE", "CLOSING"):
                    live.append(it)
            cand = live or fallback
            if cand:
                def _sort_key(it: dict):
                    st = str(it.get("state") or it.get("status") or "").upper()
                    rank = 3 if st == "OPEN" else (2 if st == "CLOSE_PENDING" else 1)
                    try:
                        ots = float(it.get("open_ts") or 0.0)
                    except Exception:
                        ots = 0.0
                    return (rank, ots, str(it.get("layer_instance_id") or it.get("instance_id") or ""))
                target = sorted(cand, key=_sort_key)[-1]
            if isinstance(target, dict):
                target["state"] = "CLOSE_PENDING"
                target["status"] = "CLOSE_PENDING"
                target["close_try"] = int(target.get("close_try") or 0) + 1
                target["last_try_ts"] = time.time()
                target["close_enq_ts"] = float(trigger_ts if trigger_ts is not None else time.time())
                if trace_id:
                    target["close_trace_id"] = str(trace_id)
                if trigger_mark is not None:
                    try:
                        target["close_trigger_mark"] = float(trigger_mark)
                    except Exception as _e:
                        _log_exc_level(mod="EXEC", stage="EXEC_CONFIRM_TS_SET_FAIL", level="C", e=_e)
        self.save()
    def _get_pos_from_snapshot(self, snap: dict, coin: str, platform: str) -> dict:
        """从扫描快照里取单腿持仓（dict），兼容 positions 的 dict/list 结构。"""
        try:
            return _snap_get_pos_any(snap if isinstance(snap, dict) else {}, platform, coin) or {}
        except Exception:
            return {}

    def _get_notional_u_from_snapshot(self, snap: dict, coin: str, platform: str) -> float:
        """从扫描快照中取名义价值U（兼容 positions 为 dict 或 list）。"""
        try:
            pos = self._get_pos_from_snapshot(snap, coin, platform) or {}
        except Exception:
            pos = {}
        try:
            nu = (
                pos.get("notional_u")
                or pos.get("notional_usd")
                or pos.get("notional")
                or pos.get("value_u")
                or pos.get("value_usd")
                or 0.0
            )
            return float(abs(float(nu or 0.0)))
        except Exception:
            return 0.0

    def on_exec_results(self, exec_results: list) -> None:
        """在执行器返回结果后，记录与本地网格相关的“已执行”信息（用于后续下一次扫描核销）。"""
        if not exec_results:
            return
        self.load()
        try:
            _cur_tid = str(_get_current_trace_id() or "").strip()
        except Exception:
            _cur_tid = ""
        now = time.time()
        with self._lock:
            for rr in (exec_results or []):
                try:
                    _ok = bool((rr or {}).get("ok"))
                    req = (rr or {}).get("req") or {}
                    mod = str(req.get("module") or "").upper()
                    act = str(req.get("action_type") or req.get("action") or "").lower()
                    meta = req.get("meta") if isinstance(req.get("meta"), dict) else {}
                    if mod == "M9" and act == "decrease" and str(meta.get("from") or "") == "LOCAL_GRID_TP":

                        try:
                            _gid0 = str(meta.get("grid_id") or "")
                            _tid0 = str(meta.get("trace_id") or req.get("_trace_id") or req.get("trace_id") or "")
                            _rsn0 = str((rr or {}).get("reason") or "")
                            _coin0 = str(req.get("coin") or "")
                            _plat0 = str(req.get("platform") or "")
                            _p0 = req.get("params") if isinstance(req.get("params"), dict) else {}
                            _amt0 = req.get("amount_usd") or req.get("notional_u") or _p0.get("amount_usd") or _p0.get("close_notional_u")
                            safe_log(lambda: f"[{now_ts()}] [GRID_TP][EXEC_RESULT] ok={1 if _ok else 0} coin={_coin0} plat={_plat0} gid={_gid0} trace={_tid0} amt_u={_fmt_float(_amt0)} reason={_rsn0}")
                        except Exception as _e:
                            _log_exc_level(mod="EXEC", stage="EXEC_CONFIRM_PIN_FAIL", level="C", e=_e)

                        gid = str(meta.get("grid_id") or "")
                        lid = str(meta.get("layer_id") or gid or "")
                        trace_id = str(meta.get("trace_id") or req.get("_trace_id") or req.get("trace_id") or "")
                        exec_u = rr.get("exec_u") or rr.get("notional_u") or req.get("amount_usd") or req.get("notional_u")
                        rr_state = str(_result_confirmation_state(rr) or "") if callable(globals().get("_result_confirmation_state")) else ""
                        try:
                            detail0 = rr.get("detail") if isinstance(rr.get("detail"), dict) else {}
                        except Exception:
                            detail0 = {}

                        if not _ok:
                            try:
                                self._rollback_close_pending_exact(gid, layer_id=lid, trace_id=trace_id, reason=str((rr or {}).get("reason") or "submit_fail"), rr=rr)
                            except Exception as _e:
                                _log_exc_level(mod="EXEC", stage="WAIT_BTN_ARIA_DISABLED_ATTR_FAIL", level="C", e=_e)
                            continue
                        if not gid:
                            continue
                        it = self._find_item_exact(gid, layer_id=lid, trace_id=trace_id)
                        if not isinstance(it, dict):
                            continue
                        it["close_exec_ok_ts"] = float(now)
                        it["close_exec_reason"] = str((rr or {}).get("reason") or "")
                        it["close_result_state"] = rr_state or "submitted_unchecked"
                        if trace_id:
                            it["close_trace_id"] = str(trace_id)
                        if exec_u is not None:
                            try:
                                it["close_exec_u"] = float(abs(float(exec_u)))
                            except Exception as _e:
                                _log_exc_level(mod="EXEC", stage="WAIT_BTN_INNER_LOOP_FAIL", level="C", e=_e)
                        try:
                            it["close_row_source"] = str((detail0 or {}).get("row_source") or "")
                            it["close_coin_page_available"] = int(bool((detail0 or {}).get("coin_page_available")))
                            it["close_coin_page_row_found"] = int(bool((detail0 or {}).get("coin_page_row_found")))
                            if (detail0 or {}).get("post_notional") is not None:
                                it["close_post_notional_u"] = float(abs(float((detail0 or {}).get("post_notional") or 0.0)))
                        except Exception as _e:
                            _record_swallowed_exception('except_pass_line_317', _e)
                            pass
                        self._local_grid_audit("exec_result", gid=gid, layer_id=lid, trace_id=trace_id, ok=1, confirmation_state=rr_state or "submitted_unchecked", exec_u=it.get("close_exec_u"), row_source=str(it.get("close_row_source") or ""))
                except Exception:
                    continue
        self.save()

    def reconcile_with_snapshot(self, snap: dict) -> int:
        """在每次扫描后调用：对 CLOSE_PENDING 的格子尝试核销为 CLOSED，并估算 realized_u。"""
        self.load()
        changed = 0
        now = time.time()
        with self._lock:
            for it in self._data.get("items") or []:
                try:
                    if str(it.get("state")) != "CLOSE_PENDING":
                        continue
                    coin = str(it.get("coin") or "").upper()
                    plat = str(it.get("platform") or "").upper()
                    side = str(it.get("side") or "").upper()
                    amt_u = float(it.get("amount_u") or 0.0)
                    entry = float(it.get("entry_price") or 0.0)
                    if amt_u <= 0 or entry <= 0:
                        continue

                    pos_row = self._get_pos_from_snapshot(snap or {}, coin, plat) or {}
                    cur_notional = self._get_notional_u_from_snapshot(snap or {}, coin, plat)
                    pos_side_now = str((pos_row or {}).get("side") or "").upper().strip()
                    open_notional = it.get("open_notional_u")
                    try:
                        open_notional_f = float(open_notional) if open_notional is not None else None
                    except Exception:
                        open_notional_f = None
                    try:
                        pending_u = float(it.get("close_exec_u") or it.get("close_pending_u") or amt_u)
                    except Exception:
                        pending_u = float(amt_u or 0.0)
                    pending_u = float(max(0.0, min(float(amt_u or 0.0), pending_u or 0.0))) if amt_u > 0 else float(max(0.0, pending_u or 0.0))
                    same_side_alive = bool(pos_side_now == side and cur_notional > 1.0)

                    closed_hit = False
                    reason = "pending_wait"
                    if cur_notional <= 1.0:
                        closed_hit = True
                        reason = "pos_gone"
                    elif same_side_alive and open_notional_f is not None and open_notional_f > 0 and pending_u > 0:
                        if cur_notional <= max(0.0, open_notional_f - 0.85 * pending_u):
                            sus_cnt = int(it.get("close_suspect_count") or 0) + 1
                            first_ts = float(it.get("close_suspect_first_ts") or now)
                            last_open_ts = float(it.get("open_ts") or it.get("opened_ts") or 0.0)
                            protect_sec = float(globals().get('GRID_NEW_LAYER_CLOSE_PROTECT_SEC', 480.0) or 480.0)
                            in_protect = bool(last_open_ts > 0 and (now - last_open_ts) < protect_sec)
                            it["close_suspect"] = True
                            it["close_suspect_reason"] = "notional_delta_exact"
                            it["close_suspect_count"] = int(sus_cnt)
                            it["close_suspect_first_ts"] = float(first_ts)
                            it["close_suspect_last_ts"] = float(now)
                            try:
                                self._local_grid_audit("grid_close_suspect", gid=str(it.get("id") or ""), layer_id=str(it.get("layer_id") or ""), coin=coin, platform=plat, side=side, cur_notional=cur_notional, open_notional=open_notional_f, pending_u=pending_u, suspect_count=sus_cnt, in_protect=in_protect)
                            except Exception as _e:
                                _record_swallowed_exception('except_pass_line_318', _e)
                                pass
                            if (not in_protect) and sus_cnt >= 3 and (now - first_ts) >= 15.0:
                                closed_hit = False
                                reason = "notional_delta_exact_confirmed_need_instance_match"
                            else:
                                closed_hit = False
                                reason = "notional_delta_exact_suspect"
                    elif (not same_side_alive) and pos_side_now and pos_side_now != side:
                        try:
                            if it.get("close_exec_ok_ts") and (now - float(it.get("close_exec_ok_ts") or 0.0)) >= 1.0:
                                closed_hit = True
                                reason = "side_flip_after_close"
                        except Exception:
                            closed_hit = False
                    else:
                        if it.get("close_exec_ok_ts") and (now - float(it.get("close_exec_ok_ts") or 0.0)) >= 8.0 and str(it.get("close_result_state") or "") in ("confirmed_success", "fill_seen_pending_confirm", "submitted_pending_confirm"):
                            closed_hit = True
                            reason = "exec_ok_timeout_close"

                    if not closed_hit:
                        if str(reason) != 'notional_delta_exact_suspect' and bool(it.get('close_suspect')):
                            try:
                                self._local_grid_audit("grid_close_suspect_cleared", gid=str(it.get("id") or ""), layer_id=str(it.get("layer_id") or ""), coin=coin, platform=plat, side=side, cur_notional=cur_notional)
                            except Exception as _e:
                                _record_swallowed_exception('except_pass_line_319', _e)
                                pass
                            it["close_suspect"] = False
                            it["close_suspect_reason"] = ""
                            it["close_suspect_count"] = 0
                            it["close_suspect_first_ts"] = 0.0
                            it["close_suspect_last_ts"] = 0.0
                        try:
                            self._local_grid_audit("pending_wait", gid=str(it.get("id") or ""), layer_id=str(it.get("layer_id") or ""), coin=coin, platform=plat, side=side, pos_side_now=pos_side_now, cur_notional=cur_notional, open_notional=open_notional_f, pending_u=pending_u, close_result_state=str(it.get("close_result_state") or ""), close_reason=str(reason or ""))
                        except Exception as _e:
                            _record_swallowed_exception('except_pass_line_320', _e)
                            pass
                        continue

                    close_px = self._get_mark_price_from_snapshot(snap or {}, coin, plat)
                    try:
                        if (close_px is None) or (isinstance(close_px, float) and math.isnan(close_px)):
                            close_px = float('nan')
                    except Exception:
                        close_px = float('nan')
                    if (not isinstance(close_px, float)) or (isinstance(close_px, float) and math.isnan(close_px)) or (close_px <= 0):
                        close_px = float(it.get("close_trigger_mark") or 0.0) or close_px

                    qty = amt_u / entry if entry > 0 else 0.0
                    realized = None
                    if qty > 0 and close_px > 0:
                        if side == "LONG":
                            realized = (close_px - entry) * qty
                        elif side == "SHORT":
                            realized = (entry - close_px) * qty

                    it["state"] = "CLOSED"
                    it["status"] = "CLOSED"
                    it["close_ts"] = float(now)
                    it["close_price"] = float(close_px) if close_px > 0 else None
                    it["close_notional_u"] = float(cur_notional)
                    it["close_reason"] = str(reason)
                    if realized is not None:
                        it["realized_u_est"] = float(realized)
                    try:
                        self._local_grid_audit("reconcile_closed", gid=str(it.get("id") or ""), layer_id=str(it.get("layer_id") or ""), coin=coin, platform=plat, side=side, reason=str(reason), cur_notional=float(cur_notional), close_price=(float(close_px) if close_px and close_px > 0 else None), realized_u_est=(float(realized) if realized is not None else None))
                    except Exception as _e:
                        _record_swallowed_exception('except_pass_line_321', _e)
                        pass
                    changed += 1
                except Exception:
                    continue
        if changed:
            self.save()
        return changed

    def reconcile_dual_ledger_consistency(self, snap: dict) -> int:
        """方案A：主账本单真相源。
        local ledger 仅作展示/审计缓存，不再与 GRID_BOOK 做双向一致性修正，
        避免旧账本反向改写主账本或因为 instance_id 不一致触发误同步。
        保留该方法仅为了兼容旧调用点。
        """
        return 0

    def ensure_open_from_snapshot(self, snap: dict, *, tp_pct_default: float = 0.01) -> int:
        """系统性修复：当存在真实仓位但本地账本没有任何 OPEN 格子时，自动补 1 个 OPEN 格子（仅写账本，不下单）。
        触发条件（幂等）：
        - (coin, platform, side) 在账本中 OPEN/CLOSE_PENDING=0
        - snapshot 中该腿 notional_u > 0
        """
        added = 0
        try:
            self.load()
        except Exception as _e:
            _log_exc_level(mod="EXEC", stage="WAIT_BTN_OUTER_LOOP_FAIL", level="C", e=_e)

        def _leg_key(it: dict):
            return (str(it.get("coin") or "").upper(),
                    str(it.get("platform") or it.get("plat") or "").upper(),
                    str(it.get("side") or "").upper())

        exist_open = {}
        try:
            for it in list(self._data.get("items") or []):
                st = str(it.get("status") or "").upper()
                if st not in ("OPEN", "CLOSE_PENDING"):
                    continue
                k = _leg_key(it)
                exist_open[k] = exist_open.get(k, 0) + 1
        except Exception as _e:
            _log_exc_level(mod="EXEC", stage="WAIT_BTN_HEARTBEAT_LOG_FAIL", level="C", e=_e)

        positions = (snap or {}).get("positions") or {}
        def _iter_legs():
            if isinstance(positions, dict):
                for coin, vv in positions.items():
                    cu = str(coin or "").upper()
                    if isinstance(vv, dict) and ("EXT" in vv or "VAR" in vv or "ext" in vv or "var" in vv):
                        for plat in ("EXT","VAR","ext","var"):
                            if plat in vv:
                                yield cu, str(plat).upper(), vv.get(plat)
                    else:
                        yield cu, "UNKNOWN", vv

        nowt = time.time()
        for coin_u, plat_u, leg in _iter_legs():
            try:
                if not isinstance(leg, dict):
                    continue
                side = str(leg.get("side") or leg.get("position_side") or "").upper()
                if side not in ("LONG","SHORT"):
                    continue
                nu = leg.get("notional_u")
                if nu is None:
                    nu = leg.get("value_u")
                if nu is None:
                    nu = leg.get("notional")
                try:
                    nu = float(nu or 0.0)
                except Exception:
                    nu = 0.0
                if nu <= 0.0:
                    continue

                key = (coin_u, plat_u, side)
                if exist_open.get(key, 0) > 0:
                    continue

                entry = leg.get("entry") or leg.get("entry_px") or leg.get("entry_price")
                mark = leg.get("mark") or leg.get("mark_px") or leg.get("price")
                try:
                    entry = float(entry) if entry is not None else None
                except Exception:
                    entry = None
                try:
                    mark = float(mark) if mark is not None else None
                except Exception:
                    mark = None

                ref_px = entry if entry is not None else mark
                if ref_px is None:
                    ref_px = 0.0

                try:
                    _tp_floor, _tp_det = _grid_live_tp_pct(str(coin_u), fallback=float(tp_pct_default))
                except Exception:
                    _tp_floor, _tp_det = float(tp_pct_default), {'src': 'local_grid_tp_floor_exc'}
                try:
                    _tp_cfg = float(cfg_getf('LOCAL_GRID_TP_PCT', _tp_floor))
                except Exception:
                    _tp_cfg = float(_tp_floor)
                tp_pct = float(max(_tp_cfg, _tp_floor))

                lid = f"RECOV_{int(nowt)}_{coin_u}_{plat_u}_{side}"
                item = {
                    "gid": f"{coin_u}_{plat_u}_{side}_RECOV",
                    "coin": coin_u,
                    "platform": plat_u,
                    "side": side,
                    "layer_id": lid,
                    "open_u": float(nu),
                    "open_ref_px": float(ref_px),
                    "tp_pct": float(tp_pct),
                    "open_ts": float(nowt),
                    "status": "OPEN",
                    "note": "RECOVER_FROM_SNAPSHOT",
                }
                with self._lock:
                    self._data.setdefault("items", []).append(item)
                    self._data["ts"] = time.time()
                exist_open[key] = 1
                added += 1
                try:
                    safe_log(lambda: f"[{now_ts()}] [LOCAL_GRID][RECOVER] coin={coin_u} plat={plat_u} side={side} "
                                     f"open_u={float(nu):.2f} ref_px={float(ref_px):.6f} tp_pct={float(tp_pct):.4f} layer_id={lid}")
                except Exception as _e:
                    _log_exc_level(mod="EXEC", stage="WAIT_BTN_SLEEP_FAIL", level="C", e=_e)
            except Exception as _e:
                _log_exc_level(mod="EXEC", stage="VAR_FLOW_PIN_FAIL", level="C", e=_e)

        if added:
            try:
                self.save()
            except Exception as _e:
                _log_exc_level(mod="EXEC", stage="VAR_TOGGLE_STATE_FAIL", level="C", e=_e)
            try:
                safe_log(lambda: f"[{now_ts()}] [LOCAL_GRID][RECOVER_SUM] added={added}")
            except Exception as _e:
                _log_exc_level(mod="EXEC", stage="VAR_TOGGLE_WAIT_FAIL", level="B", e=_e)
        return int(added)

    def _get_mark_price_from_snapshot(self, snap: dict, coin: str, platform: str, side: str = "") -> float:
        """从扫描快照中取 mark；TP 当前价只认真实持仓 Mark 真相源。"""
        c0 = str(coin or '').upper().strip()
        p0 = str(platform or '').upper().strip()
        s0 = str(side or '').upper().strip()

        def _pick_mark(row: dict, src: str) -> float | None:
            try:
                mp = (row.get('mark') or row.get('mark_px') or row.get('mark_price') or row.get('last_px') or row.get('last') or row.get('px') or row.get('cur_px') or row.get('price'))
                if mp in (None, '', 0, 0.0):
                    return None
                mpf = float(mp)
                if math.isfinite(mpf) and mpf > 0:
                    _grid_tp_mark_info_set(c0, p0, s0, mark=mpf, source=src, reason='')
                    return float(mpf)
            except Exception:
                return None
            return None

        try:
            pos = _snap_get_pos_any(snap if isinstance(snap, dict) else {}, p0, c0, s0) or {}
        except Exception:
            pos = {}
        mp0 = _pick_mark(pos if isinstance(pos, dict) else {}, 'snapshot_position')
        if mp0 is not None:
            return float(mp0)

        try:
            _sm = _get_last_snapshot_metric(c0, p0) if '_get_last_snapshot_metric' in globals() else {}
        except Exception:
            _sm = {}
        try:
            mp2 = safe_float((_sm or {}).get('mark'), default=None)
        except Exception:
            mp2 = None
        if mp2 is not None and float(mp2) > 0:
            _grid_tp_mark_info_set(c0, p0, s0, mark=mp2, source='last_snapshot_metric', reason='')
            return float(mp2)

        try:
            _disk = _load_positions_from_disk_fallback() if '_load_positions_from_disk_fallback' in globals() else {}
        except Exception:
            _disk = {}
        try:
            if isinstance(_disk, dict):
                if isinstance(_disk.get('positions'), (dict, list)):
                    _wrap = {'positions': _disk.get('positions')}
                else:
                    _wrap = _disk
            else:
                _wrap = {}
            _row = _snap_get_pos_any(_wrap, p0, c0, s0) if isinstance(_wrap, dict) else {}
            mp3 = _pick_mark(_row if isinstance(_row, dict) else {}, 'positions_disk')
            if mp3 is not None:
                return float(mp3)
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_326', _e)
            pass
        _grid_tp_mark_info_set(c0, p0, s0, mark=None, source='missing', reason='snapshot_and_positions_missing_mark')
        return float('nan')

    def _m9_owner_meta_from_item(self, it: dict) -> dict:
        """把本地账本项映射成 M9 所有权校验使用的正式 grid_id/layer_id。"""
        meta = dict(it.get("meta") or {}) if isinstance(it.get("meta"), dict) else {}
        coin = str(it.get("coin") or "").upper()
        plat = str(it.get("platform") or "").upper()
        side = str(it.get("side") or "").upper()
        gid = str(it.get("grid_id") or meta.get("grid_id") or '').strip()
        if not gid and coin and plat and side:
            gid = _m9_grid_id(coin, plat, side)
        layer_no = it.get("layer_no") if it.get("layer_no") not in (None, '', 0) else meta.get("layer_no")
        lid_raw = str(it.get("layer_id") or meta.get("layer_id") or it.get("id") or '').strip()
        lid = _grid_canonical_layer_id(gid, layer_no, lid_raw) if gid else lid_raw
        return {
            "grid_id": str(gid or ''),
            "layer_id": str(lid or ''),
            "layer_no": int(layer_no or (_grid_layer_no(lid) or 0) or 0),
            "local_item_id": str(it.get("id") or ''),
            "local_grid_id": f"LOCALGRID-{coin}-{plat}-{side}",
        }

    def scan_and_build_tp_requests(self, snap: dict) -> List[dict]:
        """根据快照扫描本地账本，命中止盈则生成“市价减仓”请求（M9 decrease），由调用方入队执行。"""
        reqs: List[dict] = []
        now = time.time()
        for it in self.iter_open_items():
            gid = str(it.get("id"))
            coin = str(it.get("coin") or "").upper()
            plat = str(it.get("platform") or "").upper()
            try:
                _cache_last_snapshot_metric(snap, coin, plat)
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_327', _e)
                pass
            side = str(it.get("side") or "").upper()
            _owner_meta = self._m9_owner_meta_from_item(it if isinstance(it, dict) else {})
            grid_id = str(_owner_meta.get("grid_id") or "")
            owner_layer_id = str(_owner_meta.get("layer_id") or "")
            local_item_id = str(_owner_meta.get("local_item_id") or gid)
            amt = float(it.get("amount_u") or 0.0)
            entry = float(it.get("entry_price") or 0.0)
            tp_price = float(it.get("tp_price") or 0.0)
            st = str(it.get("state") or "OPEN")
            last_try = float(it.get("last_try_ts") or 0.0)
            try_n = int(it.get("close_try") or 0)
            if try_n <= 0:
                cd = 0.0
            elif try_n == 1:
                cd = 5.0
            elif try_n == 2:
                cd = 15.0
            elif try_n == 3:
                cd = 30.0
            else:
                cd = 60.0
            if cd > 0 and (now - last_try) < cd:
                try:
                    _tp_flow_inc(coin, "COOLDOWN", stage="SCAN")
                except Exception as _e:
                    _log_exc(mod="SYS", stage="EXC_PASS", e=_e)
                continue

            mark = self._get_mark_price_from_snapshot(snap, coin, plat, side)
            _mark_info = _grid_tp_mark_info_get(coin, plat, side)
            try:
                if (mark is None) or (isinstance(mark, float) and math.isnan(mark)):
                    raise ValueError('mark_nan')
            except Exception:
                try:
                    _tp_flow_inc(coin, "DATA_INVALID", stage="SCAN")
                except Exception as _e:
                    _log_exc(mod="SYS", stage="EXC_PASS", e=_e)
                try:
                    _grid_tp_mark_diag_update(coin, plat, side, ok=False, mark=None, source=str((_mark_info or {}).get('source') or 'missing'), reason=str((_mark_info or {}).get('reason') or 'mark_nan'), layer_id=gid)
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_328', _e)
                    pass
                continue
            if mark <= 0 or tp_price <= 0 or entry <= 0 or amt <= 0:
                try:
                    _tp_flow_inc(coin, "DATA_INVALID", stage="SCAN")
                except Exception as _e:
                    _log_exc(mod="SYS", stage="EXC_PASS", e=_e)
                try:
                    _grid_tp_mark_diag_update(coin, plat, side, ok=False, mark=mark, source=str((_mark_info or {}).get('source') or 'invalid'), reason='non_positive_mark_or_tp', layer_id=gid)
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_329', _e)
                    pass
                continue
            try:
                _grid_tp_mark_diag_update(coin, plat, side, ok=True, mark=mark, source=str((_mark_info or {}).get('source') or 'snapshot_position'), reason='', layer_id=gid)
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_330', _e)
                pass
            hit = False
            if side == "LONG":
                hit = (mark >= tp_price)
            elif side == "SHORT":
                hit = (mark <= tp_price)

            if not hit:
                try:
                    _tp_flow_inc(coin, "NO_HIT", stage="SCAN")
                except Exception as _e:
                    _log_exc(mod="SYS", stage="EXC_PASS", e=_e)
                continue

            try:
                _tp_flow_inc(coin, "HIT", stage="SCAN")
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

            try:
                safe_log(lambda: f"[{now_ts()}] [GRID_TP][TP_TRIGGER] coin={coin} plat={plat} side={side} gid={gid} mark={_fmt_float(mark)} mark_src={str((_mark_info or {}).get('source') or '')} tp={_fmt_float(tp_price)} entry={_fmt_float(entry)} amt_u={_fmt_float(amt)}")
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

            try:
                _tp_emit_event("TP_TRIGGER", coin=coin, platform=plat, trace_id=str(it.get("trace_id") or ""), detail={"gid": gid, "side": side, "mark": float(mark), "tp_price": float(tp_price), "entry": float(entry), "amt_u": float(amt)})
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

            sell_qty = 0.0
            sell_u = float(amt)
            try:
                if entry > 0 and mark > 0:
                    sell_qty = float(amt) / float(entry)   # qty（币数量）
                    sell_u_raw = float(sell_qty) * float(mark)  # 当前价换算的名义(U)
                    sell_u = float(_m9_norm_u_tens(sell_u_raw, 10.0, max(10.0, sell_u_raw)))
            except Exception:
                sell_qty = 0.0
                sell_u = float(amt)

            try:
                _pos = (((snap or {}).get("positions") or {}).get(plat) or {}).get(coin) or {}
                pos_side = str(_pos.get("side") or "").upper()
            except Exception:
                pos_side = ""
            try:
                cur_notional = float(self._get_notional_u_from_snapshot(snap, coin, plat))
            except Exception:
                cur_notional = 0.0
            if pos_side and pos_side != side:
                try:
                    self._local_grid_audit("tp_skip_side_mismatch", gid=gid, layer_id=str(it.get("layer_id") or gid), coin=coin, platform=plat, ledger_side=side, pos_side=pos_side, cur_notional=float(cur_notional))
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_331', _e)
                    pass
                try:
                    _tp_flow_inc(coin, "SIDE_MISMATCH", stage="SCAN")
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_332', _e)
                    pass
                continue
            if cur_notional > 0 and mark > 0:
                cap_u = min(float(cur_notional) * 0.98, float(max(0.0, amt)))
                sell_u_before = float(sell_u)
                if sell_u_before > cap_u:
                    sell_u = float(_m9_norm_u_tens(cap_u, 10.0, max(10.0, cap_u)))
                    try:
                        sell_qty_cap = float(sell_u) / float(mark)
                    except Exception:
                        sell_qty_cap = 0.0
                    if sell_qty_cap > 0:
                        sell_qty = float(sell_qty_cap)
                    try:
                        safe_log(lambda: f"[{now_ts()}] [GRID_TP][DECREASE_CAP] gid={gid} side={side} pos_side={pos_side} sell_u_before={_fmt_float(sell_u_before)} cap_u={_fmt_float(cap_u)} cur_notional={_fmt_float(cur_notional)} sell_u_after={_fmt_float(sell_u)} sell_qty_after={_fmt_float(sell_qty)}")
                    except Exception as _e:
                        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)
            try:
                if sell_u <= 0:
                    self._local_grid_audit("tp_skip_zero_sell", gid=gid, layer_id=str(it.get("layer_id") or gid), coin=coin, platform=plat, sell_u=float(sell_u), cur_notional=float(cur_notional))
                    continue
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_333', _e)
                pass
            try:
                safe_log(lambda: f"[{now_ts()}] [GRID_TP][DECREASE_BUILD] coin={coin} plat={plat} side={side} gid={gid} sell_qty={_fmt_float(sell_qty,6)} sell_u={_fmt_float(sell_u)} entry={_fmt_float(entry)} mark={_fmt_float(mark)} mark_src={str((_mark_info or {}).get('source') or '')}")
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

            _layer_no_tp = int(_grid_layer_no(owner_layer_id) or _grid_layer_no(str(it.get("layer_id") or "")) or _grid_layer_no(str(it.get("id") or "")) or 0)
            _layer_tag_tp = str(_grid_layer_tag(owner_layer_id) or _grid_layer_tag(str(it.get("layer_id") or "")) or "")
            _grid_layer_payload = {
                "grid_id": str(grid_id or ""),
                "layer_id": str(owner_layer_id or ""),
                "layer_tag": str(_layer_tag_tp or ""),
                "layer_no": int(_layer_no_tp or 0),
                "source": "M9_SELF_OPEN",
                "managed_by_grid": True,
                "can_tp_close": True,
                "layer_role": "GRID_LAYER",
                "platform": plat,
                "side": side,
                "state": str(st or ""),
                "entry_price": float(entry),
                "tp_price": float(tp_price),
                "tp_pct": float(it.get("tp_pct") or 0.0),
                "amount_u": float(amt),
                "local_item_id": str(local_item_id or gid),
                "local_grid_id": str(_owner_meta.get("local_grid_id") or ""),
            }
            req = {
                "module": "M9",
                "submodule": "TP_LOCAL",
                "coin": coin,
                "platform": plat,
                "side": side,
                "action_type": "decrease",
                "action": "decrease",
                "grid_id": str(grid_id or ""),
                "layer_id": str(owner_layer_id or ""),
                "layer_tag": str(_layer_tag_tp or ""),
                "layer_no": int(_layer_no_tp or 0),
                "grid_layer": dict(_grid_layer_payload),
                "amount_usd": float(sell_u),
                "notional_u": float(sell_u),
                "params": {"amount_usd": float(sell_u), "close_notional_u": float(sell_u), "notional_u": float(sell_u), "platform": plat, "side": side, "grid_id": str(grid_id or ""), "layer_id": str(owner_layer_id or ""), "layer_tag": str(_layer_tag_tp or ""), "layer_no": int(_layer_no_tp or 0), "grid_layer": dict(_grid_layer_payload)},

                "meta": {
                    "from": "LOCAL_GRID_TP",
                    "source": "M9_SELF_OPEN",
                    "managed_by_grid": True,
                    "can_tp_close": True,
                    "layer_role": "GRID_LAYER",
                    "grid_id": str(grid_id or ""),
                    "layer_id": str(owner_layer_id or ""),
                    "layer_tag": str(_layer_tag_tp or ""),
                    "layer_no": int(_layer_no_tp or 0),
                    "grid_layer": dict(_grid_layer_payload),
                    "local_item_id": str(local_item_id or gid),
                    "local_grid_id": str(_owner_meta.get("local_grid_id") or ""),
                    "entry_price": float(entry),
                    "tp_price": float(tp_price),
                    "tp_pct": float(it.get("tp_pct") or 0.0),
                    "mark": float(mark),
                    "mark_source": str((_mark_info or {}).get("source") or ""),
                    "trigger_mark": float(mark),
                    "sell_qty": float(sell_qty),
                    "sell_u": float(sell_u),
                    "state": st,
                },
            }
            reqs.append(req)
            try:
                _tid = f"GRIDTP-{uuid.uuid4().hex[:10]}"
            except Exception:
                _tid = "GRIDTP"
            try:
                if isinstance(req.get('meta'), dict):
                    req['meta'].setdefault('trace_id', _tid)
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

            req.setdefault('trace_id', _tid)
            self.bump_close_pending(local_item_id or gid, trace_id=_tid, trigger_mark=float(mark), trigger_ts=time.time())

        return reqs

class _DisabledLocalGridLedger:
    """单账本版：彻底停用旧 local ledger。
    保留最小兼容接口，避免历史调用点炸掉；默认不读、不写、不参与任何判案。
    """
    def __init__(self):
        self.path = os.devnull
        self._lock = threading.Lock()
        self._data = {"version": 0, "ts": time.time(), "items": []}
        self._loaded = True
    def load(self):
        return None
    def save(self):
        return None
    def iter_open_items(self):
        return []
    def on_exec_results(self, rows):
        return 0
    def reconcile_with_snapshot(self, snap=None):
        return 0
    def reconcile_dual_ledger_consistency(self, snap=None):
        return 0
    def ensure_open_from_snapshot(self, snap=None, **kwargs):
        return 0
    def scan_and_build_tp_requests(self, snap=None):
        return []
    def _rollback_close_pending_exact(self, *args, **kwargs):
        return False
    def add_grid_item(self, *args, **kwargs):
        return ''
    def clear_open_scope(self, *args, **kwargs):
        return 0
    def clear_same_layer_old_instance_suspects(self, *args, **kwargs):
        return 0
    def force_flat_scope(self, *args, **kwargs):
        return 0
    def _get_mark_price_from_snapshot(self, *args, **kwargs):
        return float('nan')
    def _get_notional_u_from_snapshot(self, *args, **kwargs):
        return 0.0
    def __getattr__(self, name):
        def _noop(*args, **kwargs):
            return 0
        return _noop

_GRID_LEDGER = _DisabledLocalGridLedger()

try:
    if 'LocalGridLedger' in globals() and callable(globals().get('ensure_open_from_snapshot')):
        if not hasattr(LocalGridLedger, 'ensure_open_from_snapshot'):
            LocalGridLedger.ensure_open_from_snapshot = ensure_open_from_snapshot  # type: ignore
except Exception as _e:
    _log_exc(mod='SYS', stage='EXC_PASS', e=_e)

def ensure_open_from_snapshot(self, snap: dict, *, tp_pct_default: float = 0.01) -> int:
    """系统性修复：当存在真实仓位但本地账本没有任何 OPEN 格子时，自动补 1 个 OPEN 格子（仅写账本，不下单）。
    触发条件（幂等）：
    - (coin, platform, side) 在账本中 OPEN/CLOSE_PENDING=0
    - snapshot 中该腿 notional_u > 0
    """
    added = 0
    try:
        self.load()
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    def _leg_key(it: dict):
        return (str(it.get("coin") or "").upper(),
                str(it.get("platform") or it.get("plat") or "").upper(),
                str(it.get("side") or "").upper())

    exist_open = {}
    try:
        for it in list(self._data.get("items") or []):
            st = str(it.get("status") or "").upper()
            if st not in ("OPEN", "CLOSE_PENDING"):
                continue
            k = _leg_key(it)
            exist_open[k] = exist_open.get(k, 0) + 1
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    positions = (snap or {}).get("positions") or {}
    def _iter_legs():
        if isinstance(positions, dict):
            for coin, vv in positions.items():
                cu = str(coin or "").upper()
                if isinstance(vv, dict) and ("EXT" in vv or "VAR" in vv or "ext" in vv or "var" in vv):
                    for plat in ("EXT","VAR","ext","var"):
                        if plat in vv:
                            yield cu, str(plat).upper(), vv.get(plat)
                else:
                    yield cu, "UNKNOWN", vv

    nowt = time.time()
    for coin_u, plat_u, leg in _iter_legs():
        try:
            if not isinstance(leg, dict):
                continue
            side = str(leg.get("side") or leg.get("position_side") or "").upper()
            if side not in ("LONG","SHORT"):
                continue
            nu = leg.get("notional_u")
            if nu is None:
                nu = leg.get("value_u")
            if nu is None:
                nu = leg.get("notional")
            try:
                nu = float(nu or 0.0)
            except Exception:
                nu = 0.0
            if nu <= 0.0:
                continue

            key = (coin_u, plat_u, side)
            if exist_open.get(key, 0) > 0:
                continue

            entry = leg.get("entry") or leg.get("entry_px") or leg.get("entry_price")
            mark = leg.get("mark") or leg.get("mark_px") or leg.get("price")
            try:
                entry = float(entry) if entry is not None else None
            except Exception:
                entry = None
            try:
                mark = float(mark) if mark is not None else None
            except Exception:
                mark = None

            ref_px = entry if entry is not None else mark
            if ref_px is None:
                ref_px = 0.0

            try:
                _tp_floor, _tp_det = _grid_live_tp_pct(str(coin_u), fallback=float(tp_pct_default))
            except Exception:
                _tp_floor, _tp_det = float(tp_pct_default), {'src': 'local_grid_tp_floor_exc'}
            try:
                _tp_cfg = float(cfg_getf('LOCAL_GRID_TP_PCT', _tp_floor))
            except Exception:
                _tp_cfg = float(_tp_floor)
            tp_pct = float(max(_tp_cfg, _tp_floor))

            lid = f"RECOV_{int(nowt)}_{coin_u}_{plat_u}_{side}"
            item = {
                "gid": f"{coin_u}_{plat_u}_{side}_RECOV",
                "coin": coin_u,
                "platform": plat_u,
                "side": side,
                "layer_id": lid,
                "open_u": float(nu),
                "open_ref_px": float(ref_px),
                "tp_pct": float(tp_pct),
                "open_ts": float(nowt),
                "status": "OPEN",
                "note": "RECOVER_FROM_SNAPSHOT",
            }
            with self._lock:
                self._data.setdefault("items", []).append(item)
                self._data["ts"] = time.time()
            exist_open[key] = 1
            added += 1
            try:
                safe_log(lambda: f"[{now_ts()}] [LOCAL_GRID][RECOVER] coin={coin_u} plat={plat_u} side={side} "
                                 f"open_u={float(nu):.2f} ref_px={float(ref_px):.6f} tp_pct={float(tp_pct):.4f} layer_id={lid}")
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    if added:
        try:
            self.save()
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)
        try:
            safe_log(lambda: f"[{now_ts()}] [LOCAL_GRID][RECOVER_SUM] added={added}")
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)
    return int(added)

    def _get_mark_price_from_snapshot(self, snap: dict, coin: str, platform: str, side: str = "") -> float:
        """从扫描快照中取 mark（兼容 positions 为 dict 或 list）。

        修复口径：TP 当前价只认“真实持仓 Mark 真相源”，优先级固定为：
        1) 当前轮 snapshot / positions 中该平台该币持仓行里的 mark；
        2) 最近一次 snapshot 指标缓存里的 mark；
        3) positions.json（含 .pending）里该平台该币持仓行里的 mark；
        其余来源（例如 ring）不再用于 TP 命中判定，避免伪价格把 TP 链路带偏。
        取不到时返回 NaN，并把原因写入 TP 诊断缓存，由上游升级为模块降级/故障态。
        """
        c0 = str(coin or '').upper()
        p0 = str(platform or '').upper()
        s0 = str(side or '').upper()
        def _pick_mark(row: dict, src: str) -> float | None:
            try:
                mp = (
                    row.get("mark")
                    or row.get("mark_px")
                    or row.get("mark_price")
                    or row.get("last_px")
                    or row.get("last")
                    or row.get("px")
                    or row.get("cur_px")
                    or row.get("price")
                )
                if mp in (None, "", 0, 0.0):
                    return None
                mpf = float(mp)
                if math.isfinite(mpf) and mpf > 0:
                    _grid_tp_mark_info_set(c0, p0, s0, mark=mpf, source=src, reason='')
                    return float(mpf)
            except Exception:
                return None
            return None
        try:
            pos = self._get_pos_from_snapshot(snap, c0, p0) or {}
        except Exception:
            pos = {}
        mp0 = _pick_mark(pos if isinstance(pos, dict) else {}, 'snapshot_position')
        if mp0 is not None:
            return float(mp0)
        try:
            _sm = _get_last_snapshot_metric(c0, p0) if '_get_last_snapshot_metric' in globals() else {}
        except Exception:
            _sm = {}
        try:
            mp2 = safe_float((_sm or {}).get('mark'), default=None)
        except Exception:
            mp2 = None
        if mp2 is not None and float(mp2) > 0:
            _grid_tp_mark_info_set(c0, p0, s0, mark=mp2, source='last_snapshot_metric', reason='')
            return float(mp2)
        try:
            _disk = _load_positions_from_disk_fallback() if '_load_positions_from_disk_fallback' in globals() else {}
        except Exception:
            _disk = {}
        try:
            _root = (_disk.get('positions') if isinstance(_disk, dict) and isinstance(_disk.get('positions'), dict) else _disk) if isinstance(_disk, dict) else {}
            _plat = ((_root.get(p0) if isinstance(_root, dict) else None) or (_root.get(p0.lower()) if isinstance(_root, dict) else None) or {})
            _row = ((_plat.get(c0) if isinstance(_plat, dict) else None) or (_plat.get(c0.lower()) if isinstance(_plat, dict) else None) or {})
            if isinstance(_row, list) and _row:
                _row = next((x for x in _row if isinstance(x, dict)), {})
            mp3 = _pick_mark(_row if isinstance(_row, dict) else {}, 'positions_disk')
            if mp3 is not None:
                return float(mp3)
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_334', _e)
            pass
        _grid_tp_mark_info_set(c0, p0, s0, mark=None, source='missing', reason='snapshot_and_positions_missing_mark')
        return float("nan")

    def scan_and_build_tp_requests(self, snap: dict) -> List[dict]:
        """根据快照扫描本地账本，命中止盈则生成“市价减仓”请求（M9 decrease），由调用方入队执行。"""
        reqs: List[dict] = []
        now = time.time()
        for it in self.iter_open_items():
            gid = str(it.get("id"))
            coin = str(it.get("coin") or "").upper()
            plat = str(it.get("platform") or "").upper()
            try:
                _cache_last_snapshot_metric(snap, coin, plat)
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_335', _e)
                pass
            side = str(it.get("side") or "").upper()
            _owner_meta = self._m9_owner_meta_from_item(it if isinstance(it, dict) else {})
            grid_id = str(_owner_meta.get("grid_id") or "")
            owner_layer_id = str(_owner_meta.get("layer_id") or "")
            local_item_id = str(_owner_meta.get("local_item_id") or gid)
            amt = float(it.get("amount_u") or 0.0)
            entry = float(it.get("entry_price") or 0.0)
            tp_price = float(it.get("tp_price") or 0.0)
            st = str(it.get("state") or "OPEN")
            last_try = float(it.get("last_try_ts") or 0.0)
            try_n = int(it.get("close_try") or 0)
            if try_n <= 0:
                cd = 0.0
            elif try_n == 1:
                cd = 5.0
            elif try_n == 2:
                cd = 15.0
            elif try_n == 3:
                cd = 30.0
            else:
                cd = 60.0
            if cd > 0 and (now - last_try) < cd:
                try:
                    _tp_flow_inc(coin, "COOLDOWN", stage="SCAN")
                except Exception as _e:
                    _log_exc(mod="SYS", stage="EXC_PASS", e=_e)
                continue

            mark = self._get_mark_price_from_snapshot(snap, coin, plat, side)
            _mark_info = _grid_tp_mark_info_get(coin, plat, side)
            try:
                if (mark is None) or (isinstance(mark, float) and math.isnan(mark)):
                    raise ValueError('mark_nan')
            except Exception:
                try:
                    _tp_flow_inc(coin, "DATA_INVALID", stage="SCAN")
                except Exception as _e:
                    _log_exc(mod="SYS", stage="EXC_PASS", e=_e)
                try:
                    _grid_tp_mark_diag_update(coin, plat, side, ok=False, mark=None, source=str((_mark_info or {}).get('source') or 'missing'), reason=str((_mark_info or {}).get('reason') or 'mark_nan'), layer_id=gid)
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_336', _e)
                    pass
                continue
            try:
                eff_tp_px, eff_tp_pct, _eff_tp_changed, _eff_tp_det = _m9_layer_effective_tp_px(it if isinstance(it, dict) else {}, coin=coin, side=side, cur_px=mark, ref_px=entry, allow_reprice=True)
                if eff_tp_px is not None and float(eff_tp_px) > 0:
                    tp_price = float(eff_tp_px)
                if eff_tp_pct is not None and float(eff_tp_pct) > 0:
                    try:
                        it['tp_pct'] = float(eff_tp_pct)
                        it['tp_price'] = float(tp_price)
                        it['tp_px'] = float(tp_price)
                        it['effective_tp_pct'] = float(eff_tp_pct)
                        it['effective_tp_px'] = float(tp_price)
                    except Exception:
                        pass
            except Exception:
                eff_tp_px, eff_tp_pct, _eff_tp_changed, _eff_tp_det = None, None, False, {}
            if mark <= 0 or tp_price <= 0 or entry <= 0 or amt <= 0:
                try:
                    _tp_flow_inc(coin, "DATA_INVALID", stage="SCAN")
                except Exception as _e:
                    _log_exc(mod="SYS", stage="EXC_PASS", e=_e)
                try:
                    _grid_tp_mark_diag_update(coin, plat, side, ok=False, mark=mark, source=str((_mark_info or {}).get('source') or 'invalid'), reason='non_positive_mark_or_tp', layer_id=gid)
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_337', _e)
                    pass
                continue
            try:
                _grid_tp_mark_diag_update(coin, plat, side, ok=True, mark=mark, source=str((_mark_info or {}).get('source') or 'snapshot_position'), reason='', layer_id=gid)
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_338', _e)
                pass
            hit = False
            if side == "LONG":
                hit = (mark >= tp_price)
            elif side == "SHORT":
                hit = (mark <= tp_price)

            if not hit:
                try:
                    _tp_flow_inc(coin, "NO_HIT", stage="SCAN")
                except Exception as _e:
                    _log_exc(mod="SYS", stage="EXC_PASS", e=_e)
                continue

            try:
                _tp_flow_inc(coin, "HIT", stage="SCAN")
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

            try:
                safe_log(lambda: f"[{now_ts()}] [GRID_TP][TP_TRIGGER] coin={coin} plat={plat} side={side} gid={gid} mark={_fmt_float(mark)} mark_src={str((_mark_info or {}).get('source') or '')} tp={_fmt_float(tp_price)} entry={_fmt_float(entry)} amt_u={_fmt_float(amt)}")
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

            try:
                _tp_emit_event("TP_TRIGGER", coin=coin, platform=plat, trace_id=str(it.get("trace_id") or ""), detail={"gid": gid, "side": side, "mark": float(mark), "tp_price": float(tp_price), "entry": float(entry), "amt_u": float(amt)})
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

            sell_qty = 0.0
            sell_u = float(amt)
            try:
                if entry > 0 and mark > 0:
                    sell_qty = float(amt) / float(entry)   # qty（币数量）
                    sell_u_raw = float(sell_qty) * float(mark)  # 当前价换算的名义(U)
                    sell_u = float(_m9_norm_u_tens(sell_u_raw, 10.0, max(10.0, sell_u_raw)))
            except Exception:
                sell_qty = 0.0
                sell_u = float(amt)

            try:
                _pos = (((snap or {}).get("positions") or {}).get(plat) or {}).get(coin) or {}
                pos_side = str(_pos.get("side") or "").upper()
            except Exception:
                pos_side = ""
            try:
                cur_notional = float(self._get_notional_u_from_snapshot(snap, coin, plat))
            except Exception:
                cur_notional = 0.0
            if cur_notional > 0 and mark > 0:
                cap_u = float(cur_notional) * 0.98
                sell_u_before = float(sell_u)
                if sell_u_before > cap_u:
                    sell_u = float(_m9_norm_u_tens(cap_u, 10.0, max(10.0, cap_u)))
                    try:
                        sell_qty_cap = float(sell_u) / float(mark)
                    except Exception:
                        sell_qty_cap = 0.0
                    if sell_qty_cap > 0:
                        sell_qty = float(sell_qty_cap)
                    try:
                        safe_log(lambda: f"[{now_ts()}] [GRID_TP][DECREASE_CAP] gid={gid} side={side} pos_side={pos_side} sell_u_before={_fmt_float(sell_u_before)} cap_u={_fmt_float(cap_u)} cur_notional={_fmt_float(cur_notional)} sell_u_after={_fmt_float(sell_u)} sell_qty_after={_fmt_float(sell_qty)}")
                    except Exception as _e:
                        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

            try:
                safe_log(lambda: f"[{now_ts()}] [GRID_TP][DECREASE_BUILD] coin={coin} plat={plat} side={side} gid={gid} sell_qty={_fmt_float(sell_qty,6)} sell_u={_fmt_float(sell_u)} entry={_fmt_float(entry)} mark={_fmt_float(mark)} mark_src={str((_mark_info or {}).get('source') or '')}")
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

            _layer_no_tp = int(_grid_layer_no(owner_layer_id) or _grid_layer_no(str(it.get("layer_id") or "")) or _grid_layer_no(str(it.get("id") or "")) or 0)
            _layer_tag_tp = str(_grid_layer_tag(owner_layer_id) or _grid_layer_tag(str(it.get("layer_id") or "")) or "")
            _grid_layer_payload = {
                "grid_id": str(grid_id or ""),
                "layer_id": str(owner_layer_id or ""),
                "layer_tag": str(_layer_tag_tp or ""),
                "layer_no": int(_layer_no_tp or 0),
                "source": "M9_SELF_OPEN",
                "managed_by_grid": True,
                "can_tp_close": True,
                "layer_role": "GRID_LAYER",
                "platform": plat,
                "side": side,
                "state": str(st or ""),
                "entry_price": float(entry),
                "tp_price": float(tp_price),
                "tp_pct": float(it.get("tp_pct") or 0.0),
                "amount_u": float(amt),
                "local_item_id": str(local_item_id or gid),
                "local_grid_id": str(_owner_meta.get("local_grid_id") or ""),
            }
            req = {
                "module": "M9",
                "submodule": "TP_LOCAL",
                "coin": coin,
                "platform": plat,
                "side": side,
                "action_type": "decrease",
                "action": "decrease",
                "grid_id": str(grid_id or ""),
                "layer_id": str(owner_layer_id or ""),
                "layer_tag": str(_layer_tag_tp or ""),
                "layer_no": int(_layer_no_tp or 0),
                "grid_layer": dict(_grid_layer_payload),
                "amount_usd": float(sell_u),
                "notional_u": float(sell_u),
                "params": {"amount_usd": float(sell_u), "close_notional_u": float(sell_u), "notional_u": float(sell_u), "platform": plat, "side": side, "grid_id": str(grid_id or ""), "layer_id": str(owner_layer_id or ""), "layer_tag": str(_layer_tag_tp or ""), "layer_no": int(_layer_no_tp or 0), "grid_layer": dict(_grid_layer_payload)},

                "meta": {
                    "from": "LOCAL_GRID_TP",
                    "source": "M9_SELF_OPEN",
                    "managed_by_grid": True,
                    "can_tp_close": True,
                    "layer_role": "GRID_LAYER",
                    "grid_id": str(grid_id or ""),
                    "layer_id": str(owner_layer_id or ""),
                    "layer_tag": str(_layer_tag_tp or ""),
                    "layer_no": int(_layer_no_tp or 0),
                    "grid_layer": dict(_grid_layer_payload),
                    "local_item_id": str(local_item_id or gid),
                    "local_grid_id": str(_owner_meta.get("local_grid_id") or ""),
                    "entry_price": float(entry),
                    "tp_price": float(tp_price),
                    "tp_pct": float(it.get("tp_pct") or 0.0),
                    "mark": float(mark),
                    "mark_source": str((_mark_info or {}).get("source") or ""),
                    "trigger_mark": float(mark),
                    "sell_qty": float(sell_qty),
                    "sell_u": float(sell_u),
                    "state": st,
                },
            }
            reqs.append(req)
            try:
                _tid = f"GRIDTP-{uuid.uuid4().hex[:10]}"
            except Exception:
                _tid = "GRIDTP"
            try:
                if isinstance(req.get('meta'), dict):
                    req['meta'].setdefault('trace_id', _tid)
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

            req.setdefault('trace_id', _tid)
            self.bump_close_pending(local_item_id or gid, trace_id=_tid, trigger_mark=float(mark), trigger_ts=time.time())

        return reqs

