def safe_print(*args, **kwargs):
    try:
        print(*args, **kwargs)
    except Exception:
        try:
            msg = " ".join(str(a) for a in args)
            _os.write(2, (msg + "\n").encode("utf-8", errors="ignore"))
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

def _fmt_float(x, ndigits=None) -> str:
    """格式化浮点数（用于日志/表格/UI）。
    - ndigits=None: 使用紧凑格式（兼容旧调用）
    - ndigits=int : 固定小数位（如 6）
    """
    try:
        if x is None:
            return ""
        fx = float(x)
        if ndigits is None:
            return f"{fx:.8g}"
        try:
            nd = int(ndigits)
        except Exception:
            nd = None
        if nd is None:
            return f"{fx:.8g}"
        if abs(fx) < 0.5 * (10 ** (-nd)):
            fx = 0.0
        return f"{fx:.{nd}f}"
    except Exception:
        return str(x)

def _pos_notional(pos: dict) -> float:
    """统一名义价值口径（U）。

    历史上脚本里存在多套 notional 抽取逻辑（键集合/abs 策略不一致），会导致：
    - 硬顶判断/差额判断/止盈阈值判断出现分歧
    - 证据针口径不一致（A 说满足、B 说不满足）

    这里强制收敛：所有旧调用点统一走 _a1_pos_notional_u（返回非负 abs）。
    """
    try:
        return float(_a1_pos_notional_u(pos if isinstance(pos, dict) else {}))
    except Exception:
        return 0.0

def _m9_grid_id(coin: str, plat: str, side_: str) -> str:
    """M9 网格ID：与主逻辑保持一致，并兼容旧账本 key。

    当前主口径：{COIN}_{PLAT}_{SIDE}_M9
    旧口径（历史兼容）：{COIN}_{PLAT}_{SIDE}_M9X
    （极少数版本可能出现 M9_{COIN}_{PLAT}_{SIDE}，也一并兼容读取）
    """
    try:
        c = str(coin or "").upper()
        p = str(plat or "").upper()
        s = str(side_ or "").upper()
        if not c or not p:
            return ""
        if s not in ("LONG", "SHORT"):
            return ""
        gid_new = f"{c}_{p}_{s}_M9"
        gid_old = f"{c}_{p}_{s}_M9X"
        gid_alt = f"M9_{c}_{p}_{s}"
        try:
            gb = globals().get("GRID_BOOK")
            if gb is not None and hasattr(gb, "data") and isinstance(getattr(gb, "data"), dict):
                grids = (gb.data.get("grids") or {})
                if isinstance(grids, dict):
                    if gid_new in grids:
                        return gid_new
                    if gid_old in grids:
                        return gid_old
                    if gid_alt in grids:
                        return gid_alt
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_340', _e)
            pass
        return gid_new
    except Exception:
        try:
            return f"{str(coin)}_{str(plat)}_{str(side_)}_M9"
        except Exception:
            return ""

def _get_grid_id(snapshot: dict, coin: str, plat: str) -> str:
    try:
        pos = _get_position(snapshot or {}, coin, plat) or {}
        side = str((pos or {}).get("side") or (pos or {}).get("position_side") or "NONE").upper()
        if side not in ("LONG", "SHORT"):
            return ""
        return str(_m9_grid_id(str(coin), str(plat), side))
    except Exception:
        return ""

def _gridbook_force_flat_scope(coin: str, platform: str = "", *, reason: str = "FORCE_FLAT") -> dict:
    try:
        gb = globals().get("GRID_BOOK")
        if gb is None or (not hasattr(gb, "force_flat_scope")):
            return {"ok": False, "reason": "grid_book_unavailable", "changed": 0, "grids": []}
        return gb.force_flat_scope(str(coin or ""), str(platform or ""), reason=str(reason or "FORCE_FLAT"))
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)
        return {"ok": False, "reason": "grid_book_force_flat_exc", "changed": 0, "grids": []}

def _apply_profile(name: str, *, seq: int = 0, params: dict | None = None) -> dict:
    """运行时形态切换：只改进程内状态，不改策略主链结构。"""
    try:
        prof = str(name or '').strip().lower()
    except Exception:
        prof = ''
    if prof not in ('defensive', 'normal', 'aggressive'):
        prof = 'normal'
    try:
        p = dict(params or {}) if isinstance(params, dict) else {}
    except Exception:
        p = {}
    try:
        globals()['ACTIVE_PROFILE'] = prof
        globals()['ACTIVE_PROFILE_PARAMS'] = p
        globals()['_PROFILE_LAST_APPLIED_SEQ'] = int(seq or 0)
    except Exception:
        pass
    try:
        return {'ok': True, 'profile': prof, 'params': p, 'seq': int(seq or 0)}
    except Exception:
        return {'ok': True, 'profile': prof}

def _abs_hedge_diff_u(snapshot: dict, coin: str) -> float:
    try:
        e = _get_position(snapshot or {}, coin, "EXT") or {}
        v = _get_position(snapshot or {}, coin, "VAR") or {}
        return abs(_pos_notional(e) - _pos_notional(v))
    except Exception:
        return 0.0

def _a1_profit_leg_threshold(snapshot: dict, coin: str):
    detail = {}
    try:
        coin_u = str(coin or '').upper().strip()
        e = _get_position(snapshot or {}, coin_u, "EXT") or {}
        v = _get_position(snapshot or {}, coin_u, "VAR") or {}
        e_up = float((e or {}).get("upnl_u") or (e or {}).get("upnl_usd") or 0.0)
        v_up = float((v or {}).get("upnl_u") or (v or {}).get("upnl_usd") or 0.0)
        e_n = float(_pos_notional(e) or 0.0)
        v_n = float(_pos_notional(v) or 0.0)
        net_up = float(e_up + v_up)
        if e_up >= v_up:
            profit_leg_platform, profit_leg_notional, profit_leg_upnl = "EXT", float(e_n), float(e_up)
            loss_leg_platform, loss_leg_notional, loss_leg_upnl = "VAR", float(v_n), float(v_up)
        else:
            profit_leg_platform, profit_leg_notional, profit_leg_upnl = "VAR", float(v_n), float(v_up)
            loss_leg_platform, loss_leg_notional, loss_leg_upnl = "EXT", float(e_n), float(e_up)
        pct = float(_b2_trigger_pct_for_coin(coin_u, default=_tp_trigger_floor_pct(coin_u)) or 0.0)
        thr = float(_b2_trigger_need_u_for_coin(coin_u, loss_leg_notional, default=_tp_trigger_floor_pct(coin_u)) or 0.0)
        detail = {
            "coin": coin_u,
            "ext_upnl_u": e_up,
            "var_upnl_u": v_up,
            "ext_notional_u": e_n,
            "var_notional_u": v_n,
            "net_upnl_u": net_up,
            "profit_leg_platform": profit_leg_platform,
            "profit_leg_notional_u": profit_leg_notional,
            "profit_leg_upnl_u": profit_leg_upnl,
            "loss_leg_platform": loss_leg_platform,
            "loss_leg_notional_u": loss_leg_notional,
            "loss_leg_upnl_u": loss_leg_upnl,
            "trigger_pct": pct,
            "pct": pct,
            "thr": thr,
            "thr_u": thr,
            "threshold_basis": "b2_loss_leg_notional_x_unified_trigger_pct",
        }
        return thr, detail
    except Exception as _e:
        detail["exc"] = str(_e)
        return 0.0, detail

req_any = None
menhu = None

def _struct_legacy_fill_required_fields(req: dict, snapshot: dict | None = None) -> dict:
    """[旧补腿链已删除，仅保留旧请求清洗口径]

    目标（按你最新要求）：
    1) 缺少口径补齐：platform/side/amount_usd/action_type/coin 等关键字段尽量从快照推断补齐
    2) 冲突与共用口径隔离：结构修复只使用自己的“专用口径”，严禁与其它模块共用/混用历史同义键
       - 入口可兼容旧字段读取，但输出会被强制收敛为：
         * 顶层：module/coin/platform/side/action_type/amount_usd/params/meta
         * params：仅保留 amount_usd 与 LEGFIX__* 专用键
         * meta：写入 schema 标记与 LEGFIX__* 专用键（方便证据针与排障）
       - 清理歧义键：plat/usd/notional_u/add_notional_u/action（只保留 action_type）
    3) 不改策略：只补齐字段，不改变触发条件/阈值/优先级
    """
    try:
        if not isinstance(req, dict):
            return req
        if str(req.get("module") or "").upper().strip() != MOD_LEGACY_FIX:
            return req

        snap = snapshot or {}
        params = req.get("params") if isinstance(req.get("params"), dict) else {}
        meta = req.get("meta") if isinstance(req.get("meta"), dict) else {}

        coin = str(req.get("coin") or req.get("symbol") or params.get("coin") or meta.get("coin") or "").upper().strip()
        if coin:
            req["coin"] = coin
            params["LEGFIX__coin"] = coin
            meta["LEGFIX__coin"] = coin
        else:
            meta["LEGFIX__schema_error"] = meta.get("LEGFIX__schema_error") or "coin_missing"

        try:
            at0 = str(req.get("action_type") or req.get("action") or "").upper()
            why0 = str(params.get("why") or meta.get("why") or "")
            why_l = why0.lower()
            if at0 in ("ADD_SINGLE", "ADD_PAIR", "LEGACY_DELETED_ONE_SHOT", "ONE_SHOT", "FILL_LEG") and any(k in why_l for k in ("missing_leg", "severe_gap", "one_shot", "legacy_deleted", "补腿", "修复")):
                meta["safe_legacy_fix"] = True
                meta.setdefault("safe_reason", "legacy_fix_one_shot")
                params["LEGFIX__safe_legacy_fix"] = 1
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_341', _e)
            pass
        act = str(req.get("action_type") or params.get("action_type") or meta.get("action_type") or req.get("action") or "").lower().strip()
        if not act:
            act = "increase"
        req["action_type"] = act
        params["LEGFIX__action_type"] = act
        meta["LEGFIX__action_type"] = act

        def _struct_legacy_deleted_pos_notional_u(pos: dict) -> float:
            try:
                if not isinstance(pos, dict):
                    return 0.0
                for k in ("notional_u", "notional_usd", "value_u", "value_usd", "notional", "positionValue", "notionalUsd", "notional_usd"):
                    v = pos.get(k)
                    if v not in (None, "", 0):
                        try:
                            return float(abs(float(v)))
                        except Exception:
                            continue
                return 0.0
            except Exception:
                return 0.0

        def _struct_legacy_deleted_pos_side(pos: dict) -> str:
            try:
                if not isinstance(pos, dict):
                    return ""
                s = str(pos.get("side") or pos.get("position_side") or pos.get("pos_side") or pos.get("ls") or pos.get("direction") or "").upper().strip()
                return s if s in ("LONG", "SHORT") else ""
            except Exception:
                return ""

        def _struct_legacy_deleted_get_pos(s: dict, c: str, p: str) -> dict:
            cu = str(c or "").upper().strip()
            pu = str(p or "").upper().strip()
            if not cu or not pu:
                return {}
            try:
                pos = (((s or {}).get("positions") or {}).get(pu) or {}).get(cu)
                if isinstance(pos, dict):
                    return pos
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

            try:
                pos = (((s or {}).get("by_coin") or {}).get(cu) or {}).get(pu)
                if isinstance(pos, dict):
                    return pos
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

            try:
                cc = ((s or {}).get("coins") or {}).get(cu) or {}
                if pu == "EXT":
                    pos = cc.get("ext")
                else:
                    pos = cc.get("var")
                if isinstance(pos, dict):
                    return pos
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

            return {}

        epos = _struct_legacy_deleted_get_pos(snap, coin, "EXT")
        vpos = _struct_legacy_deleted_get_pos(snap, coin, "VAR")
        en = _struct_legacy_deleted_pos_notional_u(epos)
        vn = _struct_legacy_deleted_pos_notional_u(vpos)
        es = _struct_legacy_deleted_pos_side(epos)
        vs = _struct_legacy_deleted_pos_side(vpos)
        ext_has = (en > 0.0 and es in ("LONG", "SHORT"))
        var_has = (vn > 0.0 and vs in ("LONG", "SHORT"))

        plat = str(req.get("platform") or params.get("platform") or meta.get("platform") or req.get("plat") or "").upper().strip()
        if plat not in ("EXT", "VAR"):
            if ext_has and (not var_has):
                plat = "VAR"
            elif var_has and (not ext_has):
                plat = "EXT"
            else:
                plat = "EXT" if en <= vn else "VAR"
        req["platform"] = plat
        params["LEGFIX__platform"] = plat
        meta["LEGFIX__platform"] = plat

        side = str(req.get("side") or params.get("side") or meta.get("side") or "").upper().strip()
        if side not in ("LONG", "SHORT"):
            if act == "add_leg":
                other = vs if plat == "EXT" else es
                if other in ("LONG", "SHORT"):
                    side = "SHORT" if other == "LONG" else "LONG"
            else:
                if plat == "EXT" and es in ("LONG", "SHORT"):
                    side = es
                elif plat == "VAR" and vs in ("LONG", "SHORT"):
                    side = vs
                else:
                    other = vs if plat == "EXT" else es
                    if other in ("LONG", "SHORT"):
                        side = "SHORT" if other == "LONG" else "LONG"
        if side in ("LONG", "SHORT"):
            req["side"] = side
            params["LEGFIX__side"] = side
            meta["LEGFIX__side"] = side
        else:
            meta["LEGFIX__schema_error"] = meta.get("LEGFIX__schema_error") or "side_missing"
        def _pick_amt(obj: dict) -> float:
            try:
                if not isinstance(obj, dict):
                    return 0.0
                for k in ("amount_usd", "usd", "notional_u", "add_notional_u"):
                    v = obj.get(k)
                    if v not in (None, "", 0):
                        try:
                            return float(v)
                        except Exception:
                            continue
                return 0.0
            except Exception:
                return 0.0

        def _struct_legacy_deleted_pick_rsi(snap_: dict, coin_: str) -> float | None:
            try:
                cu = str(coin_ or "").upper()
                if not isinstance(snap_, dict):
                    return None
                ind = (snap_.get("indicators") or {}).get(cu) if isinstance(snap_.get("indicators"), dict) else None
                if isinstance(ind, dict):
                    r = ind.get("rsi") or ind.get("RSI")
                    if r not in (None, "", 0):
                        return float(r)
                rr = (snap_.get("rsi") or {}).get(cu) if isinstance(snap_.get("rsi"), dict) else None
                if rr not in (None, "", 0):
                    return float(rr)
                for obj in (meta, params, req):
                    if isinstance(obj, dict):
                        rv = obj.get("rsi") or obj.get("RSI")
                        if rv not in (None, "", 0):
                            return float(rv)
                return None
            except Exception:
                return None

        amt = _pick_amt(req) or _pick_amt(params)

        if amt <= 0.0:
            rsi_raw = _struct_legacy_deleted_pick_rsi(snap, coin)
            rsi_eff = None
            try:
                if rsi_raw is not None and side in ("LONG", "SHORT"):
                    dist = abs(float(rsi_raw) - 50.0)
                    rsi_eff = (50.0 - dist) if side == "LONG" else (50.0 + dist)
                    rsi_eff = float(max(25.0, min(75.0, float(rsi_eff))))
                    try:
                        meta["LEGFIX__rsi_raw"] = float(rsi_raw)
                        meta["LEGFIX__rsi_eff"] = float(rsi_eff)
                    except Exception as _e:
                        _record_swallowed_exception('except_pass_line_342', _e)
                        pass
                    try:
                        u, det = _grid_pick_u_in_bucket_no_repeat(
                            str(coin), str(plat), str(side),
                            rsi=float(rsi_eff), last_map=_RSI_LAST_PICK_U,
                            u_floor=10.0, u_ceil=120.0, max_retry=8,
                            req_mod=MOD_LEGACY_FIX, action_type='legacy_fix_add', req_id=str(meta.get('trace_id') or '')
                        )
                        if u is not None and float(u) > 0:
                            amt = float(u)
                    except Exception as _e:
                        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_343', _e)
                pass
        if amt <= 0.0:
            diff = float(abs(en - vn))
            if act == "add_leg":
                base = max(en, vn)
                amt = float(_round_usd10(base if base > 0 else 10.0))
            else:
                amt = float(_round_usd10(diff if diff > 0 else 10.0))

        try:
            amt = float(_round_usd10(amt))
        except Exception:
            try:
                amt = float(round(float(amt) / 10.0) * 10.0)
            except Exception:
                amt = float(amt or 0.0)

        try:
            amt = float(max(40.0, min(float(amt), 120.0)))
        except Exception:
            amt = 40.0

        try:
            amt = float(_round_usd10(amt))
        except Exception:
            try:
                amt = float(round(float(amt) / 10.0) * 10.0)
            except Exception:
                amt = float(amt or 40.0)

        req["amount_usd"] = amt
        req["usd"] = amt
        params["amount_usd"] = amt
        params["usd"] = amt
        params["LEGFIX__amount_usd"] = amt
        meta["LEGFIX__amount_usd"] = amt

        meta["schema"] = "LEGACY_FIX_SCHEMA_V2"
        meta["schema_module"] = MOD_LEGACY_FIX
        meta["schema_ts"] = float(time.time())

        for k in ("plat", "notional_u", "add_notional_u", "action"):
            try:
                if k in req:
                    req.pop(k, None)
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

        for k in ("notional_u", "add_notional_u", "plat", "action"):
            try:
                if k in params:
                    params.pop(k, None)
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

        req["params"] = params
        req["meta"] = meta
        try:
            _pin("GO_GATE_STAMP", mod="LEGACY_DELETED", coin=str(coin or ""), ok=1, reason="stamped",
                 trace=str((meta or {}).get("trace_id") or (meta or {}).get("trace") or ""),
                 act=str(act or ""), plat=str(req.get("platform") or ""), ts=str(meta.get("go_checked_ts") or ""))
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

        return req
    except Exception:
        return req

_OPEN_AMOUNT_LAST_PICK: Dict[str, float] = {}
_OPEN_AMOUNT_GLOBAL_KEY = '__GLOBAL_OPEN__'

def _build_wave_candidates_10u(base_u: Any, lo_u: Any, hi_u: Any, *, spread_steps: int = 2) -> list[float]:
    out: list[float] = []
    try:
        base = float(_half_up_round(float(base_u or 0.0), 10.0))
    except Exception:
        base = 0.0
    try:
        lo = float(_half_up_round(float(lo_u or 0.0), 10.0))
    except Exception:
        lo = 0.0
    try:
        hi = float(_half_up_round(float(hi_u or 0.0), 10.0))
    except Exception:
        hi = 0.0
    if lo <= 0.0:
        lo = 10.0
    if hi < lo:
        hi = lo
    if base <= 0.0:
        base = lo
    base = float(min(hi, max(lo, base)))
    span = max(1, int(spread_steps or 1))
    ordered = [0]
    for step in range(1, span + 1):
        ordered.extend([-step, step])
    for step in ordered:
        cand = float(base + float(step) * 10.0)
        if cand < lo - 1e-9 or cand > hi + 1e-9:
            continue
        cand = float(_half_up_round(cand, 10.0))
        if cand not in out:
            out.append(cand)
    if not out:
        cur = int((lo + 9.999) // 10) * 10
        end = int(hi // 10) * 10
        while cur <= end:
            vv = float(cur)
            if vv not in out:
                out.append(vv)
            cur += 10
    if not out:
        out = [float(max(10.0, base))]
    return list(out)

def _open_amount_no_repeat_pick(base_u: Any, *, key: str = '', candidates: list[float] | tuple[float, ...] | None = None, mode: str = 'jitter_30u_tens', global_key: str = _OPEN_AMOUNT_GLOBAL_KEY) -> tuple[float, dict]:
    try:
        base = float(base_u or 0.0)
    except Exception:
        base = 0.0
    if base <= 0.0:
        return 0.0, {'base': float(base or 0.0), 'picked': 0.0, 'range': [0.0, 0.0], 'last': 0.0, 'last_global': 0.0, 'mode': 'skip_non_positive'}
    low = max(10.0, base - 30.0)
    high = max(low, base + 30.0)
    normalized_candidates = []
    if isinstance(candidates, (list, tuple)):
        for x in candidates:
            try:
                xf = float(x)
            except Exception:
                continue
            if xf <= 0.0:
                continue
            try:
                xf = float(_half_up_round(float(xf), 10.0))
            except Exception:
                xf = float(max(10.0, round(float(xf) / 10.0) * 10.0))
            if xf not in normalized_candidates:
                normalized_candidates.append(float(xf))
    if normalized_candidates:
        candidates = sorted(normalized_candidates)
        low = float(min(candidates))
        high = float(max(candidates))
    else:
        candidates = _build_wave_candidates_10u(base, low, high, spread_steps=3)
        low = float(min(candidates))
        high = float(max(candidates))
    last = None
    last_global = None
    try:
        if key:
            last = _OPEN_AMOUNT_LAST_PICK.get(str(key))
        if global_key:
            last_global = _OPEN_AMOUNT_LAST_PICK.get(str(global_key))
    except Exception:
        last = None
        last_global = None
    preferred = [float(x) for x in candidates if abs(float(x) - float(base)) <= 10.0]
    pool0 = preferred or list(candidates)
    pool1 = [float(x) for x in pool0 if (last is None or abs(float(x) - float(last or 0.0)) > 1e-9)]
    pool2 = [float(x) for x in pool1 if (last_global is None or abs(float(x) - float(last_global or 0.0)) > 1e-9)]
    pool = pool2 or pool1 or [float(x) for x in candidates if (last is None or abs(float(x) - float(last or 0.0)) > 1e-9)] or list(candidates)
    try:
        picked = float(random.choice(pool))
    except Exception:
        picked = float(pool[0])
    if len(candidates) >= 2:
        if last is not None and abs(float(picked) - float(last or 0.0)) <= 1e-9:
            for alt in candidates:
                if abs(float(alt) - float(last or 0.0)) > 1e-9 and (last_global is None or abs(float(alt) - float(last_global or 0.0)) > 1e-9):
                    picked = float(alt)
                    break
        if last_global is not None and abs(float(picked) - float(last_global or 0.0)) <= 1e-9:
            for alt in candidates:
                if abs(float(alt) - float(last_global or 0.0)) > 1e-9 and (last is None or abs(float(alt) - float(last or 0.0)) > 1e-9):
                    picked = float(alt)
                    break
    try:
        if key:
            _OPEN_AMOUNT_LAST_PICK[str(key)] = float(picked)
        if global_key:
            _OPEN_AMOUNT_LAST_PICK[str(global_key)] = float(picked)
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_344', _e)
        pass
    return float(picked), {'base': float(base), 'picked': float(picked), 'range': [float(low), float(high)], 'last': float(last or 0.0), 'last_global': float(last_global or 0.0), 'candidates': list(candidates), 'mode': str(mode or 'jitter_30u_tens')}

def _is_open_like_for_amount_jitter(module: str = '', action: str = '') -> bool:
    m = str(module or '').upper().strip()
    a = str(_canon_action_type(action) or action or '').lower().strip()
    if a in ('decrease', 'reduce', 'reduce_only', 'sell', 'close', 'close_all', 'close_pair', 'tp', 'take_profit', 'take_profit_full', 'close_full', 'close_partial_notional', 'partial_close'):
        return False
    return bool(_is_risk_increasing_action(a) or a in ('add_leg', TXT_LEGACY_FIX, 'legacy_only', 'hedge', 'rebalance') or (m in ('B1', MOD_LEGACY_FIX, 'X1') and a in ('open', 'open_leg', 'add', 'increase', 'open_full')))


def _normalize_request_amount_truth(req_any: Any) -> Any:
    """统一金额真相源：M9 increase/open 锁定金额优先，其余走 final_amount_u。"""
    try:
        if not isinstance(req_any, dict):
            return req_any
        req = req_any
        params = req.get('params') if isinstance(req.get('params'), dict) else {}
        meta = req.get('meta') if isinstance(req.get('meta'), dict) else {}
        mod = str(req.get('module') or meta.get('module') or params.get('module') or '').upper().strip()
        act = str(req.get('action_type') or params.get('action_type') or req.get('action') or '').lower().strip()
        val = None
        val_source = 'final_amount_u'
        _locked_u, _locked_source = _m9_open_locked_amount_truth(req, params=params, meta=meta)
        if mod == 'M9' and _locked_u > 0.0:
            val = float(_locked_u)
            val_source = str(_locked_source or 'amount_locked_final_u_no_override')
        if val is None:
            for src in (req, params, meta):
                for k in ('final_amount_u','amount_locked_final_u','amount_usd','amount_usd_intent','intent_amount','usd','notional_u','add_notional_u','amount_u','amount','u'):
                    try:
                        v = src.get(k, None)
                    except Exception:
                        v = None
                    if v not in (None, '', 0, 0.0):
                        try:
                            vf = float(v or 0.0)
                        except Exception:
                            vf = 0.0
                        if vf > 0.0:
                            val = vf
                            val_source = str(k)
                            break
                if val is not None:
                    break
        if val is None:
            return req_any
        keys = ('final_amount_u','amount_usd','amount_usd_intent','intent_amount','usd','notional_u','add_notional_u','amount_u','amount','u')
        for k in keys:
            req[k] = float(val)
            params[k] = float(val)
        meta['final_amount_u'] = float(val)
        meta['amount_locked_final_u'] = float(val)
        meta['amount_truth_source'] = str(val_source)
        if mod == 'M9' and _locked_u > 0.0:
            meta['m9_amount_contract_source'] = str(val_source)
        req['params'] = params
        req['meta'] = meta
        return req_any
    except Exception:
        return req_any


def _apply_open_amount_no_repeat(req_any: Any) -> Any:
    try:
        if isinstance(req_any, dict):
            req = req_any
            mod = str(req.get('module') or '').upper().strip()
            act = str(req.get('action_type') or req.get('action') or '').lower().strip()
            if not _is_open_like_for_amount_jitter(mod, act):
                return req_any
            params = req.get('params') if isinstance(req.get('params'), dict) else {}
            meta = req.get('meta') if isinstance(req.get('meta'), dict) else {}
            if str(mod).upper().strip() == 'M9' and str(act).lower().strip() != 'decrease':
                if isinstance(meta, dict):
                    meta['open_amount_jitter_skip'] = True
                    meta['open_amount_jitter_skip_reason'] = 'm9_open_single_chain_contract'
                    req['meta'] = meta
                try:
                    _hint_u = _coerce_final_amount_u(
                        req.get('final_amount_u'), req.get('amount_u'), req.get('amount_usd'), req.get('usd'), req.get('u'), req.get('notional_u'),
                        (params.get('final_amount_u') if isinstance(params, dict) else None),
                        (params.get('amount_u') if isinstance(params, dict) else None),
                        (params.get('amount_usd') if isinstance(params, dict) else None),
                        (meta.get('final_amount_u') if isinstance(meta, dict) else None),
                        (meta.get('m9_rsi_bias_base_amount_u') if isinstance(meta, dict) else None),
                    )
                    _apply_final_amount_contract(req, params=params, meta=meta, amount_hint=float(_hint_u or 0.0))
                except Exception as _e:
                    _record_swallowed_exception('m9_open_single_chain_jitter_skip_apply', _e)
                return _normalize_request_amount_truth(req_any)
            if bool(meta.get('open_amount_jitter_skip')) or (str(mod).upper().strip() == 'B1' and bool(meta.get('b1_amount_locked') or meta.get('amount_locked_no_override') or meta.get('no_random_amount'))):
                return _normalize_request_amount_truth(req_any)
            coin = str(req.get('coin') or params.get('coin') or meta.get('coin') or '').upper().strip()
            plat = str(req.get('platform') or params.get('platform') or meta.get('platform') or '').upper().strip()
            side = str(req.get('side') or params.get('side') or meta.get('side') or '').upper().strip()
            amt = None
            for k in ('amount_usd', 'amount_usd_intent', 'intent_amount', 'usd', 'notional_u'):
                v = req.get(k, None)
                if v not in (None, '', 0, 0.0):
                    amt = v; break
            if amt in (None, '', 0, 0.0):
                for k in ('amount_usd', 'amount_usd_intent', 'intent_amount', 'usd', 'notional_u', 'add_notional_u', 'amount_u', 'amount', 'u'):
                    v = params.get(k, None)
                    if v not in (None, '', 0, 0.0):
                        amt = v; break
            try:
                amt_f = float(amt or 0.0)
            except Exception:
                amt_f = 0.0
            if amt_f <= 0.0:
                return req_any
            jitter_key = f"OPEN|{mod or 'NA'}|{coin or 'NA'}|{plat or 'NA'}|{side or 'NA'}"
            jitter_candidates = None
            jitter_mode = 'jitter_30u_tens'
            jitter_global_key = _OPEN_AMOUNT_GLOBAL_KEY
            if str(mod).upper().strip() == 'M9' and str(act).lower().strip() != 'decrease':
                try:
                    grid_obs = {}
                    if isinstance(meta.get('grid_decision_obs'), dict):
                        grid_obs = dict(meta.get('grid_decision_obs') or {})
                    elif isinstance(req.get('grid_decision_obs'), dict):
                        grid_obs = dict(req.get('grid_decision_obs') or {})
                    bucket_det = dict((grid_obs.get('bucket_det') or {}) if isinstance(grid_obs.get('bucket_det'), dict) else {})
                    lo = _safe_float(bucket_det.get('lo') or grid_obs.get('bucket_amount_lo_u'), 0.0)
                    hi = _safe_float(bucket_det.get('hi') or grid_obs.get('bucket_amount_hi_u'), 0.0)
                    _new_coin_contract = dict(_m9_new_coin_grid_contract_detail(req) or {})
                    _is_new_coin_grid_amount = bool((_new_coin_contract or {}).get('is_new_coin') or grid_obs.get('is_dynamic_new_coin') or bucket_det.get('amount_tag') == '(新)' or bucket_det.get('new_coin_grid_amount_truth_text'))
                    _layer_no = int(_safe_float(req.get('layer_no') or params.get('layer_no') or meta.get('layer_no') or grid_obs.get('layer_no') or bucket_det.get('layer_no'), 0.0) or 0)
                    picked_from_map = _safe_float(
                        ((_new_coin_contract or {}).get('expected_final_u') if _is_new_coin_grid_amount else None)
                        or grid_obs.get('final_amount_u')
                        or grid_obs.get('amount_u')
                        or grid_obs.get('amount_after_cap_u')
                        or grid_obs.get('amount_post_bucket_cap_u')
                        or bucket_det.get('picked_after_new_coin_scale')
                        or bucket_det.get('guess_u_after_new_coin_scale')
                        or bucket_det.get('picked')
                        or grid_obs.get('bucket_base_amount_u')
                        or grid_obs.get('coin_base_amount_u'),
                        0.0,
                    )
                    if picked_from_map > 0.0:
                        amt_f = float(picked_from_map)
                        if (not _is_new_coin_grid_amount) and lo > 0.0 and hi >= lo:
                            amt_f = min(float(hi), max(float(lo), float(amt_f)))
                        req['amount_usd'] = float(amt_f)
                        req['amount_usd_intent'] = float(amt_f)
                        req['intent_amount'] = float(amt_f)
                        req['final_amount_u'] = float(amt_f)
                        req['amount_u'] = float(amt_f)
                        req['notional_u'] = float(amt_f)
                        params['amount_usd'] = float(amt_f)
                        params['amount_usd_intent'] = float(amt_f)
                        params['intent_amount'] = float(amt_f)
                        params['final_amount_u'] = float(amt_f)
                        params['amount_u'] = float(amt_f)
                        params['notional_u'] = float(amt_f)
                        params['add_notional_u'] = float(amt_f)
                        meta['m9_amount_map_locked_u'] = float(amt_f)
                        meta['m9_amount_map_lock_source'] = ('grid_decision_obs.m9_rsi_leg_notional_pct(新)' if _is_new_coin_grid_amount else 'grid_decision_obs.m9_rsi_leg_notional_pct')
                        if _is_new_coin_grid_amount:
                            meta['new_coin_grid_amount_tag'] = '(新)'
                            meta['new_coin_grid_amount_truth_text'] = str(((_new_coin_contract or {}).get('truth_text')) or bucket_det.get('new_coin_grid_amount_truth_text') or grid_obs.get('new_coin_grid_amount_truth_text') or '(新)网格金额=本腿总名义×RSI线性百分比（底板1%，上限10%）→整十→单笔安全帽')
                            meta['new_coin_grid_formula_final_u'] = float(((_new_coin_contract or {}).get('expected_final_u')) or amt_f)
                            meta['new_coin_grid_expected_final_u'] = float(amt_f)
                            meta['new_coin_grid_contract_source'] = str(((_new_coin_contract or {}).get('source')) or 'new_coin_grid_final_contract')
                    _lo_wave = float(max(10.0, lo if (lo > 0.0 and hi >= lo) else amt_f - 10.0))
                    _hi_wave = float(max(_lo_wave, hi if (lo > 0.0 and hi >= lo) else amt_f + 10.0))
                    try:
                        _min_wave = float(_m9_layer_min_effective_u(_layer_no, is_dynamic_new_coin=_is_new_coin_grid_amount))
                    except Exception:
                        _min_wave = 60.0 if int(_layer_no or 0) == 2 else (10.0 if _is_new_coin_grid_amount else 40.0)
                    try:
                        _cap_wave = float(_new_coin_single_open_cap_u() if _is_new_coin_grid_amount else GRID_ADD_U_MAX_DEFAULT)
                    except Exception:
                        _cap_wave = 500.0 if _is_new_coin_grid_amount else 300.0
                    _lo_wave = float(max(_min_wave, _lo_wave, amt_f - 10.0))
                    _hi_wave = float(min(_cap_wave, max(_lo_wave, _hi_wave, amt_f + 10.0)))
                    _spread_steps = 2 if (abs(float(amt_f) - float(_lo_wave)) <= 1e-9 or abs(float(amt_f) - float(_hi_wave)) <= 1e-9) else 1
                    jitter_candidates = _build_wave_candidates_10u(amt_f, _lo_wave, _hi_wave, spread_steps=_spread_steps)
                    jitter_mode = ('m9_new_coin_wave_tens' if _is_new_coin_grid_amount else 'm9_bucket_wave_tens')
                    meta['m9_bucket_jitter_choices'] = list(jitter_candidates)
                    meta['m9_amount_wave_base_u'] = float(amt_f)
                    meta['m9_amount_wave_range_u'] = [float(_lo_wave), float(_hi_wave)]
                    meta['m9_amount_wave_layer_no'] = int(_layer_no or 0)
                except Exception:
                    jitter_candidates = None
                    jitter_mode = 'jitter_30u_tens'
            picked, det = _open_amount_no_repeat_pick(amt_f, key=jitter_key, candidates=jitter_candidates, mode=jitter_mode, global_key=jitter_global_key)
            if picked > 0.0:
                picked_f = float(picked)
                req['amount_usd'] = picked_f
                req['amount_usd_intent'] = picked_f
                req['intent_amount'] = picked_f
                req['final_amount_u'] = picked_f
                req['amount_u'] = picked_f
                req['notional_u'] = picked_f
                params['amount_usd'] = picked_f
                params['amount_usd_intent'] = picked_f
                params['intent_amount'] = picked_f
                params['final_amount_u'] = picked_f
                params['amount_u'] = picked_f
                params['notional_u'] = picked_f
                if str(mod).upper().strip() == 'M9' and str(act).lower().strip() != 'decrease':
                    params['add_notional_u'] = picked_f
                if str(mod).upper().strip() == 'B1':
                    params['B1__amount_usd'] = picked_f
                    meta['B1__amount_usd'] = picked_f
                meta['open_amount_jitter'] = dict(det)
                meta['open_amount_jitter_key'] = str(jitter_key)
                meta['open_amount_base_usd'] = float(det.get('base') or amt_f)
                meta['open_amount_final_usd'] = picked_f
                meta['amount_locked_final_u'] = picked_f
                _lock_source = ('m9_rsi_leg_notional_pct_final_locked_(新)' if (str(mod).upper().strip() == 'M9' and str(act).lower().strip() != 'decrease' and bool(meta.get('new_coin_grid_amount_tag') == '(新)' or (((meta.get('grid_decision_obs') or {}) if isinstance(meta.get('grid_decision_obs'), dict) else {}).get('amount_tag') == '(新)'))) else ('m9_rsi_leg_notional_pct_final_locked' if str(mod).upper().strip() == 'M9' and str(act).lower().strip() != 'decrease' else 'open_amount_jitter_locked'))
                _formula_new_final_u = _safe_float(meta.get('new_coin_grid_formula_final_u') or meta.get('new_coin_grid_expected_final_u'), 0.0)
                if _formula_new_final_u > 0.0:
                    meta['new_coin_grid_formula_final_u'] = float(_formula_new_final_u)
                    meta['new_coin_grid_expected_final_u'] = float(picked_f)
                    meta['new_coin_grid_wave_final_u'] = float(picked_f)
                    meta['new_coin_grid_wave_delta_u'] = float(picked_f - _formula_new_final_u)
                meta['amount_locked_source'] = _lock_source
                meta['amount_locked_no_override'] = True
                meta['amt_det'] = {
                    'ok': 1,
                    'reason': _lock_source,
                    'picked': picked_f,
                    'final_u': picked_f,
                    'u': picked_f,
                    'final_source': _lock_source,
                    'amount_truth_reason': str(meta.get('new_coin_grid_amount_truth_text') or ''),
                    'amount_model': ('m9_rsi_leg_notional_pct_floor1_cap10_round10' if meta.get('new_coin_grid_amount_tag') == '(新)' else ''),
                }
                req['params'] = params
                req['meta'] = meta
                req_any = _normalize_request_amount_truth(req_any)
                try:
                    safe_log(lambda: f"[{now_ts()}] [AMOUNT_LOCK] module={mod} coin={coin} platform={plat} action={act} locked={picked_f:.2f} source={_lock_source}")
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_345', _e)
                    pass
            return req_any
        return req_any
    except Exception:
        return req_any



def normalize_side(raw: Any) -> str:
    """全局方向标准化真相源。
    人话：M10/B2/组请求重建都只能认这一套，不再依赖误缩进在局部作用域里的残链 helper。
    """
    try:
        s = str(raw or '').strip().upper()
    except Exception:
        s = ''
    if s in ('BUY', 'LONG'):
        return 'LONG'
    if s in ('SELL', 'SHORT'):
        return 'SHORT'
    return s


def round_notional_usd(x: Any) -> float:
    try:
        xf = max(0.0, float(_safe_float(x, 0.0) or 0.0))
    except Exception:
        xf = 0.0
    if xf <= 0.0:
        return 0.0
    try:
        return float(max(10.0, round(xf / 10.0) * 10.0))
    except Exception:
        return float(max(10.0, xf))


def _uuid() -> str:
    try:
        return uuid.uuid4().hex
    except Exception:
        try:
            return f"uuid_fallback_{int(time.time() * 1000)}"
        except Exception:
            return 'uuid_fallback'


def _now_ts() -> float:
    try:
        return float(time.time())
    except Exception:
        return 0.0

def _m10_fill_required_fields(req: dict, snapshot: dict | None = None) -> dict:
    """M10 专用口径补齐与隔离：只输出标准字段 + M10__* 专用键，清理歧义键。
    关键补丁：koujing_a_3step 必须保住 GROUP + steps，不能被洗成单腿空壳。
    """
    try:
        if not isinstance(req, dict):
            return req
        if str(req.get("module") or "").upper().strip() != "M10":
            return req
        snap = snapshot or {}
        req = _m10_materialize_group_payload(dict(req), snapshot=snap)
        params = req.get("params") if isinstance(req.get("params"), dict) else {}
        meta = req.get("meta") if isinstance(req.get("meta"), dict) else {}

        coin = str(req.get("coin") or req.get("symbol") or params.get("coin") or meta.get("coin") or "").upper().strip()
        if coin:
            req["coin"] = coin
            params["M10__coin"] = coin
            meta["M10__coin"] = coin
        else:
            meta["M10__schema_error"] = "coin_missing"

        act = str(req.get("action_type") or params.get("action_type") or meta.get("action_type") or req.get("action") or "close").lower().strip()
        if not act:
            act = "close"
        req["action_type"] = act
        params["M10__action_type"] = act
        meta["M10__action_type"] = act

        _steps_any = []
        try:
            _steps_any = req.get("steps") or params.get("steps") or []
        except Exception:
            _steps_any = []

        plat = str(req.get("platform") or params.get("platform") or meta.get("platform") or req.get("plat") or "").upper().strip()
        if act == "koujing_a_3step":
            plat = "GROUP"
        elif plat not in ("EXT", "VAR"):
            plat = "EXT"
        req["platform"] = plat
        params["M10__platform"] = plat
        meta["M10__platform"] = plat

        side = str(req.get("side") or params.get("side") or meta.get("side") or "").upper().strip()
        if side not in ("LONG", "SHORT") and act == "koujing_a_3step":
            try:
                for _st in (_steps_any or []):
                    _a = str(_st.get("action") or _st.get("action_type") or "").lower().strip()
                    _s = normalize_side(_st.get("side"))
                    if _a in ("close_full", "close_all", "close") and _s in ("LONG", "SHORT"):
                        side = _s
                        break
            except Exception:
                pass
        if side not in ("LONG", "SHORT"):
            meta["M10__schema_error"] = meta.get("M10__schema_error") or "side_missing"
        else:
            req["side"] = side
            params["M10__side"] = side
            meta["M10__side"] = side

        try:
            amt = float(req.get("amount_usd") or params.get("amount_usd") or 0.0)
        except Exception:
            amt = 0.0

        if amt <= 0.0:
            try:
                for _k in ("close_notional_u", "close_u", "close_usd", "notional_u", "notional_usd", "usd", "u", "amount", "reduce_u", "dec_u"):
                    _v = params.get(_k, None)
                    if _v not in (None, "", 0):
                        try:
                            amt = float(_v)
                            break
                        except Exception:
                            continue
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

        if amt <= 0.0 and act == "koujing_a_3step":
            try:
                amt = float(_tp_extract_loss_close_notional_u(_steps_any, "") or 0.0)
            except Exception:
                amt = 0.0

        if amt > 0:
            req["amount_usd"] = amt
            params["amount_usd"] = amt
            params.setdefault("close_notional_u", amt)
            params["M10__amount_usd"] = amt
            meta["M10__amount_usd"] = amt
        else:
            meta["M10__schema_error"] = meta.get("M10__schema_error") or "amount_missing"

        if act == "koujing_a_3step":
            try:
                req = _m10_materialize_group_payload(req, snapshot=snap)
                params = req.get("params") if isinstance(req.get("params"), dict) else params
                meta = req.get("meta") if isinstance(req.get("meta"), dict) else meta
            except Exception:
                pass
            if not (isinstance(req.get("steps"), list) and req.get("steps")):
                meta["M10__schema_error"] = meta.get("M10__schema_error") or "steps_missing"

        meta["schema"] = "M10_SCHEMA_V3"
        meta["schema_module"] = "M10"
        meta["schema_ts"] = float(time.time())

        for k in ("plat", "usd", "notional_u", "add_notional_u", "action"):
            try:
                if k in req:
                    req.pop(k, None)
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

        for k in ("usd", "notional_u", "add_notional_u", "plat", "action"):
            try:
                if k in params:
                    params.pop(k, None)
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

        req["params"] = params
        req["meta"] = meta
        return req
    except Exception:
        return req

def _m9_fill_required_fields(req: dict, snapshot: dict | None = None) -> dict:
    """M9 专用口径补齐与隔离（含 GRID_TP/LOCAL_GRID_TP 也属于 M9 请求）。"""
    try:
        if not isinstance(req, dict):
            return req
        if str(req.get("module") or "").upper().strip() != "M9":
            return req
        params = req.get("params") if isinstance(req.get("params"), dict) else {}
        meta = req.get("meta") if isinstance(req.get("meta"), dict) else {}

        coin = str(req.get("coin") or req.get("symbol") or params.get("coin") or meta.get("coin") or "").upper().strip()
        if coin:
            req["coin"] = coin
            params["M9__coin"] = coin
            meta["M9__coin"] = coin
        else:
            meta["M9__schema_error"] = "coin_missing"

        act = str(req.get("action_type") or params.get("action_type") or meta.get("action_type") or req.get("action") or "").lower().strip()
        if not act:
            act = "increase"
        req["action_type"] = act
        params["M9__action_type"] = act
        meta["M9__action_type"] = act

        plat = str(req.get("platform") or params.get("platform") or meta.get("platform") or req.get("plat") or "").upper().strip()
        if plat not in ("EXT", "VAR"):
            meta["M9__schema_error"] = meta.get("M9__schema_error") or "platform_missing"
        else:
            req["platform"] = plat
            params["M9__platform"] = plat
            meta["M9__platform"] = plat

        side = str(req.get("side") or params.get("side") or meta.get("side") or "").upper().strip()
        if side in ("LONG", "SHORT"):
            req["side"] = side
            params["M9__side"] = side
            meta["M9__side"] = side
        else:
            meta["M9__schema_error"] = meta.get("M9__schema_error") or "side_missing"

        try:
            amt = float(req.get("amount_usd") or params.get("amount_usd") or 0.0)
        except Exception:
            amt = 0.0

        if (amt is None) or (float(amt or 0.0) <= 0.0):
            for _k in (
                "amount_u", "amount", "usd", "notional_u",
                "add_notional_u", "close_notional_u",
                "add_u", "close_u",
            ):
                try:
                    _v = req.get(_k) if isinstance(req, dict) else None
                except Exception:
                    _v = None
                if _v in (None, "", 0, 0.0):
                    try:
                        _v = params.get(_k) if isinstance(params, dict) else None
                    except Exception:
                        _v = None
                if _v in (None, "", 0, 0.0):
                    try:
                        _v = meta.get(_k) if isinstance(meta, dict) else None
                    except Exception:
                        _v = None
                try:
                    _f = float(_v) if _v not in (None, "", 0, 0.0) else 0.0
                except Exception:
                    _f = 0.0
                if _f > 0.0:
                    amt = _f
                    break

        if amt > 0:
            req["amount_usd"] = amt
            params["amount_usd"] = amt
            params["M9__amount_usd"] = amt
            meta["M9__amount_usd"] = amt
            try:
                if act == "decrease":
                    params["close_notional_u"] = float(params.get("close_notional_u") or amt)
                    params["M9__close_notional_u"] = float(params.get("close_notional_u") or amt)
                    meta["M9__close_notional_u"] = float(params.get("close_notional_u") or amt)
                    try:
                        if "add_notional_u" in params and float(params.get("add_notional_u") or 0.0) <= 0:
                            params.pop("add_notional_u", None)
                    except Exception as _e:
                        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

                else:
                    params["add_notional_u"] = float(params.get("add_notional_u") or amt)
                    params["M9__add_notional_u"] = float(params.get("add_notional_u") or amt)
                    meta["M9__add_notional_u"] = float(params.get("add_notional_u") or amt)
                    try:
                        if "close_notional_u" in params and float(params.get("close_notional_u") or 0.0) <= 0:
                            params.pop("close_notional_u", None)
                    except Exception as _e:
                        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

        else:
            meta["M9__schema_error"] = meta.get("M9__schema_error") or "amount_missing"

        try:
            gid = str(req.get("grid_id") or params.get("grid_id") or meta.get("grid_id") or "").strip()
            if gid:
                req["grid_id"] = gid
                params["grid_id"] = gid
                meta["grid_id"] = gid
            lid, ltag, lno = _executor_get_layer_info({"params": params, "meta": meta, **req})
            if lid:
                req["layer_id"] = lid
                params["layer_id"] = lid
                meta["layer_id"] = lid
            if act == "decrease" and lid:
                meta["tp_layer_id"] = str(meta.get("tp_layer_id") or lid)
                if isinstance(params, dict) and not params.get("tp_layer_id"):
                    params["tp_layer_id"] = lid
            if ltag and not meta.get("layer_tag"):
                meta["layer_tag"] = ltag
            if ltag and not params.get("layer_tag"):
                params["layer_tag"] = ltag
            if lno is not None:
                if meta.get("layer_no") is None:
                    meta["layer_no"] = int(lno)
                if params.get("layer_no") is None:
                    params["layer_no"] = int(lno)
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_346', _e)
            pass
        meta["schema"] = "M9_SCHEMA_V2"
        meta["schema_module"] = "M9"
        meta["schema_ts"] = float(time.time())

        for k in ("plat", "usd", "notional_u", "add_notional_u", "action"):
            try:
                if k in req:
                    req.pop(k, None)
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

        for k in ("usd", "notional_u", "add_notional_u", "plat", "action"):
            try:
                if k in params:
                    params.pop(k, None)
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

        req["params"] = params
        req["meta"] = meta
        return req
    except Exception:
        return req

def _x1_fill_required_fields(req: dict, snapshot: dict | None = None) -> dict:
    """X1 专用口径补齐与隔离（只加仓修复）。"""
    try:
        if not isinstance(req, dict):
            return req
        if str(req.get("module") or "").upper().strip() != "X1":
            return req
        params = req.get("params") if isinstance(req.get("params"), dict) else {}
        meta = req.get("meta") if isinstance(req.get("meta"), dict) else {}

        coin = str(req.get("coin") or params.get("coin") or meta.get("coin") or "").upper().strip()
        if coin:
            req["coin"] = coin
            params["X1__coin"] = coin
            meta["X1__coin"] = coin

        act_raw = str(req.get("action_type") or params.get("action_type") or meta.get("action_type") or req.get("action") or "").lower().strip()
        act = str(_canon_action_type(act_raw) or "").lower().strip()
        if act in ("", "unknown", "legacy_deleted", "fix", "balance"):
            act = ""
        try:
            if isinstance(snapshot, dict) and coin:
                epos = _get_position(snapshot or {}, coin, "EXT") or {}
                vpos = _get_position(snapshot or {}, coin, "VAR") or {}
                ext_has = bool(epos.get("has_position", False) or epos.get("side"))
                var_has = bool(vpos.get("has_position", False) or vpos.get("side"))
                if ext_has and var_has:
                    act = act or "increase"
                else:
                    act = act or "add_leg"
        except Exception:
            act = act or "increase"
        if not act:
            act = "increase"
        req["action_type"] = act
        params["X1__action_type"] = act
        meta["X1__action_type"] = act

        meta["schema"] = "X1_SCHEMA_V2"
        meta["schema_module"] = "X1"
        meta["schema_ts"] = float(time.time())
        plat = str(req.get("platform") or params.get("platform") or meta.get("platform") or "").upper().strip()
        side_req = _a1_norm_side(str(req.get("side") or params.get("side") or params.get("dir") or meta.get("side") or meta.get("dir") or "").strip())
        try:
            if (plat not in ("EXT", "VAR")) and isinstance(snapshot, dict) and coin:
                epos = _get_position(snapshot or {}, coin, "EXT") or {}
                vpos = _get_position(snapshot or {}, coin, "VAR") or {}
                en = _safe_float(epos.get("notional_u") or epos.get("notional") or 0.0)
                vn = _safe_float(vpos.get("notional_u") or vpos.get("notional") or 0.0)
                ext_has = bool(epos.get("has_position", False) or epos.get("side"))
                var_has = bool(vpos.get("has_position", False) or vpos.get("side"))
                if act == "add_leg":
                    if (not ext_has) and var_has:
                        plat = "EXT"
                    elif (not var_has) and ext_has:
                        plat = "VAR"
                if plat not in ("EXT", "VAR"):
                    plat = "EXT" if en <= vn else "VAR"
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

        if plat not in ("EXT", "VAR"):
            plat = "EXT"
            meta["X1__schema_error"] = meta.get("X1__schema_error") or "plat_missing_default_EXT"
        req["platform"] = plat
        params["platform"] = plat
        meta["X1__platform"] = plat

        try:
            if side_req not in ("LONG", "SHORT") and isinstance(snapshot, dict) and coin:
                epos = _get_position(snapshot or {}, coin, "EXT") or {}
                vpos = _get_position(snapshot or {}, coin, "VAR") or {}
                ref = epos if plat == "EXT" else vpos
                ref_side = _a1_norm_side(str(ref.get("side") or ""))
                if act == "add_leg":
                    other = vpos if plat == "EXT" else epos
                    other_side = _a1_norm_side(str(other.get("side") or ""))
                    if other_side in ("LONG","SHORT"):
                        side_req = "SHORT" if other_side == "LONG" else "LONG"
                    elif ref_side in ("LONG","SHORT"):
                        side_req = ref_side
                else:
                    if ref_side in ("LONG","SHORT"):
                        side_req = ref_side
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

        if side_req not in ("LONG", "SHORT"):
            side_req = "LONG"
            meta["X1__schema_error"] = meta.get("X1__schema_error") or "side_missing_default_LONG"
        params["side"] = side_req
        meta["X1__side"] = side_req

        amt = _safe_float(
            req.get("amount_usd") if isinstance(req.get("amount_usd"), (int,float,str)) else
            params.get("amount_usd") or params.get("usd") or params.get("notional_u") or params.get("add_notional_u") or params.get("close_notional_u") or 0.0
        )
        if amt <= 0:
            amt = _safe_float(meta.get("diff_u") or meta.get("need_u") or meta.get("legacy_deleted_u") or 0.0)
        if amt <= 0:
            meta["X1__schema_error"] = meta.get("X1__schema_error") or "amount_missing"
        if act == "decrease":
            params["close_notional_u"] = _safe_float(params.get("close_notional_u") or amt or 0.0)
            params.setdefault("add_notional_u", params.get("close_notional_u"))
        else:
            params["add_notional_u"] = _safe_float(params.get("add_notional_u") or amt or 0.0)

        meta["schema"] = "X1_SCHEMA_V3"
        meta["schema_module"] = "X1"
        meta["schema_ts"] = float(time.time())

        req["params"] = params
        req["meta"] = meta
        return req
    except Exception:
        return req

def _legacy_deleted_fill_required_fields(req: dict, snapshot: dict | None = None) -> dict:
    """
    旧修复链专用口径（已删除，仅保留历史兼容壳，严禁进入主链）。
    - 只做“缺失口径补齐 + 清理歧义键 + 写 schema 标记”
    - 不改触发条件/阈值/优先级，不改变策略核心
    """
    try:
        if not isinstance(req, dict):
            return req
        if str(req.get("module") or "").upper().strip() != MOD_LEGACY_FIX:
            return req

        snap = snapshot or {}
        params = req.get("params") if isinstance(req.get("params"), dict) else {}
        meta = req.get("meta") if isinstance(req.get("meta"), dict) else {}

        coin = str(req.get("coin") or req.get("symbol") or params.get("coin") or meta.get("coin") or "").upper().strip()
        if coin:
            req["coin"] = coin
            params["LEGFIX__coin"] = coin
        try:
            at0 = str(req.get('action_type') or req.get('action') or '').upper()
            why0 = str(params.get('why') or meta.get('why') or '')
            why_l = why0.lower()
            if at0 in ('ADD_SINGLE', 'ADD_PAIR', ACT_LEGACY_FIX_ONE_SHOT, 'ONE_SHOT', 'FILL_LEG') and any(k in why_l for k in ('missing_leg','severe_gap','one_shot',TXT_LEGACY_FIX,'补腿','修复')):
                meta['safe_b1_missing_leg'] = True
                meta.setdefault('safe_reason', 'legacy_fix_one_shot')
                params['LEGFIX__safe_legacy_fix'] = 1
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_347', _e)
            pass
        act = str(req.get("action_type") or params.get("action_type") or meta.get("action_type") or req.get("action") or "").lower().strip()
        if not act:
            act = "add_leg"
        req["action_type"] = act
        params["LEGFIX__action_type"] = act
        meta["LEGFIX__action_type"] = act

        plat = str(req.get("platform") or params.get("platform") or meta.get("platform") or req.get("plat") or "").upper().strip()
        if plat not in ("EXT", "VAR"):
            try:
                cu = coin
                if cu:
                    try:
                        epos = (((snap or {}).get("positions") or {}).get("EXT") or {}).get(cu) or {}
                    except Exception:
                        epos = {}
                    try:
                        vpos = (((snap or {}).get("positions") or {}).get("VAR") or {}).get(cu) or {}
                    except Exception:
                        vpos = {}
                    def _legacy_deleted_notional_u(p: dict) -> float:
                        try:
                            if not isinstance(p, dict):
                                return 0.0
                            for k in ("notional_u","notional_usd","value_u","value_usd","notional","positionValue","notionalUsd"):
                                vv = p.get(k)
                                if vv not in (None, "", 0):
                                    try:
                                        return float(abs(float(vv)))
                                    except Exception:
                                        continue
                            return 0.0
                        except Exception:
                            return 0.0
                    en = _legacy_deleted_notional_u(epos)
                    vn = _legacy_deleted_notional_u(vpos)
                    if en <= 1.0 and vn > 1.0:
                        plat = "EXT"
                    elif vn <= 1.0 and en > 1.0:
                        plat = "VAR"
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

        if plat not in ("EXT", "VAR"):
            plat = "EXT"
            meta["LEGFIX__schema_error"] = meta.get("LEGFIX__schema_error") or "platform_missing_default_EXT"
        req["platform"] = plat
        params["LEGFIX__platform"] = plat
        meta["LEGFIX__platform"] = plat

        side = str(req.get("side") or params.get("side") or meta.get("side") or params.get("pos_side") or "").upper().strip()
        if side not in ("LONG", "SHORT"):
            try:
                cu = coin
                other_plat = "VAR" if plat == "EXT" else "EXT"
                try:
                    opos = (((snap or {}).get("positions") or {}).get(other_plat) or {}).get(cu) or {}
                except Exception:
                    opos = {}
                oside = str(opos.get("side") or opos.get("position_side") or opos.get("pos_side") or "").upper().strip()
                if oside == "LONG":
                    side = "SHORT"
                elif oside == "SHORT":
                    side = "LONG"
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

        if side not in ("LONG", "SHORT"):
            side = "LONG"
            meta["LEGFIX__schema_error"] = meta.get("LEGFIX__schema_error") or "side_missing_default_LONG"
        req["side"] = side
        params["LEGFIX__side"] = side
        meta["LEGFIX__side"] = side

        def _legacy_deleted_pick_amt(obj: dict) -> float:
            try:
                if not isinstance(obj, dict):
                    return 0.0
                for k in ("amount_usd", "amount_usd_intent", "usd", "notional_u", "add_notional_u"):
                    vv = obj.get(k)
                    if vv not in (None, "", 0):
                        try:
                            return float(vv)
                        except Exception:
                            continue
                return 0.0
            except Exception:
                return 0.0

        amt = _legacy_deleted_pick_amt(req) or _legacy_deleted_pick_amt(params) or _legacy_deleted_pick_amt(meta)
        if amt <= 0.0:
            try:
                cu = coin
                other_plat = "VAR" if plat == "EXT" else "EXT"
                try:
                    p_this = (((snap or {}).get("positions") or {}).get(plat) or {}).get(cu) or {}
                except Exception:
                    p_this = {}
                try:
                    p_oth = (((snap or {}).get("positions") or {}).get(other_plat) or {}).get(cu) or {}
                except Exception:
                    p_oth = {}
                def _legacy_deleted_notional_u2(p: dict) -> float:
                    try:
                        if not isinstance(p, dict):
                            return 0.0
                        for k in ("notional_u","notional_usd","value_u","value_usd","notional","positionValue","notionalUsd"):
                            vv = p.get(k)
                            if vv not in (None, "", 0):
                                try:
                                    return float(abs(float(vv)))
                                except Exception:
                                    continue
                        return 0.0
                    except Exception:
                        return 0.0
                n_this = _legacy_deleted_notional_u2(p_this)
                n_oth = _legacy_deleted_notional_u2(p_oth)
                diff = max(0.0, float(n_oth) - float(n_this))
                try:
                    amt = float(int((diff + 5.0) // 10) * 10)
                except Exception:
                    amt = diff
            except Exception:
                amt = 0.0
        try:
            amt = float(max(10.0, float(amt or 0.0)))
        except Exception:
            amt = 10.0

        req["amount_usd"] = amt
        params["amount_usd"] = amt  # executor 常用字段
        params["LEGFIX__amount_usd"] = amt
        meta["LEGFIX__amount_usd"] = amt

        meta["schema"] = "LEGACY_FIX_SCHEMA_V1"
        meta["schema_module"] = MOD_LEGACY_FIX
        try:
            import time as _time
            meta["schema_ts"] = float(_time.time())
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

        for k in ("plat", "usd", "notional_u", "add_notional_u", "action"):
            try:
                if k in req:
                    req.pop(k, None)
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

        for k in ("usd", "notional_u", "add_notional_u", "plat", "action"):
            try:
                if k in params:
                    params.pop(k, None)
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

        req["params"] = params
        req["meta"] = meta
        return req
    except Exception:
        return req

def _b1_scale_first_open_amount(u: Any, *, req: dict | None = None, coin: str = "", platform: str = "", side: str = "") -> float:
    """B1 首次开仓金额统一放大后整十；新币不再额外做 1/4 缩放。

    注意：策略真相源是"新币总硬顶=1000U"，不是"B1 首开固定上限=1000U"。
    这里若触发 single_open_cap，只应视为单笔安全帽，不得替代总硬顶口径。
    """
    try:
        base_u = float(u or 0.0)
    except Exception:
        base_u = 0.0
    if base_u <= 0.0:
        return 0.0
    try:
        coin_u = str(coin or (req or {}).get('coin') or '').upper().strip()
    except Exception:
        coin_u = ''
    try:
        mul = float(cfg_getf_runtime("B1_FIRST_OPEN_AMOUNT_MULTIPLIER", 1.0) or 1.0)
    except Exception:
        mul = 1.0
    if mul <= 0.0:
        mul = 1.0
    scaled = float(base_u) * float(mul)
    try:
        scaled = float(int((scaled + 5.0) // 10) * 10)
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_348', _e)
        pass
    if scaled > 0.0:
        scaled = max(float(_b1_first_open_min_effective_u()), float(scaled))
    scaled_before_new_coin_cap = float(scaled)
    scaled = _dynamic_new_coin_round_clamp_u(scaled, coin_u)
    try:
        _pin("B1_FIRST_OPEN_AMOUNT_SCALE", mod="B1", coin=str(coin_u or '-').upper() or "-", ok=1,
             reason=f"base={base_u:.4f}|mul={mul:.4f}|scaled={scaled:.4f}|scaled_raw={scaled_before_new_coin_cap:.4f}|b1_min={float(_b1_first_open_min_effective_u()):.4f}|plat={str(platform or '').upper()}|side={str(side or '').upper()}",
             stage="B1_AMOUNT_SCALE", trace=str((req or {}).get("id") or (req or {}).get("req_id") or ""))
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_349', _e)
        pass
    return max(0.0, float(scaled))

def _b1_pick_u_in_bucket_no_repeat(coin: str, side: str, rsi: float | None, req_id: str | None = None) -> tuple[float, dict]:
    """B1 首次开仓/补齐单腿：**严格遵守 RSI 门禁**（rsi>50 只允许 LONG；rsi<50 只允许 SHORT；rsi==50/None 不允许）。

    返回：(picked_u, detail_dict)
    """
    det: dict = {
        "ok": False,
        "coin": str(coin or "").upper(),
        "platform": "PAIR",
        "side": str(side or "").upper(),
        "rsi": rsi,
        "req_id": req_id,
        "bucket": None,
        "lo": None,
        "hi": None,
        "target": None,
        "picked": None,
        "reason": "",
    }
    c = det["coin"]; p = det["platform"]; s = det["side"]

    if s not in ("LONG", "SHORT"):
        det["reason"] = f"bad_side:{s}"
        return 0.0, det

    try:
        u_floor = float(GRID_ADD_U_MIN_DEFAULT)
        u_ceil = float(GRID_ADD_U_MAX_DEFAULT)
    except Exception:
        u_floor, u_ceil = 40.0, 300.0
    _b1_min_u = float(_b1_first_open_min_effective_u())
    u_floor = max(float(u_floor), float(_b1_min_u))
    u_ceil = max(float(u_ceil), float(u_floor))
    if _coin_pool_is_dynamic_new_coin(c):
        try:
            _cap_new = float(_new_coin_single_open_cap_u())
            u_floor = max(float(_b1_min_u), min(float(u_floor), float(_cap_new)))
            u_ceil = max(u_floor, min(float(u_ceil), float(_cap_new)))
        except Exception:
            u_floor, u_ceil = float(_b1_min_u), float(_new_coin_single_open_cap_u())

    try:
        picked, det2 = _grid_pick_u_in_bucket_no_repeat(
            str(c), str(p), str(s),
            rsi=float(rsi) if rsi is not None else None,
            last_map=globals().get('_RSI_LAST_PICK_U') or {},
            u_floor=float(u_floor), u_ceil=float(u_ceil),
            max_retry=8,
            req_mod='B1',
            action_type='open_leg',
            req_id=str(req_id or ''),
        )
        if picked is None or float(picked) <= 0:
            try:
                det.update({"reason": str((det2 or {}).get("reason") or "pick_none"), "bucket": (det2 or {}).get("bucket")})
            except Exception:
                det["reason"] = "pick_none"
            return 0.0, det
        det2 = dict(det2 or {})
        det2.setdefault("coin", c)
        det2.setdefault("platform", p)
        det2.setdefault("side", s)
        det2.setdefault("req_id", req_id)
        det2.setdefault("rsi", rsi)
        det2["ok"] = True
        return float(picked), det2
    except Exception as _e:
        det["reason"] = f"pick_exc:{_e}"
        return 0.0, det
def _b1_pick_entry_platform_detail(coin: Any, side: Any = None, snapshot: dict | None = None) -> tuple[str, dict]:
    """
    B1 单腿首开平台选择：优先把 EXT/VAR 的整体多空结构拉回镜像平衡。

    爸爸最新口径：
    - 如果 EXT 当前是 5多5空，VAR 最好也是接近 5多5空；
    - 单方向允许轻微偏差，但尽量把 EXT/VAR 同方向腿数差压到 <=1；
    - 人机验证平台优先避开；在平衡分相同的前提下，再做稳定可复现的 tie-break。
    """
    try:
        coin_s = str(coin or '').upper().strip()
    except Exception:
        coin_s = ''
    try:
        side_s = str(side or '').upper().strip()
    except Exception:
        side_s = ''
    snap = snapshot or {}
    detail = {
        'coin': coin_s,
        'side': side_s,
        'selected_platform': '',
        'selection_mode': 'mirror_balance',
        'hv_ext': False,
        'hv_var': False,
        'ext_long': 0,
        'ext_short': 0,
        'var_long': 0,
        'var_short': 0,
        'ext_score': {},
        'var_score': {},
        'reason': '',
    }
    try:
        hv = ((snap or {}).get('raw') or {}).get('human_verify') or {}
        hv_ext = bool((hv.get('EXT') or {}).get('active')) if isinstance(hv, dict) else False
        hv_var = bool((hv.get('VAR') or {}).get('active')) if isinstance(hv, dict) else False
        detail['hv_ext'] = bool(hv_ext)
        detail['hv_var'] = bool(hv_var)
        if hv_ext and not hv_var:
            detail['selected_platform'] = 'VAR'
            detail['reason'] = 'human_verify_ext_active_choose_var'
            return 'VAR', detail
        if hv_var and not hv_ext:
            detail['selected_platform'] = 'EXT'
            detail['reason'] = 'human_verify_var_active_choose_ext'
            return 'EXT', detail
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_350', _e)
        pass

    try:
        ext_long, ext_short, _ = _count_platform_ls_from_snapshot(snap, 'EXT')
        var_long, var_short, _ = _count_platform_ls_from_snapshot(snap, 'VAR')
    except Exception:
        ext_long = ext_short = var_long = var_short = 0
    detail.update({
        'ext_long': int(ext_long),
        'ext_short': int(ext_short),
        'var_long': int(var_long),
        'var_short': int(var_short),
    })

    if side_s not in ('LONG', 'SHORT'):
        seed = f"{coin_s}|{side_s}"
        try:
            hvv = sum(ord(ch) for ch in seed)
        except Exception:
            hvv = 0
        chosen = 'EXT' if (hvv % 2 == 0) else 'VAR'
        detail['selected_platform'] = chosen
        detail['selection_mode'] = 'seed_fallback'
        detail['reason'] = 'side_invalid_seed_fallback'
        return chosen, detail

    def _score_for(pl: str) -> dict:
        post = {
            'EXT_LONG': int(ext_long), 'EXT_SHORT': int(ext_short),
            'VAR_LONG': int(var_long), 'VAR_SHORT': int(var_short),
        }
        post[f'{pl}_{side_s}'] += 1
        long_diff = abs(int(post['EXT_LONG']) - int(post['VAR_LONG']))
        short_diff = abs(int(post['EXT_SHORT']) - int(post['VAR_SHORT']))
        target_diff = long_diff if side_s == 'LONG' else short_diff
        opp_diff = short_diff if side_s == 'LONG' else long_diff
        total_ext = int(post['EXT_LONG']) + int(post['EXT_SHORT'])
        total_var = int(post['VAR_LONG']) + int(post['VAR_SHORT'])
        total_diff = abs(total_ext - total_var)
        overflow_penalty = max(0, target_diff - 1)
        mirror_penalty = overflow_penalty + max(0, opp_diff - 1)
        return {
            'platform': pl,
            'post_ext_long': int(post['EXT_LONG']),
            'post_ext_short': int(post['EXT_SHORT']),
            'post_var_long': int(post['VAR_LONG']),
            'post_var_short': int(post['VAR_SHORT']),
            'target_side_diff': int(target_diff),
            'opposite_side_diff': int(opp_diff),
            'platform_total_diff': int(total_diff),
            'overflow_penalty': int(overflow_penalty),
            'mirror_penalty': int(mirror_penalty),
            'score_tuple': (int(mirror_penalty), int(target_diff), int(total_diff), int(opp_diff), 0 if pl == 'EXT' else 1),
        }

    ext_score = _score_for('EXT')
    var_score = _score_for('VAR')
    detail['ext_score'] = dict(ext_score)
    detail['var_score'] = dict(var_score)

    if tuple(ext_score['score_tuple']) <= tuple(var_score['score_tuple']):
        chosen = 'EXT'
        detail['reason'] = 'mirror_balance_score_ext_le_var'
    else:
        chosen = 'VAR'
        detail['reason'] = 'mirror_balance_score_var_lt_ext'
    detail['selected_platform'] = chosen
    return chosen, detail

def _b1_pick_entry_platform(coin: Any, side: Any = None, snapshot: dict | None = None) -> str:
    try:
        chosen, _detail = _b1_pick_entry_platform_detail(coin, side, snapshot)
        return str(chosen or 'EXT')
    except Exception:
        try:
            coin_s = str(coin or '').upper().strip()
        except Exception:
            coin_s = ''
        try:
            side_s = str(side or '').upper().strip()
        except Exception:
            side_s = ''
        seed = f"{coin_s}|{side_s}"
        try:
            hvv = sum(ord(ch) for ch in seed)
        except Exception:
            hvv = 0
        return 'EXT' if (hvv % 2 == 0) else 'VAR'

def _b1_fill_required_fields(req: dict, snapshot: dict | None = None) -> dict:
    """
    B1（首次开仓）专用口径（独立于其它模块，严禁共用）。
    - 默认优先单腿首开；只有显式 open_pair 时才走双腿 schema。
    - 如果上游没给金额，本函数不强行改变策略，只做字段兜底。
    """
    try:
        if not isinstance(req, dict):
            return req
        if str(req.get("module") or "").upper().strip() != "B1":
            return req

        snap = snapshot or {}
        params = req.get("params") if isinstance(req.get("params"), dict) else {}
        meta = req.get("meta") if isinstance(req.get("meta"), dict) else {}
        req["params"], req["meta"] = params, meta

        coin = str(req.get("coin") or req.get("symbol") or params.get("coin") or meta.get("coin") or "").upper().strip()
        if coin:
            req["coin"] = coin
            params["B1__coin"] = coin
            meta["B1__coin"] = coin
        else:
            meta["B1__schema_error"] = meta.get("B1__schema_error") or "coin_missing"

        act = str(req.get("action_type") or params.get("action_type") or meta.get("action_type") or req.get("action") or "").lower().strip()
        if not act:
            act = "open_leg"
        req["action_type"] = act
        params["B1__action_type"] = act
        meta["B1__action_type"] = act

        is_single_leg = act in ("open_leg", "open_single_leg", "open_single", "open", "open_first", "open_more")
        plat_raw = str(req.get("platform") or params.get("platform") or meta.get("platform") or "").upper().strip()
        b1_platform_pick_detail = {}
        if is_single_leg:
            if plat_raw in ("EXT", "VAR"):
                plat = plat_raw
                b1_platform_pick_detail = {'selected_platform': plat, 'selection_mode': 'explicit_platform_keep', 'reason': 'upstream_platform_explicit'}
            else:
                plat, b1_platform_pick_detail = _b1_pick_entry_platform_detail(coin, req.get("side") or params.get("side") or meta.get("side"), snap)
        else:
            plat = plat_raw if plat_raw in ("PAIR", "GROUP", "BOTH") else "PAIR"
        req["platform"] = plat
        params["B1__platform"] = plat
        meta["B1__platform"] = plat

        def _pick_amt(obj: dict) -> float:
            try:
                if not isinstance(obj, dict):
                    return 0.0
                for k in ("amount_usd", "amount_usd_intent", "intent_amount", "usd", "notional_u", "W1__amount_usd", "W1__amount_u"):
                    vv = obj.get(k)
                    if vv not in (None, "", 0):
                        try:
                            return float(vv)
                        except Exception:
                            continue
                return 0.0
            except Exception:
                return 0.0

        amt = _pick_amt(req) or _pick_amt(params) or _pick_amt(meta)

        def _b1_missing_leg_target_notional_u() -> tuple[float, dict]:
            detail = {'ok': False, 'mode': 'not_missing_leg'}
            try:
                _reason_source = str(meta.get('reason_source') or '').lower().strip()
            except Exception:
                _reason_source = ''
            missing_mode = bool(meta.get('missing_leg_mode')) or (_reason_source == 'missing_leg_b1')
            detail['missing_leg_mode'] = bool(missing_mode)
            if not missing_mode:
                return 0.0, detail
            ext_side, ext_notional = _a1_extract_leg(snap if isinstance(snap, dict) else {}, coin, 'EXT')
            var_side, var_notional = _a1_extract_leg(snap if isinstance(snap, dict) else {}, coin, 'VAR')
            ext_has = str(ext_side or '').upper().strip() in ('LONG', 'SHORT') and float(ext_notional or 0.0) > float(B1_NO_LEG_EPS_U)
            var_has = str(var_side or '').upper().strip() in ('LONG', 'SHORT') and float(var_notional or 0.0) > float(B1_NO_LEG_EPS_U)
            detail.update({
                'ext_side': str(ext_side or '').upper().strip(),
                'ext_notional_u': float(ext_notional or 0.0),
                'var_side': str(var_side or '').upper().strip(),
                'var_notional_u': float(var_notional or 0.0),
                'ext_has_leg': bool(ext_has),
                'var_has_leg': bool(var_has),
            })
            if bool(ext_has) == bool(var_has):
                detail['mode'] = 'scene_invalid'
                return 0.0, detail
            existing_platform = 'EXT' if ext_has else 'VAR'
            target_raw = float(ext_notional if ext_has else var_notional)
            try:
                target_round10 = float(int((float(target_raw) + 5.0) // 10) * 10)
            except Exception:
                target_round10 = float(target_raw)
            detail.update({
                'ok': bool(target_round10 > 0.0),
                'mode': 'missing_leg_mirror_notional_round10',
                'existing_platform': existing_platform,
                'target_raw_u': float(target_raw),
                'target_round10_u': float(target_round10),
            })
            return max(0.0, float(target_round10)), detail

        if is_single_leg:
            side0 = str(req.get("side") or params.get("side") or meta.get("side") or "").upper().strip()
            if side0 not in ("LONG", "SHORT"):
                side0 = "LONG"
            req["side"] = side0
            params["side"] = side0
            meta["side"] = side0
            params["platform"] = plat
            meta["platform"] = plat
            meta["b1_leg_plat"] = plat
            meta["b1_leg_side"] = side0
            try:
                meta["b1_platform_pick_detail"] = dict(b1_platform_pick_detail or {})
            except Exception:
                meta["b1_platform_pick_detail"] = {}
            _force_rsi_amount = bool(_coin_pool_is_dynamic_new_coin(coin))
            _missing_leg_target_u, _missing_leg_target_det = _b1_missing_leg_target_notional_u()
            _missing_leg_amount_override = bool(float(_missing_leg_target_u or 0.0) > 0.0)
            try:
                meta["b1_missing_leg_amount_detail"] = dict(_missing_leg_target_det or {})
            except Exception:
                meta["b1_missing_leg_amount_detail"] = {}
            try:
                meta.setdefault("extras", {})
                if isinstance(meta.get("extras"), dict):
                    meta["extras"]["b1_leg_plat"] = plat
                    meta["extras"]["b1_leg_side"] = side0
                    meta["extras"]["force_rsi_amount"] = int(_force_rsi_amount)
                    meta["extras"]["b1_platform_pick_detail"] = dict(b1_platform_pick_detail or {})
                    meta["extras"]["b1_missing_leg_amount_override"] = int(_missing_leg_amount_override)
                    meta["extras"]["b1_missing_leg_amount_detail"] = dict(_missing_leg_target_det or {})
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_351', _e)
                pass
            _locked_b1_u = _coerce_final_amount_u(meta.get("amount_locked_final_u"))
            if bool(meta.get("amount_locked_no_override")) and _locked_b1_u > 0.0:
                # Schema completion is repeatable: never rerun RSI sizing, scaling
                # or rounding after the request amount (including cap trimming) is set.
                amt = _lock_b1_first_open_amount_contract(
                    req, _locked_b1_u,
                    source=str(meta.get("amount_locked_source") or "b1_first_open_scaled_single_source"),
                )
            elif _missing_leg_amount_override:
                amt = float(_missing_leg_target_u)
                req["amount_usd"] = float(amt)
                req["amount_usd_intent"] = float(amt)
                req["intent_amount"] = float(amt)
                params["amount_usd"] = float(amt)
                params["amount_usd_intent"] = float(amt)
                params["intent_amount"] = float(amt)
                params["B1__amount_usd"] = float(amt)
                meta["B1__amount_usd"] = float(amt)
                meta["b1_amount_mode"] = 'missing_leg_match_opposite_notional_round10'
                try:
                    meta.setdefault("extras", {})
                    if isinstance(meta.get("extras"), dict):
                        meta["extras"]["amount_usd_intent"] = float(amt)
                        meta["extras"]["b1_amount_mode"] = 'missing_leg_match_opposite_notional_round10'
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_351a', _e)
                    pass
                _lock_b1_first_open_amount_contract(req, float(amt), source='b1_missing_leg_match_opposite_notional_round10')
                try:
                    _pin("B1_FIRST_OPEN_AMOUNT_SCALE", mod="B1", coin=str(coin or '-').upper() or "-", ok=1,
                         reason=f"mode=missing_leg_match_opposite_notional_round10|amt={float(amt):.4f}|plat={str(plat or '').upper()}|side={str(side0 or '').upper()}|existing_platform={str((_missing_leg_target_det or {}).get('existing_platform') or '').upper()}",
                         stage="B1_AMOUNT_SCALE", trace=str((req or {}).get("id") or (req or {}).get("req_id") or ""))
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_351b', _e)
                    pass
            elif amt > 0.0 and (not _force_rsi_amount):
                try:
                    amt = float(int((amt + 5.0) // 10) * 10)
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_352', _e)
                    pass
                amt = _b1_scale_first_open_amount(amt, req=req, coin=str(coin), platform=str(plat), side=str(side0))
                req["amount_usd"] = float(amt)
                req["amount_usd_intent"] = float(amt)
                req["intent_amount"] = float(amt)
                params["amount_usd"] = float(amt)
                params["amount_usd_intent"] = float(amt)
                params["intent_amount"] = float(amt)
                params["B1__amount_usd"] = float(amt)
                meta["B1__amount_usd"] = float(amt)
                try:
                    meta.setdefault("extras", {})
                    if isinstance(meta.get("extras"), dict):
                        meta["extras"]["amount_usd_intent"] = float(amt)
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_352a', _e)
                    pass
                _lock_b1_first_open_amount_contract(req, float(amt), source='b1_first_open_scaled_single_source')
            else:
                _b1_rsi = _snap_get_rsi(snap, coin)
                _b1_u = 0.0
                _b1_det = {}
                try:
                    _b1_u, _b1_det = _b1_pick_u_in_bucket_no_repeat(str(coin), str(side0), rsi=_b1_rsi, req_id=str((req or {}).get('id') or (req or {}).get('req_id') or ''))
                except Exception as _e:
                    _log_exc(mod="SYS", stage="B1_AMOUNT_PICK_EXC", e=_e)
                    _b1_u = 0.0
                if float(_b1_u or 0.0) > 0.0:
                    _b1_u = _b1_scale_first_open_amount(_b1_u, req=req, coin=str(coin), platform=str(plat), side=str(side0))
                req["amount_usd"] = float(_b1_u)
                req["amount_usd_intent"] = float(_b1_u)
                req["intent_amount"] = float(_b1_u)
                params["amount_usd"] = float(_b1_u)
                params["amount_usd_intent"] = float(_b1_u)
                params["intent_amount"] = float(_b1_u)
                params["B1__amount_usd"] = float(_b1_u)
                meta["B1__amount_usd"] = float(_b1_u)
                try:
                    meta.setdefault("extras", {})
                    if isinstance(meta.get("extras"), dict):
                        meta["extras"]["amount_usd_intent"] = float(_b1_u)
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_353', _e)
                    pass
                _lock_b1_first_open_amount_contract(req, float(_b1_u), source='b1_first_open_scaled_single_source')
                try:
                    if isinstance(_b1_det, dict):
                        _b1_det.update({"coin": str(coin), "platform": str(plat), "picked": float(_b1_u), "force_rsi_amount": int(_force_rsi_amount)})
                    _rsi_amount_pin(_b1_det, stage="B1_FILL_RSI_MAP")
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_354', _e)
                    pass
            params.pop("legs", None)
            req.pop("legs", None)
        else:
            legs = params.get("legs")
            if not isinstance(legs, list):
                legs = []

            def _mk_leg(p: str, s: str) -> dict:
                return {"platform": str(p).upper(), "side": str(s).upper()}

            def _norm_leg(lg: dict) -> dict:
                try:
                    if not isinstance(lg, dict):
                        return {}
                    lp = str(lg.get("platform") or lg.get("plat") or "").upper().strip()
                    ls = str(lg.get("side") or lg.get("pos_side") or lg.get("direction") or "").upper().strip()
                    if lp not in ("EXT", "VAR"):
                        return {}
                    if ls not in ("LONG", "SHORT"):
                        ls = ""
                    out = {"platform": lp, "side": ls}
                    if lg.get("amount_usd") not in (None, "", 0):
                        try:
                            out["amount_usd"] = float(lg.get("amount_usd"))
                        except Exception as _e:
                            _record_swallowed_exception('except_pass_line_355', _e)
                            pass
                    return out
                except Exception:
                    return {}

            legs2 = []
            for lg in legs:
                nl = _norm_leg(lg)
                if nl:
                    legs2.append(nl)

            have_ext = any(l.get("platform") == "EXT" for l in legs2)
            have_var = any(l.get("platform") == "VAR" for l in legs2)

            if not have_ext:
                legs2.append(_mk_leg("EXT", "LONG"))
            if not have_var:
                legs2.append(_mk_leg("VAR", "SHORT"))
            if amt > 0.0:
                try:
                    amt = float(int((amt + 5.0) // 10) * 10)
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_356', _e)
                    pass
                for l in legs2:
                    if l.get("amount_usd") in (None, "", 0):
                        l["amount_usd"] = float(amt)
                req["amount_usd"] = float(amt)
                req["amount_usd_intent"] = float(amt)
                req["intent_amount"] = float(amt)
                params["amount_usd"] = float(amt)
                params["amount_usd_intent"] = float(amt)
                params["intent_amount"] = float(amt)
                params["B1__amount_usd"] = float(amt)
                meta["B1__amount_usd"] = float(amt)
            params["legs"] = legs2

        meta["schema"] = "B1_SCHEMA_V1"
        meta["schema_module"] = "B1"
        try:
            import time as _time
            meta["schema_ts"] = float(_time.time())
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_357', _e)
            pass
        req["params"] = params
        req["meta"] = meta

        for k in ("plat", "usd", "notional_u", "add_notional_u", "action"):
            try:
                if k in req:
                    req.pop(k, None)
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_358', _e)
                pass
        for k in ("usd", "notional_u", "add_notional_u", "plat", "action"):
            try:
                if k in params:
                    params.pop(k, None)
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_359', _e)
                pass
        return req
    except Exception:
        return req

def _z1_fill_required_fields(req: dict, snapshot: dict | None = None) -> dict:
    """
    Z1（止盈兜底次循环）专用口径。
    注意：本脚本里 Z1 通常会生成 B2/M10/M9 的请求而非 module=Z1；
    这里仅对 module=Z1 的请求做隔离补齐（无则不影响任何逻辑）。
    """
    try:
        if not isinstance(req, dict):
            return req
        if str(req.get("module") or "").upper().strip() != "Z1":
            return req

        params = req.get("params") if isinstance(req.get("params"), dict) else {}
        meta = req.get("meta") if isinstance(req.get("meta"), dict) else {}

        coin = str(req.get("coin") or req.get("symbol") or params.get("coin") or meta.get("coin") or "").upper().strip()
        if coin:
            req["coin"] = coin
            params["Z1__coin"] = coin
            meta["Z1__coin"] = coin
        else:
            meta["Z1__schema_error"] = meta.get("Z1__schema_error") or "coin_missing"

        act = str(req.get("action_type") or params.get("action_type") or meta.get("action_type") or req.get("action") or "").lower().strip()
        if not act:
            act = "tp"
        req["action_type"] = act
        params["Z1__action_type"] = act
        meta["Z1__action_type"] = act

        plat = str(req.get("platform") or params.get("platform") or meta.get("platform") or "").upper().strip()
        if not plat:
            plat = "EXT"
        req["platform"] = plat
        params["Z1__platform"] = plat
        meta["Z1__platform"] = plat

        def _pick_amt(obj: dict) -> float:
            try:
                if not isinstance(obj, dict):
                    return 0.0
                for k in ("amount_usd", "amount_usd_intent", "usd", "notional_u", "W1__amount_usd", "W1__amount_u"):
                    vv = obj.get(k)
                    if vv not in (None, "", 0):
                        try:
                            return float(vv)
                        except Exception:
                            continue
                return 0.0
            except Exception:
                return 0.0
        amt = _pick_amt(req) or _pick_amt(params) or _pick_amt(meta)
        if amt > 0.0:
            try:
                amt = float(int((amt + 5.0) // 10) * 10)
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

            req["amount_usd"] = float(amt)
            params["amount_usd"] = float(amt)
            params["Z1__amount_usd"] = float(amt)
            meta["Z1__amount_usd"] = float(amt)

        meta["schema"] = "Z1_SCHEMA_V1"
        meta["schema_module"] = "Z1"
        try:
            import time as _time
            meta["schema_ts"] = float(_time.time())
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

        for k in ("plat", "usd", "notional_u", "add_notional_u", "action"):
            try:
                if k in req:
                    req.pop(k, None)
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

        for k in ("usd", "notional_u", "add_notional_u", "plat", "action"):
            try:
                if k in params:
                    params.pop(k, None)
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

        req["params"] = params
        req["meta"] = meta
        return req
    except Exception:
        return req

