def _get_leg_side(snapshot: dict, coin: str, plat: str) -> str:
    """取仓位方向（LONG/SHORT）。

    根因修复：部分交易所/接口在某些时刻 side/position_side 为空，但 qty/positionAmt 等字段仍可用。
    若仅依赖 side 字段，会把“有仓但方向空”误判为 unknown_big_side，从而跳过 LEGACY_DELETED 的补腿/修腿。
    这里做多口径推断，优先保证“对冲方向”判定的稳定性。
    """
    try:
        pos = _get_position(snapshot or {}, coin, plat) or {}
        s = str((pos or {}).get("side") or (pos or {}).get("position_side") or "").upper().strip()
        if s in ("LONG", "SHORT"):
            return s

        for k in ("qty", "positionAmt", "position_amt", "size", "contracts", "position_size", "amount", "net_qty", "net_size"):
            if k in (pos or {}):
                q = _safe_float((pos or {}).get(k), 0.0)
                if abs(q) > 1e-12:
                    return "LONG" if q > 0 else "SHORT"

        lq = _safe_float((pos or {}).get("long_qty") or (pos or {}).get("long_amount") or (pos or {}).get("longSize"), 0.0)
        sq = _safe_float((pos or {}).get("short_qty") or (pos or {}).get("short_amount") or (pos or {}).get("shortSize"), 0.0)
        if abs(lq) > 1e-12 and abs(sq) <= 1e-12:
            return "LONG"
        if abs(sq) > 1e-12 and abs(lq) <= 1e-12:
            return "SHORT"

        return ""
    except Exception:
        return ""

def _is_legacy_deleted_request(req: Any) -> bool:
    """legacy_only_mode 下仅允许两类唯一修复入口和降风险动作通过。"""
    try:
        if isinstance(req, dict):
            mod = str(req.get("module") or "").upper().strip()
            act = str(req.get("action_type") or req.get("action") or "").lower().strip()
            meta = req.get('meta') if isinstance(req.get('meta'), dict) else {}
        else:
            mod = str(getattr(req, "module", "") or "").upper().strip()
            act = str(getattr(req, "action_type", "") or getattr(req, "action", "") or "").lower().strip()
            meta = getattr(req, 'meta', {}) if isinstance(getattr(req, 'meta', {}), dict) else {}
        if mod == MOD_LEGACY_FIX:
            return True
        if mod == 'M10' and act in ('reopen_after_tp', 'koujing_a_3step'):
            return True
        if bool((meta or {}).get('legacy_fix_mode')) and act in ('reopen_after_tp', 'legacy_deleted', 'add_leg', 'fill_leg', 'fill_missing'):
            return True
        if mod in ('ANCHOR', 'S1'):
            return True
        if act in ('force_close_all', 'close_all', 'close_pair', 'close', 'decrease', 'reduce', 'sell', 'take_profit', 'tp'):
            return True
        if act.startswith('close'):
            return True
        return False
    except Exception:
        return False

def _tp_extract_loss_close_notional_u(steps: Any, loss_plat: str) -> float:
    """从三步/多步计划 steps 里提取“亏损腿实际要平掉的名义(U)”用于门禁与净利润估算。

    兼容历史字段差异：
    - plat/platform/p
    - action/act：close/decrease/reduce/sell
    - notional_u / close_notional_u / amount_usd / usd / value / amount 等
    """
    try:
        if not steps:
            return 0.0
        lp = str(loss_plat or "").upper()
        total = 0.0

        amt_keys = (
            "close_notional_u", "close_notional", "notional_u", "notional_usd",
            "amount_u", "amount_usd", "usd", "value_u", "value_usd", "value",
            "amount", "qty_u",
        )

        for st in (steps or []):
            try:
                if not isinstance(st, dict):
                    continue
                p = str(st.get("plat") or st.get("platform") or st.get("p") or "").upper()
                if p != lp:
                    continue

                act = str(st.get("action") or st.get("act") or "").lower()

                if not any(k in act for k in ("close", "decrease", "reduce", "sell", "exit")):
                    if not bool(st.get("reduce_only") or st.get("reduceOnly") or False):
                        continue

                amt = 0.0
                for k in amt_keys:
                    if k in st and st.get(k) is not None:
                        try:
                            amt = float(st.get(k) or 0.0)
                            break
                        except Exception:
                            continue

                if amt <= 0 and isinstance(st.get("usd"), str):
                    try:
                        amt = float(str(st.get("usd")).replace(",", "").strip())
                    except Exception:
                        amt = 0.0

                if amt > 0:
                    total += amt
            except Exception:
                continue

        return float(total)
    except Exception:
        return 0.0

def _tp_est_net_realized_u(win_upnl_u: float, loss_upnl_u: float, loss_notional_u: float, loss_close_notional_u: float):
    """返回 (ratio, realized_loss_est, net_realized_est)
    - win_upnl_u：盈利腿浮盈（正数更常见）
    - loss_upnl_u：亏损腿浮亏（通常为负）
    - loss_notional_u：亏损腿名义
    - loss_close_notional_u：计划平掉的亏损腿名义
    """
    try:
        ln = float(loss_notional_u or 0.0)
        lc = float(loss_close_notional_u or 0.0)
        frac = 0.0 if ln <= 0 else max(0.0, min(1.0, lc / ln))
        realized_loss_est = float(loss_upnl_u or 0.0) * frac
        net_realized_est = float(win_upnl_u or 0.0) + realized_loss_est
        denom = lc if lc > 0 else max(1e-9, ln)
        ratio = net_realized_est / denom
        return float(ratio), float(realized_loss_est), float(net_realized_est)
    except Exception:
        return 0.0, 0.0, float(win_upnl_u or 0.0)

