try:
    from termcolor import cprint as cprint  # type: ignore
except Exception:
    def cprint(*args, **kwargs):  # type: ignore
        try:
            print(*args, **{k:v for k,v in kwargs.items() if k in ("sep","end","file","flush")})
        except Exception:
            try:
                print(*args)
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

def safe_log(msg_or_fn, *args, **kwargs):  # type: ignore
    """全局安全日志封装：
    - 支持 safe_log(lambda: f"...{maybe_missing}...")：延迟构造字符串，捕获 NameError/KeyError/TypeError 等
    - 支持 safe_log("plain string", ...)：直接输出
    - 任何日志构造失败都不会中断主线程/执行线程，只会退化输出异常信息
    """
    _msg = None
    try:
        if callable(msg_or_fn):
            _msg = msg_or_fn()
        else:
            _msg = msg_or_fn
    except Exception as _e:
        try:
            _msg = f"[SAFE_LOG][EXC] {type(_e).__name__}: {_e}"
        except Exception:
            _msg = "[SAFE_LOG][EXC] <unprintable>"

    try:
        return cprint(_msg, *args, **kwargs)
    except Exception:
        try:
            print(_msg)
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_362', _e)
            pass
        return None

def _log_line(fp, msg: str) -> None:
    """向指定文件句柄安全写一行日志（不允许抛异常影响主流程）。
    - 强制单行：把 
/
 转义成 \r/\n，避免 [PIN][ERR] 粘连和多行污染
    - 强制行尾换行
    """
    try:
        if fp is None:
            safe_log(lambda: str(msg))
            return
        try:
            _s = str(msg)
            try:
                _s = _s.replace('\\r', '\\\\r').replace('\\n', '\\\\n')
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_363', _e)
                pass
            fp.write(_s + "\\n")
            fp.flush()
        except Exception:
            if isinstance(fp, (str, bytes, os.PathLike)):
                with open(fp, "a", encoding="utf-8", errors="ignore") as _f:
                    _f.write(str(msg) + "\n")
            else:
                raise
    except Exception as _e:
        try:
            safe_log(lambda: f"[LOG_LINE][EXC] {type(_e).__name__}: {_e} msg={msg}")
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_364', _e)
            pass
