def selftest_flow_once():
    snap = _selftest_build_snapshot()
    tests = [
        _selftest_make_req(MOD_LEGACY_FIX, "SOL", "EXT", "add_leg", "LONG", 951.0),
        _selftest_make_req("M9", "SOL", "VAR", "increase", "LONG", 100.0),
        _selftest_make_req("M9", "ADA", "VAR", "increase", "LONG", 90.0),
    ]
    protocol_rows = []
    link_rows = []
    business_rows = []
    execution_rows = []
    registry_rows = []
    all_ok = True
    for r in tests:
        pchk = _selftest_protocol_check(r)
        protocol_rows.append({'coin': getattr(r, 'coin', ''), 'module': getattr(r, 'module', ''), **pchk})
        ok, code0, reason, detail = _a1_check_before_execute(snap, r, coins=None)
        _rr = _reason_registry_get(reason or code0 or 'not_planned_yet')
        registry_rows.append({
            'coin': getattr(r, 'coin', ''),
            'module': getattr(r, 'module', ''),
            'reason': str(reason or code0 or ''),
            'registered': bool(_rr),
            'stage': str((_rr or {}).get('stage') or ''),
            'priority': int((_rr or {}).get('priority') or 0),
        })
        link_rows.append({
            'coin': getattr(r, 'coin', ''),
            'module': getattr(r, 'module', ''),
            'ok': bool(ok),
            'code': str(code0 or ''),
            'reason': str(reason or ''),
            'detail': detail if isinstance(detail, dict) else ({'detail': detail} if detail not in (None, '') else {}),
        })
        business_rows.append({
            'coin': getattr(r, 'coin', ''),
            'module': getattr(r, 'module', ''),
            'scenario': ('missing_leg_b1' if str(getattr(r, 'module', '')).upper() == MOD_LEGACY_FIX else 'missing_leg_grid'),
            'ok': bool(ok),
        })
        _ev = _build_execution_evidence(req_any=r, exec_res_list=[{'ok': bool(ok), 'coin': getattr(r, 'coin', ''), 'platform': getattr(r, 'platform', ''), 'amount_u': getattr(getattr(r, 'params', {}), 'get', lambda *_: None)('amount_u') if hasattr(getattr(r, 'params', {}), 'get') else None}], pre_state={'positions': []}, post_state={'positions': []}, snapshot={'selftest': True}, ok=bool(ok), reason=str(reason or code0 or ''), detail=detail)
        _ev_reason = str((_ev or {}).get('reason') or '')
        _ev_ok = bool((_ev or {}).get('ok')) or (bool(ok) and _normalize_reason_code(_ev_reason or reason or code0) in ('allow_wrapped_default', 'ok'))
        execution_rows.append({
            'coin': getattr(r, 'coin', ''),
            'module': getattr(r, 'module', ''),
            'ok': bool(_ev_ok),
            'effective': bool((_ev or {}).get('effective')),
            'reason': _ev_reason,
        })
        safe_log(lambda: f"[SELFTEST] A1 ok={ok} code={code0} reason={reason} coin={getattr(r,'coin','')} plat={getattr(r,'platform','')} side={getattr(r,'meta',{}).get('side')}")
        if (not ok) or (not pchk.get('ok')) or (not _rr):
            all_ok = False
    protocol_ok = all(x.get('ok') for x in protocol_rows)
    link_ok = all(x.get('ok') for x in link_rows)
    business_ok = all(x.get('ok') for x in business_rows)
    execution_ok = all(x.get('ok') for x in execution_rows)
    registry_ok = all(x.get('registered') for x in registry_rows)
    _selftest_layer_put('protocol', 'request_contract', {'ok': protocol_ok, 'items': protocol_rows})
    _selftest_layer_put('protocol', 'reason_registry', {'ok': registry_ok, 'items': registry_rows})
    _selftest_layer_put('link', 'a1_gate', {'ok': link_ok, 'items': link_rows})
    _selftest_layer_put('link', 'execution_evidence', {'ok': execution_ok, 'items': execution_rows})
    _selftest_layer_put('business', 'missing_leg_cases', {'ok': business_ok, 'items': business_rows})
    SELFTEST_REPORT['summary'] = {
        'protocol_ok': bool(protocol_ok and registry_ok),
        'link_ok': bool(link_ok and execution_ok),
        'business_ok': bool(business_ok),
        'registry_ok': bool(registry_ok),
        'execution_ok': bool(execution_ok),
        'ok': bool(all_ok and protocol_ok and link_ok and business_ok and execution_ok and registry_ok),
    }
    safe_log(lambda: f"[SELFTEST] PASS={bool(SELFTEST_REPORT.get('summary',{}).get('ok'))} protocol={SELFTEST_REPORT.get('summary',{}).get('protocol_ok')} link={SELFTEST_REPORT.get('summary',{}).get('link_ok')} business={SELFTEST_REPORT.get('summary',{}).get('business_ok')} registry={SELFTEST_REPORT.get('summary',{}).get('registry_ok')} exec={SELFTEST_REPORT.get('summary',{}).get('execution_ok')}")
    return bool(SELFTEST_REPORT.get('summary', {}).get('ok'))

