def _m10_record_exec_ts(ts: float) -> None:
    """记录 M10 执行时间（用于 FASTSCAN 判定）。
    要求：去重（同秒/近似重复）、排序、仅保留最近两条，避免乱序导致误入/误出 FASTSCAN。
    """
    try:
        global _M10_EXEC_TS_HISTORY
        t = float(ts or 0.0)
        if t <= 0:
            t = float(time.time())
        hist = list(_M10_EXEC_TS_HISTORY or [])
        hist.append(t)
        hist = sorted([float(x) for x in hist if float(x) > 0.0])
        uniq = []
        for x in hist:
            if (not uniq) or abs(x - uniq[-1]) > 0.5:
                uniq.append(x)
        _M10_EXEC_TS_HISTORY = (uniq or [])[-2:]
    except Exception:
        try:
            _M10_EXEC_TS_HISTORY = [float(time.time())]
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

def _m10_fast_scan_mode() -> bool:
    """True 表示进入“3分钟扫描模式”。

    修复点：旧逻辑只看“最近两次 M10 的间隔 dt”，会出现“FASTSCAN 粘住”：
    - 如果曾经两次 M10 间隔 < 10 分钟，则 dt 固定 <600；
    - 之后即使 10 分钟都没有再发生新的 M10，dt 也不会被刷新，导致一直 3 分钟扫描。

    新逻辑：除了 dt<600 之外，还要求“距离最近一次 M10 发生时间 < 600s”，否则自动退出。
    """
    try:
        hist = list(_M10_EXEC_TS_HISTORY or [])
        if len(hist) < 2:
            return False
        try:
            if float(time.time()) - float(hist[-1]) >= 600.0:
                return False
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

        dt = float(hist[-1]) - float(hist[-2])
        return dt < 600.0  # 10分钟
    except Exception:
        return False

_M10_FASTSCAN_LAST_STATE: bool | None = None

def _m10_fast_scan_dt_sec() -> float | None:
    """返回最近两次 M10 的间隔秒数；不足两次则返回 None。"""
    try:
        hist = list(_M10_EXEC_TS_HISTORY or [])
        if len(hist) < 2:
            return None
        return float(hist[-1]) - float(hist[-2])
    except Exception:
        return None

