class _Log8Router:
    def __init__(self, base_dir: str, keep_hours: float = 24.0, clean_every_sec: float = 300.0):
        self.base_dir = str(base_dir)
        self.keep_sec = float(keep_hours) * 3600.0
        self.clean_every_sec = float(clean_every_sec)
        self.dir = os.path.join(self.base_dir, "out", "logs8")
        try:
            os.makedirs(self.dir, exist_ok=True)
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

        self.files = {
            "scan": os.path.join(self.dir, "scan.jsonl"),
            "tp":   os.path.join(self.dir, "tp.jsonl"),
            "grid": os.path.join(self.dir, "grid.jsonl"),
            "fix":  os.path.join(self.dir, "fix.jsonl"),
            "open": os.path.join(self.dir, "open.jsonl"),
            "root": os.path.join(self.dir, "root.jsonl"),
            "exec": os.path.join(self.dir, "exec.jsonl"),
            "all":  os.path.join(self.dir, "all.jsonl"),
        }
        self._buf = ""  # 行缓存（跨 write 分段）
        self._last_clean_ts = 0.0
        self._write_count = 0

    def _module_of(self, line: str) -> str:
        s = (line or "")
        u = s.upper()
        if ("[GUARD" in u) or ("S1" in u and "模块" in s) or ("最高权限" in s) or (" ROOT" in u):
            return "root"
        if ("[EXEC" in u) or ("执行器" in s) or ("DISPATCH" in u) or ("SUBMIT_REQUEST" in u) or ("UI" in u and "CLICK" in u):
            return "exec"
        if ("[M2" in u) or ("扫描" in s) or ("持仓进度" in s) or ("读取余额" in s) or ("IND_" in u) or ("ADX" in u and "RSI" in u):
            return "scan"
        if ("[B2" in u) or ("TREND_TP" in u) or ("TP_PROBE" in u) or ("[M10" in u) or ("止盈" in s) or ("EXIT" in u):
            return "tp"
        if ("[M9" in u) or ("GRID" in u) or ("网格" in s) or ("LAYERS" in u) or ("M9_" in u):
            return "grid"
        if (TAG_LEGACY_FIX in u) or (TAG_LEGACY_FIX in u) or ("修腿" in s) or ("补腿" in s) or ("LEGACY_DELETED" in u) or ("BALANCE" in u):
            return "fix"
        if ("[B1" in u) or ("首次开仓" in s) or ("FIRST_OPEN" in u):
            return "open"
        return "exec"  # 默认归到执行器日志，方便排查“谁在输出但没模块前缀”

    def _append_jsonl(self, fp: str, obj: dict):
        try:
            with open(fp, "a", encoding="utf-8", errors="replace") as f:
                f.write((globals().get('_json_dumps_bot') or (lambda _o: json.dumps(_o,ensure_ascii=False,default=globals().get('_json_default_for_bot'))))(obj) + "\n")
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    def feed(self, s: str):
        try:
            if not s:
                return
            self._buf += str(s)
            while "\n" in self._buf:
                line, self._buf = self._buf.split("\n", 1)
                self._route_line(line)
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    def _route_line(self, line: str):
        try:
            now = time.time()
            mod = self._module_of(line)
            rec = {
                "ts": float(now),
                "dt": time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(now)),
                "module": mod,
                "line": str(line),
            }
            self._append_jsonl(self.files["all"], rec)
            if mod in self.files:
                self._append_jsonl(self.files[mod], rec)
            self._write_count += 1
            if (now - float(self._last_clean_ts or 0.0)) >= self.clean_every_sec:
                self._last_clean_ts = now
                self._cleanup(now)
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    def _cleanup(self, now_ts: float):
        """按 keep_sec 裁剪各 jsonl，仅保留近 keep_sec。
        重要：使用流式写 tmp + 原子 replace，避免“读全文件进内存”导致卡顿。
        """
        cutoff = float(now_ts) - float(self.keep_sec)
        for k, fp in self.files.items():
            try:
                if not os.path.exists(fp):
                    continue

                try:
                    if os.path.getsize(fp) > 200 * 1024 * 1024:
                        bkp = fp.replace(".jsonl", f"_{time.strftime('%Y%m%d_%H%M%S')}.bak.jsonl")
                        try:
                            os.replace(fp, bkp)
                        except Exception as _e:
                            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

                        try:
                            open(fp, "w", encoding="utf-8").close()
                        except Exception as _e:
                            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

                        continue
                except Exception as _e:
                    _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

                tmp_fp = fp + ".tmp"
                kept_any = False
                with open(fp, "r", encoding="utf-8", errors="ignore") as fr, open(tmp_fp, "w", encoding="utf-8", errors="replace") as fw:
                    for ln in fr:
                        ln2 = (ln or "").strip()
                        if not ln2:
                            continue
                        try:
                            obj = json.loads(ln2)
                            ts = float(obj.get("ts") or 0.0)
                            if ts >= cutoff:
                                fw.write(ln2 + "\n")
                                kept_any = True
                        except Exception:
                            continue
                try:
                    os.replace(tmp_fp, fp)
                except Exception:
                    try:
                        if os.path.exists(tmp_fp):
                            os.remove(tmp_fp)
                    except Exception as _e:
                        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

            except Exception:
                continue
class _TeeStream:
    """把 stdout/stderr 同时写到：
    - 原始 console（stream）
    - out/bot_console.txt（fp）
    - logs/bot_console.txt（mirror_fp, 常驻句柄，避免高频 open/close 抖动）
    同时旁路喂给 LOG8 Router（分流 jsonl）。
    """
    def __init__(self, stream, fp, mirror_fp=None):
        self._stream = stream
        self._fp = fp
        self._mirror_fp = mirror_fp
    def write(self, s):
        try:
            if s is None:
                return
            try:
                if isinstance(s, str) and s and (not s.endswith('\n')):
                    s = s + '\n'
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_367', _e)
                pass
            if self._stream is not None:
                try:
                    self._stream.write(s)
                except Exception as _e:
                    _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

            if self._fp is not None:
                try:
                    self._fp.write(s)
                    try:
                        self._fp.flush()
                    except Exception as _e:
                        _record_swallowed_exception('except_pass_line_368', _e)
                        pass
                    try:
                        _cleanup_retention_target(getattr(self._fp, 'name', ''))
                    except Exception:
                        pass
                except Exception as _e:
                    _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

            if self._mirror_fp is not None:
                try:
                    self._mirror_fp.write(s)
                    try:
                        self._mirror_fp.flush()
                    except Exception as _e:
                        _record_swallowed_exception('except_pass_line_369', _e)
                        pass
                    try:
                        _cleanup_retention_target(getattr(self._mirror_fp, 'name', ''))
                    except Exception:
                        pass
                except Exception as _e:
                    _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

            try:
                global _LOG8_ROUTER
                if _LOG8_ROUTER is not None:
                    _LOG8_ROUTER.feed(s)
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    def flush(self):
        try:
            if self._stream is not None:
                try: self._stream.flush()
                except Exception as _e:
                    _record_swallowed_exception("console_tee.flush_stream", _e)
            if self._fp is not None:
                try: self._fp.flush()
                except Exception as _e:
                    _record_swallowed_exception("console_tee.flush_fp", _e)
            if self._mirror_fp is not None:
                try: self._mirror_fp.flush()
                except Exception as _e:
                    _record_swallowed_exception("console_tee.flush_mirror_fp", _e)
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    def isatty(self):
        try:
            return bool(self._stream is not None and getattr(self._stream, "isatty", lambda: False)())
        except Exception:
            return False

def _install_console_tee_early():
    global _BOT_CONSOLE_TEE_INSTALLED, _BOT_CONSOLE_TEE_FP, _BOT_CONSOLE_TEE_MIRROR_FP, _BOT_CONSOLE_TEE_PATHS
    if _BOT_CONSOLE_TEE_INSTALLED:
        return
    _BOT_CONSOLE_TEE_INSTALLED = True

    try:
        _bot_dir = Path(__file__).resolve().parent
    except Exception:
        _bot_dir = Path(".").resolve()

    _out_dir = _bot_dir / "out"
    _logs_dir = _bot_dir / "logs"
    try: _out_dir.mkdir(parents=True, exist_ok=True)
    except Exception as _e:
        _record_swallowed_exception("console_tee.mkdir_out", _e, _out_dir)
    try: _logs_dir.mkdir(parents=True, exist_ok=True)
    except Exception as _e:
        _record_swallowed_exception("console_tee.mkdir_logs", _e, _logs_dir)

    _p_out = _out_dir / 'bot_console.txt'
    _p_logs = _logs_dir / 'bot_console.txt'
    _BOT_CONSOLE_TEE_PATHS = (str(_p_out), str(_p_logs))

    try:
        global _LOG8_ROUTER
        if _LOG8_ROUTER is None:
            _LOG8_ROUTER = _Log8Router(str(_bot_dir), keep_hours=24.0, clean_every_sec=300.0)
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    try:
        fp = open(_p_out, "a", encoding="utf-8", errors="replace", buffering=1)
    except Exception:
        fp = None
    _BOT_CONSOLE_TEE_FP = fp

    try:
        mfp = open(_p_logs, "a", encoding="utf-8", errors="replace", buffering=1)
    except Exception:
        mfp = None
    _BOT_CONSOLE_TEE_MIRROR_FP = mfp

    try:
        import sys as _sys
        if not isinstance(_sys.stdout, _TeeStream):
            _sys.stdout = _TeeStream(_sys.stdout, fp, mirror_fp=mfp)
        if not isinstance(_sys.stderr, _TeeStream):
            _sys.stderr = _TeeStream(_sys.stderr, fp, mirror_fp=mfp)
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

try:
    import sys as _pin_sys
    import traceback as _pin_tb

    def _pin_global_excepthook(exc_type, exc, tb):
        try:
            msg = "".join(_pin_tb.format_exception(exc_type, exc, tb))
        except Exception:
            msg = f"{exc_type}: {exc}"
        try:
            print("[PIN][FATAL] uncaught_exception")
            print(msg)
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

        try:
            if hasattr(_pin_sys, "__excepthook__"):
                _pin_sys.__excepthook__(exc_type, exc, tb)
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    _pin_sys.excepthook = _pin_global_excepthook
except Exception as _e:
    _record_swallowed_exception('except_pass_line_370', _e)
    pass

