def _pin_safe_kv(v: Any) -> str:
    try:
        if isinstance(v, (dict, list, tuple)):
            s = json.dumps(v, ensure_ascii=False, separators=(",", ":"))
        else:
            s = str(v)
    except Exception:
        try:
            s = repr(v)
        except Exception:
            s = "<unrepr>"
    s = s.replace("\n", "\\n").replace("\r", "\\r")
    if len(s) > 600:
        s = s[:600] + "...(trunc)"
    return s

