def _go_baocuo_should_log(stage: str, ok: int, reason: str, mod: str) -> bool:
    su = str(stage or "").upper()
    ru = str(reason or "")
    mu = str(mod or "").upper()
    if su == "MOD_DECIDE" and ru == "NO_REQUEST" and mu == "M10":
        return False
    abn = {
        "SKIP","REJECT","GATE_BLOCK","SUBMIT_REJECT","EXEC_REJECT","RSI_STRICT_BLOCK",
        "BLOCK","FAIL","ERR","EXC","IO_JSON_BAD_FILE","IO_JSON_BAD","IO_FAIL",
    }
    if su in abn:
        return True
    try:
        return int(ok) == 0
    except Exception:
        return False

def _go_baocuo_rl_allow(key: str, now: float, window_sec: float = 10.0) -> tuple[bool, int]:
    try:
        last, sup = _GO_BAOCUO_PIN_RL.get(key, (0.0, 0))
    except Exception:
        last, sup = (0.0, 0)
    try:
        last = float(last or 0.0)
    except Exception:
        last = 0.0
    try:
        sup = int(sup or 0)
    except Exception:
        sup = 0
    if (now - last) < float(window_sec):
        _GO_BAOCUO_PIN_RL[key] = (last, sup + 1)
        return (False, 0)
    _GO_BAOCUO_PIN_RL[key] = (now, 0)
    return (True, sup)

