def _w1_skip_stat(reason: str, **kv) -> None:
    """记录一次 W1 的跳过原因（尽量带上 allow_side/es/vs/en/vn/diff 等关键上下文）。"""
    try:
        rr = str(reason or "unknown")
        _W1_SKIP_STATS["cnt"] = int(_W1_SKIP_STATS.get("cnt", 0)) + 1
        br = _W1_SKIP_STATS.get("by_reason") or {}
        br[rr] = int(br.get(rr, 0)) + 1
        _W1_SKIP_STATS["by_reason"] = br
        _W1_SKIP_STATS["last"][rr] = {k: (v if (isinstance(v,(int,float,str,bool,type(None),list,dict))) else str(v)) for k,v in (kv or {}).items()}

        try:
            _pin_decision(mod='W1', coin=str(kv.get('coin') or ''), plat=str(kv.get('plat') or kv.get('platform') or ''), act=str(kv.get('act') or kv.get('action') or 'grid'), side=str(kv.get('side') or ''), ok=0, reason=rr, stage='DECISION', rsi=kv.get('rsi'), adx=kv.get('adx'), loss_pct=kv.get('loss_pct'), base_u=kv.get('base_u'), add_u=kv.get('add_u'), final_u=kv.get('final_u'), amt_det=kv.get('amt_det'), **{k:v for k,v in (kv or {}).items() if k not in ('coin','plat','platform','act','action','side','rsi','adx','loss_pct','base_u','add_u','final_u','amt_det')})
        except Exception as _e:
            _log_exc(mod='SYS', stage='EXC_PASS', e=_e)
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_374', _e)
        pass
    try:
        rec = {"ts": now_ts(), "mod": "W1", "stage": "SKIP_TRACE", "ok": 0, "reason": rr}
        rec.update({k: (v if (isinstance(v,(int,float,str,bool,type(None),list,dict))) else str(v)) for k,v in (kv or {}).items()})
        _go_baocuo_write(rec)
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_375', _e)
        pass
    global _W1_SKIP_STATS_LAST_FLUSH_TS
    try:
        now = float(time.time())
        if now - float(_W1_SKIP_STATS_LAST_FLUSH_TS or 0.0) >= 30.0:
            _W1_SKIP_STATS_LAST_FLUSH_TS = now
            top = []
            try:
                items = list((_W1_SKIP_STATS.get("by_reason") or {}).items())
                items.sort(key=lambda x: x[1], reverse=True)
                top = items[:5]
            except Exception:
                top = []
            try:
                safe_log(lambda: f"[{now_ts()}] [W1][SKIP_TOP] total={_W1_SKIP_STATS.get('cnt')} top={top}")
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_376', _e)
                pass
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_377', _e)
        pass
