def _pin_exc(mod: str, *, coin: str | None = None, stage: str = "EXC", reason: str = "", exc: Exception | None = None, **kv):
    """异常插针：必须把 traceback 落盘到 bot_console.txt。"""
    try:
        import traceback as _tb
        tb = _tb.format_exc()
    except Exception:
        tb = "<no-traceback>"
    try:
        _pin(mod, coin=(coin or ""), stage=stage, reason=(reason or "exception"), err=(repr(exc) if exc is not None else None), **kv)
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    try:
        print(f"[PIN][TRACE] mod={str(mod)} coin={str((coin or '')).upper().strip()}\n{tb}")
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

def _pin_new_round(coins: list | None = None, ctx: str = "MAIN", **kv):
    global _PIN_ROUND, _PIN_SCAN_ID, _PIN_LAST_NEW_ROUND_TS
    try:
        with _PIN_LOCK:
            _PIN_ROUND += 1
            _PIN_LAST_NEW_ROUND_TS = time.time()
            _PIN_SCAN_ID = f"R{_PIN_ROUND:06d}_{int(_PIN_LAST_NEW_ROUND_TS)}"
            _sid = _PIN_SCAN_ID
        try:
            _round_ui_budget_reset(scan_id=_sid, coins=(coins or []), ctx=ctx)
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_411', _e)
            pass
        _pin("ROUND_START", mod=ctx, coin="*", ok=1, reason="OK", coins=(coins or []), **kv)
        return _sid
    except Exception as e:
        _pin("ROUND_START", mod=ctx, coin="*", ok=0, reason="ROUND_START_ERR", err=repr(e))
        return ""

