def _round_ui_is_hard_evidence(code: str) -> bool:
    try:
        cu = str(code or "").upper().strip()
    except Exception:
        cu = ""
    return bool(cu and (cu in _ROUND_UI_HARD_EVIDENCE))

def _round_ui_budget_reset(*, scan_id: str = "", coins: list | None = None, ctx: str = "") -> None:
    try:
        with _ROUND_UI_BUDGET_LOCK:
            _ROUND_UI_BUDGET.update({
                "scan_id": str(scan_id or ""),
                "round_ts": float(time.time()),
                "ctx": str(ctx or "")[:80],
                "coins": list(coins or [])[:64],
                "coin_switch_budget": int(EXEC_ROUND_COIN_SWITCH_BUDGET or 0),
                "reload_budget": int(EXEC_ROUND_RELOAD_BUDGET or 0),
                "ind_read_budget": int(EXEC_ROUND_IND_READ_BUDGET or 0),
                "final_confirm_ind_budget": int(EXEC_ROUND_FINAL_CONFIRM_IND_BUDGET or 0),
                "enqueue_budget": int(EXEC_ROUND_ENQUEUE_BUDGET or 0),
                "exec_coin_switch_budget": int(EXEC_ROUND_EXEC_COIN_SWITCH_BUDGET or 0),
                "coin_switch_count": 0,
                "exec_coin_switch_count": 0,
                "reload_count": 0,
                "ind_read_count": 0,
                "final_confirm_ind_count": 0,
                "enqueue_count": 0,
                "exec_coin_switch_denied": 0,
                "coin_switch_denied": 0,
                "reload_denied": 0,
                "ind_read_denied": 0,
                "final_confirm_ind_denied": 0,
                "enqueue_denied": 0,
                "last_deny_reason": "",
                "last_deny_ts": 0.0,
                "hard_override_used": 0,
            })
        try:
            _round_watch_touch("ROUND_BEGIN", msg="round_begin", reason=f"ui_budget reset scan_id={str(scan_id or '')}")
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_412', _e)
            pass
    except Exception:
        return

def _round_ui_budget_snapshot() -> dict:
    try:
        with _ROUND_UI_BUDGET_LOCK:
            return dict(_ROUND_UI_BUDGET)
    except Exception:
        return {}

def _round_ui_budget_refund(kind: str, *, cost: int = 1) -> None:
    try:
        k = str(kind or "").lower().strip()
        c = max(0, int(cost or 1))
    except Exception:
        return
    if c <= 0:
        return
    try:
        with _ROUND_UI_BUDGET_LOCK:
            obj = _ROUND_UI_BUDGET
            if k == "coin_switch":
                obj["coin_switch_count"] = max(0, int(obj.get("coin_switch_count") or 0) - c)
            elif k == "exec_coin_switch":
                obj["exec_coin_switch_count"] = max(0, int(obj.get("exec_coin_switch_count") or 0) - c)
            elif k == "reload":
                obj["reload_count"] = max(0, int(obj.get("reload_count") or 0) - c)
            elif k == "ind_read":
                obj["ind_read_count"] = max(0, int(obj.get("ind_read_count") or 0) - c)
            elif k == "final_confirm_ind":
                obj["final_confirm_ind_count"] = max(0, int(obj.get("final_confirm_ind_count") or 0) - c)
            elif k == "enqueue":
                obj["enqueue_count"] = max(0, int(obj.get("enqueue_count") or 0) - c)
    except Exception:
        return

def _round_ui_budget_consume(kind: str, *, coin: str = "", plat: str = "", ctx: str = "", evidence: str = "", cost: int = 1) -> tuple[bool, str]:
    """消耗本轮 UI 预算。"""
    try:
        k = str(kind or "").lower().strip()
    except Exception:
        k = ""
    ev = str(evidence or "").upper().strip()
    hard = _round_ui_is_hard_evidence(ev)
    nowv = float(time.time())
    with _ROUND_UI_BUDGET_LOCK:
        obj = _ROUND_UI_BUDGET
        if k == "coin_switch":
            cnt = int(obj.get("coin_switch_count") or 0)
            obj["coin_switch_budget"] = 0
            obj["coin_switch_count"] = cnt + int(cost or 1)
            obj["last_allow_reason"] = f"coin_switch_budget_disabled ctx={ctx} coin={coin} plat={plat}"
            obj["last_allow_ts"] = nowv
            return True, "round_coin_switch_budget_disabled"

        if k == "exec_coin_switch":
            cnt = int(obj.get("exec_coin_switch_count") or 0)
            obj["exec_coin_switch_budget"] = 0
            obj["exec_coin_switch_count"] = cnt + int(cost or 1)
            obj["last_allow_reason"] = f"exec_coin_switch_budget_disabled ctx={ctx} coin={coin} plat={plat}"
            obj["last_allow_ts"] = nowv
            return True, "round_exec_coin_switch_budget_disabled"

        if k == "reload":
            budget = int(obj.get("reload_budget") or 0)
            cnt = int(obj.get("reload_count") or 0)
            if budget > 0 and cnt >= budget and not hard:
                obj["reload_denied"] = int(obj.get("reload_denied") or 0) + 1
                obj["last_deny_reason"] = f"reload_budget_exhausted ctx={ctx} coin={coin} plat={plat}"
                obj["last_deny_ts"] = nowv
                return False, "round_reload_budget_exhausted"
            obj["reload_count"] = cnt + int(cost or 1)
            if budget > 0 and cnt >= budget and hard:
                obj["hard_override_used"] = int(obj.get("hard_override_used") or 0) + 1
                return True, "round_reload_budget_override_hard"
            return True, "ok"

        if k == "ind_read":
            budget = int(obj.get("ind_read_budget") or 0)
            cnt = int(obj.get("ind_read_count") or 0)
            if budget > 0 and cnt >= budget and not hard:
                obj["ind_read_denied"] = int(obj.get("ind_read_denied") or 0) + 1
                obj["last_deny_reason"] = f"ind_read_budget_exhausted ctx={ctx} coin={coin} plat={plat}"
                obj["last_deny_ts"] = nowv
                return False, "round_ind_read_budget_exhausted"
            obj["ind_read_count"] = cnt + int(cost or 1)
            if budget > 0 and cnt >= budget and hard:
                obj["hard_override_used"] = int(obj.get("hard_override_used") or 0) + 1
                return True, "round_ind_read_budget_override_hard"
            return True, "ok"

        if k == "final_confirm_ind":
            budget = int(obj.get("final_confirm_ind_budget") or 0)
            cnt = int(obj.get("final_confirm_ind_count") or 0)
            if budget > 0 and cnt >= budget and not hard:
                obj["final_confirm_ind_denied"] = int(obj.get("final_confirm_ind_denied") or 0) + 1
                obj["last_deny_reason"] = f"final_confirm_ind_budget_exhausted ctx={ctx} coin={coin} plat={plat}"
                obj["last_deny_ts"] = nowv
                return False, "round_final_confirm_ind_budget_exhausted"
            obj["final_confirm_ind_count"] = cnt + int(cost or 1)
            if budget > 0 and cnt >= budget and hard:
                obj["hard_override_used"] = int(obj.get("hard_override_used") or 0) + 1
                return True, "round_final_confirm_ind_budget_override_hard"
            return True, "ok"

    return True, "ok"

def _round_ui_budget_touch_watch(*, note: str = "") -> None:
    try:
        snap = _round_ui_budget_snapshot()
        rw = dict(globals().get("_MAIN_ROUND_WATCH") or {})
        if isinstance(rw, dict):
            rw["ui_coin_switch"] = int(snap.get("coin_switch_count") or 0)
            rw["ui_reload"] = int(snap.get("reload_count") or 0)
            rw["ui_ind_read"] = int(snap.get("ind_read_count") or 0)
            rw["ui_final_confirm_ind"] = int(snap.get("final_confirm_ind_count") or 0)
            rw["ui_budget_coin_switch"] = int(snap.get("coin_switch_budget") or 0)
            rw["ui_budget_reload"] = int(snap.get("reload_budget") or 0)
            rw["ui_budget_ind_read"] = int(snap.get("ind_read_budget") or 0)
            rw["ui_hard_override_used"] = int(snap.get("hard_override_used") or 0)
            rw["runtime_state_source"] = "round_watch_diag_only"
            if note:
                rw["ui_budget_note"] = str(note)[:160]
            globals()["_MAIN_ROUND_WATCH"] = rw
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_413', _e)
        pass
def _pin_snapshot_ok(snap: dict, coins: list | None, ctx: str = "M2", **kv):
    try:
        if not isinstance(snap, dict) or not snap:
            _pin("SNAPSHOT_OK", mod=ctx, coin="*", ok=0, reason="SNAPSHOT_EMPTY", **kv)
            return
        try:
            with _PIN_LOCK:
                sid = _PIN_SCAN_ID
            if sid and not snap.get("scan_id"):
                snap["scan_id"] = sid
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

        _pin("SNAPSHOT_OK", mod=ctx, coin="*", ok=1, reason="OK",
             total_u=round(float(_get_total_u(snap) or 0.0), 3),
             **kv)
        for c in (coins or []):
            cu = str(c or "").upper().strip()
            if not cu:
                continue
            try:
                eu = float(_get_notional_u(snap, cu, "EXT") or 0.0)
                vu = float(_get_notional_u(snap, cu, "VAR") or 0.0)
            except Exception:
                eu, vu = 0.0, 0.0
            try:
                eup = float(_get_upnl_u(snap, cu, "EXT") or 0.0)
                vup = float(_get_upnl_u(snap, cu, "VAR") or 0.0)
            except Exception:
                eup, vup = 0.0, 0.0
            es = _pin_get_side_from_snap(snap, cu, "EXT")
            vs = _pin_get_side_from_snap(snap, cu, "VAR")
            _pin("SNAPSHOT_COIN", mod=ctx, coin=cu, ok=1, reason="OK",
                 ext_u=round(eu,3), var_u=round(vu,3),
                 ext_upnl=round(eup,3), var_upnl=round(vup,3),
                 ext_side=es, var_side=vs)
    except Exception as e:
        _pin("SNAPSHOT_OK", mod=ctx, coin="*", ok=0, reason="SNAPSHOT_PIN_ERR", err=repr(e))
        return
def _pin_get_side_from_snap(snap: dict, coin: str, plat: str) -> str:
    try:
        cu = str(coin or "").upper()
        pu = str(plat or "").upper()
        for path in [
            ("pos", cu, pu),
            ("positions", cu, pu),
            ("pos_detail", cu, pu),
            ("data", "pos", cu, pu),
        ]:
            cur = snap
            ok = True
            for k in path:
                if isinstance(cur, dict) and k in cur:
                    cur = cur[k]
                else:
                    ok = False
                    break
            if ok and isinstance(cur, dict):
                s = cur.get("side") or cur.get("positionSide") or cur.get("posSide") or ""
                if s:
                    return str(s).upper()
        return ""
    except Exception:
        return ""

from collections import deque as _deque

_M9_PX_RING: dict[str, _deque] = {}
_M9_PX_LAST_TS: dict[str, float] = {}
_M9_LAST_AMT_DET_BY_KEY: dict[str, dict] = {}

M9_VOL_RING_N = int(os.environ.get("M9_VOL_RING_N") or 15)
M9_VOL_K = float(os.environ.get("M9_VOL_K") or 1.2)
M9_FEE_MIN = float(os.environ.get("M9_FEE_MIN") or 0.001)
M9_SLIPPAGE_BUF = float(os.environ.get("M9_SLIPPAGE_BUF") or 0.0012)
M9_GAP_FLOOR = 0.01  # 单链硬口径：最低网格间距固定 1%，禁止环境变量/旧常量改写
M9_GAP_CAP = float(os.environ.get("M9_GAP_CAP") or 0.05)
M9_PX_REC_MIN_INTERVAL = float(os.environ.get("M9_PX_REC_MIN_INTERVAL") or 10.0)

def _m9_amt_det_key(coin: str, plat: str, side: str) -> str:
    try:
        return f"{str(coin or '').upper()}|{str(plat or '').upper()}|{str(side or '').upper()}"
    except Exception:
        return f"{coin}|{plat}|{side}"

M9_VOL_KLINE_INTERVAL_SEC = int(os.environ.get("M9_VOL_KLINE_INTERVAL_SEC") or 60)
M9_VOL_KLINE_N = int(os.environ.get("M9_VOL_KLINE_N") or 3)
M9_VOL_ACCEL_WEIGHT = float(os.environ.get("M9_VOL_ACCEL_WEIGHT") or 0.25)
M9_VOL_HISTORY_MAX = int(os.environ.get("M9_VOL_HISTORY_MAX") or 240)
_M9_PX_HISTORY: dict[str, _deque] = {}

def _m9_ring_vol_pct(coin: str) -> tuple[float | None, dict]:
    coin = str(coin or '').upper()
    dq = _M9_PX_RING.get(coin)
    pts = list(dq) if dq else []
    if len(pts) < 2:
        return None, {"coin": coin, "pts": len(pts), "vol_pct": None}
    rets = []
    for i in range(1, len(pts)):
        p0 = float(pts[i-1][1]); p1 = float(pts[i][1])
        if p0 > 0 and math.isfinite(p0) and math.isfinite(p1):
            rets.append(abs(p1 - p0) / p0)
    vol = float(sum(rets) / max(1, len(rets))) if rets else 0.0
    return float(vol), {"coin": coin, "pts": len(pts), "vol_pct": float(vol), "kind": "ring_accel"}

def _m9_px_ring_push(coin: str, px: float, ts: float | None = None) -> None:
    """记录 coin 当前价到内存环 + 历史序列 + jsonl（节流防爆）"""
    try:
        if ts is None:
            ts = float(time.time())
        px = float(px)
        if (not math.isfinite(px)) or px <= 0.0:
            return
        coin = str(coin or '').upper()
        last = float(_M9_PX_LAST_TS.get(coin) or 0.0)
        if ts - last < float(M9_PX_REC_MIN_INTERVAL):
            return
        _M9_PX_LAST_TS[coin] = ts
        dq = _M9_PX_RING.get(coin)
        if dq is None:
            dq = _deque(maxlen=max(2, int(M9_VOL_RING_N)))
            _M9_PX_RING[coin] = dq
        dq.append((ts, px))
        hq = _M9_PX_HISTORY.get(coin)
        if hq is None:
            hq = _deque(maxlen=max(int(M9_VOL_HISTORY_MAX), int(M9_VOL_RING_N), 32))
            _M9_PX_HISTORY[coin] = hq
        hq.append((ts, px))
        try:
            os.makedirs(OUT_DIR, exist_ok=True)
            fn = os.path.join(OUT_DIR, "price_ring.jsonl")
            with open(fn, "a", encoding="utf-8") as wf:
                wf.write(json.dumps({"ts": ts, "coin": coin, "px": px}, ensure_ascii=False) + "\n")
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_414', _e)
            pass
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_415', _e)
        pass
_M9_PRICE_SAME_CNT: Dict[str, int] = {}
_M9_PRICE_LAST_VAL: Dict[str, float] = {}
_M9_PRICE_LAST_TS: Dict[str, float] = {}

M9_PRICE_STALE_SAME_N = int(_os.environ.get("M9_PRICE_STALE_SAME_N", "6") or 6)
M9_PRICE_STALE_MAX_AGE_S = float(_os.environ.get("M9_PRICE_STALE_MAX_AGE_S", "90") or 90.0)

def _m9_price_stale_check(coin: str, px: Optional[float], now_ts: Optional[float] = None) -> Dict[str, Any]:
    """返回：{stale:bool, same_cnt:int, age_s:float, last_px:float|None}"""
    c = str(coin or "").upper().strip()
    nowv = float(now_ts or time.time())
    out = {"stale": False, "same_cnt": 0, "age_s": 0.0, "last_px": None}
    if (not c) or (px is None):
        return out
    try:
        pxv = float(px)
        if (not math.isfinite(pxv)) or (pxv <= 0.0):
            return out
    except Exception:
        return out

    lastv = _M9_PRICE_LAST_VAL.get(c)
    last_ts = float(_M9_PRICE_LAST_TS.get(c) or 0.0)
    if (lastv is not None) and (abs(float(lastv) - float(pxv)) <= 0.0):
        _M9_PRICE_SAME_CNT[c] = int(_M9_PRICE_SAME_CNT.get(c) or 0) + 1
    else:
        _M9_PRICE_SAME_CNT[c] = 1
        _M9_PRICE_LAST_VAL[c] = float(pxv)
        _M9_PRICE_LAST_TS[c] = float(nowv)
        last_ts = float(nowv)

    same_cnt = int(_M9_PRICE_SAME_CNT.get(c) or 0)
    age_s = max(0.0, float(nowv) - float(last_ts)) if last_ts > 0 else 0.0
    out["same_cnt"] = int(same_cnt)
    out["age_s"] = float(round(age_s, 3))
    out["last_px"] = float(_M9_PRICE_LAST_VAL.get(c)) if _M9_PRICE_LAST_VAL.get(c) is not None else None
    if (same_cnt >= int(max(2, M9_PRICE_STALE_SAME_N))) and (age_s >= float(max(10.0, M9_PRICE_STALE_MAX_AGE_S))):
        out["stale"] = True
    return out

def _m9_closed_klines_from_history(coin: str, *, interval_sec: int | None = None) -> list[dict]:
    coin = str(coin or '').upper()
    interval = max(5, int(interval_sec or M9_VOL_KLINE_INTERVAL_SEC or 60))
    dq = _M9_PX_HISTORY.get(coin)
    pts = list(dq) if dq else []
    if len(pts) < 2:
        return []
    buckets: dict[int, dict] = {}
    for ts, px in pts:
        try:
            tsf = float(ts); pxf = float(px)
        except Exception:
            continue
        if (not math.isfinite(tsf)) or (not math.isfinite(pxf)) or pxf <= 0:
            continue
        b = int(tsf // interval) * interval
        row = buckets.get(b)
        if row is None:
            row = {"bucket": int(b), "open": pxf, "high": pxf, "low": pxf, "close": pxf, "count": 1}
            buckets[b] = row
        else:
            row["high"] = max(float(row.get("high") or pxf), pxf)
            row["low"] = min(float(row.get("low") or pxf), pxf)
            row["close"] = pxf
            row["count"] = int(row.get("count") or 0) + 1
    if not buckets:
        return []
    ordered = [buckets[k] for k in sorted(buckets.keys())]
    now_b = int(time.time() // interval) * interval
    closed = [dict(x) for x in ordered if int(x.get("bucket") or 0) < now_b]
    return closed

def _m9_kline_vol_pct(coin: str) -> tuple[float | None, dict]:
    coin = str(coin or '').upper()
    ks = _m9_closed_klines_from_history(coin)
    need_n = max(1, int(M9_VOL_KLINE_N or 3))
    if len(ks) < need_n:
        return None, {"coin": coin, "kline_n": len(ks), "need_n": need_n, "interval_sec": int(M9_VOL_KLINE_INTERVAL_SEC), "vol_pct": None}
    use = ks[-need_n:]
    trs = []
    prev_close = None
    for k in use:
        hi = float(k.get("high") or 0.0)
        lo = float(k.get("low") or 0.0)
        op = float(k.get("open") or 0.0)
        cl = float(k.get("close") or 0.0)
        if prev_close is None:
            prev_close = cl if cl > 0 else (op if op > 0 else hi)
        base_prev = float(prev_close or cl or op or hi or 0.0)
        if base_prev <= 0:
            prev_close = cl if cl > 0 else base_prev
            continue
        tr = max(hi - lo, abs(hi - base_prev), abs(lo - base_prev))
        trs.append(float(tr) / float(base_prev))
        prev_close = cl if cl > 0 else base_prev
    if not trs:
        return None, {"coin": coin, "kline_n": len(use), "need_n": need_n, "interval_sec": int(M9_VOL_KLINE_INTERVAL_SEC), "vol_pct": None}
    vol = float(sum(trs) / len(trs))
    return float(vol), {
        "coin": coin,
        "kline_n": len(use),
        "need_n": need_n,
        "interval_sec": int(M9_VOL_KLINE_INTERVAL_SEC),
        "vol_pct": float(vol),
        "kind": "kline_main",
    }

def _m9_gap_from_ring(coin: str) -> tuple[float, dict]:
    coin = str(coin or '').upper().strip()
    floor = 0.01
    cap = float(_m9_gap_truth_cap_pct(coin))
    gap_raw = None
    trig_det = {}
    vol24h_pct = None
    try:
        vol24h_pct, vol_det = _coin_24h_volatility_pct(coin)
        trig_det = dict(vol_det or {})
        if vol24h_pct is not None and float(vol24h_pct) > 0.0:
            gap_raw = float(vol24h_pct) / float(M9_GRID_VOL_DIVISOR or 10.0)
    except Exception as e:
        trig_det = {'src': f'm9_gap_vol_exc:{type(e).__name__}'}
    if gap_raw is None or float(gap_raw) <= 0.0:
        gap_raw = float(floor)
    gap = min(max(float(gap_raw), float(floor)), float(cap))
    det = {
        'coin': coin,
        'source': str((trig_det or {}).get('src') or '24h_volatility_x_10pct_then_floor'),
        'formula': 'm9_gap_pct = max(1%, min(m9_cap, vol24h_pct * 10%))',
        'vol_pct': _safe_float(vol24h_pct, None),
        'vol24h_pct': _safe_float(vol24h_pct, None),
        'raw_gap': float(gap_raw),
        'gap': float(gap),
        'floor': float(floor),
        'cap': float(cap),
        'symbol': str((trig_det or {}).get('symbol') or ''),
        'closed_1h_bars': int((trig_det or {}).get('closed_1h_bars') or 0),
        'trigger_floor_pct': float(floor),
        'trigger_cap_pct': float(cap),
        'trigger_pct': float(gap),
    }
    return float(gap), det

def _grid_ui_is_disabled():
    return True

def maybe_start_grid_ui():
    return False

def _grid_ui_read_jsonl_tail(fp, limit=200):
    try:
        if (not fp) or (not os.path.exists(fp)):
            return []
        out = []
        with open(fp, 'r', encoding='utf-8', errors='ignore') as f:
            for line in f:
                s = str(line).strip()
                if not s:
                    continue
                try:
                    out.append(json.loads(s))
                except Exception:
                    continue
        return out[-max(1, int(limit)):]
    except Exception:
        return []

def _grid_mark_from_sources(snapshot: dict, coin: str, platform: str, side: str = "") -> tuple:
    """网格 TP/汇总统一当前价真相源。"""
    try:
        pos = _snap_get_pos_any(snapshot if isinstance(snapshot, dict) else {}, platform, coin, side)
    except Exception:
        pos = {}
    if isinstance(pos, dict) and pos:
        for k in ("mark_px", "mark", "px", "mark_price", "last_px", "price"):
            try:
                v = pos.get(k)
                if v is None:
                    continue
                fv = float(v)
                if math.isfinite(fv) and fv > 0:
                    return float(fv), "positions_snapshot", dict(pos)
            except Exception:
                continue
    try:
        last = _get_last_snapshot_metric(coin, platform)
    except Exception:
        last = {}
    if isinstance(last, dict):
        try:
            fv = float(last.get("mark") or 0.0)
            if math.isfinite(fv) and fv > 0:
                return float(fv), "last_snapshot_metric", dict(last)
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_416', _e)
            pass
    try:
        items = list(_grid_book_layers_flat(include_closed=False) or [])
    except Exception:
        items = []
    coin_u = str(coin or "").upper().strip(); plat_u = str(platform or "").upper().strip(); side_u = str(side or "").upper().strip()
    for it in items:
        try:
            if str(it.get("coin") or "").upper().strip() != coin_u:
                continue
            if str(it.get("platform") or "").upper().strip() != plat_u:
                continue
            if side_u and str(it.get("side") or "").upper().strip() != side_u:
                continue
            for k in ("position_mark_px", "mark_px", "mark", "px"):
                v = it.get(k)
                if v is None and isinstance(it.get("meta"), dict):
                    v = it["meta"].get(k)
                if v is None:
                    continue
                fv = float(v)
                if math.isfinite(fv) and fv > 0:
                    return float(fv), "ledger_position_mark", {"layer_id": it.get("layer_id"), "id": it.get("id")}
        except Exception:
            continue
    return None, "missing", {}

def _grid_collect_open_layers_view(ledger_obj=None, snapshot: dict | None = None) -> list:
    rows = []
    snap = snapshot if isinstance(snapshot, dict) else {}
    obj = ledger_obj if ledger_obj is not None else (((globals().get('GRID_BOOK').data if ('GRID_BOOK' in globals() and globals().get('GRID_BOOK') is not None and hasattr(globals().get('GRID_BOOK'), 'data')) else None)) or {})
    items = []
    try:
        if isinstance(obj, dict):
            grids = obj.get('grids')
            if isinstance(grids, dict) and grids:
                for gid, g in list(grids.items()):
                    if not isinstance(g, dict):
                        continue
                    coin = str((g or {}).get('coin') or '').upper().strip()
                    plat = str((g or {}).get('platform') or '').upper().strip()
                    side = str((g or {}).get('side') or '').upper().strip()
                    for ly in list((g or {}).get('layers') or []):
                        if not isinstance(ly, dict):
                            continue
                        st = str((ly or {}).get('state') or (ly or {}).get('status') or '').upper().strip()
                        items.append({
                            'id': str((ly or {}).get('id') or (ly or {}).get('layer_id') or ''),
                            'grid_id': str(gid),
                            'layer_id': str((ly or {}).get('layer_id') or (ly or {}).get('id') or ''),
                            'layer_instance_id': str((ly or {}).get('layer_instance_id') or (ly or {}).get('instance_id') or ''),
                            'coin': coin, 'platform': plat, 'side': side, 'state': st,
                            'amount_u': float((ly or {}).get('amount_u') or (ly or {}).get('open_amount_u') or (ly or {}).get('open_notional_u') or 0.0),
                            'entry_price': float((ly or {}).get('entry_price') or (ly or {}).get('open_ref_px') or 0.0),
                            'tp_pct': float((ly or {}).get('tp_pct') or 0.0),
                            'tp_px': float((ly or {}).get('tp_px') or (ly or {}).get('tp_price') or 0.0),
                        })
            else:
                items = list((obj.get('items') or [])) if isinstance(obj, dict) else []
        else:
            if _m9_legacy_view_enabled():
                items = list((((getattr(obj, '_data', {}) or {}).get('items') or [])) if obj is not None else [])
            else:
                items = []
    except Exception:
        items = []

    for it in items:
        try:
            state = str(it.get('state') or it.get('status') or '').upper().strip()
            if state not in {'OPEN', 'ACTIVE', 'CLOSE_PENDING'}:
                continue
            coin = str(it.get('coin') or '').upper().strip()
            plat = str(it.get('platform') or it.get('plat') or '').upper().strip()
            side = str(it.get('side') or '').upper().strip()
            entry = float(it.get('entry_price') or it.get('open_ref_px') or it.get('layer_open_px') or 0.0)
            tp_px = float(it.get('tp_px') or it.get('tp_price') or 0.0)
            mark, mark_src, _detail = _grid_mark_from_sources(snap, coin, plat, side)
            hit = False
            gap_u = None
            if mark is not None and mark > 0 and tp_px > 0 and side in ('LONG', 'SHORT'):
                hit = (mark >= tp_px) if side == 'LONG' else (mark <= tp_px)
                gap_u = (tp_px - mark) if side == 'LONG' else (mark - tp_px)
            _meta = it.get('meta') if isinstance(it.get('meta'), dict) else {}
            _amt_det = _meta.get('amt_det') if isinstance(_meta.get('amt_det'), dict) else {}
            _grid_obs = _meta.get('grid_decision_obs') if isinstance(_meta.get('grid_decision_obs'), dict) else {}
            _gap_truth = _m9_layer_gap_truth_backfill(it, {'step_pct_range': _meta.get('step_pct_range'), 'step_pct': _meta.get('step_pct')})
            _plan_u = _safe_float(it.get('m9_open_plan_u') or _meta.get('m9_open_plan_u'), None)
            _tp_contract_u = _safe_float(it.get('m9_tp_contract_u') or _meta.get('m9_tp_contract_u'), None)
            _tp_contract_remaining_u = _safe_float(it.get('m9_tp_contract_remaining_u') or _meta.get('m9_tp_contract_remaining_u'), None)
            _bias_extra_u = _safe_float(it.get('m9_bias_extra_u') or _meta.get('m9_bias_extra_u'), None)
            _bias_carry_only = bool(it.get('m9_bias_carry_only') or it.get('bias_carry_only') or _meta.get('m9_bias_carry_only') or _meta.get('bias_carry_only'))
            rows.append({
                'id': str(it.get('id') or ''),
                'grid_id': str(it.get('grid_id') or it.get('gid') or ''),
                'layer_id': str(it.get('layer_id') or it.get('id') or ''),
                'layer_instance_id': str(it.get('layer_instance_id') or it.get('instance_id') or ''),
                'coin': coin,
                'platform': plat,
                'side': side,
                'state': state,
                'amount_u': float(it.get('amount_u') or it.get('open_amount_u') or 0.0),
                'plan_u': _plan_u,
                'tp_contract_u': _tp_contract_u,
                'tp_contract_remaining_u': _tp_contract_remaining_u,
                'bias_extra_u': _bias_extra_u,
                'bias_carry_only': bool(_bias_carry_only),
                'entry_price': entry,
                'tp_pct': float(it.get('tp_pct') or 0.0),
                'tp_px': tp_px,
                'tp_price': tp_px,
                'mark': (float(mark) if mark is not None else float('nan')),
                'mark_src': mark_src,
                'hit': bool(hit),
                'gap_u': gap_u,
                'amount_truth_reason': str(_amt_det.get('amount_truth_reason') or _meta.get('amount_truth_reason') or ''),
                'amount_model': str(_amt_det.get('amount_model') or _meta.get('amount_model') or ''),
                'bucket_amount_lo_u': _safe_float(_amt_det.get('bucket_amount_lo_u') or _amt_det.get('bucket_lo') or _amt_det.get('bucket_lo_u'), None),
                'bucket_amount_hi_u': _safe_float(_amt_det.get('bucket_amount_hi_u') or _amt_det.get('bucket_hi') or _amt_det.get('bucket_hi_u'), None),
                'bucket_picked_u': _safe_float(_amt_det.get('bucket_picked_u') or _amt_det.get('picked') or _amt_det.get('u'), None),
                'rsi_amount_detail': (dict(_amt_det.get('rsi_amount_detail') or {}) if isinstance(_amt_det.get('rsi_amount_detail'), dict) else {}),
                'rsi_amount_score': _safe_float((_amt_det.get('rsi_amount_detail') or {}).get('score') if isinstance(_amt_det.get('rsi_amount_detail'), dict) else None, None),
                'final_gap_pct': _safe_float((_gap_truth or {}).get('gap_truth_pct'), None),
                'gap_truth_pct': _safe_float((_gap_truth or {}).get('gap_truth_pct'), None),
                'gap_truth_raw_pct': _safe_float((_gap_truth or {}).get('gap_truth_raw_pct'), None),
                'gap_truth_source': str((_gap_truth or {}).get('gap_truth_source') or _grid_obs.get('final_gap_source') or ''),
                'gap_truth_components': (dict((_gap_truth or {}).get('gap_truth_components') or {}) if isinstance((_gap_truth or {}).get('gap_truth_components'), dict) else {}),
                'rsi_gap_pct': _safe_float(_grid_obs.get('rsi_gap_pct'), None),
                'adx_gap_pct': _safe_float(_grid_obs.get('adx_gap_pct'), None),
                'signal_gap_pct': _safe_float(_grid_obs.get('signal_gap_pct'), None),
            })
        except Exception:
            continue
    return rows

def _grid_ui_dashboard_ledger(ledger_obj=None, snapshot: dict | None = None) -> dict:
    try:
        rows = _grid_collect_open_layers_view(ledger_obj=ledger_obj, snapshot=snapshot if isinstance(snapshot, dict) else {})
        obj = ledger_obj if ledger_obj is not None else globals().get('_GRID_LEDGER')
        closed = []
        try:
            if isinstance(obj, dict):
                grids = obj.get('grids')
                if isinstance(grids, dict) and grids:
                    for gid, g in list(grids.items()):
                        if not isinstance(g, dict):
                            continue
                        for ly in list((g or {}).get('layers') or []):
                            if not isinstance(ly, dict):
                                continue
                            st = str((ly or {}).get('state') or (ly or {}).get('status') or '').upper().strip()
                            if st in ('CLOSED', 'CLOSE', 'DONE'):
                                closed.append(ly)
                else:
                    for it in list((obj or {}).get('items') or []):
                        if not isinstance(it, dict):
                            continue
                        st = str(it.get('state') or it.get('status') or '').upper().strip()
                        if st in ('CLOSED', 'CLOSE', 'DONE'):
                            closed.append(it)
            else:
                for it in list((((getattr(obj, '_data', {}) or {}).get('items') or [])) if obj is not None else []):
                    if not isinstance(it, dict):
                        continue
                    st = str(it.get('state') or it.get('status') or '').upper().strip()
                    if st in ('CLOSED', 'CLOSE', 'DONE'):
                        closed.append(it)
        except Exception:
            closed = []

        realized_today_u = 0.0
        close_cnt_today = 0
        partial_cnt_today = 0
        today = time.strftime('%Y-%m-%d', time.localtime(time.time()))
        for it in closed:
            try:
                ts = float(it.get('close_ts') or it.get('closed_ts') or 0.0)
                if ts > 0 and time.strftime('%Y-%m-%d', time.localtime(ts)) == today:
                    close_cnt_today += 1
                    realized_today_u += float(it.get('realized_u') or it.get('realized_u_est') or 0.0)
                    if 'partial' in str(it.get('close_reason') or '').lower():
                        partial_cnt_today += 1
            except Exception:
                continue
        return {
            'open_layers': int(len(rows)),
            'open_layer_cnt': int(len(rows)),
            'closed_layer_cnt': int(len(closed)),
            'closeable_layer_cnt': int(sum(1 for r in rows if bool(r.get('hit')))),
            'open_amount_u': round(sum(_safe_float((it or {}).get('amount_u'), 0.0) for it in rows), 4),
            'items_total': int(len(rows) + len(closed)),
            'close_cnt_today': int(close_cnt_today),
            'partial_cnt_today': int(partial_cnt_today),
            'realized_today_u': round(float(realized_today_u), 6),
            'source_format': 'unified_view',
        }
    except Exception:
        return {'open_layers': 0, 'open_layer_cnt': 0, 'closed_layer_cnt': 0, 'closeable_layer_cnt': 0, 'open_amount_u': 0.0, 'items_total': 0, 'close_cnt_today': 0, 'partial_cnt_today': 0, 'realized_today_u': 0.0, 'source_format': ''}

def iter_contexts(page: Any) -> List[Any]:
    ctxs: List[Any] = []
    if not _pw_guard(mod="IND", coin="", plat="VAR", act="read_ctx", stage="TV_ITER_CONTEXTS"):
        return ctxs
    try:
        ctxs.append(page)
    except Exception as _e:
        if _is_target_closed_exc(_e):
            raise _UiDeadError("iter_contexts.page", repr(_e)) from _e
        _log_exc_level(mod="IND", stage="TV_ITER_CONTEXTS_PAGE", level="B", e=_e, plat="VAR", act="read_ctx")

    try:
        for fr in getattr(page, "frames", []):
            ctxs.append(fr)
    except Exception as _e:
        if _is_target_closed_exc(_e):
            raise _UiDeadError("iter_contexts.frames", repr(_e)) from _e
        _log_exc_level(mod="IND", stage="TV_ITER_CONTEXTS_FRAMES", level="B", e=_e, plat="VAR", act="read_ctx")

    return ctxs

def legend_count(ctx: Any) -> int:
    if not _pw_guard(mod="IND", coin="", plat="VAR", act="legend_count", stage="TV_LEGEND_COUNT"):
        return 0
    try:
        return len(_pw_call("tv.legend_count", ctx.query_selector_all, '[data-name="legend-source-item"]'))
    except Exception as _e:
        if _is_target_closed_exc(_e):
            raise _UiDeadError("legend_count", repr(_e)) from _e
        return 0

def tv_wait_legend_ready(tv_page: Any, timeout_ms: int, coin: str = "") -> bool:
    end = time.time() + max(1, int(timeout_ms)) / 1000.0
    coin_u = str(coin or '').upper().strip()
    while time.time() < end:
        try:
            _cr = _ui_page_crash_probe(tv_page, coin=coin_u, platform='VAR')
        except Exception:
            _cr = {'crashed': False}
        if bool((_cr or {}).get('crashed')):
            raise _UiDeadError('tv_wait_legend_ready', f"page_crashed:{str((_cr or {}).get('reason') or '')}")
        best = 0
        for ctx in iter_contexts(tv_page):
            best = max(best, legend_count(ctx))
        if best > 0:
            return True
        time.sleep(0.6)
    return False

def tv_read_indicator_by_title(ctx: Any, name: str) -> Optional[float]:
    target = str(name or "").strip().upper()
    if not _pw_guard(mod="IND", coin="", plat="VAR", act=f"read_{target.lower()}", stage="TV_READ_INDICATOR"):
        return None
    try:
        rows = _pw_call(f"tv.read_indicator_by_title.{target}", ctx.query_selector_all, '[data-name="legend-source-item"]')
    except Exception as _e:
        if _is_target_closed_exc(_e):
            raise _UiDeadError(f"tv_read_indicator_by_title.{target}", repr(_e)) from _e
        return None

    for row in rows:
        try:
            title_el = _pw_call(
                f"tv.read_indicator_by_title.title_el.{target}",
                row.query_selector,
                '[data-name="legend-source-title"] .title, '
                '[data-name="legend-source-title"] .title-l31H9iuA, '
                '[data-name="legend-source-item-title"] .title'
            )
            if not title_el:
                continue
            title = (_pw_call(f"tv.read_indicator_by_title.title_text.{target}", title_el.inner_text) or "").strip().upper()

            if target == "ADX":
                if ("ADX" not in title) and ("DMI" not in title) and ("DIRECTIONAL" not in title):
                    continue
            else:
                if target not in title:
                    continue

            vals = _pw_call(
                f"tv.read_indicator_by_title.values.{target}",
                row.query_selector_all,
                ".valuesWrapper .valueValue, "
                ".valuesWrapper-l31H9iuA .valueValue-l31H9iuA, "
                ".valuesWrapper .valueValue-l31H9iuA"
            )
            nums: List[float] = []
            for v in vals:
                raw = (_pw_call(f"tv.read_indicator_by_title.value_text.{target}", v.inner_text) or "").strip().replace(",", "")
                m = re.search(r"[-+]?(?:\d+\.\d+|\d+)", raw)
                if not m:
                    continue
                try:
                    nums.append(float(m.group(0)))
                except Exception:
                    continue

            if not nums:
                continue

            if target == "ADX" and len(nums) >= 3:
                return float(nums[-1])
            return float(nums[0])
        except Exception:
            continue
    return None

def tv_sample_titles(tv_page: Any, max_items: int = 6) -> List[str]:
    out: List[str] = []
    if not _pw_guard(mod="IND", coin="", plat="VAR", act="sample_titles", stage="TV_SAMPLE_TITLES"):
        return out
    try:
        for ctx in iter_contexts(tv_page):
            rows = _pw_call("tv.sample_titles.rows", ctx.query_selector_all, '[data-name="legend-source-item"]')
            for row in rows[:max_items]:
                try:
                    title_el = _pw_call("tv.sample_titles.title_el", row.query_selector, '[data-name="legend-source-title"] .title, [data-name="legend-source-title"] .title-l31H9iuA')
                    if title_el:
                        t = (_pw_call("tv.sample_titles.inner_text", title_el.inner_text) or "").strip()
                        if t:
                            out.append(t)
                except Exception:
                    continue
            if out:
                return out
    except Exception as _e:
        if _is_target_closed_exc(_e):
            raise _UiDeadError("tv_sample_titles", repr(_e)) from _e
        _log_exc_level(mod="IND", stage="TV_SAMPLE_TITLES", level="B", e=_e, plat="VAR", act="sample_titles")

    return out

def _tv_indicator_snapshot(tv_page: Any) -> Tuple[Optional[float], Optional[float], int, List[str]]:
    """读取一帧 ADX/RSI 快照。返回(adx, rsi, legend_cnt, titles)。"""
    best_adx, best_rsi, best_cnt = None, None, -1
    for ctx in iter_contexts(tv_page):
        cnt = legend_count(ctx)
        if cnt > best_cnt:
            best_cnt = cnt
        adx = tv_read_indicator_by_title(ctx, "ADX")
        rsi = tv_read_indicator_by_title(ctx, "RSI")
        if adx is not None and rsi is not None:
            best_adx, best_rsi = adx, rsi
            break
        if best_adx is None and adx is not None:
            best_adx = adx
        if best_rsi is None and rsi is not None:
            best_rsi = rsi
    titles = tv_sample_titles(tv_page)
    return best_adx, best_rsi, int(best_cnt), list(titles or [])

def _tv_clear_hover_read_latest(tv_page: Any, coin: str = "") -> None:
    """把鼠标从 K 线区域挪开，避免 TradingView legend 读到“鼠标所在历史K线”的值。"""
    coin_u = str(coin or '').upper().strip()
    for _x, _y in ((18, 18), (40, 18), (120, 18)):
        try:
            _pw_call(f"tv.clear_hover.escape.{coin_u}", tv_page.keyboard.press, "Escape")
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_417', _e)
            pass
        try:
            _pw_call(f"tv.clear_hover.move.{coin_u}.{_x}.{_y}", tv_page.mouse.move, _x, _y)
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_418', _e)
            pass
        try:
            time.sleep(0.08)
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_419', _e)
            pass
def _tv_indicator_snapshot_stable(tv_page: Any, coin: str) -> Tuple[Optional[float], Optional[float], int, List[str], str]:
    """读取最新一根K线的稳定指标值。
    目的：修复鼠标停在历史K线上时，legend 返回历史 RSI/ADX 的问题。
    """
    coin_u = str(coin or '').upper().strip()
    _tv_clear_hover_read_latest(tv_page, coin_u)
    adx1, rsi1, cnt1, titles1 = _tv_indicator_snapshot(tv_page)
    try:
        time.sleep(0.25)
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_420', _e)
        pass
    _tv_clear_hover_read_latest(tv_page, coin_u)
    adx2, rsi2, cnt2, titles2 = _tv_indicator_snapshot(tv_page)

    best_cnt = max(int(cnt1), int(cnt2))
    titles = list(titles2 or titles1 or [])

    if adx1 is None or rsi1 is None or adx2 is None or rsi2 is None:
        adx = adx2 if adx2 is not None else adx1
        rsi = rsi2 if rsi2 is not None else rsi1
        return adx, rsi, best_cnt, titles, 'partial_unstable_sample'

    try:
        d_adx = abs(float(adx2) - float(adx1))
        d_rsi = abs(float(rsi2) - float(rsi1))
    except Exception:
        d_adx = 999.0
        d_rsi = 999.0

    if d_adx > 6.0 or d_rsi > 6.0:
        try:
            safe_log(lambda: f"[{now_ts()}] [IND][WARN] unstable_latest_sample coin={coin_u} adx1={adx1} adx2={adx2} rsi1={rsi1} rsi2={rsi2}")
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_421', _e)
            pass
        return None, None, best_cnt, titles, f'unstable_latest_sample d_adx={d_adx:.3f} d_rsi={d_rsi:.3f}'

    return float(adx2), float(rsi2), best_cnt, titles, 'stable_latest_sample'

def _m2_indicator_force_resync_var(tv_page: Any, coin: str, *, deadline_ts: float | None = None) -> Tuple[bool, str]:
    coin_u = str(coin or '').upper().strip()
    _left_ms = _m2_indicator_deadline_left_ms(deadline_ts, reserve_ms=900, floor_ms=0)
    if _left_ms <= 0:
        return False, 'coin_deadline_exhausted_before_force_resync'
    try:
        _pin('IND_FORCE_RESYNC_BEGIN', mod='M2', coin=coin_u, ok=1, plat='VAR', act='ind_refresh', stage='FORCE_RESYNC')
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_422', _e)
        pass
    ok = _exec_goto_coin_var(tv_page, coin_u, timeout_ms=min(1800, max(700, _left_ms)), allow_goto=False, ctx='IND_ADX_RSI')
    if not ok:
        return False, 'force_resync_switch_fail'
    _settle = min(0.45, max(0.12, _m2_indicator_deadline_left_sec(deadline_ts, reserve_sec=0.6)))
    if _settle > 0:
        try:
            _pw_wait_ms(tv_page, int(_settle * 1000), f"tv_force_resync.wait.{coin_u}")
        except _UiDeadError:
            raise
        except Exception:
            try:
                time.sleep(_settle)
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_423', _e)
                pass
    try:
        _det_coin = str(_detect_current_coin_var(tv_page) or '').upper().strip()
    except Exception:
        _det_coin = ''
    if _det_coin and _det_coin != coin_u:
        return False, f'coin_not_confirmed expect={coin_u} got={_det_coin}'
    return True, 'force_resync_ok'

def tv_read_adx_rsi_1h(tv_page: Any, coin: str, settle_s: float) -> Tuple[Optional[float], Optional[float], str]:
    coin_u = coin.upper().strip()
    _budget = _m2_indicator_stage_budget(coin_u, globals().get('_IND_REFRESH_PROFILE_SNAPSHOT'))
    try:
        _deadline_sec = float((_budget or {}).get('per_coin_deadline_sec') or M2_IND_PER_COIN_DEADLINE_SEC or 6.5)
    except Exception:
        _deadline_sec = 6.5
    _deadline_ts = float(time.monotonic()) + max(2.0, float(_deadline_sec))
    _skip = _m2_coin_platform_should_skip('VAR', coin_u)
    if bool((_skip or {}).get('skip')):
        return None, None, f"coin_platform_fused left={int((_skip or {}).get('left_sec') or 0)}s streak={int((_skip or {}).get('fail_streak') or 0)} reason={str((_skip or {}).get('last_reason') or '')}"

    try:
        _pin('IND_READ_BEGIN', mod='M2', coin=coin_u, ok=1, reason=f"budget={str((_budget or {}).get('bucket') or 'warm')} deadline={round(_deadline_sec, 2)}s", plat='VAR', act='ind_refresh', stage='READ_BEGIN')
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_424', _e)
        pass
    _pre_cr = _ui_page_crash_probe(tv_page, coin=coin_u, platform='VAR')
    if bool((_pre_cr or {}).get('crashed')):
        _m2_heavy_ui_recover(coin=coin_u, platform='VAR', reason='pre_switch_crash', crash_detail=_pre_cr)
        raise _UiDeadError('tv_read_adx_rsi_1h', f"page_crashed:{str((_pre_cr or {}).get('reason') or '')}")

    try:
        _pin('PAGE_TITLE', mod='M2', coin=coin_u, ok=1, reason=str((_pre_cr or {}).get('title') or '')[:120], plat='VAR', act='ind_refresh', stage='PAGE_CHECK')
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_425', _e)
        pass
    _sample_reserve_ms = int((_budget or {}).get('sample_reserve_ms') or 1800)
    _switch_timeout_ms = min(int((_budget or {}).get('switch_timeout_ms') or 2500), max(700, _m2_indicator_deadline_left_ms(_deadline_ts, reserve_ms=_sample_reserve_ms, floor_ms=0)))
    if _switch_timeout_ms <= 0:
        _m2_coin_platform_mark_fail('VAR', coin_u, reason='coin_deadline_exhausted_before_switch', fault_kind='deadline')
        return None, None, 'coin_deadline_exhausted_before_switch'

    _sw_t0 = float(time.monotonic())
    try:
        _pin('IND_SWITCH_BEGIN', mod='M2', coin=coin_u, ok=1, reason=f"switch_budget_ms={int(_switch_timeout_ms)} reserve_ms={int(_sample_reserve_ms)}", plat='VAR', act='ind_refresh', stage='SWITCH_BEGIN')
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_426', _e)
        pass
    ok = _exec_goto_coin_var(tv_page, coin_u, timeout_ms=int(_switch_timeout_ms), allow_goto=False, ctx='IND_ADX_RSI')
    try:
        _sw_cost_ms = int((float(time.monotonic()) - _sw_t0) * 1000.0)
        _pin('IND_SWITCH_DONE', mod='M2', coin=coin_u, ok=1 if ok else 0, reason=f"switch_cost_ms={_sw_cost_ms}", plat='VAR', act='ind_refresh', stage='SWITCH_DONE')
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_427', _e)
        pass
    if not ok:
        _m2_coin_platform_mark_fail('VAR', coin_u, reason='switch_fail_click_only', fault_kind='switch_fail')
        try:
            _readiness_set('ind', 'FAIL', f"switch_fail_click_only:{coin_u}", scope='local', source='tv_read_local')
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_428', _e)
            pass
        return None, None, 'switch_fail_click_only'

    _post_switch_cr = _ui_page_crash_probe(tv_page, coin=coin_u, platform='VAR')
    if bool((_post_switch_cr or {}).get('crashed')):
        _m2_heavy_ui_recover(coin=coin_u, platform='VAR', reason='post_switch_crash', crash_detail=_post_switch_cr)
        raise _UiDeadError('tv_read_adx_rsi_1h', f"page_crashed:{str((_post_switch_cr or {}).get('reason') or '')}")

    try:
        _settle_eff = max(0.15, min(float(settle_s or 0.0), float((_budget or {}).get('settle_max_sec') or 0.8), max(0.15, _m2_indicator_deadline_left_sec(_deadline_ts, reserve_sec=1.6))))
    except Exception:
        _settle_eff = max(0.15, min(0.6, _m2_indicator_deadline_left_sec(_deadline_ts, reserve_sec=1.6)))
    if _settle_eff > 0:
        try:
            _pw_wait_ms(tv_page, int(_settle_eff * 1000), f"tv_read_adx_rsi_1h.wait.{coin_u}")
        except _UiDeadError:
            raise
        except Exception:
            time.sleep(_settle_eff)

    try:
        _det_coin = str(_detect_current_coin_var(tv_page) or '').upper().strip()
    except Exception:
        _det_coin = ''
    if _det_coin and _det_coin != coin_u:
        _ok_resync, _resync_reason = _m2_indicator_force_resync_var(tv_page, coin_u, deadline_ts=_deadline_ts)
        if not _ok_resync:
            _m2_coin_platform_mark_fail('VAR', coin_u, reason=f"coin_not_confirmed:{coin_u}->{_det_coin}|{_resync_reason}", fault_kind='coin_not_confirmed')
            try:
                _readiness_set('ind', 'FAIL', f"coin_not_confirmed:{coin_u}->{_det_coin}", scope='local', source='tv_read_local')
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_429', _e)
                pass
            return None, None, f"coin_not_confirmed expect={coin_u} got={_det_coin} retry={_resync_reason}"

    _legend_timeout_ms = min(int((_budget or {}).get('legend_timeout_ms') or 1800), max(600, _m2_indicator_deadline_left_ms(_deadline_ts, reserve_ms=600, floor_ms=0)))
    if _legend_timeout_ms <= 0:
        _m2_coin_platform_mark_fail('VAR', coin_u, reason='coin_deadline_exhausted_before_legend', fault_kind='deadline')
        return None, None, 'coin_deadline_exhausted_before_legend'

    ready = tv_wait_legend_ready(tv_page, timeout_ms=int(_legend_timeout_ms), coin=coin_u)

    _warns: List[str] = []
    try:
        _titles = tv_sample_titles(tv_page) or []
        _tall = " | ".join([str(x) for x in _titles if x])
        if ("1h" not in _tall) and ("1H" not in _tall):
            _warns.append('tf_not_confirmed_expect_1h')
            try:
                safe_log(lambda: f"[{now_ts()}] [IND][WARN] tf_not_confirmed_expect_1h coin={coin_u} titles={_titles}")
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_430', _e)
                pass
        if ("Mark" not in _tall) and ("MARK" not in _tall):
            _warns.append('basis_not_mark')
            try:
                safe_log(lambda: f"[{now_ts()}] [IND][WARN] basis_not_mark coin={coin_u} titles={_titles}")
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_431', _e)
                pass
    except Exception:
        _titles = []

    if not ready:
        _ok_resync, _resync_reason = _m2_indicator_force_resync_var(tv_page, coin_u, deadline_ts=_deadline_ts)
        if _ok_resync:
            _legend_timeout_ms2 = min(1200, max(500, _m2_indicator_deadline_left_ms(_deadline_ts, reserve_ms=350, floor_ms=0)))
            if _legend_timeout_ms2 > 0:
                ready = tv_wait_legend_ready(tv_page, timeout_ms=int(_legend_timeout_ms2), coin=coin_u)
        if not ready:
            titles = tv_sample_titles(tv_page)
            _m2_coin_platform_mark_fail('VAR', coin_u, reason=f"legend_not_ready|{_resync_reason}", fault_kind='legend_not_ready')
            try:
                _readiness_set('ind', 'FAIL', f"legend_not_ready:{coin_u}", scope='local', source='tv_read_local')
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_432', _e)
                pass
            return None, None, f"legend_not_ready titles={titles} retry={_resync_reason}"

    _sample_left_ms = _m2_indicator_deadline_left_ms(_deadline_ts, reserve_ms=150, floor_ms=0)
    try:
        _pin('IND_SAMPLE_BEGIN', mod='M2', coin=coin_u, ok=1 if _sample_left_ms > 0 else 0, reason=f"sample_left_ms={int(_sample_left_ms)}", plat='VAR', act='ind_refresh', stage='SAMPLE_BEGIN')
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_433', _e)
        pass
    if _sample_left_ms <= 0:
        _m2_coin_platform_mark_fail('VAR', coin_u, reason='coin_deadline_exhausted_before_sample', fault_kind='deadline')
        return None, None, 'coin_deadline_exhausted_before_sample'

    _sp_t0 = float(time.monotonic())
    best_adx, best_rsi, best_cnt, titles, stable_reason = _tv_indicator_snapshot_stable(tv_page, coin_u)
    try:
        _sp_cost_ms = int((float(time.monotonic()) - _sp_t0) * 1000.0)
        _pin('IND_SAMPLE_DONE', mod='M2', coin=coin_u, ok=1 if (best_adx is not None and best_rsi is not None) else 0, reason=f"sample_cost_ms={_sp_cost_ms} sample_left_ms={int(_sample_left_ms)}", plat='VAR', act='ind_refresh', stage='SAMPLE_DONE')
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_434', _e)
        pass
    if best_adx is None or best_rsi is None:
        _m2_coin_platform_mark_fail('VAR', coin_u, reason=str(stable_reason or ''), fault_kind='indicator_partial')
        try:
            _readiness_set('ind', 'FAIL', f"{stable_reason}:{coin_u}", scope='local', source='tv_read_local')
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_435', _e)
            pass
        return None, None, f"{stable_reason} legend_cnt={best_cnt} titles={titles} warns={_warns}"

    _m2_coin_platform_mark_ok('VAR', coin_u)
    try:
        _readiness_set('ind', 'OK', f"ok:{coin_u}", scope='local', source='tv_read_local')
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_436', _e)
        pass
    _warn_tail = (f" warns={_warns}" if _warns else "")
    return best_adx, best_rsi, f"ok legend_cnt={best_cnt} titles={titles} stable={stable_reason} budget={str((_budget or {}).get('bucket') or 'warm')} deadline={round(_deadline_sec, 2)}s{_warn_tail}"

COINS_DEFAULT = ["SOL","BTC","ETH","HYPE","BNB","XRP","SUI","ADA"]

COIN_POOL_MAX_SLOTS_DEFAULT = 12
COIN_POOL_WAITING_KEEP = 20
COIN_POOL_WATCH_CANDIDATES_DEFAULT = 2
COIN_POOL_BINANCE_TOPN_DEFAULT = 30
COIN_POOL_TRACE_COINS_DEFAULT = 'EDGE'
COIN_POOL_REFRESH_MIN_SEC = 10800
COIN_POOL_REFRESH_MAX_SEC = 10800
COIN_POOL_STATE_CACHE: Dict[str, Any] = {}
COIN_POOL_NEXT_REFRESH_TS: float = 0.0
_COIN_POOL_LAST_FETCH_DIAG: Dict[str, Any] = {}
_COIN_POOL_MANUAL_COINS_LOCK: bool = False
_COIN_POOL_STABLE_EXACT = {
    "USDT", "USDC", "USDS", "FDUSD", "TUSD", "DAI", "USDE", "PYUSD", "USD0", "USDD", "FRAX", "USDY"
}

def _coin_pool_manual_lock_enabled() -> bool:
    try:
        return bool(globals().get('_COIN_POOL_MANUAL_COINS_LOCK'))
    except Exception:
        return False

def _coin_pool_enabled() -> bool:
    if _coin_pool_manual_lock_enabled():
        return False
    try:
        return bool(cfg_getf_runtime('COIN_POOL_DYNAMIC_ENABLE', 1.0) >= 0.5)
    except Exception:
        return True

COIN_POOL_BASE_LOCKED_COINS = tuple(str(x or '').upper().strip() for x in COINS_DEFAULT)
NEW_COIN_SINGLE_OPEN_MAX_U_DEFAULT = 1000.0
NEW_COIN_TOTAL_HARDCAP_U_DEFAULT = 1000.0
NEW_COIN_GRID_RSI_SCALE_DEFAULT = 1.0
NEW_COIN_GRID_GAP_FLOOR_PCT_DEFAULT = 0.01
NEW_COIN_GRID_GAP_MAX_PCT_DEFAULT = 0.05
NEW_COIN_B2_M10_TRIGGER_PCT_DEFAULT = 0.01  # legacy占位；主链已统一走 _tp_trigger_floor_pct()=1%
COIN_POOL_HEAD_FAIL_COOLDOWN_SEC_DEFAULT = 900.0

def _coin_pool_locked_base_coins() -> list[str]:
    try:
        return _coin_pool_dedupe(list(COIN_POOL_BASE_LOCKED_COINS or COINS_DEFAULT))
    except Exception:
        return _coin_pool_dedupe(list(COINS_DEFAULT or []))

def _coin_pool_is_base_locked_coin(coin: Any) -> bool:
    try:
        return str(coin or '').upper().strip() in set(COIN_POOL_BASE_LOCKED_COINS)
    except Exception:
        return False

def _coin_pool_is_dynamic_new_coin(coin: Any) -> bool:
    try:
        c = str(coin or '').upper().strip()
    except Exception:
        c = ''
    return bool(c) and (not _coin_pool_is_base_locked_coin(c))

def _new_coin_single_open_cap_u() -> float:
    try:
        v = float(cfg_getf_runtime('NEW_COIN_SINGLE_OPEN_MAX_U', float(NEW_COIN_SINGLE_OPEN_MAX_U_DEFAULT)) or NEW_COIN_SINGLE_OPEN_MAX_U_DEFAULT)
    except Exception:
        v = float(NEW_COIN_SINGLE_OPEN_MAX_U_DEFAULT)
    return float(max(10.0, min(v, 1000.0)))

def _new_coin_total_hardcap_u() -> float:
    try:
        v = float(cfg_getf_runtime('NEW_COIN_TOTAL_HARDCAP_U', float(NEW_COIN_TOTAL_HARDCAP_U_DEFAULT)) or NEW_COIN_TOTAL_HARDCAP_U_DEFAULT)
    except Exception:
        v = float(NEW_COIN_TOTAL_HARDCAP_U_DEFAULT)
    return float(max(_new_coin_single_open_cap_u(), min(v, 1000.0)))

def _b1_first_open_min_effective_u() -> float:
    """B1 最终最小有效下单额：爸爸口径，必须严格大于 150U，因此统一收口到 160U。"""
    return 160.0

def _m9_layer_min_effective_u(next_layer_no: Any = None, *, is_dynamic_new_coin: bool = False) -> float:
    """M9 分层最小有效下单额。

    爸爸新增口径：
    - L2（含冷启动首个真实网格层）最低必须严格大于 50U，因此统一收口到 60U；
    - 其余层沿用原口径：新币 10U，老币 GRID_ADD_U_MIN_DEFAULT。
    """
    try:
        layer_no = int(next_layer_no or 0)
    except Exception:
        layer_no = 0
    if layer_no == 2:
        return 60.0
    try:
        return float(10.0 if is_dynamic_new_coin else GRID_ADD_U_MIN_DEFAULT)
    except Exception:
        return 10.0 if is_dynamic_new_coin else 40.0

def _new_coin_grid_rsi_scale() -> float:
    """新币网格金额统一不额外缩放；该函数固定返回 1.0，确保调用点只走当前百分比口径。"""
    return 1.0

def _m9_rsi_pct_floor1_cap10(rsi: Any) -> dict:
    """M9 金额主链唯一百分比口径：服务于“本腿总名义 × RSI线性百分比（底板1%，上限10%）”。
    RSI=50 -> 0；其余走 1% 底板线性映射到 10%。"""
    try:
        rsi_f = float(rsi)
    except Exception:
        rsi_f = 50.0
    if not math.isfinite(rsi_f):
        rsi_f = 50.0
    rsi_clip = float(min(100.0, max(0.0, rsi_f)))
    distance = float(abs(rsi_clip - 50.0))
    strength = float(min(1.0, max(0.0, distance / 50.0)))
    floor_pct = 0.01
    max_pct = 0.10
    if abs(rsi_clip - 50.0) < 1e-9:
        pct = 0.0
        side = 'NONE'
    else:
        pct = float(floor_pct + strength * (max_pct - floor_pct))
        pct = float(min(max_pct, max(floor_pct, pct)))
        side = ('LONG' if rsi_clip > 50.0 else 'SHORT')
    return {
        'rsi': float(rsi_clip),
        'side': str(side),
        'rsi_strength': float(strength),
        'rsi_pct_floor': float(floor_pct),
        'rsi_pct_cap': float(max_pct),
        'rsi_pct_used': float(pct),
    }

def _m9_finalize_amount_contract_det(
    coin: Any,
    raw_u: Any,
    *,
    round10: bool = True,
    next_layer_no: Any = None,
    amount_model: str,
    amount_truth_reason: str,
    source: str,
    base_fields: Optional[Dict[str, Any]] = None,
) -> dict:
    coin_u = str(coin or '').upper().strip()
    is_new_coin = bool(coin_u) and bool(_coin_pool_is_dynamic_new_coin(coin_u))
    try:
        raw_amount_u = float(raw_u or 0.0)
    except Exception:
        raw_amount_u = 0.0
    if (not math.isfinite(raw_amount_u)) or raw_amount_u < 0.0:
        raw_amount_u = 0.0
    rounded_u = float(raw_amount_u)
    if round10 and rounded_u > 0.0:
        try:
            rounded_u = float(int(float(rounded_u) / 10.0 + 0.5) * 10)
        except Exception:
            pass
    final_u = float(max(0.0, rounded_u))
    try:
        coin_min_u = float(_m9_layer_min_effective_u(next_layer_no, is_dynamic_new_coin=is_new_coin))
    except Exception:
        coin_min_u = 60.0 if str(next_layer_no or '') == '2' else (10.0 if is_new_coin else 40.0)
    try:
        coin_max_u = float(_new_coin_single_open_cap_u() if is_new_coin else GRID_ADD_U_MAX_DEFAULT)
    except Exception:
        coin_max_u = 500.0 if is_new_coin else 300.0
    if raw_amount_u > 0.0:
        final_u = float(min(float(coin_max_u), max(float(coin_min_u), float(final_u))))
    out = {
        'coin': str(coin_u),
        'is_dynamic_new_coin': bool(is_new_coin),
        'amount_tag': ('(新)' if is_new_coin else ''),
        'amount_model': str(amount_model or ''),
        'amount_truth_reason': str(amount_truth_reason or ''),
        'base_rsi_map_amount_u': float(raw_amount_u),
        'bucket_picked_u': float(raw_amount_u),
        'bucket_amount_lo_u': float(raw_amount_u),
        'bucket_amount_hi_u': float(raw_amount_u),
        'new_coin_grid_rsi_scale': 1.0,
        'new_coin_grid_scaled_raw_u': float(raw_amount_u),
        'new_coin_grid_scaled_round10_u': float(rounded_u),
        'new_coin_grid_final_u': float(final_u),
        'new_coin_single_cap_u': (float(coin_max_u) if is_new_coin else None),
        'round10_applied': bool(round10),
        'source': str(source or ''),
    }
    if isinstance(base_fields, dict) and base_fields:
        out.update(dict(base_fields))
    return out

def _m9_fixed_rsi_amount_fallback_det(coin: Any, rsi: Any, *, round10: bool = True, next_layer_no: Any = None, fallback_reason: str = '') -> dict:
    coin_u = str(coin or '').upper().strip()
    is_new_coin = bool(coin_u) and bool(_coin_pool_is_dynamic_new_coin(coin_u))
    try:
        rsi_f = float(rsi)
    except Exception:
        rsi_f = 50.0
    if not math.isfinite(rsi_f):
        rsi_f = 50.0
    side = 'LONG' if rsi_f > 50.0 else ('SHORT' if rsi_f < 50.0 else 'NONE')
    if side == 'NONE':
        truth_text = '网格金额百分比映射失败，但 RSI=50 无允许方向，不触发固定金额兜底'
        if int(next_layer_no or 0) == 2:
            truth_text = str(truth_text) + '→L2最小60U'
        return _m9_finalize_amount_contract_det(
            coin_u,
            0.0,
            round10=round10,
            next_layer_no=next_layer_no,
            amount_model='m9_rsi_fixed_bucket_fallback_round10',
            amount_truth_reason=truth_text,
            source='m9_fixed_rsi_bucket_fallback',
            base_fields={
                'rsi': float(rsi_f),
                'side': str(side),
                'rsi_strength': 0.0,
                'rsi_pct_floor': 0.01,
                'rsi_pct_cap': 0.10,
                'rsi_pct_used': 0.0,
                'amount_fallback_used': True,
                'amount_fallback_reason': str(fallback_reason or 'pct_mapping_invalid'),
                'amount_primary_model': 'm9_rsi_leg_notional_pct_floor1_cap10_round10',
                'amount_primary_failed': True,
                'fixed_amount_fallback_used': True,
                'fixed_bucket_reason': 'rsi_eq_pivot_block',
            },
        )
    try:
        coin_min_u = float(_m9_layer_min_effective_u(next_layer_no, is_dynamic_new_coin=is_new_coin))
    except Exception:
        coin_min_u = 60.0 if str(next_layer_no or '') == '2' else (10.0 if is_new_coin else 40.0)
    try:
        coin_max_u = float(_new_coin_single_open_cap_u() if is_new_coin else GRID_ADD_U_MAX_DEFAULT)
    except Exception:
        coin_max_u = 500.0 if is_new_coin else 300.0
    try:
        fixed_target_u = float(_grid_size_u_by_rsi(side, rsi_f, u_min=float(coin_min_u), u_max=float(coin_max_u)) or 0.0)
    except Exception:
        fixed_target_u = 0.0
    truth_text = ('(新)网格金额百分比映射失败→改走固定金额RSI映射→整十→单笔安全帽' if is_new_coin else '网格金额百分比映射失败→改走固定金额RSI映射→整十')
    if int(next_layer_no or 0) == 2:
        truth_text = str(truth_text) + '→L2最小60U'
    return _m9_finalize_amount_contract_det(
        coin_u,
        fixed_target_u,
        round10=round10,
        next_layer_no=next_layer_no,
        amount_model='m9_rsi_fixed_bucket_fallback_round10',
        amount_truth_reason=truth_text,
        source='m9_fixed_rsi_bucket_fallback',
        base_fields={
            'rsi': float(rsi_f),
            'side': str(side),
            'rsi_strength': 0.0,
            'rsi_pct_floor': 0.01,
            'rsi_pct_cap': 0.10,
            'rsi_pct_used': 0.0,
            'amount_fallback_used': True,
            'amount_fallback_reason': str(fallback_reason or 'pct_mapping_invalid'),
            'amount_primary_model': 'm9_rsi_leg_notional_pct_floor1_cap10_round10',
            'amount_primary_failed': True,
            'fixed_amount_fallback_used': True,
            'fixed_bucket_reason': 'fixed_rsi_bucket_fallback_ok' if fixed_target_u > 0.0 else 'fixed_rsi_bucket_fallback_zero',
        },
    )

def _m9_leg_notional_pct_amount_det(coin: Any, rsi: Any, leg_total_notional_u: Any, *, round10: bool = True, next_layer_no: Any = None) -> dict:
    """M9 金额主链统一明细：百分比主链失败时，自动回退固定金额映射。

    主链：本腿总名义 × RSI线性百分比（底板1%，上限10%）→ 整十 → 单笔安全帽
    兜底：百分比映射异常/锚定腿名义无效时，改走固定金额 RSI 映射。

    爸爸新增口径：L2 最低必须严格大于 50U，统一收口到 60U。"""
    coin_u = str(coin or '').upper().strip()
    try:
        rsi_f = float(rsi)
    except Exception:
        return _m9_fixed_rsi_amount_fallback_det(coin_u, rsi, round10=round10, next_layer_no=next_layer_no, fallback_reason='pct_rsi_parse_fail')
    if not math.isfinite(rsi_f):
        return _m9_fixed_rsi_amount_fallback_det(coin_u, rsi_f, round10=round10, next_layer_no=next_layer_no, fallback_reason='pct_rsi_nonfinite')
    try:
        leg_total = float(leg_total_notional_u or 0.0)
    except Exception:
        return _m9_fixed_rsi_amount_fallback_det(coin_u, rsi_f, round10=round10, next_layer_no=next_layer_no, fallback_reason='pct_leg_total_parse_fail')
    if (not math.isfinite(leg_total)) or leg_total < 0.0:
        return _m9_fixed_rsi_amount_fallback_det(coin_u, rsi_f, round10=round10, next_layer_no=next_layer_no, fallback_reason='pct_leg_total_invalid')
    pct_det = dict(_m9_rsi_pct_floor1_cap10(rsi_f) or {})
    pct_used = float(pct_det.get('rsi_pct_used') or 0.0)
    side = str(pct_det.get('side') or '')
    if side == 'NONE' or pct_used <= 0.0:
        is_new_coin = bool(coin_u) and bool(_coin_pool_is_dynamic_new_coin(coin_u))
        truth_text = ('(新)网格金额=本腿总名义×RSI线性百分比（底板1%，上限10%）→整十→单笔安全帽' if is_new_coin else '网格金额=本腿总名义×RSI线性百分比（底板1%，上限10%）→整十')
        if int(next_layer_no or 0) == 2:
            truth_text = str(truth_text) + '→L2最小60U'
        out = _m9_finalize_amount_contract_det(
            coin_u,
            0.0,
            round10=round10,
            next_layer_no=next_layer_no,
            amount_model='m9_rsi_leg_notional_pct_floor1_cap10_round10',
            amount_truth_reason=truth_text,
            source='m9_leg_notional_pct_contract',
            base_fields={
                'leg_total_notional_u': float(max(0.0, leg_total)),
                'base_leg_notional_u': float(max(0.0, leg_total)),
                'rsi': float(pct_det.get('rsi') or 50.0),
                'side': str(side),
                'rsi_strength': float(pct_det.get('rsi_strength') or 0.0),
                'rsi_pct_floor': float(pct_det.get('rsi_pct_floor') or 0.01),
                'rsi_pct_cap': float(pct_det.get('rsi_pct_cap') or 0.10),
                'rsi_pct_used': float(pct_used),
                'amount_fallback_used': False,
                'amount_fallback_reason': '',
                'amount_primary_model': 'm9_rsi_leg_notional_pct_floor1_cap10_round10',
                'amount_primary_failed': False,
                'fixed_amount_fallback_used': False,
            },
        )
        return out
    raw_u = float(leg_total * pct_used) if leg_total > 0.0 else 0.0
    if (not math.isfinite(raw_u)) or raw_u <= 0.0:
        return _m9_fixed_rsi_amount_fallback_det(coin_u, rsi_f, round10=round10, next_layer_no=next_layer_no, fallback_reason='pct_raw_amount_invalid')
    is_new_coin = bool(coin_u) and bool(_coin_pool_is_dynamic_new_coin(coin_u))
    truth_text = ('(新)网格金额=本腿总名义×RSI线性百分比（底板1%，上限10%）→整十→单笔安全帽' if is_new_coin else '网格金额=本腿总名义×RSI线性百分比（底板1%，上限10%）→整十')
    if int(next_layer_no or 0) == 2:
        truth_text = str(truth_text) + '→L2最小60U'
    return _m9_finalize_amount_contract_det(
        coin_u,
        raw_u,
        round10=round10,
        next_layer_no=next_layer_no,
        amount_model='m9_rsi_leg_notional_pct_floor1_cap10_round10',
        amount_truth_reason=truth_text,
        source='m9_leg_notional_pct_contract',
        base_fields={
            'leg_total_notional_u': float(leg_total),
            'base_leg_notional_u': float(leg_total),
            'rsi': float(pct_det.get('rsi') or 50.0),
            'side': str(side),
            'rsi_strength': float(pct_det.get('rsi_strength') or 0.0),
            'rsi_pct_floor': float(pct_det.get('rsi_pct_floor') or 0.01),
            'rsi_pct_cap': float(pct_det.get('rsi_pct_cap') or 0.10),
            'rsi_pct_used': float(pct_used),
            'amount_fallback_used': False,
            'amount_fallback_reason': '',
            'amount_primary_model': 'm9_rsi_leg_notional_pct_floor1_cap10_round10',
            'amount_primary_failed': False,
            'fixed_amount_fallback_used': False,
        },
    )

def _new_coin_grid_rsi_amount_det(amount_u: Any, coin: Any, *, round10: bool = True, next_layer_no: Any = None) -> dict:
    """M9 金额落盘明细。

    现口径：
    - 新老币统一按“本腿总名义 × RSI线性百分比（带1%底板，最高10%）”先算出金额；
    - 这里不再做新币额外缩量，只负责把传入金额按整十/单笔安全帽收口落盘；
    - 爸爸新增口径：L2 最低必须严格大于 50U，统一收口到 60U。
    """
    try:
        amt = float(amount_u or 0.0)
    except Exception:
        amt = 0.0
    try:
        coin_u = str(coin or '').upper().strip()
    except Exception:
        coin_u = ''
    is_new_coin = bool(coin_u) and bool(_coin_pool_is_dynamic_new_coin(coin_u))
    try:
        cap_u = float(_new_coin_single_open_cap_u())
    except Exception:
        cap_u = 500.0
    raw_scaled = float(max(0.0, amt))
    rounded_scaled = float(raw_scaled)
    if round10 and rounded_scaled > 0.0:
        try:
            rounded_scaled = float(int(float(rounded_scaled) / 10.0 + 0.5) * 10)
        except Exception:
            pass
    final_u = float(max(0.0, rounded_scaled))
    layer_min_u = float(_m9_layer_min_effective_u(next_layer_no, is_dynamic_new_coin=is_new_coin))
    if raw_scaled > 0.0:
        final_u = float(min(float(cap_u), max(float(layer_min_u), float(final_u))))
    truth_text = ('(新)网格金额=本腿总名义×RSI线性百分比（底板1%，上限10%）→整十→单笔安全帽' if is_new_coin else '网格金额=本腿总名义×RSI线性百分比（底板1%，上限10%）→整十')
    if int(next_layer_no or 0) == 2:
        truth_text = str(truth_text) + '→L2最小60U'
    return {
        'coin': str(coin_u),
        'is_dynamic_new_coin': bool(is_new_coin),
        'amount_tag': ('(新)' if is_new_coin else ''),
        'amount_model': 'm9_rsi_leg_notional_pct_floor1_cap10_round10',
        'amount_truth_reason': truth_text,
        'base_rsi_map_amount_u': float(amt),
        'bucket_picked_u': float(amt),
        'bucket_amount_lo_u': float(amt),
        'bucket_amount_hi_u': float(amt),
        'new_coin_grid_rsi_scale': 1.0,
        'new_coin_grid_scaled_raw_u': float(raw_scaled),
        'new_coin_grid_scaled_round10_u': float(rounded_scaled),
        'new_coin_grid_final_u': float(final_u),
        'new_coin_single_cap_u': (float(cap_u) if is_new_coin else None),
        'round10_applied': bool(round10),
        'source': 'm9_leg_notional_pct_contract',
    }

def _scale_new_coin_grid_amount_u(amount_u: Any, coin: Any, *, round10: bool = True, next_layer_no: Any = None) -> float:
    try:
        det = dict(_new_coin_grid_rsi_amount_det(amount_u, coin, round10=round10, next_layer_no=next_layer_no) or {})
    except Exception:
        det = {}
    try:
        return float(det.get('new_coin_grid_final_u') or 0.0)
    except Exception:
        return 0.0

def _m9_new_coin_grid_contract_detail(req_any: Any) -> dict:
    """从请求里提取“新币 M9 金额唯一真相源”。

    返回：
    - ok/is_new_coin/expected_final_u
    - 不再把旧 bucket lo/hi 当成新币最终金额硬夹回去
    """
    out = {
        'ok': False,
        'is_new_coin': False,
        'expected_final_u': 0.0,
        'base_u': 0.0,
        'raw_u': 0.0,
        'round10_u': 0.0,
        'source': '',
        'amount_tag': '',
        'truth_text': '',
    }
    try:
        req = req_any if isinstance(req_any, dict) else {}
        meta = req.get('meta') if isinstance(req.get('meta'), dict) else {}
        grid_obs = {}
        if isinstance(meta.get('grid_decision_obs'), dict):
            grid_obs = dict(meta.get('grid_decision_obs') or {})
        elif isinstance(req.get('grid_decision_obs'), dict):
            grid_obs = dict(req.get('grid_decision_obs') or {})
        bucket_det = dict((grid_obs.get('bucket_det') or {}) if isinstance(grid_obs.get('bucket_det'), dict) else {})
        coin_u = str(req.get('coin') or meta.get('coin') or '').upper().strip()
        is_new = bool(coin_u) and bool(_coin_pool_is_dynamic_new_coin(coin_u))
        is_new = bool(is_new or grid_obs.get('is_dynamic_new_coin') or bucket_det.get('amount_tag') == '(新)' or bucket_det.get('new_coin_grid_amount_truth_text') or grid_obs.get('new_coin_grid_amount_truth_text'))
        out['is_new_coin'] = bool(is_new)
        if not is_new:
            return out
        def _pick_float(*vals):
            for v in vals:
                fv = _safe_float(v, 0.0)
                if fv > 0.0:
                    return float(fv)
            return 0.0
        expected = _pick_float(
            grid_obs.get('new_coin_grid_final_u'),
            bucket_det.get('new_coin_grid_final_u'),
            bucket_det.get('picked_after_new_coin_scale'),
            grid_obs.get('amount_after_cap_u') if bool(grid_obs.get('amount_tag') == '(新)') else None,
            grid_obs.get('amount_u') if bool(grid_obs.get('amount_tag') == '(新)') else None,
        )
        raw_u = _pick_float(grid_obs.get('new_coin_grid_scaled_raw_u'), bucket_det.get('new_coin_grid_scaled_raw_u'))
        round10_u = _pick_float(grid_obs.get('new_coin_grid_scaled_round10_u'), bucket_det.get('new_coin_grid_scaled_round10_u'))
        base_u = _pick_float(grid_obs.get('amount_before_new_coin_scale_u'), bucket_det.get('picked_before_new_coin_scale'), grid_obs.get('coin_base_amount_u'), bucket_det.get('picked'))
        next_layer_no = int(_safe_float(grid_obs.get('next_layer_no'), _safe_float(meta.get('layer_no'), _safe_float(req.get('layer_no'), 0))) or 0)
        if expected <= 0.0 and base_u > 0.0:
            det = dict(_new_coin_grid_rsi_amount_det(base_u, coin_u, round10=True, next_layer_no=next_layer_no) or {})
            expected = _pick_float(det.get('new_coin_grid_final_u'))
            raw_u = _pick_float(raw_u, det.get('new_coin_grid_scaled_raw_u'))
            round10_u = _pick_float(round10_u, det.get('new_coin_grid_scaled_round10_u'))
        if expected <= 0.0:
            return out
        out.update({
            'ok': True,
            'expected_final_u': float(expected),
            'base_u': float(base_u),
            'raw_u': float(raw_u),
            'round10_u': float(round10_u),
            'source': 'm9_leg_notional_pct_contract',
            'amount_tag': '(新)',
            'truth_text': str(bucket_det.get('new_coin_grid_amount_truth_text') or grid_obs.get('new_coin_grid_amount_truth_text') or '(新)网格金额=本腿总名义×RSI线性百分比（底板1%，上限10%）→整十→单笔安全帽'),
        })
        return out
    except Exception:
        return out

def _new_coin_grid_gap_min_pct() -> float:
    try:
        v = float(cfg_getf_runtime('NEW_COIN_GRID_GAP_FLOOR_PCT', float(NEW_COIN_GRID_GAP_FLOOR_PCT_DEFAULT)) or NEW_COIN_GRID_GAP_FLOOR_PCT_DEFAULT)
    except Exception:
        v = float(NEW_COIN_GRID_GAP_FLOOR_PCT_DEFAULT)
    return float(min(max(v, 0.01), 0.20))

def _new_coin_grid_gap_max_pct() -> float:
    try:
        v = float(cfg_getf_runtime('NEW_COIN_GRID_GAP_MAX_PCT', float(NEW_COIN_GRID_GAP_MAX_PCT_DEFAULT)) or NEW_COIN_GRID_GAP_MAX_PCT_DEFAULT)
    except Exception:
        v = float(NEW_COIN_GRID_GAP_MAX_PCT_DEFAULT)
    lo = float(_new_coin_grid_gap_min_pct())
    return float(min(max(v, lo), 0.20))

def _new_coin_grid_gap_floor_pct() -> float:
    return float(_new_coin_grid_gap_min_pct())

def _dynamic_new_coin_round_clamp_u(amount_u: Any, coin: Any) -> float:
    try:
        amt = float(amount_u or 0.0)
    except Exception:
        amt = 0.0
    if amt <= 0.0:
        return 0.0
    try:
        coin_u = str(coin or '').upper().strip()
    except Exception:
        coin_u = ''
    if (not coin_u) or (not _coin_pool_is_dynamic_new_coin(coin_u)):
        return float(max(0.0, amt))
    cap_u = float(_new_coin_single_open_cap_u())
    _raw_amt = float(amt)
    if _raw_amt > float(cap_u) + 1e-9:
        try:
            _record_new_coin_cap_event(coin_u, 'amount_scale_round_clamp', 'new_coin_single_open_cap_clamp', mode='clamp', detail={'raw_u': float(_raw_amt), 'final_u': float(cap_u), 'cap_u': float(cap_u)})
        except Exception:
            pass
    amt = min(float(amt), float(cap_u))
    try:
        amt = float(int(float(amt) / 10.0 + 0.5) * 10)
    except Exception:
        try:
            amt = float(int((float(amt) + 5.0) // 10) * 10)
        except Exception:
            pass
    amt = min(float(amt), float(cap_u))
    if amt <= 0.0:
        return 0.0
    return float(max(10.0, amt))

def _dynamic_new_coin_total_notional_u(snapshot: dict | None, coin: Any) -> float:
    try:
        c = str(coin or '').upper().strip()
    except Exception:
        c = ''
    if not c:
        return 0.0
    total = 0.0
    try:
        total += abs(float(_get_notional_u(snapshot or {}, c, 'EXT') or 0.0))
    except Exception:
        pass
    try:
        total += abs(float(_get_notional_u(snapshot or {}, c, 'VAR') or 0.0))
    except Exception:
        pass
    return float(max(0.0, total))

def _coin_pool_live_dual_platform_openable(coin: Any, timeout_s: float = 3.0) -> tuple[bool, str, dict]:
    try:
        c = str(coin or '').upper().strip()
    except Exception:
        c = ''
    detail = {'coin': c}
    if not c:
        return False, 'coin_missing', detail
    if not _coin_pool_is_dynamic_new_coin(c):
        detail['allow'] = 'base_locked_coin'
        return True, 'base_locked_coin', detail

    try:
        _st = _coin_pool_state_load(force=False)
    except Exception:
        _st = {}
    try:
        _st_ts = float((_st or {}).get('ts') or 0.0)
    except Exception:
        _st_ts = 0.0
    try:
        _state_age = max(0.0, float(time.time()) - float(_st_ts)) if _st_ts > 0 else 1e12
    except Exception:
        _state_age = 1e12
    _diag = dict((_st or {}).get('last_refresh_diag') or {}) if isinstance(_st, dict) else {}
    _waiting = _coin_pool_dedupe(list((_st or {}).get('waiting_queue') or [])) if isinstance(_st, dict) else []
    _ranked_rows = [r for r in list((_st or {}).get('ranked_openable_universe') or []) if isinstance(r, dict)] if isinstance(_st, dict) else []
    _ranked_coins = _coin_pool_dedupe([str((r or {}).get('coin') or '').upper().strip() for r in _ranked_rows])
    _state_all_ok = bool((_diag or {}).get('all_platform_ok'))
    detail.update({
        'state_age_sec': float(_state_age),
        'state_all_platform_ok': bool(_state_all_ok),
        'state_waiting_head': (_waiting[0] if _waiting else ''),
        'state_waiting_queue': list(_waiting[:10]),
    })
    if _state_all_ok and (_state_age <= 120.0) and (c in set(_waiting) or c in set(_ranked_coins)):
        detail['allow'] = 'dual_platform_tradeable_cached'
        detail['cached_from_state'] = True
        detail['cached_coin_in_waiting'] = bool(c in set(_waiting))
        detail['cached_coin_in_ranked'] = bool(c in set(_ranked_coins))
        return True, 'dual_platform_tradeable_cached', detail

    ext_set, ext_ok, ext_reason = _coin_pool_ext_active_set(timeout_s=timeout_s)
    var_set, var_ok, var_reason = _coin_pool_var_active_set(timeout_s=timeout_s)
    detail.update({'ext_ok': bool(ext_ok), 'ext_reason': str(ext_reason), 'var_ok': bool(var_ok), 'var_reason': str(var_reason)})
    if not ext_ok:
        return False, 'ext_tradeability_unknown', detail
    if not var_ok:
        return False, 'var_tradeability_unknown', detail
    in_ext = _coin_pool_selection_strict_contains(c, ext_set)
    in_var = _coin_pool_selection_strict_contains(c, var_set)
    detail.update({'in_ext': in_ext, 'in_var': in_var})
    if not in_ext:
        return False, 'coin_not_tradeable_on_ext', detail
    if not in_var:
        return False, 'coin_not_tradeable_on_var', detail
    return True, 'dual_platform_tradeable', detail

def _coin_pool_max_slots() -> int:
    try:
        v = int(cfg_getf_runtime('COIN_POOL_MAX_SLOTS', float(COIN_POOL_MAX_SLOTS_DEFAULT)) or COIN_POOL_MAX_SLOTS_DEFAULT)
    except Exception:
        v = int(COIN_POOL_MAX_SLOTS_DEFAULT)
    return int(max(1, min(v, 50)))

def _coin_pool_watch_candidates() -> int:
    try:
        v = int(cfg_getf_runtime('COIN_POOL_WATCH_CANDIDATES', float(COIN_POOL_WATCH_CANDIDATES_DEFAULT)) or COIN_POOL_WATCH_CANDIDATES_DEFAULT)
    except Exception:
        v = int(COIN_POOL_WATCH_CANDIDATES_DEFAULT)
