def _coin_pool_state_default() -> dict:
    return {
        'version': 1,
        'ts': 0.0,
        'active_holding_coins': [],
        'waiting_queue': [],
        'blocked_reopen_after_exit': [],
        'ranked_openable_universe': [],
        'binance_symbol_map': {},
        'last_refresh_diag': {},
        'waiting_skip_until': {},
    }

def _coin_pool_state_scrub(obj: dict | None = None) -> dict:
    st = dict(obj or {}) if isinstance(obj, dict) else _coin_pool_state_default()
    nowv = float(time.time())
    active = _coin_pool_dedupe(list(st.get('active_holding_coins') or []))
    blocked = _coin_pool_dedupe(list(st.get('blocked_reopen_after_exit') or []))
    waiting_raw = _coin_pool_dedupe(list(st.get('waiting_queue') or []))
    waiting_skip_raw = st.get('waiting_skip_until') if isinstance(st.get('waiting_skip_until'), dict) else {}
    waiting_skip: dict[str, dict] = {}
    for coin, meta in list(waiting_skip_raw.items()):
        c = str(coin or '').upper().strip()
        if not c:
            continue
        info = dict(meta or {}) if isinstance(meta, dict) else {'until_ts': meta}
        try:
            until_ts = float(info.get('until_ts') or 0.0)
        except Exception:
            until_ts = 0.0
        if until_ts <= nowv:
            continue
        info['until_ts'] = float(until_ts)
        info['reason'] = str(info.get('reason') or '')[:160]
        waiting_skip[c] = info
    overlap = [c for c in waiting_raw if c in set(active) or c in set(blocked)]
    waiting = [c for c in waiting_raw if c not in set(active) and c not in set(blocked)]
    st['active_holding_coins'] = active
    st['blocked_reopen_after_exit'] = blocked
    st['waiting_queue'] = waiting
    st['waiting_skip_until'] = waiting_skip
    if overlap:
        diag = dict(st.get('last_refresh_diag') or {}) if isinstance(st.get('last_refresh_diag'), dict) else {}
        diag['pool_state_conflict'] = True
        diag['pool_state_conflict_reason'] = 'active_waiting_overlap_auto_scrub'
        diag['pool_state_conflict_coins'] = list(overlap[:10])
        st['last_refresh_diag'] = diag
    return st

def _coin_pool_waiting_skip_candidates(state: dict | None = None) -> dict:
    st = _coin_pool_state_scrub(state if isinstance(state, dict) else _coin_pool_state_load(force=False))
    out = st.get('waiting_skip_until') if isinstance(st.get('waiting_skip_until'), dict) else {}
    return dict(out)

def _coin_pool_mark_waiting_skip(coin: Any, reason: str, *, cooldown_sec: float | None = None, detail: dict | None = None) -> dict:
    c = str(coin or '').upper().strip()
    if not c:
        return {}
    try:
        sec = float(cooldown_sec if cooldown_sec is not None else cfg_getf_runtime('COIN_POOL_HEAD_FAIL_COOLDOWN_SEC', float(COIN_POOL_HEAD_FAIL_COOLDOWN_SEC_DEFAULT)) or COIN_POOL_HEAD_FAIL_COOLDOWN_SEC_DEFAULT)
    except Exception:
        sec = float(COIN_POOL_HEAD_FAIL_COOLDOWN_SEC_DEFAULT)
    sec = max(60.0, min(sec, 7200.0))
    st = _coin_pool_state_scrub(_coin_pool_state_load(force=False))
    mp = st.get('waiting_skip_until') if isinstance(st.get('waiting_skip_until'), dict) else {}
    rec = {
        'until_ts': float(time.time()) + float(sec),
        'reason': str(reason or '')[:160],
        'ts': float(time.time()),
        'detail': dict(detail or {}) if isinstance(detail, dict) else ({'detail': str(detail)} if detail not in (None, '') else {}),
    }
    mp[c] = rec
    st['waiting_skip_until'] = mp
    _coin_pool_state_save(st)
    try:
        _pin('COIN_POOL_WAITING_SKIP', mod='POOL', coin=c, ok=0, reason=str(reason or 'waiting_head_temporarily_skipped'), detail={'until_ts': rec['until_ts'], **(rec.get('detail') or {})})
    except Exception:
        pass
    return rec

def _coin_pool_head_fail_should_skip(reason: Any) -> bool:
    r = _normalize_reason_code(reason)
    return r in (
        'new_coin_single_open_cap_block', 'new_coin_total_cap_no_room', 'new_coin_total_cap_block',
        'block_reopen_after_exit', 'coin_not_tradeable_on_ext', 'coin_not_tradeable_on_var',
        'ext_tradeability_unknown', 'var_tradeability_unknown', 'human_verify_active', 'human_verify_recovering',
        'dual_platform_guard_fail', 'symbol_not_tradeable'
    ) or r.startswith(('coin_not_tradeable_on_', 'human_verify_'))

def _coin_pool_effective_waiting_queue(st: dict | None = None) -> tuple[list[str], dict, list[str]]:
    state = _coin_pool_state_scrub(st if isinstance(st, dict) else _coin_pool_state_load(force=False))
    _src_state = st if isinstance(st, dict) else None
    waiting = _coin_pool_dedupe(list(state.get('waiting_queue') or []))
    waiting_skip = _coin_pool_waiting_skip_candidates(state)
    skipped = [c for c in waiting if c in waiting_skip]
    effective = [c for c in waiting if c not in waiting_skip]

    try:
        active = set(_coin_pool_dedupe(list(state.get('active_holding_coins') or [])))
        blocked = set(_coin_pool_dedupe(list(state.get('blocked_reopen_after_exit') or [])))
        max_slots = int(_coin_pool_max_slots())
        free_slots = max(0, int(max_slots) - int(len(active)))
        ranked_rows = list(state.get('ranked_openable_universe') or [])
        need_fill = bool(free_slots > 0 and waiting and (not effective))
        appended = []
        if need_fill and ranked_rows:
            for row in ranked_rows:
                if isinstance(row, dict):
                    coin = str((row or {}).get('coin') or '').upper().strip()
                else:
                    coin = str(row or '').upper().strip()
                if (not coin) or (coin in active) or (coin in blocked) or (coin in waiting_skip) or (coin in waiting):
                    continue
                waiting.append(coin)
                appended.append(coin)
                effective = [c for c in waiting if c not in waiting_skip]
                if len(effective) >= int(free_slots):
                    break
            if appended:
                state['waiting_queue'] = _coin_pool_dedupe(waiting)
                try:
                    diag = dict(state.get('last_refresh_diag') or {}) if isinstance(state.get('last_refresh_diag'), dict) else {}
                    diag['queue_auto_advance_after_skip'] = list(appended[:10])
                    diag['queue_auto_advance_reason'] = 'waiting_head_skipped_promote_next_ranked'
                    state['last_refresh_diag'] = diag
                except Exception:
                    pass
                if isinstance(_src_state, dict):
                    try:
                        _src_state['waiting_queue'] = list(state.get('waiting_queue') or [])
                        _src_state['last_refresh_diag'] = dict(state.get('last_refresh_diag') or {})
                    except Exception:
                        pass
                else:
                    try:
                        _coin_pool_state_save(state)
                    except Exception:
                        pass
                waiting = _coin_pool_dedupe(list(state.get('waiting_queue') or []))
                skipped = [c for c in waiting if c in waiting_skip]
                effective = [c for c in waiting if c not in waiting_skip]
    except Exception:
        pass
    return effective, waiting_skip, skipped

def _coin_pool_refresh_after_confirmed_close(snapshot: dict | None, post_state: dict | None, scopes: list[dict] | None = None, *, reason: str = '', src_mod: str = '') -> dict:
    """确认平仓后，立刻回收队列里的旧 skip，并按 post_state 真相重建候补。"""
    rep = {'ok': False, 'released_skip': [], 'flat_coins': [], 'active_after': [], 'waiting_after': []}
    try:
        work = copy.deepcopy(snapshot if isinstance(snapshot, dict) else {})
    except Exception:
        work = dict(snapshot or {}) if isinstance(snapshot, dict) else {}
    try:
        pos = work.get('positions') if isinstance(work.get('positions'), dict) else {}
        work['positions'] = pos
        scope_rows = [dict(x) for x in list(scopes or []) if isinstance(x, dict)]
        coins = _coin_pool_dedupe([str((x or {}).get('coin') or '').upper().strip() for x in scope_rows if str((x or {}).get('coin') or '').strip()])
        if (not coins) and isinstance(post_state, dict):
            coins = _coin_pool_dedupe([str(x or '').upper().strip() for x in [post_state.get('coin'), post_state.get('symbol')] if str(x or '').strip()])
        for coin in coins:
            for plat in ('EXT', 'VAR'):
                leg_map = pos.get(plat) if isinstance(pos.get(plat), dict) else {}
                pos[plat] = leg_map
                lk = plat.lower()
                has_v = post_state.get(f'{lk}_has') if isinstance(post_state, dict) else None
                notional_v = post_state.get(f'{lk}_notional_u') if isinstance(post_state, dict) else None
                side_v = post_state.get(f'{lk}_side') if isinstance(post_state, dict) else None
                if has_v is None and notional_v is None and side_v is None:
                    continue
                try:
                    nv = abs(float(notional_v or 0.0))
                except Exception:
                    nv = 0.0
                hv = bool(has_v) and nv > 1e-9
                leg_map[coin] = {
                    'side': (str(side_v or '').upper().strip() if hv else 'NONE'),
                    'notional_u': (float(nv) if hv else 0.0),
                    'has': bool(hv),
                    'reason': 'state_commit_postcheck',
                }
        st = _coin_pool_state_scrub(_coin_pool_state_load(force=False))
        skip_map = st.get('waiting_skip_until') if isinstance(st.get('waiting_skip_until'), dict) else {}
        changed = False
        for coin in coins:
            if _is_coin_flat(work, coin):
                rep['flat_coins'].append(coin)
                if coin in skip_map:
                    skip_map.pop(coin, None)
                    rep['released_skip'].append(coin)
                    changed = True
        if changed:
            st['waiting_skip_until'] = skip_map
            _coin_pool_state_save(st)
        _eff_before, _skip_before, _skipped_before = _coin_pool_effective_waiting_queue(st)
        refreshed = _coin_pool_refresh_runtime_state(work, base_coins=_coin_pool_locked_base_coins(), force=True)
        st_after = _coin_pool_state_scrub(_coin_pool_state_load(force=False))
        _eff_after, _skip_after, _skipped_after = _coin_pool_effective_waiting_queue(st_after)
        _waiting_after_source = 'runtime_refresh'
        if (not _eff_after):
            try:
                st_fallback = _coin_pool_state_scrub(dict(st or {}))
                if changed:
                    st_fallback['waiting_skip_until'] = dict(skip_map)
                _eff_fb, _skip_fb, _skipped_fb = _coin_pool_effective_waiting_queue(st_fallback)
                if _eff_fb:
                    st_after['waiting_queue'] = _coin_pool_dedupe(list(st_fallback.get('waiting_queue') or []))
                    if isinstance(st_fallback.get('ranked_openable_universe'), list) and st_fallback.get('ranked_openable_universe'):
                        st_after['ranked_openable_universe'] = list(st_fallback.get('ranked_openable_universe') or [])
                    st_after['waiting_skip_until'] = dict(st_fallback.get('waiting_skip_until') or {})
                    _coin_pool_state_save(st_after)
                    _eff_after, _skip_after, _skipped_after = _eff_fb, _skip_fb, _skipped_fb
                    _waiting_after_source = 'fallback_existing_ranked'
            except Exception:
                pass
        rep['ok'] = True
        rep['active_after'] = list((st_after.get('active_holding_coins') or [])[:20]) if isinstance(st_after, dict) else []
        rep['waiting_after'] = list(_eff_after[:20])
        rep['waiting_after_source'] = str(_waiting_after_source)
        rep['waiting_raw_after'] = list((st_after.get('waiting_queue') or [])[:20]) if isinstance(st_after, dict) else []
        rep['waiting_skip_after'] = list((list(_skip_after.keys()) if isinstance(_skip_after, dict) else [])[:20])
        rep['effective_waiting_before_refresh'] = list(_eff_before[:20])
        rep['skipped_waiting_before_refresh'] = list(_skipped_before[:20])
        rep['reason'] = str(reason or '')
        rep['src_mod'] = str(src_mod or '')
    except Exception as _e:
        rep['error'] = repr(_e)
    return rep

def _coin_pool_state_load(force: bool = False) -> dict:
    global COIN_POOL_STATE_CACHE
    if (not force) and isinstance(COIN_POOL_STATE_CACHE, dict) and COIN_POOL_STATE_CACHE:
        return COIN_POOL_STATE_CACHE
    try:
        fp = _coin_pool_state_fp()
        obj = safe_read_json(fp, _coin_pool_state_default())
        if not isinstance(obj, dict):
            obj = _coin_pool_state_default()
    except Exception:
        obj = _coin_pool_state_default()
    for k, dv in _coin_pool_state_default().items():
        obj.setdefault(k, copy.deepcopy(dv) if isinstance(dv, (dict, list)) else dv)
    try:
        obj['active_holding_coins'] = [str(x or '').upper().strip() for x in list(obj.get('active_holding_coins') or []) if str(x or '').strip()]
        obj['waiting_queue'] = [str(x or '').upper().strip() for x in list(obj.get('waiting_queue') or []) if str(x or '').strip()]
        obj['blocked_reopen_after_exit'] = [str(x or '').upper().strip() for x in list(obj.get('blocked_reopen_after_exit') or []) if str(x or '').strip()]
        bsm = obj.get('binance_symbol_map') or {}
        if isinstance(bsm, dict):
            obj['binance_symbol_map'] = {str(k or '').upper().strip(): str(v or '').upper().strip() for k, v in bsm.items() if str(k or '').strip() and str(v or '').strip()}
        else:
            obj['binance_symbol_map'] = {}
    except Exception:
        obj = _coin_pool_state_default()
    obj = _coin_pool_state_scrub(obj)
    COIN_POOL_STATE_CACHE = obj
    return COIN_POOL_STATE_CACHE

def _coin_pool_state_save(st: dict | None = None) -> None:
    global COIN_POOL_STATE_CACHE
    obj = st if isinstance(st, dict) else _coin_pool_state_load(force=False)
    if not isinstance(obj, dict):
        obj = _coin_pool_state_default()
    obj = _coin_pool_state_scrub(obj)
    obj['ts'] = float(time.time())
    COIN_POOL_STATE_CACHE = obj
    try:
        safe_write_json(_coin_pool_state_fp(), obj)
    except Exception as _e:
        _log_exc(mod='POOL', stage='STATE_SAVE', e=_e)

def _coin_pool_dedupe(items: list[str]) -> list[str]:
    out: list[str] = []
    seen: set[str] = set()
    for x in list(items or []):
        s = str(x or '').upper().strip()
        if not s or s in seen:
            continue
        out.append(s)
        seen.add(s)
    return out

def _coin_pool_is_stable_like(coin: str) -> bool:
    c = str(coin or '').upper().strip()
    if not c:
        return True
    if c in _COIN_POOL_STABLE_EXACT:
        return True
    if c.endswith(('USD', 'USDT', 'USDC', 'USDS')):
        return True
    bad_tokens = ('USD', 'STABLE', 'WRAP', 'BRIDGE', 'BRIDGED', 'SYNTH', 'INDEX')
    return any(tok in c for tok in bad_tokens)

def _coin_pool_extract_base_coin(raw: Any) -> str:
    try:
        s = str(raw or '').strip().upper()
    except Exception:
        s = ''
    if not s:
        return ''
    for sep in ('/', '-', '_', ':'):
        if sep in s:
            s = s.split(sep, 1)[0].strip()
            break
    for suf in ('USDT', 'USD', 'PERP', 'SWAP'):
        if s.endswith(suf) and len(s) > len(suf):
            s = s[:-len(suf)].strip()
            break
    return ''.join(ch for ch in s if ch.isalnum()).upper()

def _coin_pool_selection_strict_name(raw: Any) -> str:
    """
    选币主链专用：先做平台内部原名规范化（去 -USD / USDT 等后缀），
    再折叠到统一 canonical coin（单币真相源）。

    例：
    - Binance/VAR: 1000PEPE -> 1000PEPE
    - EXT: kPEPE-USD -> 1000PEPE

    人话：
    - 以后不是“原样硬比名字”，而是“先转成同一真名再做交集”。
    - 所以 VAR 的 1000PEPE 和 EXT 的 kPEPE，在选币/递补/可交易核验里必须算同一个币。
    """
    return _ext_canonical_coin(_coin_pool_extract_base_coin(raw))

def _m2_scan_canonical_coin(raw: Any, platform_name: Any = '') -> str:
    """M2 扫描主链统一真名。

    人话：
    - 持仓扫描/真实持仓发现时，不要把 VAR 的 ETHPERP / ZECPERP 这种原名直接塞进运行币池；
    - 统一先去后缀、再折叠 alias，保证扫描集和策略集都看到同一个真名。
    """
    try:
        _plat = str(platform_name or '').upper().strip()
    except Exception:
        _plat = ''
    try:
        _raw = str(raw or '').strip()
    except Exception:
        _raw = ''
    if not _raw:
        return ''
    try:
        return _coin_pool_selection_strict_name(_raw)
    except Exception:
        try:
            if _plat == 'VAR':
                _raw = _raw.replace('-PERP', 'PERP')
            return _ext_canonical_coin(_coin_pool_extract_base_coin(_raw))
        except Exception:
            return ''

def _coin_pool_selection_strict_contains(coin: Any, platform_names: set[str] | None = None) -> bool:
    """选币主链：允许已登记的 canonical/alias 统一折叠后再严格命中。"""
    try:
        c = _coin_pool_selection_strict_name(coin)
    except Exception:
        c = ''
    if not c:
        return False
    try:
        s = set(_coin_pool_selection_strict_name(x) for x in list(platform_names or set()) if str(x or '').strip())
        s.discard('')
    except Exception:
        s = set()
    return bool(c in s)

def _coin_pool_symbol_observe_meta(coin: Any = '', symbol: Any = '') -> dict:
    try:
        c = str(coin or '').upper().strip()
    except Exception:
        c = ''
    try:
        s = str(symbol or '').upper().strip()
    except Exception:
        s = ''
    reasons: list[str] = []
    if c and c.isdigit():
        reasons.append('coin_is_pure_digit')
    if c and (not re.fullmatch(r'[A-Z0-9]+', c)):
        reasons.append('coin_has_non_alnum')
    if c and any(ch.isdigit() for ch in c) and (not c.isdigit()):
        reasons.append('coin_mixed_alnum')
    if s and c and s not in (c, f'{c}USDT'):
        reasons.append(f'symbol_coin_mismatch:{s}')
    return {
        'coin': c,
        'symbol': s,
        'symbol_warning': bool(reasons),
        'symbol_warning_reason': '|'.join(reasons),
        'symbol_warning_list': list(reasons),
    }

def _coin_pool_unique_urls(urls: list[str] | tuple[str, ...] | None = None) -> list[str]:
    out: list[str] = []
    seen: set[str] = set()
    for raw in list(urls or []):
        try:
            u = str(raw or '').strip()
        except Exception:
            u = ''
        if not u:
            continue
        key = u.lower()
        if key in seen:
            continue
        seen.add(key)
        out.append(u)
    return out

def _coin_pool_http_headers(kind: str = '') -> dict:
    kind_u = str(kind or '').lower().strip()
    headers = {
        'Accept': 'application/json',
        'User-Agent': str(os.getenv('COIN_POOL_HTTP_USER_AGENT', 'Mozilla/5.0 ChatGPT-OAI/coin-pool')).strip(),
    }
    try:
        if kind_u == 'ext':
            api_key = str(os.getenv('COIN_POOL_EXT_API_KEY') or os.getenv('EXT_API_KEY') or '').strip()
            if api_key:
                headers['X-Api-Key'] = api_key
    except Exception:
        pass
    return headers

def _coin_pool_http_json_detail(url: str, timeout_s: float = 6.0, *, headers: dict | None = None) -> tuple[Any, str, dict]:
    meta = {'url': str(url or '').strip()}
    try:
        import urllib.request
        import urllib.error
        req = urllib.request.Request(str(url), headers=dict(headers or {}))
        with urllib.request.urlopen(req, timeout=float(timeout_s or 6.0)) as resp:
            try:
                status = int(getattr(resp, 'status', 0) or resp.getcode() or 0)
            except Exception:
                status = 0
            raw = resp.read().decode('utf-8', errors='ignore')
            meta.update({'status': int(status), 'raw_head': str(raw[:300])})
            try:
                return json.loads(raw), f'http_ok:{int(status)}', meta
            except Exception as _e:
                meta['parse_exc'] = repr(_e)
                return None, f'json_parse_fail:{type(_e).__name__}', meta
    except urllib.error.HTTPError as _e:
        raw = ''
        try:
            raw = _e.read().decode('utf-8', errors='ignore')
        except Exception:
            raw = ''
        meta.update({'status': int(getattr(_e, 'code', 0) or 0), 'raw_head': str(raw[:300]), 'exc': repr(_e)})
        return None, f'http_error:{int(getattr(_e, "code", 0) or 0)}', meta
    except urllib.error.URLError as _e:
        meta.update({'exc': repr(_e), 'reason': repr(getattr(_e, 'reason', ''))})
        return None, f'url_error:{type(getattr(_e, "reason", _e)).__name__}', meta
    except Exception as _e:
        meta.update({'exc': repr(_e)})
        return None, f'request_exc:{type(_e).__name__}', meta

def _coin_pool_http_json(url: str, timeout_s: float = 6.0, *, headers: dict | None = None) -> Any:
    try:
        js, _reason, _meta = _coin_pool_http_json_detail(url, timeout_s=timeout_s, headers=headers)
        return js
    except Exception:
        return None

def _coin_pool_collect_pre_positions_live_coins(snapshot: dict | None = None) -> list[str]:
    """持仓前真相：来自 M2 轻量 live-position 发现阶段的币集合。

    用途：让公共K线/选币可以前置到完整持仓扫描之前，仍然把
    已知活跃持仓币当成 active truth，不再被 await_scan_truth_before_select 卡住。
    """
    snap = snapshot if isinstance(snapshot, dict) else {}
    out: list[str] = []
    try:
        raw = snap.get('raw') if isinstance(snap, dict) else {}
        if isinstance(raw, dict):
            for key in ('scan_live_position_coins_ext', 'scan_live_position_coins_var', 'pre_positions_live_coins', 'pre_positions_active_coins'):
                vals = raw.get(key) or []
                if isinstance(vals, (list, tuple, set)):
                    out.extend([_ext_canonical_coin(x) for x in list(vals) if str(x or '').strip()])
    except Exception:
        pass
    return _coin_pool_dedupe([_ext_canonical_coin(x) for x in out if str(x or '').strip()])

def _coin_pool_collect_snapshot_coins(snapshot: dict | None = None) -> list[str]:
    snap = snapshot if isinstance(snapshot, dict) else {}
    out: list[str] = []
    try:
        pos = snap.get('positions')
        if isinstance(pos, dict):
            for plat in ('EXT', 'VAR'):
                pd = pos.get(plat) or {}
                if isinstance(pd, dict):
                    out.extend([_ext_canonical_coin(k) for k in pd.keys() if str(k or '').strip()])
        elif isinstance(pos, list):
            for row in pos:
                if isinstance(row, dict):
                    c = _ext_canonical_coin(row.get('coin') or row.get('symbol') or '')
                    if c:
                        out.append(c)
    except Exception:
        pass
    try:
        out.extend(_coin_pool_collect_pre_positions_live_coins(snap))
    except Exception:
        pass
    return _coin_pool_dedupe([_ext_canonical_coin(x) for x in out if str(x or '').strip()])

def _coin_pool_snapshot_has_positions_truth(snapshot: dict | None = None) -> bool:
    return _snapshot_positions_verified(snapshot)

def _coin_pool_has_position(snapshot: dict | None, coin: str) -> bool:
    c = str(coin or '').upper().strip()
    if not c:
        return False
    try:
        for p in ('EXT', 'VAR'):
            pos = _get_position(snapshot if isinstance(snapshot, dict) else {}, c, p) or {}
            side = str(pos.get('side') or '').upper().strip()
            notional = float(pos.get('notional_u') or pos.get('value_u') or 0.0)
            if side in ('LONG', 'SHORT') and abs(notional) > 1e-6:
                return True
            if bool(pos.get('has_position')) and abs(notional) > 1e-6:
                return True
    except Exception:
        return False
    try:
        pre_live = set(_coin_pool_collect_pre_positions_live_coins(snapshot if isinstance(snapshot, dict) else {}))
        if c in pre_live:
            return True
    except Exception:
        pass
    return False

def _coin_pool_has_grid_activity(coin: str) -> bool:
    c = str(coin or '').upper().strip()
    if not c:
        return False
    try:
        gb = globals().get('GRID_BOOK')
        if gb is None:
            return False
        data = getattr(gb, 'data', None)
        grids = ((data or {}).get('grids') or {}) if isinstance(data, dict) else {}
        for gid, g in list(grids.items()):
            if not isinstance(g, dict):
                continue
            gc = str(g.get('coin') or g.get('symbol') or '').upper().strip()
            if gc != c:
                continue
            try:
                if hasattr(gb, 'open_layers_count') and int(gb.open_layers_count(str(gid)) or 0) > 0:
                    return True
            except Exception:
                pass
            layers = list(g.get('layers') or g.get('open_layers') or [])
            for ly in layers:
                if not isinstance(ly, dict):
                    continue
                st = str(ly.get('status') or '').lower().strip()
                n0 = float(ly.get('notional_u') or ly.get('amount_u') or ly.get('value_u') or 0.0)
                if st not in ('closed', 'done', 'filled', 'flat', 'tp_done'):
                    return True
                if abs(n0) > 1e-6:
                    return True
            if bool(g.get('pending_close_layers') or g.get('close_pending') or g.get('reentry')):
                return True
    except Exception:
        return False
    return False

def _coin_pool_reopen_task_contains(coin: str) -> bool:
    c = str(coin or '').upper().strip()
    if not c:
        return False
    try:
        task = _reopen_task_get()
        if not isinstance(task, dict) or not task:
            return False
        rows = [str(x or '').upper().strip() for x in list(task.get('coins') or []) if str(x or '').strip()]
        return c in set(rows)
    except Exception:
        return False

def _coin_pool_reopen_task_counts_as_live(coin: str) -> bool:
    c = str(coin or '').upper().strip()
    if not c:
        return False
    try:
        if not _coin_pool_reopen_task_contains(c):
            return False
        st = _coin_pool_state_load(force=False)
        blocked = set(_coin_pool_dedupe(list((st or {}).get('blocked_reopen_after_exit') or []))) if isinstance(st, dict) else set()
        if c in blocked:
            return False
        return True
    except Exception:
        return False

def _coin_pool_coin_has_live_state(coin: str, snapshot: dict | None = None) -> bool:
    c = str(coin or '').upper().strip()
    if not c:
        return False
    if _coin_pool_has_position(snapshot, c):
        return True
    if _coin_pool_reopen_task_counts_as_live(c):
        return True
    if _coin_pool_has_grid_activity(c):
        if _coin_pool_snapshot_has_positions_truth(snapshot):
            try:
                if _is_coin_flat(snapshot if isinstance(snapshot, dict) else {}, c):
                    return False
            except Exception:
                return False
        return True
    return False

def _coin_pool_is_fully_exited(coin: str, snapshot: dict | None = None) -> bool:
    c = str(coin or '').upper().strip()
    if not c:
        return False
    try:
        if not _coin_confirmed_flat(snapshot, c):
            return False
    except Exception:
        return False
    if _coin_pool_has_grid_activity(c):
        return False
    if _coin_pool_reopen_task_counts_as_live(c):
        return False
    return True

def _coin_pool_collect_active_holding_coins(snapshot: dict | None = None, fallback_coins: list[str] | None = None) -> list[str]:
    st = _coin_pool_state_load(force=False)
    blocked = set(_coin_pool_dedupe(list((st or {}).get('blocked_reopen_after_exit') or []))) if isinstance(st, dict) else set()
    base = []
    base.extend(list(st.get('active_holding_coins') or []))
    base.extend(list(fallback_coins or []))
    base.extend(_coin_pool_collect_snapshot_coins(snapshot))
    try:
        task = _reopen_task_get()
        if isinstance(task, dict):
            task_coins = [str(x or '').upper().strip() for x in list(task.get('coins') or []) if str(x or '').strip()]
            base.extend([c for c in task_coins if c not in blocked])
    except Exception:
        pass
    base = _coin_pool_dedupe(base)
    out = []
    for c in base:
        if (_coin_pool_coin_has_live_state(c, snapshot)
                or (c in (st.get('active_holding_coins') or []) and not _coin_confirmed_flat(snapshot, c))):
            out.append(c)
    return _coin_pool_dedupe(out)

def _coin_pool_diag_runtime_sync(diag: dict | None = None, st: dict | None = None, *, active_cnt: int | None = None, free_slots: int | None = None, max_slots: int | None = None, reason: str = '', trigger: str = '') -> dict:
    d = dict(diag or {}) if isinstance(diag, dict) else {}
    state = _coin_pool_state_scrub(st if isinstance(st, dict) else _coin_pool_state_load(force=False))
    active = _coin_pool_dedupe(list(state.get('active_holding_coins') or []))
    waiting = _coin_pool_dedupe(list(state.get('waiting_queue') or []))
    blocked = _coin_pool_dedupe(list(state.get('blocked_reopen_after_exit') or []))
    max_slots_v = int(max_slots if max_slots is not None else _coin_pool_max_slots())
    active_cnt_v = int(active_cnt if active_cnt is not None else len(active))
    free_slots_v = int(free_slots if free_slots is not None else max(0, int(max_slots_v) - int(active_cnt_v)))
    d['active_cnt'] = int(active_cnt_v)
    d['free_slots'] = int(free_slots_v)
    d['max_slots'] = int(max_slots_v)
    d['active_coins'] = list(active)
    d['blocked_cnt'] = int(len(blocked))
    d['blocked_reopen_coins'] = list(blocked)
    d['queue_head'] = str((waiting[0] if waiting else ''))
    d['queue_preview'] = list(waiting[:20])
    d['snapshot_truth_ready'] = bool(d.get('snapshot_truth_ready', True))
    d['runtime_sync_reason'] = str(reason or 'runtime_state_sync')
    if str(trigger or '').strip():
        d['runtime_sync_trigger'] = str(trigger or '')
    return d

def _coin_pool_calc_binance_24h_volatility_from_1h_klines(rows: Any, *, now_ms: int | None = None) -> dict:
    out = {
        'ok': False,
        'reason': '',
        'volatility_pct': 0.0,
        'hourly_range_avg_pct': 0.0,
        'quote_volume_1h_24_sum': 0.0,
        'closed_1h_bars': 0,
        'tr_bars': 0,
        'last_closed_open_time_ms': 0,
        'last_closed_close_time_ms': 0,
    }
    try:
        now_ms_v = int(now_ms or int(time.time() * 1000))
    except Exception:
        now_ms_v = int(time.time() * 1000)
    parsed = []
    for row in list(rows or []):
        if not isinstance(row, list) or len(row) < 8:
            continue
        try:
            open_t = int(float(row[0] or 0))
            high = float(row[2] or 0.0)
            low = float(row[3] or 0.0)
            close = float(row[4] or 0.0)
            close_t = int(float(row[6] or 0))
            quote_vol = float(row[7] or 0.0)
        except Exception:
            continue
        if close <= 0.0:
            continue
        parsed.append({
            'open_time': int(open_t),
            'close_time': int(close_t),
            'high': float(high),
            'low': float(low),
            'close': float(close),
            'quote_vol': float(max(quote_vol, 0.0)),
        })
    if not parsed:
        out['reason'] = 'kline_parse_empty'
        return out
    parsed = sorted(parsed, key=lambda x: int(x.get('open_time') or 0))
    closed = [r for r in parsed if int(r.get('close_time') or 0) < int(now_ms_v)]
    out['closed_1h_bars'] = int(len(closed))
    if len(closed) < 24:
        out['reason'] = f'insufficient_closed_1h_bars:{len(closed)}'
        return out
    window = closed[-24:]
    prev_close = None
    if len(closed) >= 25:
        try:
            prev_close = float(closed[-25].get('close') or 0.0)
        except Exception:
            prev_close = None
    trs = []
    ranges = []
    quote_vol_sum = 0.0
    for row in window:
        try:
            high = float(row.get('high') or 0.0)
            low = float(row.get('low') or 0.0)
            close = float(row.get('close') or 0.0)
            qv = float(row.get('quote_vol') or 0.0)
        except Exception:
            continue
        if close <= 0.0:
            out['reason'] = 'close_non_positive'
            return out
        tr = float(max(high - low, 0.0))
        if prev_close is not None and prev_close > 0.0:
            tr = float(max(tr, abs(high - prev_close), abs(low - prev_close)))
        trs.append(float(max(tr, 0.0)))
        ranges.append(((high - low) / abs(close)) * 100.0 if abs(close) > 1e-12 else 0.0)
        quote_vol_sum += float(max(qv, 0.0))
        prev_close = close
    if len(trs) < 24:
        out['tr_bars'] = int(len(trs))
        out['reason'] = f'insufficient_tr_bars:{len(trs)}'
        return out
    try:
        current_price = float(window[-1].get('close') or 0.0)
    except Exception:
        current_price = 0.0
    if current_price <= 0.0:
        out['reason'] = 'current_price_non_positive'
        return out
    try:
        avg_tr = float(sum(float(x) for x in trs) / float(len(trs)))
        vol_pct = float((avg_tr / abs(current_price)) * 100.0)
    except Exception:
        out['reason'] = 'volatility_calc_fail'
        return out
    out.update({
        'ok': True,
        'reason': 'ok',
        'volatility_pct': float(max(vol_pct, 0.0)),
        'hourly_range_avg_pct': float(sum(ranges) / float(len(ranges))) if ranges else 0.0,
        'quote_volume_1h_24_sum': float(max(quote_vol_sum, 0.0)),
        'closed_1h_bars': int(len(closed)),
        'tr_bars': int(len(trs)),
        'last_closed_open_time_ms': int(window[-1].get('open_time') or 0),
        'last_closed_close_time_ms': int(window[-1].get('close_time') or 0),
    })
    return out

def _coin_pool_fetch_binance_symbol_24h_metrics(base: str, sym: str, timeout_s: float, headers: dict | None = None) -> dict:
    """兼容旧调用名，但内部已统一改为币安现货公共K线，不再走 fapi 合约公共接口。"""
    out = {
        'symbol': str(sym or '').upper().strip(),
        'ok': False,
        'reason': '',
        'volatility_pct': 0.0,
        'hourly_range_avg_pct': 0.0,
        'quote_volume_1h_24_sum': 0.0,
        'closed_1h_bars': 0,
        'tr_bars': 0,
        'http_reason': '',
        'http_status': 0,
        'last_closed_open_time_ms': 0,
        'last_closed_close_time_ms': 0,
    }
    url = f'{str(base).rstrip("/")}/api/v3/klines?symbol={str(sym or "").upper().strip()}&interval=1h&limit=30'
    js, why, meta = _coin_pool_http_json_detail(url, timeout_s=min(float(timeout_s or 6.0), 4.5), headers=headers)
    out['http_reason'] = str(why or '')
    try:
        out['http_status'] = int((meta or {}).get('status') or 0)
    except Exception:
        out['http_status'] = 0
    if not isinstance(js, list) or (not js):
        out['reason'] = f'kline_fetch_fail:{why}'
        return out
    det = _coin_pool_calc_binance_24h_volatility_from_1h_klines(js)
    out.update({
        'ok': bool(det.get('ok')),
        'reason': str(det.get('reason') or ''),
        'volatility_pct': float(det.get('volatility_pct') or 0.0),
        'hourly_range_avg_pct': float(det.get('hourly_range_avg_pct') or 0.0),
        'quote_volume_1h_24_sum': float(det.get('quote_volume_1h_24_sum') or 0.0),
        'closed_1h_bars': int(det.get('closed_1h_bars') or 0),
        'tr_bars': int(det.get('tr_bars') or 0),
        'last_closed_open_time_ms': int(det.get('last_closed_open_time_ms') or 0),
        'last_closed_close_time_ms': int(det.get('last_closed_close_time_ms') or 0),
    })
    return out


_SPOT_PUBLIC_BINANCE_BASE = str(os.getenv('IND_PUBLIC_KLINE_BINANCE_BASE', 'https://data-api.binance.vision')).rstrip('/')
_SPOT_PUBLIC_MEXC_BASE = str(os.getenv('IND_PUBLIC_KLINE_MEXC_BASE', 'https://api.mexc.com')).rstrip('/')
_SPOT_PUBLIC_GATE_BASE = str(os.getenv('IND_PUBLIC_KLINE_GATE_BASE', 'https://api.gateio.ws/api/v4')).rstrip('/')
_SPOT_PUBLIC_OKX_BASE = str(os.getenv('IND_PUBLIC_KLINE_OKX_BASE', 'https://www.okx.com')).rstrip('/')
_SPOT_PUBLIC_SOURCE_CACHE: Dict[str, Dict[str, Any]] = {}
_SPOT_PUBLIC_LAST_SUCCESS: Dict[str, str] = {}


def _spot_public_source_order() -> list[str]:
    raw = str(cfg_gets_runtime('IND_PUBLIC_SOURCE_ORDER', 'gate,okx,mexc,binance') or 'gate,okx,mexc,binance')
    tokens = []
    seen = set()
    for part in str(raw).replace('|', ',').replace(';', ',').split(','):
        v = str(part or '').strip().lower()
        if v in ('binance', 'mexc', 'gate', 'okx') and v not in seen:
            seen.add(v)
            tokens.append(v)
    for v in ('gate', 'okx', 'mexc', 'binance'):
        if v not in seen:
            tokens.append(v)
    return tokens


def _spot_public_effective_source_order(coin: Any = None) -> list[str]:
    """固定优先级单链：不允许 last_success 抢前，避免运行口径漂移。"""
    return list(_spot_public_source_order())


def _spot_public_timeout_budget(timeout_s: float = 6.0) -> tuple[float, float]:
    try:
        total_budget = float(cfg_getf_runtime('IND_PUBLIC_SOURCE_TOTAL_TIMEOUT_SEC', timeout_s) or timeout_s)
    except Exception:
        total_budget = float(timeout_s or 6.0)
    try:
        single_budget = float(cfg_getf_runtime('IND_PUBLIC_SOURCE_SINGLE_TIMEOUT_SEC', 2.5) or 2.5)
    except Exception:
        single_budget = 2.5
    total_budget = max(1.0, min(float(total_budget), max(1.0, float(timeout_s or 6.0))))
    single_budget = max(0.8, min(float(single_budget), float(total_budget)))
    return float(single_budget), float(total_budget)


def _spot_public_gate_interval(interval: str = '1h') -> str:
    return {
        '1m': '1m', '3m': '3m', '5m': '5m', '15m': '15m', '30m': '30m',
        '1h': '1h', '2h': '2h', '4h': '4h', '8h': '8h', '1d': '1d',
    }.get(str(interval or '1h').strip(), '1h')


def _spot_public_candidate_roots(coin: Any) -> list[str]:
    try:
        c = str(coin or '').upper().strip()
    except Exception:
        c = ''
    out: list[str] = []
    if c:
        out.append(c)
    if c.startswith('1000') and len(c) > 4:
        out.append(str(c[4:]).upper().strip())
    if c.startswith('K') and len(c) > 1:
        out.append(str(c[1:]).upper().strip())
    seen: set[str] = set()
    uniq: list[str] = []
    for x in out:
        if x and x not in seen:
            seen.add(x)
            uniq.append(x)
    return uniq


def _spot_public_normalize_binance_like_klines(rows: Any) -> list[list]:
    out: list[list] = []
    for row in list(rows or []):
        if not isinstance(row, list) or len(row) < 5:
            continue
        try:
            open_t = int(float(row[0] or 0))
            open_p = float(row[1] or 0.0)
            high = float(row[2] or 0.0)
            low = float(row[3] or 0.0)
            close = float(row[4] or 0.0)
            vol = float(row[5] or 0.0) if len(row) > 5 else 0.0
            close_t = int(float(row[6] or 0)) if len(row) > 6 else int(open_t + 3600_000 - 1)
            quote_vol = float(row[7] or 0.0) if len(row) > 7 else 0.0
        except Exception:
            continue
        out.append([open_t, open_p, high, low, close, vol, close_t, quote_vol])
    return out


def _spot_public_normalize_gate_klines(rows: Any, *, interval: str = '1h') -> list[list]:
    out: list[list] = []
    mapping = {'1m': 60, '3m': 180, '5m': 300, '15m': 900, '30m': 1800, '1h': 3600, '2h': 7200, '4h': 14400, '8h': 28800, '1d': 86400}
    interval_sec = int(mapping.get(str(interval or '1h').strip(), 3600))
    for row in list(rows or []):
        if not isinstance(row, list) or len(row) < 6:
            continue
        try:
            ts_s = int(float(row[0] or 0))
            volume = float(row[1] or 0.0)
            close = float(row[2] or 0.0)
            high = float(row[3] or 0.0)
            low = float(row[4] or 0.0)
            open_p = float(row[5] or 0.0)
            open_t = int(ts_s * 1000)
            close_t = int((ts_s + max(1, interval_sec)) * 1000 - 1)
        except Exception:
            continue
        out.append([open_t, open_p, high, low, close, volume, close_t, 0.0])
    out.sort(key=lambda x: int(x[0]))
    return out


def _spot_public_calc_rsi14_from_rows(rows: Any) -> float | None:
    closes: list[float] = []
    for row in list(rows or []):
        try:
            close = float(row[4] or 0.0)
        except Exception:
            close = 0.0
        if close > 0.0:
            closes.append(float(close))
    try:
        return _ind_calc_rsi_wilder(closes, period=14)
    except Exception:
        return None


def _spot_public_calc_close_change_24h_pct(rows: Any) -> float | None:
    try:
        norm_rows = list(rows or [])
        if len(norm_rows) < 25:
            return None
        start_close = float(norm_rows[-25][4] or 0.0)
        end_close = float(norm_rows[-1][4] or 0.0)
        if start_close <= 0.0:
            return None
        return float((end_close / start_close) - 1.0)
    except Exception:
        return None


def _spot_public_cached_market_snapshot(source: str, timeout_s: float = 6.0) -> tuple[set[str], dict[str, dict], str]:
    src = str(source or '').lower().strip()
    cache = dict((_SPOT_PUBLIC_SOURCE_CACHE or {}).get(src) or {})
    now_v = float(time.time())
    age = max(0.0, now_v - float(cache.get('ts') or 0.0)) if cache.get('ts') else 1.0e12
    ttl = 300.0
    if cache and age <= ttl:
        return set(cache.get('symbols') or set()), dict(cache.get('ticker_map') or {}), str(cache.get('reason') or 'cache_ok')
    symbols: set[str] = set()
    ticker_map: dict[str, dict] = {}
    reason = f'{src}_snapshot_empty'
    if src == 'binance':
        headers = _coin_pool_http_headers('binance')
        ex, ex_reason, _ = _coin_pool_http_json_detail(f'{_SPOT_PUBLIC_BINANCE_BASE}/api/v3/exchangeInfo', timeout_s=timeout_s, headers=headers)
        tk, tk_reason, _ = _coin_pool_http_json_detail(f'{_SPOT_PUBLIC_BINANCE_BASE}/api/v3/ticker/24hr', timeout_s=timeout_s, headers=headers)
        if isinstance(ex, dict):
            for row in list(ex.get('symbols') or []):
                if not isinstance(row, dict):
                    continue
                sym = str(row.get('symbol') or '').upper().strip()
                status = str(row.get('status') or '').upper().strip()
                if sym and status == 'TRADING':
                    symbols.add(sym)
        if isinstance(tk, list):
            for row in tk:
                if not isinstance(row, dict):
                    continue
                sym = str(row.get('symbol') or '').upper().strip()
                if sym:
                    ticker_map[sym] = dict(row)
        reason = f'binance_snapshot ex={ex_reason} tk={tk_reason} symbols={len(symbols)} tickers={len(ticker_map)}'
    elif src == 'mexc':
        headers = _coin_pool_http_headers('mexc')
        ex, ex_reason, _ = _coin_pool_http_json_detail(f'{_SPOT_PUBLIC_MEXC_BASE}/api/v3/exchangeInfo', timeout_s=timeout_s, headers=headers)
        tk, tk_reason, _ = _coin_pool_http_json_detail(f'{_SPOT_PUBLIC_MEXC_BASE}/api/v3/ticker/24hr', timeout_s=timeout_s, headers=headers)
        if isinstance(ex, dict):
            for row in list(ex.get('symbols') or []):
                if not isinstance(row, dict):
                    continue
                sym = str(row.get('symbol') or '').upper().strip()
                status = str(row.get('status') or '').upper().strip()
                if sym and status in ('1', 'ENABLED', 'TRADING'):
                    symbols.add(sym)
        if isinstance(tk, list):
            for row in tk:
                if not isinstance(row, dict):
                    continue
                sym = str(row.get('symbol') or '').upper().strip()
                if sym:
                    ticker_map[sym] = dict(row)
        reason = f'mexc_snapshot ex={ex_reason} tk={tk_reason} symbols={len(symbols)} tickers={len(ticker_map)}'
    _SPOT_PUBLIC_SOURCE_CACHE[src] = {'ts': now_v, 'symbols': set(symbols), 'ticker_map': dict(ticker_map), 'reason': str(reason)}
    return symbols, ticker_map, str(reason)


def _spot_public_fetch_metric_binance(root: str, *, interval: str = '1h', timeout_s: float = 6.0, kline_limit: int = 25) -> tuple[dict | None, str]:
    sym = f'{str(root or '').upper().strip()}USDT'
    symbols, ticker_map, snap_reason = _spot_public_cached_market_snapshot('binance', timeout_s=timeout_s)
    if sym not in symbols:
        return None, f'binance_spot_symbol_missing:{sym}'
    headers = _coin_pool_http_headers('binance')
    url = f'{_SPOT_PUBLIC_BINANCE_BASE}/api/v3/klines?symbol={sym}&interval={str(interval or "1h")}&limit={int(max(25, kline_limit or 25))}'
    js, why, _ = _coin_pool_http_json_detail(url, timeout_s=min(float(timeout_s or 6.0), 4.5), headers=headers)
    if not isinstance(js, list) or not js:
        return None, f'binance_spot_klines_fail:{why}'
    ticker = dict(ticker_map.get(sym) or {})
    return {
        'source': 'binance_spot',
        'source_kind': 'public_kline_live_1h',
        'symbol': sym,
        'rows': _spot_public_normalize_binance_like_klines(js),
        'quote_volume_24h': float(ticker.get('quoteVolume') or 0.0),
        'ticker_change_24h_pct': float(ticker.get('priceChangePercent') or 0.0),
        'snapshot_reason': str(snap_reason),
    }, 'ok'


def _spot_public_fetch_metric_mexc(root: str, *, interval: str = '1h', timeout_s: float = 6.0, kline_limit: int = 25) -> tuple[dict | None, str]:
    sym = f'{str(root or '').upper().strip()}USDT'
    headers = _coin_pool_http_headers('mexc')
    tk_url = f'{_SPOT_PUBLIC_MEXC_BASE}/api/v3/ticker/24hr?symbol={sym}'
    kl_url = f'{_SPOT_PUBLIC_MEXC_BASE}/api/v3/klines?symbol={sym}&interval={str(interval or "1h")}&limit={int(max(25, kline_limit or 25))}'
    tk, tk_reason, _ = _coin_pool_http_json_detail(tk_url, timeout_s=min(float(timeout_s or 6.0), 4.5), headers=headers)
    kl, kl_reason, _ = _coin_pool_http_json_detail(kl_url, timeout_s=min(float(timeout_s or 6.0), 4.5), headers=headers)
    if not isinstance(tk, dict) or not isinstance(kl, list) or not kl:
        return None, f'mexc_spot_metric_fail:{tk_reason}|{kl_reason}'
    return {
        'source': 'mexc_spot',
        'source_kind': 'public_kline_live_1h',
        'symbol': sym,
        'rows': _spot_public_normalize_binance_like_klines(kl),
        'quote_volume_24h': float(tk.get('quoteVolume') or 0.0),
        'ticker_change_24h_pct': float(tk.get('priceChangePercent') or 0.0),
    }, 'ok'


def _spot_public_fetch_metric_gate(root: str, *, interval: str = '1h', timeout_s: float = 6.0, kline_limit: int = 25) -> tuple[dict | None, str]:
    pair = f'{str(root or '').upper().strip()}_USDT'
    headers = _coin_pool_http_headers('gate')
    import urllib.parse
    tick_qs = urllib.parse.urlencode({'currency_pair': pair})
    gate_interval = _spot_public_gate_interval(interval)
    kl_qs = urllib.parse.urlencode({'currency_pair': pair, 'interval': gate_interval, 'limit': int(max(25, kline_limit or 25))})
    tk, tk_reason, _ = _coin_pool_http_json_detail(f'{_SPOT_PUBLIC_GATE_BASE}/spot/tickers?{tick_qs}', timeout_s=min(float(timeout_s or 6.0), 4.5), headers=headers)
    kl, kl_reason, _ = _coin_pool_http_json_detail(f'{_SPOT_PUBLIC_GATE_BASE}/spot/candlesticks?{kl_qs}', timeout_s=min(float(timeout_s or 6.0), 4.5), headers=headers)
    if not isinstance(tk, list) or not tk or not isinstance(kl, list) or not kl:
        return None, f'gate_spot_metric_fail:{tk_reason}|{kl_reason}'
    ticker = dict(tk[0] or {}) if isinstance(tk[0], dict) else {}
    quote_volume = float(ticker.get('quote_volume') or 0.0)
    if quote_volume <= 0.0:
        try:
            quote_volume = float(ticker.get('last') or 0.0) * float(ticker.get('base_volume') or 0.0)
        except Exception:
            quote_volume = 0.0
    return {
        'source': 'gate_spot',
        'source_kind': 'public_kline_live_1h',
        'symbol': pair,
        'rows': _spot_public_normalize_gate_klines(kl, interval=str(interval or '1h')),
        'quote_volume_24h': float(max(quote_volume, 0.0)),
        'ticker_change_24h_pct': float(ticker.get('change_percentage') or 0.0),
    }, 'ok'


def _spot_public_okx_bar(interval: str = '1h') -> str:
    return {
        '1m': '1m', '3m': '3m', '5m': '5m', '15m': '15m', '30m': '30m',
        '1h': '1H', '2h': '2H', '4h': '4H', '6h': '6H', '12h': '12H', '1d': '1D',
    }.get(str(interval or '1h').strip(), '1H')


def _spot_public_normalize_okx_klines(rows: Any, *, interval: str = '1h') -> list[list]:
    out: list[list] = []
    mapping = {'1m': 60, '3m': 180, '5m': 300, '15m': 900, '30m': 1800, '1h': 3600, '2h': 7200, '4h': 14400, '6h': 21600, '12h': 43200, '1d': 86400}
    interval_sec = int(mapping.get(str(interval or '1h').strip(), 3600))
    for row in list(rows or []):
        if not isinstance(row, list) or len(row) < 6:
            continue
        try:
            open_t = int(float(row[0] or 0))
            open_p = float(row[1] or 0.0)
            high = float(row[2] or 0.0)
            low = float(row[3] or 0.0)
            close = float(row[4] or 0.0)
            vol = float(row[5] or 0.0)
            close_t = int(open_t + max(1, interval_sec) * 1000 - 1)
            quote_vol = float(row[7] or 0.0) if len(row) > 7 else 0.0
        except Exception:
            continue
        out.append([open_t, open_p, high, low, close, vol, close_t, quote_vol])
    out.sort(key=lambda x: int(x[0]))
