def _spot_public_fetch_metric_okx(root: str, *, interval: str = '1h', timeout_s: float = 6.0, kline_limit: int = 25) -> tuple[dict | None, str]:
    inst = f'{str(root or '').upper().strip()}-USDT'
    headers = _coin_pool_http_headers('okx')
    import urllib.parse
    tk_qs = urllib.parse.urlencode({'instId': inst})
    kl_qs = urllib.parse.urlencode({'instId': inst, 'bar': _spot_public_okx_bar(interval), 'limit': int(max(25, kline_limit or 25))})
    tk, tk_reason, _ = _coin_pool_http_json_detail(f'{_SPOT_PUBLIC_OKX_BASE}/api/v5/market/ticker?{tk_qs}', timeout_s=min(float(timeout_s or 6.0), 4.5), headers=headers)
    kl, kl_reason, _ = _coin_pool_http_json_detail(f'{_SPOT_PUBLIC_OKX_BASE}/api/v5/market/candles?{kl_qs}', timeout_s=min(float(timeout_s or 6.0), 4.5), headers=headers)
    tk_rows = list((tk or {}).get('data') or []) if isinstance(tk, dict) else []
    kl_rows = list((kl or {}).get('data') or []) if isinstance(kl, dict) else []
    if not tk_rows or not kl_rows:
        return None, f'okx_spot_metric_fail:{tk_reason}|{kl_reason}'
    ticker = dict(tk_rows[0] or {}) if isinstance(tk_rows[0], dict) else {}
    return {
        'source': 'okx_spot',
        'source_kind': 'public_kline_live_1h',
        'symbol': inst,
        'rows': _spot_public_normalize_okx_klines(kl_rows, interval=str(interval or '1h')),
        'quote_volume_24h': float(ticker.get('volCcy24h') or 0.0),
        'ticker_change_24h_pct': float(ticker.get('sodUtc0') or 0.0) and ((float(ticker.get('last') or 0.0) / max(float(ticker.get('sodUtc0') or 0.0), 1e-12) - 1.0) * 100.0) or 0.0,
    }, 'ok'


def _spot_public_fetch_metric_multi(coin: Any, *, interval: str = '1h', timeout_s: float = 6.0, kline_limit: int = 25) -> dict:
    coin_u = str(coin or '').upper().strip()
    tried: list[str] = []
    last_reason = 'all_sources_failed_or_symbol_missing'
    fetchers = {
        'binance': lambda root, budget: _spot_public_fetch_metric_binance(root, interval=interval, timeout_s=budget, kline_limit=kline_limit),
        'mexc': lambda root, budget: _spot_public_fetch_metric_mexc(root, interval=interval, timeout_s=budget, kline_limit=kline_limit),
        'gate': lambda root, budget: _spot_public_fetch_metric_gate(root, interval=interval, timeout_s=budget, kline_limit=kline_limit),
        'okx': lambda root, budget: _spot_public_fetch_metric_okx(root, interval=interval, timeout_s=budget, kline_limit=kline_limit),
    }
    symbol_fmt = {
        'binance': lambda root: f'binance:{root}USDT',
        'mexc': lambda root: f'mexc:{root}USDT',
        'gate': lambda root: f'gate:{root}_USDT',
        'okx': lambda root: f'okx:{root}-USDT',
    }
    single_budget, total_budget = _spot_public_timeout_budget(timeout_s)
    effective_order = list(_spot_public_effective_source_order(coin_u))
    roots = list(_spot_public_candidate_roots(coin_u))
    task_specs: list[dict[str, Any]] = []
    for src_rank, src in enumerate(effective_order):
        fetcher = fetchers.get(src)
        fmt = symbol_fmt.get(src)
        if fetcher is None or fmt is None:
            continue
        for root_rank, root in enumerate(roots):
            task_specs.append({
                'src': str(src),
                'root': str(root),
                'src_rank': int(src_rank),
                'root_rank': int(root_rank),
                'symbol_label': str(fmt(root)),
            })
    if not task_specs:
        return {
            'coin': coin_u, 'source': '', 'source_kind': 'public_kline_live_1h', 'symbol': '', 'rows': [],
            'quote_volume_24h': 0.0, 'ticker_change_24h_pct': 0.0, 'tried_symbols': '',
            'source_order': ','.join(effective_order), 'reason': 'no_public_source_task_specs',
        }
    try:
        import concurrent.futures as _futures
        max_workers = max(1, min(len(task_specs), int(cfg_getf_runtime('IND_PUBLIC_SOURCE_PARALLEL_WORKERS', min(6, len(task_specs))) or min(6, len(task_specs)))))
    except Exception:
        import concurrent.futures as _futures
        max_workers = max(1, min(len(task_specs), 6))
    winner: tuple[tuple[int, int], dict] | None = None
    failure_reason_map: dict[str, str] = {}
    with _futures.ThreadPoolExecutor(max_workers=max_workers, thread_name_prefix='spot_public') as _executor:
        future_map = {}
        for spec in task_specs:
            fetcher = fetchers.get(str(spec.get('src') or ''))
            if fetcher is None:
                continue
            future = _executor.submit(fetcher, str(spec.get('root') or ''), float(single_budget))
            future_map[future] = spec
        try:
            done, not_done = _futures.wait(list(future_map.keys()), timeout=float(total_budget))
        except Exception:
            done, not_done = set(), set(future_map.keys())
        for future, spec in future_map.items():
            tried.append(str(spec.get('symbol_label') or ''))
            src = str(spec.get('src') or '')
            root = str(spec.get('root') or '')
            key = f'{src}:{root}'
            if future not in done:
                try:
                    future.cancel()
                except Exception:
                    pass
                failure_reason_map[key] = f'public_parallel_timeout:{src}'
                last_reason = str(failure_reason_map[key])
                continue
            try:
                det, rsn = future.result()
            except Exception as _e:
                det, rsn = None, f'public_parallel_exc:{src}:{type(_e).__name__}'
            if isinstance(det, dict) and list(det.get('rows') or []):
                rank = (int(spec.get('src_rank') or 0), int(spec.get('root_rank') or 0))
                if winner is None or rank < winner[0]:
                    winner = (rank, dict(det))
            else:
                failure_reason_map[key] = str(rsn or 'public_source_fail')
                last_reason = str(rsn or last_reason)
        if not_done:
            try:
                _executor.shutdown(wait=False, cancel_futures=True)
            except Exception:
                pass
    if winner is not None:
        det = dict(winner[1] or {})
        det['tried_symbols'] = ','.join([x for x in tried if x])
        det['coin'] = coin_u
        det['source_order'] = ','.join(effective_order)
        if failure_reason_map:
            det['failure_map'] = dict(failure_reason_map)
        return det
    return {
        'coin': coin_u,
        'source': '',
        'source_kind': 'public_kline_live_1h',
        'symbol': '',
        'rows': [],
        'quote_volume_24h': 0.0,
        'ticker_change_24h_pct': 0.0,
        'tried_symbols': ','.join([x for x in tried if x]),
        'source_order': ','.join(effective_order),
        'reason': str(last_reason or 'all_sources_failed_or_symbol_missing'),
        'failure_map': dict(failure_reason_map),
    }


def _spot_public_selector_weights() -> tuple[float, float, float, float]:
    try:
        wv = float(cfg_getf_runtime('COIN_POOL_W_VOLUME', 0.65) or 0.65)
    except Exception:
        wv = 0.65
    try:
        wvol = float(cfg_getf_runtime('COIN_POOL_W_VOLATILITY', 0.20) or 0.20)
    except Exception:
        wvol = 0.20
    try:
        wt = float(cfg_getf_runtime('COIN_POOL_W_TREND', 0.15) or 0.15)
    except Exception:
        wt = 0.15
    total = max(1e-9, wv + wvol + wt)
    wv, wvol, wt = wv / total, wvol / total, wt / total
    try:
        min_qv = float(cfg_getf_runtime('COIN_POOL_MIN_QUOTE_VOLUME_24H', 1000000.0) or 1000000.0)
    except Exception:
        min_qv = 1000000.0
    return float(wv), float(wvol), float(wt), float(max(0.0, min_qv))


def _coin_pool_binance_ranked(timeout_s: float = 6.0, allowed_coins: set[str] | None = None) -> tuple[list[dict], dict, bool, str, dict]:
    """共享池选币主链（EXT∩VAR -> 现货公共指标 -> 缺失币补备用源 -> 统一排名）。

    兼容旧函数名：下游仍沿用 ranked_openable_universe / binance_rank_all 等字段，
    但运行口径已改成共享池单链，不再先走币安合约 top30。
    """
    allowed_filter = sorted({str(x or '').upper().strip() for x in list(allowed_coins or set()) if str(x or '').strip() and (not _coin_pool_is_stable_like(str(x or '').upper().strip()))})
    diag = {
        'metric': 'shared_ext_var_spot_fallback_volume_volatility_rsi',
        'strict_24h_only': True,
        'used_24h_ticker': True,
        'used_7d_fallback': False,
        'used_coin_aggregate': False,
        'universe_total': int(len(allowed_filter)),
        'ranked_total': 0,
        'topn_metric_ready_total': 0,
        'insufficient_24h_total': 0,
        'ticker_missing_total': 0,
        'fetch_fail_total': 0,
        'dropped_total': 0,
        'excluded_preview': [],
        'excluded_map': {},
        'symbol_warning_total': 0,
        'symbol_warning_preview': [],
        'source_counts': {},
        'shared_pool_total': int(len(allowed_filter)),
        'ok_total': 0,
        'fail_total': 0,
    }
    if not allowed_filter:
        return [], {}, False, 'shared_pool_empty', diag
    w_volume, w_volatility, w_trend, min_qv = _spot_public_selector_weights()
    rows: list[dict] = []
    symbol_map: dict[str, str] = {}
    excluded_map: dict[str, dict] = {}
    source_counts: dict[str, int] = {}
    # [PATCH] EXT∩VAR 共享池已涨到 ~190 币（含美股），逐币串行拉取会超过 180s round watchdog，
    # 导致每轮在选币处被中止、positions.json 永远写不出来。这里先并发预取，再按原顺序走原排名逻辑。
    _pool_dets: dict[str, dict] = {}
    try:
        import concurrent.futures as _cf_pool
        try:
            _pool_workers = int(cfg_getf_runtime('COIN_POOL_FETCH_PARALLEL_WORKERS', 10) or 10)
        except Exception:
            _pool_workers = 10
        _pool_workers = max(1, min(len(allowed_filter), _pool_workers))
        with _cf_pool.ThreadPoolExecutor(max_workers=_pool_workers, thread_name_prefix='coin_pool_fetch') as _pool_ex:
            _pool_futs = {c: _pool_ex.submit(_spot_public_fetch_metric_multi, c, interval='1h', timeout_s=float(timeout_s or 6.0)) for c in allowed_filter}
            for _pc, _pf in _pool_futs.items():
                try:
                    _pool_dets[_pc] = dict(_pf.result() or {})
                except Exception as _e:
                    _pool_dets[_pc] = {'reason': f'pool_parallel_exc:{type(_e).__name__}'}
    except Exception as _e:
        _record_swallowed_exception('coin_pool_parallel_prefetch', _e)
        _pool_dets = {}
    for coin in allowed_filter:
        det = _pool_dets.get(coin)
        if det is None:
            det = dict(_spot_public_fetch_metric_multi(coin, interval='1h', timeout_s=float(timeout_s or 6.0)) or {})
        tried = str(det.get('tried_symbols') or '')
        rows_kl = list(det.get('rows') or [])
        ok = bool(rows_kl)
        rsi_v = _spot_public_calc_rsi14_from_rows(rows_kl) if ok else None
        close_chg = _spot_public_calc_close_change_24h_pct(rows_kl) if ok else None
        vol_det = _coin_pool_calc_binance_24h_volatility_from_1h_klines(rows_kl) if ok else {'ok': False, 'reason': str(det.get('reason') or 'rows_missing')}
        metric_ok = bool(ok and vol_det.get('ok') and rsi_v is not None and close_chg is not None)
        metric_reason = 'ok' if metric_ok else str((vol_det or {}).get('reason') or det.get('reason') or 'metric_calc_failed')
        quote_volume_24h = float(det.get('quote_volume_24h') or 0.0)
        volatility_pct = float((vol_det or {}).get('volatility_pct') or 0.0)
        ticker_change_pct = None
        try:
            ticker_change_pct = float(det.get('ticker_change_24h_pct') or 0.0) / 100.0
        except Exception:
            ticker_change_pct = None
        row = {
            'coin': coin,
            'symbol': str(det.get('symbol') or '').upper().strip(),
            'rep_symbol': str(det.get('symbol') or '').upper().strip(),
            'rep_quote_asset': 'USDT',
            'merged_symbols': str(det.get('symbol') or '').upper().strip(),
            'merged_symbol_count': 1,
            'quote_volume': float(quote_volume_24h),
            'quote_volume_24h': float(quote_volume_24h),
            'total_quote_volume': float(quote_volume_24h),
            'rep_symbol_quote_volume': float(quote_volume_24h),
            'last_price': 0.0,
            'price_change_percent': float((ticker_change_pct or 0.0) * 100.0),
            'metric_ok': bool(metric_ok),
            'metric_reason': str(metric_reason),
            'volatility_pct': float(volatility_pct),
            'volatility_24h_pct': float(volatility_pct),
            'hourly_range_avg_pct': float((vol_det or {}).get('hourly_range_avg_pct') or 0.0),
            'quote_volume_1h_24_sum': float((vol_det or {}).get('quote_volume_1h_24_sum') or 0.0),
            'closed_1h_bars': int((vol_det or {}).get('closed_1h_bars') or 0),
            'tr_bars': int((vol_det or {}).get('tr_bars') or 0),
            'data_quality': ('shared_pool_spot_fallback_ok' if metric_ok else 'shared_pool_spot_fallback_fail'),
            'volatility_calc': '24h_1h_tr_avg_div_close_pct',
            'score': 0.0,
            'volume_rank_score': 0.0,
            'volatility_rank_score': 0.0,
            'trend_rank_score': 0.0,
            'volume_gate_pass': False,
            'volume_rank_topn': 0,
            'volatility_rank_topn': 0,
            'trend_rank_topn': 0,
            'topn_score_rank': 0,
            'rank': 0,
            'binance_rank_all': 0,
            'binance_rank_topn': 0,
            'rank_rule': f'score=volume*{w_volume:.2f}+volatility*{w_volatility:.2f}+trend*{w_trend:.2f};gate=quote_volume_24h>={min_qv:.0f}',
            'selected_reason': '候选池固定为EXT∩VAR，先取币安现货公共指标，缺失币补MEXC/Gate，最后统一按量优先综合分排名',
            'selection_step': ('shared_pool_metric_ready' if metric_ok else 'shared_pool_metric_fail'),
            'common_platforms': ['EXT', 'VAR', str(det.get('source') or '').upper().strip()],
            'source': str(det.get('source') or ''),
            'source_used': str(det.get('source') or ''),
            'source_kind': str(det.get('source_kind') or 'public_kline_live_1h'),
            'tried_symbols': str(tried),
            'rsi14': (float(rsi_v) if rsi_v is not None else None),
            'rsi_side': ('LONG' if (rsi_v is not None and float(rsi_v) > 50.0) else ('SHORT' if (rsi_v is not None and float(rsi_v) < 50.0) else 'FLAT')),
            'close_change_24h_pct': (float(close_chg) if close_chg is not None else None),
            'ticker_change_24h_pct': ticker_change_pct,
        }
        try:
            row.update(dict(_coin_pool_symbol_observe_meta(coin, row.get('symbol') or '') or {}))
        except Exception:
            pass
        rows.append(row)
        if metric_ok:
            symbol_map[coin] = str(row.get('symbol') or '')
            src_key = str(row.get('source') or 'unknown')
            source_counts[src_key] = int(source_counts.get(src_key, 0)) + 1
        else:
            excluded_map[coin] = {'coin': coin, 'symbol': str(row.get('symbol') or ''), 'reason': str(metric_reason), 'tried_symbols': str(tried)}
            if str(metric_reason).startswith('insufficient_closed_1h_bars'):
                diag['insufficient_24h_total'] = int(diag.get('insufficient_24h_total') or 0) + 1
            elif ('symbol_missing' in str(metric_reason)) or ('all_sources_failed' in str(metric_reason)):
                diag['ticker_missing_total'] = int(diag.get('ticker_missing_total') or 0) + 1
            else:
                diag['fetch_fail_total'] = int(diag.get('fetch_fail_total') or 0) + 1
    ok_rows = [r for r in rows if bool(r.get('metric_ok'))]
    max_qv = max([float(r.get('quote_volume_24h') or 0.0) for r in ok_rows] or [1.0])
    max_vol = max([float(r.get('volatility_pct') or 0.0) for r in ok_rows] or [1.0])
    max_trend = max([abs(float(r.get('rsi14') or 50.0) - 50.0) for r in ok_rows] or [1.0])
    for row in ok_rows:
        qv = float(row.get('quote_volume_24h') or 0.0)
        vol = float(row.get('volatility_pct') or 0.0)
        trend_abs = abs(float(row.get('rsi14') or 50.0) - 50.0)
        row['volume_gate_pass'] = bool(qv >= float(min_qv))
        row['volume_rank_score'] = float((qv / max_qv) * 100.0) if max_qv > 0 else 0.0
        row['volatility_rank_score'] = float((vol / max_vol) * 100.0) if max_vol > 0 else 0.0
        row['trend_rank_score'] = float((trend_abs / max_trend) * 100.0) if max_trend > 0 else 0.0
        row['score'] = float(row['volume_rank_score'] * w_volume + row['volatility_rank_score'] * w_volatility + row['trend_rank_score'] * w_trend)
    rows = sorted(rows, key=lambda x: (bool(x.get('metric_ok')), bool(x.get('volume_gate_pass')), float(x.get('score') or 0.0), float(x.get('quote_volume_24h') or 0.0), float(x.get('volatility_pct') or 0.0)), reverse=True)
    ok_only = [r for r in rows if bool(r.get('metric_ok'))]
    by_qv = sorted(ok_only, key=lambda x: float(x.get('quote_volume_24h') or 0.0), reverse=True)
    by_vol = sorted(ok_only, key=lambda x: float(x.get('volatility_pct') or 0.0), reverse=True)
    by_trend = sorted(ok_only, key=lambda x: abs(float(x.get('rsi14') or 50.0) - 50.0), reverse=True)
    rank_qv = {str(r.get('coin') or '').upper().strip(): int(i) for i, r in enumerate(by_qv, start=1)}
    rank_vol = {str(r.get('coin') or '').upper().strip(): int(i) for i, r in enumerate(by_vol, start=1)}
    rank_trend = {str(r.get('coin') or '').upper().strip(): int(i) for i, r in enumerate(by_trend, start=1)}
    for idx, row in enumerate(rows, start=1):
        row['rank'] = int(idx)
        row['binance_rank_all'] = int(idx)
        row['binance_rank_topn'] = int(idx) if bool(row.get('metric_ok')) else 0
        c = str(row.get('coin') or '').upper().strip()
        row['volume_rank_topn'] = int(rank_qv.get(c, 0))
        row['volatility_rank_topn'] = int(rank_vol.get(c, 0))
        row['trend_rank_topn'] = int(rank_trend.get(c, 0))
        row['topn_score_rank'] = int(idx) if bool(row.get('metric_ok')) else 0
    diag['ranked_total'] = int(len(rows))
    diag['topn_metric_ready_total'] = int(len(ok_only))
    diag['ok_total'] = int(len(ok_only))
    diag['fail_total'] = int(len(rows) - len(ok_only))
    diag['dropped_total'] = int(len(excluded_map))
    diag['excluded_map'] = dict(excluded_map)
    diag['excluded_preview'] = [dict(v) for _, v in list(sorted(excluded_map.items()))[:20]]
    diag['source_counts'] = dict(source_counts)
    diag['symbol_warning_total'] = int(sum(1 for x in list(rows or []) if bool((x or {}).get('symbol_warning'))))
    diag['symbol_warning_preview'] = [{'coin': str(x.get('coin') or ''), 'symbol': str(x.get('symbol') or ''), 'warn': str(x.get('symbol_warning_reason') or '')} for x in list(rows or []) if bool((x or {}).get('symbol_warning'))][:20]
    reason = f'shared_spot_ok shared={len(allowed_filter)} ok={len(ok_only)} fail={len(rows)-len(ok_only)} sources={json.dumps(source_counts, ensure_ascii=False)}'
    return rows, symbol_map, bool(ok_only), reason, diag

def _coin_pool_ext_active_set(timeout_s: float = 6.0) -> tuple[set[str], bool, str]:
    """
    选币主链：EXT 只产出“平台原名规范化后”的严格集合，不做 1000PEPE->KPEPE 这类跨平台别名放行。
    也就是说：候选 coin 必须能按原名在 EXT 直接命中；命不中就禁止并递补。
    """
    env_url = str(os.getenv('COIN_POOL_EXT_MARKETS_URL', '')).strip()
    urls = _coin_pool_unique_urls([
        env_url,
        'https://api.starknet.extended.exchange/api/v1/info/markets',
    ])
    headers = _coin_pool_http_headers('ext')
    last_reason = 'ext_fetch_fail'
    for url in urls:
        js, fetch_reason, fetch_meta = _coin_pool_http_json_detail(url, timeout_s=timeout_s, headers=headers)
        rows = []
        data = None
        if isinstance(js, dict):
            data = js.get('data')
        if isinstance(data, list):
            rows = data
        elif isinstance(js, list):
            rows = js
        if not isinstance(rows, list) or not rows:
            last_reason = f'ext_fetch_fail:{fetch_reason}@{url}'
            continue
        out: set[str] = set()
        for row in rows:
            if not isinstance(row, dict):
                continue
            status = str(row.get('status') or '').upper().strip()
            active = bool(row.get('active'))
            if status != 'ACTIVE' or not active:
                continue
            cand = row.get('assetName') or row.get('coin') or row.get('symbol') or row.get('name')
            coin = _coin_pool_selection_strict_name(cand)
            if coin and (not _coin_pool_is_stable_like(coin)):
                out.add(coin)
        if out:
            return out, True, f'ext_ok rows={len(out)} via={url} match=canonical_name_with_ext_alias'
        last_reason = f'ext_rows_empty:{fetch_reason}@{url}'
    return set(), False, str(last_reason or 'ext_fetch_fail')

def _coin_pool_var_active_set(timeout_s: float = 6.0) -> tuple[set[str], bool, str]:
    """选币主链：VAR 同样只保留原名规范化后的严格集合，不参与跨平台别名放行。"""
    env_url = str(os.getenv('COIN_POOL_VAR_STATS_URL', '')).strip()
    urls = _coin_pool_unique_urls([
        env_url,
        'https://omni-client-api.prod.ap-northeast-1.variational.io/metadata/stats',
    ])
    headers = _coin_pool_http_headers('var')
    attempt_logs = []
    for url in urls:
        js, fetch_reason, fetch_meta = _coin_pool_http_json_detail(url, timeout_s=timeout_s, headers=headers)
        listings = js.get('listings') if isinstance(js, dict) else None
        if not isinstance(listings, list) or not listings:
            meta = dict(fetch_meta or {}) if isinstance(fetch_meta, dict) else {}
            attempt_logs.append(f'try={url}|result=fail|why={fetch_reason}|status={str(meta.get("status") or "")}|raw={str(meta.get("raw_head") or "").replace(chr(10), " ")[:120]}')
            continue
        out: set[str] = set()
        for row in listings:
            if not isinstance(row, dict):
                continue
            coin = _coin_pool_selection_strict_name(row.get('ticker') or '')
            if coin and (not _coin_pool_is_stable_like(coin)):
                out.add(coin)
        if out:
            attempt_logs.append(f'try={url}|result=ok|rows={len(out)}')
            return out, True, 'var_ok rows=%d via=%s match=canonical_name_with_ext_alias attempts=%s' % (len(out), url, ' || '.join(attempt_logs[:3]))
        attempt_logs.append(f'try={url}|result=empty|why={fetch_reason}')
    return set(), False, 'var_fetch_fail:' + ' || '.join(attempt_logs[:3])

def _coin_pool_binance_topn() -> int:
    try:
        v = int(cfg_getf_runtime('COIN_POOL_BINANCE_TOPN', float(COIN_POOL_BINANCE_TOPN_DEFAULT)) or COIN_POOL_BINANCE_TOPN_DEFAULT)
    except Exception:
        v = int(COIN_POOL_BINANCE_TOPN_DEFAULT)
    return int(max(5, min(v, 100)))

def _coin_pool_trace_watch_coins() -> list[str]:
    raw = ''
    try:
        raw = str(os.getenv('COIN_POOL_TRACE_COINS', COIN_POOL_TRACE_COINS_DEFAULT) or COIN_POOL_TRACE_COINS_DEFAULT)
    except Exception:
        raw = str(COIN_POOL_TRACE_COINS_DEFAULT or 'EDGE')
    items = []
    for part in re.split(r'[，,;；\s]+', str(raw or '')):
        s = str(part or '').upper().strip()
        if s:
            items.append(s)
    if 'EDGE' not in set(items):
        items.append('EDGE')
    return _coin_pool_dedupe(items)

def _coin_pool_selection_row_preview(row: dict | None = None) -> dict:
    try:
        r = dict(row or {}) if isinstance(row, dict) else {}
    except Exception:
        r = {}
    try:
        coin = str(r.get('coin') or '').upper().strip()
    except Exception:
        coin = ''
    try:
        common_platforms = [str(x or '').upper().strip() for x in list(r.get('common_platforms') or []) if str(x or '').strip()]
    except Exception:
        common_platforms = []
    return {
        'coin': coin,
        'rank': int(r.get('rank') or 0),
        'score': round(float(r.get('score') or 0.0), 6),
        'quote_volume': round(float(r.get('quote_volume') or 0.0), 2),
        'quote_volume_24h': round(float(r.get('quote_volume_24h') or r.get('quote_volume') or 0.0), 2),
        'rep_symbol_quote_volume': round(float(r.get('rep_symbol_quote_volume') or 0.0), 2),
        'volatility_pct': round(float(r.get('volatility_pct') or 0.0), 6),
        'volatility_24h_pct': round(float(r.get('volatility_24h_pct') or r.get('volatility_pct') or 0.0), 6),
        'metric_ok': int(bool(r.get('metric_ok'))),
        'metric_reason': str(r.get('metric_reason') or ''),
        'binance_rank_all': int(r.get('binance_rank_all') or r.get('rank') or 0),
        'binance_rank_topn': int(r.get('binance_rank_topn') or 0),
        'symbol': str(r.get('symbol') or r.get('rep_symbol') or ''),
        'rep_symbol': str(r.get('rep_symbol') or r.get('symbol') or ''),
        'rep_quote_asset': str(r.get('rep_quote_asset') or ''),
        'merged_symbols': str(r.get('merged_symbols') or ''),
        'common_platforms': list(common_platforms or ['BINANCE', 'EXT', 'VAR']),
        'selected_reason': str(r.get('selected_reason') or '候选池固定为EXT∩VAR，先取币安现货公共指标，缺失币补MEXC/Gate，再统一按量优先综合分排序'),
        'rank_rule': str(r.get('rank_rule') or 'score=volume*0.65+volatility*0.20+trend*0.15;gate=quote_volume_24h>=1000000'),
        'selection_step': str(r.get('selection_step') or ''),
        'exclude_reason': str(r.get('exclude_reason') or ''),
        'exclude_stage': str(r.get('exclude_stage') or ''),
    }

def _coin_pool_selection_candidate_trace(coin: Any, row_map: dict | None = None, topn_coins: set[str] | None = None,
                                         ext_set: set[str] | None = None, var_set: set[str] | None = None,
                                         active: set[str] | None = None, blocked: set[str] | None = None,
                                         final_queue: list[str] | None = None, final_rank_map: dict | None = None,
                                         binance_excluded_map: dict | None = None, *, ext_ok: bool = True, var_ok: bool = True) -> dict:
    c = str(coin or '').upper().strip()
    row = dict((row_map or {}).get(c) or {}) if isinstance(row_map, dict) else {}
    topn_set = set(topn_coins or set())
    ext_u = set(ext_set or set())
    var_u = set(var_set or set())
    active_u = set(active or set())
    blocked_u = set(blocked or set())
    final_rank_mp = dict(final_rank_map or {}) if isinstance(final_rank_map, dict) else {}
    excluded_map = dict(binance_excluded_map or {}) if isinstance(binance_excluded_map, dict) else {}
    excluded_row = dict(excluded_map.get(c) or {})
    in_ranked = bool(row)
    in_topn = bool(c in topn_set)
    metric_ok = bool(row.get('metric_ok'))
    metric_reason = str(row.get('metric_reason') or '')
    in_ext = (_coin_pool_selection_strict_contains(c, ext_u) if ext_ok else None)
    in_var = (_coin_pool_selection_strict_contains(c, var_u) if var_ok else None)
    final_selected = bool(c in set(final_queue or []))
    after_platform_both = bool(in_topn and metric_ok and (in_ext is True) and (in_var is True))
    exclude_stage = ''
    exclude_reason = ''
    explain = ''
    if not in_ranked:
        exclude_stage = 'binance_rank'
        if excluded_row:
            exclude_reason = str(excluded_row.get('reason') or 'binance_rank_missing')
            explain = f"EXT∩VAR 共享池里没有该币，或共享池指标链未产出：{exclude_reason}"
        else:
            exclude_reason = 'binance_rank_missing'
            explain = 'EXT∩VAR 共享池评分结果里没有这个币'
    elif not in_topn:
        exclude_stage = 'binance_topn'
        exclude_reason = f'binance_rank_outside_top{_coin_pool_binance_topn()}'
        explain = f"币安近24小时成交额（coin聚合）排名第{int(row.get('rank') or 0)}名，未进入前{_coin_pool_binance_topn()}"
    elif not metric_ok:
        exclude_stage = 'binance_topn_metric'
        exclude_reason = str(metric_reason or excluded_row.get('reason') or 'top30_metric_missing')
        if str(exclude_reason).startswith('insufficient_closed_1h_bars'):
            explain = f"已进币安近24小时成交额前30，但代表symbol={str(row.get('symbol') or row.get('rep_symbol') or '-') } 的近24小时1小时K线不足，波动率口径不成立"
        elif str(exclude_reason).startswith('kline_fetch_fail') or str(exclude_reason).startswith('kline_fetch_except'):
            explain = f"已进币安近24小时成交额前30，但代表symbol={str(row.get('symbol') or row.get('rep_symbol') or '-') } 的近24小时1小时K线获取失败：{exclude_reason}"
        else:
            explain = f"已进币安近24小时成交额前30，但近24小时波动率未通过：{exclude_reason}"
    elif not ext_ok:
        exclude_stage = 'ext_fetch'
        exclude_reason = 'ext_fetch_fail'
        explain = 'EXT 可交易集合获取失败，无法核实'
    elif not var_ok:
        exclude_stage = 'var_fetch'
        exclude_reason = 'var_fetch_fail'
        explain = 'VAR 可交易集合获取失败，无法核实'
    elif in_ext is not True and in_var is not True:
        exclude_stage = 'platform_verify'
        exclude_reason = 'not_on_ext_and_var'
        explain = '已进币安前30且24小时波动率通过，但按币安原名直查 EXT 和 VAR 都没命中（不做别名放行）'
    elif in_ext is not True:
        exclude_stage = 'platform_verify'
        exclude_reason = 'not_on_ext'
        explain = '已进币安前30且24小时波动率通过，但按币安原名直查 EXT 没有这个币（不做别名放行）'
    elif in_var is not True:
        exclude_stage = 'platform_verify'
        exclude_reason = 'not_on_var'
        explain = '已进币安前30且24小时波动率通过，但按币安原名直查 VAR 没有这个币（不做别名放行）'
    elif c in active_u:
        exclude_stage = 'active_filter'
        exclude_reason = 'active_holding_coin'
        explain = '三平台都通过，但当前已在持仓池，占用槽位，不参与新币递补'
    elif c in blocked_u:
        exclude_stage = 'blocked_filter'
        exclude_reason = 'block_reopen_after_exit'
        explain = '三平台都通过，但处于禁重开名单，本轮不递补'
    elif final_selected:
        explain = f"已入选选币器模块最终候补，第{int(final_rank_mp.get(c) or 0)}名"
    else:
        exclude_stage = 'final_rank'
        exclude_reason = 'final_rank_not_kept'
        explain = '通过全部门禁，但未进入最终候补保留名单'
    _sym_meta = _coin_pool_symbol_observe_meta(c, row.get('symbol') or row.get('rep_symbol') or excluded_row.get('symbol') or '')
    if bool(_sym_meta.get('symbol_warning')):
        _warn_txt = str(_sym_meta.get('symbol_warning_reason') or '')
        explain = (str(explain or '') + (f'；观测警告：{_warn_txt}' if _warn_txt else '')).strip('；')
    return {
        'coin': c,
        'binance_rank_all': int(row.get('binance_rank_all') or row.get('rank') or 0),
        'binance_rank_topn': (int(row.get('binance_rank_all') or row.get('rank') or 0) if in_topn else 0),
        'score': round(float(row.get('score') or 0.0), 6),
        'quote_volume': round(float(row.get('quote_volume') or 0.0), 2),
        'quote_volume_24h': round(float(row.get('quote_volume_24h') or row.get('quote_volume') or 0.0), 2),
        'rep_symbol_quote_volume': round(float(row.get('rep_symbol_quote_volume') or 0.0), 2),
        'volatility_pct': round(float(row.get('volatility_pct') or 0.0), 6),
        'volatility_24h_pct': round(float(row.get('volatility_24h_pct') or row.get('volatility_pct') or 0.0), 6),
        'metric_ok': int(metric_ok),
        'metric_reason': str(metric_reason),
        'in_binance_ranked': bool(in_ranked),
        'in_binance_topn': bool(in_topn),
        'in_ext': in_ext,
        'in_var': in_var,
        'after_platform_both': bool(after_platform_both),
        'active_holding': bool(c in active_u),
        'blocked_reopen': bool(c in blocked_u),
        'in_waiting_queue': bool(final_selected),
        'final_rank': int(final_rank_mp.get(c) or 0),
        'exclude_stage': str(exclude_stage),
        'exclude_reason': str(exclude_reason),
        'binance_excluded_detail': dict(excluded_row or {}),
        'symbol': str(row.get('symbol') or row.get('rep_symbol') or excluded_row.get('symbol') or ''),
        'rep_symbol': str(row.get('rep_symbol') or row.get('symbol') or excluded_row.get('symbol') or ''),
        'rep_quote_asset': str(row.get('rep_quote_asset') or ''),
        'merged_symbols': str(row.get('merged_symbols') or ''),
        'symbol_warning': bool(_sym_meta.get('symbol_warning')),
        'symbol_warning_reason': str(_sym_meta.get('symbol_warning_reason') or ''),
        'explain': str(explain),
    }

def _coin_pool_selection_preview_text(rows: list[dict] | None = None, limit: int = 5) -> str:
    parts = []
    for row in list(rows or [])[:max(1, int(limit or 5))]:
        try:
            r = _coin_pool_selection_row_preview(row if isinstance(row, dict) else {})
            coin = str(r.get('coin') or '-')
            rank = int(r.get('rank') or 0)
            score = float(r.get('score') or 0.0)
            qv = float(r.get('quote_volume_24h') or r.get('quote_volume') or 0.0)
            vib = float(r.get('volatility_24h_pct') or r.get('volatility_pct') or 0.0)
            parts.append(f"{rank}.{coin}(score={score:.6f},24h量={qv:.2f},24h波动={vib:.6f})")
        except Exception:
            continue
    return ' | '.join(parts[:max(1, int(limit or 5))])

def _coin_pool_selection_detail_row(trace: dict | None = None) -> dict:
    try:
        t = dict(trace or {}) if isinstance(trace, dict) else {}
    except Exception:
        t = {}
    coin = str(t.get('coin') or '').upper().strip()
    final_selected = bool(t.get('in_waiting_queue'))
    bin_rank = int(t.get('binance_rank_all') or 0)
    final_rank = int(t.get('final_rank') or 0)
    in_ranked = bool(t.get('in_binance_ranked')) or bool(bin_rank > 0) or bool(t.get('in_binance_topn'))
    if final_selected:
        result = '入选'
    elif bool(t.get('active_holding')) or bool(t.get('blocked_reopen')) or in_ranked:
        result = '淘汰'
    else:
        result = '未进币安近24h成交额排名'
    return {
        'coin': coin,
        'symbol': str(t.get('symbol') or t.get('rep_symbol') or ''),
        'rep_symbol': str(t.get('rep_symbol') or t.get('symbol') or ''),
        'rep_quote_asset': str(t.get('rep_quote_asset') or ''),
        'merged_symbols': str(t.get('merged_symbols') or ''),
        'binance_rank_all': bin_rank,
        'in_binance_topn': int(bool(t.get('in_binance_topn'))),
        'in_ext': ('Y' if t.get('in_ext') is True else ('N' if t.get('in_ext') is False else '?')),
        'in_var': ('Y' if t.get('in_var') is True else ('N' if t.get('in_var') is False else '?')),
        'metric_ok': int(bool(t.get('metric_ok'))),
        'metric_reason': str(t.get('metric_reason') or ''),
        'active_holding': int(bool(t.get('active_holding'))),
        'blocked_reopen': int(bool(t.get('blocked_reopen'))),
        'in_waiting_queue': int(final_selected),
        'final_rank': final_rank,
        'score': round(float(t.get('score') or 0.0), 6),
        'quote_volume': round(float(t.get('quote_volume') or 0.0), 2),
        'quote_volume_24h': round(float(t.get('quote_volume_24h') or t.get('quote_volume') or 0.0), 2),
        'rep_symbol_quote_volume': round(float(t.get('rep_symbol_quote_volume') or 0.0), 2),
        'volatility_pct': round(float(t.get('volatility_pct') or 0.0), 6),
        'volatility_24h_pct': round(float(t.get('volatility_24h_pct') or t.get('volatility_pct') or 0.0), 6),
        'exclude_stage': str(t.get('exclude_stage') or ''),
        'exclude_reason': str(t.get('exclude_reason') or ''),
        'symbol_warning': int(bool(t.get('symbol_warning'))),
        'symbol_warning_reason': str(t.get('symbol_warning_reason') or ''),
        'result': result,
        'explain': str(t.get('explain') or ''),
    }

def _coin_pool_tri_bool_text(v: Any) -> str:
    try:
        if v is True:
            return 'Y'
        if v is False:
            return 'N'
    except Exception:
        pass
    return '?'

def _coin_pool_selection_detail_table_text(rows: list[dict] | None = None, limit: int = 0) -> str:
    try:
        items = list(rows or [])
    except Exception:
        items = []
    if limit and int(limit) > 0:
        items = items[:int(limit)]
    header = '币种 | 代表symbol | 合并symbol | 共享池排 | 指标就绪 | EXT | VAR | 持仓 | 禁重开 | 入队 | 最终排 | 分数 | 24h总交易额 | 代表symbol交易额 | 24h波动 | 警告 | 结果 | 原因'
    lines = [header]
    for row in items:
        try:
            r = _coin_pool_selection_detail_row(row if isinstance(row, dict) else {})
            lines.append(
                f"{str(r.get('coin') or '-')} | {str(r.get('rep_symbol') or r.get('symbol') or '-')} | {str(r.get('merged_symbols') or '-')} | {int(r.get('binance_rank_all') or 0)} | {int(r.get('in_binance_topn') or 0)} | {int(r.get('metric_ok') or 0)} | "
                f"{_coin_pool_tri_bool_text(r.get('in_ext'))} | {_coin_pool_tri_bool_text(r.get('in_var'))} | {int(r.get('active_holding') or 0)} | "
                f"{int(r.get('blocked_reopen') or 0)} | {int(r.get('in_waiting_queue') or 0)} | {int(r.get('final_rank') or 0)} | "
                f"{float(r.get('score') or 0.0):.6f} | {float(r.get('quote_volume_24h') or r.get('quote_volume') or 0.0):.2f} | {float(r.get('rep_symbol_quote_volume') or 0.0):.2f} | {float(r.get('volatility_24h_pct') or r.get('volatility_pct') or 0.0):.6f} | "
                f"{str(r.get('symbol_warning_reason') or '-') } | {str(r.get('result') or '-')} | {str(r.get('exclude_reason') or r.get('explain') or '-') }"
            )
        except Exception:
            continue
    return '\n'.join(lines)

def _coin_pool_selection_line_text(row: dict | None = None) -> str:
    try:
        if isinstance(row, dict) and ('result' in row) and ('in_ext' in row):
            r = dict(row or {})
        else:
            r = _coin_pool_selection_detail_row(row if isinstance(row, dict) else {})
    except Exception:
        r = {}
    return (
        f"coin={str(r.get('coin') or '-')} rep_symbol={str(r.get('rep_symbol') or r.get('symbol') or '-')} merged={str(r.get('merged_symbols') or '-')} "
        f"bin_rank_24h={int(r.get('binance_rank_all') or 0)} topn={int(r.get('in_binance_topn') or 0)} metric_ok={int(r.get('metric_ok') or 0)} "
        f"ext={_coin_pool_tri_bool_text(r.get('in_ext'))} var={_coin_pool_tri_bool_text(r.get('in_var'))} "
        f"active={int(r.get('active_holding') or 0)} blocked={int(r.get('blocked_reopen') or 0)} queued={int(r.get('in_waiting_queue') or 0)} "
        f"final_rank={int(r.get('final_rank') or 0)} score={float(r.get('score') or 0.0):.6f} "
        f"qv24h={float(r.get('quote_volume_24h') or r.get('quote_volume') or 0.0):.2f} rep_qv24h={float(r.get('rep_symbol_quote_volume') or 0.0):.2f} vol24h={float(r.get('volatility_24h_pct') or r.get('volatility_pct') or 0.0):.6f} "
        f"warn={str(r.get('symbol_warning_reason') or '-') } result={str(r.get('result') or '-')} "
        f"reason={str(r.get('exclude_reason') or '-') } explain={str(r.get('explain') or '-') }"
    )

def _coin_pool_emit_selection_observability(diag: dict | None = None, *, mode: str = '') -> None:
    try:
        d = dict(diag or {}) if isinstance(diag, dict) else {}
    except Exception:
        d = {}
    rows = [dict(x) for x in list(d.get('selection_detail_rows') or []) if isinstance(x, dict)]
    if (not rows) and str(mode or '').lower().startswith('skip'):
        rows = [dict(x) for x in list(d.get('last_selection_detail_rows') or []) if isinstance(x, dict)]
    active_coins = _coin_pool_dedupe([str(x or '').upper().strip() for x in list(d.get('active_coins') or []) if str(x or '').strip()])
    blocked_coins = _coin_pool_dedupe([str(x or '').upper().strip() for x in list(d.get('blocked_reopen_coins') or []) if str(x or '').strip()])
    queue_preview = [str(x or '').upper().strip() for x in list(d.get('queue_preview') or []) if str(x or '').strip()]
    last_queue_preview = [str(x or '').upper().strip() for x in list(d.get('last_queue_preview') or []) if str(x or '').strip()]
    steps = [str(x or '').strip() for x in list(d.get('selection_steps') or d.get('last_selection_steps') or []) if str(x or '').strip()]
    row_source = 'current' if list(d.get('selection_detail_rows') or []) else ('last' if rows else 'none')
    prefixes = ['[POOL][SELECT]', '[SELECTOR]']
    for pfx in prefixes:
        try:
            safe_log(lambda _pfx=pfx: f"{_pfx}[FLOW] mode={str(mode or d.get('mode') or '-')} row_source={row_source} active={int(d.get('active_cnt') or 0)}/{int(d.get('max_slots') or _coin_pool_max_slots())} free_slots={int(d.get('free_slots') or 0)} steps={' || '.join(steps) or '-'}")
            safe_log(lambda _pfx=pfx: f"{_pfx}[STATE] active_coins={','.join(active_coins) or '-'} blocked_reopen={','.join(blocked_coins) or '-'} locked_base={','.join([str(x or '').upper().strip() for x in list(d.get('locked_base') or []) if str(x or '').strip()]) or '-'}")
            safe_log(lambda _pfx=pfx: f"{_pfx}[QUEUE] head={str(d.get('queue_head') or '-')} queue={','.join(queue_preview) or '-'} last_head={str(d.get('last_queue_head') or '-')} last_queue={','.join(last_queue_preview) or '-'} skip_reason={str(d.get('skip_reason') or '-')} table={'yes' if str(d.get('selection_detail_table_text') or '').strip() else 'no'}")
        except Exception:
            pass
    try:
        _observe_emit('SELECTOR', f"mode={str(mode or d.get('mode') or '-')} active={int(d.get('active_cnt') or 0)}/{int(d.get('max_slots') or _coin_pool_max_slots())} free_slots={int(d.get('free_slots') or 0)} head={str(d.get('queue_head') or '-')} queue={','.join(queue_preview) or '-'} steps={' || '.join(steps) or '-'}", subtag='MODULE')
    except Exception:
        pass
    try:
        _pin('SELECTOR_OBSERVE', mod='SELECTOR', coin='*', stage='SELECTOR_OBSERVE', ok=1, reason=str(mode or d.get('mode') or 'selector_observe'), detail={'queue_head': str(d.get('queue_head') or ''), 'queue_preview': list(queue_preview[:10]), 'row_source': row_source})
    except Exception:
        pass
    warn_rows = []
    for row in rows[:80]:
        try:
            safe_log(lambda _row=dict(row): f"[POOL][SELECT][ROW] {_coin_pool_selection_line_text(_row)}")
            safe_log(lambda _row=dict(row): f"[SELECTOR][ROW] {_coin_pool_selection_line_text(_row)}")
            if str((row or {}).get('symbol_warning_reason') or '').strip():
                warn_rows.append(dict(row))
        except Exception:
            continue
    for row in warn_rows[:20]:
        try:
            safe_log(lambda _row=dict(row): f"[POOL][SELECT][WARN] coin={str(_row.get('coin') or '-')} symbol={str(_row.get('symbol') or _row.get('rep_symbol') or '-')} warn={str(_row.get('symbol_warning_reason') or '-')} ")
            safe_log(lambda _row=dict(row): f"[SELECTOR][WARN] coin={str(_row.get('coin') or '-')} symbol={str(_row.get('symbol') or _row.get('rep_symbol') or '-')} warn={str(_row.get('symbol_warning_reason') or '-')} ")
        except Exception:
            continue

def _coin_pool_rebuild_waiting_queue(snapshot: dict | None = None, base_coins: list[str] | None = None) -> tuple[list[str], list[dict], dict]:
    st = _coin_pool_state_scrub(_coin_pool_state_load(force=False))
    active = set(_coin_pool_dedupe(list(st.get('active_holding_coins') or [])))
    try:
        if _coin_pool_snapshot_has_positions_truth(snapshot):
            _active_truth = _coin_pool_collect_active_holding_coins(snapshot, fallback_coins=list(base_coins or []))
            active = set(_coin_pool_dedupe(list(_active_truth or [])))
    except Exception:
        pass
    blocked = set(_coin_pool_dedupe(list(st.get('blocked_reopen_after_exit') or [])))
    try:
        _max_slots_rebuild = int(_coin_pool_max_slots())
    except Exception:
        _max_slots_rebuild = 0
    _active_cnt_rebuild = int(len(active))
    _free_slots_rebuild = max(0, int(_max_slots_rebuild) - int(_active_cnt_rebuild))
    if int(_free_slots_rebuild) <= 0:
        diag = {
            'mode': 'skip_rebuild_slots_full',
            'skip_reason': 'slots_full_no_need_rebuild',
            'active_cnt': int(_active_cnt_rebuild),
            'max_slots': int(_max_slots_rebuild),
            'free_slots': int(_free_slots_rebuild),
            'active_coins': list(sorted(active)),
            'blocked_reopen_coins': list(sorted(blocked)),
            'queue_head': '',
            'queue_preview': [],
            'frozen_waiting_queue': True,
            'rank_advance_ok': False,
            'selection_deferred_until_scan_truth': False,
        }
        try:
            safe_log(lambda: f"[POOL][SELECT] skip_rebuild_slots_full active={diag.get('active_cnt')}/{diag.get('max_slots')} free_slots={diag.get('free_slots')} active_coins={','.join(list(diag.get('active_coins') or [])[:20]) or '-'}")
            _pin('COIN_POOL_SELECT', mod='POOL', coin='*', stage='COIN_POOL_SELECT', ok=1, reason='skip_rebuild_slots_full', detail=diag)
        except Exception:
            pass
        return [], [], {'diag': diag, 'symbol_map': {}}
    ext_set, ext_ok, ext_reason = _coin_pool_ext_active_set(timeout_s=6.0)
    var_set, var_ok, var_reason = _coin_pool_var_active_set(timeout_s=6.0)
    shared_set = set()
    if ext_ok and var_ok:
        shared_set = set([c for c in set(ext_set) & set(var_set) if c and (not _coin_pool_is_stable_like(c))])
    ranked_all, symbol_map, spot_ok, spot_reason, spot_diag = _coin_pool_binance_ranked(timeout_s=6.0, allowed_coins=shared_set)
    all_ok = bool(ext_ok and var_ok and spot_ok)
    locked_base = _coin_pool_locked_base_coins()
    row_map = {str((r or {}).get('coin') or '').upper().strip(): dict(r or {}) for r in list(ranked_all or []) if isinstance(r, dict) and str((r or {}).get('coin') or '').strip()}
    rows_after_metric = [dict(r or {}) for r in list(ranked_all or []) if isinstance(r, dict) and bool((r or {}).get('metric_ok'))]
    rows_after_active_block = []
    active_block_filtered_preview = []
    for row in rows_after_metric:
        coin = str((row or {}).get('coin') or '').upper().strip()
        if (coin in active) or (coin in blocked):
            why = 'active_holding' if coin in active else 'blocked_reopen'
            row['exclude_stage'] = ('active_filter' if coin in active else 'blocked_filter')
            row['exclude_reason'] = why
            if len(active_block_filtered_preview) < 10:
                active_block_filtered_preview.append(coin)
            continue
        row['selection_step'] = 'final_ranked'
        rows_after_active_block.append(row)
    rows_after_active_block = sorted(rows_after_active_block, key=lambda x: (bool(x.get('volume_gate_pass')), float(x.get('score') or 0.0), float(x.get('quote_volume_24h') or 0.0), float(x.get('volatility_pct') or 0.0)), reverse=True)
    for idx, row in enumerate(rows_after_active_block, start=1):
        if isinstance(row, dict):
            row['rank'] = int(idx)
            row['final_rank'] = int(idx)
            row['common_platforms'] = ['EXT', 'VAR', str(row.get('source') or '').upper().strip()]
            row['selected_reason'] = '候选池固定为EXT∩VAR，先取币安现货公共指标，缺失币补MEXC/Gate，再按量优先综合分从高到低递补'
    free_slots = max(0, int(_coin_pool_max_slots()) - int(len(active)))
    queue_limit_by_slots = max(0, int(free_slots))
    queue_limit_final = max(0, min(int(COIN_POOL_WAITING_KEEP), int(queue_limit_by_slots)))
    queue = _coin_pool_dedupe([str(r.get('coin') or '').upper().strip() for r in rows_after_active_block])[:int(queue_limit_final)]
    final_rank_map = {str((r or {}).get('coin') or '').upper().strip(): int(idx + 1) for idx, r in enumerate(rows_after_active_block) if isinstance(r, dict)}
    selection_rows_preview = [_coin_pool_selection_row_preview(r) for r in list(rows_after_active_block or [])[:10] if isinstance(r, dict)]
    watch_coins = _coin_pool_trace_watch_coins()
    selection_detail_coins = _coin_pool_dedupe(list(shared_set) + list(watch_coins))
    selection_detail_traces = [
        _coin_pool_selection_candidate_trace(c, row_map=row_map, topn_coins=shared_set, ext_set=ext_set, var_set=var_set,
                                            active=active, blocked=blocked, final_queue=queue, final_rank_map=final_rank_map,
                                            binance_excluded_map=((spot_diag or {}).get('excluded_map') or {}),
                                            ext_ok=bool(ext_ok), var_ok=bool(var_ok))
        for c in selection_detail_coins
    ]
    watch_candidates = _coin_pool_dedupe(list(watch_coins) + [c for c in list(selection_detail_coins)[:10] if c])
    watch_traces = [dict(x) for x in selection_detail_traces if str((x or {}).get('coin') or '').upper().strip() in set(watch_candidates)]
    selection_detail_rows = [_coin_pool_selection_detail_row(x) for x in list(selection_detail_traces or [])]
    selection_detail_table_text = _coin_pool_selection_detail_table_text(selection_detail_traces, limit=0)
    edge_trace = next((dict(x) for x in selection_detail_traces if str((x or {}).get('coin') or '').upper().strip() == 'EDGE'), {})
    diag = {
        'binance': spot_reason,
        'ext': ext_reason,
        'var': var_reason,
        'all_platform_ok': bool(all_ok),
        'active_cnt': len(active),
        'blocked_cnt': len(blocked),
        'free_slots': max(0, int(_coin_pool_max_slots()) - int(len(active))),
        'active_coins': list(sorted(active)),
        'blocked_reopen_coins': list(sorted(blocked)),
        'locked_base': list(locked_base),
        'ext_fetch_debug': str(ext_reason),
        'var_fetch_debug': str(var_reason),
        'binance_total': int(len(list(ranked_all or []))),
        'binance_universe_total': int(len(shared_set)),
        'binance_top30_metric_ready_total': int((spot_diag or {}).get('topn_metric_ready_total') or 0),
        'binance_insufficient_24h_total': int((spot_diag or {}).get('insufficient_24h_total') or 0),
        'binance_ticker_missing_total': int((spot_diag or {}).get('ticker_missing_total') or 0),
        'binance_fetch_fail_total': int((spot_diag or {}).get('fetch_fail_total') or 0),
        'binance_topn_limit': int(len(shared_set)),
        'binance_topn_cnt': int(len(list(ranked_all or []))),
        'after_topn_cnt': int(len(list(ranked_all or []))),
        'after_metric_cnt': int(len(rows_after_metric)),
        'after_platform_verify_cnt': int(len(rows_after_metric)),
        'after_stable_cnt': int(len(rows_after_metric)),
        'after_active_block_cnt': int(len(rows_after_active_block)),
        'ext_tradeable_total': int(len(ext_set or set())),
        'var_tradeable_total': int(len(var_set or set())),
        'after_ext_cnt': int(len(shared_set)),
        'after_var_cnt': int(len(shared_set)),
        'queue_head': str((queue[0] if queue else '')),
        'queue_preview': list(queue[:20]),
        'selection_rows_preview': list(selection_rows_preview),
        'selection_scope': 'shared_ext_var_spot_fallback',
        'selection_reason': '候选池固定为EXT∩VAR；指标主源=币安现货公共接口；缺失币补MEXC/Gate；统一按量优先综合分排名',
        'selection_rank_rule': str((list(ranked_all or [])[:1] or [{}])[0].get('rank_rule') if list(ranked_all or []) else ''),
        'selection_steps': [
            '第1步：拉取 EXT 可交易币',
            '第2步：拉取 VAR 可交易币',
            '第3步：取 EXT∩VAR 共有币作为唯一候选池',
            '第4步：候选池逐币先取币安现货公共指标，缺失币补 MEXC/Gate',
            '第5步：按量优先综合分统一排名，再扣除已持仓/禁重开后形成候补队列',
        ],
        'selection_detail_rows': list(selection_detail_rows),
        'selection_detail_table_text': str(selection_detail_table_text),
        'watch_coin_traces': list(watch_traces),
        'edge_trace': dict(edge_trace),
        'metric_filtered_preview': [str((x or {}).get('coin') or '') + '(' + str((x or {}).get('metric_reason') or '') + ')' for x in list(ranked_all or []) if isinstance(x, dict) and (not bool(x.get('metric_ok')))][0:10],
        'platform_filtered_preview': [],
        'active_block_filtered_preview': list(active_block_filtered_preview[:10]),
        'top_binance_preview': [dict(_coin_pool_selection_row_preview(r)) for r in list(ranked_all or [])[:10] if isinstance(r, dict)],
        'binance_excluded_preview': [dict(x) for x in list((spot_diag or {}).get('excluded_preview') or [])[:10]],
        'symbol_warning_total': int((spot_diag or {}).get('symbol_warning_total') or 0),
        'symbol_warning_preview': list((spot_diag or {}).get('symbol_warning_preview') or [])[:10],
        'source_counts': dict((spot_diag or {}).get('source_counts') or {}),
        'shared_total': int(len(shared_set)),
        'ok_total': int((spot_diag or {}).get('ok_total') or len(rows_after_metric)),
        'fail_total': int((spot_diag or {}).get('fail_total') or (len(shared_set) - len(rows_after_metric))),
        'freeze_new_candidates': False,
        'frozen_waiting_queue': False,
        'rank_advance_ok': True,
    }
    if all_ok:
        try:
            _sel_preview_txt = _coin_pool_selection_preview_text(diag.get('selection_rows_preview') or [], limit=5)
            _trace_txt = ' | '.join([f"{str(t.get('coin') or '-')}=>{str(t.get('exclude_reason') or 'selected') or 'selected'}" for t in list(diag.get('watch_coin_traces') or [])[:8]])
            safe_log(lambda: f"[POOL][SELECT] active={diag.get('active_cnt')}/{_coin_pool_max_slots()} free_slots={diag.get('free_slots')} shared={diag.get('shared_total')} ok={diag.get('ok_total')} fail={diag.get('fail_total')} ext_total={diag.get('ext_tradeable_total')} var_total={diag.get('var_tradeable_total')} source_counts={json.dumps(diag.get('source_counts') or {}, ensure_ascii=False)} head={diag.get('queue_head') or '-'} queue={','.join(list(diag.get('queue_preview') or [])[:10]) or '-'} how={diag.get('selection_reason') or '-'} top={_sel_preview_txt or '-'} filtered_metric={','.join(list(diag.get('metric_filtered_preview') or [])[:5]) or '-'} filtered_active_block={','.join(list(diag.get('active_block_filtered_preview') or [])[:5]) or '-'} trace={_trace_txt or '-'}")
            safe_log(lambda: "[POOL][SELECT][DETAIL_TABLE]\n" + str(diag.get('selection_detail_table_text') or '-'))
            _coin_pool_emit_selection_observability(diag, mode='rebuild_waiting_queue')
            _pin('COIN_POOL_SELECT', mod='POOL', coin='*', stage='COIN_POOL_SELECT', ok=1, reason='rebuild_waiting_queue', detail=diag)
        except Exception:
            pass
        try:
            _sel_preview_txt = _coin_pool_selection_preview_text(diag.get('selection_rows_preview') or [], limit=5)
            _trace_txt = ' | '.join([f"{str(t.get('coin') or '-')}=>{str(t.get('explain') or '-')}" for t in list(diag.get('watch_coin_traces') or [])[:5]])
            _detail_rows = list(diag.get('selection_detail_rows') or [])
            _detail_preview = ' | '.join([f"{str(x.get('coin') or '-')}:{str(x.get('result') or '-')}/{str(x.get('exclude_reason') or 'selected') or 'selected'}" for x in _detail_rows[:10]])
            _observe_emit('POOL', f"选币：持仓={diag['active_cnt']}/{_coin_pool_max_slots()} -> EXT∩VAR共有池={diag.get('shared_total')} -> 现货指标成功={diag.get('ok_total')}（失败={diag.get('fail_total')}） -> 去持仓/禁重开后={diag['after_active_block_cnt']} | 来源分布={json.dumps(diag.get('source_counts') or {}, ensure_ascii=False)} | 规则={diag.get('selection_rank_rule') or '-'} | 队首={diag['queue_head'] or '-'} | 队列前十={','.join(queue[:10]) or '-'} | 入选明细={_sel_preview_txt or '-'} | 逐币表前十={_detail_preview or '-'} | 指标未过={','.join(list(diag.get('metric_filtered_preview') or [])[:5]) or '-'} | 重点追踪={_trace_txt or '-'}", subtag='SELECT')
        except Exception:
            pass
        return queue, rows_after_active_block[:50], {'diag': diag, 'symbol_map': symbol_map}
    diag['mode'] = 'selector_module_fallback_locked_base_platform_guard'
    diag['freeze_new_candidates'] = True
    diag['frozen_waiting_queue'] = True
    diag['rank_advance_ok'] = False
    try:
        safe_log(lambda: f"[POOL][SELECT] freeze_new_candidates shared={diag.get('shared_total')} why_ext={diag.get('ext')} why_var={diag.get('var')} why_spot={diag.get('binance')} sources={json.dumps(diag.get('source_counts') or {}, ensure_ascii=False)}")
        _coin_pool_emit_selection_observability(diag, mode='freeze_new_candidates')
        _pin('COIN_POOL_SELECT', mod='POOL', coin='*', stage='COIN_POOL_SELECT', ok=0, reason='freeze_new_candidates', detail=diag)
    except Exception:
        pass
    try:
        _observe_emit('POOL', f"选币冻结：spot={diag['binance']} EXT={diag['ext']} VAR={diag['var']} | waiting_queue=空", subtag='SELECT')
    except Exception:
        pass
    return [], [], {'diag': diag, 'symbol_map': symbol_map}

def _coin_pool_refresh_runtime_state(snapshot: dict | None = None, base_coins: list[str] | None = None, *, force: bool = False) -> dict:
    global COIN_POOL_NEXT_REFRESH_TS, _COIN_POOL_LAST_FETCH_DIAG
    st = _coin_pool_state_load(force=False)
    prev_active = _coin_pool_dedupe(list(st.get('active_holding_coins') or []))
    if not _snapshot_positions_verified(snapshot):
        # A failed scan cannot release live slots, clear the pool, or rebuild it.
        return copy.deepcopy(st)
    active = _coin_pool_collect_active_holding_coins(snapshot, fallback_coins=list(base_coins or []))
    blocked = _coin_pool_dedupe(list(st.get('blocked_reopen_after_exit') or []))
    blocked_set = set(blocked)
    _removed_fully_exited: list[str] = []
    for c in prev_active:
        if (c not in active) and _coin_pool_is_fully_exited(c, snapshot):
            blocked_set.add(c)
            _removed_fully_exited.append(c)
    for c in active:
        if c in blocked_set:
            blocked_set.discard(c)
    st['active_holding_coins'] = _coin_pool_dedupe(active)
    st['blocked_reopen_after_exit'] = _coin_pool_dedupe(list(blocked_set))
    _prev_diag = dict(st.get('last_refresh_diag') or {}) if isinstance(st.get('last_refresh_diag'), dict) else {}
    _waiting_queue_before_clear = _coin_pool_dedupe(list(st.get('waiting_queue') or []))
    max_slots = int(_coin_pool_max_slots())
    active_cnt = int(len(st['active_holding_coins']))
    free_slots = max(0, int(max_slots) - int(active_cnt))
    has_scan_truth = bool(_coin_pool_snapshot_has_positions_truth(snapshot))
    provisional_active = _coin_pool_dedupe(list(base_coins or [])) if (not has_scan_truth) else list(st.get('active_holding_coins') or [])
    provisional_active_cnt = int(len(provisional_active))
    provisional_free_slots = max(0, int(max_slots) - int(provisional_active_cnt))
    _effective_waiting_before, _waiting_skip_before, _skipped_waiting_before = _coin_pool_effective_waiting_queue(st)
    _prev_active_cnt = int(len(prev_active))
    _stale_slots_full_diag = bool(has_scan_truth and free_slots > 0 and str(_prev_diag.get('skip_reason') or '') == 'slots_full_no_need_select' and int(_prev_diag.get('active_cnt') or 0) >= int(max_slots))
    _waiting_queue_short = bool(has_scan_truth and free_slots > 0 and len(_effective_waiting_before) < int(free_slots))
    _slots_released_after_exit = bool(has_scan_truth and free_slots > 0 and active_cnt < _prev_active_cnt)
    _immediate_refresh_reason = ''
    if _coin_pool_enabled() and (not force):
        if _slots_released_after_exit and _removed_fully_exited:
            _immediate_refresh_reason = 'slots_released_after_exit'
        elif _stale_slots_full_diag:
            _immediate_refresh_reason = 'slots_released_stale_slots_full_diag'
        elif _waiting_queue_short:
            _immediate_refresh_reason = 'slots_released_waiting_queue_short'
    need_refresh = bool(force or bool(_immediate_refresh_reason) or (float(time.time()) >= float(COIN_POOL_NEXT_REFRESH_TS or 0.0)))
    if _immediate_refresh_reason:
        try:
            _pin('COIN_POOL_SLOT_RELEASE', mod='POOL', coin='*', stage='COIN_POOL_SLOT_RELEASE', ok=1, reason=str(_immediate_refresh_reason), detail={
                'prev_active_cnt': int(_prev_active_cnt),
                'active_cnt': int(active_cnt),
                'free_slots': int(free_slots),
                'removed_fully_exited': list(_removed_fully_exited[:10]),
                'effective_waiting_before': list(_effective_waiting_before[:10]),
                'waiting_skip_before': list((_waiting_skip_before or {}).keys())[:10],
                'skipped_waiting_before': list(_skipped_waiting_before[:10]),
                'prev_skip_reason': str(_prev_diag.get('skip_reason') or ''),
                'prev_queue_head': str(_prev_diag.get('queue_head') or ''),
                'prev_queue_preview': list((_prev_diag.get('queue_preview') or [])[:10]),
            })
        except Exception:
            pass
        if _removed_fully_exited:
            try:
                safe_log(lambda: f"[POOL][FULLY_EXITED] removed={','.join(list(_removed_fully_exited)[:10]) or '-'} prev_active={','.join(list(prev_active)[:20]) or '-'} active_now={','.join(list(st.get('active_holding_coins') or [])[:20]) or '-'} free_slots={int(free_slots)} trigger={str(_immediate_refresh_reason or '-')}")
                _observe_emit('POOL', f"币池释放槽位：退出={','.join(list(_removed_fully_exited)[:10]) or '-'} | active={active_cnt}/{max_slots} 空槽={free_slots} | 立即重建候补队列", subtag='SELECT')
                _pin('COIN_POOL_FULLY_EXITED', mod='POOL', coin='*', stage='COIN_POOL_FULLY_EXITED', ok=1, reason='fully_exited_removed_from_active_pool', detail={
                    'removed_fully_exited': list(_removed_fully_exited[:10]),
                    'active_cnt': int(active_cnt),
                    'free_slots': int(free_slots),
                    'trigger': str(_immediate_refresh_reason or ''),
                })
            except Exception:
                pass
    if _coin_pool_enabled() and need_refresh:
        if (not force) and (not has_scan_truth):
            _diag_now = {
                'mode': 'defer_select_wait_scan_truth',
                'all_platform_ok': None,
                'active_cnt': int(provisional_active_cnt),
                'blocked_cnt': int(len(st['blocked_reopen_after_exit'] or [])),
                'active_coins': list(provisional_active or []),
                'raw_active_cnt': int(active_cnt),
                'raw_active_coins': list(st.get('active_holding_coins') or []),
                'blocked_reopen_coins': list(st.get('blocked_reopen_after_exit') or []),
                'locked_base': list(_coin_pool_locked_base_coins()),
                'freeze_new_candidates': True,
                'frozen_waiting_queue': True,
                'rank_advance_ok': False,
                'skip_reason': 'await_scan_truth_before_select',
                'selection_deferred_until_scan_truth': True,
                'snapshot_truth_ready': False,
                'max_slots': int(max_slots),
                'free_slots': int(provisional_free_slots),
                'binance_total': 0,
                'ext_tradeable_total': 0,
                'var_tradeable_total': 0,
                'after_ext_cnt': 0,
                'after_var_cnt': 0,
                'after_stable_cnt': 0,
                'after_active_block_cnt': 0,
                'queue_head': str((_waiting_queue_before_clear[0] if _waiting_queue_before_clear else '')),
                'queue_preview': list(_waiting_queue_before_clear[:20]),
                'top_binance_preview': [],
                'waiting_queue_cleared': 0,
                'waiting_queue_before_clear': list(_waiting_queue_before_clear[:20]),
                'last_queue_head': str(_prev_diag.get('queue_head') or (_waiting_queue_before_clear[0] if _waiting_queue_before_clear else '')),
                'last_queue_preview': list((_prev_diag.get('queue_preview') or _waiting_queue_before_clear)[:20]),
                'last_selection_steps': list(_prev_diag.get('selection_steps') or []),
                'last_selection_scope': str(_prev_diag.get('selection_scope') or ''),
                'last_selection_reason': str(_prev_diag.get('selection_reason') or ''),
                'last_selection_detail_rows': [dict(x) for x in list(_prev_diag.get('selection_detail_rows') or [])[:80]],
                'last_selection_detail_table_text': str(_prev_diag.get('selection_detail_table_text') or ''),
                'last_watch_coin_traces': [dict(x) for x in list(_prev_diag.get('watch_coin_traces') or [])[:20]],
                'last_edge_trace': dict(_prev_diag.get('edge_trace') or {}),
            }
            try:
                safe_log(lambda: f"[POOL][SELECT] defer_select_wait_scan_truth active={_diag_now.get('active_cnt')}/{_diag_now.get('max_slots')} free_slots={_diag_now.get('free_slots')} raw_active={_diag_now.get('raw_active_cnt')} active_coins={','.join(list(_diag_now.get('active_coins') or [])[:20]) or '-'} raw_active_coins={','.join(list(_diag_now.get('raw_active_coins') or [])[:20]) or '-'} blocked={','.join(list(_diag_now.get('blocked_reopen_coins') or [])[:20]) or '-'} last_head={_diag_now.get('last_queue_head') or '-'} last_queue={','.join(list(_diag_now.get('last_queue_preview') or [])[:10]) or '-'}")
                if str(_diag_now.get('last_selection_detail_table_text') or '').strip():
                    safe_log(lambda: "[POOL][SELECT][LAST_DETAIL_TABLE]\n" + str(_diag_now.get('last_selection_detail_table_text') or '-'))
                _coin_pool_emit_selection_observability(_diag_now, mode='defer_select_wait_scan_truth')
                _pin('COIN_POOL_SELECT', mod='POOL', coin='*', stage='COIN_POOL_SELECT', ok=1, reason='await_scan_truth_before_select', detail=_diag_now)
            except Exception:
                pass
            try:
                _observe_emit('POOL', f"选币延后：active={provisional_active_cnt}/{max_slots} 空槽={provisional_free_slots} | 扫描真相未就绪，本轮先不按旧活跃态跳过新币递补 | 当前基础币={','.join(list(_diag_now.get('active_coins') or [])[:10]) or '-'} | 旧活跃态={','.join(list(_diag_now.get('raw_active_coins') or [])[:10]) or '-'}", subtag='SELECT')
            except Exception:
                pass
            _COIN_POOL_LAST_FETCH_DIAG = dict(_diag_now or {})
            st['last_refresh_diag'] = dict(_COIN_POOL_LAST_FETCH_DIAG or {})
        elif (not force) and active_cnt >= int(max_slots):
            _diag_now = {
                'mode': 'skip_select_slots_full',
                'all_platform_ok': None,
                'active_cnt': int(active_cnt),
                'blocked_cnt': int(len(st['blocked_reopen_after_exit'] or [])),
                'active_coins': list(st.get('active_holding_coins') or []),
                'blocked_reopen_coins': list(st.get('blocked_reopen_after_exit') or []),
                'locked_base': list(_coin_pool_locked_base_coins()),
                'freeze_new_candidates': True,
                'frozen_waiting_queue': True,
                'rank_advance_ok': False,
                'skip_reason': 'slots_full_no_need_select',
                'selection_deferred_until_scan_truth': False,
                'snapshot_truth_ready': True,
                'max_slots': int(max_slots),
                'free_slots': int(free_slots),
                'binance_total': 0,
                'ext_tradeable_total': 0,
                'var_tradeable_total': 0,
                'after_ext_cnt': 0,
                'after_var_cnt': 0,
                'after_stable_cnt': 0,
                'after_active_block_cnt': 0,
                'queue_head': '',
                'queue_preview': [],
                'top_binance_preview': [],
                'waiting_queue_cleared': int(bool(_waiting_queue_before_clear)),
                'waiting_queue_before_clear': list(_waiting_queue_before_clear[:20]),
                'last_queue_head': str(_prev_diag.get('queue_head') or (_waiting_queue_before_clear[0] if _waiting_queue_before_clear else '')),
                'last_queue_preview': list((_prev_diag.get('queue_preview') or _waiting_queue_before_clear)[:20]),
                'last_selection_steps': list(_prev_diag.get('selection_steps') or []),
                'last_selection_scope': str(_prev_diag.get('selection_scope') or ''),
                'last_selection_reason': str(_prev_diag.get('selection_reason') or ''),
                'last_selection_detail_rows': [dict(x) for x in list(_prev_diag.get('selection_detail_rows') or [])[:80]],
                'last_selection_detail_table_text': str(_prev_diag.get('selection_detail_table_text') or ''),
                'last_watch_coin_traces': [dict(x) for x in list(_prev_diag.get('watch_coin_traces') or [])[:20]],
                'last_edge_trace': dict(_prev_diag.get('edge_trace') or {}),
            }
            st['waiting_queue'] = []
            st['ranked_openable_universe'] = []
            st['binance_symbol_map'] = {}
            try:
                safe_log(lambda: f"[POOL][SELECT] skip_select_slots_full active={_diag_now.get('active_cnt')}/{_diag_now.get('max_slots')} free_slots={_diag_now.get('free_slots')} waiting_cleared={_diag_now.get('waiting_queue_cleared')} active_coins={','.join(list(_diag_now.get('active_coins') or [])[:20]) or '-'} blocked={','.join(list(_diag_now.get('blocked_reopen_coins') or [])[:20]) or '-'} last_head={_diag_now.get('last_queue_head') or '-'} last_queue={','.join(list(_diag_now.get('last_queue_preview') or [])[:10]) or '-'}")
                if str(_diag_now.get('last_selection_detail_table_text') or '').strip():
                    safe_log(lambda: "[POOL][SELECT][LAST_DETAIL_TABLE]\n" + str(_diag_now.get('last_selection_detail_table_text') or '-'))
                _coin_pool_emit_selection_observability(_diag_now, mode='skip_select_slots_full')
                _pin('COIN_POOL_SELECT', mod='POOL', coin='*', stage='COIN_POOL_SELECT', ok=1, reason='skip_select_slots_full', detail=_diag_now)
            except Exception:
                pass
            try:
                _observe_emit('POOL', f"选币跳过：active={active_cnt}/{max_slots} 空槽={free_slots} | 持仓已满，无需每轮重选新币 | 当前持仓={','.join(list(_diag_now.get('active_coins') or [])[:10]) or '-'} | 上次候补={','.join(list(_diag_now.get('last_queue_preview') or [])[:10]) or '-'}", subtag='SELECT')
            except Exception:
                pass
            if str(_immediate_refresh_reason or '').strip():
                _diag_now['refresh_trigger'] = str(_immediate_refresh_reason)
                _diag_now['slot_release_removed'] = list(_removed_fully_exited[:10])
                _diag_now['waiting_queue_before_refresh'] = list(_waiting_queue_before_clear[:10])
                _diag_now['effective_waiting_before_refresh'] = list(_effective_waiting_before[:10])
                _diag_now['skipped_waiting_before_refresh'] = list(_skipped_waiting_before[:10])
            _COIN_POOL_LAST_FETCH_DIAG = dict(_diag_now or {})
            st['last_refresh_diag'] = dict(_COIN_POOL_LAST_FETCH_DIAG or {})
            try:
                lo = int(max(300, int(cfg_getf_runtime('COIN_POOL_REFRESH_MIN_SEC', float(COIN_POOL_REFRESH_MIN_SEC)) or COIN_POOL_REFRESH_MIN_SEC)))
                hi = int(max(lo, int(cfg_getf_runtime('COIN_POOL_REFRESH_MAX_SEC', float(COIN_POOL_REFRESH_MAX_SEC)) or COIN_POOL_REFRESH_MAX_SEC)))
            except Exception:
                lo, hi = int(COIN_POOL_REFRESH_MIN_SEC), int(COIN_POOL_REFRESH_MAX_SEC)
            try:
                COIN_POOL_NEXT_REFRESH_TS = float(time.time()) + float(random.randint(int(lo), int(hi)))
            except Exception:
                COIN_POOL_NEXT_REFRESH_TS = float(time.time()) + float(lo)
        else:
            waiting, ranked, meta = _coin_pool_rebuild_waiting_queue(snapshot, base_coins=list(base_coins or []))
            _diag_now = dict((meta or {}).get('diag') or {}) if isinstance(meta, dict) else {}
            _diag_now['refresh_trigger'] = str(_immediate_refresh_reason or ('force_refresh' if force else 'scheduled_refresh'))
            _diag_now['force_rebuild_now'] = bool(force or bool(_immediate_refresh_reason))
            _diag_now['waiting_queue_before_refresh'] = list(_waiting_queue_before_clear[:10])
            _diag_now['effective_waiting_before_refresh'] = list(_effective_waiting_before[:10])
            _diag_now['skipped_waiting_before_refresh'] = list(_skipped_waiting_before[:10])
            _diag_now['slot_release_removed'] = list(_removed_fully_exited[:10])
            _freeze_new = bool(_diag_now.get('freeze_new_candidates'))
            if _freeze_new:
                st['waiting_queue'] = []
                st['ranked_openable_universe'] = []
                st['binance_symbol_map'] = {}
            else:
                st['waiting_queue'] = _coin_pool_dedupe(waiting)
                st['ranked_openable_universe'] = [r for r in ranked if isinstance(r, dict)][:50]
                st = _coin_pool_state_scrub(st)
                try:
                    st['binance_symbol_map'] = dict((meta or {}).get('symbol_map') or st.get('binance_symbol_map') or {})
                except Exception:
                    st['binance_symbol_map'] = dict(st.get('binance_symbol_map') or {})
            _COIN_POOL_LAST_FETCH_DIAG = dict(_diag_now or {})
            st['last_refresh_diag'] = dict(_COIN_POOL_LAST_FETCH_DIAG or {})
            try:
                lo = int(max(300, int(cfg_getf_runtime('COIN_POOL_REFRESH_MIN_SEC', float(COIN_POOL_REFRESH_MIN_SEC)) or COIN_POOL_REFRESH_MIN_SEC)))
                hi = int(max(lo, int(cfg_getf_runtime('COIN_POOL_REFRESH_MAX_SEC', float(COIN_POOL_REFRESH_MAX_SEC)) or COIN_POOL_REFRESH_MAX_SEC)))
            except Exception:
                lo, hi = int(COIN_POOL_REFRESH_MIN_SEC), int(COIN_POOL_REFRESH_MAX_SEC)
            try:
                COIN_POOL_NEXT_REFRESH_TS = float(time.time()) + float(random.randint(int(lo), int(hi)))
            except Exception:
                COIN_POOL_NEXT_REFRESH_TS = float(time.time()) + float(lo)
    else:
        st['waiting_queue'] = _coin_pool_dedupe(list(st.get('waiting_queue') or []))
        try:
            st['last_refresh_diag'] = _coin_pool_diag_runtime_sync(
                (st.get('last_refresh_diag') or {}),
                st,
                active_cnt=active_cnt,
                free_slots=free_slots,
                max_slots=max_slots,
                reason='runtime_state_sync_no_rebuild',
                trigger=str(_immediate_refresh_reason or ''),
            )
        except Exception:
            pass
    st = _coin_pool_state_scrub(st)
    _coin_pool_state_save(st)
    return st

def _coin_pool_runtime_scan_watch_coins(snapshot: dict | None = None, base_coins: list[str] | None = None) -> list[str]:
    st = _coin_pool_refresh_runtime_state(snapshot, base_coins=list(base_coins or []), force=False)
    active = _coin_pool_dedupe(list(st.get('active_holding_coins') or []))
    waiting = _coin_pool_dedupe(list(st.get('waiting_queue') or []))
    max_slots = int(_coin_pool_max_slots())
    free_slots = max(0, int(max_slots) - int(len(active)))
    watch_n = max(0, int(_coin_pool_watch_candidates()))
    waiting_take = max(0, min(int(free_slots), int(watch_n)))
    run = _coin_pool_dedupe(active + waiting[:int(waiting_take)])
    try:
        _observe_emit('POOL', f'运行币池：真实持仓={len(active)}/{max_slots} 空槽={free_slots} 候补带入={waiting_take} | active={",".join(active[:12]) or "-"} | waiting={",".join(waiting[:12]) or "-"} | run={",".join(run[:20]) or "-"}', subtag='RUNSET')
    except Exception:
        pass
    if run:
        return run
    return _coin_pool_dedupe(list(_coin_pool_locked_base_coins()))[:max(int(max_slots), len(_coin_pool_locked_base_coins()))]

_COIN_POOL_LAST_BLOCKED_REOPEN_EVENT: dict = {}

def _coin_pool_last_blocked_reopen_event() -> dict:
    try:
        ev = globals().get('_COIN_POOL_LAST_BLOCKED_REOPEN_EVENT')
        return dict(ev or {}) if isinstance(ev, dict) else {}
    except Exception:
        return {}

_NEW_COIN_LAST_CAP_EVENT: dict = {}

def _new_coin_last_cap_event() -> dict:
    try:
        ev = globals().get('_NEW_COIN_LAST_CAP_EVENT')
        return dict(ev or {}) if isinstance(ev, dict) else {}
    except Exception:
        return {}

def _new_coin_last_cap_text(ev: dict | None = None) -> str:
    try:
        obj = dict(ev or _new_coin_last_cap_event() or {})
        coin = str(obj.get('coin') or '-')
        source = str(obj.get('source') or '-')
        reason = str(obj.get('reason') or '-')
        mode = str(obj.get('mode') or '-')
        raw_u = obj.get('raw_u')
        final_u = obj.get('final_u')
        cap_u = obj.get('cap_u')
        cur_u = obj.get('cur_u')
        remain_u = obj.get('remain_u')
        tsv = float(obj.get('ts') or 0.0)
        ttxt = '-'
        if tsv > 0:
            try:
                ttxt = time.strftime('%H:%M:%S', time.localtime(tsv))
            except Exception:
                ttxt = str(int(tsv))
        parts = [f'最近新币限额命中：{coin}', f'类型={reason}', f'动作={mode}', f'来源={source}']
        if raw_u is not None:
            try:
                parts.append(f'原始={float(raw_u):.4f}U')
            except Exception:
                parts.append(f'原始={raw_u}')
        if final_u is not None:
            try:
                parts.append(f'最终={float(final_u):.4f}U')
            except Exception:
                parts.append(f'最终={final_u}')
        if cur_u is not None:
            try:
                parts.append(f'当前总仓={float(cur_u):.4f}U')
            except Exception:
                parts.append(f'当前总仓={cur_u}')
        if remain_u is not None:
            try:
                parts.append(f'剩余额度={float(remain_u):.4f}U')
            except Exception:
                parts.append(f'剩余额度={remain_u}')
        if cap_u is not None:
            try:
                parts.append(f'上限={float(cap_u):.4f}U')
            except Exception:
                parts.append(f'上限={cap_u}')
        parts.append(f'时间={ttxt}')
        return ' | '.join(parts)
    except Exception:
        return '最近新币限额命中：-'

def _record_new_coin_cap_event(coin: Any, source: str, reason: str, *, mode: str = 'clamp', detail: dict | None = None) -> dict:
    try:
        d = dict(detail or {}) if isinstance(detail, dict) else ({'detail': str(detail)} if detail not in (None, '') else {})
    except Exception:
        d = {}
    ev = {
        'ts': float(time.time()),
        'coin': str(coin or '').upper().strip(),
        'source': str(source or '').strip(),
        'reason': str(reason or '').strip(),
        'mode': str(mode or '').strip(),
        'raw_u': d.get('raw_u'),
        'final_u': d.get('final_u'),
        'cap_u': d.get('cap_u'),
        'cur_u': d.get('cur_u'),
        'remain_u': d.get('remain_u'),
        'detail': d,
    }
    try:
        globals()['_NEW_COIN_LAST_CAP_EVENT'] = dict(ev)
    except Exception:
        pass
    try:
        if str(mode or '').lower() == 'reject' and _coin_pool_head_fail_should_skip(reason):
            _coin_pool_mark_waiting_skip(ev.get('coin'), str(reason), detail=d)
    except Exception:
        pass
    try:
        _observe_emit('新币限额', _new_coin_last_cap_text(ev))
    except Exception:
        pass
    try:
        _pin('NEW_COIN_CAP_HIT', mod='POOL', coin=str(ev.get('coin') or ''), ok=(1 if str(ev.get('mode') or '').lower() == 'clamp' else 0), reason=str(ev.get('reason') or ''), detail={'source': str(ev.get('source') or ''), 'mode': str(ev.get('mode') or ''), **(ev.get('detail') or {})})
    except Exception:
        pass
    return ev

def _coin_pool_compact_text(snapshot: dict | None = None, st: dict | None = None) -> str:
    try:
        state = st if isinstance(st, dict) else _coin_pool_state_load(force=False)
        active = _coin_pool_dedupe(list((state or {}).get('active_holding_coins') or []))
        waiting = _coin_pool_dedupe(list((state or {}).get('waiting_queue') or []))
        blocked = _coin_pool_dedupe(list((state or {}).get('blocked_reopen_after_exit') or []))
        max_slots = int(_coin_pool_max_slots())
        free_slots = max(0, int(max_slots) - int(len(active)))
        head = str(waiting[0] if waiting else '-')
        next_ts = float(globals().get('COIN_POOL_NEXT_REFRESH_TS') or 0.0)
        next_text = '-'
        if next_ts > 0:
            try:
                next_text = time.strftime('%H:%M:%S', time.localtime(next_ts))
            except Exception:
                next_text = str(int(next_ts))
        return f"槽位={len(active)}/{max_slots} 空槽={free_slots} 队首={head} 下刷={next_text} 持仓池={','.join(active[:10]) or '-'} 候补={','.join(waiting[:5]) or '-'} 禁重开={','.join(blocked[:6]) or '-'}"
    except Exception:
        return '槽位=NA'

def _coin_pool_last_blocked_reopen_text(ev: dict | None = None) -> str:
    try:
        obj = dict(ev or _coin_pool_last_blocked_reopen_event() or {})
        coin = str(obj.get('coin') or '-')
        source = str(obj.get('source') or '-')
        reason = str(obj.get('reason') or '-')
        tsv = float(obj.get('ts') or 0.0)
        ttxt = '-'
        if tsv > 0:
            try:
                ttxt = time.strftime('%H:%M:%S', time.localtime(tsv))
            except Exception:
                ttxt = str(int(tsv))
        return f"最近禁重开命中：{coin} | 来源={source} | 原因={reason} | 时间={ttxt}"
    except Exception:
        return '最近禁重开命中：-'

def _coin_pool_record_blocked_reopen_event(coin: str, source: str, reason: str = 'block_reopen_after_exit', detail: dict | None = None) -> dict:
    ev = {
        'ts': float(time.time()),
        'coin': str(coin or '').upper().strip(),
        'source': str(source or '').strip(),
        'reason': str(reason or 'block_reopen_after_exit').strip(),
        'detail': dict(detail or {}) if isinstance(detail, dict) else ({'detail': str(detail)} if detail not in (None, '') else {}),
    }
    try:
        globals()['_COIN_POOL_LAST_BLOCKED_REOPEN_EVENT'] = dict(ev)
    except Exception:
        pass
    try:
        _observe_emit('动态币池', _coin_pool_last_blocked_reopen_text(ev))
    except Exception:
        pass
    try:
        _pin('COIN_POOL_BLOCKED_REOPEN', mod='POOL', coin=str(ev.get('coin') or ''), ok=0, reason=str(ev.get('reason') or ''), detail={'source': str(ev.get('source') or ''), **(ev.get('detail') or {})})
    except Exception:
        pass
    return ev

def _coin_pool_should_gate_b1_req(req: Any) -> bool:
    try:
        mod = str(getattr(req, 'module', '') or '').upper().strip()
        act = str(getattr(req, 'action_type', '') or '').lower().strip()
        if mod != 'B1' or act not in ('open_leg', 'open_pair', 'open_position', 'open'):
            return False
        meta = getattr(req, 'meta', None)
        params = getattr(req, 'params', None)
        reason = ''
        if isinstance(meta, dict):
            reason = str(meta.get('reason') or '').lower().strip()
            if meta.get('from_reopen_task'):
                return False
        if isinstance(params, dict) and (not reason):
            reason = str(params.get('reason') or '').lower().strip()
        if 'reopen_after_force_close_all' in reason:
            return False
        return True
    except Exception:
        return False

def _coin_pool_b1_slot_gate(req: Any, snapshot: dict | None = None) -> tuple[bool, str, dict]:
    detail = {'enabled': bool(_coin_pool_enabled())}
    if not _coin_pool_enabled():
        detail['allow'] = 'dynamic_pool_disabled'
        return True, 'dynamic_pool_disabled', detail
    if not _coin_pool_should_gate_b1_req(req):
        detail['allow'] = 'explicit_reopen_bypass'
        return True, 'explicit_reopen_bypass', detail
    coin = str(getattr(req, 'coin', '') or '').upper().strip()
    base_coins = _coin_pool_locked_base_coins()
    st = _coin_pool_state_scrub(_coin_pool_refresh_runtime_state(snapshot if isinstance(snapshot, dict) else {}, base_coins=base_coins, force=False))
    active = _coin_pool_dedupe(list(st.get('active_holding_coins') or []))
    waiting = _coin_pool_dedupe(list(st.get('waiting_queue') or []))
    effective_waiting, waiting_skip, skipped_waiting = _coin_pool_effective_waiting_queue(st)
    blocked = set(_coin_pool_dedupe(list(st.get('blocked_reopen_after_exit') or [])))
    max_slots = _coin_pool_max_slots()
    detail.update({'coin': coin, 'active_cnt': len(active), 'max_slots': int(max_slots), 'waiting_head': (waiting[0] if waiting else ''), 'effective_waiting_head': (effective_waiting[0] if effective_waiting else ''), 'active_coins': list(active[:20]), 'waiting_queue': list(waiting[:10]), 'waiting_skip_coins': list(skipped_waiting[:10])})
    if coin in active:
        detail['allow'] = 'active_holding_coin'
        return True, 'active_holding_coin', detail
    if coin in blocked:
        detail['final_fail_stage'] = 'POOL_SLOT_GATE'
        detail['final_fail_reason'] = 'block_reopen_after_exit'
        try:
            _coin_pool_record_blocked_reopen_event(coin, source='queue_pool_slot_gate', reason='block_reopen_after_exit', detail=detail)
        except Exception:
            pass
        if _coin_pool_head_fail_should_skip('block_reopen_after_exit'):
            _coin_pool_mark_waiting_skip(coin, 'block_reopen_after_exit', detail=detail)
        return False, 'block_reopen_after_exit', detail
    if _coin_pool_is_dynamic_new_coin(coin):
        _ok_dual, _why_dual, _det_dual = _coin_pool_live_dual_platform_openable(coin, timeout_s=3.0)
        detail['dual_platform_guard'] = _det_dual if isinstance(_det_dual, dict) else {'detail': str(_det_dual)}
        if not _ok_dual:
            detail['final_fail_stage'] = 'POOL_SLOT_GATE'
            detail['final_fail_reason'] = str(_why_dual)
            if _coin_pool_head_fail_should_skip(_why_dual):
                _coin_pool_mark_waiting_skip(coin, str(_why_dual), detail=detail)
            return False, str(_why_dual), detail
    if len(active) >= int(max_slots):
        detail['final_fail_stage'] = 'POOL_SLOT_GATE'
        detail['final_fail_reason'] = 'slot_full_waiting_queue'
        return False, 'slot_full_waiting_queue', detail
    if not waiting:
        if _coin_pool_is_dynamic_new_coin(coin):
            detail['final_fail_stage'] = 'POOL_SLOT_GATE'
            detail['final_fail_reason'] = 'waiting_queue_empty_no_dynamic_candidates'
            return False, 'waiting_queue_empty_no_dynamic_candidates', detail
        detail['allow'] = 'waiting_queue_empty_fallback_allow'
        return True, 'waiting_queue_empty_fallback_allow', detail
    if coin in waiting_skip:
        detail['final_fail_stage'] = 'POOL_SLOT_GATE'
        detail['final_fail_reason'] = 'waiting_head_temporarily_skipped'
        detail['skip_until_ts'] = float((waiting_skip.get(coin) or {}).get('until_ts') or 0.0)
        return False, 'waiting_head_temporarily_skipped', detail
    if not effective_waiting:
        detail['final_fail_stage'] = 'POOL_SLOT_GATE'
        detail['final_fail_reason'] = 'waiting_queue_all_temporarily_skipped'
        return False, 'waiting_queue_all_temporarily_skipped', detail
    if coin == str(effective_waiting[0] or '').upper().strip():
        detail['allow'] = ('waiting_queue_head_after_skip' if skipped_waiting else 'waiting_queue_head')
        return True, str(detail['allow']), detail
    detail['final_fail_stage'] = 'POOL_SLOT_GATE'
    detail['final_fail_reason'] = 'not_queue_head'
    return False, 'not_queue_head', detail

class IndicatorCache:
    def __init__(self, fp: Optional[str] = None):
        self.fp = fp
        self.data: Dict[str, Any] = {"version": 1, "coins": {}}
        self._load()

    def _load(self) -> None:
        if not self.fp:
            return
        try:
            if os.path.exists(self.fp):
                self.data = safe_read_json(self.fp, default={"version": 1, "coins": {}}) or {"version": 1, "coins": {}}
            if "coins" not in self.data:
                self.data["coins"] = {}
        except Exception:
            self.data = {"version": 1, "coins": {}}

    def _save(self) -> None:
        if not self.fp:
            return
        try:
            _atomic_write_json(self.fp, self.data if isinstance(self.data, dict) else {"version": 1, "coins": {}})
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    def get(self, coin: str, now_ts: float) -> Tuple[Optional[float], Optional[float], Optional[float], str]:
        c = str(coin).upper()
        it = (self.data.get("coins") or {}).get(c) or {}
        adx = it.get("adx")
        rsi = it.get("rsi")
        next_refresh_ts = it.get("next_refresh_ts")
        if next_refresh_ts is None:
            return None, None, None, "cache_miss"
        try:
            next_refresh_ts = float(next_refresh_ts)
        except Exception:
            return None, None, None, "cache_bad_ts"

        if now_ts < next_refresh_ts:
            left = int(max(0.0, next_refresh_ts - now_ts))
            if adx is None or rsi is None:
                return (float(adx) if adx is not None else None), (float(rsi) if rsi is not None else None), 0.0, "cache_missing_bypass_throttle"
            return float(adx), float(rsi), next_refresh_ts, f"cache_hit refresh_in={left}s"
        if adx is None or rsi is None:
            return (float(adx) if adx is not None else None), (float(rsi) if rsi is not None else None), next_refresh_ts, "cache_missing_expired"
        return float(adx), float(rsi), next_refresh_ts, "cache_expired"

    def update(self, coin: str, adx: Optional[float], rsi: Optional[float], now_ts: float, next_in_sec: int, reason: str) -> None:
        c = str(coin).upper()
        prev = (self.data.get("coins", {}) or {}).get(c, {}) if isinstance(self.data.get("coins", {}), dict) else {}

        last_good_adx = prev.get("last_good_adx")
        last_good_rsi = prev.get("last_good_rsi")
        if last_good_adx is None:
            last_good_adx = prev.get("adx")
        if last_good_rsi is None:
            last_good_rsi = prev.get("rsi")
        fail_streak = int(prev.get("ind_fail_streak", 0) or 0)

        raw_adx, raw_rsi = adx, rsi
        used_last_good = False

        try:
            max_stale = float(cfg_getf_runtime("IND_MAX_STALE_SEC", 900.0))
        except Exception:
            max_stale = 900.0
        try:
            prev_ts = float(prev.get("ts") or 0.0)
        except Exception:
            prev_ts = 0.0
        is_stale = bool(prev_ts > 0.0 and (float(now_ts) - prev_ts) > max_stale)
        if is_stale:
            last_good_adx = None
            last_good_rsi = None

        if adx is None and last_good_adx is not None:
            adx = float(last_good_adx)
            used_last_good = True
        if rsi is None and last_good_rsi is not None:
            rsi = float(last_good_rsi)
            used_last_good = True

        still_bad = (raw_adx is None) or (raw_rsi is None)

        if still_bad:
            fail_streak += 1
        else:
            fail_streak = 0
            if adx is not None and rsi is not None:
                last_good_adx = float(adx)
                last_good_rsi = float(rsi)

        next_in_sec_eff = int(next_in_sec)
        try:
            if still_bad and (not used_last_good) and (last_good_adx is None or last_good_rsi is None):
                next_in_sec_eff = int(min(3600, max(600, 600 * int(fail_streak))))
        except Exception:
            next_in_sec_eff = int(next_in_sec)
        rec = {
            "adx": adx,
            "rsi": rsi,
            "raw_adx": raw_adx,
            "raw_rsi": raw_rsi,
            "used_last_good": bool(used_last_good),
            "ind_fail_streak": int(fail_streak),
            "last_good_adx": last_good_adx,
            "last_good_rsi": last_good_rsi,
            "fetch_ts": float(now_ts),
            "val_ts": float(prev_ts) if (bool(used_last_good) and bool(still_bad) and float(prev_ts) > 0.0) else float(now_ts),
            "ts": float(now_ts),
            "next_refresh_ts": float(now_ts) + float(next_in_sec_eff),
            "next_in_sec_eff": int(next_in_sec_eff),
            "reason": reason,
        }
        self.data.setdefault("coins", {})[c] = rec
        self._save()

        try:
            if int(fail_streak) >= int(cfg_getf_runtime("IND_FAIL_LEGACY_FIX_ONLY_THRESHOLD", 5.0)):
                try:
                        _legacy_only_set(True, reason=f"IndicatorFailStreak coin={c} streak={fail_streak} reason={reason}")
                except Exception as _e:
                    _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

                try:
                    safe_log(lambda: f"[IND][WARN] 指标连续失败 coin={c} streak={fail_streak} reason={reason} -> 进入 LEGACY_FIX_ONLY（仅修复态）")
                except Exception as _e:
                    _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

                try:
                    self.data.setdefault("coins", {}).setdefault(c, {})["ind_fail_streak"] = int(min(int(fail_streak), 99))
                    self._save()
                except Exception as _e:
                    _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

IND_CACHE: Optional[IndicatorCache] = None
IND_NEXT_REFRESH_TS: float = 0.0
IND_IND_SWITCH_LAST_TS_BY_COIN: Dict[str, float] = {}
IND_ROTATE_CURSOR: int = 0
_PLATFORM_HUMAN_VERIFY_STATE: Dict[str, Dict[str, Any]] = {}

_EXEC_COIN_COOLDOWN_UNTIL: Dict[str, float] = {}

def _exec_coin_cooldown_set(coin: str, sec: float = 120.0, *, reason: str = '') -> None:
    try:
        c = str(coin or '').upper().strip()
        if not c:
            return
        until = float(time.time()) + float(max(1.0, sec))
        cur = float(_EXEC_COIN_COOLDOWN_UNTIL.get(c, 0.0) or 0.0)
        if until > cur:
            _EXEC_COIN_COOLDOWN_UNTIL[c] = until
        try:
            _pin("COIN_COOLDOWN_SET", mod="EXEC", coin=c, ok=1, reason=str(reason or '')[:120], stage="COOLDOWN", trace="")
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_437', _e)
            pass
    except Exception:
        return

def _exec_coin_cooldown_left_sec(coin: str) -> float:
    try:
        c = str(coin or '').upper().strip()
        if not c:
            return 0.0
        return max(0.0, float(_EXEC_COIN_COOLDOWN_UNTIL.get(c, 0.0) or 0.0) - float(time.time()))
    except Exception:
        return 0.0

def _exec_ctx_bypass_coin_cooldown(ctx: str = '', allow_goto: bool = True) -> bool:
    """真实执行链放开切币冷却；扫描/指标链继续受限。

    口径收死：只有明确白名单执行上下文才允许绕过；空 ctx / 未识别 ctx 一律不放权。
    人话：真实下单可以强制切币，扫描和来路不明的调用不能顺手偷过冷却。
    """
    try:
        s = str(ctx or '').upper().strip()
    except Exception:
        s = ''
    if not s:
        return False
    if s in {'IND_ADX_RSI', 'VAR_IND_GOTO', 'SCAN', 'IND', 'RSI', 'ADX'}:
        return False
    if any(_kw in s for _kw in ('IND_', 'SCAN', 'RSI', 'ADX', 'CACHE', 'REFRESH_PROFILE')):
        return False
    if s in {
        'OPEN_POSITION', 'VAR_OPEN_POSITION', 'EXEC_OPEN', 'VAR_EXEC_OPEN',
        'CLOSE_POSITION', 'VAR_CLOSE_ALL', 'VAR_CLOSE_ALL_RETRY', 'EXEC_CLOSE',
        'INCREASE_POSITION', 'EXEC_INCREASE', 'DECREASE_POSITION', 'EXEC_DECREASE',
        'M10_STEP3_RETRY', 'VAR_GOTO_EXEC', 'UI_EXEC',
    }:
        return True
    return False

def _exec_ctx_force_goto(ctx: str = '', allow_goto: bool = True, *, exec_privilege: bool = False, privilege_reason: str = '') -> bool:
    """真实执行/修复链强制放开 goto 兜底；扫描/指标链绝不放权。"""
    try:
        s = str(ctx or '').upper().strip()
    except Exception:
        s = ''
    try:
        pr = str(privilege_reason or '').strip().lower()
    except Exception:
        pr = ''
    if bool(allow_goto):
        return True
    if _exec_ctx_bypass_coin_cooldown(s, allow_goto=True):
        return True
    if bool(exec_privilege) and pr in {'m10_step1_retry', 'm10_step2_retry', 'm10_step3_retry', 'm10_reopen_reopen', 'm10_reopen_force_submit', 'exec_trade_submit'}:
        return True
    return False

def _runtime_recovering_gate(req: Any | None = None, *, stage: str = 'QUEUE_SUBMIT', coin: str = '', plat: str = '', act: str = '', allow_protective: bool = True) -> tuple[bool, str, dict]:
    """恢复态总闸：单链 UI 修复启用时，不再让旧 recovering 标记阻断主链。"""
    if bool(globals().get('UI_DISABLE_RUNTIME_RECOVERING_GATE', False)):
        return True, 'single_chain_runtime_gate_disabled', {'recovering': False, 'stage': str(stage or ''), 'platform': str(plat or ''), 'coin': str(coin or ''), 'action_type': str(act or ''), 'gate_disabled': True}
    try:
        req_coin = str(coin or getattr(req, 'coin', '') or (req.get('coin') if isinstance(req, dict) else '') or '').upper().strip()
    except Exception:
        req_coin = str(coin or '').upper().strip()
    try:
        req_plat = str(plat or getattr(req, 'platform', '') or (req.get('platform') if isinstance(req, dict) else '') or '').upper().strip()
    except Exception:
        req_plat = str(plat or '').upper().strip()
    try:
        req_act = str(act or getattr(req, 'action_type', '') or (req.get('action_type') if isinstance(req, dict) else '') or '').lower().strip()
    except Exception:
        req_act = str(act or '').lower().strip()
    try:
        recovering = bool(_pw_runtime_is_recovering(req_plat or plat))
    except Exception:
        recovering = False
    if not recovering:
        return True, 'ok', {'recovering': False, 'stage': str(stage or ''), 'platform': req_plat, 'coin': req_coin, 'action_type': req_act}
    protective = bool(allow_protective and _req_is_protective_or_risk_reducing(req)) if req is not None else False
    detail = {'recovering': True, 'stage': str(stage or ''), 'coin': req_coin, 'platform': req_plat, 'action_type': req_act, 'protective': bool(protective)}
    if protective:
        detail['allow'] = 'protective_bypass'
        return True, 'runtime_recovering_protective_bypass', detail
    detail['final_fail_stage'] = 'UI_RUNTIME_GATE'
    detail['final_fail_reason'] = 'runtime_recovering'
    return False, 'runtime_recovering', detail

