def _http_json_any(url: str, timeout_s: float = 8.0) -> Any:
    try:
        import urllib.request
        with urllib.request.urlopen(url, timeout=float(timeout_s)) as r:
            raw = r.read().decode("utf-8", errors="ignore")
            return json.loads(raw)
    except Exception:
        return None

def _ind_public_kline_symbol(coin: str) -> str:
    c = str(coin or '').upper().strip()
    if not c:
        return ''
    try:
        st = _coin_pool_state_load(force=False)
    except Exception:
        st = {}
    rows = []
    try:
        rows.extend([dict(x) for x in list((st.get('ranked_openable_universe') or [])) if isinstance(x, dict)])
    except Exception:
        pass
    try:
        diag = dict((st.get('last_refresh_diag') or {})) if isinstance(st.get('last_refresh_diag'), dict) else {}
        rows.extend([dict(x) for x in list((diag.get('selection_detail_rows') or [])) if isinstance(x, dict)])
        rows.extend([dict(x) for x in list((diag.get('last_selection_detail_rows') or [])) if isinstance(x, dict)])
    except Exception:
        pass
    for row in rows:
        try:
            if str(row.get('coin') or '').upper().strip() == c:
                sym = str(row.get('symbol') or row.get('rep_symbol') or '').upper().strip()
                if sym:
                    return sym
        except Exception:
            continue
    try:
        st = _coin_pool_state_load(force=False)
        sym = str(((st.get('binance_symbol_map') or {}) if isinstance(st, dict) else {}).get(c) or '').upper().strip()
        if sym:
            return sym
    except Exception:
        pass
    sym = str((_IND_PUBLIC_KLINE_SYMBOL_MAP or {}).get(c) or '').upper().strip()
    if sym:
        return sym
    for root in _spot_public_candidate_roots(c):
        if root:
            return f'{root}USDT'
    return ''


def _ind_public_fetch_klines_detail(coin: str, *, interval: str = '1h', limit: int = 200, timeout_sec: float = 8.0) -> tuple[Optional[list], str, dict]:
    c = str(coin or '').upper().strip()
    if not c:
        return None, 'public_bad_coin', {}
    det = dict(_spot_public_fetch_metric_multi(c, interval=str(interval or '1h'), timeout_s=float(timeout_sec or 8.0), kline_limit=int(max(80, limit or 200))) or {})
    rows = list(det.get('rows') or [])
    if not rows:
        return None, str(det.get('reason') or 'public_fetch_fail'), {
            'source': str(det.get('source') or ''),
            'source_kind': 'public_kline_live_1h',
            'symbol': str(det.get('symbol') or _ind_public_kline_symbol(c) or ''),
            'tried_symbols': str(det.get('tried_symbols') or ''),
            'interval': str(interval or '1h'),
        }
    if int(limit or 200) > 0 and len(rows) > int(limit):
        rows = rows[-int(limit):]
    meta = {
        'source': str(det.get('source') or ''),
        'source_kind': 'public_kline_live_1h',
        'symbol': str(det.get('symbol') or _ind_public_kline_symbol(c) or ''),
        'tried_symbols': str(det.get('tried_symbols') or ''),
        'source_order': str(det.get('source_order') or ''),
        'interval': str(interval or '1h'),
        'quote_volume_24h': float(det.get('quote_volume_24h') or 0.0),
        'ticker_change_24h_pct': (float(det.get('ticker_change_24h_pct') or 0.0) / 100.0 if det.get('ticker_change_24h_pct') not in (None, '') else None),
    }
    return rows, f"{str(det.get('source') or 'public_spot')} ok symbol={str(meta.get('symbol') or '')} tried={str(meta.get('tried_symbols') or '')}", meta


def _ind_public_fetch_klines(coin: str, *, interval: str = '1h', limit: int = 200, timeout_sec: float = 8.0) -> Tuple[Optional[list], str]:
    rows, reason, _meta = _ind_public_fetch_klines_detail(coin, interval=interval, limit=limit, timeout_sec=timeout_sec)
    return rows, reason

_COIN_24H_VOL_PCT_CACHE: Dict[str, Dict[str, Any]] = {}

def _coin_24h_volatility_pct(coin: Any, *, max_age_sec: float = 900.0) -> tuple[float | None, dict]:
    coin_u = str(coin or '').upper().strip()
    det = {'coin': coin_u, 'src': 'missing'}
    if not coin_u:
        det['reason'] = 'coin_empty'
        return None, det
    try:
        ov = globals().get('_COIN_24H_VOL_PCT_OVERRIDE') or {}
        if isinstance(ov, dict) and coin_u in ov:
            vv = float(ov.get(coin_u) or 0.0)
            if vv > 1.0:
                vv = vv / 100.0
            if vv > 0.0:
                det.update({'src': 'override', 'vol24h_pct': float(vv), 'age_sec': 0.0})
                return float(vv), det
    except Exception:
        pass
    try:
        cache = globals().setdefault('_COIN_24H_VOL_PCT_CACHE', {})
        row = dict(cache.get(coin_u) or {}) if isinstance(cache, dict) else {}
        age = max(0.0, float(time.time()) - float(row.get('ts') or 0.0)) if row.get('ts') else 1e12
        vv = float(row.get('vol24h_pct') or 0.0)
        if vv > 0.0 and age <= float(max_age_sec):
            det.update({'src': str(row.get('src') or 'cache'), 'vol24h_pct': float(vv), 'age_sec': float(age), 'symbol': str(row.get('symbol') or '')})
            return float(vv), det
    except Exception:
        pass
    try:
        st = _coin_pool_state_load(force=False)
    except Exception:
        st = {}
    try:
        st_ts = float((st or {}).get('ts') or 0.0)
        st_age = max(0.0, float(time.time()) - float(st_ts)) if st_ts > 0 else 1e12
    except Exception:
        st_age = 1e12
    if isinstance(st, dict) and st_age <= max(float(max_age_sec), 1800.0):
        rows_state = []
        try:
            rows_state.extend([dict(x) for x in list((st.get('ranked_openable_universe') or [])) if isinstance(x, dict)])
        except Exception:
            pass
        try:
            diag = dict((st.get('last_refresh_diag') or {})) if isinstance(st.get('last_refresh_diag'), dict) else {}
            rows_state.extend([dict(x) for x in list((diag.get('selection_detail_rows') or [])) if isinstance(x, dict)])
            rows_state.extend([dict(x) for x in list((diag.get('last_selection_detail_rows') or [])) if isinstance(x, dict)])
        except Exception:
            pass
        for row in rows_state:
            try:
                rc = str(row.get('coin') or '').upper().strip()
                if rc != coin_u:
                    continue
                vv = row.get('volatility_24h_pct')
                if vv is None:
                    vv = row.get('vol24h_pct')
                if vv is None:
                    vv = row.get('volatility_pct')
                vv = float(vv or 0.0) / 100.0
                if vv > 0.0:
                    sym = str(row.get('symbol') or row.get('rep_symbol') or '')
                    try:
                        globals().setdefault('_COIN_24H_VOL_PCT_CACHE', {})[coin_u] = {'ts': float(time.time()), 'vol24h_pct': float(vv), 'src': str(row.get('source') or 'state_ranked'), 'symbol': sym}
                    except Exception:
                        pass
                    det.update({'src': str(row.get('source') or 'state_ranked'), 'vol24h_pct': float(vv), 'age_sec': float(st_age), 'symbol': sym})
                    return float(vv), det
            except Exception:
                continue
    try:
        rows_live, why, meta_live = _ind_public_fetch_klines_detail(coin_u, interval='1h', limit=30, timeout_sec=4.5)
    except Exception as _e:
        rows_live, why, meta_live = None, f'public_fetch_exc:{type(_e).__name__}', {}
    if isinstance(rows_live, list) and rows_live:
        try:
            calc = _coin_pool_calc_binance_24h_volatility_from_1h_klines(rows_live)
        except Exception as _e:
            calc = {'ok': False, 'reason': f'calc_exc:{type(_e).__name__}'}
        if bool((calc or {}).get('ok')):
            vv = float(calc.get('volatility_pct') or 0.0) / 100.0
            sym = str((meta_live or {}).get('symbol') or _ind_public_kline_symbol(coin_u) or '')
            if vv > 0.0:
                try:
                    globals().setdefault('_COIN_24H_VOL_PCT_CACHE', {})[coin_u] = {
                        'ts': float(time.time()),
                        'vol24h_pct': float(vv),
                        'src': str((meta_live or {}).get('source') or 'public_spot_live_1h'),
                        'symbol': sym,
                        'closed_1h_bars': int((calc or {}).get('closed_1h_bars') or 0),
                    }
                except Exception:
                    pass
                det.update({
                    'src': str((meta_live or {}).get('source') or 'public_spot_live_1h'),
                    'vol24h_pct': float(vv),
                    'symbol': sym,
                    'closed_1h_bars': int((calc or {}).get('closed_1h_bars') or 0),
                    'hourly_range_avg_pct': float((calc or {}).get('hourly_range_avg_pct') or 0.0),
                    'quote_volume_1h_24_sum': float((calc or {}).get('quote_volume_1h_24_sum') or 0.0),
                    'fetch_reason': str(why or ''),
                })
                return float(vv), det
        det.update({'src': str((meta_live or {}).get('source') or 'public_spot_live_1h') + '_failed', 'reason': str((calc or {}).get('reason') or why or 'calc_fail')})
        return None, det
    det.update({'src': 'public_spot_missing', 'reason': str(why or 'rows_missing')})
    return None, det


def _ind_fetch_adx_rsi_public(coin: str, *, now_ts_val: float | None = None, interval: str = '1h', limit: int = 200) -> Tuple[Optional[float], Optional[float], Optional[float], str, dict]:
    c = str(coin or '').upper().strip()
    if not c:
        return None, None, None, 'public_bad_coin', {}
    if not _ind_public_kline_enabled():
        return None, None, None, 'public_disabled', {}
    try:
        timeout_sec = float(cfg_getf_runtime('IND_PUBLIC_KLINE_TIMEOUT_SEC', 8.0) or 8.0)
    except Exception:
        timeout_sec = 8.0
    rows, rsn0, fetch_meta = _ind_public_fetch_klines_detail(c, interval=str(interval or '1h'), limit=int(limit or 200), timeout_sec=timeout_sec)
    try:
        safe_log(lambda: f"[{now_ts()}] [IND_PUBLIC_FETCH] coin={c} interval={str(interval or '1h')} ok={1 if isinstance(rows, list) and bool(rows) else 0} reason={str(rsn0 or '')[:220]}")
        safe_log(lambda: f"[{now_ts()}] [INDV2] stage=PUBLIC_FETCH coin={c} tf={str(interval or '1h')} ok={1 if isinstance(rows, list) and bool(rows) else 0} source=public_kline_live_1h fallback=0 reason={str(rsn0 or '')[:220]}")
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_438', _e)
        pass
    if not isinstance(rows, list) or not rows:
        return None, None, None, str(rsn0 or 'public_fetch_fail'), dict(fetch_meta or {})
    try:
        calc_rows = list(rows)
        highs = [float(r[2]) for r in calc_rows]
        lows = [float(r[3]) for r in calc_rows]
        closes = [float(r[4]) for r in calc_rows]
        open_ts = float(calc_rows[-1][0]) / 1000.0 if calc_rows else 0.0
        close_ts = float(calc_rows[-1][6]) / 1000.0 if calc_rows and len(calc_rows[-1]) > 6 else 0.0
    except Exception as _e:
        return None, None, None, f'public_parse_fail:{type(_e).__name__}', dict(fetch_meta or {})
    rsi = _ind_calc_rsi_wilder(closes, period=14)
    adx = _ind_calc_adx_wilder(highs, lows, closes, period=14)
    if rsi is None:
        return None, None, None, f'public_calc_fail adx={adx} rsi={rsi} {rsn0}', {'rows': len(rows or []), 'calc_rows': len(calc_rows or []), **dict(fetch_meta or {})}
    adx_fallback_used = False
    if adx is None:
        adx_fallback_used = True
        try:
            _cache_item = ((_ind_cache_latest_dict() or {}).get(c) or {}) if IND_CACHE is not None else {}
        except Exception:
            _cache_item = {}
        try:
            _cache_adx = _cache_item.get('adx')
            adx = float(_cache_adx) if _cache_adx is not None else 0.0
        except Exception:
            adx = 0.0
    tsv = float(now_ts_val if now_ts_val is not None else time.time())
    source_used = str((fetch_meta or {}).get('source') or 'public_spot_live_1h')
    meta = {
        'source': source_used,
        'source_kind': 'public_kline_live_1h',
        'symbol': str((fetch_meta or {}).get('symbol') or _ind_public_kline_symbol(c) or ''),
        'tried_symbols': str((fetch_meta or {}).get('tried_symbols') or ''),
        'interval': str(interval or '1h'),
        'rows': int(len(rows or [])),
        'calc_rows': int(len(calc_rows or [])),
        'bar_open_ts': float(open_ts or 0.0),
        'bar_close_ts': float(close_ts or 0.0),
        'used_live_bar': True,
        'calc_mode': ('current_bar_included_adx_cache_or_zero' if adx_fallback_used else 'current_bar_included'),
        'adx_fallback_used': int(bool(adx_fallback_used)),
    }
    return float(adx), float(rsi), float(tsv), f'public_kline_live_ok {rsn0}', meta

