def _coin_total_notional(snapshot: dict, coin: str) -> float:
    try:
        c = str(coin or '').upper().strip()
        if not c:
            return 0.0
        e = _get_position(snapshot or {}, c, "EXT") or {}
        v = _get_position(snapshot or {}, c, "VAR") or {}
        return float(_pos_notional(e) + _pos_notional(v))
    except Exception:
        return 0.0

def _max_coin_total_notional(snapshot: dict) -> float:
    try:
        mx = 0.0
        poss = (snapshot or {}).get("positions") or {}
        for pp in ("EXT", "VAR"):
            dd = (poss.get(pp) or {}) if isinstance(poss, dict) else {}
            if not isinstance(dd, dict):
                continue
            for cc in dd.keys():
                try:
                    ct = float(_coin_total_notional(snapshot, str(cc)))
                    if ct > mx:
                        mx = ct
                except Exception:
                    continue
        return float(mx)
    except Exception:
        return 0.0

def _multiplier_tick_and_get_factor(snapshot: dict, coin: str) -> float:
    """返回该 coin 当前应使用的倍增因子（1.0 或 2.0）。"""
    try:
        if int(MULTIPLIER_ENABLED or 0) <= 0:
            return 1.0
        c = str(coin or '').upper().strip()
        if not c:
            return 1.0
        if c in ('BTC', 'ETH'):
            return float(MULTIPLIER_FACTOR)
        mx = float(_max_coin_total_notional(snapshot or {}))
        if mx <= 0:
            return 1.0
        tot = float(_coin_total_notional(snapshot or {}, c))
        thr = float(mx) * float(MULTIPLIER_RATIO)
        if tot < thr:
            return float(MULTIPLIER_FACTOR)
        return 1.0
    except Exception:
        return 1.0

def _multiplier_reason_unified(snapshot: dict, coin: str) -> str:
    try:
        c = str(coin or '').upper().strip()
        if c in ('BTC', 'ETH'):
            return 'coin_whitelist_btc_eth'
        mx = float(_max_coin_total_notional(snapshot or {}))
        tot = float(_coin_total_notional(snapshot or {}, c))
        return f'low_notional(<max*{float(MULTIPLIER_RATIO):.2f}) current={tot:.2f} max={mx:.2f}'
    except Exception:
        return 'unknown'

def _is_reduce_action(act: str) -> bool:
    a = str(act or "").lower().strip()
    if not a:
        return False
    if a in ("decrease", "close", "close_pair", "close_all", "close_one_leg", "reduce", "tp", "take_profit"):
        return True
    return any(k in a for k in ("reduce", "decrease", "close", "flatten", "tp", "take_profit", "hard_tp", "hardtp", "stop_profit"))

def _ind_force_fetch_one_coin(coin: str, timeout_sec: float = 25.0) -> Tuple[Optional[float], Optional[float], Optional[float], Optional[float], str]:
    """主动获取某币 RSI/ADX：优先走公共K线自算；失败后再走原 UI 切币兜底，并写入 IND_CACHE。

    返回 (adx, rsi, ts, age_sec, reason)。若失败则 adx/rsi 为 None（调用方应拒绝交易）。
    """
    now = float(time.time())
    c = str(coin or '').upper().strip()
    if not c:
        return None, None, None, None, "bad_coin"
    if IND_CACHE is None:
        return None, None, None, None, "no_ind_cache"

    public_fail_reason = ""
    if _ind_public_kline_enabled():
        try:
            adx_pk, rsi_pk, ts_pk, rsn_pk, meta_pk = _ind_public_refresh_and_cache(c, now_ts_val=now)
            if adx_pk is not None and rsi_pk is not None:
                try:
                    age_pk = max(0.0, float(time.time()) - float(ts_pk or now))
                except Exception:
                    age_pk = 0.0
                try:
                    safe_log(lambda: f"[{now_ts()}] [IND_FORCE][PUBLIC] coin={c} adx={adx_pk} rsi={rsi_pk} reason={rsn_pk} meta={meta_pk}")
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_455', _e)
                    pass
                return float(adx_pk), float(rsi_pk), float(ts_pk or now), float(age_pk), f"force_public:{rsn_pk}"
            public_fail_reason = str(rsn_pk or 'public_refresh_fail')
        except Exception as _e:
            public_fail_reason = f"public_force_exc:{type(_e).__name__}"

    pg = globals().get("IND_FORCE_PAGE")
    if pg is None:
        return None, None, None, None, (f"{public_fail_reason}|no_force_page" if public_fail_reason else "no_force_page")
    try:
        _pw_require_page(pg, "IND_FORCE")
    except Exception as _e:
        try:
            msg = str(_e)
        except Exception:
            msg = ""
        if ("Event loop is closed" in msg) or _pw_msg_is_closed(msg):
            try:
                globals()["IND_FORCE_PAGE"] = None
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_456', _e)
                pass
            try:
                _pw_set_alive(False)
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_457', _e)
                pass
            try:
                _pin(mod="SYS", coin="-", stage="PW_EVENT_LOOP_CLOSED", ok=0, reason="Event loop is closed / page dead; set PW_ALIVE=False")
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_458', _e)
                pass
            _rsn = "force_page_dead_or_event_loop_closed"
            return None, None, None, None, (f"{public_fail_reason}|{_rsn}" if public_fail_reason else _rsn)
        try:
            globals()["IND_FORCE_PAGE"] = None
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_459', _e)
            pass
        _rsn = f"force_page_unusable:{type(_e).__name__}"
        return None, None, None, None, (f"{public_fail_reason}|{_rsn}" if public_fail_reason else _rsn)
    try:
        ok_lock = IND_FORCE_LOCK.acquire(timeout=max(1.0, float(timeout_sec)))
    except Exception:
        ok_lock = False
    if not ok_lock:
        _rsn = "force_lock_timeout"
        return None, None, None, None, (f"{public_fail_reason}|{_rsn}" if public_fail_reason else _rsn)
    try:
        try:
            last_sw = float(IND_IND_SWITCH_LAST_TS_BY_COIN.get(c, 0.0) or 0.0)
            if last_sw > 0 and (now - last_sw) < 3600.0:
                safe_log(lambda: f"[{now_ts()}] [IND_FORCE] coin={c} note=recent_switch age_sec={int(now-last_sw)}")
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_460', _e)
            pass
        try:
            _pw_front(pg, f"ind_force.front coin={c}")
            try:
                _pw_call(f"ind_force.click_body coin={c}", pg.click, "body", timeout=2500)
            except _UiDeadError:
                raise
            except Exception as _e:
                _log_exc_level(mod="IND", stage="IND_FORCE_BODY_CLICK_FAIL", level="B", e=_e, coin=c, plat="VAR", act="focus")
        except _UiDeadError:
            raise
        except Exception as _e:
            _log_exc_level(mod="IND", stage="IND_FORCE_FRONT_FAIL", level="B", e=_e, coin=c, plat="VAR", act="focus")

        try:
            settle = float(rand_delay(2.0, 6.0, seed=f"IND_FORCE:{c}:{int(now)}"))
        except Exception:
            settle = 3.0

        safe_log(lambda: f"[{now_ts()}] [IND_FORCE][UI_FALLBACK] coin={c} action=fetch begin public_fail={public_fail_reason}")
        adx, rsi, rsn = tv_read_adx_rsi_1h(pg, c, settle_s=settle)
        try:
            next_in = int(cfg_getf_runtime("IND_FORCE_NEXT_IN_SEC", 600.0))
        except Exception:
            next_in = 3600
        try:
            if IND_CACHE is not None:
                _ui_now = float(time.time())
                IND_CACHE.update(c, adx, rsi, _ui_now, next_in_sec=next_in, reason=f"force_ui_fallback:{rsn}")
                _ind_cache_attach_meta(c,
                    source='ui_fallback_var_tv_1h', source_kind='ui_fallback_var_tv_1h',
                    source_symbol=c, source_interval='1h', calc_ts=_ui_now, bar_open_ts=0.0, bar_close_ts=0.0,
                    ui_fallback_used=1, ui_fallback_reason=str(public_fail_reason or rsn or ''), used_live_bar=0, calc_mode='ui_legend_fallback', next_refresh_in_sec=int(next_in))
                _ind_cache_clear_display_invalid(c)
                try:
                    safe_log(lambda: f"[{now_ts()}] [IND_UI_FALLBACK] coin={c} ok=1 source=ui_fallback_var_tv_1h adx={float(adx):.4f} rsi={float(rsi):.4f} calc_ts={float(_ui_now):.3f} next_in={int(next_in)} reason={str(public_fail_reason or rsn or '')[:220]}")
                    safe_log(lambda: f"[{now_ts()}] [INDV2] stage=UI_FALLBACK coin={c} tf=1h ok=1 source=ui_fallback_var_tv_1h fallback=1 adx={float(adx):.4f} rsi={float(rsi):.4f} calc_ts={float(_ui_now):.3f} bar_close_ts=0.000 next_in={int(next_in)} reason={str(public_fail_reason or rsn or '')[:220]}")
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_461', _e)
                    pass
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

        try:
            ind_switch_mark_per_coin(c, float(time.time()))
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_462', _e)
            pass
        adx2, rsi2, ts2, age2, rsn2 = _ind_get_fresh_from_cache(c, float(time.time()))
        safe_log(lambda: f"[{now_ts()}] [IND_FORCE][UI_FALLBACK] coin={c} action=fetch end adx={adx2} rsi={rsi2} age_sec={age2} reason={rsn2}")
        rsn_final = f"force_ui_fallback:{rsn2}"
        if public_fail_reason:
            rsn_final = f"{rsn_final}|public_fail={public_fail_reason}"
        return adx2, rsi2, ts2, age2, rsn_final
    finally:
        try:
            IND_FORCE_LOCK.release()
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_463', _e)
            pass
def _ind_require_adx_rsi(coin: str, now_ts_sec: float, ttl_sec: Optional[float] = None, allow_force: bool = True) -> Tuple[float, float, float, float, str]:
    """模块“需要”指标：不允许 RSI/ADX 为 None。

    - 先从缓存按严格新鲜度读取；
    - 若缺失/过期且 allow_force=True，则主动强制读取一次；
    - 若仍失败，抛出 ValueError（调用方应 reject）。
    """
    adx, rsi, ts0, age0, rsn0 = _ind_get_fresh_from_cache(coin, now_ts_sec, ttl_sec=ttl_sec)
    if adx is not None and rsi is not None:
        return float(adx), float(rsi), float(ts0) if ts0 is not None else float(now_ts_sec), float(age0) if age0 is not None else 0.0, str(rsn0)
    if allow_force:
        adx, rsi, ts0, age0, rsn0 = _ind_force_fetch_one_coin(coin)
        if adx is not None and rsi is not None:
            return float(adx), float(rsi), float(ts0) if ts0 is not None else float(time.time()), float(age0) if age0 is not None else 0.0, str(rsn0)
    try:
        lgs = globals().get("LAST_GOOD_SNAPSHOT") or {}
        inds = (lgs.get("indicators") or {}) if isinstance(lgs, dict) else {}
        c0 = str(coin or "").upper().strip()
        d0 = inds.get(c0, {}) if isinstance(inds, dict) else {}
        if isinstance(d0, dict):
            adx2 = d0.get("adx")
            rsi2 = d0.get("rsi")
            ts2 = d0.get("ts") or d0.get("ind_ts") or None
            if adx2 is not None and rsi2 is not None:
                try:
                    nowv = float(now_ts_sec)
                except Exception:
                    nowv = float(time.time())
                try:
                    tsv = float(ts2) if ts2 is not None else nowv
                except Exception:
                    tsv = nowv
                agev = float(max(0.0, nowv - tsv))
                try:
                    ttlv = float(ttl_sec) if ttl_sec is not None else float(globals().get('IND_TTL_SEC_DEFAULT') or 3600.0)
                except Exception:
                    ttlv = 3600.0
                if agev <= ttlv:
                    return float(adx2), float(rsi2), float(tsv), float(agev), f"last_good_snapshot_fallback({str(rsn0)})"
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_464', _e)
        pass
    raise ValueError(f"indicator_required_missing coin={coin} reason={rsn0}")

def _ind_get_fresh_from_cache(coin: str, now_ts: float, ttl_sec: float | None = None) -> tuple[float | None, float | None, float | None, float | None, str]:
    """严格从 IND_CACHE 读取 (adx, rsi, ts, age_sec, reason)。

    - 若缓存缺失 / 解析失败 / 过期（age > ttl_sec），返回 adx/rsi 为 None（视为不可用）。
    - ttl_sec 默认取 IND_TTL_SEC_DEFAULT（若不存在则 3600）。
    """
    try:
        c = str(coin or '').upper().strip()
        if not c:
            return None, None, None, None, 'bad_coin'
        try:
            ttl = float(ttl_sec) if ttl_sec is not None else float(globals().get('IND_TTL_SEC_DEFAULT') or 3600.0)
        except Exception:
            ttl = 3600.0

        cache = globals().get('IND_CACHE')
        if cache is None:
            return None, None, None, None, 'no_ind_cache'

        it = None
        try:
            it = (getattr(cache, 'data', {}) or {}).get('coins', {}).get(c)
        except Exception:
            it = None
        if not isinstance(it, dict):
            return None, None, None, None, 'cache_miss'

        adx = it.get('adx')
        rsi = it.get('rsi')
        val_ts = it.get('val_ts')
        fetch_ts = it.get('fetch_ts') or it.get('ts') or it.get('ts_sec') or it.get('time') or None
        rsn = str(it.get('reason') or it.get('rsn') or '')

        try:
            tsf = float(val_ts) if val_ts is not None else None
        except Exception:
            tsf = None
        try:
            fetch_tsf = float(fetch_ts) if fetch_ts is not None else None
        except Exception:
            fetch_tsf = None

        if tsf is None:
            return None, None, None, None, 'no_ts'

        try:
            age = float(now_ts) - float(tsf)
        except Exception:
            age = None

        if (age is None) or (age > ttl):
            try:
                return None, None, float(tsf), float(age) if age is not None else None, f'stale(age={age} ttl={ttl} val_ts={tsf} fetch_ts={fetch_tsf}) {rsn}'.strip()
            except Exception:
                return None, None, float(tsf), None, 'stale'

        try:
            _why = rsn or 'ok'
            if bool(it.get('used_last_good')):
                _why = f'last_good:{_why}'
            return (float(adx) if adx is not None else None), (float(rsi) if rsi is not None else None), float(tsf), float(age), _why
        except Exception:
            return None, None, float(tsf), float(age) if age is not None else None, 'cache_bad_value'
    except Exception:
        return None, None, None, None, 'ind_get_exc'

def _ind_refresh_profile_for_coin(coin: str, snapshot: dict | None = None, *, now_ts: float | None = None) -> dict:
    """RSI/ADX 动态刷新档位：按爸爸最新口径，统一到 live_1h 每 10 分钟左右重算。"""
    c = str(coin or '').upper().strip()
    snap = snapshot if isinstance(snapshot, dict) else (globals().get('_IND_REFRESH_PROFILE_SNAPSHOT') if isinstance(globals().get('_IND_REFRESH_PROFILE_SNAPSHOT'), dict) else {})
    nowv = float(now_ts if now_ts is not None else time.time())
    near = 999.0
    rsi = None
    try:
        cache_map = _ind_cache_latest_dict()
        item = (cache_map or {}).get(c) if isinstance(cache_map, dict) else None
        if isinstance(item, dict):
            rsi = item.get('rsi')
            if rsi is not None:
                near = abs(float(rsi) - 50.0)
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_465', _e)
        pass
    has_pos = False
    total_notional = 0.0
    try:
        pos_all = ((snap or {}).get('positions') or {}) if isinstance((snap or {}).get('positions'), dict) else {}
        for _pp in ('EXT','VAR'):
            _pos = ((pos_all.get(_pp) or {}) if isinstance(pos_all.get(_pp), dict) else {}).get(c) or {}
            _nt = abs(float(_pos.get('notional_u') or 0.0))
            total_notional += _nt
            if _nt > 1e-6 or str(_pos.get('side') or '').upper() in ('LONG','SHORT'):
                has_pos = True
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_466', _e)
        pass
    try:
        batch_hot = set(str(x or '').upper().strip() for x in (globals().get('_IND_REFRESH_HOT_COINS') or []))
    except Exception:
        batch_hot = set()
    if c in batch_hot or near <= 0.8:
        bucket, lo, hi = 'hot', 540, 660
    elif has_pos or near <= 1.5 or has_pos:
        bucket, lo, hi = 'warm', 570, 690
    else:
        bucket, lo, hi = 'cold', 600, 720
    return {'bucket': bucket, 'min_sec': int(lo), 'max_sec': int(hi), 'coin': c, 'has_position': bool(has_pos), 'rsi': rsi, 'near_50': (None if near >= 900 else float(near)), 'total_notional': float(total_notional), 'now_ts': float(nowv)}

IND_REFRESH_EVERY_SCAN_COUNT_DEFAULT = 3

def _ind_refresh_every_scan_count() -> int:
    try:
        v = int(cfg_getf_runtime('IND_REFRESH_EVERY_SCAN_COUNT', float(IND_REFRESH_EVERY_SCAN_COUNT_DEFAULT)) or IND_REFRESH_EVERY_SCAN_COUNT_DEFAULT)
    except Exception:
        v = int(IND_REFRESH_EVERY_SCAN_COUNT_DEFAULT)
    return max(1, min(12, int(v)))

def _ind_should_refresh_this_scan(coin: str, snapshot: dict | None = None, *, now_ts_val: float | None = None, cached_adx: Any = None, cached_rsi: Any = None) -> tuple[bool, str]:
    c = str(coin or '').upper().strip()
    nowv = float(now_ts_val if now_ts_val is not None else time.time())
    if not c:
        return True, 'coin_missing'
    if cached_adx is None or cached_rsi is None:
        return True, 'cache_missing'
    try:
        item = (_ind_cache_latest_dict() or {}).get(c) or {}
    except Exception:
        item = {}
    try:
        ts0 = float((item or {}).get('val_ts') or (item or {}).get('ts') or 0.0)
    except Exception:
        ts0 = 0.0
    try:
        next_refresh_ts = float((item or {}).get('next_refresh_ts') or 0.0)
    except Exception:
        next_refresh_ts = 0.0
    try:
        max_stale = float(cfg_getf_runtime('IND_MAX_STALE_SEC', 900.0) or 900.0)
    except Exception:
        max_stale = 900.0
    if ts0 <= 0.0:
        return True, 'cache_ts_missing'
    if (nowv - ts0) > float(max_stale):
        return True, 'cache_stale'
    if next_refresh_ts > 0.0 and nowv < float(next_refresh_ts):
        return False, f'next_refresh_hold left={int(max(0.0, float(next_refresh_ts) - float(nowv)))}s'
    if next_refresh_ts > 0.0:
        return True, 'next_refresh_due'
    return False, 'cache_fresh_hold'

def ind_switch_allow_per_coin(coin: str, now_ts: float, window_sec: int = 3600) -> Tuple[bool, int]:
    """默认关闭指标/UI 切币频率限制；仅显式开启时才走旧节流。
    返回 (allow, left_sec)。
    """
    global IND_IND_SWITCH_NEXT_TS_BY_COIN
    c = str(coin or '').upper()
    if not c:
        return False, 3600
    if not _goto_switch_rate_limit_enabled():
        return True, 0
    try:
        if "IND_IND_SWITCH_NEXT_TS_BY_COIN" not in globals() or not isinstance(globals().get("IND_IND_SWITCH_NEXT_TS_BY_COIN"), dict):
            globals()["IND_IND_SWITCH_NEXT_TS_BY_COIN"] = {}
        IND_IND_SWITCH_NEXT_TS_BY_COIN = globals()["IND_IND_SWITCH_NEXT_TS_BY_COIN"]
    except Exception:
        IND_IND_SWITCH_NEXT_TS_BY_COIN = {}
        globals()["IND_IND_SWITCH_NEXT_TS_BY_COIN"] = IND_IND_SWITCH_NEXT_TS_BY_COIN

    try:
        nxt = float(IND_IND_SWITCH_NEXT_TS_BY_COIN.get(c, 0.0) or 0.0)
    except Exception:
        nxt = 0.0
    if nxt > 0.0 and float(now_ts) < nxt:
        left = int(max(0.0, nxt - float(now_ts)))
        return False, left
    return True, 0

def ind_switch_mark_per_coin(coin: str, now_ts: Optional[float] = None) -> None:
    """默认关闭指标/UI 切币频率限制；仅显式开启时才记录下一次允许时间。"""
    global IND_IND_SWITCH_NEXT_TS_BY_COIN
    c = str(coin or '').upper()
    if not c:
        return
    if not _goto_switch_rate_limit_enabled():
        return
    try:
        if "IND_IND_SWITCH_NEXT_TS_BY_COIN" not in globals() or not isinstance(globals().get("IND_IND_SWITCH_NEXT_TS_BY_COIN"), dict):
            globals()["IND_IND_SWITCH_NEXT_TS_BY_COIN"] = {}
        IND_IND_SWITCH_NEXT_TS_BY_COIN = globals()["IND_IND_SWITCH_NEXT_TS_BY_COIN"]
    except Exception:
        IND_IND_SWITCH_NEXT_TS_BY_COIN = {}
        globals()["IND_IND_SWITCH_NEXT_TS_BY_COIN"] = IND_IND_SWITCH_NEXT_TS_BY_COIN

    try:
        nowv = float(now_ts if now_ts is not None else time.time())
    except Exception:
        nowv = time.time()
    try:
        prof = _ind_refresh_profile_for_coin(c, now_ts=nowv)
        delay = random.randint(int(prof.get('min_sec') or 30), int(prof.get('max_sec') or 45))
    except Exception:
        delay = 45
    try:
        IND_IND_SWITCH_NEXT_TS_BY_COIN[c] = float(nowv + float(delay))
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_467', _e)
        pass
_LAST_EXEC_ERR: dict = {}

def _set_last_exec_err(*, reason: str = "", err: str = "", coin: str = "", plat: str = "", act: str = "") -> None:
    try:
        _LAST_EXEC_ERR.clear()
        _LAST_EXEC_ERR.update({
            "reason": str(reason or ""),
            "err": str(err or ""),
            "coin": str(coin or ""),
            "plat": str(plat or ""),
            "act": str(act or ""),
            "ts": float(time.time()) if 'time' in globals() else 0.0,
        })
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_468', _e)
        pass
def _clear_last_exec_err() -> None:
    try:
        _LAST_EXEC_ERR.clear()
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_469', _e)
        pass

def _peek_last_exec_err(*, coin: str = "", plat: str = "", act: str = "", max_age_sec: float = 8.0) -> dict:
    try:
        det = dict(_LAST_EXEC_ERR) if isinstance(_LAST_EXEC_ERR, dict) else {}
    except Exception:
        det = {}
    if not det:
        return {}
    try:
        ts = float(det.get('ts') or 0.0)
    except Exception:
        ts = 0.0
    try:
        if ts > 0 and (float(time.time()) - float(ts)) > float(max_age_sec or 8.0):
            return {}
    except Exception:
        return {}
    try:
        if coin and str(det.get('coin') or '').upper().strip() not in ('', str(coin or '').upper().strip()):
            return {}
    except Exception:
        return {}
    try:
        if plat and str(det.get('plat') or '').upper().strip() not in ('', str(plat or '').upper().strip()):
            return {}
    except Exception:
        return {}
    try:
        _act_det = str(det.get('act') or '').strip().lower()
        _act_in = str(act or '').strip().lower()
        if _act_in and _act_det not in ('', _act_in, 'open_position'):
            return {}
    except Exception:
        return {}
    return det

DEBUG_EXEC_DIR = os.path.join(str(globals().get("OUT_DIR") or "out"), "debug_exec")
os.makedirs(DEBUG_EXEC_DIR, exist_ok=True)
EXEC_FAIL_REPORT_DIR = os.path.join(str(globals().get("OUT_DIR") or "out"), "exec_fail_reports")
os.makedirs(EXEC_FAIL_REPORT_DIR, exist_ok=True)
_EXEC_FAIL_REPORT_DEDUP: dict[str, float] = {}

def _exec_fail_report_append(*, phase: str = '', module: str = '', coin: str = '', plat: str = '', action: str = '',
                             amount_u: float | None = None, reason: str = '', err: Any = None, req_id: str = '', trace_id: str = '',
                             layer_id: str = '', grid_id: str = '', fail_step: str = '', last_step: str = '',
                             timeout_sec: float | None = None, screenshot: str = '', extra: Any = None) -> dict:
    try:
        ts_now = float(time.time())
    except Exception:
        ts_now = 0.0
    try:
        ts_text = time.strftime('%Y-%m-%d %H:%M:%S', time.localtime(ts_now or time.time()))
    except Exception:
        ts_text = ''
    try:
        amt_f = float(amount_u) if amount_u is not None else None
    except Exception:
        amt_f = None
    rec = {
        'ts': float(ts_now or 0.0),
        'time': str(ts_text or ''),
        'phase': str(phase or ''),
        'module': str(module or ''),
        'coin': str(coin or '').upper(),
        'platform': str(plat or '').upper(),
        'action': str(action or ''),
        'amount_u': amt_f,
        'reason': str(reason or ''),
        'error': (str(err) if err not in (None, '') else ''),
        'req_id': str(req_id or ''),
        'trace_id': str(trace_id or ''),
        'layer_id': str(layer_id or ''),
        'grid_id': str(grid_id or ''),
        'fail_step': str(fail_step or ''),
        'last_step': str(last_step or ''),
        'timeout_sec': (float(timeout_sec) if timeout_sec not in (None, '') else None),
        'screenshot': str(screenshot or ''),
        'extra': extra,
    }
    try:
        dedup_key = '|'.join([
            str(rec.get('time') or '')[:16],
            str(rec.get('module') or ''),
            str(rec.get('coin') or ''),
            str(rec.get('platform') or ''),
            str(rec.get('action') or ''),
            str(rec.get('reason') or '')[:120],
            str(rec.get('req_id') or ''),
            str(rec.get('trace_id') or ''),
        ])
        last_ts = float(_EXEC_FAIL_REPORT_DEDUP.get(dedup_key) or 0.0)
        if last_ts > 0 and (float(ts_now or 0.0) - last_ts) < 1.0:
            return rec
        _EXEC_FAIL_REPORT_DEDUP[dedup_key] = float(ts_now or 0.0)
    except Exception:
        pass
    try:
        day = time.strftime('%Y%m%d', time.localtime(ts_now or time.time()))
    except Exception:
        day = 'unknown'
    try:
        jsonl_fp = os.path.join(EXEC_FAIL_REPORT_DIR, f'{day}_exec_fail_report.jsonl')
        with open(jsonl_fp, 'a', encoding='utf-8') as f:
            f.write(json.dumps(rec, ensure_ascii=False) + '\n')
    except Exception as _e:
        _record_swallowed_exception('except_pass_exec_fail_report_jsonl', _e)
    try:
        txt_fp = os.path.join(EXEC_FAIL_REPORT_DIR, f'{day}_exec_fail_report.txt')
        _amt_show = '-' if rec.get('amount_u') in (None, '') else f"{float(rec.get('amount_u')):.4f}"
        parts = [
            f"时间={rec.get('time') or '-'}",
            f"阶段={rec.get('phase') or '-'}",
            f"模块={rec.get('module') or '-'}",
            f"币种={rec.get('coin') or '-'}",
            f"平台={rec.get('platform') or '-'}",
            f"动作={rec.get('action') or '-'}",
            f"金额U={_amt_show}",
            f"原因={rec.get('reason') or '-'}",
        ]
        if rec.get('req_id'):
            parts.append(f"req_id={rec.get('req_id')}")
        if rec.get('trace_id'):
            parts.append(f"trace_id={rec.get('trace_id')}")
        if rec.get('layer_id'):
            parts.append(f"layer_id={rec.get('layer_id')}")
        if rec.get('fail_step'):
            parts.append(f"fail_step={rec.get('fail_step')}")
        if rec.get('last_step'):
            parts.append(f"last_step={rec.get('last_step')}")
        if rec.get('timeout_sec') not in (None, ''):
            parts.append(f"timeout_sec={float(rec.get('timeout_sec')):.1f}")
        if rec.get('screenshot'):
            parts.append(f"screenshot={rec.get('screenshot')}")
        if rec.get('error'):
            parts.append(f"错误详情={rec.get('error')}")
        with open(txt_fp, 'a', encoding='utf-8') as f:
            f.write(' | '.join(parts) + '\n')
    except Exception as _e:
        _record_swallowed_exception('except_pass_exec_fail_report_txt', _e)
    try:
        safe_log(lambda: f"[{now_ts()}] EXEC_FAIL_REPORT phase={str(phase or '-')} mod={str(module or '-')} coin={str(coin or '').upper() or '-'} plat={str(plat or '').upper() or '-'} act={str(action or '-') or '-'} amount_u={('-' if amt_f is None else f'{float(amt_f):.4f}')} reason={str(reason or '-')[:220]}")
    except Exception:
        pass
    return rec

def _now_ms() -> int:
    try:
        return int(time.time() * 1000)
    except Exception:
        return 0

def _safe_str(x, limit: int = 500) -> str:
    try:
        s = str(x)
    except Exception:
        s = repr(x)
    try:
        if len(s) > int(limit):
            s = s[:int(limit)] + "...(truncated)"
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_470', _e)
        pass
    return s

def _safe_page_url(page) -> str:
    try:
        return str(getattr(page, 'url', '') or '')
    except Exception:
        return ''

def _safe_page_title(page) -> str:
    try:
        return str(page.title() or '')
    except Exception:
        return ''

def _safe_page_text(page, limit: int = 500) -> str:
    try:
        txt = page.locator("body").inner_text(timeout=2000) or ""
        txt = re.sub(r"\s+", " ", str(txt)).strip()
        return txt[:int(limit)]
    except Exception:
        return ''

def _safe_html_hint(page, limit: int = 500) -> str:
    try:
        html = page.content() or ''
        html = re.sub(r"\s+", " ", str(html)).strip()
        return html[:int(limit)]
    except Exception:
        return ''

def _exec_debug_png_name(plat: str, coin: str, action: str, stage: str) -> str:
    try:
        ts = datetime.now().strftime("%Y%m%d_%H%M%S")
    except Exception:
        ts = str(int(time.time()))
    safe_stage = re.sub(r"[^A-Za-z0-9_\-]", "_", str(stage or ''))
    safe_plat = re.sub(r"[^A-Za-z0-9_\-]", "_", str(plat or ''))
    safe_coin = re.sub(r"[^A-Za-z0-9_\-]", "_", str(coin or ''))
    safe_action = re.sub(r"[^A-Za-z0-9_\-]", "_", str(action or ''))
    return f"{ts}_{safe_plat}_{safe_coin}_{safe_action}_{safe_stage}.png"

def _exec_capture_debug_shot(page, plat: str, coin: str, action: str, stage: str) -> str:
    try:
        os.makedirs(DEBUG_EXEC_DIR, exist_ok=True)
        fname = _exec_debug_png_name(plat, coin, action, stage)
        fpath = os.path.join(DEBUG_EXEC_DIR, fname)
        page.screenshot(path=fpath, full_page=True, timeout=3000)
        return str(fpath)
    except Exception as e:
        return f"screenshot_failed:{_safe_str(e, 200)}"

def _exec_get_req_ref(obj: Any = None) -> Any:
    try:
        if isinstance(obj, dict):
            return obj
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_471', _e)
