                    _extra = {"coins_cnt": len(need_refresh or []), "phase_budget_sec": float((_ind_phase_cfg or {}).get('phase_budget_sec') or 0.0), "max_batch": int(min(int(_ui_fallback_max_batch), int((_ind_phase_cfg or {}).get('max_batch') or _ui_fallback_max_batch)))}
