def _scan_sleep_wake_tolerance_sec(default: float = 5.0) -> float:
    val = None
    try:
        _cfg = globals().get("cfg_getf_runtime")
        if callable(_cfg):
            val = _cfg("SCAN_WAKE_TOLERANCE_SEC", default)
    except Exception:
        val = None
    if val is None:
        try:
            val = os.getenv("SCAN_WAKE_TOLERANCE_SEC", str(default))
        except Exception:
            val = default
    try:
        sec = float(val or default)
    except Exception:
        sec = float(default)
    if sec < 1.0:
        sec = 1.0
    if sec > 30.0:
        sec = 30.0
    return float(sec)

