def _scan_sleep_plan_set(*, deadline_ts: float, reason: str = "", sleep_total_sec: float = 0.0, scan_count: int = 0, plan_source: str = "MAIN", round_stage: str = "SLEEPING", round_msg: str = "", extra: dict | None = None) -> dict:
    nowv = float(time.time())
    try:
        dts = float(deadline_ts or 0.0)
    except Exception:
        dts = 0.0
    obj = {
        "active": bool(dts > 0),
        "state": "SLEEPING" if dts > 0 else "IDLE",
        "reason": str(reason or "")[:240],
        "plan_source": str(plan_source or "MAIN")[:80],
        "deadline_ts": float(dts),
        "deadline_text": datetime.fromtimestamp(dts).strftime("%Y-%m-%d %H:%M:%S") if dts > 0 else "",
        "sleep_total_sec": float(max(0.0, sleep_total_sec or 0.0)),
        "created_ts": nowv,
        "updated_ts": nowv,
        "heartbeat_ts": nowv,
        "scan_count": int(scan_count or 0),
        "round_stage": str(round_stage or "SLEEPING")[:80],
        "round_msg": str(round_msg or "")[:240],
        "display_state": "正常等待下一轮" if dts > 0 else "空闲",
        "display_text": str(round_msg or "")[:240],
        "remain_sec": int(max(0, round(dts - nowv))) if dts > 0 else 0,
        "overdue_sec": 0.0,
        "wake_state": "WAITING" if dts > 0 else "IDLE",
        "wake_tolerance_sec": float(_scan_sleep_wake_tolerance_sec()),
        "wake_logged": False,
        "wake_ok_logged": False,
        "wake_recover_logged": False,
        "wake_recover_mode": "",
        "wake_event_ts": 0.0,
        "wake_event_text": "",
    }
    if isinstance(extra, dict) and extra:
        try:
            obj["extra"] = dict(extra)
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_540', _e)
            pass
    globals()["_SCAN_SLEEP_PLAN"] = obj
    return dict(obj)

