                err=_detail,
                req_id=str((_meta.get('req_id') if isinstance(_meta, dict) else '') or _rd.get('request_id') or ''),
                trace_id=str((_meta.get('trace_id') if isinstance(_meta, dict) else '') or _rd.get('trace_id') or ''),
