def _executor_run_quanbu_isolated(cdp: str, log_path: str, snapshot: dict, requests: list, *, coins: list[str], exec_modules: set | None = None,
                                  max_orders: int | None = None, max_notional_u: float | None = None, pre_reload_times: int = 0,
                                  batch_name: str = "EXECUTOR_QUANBU_ISOLATED") -> list:
    _reqs = list(requests or [])
    if not _reqs:
        return []

    def _run_one(_req: Any, _idx: int) -> list:
        _one_req = [_req]
        try:
            _res = executor_run_quanbu(
                cdp,
                log_path=log_path,
                snapshot=snapshot,
                requests=_one_req,
                coins=coins,
                exec_modules=exec_modules,
                max_orders=(1 if max_orders is None else max(1, int(max_orders))),
                max_notional_u=max_notional_u,
                pre_reload_times=pre_reload_times,
            )
        except Exception as _e:
            _reason = f"isolated_executor_exception:{repr(_e)}"
            try:
                _r0 = _req_get_dict(_req)
                _m0 = str(_r0.get('module') or '').upper()
                _c0 = str(_r0.get('coin') or '').upper()
                _p0 = str(_r0.get('platform') or '').upper()
                _a0 = str(_r0.get('action_type') or _r0.get('action') or '').lower()
                _meta0 = _r0.get('meta') if isinstance(_r0.get('meta'), dict) else {}
                _pin('EXEC_ISOLATED_FAIL_CONTINUE', ok=0, reason=_reason[:180], mod=_m0, coin=_c0, plat=_p0, act=_a0,
                     trace=str((_meta0.get('trace_id') if isinstance(_meta0, dict) else '') or _r0.get('trace_id') or ''),
                     batch_name=str(batch_name or 'EXECUTOR_QUANBU_ISOLATED'), req_idx=int(_idx), req_total=int(len(_reqs)))
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_616', _e)
                pass
            return _executor_exception_fail_results(_one_req, reason=_reason, batch_name=batch_name)
        if not isinstance(_res, list):
            _reason = "isolated_executor_bad_result:not_list"
            try:
                _r0 = _req_get_dict(_req)
                _m0 = str(_r0.get('module') or '').upper()
                _c0 = str(_r0.get('coin') or '').upper()
                _p0 = str(_r0.get('platform') or '').upper()
                _a0 = str(_r0.get('action_type') or _r0.get('action') or '').lower()
                _meta0 = _r0.get('meta') if isinstance(_r0.get('meta'), dict) else {}
                _pin('EXEC_ISOLATED_FAIL_CONTINUE', ok=0, reason=_reason, mod=_m0, coin=_c0, plat=_p0, act=_a0,
                     trace=str((_meta0.get('trace_id') if isinstance(_meta0, dict) else '') or _r0.get('trace_id') or ''),
                     batch_name=str(batch_name or 'EXECUTOR_QUANBU_ISOLATED'), req_idx=int(_idx), req_total=int(len(_reqs)))
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_617', _e)
                pass
            return _executor_exception_fail_results(_one_req, reason=_reason, batch_name=batch_name)
        if len(_res) <= 0:
            _reason = "isolated_executor_empty_result"
            try:
                _r0 = _req_get_dict(_req)
                _meta0 = _r0.get('meta') if isinstance(_r0.get('meta'), dict) else {}
                _pin('EXEC_LOST_AFTER_DEQUEUE', ok=0, reason=_reason,
                     mod=str(_r0.get('module') or '').upper(), coin=str(_r0.get('coin') or '').upper(),
                     plat=str(_r0.get('platform') or '').upper(), act=str(_r0.get('action_type') or _r0.get('action') or '').lower(),
                     trace=str((_meta0.get('trace_id') if isinstance(_meta0, dict) else '') or _r0.get('trace_id') or ''),
                     batch_name=str(batch_name or 'EXECUTOR_QUANBU_ISOLATED'), req_idx=int(_idx), req_total=int(len(_reqs)))
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_618', _e)
                pass
            return _executor_exception_fail_results(_one_req, reason=_reason, batch_name=batch_name)
        if len(_res) != 1:
            _packed = []
            try:
                if _req_is_m10_koujing_group(_req):
                    _packed = _m10_pack_isolated_executor_rows(_res)
            except Exception:
                _packed = []
            if _packed:
                try:
                    _r0 = _req_get_dict(_req)
                    _meta0 = _r0.get('meta') if isinstance(_r0.get('meta'), dict) else {}
                    _pin('EXEC_ISOLATED_GROUP_PACK_OK', ok=1, reason=f'm10_group_pack:{len(_res)}->{len(_packed)}',
                         mod=str(_r0.get('module') or '').upper(), coin=str(_r0.get('coin') or '').upper(),
                         plat=str(_r0.get('platform') or '').upper(), act=str(_r0.get('action_type') or _r0.get('action') or '').lower(),
                         trace=str((_meta0.get('trace_id') if isinstance(_meta0, dict) else '') or _r0.get('trace_id') or ''),
                         batch_name=str(batch_name or 'EXECUTOR_QUANBU_ISOLATED'), req_idx=int(_idx), req_total=int(len(_reqs)))
                except Exception:
                    pass
                _res = list(_packed)
            else:
                _reason = f"isolated_executor_result_count_mismatch:{len(_res)}"
                try:
                    _r0 = _req_get_dict(_req)
                    _meta0 = _r0.get('meta') if isinstance(_r0.get('meta'), dict) else {}
                    _pin('EXEC_ISOLATED_FAIL_CONTINUE', ok=0, reason=_reason,
                         mod=str(_r0.get('module') or '').upper(), coin=str(_r0.get('coin') or '').upper(),
                         plat=str(_r0.get('platform') or '').upper(), act=str(_r0.get('action_type') or _r0.get('action') or '').lower(),
                         trace=str((_meta0.get('trace_id') if isinstance(_meta0, dict) else '') or _r0.get('trace_id') or ''),
                         batch_name=str(batch_name or 'EXECUTOR_QUANBU_ISOLATED'), req_idx=int(_idx), req_total=int(len(_reqs)))
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_619', _e)
                    pass
                if len(_res) > 1:
                    _res = list(_res[:1])
                else:
                    _res = _executor_exception_fail_results(_one_req, reason=_reason, batch_name=batch_name)
        return list(_res)

    _all = []
    for _idx, _req in enumerate(_reqs):
        try:
            _one_res = _run_one(_req, _idx)
        except Exception as _e:
            _one_res = _executor_exception_fail_results([_req], reason=f"isolated_wrapper_exception:{repr(_e)}", batch_name=batch_name)
        if not isinstance(_one_res, list) or len(_one_res) != 1:
            _one_res = _executor_exception_fail_results([_req], reason="isolated_wrapper_result_legacy_deleted", batch_name=batch_name)
        _all.extend(list(_one_res[:1]))

    if len(_all) != len(_reqs):
        _fixed = []
        for _idx, _req in enumerate(_reqs):
            if _idx < len(_all) and isinstance(_all[_idx], dict):
                _fixed.append(_all[_idx])
            else:
                _fixed.extend(_executor_exception_fail_results([_req], reason="isolated_wrapper_batch_count_legacy_deleted", batch_name=batch_name))
        _all = _fixed[:len(_reqs)]
    return list(_all)

def _log_sync_pw_asyncio_handoff(logfp_or_path: Any, *, mod: str, note: str = "", reason: str = "") -> None:
    if not _handoff_guard_allow(mod=str(mod or "SYS"), note=str(note or "running_loop_detected_use_worker_thread"), reason=str(reason or "")):
        return
    _row = {
        "ts": now_ts(),
        "mod": str(mod or "SYS"),
        "type": "sync_pw_asyncio_handoff",
        "reason": str(reason or ""),
        "note": str(note or "running_loop_detected_use_worker_thread"),
        "trace": "",
    }
    try:
        if isinstance(logfp_or_path, str):
            write_jsonl(logfp_or_path, _row)
        else:
            write_jsonl(logfp_or_path, _row)
        return
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_620', _e)
        pass
    try:
        safe_log(lambda: f"[{now_ts()}] [{str(mod or 'SYS')}] sync_pw_asyncio_handoff note={note} reason={reason}")
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_621', _e)
        pass
def _m2_accept_snapshot(snapshot: dict, runtime_gen: int) -> dict:
    global LAST_GOOD_SNAPSHOT, LAST_GOOD_TS, LAST_GOOD_REASON
    with _SNAPSHOT_COMMIT_LOCK:
        if int(runtime_gen) != _pw_runtime_gen_value():
            return _m2_make_fail_snapshot('runtime_generation_changed_before_commit', note='stale_result_rejected')
        if _snapshot_positions_verified(snapshot):
            LAST_GOOD_SNAPSHOT = copy.deepcopy(snapshot)
            LAST_GOOD_TS = float(snapshot.get('ts') or time.time())
            LAST_GOOD_REASON = str(snapshot.get('data_quality_reason') or '')
    try:
        _audit_observe_snapshot(__file__, snapshot)
    except Exception:
        pass  # Passive audit failure must not alter scan/trading decisions.
    try:
        if _snapshot_positions_verified(snapshot):
            _m10_step3_reconcile_scan(snapshot)  # Evidence only; never submits a replacement order.
    except Exception as _e:
        try:
            _record_swallowed_exception('m10_step3_scan_confirmation', _e)
        except Exception:
            pass  # Keep pending intact when reconciliation is unavailable.
    return snapshot

def m2_scan(cdp: str, coins: List[str], logfp: str, seed: Optional[int] = None, ind_mode: str = 'on', *, only_positions: bool = False, reason: str = "", scan_scope: str = "", _ui_retry: int = 0, **kwargs) -> Dict[str, Any]:
    """Playwright 同步版扫描包装层（已加硬超时/卡死重建/假活可观测）。"""
    try:
        import asyncio as _asyncio
    except Exception:
        _asyncio = None

    _running_loop = False
    if _asyncio is not None:
        try:
            _running_loop = bool(_asyncio.get_running_loop().is_running())
        except Exception:
            _running_loop = False

    _force_worker = True
    try:
        _flag = _env_flag("M2_FORCE_WORKER_THREAD", True)
        _force_worker = True if _flag is None else bool(_flag)
    except Exception:
        _force_worker = True
    _timeout_sec = _m2_scan_timeout_sec(90.0)
    # Only postcheck callers supply this budget. Ordinary M2 lifecycle is unchanged.
    _postcheck_deadline = kwargs.pop('_postcheck_deadline_monotonic', None)
    if _postcheck_deadline is not None:
        _left = float(_postcheck_deadline) - time.monotonic()
        if _left <= 0:
            return _m2_make_fail_snapshot('postcheck_deadline_exhausted')
        _timeout_sec = min(float(_timeout_sec or _left), _left)
    _started_ts = float(time.time())
    _scan_runtime_gen = _m2_scan_runtime_gen_capture()
    _m2_scan_watch_update("dispatch", 0, "M2 扫描准备开始", reason=str(reason or ""), state="SCANNING", extra={"coins_cnt": len(coins or []), "only_positions": bool(only_positions), "timeout_sec": float(_timeout_sec), "scan_scope": str(scan_scope or ""), "runtime_gen": int(_scan_runtime_gen)}, touch_panel=True)

    if (not _running_loop) and (not _force_worker):
        try:
            _res_direct = _m2_scan_impl(cdp, coins, logfp, seed=seed, ind_mode=ind_mode, only_positions=only_positions, reason=reason, scan_scope=scan_scope, _ui_retry=_ui_retry, _scan_runtime_gen=_scan_runtime_gen, **kwargs)
            _accepted = _m2_accept_snapshot(_res_direct if isinstance(_res_direct, dict) else {}, _scan_runtime_gen)
            _dq_ok = _accepted.get('data_quality') == 'ok'
            _m2_scan_watch_finish("DONE" if _dq_ok else "ERROR", reason="scan_ok" if _dq_ok else str(_accepted.get('data_quality_reason') or _accepted.get('dq_reason') or 'scan_dq_fail'), touch_panel=False)
            return _accepted
        except Exception as _e:
            _m2_scan_watch_update("error", int((_m2_scan_watch_snapshot() or {}).get("pct") or 0), "M2 直连扫描异常", reason=repr(_e), state="ROUND_ERROR", touch_panel=True)
            raise

    try:
        _note = "running_loop_detected_use_worker_thread" if _running_loop else "force_worker_thread_timeout_guard"
        write_jsonl(logfp, {
            "ts": now_ts(),
            "mod": "M2",
            "type": "sync_pw_asyncio_handoff",
            "reason": str(reason or ""),
            "note": _note,
            "timeout_sec": float(_timeout_sec),
        })
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_622', _e)
        pass

    _max_runtime_retry = 0 if _postcheck_deadline is not None else 1
    _attempt = 0
    _last_retryable_reason = ""
    while True:
        try:
            _res = _run_call_in_worker_thread(
                lambda: _m2_scan_impl(cdp, coins, logfp, seed=seed, ind_mode=ind_mode, only_positions=only_positions, reason=reason, scan_scope=scan_scope, _ui_retry=_ui_retry, _scan_runtime_gen=_scan_runtime_gen, **kwargs),
                thread_name="M2SyncPlaywrightWorker",
                timeout_sec=_timeout_sec,
                logfp=logfp,
                mod="M2",
                on_timeout_rebuild=True,
                **({'deadline_monotonic': _postcheck_deadline} if _postcheck_deadline is not None else {}),
            )
            _accepted = _m2_accept_snapshot(_res if isinstance(_res, dict) else {}, _scan_runtime_gen)
            _dq_ok = _accepted.get('data_quality') == 'ok'
            _m2_scan_watch_finish("DONE" if _dq_ok else "ERROR", reason="scan_ok" if _dq_ok else str(_accepted.get('data_quality_reason') or _accepted.get('dq_reason') or 'scan_dq_fail'), touch_panel=False)
            return _accepted
        except TimeoutError as _te:
            _reason = str(_te or f"m2_scan_timeout:{_timeout_sec:.1f}s")
            _last_retryable_reason = _reason
            if _reason.startswith('m2_positions_scan_timeout:'):
                # The worker raised and returned normally: a budget expiry is
                # not proof of a dead browser and must not reset the executor.
                safe_log(lambda: f'[M2][SCAN_BUDGET_EXHAUSTED] reason={_reason} runtime_reset=0 wait_next_scan=1')
                return _m2_make_fail_snapshot(_reason, note='positions_budget_exhausted', started_ts=_started_ts)
            try:
                _m2_scan_watch_update("timeout", int((_m2_scan_watch_snapshot() or {}).get("pct") or 5), "M2 扫描超时，准备重建并重试", reason=_reason, state="SCAN_STUCK", extra={"timeout_sec": float(_timeout_sec), "retry_attempt": int(_attempt + 1)}, touch_panel=True)
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_623', _e)
                pass
            try:
                write_jsonl(logfp, {
                    "ts": now_ts(),
                    "mod": "M2",
                    "type": "m2_scan_timeout",
                    "reason": _reason,
                    "timeout_sec": float(_timeout_sec),
                    "running_loop": bool(_running_loop),
                    "force_worker": bool(_force_worker),
                    "retry_attempt": int(_attempt + 1),
                })
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_624', _e)
                pass
            if _attempt < _max_runtime_retry:
                try:
                    _pw_runtime_hard_reset(_reason, source="M2", logfp=logfp, stop_exec_runtime=False, rebuild_worker=True, touch_scan=True)
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_624b', _e)
                    pass
                try:
                    _pw_runtime_wait_until_ready(timeout_sec=min(3.0, max(0.5, float(_timeout_sec) / 12.0)), reason=_reason, logfp=logfp, mod="M2")
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_624c', _e)
                    pass
                _attempt += 1
                _scan_runtime_gen = _m2_scan_runtime_gen_capture()
                continue
            return _m2_make_fail_snapshot(_reason, note="timeout_fail_closed", started_ts=_started_ts)
        except (_UiDeadError, _UiLinkError) as _ue:
            _reason = str(_ue or "m2_ui_dead")
            if any(marker in _reason for marker in ('ext_recovery_deferred', 'ext_recovery_in_progress', 'var_recovery_deferred', 'var_recovery_in_progress')):
                _platform_wait = 'VAR' if 'var_recovery_' in _reason else 'EXT'
                _m2_scan_watch_update('recovery_wait', 20, f'{_platform_wait}页面恢复等待，禁止使用失败快照交易', reason=_reason, state='RECOVERING_UI', touch_panel=True)
                return _m2_make_fail_snapshot(_reason, note=f'{_platform_wait.lower()}_recovery_wait_fail_closed', started_ts=_started_ts)
            _last_retryable_reason = _reason
            try:
                _m2_scan_watch_update("recovering_ui", int((_m2_scan_watch_snapshot() or {}).get("pct") or 5), "M2 UI 异常，准备重建并重试", reason=_reason, state="RECOVERING_UI", extra={"retry_attempt": int(_attempt + 1), "where": str(getattr(_ue, 'where', '') or ''), "detail": str(getattr(_ue, 'detail', '') or '')[:200]}, touch_panel=True)
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_624d', _e)
                pass
            try:
                write_jsonl(logfp, {
                    "ts": now_ts(),
                    "mod": "M2",
                    "type": "m2_scan_ui_fault",
                    "reason": _reason,
                    "where": str(getattr(_ue, 'where', '') or ''),
                    "detail": str(getattr(_ue, 'detail', '') or ''),
                    "retry_attempt": int(_attempt + 1),
                })
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_624e', _e)
                pass
            if _attempt < _max_runtime_retry:
                try:
                    _pw_runtime_hard_reset(_reason, source="M2", logfp=logfp, stop_exec_runtime=False, rebuild_worker=True, touch_scan=True)
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_624f', _e)
                    pass
                try:
                    _pw_runtime_wait_until_ready(timeout_sec=min(3.0, max(0.5, float(_timeout_sec) / 12.0)), reason=_reason, logfp=logfp, mod="M2")
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_624g', _e)
                    pass
                _attempt += 1
                _scan_runtime_gen = _m2_scan_runtime_gen_capture()
                continue
            return _m2_make_fail_snapshot(_reason, note="ui_dead_fail_closed", started_ts=_started_ts)
        except Exception as _e:
            _m2_scan_watch_update("error", int((_m2_scan_watch_snapshot() or {}).get("pct") or 5), "M2 扫描异常", reason=repr(_e), state="ROUND_ERROR", extra={"retry_attempt": int(_attempt + 1), "last_retryable_reason": str(_last_retryable_reason or '')[:200]}, touch_panel=True)
            raise

def _contract_drop_is_fatal(fn_name: str, dropped: list[str] | None = None) -> tuple[bool, list[str]]:
    _fn = str(fn_name or '').strip()
    _d = [str(k or '').strip() for k in (dropped or []) if str(k or '').strip()]
    if not _d:
        return False, []
    critical_map = {
        'm2_scan': {'scan_scope', 'only_positions', 'reason', '_ui_retry', 'force_reload_n'},
        '_m2_scan_impl': {'scan_scope', 'only_positions', 'reason', '_ui_retry', 'force_reload_n'},
    }
    critical = set(critical_map.get(_fn, set()))
    hit = [k for k in _d if k in critical]
    return bool(hit), hit

def _legacy_compat_filter_kwargs(fn: Any, kwargs: dict | None, *, logfp: str, fn_name: str) -> tuple[dict, list]:
    try:
        import inspect as _inspect
        sig = _inspect.signature(fn)
        ok = set(sig.parameters.keys())
        accepts_var_kw = any(p.kind == _inspect.Parameter.VAR_KEYWORD for p in sig.parameters.values())
    except Exception:
        ok = set()
        accepts_var_kw = False
    filt = {}
    dropped = []
    for k, v in (kwargs or {}).items():
        if accepts_var_kw or (not ok) or (k in ok):
            filt[k] = v
        else:
            dropped.append(k)
    if dropped:
        try:
            _log_jsonl(logfp, {"ts": time.time(), "mod": "SYS", "event": "contract_kw_dropped", "fn": str(fn_name or ''), "dropped": dropped})
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_625', _e)
            pass
        try:
            ADAPTER.append_telemetry({"event": "contract_kw_dropped", "fn": str(fn_name or ''), "dropped": dropped})
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_626', _e)
            pass
        try:
            _fatal, _critical = _contract_drop_is_fatal(str(fn_name or ''), dropped)
        except Exception:
            _fatal, _critical = False, []
        if _fatal:
            raise TypeError(f"contract_kw_dropped_fatal:{str(fn_name or '')}|critical={','.join(_critical)}|dropped={','.join(dropped)}")
    return filt, dropped

def _legacy_compat_m2_scan(cdp: str, coins: List[str], logfp: str, *args, **kwargs) -> Dict[str, Any]:
    """m2_scan 旧签名/旧参数兼容边界层。
    主链只允许调这个边界函数，不允许在主链里继续散落 compat 判断。
    """
    try:
        filt, _ = _legacy_compat_filter_kwargs(m2_scan, kwargs, logfp=logfp, fn_name='m2_scan')
        attempt = 0
        try:
            attempt = int((filt or {}).get('_ui_retry') or 0)
        except Exception:
            attempt = 0
        try:
            return m2_scan(cdp, coins, logfp, *args, **filt)
        except _UiDeadError as _ude:
            try:
                write_jsonl(logfp, {'ts': now_ts(), 'mod': 'M2', 'type': 'm2_scan_ui_dead', 'attempt': int(attempt or 0), 'where': str(getattr(_ude,'where','') or ''), 'detail': str(getattr(_ude,'detail','') or ''), 'reason': str(_ude)})
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_627', _e)
                pass
            if attempt < 1:
                try:
                    progress(logfp, 9, "[PIN][UI_DEAD][M2_RETRY] 强制重连 + 自动重试", attempt=attempt+1, where=getattr(_ude,'where',''), detail=getattr(_ude,'detail',''))
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_628', _e)
                    pass
                filt2 = dict(filt or {})
                filt2['_ui_retry'] = attempt + 1
                try:
                    _r0 = str(filt2.get('reason') or '')
                except Exception:
                    _r0 = ''
                filt2['reason'] = ((f"ui_dead_retry{attempt+1}|{_ude}") if (not _r0) else (f"{_r0} | ui_dead_retry{attempt+1}|{_ude}"))
                return m2_scan(cdp, coins, logfp, *args, **filt2)
            return {
                "ts": time.time(),
                "data_quality": "fail",
                "data_quality_reason": f"ui_dead:{_ude}",
                "balances": {},
                "positions": {"EXT": {}, "VAR": {}},
                "indicators": {},
                "coins": {},
                "raw": {"reason": str(_ude)},
            }
    except TypeError as _e:
        try:
            _msg = str(_e or '')
        except Exception:
            _msg = ''
        if str(_msg).startswith('contract_kw_dropped_fatal:'):
            raise
        try:
            _log_exc(mod="SYS", stage="M2_COMPAT_TYPEERROR", e=_e)
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_629', _e)
            pass
        return m2_scan(cdp, coins, logfp, *args)

def m2_scan_compat(cdp: str, coins: List[str], logfp: str, *args, **kwargs) -> Dict[str, Any]:
    """兼容入口保留给旧调用点；内部立即转到 legacy_compat 边界层。"""
    return _legacy_compat_m2_scan(cdp, coins, logfp, *args, **kwargs)

_M2_SCAN_CACHE = {"ts": 0.0, "snap": None, "coins_key": "", "cdp": ""}

def _m2_scan_cached(cdp: str, coins: List[str], logfp: str, seed: Optional[int] = None, ind_mode: str = 'on',
                    *, only_positions: bool = False, reason: str = "", scan_scope: str = "", decision_needed: bool = True,
                    pending_len: int = 0, force: bool = False, _ui_retry: int = 0, **kwargs) -> Dict[str, Any]:
    now_t = float(time.time())
    try:
        min_sec = float(cfg_getf_runtime("M2_MIN_REFRESH_SEC", 5) or 5)
    except Exception:
        min_sec = 5.0

    try:
        coins_key = ",".join([str(c or "").upper().strip() for c in (coins or [])])
    except Exception:
        coins_key = ""

    cache = _M2_SCAN_CACHE
    same_target = (str(cache.get("cdp") or "") == str(cdp or "")) and (str(cache.get("coins_key") or "") == str(coins_key or ""))
    age = now_t - float(cache.get("ts") or 0.0)

    allow_skip = (not force) and same_target and (cache.get("snap") is not None) and (int(pending_len or 0) <= 0) and (not bool(decision_needed)) and (age < float(min_sec))

    if allow_skip:
        try:
            _log_jsonl(logfp, {
                "ts": now_t,
                "mod": "M2",
                "event": "m2_scan_skip_cache",
                "ok": True,
                "reason": str(reason or "cache_hit"),
                "pending_len": int(pending_len or 0),
                "decision_needed": bool(decision_needed),
                "age_sec": round(float(age), 6),
                "min_refresh_sec": float(min_sec),
                "coins": coins_key,
            })
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_630', _e)
            pass
        return cache.get("snap") or {}

    snap = m2_scan_compat(cdp, coins, logfp, seed=seed, ind_mode=ind_mode, only_positions=only_positions, reason=reason, scan_scope=scan_scope, _ui_retry=_ui_retry, **kwargs) or {}
    try:
        cache["ts"] = now_t
        cache["snap"] = snap
        cache["coins_key"] = coins_key
        cache["cdp"] = str(cdp or "")
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_631', _e)
        pass
    try:
        _log_jsonl(logfp, {
            "ts": now_t,
            "mod": "M2",
            "event": "m2_scan_fetch",
            "ok": True,
            "reason": str(reason or ""),
            "pending_len": int(pending_len or 0),
            "decision_needed": bool(decision_needed),
            "only_positions": bool(only_positions),
            "age_sec_prev": round(float(age), 6),
            "min_refresh_sec": float(min_sec),
            "coins": coins_key,
        })
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_632', _e)
        pass
    return snap

def _snapshot_merge_coin_positions(base_snap: dict | None, fresh_snap: dict | None, target_coins: list[str] | None = None) -> dict:
    """把轻量重扫结果按币合并回当前快照。
    目的：执行后只刷新目标币，避免整轮全量重扫。
    """
    try:
        if not isinstance(base_snap, dict):
            base_snap = {}
        if not isinstance(fresh_snap, dict) or not fresh_snap:
            return dict(base_snap or {})
        merged = copy.deepcopy(base_snap)
        target_set = {str(c or '').upper().strip() for c in (target_coins or []) if str(c or '').strip()}
        if not target_set:
            target_set = {str(c or '').upper().strip() for c in ((fresh_snap.get('coins') or []) if isinstance(fresh_snap, dict) else []) if str(c or '').strip()}
        if not target_set:
            return fresh_snap
        for _k in ('ts', 'timestamp', 'scan_id', 'scan_count', 'data_quality', 'data_quality_reason'):
            if _k in fresh_snap:
                merged[_k] = fresh_snap.get(_k)
        try:
            _meta0 = merged.get('meta') if isinstance(merged, dict) else None
            _meta1 = fresh_snap.get('meta') if isinstance(fresh_snap, dict) else None
            if not isinstance(_meta0, dict):
                _meta0 = {}
            if isinstance(_meta1, dict):
                for _mk in (
                    'strict_fresh_positions', 'strict_latest_only', 'scope', 'scan_scope',
                    'allow_commit_global', 'reason', 'postcheck_direct_read'
                ):
                    if _mk in _meta1:
                        _meta0[_mk] = _meta1.get(_mk)
                merged['meta'] = _meta0
            if 'scan_scope' in fresh_snap:
                merged['scan_scope'] = fresh_snap.get('scan_scope')
        except Exception:
            pass

        def _merge_platform_dict(dst_root: dict, src_root: dict, key: str) -> None:
            try:
                d0 = dst_root.get(key) or {}
                s0 = src_root.get(key) or {}
                if not isinstance(d0, dict):
                    d0 = {}
                if not isinstance(s0, dict):
                    return
                for _plat in ('EXT', 'VAR', 'ext', 'var'):
                    sd = s0.get(_plat)
                    if not isinstance(sd, dict):
                        continue
                    dd = d0.get(_plat)
                    if not isinstance(dd, dict):
                        dd = {}
                    for _coin in target_set:
                        if _coin in sd:
                            dd[_coin] = sd.get(_coin)
                        else:
                            dd.pop(_coin, None)
                    d0[_plat] = dd
                dst_root[key] = d0
            except Exception:
                return

        _merge_platform_dict(merged, fresh_snap, 'positions')
        _merge_platform_dict(merged, fresh_snap, 'raw_positions')

        try:
            d0 = merged.get('by_coin') or {}
            s0 = fresh_snap.get('by_coin') or {}
            if isinstance(d0, dict) and isinstance(s0, dict):
                for _coin in target_set:
                    if _coin in s0:
                        d0[_coin] = s0.get(_coin)
                    else:
                        d0.pop(_coin, None)
                merged['by_coin'] = d0
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_633', _e)
            pass
        try:
            d0 = merged.get('coins') or {}
            s0 = fresh_snap.get('coins') or {}
            if isinstance(d0, dict) and isinstance(s0, dict):
                for _coin in target_set:
                    if _coin in s0:
                        d0[_coin] = s0.get(_coin)
                    else:
                        d0.pop(_coin, None)
                merged['coins'] = d0
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_634', _e)
            pass
        try:
            ind0 = merged.get('indicators') or {}
            ind1 = fresh_snap.get('indicators') or {}
            if isinstance(ind0, dict) and isinstance(ind1, dict):
                for _coin in target_set:
                    if _coin in ind1:
                        ind0[_coin] = ind1.get(_coin)
                merged['indicators'] = ind0
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_635', _e)
            pass
        return merged
    except Exception:
        try:
            return dict(base_snap or {})
        except Exception:
            return {}

def _snapshot_refresh_targeted(cdp: str, current_snap: dict | None, coins: list[str] | None, logfp: str, *, reason: str = '', target_coin: str = '', force: bool = False, allow_full_fallback: bool = False, refresh_indicators: bool = False) -> dict | None:
    """局部刷新保留给非交易主链的兼容调用。
    爸爸口径：真实交易主链（PRETRADE / EXEC_PRE / POSTCHECK / POST_EXEC）不再允许用它代替全量扫描。
    """
    try:
        _allow_light, _light_rsn = _refresh_reason_guard(reason=str(reason or ''), evidence=str(reason or ''), where='snapshot_refresh_targeted', light=True)
        if bool(force) and (not _allow_light):
            force = False
        if bool(allow_full_fallback) and (not _allow_light):
            allow_full_fallback = False
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_636', _e)
        pass
    try:
        _coin = str(target_coin or '').upper().strip()
    except Exception:
        _coin = ''
    try:
        _coins = [str(c or '').upper().strip() for c in (coins or []) if str(c or '').strip()]
    except Exception:
        _coins = []
    if _coin:
        try:
            snap_one = _m2_scan_cached(
                        cdp,
                        [_coin],
                        logfp,
                        reason=str(reason or 'TARGET_REFRESH_ONE'),
                        force=bool(force),
                        decision_needed=True,
                        pending_len=0,
                        only_positions=(False if bool(refresh_indicators) else True),
                        ind_mode=('force' if bool(refresh_indicators) else 'off'),
                        scan_scope='local',
                    )
        except Exception:
            snap_one = None
        if isinstance(snap_one, dict) and snap_one:
            try:
                merged_snap = _snapshot_merge_coin_positions(current_snap or {}, snap_one, [_coin])
                try:
                    if bool(refresh_indicators):
                        merged_snap = _snapshot_merge_coin_indicators(merged_snap, snap_one, [_coin])
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_637', _e)
                    pass
                try:
                    _exp = {str(c or '').upper().strip() for c in (_coins or []) if str(c or '').strip()}
                    _base_coins = set()
                    try:
                        _bc = (current_snap or {}).get('coins') or {}
                        if isinstance(_bc, dict):
                            _base_coins = {str(x or '').upper().strip() for x in _bc.keys() if str(x or '').strip()}
                    except Exception:
                        _base_coins = set()
                    _base_full = bool(_exp) and bool(_base_coins) and _exp.issubset(_base_coins)
                    _m = merged_snap.get('meta') if isinstance(merged_snap, dict) else None
                    if not isinstance(_m, dict):
                        _m = {}
                    _m['scope'] = 'global' if _base_full else 'local'
                    _m['scan_scope'] = _m['scope']
                    _m['allow_commit_global'] = True if _base_full else False
                    _m['reason'] = str(reason or 'POST_EXEC_TARGET_REFRESH')[:180]
                    merged_snap['meta'] = _m
                    merged_snap['scan_scope'] = _m['scope']
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_638', _e)
                    pass
                return merged_snap
            except Exception:
                return snap_one
        if not allow_full_fallback:
            return current_snap if isinstance(current_snap, dict) else snap_one
    if allow_full_fallback and _coins:
        try:
            return _m2_scan_cached(cdp, _coins, logfp, reason=str(reason or 'TARGET_REFRESH_ALL'), force=True, decision_needed=True, pending_len=0, only_positions=True, ind_mode='off', scan_scope='local')
        except Exception:
            return current_snap if isinstance(current_snap, dict) else None
    return current_snap if isinstance(current_snap, dict) else None

def _snapshot_refresh_fullscan(cdp: str, current_snap: dict | None, coins: list[str] | None, logfp: str, *, reason: str = '', force: bool = False, only_positions: bool = True, refresh_indicators: bool = False, strict_fresh_positions: bool = False) -> dict | None:
    """爸爸口径：交易主链刷新一律走全量扫描，不允许单币轻量刷新冒充全量。"""
    try:
        _coins = [str(c or '').upper().strip() for c in (coins or []) if str(c or '').strip()]
    except Exception:
        _coins = []
    if not _coins:
        try:
            _src = (current_snap or {}).get('coins') or {}
            if isinstance(_src, dict):
                _coins = [str(c or '').upper().strip() for c in _src.keys() if str(c or '').strip()]
        except Exception:
            _coins = []
    if not _coins:
        return current_snap if isinstance(current_snap, dict) else None
    try:
        snap_all = _m2_scan_cached(
            cdp,
            _coins,
            logfp,
            reason=str(reason or 'FULLSCAN_REFRESH'),
            force=bool(force),
            decision_needed=True,
            pending_len=0,
            only_positions=(False if bool(refresh_indicators) else bool(only_positions)),
            ind_mode=('force' if bool(refresh_indicators) else 'off'),
            scan_scope='global',
            strict_fresh_positions=bool(strict_fresh_positions),
            strict_latest_only=bool(strict_fresh_positions),
        )
    except Exception:
        snap_all = None
    if isinstance(snap_all, dict) and snap_all:
        try:
            _m = snap_all.get('meta') if isinstance(snap_all, dict) else None
            if not isinstance(_m, dict):
                _m = {}
            _m['scope'] = 'global'
            _m['scan_scope'] = 'global'
            _m['allow_commit_global'] = True
            _m['reason'] = str(reason or 'FULLSCAN_REFRESH')[:180]
            _m['strict_fresh_positions'] = bool(strict_fresh_positions)
            _m['strict_latest_only'] = bool(strict_fresh_positions)
            snap_all['meta'] = _m
            snap_all['scan_scope'] = 'global'
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_638a', _e)
            pass
        return snap_all
    return current_snap if isinstance(current_snap, dict) else None

def _contract_self_check() -> None:
    """启动即自检：发现签名漂移/缺失关键参数，宁可 fail-fast 也不要带病跑真钱。"""
    try:
        import inspect as _inspect
    except Exception as _e:
        print(f"[PIN][CONTRACT][WARN] inspect_import_failed: {_e}")
        return

    issues = []
    try:
        sig = _inspect.signature(_in_tp_lock)
        if "now_ts_s" not in sig.parameters:
            issues.append("_in_tp_lock missing param now_ts_s")
    except Exception as _e:
        issues.append(f"_in_tp_lock signature check failed: {_e}")

    try:
        sig = _inspect.signature(m2_scan)
        p = sig.parameters
        if "only_positions" not in p:
            issues.append("m2_scan missing kw only_positions (need compat)")
        if "reason" not in p:
            issues.append("m2_scan missing kw reason (need compat)")
        if "scan_scope" not in p:
            issues.append("m2_scan missing kw scan_scope (need compat)")
        try:
            _probe_filt, _probe_dropped = _legacy_compat_filter_kwargs(m2_scan, {"scan_scope": "local", "reason": "contract_probe", "force_reload_n": 2}, logfp=os.devnull, fn_name='m2_scan')
            if "scan_scope" in list(_probe_dropped or []):
                issues.append("m2_scan compat drops critical kw scan_scope")
            if "force_reload_n" in list(_probe_dropped or []):
                issues.append("m2_scan compat drops critical kw force_reload_n")
            if str((_probe_filt or {}).get("scan_scope") or "") != "local":
                issues.append("m2_scan compat lost scan_scope payload")
            if int((_probe_filt or {}).get("force_reload_n") or 0) != 2:
                issues.append("m2_scan compat lost force_reload_n payload")
        except Exception as _e:
            issues.append(f"m2_scan scan_scope compat check failed: {_e}")
    except Exception as _e:
        issues.append(f"m2_scan signature check failed: {_e}")

    if issues:
        msg = "[PIN][CONTRACT][FAIL] " + "; ".join(issues)
        try:
            print(msg)
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_639', _e)
            pass
        try:
            ADAPTER.append_telemetry({"event": "contract_fail", "issues": issues})
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_640', _e)
            pass
        if str(os.environ.get("ALLOW_CONTRACT_DEGRADED", "0")).strip() != "1":
            raise RuntimeError(msg)
        else:
            try:
                print("[PIN][CONTRACT][DEGRADED] ALLOW_CONTRACT_DEGRADED=1 -> continue")
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_641', _e)
                pass
    else:
        try:
            print("[PIN][CONTRACT][OK] core signatures healthy")
            try:
                print(f"[PIN][CONTRACT][SIG] _in_tp_lock={_inspect.signature(_in_tp_lock)}")
                print(f"[PIN][CONTRACT][SIG] m2_scan={_inspect.signature(m2_scan)}")
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_642', _e)
                pass
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_643', _e)
            pass

def _ensure_global(name: str, value) -> None:
    try:
        if name not in globals():
            globals()[name] = value
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

if 'rand_delay' not in globals():
    def rand_delay(lo: float, hi: float, seed=None) -> float:
        try:
            lo_f = float(lo); hi_f = float(hi)
            if seed is not None:
                _rnd = random.Random(seed)
                return float(_rnd.uniform(lo_f, hi_f))
            return float(random.uniform(lo_f, hi_f))
        except Exception:
            try:
                return float(lo)
            except Exception:
                return 0.0
    _ensure_global('rand_delay', rand_delay)

if 'rand_amount' not in globals():
    _LAST_RAND_AMOUNT = {}  # key -> last_int_u
    _RAND_RNG_CACHE = {}    # (key, seed) -> random.Random

    def _get_rng(seed, key: str):
        if seed is None:
            return random
        sk = (str(key), str(seed))
        rng = _RAND_RNG_CACHE.get(sk)
        if rng is None:
            rng = random.Random(seed)
            _RAND_RNG_CACHE[sk] = rng
        return rng

    def rand_amount(lo_u: float, hi_u: float, step: float = 10.0, seed=None, key: str = 'DEFAULT') -> int:
        """返回整数金额（U），范围 [lo_u, hi_u]，按 step（步长）对齐；尽量避免同 key 连续重复。
        关键修复：
        - 不能在每次重抽时 random.Random(seed) 重新初始化，否则会永远抽到同一个值（你遇到的连续 50U）。
        - 使用 (key, seed) 级别的 RNG（随机数发生器）缓存，保证同一条序列能前进。
        """
        try:
            lo_f = float(lo_u); hi_f = float(hi_u)
            if hi_f < lo_f:
                lo_f, hi_f = hi_f, lo_f
            step_f = float(step) if float(step) > 0 else 1.0

            rng = _get_rng(seed, key)

            def _pick_once() -> int:
                raw = float(rng.uniform(lo_f, hi_f))
                q = raw / step_f
                if q >= 0:
                    pick_i = int(math.floor(q + 0.5) * step_f)
                else:
                    pick_i = int(math.ceil(q - 0.5) * step_f)
                lo_i = int(math.ceil(lo_f / step_f) * step_f)
                hi_i = int(math.floor(hi_f / step_f) * step_f)
                return int(max(lo_i, min(pick_i, hi_i)))

            pick = _pick_once()

            last = _LAST_RAND_AMOUNT.get(key)
            if last is not None and int(pick) == int(last):
                for _ in range(6):
                    pick2 = _pick_once()
                    if int(pick2) != int(last):
                        pick = pick2
                        break
                if int(pick) == int(last):
                    try:
                        pick = int(pick) + int(step_f)
                        lo_i = int(math.ceil(lo_f / step_f) * step_f)
                        hi_i = int(math.floor(hi_f / step_f) * step_f)
                        if pick > hi_i:
                            pick = lo_i
                        if pick < lo_i:
                            pick = lo_i
                    except Exception as _e:
                        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

            _LAST_RAND_AMOUNT[key] = int(pick)
            return int(pick)
        except Exception:
            try:
                return int(float(lo_u))
            except Exception:
                return 0

    _ensure_global('rand_amount', rand_amount)

if '_half_up_round' not in globals():
    def _half_up_round(x: float, step: float) -> float:
        try:
            x_f = float(x); step_f = float(step)
            if step_f == 0:
                return x_f
            q = x_f / step_f
            if q >= 0:
                return float(math.floor(q + 0.5) * step_f)
            else:
                return float(math.ceil(q - 0.5) * step_f)
        except Exception:
            try:
                return float(x)
            except Exception:
                return 0.0
    _ensure_global('_half_up_round', _half_up_round)

if '_json_sanitize' not in globals():
    def _json_sanitize(obj):
        """把任意对象变成可 JSON 序列化的结构，并强制清理 NaN/Inf，避免 json.dump(allow_nan=False) 写到一半报错，
        进而导致 positions.json / equity.json 偶发成为半截文件（面板 JSONDecodeError line=1 col=2）。"""
        try:
            if obj is None:
                return None

            if isinstance(obj, bool):
                return bool(obj)
            if isinstance(obj, int):
                return int(obj)
            if isinstance(obj, float):
                try:
                    import math as _math
                    if not _math.isfinite(obj):
                        return None
                except Exception:
                    s = str(obj).lower()
                    if "nan" in s or "inf" in s:
                        return None
                return float(obj)
            if isinstance(obj, str):
                return obj

            try:
                if hasattr(obj, "__float__") and (type(obj).__name__.lower().find("float") >= 0 or type(obj).__name__.lower().find("decimal") >= 0):
                    fv = float(obj)
                    try:
                        import math as _math
                        if not _math.isfinite(fv):
                            return None
                    except Exception:
                        s = str(fv).lower()
                        if "nan" in s or "inf" in s:
                            return None
                    return fv
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_644', _e)
                pass
            if isinstance(obj, (list, tuple)):
                return [_json_sanitize(x) for x in obj]
            if isinstance(obj, dict):
                return {str(k): _json_sanitize(v) for k, v in obj.items()}

            if isinstance(obj, datetime):
                return obj.isoformat()
            if isinstance(obj, Path):
                return str(obj)
            if isinstance(obj, set):
                return [_json_sanitize(x) for x in list(obj)]

            return str(obj)
        except Exception:
            try:
                return str(obj)
            except Exception:
                return None
    _ensure_global('_json_sanitize', _json_sanitize)

