if '_apply_profile_from_ctl_state' not in globals():
    def _apply_profile_from_ctl_state(_state=None) -> dict:
        try:
            st = dict(_state or {}) if isinstance(_state, dict) else {}
        except Exception:
            st = {}
        try:
            prof = str(st.get('profile') or st.get('mode_profile') or st.get('risk_profile') or '').strip().lower()
        except Exception:
            prof = ''
        params = st.get('params') or st.get('profile_params') or {}
        if not prof:
            return {'ok': True, 'applied': False, 'reason': 'profile_missing'}
        if prof not in ('defensive', 'normal', 'aggressive'):
            return {'ok': True, 'applied': False, 'reason': 'profile_invalid', 'profile': prof}
        try:
            seq = int(st.get('seq') or st.get('profile_seq') or st.get('cmd_seq') or time.time())
        except Exception:
            seq = int(time.time())
        try:
            last_seq = int(globals().get('_PROFILE_LAST_APPLIED_SEQ') or 0)
        except Exception:
            last_seq = 0
        try:
            cur_prof = str(globals().get('ACTIVE_PROFILE') or 'normal').strip().lower()
        except Exception:
            cur_prof = 'normal'
        try:
            cur_params = dict(globals().get('ACTIVE_PROFILE_PARAMS') or {})
        except Exception:
            cur_params = {}
        try:
            req_params = dict(params or {}) if isinstance(params, dict) else {}
        except Exception:
            req_params = {}
        if seq < last_seq:
            return {'ok': True, 'applied': False, 'reason': 'profile_seq_stale', 'seq': seq, 'last_seq': last_seq}
        if seq == last_seq and cur_prof == prof and cur_params == req_params:
            return {'ok': True, 'applied': False, 'reason': 'profile_already_applied', 'profile': prof, 'seq': seq}
        rep = _apply_profile(prof, seq=seq, params=req_params)
        if isinstance(rep, dict):
            rep.setdefault('ok', True)
            rep['applied'] = True
            rep['reason'] = rep.get('reason') or 'profile_applied'
            return rep
        return {'ok': True, 'applied': True, 'profile': prof, 'seq': seq, 'reason': 'profile_applied'}
    _ensure_global('_apply_profile_from_ctl_state', _apply_profile_from_ctl_state)

if 'setup_console_txt_tee' not in globals():
    def setup_console_txt_tee(_logs_dir: str) -> None:
        try:
            if getattr(sys, '_bot_console_tee_installed', False):
                return
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

        try:
            os.makedirs(str(_logs_dir), exist_ok=True)
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

        paths = []
        try:
            ld = str(_logs_dir or '').strip()
            if ld:
                paths.append(os.path.join(ld, 'bot_console.log'))
                paths.append(os.path.join(ld, 'bot_console.txt'))
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

        try:
            od = globals().get('OUT_DIR', None)
            if od:
                od = str(od)
                try:
                    os.makedirs(od, exist_ok=True)
                except Exception as _e:
                    _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

                paths.append(os.path.join(od, 'bot_console.log'))
                paths.append(os.path.join(od, 'bot_console.txt'))
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

        uniq = []
        seen = set()
        for p in paths:
            try:
                ap = os.path.abspath(str(p))
            except Exception:
                ap = str(p)
            if ap in seen:
                continue
            seen.add(ap)
            uniq.append(ap)
        paths = uniq

        fhs = []
        for p in paths:
            try:
                try:
                    _rotate_existing_logfile(p)
                except Exception as _e:
                    _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

                fh = safe_open(p, mode='a', encoding='utf-8', errors='ignore', buffering=1)
                fhs.append(fh)
            except Exception:
                continue

        if not fhs:
            try:
                sys._bot_console_tee_installed = True  # type: ignore
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

            return

        import io, threading, atexit
        lock = threading.Lock()
        last = {'ts': 0.0}

        def _fsync_throttle():
            try:
                now = time.time()
                if now - float(last.get('ts', 0.0)) < 0.5:
                    return
                for fh in list(fhs):
                    try:
                        os.fsync(fh.fileno())
                    except Exception as _e:
                        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

                last['ts'] = now
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

        class _Tee(io.TextIOBase):
            def __init__(self, base_stream):
                super().__init__()
                self._base = base_stream

            @property
            def encoding(self):  # type: ignore
                return 'utf-8'

            @property
            def errors(self):  # type: ignore
                return 'ignore'

            def writable(self):  # type: ignore
                return True

            def write(self, s):  # type: ignore
                if s is None:
                    return 0
                try:
                    txt = str(s)
                except Exception:
                    txt = ''
                if txt == '':
                    return 0
                with lock:
                    try:
                        self._base.write(txt)
                    except Exception as _e:
                        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

                    try:
                        self._base.flush()
                    except Exception as _e:
                        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

                    for fh in list(fhs):
                        try:
                            fh.write(txt)
                        except Exception as _e:
                            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

                    for fh in list(fhs):
                        try:
                            fh.flush()
                        except Exception as _e:
                            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

                    _fsync_throttle()
                return len(txt)

            def flush(self):  # type: ignore
                with lock:
                    try:
                        self._base.flush()
                    except Exception as _e:
                        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

                    for fh in list(fhs):
                        try:
                            fh.flush()
                        except Exception as _e:
                            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

                    _fsync_throttle()

            def isatty(self):  # type: ignore
                return False

        try:
            base_out = sys.stdout
            base_err = sys.stderr
            sys.stdout = _Tee(base_out)  # type: ignore
            sys.stderr = _Tee(base_err)  # type: ignore
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

        def _close_all():
            try:
                for fh in list(fhs):
                    try:
                        fh.flush()
                    except Exception as _e:
                        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

                    try:
                        os.fsync(fh.fileno())
                    except Exception as _e:
                        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

                    try:
                        fh.close()
                    except Exception as _e:
                        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

        try:
            atexit.register(_close_all)
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

        try:
            sys._bot_console_tee_installed = True  # type: ignore
            sys._bot_console_tee_paths = list(paths)  # type: ignore
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    _ensure_global('setup_console_txt_tee', setup_console_txt_tee)

