def _log_should_route_to_machine(path: str) -> bool:
    try:
        name = str(Path(str(path or '')).name).lower()
    except Exception:
        name = str(path or '').lower()
    if not name:
        return False
    keep_names = {
        MACHINE_DEBUG_LOG_BASENAME.lower(),
        'trades.jsonl',
        'positions.json',
        'equity.json',
        'status.json',
        'control.json',
        GRID_DATA_LOG_BASENAME.lower(),
        'grid_rate_pause_ledger.json',
        'go_baocuo.txt',
        'bot_error.txt',
    }
    if name in keep_names:
        return False
    noisy_suffixes = ('.jsonl', '.log', '.txt')
    noisy_names = {
        'full_all.jsonl', 'bot_grid_full.jsonl', 'bot_grid_full.txt', 'executor_results.jsonl',
        'exec_results.jsonl', 'telemetry.jsonl', 'm9_reason_rank.jsonl', 'bot_run.jsonl',
        'panel_spawn_stdout.txt', 'bot_console.txt', 'bot_console.log', 'trace_events.jsonl',
        'module_m9.jsonl', 'm9_grid_ledger.jsonl', 'round_summary.jsonl', 'round_priority_rank.jsonl',
    }
    if name in noisy_names:
        return True
    return name.endswith(noisy_suffixes) and ('grid' not in name or 'bot_grid_full' in name)

def _route_log_path(path: str) -> str:
    try:
        if _log_should_route_to_machine(path):
            return _machine_debug_log_fp()
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_656', _e)
        pass
    return str(path)

