if "write_jsonl" not in globals():
    def write_jsonl(path: str, obj: dict, ensure_dir: bool = True) -> bool:
        """Append one JSON line. Never raise."""
        try:
            dst_path = _route_log_path(path)
            p = Path(dst_path)
            if ensure_dir:
                p.parent.mkdir(parents=True, exist_ok=True)
            line = _json_dumps_bot(obj, separators=(",", ":")) + "\n"
            with p.open("a", encoding="utf-8", buffering=1) as f:
                f.write(line)
                try:
                    f.flush()
                except Exception as _e:
                    _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

            try:
                _ensure_full_jsonl_ready()
                if _FULL_JSONL_FP and str(p) != str(_FULL_JSONL_FP):
                    try:
                        pobj = dict(obj) if isinstance(obj, dict) else {"_obj": obj}
                        pobj["_src"] = str(path)
                        line2 = json.dumps(pobj, ensure_ascii=False, separators=(",", ":")) + "\n"
                        with Path(_FULL_JSONL_FP).open("a", encoding="utf-8", buffering=1) as f2:
                            f2.write(line2)
                    except Exception as _e:
                        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

            return True
        except Exception:
            return False

