def _user_cfg_path() -> str:
    try:
        p = str(os.environ.get("BOT_USER_CFG_PATH") or "").strip()
    except Exception:
        p = ""
    if p:
        return p
    try:
        here = os.path.dirname(os.path.abspath(__file__))
    except Exception:
        here = "."
    return os.path.join(here, "bot_user_cfg.json")

def _clamp(v: float, lo: float, hi: float) -> float:
    try:
        v = float(v)
    except Exception:
        v = float(lo)
    if v < lo:
        return float(lo)
    if v > hi:
        return float(hi)
    return float(v)

def _load_user_cfg_file() -> dict:
    fp = _user_cfg_path()
    try:
        raw = safe_read_json(fp, default={})
    except FileNotFoundError:
        return {}
    except Exception as e:
        try:
            print(f"[CFG（配置）] 读取失败 | fp={fp} err（错误）={repr(e)}")
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

        return {}
    if not isinstance(raw, dict):
        return {}
    out = {}
    for k, v in raw.items():
        if k not in BOT_USER_CFG_DEFAULT:
            continue
        try:
            lo, hi = BOT_USER_CFG_RANGES.get(k, (None, None))
            if lo is not None and hi is not None:
                out[k] = _clamp(float(v), float(lo), float(hi))
            else:
                out[k] = float(v)
        except Exception:
            continue
    return out

def _merge_user_cfg() -> dict:
    cfg = dict(BOT_USER_CFG_DEFAULT)
    cfg.update(_load_user_cfg_file())
    return cfg

USER_CFG: dict = _merge_user_cfg()

def cfg_getf(key: str, default: float) -> float:
    try:
        return float(USER_CFG.get(key, default))
    except Exception:
        return float(default)

def cfg_geti(key: str, default: int) -> int:
    try:
        v = USER_CFG.get(key, default)
        if isinstance(v, bool):
            return int(v)
        if isinstance(v, (int, float)):
            return int(v)
        s = str(v).strip().lower()
        if s in ("true", "t", "yes", "y", "on"):
            return 1
        if s in ("false", "f", "no", "n", "off"):
            return 0
        return int(float(s))
    except Exception:
        return int(default)

def cfg_getb(key: str, default: bool) -> bool:
    try:
        v = USER_CFG.get(key, default)
        if isinstance(v, bool):
            return bool(v)
        if isinstance(v, (int, float)):
            return bool(int(v))
        s = str(v).strip().lower()
        if s in ("true", "t", "yes", "y", "on", "1"):
            return True
        if s in ("false", "f", "no", "n", "off", "0"):
            return False
        return bool(default)
    except Exception:
        return bool(default)

def _cfg_alias_key_m9(key: str) -> str:
    """M9 配置键别名：支持新键与旧键互通（旧键在代码里动态拼接，避免视觉混淆）。"""
    try:
        k = str(key or "")
        _P_M9 = "M9_"
        _P_OLD = "M9" + "X_"
        if k.startswith(_P_OLD):
            return _P_M9 + k[len(_P_OLD):]
        if k.startswith(_P_M9):
            return _P_OLD + k[len(_P_M9):]
        return ""
    except Exception:
        return ""

def cfg_getf_m9(key: str, default: float) -> float:
    try:
        if key in USER_CFG:
            return cfg_getf(key, default)
        k2 = _cfg_alias_key_m9(key)
        if k2 and (k2 in USER_CFG):
            return cfg_getf(k2, default)
        return float(default)
    except Exception:
        return float(default)

