def emit_module_observe(module_name: str, coins: list[str], snapshot: dict, _mark: int, probe_events: list[dict], report_extra: dict | None = None) -> None:
    """在“决策阶段”输出单模块 8 币汇总（不改策略，只增强可读性）。

    - 这里没有执行器结果，因此 exec_recs 传空；
    - 主要靠 probe_events（探针事件）显示 ENQUEUED（已入队）/ REJECT（拒绝）
    - 对无探针事件的币，t_no_request 已另行逐币打印 NO_REQUEST。
    """
    if not VERBOSE_MODULE_TRACE:
        return
    try:
        try:
            coins_sorted = _sorted_coins_by_notional(snapshot, coins)
        except Exception:
            coins_sorted = list(coins)

        lines = _build_module_report_lines(
            str(module_name or ''),
            snapshot,
            coins_sorted,
            exec_recs=[],
            probe_events=(probe_events or []),
            report_extra=(report_extra if isinstance(report_extra, dict) else None),
        )

        cprint("")
        safe_log(lambda: f"==== 模块可观测汇总（{module_name}） ====")
        for ln in lines:
            cprint(ln)
        safe_log(lambda: f"==== 结束（{module_name}） ====")
        cprint("")
    except Exception:
        return

def _trace_kv_str(kv: dict) -> str:
    try:
        s = json.dumps(kv, ensure_ascii=False, separators=(",", ":"), default=str)
    except Exception:
        try:
            s = str(kv)
        except Exception:
            s = ""
    if len(s) > _TRACE_JSON_MAXLEN:
        s = s[:_TRACE_JSON_MAXLEN] + "...(truncated)"
    return s

def tprint(mod: str, coin: str|None=None, step: str|None=None, **kv: Any) -> None:
    if not VERBOSE_MODULE_TRACE:
        return
    if step is None:
        if coin is not None:
            kv.setdefault('msg', coin)
        coin = '-'
        step = 'MSG'
    kv.pop("coin", None)  # 避免 coin（币种）重复传参导致 TypeError（类型错误）
    _coin = (coin or "-")
    line = f"[{now_ts()}] [TRACE] mod={mod} coin={_coin} step={step}"
    if kv:
        line += " " + _trace_kv_str(kv)
    cprint(line)

def tprobe(mod: str, events: list[dict]) -> None:
    if not VERBOSE_MODULE_TRACE:
        return
    if not events:
        safe_log(lambda: f"[{now_ts()}] [TRACE] mod={mod} probe_events=0")
        return
    safe_log(lambda: f"[{now_ts()}] [TRACE] mod={mod} probe_events={len(events)}")
    for e in events:
        try:
            ok = bool(e.get("ok"))
            tag = "ACCEPT" if ok else "REJECT"
            rr = str(e.get("reject_reason") or "").strip()
            if (not ok) and (not rr):
                rr = f"EMPTY_REJECT_REASON stage={e.get('stage')} code={e.get('reject_code')}"
                try:
                    write_jsonl(DEFAULT_LOGFP, {"ts": now_ts(), "mod": "TRACE", "type": "empty_reject_reason", "module": mod, "event": e, "filled": rr})
                except Exception as _e:
                    _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

            line = {
                "stage": e.get("stage"),
                "module": e.get("module"),
                "coin": e.get("coin"),
                "platform": e.get("platform"),
                "action_type": e.get("action_type"),
                "intent_amount": e.get("intent_amount"),
                "std_amount": e.get("std_amount"),
                "reject_code": e.get("reject_code"),
                "reject_reason": rr,
            }
            safe_log(lambda: f"[{now_ts()}] [TRACE] mod={mod} {tag} " + _trace_kv_str(line))
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

def _coin_basic_metrics(snap: dict, coin: str) -> dict:
    out = {}
    try:
        co = ((snap.get("coins") if isinstance(snap, dict) else {}) or {}).get(coin) or {}
        ext = co.get("ext") or {}
        var = co.get("var") or {}
        out.update({
            "ext_has": bool(ext.get("has_position")),
            "ext_side": ext.get("side"),
            "ext_val": ext.get("value_usd") if ext.get("value_usd") is not None else ext.get("notional_u"),
            "ext_upnl": ext.get("upnl_usd") if ext.get("upnl_usd") is not None else ext.get("upnl_u"),
            "var_has": bool(var.get("has_position")),
            "var_side": var.get("side"),
            "var_val": var.get("value_usd") if var.get("value_usd") is not None else var.get("notional_u"),
            "var_upnl": var.get("upnl_usd") if var.get("upnl_usd") is not None else var.get("upnl_u"),
        })
        out["diff_abs"] = abs(float(out.get("ext_val") or 0.0) - float(out.get("var_val") or 0.0))
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    return out

def _snap_get_rsi(_snap: dict | None, _coin: str) -> float | None:
    """从 snapshot 中尽力提取 RSI（B1/旧补腿链/W1/X1/M9 等统一取值口径的轻量 helper）。"""
    try:
        if not isinstance(_snap, dict):
            return None
        cu = str(_coin or "").upper().strip()
        co = ((_snap.get("coins") or {}).get(cu) or {}) if isinstance(_snap.get("coins"), dict) else {}
        for kk in ("rsi", "RSI", "rsi14", "rsi_14"):
            v = co.get(kk)
            if v not in (None, "", 0, 0.0):
                try:
                    return float(v)
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_670', _e)
                    pass
        for sk in ("ind", "inds", "indicator", "indicators", "tv", "ta", "meta"):
            sub = co.get(sk) if isinstance(co.get(sk), dict) else None
            if not isinstance(sub, dict):
                continue
            for kk in ("rsi", "RSI", "rsi14", "rsi_14"):
                v = sub.get(kk)
                if v not in (None, "", 0, 0.0):
                    try:
                        return float(v)
                    except Exception as _e:
                        _record_swallowed_exception('except_pass_line_671', _e)
                        pass
        inds = _snap.get("inds") or _snap.get("indicators") or {}
        if isinstance(inds, dict):
            sub2 = inds.get(cu)
            if isinstance(sub2, dict):
                for kk in ("rsi", "RSI", "rsi14", "rsi_14"):
                    v = sub2.get(kk)
                    if v not in (None, "", 0, 0.0):
                        try:
                            return float(v)
                        except Exception as _e:
                            _record_swallowed_exception('except_pass_line_672', _e)
                            pass
        return None
    except Exception:
        return None

