def _m9_norm_u_tens(u: float, lo: float = 0.0, hi: float = 0.0) -> float:
    """[HARD] 映射金额=最终下单金额：禁用取整/禁用强制上下限
    仅做最基本的 float 转换；非法则返回 0。
    """
    try:
        u = float(u)
    except Exception:
        return 0.0
    if (not math.isfinite(u)) or u <= 0.0:
        return 0.0
    return float(u)

