def _m9_snapshot_positions_nonempty(snapshot: dict, coins: list | None = None) -> bool:
    try:
        coin_set = {str(c or '').upper().strip() for c in (coins or []) if str(c or '').strip()}
    except Exception:
        coin_set = set()
    try:
        for _plat, _pm in (_pos_root(snapshot or {}) or {}).items():
            if not isinstance(_pm, dict):
                continue
            for _coin, _pos in _pm.items():
                _cu = str(_coin or '').upper().strip()
                if coin_set and _cu not in coin_set:
                    continue
                if not isinstance(_pos, dict):
                    continue
                try:
                    if bool(_pos.get('has_position')):
                        return True
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_721', _e)
                    pass
                try:
                    _nu = abs(float(_pos.get('notional_u') or _pos.get('value_u') or _pos.get('notional') or _pos.get('notional_usd') or _pos.get('value_usd') or 0.0))
                    if _nu > 1e-9:
                        return True
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_722', _e)
                    pass
        return False
    except Exception:
        return False

def _m9_payload_has_meaningful_rows(payload: dict | None) -> bool:
    try:
        entries = list((payload or {}).get('entries') or [])
    except Exception:
        entries = []
    for e in entries:
        if not isinstance(e, dict):
            continue
        try:
            if bool(e.get('has_position')):
                return True
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_723', _e)
            pass
        try:
            if int(e.get('layers_open_cnt') or 0) > 0:
                return True
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_724', _e)
            pass
        try:
            if list(e.get('layers') or []):
                return True
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_725', _e)
            pass
        try:
            if list(e.get('plans') or []):
                return True
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_726', _e)
            pass
        try:
            if e.get('next_sell_tp_px') is not None or e.get('next_buy_px') is not None:
                return True
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_727', _e)
            pass
    return False

def _m9_safe_read_json_file(fp: str) -> dict:
    try:
        obj = safe_read_json(fp, default=None, retries=1)
        return obj if isinstance(obj, dict) else {}
    except Exception:
        return {}

def _m9_payload_is_synthetic_or_broken(payload: dict | None) -> bool:
    try:
        meta = dict((payload or {}).get('meta') or {}) if isinstance((payload or {}).get('meta'), dict) else {}
    except Exception:
        meta = {}
    try:
        if bool(meta.get('synthetic_from_summary')):
            return True
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_728', _e)
        pass
    try:
        entries = [e for e in list((payload or {}).get('entries') or []) if isinstance(e, dict)]
    except Exception:
        entries = []
    if not entries:
        return True
    good = 0
    broken = 0
    for e in entries:
        try:
            plat = str(e.get('platform') or '').upper().strip()
            gid = str(e.get('grid_id') or '').strip()
            layers = int(e.get('layers_open_cnt') or 0)
            has_tp = e.get('next_sell_tp_px') is not None
            has_buy = e.get('next_buy_px') is not None
            if plat in ('EXT', 'VAR') and gid and (layers > 0 or has_tp or has_buy):
                good += 1
            elif layers > 0 or has_tp or has_buy:
                broken += 1
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_729', _e)
            pass
    if good > 0:
        return False
    return broken > 0 or bool(_m9_master_book_nonempty())



def _m9_observe_payload_align_to_master_book(payload: dict | None) -> dict:
    """
    可观测导出只认主账本真相。
    作用：
    - 修正 live payload 因旧投影/旧缓存导致的 layers_open_cnt=0、冷启动绕过文案残留。
    - 保留本轮 final_reason / final_stage / final_verdict / plans 等运行信息。
    """
    try:
        base = dict(payload or {}) if isinstance(payload, dict) else {}
    except Exception:
        base = {}
    if not isinstance(base, dict):
        base = {}
    try:
        if not bool(_m9_master_book_nonempty()):
            return base
    except Exception:
        return base
    try:
        coins = []
        seen_coins = set()
        for _e in list(base.get('entries') or []):
            if not isinstance(_e, dict):
                continue
            _coin = str(_e.get('coin') or '').upper().strip()
            if _coin and _coin not in seen_coins:
                seen_coins.add(_coin)
                coins.append(_coin)
        rebuilt = _m9_rebuild_detail_payload_from_master_book(snapshot={}, payload=base, coins=coins or None)
    except Exception:
        return base
    rebuilt_entries = [dict(x) for x in list((rebuilt or {}).get('entries') or []) if isinstance(x, dict)]
    if not rebuilt_entries:
        return base
    orig_entries = [dict(x) for x in list(base.get('entries') or []) if isinstance(x, dict)]
    orig_by_key = {}
    for _e in orig_entries:
        _key = (str(_e.get('grid_id') or '').strip(), str(_e.get('platform') or '').upper().strip(), str(_e.get('coin') or '').upper().strip(), str(_e.get('side') or '').upper().strip())
        orig_by_key[_key] = dict(_e)
    keep_keys = {
        'final_reason', 'final_reason_code', 'final_stage', 'final_verdict', 'reason', 'reason_code',
        'detail_state', 'detail_reason', 'plans', 'plan_state', 'candidate_mode', 'selected',
        'trend_state', 'trend_side', 'trend_reason', 'trend_cover_ratio', 'trend_layers_open',
        'trend_layers_cap', 'freeze_loss_leg_new_grid', 'trend_same_notional_u', 'trend_opp_notional_u',
        'trend_same_upnl_u', 'trend_opp_upnl_u', 'gates', 'obs', 'observations', 'execution_evidence',
        'hardcap_precheck_reason', 'first_block_reason', 'first_block_reason_code', 'first_block_stage',
        'first_block_source', 'last_plan_reason', 'last_action', 'score', 'candidate', 'rank',
    }
    merged_entries = []
    seen_keys = set()
    repaired = 0
    for _re in rebuilt_entries:
        _key = (str(_re.get('grid_id') or '').strip(), str(_re.get('platform') or '').upper().strip(), str(_re.get('coin') or '').upper().strip(), str(_re.get('side') or '').upper().strip())
        _orig = dict(orig_by_key.get(_key) or {})
        _merged = dict(_re)
        for _k in keep_keys:
            try:
                _v = _orig.get(_k)
            except Exception:
                _v = None
            if _v not in (None, '', [], {}):
                _merged[_k] = _v
        _before_layers = 0
        try:
            _before_layers = int(_orig.get('layers_open_cnt') or 0)
        except Exception:
            _before_layers = 0
        try:
            _after_layers = int(_merged.get('layers_open_cnt') or 0)
        except Exception:
            _after_layers = 0
        _detail_reason = str(_merged.get('detail_reason') or '')
        if _after_layers > _before_layers:
            repaired += 1
        if _after_layers > 0 and 'cold_start_l2_immediate_gap_bypassed' in _detail_reason.lower():
            _merged['detail_reason'] = 'master_book_open_layers_restored（主账本已恢复真实开放层）'
        _merged['observe_truth_source'] = 'MASTER_BOOK'
        _merged['observe_truth_merged'] = True
        merged_entries.append(_merged)
        seen_keys.add(_key)
    for _orig in orig_entries:
        _key = (str(_orig.get('grid_id') or '').strip(), str(_orig.get('platform') or '').upper().strip(), str(_orig.get('coin') or '').upper().strip(), str(_orig.get('side') or '').upper().strip())
        if _key in seen_keys:
            continue
        _tail = dict(_orig)
        _tail['observe_truth_source'] = str(_tail.get('observe_truth_source') or 'LIVE_ONLY')
        merged_entries.append(_tail)
    base['entries'] = merged_entries
    base.setdefault('meta', {})
    if isinstance(base.get('meta'), dict):
        base['meta']['observe_truth_aligned_from_master_book'] = True
        base['meta']['observe_truth_repaired_entry_count'] = int(repaired)
    return base


def _m9_summary_repair_reason_leak(summary: dict | None, payload: dict | None = None) -> dict:
    """
    防止最终导出把真实故障洗成 no_request。
    仅修正“bare no_request”——没有显式 no_request 证据，但该币明明存在持仓/网格/价格触发上下文。
    """
    try:
        base = dict(summary or {}) if isinstance(summary, dict) else {}
    except Exception:
        base = {}
    rows = [dict(r) for r in list(base.get('rows') or []) if isinstance(r, dict)]
    if not rows:
        return base
    entry_map = {}
    try:
        for _e in list((payload or {}).get('entries') or []):
            if not isinstance(_e, dict):
                continue
            _coin = str(_e.get('coin') or '').upper().strip()
            if not _coin:
                continue
            entry_map.setdefault(_coin, []).append(dict(_e))
    except Exception:
        entry_map = {}
    repaired = 0
    new_rows = []
    for _r in rows:
        _ff = _final_fields_for_output(_r, default_reason='NO_REQUEST', default_stage=_entry_stage_view(_r, default='PLANNER'))
        _reason = _normalize_reason_code(_ff.get('final_reason_code') or _ff.get('final_reason') or _r.get('reason') or '')
        _plan_state = _normalize_reason_code(_r.get('plan_state') or '')
        _explicit_block = bool(str(_r.get('block_reason') or _r.get('detail_reason') or _r.get('first_block_reason') or _r.get('last_plan_reason') or '').strip())
        _coin = str(_r.get('coin') or '').upper().strip()
        _ents = list(entry_map.get(_coin) or [])
        _has_runtime_state = False
        for _e in _ents:
            try:
                if bool(_e.get('has_position')) or int(_e.get('layers_open_cnt') or 0) > 0 or _e.get('next_buy_px') is not None or _e.get('next_sell_tp_px') is not None:
                    _has_runtime_state = True
                    break
            except Exception:
                continue
        _looks_bare_no_request = (_reason in ('', 'no_request')) and (not _explicit_block) and (_plan_state in ('', 'init')) and (str(_r.get('candidate') or '').strip() == '')
        if _looks_bare_no_request and _has_runtime_state and int(_r.get('selected') or 0) != 1:
            _miss_reason, _miss_stage = _compose_internal_reason_missing(_r, None, default_stage='PLANNER')
            _r['final_reason_code'] = str(_miss_reason)
            _r['final_reason'] = str(_miss_reason)
            _r['reason_code'] = str(_miss_reason)
            _r['reason'] = str(_miss_reason)
            _r['final_stage'] = str(_miss_stage)
            _r['stage'] = str(_miss_stage)
            _r['final_verdict'] = 'REJECTED'
            _r['reason_source'] = 'final_export_reason_leak_guard'
            repaired += 1
        new_rows.append(_r)
    if repaired:
        skipped_rows = [r for r in new_rows if int(r.get('selected') or 0) != 1]
        reason_counter = {}
        for r in skipped_rows:
            rs = str(_final_fields_for_output(r, default_reason='NO_REQUEST', default_stage=_entry_stage_view(r, default='PLANNER')).get('final_reason') or r.get('reason') or 'UNKNOWN:missing_final_reason')
            reason_counter[rs] = int(reason_counter.get(rs, 0) or 0) + 1
        base['rows'] = new_rows
        base['top_final_reasons'] = [
            {'reason': str(k), 'count': int(v)}
            for k, v in sorted(reason_counter.items(), key=lambda kv: (-int(kv[1]), str(kv[0])))[:8]
        ]
        base.setdefault('meta', {})
        if isinstance(base.get('meta'), dict):
            base['meta']['reason_leak_repaired_count'] = int(repaired)
            base['meta']['reason_single_source_guard'] = True
    else:
        base['rows'] = new_rows
    return base
def _m9_rebuild_detail_payload_from_master_book(snapshot: dict | None = None, payload: dict | None = None, coins: list | None = None) -> dict:
    snapshot = dict(snapshot or {})
    base_payload = dict(payload or {}) if isinstance(payload, dict) else {}
    out = {
        'ts': float(base_payload.get('ts') or time.time()),
        'mod': 'M9',
        'type': 'detail_round',
        'dq': base_payload.get('dq', snapshot.get('dq')),
        'dq_reason': base_payload.get('dq_reason', snapshot.get('dq_reason')),
        'total_equity_u': float(base_payload.get('total_equity_u') or (_get_total_u(snapshot or {}) or 0.0)),
        'm9': dict(base_payload.get('m9') or {}),
        'summary': dict(base_payload.get('summary') or {}),
        'entries': [],
        'reject_hint': dict(base_payload.get('reject_hint') or {}),
        'obs_round': int(base_payload.get('obs_round') or globals().get('_M9_OBS_ROUND', 0) or 0),
        'final_record_source': 'MASTER_BOOK_REBUILD',
    }
    try:
        out['m9'].setdefault('rate_source', 'master_book_rebuild')
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_730', _e)
        pass
    data = _m9_master_book_data()
    grids = (data.get('grids') or {}) if isinstance(data, dict) else {}
    coin_allow = {str(c or '').upper().strip() for c in (coins or []) if str(c or '').strip()}
    entries = []
    for _gid, _g in grids.items():
        if not isinstance(_g, dict):
            continue
        coin = str(_g.get('coin') or '').upper().strip()
        plat = str(_g.get('platform') or '').upper().strip()
        side = str(_g.get('side') or '').upper().strip()
        if plat not in ('EXT', 'VAR') or side not in ('LONG', 'SHORT') or not coin:
            continue
        if coin_allow and coin not in coin_allow:
            pass
        layers_all = list(_g.get('layers') or []) if isinstance(_g.get('layers'), list) else []
        open_layers = []
        closed_layers = []
        valid_open_layers = []
        for _ly in layers_all:
            if not isinstance(_ly, dict):
                continue
            _lid = str(_ly.get('layer_id') or _ly.get('id') or '')
            try:
                if _m9_is_base_layer_id(_lid, _ly):
                    continue
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_731', _e)
                pass
            _st = str(_ly.get('status') or _ly.get('state') or '').upper().strip()
            if _st == 'OPEN':
                _cpy = dict(_ly)
                try:
                    _cpy.update(_m9_layer_gap_truth_backfill(_cpy, _g))
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_gap_truth_backfill_open', _e)
                open_layers.append(_cpy)
                if _m9_is_valid_native_grid_layer(_cpy):
                    valid_open_layers.append(dict(_cpy))
            else:
                _closed = dict(_ly)
                try:
                    _closed.update(_m9_layer_gap_truth_backfill(_closed, _g))
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_gap_truth_backfill_closed', _e)
                closed_layers.append(_closed)
        if not open_layers and not closed_layers:
            continue
        pos = _get_position(snapshot or {}, coin, plat) or {}
        has_pos = bool(pos.get('has_position')) or bool(_has_leg_u(pos_notional_u) and side in ('LONG', 'SHORT')) or bool(open_layers)
        pos_notional_u = _safe_float(pos.get('notional_u') or pos.get('value_usd'), 0.0)
        pos_upnl_u = _safe_float(pos.get('upnl_u') or pos.get('upnl_usd'), 0.0)
        cur_px = _safe_float(pos.get('mark') or pos.get('mark_px') or pos.get('mark_price') or pos.get('cur_px') or pos.get('px') or pos.get('last_px') or pos.get('last') or pos.get('price'), None)
        if cur_px is None:
            try:
                for _ly in reversed(open_layers or layers_all):
                    _meta = _ly.get('meta') if isinstance(_ly.get('meta'), dict) else {}
                    cur_px = _safe_float(_meta.get('cur_px') or _ly.get('cur_px') or _g.get('last_px') or _g.get('mark_px') or _g.get('start_px'), None)
                    if cur_px is not None:
                        break
            except Exception:
                cur_px = None
        if cur_px is None:
            cur_px = _safe_float(_g.get('start_px'), None)
        layers_detail = []
        sum_open_u = 0.0
        hit_layers = 0
        closest = None
        hit_best = None
        next_buy_base_px = None
        next_buy_gap_pct = None
        next_buy_gap_px = None
        next_buy_hit = False
        main_gap_pct = None
        main_gap_raw_pct = None
        grid_observe_cnt = _safe_float(_g.get('observe_cnt'), None)
        sorted_open = sorted(valid_open_layers, key=lambda x: (int(_safe_float(x.get('layer_no'), 0) or 0), float(_safe_float(x.get('open_ts'), 0.0) or 0.0), str(x.get('layer_id') or '')))
        for _ly in sorted_open:
            lid = str(_ly.get('layer_id') or _ly.get('id') or '')
            open_u = _safe_float(_ly.get('open_notional_u') or _ly.get('open_u'), 0.0)
            sum_open_u += float(open_u or 0.0)
            open_px = _m9_layer_truth_open_px(_ly, None)
            if open_px is None:
                open_px = _safe_float(_ly.get('open_ref_px') or _ly.get('open_px') or _g.get('start_px'), None)
            tp_px = _safe_float(_ly.get('tp_px'), None)
            if tp_px is None and open_px is not None:
                _tp_pct = _safe_float(_ly.get('tp_pct') or globals().get('M9_TP_PCT_MIN', None), None)
                try:
                    if _tp_pct is not None and side == 'LONG':
                        tp_px = float(open_px) * (1.0 + float(_tp_pct))
                    elif _tp_pct is not None and side == 'SHORT':
                        tp_px = float(open_px) * (1.0 - float(_tp_pct))
                except Exception:
                    tp_px = None
            _ly_gap_truth = _m9_layer_gap_truth_backfill(_ly, _g)
            try:
                _ly.update(_ly_gap_truth)
            except Exception:
                pass
            grid_pct = _safe_float((_ly_gap_truth or {}).get('gap_truth_pct') or _ly.get('grid_pct'), None)
            if grid_pct is not None:
                main_gap_pct = float(grid_pct) * 100.0
                _raw_gp = _safe_float((_ly_gap_truth or {}).get('gap_truth_raw_pct'), grid_pct)
                main_gap_raw_pct = float(_raw_gp) * 100.0
            hit = False
            gap_u = None
            gap_pct = None
            if cur_px is not None and tp_px is not None:
                try:
                    hit = bool(_m9_layer_hit(side, float(cur_px), float(tp_px)))
                    _gap = _m9_layer_gap(side, float(cur_px), float(tp_px)) or {}
                    gap_u = _gap.get('gap_u')
                    gap_pct = _gap.get('gap_pct')
                    if hit:
                        hit_layers += 1
                        if hit_best is None:
                            hit_best = (float(tp_px), lid)
                        elif side == 'LONG' and float(tp_px) > float(hit_best[0]):
                            hit_best = (float(tp_px), lid)
                        elif side == 'SHORT' and float(tp_px) < float(hit_best[0]):
                            hit_best = (float(tp_px), lid)
                    else:
                        gap_px_abs = abs(float(gap_u)) if gap_u is not None else None
                        gap_pct_abs = abs(float(gap_pct)) if gap_pct is not None else (abs(float(gap_u)) / abs(float(tp_px)) * 100.0 if (gap_u is not None and tp_px not in (None, 0)) else None)
                        if gap_pct_abs is not None:
                            tup = (float(gap_pct_abs), float(gap_px_abs or 0.0), float(tp_px), lid)
                            if (closest is None) or tup[0] < closest[0]:
                                closest = tup
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_732', _e)
                    pass
            layers_detail.append({
                'layer_id': lid,
                'layer_instance_id': str(_ly.get('layer_instance_id') or _ly.get('instance_id') or ''),
                'layer_tag': str(_ly.get('layer_tag') or _grid_layer_tag(lid) or ''),
                'layer_no': int(_safe_float(_ly.get('layer_no'), 0) or (_parse_layer_no(lid) or 0) or 0),
                'status': str(_ly.get('status') or _ly.get('state') or ''),
                'open_u': float(open_u or 0.0),
                'open_notional_u': float(open_u or 0.0),
                'remain_notional_u': float(open_u or 0.0),
                'open_ref_px': open_px,
                'open_px': open_px,
                'tp_px': tp_px,
                'age_sec': (max(0.0, out['ts'] - float(_safe_float(_ly.get('open_ts'), 0.0) or 0.0)) if _safe_float(_ly.get('open_ts'), None) else None),
                'hit': bool(hit),
                'gap_u': gap_u,
                'gap_pct': gap_pct,
                'grid_mode': _m9_layer_mode(_ly),
                'trend_state': str(_ly.get('trend_state') or ''),
                'profit_locked': int(bool(_ly.get('profit_locked'))),
                'partial_close_ratio': _safe_float(_ly.get('partial_close_ratio'), 0.0),
                'trail_anchor_px': _safe_float(_ly.get('trail_anchor_px'), None),
                'protect_px': _safe_float(_ly.get('protect_px'), None),
                'trend_close_reason': str(_ly.get('trend_close_reason') or _ly.get('close_reason') or ''),
                'note': _ly.get('note'),
                'grid_pct': grid_pct,
                'source': str(_ly.get('source') or ''),
                'source_module': str(_ly.get('source_module') or ''),
                'grid_owner_module': str(_ly.get('grid_owner_module') or ''),
                'owner_chain': str(_ly.get('owner_chain') or ''),
                'managed_by_grid': bool(_ly.get('managed_by_grid')),
                'can_tp_close': bool(_ly.get('can_tp_close')),
                'detail_state': ('OK' if bool(_ly.get('layer_instance_id') or _ly.get('instance_id') or lid) else 'LAYER_TRUTH_MISSING'),
                'gap_truth_pct': _safe_float((_ly_gap_truth or {}).get('gap_truth_pct'), None),
                'gap_truth_raw_pct': _safe_float((_ly_gap_truth or {}).get('gap_truth_raw_pct'), None),
                'gap_truth_source': str(((_ly_gap_truth or {}).get('gap_truth_source') or '')),
                'gap_truth_components': dict(((_ly_gap_truth or {}).get('gap_truth_components') or {})) if isinstance(((_ly_gap_truth or {}).get('gap_truth_components')), dict) else {},
            })
            next_buy_base_px = open_px if open_px is not None else next_buy_base_px
        next_sell_tp_px = None
        next_sell_layer_id = None
        next_sell_gap_pct = None
        next_sell_gap_px = None
        next_sell_hit = False
        next_sell_qty = None
        if hit_best is not None:
            next_sell_tp_px = float(hit_best[0])
            next_sell_layer_id = str(hit_best[1])
            next_sell_gap_pct = 0.0
            next_sell_gap_px = 0.0
            next_sell_hit = True
            next_sell_qty = _safe_float((_m9_find_layer_detail_by_id(layers_detail, next_sell_layer_id) or {}).get('open_u'), None)
        elif closest is not None:
            next_sell_gap_pct = float(closest[0])
            next_sell_gap_px = float(closest[1])
            next_sell_tp_px = float(closest[2])
            next_sell_layer_id = str(closest[3])
            next_sell_qty = _safe_float((_m9_find_layer_detail_by_id(layers_detail, next_sell_layer_id) or {}).get('open_u'), None)
        next_buy_px = None
        next_buy_px_range = None
        try:
            _need_px, _need_range, _need_det = _m9_calc_next_buy_gate(str(coin), str(_g.get('id') or ''), str(side), _safe_float(cur_px, None), list(sorted_open or []), rsi=None, adx=None, snapshot=snapshot or {})
            if _need_px is not None:
                next_buy_px = float(_need_px)
                next_buy_px_range = _need_range
        except Exception:
            next_buy_px = None
            next_buy_px_range = None
        if next_buy_px is None and next_buy_base_px is not None:
            try:
                _step = None
                for _ly in reversed(sorted_open):
                    _step = _safe_float(_ly.get('grid_pct'), None)
                    if _step is not None and float(_step) > 0:
                        break
                if _step is None:
                    _spr = _g.get('step_pct_range') if isinstance(_g.get('step_pct_range'), list) else []
                    _step = _safe_float((_spr[0] if _spr else None), None)
                if _step is not None and float(_step) > 0:
                    if side == 'LONG':
                        next_buy_px = float(next_buy_base_px) * (1.0 - float(_step))
                        if cur_px is not None:
                            next_buy_hit = float(cur_px) <= float(next_buy_px)
                    else:
                        next_buy_px = float(next_buy_base_px) * (1.0 + float(_step))
                        if cur_px is not None:
                            next_buy_hit = float(cur_px) >= float(next_buy_px)
                    if cur_px is not None and next_buy_px not in (None, 0):
                        next_buy_gap_px = abs(float(cur_px) - float(next_buy_px))
                        next_buy_gap_pct = abs(float(cur_px) - float(next_buy_px)) / abs(float(next_buy_px)) * 100.0
            except Exception:
                next_buy_px = None
        grid_realized_pnl_u = 0.0
        for _ly in list(valid_open_layers or []) + [x for x in list(closed_layers or []) if _m9_is_valid_native_grid_layer(x)]:
            if not isinstance(_ly, dict):
                continue
            try:
                grid_realized_pnl_u += float(_m9_layer_realized_total(_ly))
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_733', _e)
                pass
        grid_unreal_pnl_u = None
        grid_target_profit_u = None
        try:
            if cur_px is not None:
                _u_sum = 0.0
                _t_sum = 0.0
                for _ly in sorted_open:
                    ou = _safe_float(_ly.get('open_notional_u') or _ly.get('open_u'), 0.0)
                    opx = _m9_layer_truth_open_px(_ly, None)
                    if opx is None:
                        opx = _safe_float(_ly.get('open_ref_px') or _ly.get('open_px'), None)
                    tpx = _safe_float(_ly.get('tp_px'), None)
                    if ou <= 0 or opx is None or float(opx) <= 0:
                        continue
                    if side == 'LONG':
                        _u_sum += float(ou) * (float(cur_px) - float(opx)) / float(opx)
                        if tpx is not None:
                            _t_sum += float(ou) * (float(tpx) - float(opx)) / float(opx)
                    else:
                        _u_sum += -float(ou) * (float(cur_px) - float(opx)) / float(opx)
                        if tpx is not None:
                            _t_sum += -float(ou) * (float(tpx) - float(opx)) / float(opx)
                grid_unreal_pnl_u = float(_u_sum)
                grid_target_profit_u = float(_t_sum)
        except Exception:
            grid_unreal_pnl_u = None
            grid_target_profit_u = None
        grid_total_pnl_u = None
        if grid_unreal_pnl_u is not None:
            try:
                grid_total_pnl_u = float(grid_realized_pnl_u) + float(grid_unreal_pnl_u)
            except Exception:
                grid_total_pnl_u = None
        _entry_gap_truth = {}
        try:
            _entry_gap_layer = (sorted_open[-1] if sorted_open else (valid_open_layers[-1] if valid_open_layers else None))
            _entry_gap_truth = _m9_layer_gap_truth_backfill(_entry_gap_layer, _g)
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_entry_gap_truth', _e)
            _entry_gap_truth = {}
        if main_gap_pct is None:
            try:
                _gp = _safe_float((_entry_gap_truth or {}).get('gap_truth_pct'), None)
                if _gp is not None and float(_gp) > 0:
                    main_gap_pct = float(_gp) * 100.0
            except Exception:
                pass
        if main_gap_raw_pct is None:
            try:
                _grp = _safe_float((_entry_gap_truth or {}).get('gap_truth_raw_pct'), None)
                if _grp is None:
                    _grp = _safe_float((_entry_gap_truth or {}).get('gap_truth_pct'), None)
                if _grp is not None and float(_grp) > 0:
                    main_gap_raw_pct = float(_grp) * 100.0
            except Exception:
                pass
        entry = {
            'coin': coin,
            'platform': plat,
            'grid_id': str(_gid),
            'side': side,
            'has_position': bool(has_pos),
            'pos_notional_u': float(pos_notional_u or 0.0),
            'pos_upnl_u': float(pos_upnl_u or 0.0),
            'px': cur_px,
            'cur_px': cur_px,
            'layers_open_cnt': int(len(sorted_open)),
            'layers_hit_cnt': int(hit_layers),
            'bought_u_sum': float(sum_open_u or 0.0),
            'grid_open_u_sum': float(sum_open_u or 0.0),
            'base_position_u': max(0.0, float(pos_notional_u or 0.0) - float(sum_open_u or 0.0)),
            'non_grid_same_side_u': max(0.0, float(pos_notional_u or 0.0) - float(sum_open_u or 0.0)),
            'grid_realized_pnl_u': float(grid_realized_pnl_u or 0.0),
            'grid_unreal_pnl_u': grid_unreal_pnl_u,
            'grid_total_pnl_u': grid_total_pnl_u,
            'grid_target_profit_u': grid_target_profit_u,
            'next_sell_tp_px': next_sell_tp_px,
            'next_sell_gap_pct': next_sell_gap_pct,
            'next_sell_gap_px': next_sell_gap_px,
            'sell_tp_gap_pct': next_sell_gap_pct,
            'sell_tp_gap_px': next_sell_gap_px,
            'next_sell_hit': bool(next_sell_hit),
            'next_buy_px': next_buy_px,
            'next_buy_gap_pct': next_buy_gap_pct,
            'next_buy_gap_px': next_buy_gap_px,
            'next_buy_hit': bool(next_buy_hit),
            'gap_truth_pct': _safe_float((_entry_gap_truth or {}).get('gap_truth_pct'), None),
            'gap_truth_raw_pct': _safe_float((_entry_gap_truth or {}).get('gap_truth_raw_pct'), None),
            'gap_truth_source': str(((_entry_gap_truth or {}).get('gap_truth_source') or 'missing_gap_truth')),
            'gap_truth_components': dict(((_entry_gap_truth or {}).get('gap_truth_components') or {})) if isinstance(((_entry_gap_truth or {}).get('gap_truth_components')), dict) else {},
            'main_trigger_gap_pct': main_gap_pct,
            'main_trigger_gap_raw_pct': main_gap_raw_pct,
            'main_trigger_gap_px': (float(next_buy_base_px) * (float(main_gap_pct) / 100.0) if (next_buy_base_px is not None and main_gap_pct is not None) else None),
            'grid_observe_cnt': (int(grid_observe_cnt) if grid_observe_cnt is not None else None),
            'detail_state': 'OK',
            'detail_reason': '',
            'next_sell_layer_id': next_sell_layer_id,
            'layers': layers_detail[:50],
            'adx': _safe_float(pos.get('adx'), None),
            'rsi': _safe_float(pos.get('rsi'), None),
            'ind_reason': str(pos.get('ind_reason') or ''),
            'fallback_used': True,
            'fallback_source': 'MASTER_BOOK_REBUILD',
        }
        _detail_anchor_ids = []
        try:
            for _raw_ly in list(layers_all or []):
                if _m9_detail_anchor_only_dict(_raw_ly):
                    _detail_anchor_ids.append(str(_raw_ly.get('layer_id') or _raw_ly.get('id') or ''))
        except Exception:
            _detail_anchor_ids = []
        if int(len(sorted_open or [])) == 0 and float(_safe_float(pos_notional_u, 0.0) or 0.0) >= 10.0 and bool(_detail_anchor_ids):
            entry = _m9_detail_apply_cold_start_bypass(entry, same_side_pos_u=float(_safe_float(pos_notional_u, 0.0) or 0.0), expected_layer_no=2, anchor_layer_ids=_detail_anchor_ids)
        entries.append(entry)
    if (not entries) and coin_allow:
        return _m9_rebuild_detail_payload_from_master_book(snapshot=snapshot, payload={k: v for k, v in base_payload.items() if k != 'entries'}, coins=[])
    try:
        entries.sort(key=lambda x: (str(x.get('platform') or ''), str(x.get('coin') or ''), str(x.get('side') or '')))
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_734', _e)
        pass
    out['entries'] = entries
    out['summary']['rebuild_entry_cnt'] = int(len(entries))
    out['summary']['rebuild_open_grid_cnt'] = int(sum(1 for e in entries if int(e.get('layers_open_cnt') or 0) > 0))
    out['meta'] = dict(base_payload.get('meta') or {}) if isinstance(base_payload.get('meta'), dict) else {}
    out['meta'].update({
        'source': 'MASTER_BOOK_REBUILD',
        'synthetic_from_summary': False,
        'rebuilt_from_master_book': True,
        'master_book_paths': list(_m9_master_book_candidate_paths() or []),
        'entry_cnt': int(len(entries)),
    })
    return out

def _m9_synthesize_payload_from_summary(summary: dict, payload: dict | None = None) -> dict:
    out = dict(payload or {}) if isinstance(payload, dict) else {}
    rows = [r for r in list((summary or {}).get('rows') or []) if isinstance(r, dict)]
    entries = []
    for r in rows:
        coin = str(r.get('coin') or '').upper().strip()
        if not coin:
            continue
        selected = int(r.get('selected') or 0) == 1
        executed_action = str(r.get('executed_action') or r.get('action') or '')
        ff = _final_fields_for_output(r, default_reason='NO_REQUEST', default_stage=_entry_stage_view(r, default=''))
        ent = {
            'coin': coin,
            'has_position': bool(selected),
            'layers_open_cnt': 1 if selected else 0,
            'layers': ([{'layer_id': f'{coin}_SYNTH_L1', 'status': 'OPEN'}] if selected else []),
            'plans': ([{'coin': coin, 'action': executed_action or ('increase' if selected else ''), 'reason': ff.get('final_reason'), 'stage': ff.get('final_stage')}] if (selected or executed_action) else []),
            'next_sell_tp_px': (0.0 if selected else None),
            'next_buy_px': (0.0 if selected else None),
            'reason': str(ff.get('final_reason') or ''),
            'stage': str(ff.get('final_stage') or ''),
            'selected': 1 if selected else 0,
            'executed_action': executed_action,
        }
        entries.append(ent)
    if entries:
        out['entries'] = entries
        meta = dict(out.get('meta') or {}) if isinstance(out.get('meta'), dict) else {}
        meta['source'] = str(meta.get('source') or 'STATE_COMMIT_FINAL_RECORD')
        meta['synthetic_from_summary'] = True
        meta['synthetic_entry_cnt'] = int(len(entries))
        out['meta'] = meta
    return out

