def _m9_export_from_master_sources(summary: dict, payload: dict, snapshot: dict, coins: list[str]) -> dict:
    summary = dict(summary or {})
    payload = dict(payload or {})
    bases = []
    for _base in (globals().get('LOGS_DIR'), globals().get('OUT_DIR')):
        try:
            if _base:
                bases.append(str(_base))
        except Exception as _e:
            _record_swallowed_exception('m9_export_bases', _e)
    book_nonempty = bool(_m9_master_book_nonempty())
    pos_nonempty = bool(_m9_snapshot_positions_nonempty(snapshot or {}, coins or []))
    payload_ok = bool(_m9_payload_has_meaningful_rows(payload))
    payload_broken = bool(_m9_payload_is_synthetic_or_broken(payload))
    fallback_used = False
    fallback_reason = ''
    detail_source = 'LIVE_PAYLOAD' if payload_ok and not payload_broken else ''
    if book_nonempty and ((not payload_ok) or payload_broken):
        _rebuilt = _m9_rebuild_detail_payload_from_master_book(snapshot or {}, payload or {}, coins or [])
        if _m9_payload_has_meaningful_rows(_rebuilt):
            payload = _rebuilt
            payload_ok = True
            payload_broken = False
            fallback_used = True
            fallback_reason = 'MASTER_BOOK_REBUILD'
            detail_source = 'MASTER_BOOK_REBUILD'
    if not payload_ok:
        for _base in bases:
            _prev = _m9_safe_read_json_file(os.path.join(str(_base), 'm9_detail_last.json'))
            if _m9_payload_has_meaningful_rows(_prev) and (not _m9_payload_is_synthetic_or_broken(_prev)):
                payload = _prev
                payload_ok = True
                fallback_used = True
                fallback_reason = 'PREV_NON_SYNTHETIC_DETAIL'
                detail_source = 'PREV_NON_SYNTHETIC_DETAIL'
                break
    if not payload_ok:
        fallback_reason = 'EMPTY_EXPORT_SOURCE_MISMATCH' if (book_nonempty or pos_nonempty) else 'EMPTY_EXPORT_NO_MASTER_SOURCE'
        detail_source = fallback_reason
        _m9_write_empty_round_debug(payload, summary, reason=fallback_reason)
    summary.setdefault('meta', {})
    if isinstance(summary.get('meta'), dict):
        summary['meta']['payload_fallback_used'] = bool(fallback_used)
        summary['meta']['empty_export_reason'] = str(fallback_reason or '')
        summary['meta']['book_nonempty'] = bool(book_nonempty)
        summary['meta']['positions_nonempty'] = bool(pos_nonempty)
        summary['meta']['detail_export_source'] = str(detail_source or '')
        summary['meta']['detail_single_source'] = True
    if isinstance(payload, dict):
        payload['detail_export_source'] = str(detail_source or '')
        payload['detail_single_source'] = True
        payload['payload_fallback_used'] = bool(fallback_used)
        payload['empty_export_reason'] = str(fallback_reason or '')
    try:
        payload = _m9_observe_payload_align_to_master_book(payload)
    except Exception as _e:
        _record_swallowed_exception('m9_export.observe_align', _e)
    try:
        summary = _m9_summary_repair_reason_leak(summary, payload)
    except Exception as _e:
        _record_swallowed_exception('m9_export.reason_repair', _e)
    reason_payload = _m9_build_reason_rank_payload({'ts': summary.get('ts') or now_ts(), 'mod': 'M9', 'rows': list(summary.get('rows') or [])}, row_limit=8)
    reason_payload['meta'] = dict(reason_payload.get('meta') or {})
    reason_payload['meta'].update({
        'source': 'STATE_COMMIT_FINAL_RECORD',
        'payload_fallback_used': bool(fallback_used),
        'empty_export_reason': str(fallback_reason or ''),
        'detail_export_source': str(detail_source or ''),
        'detail_single_source': True,
    })
    for _base in bases:
        try:
            safe_write_json(os.path.join(_base, 'm9_decision_summary_last.json'), summary)
            safe_write_json(os.path.join(_base, 'm9_detail_last.json'), payload)
            safe_write_json(os.path.join(_base, 'm9_reason_rank_last.json'), reason_payload)
        except Exception as _e:
            _record_swallowed_exception('m9_export_write', _e, base=_base)
    try:
        _tfp = _m9_detail_last_txt_fp()
        _line = _m9_build_text_summary_line(payload, coins or [])
        if fallback_used and fallback_reason:
            _line = f"{_line} || EXPORT_FALLBACK[{fallback_reason}]"
        _dirty_write_text(_tfp, _line, cache_key='m9_detail_last_txt', semantic_text=_semanticize_text_for_dirty(_line))
    except Exception as _e:
        _log_exc(mod='SYS', stage='EXC_PASS', e=_e)
    try:
        _m9_write_layers_csv_from_payload(payload)
        _m9_write_observe_table_from_payload(payload)
    except Exception as _e:
        _log_exc(mod='SYS', stage='EXC_PASS', e=_e)
    return {'ok': True, 'payload_fallback_used': bool(fallback_used), 'empty_export_reason': str(fallback_reason or ''), 'summary': summary, 'payload': payload, 'reason_payload': reason_payload}

