            globals().setdefault('SELFTEST_REPORT', {})['m9_trend_breakout_m10_blocked'] = _selftest_m9_trend_breakout_m10_blocked()
            globals().setdefault('SELFTEST_REPORT', {})['m10_step3_70pct_contract'] = _selftest_m10_step3_70pct_contract()
            globals().setdefault('SELFTEST_REPORT', {})['m9_trend_alpha_freeze_contract'] = _selftest_m9_trend_alpha_freeze_contract()
