def _m9_recent_reduce_fail_ttl() -> float:
    """最近一次 M9 decrease 失败后的短冷却。
    人话：避免同目标刚减仓失败，本轮/下一轮立刻又去顺势加仓，造成 HYPE 那种“先减失败、后加又撞锁”的乱序。
    """
    try:
        return float(max(15.0, float(globals().get("M9_RECENT_REDUCE_FAIL_COOLDOWN_SEC", 120.0) or 120.0)))
    except Exception:
        return 120.0

def _m9_target_key(coin: str, platform: str = '', side: str = '') -> str:
    return f"{str(coin or '').upper().strip()}|{str(platform or '').upper().strip()}|{str(side or '').upper().strip()}"

_M9_RUNTIME_DIAG_NS: Dict[str, Any] = {}

def _m9_load_state_ns() -> tuple[dict, dict]:
    try:
        ns = dict(globals().get('_M9_RUNTIME_DIAG_NS') or {})
    except Exception:
        ns = {}
    return {}, ns

def _m9_save_state_ns(obj: dict, ns: dict) -> None:
    try:
        globals()['_M9_RUNTIME_DIAG_NS'] = dict(ns or {})
    except Exception as _e:
        _log_exc(mod='SYS', stage='EXC_PASS', e=_e)

def _m9_register_recent_reduce_fail(coin: str, platform: str = '', side: str = '', *, reason: str = '', detail: Any = None, req_id: str = '', trace_id: str = '') -> dict:
    key = _m9_target_key(coin, platform, side)
    now_ts0 = float(time.time())
    ttl = float(_m9_recent_reduce_fail_ttl())
    row = {
        'ts': now_ts0,
        'until_ts': float(now_ts0 + ttl),
        'reason': str(reason or 'reduce_fail')[:160],
        'req_id': str(req_id or '')[:120],
        'trace_id': str(trace_id or '')[:120],
    }
    if isinstance(detail, dict):
        try:
            row['detail'] = json.loads(json.dumps(detail, ensure_ascii=False, default=str))
        except Exception:
            row['detail'] = {'detail': str(detail)[:400]}
    elif detail not in (None, ''):
        row['detail'] = {'detail': str(detail)[:400]}
    try:
        obj, ns = _m9_load_state_ns()
        mp = dict(ns.get('recent_reduce_fail') or {})
        mp[str(key)] = row
        ns['recent_reduce_fail'] = mp
        _m9_save_state_ns(obj, ns)
    except Exception as _e:
        _log_exc(mod='SYS', stage='EXC_PASS', e=_e)
    return row

def _m9_get_recent_reduce_fail(coin: str, platform: str = '', side: str = '') -> dict:
    key = _m9_target_key(coin, platform, side)
    try:
        _obj, ns = _m9_load_state_ns()
        mp = dict(ns.get('recent_reduce_fail') or {})
        row = mp.get(str(key))
        return dict(row) if isinstance(row, dict) else {}
    except Exception:
        return {}

def _m9_clear_recent_reduce_fail(coin: str, platform: str = '', side: str = '') -> bool:
    key = _m9_target_key(coin, platform, side)
    try:
        obj, ns = _m9_load_state_ns()
        mp = dict(ns.get('recent_reduce_fail') or {})
        existed = str(key) in mp
        if existed:
            mp.pop(str(key), None)
            ns['recent_reduce_fail'] = mp
            _m9_save_state_ns(obj, ns)
        return bool(existed)
    except Exception as _e:
        _log_exc(mod='SYS', stage='EXC_PASS', e=_e)
        return False

def _m9_same_target_pending_close(coin: str, platform: str = '', side: str = '') -> dict:
    c = str(coin or '').upper().strip()
    p = str(platform or '').upper().strip()
    sd = str(side or '').upper().strip()
    rep = {'ok': True, 'blocked': False, 'reason': '', 'grid_id': '', 'pending_count': 0, 'layer_ids': [], 'req_ids': [], 'trace_ids': []}
    try:
        if ('GRID_BOOK' not in globals()) or (globals().get('GRID_BOOK') is None) or (not hasattr(GRID_BOOK, 'get_pending_close_layers')):
            return rep
        gids = [f'{c}_{p}_{sd}_M9', f'{c}_{p}_{sd}_M9X']
        for gid in gids:
            try:
                rows = GRID_BOOK.get_pending_close_layers(str(gid)) or []
            except Exception:
                rows = []
            if not rows:
                continue
            rep['blocked'] = True
            rep['reason'] = 'same_target_reduce_first'
            rep['grid_id'] = str(gid)
            rep['pending_count'] = int(len(rows))
            rep['layer_ids'] = [str((x or {}).get('layer_id') or '') for x in rows if isinstance(x, dict)]
            rep['req_ids'] = [str((x or {}).get('close_pending_req_id') or '') for x in rows if isinstance(x, dict) and str((x or {}).get('close_pending_req_id') or '')]
            rep['trace_ids'] = [str((x or {}).get('close_pending_trace_id') or '') for x in rows if isinstance(x, dict) and str((x or {}).get('close_pending_trace_id') or '')]
            return rep
    except Exception as _e:
        _log_exc(mod='SYS', stage='EXC_PASS', e=_e)
    return rep

def _m9_precheck_allow_increase(coin: str, platform: str = '', side: str = '') -> tuple[bool, str, dict]:
    """M9 单主链收口：increase 预检只认同目标 pending close。
    recent_reduce_fail 仍可保留为运行时诊断，但不得再参与业务裁决。
    返回 detail 时同步固化 final_* 字段，避免后续展示链再猜一次。
    """
    pend = _m9_same_target_pending_close(coin, platform, side)
    if bool((pend or {}).get('blocked')):
        det = dict(pend or {})
        rr = _normalize_reason_code((pend or {}).get('reason') or 'same_target_reduce_first', default='same_target_reduce_first')
        det['final_reason'] = str(rr)
        det['final_reason_code'] = str(rr)
        det['final_stage'] = 'ELIGIBILITY'
        det['final_verdict'] = 'REJECTED'
        return False, str(rr), det
    return True, 'ok', {
        'final_reason': 'arbitration_accepted',
        'final_reason_code': 'arbitration_accepted',
        'final_stage': 'ELIGIBILITY',
        'final_verdict': 'ACCEPTED',
    }

def _m9_pre_adjudicate_increase(snapshot: dict | None, coin: str, platform: str, side: str, add_u: float, *,
                               cur_px: float | None = None, last_real_layer: dict | None = None,
                               step_pct: float | None = None, is_first_real_m9_layer: bool = False,
                               grid_mode: str = "NORMAL", source: str = "main") -> tuple[bool, str, dict]:
    """M9 increase 唯一前置裁决：请求在 candidate / enqueue 之前，必须先过 precheck + hardcap。
    - 目的：彻底消灭“前面 selected，后面又 GO_REJECT(硬顶)”的假动作。
    - gap 是否检查由调用方决定；这里只把相关真相源带出去，供日志/汇总/面板统一使用。
    - 这里直接固化 final_* 字段，后续汇总/展示只需要镜像，不再二次猜原因。
    """
    detail: dict[str, Any] = {
        "coin": str(coin or "").upper().strip(),
        "platform": str(platform or "").upper().strip(),
        "side": str(side or "").upper().strip(),
        "source": str(source or "main"),
        "grid_mode": str(grid_mode or "NORMAL"),
        "is_first_real_m9_layer": bool(is_first_real_m9_layer),
        "hardcap_ok": True,
        "precheck_ok": True,
        "final_reason": "",
        "final_reason_code": "",
        "final_stage": "ELIGIBILITY",
        "final_verdict": "",
    }
    try:
        detail["candidate_u"] = float(add_u or 0.0)
    except Exception:
        detail["candidate_u"] = add_u
    try:
        if cur_px is not None:
            detail["cur_px"] = float(cur_px)
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_739', _e)
        pass
    try:
        if isinstance(last_real_layer, dict) and last_real_layer:
            detail["last_real_layer_id"] = str(last_real_layer.get("layer_id") or "")
            _last_px = float(_m9_layer_truth_open_px(last_real_layer, 0.0) or 0.0)
            if _last_px > 0:
                detail["last_real_m9_px"] = float(_last_px)
                if (cur_px is not None) and (step_pct is not None):
                    _cp = float(cur_px)
                    _sp = float(step_pct)
                    if str(side or "").upper().strip() == "LONG":
                        detail["gap_need_px"] = float(_last_px * (1.0 - _sp))
                        detail["gap_real"] = float((_last_px - _cp) / _last_px)
                    elif str(side or "").upper().strip() == "SHORT":
                        detail["gap_need_px"] = float(_last_px * (1.0 + _sp))
                        detail["gap_real"] = float((_cp - _last_px) / _last_px)
        elif bool(is_first_real_m9_layer):
            detail["gap_bypass"] = True
    except Exception as _e:
        detail["gap_diag_exc"] = repr(_e)

    try:
        _ok_pre, _why_pre, _det_pre = _m9_precheck_allow_increase(coin, platform, side)
    except Exception as _e:
        _ok_pre, _why_pre, _det_pre = False, f'm9_precheck_exc:{repr(_e)}', {'exc': repr(_e)}
    detail["precheck_ok"] = bool(_ok_pre)
    if isinstance(_det_pre, dict) and _det_pre:
        detail["precheck_detail"] = dict(_det_pre or {})
        for _k in ("final_reason", "final_reason_code", "final_stage", "final_verdict"):
            if _det_pre.get(_k) not in (None, "") and not detail.get(_k):
                detail[_k] = _det_pre.get(_k)
    if not _ok_pre:
        _rr = _normalize_reason_code(_why_pre or "increase_precheck_block", default="increase_precheck_block")
        detail["final_reason"] = str(detail.get("final_reason") or _rr)
        detail["final_reason_code"] = str(detail.get("final_reason_code") or _rr)
        detail["final_stage"] = str(detail.get("final_stage") or "ELIGIBILITY")
        detail["final_verdict"] = str(detail.get("final_verdict") or "REJECTED")
        return False, str(_rr), detail

    try:
        ok_y, y_reason, y_detail = yingding_jiancha(snapshot if isinstance(snapshot, dict) else {}, coin, platform, float(add_u or 0.0), module="M9", action_type="increase")
    except Exception as _e:
        ok_y, y_reason, y_detail = True, "ok", {"exc": repr(_e)}
    detail["hardcap_ok"] = bool(ok_y)
    if isinstance(y_detail, dict) and y_detail:
        detail["hardcap_detail"] = dict(y_detail or {})
    if not ok_y:
        _rr = _normalize_reason_code(f'hardcap_block:{str(y_reason or "yingding")}', default='hardcap_block')
        detail["yingding"] = str(y_reason or "")
        detail["final_reason"] = str(_rr)
        detail["final_reason_code"] = str(_rr)
        detail["final_stage"] = "ELIGIBILITY"
        detail["final_verdict"] = "REJECTED"
        return False, str(_rr), detail
    detail["final_reason"] = "arbitration_accepted"
    detail["final_reason_code"] = "arbitration_accepted"
    detail["final_stage"] = "ELIGIBILITY"
    detail["final_verdict"] = "ACCEPTED"
    return True, 'ok', detail

_SELFTEST_CONTEXT_DEPTH = int(globals().get('_SELFTEST_CONTEXT_DEPTH', 0) or 0)

def _selftest_context_enter() -> None:
    try:
        globals()['_SELFTEST_CONTEXT_DEPTH'] = int(globals().get('_SELFTEST_CONTEXT_DEPTH', 0) or 0) + 1
    except Exception:
        globals()['_SELFTEST_CONTEXT_DEPTH'] = 1

def _selftest_context_leave() -> None:
    try:
        _cur = int(globals().get('_SELFTEST_CONTEXT_DEPTH', 0) or 0)
    except Exception:
        _cur = 0
    globals()['_SELFTEST_CONTEXT_DEPTH'] = max(0, _cur - 1)

def _selftest_context_active() -> bool:
    try:
        return bool(int(globals().get('_SELFTEST_CONTEXT_DEPTH', 0) or 0) > 0)
    except Exception:
        return False

def _synthetic_meta_keys() -> tuple[str, ...]:
    return ('synthetic', 'selfcheck', 'regression', 'dry_run', 'stub', 'fake_submit', 'selfcheck_silent')

def _is_synthetic_or_selfcheck_event(req_any=None, exec_res_list: list | None = None, ok_detail: Any = None) -> bool:
    try:
        if _selftest_context_active():
            return True
    except Exception:
        pass
    try:
        _meta = _req_meta(req_any) if '_req_meta' in globals() else {}
    except Exception:
        try:
            _meta = req_any.get('meta') if isinstance(req_any, dict) and isinstance(req_any.get('meta'), dict) else {}
        except Exception:
            _meta = {}
    try:
        if isinstance(_meta, dict):
            for _k in _synthetic_meta_keys():
                if bool(_meta.get(_k)):
                    return True
    except Exception:
        pass
    try:
        if isinstance(ok_detail, dict):
            for _k in _synthetic_meta_keys():
                if bool(ok_detail.get(_k)):
                    return True
    except Exception:
        pass
    try:
        _ids = []
        if isinstance(_meta, dict):
            _ids.extend([_meta.get('req_id'), _meta.get('trace_id'), _meta.get('order_id'), _meta.get('id'), _meta.get('tid')])
        for _rr in list(exec_res_list or []):
            if not isinstance(_rr, dict):
                continue
            _ids.extend([
                _rr.get('req_id'),
                _rr.get('trace_id'),
                _rr.get('order_id'),
                ((_rr.get('req') or {}).get('meta', {}) or {}).get('req_id'),
                ((_rr.get('req') or {}).get('meta', {}) or {}).get('trace_id'),
            ])
        if _arb_is_placeholder_identity(*_ids):
            return True
    except Exception:
        pass
    return False

def _close_kind_text(ok_detail: Any) -> str:
    try:
        if isinstance(ok_detail, dict):
            return str(ok_detail.get('kind') or ok_detail.get('state') or ok_detail.get('reason') or '').strip().lower()
    except Exception:
        pass
    try:
        return str(ok_detail or '').strip().lower()
    except Exception:
        return ''

def _is_close_action_like(req_any) -> bool:
    try:
        _reqd = _req_get_dict(req_any)
    except Exception:
        _reqd = {}
    try:
        _act = str((_reqd or {}).get('action_type') or (_reqd or {}).get('action') or '').strip().lower()
    except Exception:
        _act = ''
    if _act in ('close', 'close_pair', 'close_full', 'close_partial', 'close_partial_notional', 'decrease', 'reduce', 'take_profit', 'tp', 'trend_tp', 'koujing_a_3step'):
        return True
    try:
        _params = (_reqd or {}).get('params') if isinstance((_reqd or {}).get('params'), dict) else {}
        if bool((_params or {}).get('reduce_only')):
            return True
    except Exception:
        pass
    return False

def _platform_leg_state(state: dict | None, platform: str = '') -> tuple[bool | None, str, float]:
    st = state if isinstance(state, dict) else {}
    p = str(platform or '').upper().strip()
    pfx = 'ext' if p == 'EXT' else ('var' if p == 'VAR' else '')
    try:
        if pfx:
            _has = st.get(f'{pfx}_has')
            _side = str(st.get(f'{pfx}_side') or '').upper().strip()
            _notional = float(st.get(f'{pfx}_notional_u') or 0.0)
            return (_has if isinstance(_has, bool) else None), _side, _notional
    except Exception:
        pass
    try:
        _has = st.get('has_position')
        _side = str(st.get('side') or '').upper().strip()
        _notional = float(st.get('notional_u') or 0.0)
        return (_has if isinstance(_has, bool) else None), _side, _notional
    except Exception:
        return None, '', 0.0

def _derive_confirmed_close_reset_scopes(req_any, exec_res_list: list | None = None) -> list[dict]:
    """从真实成交结果里提取需要清空网格的作用域。
    重点：M10 的父请求常是 GROUP，但真正需要清空的是 step1 的 full-close 腿。
    """
    scopes: list[dict] = []
    seen: set[tuple[str, str, str]] = set()
    try:
        _mod, _act, _coin, _plat, _side = _req_identity_tuple(req_any)
    except Exception:
        _mod, _act, _coin, _plat, _side = '', '', '', '', ''
    try:
        _mod_u = str(_mod or '').upper().strip()
        _act_l = str(_act or '').lower().strip()
    except Exception:
        _mod_u = ''
        _act_l = ''
    _rows = list(exec_res_list or [])
    if _mod_u == 'M10' and _act_l == 'koujing_a_3step':
        _rows = _m10_extract_child_rows(_rows) or _rows
        for _row in _rows:
            try:
                if not isinstance(_row, dict):
                    continue
                if not _result_is_trade_effective(_row):
                    continue
                _req = _row.get('req') if isinstance(_row.get('req'), dict) else {}
                _rmod = str(_req.get('module') or _mod_u).upper().strip()
                _ract = str(_req.get('action_type') or _req.get('action') or '').lower().strip()
                if _rmod != 'M10':
                    continue
                if _ract not in ('close_full', 'close_all', 'close', 'close_position_full'):
                    continue
                _coin_s = str(_req.get('coin') or _coin or '').upper().strip()
                _plat_s = str(_req.get('platform') or '').upper().strip()
                _side_s = str(_req.get('side') or '').upper().strip()
                if _plat_s in ('GROUP', 'PAIR', 'BOTH', 'ALL', 'M10'):
                    _plat_s = ''
                if _side_s in ('GROUP', 'PAIR', 'BOTH', 'ALL', 'NONE'):
                    _side_s = ''
                if not _coin_s:
                    continue
                _key = (_coin_s, _plat_s, _side_s)
                if _key in seen:
                    continue
                seen.add(_key)
                scopes.append({'coin': _coin_s, 'platform': _plat_s, 'side': _side_s, 'source': 'm10_step_full_close'})
            except Exception as _e:
                _record_swallowed_exception('derive_close_reset_scopes_m10', _e)
                continue
    if scopes:
        return scopes
    _coin_s = str(_coin or '').upper().strip()
    _plat_s = str(_plat or '').upper().strip()
    _side_s = str(_side or '').upper().strip()
    if _plat_s in ('GROUP', 'PAIR', 'BOTH', 'ALL', 'M10'):
        _plat_s = ''
    if _side_s in ('GROUP', 'PAIR', 'BOTH', 'ALL', 'NONE'):
        _side_s = ''
    if _coin_s:
        scopes.append({'coin': _coin_s, 'platform': _plat_s, 'side': _side_s, 'source': 'parent_req'})
    return scopes

def _allow_real_state_reset_after_confirm(*, req_any, pre_state: dict | None, post_state: dict | None, exec_res_list: list | None, ok_reason: str = '', ok_detail: Any = None) -> tuple[bool, str]:
    if _is_synthetic_or_selfcheck_event(req_any=req_any, exec_res_list=exec_res_list, ok_detail=ok_detail):
        return False, 'synthetic_event'
    try:
        if _pw_runtime_is_recovering(((req_any or {}) if isinstance(req_any, dict) else {}).get('platform') or getattr(req_any, 'platform', '')):
            return False, 'runtime_recovering'
    except Exception:
        pass
    if not _is_close_action_like(req_any):
        return False, 'not_close_action'
    _kind = _close_kind_text(ok_detail)
    if any(_x in _kind for _x in ('open', 'increase')):
        return False, 'open_like_postcheck'
    if _kind and not any(_x in _kind for _x in ('close', 'reduce', 'tp', 'profit')):
        return False, 'close_evidence_missing'
    try:
        _mod, _act, _coin, _plat, _side = _req_identity_tuple(req_any)
    except Exception:
        _mod, _act, _coin, _plat, _side = '', '', '', '', ''
    try:
        _mod_u = str(_mod or '').upper().strip()
        _act_l = str(_act or '').lower().strip()
    except Exception:
        _mod_u, _act_l = '', ''
    try:
        _child_rows = _m10_extract_child_rows(exec_res_list)
    except Exception:
        _child_rows = []
    if _mod_u == 'M10' and _act_l == 'koujing_a_3step':
        try:
            _step_meta = _m10_postcheck_collect_step_meta(req_any, exec_res_list)
        except Exception:
            _step_meta = {'step_ok': {}, 'expected': {}, 'child_rows': []}
        _step_ok = dict((_step_meta or {}).get('step_ok') or {})
        _close_like_actions = ('close_full', 'close_all', 'close', 'close_position_full', 'close_partial_notional', 'reduce', 'decrease', 'trend_tp', 'tp_full')
        _has_effective_close_child = False
        _has_any_trade_effective_child = False
        if _child_rows:
            for _row in list(_child_rows or []):
                try:
                    if not isinstance(_row, dict):
                        continue
                    if not _result_is_trade_effective(_row):
                        continue
                    _has_any_trade_effective_child = True
                    _req = _row.get('req') if isinstance(_row.get('req'), dict) else {}
                    _rmod = str(_req.get('module') or _mod_u).upper().strip()
                    _ract = str(_req.get('action_type') or _req.get('action') or '').lower().strip()
                    if _rmod != 'M10':
                        continue
                    if _ract in _close_like_actions:
                        _has_effective_close_child = True
                        return True, f'm10_child_step_confirmed:{_ract or "close"}'
                except Exception as _e:
                    _record_swallowed_exception('allow_real_state_reset_after_confirm.m10_child_rows', _e)
                    continue
        _has_any_step_signal = bool(_child_rows) or bool(_step_ok) or bool(((_step_meta or {}).get('child_rows') or [])) or bool(((_step_meta or {}).get('expected') or {}))
        _strict_known = all(k in _step_ok for k in (1, 2, 3)) if _step_ok else False
        _strict_ok = bool(_step_ok.get(1) and _step_ok.get(2) and _step_ok.get(3)) if _strict_known else False
        if _has_any_step_signal and (not _has_effective_close_child):
            if _has_any_trade_effective_child:
                return False, 'm10_child_close_missing'
            _only_reopen_child = False
            try:
                _only_reopen_child = any(
                    isinstance(_row, dict)
                    and str((((_row.get('req') if isinstance(_row.get('req'), dict) else {}) or {}).get('action_type') or ((_row.get('req') if isinstance(_row.get('req'), dict) else {}) or {}).get('action') or '')).lower().strip() in ('open_full', 'open', 'increase', 'add')
                    for _row in list(_child_rows or [])
                )
            except Exception:
                _only_reopen_child = False
            if _only_reopen_child:
                return False, 'm10_child_close_missing'
            if _strict_known and (not _strict_ok):
                return False, 'm10_strict_steps_incomplete'
            if not _strict_known:
                return False, 'm10_strict_steps_unknown'
        return False, 'm10_child_close_missing'
    _pre_has, _pre_side, _pre_notional = _platform_leg_state(pre_state, _plat)
    _post_has, _post_side, _post_notional = _platform_leg_state(post_state, _plat)
    try:
        _req_side = str(_side or '').upper().strip()
    except Exception:
        _req_side = ''
    try:
        if _req_side and _post_side == _req_side and float(_post_notional or 0.0) > float(_pre_notional or 0.0) + 1e-9:
            return False, 'same_side_notional_increased'
    except Exception:
        pass
    try:
        if bool(_pre_has) and (_post_has is False or float(_post_notional or 0.0) + 1e-9 < float(_pre_notional or 0.0)):
            return True, 'real_close_confirmed'
    except Exception:
        pass
    if 'close' in _kind or 'reduce' in _kind or 'tp' in _kind or 'profit' in _kind:
        return True, 'close_detail_confirmed'
    return False, 'close_evidence_missing'

def _m9_verify_trades_written(trades_fp: str, *, req_id: str = '', trace_id: str = '', min_matches: int = 1, max_lines: int = 4000) -> dict:
    rep = {'ok': False, 'matches': 0, 'reason': '', 'path': str(trades_fp or '')}
    try:
        fp = str(trades_fp or '').strip()
        if not fp:
            rep['reason'] = 'trades_fp_missing'
            return rep
        if not os.path.exists(fp):
            rep['reason'] = 'trades_file_missing'
            return rep
        try:
            with open(fp, 'r', encoding='utf-8', errors='ignore') as f:
                lines = f.readlines()[-max(1, int(max_lines)): ]
        except Exception as _e:
            rep['reason'] = f'read_exc:{type(_e).__name__}'
            rep['error'] = repr(_e)
            return rep
        rid = str(req_id or '').strip()
        tid = str(trace_id or '').strip()
        matches = 0
        for line in lines:
            s = str(line or '').strip()
            if not s:
                continue
            try:
                row = json.loads(s)
            except Exception:
                continue
            if not isinstance(row, dict):
                continue
            if rid and str(row.get('req_id') or '').strip() == rid:
                matches += 1
                continue
            if tid and str(row.get('trace_id') or '').strip() == tid:
                matches += 1
                continue
            meta = row.get('meta') if isinstance(row.get('meta'), dict) else {}
            if rid and str(meta.get('req_id') or '').strip() == rid:
                matches += 1
                continue
            if tid and str(meta.get('trace_id') or '').strip() == tid:
                matches += 1
                continue
        rep['matches'] = int(matches)
        rep['ok'] = bool(matches >= max(1, int(min_matches or 1)))
        rep['reason'] = 'ok' if rep['ok'] else 'trade_row_not_found'
        return rep
    except Exception as _e:
        rep['reason'] = f'verify_exc:{type(_e).__name__}'
        rep['error'] = repr(_e)
        return rep


def _m9_verify_executor_results_written(exec_fp: str, *, req_id: str = '', trace_id: str = '', min_matches: int = 1, max_lines: int = 4000) -> dict:
    rep = {'ok': False, 'matches': 0, 'reason': '', 'path': str(exec_fp or '')}
    try:
        fp = str(exec_fp or '').strip()
        if not fp:
            rep['reason'] = 'executor_fp_missing'
            return rep
        if not os.path.exists(fp):
            rep['reason'] = 'executor_file_missing'
            return rep
        try:
            with open(fp, 'r', encoding='utf-8', errors='ignore') as f:
                lines = f.readlines()[-max(1, int(max_lines)): ]
        except Exception as _e:
            rep['reason'] = f'read_exc:{type(_e).__name__}'
            rep['error'] = repr(_e)
            return rep
        rid = str(req_id or '').strip()
        tid = str(trace_id or '').strip()
        matches = 0
        for line in lines:
            s = str(line or '').strip()
            if not s:
                continue
            try:
                row = json.loads(s)
            except Exception:
                continue
            if not isinstance(row, dict):
                continue
            if rid and str(row.get('req_id') or '').strip() == rid:
                matches += 1
                continue
            if tid and str(row.get('trace_id') or '').strip() == tid:
                matches += 1
                continue
            meta = row.get('meta') if isinstance(row.get('meta'), dict) else {}
            req = row.get('req') if isinstance(row.get('req'), dict) else {}
            req_meta = req.get('meta') if isinstance(req.get('meta'), dict) else {}
            if rid and (str(meta.get('req_id') or '').strip() == rid or str(req_meta.get('req_id') or '').strip() == rid):
                matches += 1
                continue
            if tid and (str(meta.get('trace_id') or '').strip() == tid or str(req_meta.get('trace_id') or '').strip() == tid):
                matches += 1
                continue
        rep['matches'] = int(matches)
        rep['ok'] = bool(matches >= max(1, int(min_matches or 1)))
        rep['reason'] = 'ok' if rep['ok'] else 'executor_row_not_found'
        return rep
    except Exception as _e:
        rep['reason'] = f'verify_exc:{type(_e).__name__}'
        rep['error'] = repr(_e)
        return rep


def _m9_runtime_persist_verify(*, req_any: Any, adapter: Any = None) -> dict:
    rep = {'ok': False, 'kind': '', 'book_verify': {}, 'exec_verify': {}, 'trade_verify': {}, 'reason': ''}
    try:
        rd = _req_get_dict(req_any)
    except Exception:
        rd = dict(req_any or {}) if isinstance(req_any, dict) else {}
    try:
        mod = str(rd.get('module') or '').upper().strip()
        act = str(rd.get('action_type') or rd.get('action') or '').lower().strip()
    except Exception:
        mod = ''
        act = ''
    if mod != 'M9' or act not in ('increase', 'decrease'):
        rep['reason'] = 'not_m9_trade_action'
        return rep
    meta = _req_ensure_meta(req_any)
    coin = str(rd.get('coin') or '').upper().strip()
    plat = str(rd.get('platform') or '').upper().strip()
    side = str(rd.get('side') or meta.get('side') or '').upper().strip()
    rep['kind'] = f'{mod}:{act}'
    try:
        gb = globals().get('GRID_BOOK')
        if gb is not None and hasattr(gb, '_save'):
            gb._save()
            rep['book_verify'] = _m9_verify_dual_ledger_export(getattr(gb, 'fp', None), getattr(gb, 'data', {}), coin=coin, platform=plat, side=side)
        else:
            rep['book_verify'] = {'ok': False, 'reason': 'grid_book_missing'}
    except Exception as _e:
        rep['book_verify'] = {'ok': False, 'reason': f'book_verify_exc:{type(_e).__name__}', 'error': repr(_e)}
    try:
        _exec_fp = ''
        if adapter is not None:
            _exec_fp = str(getattr(adapter, 'executor_fp', None) or getattr(adapter, 'executor_fp_fallback', None) or '')
        rep['exec_verify'] = _m9_verify_executor_results_written(_exec_fp, req_id=str(meta.get('req_id') or ''), trace_id=str(meta.get('trace_id') or '')) if _exec_fp else {'ok': False, 'reason': 'adapter_or_executor_fp_missing'}
    except Exception as _e:
        rep['exec_verify'] = {'ok': False, 'reason': f'exec_verify_exc:{type(_e).__name__}', 'error': repr(_e)}
    try:
        if adapter is not None and getattr(adapter, 'trades_fp', None):
            rep['trade_verify'] = _m9_verify_trades_written(str(getattr(adapter, 'trades_fp') or ''), req_id=str(meta.get('req_id') or ''), trace_id=str(meta.get('trace_id') or ''))
        else:
            rep['trade_verify'] = {'ok': False, 'reason': 'adapter_or_trades_fp_missing'}
    except Exception as _e:
        rep['trade_verify'] = {'ok': False, 'reason': f'trade_verify_exc:{type(_e).__name__}', 'error': repr(_e)}
    _exec_required = bool(str((rep.get('exec_verify') or {}).get('reason') or '') != 'adapter_or_executor_fp_missing')
    rep['ok'] = bool((rep.get('book_verify') or {}).get('ok')) and bool((rep.get('trade_verify') or {}).get('ok')) and (bool((rep.get('exec_verify') or {}).get('ok')) if _exec_required else True)
    rep['reason'] = 'ok' if rep['ok'] else ('executor_result_write_missing' if _exec_required and not bool((rep.get('exec_verify') or {}).get('ok')) else 'persist_chain_incomplete')
    return rep


def _state_commit_confirmed_success(*, req_any, snapshot: dict, pre_state: dict | None, post_state: dict | None, exec_res_list: list | None, ok_reason: str = '', ok_detail: Any = None, adapter: Any = None) -> dict:
    """确认成功后的唯一落账入口：先标 postcheck，再落摘要，再清策略状态。
    关键约束：
    - synthetic/selfcheck/regression 事件绝不允许污染真实结果链/摘要链/清链主链；
    - 只有真实 close 证据成立时，才允许 clear grid / clear m9 / reset l1。
    """
    rep = {'postcheck_marked': 0, 'trade_effective_count': 0, 'trades_appended': 0, 'state_reset': None, 'audit_written': False}
    _all_exec = list(exec_res_list or [])
    _marked = _mark_exec_results_postcheck(_all_exec, ok=True, reason=str(ok_reason or 'postcheck_ok'), detail=ok_detail)
    rep['postcheck_marked'] = len(_marked)
    _synthetic_commit = bool(_is_synthetic_or_selfcheck_event(req_any=req_any, exec_res_list=_marked, ok_detail=ok_detail))
    rep['synthetic_commit'] = _synthetic_commit
    try:
        if _synthetic_commit:
            rep['executor_result_updates_written'] = 0
            rep['executor_result_updates_skipped_reason'] = 'synthetic_event'
        else:
            rep['executor_result_updates_written'] = int(_exec_results_write_updates(
                _marked,
                kind="executor_result_update",
                extra={"stage": "state_commit_confirmed_success", "ok": True, "ok_reason": str(ok_reason or '')},
            ))
    except Exception:
        rep['executor_result_updates_written'] = 0
    _to_trades = list(_marked or [])
    try:
        _reqd = _req_get_dict(req_any)
    except Exception:
        try:
            _reqd = req_any.to_dict() if hasattr(req_any, 'to_dict') else (dict(req_any) if isinstance(req_any, dict) else {})
        except Exception:
            _reqd = {}
    try:
        _mod_u = str((_reqd or {}).get('module') or '').upper().strip()
        _act_l = str((_reqd or {}).get('action_type') or (_reqd or {}).get('action') or '').lower().strip()
    except Exception:
        _mod_u = ''
        _act_l = ''
    try:
        if _mod_u == 'M10' and _act_l == 'koujing_a_3step':
            _child_rows = _m10_extract_child_rows(_marked)
            if _child_rows:
                _to_trades = list(_child_rows)
                rep['m10_trade_rows_only'] = int(len(_child_rows))
            else:
                rep['m10_trade_rows_only'] = 0
                rep['m10_trade_rows_fallback'] = 1
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_740', _e)
        pass
    try:
        if (not _synthetic_commit) and adapter is not None and _to_trades:
            adapter.append_trades(snapshot or {}, _to_trades)
            rep['trades_appended'] = sum(1 for _r in _to_trades if _result_is_trade_effective(_r))
        elif _synthetic_commit:
            rep['trades_append_skipped_reason'] = 'synthetic_event'
    except Exception as _e:
        rep['trades_append_error'] = repr(_e)
        try:
            _append_txt(fp_baocuo, f"STATE_COMMIT append_trades异常：{repr(_e)}")
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_741', _e)
            pass
    try:
        if not _synthetic_commit:
            _audit_executor_action(
                req_any=req_any,
                pre_state=pre_state,
                post_state=post_state,
                exec_res_list=_marked,
                ok=True,
                reason=str(ok_reason or 'postcheck_ok'),
                detail=(ok_detail if isinstance(ok_detail, dict) else {'detail': ok_detail}),
            )
            rep['audit_written'] = True
        else:
            rep['audit_written'] = False
            rep['audit_skipped_reason'] = 'synthetic_event'
    except Exception as _e:
        _log_exc(mod='SYS', stage='EXC_PASS', e=_e)
        rep['audit_error'] = repr(_e)
    rep['trade_effective_count'] = sum(1 for _r in _marked if _result_is_trade_effective(_r))
    try:
        rep['execution_evidence'] = _build_execution_evidence(req_any=req_any, exec_res_list=_marked, pre_state=pre_state, post_state=post_state, snapshot=snapshot, ok=True, reason=str(ok_reason or 'postcheck_ok'), detail=ok_detail)
        _attach_execution_evidence(_marked, rep.get('execution_evidence'))
        try:
            _rd_m9 = _req_get_dict(req_any)
        except Exception:
            _rd_m9 = dict(req_any or {}) if isinstance(req_any, dict) else {}
        try:
            _mod_m9 = str((_rd_m9 or {}).get('module') or '').upper().strip()
            _act_m9 = str((_rd_m9 or {}).get('action_type') or (_rd_m9 or {}).get('action') or '').lower().strip()
            _ev_state = str(((rep.get('execution_evidence') or {}).get('final_confirmation_code') or (rep.get('execution_evidence') or {}).get('final_state') or '')).strip().lower()
            if _mod_m9 == 'M9' and _act_m9 in ('increase', 'add', 'open') and _ev_state == 'confirmed_success':
                rep['m9_confirmed_open_guard'] = bool(_grid_pending_open_mark_confirmed(req_any=_rd_m9, execution_evidence=rep.get('execution_evidence'), reason=str(ok_reason or 'postcheck_ok')))
        except Exception as _e_guard:
            rep['m9_confirmed_open_guard_error'] = repr(_e_guard)
    except Exception as _e:
        rep['execution_evidence_error'] = repr(_e)
    try:
        if int(rep.get('trade_effective_count') or 0) > 0:
            try:
                rep['noise_guard_commit'] = _noise_guard_commit(req_any, reason=str(ok_reason or 'confirmed_success'))
            except Exception as _e:
                rep['noise_guard_commit_error'] = repr(_e)
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_742', _e)
        pass
    try:
        _mod, _act, _coin, _plat, _side = _req_identity_tuple(req_any)
        if rep['trade_effective_count'] > 0 and str(_mod or '').upper() == 'M9' and _coin:
            try:
                _m9_clear_recent_reduce_fail(_coin, _plat, _side)
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_743', _e)
                pass
        try:
            _m9_round_final_note_request(req_any, state='EXEC_OK' if int(rep.get('trade_effective_count') or 0) > 0 else 'DONE', reason=str(ok_reason or 'postcheck_ok'), detail=ok_detail, commit_rep=rep)
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_744', _e)
            pass
        try:
            if rep['trade_effective_count'] > 0 and _coin and str(_mod or '').upper().strip() == 'M9':
                rep['m9_live_sync'] = _m9_sync_coin_live_positions_into_book(
                    _coin,
                    snapshot=(snapshot if isinstance(snapshot, dict) else {}),
                    post_state=(post_state if isinstance(post_state, dict) else {}),
                    reason=str(ok_reason or 'postcheck_ok'),
                    src_mod=str(_mod or ''),
                    src_act=str(_act or ''),
                    allow_without_history=False,
                )
        except Exception as _e_sync:
            rep['m9_live_sync_error'] = repr(_e_sync)
        try:
            if rep['trade_effective_count'] > 0 and str(_mod or '').upper().strip() == 'M9':
                rep['m9_persist_verify'] = _m9_runtime_persist_verify(req_any=req_any, adapter=adapter)
                if not bool((rep.get('m9_persist_verify') or {}).get('ok')):
                    try:
                        _append_txt(fp_baocuo, f"M9_PERSIST_VERIFY_FAIL|coin={str(_coin or '')}|plat={str(_plat or '')}|side={str(_side or '')}|detail={json.dumps(rep.get('m9_persist_verify') or {}, ensure_ascii=False)}")
                    except Exception as _e_persist_log:
                        _record_swallowed_exception('m9_persist_verify_baocuo', _e_persist_log)
        except Exception as _e_persist:
            rep['m9_persist_verify_error'] = repr(_e_persist)
        try:
            _meta_commit = _req_ensure_meta(req_any)
            if rep['trade_effective_count'] > 0 and str(_mod or '').upper().strip() == 'M9' and _is_reduce_action(_act):
                if str((_meta_commit or {}).get('m9_close_kind') or '').upper().strip() in ('PARTIAL_CLOSE', 'PARTIAL_EXIT_TO_RUNNER'):
                    rep['m9_partial_transient_scrub'] = _m9_scrub_exact_req_transients_after_partial_close(
                        coin=str(_coin or ''),
                        grid_id=str((_meta_commit or {}).get('grid_id') or ''),
                        layer_id=str((_meta_commit or {}).get('layer_id') or ''),
                        layer_instance_id=str((_meta_commit or {}).get('layer_instance_id') or (_meta_commit or {}).get('instance_id') or ''),
                        req_id=str((_meta_commit or {}).get('req_id') or ''),
                        trace_id=str((_meta_commit or {}).get('trace_id') or ''),
                        reason=str(ok_reason or 'postcheck_ok'),
                        src_mod=str(_mod or ''),
                        src_act=str(_act or ''),
                    )
        except Exception as _e_m9_partial:
            rep['m9_partial_transient_scrub_error'] = repr(_e_m9_partial)
        if rep['trade_effective_count'] > 0 and _coin and (_m10_should_preempt_m9(req_any) or _b2_should_preempt_m9(req_any)):
            _arb_evt = _arb_build_event(req_any, _marked)
            rep['arb_event'] = dict(_arb_evt or {})
            _arb_reason = f'{_mod}:{_act}:confirmed_success:{rep["trade_effective_count"]}'
            _allow_reset, _deny_reason = _allow_real_state_reset_after_confirm(
                req_any=req_any,
                pre_state=pre_state,
                post_state=post_state,
                exec_res_list=_marked,
                ok_reason=str(ok_reason or 'postcheck_ok'),
                ok_detail=ok_detail,
            )
            _arb_placeholder = bool(_arb_event_is_placeholder(
                req_any=req_any,
                exec_res_list=_marked,
                reason=_arb_reason,
                req_id=str((_arb_evt or {}).get('req_id') or ''),
                trace_id=str((_arb_evt or {}).get('trace_id') or ''),
                order_id=str((_arb_evt or {}).get('order_id') or ''),
                event_id=str((_arb_evt or {}).get('event_id') or ''),
            ))
            if (not _allow_reset) or _arb_placeholder:
                rep['state_reset'] = {
                    'coin': _coin, 'platform': _plat, 'side': _side,
                    'reason': _arb_reason, 'src_mod': _mod or 'SYS', 'src_act': _act or '',
                    'event_id': str((_arb_evt or {}).get('event_id') or ''),
                    'req_id': str((_arb_evt or {}).get('req_id') or ''),
                    'trace_id': str((_arb_evt or {}).get('trace_id') or ''),
                    'winner': _arb_winner_module_name(_mod or ''),
                    'grid_changed': 0, 'a1_changed': False, 'bucket_reset_called': False, 'round_block_applied': False,
                    'arb_accepted': False,
                    'arb_reject_reason': ('placeholder_event' if _arb_placeholder else str(_deny_reason or 'state_reset_denied')),
                    'skip': ('placeholder_event' if _arb_placeholder else str(_deny_reason or 'state_reset_denied')),
                }
                try:
                    if str(_mod or '').upper().strip() == 'M10' and str(_act or '').lower().strip() == 'koujing_a_3step' and _coin:
                        _step_meta = _m10_postcheck_collect_step_meta(req_any, _marked)
                        _step_ok = dict((_step_meta or {}).get('step_ok') or {})
                        _expected = dict((_step_meta or {}).get('expected') or {})
                        _pending_kind = 'step3_reopen'
                        _pending_state = 'step3_reopen'
                        _blocking = True
                        if _step_ok and (not bool(_step_ok.get(2))):
                            _pending_kind = 'retry_step2_then_step3'
                            _pending_state = 'retry_step2_then_step3'
                            _blocking = False
                        _m10_reopen_mark_pending(
                            _coin,
                            platform=str(_expected.get('platform') or _plat or ''),
                            side=str(_expected.get('side') or _side or ''),
                            amount_u=float(_expected.get('amount_u') or 0.0),
                            reason=str(_deny_reason or 'm10_state_reset_denied'),
                            source_mod='M10',
                            req_id=str((_arb_evt or {}).get('req_id') or ''),
                            trace_id=str((_arb_evt or {}).get('trace_id') or ''),
                            pending_kind=_pending_kind,
                            state=_pending_state,
                            blocking=bool(_blocking),
                            ttl_sec=(90.0 if not _blocking else 180.0),
                            last_fail_reason=str(_deny_reason or 'm10_state_reset_denied'),
                        )
                        rep['m10_reopen_pending'] = {
                            'kind': _pending_kind,
                            'state': _pending_state,
                            'blocking': bool(_blocking),
                            'reason': str(_deny_reason or 'm10_state_reset_denied'),
                        }
                except Exception as _e:
                    rep['m10_reopen_pending_error'] = repr(_e)
            else:
                _reset_scopes = list(_derive_confirmed_close_reset_scopes(req_any, _marked) or [])
                try:
                    _pin('GRID_RESET_SCOPES', mod=str(_mod or 'SYS'), coin=str(_coin or '').upper(), ok=1,
                         reason='confirmed_close_reset_scopes', scopes=json.dumps(_reset_scopes, ensure_ascii=False))
                except Exception as _e:
                    _record_swallowed_exception('grid_reset_scopes_pin', _e)
                if not _reset_scopes:
                    _reset_scopes = [{'coin': _coin, 'platform': _plat, 'side': _side, 'source': 'parent_req'}]
                _scope_rows = []
                _grid_changed_total = 0
                _a1_changed_any = False
                _bucket_reset_any = False
                _round_block_any = False
                _arb_accept_any = False
                _skip_reasons = []
                for _scope in _reset_scopes:
                    try:
                        _coin_s = str((_scope or {}).get('coin') or _coin or '').upper().strip()
                        _plat_s = str((_scope or {}).get('platform') or '').upper().strip()
                        _side_s = str((_scope or {}).get('side') or '').upper().strip()
                        _src_scope = str((_scope or {}).get('source') or '')
                        _scope_rep = _clear_m9_state_after_confirmed_close(
                            _coin_s, _plat_s, _side_s,
                            reason=_arb_reason,
                            src_mod=_mod or 'SYS',
                            src_act=_act or '',
                            apply_round_block=True,
                            event_id=str((_arb_evt or {}).get('event_id') or ''),
                            req_id=str((_arb_evt or {}).get('req_id') or ''),
                            trace_id=str((_arb_evt or {}).get('trace_id') or ''),
                        )
                        try:
                            _scope_rep['scope_source'] = _src_scope
                        except Exception:
                            pass
                        _scope_rows.append(dict(_scope_rep or {}))
                        _grid_changed_total += int((_scope_rep or {}).get('grid_changed') or 0)
                        _a1_changed_any = bool(_a1_changed_any or bool((_scope_rep or {}).get('a1_changed')))
                        _bucket_reset_any = bool(_bucket_reset_any or bool((_scope_rep or {}).get('bucket_reset_called')))
                        _round_block_any = bool(_round_block_any or bool((_scope_rep or {}).get('round_block_applied')))
                        _arb_accept_any = bool(_arb_accept_any or bool((_scope_rep or {}).get('arb_accepted')))
                        if str((_scope_rep or {}).get('skip') or ''):
                            _skip_reasons.append(str((_scope_rep or {}).get('skip') or ''))
                    except Exception as _e:
                        _record_swallowed_exception('state_reset_multi_scope', _e)
                        continue
                rep['state_reset'] = {
                    'coin': _coin, 'platform': _plat, 'side': _side,
                    'reason': _arb_reason, 'src_mod': _mod or 'SYS', 'src_act': _act or '',
                    'event_id': str((_arb_evt or {}).get('event_id') or ''),
                    'req_id': str((_arb_evt or {}).get('req_id') or ''),
                    'trace_id': str((_arb_evt or {}).get('trace_id') or ''),
                    'winner': _arb_winner_module_name(_mod or ''),
                    'grid_changed': int(_grid_changed_total),
                    'a1_changed': bool(_a1_changed_any),
                    'bucket_reset_called': bool(_bucket_reset_any),
                    'round_block_applied': bool(_round_block_any),
                    'arb_accepted': bool(_arb_accept_any),
                    'scopes': _scope_rows,
                }
                try:
                    _seed_rows = []
                    for _scope in list(_reset_scopes or []):
                        try:
                            _coin_s = str((_scope or {}).get('coin') or _coin or '').upper().strip()
                            _plat_s = str((_scope or {}).get('platform') or _plat or '').upper().strip()
                            _side_s = str((_scope or {}).get('side') or _side or '').upper().strip()
                            _seed_rep = _m9_seed_immediate_coldstart_after_full_close(_coin_s, _plat_s, _side_s, post_state=post_state, snapshot=snapshot, req_any=req_any, reason=_arb_reason, src_mod=_mod or 'SYS', src_act=_act or '', req_id=str((_arb_evt or {}).get('req_id') or ''), trace_id=str((_arb_evt or {}).get('trace_id') or ''))
                            _seed_rows.append(dict(_seed_rep or {}))
                        except Exception as _e_seed:
                            _record_swallowed_exception('state_reset_seed_immediate_coldstart', _e_seed)
                            continue
                    rep['state_reset']['immediate_coldstart'] = _seed_rows
                except Exception as _e_seed_outer:
                    _record_swallowed_exception('state_reset_seed_immediate_coldstart_outer', _e_seed_outer)
                if _skip_reasons and not _arb_accept_any:
                    rep['state_reset']['skip'] = ';'.join(sorted(set(_skip_reasons)))
        try:
            if rep['trade_effective_count'] > 0 and _coin and _is_reduce_action(_act):
                _close_scopes = []
                if isinstance(rep.get('state_reset'), dict) and isinstance((rep.get('state_reset') or {}).get('scopes'), list):
                    _close_scopes = [dict(x) for x in list((rep.get('state_reset') or {}).get('scopes') or []) if isinstance(x, dict)]
                if not _close_scopes:
                    _close_scopes = [{'coin': _coin, 'platform': _plat, 'side': _side, 'source': 'req_identity'}]
                rep['coin_pool_post_close_refresh'] = _coin_pool_refresh_after_confirmed_close(
                    snapshot if isinstance(snapshot, dict) else {},
                    post_state if isinstance(post_state, dict) else {},
                    _close_scopes,
                    reason=str(ok_reason or 'postcheck_ok'),
                    src_mod=str(_mod or ''),
                )
        except Exception as _e_pool:
            rep['coin_pool_post_close_refresh_error'] = repr(_e_pool)
    except Exception as _e:
        _log_exc(mod='SYS', stage='EXC_PASS', e=_e)
        rep['state_reset_error'] = repr(_e)
    return rep

def _state_commit_postcheck_fail(*, req_any, pre_state: dict | None, post_state: dict | None, exec_res_list: list | None, fail_reason: str = '', fail_detail: Any = None) -> dict:
    """失败后的唯一收口入口：禁止 trade_effective，保留审计，不允许状态落账。

    例外收口：M9 increase 若 postcheck 失败但已见 submit/fill 痕迹，必须把同层冻结进 recovering_open，
    不能直接当成“完全没下成”，否则下一轮会把同一个 L2 再开一次。
    """
    rep = {'postcheck_marked': 0, 'trade_effective_count': 0, 'audit_written': False}
    _all_exec = list(exec_res_list or [])
    _marked = _mark_exec_results_postcheck(_all_exec, ok=False, reason=str(fail_reason or 'postcheck_fail'), detail=fail_detail)
    rep['postcheck_marked'] = len(_marked)
    rep['trade_effective_count'] = sum(1 for _r in _marked if _result_is_trade_effective(_r))
    _synthetic_commit = bool(_is_synthetic_or_selfcheck_event(req_any=req_any, exec_res_list=_marked, ok_detail=fail_detail))
    rep['synthetic_commit'] = _synthetic_commit
    try:
        rep['execution_evidence'] = _build_execution_evidence(req_any=req_any, exec_res_list=_marked, pre_state=pre_state, post_state=post_state, snapshot=None, ok=False, reason=str(fail_reason or 'postcheck_fail'), detail=fail_detail)
        _attach_execution_evidence(_marked, rep.get('execution_evidence'))
    except Exception as _e:
        rep['execution_evidence_error'] = repr(_e)
    try:
        if _synthetic_commit:
            rep['executor_result_updates_written'] = 0
            rep['executor_result_updates_skipped_reason'] = 'synthetic_event'
        else:
            rep['executor_result_updates_written'] = int(_exec_results_write_updates(
                _marked,
                kind="executor_result_update",
                extra={"stage": "state_commit_postcheck_fail", "ok": False, "fail_reason": str(fail_reason or 'postcheck_fail')},
            ))
    except Exception:
        rep['executor_result_updates_written'] = 0
    try:
        _audit_executor_action(
            req_any=req_any,
            pre_state=pre_state,
            post_state=post_state,
            exec_res_list=_marked,
            ok=False,
            reason=str(fail_reason or 'postcheck_fail'),
            detail=(fail_detail if isinstance(fail_detail, dict) else {'detail': fail_detail}),
        )
        rep['audit_written'] = True
    except Exception as _e:
        _log_exc(mod='SYS', stage='EXC_PASS', e=_e)
        rep['audit_error'] = repr(_e)
    try:
        _mod, _act, _coin, _plat, _side = _req_identity_tuple(req_any)
        _meta = {}
        if isinstance(req_any, dict):
            _meta = req_any.get('meta') if isinstance(req_any.get('meta'), dict) else {}
        else:
            _meta = getattr(req_any, 'meta', None) if isinstance(getattr(req_any, 'meta', None), dict) else {}
        if str(_mod or '').upper() == 'M9' and str(_act or '').lower().strip() in ('increase', 'add', 'open') and _coin:
            try:
                _ev = dict(rep.get('execution_evidence') or {}) if isinstance(rep.get('execution_evidence'), dict) else {}
                _freeze_needed = bool(_ev.get('submit_ok') or _ev.get('fill_seen'))
                if _freeze_needed:
                    rep['m9_recovering_open_guard'] = bool(_grid_pending_open_mark_legacy_deleteding(
                        req_any=req_any,
                        execution_evidence=_ev,
                        reason=str(fail_reason or 'postcheck_fail'),
                        detail=fail_detail,
                    ))
            except Exception as _e_guard:
                rep['m9_recovering_open_guard_error'] = repr(_e_guard)
        if str(_mod or '').upper() == 'M9' and str(_act or '').lower().strip() in ('decrease', 'reduce', 'close', 'tp', 'trend_tp') and _coin:
            _rr = _m9_register_recent_reduce_fail(
                _coin, _plat, _side,
                reason=str(fail_reason or 'postcheck_fail'),
                detail=(fail_detail if isinstance(fail_detail, dict) else {'detail': fail_detail}),
                req_id=str((_meta.get('req_id') if isinstance(_meta, dict) else '') or (req_any.get('request_id') if isinstance(req_any, dict) else getattr(req_any, 'request_id', '')) or ''),
                trace_id=str((_meta.get('trace_id') if isinstance(_meta, dict) else '') or ''),
            )
            rep['recent_reduce_fail'] = dict(_rr or {})
            try:
                _gid = str((_meta.get('grid_id') if isinstance(_meta, dict) else '') or (req_any.get('grid_id') if isinstance(req_any, dict) else getattr(req_any, 'grid_id', '')) or '').strip()
                _lid = str((_meta.get('layer_id') if isinstance(_meta, dict) else '') or '').strip()
                if _gid and _lid and ('GRID_BOOK' in globals()) and GRID_BOOK and hasattr(GRID_BOOK, 'clear_close_pending'):
                    GRID_BOOK.clear_close_pending(_gid, _lid, reason=f'postcheck_fail:{str(fail_reason or "postcheck_fail")}')
                    rep['pending_rollback'] = {'grid_id': _gid, 'layer_id': _lid, 'reason': str(fail_reason or 'postcheck_fail')}
            except Exception as _e:
                _log_exc(mod='SYS', stage='EXC_PASS', e=_e)
        if _coin and (_m10_should_preempt_m9(req_any) or _b2_should_preempt_m9(req_any)):
            _m10_release_pending_preempt(
                _coin,
                _plat,
                _side,
                reason=str(fail_reason or 'postcheck_fail'),
                src_mod=str(_mod or 'M10'),
                src_act=str(_act or ''),
                req_id=str((_meta.get('req_id') if isinstance(_meta, dict) else '') or (req_any.get('request_id') if isinstance(req_any, dict) else getattr(req_any, 'request_id', '')) or ''),
                trace_id=str((_meta.get('trace_id') if isinstance(_meta, dict) else '') or ''),
            )
            rep['preempt_release'] = True
        if str(_mod or '').upper().strip() == 'M10' and str(_act or '').lower().strip() == 'koujing_a_3step' and _coin:
            _step_meta = _m10_postcheck_collect_step_meta(req_any, _marked)
            _step_ok = dict((_step_meta or {}).get('step_ok') or {})
            _expected = dict((_step_meta or {}).get('expected') or {})
            _has_effect_trace = bool(_step_ok) or bool((fail_detail or {}).get('exec_submit_ok') if isinstance(fail_detail, dict) else False) or bool((fail_detail or {}).get('exec_fill_evidence') if isinstance(fail_detail, dict) else False)
            if _has_effect_trace:
                _pending_kind = 'step3_reopen'
                _pending_state = 'step3_reopen'
                _blocking = True
                if _step_ok and (not bool(_step_ok.get(2))):
                    _pending_kind = 'retry_step2_then_step3'
                    _pending_state = 'retry_step2_then_step3'
                    _blocking = False
                _m10_reopen_mark_pending(
                    _coin,
                    platform=str(_expected.get('platform') or _plat or ''),
                    side=str(_expected.get('side') or _side or ''),
                    amount_u=float(_expected.get('amount_u') or 0.0),
                    reason=str(fail_reason or 'postcheck_fail'),
                    source_mod='M10',
                    req_id=str((_meta.get('req_id') if isinstance(_meta, dict) else '') or (req_any.get('request_id') if isinstance(req_any, dict) else getattr(req_any, 'request_id', '')) or ''),
                    trace_id=str((_meta.get('trace_id') if isinstance(_meta, dict) else '') or ''),
                    pending_kind=_pending_kind,
                    state=_pending_state,
                    blocking=bool(_blocking),
                    ttl_sec=(90.0 if not _blocking else 180.0),
                    last_fail_reason=str(fail_reason or 'postcheck_fail'),
                )
                rep['m10_reopen_pending'] = {
                    'kind': _pending_kind,
                    'state': _pending_state,
                    'blocking': bool(_blocking),
                    'reason': str(fail_reason or 'postcheck_fail'),
                }
    except Exception as _e:
        _log_exc(mod='SYS', stage='EXC_PASS', e=_e)
    return rep

def _legacy_m9_run_round_disabled(menhu: 'GOMenHu', snapshot: dict, coins: list[str]) -> dict:
    """[REMOVED_LEGACY_M9] 旧 M9 逻辑已移除，仅保留空壳占位，避免任何残留调用。"""
    return {'ok': True, 'skip': True, 'reason': 'legacy_m9_removed', 'plans': [], 'summary': ''}

def _m9_last_action_ts_coin(coin: str) -> float:
    """从 M9_STATS 里取该 coin 最近一次真实执行动作的时间戳（秒）。"""
    c = str(coin or '').upper()
    try:
        evs = (_M9_STATS.get('action_events', {}) or {}).get(c, [])
    except Exception:
        evs = []
    last_ts = 0.0
    for it in (evs or []):
        try:
            ts = float((it or {}).get('ts') or 0.0)
            if ts > last_ts:
                last_ts = ts
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    return float(last_ts)

def _sorted_coins_by_notional(snapshot: dict, coins: list[str]) -> list[str]:
    """按总名义（EXT+VAR 绝对值）从大到小排序币种。

    - 仅用于输出/模块汇报的展示顺序，不改变策略本身。
    - 若快照缺字段或计算失败，回退原 coins 顺序。
    """
    try:
        rows = []
        for c in (coins or []):
            try:
                ext_u = float(_get_notional_u(snapshot, c, 'EXT') or 0.0)
            except Exception:
                ext_u = 0.0
            try:
                var_u = float(_get_notional_u(snapshot, c, 'VAR') or 0.0)
            except Exception:
                var_u = 0.0
            tot = abs(ext_u) + abs(var_u)
            rows.append((c, tot))
        rows.sort(key=lambda x: (-x[1], x[0]))
        return [c for c, _ in rows]
    except Exception:
        return list(coins or [])

def _m10_single_leg_notional_rank_map(snapshot: dict | None = None, coins: list[str] | None = None) -> dict[str, int]:
    """按“单腿金额=max(EXT,VAR)”从大到小给币种排名。仅供 M10 触发阈值使用。"""
    try:
        snap = snapshot if isinstance(snapshot, dict) else {}
        base_coins: list[str] = []
        if isinstance(coins, list) and coins:
            base_coins = [str(x or '').upper().strip() for x in coins if str(x or '').strip()]
        if not base_coins:
            try:
                base_coins = [str(x or '').upper().strip() for x in list(globals().get('COINS') or globals().get('COINS_DEFAULT') or []) if str(x or '').strip()]
            except Exception:
                base_coins = []
        if not base_coins:
            try:
                pos = ((snap or {}).get('positions') or {})
                names = set()
                for pf in ('EXT', 'VAR'):
                    pd = pos.get(pf) if isinstance(pos.get(pf), dict) else {}
                    for k in (pd or {}).keys():
                        ku = str(k or '').upper().strip()
                        if ku:
                            names.add(ku)
                base_coins = sorted(names)
            except Exception:
                base_coins = []
        rows: list[tuple[str, float, float]] = []
        seen = set()
        for c in (base_coins or []):
            cu = str(c or '').upper().strip()
            if not cu or cu in seen:
                continue
            seen.add(cu)
            try:
                ext_u = abs(float(_get_notional_u(snap, cu, 'EXT') or 0.0))
            except Exception:
                ext_u = 0.0
            try:
                var_u = abs(float(_get_notional_u(snap, cu, 'VAR') or 0.0))
            except Exception:
                var_u = 0.0
            leg_u = max(ext_u, var_u)
            tot_u = ext_u + var_u
            rows.append((cu, leg_u, tot_u))
        rows.sort(key=lambda x: (-x[1], -x[2], x[0]))
        return {c: idx + 1 for idx, (c, _, _) in enumerate(rows)}
    except Exception:
        return {}

def _m10_trigger_pct_for_coin(coin: str, *, snapshot: dict | None = None, coins: list[str] | None = None, default: float = 0.01) -> float:
    """M10 统一口径：近24小时波动 × 10%，老币/新币统一最低 1%，最高 20%。"""
    try:
        pct, _det = _coin_unified_trigger_pct(str(coin or ''), default=default, floor_override=_tp_trigger_floor_pct(coin), cap_override=_tp_trigger_cap_pct(coin), trigger_tag='B2_M10')
        return float(pct)
    except Exception:
        return float(max(_tp_trigger_floor_pct(coin), float(default or 0.01)))

def _m10_trigger_pct_by_root(root: Any, coin: str, *, default: float = 0.01, coins: list[str] | None = None) -> float:
    """给内嵌 b2m10 用：与主链完全同口径（最低1%）。"""
    try:
        pct, _det = _coin_unified_trigger_pct(str(coin or ''), default=default, floor_override=_tp_trigger_floor_pct(coin), cap_override=_tp_trigger_cap_pct(coin), trigger_tag='B2_M10')
        return float(pct)
    except Exception:
        return float(max(_tp_trigger_floor_pct(coin), float(default or 0.01)))

def _m10_trigger_need_u_for_coin(coin: str, loss_notional: Any, *, snapshot: dict | None = None, coins: list[str] | None = None, default: float = 0.01) -> float:
    try:
        ln = float(loss_notional or 0.0)
    except Exception:
        ln = 0.0
    if ln <= 0.0:
        return 0.0
    try:
        pct = float(_m10_trigger_pct_for_coin(str(coin or ''), snapshot=snapshot, coins=coins, default=default) or default)
    except Exception:
        pct = float(default or 0.01)
    try:
        return float(max(0.0, ln * pct))
    except Exception:
        return 0.0

def _m10_calc_step2_close_u10(target_close_u: Any, loss_notional_u: Any) -> dict:
    """M10 Step2 唯一金额口径。
    人话：第二步只能向下取整十，绝不允许向上补到 20/30/40。
    若向下取整后不足 10U，或超过亏损腿 95% 上限，则直接判定本轮等待。
    """
    rep = {
        'target_close_u': 0.0,
        'loss_notional_u': 0.0,
        'final_u': 0.0,
        'cap_u': 0.0,
        'rounding': 'floor10_no_raise',
        'min_u': 10.0,
        'rule': 'm10_step2_floor10_exact_reduce',
        'wait': True,
        'reason': 'target_le_0',
    }
    try:
        rep['target_close_u'] = max(0.0, float(target_close_u or 0.0))
    except Exception:
        rep['target_close_u'] = 0.0
    try:
        rep['loss_notional_u'] = max(0.0, float(loss_notional_u or 0.0))
    except Exception:
        rep['loss_notional_u'] = 0.0
    rep['cap_u'] = max(0.0, float(rep['loss_notional_u']) * 0.95)
    if float(rep['target_close_u']) <= 0.0:
        return rep
    if float(rep['cap_u']) < 10.0:
        rep['reason'] = 'loss_cap_lt_10_wait'
        return rep
    _raw = min(float(rep['target_close_u']), float(rep['cap_u']))
    try:
        _floor_u = float(int(float(_raw) // 10) * 10)
    except Exception:
        _floor_u = 0.0
    if _floor_u < 10.0:
        rep['reason'] = 'floor10_lt_10_wait'
        rep['final_u'] = 0.0
        return rep
    rep['final_u'] = float(min(_floor_u, rep['cap_u']))
    if float(rep['final_u']) < 10.0:
        rep['final_u'] = 0.0
        rep['reason'] = 'post_cap_lt_10_wait'
        return rep
    rep['wait'] = False
    rep['reason'] = 'ok'
    return rep


def _m10_calc_step3_reopen_u10(loss_remain_u: Any, pct: float | None = None) -> dict:
    """M10 Step3 重开金额唯一口径。
    人话：按亏损腿 step2 后剩余名义的指定比例计算，再向上收口到整十；
    但仍保留最小有效下单 40U。
    """
    _pct = float(pct if pct is not None else M10_STEP3_REOPEN_PCT)
    _pct = max(0.10, min(1.20, _pct))
    rep = {
        'loss_remain_u': 0.0,
        'target_u': 0.0,
        'final_u': 40.0,
        'pct': float(_pct),
        'rounding': 'ceil10',
        'min_u': 40.0,
        'rule': 'reopen_loss_leg_dynamic_u10',
    }
    try:
        rep['loss_remain_u'] = max(0.0, float(loss_remain_u or 0.0))
    except Exception:
        rep['loss_remain_u'] = 0.0
    try:
        rep['target_u'] = max(0.0, float(rep['loss_remain_u']) * float(_pct))
    except Exception:
        rep['target_u'] = 0.0
    try:
        _loss_u = float(rep['loss_remain_u'])
        _base_u = float(max(40.0, rep['target_u']))
        if _loss_u < 40.0:
            rep['final_u'] = 40.0
        else:
            rep['final_u'] = float(int((_base_u + 9.999999999) // 10) * 10)
    except Exception:
        _loss_u = float(rep.get('loss_remain_u') or 0.0)
        _base_u = float(max(40.0, float(rep['target_u'])))
        if _loss_u < 40.0:
            rep['final_u'] = 40.0
        else:
            rep['final_u'] = float(int((_base_u + 9.999999999) // 10) * 10)
    if float(rep['final_u']) < 40.0:
        rep['final_u'] = 40.0
    return rep

def _m10_calc_step3_reopen_70pct_u10(loss_remain_u: Any) -> dict:
    return _m10_calc_step3_reopen_u10(loss_remain_u, pct=0.70)

