def _pipe_group_of_req(req) -> str:
    """把请求映射到流水线分组（唯一真相源：ANCHOR→B2→M10→B1→M9→OTHER）。"""
    try:
        m = _norm_module_name(getattr(req, 'module', '') or '').upper().strip()
    except Exception:
        try:
            m = _norm_module_name((req.get('module') if isinstance(req, dict) else '') or '').upper().strip()
        except Exception:
            m = ''
    if m == 'B2':
        return 'B2'
    if m == 'M10':
        return 'M10'
    if m in ('M9', ("M9" + "X")):
        return 'M9'
    if m == 'B1':
        return 'B1'
    if m == 'ANCHOR':
        return 'ANCHOR'
    return 'OTHER'

def _pipe_group_rank(g: str) -> int:
    order = ['ANCHOR', 'B2', 'M10', 'B1', 'M9', 'OTHER']
    try:
        return order.index(str(g or 'OTHER'))
    except Exception:
        return len(order) - 1

def _reason_human_cn(reason: Any) -> str:
    r = _normalize_reason_code(reason)
    if not r:
        return "无请求"
    reg = _reason_registry_get(r)
    if reg.get("human"):
        return str(reg.get("human") or "")
    if r.startswith("hardcap_block"):
        return "硬顶拦截"
    if r.startswith("planned_and_submitted"):
        return "已计划并已提交"
    return str(reason or r)

def _m9_human_reason_from_entry(entry: Any) -> str:
    try:
        d = dict(entry or {}) if isinstance(entry, dict) else {}
    except Exception:
        d = {}
    reason = str(_primary_reason_for_output(d, default='NO_REQUEST') or '')
    rr = _normalize_reason_code(reason)
    req_leg = str(d.get('request_leg') or '')
    cold_state = str(d.get('cold_start_state') or '')
    req_drop_events = d.get('req_drop_events') if isinstance(d.get('req_drop_events'), list) else []
    last_drop = dict(req_drop_events[-1] or {}) if req_drop_events else {}
    pre = d.get('m9_pre_adjudication') if isinstance(d.get('m9_pre_adjudication'), dict) else {}
    hardcap_detail = (pre.get('hardcap_detail') if isinstance(pre.get('hardcap_detail'), dict) else {}) if isinstance(pre, dict) else {}
    cur_px = d.get('cur_px')
    need_px = d.get('gap_need_px', d.get('need_px'))
    last_px = d.get('last_real_m9_px', d.get('last_px'))
    if not cur_px and isinstance(last_drop, dict):
        cur_px = last_drop.get('cur_px', cur_px)
        need_px = last_drop.get('need_px', need_px)
        last_px = last_drop.get('last_px', last_px)
    if rr in ('grid_gap_not_reached', 'allowed_leg_seen_but_no_candidate'):
        drop_reason = _normalize_reason_code(last_drop.get('reason') or rr)
        if drop_reason == 'grid_gap_not_reached':
            if int(d.get('request_leg_has_pos') or 0) == 1 and int(d.get('request_leg_real_m9_open_layers') or 0) == 0:
                base = '冷启动首层应放行，但被普通 gap 误拦'
            else:
                base = '网格间距未到'
            bits = []
            if req_leg:
                bits.append(req_leg)
            try:
                _last_no = d.get('last_real_layer_no')
                _next_no = d.get('next_layer_no')
                if _last_no is not None:
                    bits.append(f"最后层=L{int(_last_no)}")
                if _next_no is not None:
                    bits.append(f"下一层=L{int(_next_no)}")
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_745', _e)
                pass
            try:
                if cur_px is not None and need_px is not None:
                    bits.append(f"现价={float(cur_px):g}")
                    bits.append(f"触发价={float(need_px):g}")
                elif last_px is not None:
                    bits.append(f"上一层价={float(last_px):g}")
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_746', _e)
                pass
            return base + ("（" + '，'.join(bits) + "）" if bits else "")
    if rr in ('grid_risk_block_hourly_limit', 'grid_risk_block_consec_limit', 'grid_risk_block_daily_limit') or rr.startswith('grid_risk_block'):
        _risk_map = {
            'grid_risk_block_hourly_limit': '每小时风控拦截',
            'grid_risk_block_consec_limit': '连续开仓风控拦截',
            'grid_risk_block_daily_limit': '每日风控拦截',
        }
        base = _risk_map.get(rr, '风控拦截')
        bits = []
        if req_leg:
            bits.append(req_leg)
        try:
            _rd = d.get('risk_detail') if isinstance(d.get('risk_detail'), dict) else {}
            _opens = _rd.get('opens_last_hour')
            _wait = _rd.get('wait_sec')
            if _opens is not None:
                bits.append(f"近1小时开仓={int(_opens)}")
            if _wait is not None:
                bits.append(f"等待={int(float(_wait))}s")
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_747', _e)
            pass
        try:
            if cur_px is not None and need_px is not None:
                bits.append(f"现价={float(cur_px):g}")
                bits.append(f"触发价={float(need_px):g}")
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_748', _e)
            pass
        return base + ("（" + '，'.join(bits) + "）" if bits else "")
    if rr == 'layer_id_discontinuity':
        bits = []
        if req_leg:
            bits.append(req_leg)
        try:
            _nos = list(d.get('request_leg_real_open_layer_nos') or [])
            if _nos:
                bits.append('层号=' + '/'.join([f"L{int(x)}" for x in _nos]))
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_749', _e)
            pass
        try:
            _next = d.get('next_layer_no')
            if _next is not None:
                bits.append(f"拟开=L{int(_next)}")
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_750', _e)
            pass
        return '层号不连续，禁止跳层开仓' + ("（" + '，'.join(bits) + "）" if bits else "")
    if rr.startswith('hardcap_block'):
        base = '冷启动已放行，但被硬顶拦截' if str(cold_state).upper() == 'FIRST_REAL_LAYER' else '硬顶拦截'
        bits = []
        if req_leg:
            bits.append(req_leg)
        try:
            _used = hardcap_detail.get('used_u', hardcap_detail.get('now_u'))
            _cap = hardcap_detail.get('cap_u', hardcap_detail.get('max_u'))
            _left = hardcap_detail.get('left_u', hardcap_detail.get('remain_u'))
            if _used is not None and _cap is not None:
                bits.append(f"占用={float(_used):g}/{float(_cap):g}U")
            if _left is not None:
                bits.append(f"剩余={float(_left):g}U")
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_751', _e)
            pass
        return base + ("（" + '，'.join(bits) + "）" if bits else "")
    base = _reason_human_cn(reason)
    if rr in ('allowed_leg_seen_but_no_candidate', 'no_candidate_generated'):
        try:
            _layers = int(d.get('request_leg_real_m9_open_layers') or 0)
            if _layers == 0 and str(cold_state).upper() != 'FIRST_REAL_LAYER':
                base = '应冷启动但未进入冷启动链'
            elif _layers >= 1:
                base = '已有网格层，但未形成候选请求'
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_752', _e)
            pass
    bits = []
    if req_leg and (not _reason_is_explicit_idle(rr)) and rr not in ('INTERNAL_REASON_CHAIN_BROKEN', 'not_triggered_or_filtered'):
        bits.append(req_leg)
    if str(cold_state).upper() == 'FIRST_REAL_LAYER' and '冷启动' not in base:
        bits.append('冷启动首层')
    return base + ("（" + '，'.join(bits) + "）" if bits else "")

def _build_module_report_lines(module_name: str, snapshot: dict, coins_sorted: list[str],
                               exec_recs: list[dict], probe_events: list[dict], report_extra: dict | None = None) -> list[str]:
    """生成单模块 8 币汇报（执行动作 + 不执行原因）。"""
    by_coin_exec: dict[str, list[dict]] = {}
    for r in (exec_recs or []):
        try:
            req = (r or {}).get('req')
            if not isinstance(req, dict):
                continue
            coin = str(req.get('coin') or '').upper().strip()
            if not coin:
                continue
            by_coin_exec.setdefault(coin, []).append(r)
        except Exception:
            continue

    last_probe: dict[tuple[str,str], dict] = {}
    for e in (probe_events or []):
        try:
            mod = str(e.get('module') or '').upper().strip()
            coin = str(e.get('coin') or '').upper().strip()
            if not mod or not coin:
                continue
            last_probe[(mod, coin)] = e
        except Exception:
            continue

    def _fmt_side_cn(s: str) -> str:
        ss = str(s or '').upper()
        if ss == 'LONG':
            return 'LONG（多）'
        if ss == 'SHORT':
            return 'SHORT（空）'
        return 'NONE（无）'

    def _fmt_u(x) -> str:
        try:
            return f"{float(x):.0f}"
        except Exception:
            return '-'

    def _best_probe_for_coin(coin: str):
        c = coin
        mod = str(module_name or '').upper().strip()
        if mod == MOD_LEGACY_FIX:
            for mm in ('GO', 'LEGACY_DELETED', 'LEGACY_DELETED'):
                if (mm, c) in last_probe:
                    return last_probe[(mm, c)]
            return None
        if mod == "M10":
            for mm in ("M10", 'M10_PURE_TP_KOUJING_A'):
                if (mm, c) in last_probe:
                    return last_probe[(mm, c)]
            return None
        return last_probe.get((mod, c))

    lines: list[str] = []
    header = (
        "币种 | 总名义U（两平台） | EXT 名义U | EXT 方向 | EXT UPnL(U) | "
        "VAR 名义U | VAR 方向 | VAR UPnL(U) | 差额U | 本模块结果 | 原因（中文）"
    )
    lines.append(header)

    cnt_exec_ok = 0
    cnt_exec_fail = 0
    cnt_reject = 0
    cnt_no_req = 0

    for coin in (coins_sorted or []):
        ext_u = _get_notional_u(snapshot, coin, 'EXT')
        var_u = _get_notional_u(snapshot, coin, 'VAR')
        tot_u = abs(float(ext_u or 0.0)) + abs(float(var_u or 0.0))
        ext = _get_snapshot_coin_leg(snapshot, coin, 'EXT')
        var = _get_snapshot_coin_leg(snapshot, coin, 'VAR')
        ext_side = _fmt_side_cn(ext.get('side'))
        var_side = _fmt_side_cn(var.get('side'))
        ext_upnl = _get_upnl_usd(snapshot, coin, 'EXT')
        var_upnl = _get_upnl_usd(snapshot, coin, 'VAR')
        diff_abs = _abs_hedge_diff_u(snapshot, coin)
        status = 'SKIP（跳过）'
        reason = 'NO_REQUEST（无请求/未触发）'
        extra_entry = {}
        try:
            if isinstance(report_extra, dict):
                extra_entry = dict(report_extra.get(str(coin)) or report_extra.get(str(coin).upper()) or {})
        except Exception:
            extra_entry = {}

        if coin in by_coin_exec:
            rs = by_coin_exec[coin]
            ok_any = any(bool((x or {}).get('ok')) for x in rs)
            if ok_any:
                cnt_exec_ok += 1
                status = 'EXEC_OK（已执行）'
                try:
                    req = (rs[0] or {}).get('req') or {}
                    plat = str(req.get('platform') or '-').upper()
                    act = str(req.get('action_type') or '-')
                    amt = (req.get('params') or {}).get('amount_usd') or (req.get('params') or {}).get('usd') or (req.get('params') or {}).get('amount_u')
                    reason = f"{act}（动作）@{plat}（平台） { _fmt_u(amt) }U（金额）"
                except Exception:
                    reason = 'ok（成功）'
            else:
                cnt_exec_fail += 1
                status = 'EXEC_FAIL（执行失败）'
                rr = ''
                for x in rs:
                    if not bool((x or {}).get('ok')):
                        rr = str((x or {}).get('reason') or (x or {}).get('err') or '')
                        if rr:
                            break
                reason = rr[:120] if rr else 'fail（失败）'
        else:
            pe = _best_probe_for_coin(coin)
            if isinstance(pe, dict):
                if pe.get('ok') is True:
                    status = 'ENQUEUED（已入队）'
                    reason = f"stage={pe.get('stage','-')}（阶段）"
                else:
                    cnt_reject += 1
                    status = 'REJECT（拒绝）'
                    rc = str(pe.get('reject_code') or '-')
                    rr = str(pe.get('reject_reason') or '-')
                    reason = f"{rc}（拒绝码） {rr}（原因）"
            else:
                cnt_no_req += 1
                if str(module_name or '').upper().strip() == 'M9' and isinstance(extra_entry, dict) and extra_entry:
                    reason = _m9_human_reason_from_entry(extra_entry)
                elif isinstance(extra_entry, dict) and extra_entry:
                    reason = _reason_human_cn(_primary_reason_for_output(extra_entry, default='NO_REQUEST'))

        line = (
            f"{coin:<5} | {tot_u:>10.0f} | {float(ext_u or 0.0):>8.0f} | {ext_side:<9} | {float(ext_upnl or 0.0):>8.1f} | "
            f"{float(var_u or 0.0):>8.0f} | {var_side:<9} | {float(var_upnl or 0.0):>8.1f} | {float(diff_abs or 0.0):>7.0f} | "
            f"{status:<12} | {reason}"
        )
        lines.append(line)

    lines.append("")
    lines.append(
        f"小结（汇总）: EXEC_OK（已执行）={cnt_exec_ok} | EXEC_FAIL（执行失败）={cnt_exec_fail} | REJECT（拒绝）={cnt_reject} | NO_REQUEST（无请求）={cnt_no_req}"
    )
    return lines

def _m9_build_decision_summary_payload(payload: dict | None, row_limit: int = 8) -> dict:
    payload = payload if isinstance(payload, dict) else {}
    rows = list(payload.get('rows') or [])
    meta = dict(payload.get('meta') or {}) if isinstance(payload.get('meta'), dict) else {}
    rows = [r for r in rows if isinstance(r, dict)]
    selected_rows = [r for r in rows if int(r.get('selected') or 0) == 1]
    skipped_rows = [r for r in rows if int(r.get('selected') or 0) != 1]
    m9_state_debug = dict(meta.get('m9_state_debug') or {}) if isinstance(meta.get('m9_state_debug'), dict) else {}
    executed_coins = [str(x or "").upper() for x in list(m9_state_debug.get('exec_coins') or []) if str(x or "").strip()]
    if not executed_coins and str(m9_state_debug.get('exec_coin') or "").strip():
        executed_coins = [str(m9_state_debug.get('exec_coin') or "").upper()]
    candidate_coins = [str(r.get('coin') or "").upper() for r in selected_rows[:8]]
    reason_counter = {}
    for r in skipped_rows:
        _reason = _primary_reason_for_output(r, default='NO_REQUEST')
        reason_counter[_reason] = int(reason_counter.get(_reason, 0) or 0) + 1
    top_final_reasons = [
        {'reason': str(k), 'count': int(v)}
        for k, v in sorted(reason_counter.items(), key=lambda kv: (-int(kv[1]), str(kv[0])))[:6]
    ]
    head = []
    rows_out = []
    for r in rows[:max(1, int(row_limit or 8))]:
        _coin = str(r.get('coin') or '').upper()
        _sel = int(r.get('selected') or 0)
        _ff = _final_fields_for_output(r, default_reason='NO_REQUEST', default_stage=_entry_stage_view(r, default=''))
        _reason = str(_ff.get('final_reason') or 'NO_REQUEST')
        _stage = str(_ff.get('final_stage') or _entry_stage_view(r, default=''))
        _status = '已选中' if _sel else '未选中'
        head.append(f"#{int(r.get('rank') or 0)}:{_coin}|{_status}|因={_reason}")
        rows_out.append({
            'rank': int(r.get('rank') or 0),
            'coin': _coin,
            'selected': _sel,
            'selected_text': _status,
            'reason': _reason,
            'stage': _stage,
            'candidate': r.get('candidate'),
            'score': r.get('score'),
            'trend_state': str(r.get('trend_state') or ''),
            'trend_side': str(r.get('trend_side') or ''),
            'trend_reason': str(r.get('trend_reason') or ''),
            'freeze_loss_leg_new_grid': int(r.get('freeze_loss_leg_new_grid') or 0),
            'runner_protect': int(r.get('runner_protect') or 0),
            'opp_side_frozen': int(r.get('opp_side_frozen') or 0),
            'final_reason': _ff.get('final_reason'),
            'final_reason_code': _ff.get('final_reason_code'),
            'final_stage': _ff.get('final_stage'),
            'final_verdict': _ff.get('final_verdict'),
        })
    return {
        'ts': payload.get('ts') or now_ts(),
        'mod': str(payload.get('mod') or 'M9'),
        'type': 'm9_decision_summary',
        'selected_count': int(len(executed_coins) if executed_coins else len(selected_rows)),
        'skipped_count': int(len(skipped_rows)),
        'selected_coins': list(executed_coins[:8] if executed_coins else candidate_coins[:8]),
        'candidate_coins': candidate_coins,
        'executed_coins': executed_coins,
        'top_final_reasons': top_final_reasons,
        'head': head,
        'rows': rows_out,
        'meta': meta,
        'm9_state_debug': m9_state_debug,
    }

def _m9_build_reason_rank_payload(payload: dict | None, row_limit: int = 8) -> dict:
    payload = payload if isinstance(payload, dict) else {}
    rows = [r for r in list(payload.get('rows') or []) if isinstance(r, dict)]
    meta = dict(payload.get('meta') or {}) if isinstance(payload.get('meta'), dict) else {}
    m9_state_debug = dict(meta.get('m9_state_debug') or payload.get('m9_state_debug') or {}) if isinstance(meta.get('m9_state_debug') or payload.get('m9_state_debug') or {}, dict) else {}
    executed_coins = [str(x or '').upper() for x in list(m9_state_debug.get('exec_coins') or []) if str(x or '').strip()]
    if executed_coins:
        rows2 = []
        for r in rows:
            rr = dict(r)
            if str(rr.get('coin') or '').upper() in executed_coins:
                rr['selected'] = 1
            rows2.append(rr)
        rows = rows2
    skipped_rows = [r for r in rows if int(r.get('selected') or 0) != 1]
    agg = {}
    for r in skipped_rows:
        _ff = _final_fields_for_output(r, default_reason='NO_REQUEST', default_stage=_entry_stage_view(r, default=''))
        _reason = str(_ff.get('final_reason') or 'NO_REQUEST')
        _it = agg.setdefault(_reason, {'reason': _reason, 'final_reason': _reason, 'final_reason_code': _ff.get('final_reason_code'), 'final_stage': _ff.get('final_stage'), 'final_verdict': _ff.get('final_verdict'), 'count': 0, 'coins': [], 'head': []})
        _it['count'] = int(_it.get('count') or 0) + 1
        _coin = str(r.get('coin') or '').upper()
        if _coin and _coin not in _it['coins']:
            _it['coins'].append(_coin)
        if len(_it['head']) < 4:
            _it['head'].append({'rank': int(r.get('rank') or 0), 'coin': _coin, 'stage': _entry_stage_view(r, default='')})
    rows_out = sorted(list(agg.values()), key=lambda x: (-int(x.get('count') or 0), str(x.get('reason') or '')))[:max(1, int(row_limit or 8))]
    for idx, it in enumerate(rows_out, start=1):
        it['order'] = int(idx)
        it['coins_text'] = '/'.join(list(it.get('coins') or [])[:6])
    return {
        'ts': payload.get('ts') or now_ts(),
        'mod': str(payload.get('mod') or 'M9'),
        'type': 'm9_reason_rank',
        'selected_count': int(len(executed_coins) if executed_coins else sum(1 for r in rows if int(r.get('selected') or 0) == 1)),
        'skipped_count': int(len(skipped_rows)),
        'rows': rows_out,
    }

def _write_round_priority_rank_log(mod: str, coins: list[str], touched: set[str], skipped: list[tuple[str, dict]], extra: dict | None = None) -> None:
    """把“本轮优先级排序 + 未选中原因”落成单独日志。
    - rank 按 coins 原顺序
    - selected=1 表示本轮进入过事件/请求链路（touched）
    - selected=0 表示未选中，并给出最终 reason
    输出：logs/out/round_priority_rank.jsonl
    """
    try:
        rows = []
        _payload_meta = {}
        if isinstance(extra, dict):
            try:
                _payload_meta = dict(extra.get('__meta__') or {}) if isinstance(extra.get('__meta__'), dict) else {}
            except Exception:
                _payload_meta = {}
        skipped_map = {str(c).upper(): (m if isinstance(m, dict) else {}) for c, m in (skipped or [])}
        for _idx, _coin in enumerate(coins or [], start=1):
            _cu = str(_coin or '').upper().strip()
            _extra = {}
            if isinstance(extra, dict):
                try:
                    _extra = (extra.get(str(_coin)) or extra.get(_cu) or {})
                except Exception:
                    _extra = {}
            _ev = dict(skipped_map.get(_cu) or {})
            if _extra:
                try:
                    _ev.update(dict(_extra or {}))
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_753', _e)
                    pass
            _selected = int(_cu in (touched or set()))
            _ff = _final_fields_for_output(_ev, default_reason=('selected' if _selected else 'NO_REQUEST'), default_stage=_entry_stage_view(_ev, default=''))
            _reason = 'selected' if _selected else str(_ff.get('final_reason') or 'NO_REQUEST')
            rows.append({
                'rank': int(_idx),
                'coin': _cu,
                'selected': _selected,
                'reason': _reason,
                'block_reason': str((_ev.get('final_reason') if isinstance(_ev, dict) and _ev.get('final_reason') else _ev.get('block_reason')) or ''),
                'candidate': _ev.get('candidate'),
                'stage': str(_ff.get('final_stage') or _entry_stage_view(_ev, default='')),
                'plan_state': _entry_plan_state_view(_ev, default=''),
                'score': _ev.get('score'),
                'module': str(mod or ''),
                'final_reason': _ff.get('final_reason'),
                'final_reason_code': _ff.get('final_reason_code'),
                'final_stage': _ff.get('final_stage'),
                'final_verdict': ('ACCEPTED' if _selected else _ff.get('final_verdict')),
            })
        payload = {
            'ts': now_ts(),
            'mod': str(mod or ''),
            'type': 'round_priority_rank',
            'selected_count': int(sum(int(r.get('selected') or 0) for r in rows)),
            'skipped_count': int(sum(1 for r in rows if not int(r.get('selected') or 0))),
            'rows': rows,
            'meta': _payload_meta,
        }
        try:
            if str(mod or '').upper().strip() == 'M9':
                for _r in list(rows or []):
                    _m9_round_final_note_row(_r)
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_754', _e)
            pass
        _bases = []
        for _base in (globals().get('LOGS_DIR'), globals().get('OUT_DIR')):
            try:
                if _base:
                    _bases.append(str(_base))
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_755', _e)
                pass
        for _base in _bases:
            try:
                _fp = os.path.join(str(_base), 'round_priority_rank.jsonl')
                write_jsonl(_fp, payload)
                safe_write_json(os.path.join(str(_base), 'round_priority_rank_last.json'), payload)
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_756', _e)
                pass
        try:
            if str(mod or '').upper().strip() == 'M9':
                _summary_payload = _m9_build_decision_summary_payload(payload, row_limit=8)
                _summary_payload['type'] = 'm9_decision_summary_planned'
                _summary_payload['meta'] = dict(_summary_payload.get('meta') or {})
                _summary_payload['meta']['source'] = 'PLANNED_PRE_EXEC_ONLY'
                _reason_payload = _m9_build_reason_rank_payload(payload, row_limit=8)
                for _base in _bases:
                    try:
                        safe_write_json(os.path.join(str(_base), 'm9_decision_summary_planned_last.json'), _summary_payload)
                        safe_write_json(os.path.join(str(_base), 'm9_reason_rank_last.json'), _reason_payload)
                        write_jsonl(os.path.join(str(_base), 'm9_reason_rank.jsonl'), _reason_payload)
                        if _payload_meta:
                            safe_write_json(os.path.join(str(_base), 'm9_state_debug_last.json'), _payload_meta)
                    except Exception as _e:
                        _record_swallowed_exception('except_pass_line_757', _e)
                        pass
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_758', _e)
            pass
    except Exception as _e:
        try:
            _log_exc(mod='SYS', stage='ROUND_PRIORITY_RANK_LOG_FAIL', e=_e)
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_759', _e)
            pass
def t_no_request(mod: str, coins: list[str], events: list[dict], snap: dict, *, extra: dict|None=None) -> None:
    if not VERBOSE_MODULE_TRACE:
        return
    try:
        _detail = bool(cfg_getb_runtime("TRACE_NO_REQUEST_DETAIL", False))
    except Exception:
        _detail = False
    try:
        _jsonl_detail = bool(cfg_getb_runtime("TRACE_NO_REQUEST_JSONL_DETAIL", False))
    except Exception:
        _jsonl_detail = False
    touched = set()
    for e in (events or []):
        c = e.get("coin")
        if c:
            touched.add(str(c).upper())
    skipped: list[tuple[str, dict]] = []
    reason_counter: dict[str, int] = {}
    for _idx, c in enumerate(coins or [], start=1):
        if str(c).upper() in touched:
            continue
        m = _coin_basic_metrics(snap, c)
        try:
            m.setdefault("rank", int(_idx))
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_760', _e)
            pass
        if extra:
            try:
                _k0 = str(c)
                _k1 = str(c).upper()
                m.update((extra.get(_k0) or extra.get(_k1) or {}) if isinstance(extra, dict) else {})
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)
        m.pop("coin", None)
        _ff = _final_fields_for_output(m, default_reason='NO_REQUEST', default_stage=_entry_stage_view(m, default=''))
        _reason = str(_ff.get('final_reason') or 'NO_REQUEST')
        reason_counter[_reason] = int(reason_counter.get(_reason, 0) or 0) + 1
        skipped.append((str(c).upper(), m))
        if _jsonl_detail:
            try:
                write_jsonl(DEFAULT_LOGFP, {"ts": now_ts(), "mod": str(mod), "type": "no_request", "coin": str(c).upper(), "evidence": m})
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)
        if _detail:
            tprint(mod, c, "NO_REQUEST", **m)
    try:
        _write_round_priority_rank_log(mod, list(coins or []), set(touched or set()), list(skipped or []), extra=extra)
    except Exception as _e:
        _log_exc(mod="SYS", stage="ROUND_PRIORITY_RANK_LOG_FAIL", e=_e)
    if skipped:
        try:
            _top = sorted(reason_counter.items(), key=lambda kv: (-int(kv[1]), str(kv[0])))[:5]
            _brief = ", ".join([f"{k}:{v}" for k, v in _top])
            _head_rows = []
            for _c, _m in skipped[:3]:
                try:
                    _head_rows.append({
                        "rank": int(_m.get("rank") or 0),
                        "coin": str(_c),
                        "reason": _primary_reason_for_output(_m, default='NO_REQUEST'),
                        "final_reason": _final_fields_for_output(_m, default_reason='NO_REQUEST', default_stage=_entry_stage_view(_m, default='')).get('final_reason'),
                        "final_reason_code": _final_fields_for_output(_m, default_reason='NO_REQUEST', default_stage=_entry_stage_view(_m, default='')).get('final_reason_code'),
                    })
                except Exception:
                    _head_rows.append({"coin": str(_c), "reason": "no_request"})
            _summary = {
                "ts": now_ts(),
                "mod": str(mod),
                "type": "no_request_summary",
                "count": int(len(skipped)),
                "touched": int(len(touched)),
                "coins": [c for c, _ in skipped[:8]],
                "reason_top": [{"reason": str(k), "count": int(v)} for k, v in _top],
                "head": _head_rows,
            }
            try:
                write_jsonl(DEFAULT_LOGFP, _summary)
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)
            tprint(mod, '-', 'NO_REQUEST_SUMMARY', count=len(skipped), coins="/".join([c for c, _ in skipped[:6]]) + ('...' if len(skipped) > 6 else ''), reasons=_brief, head=" | ".join([f"#{int(r.get('rank') or 0)}:{r.get('coin')}:{r.get('reason')}" for r in _head_rows]))
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

_PANEL_HOST = '127.0.0.1'
_PANEL_PORT = 0
_PANEL_URL = ''
_PANEL_OPENED_ONCE = False
_PANEL_LAST_LOOP = {}
_PANEL_LAST_METRICS = {}

_PROGRESS_CONSOLE_OVERRIDE = None
_CONSOLE_LAST_PRINT_TS = 0.0

def _grid_book_panel_root_dir() -> str:
    for _p in (globals().get('PANEL_OUT_DIR', ''), globals().get('OUT_DIR', '')):
        try:
            if _p:
                Path(str(_p)).mkdir(parents=True, exist_ok=True)
                return str(_p)
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_761', _e)
            pass
    try:
        _fb = os.path.join(os.path.dirname(__file__), 'out')
        os.makedirs(_fb, exist_ok=True)
        return _fb
    except Exception:
        return '.'

def _grid_book_panel_pick_port(host: str = '127.0.0.1', preferred: int = 5123) -> int:
    import socket
    ports = [preferred] + [preferred + i for i in range(1, 20)]
    for _port in ports:
        try:
            with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
                s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
                s.bind((host, int(_port)))
                return int(_port)
        except Exception:
            continue
    return 0

def _maybe_open_grid_book_panel(url: str) -> None:
    global _PANEL_OPENED_ONCE
    try:
        if _PANEL_OPENED_ONCE:
            return
        if not _env_flag('GRID_BOOK_AUTO_OPEN', False):
            return
        import webbrowser
        if webbrowser.open(str(url), new=1, autoraise=True):
            _PANEL_OPENED_ONCE = True
    except Exception as _e:
        _log_exc(mod='PANEL', stage='EXC_PASS', e=_e)

def start_web_panel_once():
    global _HTTPD, _HTTPD_THREAD, _PANEL_PORT, _PANEL_URL
    try:
        if globals().get('_HTTPD') is not None and globals().get('_HTTPD_THREAD') is not None:
            if getattr(globals().get('_HTTPD_THREAD'), 'is_alive', lambda: False)():
                return str(globals().get('_PANEL_URL') or '')
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_762', _e)
        pass
    try:
        root_dir = _grid_book_panel_root_dir()
        host = str(globals().get('_PANEL_HOST') or '127.0.0.1')
        port = int(globals().get('_PANEL_PORT') or 0) or _grid_book_panel_pick_port(host, 5123)
        if port <= 0:
            return ''

        class _GridBookStaticHandler(BaseHTTPRequestHandler):
            def do_GET(self):
                try:
                    from urllib.parse import urlparse, unquote
                    import mimetypes
                    req_path = str(urlparse(self.path).path or '/').strip()
                    if req_path in ('', '/'):
                        req_path = '/grid_book_observe.html'
                    rel = unquote(req_path.lstrip('/'))
                    fp = os.path.abspath(os.path.join(root_dir, rel))
                    root_abs = os.path.abspath(root_dir)
                    if not fp.startswith(root_abs):
                        self.send_error(403)
                        return
                    if os.path.isdir(fp):
                        fp = os.path.join(fp, 'grid_book_observe.html')
                    if not os.path.exists(fp):
                        self.send_error(404)
                        return
                    ctype = mimetypes.guess_type(fp)[0] or 'application/octet-stream'
                    with open(fp, 'rb') as f:
                        data = f.read()
                    self.send_response(200)
                    self.send_header('Content-Type', ctype)
                    self.send_header('Content-Length', str(len(data)))
                    self.send_header('Cache-Control', 'no-cache, no-store, must-revalidate')
                    self.send_header('Pragma', 'no-cache')
                    self.send_header('Expires', '0')
                    self.end_headers()
                    self.wfile.write(data)
                except BrokenPipeError:
                    return
                except Exception:
                    try:
                        self.send_error(500)
                    except Exception as _e:
                        _record_swallowed_exception('except_pass_line_763', _e)
                        pass
            def log_message(self, fmt, *args):
                return

        httpd = ThreadingHTTPServer((host, int(port)), _GridBookStaticHandler)
        httpd.daemon_threads = True
        th = threading.Thread(target=httpd.serve_forever, name='GridBookObserveHTTPD', daemon=True)
        th.start()
        globals()['_HTTPD'] = httpd
        globals()['_HTTPD_THREAD'] = th
        globals()['_PANEL_PORT'] = int(port)
        globals()['_PANEL_URL'] = f'http://{host}:{int(port)}/grid_book_observe.html'
        try:
            _pin('GRID_BOOK_HTTPD_ON', mod='PANEL', ok=1, stage='HTTPD_START', reason='grid_book_httpd_started', extra={'url': globals().get('_PANEL_URL',''), 'root_dir': root_dir})
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_764', _e)
            pass
        _maybe_open_grid_book_panel(globals().get('_PANEL_URL') or '')
        return str(globals().get('_PANEL_URL') or '')
    except Exception as _e:
        _log_exc(mod='PANEL', stage='EXC_PASS', e=_e)
        return ''

