        _runtime_busy = (bool((_sw_guard or {}).get("active")) and _sw_guard_state in ("SCANNING", "RECOVERING_UI", "SCAN_STUCK")) or (bool((_rw_guard or {}).get("active")) and _rw_guard_stage == "SCAN_M2")
        _st_text = "运行中"
        if st == "RECOVERING_UI":
            _st_text = "上一轮扫描已超时，正在恢复"
        elif st == "SCAN_STUCK":
            _st_text = "本轮扫描卡住，正在强制恢复"
        elif st == "ROUND_BUSY":
            if _sw_guard_state == "RECOVERING_UI":
                _st_text = "上一轮扫描已超时，正在恢复"
            elif _sw_guard_state == "SCAN_STUCK":
                _st_text = "本轮扫描卡住，正在强制恢复"
