_COST_MON_LAST: Dict[str, float] = {}
_COST_MON_LAST_TS: Dict[str, int] = {}

def cost_monitor_tick(snapshot: Dict[str, Any], logfp: str,
                      abs_threshold: float = 0.0,
                      pct_threshold: float = 0.0001,
                      console: bool = False) -> None:
    """
    监控每个币种每条腿（平台+币种+方向）的 entry price（成本价/开仓均价）变化。
    - abs_threshold: 绝对变化阈值（价格单位）
    - pct_threshold: 相对变化阈值（默认 0.01%）
    """
    try:
        ts = int(float((snapshot or {}).get("ts") or time.time()))
    except Exception:
        ts = int(time.time())

    positions = _pos_root(snapshot) or {}
    for plat, m in positions.items():
        if not isinstance(m, dict):
            continue
        for coin, row in m.items():
            if not isinstance(row, dict):
                continue
            side = (row.get("side") or "NONE").upper()
            if side in ("NONE", "", "N/A"):
                continue
            entry_px = row.get("entry_px")
            try:
                entry_px = float(entry_px) if entry_px is not None else 0.0
            except Exception:
                entry_px = 0.0
            if entry_px <= 0:
                continue

            key = f"{plat}:{coin}:{side}"
            prev = _COST_MON_LAST.get(key)
            _COST_MON_LAST[key] = entry_px
            _COST_MON_LAST_TS[key] = ts

            if prev is None or prev <= 0:
                continue

            delta = entry_px - float(prev)
            thr = max(float(abs_threshold), float(prev) * float(pct_threshold))
            if abs(delta) < thr:
                continue

            delta_pct = 0.0
            try:
                delta_pct = (delta / float(prev)) * 100.0
            except Exception:
                delta_pct = 0.0

            payload = {
                "ts": now_ts(),
                "mod": "MON_COST",
                "coin": str(coin),
                "platform": str(plat),
                "side": str(side),
                "entry_prev": float(prev),
                "entry_now": float(entry_px),
                "delta": float(delta),
                "delta_pct": float(delta_pct),
                "notional_u": float(row.get("notional_u") or 0.0),
            }
            write_jsonl(logfp, payload)
            if console:
                safe_print(f"[COST] {plat} {coin} {side} {prev:.6g} -> {entry_px:.6g} ({delta_pct:+.4f}%)")

