import threading as _th
import atexit as _atexit

_BOT_CONSOLE_LOCK = globals().get('_BOT_CONSOLE_LOCK', _th.Lock())
_BOT_CONSOLE_FHS = globals().get('_BOT_CONSOLE_FHS', {})  # type: ignore

try:
    BOT_CONSOLE_MAX_MB = float(os.getenv("BOT_CONSOLE_MAX_MB", "8") or 8.0)
except Exception:
    BOT_CONSOLE_MAX_MB = 8.0
try:
    BOT_CONSOLE_BACKUPS = int(float(os.getenv("BOT_CONSOLE_BACKUPS", "3") or 3))
except Exception:
    BOT_CONSOLE_BACKUPS = 3
BOT_CONSOLE_MAX_BYTES = int(max(1.0, BOT_CONSOLE_MAX_MB) * 1024.0 * 1024.0)

def _bot_console_rotate_if_needed(fp: str) -> None:
    """超过上限就轮转：bot_console.txt -> bot_console.txt.1 -> ..."""
    try:
        if not fp:
            return
        if BOT_CONSOLE_MAX_BYTES <= 0:
            return
        if not os.path.exists(fp):
            return
        try:
            sz = int(os.path.getsize(fp))
        except Exception:
            sz = 0
        if sz < BOT_CONSOLE_MAX_BYTES:
            return
        bkp = int(max(1, BOT_CONSOLE_BACKUPS))
        for i in range(bkp, 0, -1):
            src = fp if i == 1 else f"{fp}.{i-1}"
            dst = f"{fp}.{i}"
            try:
                if os.path.exists(src):
                    if os.path.exists(dst):
                        try:
                            os.remove(dst)
                        except Exception as _e:
                            _record_swallowed_exception('except_pass_line_791', _e)
                            pass
                    os.replace(src, dst)
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_792', _e)
                pass
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_793', _e)
        pass
def _bot_console__paths(logfp: str):
    paths = []
    try:
        paths.append(_human_observe_log_fp())
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    try:
        from pathlib import Path as _P
        lp = _P(str(logfp)).resolve()
        outp = None
        if lp.parent.name.lower() == "logs":
            outp = lp.parent.parent / "out"
        elif lp.parent.name.lower() == "out":
            outp = lp.parent
        if outp is not None:
            paths.append(outp / HUMAN_OBSERVE_LOG_BASENAME)
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    uniq = []
    seen = set()
    for p in paths:
        try:
            ap = str(p)
        except Exception:
            ap = str(p)
        if ap in seen:
            continue
        seen.add(ap)
        uniq.append(ap)
    return uniq

def _bot_console__ensure_fhs(logfp: str):
    key = str(logfp or "")
    try:
        if key in _BOT_CONSOLE_FHS and _BOT_CONSOLE_FHS[key]:
            return _BOT_CONSOLE_FHS[key]
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    fhs = []
    for p in _bot_console__paths(logfp):
        try:
            import os as _os
            _os.makedirs(str(_os.path.dirname(p)), exist_ok=True)
            fh = open(p, mode="a", encoding="utf-8", errors="ignore", buffering=1)
            fhs.append(fh)
        except Exception:
            continue

    try:
        _BOT_CONSOLE_FHS[key] = fhs
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    try:
        if not getattr(sys, "_bot_console_close_reg", False):
            def _close_all():
                try:
                    for _k, _lst in list(_BOT_CONSOLE_FHS.items()):
                        for _fh in list(_lst or []):
                            try:
                                _fh.close()
                            except Exception as _e:
                                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

                except Exception as _e:
                    _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

            _atexit.register(_close_all)
            setattr(sys, "_bot_console_close_reg", True)
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    return fhs

def _bot_console_emit(logfp: str, line: str):
    try:
        fhs = _bot_console__ensure_fhs(logfp)
        if not fhs:
            return
        with _BOT_CONSOLE_LOCK:
            for fh in list(fhs):
                try:
                    _fp = getattr(fh, 'name', None)
                    if isinstance(_fp, str) and _fp and (BOT_CONSOLE_MAX_BYTES > 0):
                        try:
                            if os.path.exists(_fp) and int(os.path.getsize(_fp)) >= int(BOT_CONSOLE_MAX_BYTES):
                                try:
                                    for _fh2 in list(fhs):
                                        try:
                                            _fh2.close()
                                        except Exception as _e:
                                            _record_swallowed_exception('except_pass_line_794', _e)
                                            pass
                                except Exception as _e:
                                    _record_swallowed_exception('except_pass_line_795', _e)
                                    pass
                                try:
                                    _BOT_CONSOLE_FHS[str(logfp or "")] = []
                                except Exception as _e:
                                    _record_swallowed_exception('except_pass_line_796', _e)
                                    pass
                                try:
                                    _bot_console_rotate_if_needed(_fp)
                                except Exception as _e:
                                    _record_swallowed_exception('except_pass_line_797', _e)
                                    pass
                                fhs = _bot_console__ensure_fhs(logfp)
                                if not fhs:
                                    return
                                for _fh3 in list(fhs):
                                    try:
                                        _fh3.write(line)
                                        _fh3.flush()
                                    except Exception as _e:
                                        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)
                                return
                        except Exception as _e:
                            _record_swallowed_exception('except_pass_line_798', _e)
                            pass
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_799', _e)
                    pass
                try:
                    fh.write(line)
                except Exception as _e:
                    _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

                try:
                    fh.flush()
                except Exception as _e:
                    _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

def progress(logfp: str, pct: int, msg: str, **kv: Any) -> None:
    """
    进度/日志统一出口：
    - 永远写 jsonl（面板/复盘用）
    - 永远同步写 bot_console.txt（面板追随用；不依赖 stdout 是否存在）
    - 可选打印到控制台（console=True/False）
    """
    console = bool(kv.pop("console", True))
    global _PROGRESS_CONSOLE_OVERRIDE
    if _PROGRESS_CONSOLE_OVERRIDE is not None:
        console = bool(_PROGRESS_CONSOLE_OVERRIDE)

    payload = {"ts": now_ts(), "mod": "BOT", "pct": int(pct), "msg": msg, **kv}
    write_jsonl(logfp, payload)

    def _fmt_val(v: Any) -> str:
        try:
            if v is None:
                return "None"
            if isinstance(v, bool):
                return "1" if v else "0"
            if isinstance(v, int):
                return str(v)
            if isinstance(v, float):
                av = abs(v)
                if av >= 1000:
                    return f"{v:.2f}"
                if av >= 10:
                    return f"{v:.3f}"
                if av >= 1:
                    return f"{v:.4f}"
                return f"{v:.6f}"
            return str(v)
        except Exception:
            return str(v)

    suffix = ""
    if kv:
        try:
            parts = [f"{k}={_fmt_val(v)}" for k, v in kv.items()]
            suffix = " | " + " ".join(parts)
        except Exception:
            suffix = ""

    line = f"[{payload['ts']}] {payload['pct']:>3}% | {msg}{suffix}\n"

    global _CONSOLE_LAST_PRINT_TS
    try:
        _now = time.time()
        is_critical = (pct in (0, 5, 12, 20, 28, 40, 66, 92, 100)) or ("ERROR" in (msg or "").upper())
        if (not is_critical) and (_now - float(_CONSOLE_LAST_PRINT_TS or 0.0) < 0.12):
            return
        _CONSOLE_LAST_PRINT_TS = _now
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    try:
        _tee_on = bool(getattr(sys, "_bot_console_tee_installed", False))
    except Exception:
        _tee_on = False
    if not (_tee_on and console):
        _bot_console_emit(logfp, line)

    if not console:
        return

    try:
        cprint(line.rstrip("\n"))
    except Exception:
        try:
            print(line.rstrip("\n"))
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

_ERR_FP: Optional[str] = None
_ERR_WARNED: bool = False

def write_error(errfp: Optional[str], msg: str, detail: Optional[str] = None) -> None:
    """统一错误落盘接口（兼容 2/3 参数调用）。

    - 旧调用：write_error(fp, msg)
    - 新调用：write_error(fp, msg, detail)

    设计目标：任何地方都可以安全调用，不因参数个数变化而 TypeError；
    同时保持“仅出错才写”的最小输出策略。
    """
    global _ERR_FP, _ERR_WARNED
    target = errfp or _ERR_FP
    if not target:
        if not _ERR_WARNED:
            _ERR_WARNED = True
            cprint("[WARN] 未设置错误文件路径，错误将不落盘")
        return

    _ERR_FP = target
    ts = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    if detail:
        line = f"[{ts}] {msg} | {detail}\n"
    else:
        line = f"[{ts}] {msg}\n"

    try:
        _makedirs(os.path.dirname(str(target)))
        with open(target, "a", encoding="utf-8") as f:
            f.write(line)
        return
    except Exception:
        pass

    try:
        import tempfile as _tempfile
        fb_dir = _tempfile.gettempdir()
        fb_fp = os.path.join(fb_dir, "bot_error_fallback.txt")
        with open(fb_fp, "a", encoding="utf-8") as f:
            f.write(line)
        _ERR_FP = fb_fp
        if not _ERR_WARNED:
            _ERR_WARNED = True
            safe_log(lambda: f"[WARN] 错误文件无权限，已回退到：{fb_fp}")
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

TP_POST_ADD_LOSS_LEG_ENABLE = int(globals().get("TP_POST_ADD_LOSS_LEG_ENABLE", 0) or 0)
TP_POST_ADD_LOSS_LEG_PCT = float(globals().get("TP_POST_ADD_LOSS_LEG_PCT", 0.25) or 0.25)
TP_POST_ADD_LOSS_LEG_MIN_U = float(globals().get("TP_POST_ADD_LOSS_LEG_MIN_U", 10.0) or 10.0)
TP_POST_ADD_LOSS_LEG_MAX_U = float(globals().get("TP_POST_ADD_LOSS_LEG_MAX_U", 200.0) or 200.0)

_TP_POST_ADD_TX_DONE: set[str] = set()

def _tp_post_add_loss_leg_25pct_enqueue(q, req0, snap: dict, force: bool = False):
    """纯止盈/成对止盈执行后的“后置补齐”兼容入口（默认关闭）。

    历史版本里有调用：_tp_post_add_loss_leg_25pct_enqueue(q, req0, snap, force=False)
    但部分拼接版缺失该函数导致 NameError。这里提供一个**默认关闭**、可控开启的实现：
    - 默认：直接返回 (False, 'DISABLED', {...})，不改变任何仓位（最安全）
    - 开启（TP_POST_ADD_LOSS_LEG_ENABLE=1 或 force=True）：
        1) 识别 coin + 当前两腿盈亏（snapshot->positions）
        2) 选择“亏损腿”所在平台作为目标平台
        3) 按亏损腿名义 * pct（默认 25%）计算补仓金额，限制在 [min_u, max_u]
        4) 生成一笔 increase 请求入队（由执行器再做硬顶/门禁）
    注意：这是“兼容补丁”，旧修复链已删除；如要启用请明确打开开关。
    """
    try:
        if (not force) and int(TP_POST_ADD_LOSS_LEG_ENABLE) <= 0:
            return False, "DISABLED", {"enable_key": "TP_POST_ADD_LOSS_LEG_ENABLE"}

        coin = ""
        try:
            coin = str(getattr(req0, "coin", "") or (req0.get("coin") if isinstance(req0, dict) else "") or "").upper().strip()
        except Exception:
            coin = ""
        if not coin:
            return False, "NO_COIN", {}

        try:
            snap_ts = int(float((snap or {}).get("ts") or time.time()))
        except Exception:
            snap_ts = int(time.time())
        tx = f"{coin}:{snap_ts}"
        if (not force) and tx in _TP_POST_ADD_TX_DONE:
            return False, "IDEMPOTENT_SKIP", {"tx": tx}

        p_ext = _get_position(snap or {}, coin, "EXT") or {}
        p_var = _get_position(snap or {}, coin, "VAR") or {}
        ext_notional = float(p_ext.get("notional_u") or 0.0)
        var_notional = float(p_var.get("notional_u") or 0.0)
        ext_upnl = float(p_ext.get("upnl_u") or 0.0)
        var_upnl = float(p_var.get("upnl_u") or 0.0)

        loss_plat = ""
        loss_pos = {}
        if ext_notional > 0 and var_notional > 0:
            if ext_upnl <= var_upnl:
                loss_plat = "EXT"; loss_pos = p_ext
            else:
                loss_plat = "VAR"; loss_pos = p_var
        elif ext_notional > 0:
            loss_plat = "EXT"; loss_pos = p_ext
        elif var_notional > 0:
            loss_plat = "VAR"; loss_pos = p_var
        else:
            return False, "NO_POSITION", {"ext_notional": ext_notional, "var_notional": var_notional}

        side = str(loss_pos.get("side") or loss_pos.get("position_side") or "").upper().strip()
        if side not in ("LONG", "SHORT"):
            return False, "BAD_SIDE", {"loss_plat": loss_plat, "side": side}

        base = float(loss_pos.get("notional_u") or 0.0)
        amt = abs(base) * float(TP_POST_ADD_LOSS_LEG_PCT or 0.25)
        amt = max(float(TP_POST_ADD_LOSS_LEG_MIN_U), min(float(TP_POST_ADD_LOSS_LEG_MAX_U), float(amt)))

        try:
            amt_i = int(round(float(amt) / 10.0) * 10)
        except Exception:
            amt_i = int(amt)
        if amt_i <= 0:
            return False, "AMT_ZERO", {"amt": amt}

        try:
            if "_rand_u_avoid_last" in globals() and callable(globals().get("_rand_u_avoid_last")):
                amt_i = int(_rand_u_avoid_last("TP_POST_ADD", loss_plat, max(10, amt_i - 10), amt_i + 10, step=10))
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_800', _e)
            pass
        req = {
            "module": "TP_POST",
            "submodule": "TP_POST_ADD_LOSS_LEG",
            "coin": coin,
            "platform": loss_plat,
            "action_type": "increase",
            "params": {"side": side, "amount_usd": float(amt_i)},
            "meta": {"origin": "tp_post_add_loss_leg_25pct", "pct": float(TP_POST_ADD_LOSS_LEG_PCT), "snapshot_ts": snap_ts, "tx": tx},
        }

        ok = False
        why = "NO_SUBMIT"
        det = {"loss_plat": loss_plat, "side": side, "amt_u": float(amt_i), "tx": tx}
        try:
            if q is not None and hasattr(q, "submit") and callable(getattr(q, "submit")):
                ok = bool(q.submit(req))
                why = "SUBMIT_OK" if ok else "SUBMIT_REJECT"
            else:
                why = "QUEUE_NO_SUBMIT"
        except Exception as _e:
            ok = False
            why = "SUBMIT_EXC"
            det["err"] = repr(_e)

        if ok:
            _TP_POST_ADD_TX_DONE.add(tx)
        return ok, why, det
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)
        return False, "EXC", {"err": repr(_e)}

def human(logfp: str, title: str, lines: List[str]) -> None:
    payload = {"ts": now_ts(), "mod": "BOT", "type": "HUMAN", "title": title, "lines": lines}
    write_jsonl(logfp, payload)
    cprint("")
    cprint("==== " + title + " ====")
    for ln in lines:
        cprint(ln)
    cprint("")

def pause_exit(enable: bool) -> None:
    """结束点保持窗口打开：**必须等待人工确认（回车）**后才允许退出。
    - enable=False：直接返回
    - enable=True：打印原因 -> 等待回车；若无交互环境（EOF），则降级为低频 sleep 保持窗口不闪退
    """
    if not enable:
        return
    try:
        cprint("[PAUSE_END（结束保持）] 运行已结束：按回车确认后退出。")
        try:
            input("按回车退出（Enter to exit）: ")
            return
        except EOFError:
            while True:
                time.sleep(60)
    except KeyboardInterrupt:
        return
    except Exception:
        return

def ask_yes_no(prompt: str, default: bool = False) -> bool:
    """历史遗留：交互确认。
    按你的最新要求：**脚本运行中不再弹任何确认**，因此这里直接返回 default。
    """
    return bool(default)

def ask_type_yes(prompt: str) -> bool:
    """历史遗留：实盘确认。
    按你的最新要求：**取消确认，直接进入**，因此这里固定返回 True。
    注意：真正的安全上限由 max_orders / max_notional_u 约束。
    """
    return True

def clean_num(x: Any) -> Optional[float]:
    if x is None:
        return None
    s = str(x).strip().replace(",", "")
    m = re.search(r"[-+]?(?:\d+\.\d+|\d+)", s)
    if not m:
        return None
    try:
        return float(m.group(0))
    except Exception:
        return None

def safe_float(x: Any, default: Optional[float] = None) -> Optional[float]:
    """安全转换为 float：
    - 兼容 None/tuple/list/numpy 标量/字符串
    - tuple/list 取第一个元素
    - 转换失败返回 default（默认 None）
    重要：交易链路中的日志/插针/门禁计算不得因 float() 崩溃。
    """
    try:
        if x is None:
            return default
        if isinstance(x, (tuple, list)):
            if len(x) == 0:
                return default
            x = x[0]
        try:
            import numpy as _np  # type: ignore
            if isinstance(x, _np.generic):
                x = x.item()
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_801', _e)
            pass
        return float(x)  # type: ignore
    except Exception:
        return default

_BOT_CONSOLE_ACTION_ENABLED = True

def _fmt_ts_local(ts: float | None = None) -> str:
    try:
        import datetime as _dt
        t = float(time.time() if ts is None else ts)
        return _dt.datetime.fromtimestamp(t).strftime("%Y-%m-%d %H:%M:%S")
    except Exception:
        return str(int(time.time()))

_EXEC_FILL_CACHE: dict[str, dict] = {}

def _exec_fill_cache_put(detail: dict) -> None:
    """缓存最近一次真实成交回填结果，供执行结果/摘要/trades.jsonl 统一取真实成交价。"""
    try:
        if not isinstance(detail, dict):
            return
        fp = safe_float(detail.get("fill_price") or detail.get("avg_fill_price") or detail.get("exec_price"), default=None)
        if fp is None or float(fp) <= 0:
            return
        keys = []
        for k in ("req_id", "trace_id", "order_id"):
            try:
                v = str(detail.get(k) or '').strip()
            except Exception:
                v = ''
            if v:
                keys.append(f'{k}:{v}')
        try:
            coin = str(detail.get('coin') or '').upper().strip()
            plat = str(detail.get('platform') or '').upper().strip()
            side = str(detail.get('side') or '').upper().strip()
            if coin and plat:
                keys.append(f'cps:{coin}:{plat}:{side}')
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_802', _e)
            pass
        if not keys:
            return
        detail2 = dict(detail)
        detail2['ts'] = float(detail.get('ts') or time.time())
        for k in keys:
            _EXEC_FILL_CACHE[k] = detail2
        if len(_EXEC_FILL_CACHE) > 200:
            try:
                items = sorted(_EXEC_FILL_CACHE.items(), key=lambda kv: float((kv[1] or {}).get('ts') or 0.0), reverse=True)[:120]
                _EXEC_FILL_CACHE.clear()
                _EXEC_FILL_CACHE.update(items)
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_803', _e)
                pass
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_804', _e)
        pass
def _exec_fill_cache_lookup(reqd: dict) -> dict | None:
    try:
        if not isinstance(reqd, dict):
            return None
        meta = reqd.get('meta') if isinstance(reqd.get('meta'), dict) else {}
        keys = []
        for k in ('req_id', 'trace_id', 'order_id'):
            v = ''
            try:
                if k in ('req_id', 'trace_id'):
                    v = str(meta.get(k) or reqd.get(k) or '').strip()
                else:
                    v = str(reqd.get(k) or meta.get(k) or '').strip()
            except Exception:
                v = ''
            if v:
                keys.append(f'{k}:{v}')
        try:
            coin = str(reqd.get('coin') or '').upper().strip()
            plat = str(reqd.get('platform') or reqd.get('plat') or '').upper().strip()
            side = str(reqd.get('side') or meta.get('side') or '').upper().strip()
            if coin and plat:
                keys.append(f'cps:{coin}:{plat}:{side}')
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_805', _e)
            pass
        best = None
        best_ts = -1.0
        for k in keys:
            d = _EXEC_FILL_CACHE.get(k)
            if not isinstance(d, dict):
                continue
            ts0 = safe_float(d.get('ts'), default=0.0) or 0.0
            if ts0 >= best_ts:
                best = d
                best_ts = ts0
        return best if isinstance(best, dict) else None
    except Exception:
        return None

def _exec_request_price_from_order(order: Any) -> float | None:
    try:
        meta = getattr(order, 'meta', None)
        if isinstance(meta, dict):
            for k in ('request_price', 'open_ref_px', 'ref_px', 'price', 'fill_price', 'avg_fill_price', 'exec_price'):
                v = safe_float(meta.get(k), default=None)
                if v is not None and float(v) > 0:
                    return float(v)
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_806', _e)
        pass
    return None

def _exec_locator_texts(loc: Any, *, limit: int = 48) -> list[str]:
    out = []
    try:
        txt = (_pw_call('exec.locator_texts.row.inner_text', loc.inner_text, timeout=900) or '').strip()
        if txt:
            out.extend([x.strip() for x in re.split(r'[\n\t]+', txt) if str(x).strip()])
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_807', _e)
        pass
    try:
        kids = loc.locator('span,div,td,a')
        n = min(int(kids.count() or 0), int(limit))
    except Exception:
        n = 0
        kids = None
    for i in range(n):
        try:
            tt = (_pw_call('exec.locator_texts.kid.text', kids.nth(i).inner_text, timeout=250) or '').strip()
        except Exception:
            tt = ''
        if not tt:
            continue
        if tt not in out:
            out.append(tt)
    return out

def _exec_parse_recent_fill_row_var(row: Any, coin: str, side_bs: str, submit_ts: float, amount_u_hint: float | None = None) -> dict | None:
    try:
        coin_u = str(coin or '').upper().strip()
        side_word = 'BUY' if str(side_bs or '').lower().strip() == 'buy' else 'SELL'
        texts = _exec_locator_texts(row)
        if not texts:
            return None
        joined = ' | '.join(texts)
        up = joined.upper()
        if coin_u and (coin_u not in up):
            return None
        if side_word and (side_word not in up):
            return None
        if ('CONFIRMED' not in up) and ('FILLED' not in up) and ('TRADE' not in up):
            return None
        price = None
        qty = None
        order_id = ''
        time_s = ''
        for tt in texts:
            if (not order_id) and re.fullmatch(r'[0-9a-fA-F-]{12,}', tt.strip()):
                order_id = tt.strip()
            if (not time_s):
                m = re.search(r'(20\d\d-\d\d-\d\d\s+\d\d:\d\d:\d\d)', tt)
                if m:
                    time_s = m.group(1)
            if price is None:
                m = re.search(r'\$\s*([0-9]+(?:\.[0-9]+)?)', tt)
                if m:
                    try:
                        price = float(m.group(1))
                        continue
                    except Exception as _e:
                        _record_swallowed_exception('except_pass_line_808', _e)
                        pass
        if price is None:
            nums = []
            for tt in texts:
                if re.search(r'20\d\d-\d\d-\d\d', tt):
                    continue
                if re.fullmatch(r'[0-9a-fA-F-]{12,}', tt.strip()):
                    continue
                m = re.search(r'([0-9]+(?:\.[0-9]+)?)', tt.replace(',', ''))
                if not m:
                    continue
                try:
                    v = float(m.group(1))
                except Exception:
                    continue
                if v <= 0:
                    continue
                nums.append((tt, v))
            for tt, v in nums:
                if '$' in tt or (0 < v < 100000 and 'PERP' not in tt.upper() and side_word not in tt.upper()):
                    price = v
                    break
        seen_price = False
        for tt in texts:
            if price is not None and (('$' in tt and str(price)[:4] in tt) or tt.strip() == str(price)):
                seen_price = True
                continue
            if not seen_price:
                continue
            if re.search(r'20\d\d-\d\d-\d\d', tt) or ('CONFIRMED' in tt.upper()) or ('TRADE' in tt.upper()):
                continue
            m = re.search(r'([0-9]+(?:\.[0-9]+)?)', tt.replace(',', ''))
            if m:
                try:
                    qv = float(m.group(1))
                    if qv > 0:
                        qty = qv
                        break
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_809', _e)
                    pass
        ts_found = None
        if time_s:
            try:
                ts_found = datetime.strptime(time_s, '%Y-%m-%d %H:%M:%S').astimezone().timestamp()
            except Exception:
                ts_found = None
        score = 0.0
        score += 100.0
        if price is not None and price > 0:
            score += 50.0
        if qty is not None and qty > 0:
            score += 20.0
        if ts_found is not None:
            score += max(0.0, 60.0 - min(abs(float(ts_found) - float(submit_ts)), 600.0) * 0.2)
        if amount_u_hint and price and qty:
            try:
                notional = float(price) * float(qty)
                rel = abs(notional - float(amount_u_hint)) / max(float(amount_u_hint), 1e-9)
                score += max(0.0, 30.0 - rel * 40.0)
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_810', _e)
                pass
        return {
            'coin': coin_u, 'side': ('LONG' if side_word == 'BUY' else 'SHORT'), 'fill_price': float(price) if price else None,
            'avg_fill_price': float(price) if price else None, 'filled_qty': (float(qty) if qty else None),
            'order_id': order_id or None, 'fill_ts': ts_found, 'row_time': time_s or None, 'source': 'var_trade_history',
            'price_source': 'fill', 'score': float(score), 'row_text': joined[:400],
        }
    except Exception:
        return None

def _exec_parse_recent_fill_row_ext(row: Any, coin: str, side_bs: str, submit_ts: float, amount_u_hint: float | None = None) -> dict | None:
    try:
        coin_req = _ext_canonical_coin(coin)
        coin_aliases = [a for a in _ext_coin_aliases(coin_req) if str(a or '').strip()]
        side_word = 'BUY' if str(side_bs or '').lower().strip() == 'buy' else 'SELL'
        texts = _exec_locator_texts(row)
        if not texts:
            return None
        joined = ' | '.join(texts)
        up = joined.upper()
        matched_alias = ''
        for _alias in coin_aliases:
            if str(_alias or '').upper().strip() and str(_alias or '').upper().strip() in up:
                matched_alias = str(_alias or '').upper().strip()
                break
        if coin_aliases and (not matched_alias):
            return None
        if side_word and (side_word not in up):
            return None
        if 'TRADE' not in up and 'TAKER' not in up and 'MAKER' not in up:
            return None
        price = None
        qty = None
        order_id = ''
        row_dt = None
        for tt in texts:
            ttu = tt.upper()
            if qty is None and matched_alias and matched_alias in ttu:
                m = re.search(r'([0-9]+(?:\.[0-9]+)?)\s*' + re.escape(matched_alias), tt.replace(',', ''), flags=re.IGNORECASE)
                if m:
                    try:
                        qty = float(m.group(1))
                    except Exception:
                        qty = None
            if price is None:
                if 'USD' in ttu or 'APR ' in ttu or 'AM ' in ttu or 'PM ' in ttu or '/' in tt:
                    pass
                m = re.fullmatch(r'\s*([0-9]+(?:\.[0-9]+)?)\s*', tt.replace(',', ''))
                if m:
                    try:
                        v = float(m.group(1))
                    except Exception:
                        v = None
                    if v is not None and v > 0:
                        price = float(v)
            if row_dt is None:
                m = re.search(r'([A-Z][a-z]{2}\s+\d{1,2},\s*20\d{2}).*?(\d{1,2}:\d{2}:\d{2})', tt.replace('\n', ' '))
                if m:
                    try:
                        row_dt = datetime.strptime(f"{m.group(1)} {m.group(2)}", '%b %d, %Y %H:%M:%S').astimezone()
                    except Exception:
                        row_dt = None
        if price is None:
            nums = []
            for tt in texts:
                ttu = tt.upper()
                if any(x in ttu for x in ('USD', 'APR ', 'AM ', 'PM ', 'TAKER', 'MAKER', 'TRADE')):
                    continue
                m = re.search(r'([0-9]+(?:\.[0-9]+)?)', tt.replace(',', ''))
                if not m:
                    continue
                try:
                    v = float(m.group(1))
                except Exception:
                    continue
                if v > 0:
                    nums.append(v)
            if nums:
                price = float(nums[0])
        ts_found = row_dt.timestamp() if row_dt is not None else None
        score = 100.0
        if price is not None and price > 0:
            score += 50.0
        if qty is not None and qty > 0:
            score += 20.0
        if ts_found is not None:
            score += max(0.0, 60.0 - min(abs(float(ts_found) - float(submit_ts)), 600.0) * 0.2)
        if amount_u_hint and price and qty:
            try:
                notional = float(price) * float(qty)
                rel = abs(notional - float(amount_u_hint)) / max(float(amount_u_hint), 1e-9)
                score += max(0.0, 30.0 - rel * 40.0)
            except Exception:
                pass
        return {
            'coin': coin_req, 'matched_alias': matched_alias, 'side': ('LONG' if side_word == 'BUY' else 'SHORT'), 'fill_price': float(price) if price else None,
            'avg_fill_price': float(price) if price else None, 'filled_qty': (float(qty) if qty else None),
            'order_id': order_id or None, 'fill_ts': ts_found, 'row_time': (row_dt.isoformat(timespec='seconds') if row_dt is not None else None), 'source': 'ext_trade_history',
            'price_source': 'fill', 'score': float(score), 'row_text': joined[:400],
        }
    except Exception:
        return None

def _exec_wait_trades_view_stable(page: Any, platform: str, *, timeout_ms: int = 2600) -> dict:
    plat = str(platform or '').upper().strip()
    start = time.time()
    last_n = None
    stable_hits = 0
    active_hits = 0
    loops = 0
    tab_sels = [
        '[role="tab"][aria-selected="true"]:has-text("Trades")',
        'button[aria-selected="true"]:has-text("Trades")',
        'div[role="tab"][aria-selected="true"]:has-text("Trades")',
        'text="Trades"',
    ]
    row_sels = [
        '[data-testid="positions-table-row"]',
        'svelte-virtual-list-row',
        'tbody tr',
    ]
    best_rows = 0
    while (time.time() - start) * 1000.0 < float(timeout_ms):
        loops += 1
        cur_rows = 0
        for sel in tab_sels:
            try:
                if _pw_locator_count(page.locator(sel), f'exec.trades.active[{sel}]') > 0:
                    active_hits += 1
                    break
            except Exception:
                continue
        for sel in row_sels:
            try:
                cur_rows = max(cur_rows, int(page.locator(sel).count() or 0))
            except Exception:
                continue
        best_rows = max(best_rows, int(cur_rows or 0))
        if last_n is not None and int(cur_rows) == int(last_n):
            stable_hits += 1
        else:
            stable_hits = 0
        last_n = int(cur_rows)
        if (active_hits >= 1 or loops >= 3) and stable_hits >= 1:
            return {'ok': True, 'active_hits': int(active_hits), 'stable_hits': int(stable_hits), 'row_count': int(cur_rows), 'best_row_count': int(best_rows), 'loops': int(loops)}
        try:
            _pw_wait_ms(page, 220, 'exec.trades.wait_stable')
        except Exception:
            time.sleep(0.24)
    return {'ok': False, 'active_hits': int(active_hits), 'stable_hits': int(stable_hits), 'row_count': int(last_n or 0), 'best_row_count': int(best_rows), 'loops': int(loops)}

def _exec_try_get_recent_fill(page: Any, platform: str, coin: str, side_bs: str, submit_ts: float, amount_u_hint: float | None = None) -> dict | None:
    """爸爸口径：彻底删除切 Trades 动作本身。

    人话：
    - 不再切 Trades。
    - 不再等待 Trades 视图稳定。
    - 不再从 Trades 表抓成交痕迹。
    - EXT/VAR 提交后的确认，只走平台真相/batch postcheck/下轮统一复核。
    """
    try:
        if bool(globals().get('EXEC_DISABLE_TRADES_ACTION', True)):
            return None
        return None
    except Exception:
        return None

def _order_skip_immediate_trade_fill_reconcile(order: Any, *, plat: str = '', act: str = '') -> tuple[bool, str]:
    """是否跳过提交后的即时成交补抓。

    人话：
    - 现口径已彻底删除切 Trades 动作。
    - 这里只保留统一跳过原因，避免后面任何链路再偷偷恢复该动作。
    """
    try:
        meta = getattr(order, 'meta', None)
    except Exception:
        meta = None
    if not isinstance(meta, dict):
        meta = {}
    try:
        verified = bool(meta.get('_submit_verified_ok'))
    except Exception:
        verified = False
    if verified:
        return True, 'submit_verified_by_position_delta'
    try:
        if bool(meta.get('_skip_immediate_trade_fill_reconcile')):
            return True, str(meta.get('_skip_immediate_trade_fill_reconcile_reason') or 'skip_immediate_trade_fill_reconcile')
    except Exception:
        pass
    return False, ''

def _exec_reconcile_fill_after_submit(exe: Any, order: Any, *, plat: str = '', act: str = '') -> dict | None:
    try:
        if bool(globals().get('EXEC_DISABLE_TRADES_ACTION', True)):
            try:
                _pin('FILL_RECON_SKIP', mod='EXEC', coin=str(getattr(order, 'coin', '') or '').upper(), ok=1, reason='trades_action_deleted', plat=str(plat or getattr(order, 'platform', '') or '').upper(), act=str(act or ''))
            except Exception:
                pass
            return None
    except Exception:
        return None
    _skip_now, _skip_reason = _order_skip_immediate_trade_fill_reconcile(order, plat=plat, act=act)
    if _skip_now:
        try:
            _pin('FILL_RECON_SKIP', mod='EXEC', coin=str(getattr(order, 'coin', '') or '').upper(), ok=1, reason=str(_skip_reason or 'skip'), plat=str(plat or getattr(order, 'platform', '') or '').upper(), act=str(act or ''))
        except Exception:
            pass
        return None
    try:
        page = getattr(exe, 'page', None)
    except Exception:
        page = None
    if page is None:
        return None
    try:
        submit_ts = float(time.time())
    except Exception:
        submit_ts = time.time()
    try:
        coin = str(getattr(order, 'coin', '') or '').upper().strip()
    except Exception:
        coin = ''
    try:
        side_bs = str(getattr(order, 'side', '') or '').lower().strip()
    except Exception:
        side_bs = ''
    try:
        amount_u_hint = safe_float(getattr(order, 'usd', None), default=None)
    except Exception:
        amount_u_hint = None
    if not coin or side_bs not in ('buy', 'sell'):
        return None
    det = _exec_try_get_recent_fill(page, str(plat or '').upper() or str(getattr(order, 'platform', '') or '').upper(), coin, side_bs, submit_ts, amount_u_hint)
    if not isinstance(det, dict):
        return None
    try:
        meta = getattr(order, 'meta', None)
        if isinstance(meta, dict):
            for k in ('req_id', 'trace_id'):
                if meta.get(k):
                    det[k] = meta.get(k)
            if _exec_request_price_from_order(order):
                det['request_price'] = _exec_request_price_from_order(order)
            meta['fill_price'] = det.get('fill_price')
            meta['avg_fill_price'] = det.get('avg_fill_price')
            meta['filled_qty'] = det.get('filled_qty')
            meta['order_id'] = det.get('order_id')
            meta['fill_price_source'] = det.get('source')
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_812', _e)
        pass
    try:
        setattr(order, 'fill_price', det.get('fill_price'))
        setattr(order, 'avg_fill_price', det.get('avg_fill_price'))
        setattr(order, 'filled_qty', det.get('filled_qty'))
        setattr(order, 'order_id', det.get('order_id'))
        setattr(order, 'fill_price_source', det.get('source'))
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_813', _e)
        pass
    try:
        det.setdefault('platform', str(plat or getattr(order, 'platform', '') or '').upper())
        _exec_fill_cache_put(det)
        try:
            _pin('FILL_RECON_OK', mod='EXEC', coin=str(coin), ok=1, reason=str(det.get('source') or 'fill'),
                 plat=str(det.get('platform') or ''), act=str(act or ''), req_px=det.get('request_price'), fill_px=det.get('fill_price'), qty=det.get('filled_qty'))
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_814', _e)
            pass
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_815', _e)
        pass
    return det

def _extract_exec_price_from_req(reqd: dict) -> float | None:
    """尽量从请求/元数据里提取“本次动作对应的价格”。
    - 开仓/加仓：优先 entry/open_ref/成交参考价
    - 平仓/减仓：优先 cur/close/mark 触发价
    - 兼容：补看 params.meta / params.params / grid_layer，最后回退 request_price
    """
    try:
        if not isinstance(reqd, dict):
            return None
        p = reqd.get("params") if isinstance(reqd.get("params"), dict) else {}
        p2 = p.get("params") if isinstance(p.get("params"), dict) else {}
        m = reqd.get("meta") if isinstance(reqd.get("meta"), dict) else {}
        pm = p.get("meta") if isinstance(p.get("meta"), dict) else {}
        p2m = p2.get("meta") if isinstance(p2.get("meta"), dict) else {}
        mg = m.get("grid_layer") if isinstance(m.get("grid_layer"), dict) else {}
        pg = p.get("grid_layer") if isinstance(p.get("grid_layer"), dict) else {}
        p2g = p2.get("grid_layer") if isinstance(p2.get("grid_layer"), dict) else {}
        action = str(reqd.get("action_type") or reqd.get("action") or "").lower()

        def _pick_float(*objs_and_keys):
            for obj, keys in objs_and_keys:
                if not isinstance(obj, dict):
                    continue
                for k in keys:
                    try:
                        v = safe_float(obj.get(k), default=None)
                    except Exception:
                        v = None
                    if v is not None and float(v) > 0:
                        return float(v)
            return None

        if action in ("decrease", "reduce", "close", "tp", "take_profit", "grid_sell", "grid_reduce"):
            px = _pick_float(
                (m, ("cur_px", "close_px", "close_price", "mark_px", "mark_price", "mark", "last_px", "last", "price")),
                (pm, ("cur_px", "close_px", "close_price", "mark_px", "mark_price", "mark", "last_px", "last", "price")),
                (p2m, ("cur_px", "close_px", "close_price", "mark_px", "mark_price", "mark", "last_px", "last", "price")),
                (mg, ("cur_px", "close_px", "close_price", "mark_px", "mark_price", "mark", "last_px", "last", "price", "tp_px", "tp_price")),
                (pg, ("cur_px", "close_px", "close_price", "mark_px", "mark_price", "mark", "last_px", "last", "price", "tp_px", "tp_price")),
                (p2g, ("cur_px", "close_px", "close_price", "mark_px", "mark_price", "mark", "last_px", "last", "price", "tp_px", "tp_price")),
                (p2, ("cur_px", "close_px", "close_price", "mark_px", "mark_price", "mark", "last_px", "last", "price")),
                (p, ("cur_px", "close_px", "close_price", "mark_px", "mark_price", "mark", "last_px", "last", "price")),
                (reqd, ("cur_px", "close_px", "close_price", "mark_px", "mark_price", "mark", "last_px", "last", "price")),
            )
            if px is not None:
                return float(px)

        px = _pick_float(
            (m, ("fill_price", "avg_fill_price", "fill_px", "exec_price", "layer_open_px", "layer_fill_px", "layer_request_px", "request_price", "price", "open_ref_px", "cur_px", "mark_px", "mark_price", "mark", "last_px")),
            (pm, ("fill_price", "avg_fill_price", "fill_px", "exec_price", "layer_open_px", "layer_fill_px", "layer_request_px", "request_price", "price", "open_ref_px", "cur_px", "mark_px", "mark_price", "mark", "last_px")),
            (p2m, ("fill_price", "avg_fill_price", "fill_px", "exec_price", "layer_open_px", "layer_fill_px", "layer_request_px", "request_price", "price", "open_ref_px", "cur_px", "mark_px", "mark_price", "mark", "last_px")),
            (mg, ("layer_open_px", "layer_fill_px", "layer_request_px", "request_price", "price", "open_ref_px", "mark_px", "mark_price", "mark")),
            (pg, ("layer_open_px", "layer_fill_px", "layer_request_px", "request_price", "price", "open_ref_px", "mark_px", "mark_price", "mark")),
            (p2g, ("layer_open_px", "layer_fill_px", "layer_request_px", "request_price", "price", "open_ref_px", "mark_px", "mark_price", "mark")),
            (p2, ("fill_price", "avg_fill_price", "fill_px", "exec_price", "layer_open_px", "layer_fill_px", "layer_request_px", "request_price", "price", "open_ref_px", "cur_px", "mark_px", "mark_price", "mark", "last_px")),
            (p, ("fill_price", "avg_fill_price", "fill_px", "exec_price", "layer_open_px", "layer_fill_px", "layer_request_px", "request_price", "price", "open_ref_px", "cur_px", "mark_px", "mark_price", "mark", "last_px")),
            (reqd, ("fill_price", "avg_fill_price", "fill_px", "exec_price", "layer_open_px", "layer_fill_px", "layer_request_px", "request_price", "price", "open_ref_px", "cur_px", "mark_px", "mark_price", "mark", "last_px")),
        )
        if px is None:
            try:
                px = _extract_request_price_from_req(reqd)
            except Exception:
                px = None
        return float(px) if px is not None else None
    except Exception:
        return None

def _extract_profit_u_from_req(reqd: dict) -> float | None:
    try:
        if not isinstance(reqd, dict):
            return None
        p = reqd.get("params") if isinstance(reqd.get("params"), dict) else {}
        p2 = p.get("params") if isinstance(p.get("params"), dict) else {}
        m = reqd.get("meta") if isinstance(reqd.get("meta"), dict) else {}
        action = str(reqd.get("action_type") or reqd.get("action") or "").lower().strip()

        for k in ("profit_u", "net_profit_u", "grid_profit_u", "pnl_u", "realized_pnl_u", "est_profit_u"):
            v = None
            try:
                v = p.get(k)
            except Exception:
                v = None
            if v is None:
                try:
                    v = p2.get(k)
                except Exception:
                    v = None
            if v is None:
                try:
                    v = m.get(k)
                except Exception:
                    v = None
            if v is None:
                continue
            fv = safe_float(v, default=None)
            if fv is not None:
                return float(fv)

        if action == "close_pair":
            for obj in (p2, p, m, reqd):
                if not isinstance(obj, dict):
                    continue
                v = safe_float(obj.get("net_u_sum"), default=None)
                if v is not None:
                    return float(v)
                eu = safe_float(obj.get("ext_upnl_u"), default=None)
                vu = safe_float(obj.get("var_upnl_u"), default=None)
                if (eu is not None) and (vu is not None):
                    return float(eu) + float(vu)
        if action == "close_one_leg":
            for obj in (p2, p, m, reqd):
                if not isinstance(obj, dict):
                    continue
                for k in ("upnl_u", "profit_u", "realized_pnl_u"):
                    v = safe_float(obj.get(k), default=None)
                    if v is not None:
                        return float(v)

        if action in ("decrease", "reduce", "close", "tp", "take_profit", "grid_sell", "grid_reduce"):
            side = str(reqd.get("side") or p.get("side") or p2.get("side") or m.get("side") or "").upper()
            open_px = safe_float(m.get("open_ref_px") if isinstance(m, dict) else None, default=None)
            if open_px is None:
                open_px = safe_float(p2.get("open_ref_px") if isinstance(p2, dict) else None, default=None)
            close_px = _extract_exec_price_from_req(reqd)
            notional_u = None
            for obj in (p2, p, m, reqd):
                if not isinstance(obj, dict):
                    continue
                for k in ("close_notional_u", "amount_usd", "amount_u", "notional_u", "u", "usd"):
                    try:
                        vv = safe_float(obj.get(k), default=None)
                    except Exception:
                        vv = None
                    if vv is not None and float(vv) > 0:
                        notional_u = float(vv)
                        break
                if notional_u is not None:
                    break
            if (open_px is not None) and (close_px is not None) and (notional_u is not None) and str(side or "") in ("LONG", "SHORT"):
                try:
                    return float(_m9_estimate_net_profit_u(str(side), float(open_px), float(close_px), float(notional_u), fee_rate=M9_FEE_RATE))
                except Exception:
                    return None
        return None
    except Exception:
        return None

def _grid_layer_tag(layer_id: object) -> str:
    try:
        s = str(layer_id or '').strip()
        if not s:
            return ''
        m = _re.search(r'(L\d+)(?!.*L\d+)', s, flags=_re.IGNORECASE)
        if m:
            return str(m.group(1)).upper()
        m = _re.search(r'[:#\-_](\d+)(?!.*[:#\-_]\d+)', s)
        if m:
            return f"L{int(m.group(1))}"
        m = _re.search(r'(\d+)$', s)
        if m:
            return f"L{int(m.group(1))}"
        return s[-24:]
    except Exception:
        return ''

def _grid_layer_no(layer_id: object):
    try:
        s = str(layer_id or '').strip()
        if not s:
            return None
        tag = _grid_layer_tag(s)
        m = _re.search(r'L(\d+)', str(tag), flags=_re.IGNORECASE)
        if m:
            return int(m.group(1))
        m = _re.search(r'[:#\-_](\d+)(?!.*[:#\-_]\d+)', s)
        if m:
            return int(m.group(1))
        m = _re.search(r'(\d+)$', s)
        return int(m.group(1)) if m else None
    except Exception:
        return None

def _grid_canonical_layer_id(grid_id: object, layer_no: object = None, fallback: object = '') -> str:
    try:
        gid = str(grid_id or '').strip()
        lno = None
        try:
            lno = int(layer_no) if layer_no is not None and str(layer_no).strip() != '' else None
        except Exception:
            lno = None
        if lno is None:
            try:
                lno = _grid_layer_no(fallback)
            except Exception:
                lno = None
        if gid and lno is not None and int(lno) > 0:
            return f"{gid}:{int(lno)}"
        fb = str(fallback or '').strip()
        if gid and fb.startswith(f"{gid}_L"):
            try:
                _fb_no = _grid_layer_no(fb)
                if _fb_no is not None:
                    return f"{gid}:{int(_fb_no)}"
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_816', _e)
                pass
        return fb
    except Exception:
        try:
            return str(fallback or '').strip()
        except Exception:
            return ''

def _grid_alive_layer_rows(grid_id: object = '', *, include_close_pending: bool = True) -> list[dict]:
    rows = []
    gid = str(grid_id or '').strip()
    alive_states = {'OPEN', 'ACTIVE', 'EXEC_PENDING', 'DECREASE_SUBMITTED'}
    if include_close_pending:
        alive_states.update({'CLOSE_PENDING', 'PENDING_CLOSE', 'CLOSING'})
    try:
        if ('GRID_BOOK' in globals()) and (globals().get('GRID_BOOK') is not None):
            try:
                _get_alive_raw = getattr(GRID_BOOK, 'get_alive_layers_raw', None)
                if gid and callable(_get_alive_raw):
                    glayers = list(_get_alive_raw(gid) or [])
                else:
                    glayers = list(GRID_BOOK.get_open_layers(gid) or []) if gid else []
            except Exception:
                glayers = []
            for ly in glayers:
                try:
                    lyd = dict(ly or {})
                    st = str(lyd.get('status') or lyd.get('state') or 'OPEN').upper().strip()
                    if st not in alive_states:
                        continue
                    lid0 = str(lyd.get('layer_id') or '').strip()
                    lno0 = lyd.get('layer_no')
                    try:
                        lno0 = int(lno0) if lno0 is not None else (_grid_layer_no(lid0) or 0)
                    except Exception:
                        lno0 = (_grid_layer_no(lid0) or 0)
                    lyd['_src'] = 'GRID_BOOK'
                    lyd['grid_id'] = str(gid or lyd.get('grid_id') or '')
                    lyd['layer_no'] = int(lno0 or 0)
                    lyd['layer_id'] = _grid_canonical_layer_id(lyd['grid_id'], lyd['layer_no'], lid0)
                    rows.append(lyd)
                except Exception:
                    continue
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_817', _e)
        pass
    try:
        items = list((((getattr(globals().get('_GRID_LEDGER'), '_data', {}) or {}).get('items') or [])) if _m9_legacy_view_enabled() and globals().get('_GRID_LEDGER') is not None else [])
    except Exception:
        items = []
    for it in items:
        try:
            if not isinstance(it, dict):
                continue
            it_gid = str(it.get('grid_id') or it.get('id') or '').strip()
            if gid and it_gid != gid:
                continue
            st = str(it.get('state') or it.get('status') or 'OPEN').upper().strip()
            if st not in alive_states:
                continue
            lid0 = str(it.get('layer_id') or '').strip()
            lno0 = it.get('layer_no')
            try:
                lno0 = int(lno0) if lno0 is not None else (_grid_layer_no(lid0) or 0)
            except Exception:
                lno0 = (_grid_layer_no(lid0) or 0)
            rows.append({'_src':'LEGACY_LOCAL_GRID_VIEW','grid_id':it_gid,'layer_id':_grid_canonical_layer_id(it_gid,lno0,lid0),'layer_no':int(lno0 or 0),'status':st,'state':st,'coin':str(it.get('coin') or '').upper().strip(),'platform':str(it.get('platform') or it.get('plat') or '').upper().strip(),'side':str(it.get('side') or '').upper().strip()})
        except Exception:
            continue
    uniq=[]; seen=set()
    for row in rows:
        try: key=(str(row.get('grid_id') or ''),str(row.get('layer_id') or ''),int(row.get('layer_no') or 0),str(row.get('_src') or ''))
        except Exception: key=None
        if key in seen: continue
        seen.add(key); uniq.append(row)
    return uniq

def _grid_has_alive_layer_no(grid_id: object, layer_no: object, *, include_close_pending: bool = True) -> bool:
    try:
        gid = str(grid_id or '').strip(); lno = int(layer_no or 0)
        if (not gid) or lno <= 0: return False
        for row in _grid_alive_layer_rows(gid, include_close_pending=include_close_pending):
            try:
                if int(row.get('layer_no') or 0) == lno: return True
            except Exception:
                continue
        return False
    except Exception:
        return False

def _grid_has_close_pending_layer(grid_id: object) -> bool:
    try:
        gid = str(grid_id or '').strip()
        if not gid: return False
        for row in _grid_alive_layer_rows(gid, include_close_pending=True):
            st = str(row.get('status') or row.get('state') or '').upper().strip()
            if st in {'CLOSE_PENDING','PENDING_CLOSE','CLOSING'}: return True
        return False
    except Exception:
        return False

def _is_close_like_action(action_type: object) -> bool:
    try:
        a = str(action_type or '').lower().strip()
        return any(k in a for k in ('decrease', 'reduce', 'close', 'tp', 'take_profit', 'flatten', 'stop_profit'))
    except Exception:
        return False

def _req_ensure_meta(req_any):
    try:
        if isinstance(req_any, dict):
            m = req_any.get('meta')
            if not isinstance(m, dict):
                m = {}
                req_any['meta'] = m
            return m
        m = getattr(req_any, 'meta', None)
        if not isinstance(m, dict):
            m = {}
            try:
                setattr(req_any, 'meta', m)
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_818', _e)
                pass
        return m
    except Exception:
        return {}

def _req_get_dict(req_any) -> dict:
    """统一把请求对象转成 dict，并尽量清洗成 JSON 可序列化结构。
    修复：req.params/meta 内含 CloseLegSpec/dataclass/自定义对象时，后续 trace/log json.dumps 直接炸。
    """
    try:
        if isinstance(req_any, dict):
            d = dict(req_any)
        elif hasattr(req_any, 'to_dict') and callable(getattr(req_any, 'to_dict')):
            d = req_any.to_dict()
            d = d if isinstance(d, dict) else {}
        elif hasattr(req_any, '__dict__'):
            d = dict(req_any.__dict__)
        else:
            d = {}
    except Exception:
        d = {}
    try:
        return _json_sanitize(d) if callable(globals().get('_json_sanitize')) else d
    except Exception:
        try:
            return json.loads(_json_dumps_bot(d))
        except Exception:
            return d if isinstance(d, dict) else {}

def _grid_action_label(*, coin: object = '', platform: object = '', layer_id: object = '', action_type: object = '', amount_u: object = None, profit_u: object = None) -> str:
    try:
        coin_s = str(coin or '').upper().strip()
        plat_s = str(platform or '').upper().strip()
        tag = _grid_layer_tag(layer_id)
        act = '平' if _is_close_like_action(action_type) else '开'
        amt_s = '-'
        try:
            if amount_u is not None:
                amt_s = f"{float(amount_u):.2f}U"
        except Exception:
            amt_s = str(amount_u)
        parts = [x for x in (coin_s, plat_s, tag, f"{act}{amt_s}") if x]
        if profit_u is not None and _is_close_like_action(action_type):
            try:
                parts.append(f"利润{float(profit_u):.4f}U")
            except Exception:
                parts.append(f"利润{profit_u}")
        return ' '.join(parts)
    except Exception:
        return ''

def _attach_layer_meta(req_any, *, layer_id: object = None, layer_instance_id: object = None, amount_u: object = None, profit_u: object = None, **extra_meta) -> dict:
    meta = _req_ensure_meta(req_any)
    try:
        rd = _req_get_dict(req_any)
        coin = str(rd.get('coin') or '').upper().strip()
        plat = str(rd.get('platform') or '').upper().strip()
        act = str(rd.get('action_type') or rd.get('action') or '')
    except Exception:
        coin = ''
        plat = ''
        act = ''
    try:
        lid = str(layer_id or meta.get('layer_id') or '').strip()
    except Exception:
        lid = ''
    if lid:
        meta['layer_id'] = lid
    try:
        liid = str(layer_instance_id or meta.get('layer_instance_id') or meta.get('instance_id') or '').strip()
    except Exception:
        liid = ''
    if liid:
        meta['layer_instance_id'] = liid
        meta['instance_id'] = liid
        tag = _grid_layer_tag(lid)
        if tag:
            meta['layer_tag'] = tag
        no = _grid_layer_no(lid)
        if no is not None:
            meta['layer_no'] = int(no)
    if amount_u is not None:
        try:
            meta['grid_amount_u'] = float(amount_u)
        except Exception:
            meta['grid_amount_u'] = amount_u
    if profit_u is not None:
        try:
            meta['profit_u'] = float(profit_u)
            meta['grid_profit_u'] = float(profit_u)
            meta['net_profit_u'] = float(profit_u)
            meta['realized_pnl_u'] = float(profit_u)
            meta['realized_pnl_usd'] = float(profit_u)
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_819', _e)
            pass
    try:
        for _k, _v in dict(extra_meta or {}).items():
            if not str(_k or '').strip():
                continue
            meta[str(_k)] = _v
    except Exception as _e:
        _record_swallowed_exception('attach_layer_meta.extra_meta', _e)
        pass
    try:
        meta['grid_action_label'] = _grid_action_label(
            coin=coin,
            platform=plat,
            layer_id=meta.get('layer_id') or lid,
            action_type=act,
            amount_u=(meta.get('grid_amount_u') if amount_u is None else amount_u),
            profit_u=(meta.get('profit_u') if profit_u is None else profit_u),
        )
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_820', _e)
        pass
    return meta

def _apply_m9_exec_bookkeeping(req_any, *, exec_notional_u: object, ref_px: object = None, snapshot_id: object = None, reason: str = '', pos_side: object = ''):
    try:
        rd = _req_get_dict(req_any)
        mod = str(rd.get('module') or '').upper().strip()
        act = str(rd.get('action_type') or rd.get('action') or '').lower().strip()
        if mod != 'M9' or act not in ('increase', 'decrease'):
            return None
        meta = _req_ensure_meta(req_any)
        params = rd.get('params') if isinstance(rd.get('params'), dict) else {}
        gid = str(meta.get('grid_id') or params.get('grid_id') or rd.get('grid_id') or '').strip()
        if not gid or ('GRID_BOOK' not in globals()) or (globals().get('GRID_BOOK') is None):
            return None
        try:
            amt_u = float(exec_notional_u or 0.0)
        except Exception:
            amt_u = 0.0
        if amt_u <= 0:
            return None
        try:
            snap_id = snapshot_id if snapshot_id is not None else meta.get('snapshot_id')
        except Exception:
            snap_id = snapshot_id
        try:
            px = float(ref_px) if ref_px is not None else None
        except Exception:
            px = None
        coin = str(rd.get('coin') or '').upper().strip()
        plat = str(rd.get('platform') or '').upper().strip()
        side_now = str(pos_side or rd.get('side') or params.get('side') or meta.get('side') or '').upper().strip()
        if act == 'increase':
            trace_id = str(getattr(req_any, 'trace_id', '') or (meta.get('trace_id') if isinstance(meta, dict) else '') or '').strip()
            req_id = str((meta.get('req_id') if isinstance(meta, dict) else '') or rd.get('request_id') or '').strip()
            try:
                grids = (getattr(GRID_BOOK, 'data', {}) or {}).get('grids', {}) if hasattr(GRID_BOOK, 'data') else {}
                g0 = grids.get(str(gid)) if isinstance(grids, dict) else None
                layers0 = (g0.get('layers') or []) if isinstance(g0, dict) else []
            except Exception:
                layers0 = []
            for _ly0 in (layers0 or []):
                try:
                    _req0 = str(_ly0.get('open_req_id') or '').strip()
                    _tid0 = str(_ly0.get('open_trace_id') or '').strip()
                    if (req_id and _req0 == req_id) or (trace_id and _tid0 == trace_id):
                        _attach_layer_meta(req_any, layer_id=_ly0.get('layer_id'), layer_instance_id=_ly0.get('layer_instance_id') or _ly0.get('instance_id'), amount_u=float(amt_u), profit_u=None)
                        return _ly0
                except Exception:
                    continue
            ly = GRID_BOOK.open_layer(
                grid_id=str(gid),
                coin=str(coin),
                platform=str(plat),
                side=str(side_now),
                notional_u=float(amt_u),
                ref_px=px,
                snapshot_id=snap_id,
                tp_pct=(meta.get('tp_pct') if isinstance(meta, dict) else None),
                step_pct=(meta.get('step_pct') if isinstance(meta, dict) else None),
                reason=str(reason or ''),
                meta_info=(meta if isinstance(meta, dict) else None),
            )
            if isinstance(ly, dict):
                try:
                    ly['open_trace_id'] = trace_id
                    ly['open_req_id'] = req_id
                    ly['open_exec_reason'] = str(reason or '')
                    ly['source_module'] = 'M9'
                    ly['grid_owner_module'] = 'M9'
                    GRID_BOOK._save()
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_821', _e)
                    pass
                try:
                    _grid_rate_mark_open(coin, plat, side_now, time.time(), layer_id=str(ly.get('layer_id') or ''), req_id=req_id)
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_822', _e)
                    pass
                try:
                    _grid_pending_open_add(coin=coin, platform=plat, side=side_now, grid_id=str(gid), layer_id=str(ly.get('layer_id') or ''), layer_no=int(ly.get('layer_no') or (_parse_layer_no(str(ly.get('layer_id') or '')) or 0) or 0), open_u=float(amt_u), entry_px=float(px or ly.get('entry_px') or 0.0), req_id=req_id, trace_id=trace_id, snapshot_id=str(snap_id or ''), ts=time.time())
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_823', _e)
                    pass
                _attach_layer_meta(req_any, layer_id=ly.get('layer_id'), layer_instance_id=ly.get('layer_instance_id') or ly.get('instance_id'), amount_u=float(amt_u), profit_u=None)
                try:
                    if _m9_legacy_view_enabled():
                        _gl = globals().get('_GRID_LEDGER')
                        if _gl is not None and hasattr(_gl, 'clear_same_layer_old_instance_suspects'):
                            _gl.clear_same_layer_old_instance_suspects(str(gid), str(ly.get('layer_id') or ''), str(ly.get('layer_instance_id') or ly.get('instance_id') or ''))
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_m9_clear_old_instance_suspects', _e)
                    pass
            return ly
        layer_id, _ltag_apply, _lno_apply = _executor_get_layer_info(rd)
        layer_id = str(layer_id or meta.get('layer_id') or meta.get('tp_layer_id') or params.get('layer_id') or params.get('tp_layer_id') or rd.get('layer_id') or rd.get('tp_layer_id') or '').strip()
        if layer_id and not meta.get('layer_id'):
            meta['layer_id'] = layer_id
        if _ltag_apply and not meta.get('layer_tag'):
            meta['layer_tag'] = _ltag_apply
        if (_lno_apply is not None) and meta.get('layer_no') is None:
            meta['layer_no'] = int(_lno_apply)
        target_before = None
        if layer_id and hasattr(GRID_BOOK, '_find_layer'):
            try:
                target_before = GRID_BOOK._find_layer(str(gid), str(layer_id))
            except Exception:
                target_before = None
        if not layer_id:
            try:
                ly = GRID_BOOK.pick_closable_layer(str(gid), cur_px=px)
            except Exception:
                ly = None
            if isinstance(ly, dict):
                layer_id = str(ly.get('layer_id') or '').strip()
                target_before = ly
        if not layer_id:
            return None
        if isinstance(target_before, dict) and str(target_before.get('status') or '').upper() == 'CLOSED':
            _profit0 = target_before.get('last_partial_realized_pnl_usd')
            if _profit0 is None:
                _profit0 = target_before.get('realized_pnl_usd')
            _attach_layer_meta(req_any, layer_id=layer_id, amount_u=float(amt_u), profit_u=_profit0)
            meta['duplicate_close_skip'] = 1
            meta['duplicate_close_reason'] = 'layer_already_closed'
            return target_before
        closed = GRID_BOOK.apply_decrease(
            grid_id=str(gid),
            layer_id=str(layer_id),
            close_notional_u=float(amt_u),
            ref_px=px,
            snapshot_id=snap_id,
            reason=str(reason or ''),
        )
        _profit = None
        if isinstance(closed, dict):
            _profit = closed.get('last_partial_realized_pnl_usd')
            if _profit is None:
                _profit = closed.get('realized_pnl_usd')
        if _profit is None:
            try:
                _profit = _extract_profit_u_from_req(_req_get_dict(req_any))
            except Exception:
                _profit = None
        _m9_close_kind = ''
        _m9_layer_status = ''
        _m9_layer_open_remaining_u = None
        _m9_layer_instance_id = ''
        try:
            if isinstance(closed, dict):
                _m9_layer_status = str(closed.get('status') or '').upper().strip()
                _m9_layer_instance_id = str(closed.get('layer_instance_id') or closed.get('instance_id') or '').strip()
                _m9_layer_open_remaining_u = float(closed.get('open_notional_u') or 0.0)
                if _m9_layer_status == 'CLOSED' and float(closed.get('runner_carry_u') or 0.0) > 0:
                    _m9_close_kind = 'PARTIAL_EXIT_TO_RUNNER'
                elif _m9_layer_status == 'CLOSED':
                    _m9_close_kind = 'FULL_CLOSE'
                elif closed.get('last_partial_close_notional_u') is not None:
                    _m9_close_kind = 'PARTIAL_CLOSE'
        except Exception:
            pass
        _meta_after = _attach_layer_meta(
            req_any,
            layer_id=layer_id,
            layer_instance_id=(_m9_layer_instance_id or None),
            amount_u=float(amt_u),
            profit_u=_profit,
            grid_id=str(gid),
            m9_close_kind=str(_m9_close_kind or ''),
            m9_layer_status=str(_m9_layer_status or ''),
            m9_layer_open_remaining_u=_m9_layer_open_remaining_u,
        )
        try:
            if isinstance(closed, dict) and isinstance(_meta_after, dict):
                for _k in ('close_grid_gap_pct', 'close_grid_gap_pct_display', 'close_grid_gap_source', 'close_realized_gap_pct', 'close_realized_gap_pct_display', 'close_fill_px', 'close_ref_px', 'last_partial_close_grid_gap_pct', 'last_partial_close_grid_gap_pct_display', 'last_partial_close_grid_gap_source', 'last_partial_close_realized_gap_pct', 'last_partial_close_realized_gap_pct_display', 'last_partial_close_fill_px'):
                    if closed.get(_k) is not None:
                        _meta_after[_k] = closed.get(_k)
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_m9_close_gap_meta', _e)
        try:
            if (px is not None) and isinstance(closed, dict):
                _tp_pct = None
                try:
                    _tp_pct = float(closed.get('tp_pct')) if closed.get('tp_pct') is not None else None
                except Exception:
                    _tp_pct = None
                GRID_BOOK.set_reentry(str(gid), side=str(side_now), close_px=float(px), notional_u=float(amt_u), tp_pct=_tp_pct)
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_824', _e)
            pass
        return closed
    except Exception as _e:
        _log_exc(mod='SYS', stage='EXC_PASS', e=_e)
        return None

def _make_exec_result_row(req_any, *, ok: bool, skipped: bool = False, reason: str = '', t_sec: object = None, exec_u: object = None, exec_px: object = None, detail: dict | None = None) -> dict:
    try:
        reqd = _req_get_dict(req_any)
    except Exception:
        reqd = {}
    meta = reqd.get('meta') if isinstance(reqd.get('meta'), dict) else {}
    amt = None
    for cand in (exec_u, reqd.get('final_amount_u'), reqd.get('amount_u'), reqd.get('amount_usd'), reqd.get('notional_u'), (reqd.get('params') or {}).get('final_amount_u') if isinstance(reqd.get('params'), dict) else None, (reqd.get('params') or {}).get('close_notional_u') if isinstance(reqd.get('params'), dict) else None, (reqd.get('params') or {}).get('add_notional_u') if isinstance(reqd.get('params'), dict) else None):
        try:
            if cand is not None:
                amt = float(cand)
                break
        except Exception:
            continue
    profit_u = None
    try:
        profit_u = _extract_profit_u_from_req(reqd)
    except Exception:
        profit_u = None
    layer_id, layer_tag, layer_no = _executor_get_layer_info(reqd)
    layer_id = str(layer_id or (meta.get('layer_id') if isinstance(meta, dict) else '') or (meta.get('tp_layer_id') if isinstance(meta, dict) else '') or reqd.get('layer_id') or reqd.get('tp_layer_id') or '')
    layer_tag = str(layer_tag or _grid_layer_tag(layer_id) or '')
    layer_no = layer_no if layer_no is not None else _grid_layer_no(layer_id)
    _cinfo = _executor_contract_detail_from_req(reqd)
    _fill_det = _exec_fill_cache_lookup(reqd) or {}
    _exec_px_final = exec_px
    try:
        if _exec_px_final is None:
            _exec_px_final = safe_float((_fill_det or {}).get('fill_price') or (_fill_det or {}).get('avg_fill_price'), default=None)
    except Exception:
        _exec_px_final = exec_px
    _price_source = 'fill' if (_exec_px_final is not None and isinstance(_fill_det, dict) and ((_fill_det or {}).get('fill_price') or (_fill_det or {}).get('avg_fill_price'))) else ('request' if _cinfo.get('request_price') is not None else None)
    _filled_notional_u = None
    try:
        if isinstance(_fill_det, dict):
            for _k in ('filled_notional_u', 'fill_notional_u', 'filled_notional', 'notional_u'):
                if (_fill_det or {}).get(_k) is not None:
                    _filled_notional_u = safe_float((_fill_det or {}).get(_k), default=None)
                    if _filled_notional_u is not None:
                        break
            if _filled_notional_u is None:
                _fq = safe_float((_fill_det or {}).get('filled_qty'), default=None)
                _fp = safe_float((_fill_det or {}).get('avg_fill_price') or (_fill_det or {}).get('fill_price'), default=None)
                if _fq is not None and _fp is not None:
                    _filled_notional_u = abs(float(_fq) * float(_fp))
    except Exception:
        _filled_notional_u = None
    _submit_verified_ok = bool((meta or {}).get('_submit_verified_ok')) if isinstance(meta, dict) else False
    _submit_verified_ev = dict((meta or {}).get('_submit_verified_ev') or {}) if isinstance(meta, dict) and isinstance((meta or {}).get('_submit_verified_ev'), dict) else {}
    _submit_verified_reason = str(_submit_verified_ev.get('reason_code') or _submit_verified_ev.get('reason') or 'confirmed_success').strip() or 'confirmed_success'
    _submit_verified_state = 'confirmed_success' if _submit_verified_ok else ('submitted_unchecked' if bool(ok) else 'submit_fail')
    out = {
        'req': reqd,
        'ok': bool(ok),
        'skipped': bool(skipped),
        'reason': str(reason or ''),
        't_sec': t_sec,
        'module': str(reqd.get('module') or '').upper().strip(),
        'coin': str(reqd.get('coin') or '').upper().strip(),
        'platform': str(reqd.get('platform') or reqd.get('plat') or '').upper().strip(),
        'action_type': str(reqd.get('action_type') or reqd.get('action') or '').lower().strip(),
        'side': _cinfo.get('side'),
        'request_ts': _cinfo.get('request_ts'),
        'request_price': _cinfo.get('request_price'),
        'ind_rsi': _cinfo.get('ind_rsi'),
        'ind_adx': _cinfo.get('ind_adx'),
        'intent_notional_u': amt,
        'exec_u': amt,
        'notional_u': amt,
        'filled_notional_u': _filled_notional_u,
        'exec_price': _exec_px_final,
        'fill_price': (safe_float((_fill_det or {}).get('fill_price') or (_fill_det or {}).get('avg_fill_price'), default=None) if isinstance(_fill_det, dict) else None),
        'avg_fill_price': (safe_float((_fill_det or {}).get('avg_fill_price') or (_fill_det or {}).get('fill_price'), default=None) if isinstance(_fill_det, dict) else None),
        'filled_qty': ((_fill_det or {}).get('filled_qty') if isinstance(_fill_det, dict) else None),
        'order_id': ((_fill_det or {}).get('order_id') if isinstance(_fill_det, dict) else None),
        'price_source': _price_source,
        'close_grid_gap_pct': (meta.get('close_grid_gap_pct') if isinstance(meta, dict) else None),
        'close_grid_gap_pct_display': (meta.get('close_grid_gap_pct_display') if isinstance(meta, dict) else None),
        'close_grid_gap_source': (meta.get('close_grid_gap_source') if isinstance(meta, dict) else None),
        'close_realized_gap_pct': (meta.get('close_realized_gap_pct') if isinstance(meta, dict) else None),
        'close_realized_gap_pct_display': (meta.get('close_realized_gap_pct_display') if isinstance(meta, dict) else None),
        'price': _exec_px_final if _exec_px_final is not None else _cinfo.get('request_price'),
        'profit_u': profit_u if profit_u is not None else _cinfo.get('profit_u'),
        'realized_pnl_u': profit_u if profit_u is not None else _cinfo.get('profit_u'),
        'realized_pnl_usd': profit_u if profit_u is not None else _cinfo.get('profit_u'),
        'grid_id': (meta.get('grid_id') if isinstance(meta, dict) else None),
        'layer_id': layer_id or (_cinfo.get('layer_id') or None),
        'layer_tag': layer_tag or (_cinfo.get('layer_tag') or None),
        'layer_no': layer_no if layer_no is not None else _cinfo.get('layer_no'),
        'grid_action_label': (meta.get('grid_action_label') if isinstance(meta, dict) else None) or _cinfo.get('grid_action_label'),
        'm9_open_plan_u': (safe_float((meta.get('m9_open_plan_u') if isinstance(meta, dict) else None), default=None)),
        'm9_tp_contract_u': (safe_float((meta.get('m9_tp_contract_u') if isinstance(meta, dict) else None), default=None)),
        'm9_tp_contract_remaining_u': (safe_float((meta.get('m9_tp_contract_remaining_u') if isinstance(meta, dict) else None), default=None)),
        'm9_bias_extra_u': (safe_float((meta.get('m9_bias_extra_u') if isinstance(meta, dict) else None), default=None)),
        'm9_direction_bias_active': (bool((meta.get('m9_direction_bias_active') if isinstance(meta, dict) else False))),
        'm9_direction_bias_mode': (str((meta.get('m9_direction_bias_mode') if isinstance(meta, dict) else '') or '')),
        'm9_bias_carry_only': (bool((meta.get('m9_bias_carry_only') if isinstance(meta, dict) else False) or (meta.get('bias_carry_only') if isinstance(meta, dict) else False))),
        'submit_ok': bool(ok),
        'fill_confirmed': bool(_filled_notional_u and float(_filled_notional_u) > 0.0),
        'postcheck_ok': (True if _submit_verified_ok else None),
        'postcheck_state': ('verified_ok' if _submit_verified_ok else 'not_checked'),
        'pending_confirm': (False if _submit_verified_ok else bool(ok)),
        'confirmed_success': bool(_submit_verified_ok),
        'confirmed_fail': False,
        'submit_failed': (not bool(ok)),
        'confirmation_state': _submit_verified_state,
        'status_label': ('confirmed' if _submit_verified_ok else ('pending_confirm' if bool(ok) else 'submit_fail')),
        'execution_evidence': {
            'submit_ok': bool(ok),
            'postcheck_ok': (True if _submit_verified_ok else None),
            'final_state': _submit_verified_state,
            'final_confirmation_code': ('confirmed_success' if _submit_verified_ok else ('submit_fail' if not bool(ok) else 'submitted_unchecked')),
            'reason': _submit_verified_reason,
            'confirm_mode': str(_submit_verified_ev.get('confirm_mode') or ''),
            'effective': bool(_submit_verified_ok),
            'trade_effective_count': (1 if _submit_verified_ok else 0),
        },
    }
    if _submit_verified_ok and _submit_verified_ev:
        try:
            out['execution_evidence']['verify'] = dict(_submit_verified_ev)
        except Exception:
            pass
    if isinstance(detail, dict) and detail:
        out['detail'] = detail
        try:
            _fs = str(detail.get('fail_step') or '').strip()
        except Exception:
            _fs = ''
        try:
            _fr = str(detail.get('fail_reason') or '').strip()
        except Exception:
            _fr = ''
        if _fs and (not out.get('fail_step')):
            out['fail_step'] = _fs
        if _fr and (not out.get('fail_reason')):
            out['fail_reason'] = _fr
    # Same-symbol pending records may belong to older requests. They cannot
    # turn this request's disabled button / pre-click failure into a submission.
    out = _apply_submission_evidence(out, (meta or {}).get('_submission_attempts') or [])
    return _result_apply_confirmation_fields(out)

def _req_action_buy_sell(action_type: str, side: str) -> str:
    """把 action_type+方向映射为 买/卖（符合你的口径）。"""
    try:
        act = str(action_type or "").strip().lower()
        sd = str(side or "").strip().upper()
        is_open_like = act in ("open","open_leg","add","add_leg","increase","grid_add","grid_increase")
        is_close_like = act in ("close","close_leg","reduce","decrease","grid_reduce","grid_decrease")
        if is_open_like:
            return "BUY" if sd == "LONG" else ("SELL" if sd == "SHORT" else "-")
        if is_close_like:
            return "SELL" if sd == "LONG" else ("BUY" if sd == "SHORT" else "-")
        if act == "close_pair":
            return "CLOSE_PAIR"
        return act.upper() if act else "-"
    except Exception:
        return "-"

def _bot_console_emit_exec_action(rr: dict) -> None:
    """对单条执行器结果 rr 输出一行 bot_console 动作日志。永不抛异常。"""
    try:
        if not _BOT_CONSOLE_ACTION_ENABLED:
            return
        if not isinstance(rr, dict):
            return
        reqd = rr.get("req") if isinstance(rr.get("req"), dict) else {}
        if not isinstance(reqd, dict) or (not reqd):
            return

        ok = 1 if bool(rr.get("ok")) else 0
        skipped = 1 if bool(rr.get("skipped")) else 0
        mod = str(reqd.get("module") or "-").upper()
        subm = str(reqd.get("submodule") or "").strip()
        coin = str(reqd.get("coin") or "-").upper()
        plat = str(reqd.get("platform") or "-").upper()
        act_type = str(reqd.get("action_type") or "-").strip()
        params = reqd.get("params") if isinstance(reqd.get("params"), dict) else {}
        meta = reqd.get("meta") if isinstance(reqd.get("meta"), dict) else {}

        side = ""
        try:
            side = _extract_side(params, meta)
        except Exception:
            side = str(params.get("side") or meta.get("side") or "").upper()

        notional_u = None
        try:
            notional_u = _extract_amount_usd(params, meta)
        except Exception:
            notional_u = safe_float(params.get("amount_u") or params.get("amount_usd") or meta.get("amount_u") or meta.get("amount_usd"), default=None)
        if notional_u is None:
            notional_u = safe_float(rr.get("exec_notional_u") or rr.get("filled_notional_u"), default=None)

        profit_u = safe_float(rr.get("profit_u"), default=None)
        if profit_u is None:
            profit_u = _extract_profit_u_from_req(reqd)

        trace = ""
        try:
            trace = str(rr.get("trace_id") or reqd.get("trace_id") or meta.get("trace_id") or "").strip()
        except Exception:
            trace = ""
        if not trace:
            try:
                trace = str(_get_current_trace_id() or "").strip()
            except Exception:
                trace = ""

        reason = str(rr.get("reason") or rr.get("detail") or "").strip()

        ind_rsi = None
        ind_adx = None
        ind_age = None
        try:
            if isinstance(meta, dict):
                ind_rsi = meta.get("ind_rsi", None)
                ind_adx = meta.get("ind_adx", None)
                ind_age = meta.get("ind_age_sec", None)
                if ind_age is None:
                    _its = meta.get("ind_ts", None)
                    if _its is not None:
                        try:
                            ind_age = max(0.0, float(time.time()) - float(_its))
                        except Exception:
                            ind_age = None
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_825', _e)
            pass
        action_bs = _req_action_buy_sell(act_type, side)
        ts = _fmt_ts_local(float(rr.get("exec_ts") or rr.get("ts") or time.time()))
        parts = [
            "[EXEC_ACTION]",
            f"ts={ts}",
            f"plat={plat}",
            f"coin={coin}",
            f"mod={mod}{('/'+subm) if subm else ''}",
            f"action={action_bs}",
            f"dir={str(side or '-').upper()}",
        ]
        try:
            if ind_rsi is not None:
                parts.append(f"rsi={float(ind_rsi):.2f}")
            else:
                parts.append("rsi=-")
        except Exception:
            parts.append(f"rsi={ind_rsi if ind_rsi is not None else '-'}")
        try:
            if ind_adx is not None:
                parts.append(f"adx={float(ind_adx):.2f}")
            else:
                parts.append("adx=-")
        except Exception:
            parts.append(f"adx={ind_adx if ind_adx is not None else '-'}")
        try:
            if ind_age is not None:
                parts.append(f"ind_age_s={float(ind_age):.0f}")
            else:
                parts.append("ind_age_s=-")
        except Exception:
            parts.append(f"ind_age_s={ind_age if ind_age is not None else '-'}")

        if notional_u is not None:
            try:
                parts.append(f"notional_u={float(notional_u):.2f}")
            except Exception:
                parts.append(f"notional_u={notional_u}")
        else:
            parts.append("notional_u=-")
        try:
            _layer_id = str(meta.get("layer_id") or "") if isinstance(meta, dict) else ""
            _layer_tag = _grid_layer_tag(_layer_id)
            if _layer_tag:
                parts.append(f"layer={_layer_tag}")
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_826', _e)
            pass
        if profit_u is not None:
            try:
                parts.append(f"profit_u={float(profit_u):.4f}")
            except Exception:
                parts.append(f"profit_u={profit_u}")
        else:
            parts.append("profit_u=-")
        parts.append(f"ok={ok}")
        parts.append(f"skipped={skipped}")
        if trace:
            parts.append(f"trace={trace}")
        if reason:
            parts.append(f"reason={str(reason)[:220]}")
        print(" ".join(parts))
    except Exception:
        try:
            print("[EXEC_ACTION][ERR] emit_failed")
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_827', _e)
            pass
_NOISE_GUARD_LAST: dict[str, dict] = {}

def _noise_guard_cfg() -> tuple[float, float]:
    """返回 (min_interval_sec, min_price_gap_pct)。可用环境变量覆盖：
    - GRID_NOISE_MIN_INTERVAL_SEC
    - GRID_NOISE_MIN_PX_GAP_PCT
    """
    try:
        mi = safe_float(os.getenv("GRID_NOISE_MIN_INTERVAL_SEC"), default=None)
        mg = safe_float(os.getenv("GRID_NOISE_MIN_PX_GAP_PCT"), default=None)
        min_interval = float(mi) if mi is not None else 90.0
        min_gap = float(mg) if mg is not None else 0.003
        if min_interval < 0:
            min_interval = 0.0
        if min_gap < 0:
            min_gap = 0.0
        return min_interval, min_gap
    except Exception:
        return 90.0, 0.003

def _noise_guard_key(req: 'Request', side: str) -> str:
    try:
        return "|".join([
            str(getattr(req, "module", "") or "").upper(),
            str(getattr(req, "platform", "") or "").upper(),
            str(getattr(req, "coin", "") or "").upper(),
            str(side or "").upper(),
            str(getattr(req, "action_type", "") or "").lower(),
        ])
    except Exception:
        return "UNK"

def _noise_guard_should_bypass(req: 'Request', *, meta: dict | None = None, params: dict | None = None) -> tuple[bool, str]:
    """人话：修复/补救单不要被网格噪声门禁二次卡死。

    典型场景：
    - 上一笔执行器超时，但其实这次不是“网格噪声”，而是执行链路挂了；
    - postcheck 判 no_effect 后，下一轮要立刻重试；
    - 自动修复/补救路径（recover/retry/safe_legacy_fix）本来就不该再吃 min_interval。
    """
    try:
        meta = meta if isinstance(meta, dict) else (getattr(req, "meta", {}) if isinstance(getattr(req, "meta", None), dict) else {})
    except Exception:
        meta = {}
    try:
        params = params if isinstance(params, dict) else (getattr(req, "params", {}) if isinstance(getattr(req, "params", None), dict) else {})
    except Exception:
        params = {}
    try:
        mod = str(getattr(req, "module", "") or "").upper().strip()
    except Exception:
        mod = ""
    try:
        act = str(getattr(req, "action_type", "") or "").lower().strip()
    except Exception:
        act = ""

    flags = [
        "bypass_noise_guard", "recover_retry", "recover_pending", "safe_legacy_fix",
        "force_recover", "force_retry", "timeout_recover", "postcheck_recover",
        "executor_timeout_recover", "auto_recover", "requeue_after_timeout",
    ]
    for _k in flags:
        try:
            if bool(meta.get(_k)) or bool(params.get(_k)):
                return True, f"flag:{_k}"
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_828', _e)
            pass
    try:
        _src = str(meta.get("retry_source") or meta.get("recover_source") or meta.get("queue_retry_reason") or meta.get("fail_reason") or "").lower()
    except Exception:
        _src = ""
    if _src and any(_kw in _src for _kw in ("worker_timeout", "executor_timeout", "postcheck_increase_no_effect", "postcheck_fail", "ui_dead", "recover")):
        return True, f"source:{_src[:80]}"

    try:
        if mod in ("LEGACY_DELETED", "LEGACY_DELETED", "X1"):
            return True, f"legacy_deleted_mod:{mod}"
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_829', _e)
        pass
    try:
        if mod == "M9" and act in ("increase", "open", "add") and bool(meta.get("safe_legacy_fix")):
            return True, "m9_safe_legacy_fix"
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_830', _e)
        pass
    return False, ""

def _noise_guard_check(req: 'Request') -> tuple[bool, str, dict]:
    """返回 (allow, reason, detail)。只对网格类请求启用：W1/M9。

    关键口径修复：
    - 这里只做检查，不再在“入队前”提前写入 _NOISE_GUARD_LAST；
    - 只有确认成功后，才由 _noise_guard_commit(...) 落最终时间戳；
    - 否则一次 timeout / no_effect 也会把下一轮补救卡死。
    """
    detail: dict = {}
    try:
        mod = str(getattr(req, "module", "") or "").upper()
        if mod not in ("W1", "M9"):
            return True, "na", detail
        act = str(getattr(req, "action_type", "") or "").lower()
        if act in ("close_pair",):
            return True, "na", detail

        params = getattr(req, "params", {}) if isinstance(getattr(req, "params", None), dict) else {}
        meta = getattr(req, "meta", {}) if isinstance(getattr(req, "meta", None), dict) else {}

        _bypass, _bypass_reason = _noise_guard_should_bypass(req, meta=meta, params=params)
        if _bypass:
            return True, f"bypass:{_bypass_reason}", {"bypass": True, "bypass_reason": str(_bypass_reason or "")}

        try:
            side = _extract_side(params, meta)
        except Exception:
            side = str(params.get("side") or meta.get("side") or "").upper()

        k = _noise_guard_key(req, side)
        now = time.time()
        min_interval, min_gap = _noise_guard_cfg()
        detail["min_interval_sec"] = min_interval
        detail["min_px_gap_pct"] = min_gap

        last = _NOISE_GUARD_LAST.get(k) if isinstance(_NOISE_GUARD_LAST, dict) else None
        last = last if isinstance(last, dict) else {}
        last_ts = safe_float(last.get("ts"), default=0.0) or 0.0
        last_px = safe_float(last.get("ref_px"), default=None)

        cur_px = safe_float((meta or {}).get("ref_px") if isinstance(meta, dict) else None, default=None)
        if cur_px is None:
            cur_px = safe_float((params or {}).get("ref_px") if isinstance(params, dict) else None, default=None)

        dt = float(now - float(last_ts or 0.0))
        detail["dt_sec"] = dt
        if (min_interval > 0) and (last_ts > 0) and (dt < min_interval):
            return False, f"noise_guard:min_interval<{min_interval:.0f}s", {"k": k, **detail}

        if (min_gap > 0) and (last_px is not None) and (cur_px is not None) and (float(last_px) > 0):
            gap = abs(float(cur_px) - float(last_px)) / float(last_px)
            detail["px_gap_pct"] = gap
            if gap < float(min_gap):
                return False, f"noise_guard:min_px_gap<{min_gap:.4f}", {"k": k, **detail, "last_px": last_px, "cur_px": cur_px}

        return True, "ok", {"k": k, **detail, "cur_px": cur_px}
    except Exception as _e:
        return True, "na", {"err": repr(_e)}

def _noise_guard_commit(req_any: Any, *, ref_px: float | None = None, reason: str = "confirmed_success") -> dict:
    """只有确认成功后才记噪声门禁时间戳。"""
    try:
        _rd = _req_get_dict(req_any) if '_req_get_dict' in globals() else None
    except Exception:
        _rd = None
    try:
        if not isinstance(_rd, dict):
            _rd = req_any if isinstance(req_any, dict) else {}
    except Exception:
        _rd = {}
    try:
        _mod = str((_rd or {}).get("module") or getattr(req_any, "module", "") or "").upper().strip()
        _act = str((_rd or {}).get("action_type") or (_rd or {}).get("action") or getattr(req_any, "action_type", "") or "").lower().strip()
        if _mod not in ("W1", "M9") or _act in ("close_pair",):
            return {"ok": False, "reason": "na"}
        _params = (_rd or {}).get("params") if isinstance((_rd or {}).get("params"), dict) else {}
        _meta = (_rd or {}).get("meta") if isinstance((_rd or {}).get("meta"), dict) else {}
        try:
            _side = _extract_side(_params, _meta)
        except Exception:
            _side = str(_params.get("side") or _meta.get("side") or (_rd or {}).get("side") or "").upper()
        _req_obj = type('_NGReq', (), {'module': _mod, 'coin': str((_rd or {}).get("coin") or ""), 'platform': str((_rd or {}).get("platform") or ""), 'action_type': _act})()
        _k = _noise_guard_key(_req_obj, _side)
        _px = safe_float(ref_px, default=None)
        if _px is None:
            _px = safe_float((_meta or {}).get("ref_px"), default=None)
        if _px is None:
            _px = safe_float((_params or {}).get("ref_px"), default=None)
        if _px is None:
            _px = safe_float((_rd or {}).get("request_price") or (_rd or {}).get("price"), default=None)
        _NOISE_GUARD_LAST[str(_k)] = {"ts": float(time.time()), "ref_px": _px, "reason": str(reason or "confirmed_success")[:80]}
        return {"ok": True, "k": str(_k), "ref_px": _px, "reason": str(reason or "confirmed_success")[:80]}
    except Exception as _e:
        return {"ok": False, "reason": f"exception:{type(_e).__name__}"}

def parse_signed_number(txt: Any) -> Optional[float]:
    """更稳健的带符号数值解析
    - 兼容：-$12.3 / $-12.3 / −12.3 / (12.3)
    - 避免：clean_num 已含符号又二次乘符号导致正负翻转
    """
    if txt is None:
        return None
    s = str(txt).strip().replace(",", "").replace("−", "-")
    if not s:
        return None

    neg_by_bracket = ("(" in s and ")" in s)

    m = re.search(r"[-+]?(?:\d+\.\d+|\d+)", s)
    if not m:
        return None
    raw = m.group(0)
    try:
        v = float(raw)
    except Exception:
        return None

    head = s.lstrip()
    if raw and raw[0] not in "+-" and head.startswith("-"):
        v = -abs(v)
    if raw and raw[0] not in "+-" and head.startswith("+"):
        v = abs(v)

    if neg_by_bracket:
        v = -abs(v)

    return v

def parse_pnl_value(txt: Any) -> Optional[float]:
    """用于持仓 PnL 的稳健解析：
    - EXT/VAR 可能同时出现「百分比 + 金额」两个数，这里默认取最后一个数作为金额
    - 兼容：-$12.3 / $-12.3 / −12.3 / (12.3) / - 12.3
    """
    if txt is None:
        return None
    s = str(txt).strip().replace(",", "").replace("−", "-")
    if not s:
        return None

    neg_by_bracket = ("(" in s and ")" in s)

    nums = re.findall(r"[-+]?(?:\d+\.\d+|\d+)", s)
    if not nums:
        return None

    raw = nums[-1]  # 关键：取最后一个，通常是金额（U/USD），前面可能是百分比
    try:
        v = float(raw)
    except Exception:
        return None

    head = s.lstrip()
    if raw and raw[0] not in "+-" and head.startswith("-"):
        v = -abs(v)
    if raw and raw[0] not in "+-" and head.startswith("+"):
        v = abs(v)

    if neg_by_bracket:
        v = -abs(v)

    return v

def parse_upnl_cell(txt: Any) -> Tuple[Optional[float], Optional[float]]:
    """Parse a PnL cell text and return (usd_pnl, pct_pnl).

    We prefer the number that is explicitly tied to USD/$, not the percentage.
    Handles formats like:
      - -20.78 USD
-138.67%
      - -$20.78 (-138.67%)
      - $10.27 (+79.94%)
      - (3.66) USD (-43.53%)
    """
    if txt is None:
        return None, None
    s = str(txt).strip().replace(',', '').replace('−', '-')
    s = re.sub(r'\$\s*([+-])\s*', r'\1$', s)
    if not s:
        return None, None

    usd = None

    m = re.search(r'([+-])?\s*\$\s*(\(?\d+(?:\.\d+)?\)?)', s)
    if m:
        num = parse_signed_number(m.group(2))
        if num is not None:
            sign = -1 if (m.group(1) == '-') else 1
            usd = sign * abs(num)

    if usd is None:
        m = re.search(r'([-+]?\(?\d+(?:\.\d+)?\)?)\s*(?:USD|\$)', s, flags=re.IGNORECASE)
        if m:
            usd = parse_signed_number(m.group(1))

    pct = None
    m = re.search(r'([-+]?\(?\d+(?:\.\d+)?\)?)\s*%', s)
    if m:
        pct = parse_signed_number(m.group(1))

    if usd is None:
        usd = parse_pnl_value(s)

    return usd, pct

def sign_from_text(s: str) -> int:
    if not s:
        return 1
    t = s.strip().replace("−", "-")
    return -1 if t.startswith("-") else 1

def norm_coin_symbol(s: str) -> str:
    s = str(s or "").strip().upper()
    if not s:
        return ""
    # [PATCH] EXT 改版：持仓行 MARKET 单元格是多行 "BTC\n-\nUSD\nPerp"，只取第一行非空内容作为币种
    if "\n" in s:
        s = next((ln.strip() for ln in s.splitlines() if ln.strip()), "")
        if not s:
            return ""
    for suf in ["-USD", "/USD"]:
        if s.endswith(suf):
            s = s[: -len(suf)]
            break
    if s.endswith("USD") and len(s) > 3:
        s = s[:-3]
    return s

