M9_OLD_LAYER_MIN_NET_PCT = float(os.environ.get('M9_OLD_LAYER_MIN_NET_PCT') or 0.0015)
M9_OLD_LAYER_PARTIAL_RATIO = float(os.environ.get('M9_OLD_LAYER_PARTIAL_RATIO') or 0.35)
M9_OLD_LAYER_NEAR_BREAKEVEN_PCT = float(os.environ.get('M9_OLD_LAYER_NEAR_BREAKEVEN_PCT') or 0.0025)
M9_OLD_LAYER_REBOUND_TRAIL_PCT = float(os.environ.get('M9_OLD_LAYER_REBOUND_TRAIL_PCT') or 0.0035)

def _m9_estimate_net_profit_u(side: str, open_px: float, close_px: float, notional_u: float, fee_rate: float = M9_FEE_RATE) -> float:
    try:
        opx = float(open_px)
        cpx = float(close_px)
        nu = float(notional_u)
        fr = float(fee_rate)
    except Exception:
        return 0.0
    if nu <= 0 or opx <= 0:
        return 0.0
    s = str(side or '').upper()
    if s == 'LONG':
        pnl = nu * (cpx - opx) / opx
    elif s == 'SHORT':
        pnl = -nu * (cpx - opx) / opx
    else:
        pnl = 0.0
    fees = nu * fr * 2.0
    try:
        return float(pnl - fees)
    except Exception:
        return 0.0

def _m9_tp_hit_update(key: tuple, hit: bool, now_ts: float) -> int:
    try:
        rec = _M9_TP_HIT_TRACK.get(key) or {}
        last_ts = float(rec.get('last_ts') or 0.0)
        cnt = int(rec.get('cnt') or 0)
        if not hit:
            _M9_TP_HIT_TRACK[key] = {'cnt': 0, 'last_ts': float(now_ts)}
            return 0
        if last_ts > 0 and (now_ts - last_ts) > float(M9_TP_CONFIRM_WINDOW_SEC):
            cnt = 0
        cnt = cnt + 1
        _M9_TP_HIT_TRACK[key] = {'cnt': int(cnt), 'last_ts': float(now_ts)}
        return int(cnt)
    except Exception:
        try:
            _M9_TP_HIT_TRACK[key] = {'cnt': 0, 'last_ts': float(now_ts)}
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

        return 0

def _m9_tp_hit_ready(grid_id: str, layer_id: str, hit: bool, now_ts: float) -> bool:
    key = (str(grid_id), str(layer_id))
    rec = _M9_TP_HIT_TRACK.get(key) or {"cnt": 0, "last_ts": 0.0}
    last_ts = float(rec.get("last_ts") or 0.0)
    cnt = int(rec.get("cnt") or 0)

    if not hit:
        _M9_TP_HIT_TRACK.pop(key, None)
        return False

    if last_ts and (float(now_ts) - last_ts > float(M9_TP_CONFIRM_WINDOW_SEC)):
        cnt = 0

    cnt += 1
    _M9_TP_HIT_TRACK[key] = {"cnt": cnt, "last_ts": float(now_ts)}
    return cnt >= int(M9_TP_CONFIRM_HITS)

def _m9_layer_truth_open_px(layer: dict | None, default: float | None = None) -> float | None:
    """网格层开仓真相价：只认真实成交价 fill，其次才允许回退到 request；禁止把 position_avg 当成网格层价。"""
    try:
        ly = layer if isinstance(layer, dict) else {}
        for _k in (
            'layer_fill_px', 'fill_price', 'avg_fill_price',
            'layer_request_px', 'request_price',
            'layer_open_px', 'open_ref_px', 'open_px',
        ):
            try:
                _v = ly.get(_k)
            except Exception:
                _v = None
            if _v is None:
                continue
            try:
                _fv = float(_v)
            except Exception:
                continue
            if _fv > 0:
                return float(_fv)
        return default
    except Exception:
        return default

def _m9_est_layer_net_profit_u(layer: dict | None, side: str, cur_px: float | None, close_u: float | None = None) -> tuple[float | None, dict]:
    """估算单层当前若止盈，扣双边手续费 + 执行拖延缓冲后的净利润。"""
    det = {}
    try:
        ly = dict(layer or {})
        opx = float(_m9_layer_truth_open_px(ly, 0.0) or 0.0)
        cpx = float(cur_px or 0.0)
        ou = float(ly.get('open_notional_u') or ly.get('open_u') or 0.0)
        cu = float(close_u if close_u is not None else ou)
        if opx <= 0.0 or cpx <= 0.0 or ou <= 0.0 or cu <= 0.0:
            return None, {'reason': 'bad_px_or_u', 'open_px': opx, 'cur_px': cpx, 'open_u': ou, 'close_u': cu}
        cu = max(0.0, min(float(cu), float(ou)))
        side_u = str(side or '').upper()
        if side_u == 'LONG':
            gross = float(cu) * (float(cpx) - float(opx)) / float(opx)
        elif side_u == 'SHORT':
            gross = -float(cu) * (float(cpx) - float(opx)) / float(opx)
        else:
            return None, {'reason': 'bad_side', 'side': side_u}
        fee_rate = float(ly.get('open_fee_rate') or M9_FEE_RATE)
        fee_u = float(cu) * float(fee_rate) * 2.0
        drag_u = float(cu) * float(M9_EXEC_DRAG_PCT)
        net_u = float(gross) - float(fee_u) - float(drag_u)
        det = {
            'gross_u': round(float(gross), 6),
            'fee_u': round(float(fee_u), 6),
            'drag_u': round(float(drag_u), 6),
            'net_u': round(float(net_u), 6),
            'open_px': float(opx),
            'cur_px': float(cpx),
            'open_u': float(ou),
            'close_u': float(cu),
            'need_u_abs': round(float(M9_MIN_NET_PROFIT_U), 6),
            'need_u_pct': round(float(cu) * float(M9_MIN_NET_PROFIT_PCT), 6),
        }
        return float(net_u), det
    except Exception as e:
        return None, {'reason': f'calc_exc:{type(e).__name__}'}

def _grid_live_step_pct(coin: str, *, fallback: float | None = None) -> tuple[float, dict]:
    try:
        gap, det = _m9_gap_from_ring(str(coin or '').upper())
        return float(gap), dict(det or {})
    except Exception as e:
        try:
            fb = float(fallback if fallback is not None else 0.01)
        except Exception:
            fb = 0.01
        return float(max(0.01, fb)), {'source': f'grid_live_step_pct_exc:{type(e).__name__}', 'formula': 'fallback=max(1%,provided)'}

def _grid_live_tp_pct(coin: str, *, step_pct: float | None = None, fallback: float | None = None) -> tuple[float, dict]:
    """网格止盈与网格间距同口径：近24h波动×10%，统一最低地板 1%。"""
    coin_u = str(coin or '').upper()
    floor = float(_m9_gap_truth_floor_pct(coin_u))
    cap = float(_m9_gap_truth_cap_pct(coin_u))
    try:
        raw_tp = None
        trig_det = {}
        try:
            _base_tp, trig_det = _coin_unified_trigger_pct(coin_u, default=(fallback if fallback is not None else floor))
            raw_tp = _safe_float((trig_det or {}).get('raw_trigger_pct'), None)
            if raw_tp is None or float(raw_tp) <= 0.0:
                raw_tp = _safe_float(_base_tp, None)
        except Exception as _e_inner:
            trig_det = {'src': f'grid_tp_trigger_exc:{type(_e_inner).__name__}'}
            raw_tp = None
        if raw_tp is None or float(raw_tp) <= 0.0:
            raw_tp = float(fallback if fallback is not None else floor)
        tp_pct = float(min(max(float(raw_tp), float(floor)), float(cap)))
        det = dict(trig_det or {})
        det.update({
            'tp_pct': float(tp_pct),
            'tp_floor': float(floor),
            'tp_cap': float(cap),
            'raw_tp_pct': float(raw_tp),
            'step_pct_input': (_safe_float(step_pct, None) if 'step_pct' in locals() else None),
            'tp_policy': 'same_as_grid_gap_24h_vol_x_10pct',
        })
        return float(tp_pct), det
    except Exception as e:
        tp_pct = float(max(fallback if fallback is not None else floor, floor))
        return tp_pct, {'coin': coin_u, 'src': f'grid_tp_exc:{type(e).__name__}', 'tp_pct': tp_pct, 'tp_floor': float(floor), 'tp_cap': float(cap)}

def _m9_normalize_tp_pct(coin: str, raw_tp_pct: float | None, *, step_pct: float | None = None,
                         fallback: float | None = None, tp_min: float | None = None,
                         tp_max: float | None = None) -> tuple[float, dict]:
    """把新单/历史层 TP 统一压回“近24h波动×10% + 币种地板”的动态区间，不再叠隐藏保守地板。"""
    coin_u = str(coin or '').upper().strip()
    det = {'coin': coin_u, 'src': 'm9_tp_norm'}
    try:
        _raw = float(raw_tp_pct) if raw_tp_pct is not None else 0.0
    except Exception:
        _raw = 0.0
    try:
        _step = float(step_pct) if step_pct is not None else None
    except Exception:
        _step = None
    try:
        live_tp, live_det = _grid_live_tp_pct(coin_u, step_pct=_step, fallback=fallback)
    except Exception as e:
        live_tp = float(max(_m9_gap_truth_floor_pct(coin_u), _safe_float(fallback, 0.0) or 0.0))
        live_det = {'src': f'm9_tp_norm_live_exc:{type(e).__name__}', 'tp_floor': float(_m9_gap_truth_floor_pct(coin_u)), 'tp_cap': float(_m9_gap_truth_cap_pct(coin_u))}
    floor_candidates = [float(_m9_gap_truth_floor_pct(coin_u)), float(live_tp)]
    for _v in (fallback, tp_min):
        try:
            if _v is not None and float(_v) > 0:
                floor_candidates.append(float(_v))
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_869', _e)
            pass
    floor_v = max(float(x) for x in floor_candidates if x is not None)
    cap_candidates = [float((live_det or {}).get('tp_cap') or _coin_trigger_cap_pct(coin_u))]
    for _v in (tp_max,):
        try:
            if _v is not None and float(_v) > 0:
                cap_candidates.append(float(_v))
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_870', _e)
            pass
    cap_v = min(cap_candidates) if cap_candidates else float(_coin_trigger_cap_pct(coin_u))
    cap_v = max(float(cap_v), float(floor_v))
    eff = float(_raw if _raw > 0 else live_tp)
    eff = min(max(float(eff), float(floor_v)), float(cap_v))
    det.update(dict(live_det or {}))
    det.update({'raw_tp_pct': float(_raw), 'tp_pct': float(eff), 'tp_floor': float(floor_v), 'tp_cap': float(cap_v), 'tp_hidden_floor_removed': True})
    return float(eff), det

def _m9_normalize_layer_tp(layer: dict | None, *, coin: str, side: str, ref_px: float | None = None,
                           fallback_tp_pct: float | None = None, tp_min: float | None = None,
                           tp_max: float | None = None) -> tuple[float | None, float | None, bool, dict]:
    """归一化历史层 TP：优先修正过宽/缺失的 tp_pct，再同步 tp_px。"""
    ly = layer if isinstance(layer, dict) else {}
    det = {'coin': str(coin or '').upper().strip(), 'side': str(side or '').upper().strip(), 'changed': False}
    try:
        step_pct = None
        for _k in ('grid_pct', 'step_pct', 'reentry_step_pct'):
            try:
                _v = ly.get(_k)
                if _v is not None and float(_v) > 0:
                    step_pct = float(_v)
                    break
            except Exception:
                continue
        tp_pct_raw = ly.get('tp_pct')
        tp_pct, tp_det = _m9_normalize_tp_pct(str(coin or ''), tp_pct_raw, step_pct=step_pct,
                                              fallback=fallback_tp_pct, tp_min=tp_min, tp_max=tp_max)
        opx = None
        for _k in ('layer_open_px', 'open_ref_px', 'open_px', 'layer_fill_px', 'layer_request_px', 'request_price'):
            try:
                _v = ly.get(_k)
                if _v is not None and float(_v) > 0:
                    opx = float(_v)
                    break
            except Exception:
                continue
        if (opx is None or opx <= 0) and ref_px is not None:
            try:
                if float(ref_px) > 0:
                    opx = float(ref_px)
            except Exception:
                opx = None
        tp_px = None
        if opx is not None and opx > 0:
            if str(side or '').upper().strip() == 'SHORT':
                tp_px = float(opx) * (1.0 - float(tp_pct))
            else:
                tp_px = float(opx) * (1.0 + float(tp_pct))
        changed = False
        try:
            old_tp_pct = float(tp_pct_raw) if tp_pct_raw is not None else None
        except Exception:
            old_tp_pct = None
        try:
            old_tp_px = float(ly.get('tp_px')) if ly.get('tp_px') is not None else None
        except Exception:
            old_tp_px = None
        if old_tp_pct is None or abs(float(old_tp_pct) - float(tp_pct)) > 1e-9:
            ly['tp_pct'] = round(float(tp_pct), 6)
            changed = True
        if opx is not None and (ly.get('open_ref_px') is None or float(ly.get('open_ref_px') or 0.0) <= 0.0):
            ly['open_ref_px'] = float(opx)
            changed = True
        if tp_px is not None and (old_tp_px is None or abs(float(old_tp_px) - float(tp_px)) > max(1e-9, abs(float(tp_px)) * 1e-9)):
            ly['tp_px'] = float(tp_px)
            ly['tp_ts'] = float(time.time())
            changed = True
        det.update(dict(tp_det or {}))
        det.update({'changed': bool(changed), 'open_ref_px': (float(opx) if opx is not None else None), 'tp_px': (float(tp_px) if tp_px is not None else None)})
        return (float(tp_px) if tp_px is not None else None), float(tp_pct), bool(changed), det
    except Exception as e:
        det.update({'src': f'm9_layer_tp_exc:{type(e).__name__}', 'exc': repr(e)})
        try:
            tp_px = float(ly.get('tp_px')) if ly.get('tp_px') is not None else None
        except Exception:
            tp_px = None
        try:
            tp_pct = float(ly.get('tp_pct')) if ly.get('tp_pct') is not None else None
        except Exception:
            tp_pct = None
        return tp_px, tp_pct, False, det

def _m9_layer_effective_tp_px(layer: dict | None, *, coin: str, side: str, cur_px: float | None = None,
                              ref_px: float | None = None, allow_reprice: bool = True) -> tuple[float | None, float | None, bool, dict]:
    """返回当前层生效 TP。
    口径：保留原始 tp_px/tp_pct 作为历史真相，但生效 TP 按最新近24h波动动态重定价，可随波动放宽也可收紧。
    """
    ly = layer if isinstance(layer, dict) else {}
    side_u = str(side or '').upper().strip()
    coin_u = str(coin or '').upper().strip()
    det = {'coin': coin_u, 'side': side_u, 'repriced': False, 'repricing_block_reason': ''}
    try:
        norm_tp_px, norm_tp_pct, norm_changed, norm_det = _m9_normalize_layer_tp(
            ly, coin=coin_u, side=side_u, ref_px=ref_px, fallback_tp_pct=None, tp_min=None, tp_max=None
        )
        det.update({'norm_changed': bool(norm_changed)})
        det.update(dict(norm_det or {}))
        opx = _m9_layer_truth_open_px(ly, None)
        if (opx is None or float(opx) <= 0.0) and ref_px is not None:
            try:
                if float(ref_px) > 0:
                    opx = float(ref_px)
            except Exception:
                opx = None
        if opx is None or float(opx) <= 0.0:
            base_tp_px = _safe_float(ly.get('live_tp_px') or ly.get('tp_px') or norm_tp_px, None)
            base_tp_pct = _safe_float(ly.get('live_tp_pct') or ly.get('tp_pct') or norm_tp_pct, None)
            det['repricing_block_reason'] = 'missing_open_ref_px'
            return base_tp_px, base_tp_pct, bool(norm_changed), det

        base_tp_px = _safe_float(ly.get('tp_px') or norm_tp_px, None)
        base_tp_pct = _safe_float(ly.get('tp_pct') or norm_tp_pct, None)
        orig_tp_px = _safe_float(ly.get('orig_tp_px'), None)
        orig_tp_pct = _safe_float(ly.get('orig_tp_pct'), None)
        changed = bool(norm_changed)
        if orig_tp_px is None and base_tp_px is not None:
            ly['orig_tp_px'] = float(base_tp_px)
            orig_tp_px = float(base_tp_px)
            changed = True
        if orig_tp_pct is None and base_tp_pct is not None:
            ly['orig_tp_pct'] = float(base_tp_pct)
            orig_tp_pct = float(base_tp_pct)
            changed = True
        if 'repricing_enabled' not in ly:
            ly['repricing_enabled'] = True
            changed = True
        if 'repricing_freeze' not in ly:
            ly['repricing_freeze'] = False
            changed = True

        effective_tp_px = _safe_float(ly.get('live_tp_px'), None)
        effective_tp_pct = _safe_float(ly.get('live_tp_pct'), None)
        reprice_block = ''
        if not bool(allow_reprice):
            reprice_block = 'repricing_disabled_by_caller'
        elif not bool(ly.get('repricing_enabled', True)):
            reprice_block = 'repricing_disabled'
        elif bool(ly.get('repricing_freeze')):
            reprice_block = 'repricing_frozen'
        elif bool(ly.get('profit_locked')):
            reprice_block = 'profit_locked'
        elif bool(ly.get('close_pending')) or bool(ly.get('pending_close')) or str(ly.get('status') or '').upper().strip() in ('CLOSE_PENDING', 'PENDING_CLOSE', 'CLOSING', 'CLOSED'):
            reprice_block = 'close_pending_or_closed'

        if not reprice_block:
            step_pct = None
            for _k in ('grid_pct', 'step_pct', 'reentry_step_pct'):
                try:
                    _v = ly.get(_k)
                    if _v is not None and float(_v) > 0:
                        step_pct = float(_v)
                        break
                except Exception:
                    continue
            live_tp_pct_raw, live_det = _grid_live_tp_pct(coin_u, step_pct=step_pct, fallback=base_tp_pct)
            det.update({'live_tp_src': str((live_det or {}).get('src') or ''), 'live_tp_formula': str((live_det or {}).get('formula') or '')})
            candidate_tp_pct = float(live_tp_pct_raw or 0.0)
            if candidate_tp_pct <= 0.0:
                candidate_tp_pct = float(base_tp_pct or orig_tp_pct or _m9_gap_truth_floor_pct(coin_u) or 0.0)
            candidate_tp_pct = max(float(candidate_tp_pct), float(_m9_gap_truth_floor_pct(coin_u)))
            if side_u == 'SHORT':
                candidate_tp_px = float(opx) * (1.0 - float(candidate_tp_pct))
            else:
                candidate_tp_px = float(opx) * (1.0 + float(candidate_tp_pct))
            prev_live_tp_px = _safe_float(ly.get('live_tp_px'), None)
            prev_live_tp_pct = _safe_float(ly.get('live_tp_pct'), None)
            if prev_live_tp_px is None or abs(float(prev_live_tp_px) - float(candidate_tp_px)) > max(1e-9, abs(float(candidate_tp_px)) * 1e-9):
                ly['live_tp_px'] = float(candidate_tp_px)
                changed = True
            if prev_live_tp_pct is None or abs(float(prev_live_tp_pct) - float(candidate_tp_pct)) > 1e-9:
                ly['live_tp_pct'] = float(candidate_tp_pct)
                changed = True
            ly['repricing_last_ts'] = float(time.time())
            ly['repricing_reason'] = 'live_tp_follow_24h_vol'
            effective_tp_px = float(candidate_tp_px)
            effective_tp_pct = float(candidate_tp_pct)
            det['repriced'] = True
        else:
            det['repricing_block_reason'] = str(reprice_block)

        if effective_tp_px is None:
            effective_tp_px = _safe_float(ly.get('live_tp_px') or ly.get('tp_px') or norm_tp_px, None)
        if effective_tp_pct is None:
            effective_tp_pct = _safe_float(ly.get('live_tp_pct') or ly.get('tp_pct') or norm_tp_pct, None)
        if effective_tp_px is not None:
            ly['effective_tp_px'] = float(effective_tp_px)
        if effective_tp_pct is not None:
            ly['effective_tp_pct'] = float(effective_tp_pct)
        det.update({
            'open_ref_px': float(opx),
            'orig_tp_px': orig_tp_px,
            'orig_tp_pct': orig_tp_pct,
            'base_tp_px': base_tp_px,
            'base_tp_pct': base_tp_pct,
            'effective_tp_px': effective_tp_px,
            'effective_tp_pct': effective_tp_pct,
        })
        return effective_tp_px, effective_tp_pct, bool(changed), det
    except Exception as e:
        det.update({'repricing_block_reason': f'repricing_exc:{type(e).__name__}', 'exc': repr(e)})
        return _safe_float((ly or {}).get('live_tp_px') or (ly or {}).get('tp_px'), None), _safe_float((ly or {}).get('live_tp_pct') or (ly or {}).get('tp_pct'), None), False, det

def _m9_layer_mode(layer: dict | None) -> str:
    try:
        ly = dict(layer or {})
        gm = str(ly.get('grid_mode') or ly.get('mode') or '').upper().strip()
        if gm in ('TREND', 'NORMAL'):
            return gm
        if bool(ly.get('is_trend_grid') or ly.get('trend_mode')):
            return 'TREND'
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_871', _e)
        pass
    return 'NORMAL'

def _m9_is_base_layer_id(layer_id: str, layer_obj: dict | None = None) -> bool:
    """[HARD] 爸爸口径：网格模块不管理基础层（L1）。
    - 只要识别为 L1，就禁止做 M9 decrease / close / pending_reconcile / force_tp。
    - 识别规则尽量稳：layer_id 包含 _L1 或以 L1 结尾；或 layer_obj 显式给 layer_no=1；或 tag/note 提示 L1。
    """
    try:
        lid = str(layer_id or '').strip().upper()
    except Exception:
        lid = ''
    if not lid:
        return False
    try:
        if re.search(r'(^|[^A-Z0-9])L1($|[^A-Z0-9])', lid):
            return True
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_872', _e)
        pass
    try:
        if lid.endswith('L1') or ('_L1' in lid) or ('-L1' in lid):
            return True
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_873', _e)
        pass
    try:
        ly = dict(layer_obj or {})
    except Exception:
        ly = {}
    try:
        if int(ly.get('layer_no') or ly.get('no') or 0) == 1:
            return True
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_874', _e)
        pass
    try:
        tag = str(ly.get('layer_tag') or ly.get('tag') or ly.get('name') or '').upper()
        note = str(ly.get('note') or '').upper()
        if 'L1' in tag or 'L1' in note:
            return True
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_875', _e)
        pass
    return False

def _m9_trend_cap_by_rsi(side: str, rsi: float | None) -> int:
    try:
        rv = float(rsi) if rsi is not None else None
    except Exception:
        rv = None
    if rv is None:
        return 0
    s = str(side or '').upper().strip()
    if s == 'LONG':
        if rv >= float(M9_TREND_RSI_STOP_ADD_LONG):
            return 0
        if rv >= 65.0:
            return min(int(M9_TREND_MAX_LAYERS), 3)
        if rv >= 60.0:
            return min(int(M9_TREND_MAX_LAYERS), 2)
        if rv >= float(M9_TREND_RSI_LONG_MIN):
            return min(int(M9_TREND_MAX_LAYERS), 1)
        return 0
    if s == 'SHORT':
        if rv <= float(M9_TREND_RSI_STOP_ADD_SHORT):
            return 0
        if rv <= 35.0:
            return min(int(M9_TREND_MAX_LAYERS), 3)
        if rv <= 40.0:
            return min(int(M9_TREND_MAX_LAYERS), 2)
        if rv <= float(M9_TREND_RSI_SHORT_MAX):
            return min(int(M9_TREND_MAX_LAYERS), 1)
        return 0
    return 0

def _m9_count_open_layers_by_mode(grid_id: str, mode: str = 'TREND') -> int:
    try:
        if ('GRID_BOOK' not in globals()) or (globals().get('GRID_BOOK') is None):
            return 0
        ols = GRID_BOOK.get_open_layers(str(grid_id)) or []
        mu = str(mode or '').upper().strip()
        return int(sum(1 for ly in (ols or []) if _m9_layer_mode(ly) == mu))
    except Exception:
        return 0

def _m9_last_open_layer_by_mode(grid_id: str, mode: str = 'TREND') -> dict | None:
    try:
        if ('GRID_BOOK' not in globals()) or (globals().get('GRID_BOOK') is None):
            return None
        mu = str(mode or '').upper().strip()
        ols = GRID_BOOK.get_open_layers(str(grid_id)) or []
        hit = [ly for ly in (ols or []) if _m9_layer_mode(ly) == mu]
        return (hit[-1] if hit else None)
    except Exception:
        return None

def _m9_coin_side_state(snapshot: dict | None, coin: str) -> dict:
    out = {
        'LONG': {'notional_u': 0.0, 'upnl_u': 0.0, 'legs': 0, 'platforms': []},
        'SHORT': {'notional_u': 0.0, 'upnl_u': 0.0, 'legs': 0, 'platforms': []},
    }
    try:
        c = str(coin or '').upper().strip()
        if not c:
            return out
        for plat in ('EXT', 'VAR'):
            try:
                pos = _get_position(snapshot or {}, c, plat) or {}
            except Exception:
                pos = {}
            side = str((pos or {}).get('side') or '').upper().strip()
            if side not in ('LONG', 'SHORT'):
                continue
            try:
                notional_u = float(abs(float((pos or {}).get('notional_u') or 0.0)))
            except Exception:
                notional_u = 0.0
            if notional_u <= 1e-9:
                continue
            try:
                upnl_u = float((pos or {}).get('upnl_u') or 0.0)
            except Exception:
                upnl_u = 0.0
            node = out.get(side) or {}
            node['notional_u'] = float(node.get('notional_u') or 0.0) + float(notional_u)
            node['upnl_u'] = float(node.get('upnl_u') or 0.0) + float(upnl_u)
            node['legs'] = int(node.get('legs') or 0) + 1
            plats = list(node.get('platforms') or [])
            plats.append(str(plat))
            node['platforms'] = plats
            out[side] = node
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_876', _e)
        pass
    return out

def _m9_trend_side_from_signal(rsi: float | None, adx: float | None) -> str:
    """M9 趋势方向只看 RSI，不再受 ADX 阈值限制。"""
    try:
        rv = float(rsi) if rsi is not None else None
    except Exception:
        rv = None
    if rv is None:
        return ''
    if rv >= float(M9_TREND_RSI_LONG_MIN):
        return 'LONG'
    if rv <= float(M9_TREND_RSI_SHORT_MAX):
        return 'SHORT'
    return ''

def _m9_trend_side_for_coin(coin: str, rsi: float | None, adx: float | None) -> str:
    """趋势方向滞回：进入用强阈值，退出用宽阈值，避免 55.9/56.1 这类边缘抖动。
    你的最新要求：M9 趋势判断只看 RSI，不再受 ADX 阈值限制。
    """
    try:
        c = str(coin or '').upper().strip()
        rv = float(rsi) if rsi is not None else None
    except Exception:
        c, rv = '', None
    prev = str((_M9_TREND_SIDE_MEMORY or {}).get(c) or '').upper().strip()
    if rv is None:
        if c:
            _M9_TREND_SIDE_MEMORY[c] = ''
        return ''
    side = ''
    if prev == 'LONG':
        side = 'LONG' if rv >= float(M9_TREND_RSI_LONG_EXIT) else ''
    elif prev == 'SHORT':
        side = 'SHORT' if rv <= float(M9_TREND_RSI_SHORT_EXIT) else ''
    else:
        side = _m9_trend_side_from_signal(rv, adx)
    if not side:
        if rv >= float(M9_TREND_RSI_LONG_MIN):
            side = 'LONG'
        elif rv <= float(M9_TREND_RSI_SHORT_MAX):
            side = 'SHORT'
    if c:
        _M9_TREND_SIDE_MEMORY[c] = str(side or '')
    return str(side or '')

def _m9_trend_add_gap_pct(base_gap_pct: float | None, opened_trend_layers: int = 0) -> float:
    try:
        bg = float(base_gap_pct if base_gap_pct is not None else GRID_CONSERVATIVE_MIN_PCT)
    except Exception:
        bg = float(GRID_CONSERVATIVE_MIN_PCT)
    try:
        od = max(0, int(opened_trend_layers or 0))
    except Exception:
        od = 0
    floor = float(M9_TREND_ADD_BASE_PCT) + float(od) * float(M9_TREND_ADD_STEP_PCT)
    step = max(float(bg), float(floor), float(GRID_CONSERVATIVE_MIN_PCT))
    cap = max(float(M9_TREND_ADD_MAX_PCT), float(GRID_CONSERVATIVE_MIN_PCT))
    return float(min(float(step), float(cap)))

def _m9_calc_next_buy_gate(coin: str, grid_id: str, side: str, cur_px: float | None, open_layers: list | None, rsi: float | None = None, adx: float | None = None, snapshot: dict | None = None):
    """复用真实 M9 increase gate，给 observe/panel 计算和主链一致的 next_buy/need_px。"""
    try:
        if cur_px is None or float(cur_px) <= 0 or str(side).upper() not in ('LONG', 'SHORT'):
            return None, None, {}
        side_u = str(side).upper()
        gid = str(grid_id or '')
        real_ols = []
        for ly in list(open_layers or []):
            if not isinstance(ly, dict):
                continue
            if str(ly.get('status') or 'OPEN').upper() != 'OPEN':
                continue
            if str(ly.get('mode') or '').upper() == 'RECOVER':
                continue
            real_ols.append(ly)
        last_real_layer = real_ols[-1] if real_ols else None
        grid_mode, trend_det = _m9_pick_grid_mode(side_u, rsi, adx, gid, snapshot=snapshot, coin=coin)
        trend_opened = int((trend_det or {}).get('opened') or 0)
        gap_truth_pct = _m9_extract_gap_truth_pct(last_real_layer, None)
        gap_det2 = {'source': 'last_real_layer_gap_truth' if gap_truth_pct is not None else 'missing_last_real_layer_gap_truth'}
        if gap_truth_pct is None:
            gap_truth_pct = _m9_gap_truth_floor_pct(coin)
            gap_det2['source'] = 'gap_truth_floor'
        gate_gap_pct = float(max(_m9_gap_truth_floor_pct(coin), gap_truth_pct))
        is_first_real_m9_layer = not isinstance(last_real_layer, dict)
        gate_layer = None if is_first_real_m9_layer else last_real_layer
        if not isinstance(gate_layer, dict):
            return None, None, {'mode': str(grid_mode), 'gap_pct': float(gate_gap_pct), 'reason': 'first_real_layer_gap_bypass' if is_first_real_m9_layer else 'no_gate_layer', 'is_first_real_m9_layer': int(is_first_real_m9_layer), 'gap_source': str(gap_det2.get('source') or '')}
        lp = _m9_layer_truth_open_px(gate_layer, None)
        if lp is None or float(lp) <= 0:
            return None, None, {'mode': str(grid_mode), 'gap_pct': float(gate_gap_pct), 'reason': 'gate_layer_px_missing', 'gap_source': str(gap_det2.get('source') or '')}
        hi_gap = _safe_float((gap_det2 or {}).get('hi'), None)
        if hi_gap is None or float(hi_gap) <= 0:
            hi_gap = float(M9_GAP_CAP)
        hi_cap = float(M9_GAP_CAP)
        hi_gap = min(float(hi_cap), max(float(gate_gap_pct), float(hi_gap)))
        if side_u == 'LONG':
            need_px = float(lp) * (1.0 - float(gate_gap_pct))
            need_hi_px = float(lp) * (1.0 - float(hi_gap))
            px_range = f"[{need_hi_px:.6f}, {need_px:.6f}]"
        else:
            need_px = float(lp) * (1.0 + float(gate_gap_pct))
            need_hi_px = float(lp) * (1.0 + float(hi_gap))
            px_range = f"[{need_px:.6f}, {need_hi_px:.6f}]"
        return float(need_px), px_range, {
            'mode': str(grid_mode),
            'gap_pct': float(gate_gap_pct),
            'hi_gap_pct': float(hi_gap),
            'last_px': float(lp),
            'trend_opened': int(trend_opened),
            'gap_source': str(gap_det2.get('source') or ''),
        }
    except Exception as _e:
        try:
            _log_exc(mod='SYS', stage='EXC_PASS', e=_e)
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_877', _e)
            pass
        return None, None, {'reason': f'next_buy_gate_exc:{type(_e).__name__}'}

_TREND_UPNL_HISTORY: Dict[str, List[float]] = {}

def _trend_alpha_slot_limit(side: str) -> int:
    s = str(side or '').upper().strip()
    if s == 'LONG':
        return max(1, min(int(TREND_ALPHA_MAIN_SLOTS_LONG), int(TREND_ALPHA_MAIN_SLOTS_LONG_MAX)))
    if s == 'SHORT':
        return max(1, min(int(TREND_ALPHA_MAIN_SLOTS_SHORT), int(TREND_ALPHA_MAIN_SLOTS_SHORT_MAX)))
    return 1

def _trend_upnl_history_push(coin: str, same_upnl: float) -> List[float]:
    c = str(coin or '').upper().strip()
    val = float(same_upnl or 0.0)
    hist = list((_TREND_UPNL_HISTORY or {}).get(c) or [])
    if (not hist) or abs(float(hist[-1]) - val) > 1e-9:
        hist.append(val)
    hist = hist[-4:]
    _TREND_UPNL_HISTORY[c] = list(hist)
    return hist


SINGLE_LEG_B2_MIN_PROFIT_U = float(globals().get("SINGLE_LEG_B2_MIN_PROFIT_U", 20.0) or 20.0)
SINGLE_LEG_B2_STALE_HIGH_HOURS = float(globals().get("SINGLE_LEG_B2_STALE_HIGH_HOURS", 5.0) or 5.0)
_SINGLE_LEG_B2_STALE_TRACK: Dict[str, Dict[str, Any]] = {}

def _single_leg_b2_need_profit_u(coin: str | None = None) -> float:
    return float(max(0.0, float(SINGLE_LEG_B2_MIN_PROFIT_U or 20.0)))

def _single_leg_b2_stale_high_gate(snapshot: dict | None, coin: str, platform: str, pos: dict | None, *, now_ts_s: float | None = None) -> dict:
    """单腿 B2 唯一口径：盈利>20U，且连续5小时未创新高，才允许平仓。"""
    c = str(coin or '').upper().strip()
    plat = str(platform or '').upper().strip()
    p = dict(pos or {}) if isinstance(pos, dict) else {}
    side = str(_pos_side(p) or '').upper().strip()
    try:
        notional_u = float(_a1_pos_notional_u(p) or 0.0)
    except Exception:
        notional_u = 0.0
    try:
        upnl_u = float(_a1_pos_upnl_u(p) or 0.0)
    except Exception:
        upnl_u = 0.0
    try:
        snap_ts = float((snapshot or {}).get('ts') or 0.0) if isinstance(snapshot, dict) else 0.0
    except Exception:
        snap_ts = 0.0
    now_ts = float(now_ts_s if now_ts_s is not None else (snap_ts if snap_ts > 0.0 else time.time()))
    min_profit_u = float(_single_leg_b2_need_profit_u(c))
    stale_need_sec = float(max(0.0, float(SINGLE_LEG_B2_STALE_HIGH_HOURS or 5.0)) * 3600.0)
    out = {
        'coin': c, 'platform': plat, 'side': side, 'notional_u': float(notional_u), 'upnl_u': float(upnl_u),
        'min_profit_u': float(min_profit_u), 'stale_need_sec': float(stale_need_sec), 'allow': False,
        'reason': 'single_leg_b2_profit_lt_20u', 'high_upnl_u': float(upnl_u), 'last_high_ts': float(now_ts),
        'stale_sec': 0.0, 'track_key': '',
    }
    if (not c) or plat not in ('EXT', 'VAR') or (not side) or notional_u <= 0.0:
        out['reason'] = 'single_leg_b2_structure_invalid'
        return out
    prefix = f"{c}|"
    key = f"{c}|{plat}|{side}"
    out['track_key'] = key
    try:
        for _k in list((_SINGLE_LEG_B2_STALE_TRACK or {}).keys()):
            if str(_k).startswith(prefix) and str(_k) != key:
                _SINGLE_LEG_B2_STALE_TRACK.pop(_k, None)
    except Exception:
        pass
    rec = dict((_SINGLE_LEG_B2_STALE_TRACK or {}).get(key) or {})
    high_upnl_u = float(rec.get('high_upnl_u') or upnl_u)
    last_high_ts = float(rec.get('last_high_ts') or now_ts)
    if ('high_upnl_u' not in rec) or (upnl_u > high_upnl_u + 1e-9):
        high_upnl_u = float(upnl_u)
        last_high_ts = float(now_ts)
    stale_sec = max(0.0, float(now_ts) - float(last_high_ts))
    rec.update({
        'coin': c, 'platform': plat, 'side': side, 'notional_u': float(notional_u), 'upnl_u': float(upnl_u),
        'high_upnl_u': float(high_upnl_u), 'last_high_ts': float(last_high_ts), 'last_seen_ts': float(now_ts),
        'min_profit_u': float(min_profit_u), 'stale_need_sec': float(stale_need_sec),
    })
    _SINGLE_LEG_B2_STALE_TRACK[key] = rec
    out.update({'high_upnl_u': float(high_upnl_u), 'last_high_ts': float(last_high_ts), 'stale_sec': float(stale_sec)})
    if upnl_u <= float(min_profit_u) + 1e-9:
        out['reason'] = 'single_leg_b2_profit_lt_20u'
        return out
    if stale_sec + 1e-9 < stale_need_sec:
        out['reason'] = 'single_leg_b2_wait_stale_high_5h'
        return out
    out['allow'] = True
    out['reason'] = 'single_leg_b2_stale_high_ready'
    return out

def _trend_profit_streak_flags(hist: List[float] | None) -> dict:
    vals = [float(x or 0.0) for x in list(hist or [])]
    if not vals:
        return {'expansion_ok': False, 'contraction_ok': False, 'early_profit_ok': False, 'len': 0}
    if len(vals) < 2:
        last_v = float(vals[-1] or 0.0)
        return {'expansion_ok': False, 'contraction_ok': False, 'early_profit_ok': bool(last_v > 0.0), 'len': len(vals)}
    tail2 = vals[-2:]
    early_profit_ok = bool(tail2[-1] > 0.0 and tail2[-1] >= tail2[0] - 1e-9)
    if len(vals) < 3:
        return {'expansion_ok': False, 'contraction_ok': False, 'early_profit_ok': early_profit_ok, 'len': len(vals)}
    tail = vals[-3:]
    expansion_ok = bool(tail[-1] > tail[0] + 1e-9 and tail[-1] >= tail[-2] - 1e-9)
    contraction_ok = bool(tail[-1] < tail[0] - 1e-9 and tail[-1] <= tail[-2] + 1e-9)
    return {'expansion_ok': expansion_ok, 'contraction_ok': contraction_ok, 'early_profit_ok': early_profit_ok, 'len': len(vals)}

def _trend_strength_bucket(rsi: float | None, same_upnl: float, same_notional: float, opp_upnl: float) -> str:
    try:
        rv = float(rsi) if rsi is not None else 50.0
    except Exception:
        rv = 50.0
    try:
        profit_pct = (float(same_upnl) / max(float(same_notional), 1e-9)) if float(same_notional) > 1e-9 else 0.0
    except Exception:
        profit_pct = 0.0
    dist = abs(float(rv) - 50.0)
    if dist >= 12.0 and profit_pct >= 0.010 and float(opp_upnl or 0.0) <= 0.0:
        return 'STRONG'
    if dist >= 8.0 and profit_pct >= 0.004:
        return 'MEDIUM'
    return 'WEAK'

def _trend_dynamic_partial_ratios(rsi: float | None, same_upnl: float, same_notional: float, opp_upnl: float) -> dict:
    bucket = _trend_strength_bucket(rsi, same_upnl, same_notional, opp_upnl)
    if bucket == 'STRONG':
        p1 = float(M9_TREND_PARTIAL1_RATIO_STRONG)
        p2 = float(M9_TREND_PARTIAL2_RATIO_STRONG)
    elif bucket == 'WEAK':
        p1 = float(M9_TREND_PARTIAL1_RATIO_WEAK)
        p2 = float(M9_TREND_PARTIAL2_RATIO_WEAK)
    else:
        p1 = float(M9_TREND_PARTIAL1_RATIO)
        p2 = float(M9_TREND_PARTIAL2_RATIO)
    return {'bucket': bucket, 'partial1_ratio': p1, 'partial2_ratio': p2, 'runner_ratio': max(0.0, 1.0 - p1 - p2)}

def _trend_alpha_score_for_coin(snapshot: dict | None, coin: str, trend_side: str, rsi: float | None = None) -> float:
    try:
        c = str(coin or '').upper().strip()
        ts = str(trend_side or '').upper().strip()
        if ts not in ('LONG', 'SHORT'):
            return 0.0
        state = _m9_coin_side_state(snapshot, c)
        same = dict((state or {}).get(ts) or {})
        opp = dict((state or {}).get('SHORT' if ts == 'LONG' else 'LONG') or {})
        same_n = float(same.get('notional_u') or 0.0)
        same_u = float(same.get('upnl_u') or 0.0)
        opp_u = float(opp.get('upnl_u') or 0.0)
        rv = float(rsi) if rsi is not None else None
        if rv is None:
            _adx, rv = _a1_get_adx_rsi(snapshot or {}, c)
        dist = abs(float(rv or 50.0) - 50.0)
        profit_pct = (same_u / max(same_n, 1e-9)) if same_n > 1e-9 else 0.0
        opp_drag = max(0.0, -float(opp_u or 0.0))
        return float(dist * 1.2 + profit_pct * 1200.0 + max(0.0, same_u) * 0.2 + opp_drag * 0.05)
    except Exception:
        return 0.0

def _trend_alpha_slot_winner(snapshot: dict | None, coin: str, trend_side: str, rsi: float | None = None) -> tuple[bool, dict]:
    rep = {'rank': 999, 'slots': 1, 'score': 0.0, 'leaders': []}
    try:
        c = str(coin or '').upper().strip()
        ts = str(trend_side or '').upper().strip()
        slots = _trend_alpha_slot_limit(ts)
        rep['slots'] = int(slots)
        if ts not in ('LONG', 'SHORT') or not isinstance(snapshot, dict):
            return True, rep
        coins = set()
        for plat in ('EXT', 'VAR'):
            mp = snapshot.get('positions', {}).get(plat, {}) if isinstance(snapshot.get('positions', {}), dict) else {}
            if isinstance(mp, dict):
                coins.update(str(k or '').upper().strip() for k in mp.keys())
        coins.add(c)
        rows = []
        for cc in list(coins):
            if not cc:
                continue
            _adx_cc, rsi_cc = _a1_get_adx_rsi(snapshot or {}, cc)
            if _m9_trend_side_for_coin(cc, rsi_cc, _adx_cc) != ts:
                continue
            score = _trend_alpha_score_for_coin(snapshot, cc, ts, rsi=rsi_cc)
            rows.append((cc, float(score)))
        rows = sorted(rows, key=lambda x: x[1], reverse=True)
        rep['leaders'] = [x[0] for x in rows[:max(3, slots)]]
        for i, (cc, score) in enumerate(rows, start=1):
            if cc == c:
                rep['rank'] = int(i)
                rep['score'] = float(score)
                break
        return bool(rep['rank'] <= slots), rep
    except Exception:
        return True, rep

def _m9_resolve_trend_state(snapshot: dict | None, coin: str, trend_side: str, rsi: float | None = None) -> dict:
    out = {
        'trend_state': 'NORMAL',
        'trend_alpha': 0,
        'opp_side_frozen': 0,
        'runner_protect': 0,
        'reason': 'trend_neutral',
        'same_notional_u': 0.0,
        'opp_notional_u': 0.0,
        'same_upnl_u': 0.0,
        'opp_upnl_u': 0.0,
        'cover_ratio': None,
        'profit_history': [],
        'profit_expansion_ok': False,
        'profit_contraction_ok': False,
        'trend_strength_bucket': 'WEAK',
        'trend_score': 0.0,
        'trend_rank': 999,
        'trend_slots': 1,
    }
    try:
        ts = str(trend_side or '').upper().strip()
        if ts not in ('LONG', 'SHORT'):
            return out
        state = _m9_coin_side_state(snapshot, coin)
        same = dict((state or {}).get(ts) or {})
        opp_side = 'SHORT' if ts == 'LONG' else 'LONG'
        opp = dict((state or {}).get(opp_side) or {})
        same_notional = float(same.get('notional_u') or 0.0)
        opp_notional = float(opp.get('notional_u') or 0.0)
        same_upnl = float(same.get('upnl_u') or 0.0)
        opp_upnl = float(opp.get('upnl_u') or 0.0)
        out.update({
            'same_notional_u': float(same_notional),
            'opp_notional_u': float(opp_notional),
            'same_upnl_u': float(same_upnl),
            'opp_upnl_u': float(opp_upnl),
        })
        if opp_notional > 1e-9:
            out['cover_ratio'] = float(same_notional / max(opp_notional, 1e-12))
        elif same_notional > 1e-9:
            out['cover_ratio'] = 999.0
        else:
            out['cover_ratio'] = 0.0
        hist = _trend_upnl_history_push(str(coin or '').upper().strip(), same_upnl)
        streak = _trend_profit_streak_flags(hist)
        out['profit_history'] = list(hist)
        out['profit_expansion_ok'] = bool(streak.get('expansion_ok'))
        out['profit_contraction_ok'] = bool(streak.get('contraction_ok'))
        out['trend_strength_bucket'] = _trend_strength_bucket(rsi, same_upnl, same_notional, opp_upnl)
        if same_notional <= 1e-9:
            out['trend_state'] = 'TREND_CANDIDATE'
            out['reason'] = 'trend_candidate_same_leg_missing'
            return out
        weak_rsi = False
        try:
            if rsi is not None:
                rv = float(rsi)
                if ts == 'LONG':
                    weak_rsi = bool(rv <= float(M9_TREND_RSI_LONG_EXIT))
                else:
                    weak_rsi = bool(rv >= float(M9_TREND_RSI_SHORT_EXIT))
        except Exception:
            weak_rsi = False
        min_same_upnl = max(3.0, float(same_notional) * 0.003)
        if weak_rsi and bool(streak.get('contraction_ok')):
            out['trend_state'] = 'TREND_EXIT_ONLY'
            out['opp_side_frozen'] = 1
            out['runner_protect'] = 1
            out['reason'] = 'trend_exit_only_no_new_grid'
            return out
        alpha_candidate = bool(same_upnl > min_same_upnl and (opp_notional <= 1e-9 or opp_upnl <= 0.0) and bool(streak.get('expansion_ok')) and (not weak_rsi))
        if alpha_candidate:
            slot_ok, slot_det = _trend_alpha_slot_winner(snapshot, coin, ts, rsi=rsi)
            out['trend_score'] = float(slot_det.get('score') or 0.0)
            out['trend_rank'] = int(slot_det.get('rank') or 999)
            out['trend_slots'] = int(slot_det.get('slots') or 1)
            if bool(slot_ok):
                out['trend_state'] = 'TREND_ALPHA'
                out['trend_alpha'] = 1
                out['opp_side_frozen'] = 1
                out['runner_protect'] = 1
                out['reason'] = 'trend_alpha_allow_same_side_expand'
                return out
            out['trend_state'] = 'TREND_CANDIDATE'
            out['reason'] = 'trend_candidate_slot_competition'
            return out
        if same_upnl > 0.0:
            out['trend_state'] = 'TREND_CANDIDATE'
            out['reason'] = 'trend_candidate_profit_seen'
            return out
        out['trend_state'] = 'TREND_CANDIDATE'
        out['reason'] = 'trend_candidate_wait_profit_confirm'
        return out
    except Exception as _e:
        out['reason'] = f'trend_state_exc:{type(_e).__name__}'
        return out

def _m9_trend_open_policy(snapshot: dict | None, coin: str, side: str, rsi: float | None, adx: float | None) -> dict:
    out = {
        'allow': True,
        'block_new_grid': 0,
        'reason': 'trend_neutral',
        'trend_reason': 'trend_neutral',
        'trend_side': '',
        'same_notional_u': 0.0,
        'opp_notional_u': 0.0,
        'same_upnl_u': 0.0,
        'opp_upnl_u': 0.0,
        'cover_ratio': None,
        'trend_layers_open': 0,
        'trend_layers_cap': 0,
        'freeze_loss_leg_new_grid': 0,
        'trend_policy_block_new_grid': 0,
        'trend_state': 'NORMAL',
        'trend_alpha': 0,
        'opp_side_frozen': 0,
        'runner_protect': 0,
    }
    def _ret() -> dict:
        out['trend_reason'] = str(out.get('reason') or 'trend_neutral')
        out['trend_policy_block_new_grid'] = int(bool(out.get('block_new_grid', 0)))
        try:
            _trend_field_selfcheck(str(coin or '').upper().strip(), '', out)
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_878', _e)
            pass
        return out
    try:
        s = str(side or '').upper().strip()
        trend_side = _m9_trend_side_for_coin(coin, rsi, adx)
        out['trend_side'] = str(trend_side)
        if trend_side not in ('LONG', 'SHORT'):
            out['reason'] = 'trend_neutral'
            return _ret()
        st = _m9_resolve_trend_state(snapshot, coin, trend_side, rsi=rsi) or {}
        out.update({
            'trend_state': str(st.get('trend_state') or 'TREND_CANDIDATE'),
            'trend_alpha': int(bool(st.get('trend_alpha', 0))),
            'opp_side_frozen': int(bool(st.get('opp_side_frozen', 0))),
            'runner_protect': int(bool(st.get('runner_protect', 0))),
            'same_notional_u': float(st.get('same_notional_u') or 0.0),
            'opp_notional_u': float(st.get('opp_notional_u') or 0.0),
            'same_upnl_u': float(st.get('same_upnl_u') or 0.0),
            'opp_upnl_u': float(st.get('opp_upnl_u') or 0.0),
            'cover_ratio': st.get('cover_ratio'),
        })
        if s != trend_side and bool(out.get('trend_alpha')):
            out['allow'] = False
            out['block_new_grid'] = 1
            out['freeze_loss_leg_new_grid'] = 1
            out['trend_policy_block_new_grid'] = 1
            out['reason'] = 'opposite_side_frozen_in_trend_alpha'
            return _ret()
        if s != trend_side:
            out['reason'] = 'trend_side_not_match'
            return _ret()
        cover_ratio = float(out.get('cover_ratio') or 0.0)
        opp_notional = float(out.get('opp_notional_u') or 0.0)
        if bool(out.get('trend_alpha')):
            out['allow'] = True
            out['block_new_grid'] = 0
            out['freeze_loss_leg_new_grid'] = 0
            out['reason'] = 'trend_alpha_allow_same_side_expand'
            return _ret()
        if opp_notional > 1e-9 and cover_ratio >= float(M9_TREND_COVER_RATIO_TARGET) - 1e-12:
            out['allow'] = True
            out['block_new_grid'] = 0
            out['reason'] = 'trend_cover_ratio_disabled'
        elif opp_notional > 1e-9 and cover_ratio >= float(M9_TREND_COVER_RATIO_SOFT) - 1e-12:
            out['allow'] = True
            out['block_new_grid'] = 0
            out['reason'] = 'trend_cover_soft_zone_disabled'
        else:
            out['reason'] = str(st.get('reason') or 'trend_cover_expand')
        return _ret()
    except Exception as e:
        out['allow'] = True
        out['block_new_grid'] = 0
        out['reason'] = f'trend_policy_exc:{type(e).__name__}'
        return _ret()

def _m9_payload_trend_view(snapshot: dict | None, coin: str, platform: str, rsi: float | None, adx: float | None) -> dict:
    out = {
        'trend_side': '',
        'trend_reason': 'trend_neutral',
        'cover_ratio': None,
        'same_notional_u': 0.0,
        'opp_notional_u': 0.0,
        'same_upnl_u': 0.0,
        'opp_upnl_u': 0.0,
        'long_notional_u': 0.0,
        'short_notional_u': 0.0,
        'long_upnl_u': 0.0,
        'short_upnl_u': 0.0,
        'trend_grid_id': '',
        'trend_layers_open': 0,
        'trend_layers_cap': 0,
        'freeze_loss_leg_new_grid': 0,
        'trend_policy_allow': 1,
        'trend_policy_block_new_grid': 0,
        'trend_state': 'NORMAL',
        'trend_alpha': 0,
        'opp_side_frozen': 0,
        'runner_protect': 0,
    }
    try:
        c = str(coin or '').upper().strip()
        p = str(platform or '').upper().strip()
        if not c or p not in ('EXT', 'VAR'):
            return out
        trend_side = _m9_trend_side_for_coin(coin, rsi, adx)
        out['trend_side'] = str(trend_side or '')
        state = _m9_coin_side_state(snapshot, c)
        long_state = dict((state or {}).get('LONG') or {})
        short_state = dict((state or {}).get('SHORT') or {})
        out['long_notional_u'] = float(long_state.get('notional_u') or 0.0)
        out['short_notional_u'] = float(short_state.get('notional_u') or 0.0)
        out['long_upnl_u'] = float(long_state.get('upnl_u') or 0.0)
        out['short_upnl_u'] = float(short_state.get('upnl_u') or 0.0)
        if trend_side in ('LONG', 'SHORT'):
            pol = _m9_trend_open_policy(snapshot, c, trend_side, rsi, adx) or {}
            out['trend_reason'] = str(pol.get('reason') or out['trend_reason'])
            out['cover_ratio'] = (float(pol.get('cover_ratio')) if pol.get('cover_ratio') is not None else None)
            out['same_notional_u'] = float(pol.get('same_notional_u') or 0.0)
            out['opp_notional_u'] = float(pol.get('opp_notional_u') or 0.0)
            out['same_upnl_u'] = float(pol.get('same_upnl_u') or 0.0)
            out['opp_upnl_u'] = float(pol.get('opp_upnl_u') or 0.0)
            out['trend_policy_allow'] = int(bool(pol.get('allow', True)))
            out['trend_policy_block_new_grid'] = int(bool(pol.get('block_new_grid', 0)))
            out['trend_state'] = str(pol.get('trend_state') or 'TREND_CANDIDATE')
            out['trend_alpha'] = int(bool(pol.get('trend_alpha', 0)))
            out['opp_side_frozen'] = int(bool(pol.get('opp_side_frozen', 0)))
            out['runner_protect'] = int(bool(pol.get('runner_protect', 0)))
            side_for_plat = ''
            try:
                pos = _get_position(snapshot or {}, c, p) or {}
                side_for_plat = str((pos or {}).get('side') or '').upper().strip()
            except Exception:
                side_for_plat = ''
            if side_for_plat in ('LONG', 'SHORT'):
                pol_cur = _m9_trend_open_policy(snapshot, c, side_for_plat, rsi, adx) or {}
                out['freeze_loss_leg_new_grid'] = int(bool(pol_cur.get('freeze_loss_leg_new_grid', 0)))
                if bool(pol_cur.get('block_new_grid', 0)):
                    out['trend_policy_block_new_grid'] = 1
                    out['trend_reason'] = str(pol_cur.get('reason') or out['trend_reason'])
            gid = _m9_grid_id(c, p, trend_side)
            out['trend_grid_id'] = str(gid or '')
            if gid:
                out['trend_layers_open'] = int(_m9_count_open_layers_by_mode(str(gid), 'TREND'))
            try:
                out['trend_layers_cap'] = int(_m9_trend_cap_by_rsi(str(trend_side), float(rsi) if rsi is not None else None))
            except Exception:
                out['trend_layers_cap'] = 0
        _trend_field_selfcheck(c, p, out)
        return out
    except Exception as e:
        out['trend_reason'] = f'trend_view_exc:{type(e).__name__}'
        return out

def _m9_est_same_leg_profit_buffer_u(positions: list | None, coin: str, platform: str, side: str, cur_px: float | None) -> tuple[float, dict]:
    det = {'coin': str(coin or '').upper().strip(), 'platform': str(platform or '').upper().strip(), 'side': str(side or '').upper().strip()}
    try:
        c = str(coin or '').upper().strip()
        p = str(platform or '').upper().strip()
        s = str(side or '').upper().strip()
        px = float(cur_px or 0.0)
        if not c or p not in ('EXT', 'VAR') or s not in ('LONG', 'SHORT') or px <= 0.0:
            det['reason'] = 'bad_input'
            return 0.0, det
        row = None
        for pos in list(positions or []):
            try:
                if str(getattr(pos, 'coin', '') or '').upper().strip() != c:
                    continue
                if str(getattr(pos, 'platform', '') or '').upper().strip() != p:
                    continue
                if str(getattr(pos, 'side', '') or '').upper().strip() != s:
                    continue
                row = pos
                break
            except Exception:
                continue
        if row is None:
            det['reason'] = 'same_leg_missing'
            return 0.0, det
        entry_px = float(getattr(row, 'entry_px', 0.0) or 0.0)
        notional_u = float(getattr(row, 'notional_u', 0.0) or 0.0)
        if entry_px <= 0.0 or notional_u <= 0.0:
            det['reason'] = 'bad_entry_or_notional'
            det['entry_px'] = float(entry_px)
            det['notional_u'] = float(notional_u)
            return 0.0, det
        if s == 'LONG':
            upnl_u = float(notional_u) * (float(px) - float(entry_px)) / float(entry_px)
        else:
            upnl_u = -float(notional_u) * (float(px) - float(entry_px)) / float(entry_px)
        det.update({'entry_px': float(entry_px), 'notional_u': float(notional_u), 'upnl_u': float(upnl_u)})
        return float(upnl_u), det
    except Exception as _e:
        det['reason'] = f'profit_buffer_exc:{type(_e).__name__}'
        return 0.0, det

def _m9_trend_breakout_eval(coin: str, market, positions: list | None, request_leg: str, amount_u: float, grid_mode: str, trend_det: dict | None = None) -> dict:
    out = {
        'allow': False,
        'reason': 'trend_breakout_disabled',
        'grid_mode': str(grid_mode or 'NORMAL').upper().strip(),
        'breakout_amount_u': float(amount_u or 0.0),
        'amount_mult': 1.0,
        'breakout_need_px': None,
        'breakout_ref_px': None,
        'breakout_buffer_pct': float(M9_TREND_BREAKOUT_BUFFER_PCT),
        'profit_buffer_need_u': 0.0,
        'profit_buffer_u': 0.0,
        'profit_buffer_ok': False,
        'm10_blocked': False,
        'recent_close_path_ok': False,
        'breakout_px_ok': False,
    }
    try:
        if not bool(M9_TREND_BREAKOUT_ENABLE):
            out['reason'] = 'trend_breakout_disabled'
            return out
        gm = str(grid_mode or '').upper().strip()
        if gm != 'TREND':
            out['reason'] = 'grid_mode_not_trend'
            return out
        leg = str(request_leg or '').strip()
        if '|' not in leg:
            out['reason'] = 'request_leg_missing'
            return out
        plat, side = leg.split('|', 1)
        plat = str(plat or '').upper().strip()
        side = str(side or '').upper().strip()
        if plat not in ('EXT', 'VAR') or side not in ('LONG', 'SHORT'):
            out['reason'] = 'bad_request_leg'
            return out
        cur_px = float(getattr(market, 'mark_px', 0.0) or 0.0)
        rsi = _safe_float(getattr(market, 'rsi', None), None)
        if cur_px <= 0.0 or rsi is None:
            out['reason'] = 'bad_cur_px_or_rsi'
            return out
        if side == 'LONG' and float(rsi) + 1e-9 < float(M9_TREND_BREAKOUT_RSI_LONG_MIN):
            out['reason'] = 'trend_breakout_rsi_not_strong'
            return out
        if side == 'SHORT' and float(rsi) - 1e-9 > float(M9_TREND_BREAKOUT_RSI_SHORT_MAX):
            out['reason'] = 'trend_breakout_rsi_not_strong'
            return out
        block = None
        try:
            block = _m10_get_block(str(coin), plat, side, phase='gate')
        except Exception:
            block = None
        if isinstance(block, dict):
            try:
                _age = max(0.0, float(time.time()) - float(block.get('ts') or 0.0))
            except Exception:
                _age = 0.0
            if _age <= float(M9_TREND_BREAKOUT_AFTER_M10_BLOCK_SEC):
                out['m10_blocked'] = True
                out['reason'] = 'trend_breakout_wait_m10_cooldown'
                out['m10_block_age_sec'] = float(_age)
                out['m10_block_round_id'] = str(block.get('round_id') or '')
                return out
        lookback = max(3, int(M9_TREND_BREAKOUT_LOOKBACK or 3))
        candles = [x for x in list(getattr(market, 'candles', []) or []) if x is not None]
        if len(candles) < lookback:
            out['reason'] = 'trend_breakout_candles_not_enough'
            out['candles_cnt'] = int(len(candles))
            return out
        seg = candles[-lookback:]
        closes = [float(getattr(x, 'close', 0.0) or 0.0) for x in seg]
        highs = [float(getattr(x, 'high', 0.0) or 0.0) for x in seg]
        lows = [float(getattr(x, 'low', 0.0) or 0.0) for x in seg]
        if any(v <= 0.0 for v in closes + highs + lows):
            out['reason'] = 'trend_breakout_bad_candle_px'
            return out
        if side == 'LONG':
            path_ok = all(closes[i] > closes[i - 1] for i in range(1, len(closes)))
            ref_px = max(highs[:-1] or highs)
            need_px = float(ref_px) * (1.0 + float(M9_TREND_BREAKOUT_BUFFER_PCT))
            px_ok = float(cur_px) >= float(need_px)
        else:
            path_ok = all(closes[i] < closes[i - 1] for i in range(1, len(closes)))
            ref_px = min(lows[:-1] or lows)
            need_px = float(ref_px) * (1.0 - float(M9_TREND_BREAKOUT_BUFFER_PCT))
            px_ok = float(cur_px) <= float(need_px)
        out['recent_close_path_ok'] = bool(path_ok)
        out['breakout_px_ok'] = bool(px_ok)
        out['breakout_ref_px'] = float(ref_px)
        out['breakout_need_px'] = float(need_px)
        out['recent_closes'] = [float(x) for x in closes]
        if not bool(path_ok):
            out['reason'] = 'trend_breakout_path_not_ready'
            return out
        if not bool(px_ok):
            out['reason'] = 'trend_breakout_px_not_hit'
            return out
        profit_u, profit_det = _m9_est_same_leg_profit_buffer_u(positions, str(coin), plat, side, cur_px)
        out['profit_buffer_u'] = float(profit_u or 0.0)
        out['profit_buffer_detail'] = dict(profit_det or {})
        need_profit_u = max(0.0, float(amount_u or 0.0) * float(M9_TREND_BREAKOUT_MIN_PROFIT_BUFFER_RATIO))
        out['profit_buffer_need_u'] = float(need_profit_u)
        out['profit_buffer_ok'] = bool(float(profit_u or 0.0) + 1e-9 >= float(need_profit_u))
        if not bool(out['profit_buffer_ok']):
            out['reason'] = 'trend_breakout_profit_buffer_not_enough'
            return out
        raw_amount = max(10.0, float(amount_u or 0.0) * float(M9_TREND_BREAKOUT_AMOUNT_MULT))
        breakout_amount_u = float(_round_usd10(raw_amount))
        breakout_amount_u = max(10.0, min(float(amount_u or 0.0), float(breakout_amount_u)))
        out['allow'] = bool(breakout_amount_u > 0.0)
        out['reason'] = 'trend_breakout_add' if out['allow'] else 'trend_breakout_amount_zero'
        out['amount_mult'] = float(M9_TREND_BREAKOUT_AMOUNT_MULT)
        out['breakout_amount_u'] = float(breakout_amount_u)
        try:
            out['trend_opened'] = int((trend_det or {}).get('opened') or 0)
            out['trend_cap'] = int((trend_det or {}).get('cap') or 0)
        except Exception:
            pass
        return out
    except Exception as _e:
        out['allow'] = False
        out['reason'] = f'trend_breakout_exc:{type(_e).__name__}'
        return out

def _m9_trend_tp_pct(step_pct: float | None, fallback: float | None = None) -> float:
    try:
        sp = float(step_pct if step_pct is not None else 0.0)
    except Exception:
        sp = 0.0
    try:
        fb = float(fallback if fallback is not None else M9_TREND_TP_MIN_PCT)
    except Exception:
        fb = float(M9_TREND_TP_MIN_PCT)
    base = max(float(M9_TREND_TP_MIN_PCT), sp + float(M9_TREND_TP_EXTRA_PCT), fb)
    return float(min(max(base, float(M9_TREND_TP_MIN_PCT)), float(max(GRID_CONSERVATIVE_TP_CAP_PCT, M9_TREND_TP_MIN_PCT))))

def _m9_trend_move_pct(layer: dict | None, side: str, cur_px: float | None) -> float | None:
    try:
        ly = dict(layer or {})
        opx = float(_m9_layer_truth_open_px(ly, 0.0) or 0.0)
        cpx = float(cur_px or 0.0)
        if opx <= 0 or cpx <= 0:
            return None
        s = str(side or '').upper().strip()
        if s == 'LONG':
            return float((cpx - opx) / opx)
        if s == 'SHORT':
            return float((opx - cpx) / opx)
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_879', _e)
        pass
    return None

def _m9_trend_exit_decision(layer: dict | None, side: str, cur_px: float | None, rsi: float | None = None, adx: float | None = None) -> dict:
    out = {'hit': False, 'sell_ratio': None, 'close_reason': '', 'grid_mode': _m9_layer_mode(layer)}
    try:
        ly = layer if isinstance(layer, dict) else {}
        if _m9_layer_mode(ly) != 'TREND':
            out['close_reason'] = 'normal_layer'
            return out
        move_pct = _m9_trend_move_pct(ly, side, cur_px)
        if move_pct is None:
            out['close_reason'] = 'trend_no_move_pct'
            return out
        net_u, net_det = _m9_est_layer_net_profit_u(ly, side, cur_px)
        out['move_pct'] = float(move_pct)
        out['est_net_u'] = (float(net_u) if net_u is not None else None)
        out['net_det'] = net_det
        changed = False
        cpx = float(cur_px or 0.0)
        nowv = float(time.time())
        s = str(side or '').upper().strip()
        if s == 'LONG':
            max_fav = float(ly.get('max_fav_px') or ly.get('trail_anchor_px') or 0.0)
            if cpx > 0 and cpx > max_fav + 1e-12:
                ly['max_fav_px'] = float(cpx)
                ly['trail_anchor_px'] = float(cpx)
                changed = True
        else:
            min_fav = float(ly.get('min_fav_px') or ly.get('trail_anchor_px') or 0.0)
            if cpx > 0 and (min_fav <= 0 or cpx < min_fav - 1e-12):
                ly['min_fav_px'] = float(cpx)
                ly['trail_anchor_px'] = float(cpx)
                changed = True
        lock_need_u = max(float(M9_TREND_LOCK_MIN_U), float((net_det or {}).get('close_u') or 0.0) * float(M9_MIN_NET_PROFIT_PCT))
        if (not bool(int(ly.get('profit_locked') or 0))) and (net_u is not None) and (float(net_u) + 1e-12 >= float(lock_need_u)) and (float(move_pct) >= float(M9_TREND_LOCK_MIN_PCT)):
            ly['profit_locked'] = 1
            ly['profit_locked_ts'] = nowv
            ly['trend_state'] = 'LOCKED'
            try:
                opx = float(_m9_layer_truth_open_px(ly, 0.0) or 0.0)
            except Exception:
                opx = 0.0
            if opx > 0:
                if s == 'LONG':
                    ly['protect_px'] = float(opx) * (1.0 + float(M9_TREND_PROTECT_PCT))
                elif s == 'SHORT':
                    ly['protect_px'] = float(opx) * (1.0 - float(M9_TREND_PROTECT_PCT))
            changed = True
        partial_ratio_done = float(ly.get('partial_close_ratio') or 0.0)
        if (net_u is not None) and (float(net_u) + 1e-12 >= float(lock_need_u)):
            _dyn_rat = _trend_dynamic_partial_ratios(rsi, float(ly.get('realized_u') or 0.0) + float(ly.get('floating_u') or 0.0), float(ly.get('amount_u') or ly.get('notional_u') or 0.0), 0.0)
            _p1r = float((_dyn_rat or {}).get('partial1_ratio') or M9_TREND_PARTIAL1_RATIO)
            _p2r = float((_dyn_rat or {}).get('partial2_ratio') or M9_TREND_PARTIAL2_RATIO)
            if float(move_pct) >= float(M9_TREND_PARTIAL2_PCT) and partial_ratio_done + 1e-9 < float(_p1r + _p2r):
                ratio = max(0.0, min(1.0, float(_p1r + _p2r) - partial_ratio_done))
                if ratio > 0:
                    ly['trend_state'] = 'PARTIAL_TP'
                    ly['last_trend_signal_ts'] = nowv
                    changed = True
                    if changed and ('GRID_BOOK' in globals()) and getattr(globals().get('GRID_BOOK'), '_save', None):
                        GRID_BOOK._save()
                    out.update({'hit': True, 'sell_ratio': float(ratio), 'close_reason': 'trend_partial2'})
                    return out
            if float(move_pct) >= float(M9_TREND_PARTIAL1_PCT) and partial_ratio_done + 1e-9 < float(_p1r):
                ratio = max(0.0, min(1.0, float(_p1r) - partial_ratio_done))
                if ratio > 0:
                    ly['trend_state'] = 'PARTIAL_TP'
                    ly['last_trend_signal_ts'] = nowv
                    changed = True
                    if changed and ('GRID_BOOK' in globals()) and getattr(globals().get('GRID_BOOK'), '_save', None):
                        GRID_BOOK._save()
                    out.update({'hit': True, 'sell_ratio': float(ratio), 'close_reason': 'trend_partial1'})
                    return out
        protect_px = float(ly.get('protect_px') or 0.0)
        trail_anchor = float(ly.get('trail_anchor_px') or ly.get('max_fav_px') or ly.get('min_fav_px') or 0.0)
        trail_hit = False
        protect_hit = False
        if bool(int(ly.get('profit_locked') or 0)) and cpx > 0 and trail_anchor > 0:
            if s == 'LONG':
                trail_hit = bool(cpx <= trail_anchor * (1.0 - float(M9_TREND_TRAIL_PCT)))
                protect_hit = bool(protect_px > 0 and cpx <= protect_px)
            elif s == 'SHORT':
                trail_hit = bool(cpx >= trail_anchor * (1.0 + float(M9_TREND_TRAIL_PCT)))
                protect_hit = bool(protect_px > 0 and cpx >= protect_px)
        weak_rsi = False
        try:
            if rsi is not None:
                rv = float(rsi)
                if s == 'LONG':
                    weak_rsi = bool(rv <= float(M9_TREND_EXIT_RSI_LONG))
                elif s == 'SHORT':
                    weak_rsi = bool(rv >= float(M9_TREND_EXIT_RSI_SHORT))
        except Exception:
            weak_rsi = False
        if trail_hit or protect_hit or weak_rsi:
            ly['trend_state'] = 'TRAILING' if trail_hit else ('PROTECT_EXIT' if protect_hit else 'TREND_WEAK_EXIT')
            ly['last_trend_signal_ts'] = nowv
            changed = True
            if changed and ('GRID_BOOK' in globals()) and getattr(globals().get('GRID_BOOK'), '_save', None):
                GRID_BOOK._save()
            out.update({'hit': True, 'sell_ratio': None, 'close_reason': ('trend_trail_exit' if trail_hit else ('trend_protect_exit' if protect_hit else 'trend_rsi_exit'))})
            return out
        if changed and ('GRID_BOOK' in globals()) and getattr(globals().get('GRID_BOOK'), '_save', None):
            GRID_BOOK._save()
        out['close_reason'] = 'trend_hold'
        _trend_field_selfcheck('', '', out)
        return out
    except Exception as e:
        out['close_reason'] = f'trend_exit_exc:{type(e).__name__}'
        return out

def _m9_old_layer_exit_decision(layer: dict | None, side: str, cur_px: float | None, tp_px: float | None = None, rsi: float | None = None, adx: float | None = None) -> dict:
    out = {'hit': False, 'sell_ratio': None, 'close_reason': '', 'grid_mode': _m9_layer_mode(layer)}
    try:
        if not bool(M9_OLD_LAYER_ENABLE):
            out['close_reason'] = 'old_layer_disabled'
            return out
        ly = layer if isinstance(layer, dict) else {}
        if _m9_layer_mode(ly) != 'NORMAL':
            out['close_reason'] = 'old_layer_not_normal'
            return out
        move_pct = _m9_trend_move_pct(ly, side, cur_px)
        if move_pct is None:
            out['close_reason'] = 'old_layer_no_move_pct'
            return out
        net_u, net_det = _m9_est_layer_net_profit_u(ly, side, cur_px)
        out['move_pct'] = float(move_pct)
        out['est_net_u'] = (float(net_u) if net_u is not None else None)
        out['net_det'] = net_det
        if net_u is None:
            out['close_reason'] = 'old_layer_no_net_u'
            return out
        nowv = float(time.time())
        open_ts = _safe_float(ly.get('open_ts'), 0.0) or 0.0
        age_sec = max(0.0, float(nowv) - float(open_ts)) if open_ts > 0 else 0.0
        out['age_sec'] = float(age_sec)
        if age_sec + 1e-9 < float(M9_OLD_LAYER_MIN_AGE_SEC):
            out['close_reason'] = 'old_layer_too_young'
            return out
        need_u = max(float(M9_OLD_LAYER_MIN_NET_U), float((net_det or {}).get('close_u') or 0.0) * float(M9_OLD_LAYER_MIN_NET_PCT))
        if float(net_u) + 1e-12 < float(need_u):
            out['close_reason'] = 'old_layer_profit_not_enough'
            out['need_net_u'] = float(need_u)
            return out
        cpx = float(cur_px or 0.0)
        opx = float(_m9_layer_truth_open_px(ly, 0.0) or 0.0)
        if opx <= 0.0 or cpx <= 0.0:
            out['close_reason'] = 'old_layer_bad_px'
            return out
        if tp_px is None:
            tp_px = _safe_float(ly.get('tp_px'), None)
        tp_gap_pct = None
        try:
            if tp_px is not None and float(tp_px) > 0:
                if str(side or '').upper().strip() == 'LONG':
                    tp_gap_pct = max(0.0, float(tp_px) - float(cpx)) / max(abs(float(tp_px)), 1e-12)
                else:
                    tp_gap_pct = max(0.0, float(cpx) - float(tp_px)) / max(abs(float(tp_px)), 1e-12)
        except Exception:
            tp_gap_pct = None
        out['tp_gap_pct'] = (float(tp_gap_pct) if tp_gap_pct is not None else None)
        near_breakeven = bool(abs(float(cpx) - float(opx)) / max(abs(float(opx)), 1e-12) <= float(M9_OLD_LAYER_NEAR_BREAKEVEN_PCT))
        far_tp = bool(tp_gap_pct is not None and float(tp_gap_pct) >= float(M9_OLD_LAYER_FAR_TP_GAP_PCT))
        anchor_key = 'old_exit_anchor_px'
        changed = False
        s = str(side or '').upper().strip()
        anchor = float(ly.get(anchor_key) or 0.0)
        if s == 'LONG':
            if cpx > 0 and cpx > anchor + 1e-12:
                ly[anchor_key] = float(cpx)
                anchor = float(cpx)
                changed = True
            rebound_trail_hit = bool(anchor > 0 and cpx <= anchor * (1.0 - float(M9_OLD_LAYER_REBOUND_TRAIL_PCT)))
        else:
            if cpx > 0 and (anchor <= 0 or cpx < anchor - 1e-12):
                ly[anchor_key] = float(cpx)
                anchor = float(cpx)
                changed = True
            rebound_trail_hit = bool(anchor > 0 and cpx >= anchor * (1.0 + float(M9_OLD_LAYER_REBOUND_TRAIL_PCT)))
        if changed and ('GRID_BOOK' in globals()) and getattr(globals().get('GRID_BOOK'), '_save', None):
            try:
                GRID_BOOK._save()
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_880', _e)
                pass
        if rebound_trail_hit:
            out.update({'hit': True, 'sell_ratio': float(M9_OLD_LAYER_PARTIAL_RATIO), 'close_reason': 'old_layer_rebound_trail_exit'})
            return out
        if near_breakeven:
            out.update({'hit': True, 'sell_ratio': float(M9_OLD_LAYER_PARTIAL_RATIO), 'close_reason': 'old_layer_near_breakeven_exit'})
            return out
        if far_tp:
            out.update({'hit': True, 'sell_ratio': float(M9_OLD_LAYER_PARTIAL_RATIO), 'close_reason': 'old_layer_far_tp_relief'})
            return out
        out['close_reason'] = 'old_layer_hold'
        return out
    except Exception as e:
        out['close_reason'] = f'old_layer_exc:{type(e).__name__}'
        return out

def _write_control_cmd(cmd: str, reason: str = "") -> None:
    try:
        run_state = "paused" if str(cmd).lower().strip() == "pause" else "running"
        obj = {"cmd": cmd, "run_state": run_state, "updated_ts": time.time()}
        if reason:
            obj["reason"] = reason
        for fp in (CONTROL_FP, CONTROL_FP_FALLBACK):
            try:
                Path(fp).parent.mkdir(parents=True, exist_ok=True)
                if callable(globals().get("safe_write_json")):
                    ok = bool(globals()["safe_write_json"](str(fp), obj, indent=2))
                else:
                    payload = _json_dumps_bot(obj, indent=2)
                    Path(fp).write_text(payload, encoding="utf-8")
                    ok = True
                if ok:
                    break
            except Exception:
                continue
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

def _wait_enter_no_exit(prompt: str) -> None:
    """历史函数名保留，但默认不再把机器人卡死在人工等待。
    人话：你已经明确要求“有问题别停，优先重启/自愈”，所以默认改为发起软重启请求。"""
    msg = str(prompt or "").strip()

    _auto_bypass = True
    try:
        _auto_bypass = bool(int(float(os.getenv('AUTO_RECOVER_NO_WAIT_ENTER', '1') or 1)))
    except Exception:
        _auto_bypass = True
    if _auto_bypass:
        try:
            panel_set_mainloop_state('RECOVERING', hint=msg[:200])
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_881', _e)
            pass
        try:
            cprint(f"[AUTO_RECOVER] {msg} -> 已跳过 WAIT_ENTER，转为软重启/自动恢复")
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_882', _e)
            pass
        try:
            _request_soft_restart('WAIT_ENTER_BYPASS', {'prompt': msg[:300]}, source='WAIT_ENTER')
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_883', _e)
            pass
        return

    panel_set_mainloop_state("WAIT_ENTER", hint=msg)

    try:
        cprint(msg)
    except Exception:
        try:
            print(msg)
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    try:
        if 'panel_update_last_loop' in globals():
            panel_update_last_loop({
                'ts': time.time(),
                'ts_human': now_ts(),
                'pid': os.getpid(),
                'panel_url': _PANEL_URL,
                'panel_host': _PANEL_HOST,
                'panel_port': _PANEL_PORT,
                'source': 'PAUSE',
                'state': 'PAUSED_WAIT_ENTER',
                'brief': '已暂停等待回车（不允许自动退出）',
                'reason_cn': msg,
                'decisions': [],
            })
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    while True:
        try:
            input('[HUMAN] 回车继续（不允许自动退出）> ')
            panel_set_mainloop_state('RUNNING', hint='已回车，继续主循环')
            return
        except EOFError:
            try:
                cprint('[HUMAN] 当前无交互输入（EOF），继续等待...（每 5 秒提示一次）')
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

            time.sleep(5)
        except KeyboardInterrupt:
            try:
                cprint('[HUMAN] 捕获 Ctrl+C（中断），仍继续等待回车确认...')
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

            time.sleep(1)
        except Exception:
            time.sleep(1)

_GO_LEGACY_FIX_STREAK = {}  # coin -> 连续未修复轮次
_GO_LEGACY_FIX_PREV = set()  # 上一轮 need_legacy_deleted coins（用于观测修复成功/失败）
_GO_LEGACY_FIX_STREAK_LIMIT = 3  # 连续未修复阈值：达到后进入 LEGACY_FIX_ONLY（仅修复态），不再等待回车
_GO_LEGACY_FIX_PREV_DIFF = {}  # coin -> 上一轮 notional_diff_u（用于打印 diff 变化）

LEGACY_FIX_CFG = {
    "WHITELIST_BYPASS_LIMITS": False,  # 修复模块白名单：绕过 chase_cap/MAX_STEP/节流/熔断
    "SAFE_GAP_U": 50.0,          # 安全差额上限（U）
    "CHASE_CAP_RATIO": 0.80,      # 追赶上限 = cap_leg * ratio（避免把小腿追满）
    "MAX_STEP_U": 100.0,          # 每轮最大补腿步长（U）
    "WINDOW_SEC": 300.0,          # 5分钟窗口
    "MAX_PER_WINDOW": 2,          # 每币每5分钟最多补腿次数
    "FAIL_STREAK_LIMIT": 3,       # 连续失败次数达到即 Pause（暂停）
}

try:
    SAFE_GAP_U = float(LEGACY_FIX_CFG.get('SAFE_GAP_U', 50.0) or 50.0)
except Exception:
    SAFE_GAP_U = 50.0
GLOBAL_PLATFORM_DIFF_PCT = 0.10  # 全平台总名义差额阈值：10% × total_u（总资金）
ENABLE_HP_GLOBAL_PLATFORM_TOTAL = False  # 已取消：平台总名义层面管控

_LEGACY_FIX_TRACK: dict[str, dict] = {}

def _legacy_fix_is_whitelist(req: dict | None = None) -> bool:
    """[NO_BYPASS] 系统级风控：禁用任何“修复白名单绕过风控/硬顶/节流/熔断”的路径。

    说明：
    - legacy_fix_mode / auto_legacy_fix / legacy_only_mode 等标记仅用于日志取证与优先级排序，不用于绕过限制。
    - 即使 LEGACY_FIX_CFG 里有人手动把 WHITELIST_BYPASS_LIMITS 打开，这里也强制返回 False，防止误操作造成不可控下单。
    """
    return False

def _legacy_fix_is_whitelist_any(req: object | None = None) -> bool:
    """白名单判定（兼容 dict 或带属性的请求对象）。"""
    try:
        if req is None:
            return False
        if isinstance(req, dict):
            return _legacy_fix_is_whitelist(req)
        d = {}
        for k in ("module","action_type","action","coin","platform","notional_u","amount_usd","meta","params"):
            try:
                v = getattr(req, k)
            except Exception:
                v = None
            if v is not None:
                d[k] = v
        return _legacy_fix_is_whitelist(d)
    except Exception:
        return False
    except Exception:
        return False

def _legacy_deleted_track_allow(coin: str, req: dict | None = None) -> bool:
    """窗口节流：每币每 WINDOW_SEC 秒最多 MAX_PER_WINDOW 次。
    白名单：直接放行（绕过窗口节流）。
    """
    try:
        if _legacy_fix_is_whitelist(req):
            return True
        rec = _LEGACY_FIX_TRACK.setdefault(str(coin), {})
        pu = float(rec.get("pause_until_ts") or 0.0)
        if pu > 0.0 and time.time() < pu:
            return False

        window_sec = float((LEGACY_FIX_CFG.get("WINDOW_SEC") if isinstance(LEGACY_FIX_CFG, dict) else 300.0) or 300.0)
        max_per = int((LEGACY_FIX_CFG.get("MAX_PER_WINDOW") if isinstance(LEGACY_FIX_CFG, dict) else 2) or 2)
        now = time.time()
        win_ts = float(rec.get("win_ts") or 0.0)
        cnt = int(rec.get("cnt") or 0)
        if win_ts <= 0.0 or (now - win_ts) >= window_sec:
            rec["win_ts"] = float(now)
            rec["cnt"] = 0
            cnt = 0
        if cnt >= max_per:
            return False
        rec["cnt"] = int(cnt + 1)
        return True
    except Exception:
        return True

def _legacy_deleted_track_mark_success(coin: str) -> None:
    """修复成功：清失败熔断计数。"""
    try:
        rec = _LEGACY_FIX_TRACK.setdefault(str(coin), {})
        rec["fail_streak"] = 0
        rec["pause_until_ts"] = 0.0
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

def _legacy_deleted_track_mark_fail_and_maybe_pause(coin: str, reason: str = "", req: dict | None = None) -> None:
    """失败熔断：连续失败达到阈值会进入暂停。
    白名单：绕过失败熔断（只记录，不暂停）。
    """
    try:
        if _legacy_fix_is_whitelist(req):
            try:
                print(f"[LEGACY_DELETED][FAIL][WL] coin={coin} reason={reason}")
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

            return
        limit = int((LEGACY_FIX_CFG.get("FAIL_STREAK_LIMIT") if isinstance(LEGACY_FIX_CFG, dict) else 3) or 3)
        rec = _LEGACY_FIX_TRACK.setdefault(str(coin), {})
        fs = int(rec.get("fail_streak") or 0) + 1
        rec["fail_streak"] = int(min(fs, 99))
        if fs >= limit:
            rec["pause_until_ts"] = float(time.time() + 3600.0)  # 默认 1 小时
            try:
                print(f"[LEGACY_DELETED][PAUSE] coin={coin} fail_streak={fs} limit={limit} reason={reason}")
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

def _legacy_deleted_after_failure(*args, **kwargs):
    raise RuntimeError('LEGACY_FIX_SOURCE_DELETED_HARD')

def _struct_legacy_deleted_force_legacy_deleted(snapshot: dict, trigger: str, max_submit: int = 1) -> int:
    """LEGACY_DELETED（结构修复）强制触发入口（恢复“缺腿/大失衡必须立刻修”的行为）。

    说明：此前主循环里把 旧结构修复evaluate 移除了，导致虽然识别到 MISSING_LEG/IMBALANCE/SAME_DIR，
    但只打印 BYPASS、不入队，极其危险（新号/小资金更危险）。

    这里采用“复用 LEGACY_DELETED 补腿入队逻辑”的方式：
    - 选择最严重的 1 个币（默认 max_submit=1，避免同轮大量 UI 点击）
    - 直接调用 _legacy_deleted_after_failure 入队补腿（其内部不受睡眠/硬顶等限制，且会持续修到 gap 收敛）
    """
    if _module_is_standby("LEGACY_DELETED"):
        return 0

    try:
        trig = str(trigger or '').strip() or 'missing_leg_force_legacy_deleted'
    except Exception:
        trig = 'missing_leg_force_legacy_deleted'

    coins = []
    try:
        coins = list(snapshot.get('coins') or snapshot.get('coin_list') or snapshot.get('coins_all') or [])
    except Exception:
        coins = []
    if not coins:
        try:
            pos = snapshot.get('pos') or _pos_root(snapshot) or {}
            coins = list(pos.keys())
        except Exception:
            coins = []

    picks = []
    for c in coins:
        try:
            coin = str(c or '').upper()
            try:
                _trace_set_for("LEGACY_DELETED", coin)
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_886', _e)
                pass
            if not coin:
                continue
            state, st = classify_state_detail(snapshot or {}, coin)

            try:
                _st_ext = float(st.get('ext_u') or 0.0)
                _st_var = float(st.get('var_u') or 0.0)
                _st_gap = float(st.get('diff_abs_u') or abs(_st_ext - _st_var))
                _st_ratio = float(st.get('diff_ratio') or 0.0)
                _st_abs_thr = float(st.get('abs_thr') or 0.0)
                _st_ratio_thr = float(st.get('ratio_thr') or 0.0)
                safe_log(lambda: f"[{now_ts()}] [PIN][LEGACY_DELETED_STATE] coin={coin} state={state} ext={_st_ext:.6g} var={_st_var:.6g} gap={_st_gap:.6g} ratio={_st_ratio:.6g} abs_thr={_st_abs_thr:.6g} ratio_thr={_st_ratio_thr:.6g} ext_has={bool(st.get('ext_has'))} var_has={bool(st.get('var_has'))} ext_side={str(st.get('ext_side') or '')} var_side={str(st.get('var_side') or '')}")
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

            try:
                _e = _get_position(snapshot or {}, coin, "EXT") or {}
                _v = _get_position(snapshot or {}, coin, "VAR") or {}
                en_abs = float(abs(float(_pos_notional(_e) or 0.0)))
                vn_abs = float(abs(float(_pos_notional(_v) or 0.0)))
                es = str((_e.get("side") or _e.get("position_side") or "")).upper()
                vs = str((_v.get("side") or _v.get("position_side") or "")).upper()
                if es not in ("LONG", "SHORT"): es = str(st.get("ext_side") or "").upper()
                if vs not in ("LONG", "SHORT"): vs = str(st.get("var_side") or "").upper()
            except Exception:
                en_abs, vn_abs, es, vs = 0.0, 0.0, "", ""

            gap = float(abs(en_abs - vn_abs))
            ext_has = bool(_has_leg_u(en_abs) and es in ("LONG", "SHORT"))
            var_has = bool(_has_leg_u(vn_abs) and vs in ("LONG", "SHORT"))
            miss = bool((ext_has and (not var_has)) or (var_has and (not ext_has))) or bool(st.get('missing_leg')) or (str(state) in ("MISSING_LEG","MISSING_LEG_HARD","MISSING_LEG_BIG"))
            same = bool(ext_has and var_has and (es == vs) and es in ("LONG","SHORT")) or bool(st.get('same_dir')) or (str(state) == 'SAME_DIR')
            imb = (str(state) == 'GAP_BIG') or bool(st.get('imbalance')) or (ext_has and var_has and gap > 1e-9)

            if trig.startswith('missing'):
                if not miss:
                    continue
                score = float(max(en_abs, vn_abs))
            elif trig.startswith('imbalance'):
                if not (imb or same):
                    continue
                score = float(gap)
            else:
                if not (miss or imb or same):
                    continue
                score = float(max(max(en_abs, vn_abs), gap))

            picks.append((score, coin, state, en_abs, vn_abs, gap, bool(miss), {"ext_side": es, "var_side": vs, **(dict(st) if isinstance(st, dict) else {})}))

            picks.append((score, coin, state, ext_u, var_u, gap, bool(miss), dict(st) if isinstance(st, dict) else {}))
        except Exception:
            continue

    if not picks:
        return 0

    picks.sort(key=lambda x: float(x[0]), reverse=True)

    submitted = 0
    for score, coin, state, ext_u, var_u, gap, miss_pick, st_pick in picks:
        if submitted >= int(max_submit or 1):
            break
        try:
            try:

                _need_plat = '-'
                _need_side = '-'
                _need_amt = 0.0

                en_abs = float(abs(float(ext_u or 0.0)))
                vn_abs = float(abs(float(var_u or 0.0)))
                gap_abs = float(abs(en_abs - vn_abs))

                if miss_pick:
                    if en_abs <= 1e-9 and vn_abs > 1e-9:
                        _need_plat = "EXT"
                        other_side = str(st_pick.get("var_side") or "").upper()
                    elif vn_abs <= 1e-9 and en_abs > 1e-9:
                        _need_plat = "VAR"
                        other_side = str(st_pick.get("ext_side") or "").upper()
                    else:
                        _need_plat = "EXT" if en_abs <= vn_abs else "VAR"
                        other_side = str(st_pick.get("var_side") if _need_plat == "EXT" else st_pick.get("ext_side") or "").upper()

                    if other_side == "LONG":
                        _need_side = "SHORT"
                    elif other_side == "SHORT":
                        _need_side = "LONG"
                    else:
                        _need_side = "LONG"

                    _need_amt = float(max(en_abs, vn_abs, 0.0))

                else:
                    if en_abs <= vn_abs:
                        _need_plat = "EXT"
                        this_side = str(st_pick.get("ext_side") or "").upper()
                    else:
                        _need_plat = "VAR"
                        this_side = str(st_pick.get("var_side") or "").upper()

                    if this_side == "LONG":
                        _need_side = "LONG"
                    elif this_side == "SHORT":
                        _need_side = "SHORT"
                    else:
                        other = str(st_pick.get("var_side") if _need_plat == "EXT" else st_pick.get("ext_side") or "").upper()
                        _need_side = "SHORT" if other == "LONG" else ("LONG" if other == "SHORT" else "LONG")

                    _need_amt = float(max(gap_abs, 0.0))

                _adx_legacy_deleted, _rsi_legacy_deleted, _ind_rsn_legacy_deleted = _legacy_deleted_get_adx_rsi(snapshot or {}, coin)
                _missing_leg_bypass = bool(miss_pick)
                if _missing_leg_bypass:
                    try:
                        tprint('LEGACY_DELETED', coin, 'BYPASS_LEGACY_DELETED_GATE', reason='missing_leg_bypass_rsi', adx=_adx_legacy_deleted, rsi=_rsi_legacy_deleted, need_side=str(_need_side), need_plat=str(_need_plat))
                    except Exception as _e:
                        _log_exc(mod='SYS', stage='EXC_PASS', e=_e)
                else:
                    _ok_dir_legacy_deleted, _rsn_dir_legacy_deleted = _rsi_dir_allow_unified(_rsi_legacy_deleted, _need_side)
                    if not _ok_dir_legacy_deleted:
                        try:
                            tprint('LEGACY_DELETED', coin, 'SKIP_LEGACY_DELETED_GATE', reason=str(_rsn_dir_legacy_deleted), rsi=_rsi_legacy_deleted, pivot=float(LEGACY_FIX_RSI_PIVOT), need_side=str(_need_side))
                        except Exception as _e:
                            _log_exc(mod='SYS', stage='EXC_PASS', e=_e)
                        continue

                try:
                    _gap_u = float(_need_amt)
                except Exception:
                    _gap_u = 0.0

                try:
                    _min_r = float(cfg_getf_runtime('LEGACY_DELETED_MIN_U', 10.0))
                except Exception:
                    _min_r = 10.0

                try:
                    _base_cfg = float(cfg_getf_runtime('LEGACY_DELETED_LEGACY_DELETED_BASE_U', cfg_getf_runtime('LEGACY_DELETED_BASE_U', 100.0)))
                except Exception:
                    _base_cfg = 100.0

                _base_step = float(max(_min_r, _base_cfg))
                try:
                    if _gap_u > 0:
                        _base_step = float(min(_base_step, float(_gap_u)))
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_887', _e)
                    pass
                try:
                    _base_step = float(_m9_norm_u_tens(float(_base_step), lo=float(_min_r), hi=float(max(_gap_u, _min_r))))
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_888', _e)
                    pass
                try:
                    _need_amt_s, _rsi_stage_det = _legacy_deleted_scale_amount_by_rsi(float(_base_step), str(_need_side).upper(), _rsi_legacy_deleted)
                except Exception:
                    _need_amt_s, _rsi_stage_det = float(_base_step), {}

                try:
                    _need_amt_s = float(min(float(_need_amt_s), float(_gap_u))) if float(_gap_u) > 0 else float(_need_amt_s)
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_889', _e)
                    pass
                try:
                    _need_amt = float(_m9_norm_u_tens(float(_need_amt_s), lo=float(_min_r), hi=float(max(_gap_u, _min_r))))
                except Exception:
                    _need_amt = float(_need_amt_s)
                try:
                    tprint('LEGACY_DELETED', coin, 'LEGACY_DELETED_RSI_STAGE', side=str(_need_side), rsi=_rsi_legacy_deleted,
                           stage=(_rsi_stage_det or {}).get('stage'), mult=(_rsi_stage_det or {}).get('mult'),
                           amt0=float(_need_amt_s), amt=float(_need_amt))
                except Exception as _e:
                    _log_exc(mod='SYS', stage='EXC_PASS', e=_e)

                _legacy_deleted_after_failure(snapshot or {}, coin, _need_plat, _need_side, float(_need_amt), trig)

            except Exception:
                _legacy_deleted_after_failure(snapshot or {}, coin, '-', '-', 0.0, trig)

            try:
                tprint('LEGACY_DELETED', coin, 'ENQUEUE_LEGACY_DELETED', trigger=trig, state=state, ext=float(ext_u), var=float(var_u), gap=float(gap), score=float(score))
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

            submitted += 1
        except Exception:
            continue

    return int(submitted)

def _post_m10_enqueue_struct_legacy_deleted_for_coin(snapshot: dict, coin: str, force_gap_thr_u: float = 20.0) -> int:
    """M10 执行成功后：强制对该币触发一次 LEGACY_DELETED（修腿/对冲平衡）入队。

    规则（按用户方案2）：
    - 缺腿：必入队（无门槛）
    - 双腿都在：若差额 diff >= force_gap_thr_u 则入队（action_type=increase）
    - 同向：必入队（视为结构异常）
    备注：这里只负责“入队触发”，实际下单金额/方向由 LEGACY_DELETED 执行器逻辑统一决策。
    """
    if _module_is_standby("LEGACY_DELETED"):
        return 0

    try:
        cu = str(coin or '').upper().strip()
        try:
            _trace_set_for("LEGACY_DELETED", cu)
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_890', _e)
            pass
    except Exception:
        cu = ''
    if not cu:
        return 0

    try:
        coins_map2 = (snapshot.get("coins") if isinstance(snapshot, dict) else {}) or {}
        co2 = coins_map2.get(cu) or {}
        ext2 = (co2.get("ext") or {})
        var2 = (co2.get("var") or {})
        ext_has2 = bool(ext2.get("has_position", False))
        var_has2 = bool(var2.get("has_position", False))
        ext_val2 = float(ext2.get("value_usd", 0.0) or 0.0) if ext_has2 else 0.0
        var_val2 = float(var2.get("value_usd", 0.0) or 0.0) if var_has2 else 0.0
        diff2 = abs(ext_val2 - var_val2)

        ext_side2 = str((ext2.get("side") or "")).upper()
        var_side2 = str((var2.get("side") or "")).upper()
        same_dir2 = bool(ext_has2 and var_has2 and ext_side2 and var_side2 and (ext_side2 == var_side2))

        is_missing = (ext_has2 and (not var_has2)) or (var_has2 and (not ext_has2))
        is_imb = (ext_has2 and var_has2 and (diff2 >= float(force_gap_thr_u or 0.0)))

        if not (is_missing or is_imb or same_dir2):
            try:
                safe_log(lambda: f"[{now_ts()}] POST_M10_REOPEN_SKIP coin={cu} reason=gap_ok diff={diff2:.2f} thr={float(force_gap_thr_u):.2f} same_dir={same_dir2}")
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

            return 0

        act = "increase" if (ext_has2 and var_has2) else "add_leg"

        try:
            _e = _get_position(snapshot or {}, cu, "EXT") or {}
            _v = _get_position(snapshot or {}, cu, "VAR") or {}
            _en = float(abs(float(_pos_notional(_e) or 0.0)))
            _vn = float(abs(float(_pos_notional(_v) or 0.0)))
            _es = str((_e.get("side") or "")).upper()
            _vs = str((_v.get("side") or "")).upper()
            if (_en <= 1e-9) and (_vn > 1e-9):
                need_plat = "EXT"
                need_side = "SHORT" if _vs == "LONG" else ("LONG" if _vs == "SHORT" else "SHORT")
            elif (_vn <= 1e-9) and (_en > 1e-9):
                need_plat = "VAR"
                need_side = "SHORT" if _es == "LONG" else ("LONG" if _es == "SHORT" else "SHORT")
            else:
                need_plat = "EXT" if (_en <= _vn) else "VAR"
                need_side = _es if need_plat == "EXT" else _vs
                if need_side not in ("LONG","SHORT"):
                    other = _vs if need_plat=="EXT" else _es
                    need_side = "SHORT" if other == "LONG" else ("LONG" if other == "SHORT" else "LONG")
            planned_u = float(max(40.0, min(float(diff2 or 0.0), 120.0)))
            try:
                _safe_gap_u = float((LEGACY_FIX_CFG.get('SAFE_GAP_U') if isinstance(LEGACY_FIX_CFG, dict) else 100.0) or 50.0)
            except Exception:
                _safe_gap_u = 100.0
            try:
                _diff_u2 = float(abs(float(_en) - float(_vn)))
            except Exception:
                _diff_u2 = 0.0
            if _diff_u2 > float(_safe_gap_u):
                _big_plat = "EXT" if float(_en) >= float(_vn) else "VAR"
                if str(need_plat).upper() == _big_plat:
                    need_plat = ("VAR" if _big_plat == "EXT" else "EXT")

        except Exception:
            need_plat = "EXT"
            need_side = "LONG"
            planned_u = 40.0

        req_legacy_deleted = {
            "module": "LEGACY_DELETED",
            "coin": cu,
            "platform": str(need_plat),
            "action_type": act,
            "params": {
                "why": "POST_M10_FORCE_LEGACY_DELETED",
                "platform": str(need_plat),
                "side": str(need_side),
                "amount_usd": float(planned_u),
                "add_notional_u": float(planned_u),
                "force_gap_thr_u": float(force_gap_thr_u or 0.0),
                "post_m10_force": True,
                "post_m10_diff_u": float(diff2),
                "post_m10_same_dir": bool(same_dir2),
                "post_m10_missing_leg": bool(is_missing),
            },
            "meta": {
                "post_m10_force": True,
                "planned_u": float(planned_u),
                "planned_plat": str(need_plat),
                "planned_side": str(need_side),
            }
        }
        try:
            safe_log(lambda: f"[{now_ts()}] [PIN][POST_M10_REOPEN_PLAN] coin={cu} act={act} plat={need_plat} side={need_side} planned_u={planned_u:.2f} diff_u={float(diff2 or 0.0):.2f} missing={is_missing} same_dir={same_dir2}")
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

        rid = _struct_legacy_deleted_submit_to_main_deleted_flow(req_legacy_deleted)

        if rid:
            try:
                safe_log(lambda: f"[{now_ts()}] POST_M10_REOPEN_ENQUEUED coin={cu} rid={rid} act={act} diff={diff2:.2f} thr={float(force_gap_thr_u):.2f} missing={is_missing} same_dir={same_dir2}")
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

            return 1
    except Exception as e:
        try:
            _append_txt(_rizhi_path("go_baocuo.txt") or "go_baocuo.txt", f"post_m10_enqueue_legacy_deleted异常：{repr(e)}")
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    return 0

def _legacy_deleted_balance_legacy_deleted(
    snapshot: dict,
    coin: str,
    *,
    submit_func,
    stage: int = 1,
    stage_ratio: float = 0.8,
    tol_u: float = 50.0,
    missing_u: float = 100.0,
    cap_u: float = 1000.0,
    trigger: str = "LEGACY_DELETED_BALANCE_LEGACY_DELETED",
) -> tuple[bool, str, dict]:
    """
    LEGACY_DELETED：补腿/修复入口（跨平台对冲腿修复）

    系统性原则：
    - “修腿（常规修复）”路径：遵守原有 ADX/RSI 门禁 + RSI 金额缩放逻辑（保持不变）
    - “补腿（缺腿/严重失衡一次性补齐）”路径：当出现
        1) 一腿有一腿无（missing_leg）
        2) 两腿差额 > LEG_ONE_SHOT_GAP_RATIO（默认 50%）
      时，执行一次性补齐（以 big_u - sml_u 为目标），并可绕过 ADX/RSI（默认开启）。
    - 任何下单请求必须携带 trace_id（策略→执行器→回报一致性）。
    """
    if _module_is_standby("LEGACY_DELETED"):
        return False, "module_disabled", {"coin": str(coin or "").upper().strip(), "trigger": str(trigger or ""), "status": "STANDBY", "reason": "module_disabled"}

    det: dict = {
        "coin": str(coin or "").upper().strip(),
        "stage": int(stage),
        "trigger": str(trigger or ""),
    }

    try:
        try:
            _trace_set_for("LEGACY_DELETED", det["coin"])
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_891', _e)
            pass
        c = det["coin"]
        if not c:
            det["skip"] = {"reason": "no_coin"}
            _legacy_deleted_gate_log("LEGACY_DELETED", "LEGACY_DELETED_G001", coin=det.get("coin",""), reason="no_coin", trigger=det.get("trigger",""), stage=det.get("stage"))
            return False, "no_coin", det

        en = float(_get_notional_u(snapshot, c, "EXT") or 0.0)
        vn = float(_get_notional_u(snapshot, c, "VAR") or 0.0)

        big_plat = "EXT" if en >= vn else "VAR"
        sml_plat = "VAR" if big_plat == "EXT" else "EXT"
        big_u = en if big_plat == "EXT" else vn
        sml_u = vn if big_plat == "EXT" else en

        det.update({"big_plat": big_plat, "sml_plat": sml_plat, "big_u": float(big_u), "sml_u": float(sml_u)})

        if big_u < float(missing_u) and sml_u < float(missing_u):
            det["skip"] = {"reason": "both_legs_small"}
            _legacy_deleted_gate_log("LEGACY_DELETED", "LEGACY_DELETED_G002", coin=det.get("coin",""), reason="both_legs_small", trigger=det.get("trigger",""), stage=det.get("stage"))
            return False, "both_legs_small", det

        diff = float(big_u - sml_u)
        det["diff_u"] = float(diff)
        det["gap_ratio"] = float(diff / max(1.0, float(big_u)))

        if diff <= float(tol_u):
            det["skip"] = {"reason": "within_tol"}
            _legacy_deleted_gate_log("LEGACY_DELETED", "LEGACY_DELETED_G003", coin=det.get("coin",""), reason="within_tol", trigger=det.get("trigger",""), stage=det.get("stage"))
            return False, "within_tol", det

        _missing_eps = float(globals().get("LEG_ONE_SHOT_MISSING_EPS_U", 1.0))
        _gap_thr = float(globals().get("LEG_ONE_SHOT_GAP_RATIO", 0.5))
        _one_shot_abs_cap = float(globals().get("LEG_ONE_SHOT_ABS_CAP_U", 5000.0))
        _bypass_gate = bool(globals().get("LEG_ONE_SHOT_BYPASS_ADX_RSI", True))

        missing_leg = bool((float(sml_u) <= float(_missing_eps) or float(sml_u) < float(missing_u)) and float(big_u) >= float(missing_u))
        severe_gap = bool((float(diff) / max(1.0, float(big_u))) > float(_gap_thr))

        one_shot = bool(missing_leg or severe_gap)
        det["mode"] = "ONE_SHOT_HEDGE" if one_shot else "LEGACY_DELETED"
        det["missing_leg"] = bool(missing_leg)
        det["severe_gap"] = bool(severe_gap)

        kind = "missing_leg" if missing_leg else ("gap_gt_thr" if severe_gap else ("short_leg" if sml_u < float(missing_u) else "rebalance"))
        det["kind"] = str(kind)

        big_side = str(_get_leg_side(snapshot, c, big_plat) or "").upper()
        sml_side = str(_get_leg_side(snapshot, c, sml_plat) or "").upper()
        det["big_side"] = big_side
        det["sml_side"] = sml_side

        if big_side == "LONG":
            need_side = "SHORT"
        elif big_side == "SHORT":
            need_side = "LONG"
        else:
            det["skip"] = {"reason": "unknown_big_side", "big_side": str(big_side)}
            _legacy_deleted_gate_log("LEGACY_DELETED", "LEGACY_DELETED_G004", coin=det.get("coin",""), reason="unknown_big_side", trigger=det.get("trigger",""), stage=det.get("stage"))
            return False, "unknown_big_side", det

        if float(sml_u) > float(_missing_eps) and sml_side and sml_side != need_side:
            det["skip"] = {"reason": "sml_side_mismatch", "need_side": need_side, "sml_side": sml_side}
            _legacy_deleted_gate_log("LEGACY_DELETED", "LEGACY_DELETED_G004B", coin=det.get("coin",""), reason="sml_side_mismatch", trigger=det.get("trigger",""), stage=det.get("stage"))
            return False, "sml_side_mismatch", det

        det["need_side"] = need_side
        det["need_plat"] = sml_plat

        _adx_legacy_deleted, _rsi_legacy_deleted, _ind_rsn_legacy_deleted = _legacy_deleted_get_adx_rsi(snapshot or {}, c)
        det["ind_adx"] = _adx_legacy_deleted
        det["ind_rsi"] = _rsi_legacy_deleted
        det["ind_reason"] = str(_ind_rsn_legacy_deleted or "")

        if (not one_shot) or (one_shot and not _bypass_gate):
            if not _legacy_deleted_adx_allow_execute(_adx_legacy_deleted, thr=0.0):
                det["skip"] = {"reason": "adx_not_gt_thr", "adx": _adx_legacy_deleted, "thr": 0.0}
                _legacy_deleted_gate_log("LEGACY_DELETED", "LEGACY_DELETED_G_ADX", coin=det.get("coin",""), reason="adx_not_gt_thr", trigger=det.get("trigger",""), stage=det.get("stage"))
                return False, "adx_not_gt_thr", det
            _allow_legacy_deleted = _legacy_deleted_rsi_allowed_sides(_rsi_legacy_deleted)
            if str(need_side).upper() not in _allow_legacy_deleted:
                det["skip"] = {"reason": "rsi_side_block", "rsi": _rsi_legacy_deleted, "pivot": float(RSI_PIVOT), "need_side": str(need_side), "allow": list(_allow_legacy_deleted)}
                _legacy_deleted_gate_log("LEGACY_DELETED", "LEGACY_DELETED_G_RSI", coin=det.get("coin",""), reason="rsi_side_block", trigger=det.get("trigger",""), stage=det.get("stage"))
                return False, "rsi_side_block", det
        else:
            det["bypass_gate"] = True
            _legacy_deleted_gate_log("LEGACY_DELETED", "LEGACY_DELETED_G_WL", coin=det.get("coin",""), reason="bypass_adx_rsi_one_shot", trigger=det.get("trigger",""), stage=det.get("stage"))

        if one_shot:
            raw_need = float(diff)
            det["raw_need_u"] = float(raw_need)
            need_amt = float(_m9_norm_u_tens(raw_need, lo=0.0, hi=10**12))
            cap_eff = float(min(max(float(cap_u), float(need_amt)), float(_one_shot_abs_cap)))
            need_amt = float(min(float(need_amt), float(cap_eff)))
            det["need_amt_u"] = float(need_amt)
            det["cap_eff_u"] = float(cap_eff)
        else:
            if int(stage) == 1:
                raw_need = diff * float(stage_ratio)
            else:
                raw_need = diff
            det["raw_need_u"] = float(raw_need)

            need_amt0 = float(_m9_norm_u_tens(raw_need, lo=0.0, hi=10**12))
            try:
                need_amt_s, _legacy_deleted_stage_det = _legacy_deleted_scale_amount_by_rsi(float(need_amt0), str(need_side).upper(), _rsi_legacy_deleted)
            except Exception:
                need_amt_s, _legacy_deleted_stage_det = float(need_amt0), {}
            need_amt = float(_m9_norm_u_tens(float(need_amt_s), lo=0.0, hi=10**12))
            need_amt = float(min(float(need_amt), float(cap_u)))

            det["need_amt0_u"] = float(need_amt0)
            det["need_amt_u"] = float(need_amt)
            det["rsi_stage"] = int((_legacy_deleted_stage_det or {}).get("stage") or 0)
            det["rsi_mult"] = float((_legacy_deleted_stage_det or {}).get("mult") or 1.0)

        if float(det.get("need_amt_u") or 0.0) < 10.0:
            det["skip"] = {"reason": "need_amt_too_small"}
            _legacy_deleted_gate_log("LEGACY_DELETED", "LEGACY_DELETED_G005", coin=det.get("coin",""), reason="need_amt_too_small", trigger=det.get("trigger",""), stage=det.get("stage"))
            return False, "need_amt_too_small", det

        meta = _ensure_meta_trace({
            "legacy_deleted_balance_legacy_deleted": True,
            "safe_legacy_fix": True,
            "force_fill_ext": True,
            "legacy_deleted_stage": int(stage),
            "legacy_deleted_kind": str(kind),
            "legacy_deleted_trigger": str(trigger or ""),
            "legacy_deleted_need_u": float(det["need_amt_u"]),
            "legacy_deleted_big_plat": str(big_plat),
            "legacy_deleted_sml_plat": str(sml_plat),
            "legacy_deleted_big_u": float(big_u),
            "legacy_deleted_sml_u": float(sml_u),
            "legacy_deleted_diff_u": float(diff),
            "legacy_deleted_gap_ratio": float(det.get("gap_ratio") or 0.0),
            "legacy_fix_mode": str(det.get("mode") or ""),
            "legacy_deleted_bypass_gate": bool(det.get("bypass_gate") or False),
        })

        req = SimpleNamespace(
            module="LEGACY_DELETED",
            coin=c,
            platform=str(sml_plat),
            side=str(need_side),
            action_type="ADD_SINGLE",
            params={
                "amount_usd": float(det["need_amt_u"]),
                "why": f"{trigger}|balance|{kind}|{det.get('mode','')}|stage{int(stage)}",
                "big_plat": str(big_plat),
                "big_u": float(big_u),
                "sml_u": float(sml_u),
                "diff_u": float(diff),
                "tol_u": float(tol_u),
                "stage": int(stage),
                "need_plat": str(sml_plat),
                "need_side": str(need_side),
            },
            meta=meta,
        )
        det["req"] = {
            "coin": c,
            "platform": str(sml_plat),
            "side": str(need_side),
            "amount_usd": float(det["need_amt_u"]),
            "why": str(req.params.get("why") or ""),
            "trace_id": str(meta.get("trace_id") or ""),
        }

        try:
            safe_log(lambda: f"[{now_ts()}] [PIN][LEGACY_DELETED] coin={c} mode={det.get('mode')} kind={kind} big={big_plat}:{big_u:.2f} sml={sml_plat}:{sml_u:.2f} diff={diff:.2f} ratio={det.get('gap_ratio'):.4f} need={need_side}@{sml_plat} amt_u={float(det['need_amt_u']):.2f} trace={meta.get('trace_id','')}")
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

        rid = submit_func(req)
        det["rid"] = str(rid or "")
        if not rid:
            det["fail"] = {"reason": "submit_failed"}
            _legacy_deleted_gate_log("LEGACY_DELETED", "LEGACY_DELETED_G006", coin=det.get("coin",""), reason="submit_failed", trigger=det.get("trigger",""), stage=det.get("stage"), req=det.get("req"))
            return False, "submit_failed", det

        return True, "enqueued", det

    except Exception as e:
        det["exc"] = str(e)
        _legacy_deleted_gate_log("LEGACY_DELETED", "LEGACY_DELETED_G999", coin=det.get("coin",""), reason="exc", trigger=det.get("trigger",""), stage=det.get("stage"), exc=det.get("exc"))
        return False, "exc", det
def _x1_build_requests(snapshot: dict, coins: list[str] | None, *, trigger_diff_u: float, total_min_u: float,
                       min_order_u: float, cap_u: float) -> list['Request']:
    """X1：只加仓不减仓。
    触发：
      - 双腿差额 > trigger_diff_u
      - 或 双腿合计名义 < total_min_u
    约束（按你的要求）：
      - 不绕过单币硬顶 / 平台硬顶（由执行器硬顶闸门统一约束）
      - 允许补缺腿：act=add_leg（legacy_fix_mode=True），但依然受硬顶闸门约束
    """
    out: list['Request'] = []
    try:
        _pin('X1', stage='BEGIN', reason='build_requests', coins=len(coins or []), trigger_diff_u=trigger_diff_u, total_min_u=total_min_u, min_order_u=min_order_u, cap_u=cap_u)
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    if not isinstance(snapshot, dict):
        try:
            _pin('X1', stage='SKIP', reason='snapshot_not_dict')
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

        return out
    for coin in (coins or []):
        c = str(coin or '').upper().strip()
        try:
            _trace_set_for("X1", c)
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_892', _e)
            pass
        if not c:
            continue
        try:
            en = float(_get_notional_u(snapshot, c, "EXT") or 0.0)
        except Exception:
            en = 0.0
        try:
            vn = float(_get_notional_u(snapshot, c, "VAR") or 0.0)
        except Exception:
            vn = 0.0
        en = abs(float(en))
        vn = abs(float(vn))
        total_u = float(en + vn)
        diff_u = float(abs(en - vn))
        has_e = bool(_has_leg_u(en) and str(_get_leg_side(snapshot, c, "EXT") or "").upper() in ("LONG","SHORT"))
        has_v = bool(_has_leg_u(vn) and str(_get_leg_side(snapshot, c, "VAR") or "").upper() in ("LONG","SHORT"))
        missing_leg = (has_e and (not has_v)) or (has_v and (not has_e))

        hit = (diff_u > float(trigger_diff_u)) or (total_u < float(total_min_u))
        if not hit:
            try:
                _pin('X1', coin=c, stage='SKIP', reason='no_hit', en=en, vn=vn, total_u=total_u, diff_u=diff_u, trigger_diff_u=trigger_diff_u, total_min_u=total_min_u)
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

            continue

        _adx_x1, _rsi_x1, _ind_rsn_x1 = _legacy_deleted_get_adx_rsi(snapshot or {}, c)
        if not _legacy_deleted_adx_allow_execute(_adx_x1, thr=0.0):
            try:
                _pin('X1', coin=c, stage='SKIP', reason='legacy_deleted_gate_adx_not_gt', adx=_adx_x1, thr=0.0, ind_reason=str(_ind_rsn_x1 or ''))
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)
            continue
        _allow_x1 = _legacy_deleted_rsi_allowed_sides(_rsi_x1)
        if not _allow_x1:
            try:
                _pin('X1', coin=c, stage='SKIP', reason='legacy_deleted_gate_rsi_eq_pivot_or_missing', rsi=_rsi_x1, pivot=float(LEGACY_FIX_RSI_PIVOT), ind_reason=str(_ind_rsn_x1 or ''))
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)
            continue

        plans: list[tuple[str, str, str, float, str]] = []

        def _round10(u: float) -> float:
            try:
                return float(_m9_norm_u_tens(float(u), lo=0.0, hi=10**12))
            except Exception:
                return float(_round_usd10(float(u)))

        if total_u < float(total_min_u):
            target_each = float(total_min_u) / 2.0
            if en < target_each:
                need = _round10(max(0.0, target_each - en))
                if need >= float(min_order_u):
                    if has_e:
                        side_e = str(_get_leg_side(snapshot, c, "EXT") or "").upper()
                        if side_e in ("LONG","SHORT"):
                            plans.append(("EXT", "increase", side_e, min(need, float(cap_u)), "total_min_topup_ext"))
                    else:
                        side_v = str(_get_leg_side(snapshot, c, "VAR") or "").upper()
                        if side_v == "LONG":
                            need_side = "SHORT"
                        elif side_v == "SHORT":
                            need_side = "LONG"
                        else:
                            need_side = "LONG"
                        plans.append(("EXT", "add_leg", need_side, min(need, float(cap_u)), "total_min_add_leg_ext"))

            if vn < target_each:
                need = _round10(max(0.0, target_each - vn))
                if need >= float(min_order_u):
                    if has_v:
                        side_v = str(_get_leg_side(snapshot, c, "VAR") or "").upper()
                        if side_v in ("LONG","SHORT"):
                            plans.append(("VAR", "increase", side_v, min(need, float(cap_u)), "total_min_topup_var"))
                    else:
                        side_e = str(_get_leg_side(snapshot, c, "EXT") or "").upper()
                        if side_e == "LONG":
                            need_side = "SHORT"
                        elif side_e == "SHORT":
                            need_side = "LONG"
                        else:
                            need_side = "SHORT"
                        plans.append(("VAR", "add_leg", need_side, min(need, float(cap_u)), "total_min_add_leg_var"))

        if diff_u > float(trigger_diff_u):
            big_plat = "EXT" if en >= vn else "VAR"
            sml_plat = "VAR" if big_plat == "EXT" else "EXT"
            big_u = en if big_plat == "EXT" else vn
            sml_u = vn if big_plat == "EXT" else en
            raw_need = max(0.0, (big_u - sml_u) - float(trigger_diff_u))
            raw_need *= 0.8
            need = _round10(raw_need)
            need = min(float(need), float(cap_u))
            if need >= float(min_order_u):
                if sml_plat == "EXT":
                    if has_e:
                        side_s = str(_get_leg_side(snapshot, c, "EXT") or "").upper()
                        if side_s in ("LONG","SHORT"):
                            plans.append(("EXT", "increase", side_s, need, "diff_topup_short_leg"))
                    else:
                        side_v = str(_get_leg_side(snapshot, c, "VAR") or "").upper()
                        need_side = ("SHORT" if side_v == "LONG" else "LONG") if side_v in ("LONG","SHORT") else "LONG"
                        plans.append(("EXT", "add_leg", need_side, need, "diff_add_leg_short_leg"))
                else:
                    if has_v:
                        side_s = str(_get_leg_side(snapshot, c, "VAR") or "").upper()
                        if side_s in ("LONG","SHORT"):
                            plans.append(("VAR", "increase", side_s, need, "diff_topup_short_leg"))
                    else:
                        side_e = str(_get_leg_side(snapshot, c, "EXT") or "").upper()
                        need_side = ("SHORT" if side_e == "LONG" else "LONG") if side_e in ("LONG","SHORT") else "SHORT"
                        plans.append(("VAR", "add_leg", need_side, need, "diff_add_leg_short_leg"))

        dedup: dict[tuple[str,str,str], float] = {}
        why_map: dict[tuple[str,str,str], str] = {}
        for plat, act, side, amt, why in plans:
            if str(side or '').upper() not in _allow_x1:
                try:
                    _pin('X1', coin=c, stage='SKIP_PLAN', reason='rsi_side_block', plan_side=str(side), allow=list(_allow_x1), rsi=_rsi_x1, pivot=float(LEGACY_FIX_RSI_PIVOT))
                except Exception as _e:
                    _log_exc(mod="SYS", stage="EXC_PASS", e=_e)
                continue

            try:
                _amt0 = float(amt)
            except Exception:
                _amt0 = 0.0
            try:
                _amt_s, _x1_stage_det = _legacy_deleted_scale_amount_by_rsi(_amt0, str(side).upper(), _rsi_x1)
            except Exception:
                _amt_s, _x1_stage_det = float(_amt0), {}
            try:
                _amt1 = float(_round10(float(_amt_s)))
            except Exception:
                _amt1 = float(_amt_s)
            try:
                _amt1 = min(float(_amt1), float(cap_u))
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_893', _e)
                pass
            try:
                _amt1 = min(float(_amt1), float(diff_u))
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_894', _e)
                pass
            if float(_amt1) <= 0:
                continue
            if float(_amt1) < float(min_order_u):
                try:
                    _pin('X1', coin=c, stage='SKIP_PLAN', reason='scaled_amt_too_small', amt0=_amt0, amt=float(_amt1), min_order_u=float(min_order_u),
                         rsi=_rsi_x1, rsi_stage=(_x1_stage_det or {}).get('stage'), mult=(_x1_stage_det or {}).get('mult'))
                except Exception as _e:
                    _log_exc(mod="SYS", stage="EXC_PASS", e=_e)
                continue

            try:
                _stg = int((_x1_stage_det or {}).get('stage') or 0)
                _mul = float((_x1_stage_det or {}).get('mult') or 1.0)
                why = f"{str(why)}|rsi_stage{_stg}|mult{_mul:.2f}"
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_895', _e)
                pass
            amt = float(_amt1)

            k = (plat, act, side)
            if float(amt) <= 0:
                continue
            if (k not in dedup) or (float(amt) > float(dedup[k])):
                dedup[k] = float(amt)
                why_map[k] = str(why)

        for (plat, act, side), amt in dedup.items():
            act_l = str(act or "").lower()
            if act_l == "add_single" or act_l == "add":
                act_l = "increase"
            if act_l not in ("increase", "add_leg"):
                continue

            meta = {
                "legacy_fix_mode": True,
                "trigger_type": ("x1_total_min" if total_u < float(total_min_u) else "x1_diff"),
                "diff_abs": float(diff_u),
                "total_u": float(total_u),
                "planned_notional": float(amt),
                "why": why_map.get((plat, act, side), ""),
            }
            try:
                ok, why_cap, det_cap = _yingding_check(snapshot, list(coins or []), coin=str(c), platform=str(plat),
                                                      add_u=float(amt), module="X1", action_type=str(act_l))
                if not ok:
                    try:
                        safe_log(lambda: f"[{now_ts()}] [X1] CAP_BLOCK coin={c} plat={plat} side={side} amt={float(amt):.2f} why={why_cap} det={str(det_cap)[:180]}")
                    except Exception as _e:
                        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

                    continue
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

            try:
                req = SimpleNamespace(
                    module="X1",
                    coin=c,
                    platform=str(plat),
                    side=str(side),
                    action_type=str(act_l),
                    params={"platform": str(plat), "side": str(side), "amount_usd": float(amt), "legacy_fix_mode": True},
                    meta=meta,
                    priority=int(PRIORITY.get("LEGACY_DELETED", 50)),  # 复用修复优先级
                )
                out.append(Request.from_any(req))
            except Exception:
                try:
                    _pin('X1', coin=c, stage='PLAN', reason='append_request', plan={'platform': str(plat), 'act': str(act), 'side': str(side), 'u': float(amt), 'why': str(why)})
                except Exception as _e:
                    _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

                out.append(Request.from_any({
                    "module": "X1", "coin": c, "platform": str(plat), "side": str(side),
                    "action_type": str(act_l),
                    "params": {"platform": str(plat), "side": str(side), "amount_usd": float(amt), "legacy_fix_mode": True},
                    "meta": meta, "priority": int(PRIORITY.get("LEGACY_DELETED", 50)),
                }))
    return out

def _x1_run_after_round(cdp: str, *, snapshot: dict, coins: list[str], log_path: str,
                      delay_min_sec: int | None = None, delay_max_sec: int | None = None) -> list[dict]:
    """X1 已从源代码层面硬删除：静默返回，不打 BEGIN / MODULE_REMOVED，也绝不触发 m2_scan。"""
    return []

    try:
        dmin = int(cfg_getf_runtime("X1_DELAY_MIN_SEC", X1_DELAY_MIN_SEC) or X1_DELAY_MIN_SEC)
        dmax = int(cfg_getf_runtime("X1_DELAY_MAX_SEC", X1_DELAY_MAX_SEC) or X1_DELAY_MAX_SEC)
    except Exception:
        dmin, dmax = int(X1_DELAY_MIN_SEC), int(X1_DELAY_MAX_SEC)
    if delay_min_sec is not None:
        try: dmin = int(delay_min_sec)
        except Exception as _e:
            _record_swallowed_exception("x1.delay_min_cast", _e, delay_min_sec)
    if delay_max_sec is not None:
        try: dmax = int(delay_max_sec)
        except Exception as _e:
            _record_swallowed_exception("x1.delay_max_cast", _e, delay_max_sec)
    if dmin < 0: dmin = 0
    if dmax < dmin: dmax = dmin

    try:
        try:
            import random as _random
        except Exception:
            _random = None  # type: ignore
        _delay = int((_random.randint(int(dmin), int(dmax))) if _random else int(dmin))
    except Exception:
        _delay = int(dmin)

    try:
        _sleep_heartbeat(_delay, next_shijian="", interval_sec=10, fp_yunxing=None, reason=f"X1_DELAY_IN_SLEEP（X1延迟{_delay}s）")
    except Exception:
        try:
            try:
                _pin("SCHEDULED", mod="X1", coin="*", ok=1, reason=f"delay={_delay:.1f}s")
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_896', _e)
                pass
            time.sleep(float(_delay))
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    _mutex_acquired = False
    _mutex_hold_t0 = None
    try:

        try:

            _timeout = float(cfg_getf_runtime("SECONDARY_MUTEX_TIMEOUT_SEC", 1.5) or 1.5)

        except Exception:

            _timeout = 1.5

        _timeout = max(0.1, min(float(_timeout), 2.0))

        _wait0 = None

        try:

            _wait0 = time.time()

        except Exception as _e:
            _record_swallowed_exception('except_pass_line_897', _e)
            pass
        _timeout = max(0.1, min(float(_timeout), 2.0))

        _wait0 = None

        try:

            _pin("LOCK_WAIT", mod="X1", coin="*", ok=0, reason=f"timeout={_timeout:.0f}s")

        except Exception as _e:
            _record_swallowed_exception('except_pass_line_898', _e)
            pass
        _got = False

        try:

            _got = bool(_MAIN_X1_MUTEX.acquire(timeout=float(_timeout)))

        except TypeError:

            _MAIN_X1_MUTEX.acquire(); _got = True

        if not _got:

            try:

                _pin("LOCK_TIMEOUT", mod="X1", coin="*", ok=0, reason=f"timeout={_timeout:.0f}s")

            except Exception as _e:
                _record_swallowed_exception('except_pass_line_899', _e)
                pass
            return []

        try:

            if _wait0 is not None:

                _pin("LOCK_OK", mod="X1", coin="*", ok=1, reason=f"wait={time.time()-float(_wait0):.3f}s")

        except Exception as _e:
            _record_swallowed_exception('except_pass_line_900', _e)
            pass
        _mutex_acquired = True
        _mutex_hold_t0 = time.time()
    except Exception as _e:
        _log_exc(mod="MUTEX", stage="ACQUIRE_FAIL", e=_e, coin="*", who="X1")

    try:
        _t0_pin = time.time()
        try:
            _pin("SUB_START", mod="X1", coin="*", ok=1, reason="OK")
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

        snap2 = snapshot
        try:
            snap2 = m2_scan(cdp, list(coins or []), PEIZHI, seed=None, ind_mode="off") or snapshot
        except Exception:
            snap2 = snapshot

        try:
            reqs = _x1_build_requests(
                snap2, list(coins or []),
                trigger_diff_u=float(cfg_getf_runtime("X1_DIFF_TRIGGER_U", X1_DIFF_TRIGGER_U) or X1_DIFF_TRIGGER_U),
                total_min_u=float(cfg_getf_runtime("X1_TOTAL_MIN_U", X1_TOTAL_MIN_U) or X1_TOTAL_MIN_U),
                min_order_u=float(cfg_getf_runtime("X1_MIN_ORDER_U", X1_MIN_ORDER_U) or X1_MIN_ORDER_U),
                cap_u=float(cfg_getf_runtime("X1_CAP_U", X1_CAP_U) or X1_CAP_U),
            )
        except Exception:
            reqs = []

        if not reqs:
            try:
                write_jsonl(log_path, {"ts": now_ts(), "mod": "X1", "type": "X1_SKIP", "detail": {"why": "no_request_after_delay", "delay_sec": _delay}})
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

            return []

        try:
            try:
                _pin("SUB_ENQ", mod="X1", coin="*", ok=1, reason="OK", enq_n=len(reqs))
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

            res = _executor_run_quanbu_isolated(
                cdp,
                log_path=(log_path or (_rizhi_path("bot_run.jsonl") or "bot_run.jsonl")),
                snapshot=snap2,
                requests=reqs,
                coins=list(coins or []),
                exec_modules=set(["X1"]),
            )
        except Exception as e:
            try:
                write_jsonl(log_path, {"ts": now_ts(), "mod": "X1", "type": "X1_EXEC_ERR", "detail": {"err": repr(e), "delay_sec": _delay}})
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

            res = []

        return res if isinstance(res, list) else []
    finally:
        try:
            _pin("SUB_DONE", mod="X1", coin="*", ok=1, reason="OK", cost_sec=max(0.0, round(time.time()-float(locals().get("_t0_pin", time.time())), 3)))
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

        if _mutex_acquired:
            try:
                _MAIN_X1_MUTEX.release()
                try:
                    if _mutex_hold_t0 is not None:
                        _dt = time.time() - float(_mutex_hold_t0)
                        if _dt > 30.0:
                            _pin("LOCK_SLOW", mod="X1", coin="*", ok=1, reason=f"{_dt:.1f}s")
                except Exception as _e2:
                    _log_exc(mod="MUTEX", stage="HOLD_DUR_FAIL", e=_e2, coin="*", who="X1")
            except Exception as _e:
                _log_exc(mod="MUTEX", stage="RELEASE_FAIL", e=_e, coin="*", who="X1")

def _legacy_only_should_block(req: Any) -> bool:
    return False

def _z1_tp_build_request(snapshot: dict, coin: str) -> tuple[dict | None, dict]:
    """Z1（止盈兜底）为单币生成 0/1 个请求（B2 或 M10），并返回 summary 细节。
    设计原则：
    - 这里只对 B2/M10 自身的双腿结构做硬判断：缺腿 / 同向 / 方向缺失 才直接跳过
    - 全局结构差额（EXT/VAR gap）仅做观测与解释，不再把 B2/M10 作为强门禁拦掉
    - 先 B2（合计盈利触发全平），后 M10（盈利腿触发温和止盈）
    - 只生成“你现有稳定执行器能识别”的请求，不改执行器点击链路
    """
    coin_u = str(coin or '').upper().strip()
    det: dict = {}
    out_req: dict | None = None

    struct_ok = False
    fail_reason = ""
    try:
        stc, d = classify_state_detail(snapshot, coin_u)
        det.update(d or {})

        ext_has = bool((d or {}).get('ext_has'))
        var_has = bool((d or {}).get('var_has'))
        ext_side = str((d or {}).get('ext_side') or '').upper().strip()
        var_side = str((d or {}).get('var_side') or '').upper().strip()

        try:
            ext_n = float((d or {}).get('ext_notional_u') or 0.0)
        except Exception:
            ext_n = 0.0
        try:
            var_n = float((d or {}).get('var_notional_u') or 0.0)
        except Exception:
            var_n = 0.0

        struct_mode = "HARD"
        tiny_leg_plat = ""
        soft_ratio = _small_leg_ratio(ext_n, var_n)

        if ext_has and var_has:
            if (not ext_side) or (not var_side):
                fail_reason = 'missing_side'
            elif ext_side == var_side:
                fail_reason = 'same_dir'
            else:
                struct_ok = True
        else:
            fail_reason = 'missing_leg'

        det.update({
            "struct_mode": struct_mode,
            "small_leg_ratio": float(soft_ratio),
            "tiny_leg_plat": tiny_leg_plat,
            "ext_notional_u": float(ext_n),
            "var_notional_u": float(var_n),
        })

    except Exception as e:
        struct_ok = False
        fail_reason = f'classify_exc:{repr(e)}'

    truth = _tpm10_coin_truth(snapshot, coin_u)
    ext_upnl_u = float(truth.get('ext_upnl_u') or 0.0)
    var_upnl_u = float(truth.get('var_upnl_u') or 0.0)
    net_u_sum = float(ext_upnl_u + var_upnl_u)
    ext_notional_u = float(truth.get('ext_notional_u') or 0.0)
    var_notional_u = float(truth.get('var_notional_u') or 0.0)
    loss_plat = str(truth.get('loss_plat') or ('EXT' if ext_upnl_u <= var_upnl_u else 'VAR'))
    profit_plat = str(truth.get('profit_plat') or ('EXT' if ext_upnl_u >= var_upnl_u else 'VAR'))
    loss_u = float(truth.get('loss_u') or 0.0)
    profit_u = float(truth.get('profit_u') or 0.0)
    profit_notional = float(truth.get('profit_notional') or 0.0)
    loss_notional = float(truth.get('loss_notional') or max(ext_notional_u, var_notional_u))

    _trigger_pct_used, _trigger_det = _coin_unified_trigger_pct(coin_u, default=_tp_trigger_floor_pct(coin_u), floor_override=_tp_trigger_floor_pct(coin_u), cap_override=_tp_trigger_cap_pct(coin_u), trigger_tag='B2_M10')
    b2_threshold = _b2_trigger_need_u_for_coin(coin_u, loss_notional, default=0.01)
    _m10_trigger_need_obs_u = _m10_trigger_need_u_for_coin(coin_u, loss_notional, snapshot=snapshot, coins=None, default=0.01)
    m10_profit_min_u = float(cfg_getf_runtime("M10_PROFIT_MIN_U", cfg_getf_runtime("B2_TREND_PROFIT_MIN_U", cfg_getf_runtime("TREND_TP_PROFIT_MIN_U", 1.0))) or 1.0)
    if m10_profit_min_u < 0:
        m10_profit_min_u = 0.0
    m10_profit_leg_pct = 0.01
    m10_profit_leg_need_u = float(max(0.0, profit_notional) * m10_profit_leg_pct)
    m10_threshold = float(max(m10_profit_min_u, m10_profit_leg_need_u))

    summary = {
        'coin': coin_u,
        'ext_has': bool((det or {}).get('ext_has')),
        'var_has': bool((det or {}).get('var_has')),
        'ext_side': str((det or {}).get('ext_side') or '').upper().strip(),
        'var_side': str((det or {}).get('var_side') or '').upper().strip(),
        'req_module': None,
        'req_action': None,
        'req_platform': None,
        'struct_state': ('SOFT_OK' if (struct_ok and str((det or {}).get('struct_mode') or '').upper()=='SOFT') else ('OK' if struct_ok else 'FAIL')) ,
        'fail_reason': fail_reason,
        'struct_mode': str((det or {}).get('struct_mode') or ''),
        'small_leg_ratio': float((det or {}).get('small_leg_ratio') or 0.0),
        'tiny_leg_plat': str((det or {}).get('tiny_leg_plat') or ''),
        'ext_upnl_u': ext_upnl_u,
        'var_upnl_u': var_upnl_u,
        'net_u_sum': net_u_sum,
        'profit_plat': profit_plat,
        'profit_u': profit_u,
        'loss_plat': loss_plat,
        'loss_u': loss_u,
        'ext_notional_u': ext_notional_u,
        'var_notional_u': var_notional_u,
        'profit_notional': profit_notional,
        'loss_notional': loss_notional,
        'b2_threshold': b2_threshold,
        'm10_threshold': m10_threshold,
        'm10_profit_min_u': float(m10_profit_min_u),
        'm10_profit_leg_pct': float(m10_profit_leg_pct),
        'm10_profit_leg_need_u': float(m10_profit_leg_need_u),
        'm10_trigger_need_obs_u': float(_m10_trigger_need_obs_u or 0.0),
        'm10_threshold_basis': 'max_profit_min_u_or_profit_leg_notional_1pct',
        'trigger_pct_used': float(_trigger_pct_used or 0.0),
        'trigger_floor_pct': _safe_float((_trigger_det or {}).get('trigger_floor_pct'), None),
        'vol24h_pct': _safe_float((_trigger_det or {}).get('vol24h_pct'), None),
        'trigger_raw_pct': _safe_float((_trigger_det or {}).get('raw_trigger_pct'), None),
        'trigger_source': str((_trigger_det or {}).get('src') or ''),
        'trigger_formula': str((_trigger_det or {}).get('formula') or ''),
        'trigger_calc_text': f"M10触发门槛=max({float(m10_profit_min_u):.2f}U, 盈利腿名义{float(max(0.0, profit_notional)):.2f}U × 1%={float(m10_profit_leg_need_u):.2f}U)={float(m10_threshold):.2f}U；旧的近24h波动触发百分比仅保留观测，不再参与M10触发拦截。观测值：近24h波动={_m9_fmt_pct_text(_safe_float((_trigger_det or {}).get('vol24h_pct'), None) * 100.0 if (_trigger_det or {}).get('vol24h_pct') is not None else None)} × 10% -> 原始触发={_m9_fmt_pct_text(_safe_float((_trigger_det or {}).get('raw_trigger_pct'), None) * 100.0 if (_trigger_det or {}).get('raw_trigger_pct') is not None else None)} -> 地板={_m9_fmt_pct_text(_safe_float((_trigger_det or {}).get('trigger_floor_pct'), None) * 100.0 if (_trigger_det or {}).get('trigger_floor_pct') is not None else None)} -> 观测触发={_m9_fmt_pct_text(float(_trigger_pct_used or 0.0) * 100.0)}",
        'branch': 'SKIP',
        'reason': '',
        'truth_source': 'tpm10_coin_truth',
        'ext_side_source': str((truth.get('ext') or {}).get('side_source') or ''),
        'var_side_source': str((truth.get('var') or {}).get('side_source') or ''),
    }

    if not struct_ok:
        summary['reason'] = f'struct_fail:{fail_reason}'
        return None, summary

    try:
        if _in_tp_lock(coin_u):
            summary['reason'] = 'tp_lock_cooldown'
            return None, summary
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    _trend_guard = _trend_alpha_guard_for_b2_m10(snapshot, coin_u) or {}
    summary['trend_guard'] = dict(_trend_guard)

    if float(net_u_sum) > float(b2_threshold) + 1e-9:
        if bool(_trend_guard.get('active')):
            summary['branch'] = 'B2_BLOCK'
            summary['reason'] = 'b2_blocked_by_trend_alpha'
            return None, summary
        summary['branch'] = 'B2'
        summary['reason'] = 'net_u_sum_gt_b2_threshold'
        out_req = {
            'module': 'B2',
            'coin': coin_u,
            'platform': 'BOTH',
            'action_type': 'close_pair',
            'params': {
                            'src': 'Z1', 'rule': 'b2', 'loss_notional': float(loss_notional), 'net_u_sum': float(net_u_sum),
                            'trend_guard': dict(_trend_guard), 'trend_state': str(_trend_guard.get('trend_state') or ''),
                            'trend_side': str(_trend_guard.get('trend_side') or '')},
        }
        out_req = _apply_b1_m9_b2_m10_unified_contract(out_req, snapshot=snapshot)
        summary['req_module']=out_req.get('module')
        summary['req_action']=out_req.get('action_type')
        summary['req_platform']=out_req.get('platform')
        return out_req, summary

    _thr = max(1.0, float(m10_threshold))
    if (profit_u > 0.0) and (loss_u < 0.0) and (profit_u > _thr + 1e-9) and ( (str((det or {}).get('struct_mode') or '').upper() != 'SOFT') or (_small_leg_ratio(ext_notional_u, var_notional_u) >= float(B2M10_SMALL_LEG_MIN_RATIO) - 1e-12) ) :
        if bool((_trend_guard or {}).get('active')) and bool((_trend_guard or {}).get('runner_protect')):
            summary['branch'] = 'M10_BLOCK'
            summary['reason'] = 'm10_runner_protected'
            summary['m10_cap_pct'] = 0.0
            return None, summary
        summary['branch'] = 'M10'
        summary['reason'] = 'profit_u_gt_m10_threshold'
        out_req = {
            'module': 'M10',
            'coin': coin_u,
            'platform': 'BOTH',
            'action_type': 'koujing_a_3step',  # 复用你现有稳定执行器（M10 三步）
            'params': {'src': 'Z1', 'rule': 'm10', 'loss_notional': float(loss_notional), 'profit_u': float(profit_u),
                       'trend_guard': dict(_trend_guard), 'trend_state': str(_trend_guard.get('trend_state') or ''),
                       'trend_side': str(_trend_guard.get('trend_side') or ''), 'trend_runner_protect': int(bool(_trend_guard.get('runner_protect'))),
                       'trend_alpha_cap_pct': 0.0 if bool((_trend_guard or {}).get('active')) else None},
        }
        out_req = _apply_b1_m9_b2_m10_unified_contract(out_req, snapshot=snapshot)
        summary['req_module']=out_req.get('module')
        summary['req_action']=out_req.get('action_type')
        summary['req_platform']=out_req.get('platform')
        return out_req, summary

    summary['reason'] = 'no_hit'
    return None, summary


def _build_m10_fallback_request_after_b2_reject(snapshot: dict, coin: str, *, source_req: Any = None) -> tuple[dict | None, dict]:
    """当 B2 先赢仲裁、但执行前被趋势保护拦掉时，同轮补跑一次 M10。"""
    coin_u = str(coin or '').upper().strip()
    summary = {'coin': coin_u, 'reason': '', 'branch': 'SKIP', 'req_module': None}
    try:
        req, det = _z1_tp_build_request(snapshot, coin_u)
        if isinstance(det, dict):
            summary.update(det)
        if isinstance(req, dict) and str(req.get('module') or '').upper().strip() == 'M10':
            req.setdefault('params', {})
            req.setdefault('meta', {})
            if isinstance(req.get('meta'), dict):
                req['meta']['fallback_from_b2_reject'] = True
                req['meta']['fallback_reason'] = 'b2_rejected_same_round'
            summary['reason'] = 'reuse_z1_m10_after_b2_reject'
            return req, summary

        st = _postcheck_extract_coin_state(snapshot, coin_u) or {}
        ext_upnl_u = float(st.get('ext_upnl_u', 0.0) or 0.0)
        var_upnl_u = float(st.get('var_upnl_u', 0.0) or 0.0)
        ext_notional_u = float(st.get('ext_notional_u', 0.0) or 0.0)
        var_notional_u = float(st.get('var_notional_u', 0.0) or 0.0)

        profit_plat = 'EXT' if ext_upnl_u >= var_upnl_u else 'VAR'
        loss_plat = 'EXT' if ext_upnl_u <= var_upnl_u else 'VAR'
        profit_u = float(ext_upnl_u if profit_plat == 'EXT' else var_upnl_u)
        loss_u = float(ext_upnl_u if loss_plat == 'EXT' else var_upnl_u)
        profit_notional = float(ext_notional_u if profit_plat == 'EXT' else var_notional_u)

        _stc, d = classify_state_detail(snapshot, coin_u)
        d = dict(d or {})
        ext_has = bool(d.get('ext_has'))
        var_has = bool(d.get('var_has'))
        ext_side = str(d.get('ext_side') or '').upper().strip()
        var_side = str(d.get('var_side') or '').upper().strip()
        struct_ok = bool(ext_has and var_has and ext_side and var_side and ext_side != var_side)
        small_leg_ratio = float(_small_leg_ratio(ext_notional_u, var_notional_u))
        m10_profit_min_u = float(cfg_getf_runtime('M10_PROFIT_MIN_U', cfg_getf_runtime('B2_TREND_PROFIT_MIN_U', cfg_getf_runtime('TREND_TP_PROFIT_MIN_U', 1.0))) or 1.0)
        if m10_profit_min_u < 0:
            m10_profit_min_u = 0.0
        m10_profit_leg_need_u = float(max(0.0, profit_notional) * 0.01)
        m10_threshold = float(max(m10_profit_min_u, m10_profit_leg_need_u))
        summary.update({
            'profit_u': float(profit_u),
            'loss_u': float(loss_u),
            'profit_notional': float(profit_notional),
            'm10_threshold': float(m10_threshold),
            'small_leg_ratio': float(small_leg_ratio),
            'struct_state': 'OK' if struct_ok else 'FAIL',
        })
        if not struct_ok:
            summary['reason'] = 'fallback_struct_fail'
            return None, summary
        if not ((profit_u > 0.0) and (loss_u < 0.0) and (profit_u > m10_threshold + 1e-9) and (small_leg_ratio >= float(B2M10_SMALL_LEG_MIN_RATIO) - 1e-12)):
            summary['reason'] = 'fallback_m10_not_hit'
            return None, summary

        req = {
            'module': 'M10',
            'coin': coin_u,
            'platform': 'BOTH',
            'action_type': 'koujing_a_3step',
            'params': {
                'src': 'Z1_FALLBACK',
                'rule': 'm10_after_b2_reject',
                'loss_notional': float(ext_notional_u if loss_plat == 'EXT' else var_notional_u),
                'profit_u': float(profit_u),
                'fallback_from_b2_reject': True,
                'fallback_same_round': True,
            },
            'meta': {
                'fallback_from_b2_reject': True,
                'fallback_same_round': True,
                'fallback_reason': 'b2_rejected_same_round',
            }
        }
        req = _apply_b1_m9_b2_m10_unified_contract(req, snapshot=snapshot)
        summary['branch'] = 'M10'
        summary['reason'] = 'fallback_m10_after_b2_reject'
        summary['req_module'] = 'M10'
        return req, summary
    except Exception as _e:
        summary['reason'] = f'fallback_exc:{type(_e).__name__}'
        summary['err'] = repr(_e)
        return None, summary


_TP_DECISION_LINE_LAST: Dict[str, str] = {}

def _tp_decision_leg_text(platform: Any, side: Any, upnl_u: Any, notional_u: Any) -> str:
    plat = str(platform or '-').upper().strip() or '-'
    sd = str(side or '-').upper().strip() or '-'
    try:
        pu = float(_safe_float(upnl_u, 0.0) or 0.0)
    except Exception:
        pu = 0.0
    try:
        nu = float(_safe_float(notional_u, 0.0) or 0.0)
    except Exception:
        nu = 0.0
    return f"{plat}/{sd}/upnl={pu:.2f}U/notional={nu:.2f}U"

def _tp_decision_profit_rate_text(summary: dict | None) -> str:
    summ = dict(summary or {})
    try:
        profit_u = float(_safe_float(summ.get('profit_u'), 0.0) or 0.0)
    except Exception:
        profit_u = 0.0
    try:
        profit_notional = float(_safe_float(summ.get('profit_notional'), 0.0) or 0.0)
    except Exception:
        profit_notional = 0.0
    if profit_notional > 1e-9:
        return f"{(profit_u / profit_notional) * 100.0:.2f}%({profit_u:.2f}U/{profit_notional:.2f}U)"
    return f"-({profit_u:.2f}U/{profit_notional:.2f}U)"

def _tp_decision_struct_text(snapshot_any: Any, coin: str, summary: dict | None) -> str:
    summ = dict(summary or {})
    pair_state = str(summ.get('struct_state') or 'FAIL').upper().strip() or 'FAIL'
    snapd = _snapshot_to_dict_compat(snapshot_any)
    coin_u = str(coin or summ.get('coin') or '').upper().strip()
    safe_gap_u = float(globals().get('SAFE_GAP_U', 0.0) or 0.0)
    ext_n = 0.0
    var_n = 0.0
    try:
        coins_root = snapd.get('coins') if isinstance(snapd.get('coins'), dict) else snapd
        cd = coins_root.get(coin_u) if isinstance(coins_root, dict) else {}
        ext = cd.get('EXT') or cd.get('ext') or {}
        var = cd.get('VAR') or cd.get('var') or {}
        ext_n = float(_safe_float((ext or {}).get('value_usd') or (ext or {}).get('notional_u'), 0.0) or 0.0)
        var_n = float(_safe_float((var or {}).get('value_usd') or (var or {}).get('notional_u'), 0.0) or 0.0)
    except Exception:
        ext_n = float(_safe_float(summ.get('ext_notional_u'), 0.0) or 0.0)
        var_n = float(_safe_float(summ.get('var_notional_u'), 0.0) or 0.0)
    gap = abs(ext_n - var_n)
    total_notional = max(0.0, ext_n + var_n)
    dyn_th = max(float(safe_gap_u or 0.0), total_notional * 0.02, 50.0)
    hard_th = float(dyn_th + max(10.0, dyn_th * 0.10))
    global_state = 'OK' if gap <= hard_th + 1e-9 else 'OBSERVE'
    return f"pair={pair_state};global={global_state}(gap={gap:.2f}U/hard={hard_th:.2f}U)"

def _tp_decision_cooldown_text(coin: str, summary: dict | None) -> str:
    summ = dict(summary or {})
    rsn = str(summ.get('reason') or '').strip()
    if rsn == 'tp_lock_cooldown':
        return '是'
    try:
        return '是' if bool(_in_tp_lock(str(coin or summ.get('coin') or '').upper().strip())) else '否'
    except Exception:
        return '否'

def _tp_decision_final_reason_text(summary: dict | None, req: Any = None) -> str:
    summ = dict(summary or {})
    if isinstance(req, dict):
        mod = str(req.get('module') or summ.get('req_module') or '').upper().strip() or '-'
        act = str(req.get('action_type') or summ.get('req_action') or '').strip() or '-'
        return f"无（已生成 {mod}/{act}）"
    rsn = str(summ.get('reason') or '').strip()
    if not rsn:
        return '无（未写明）'
    human = _reason_human_text(rsn)
    return f"{rsn}（{human}）" if human else rsn

def _tp_decision_emit_line(snapshot_any: Any, coin: str, summary: dict | None, req: Any = None) -> None:
    summ = dict(summary or {})
    coin_u = str(coin or summ.get('coin') or '').upper().strip()
    if not coin_u:
        return
    snapd = _snapshot_to_dict_compat(snapshot_any)
    snap_ts = str((snapd or {}).get('ts') or summ.get('snapshot_ts') or '')
    win_leg = _tp_decision_leg_text(summ.get('profit_plat'), summ.get('ext_side') if str(summ.get('profit_plat') or '').upper().strip() == 'EXT' else summ.get('var_side'), summ.get('profit_u'), summ.get('profit_notional'))
    loss_leg = _tp_decision_leg_text(summ.get('loss_plat'), summ.get('ext_side') if str(summ.get('loss_plat') or '').upper().strip() == 'EXT' else summ.get('var_side'), summ.get('loss_u'), summ.get('loss_notional'))
    profit_rate = _tp_decision_profit_rate_text(summ)
    struct_text = _tp_decision_struct_text(snapd, coin_u, summ)
    cooldown_text = _tp_decision_cooldown_text(coin_u, summ)
    final_reason = _tp_decision_final_reason_text(summ, req=req)
    branch = str(summ.get('branch') or '-').upper().strip() or '-'
    req_mod = str((req or {}).get('module') or summ.get('req_module') or '-').upper().strip() if isinstance(req, dict) else str(summ.get('req_module') or '-').upper().strip()
    req_act = str((req or {}).get('action_type') or summ.get('req_action') or '-').strip() if isinstance(req, dict) else str(summ.get('req_action') or '-').strip()
    line = (
        f"[{now_ts()}] [TP逐币] 币种={coin_u} | 盈利腿={win_leg} | 亏损腿={loss_leg} | "
        f"利润率={profit_rate} | 结构安全={struct_text} | 冷却={cooldown_text} | "
        f"最终拒绝原因={final_reason} | 分支={branch} | 请求={req_mod}/{req_act}"
    )
    cache_key = f"{snap_ts}|{coin_u}|{win_leg}|{loss_leg}|{profit_rate}|{struct_text}|{cooldown_text}|{final_reason}|{branch}|{req_mod}|{req_act}"
    try:
        last_key = str((_TP_DECISION_LINE_LAST or {}).get(coin_u) or '')
    except Exception:
        last_key = ''
    if last_key == cache_key:
        return
    try:
        _TP_DECISION_LINE_LAST[coin_u] = cache_key
    except Exception:
        pass
    try:
        safe_log(lambda: line)
    except Exception:
        try:
            print(line)
        except Exception:
            pass
    try:
        _pin('TP_PER_COIN', mod='TP', coin=coin_u, ok=int(1 if isinstance(req, dict) else 0), stage='DECIDE',
             reason=str(summ.get('reason') or ''), profit_plat=str(summ.get('profit_plat') or ''),
             loss_plat=str(summ.get('loss_plat') or ''), profit_u=float(_safe_float(summ.get('profit_u'), 0.0) or 0.0),
             loss_u=float(_safe_float(summ.get('loss_u'), 0.0) or 0.0), profit_notional=float(_safe_float(summ.get('profit_notional'), 0.0) or 0.0),
             loss_notional=float(_safe_float(summ.get('loss_notional'), 0.0) or 0.0), struct_state=str(summ.get('struct_state') or ''),
             struct_text=str(struct_text), cooldown=str(cooldown_text), req_mod=str(req_mod or ''), req_act=str(req_act or ''),
             ext_side=str(summ.get('ext_side') or ''), var_side=str(summ.get('var_side') or ''),
             ext_side_source=str(summ.get('ext_side_source') or ''), var_side_source=str(summ.get('var_side_source') or ''),
             truth_source=str(summ.get('truth_source') or ''))
    except Exception:
        pass


def _m10_materialize_group_payload(req: dict, snapshot: dict | None = None) -> dict:
    """把 M10 三步组请求的 steps / close_notional / GROUP 平台物理补齐。
    人话：不允许 koujing_a_3step 只剩一个空壳进门禁；必须把三步明细显式塞到
    - 顶层 req["steps"]
    - req["params"]["steps"]
    - req["group_request"]["steps"]
    - req["meta"]["extras"]["steps"]
    这样下游任何一条旧链/兼容链都能读到同一份真相。
    """
    try:
        if not isinstance(req, dict):
            return req
        if str(req.get("module") or "").upper().strip() != "M10":
            return req
        act = str(req.get("action_type") or req.get("action") or "").lower().strip()
        if act != "koujing_a_3step":
            return req

        snap = snapshot or {}
        params = req.get("params") if isinstance(req.get("params"), dict) else {}
        meta = req.get("meta") if isinstance(req.get("meta"), dict) else {}
        extras = meta.get("extras") if isinstance(meta.get("extras"), dict) else {}

        def _pick_steps(obj: Any) -> list:
            if isinstance(obj, list) and obj:
                return [dict(x) if isinstance(x, dict) else x for x in obj]
            return []

        steps = []
        for cand in (
            req.get("steps"),
            params.get("steps"),
            (params.get("params") or {}).get("steps") if isinstance(params.get("params"), dict) else None,
            req.get("plan"),
            params.get("plan"),
            (req.get("group_request") or {}).get("steps") if isinstance(req.get("group_request"), dict) else None,
            (req.get("group_request") or {}).get("plan") if isinstance(req.get("group_request"), dict) else None,
            extras.get("steps"),
            extras.get("plan"),
        ):
            steps = _pick_steps(cand)
            if steps:
                break

        if not steps:
            try:
                rebuilt = _m10_synthesize_steps_from_snapshot_req(req, snap)
            except Exception:
                rebuilt = req
            if isinstance(rebuilt, dict):
                req = rebuilt
                params = req.get("params") if isinstance(req.get("params"), dict) else {}
                meta = req.get("meta") if isinstance(req.get("meta"), dict) else {}
                extras = meta.get("extras") if isinstance(meta.get("extras"), dict) else {}
                for cand in (
                    req.get("steps"),
                    params.get("steps"),
                    (params.get("params") or {}).get("steps") if isinstance(params.get("params"), dict) else None,
                    req.get("plan"),
                    params.get("plan"),
                    (req.get("group_request") or {}).get("steps") if isinstance(req.get("group_request"), dict) else None,
                    extras.get("steps"),
                ):
                    steps = _pick_steps(cand)
                    if steps:
                        break

        if steps:
            req["steps"] = list(steps)
            params["steps"] = list(steps)
            params.setdefault("plan", list(steps))
            req["group_request"] = {"steps": list(steps), "plan": list(steps)}
            extras["steps"] = list(steps)
            extras.setdefault("plan", list(steps))
            meta["extras"] = extras
            meta["M10__has_steps"] = 1
            meta["M10__steps_len"] = int(len(steps))
            req["platform"] = "GROUP"
            params["platform"] = "GROUP"
            meta["platform"] = "GROUP"
            try:
                close_u = float(_tp_extract_loss_close_notional_u(steps, "") or 0.0)
            except Exception:
                close_u = 0.0
            if close_u <= 0.0:
                for st in steps:
                    try:
                        a = str(st.get("action") or st.get("action_type") or "").lower().strip()
                    except Exception:
                        a = ""
                    if a in ("close_partial_notional", "close_partial", "close_notional", "close_loss_partial", "close_loss_part", "decrease", "reduce"):
                        try:
                            close_u = float(
                                st.get("close_notional_u")
                                or st.get("target_notional_u")
                                or st.get("target_notional")
                                or st.get("notional_u")
                                or st.get("amount_usd")
                                or st.get("usd")
                                or 0.0
                            )
                        except Exception:
                            close_u = 0.0
                        if close_u > 0.0:
                            break
            if close_u > 0.0:
                req["amount_usd"] = float(close_u)
                req["amount_u"] = float(close_u)
                req["notional_u"] = float(close_u)
                params["amount_usd"] = float(close_u)
                params["amount_u"] = float(close_u)
                params["close_notional_u"] = float(close_u)
                params["notional_u"] = float(close_u)
                meta["M10__amount_usd"] = float(close_u)
                meta["M10__close_notional_u"] = float(close_u)
            try:
                for st in steps:
                    a = str(st.get("action") or st.get("action_type") or "").lower().strip()
                    s = normalize_side(st.get("side"))
                    if a in ("close_full", "close_all", "close") and s in ("LONG", "SHORT"):
                        req["side"] = s
                        params["side"] = s
                        meta["side"] = s
                        break
            except Exception:
                pass

        req["params"] = params
        req["meta"] = meta
        return req
    except Exception:
        return req




def _selftest_m10_full_flow_contract() -> dict:
    """M10 全流程自测：候选组请求 -> sanitize -> unified -> fill_required -> GO gate -> submit_queue。
    目标：把“能发请求”与“进 GO gate 时仍带完整三步 contract”一次性对拍清楚。
    """
    rep: dict[str, Any] = {'name': 'm10_full_flow_contract', 'ok': False, 'steps': {}, 'error': ''}
    try:
        coin = 'ZEC'
        snapshot = {
            'ts': float(time.time()),
            'scan_id': 'SELFTEST_M10_FULL_FLOW',
            'data_quality': 'ok',
            'data_quality_reason': '',
            'dq_reason': '',
            'ctl': {},
            'indicators': {coin: {'rsi': 55.0, 'adx': 20.0, 'reason': 'selftest'}},
            'positions': {
                'EXT': {coin: {'side': 'SHORT', 'notional_u': 1434.13, 'value_usd': 1434.13, 'upnl_usd': 23.63, 'upnl_u': 23.63, 'has_position': True}},
                'VAR': {coin: {'side': 'LONG', 'notional_u': 1538.49, 'value_usd': 1538.49, 'upnl_usd': -287.47, 'upnl_u': -287.47, 'has_position': True}},
            },
            'coins': {
                coin: {
                    'EXT': {'side': 'SHORT', 'notional_u': 1434.13, 'value_usd': 1434.13, 'upnl_usd': 23.63, 'upnl_u': 23.63, 'has_position': True},
                    'VAR': {'side': 'LONG', 'notional_u': 1538.49, 'value_usd': 1538.49, 'upnl_usd': -287.47, 'upnl_u': -287.47, 'has_position': True},
                }
            },
        }
        summary = {
            'coin': coin,
            'branch': 'M10',
            'reason': 'profit_u_gt_m10_threshold',
            'profit_plat': 'EXT',
            'loss_plat': 'VAR',
            'profit_u': 23.63,
            'loss_u': -287.47,
            'profit_notional': 1434.13,
            'loss_notional': 1538.49,
            'm10_threshold': 15.38,
            'struct_state': 'OK',
        }
        req0 = _m10_group_request_from_summary(snapshot, coin, summary)
        rep['steps']['group_request_from_summary'] = {
            'ok': bool(isinstance(req0, dict) and str(req0.get('module') or '').upper() == 'M10' and str(req0.get('action_type') or '').lower() == 'koujing_a_3step'),
            'steps_len': int(len((req0 or {}).get('steps') or [])) if isinstance(req0, dict) else 0,
            'params_steps_len': int(len((((req0 or {}).get('params') or {}).get('steps') or []))) if isinstance(req0, dict) else 0,
            'platform': str((req0 or {}).get('platform') or '') if isinstance(req0, dict) else '',
        }
        if not rep['steps']['group_request_from_summary']['ok']:
            raise AssertionError('group_request_from_summary_failed')

        rq = RequestQueue(_rizhi_path('m10_full_flow_selftest_queue.jsonl'))
        menhu = GOMenHu(rq, snapshot, [coin])
        req1 = menhu._contract_sanitize(dict(req0))
        rep['steps']['contract_sanitize'] = {
            'steps_len': int(len((req1 or {}).get('steps') or [])),
            'params_steps_len': int(len((((req1 or {}).get('params') or {}).get('steps') or []))),
            'platform': str((req1 or {}).get('platform') or ''),
        }
        req2 = _apply_b1_m9_b2_m10_unified_contract(dict(req1), snapshot=snapshot)
        rep['steps']['unified_contract'] = {
            'steps_len': int(len((req2 or {}).get('steps') or [])),
            'params_steps_len': int(len((((req2 or {}).get('params') or {}).get('steps') or []))),
            'platform': str((req2 or {}).get('platform') or ''),
        }
        try:
            req3 = _executor_enrich_request_contract(dict(req2), snapshot=snapshot)
        except Exception:
            req3 = dict(req2)
        req4 = _m10_fill_required_fields(dict(req3), snapshot)
        rep['steps']['fill_required_fields'] = {
            'steps_len': int(len((req4 or {}).get('steps') or [])),
            'params_steps_len': int(len((((req4 or {}).get('params') or {}).get('steps') or []))),
            'group_steps_len': int(len((((req4 or {}).get('group_request') or {}).get('steps') or []))) if isinstance((req4 or {}).get('group_request'), dict) else 0,
            'close_notional_u': float((((req4 or {}).get('params') or {}).get('close_notional_u') or 0.0) or 0.0),
            'platform': str((req4 or {}).get('platform') or ''),
        }
        ok_gate, gate_reason = menhu._gate_check_and_stamp(dict(req4))
        rep['steps']['gate_check'] = {'ok': bool(ok_gate), 'reason': str(gate_reason or '')}
        if not ok_gate:
            raise AssertionError(f'gate_failed:{gate_reason}')

        rid = menhu.submit_request(dict(req4))
        rep['steps']['submit_request'] = {
            'request_id': str(rid or ''),
            'queue_len': int(len(getattr(rq, 'items', []) or [])),
            'probe_events': int(len(getattr(menhu, '_probe_events', []) or [])),
        }
        if not str(rid or '').strip():
            raise AssertionError('submit_request_empty')
        if not (len(getattr(rq, 'items', []) or []) >= 1):
            raise AssertionError('queue_empty_after_submit')
        try:
            qd = rq.items[-1].to_dict()
        except Exception:
            qd = {}
        rep['steps']['queued_request'] = {
            'steps_len': int(len((qd or {}).get('steps') or [])) if isinstance(qd, dict) else 0,
            'params_steps_len': int(len((((qd or {}).get('params') or {}).get('steps') or []))) if isinstance(qd, dict) else 0,
            'platform': str((qd or {}).get('platform') or '') if isinstance(qd, dict) else '',
            'close_notional_u': float((((qd or {}).get('params') or {}).get('close_notional_u') or 0.0) or 0.0) if isinstance(qd, dict) else 0.0,
        }
        if not (rep['steps']['queued_request']['steps_len'] >= 3 and rep['steps']['queued_request']['params_steps_len'] >= 3 and rep['steps']['queued_request']['close_notional_u'] > 0):
            raise AssertionError('queued_request_contract_broken')
        rep['ok'] = True
        return rep
    except Exception as e:
        rep['error'] = f'{type(e).__name__}:{e}'
        return rep

def _selftest_m10_realized_loss_half_win_bypass() -> dict:
    """确认 M10 不再被 realized_loss > half_win 单独拦截；只要净收益仍为正，就不能因为 half_win 单独拒绝。"""
    rep: dict[str, Any] = {'name': 'm10_realized_loss_half_win_bypass', 'ok': False, 'reason': '', 'abs_realized': 0.0, 'half_win': 0.0, 'net_u': 0.0}
    try:
        coin = 'HYPE'
        snapshot = {
            'ts': float(time.time()),
            'data_quality': 'ok',
            'positions': {
                'EXT': {coin: {'side': 'SHORT', 'notional_u': 2201.91, 'value_usd': 2201.91, 'upnl_usd': 47.00, 'upnl_u': 47.00, 'has_position': True}},
                'VAR': {coin: {'side': 'LONG', 'notional_u': 2605.60, 'value_usd': 2605.60, 'upnl_usd': -520.00, 'upnl_u': -520.00, 'has_position': True}},
            },
            'coins': {
                coin: {
                    'EXT': {'side': 'SHORT', 'notional_u': 2201.91, 'value_usd': 2201.91, 'upnl_usd': 47.00, 'upnl_u': 47.00, 'has_position': True},
                    'VAR': {'side': 'LONG', 'notional_u': 2605.60, 'value_usd': 2605.60, 'upnl_usd': -520.00, 'upnl_u': -520.00, 'has_position': True},
                }
            },
            'indicators': {coin: {'rsi': 55.0, 'adx': 20.0, 'reason': 'selftest'}},
        }
        req = _m10_group_request_from_summary(snapshot, coin, {
            'coin': coin,
            'branch': 'M10',
            'reason': 'profit_u_gt_m10_threshold',
            'profit_plat': 'EXT',
            'loss_plat': 'VAR',
            'profit_u': 47.00,
            'loss_u': -520.00,
            'profit_notional': 2201.91,
            'loss_notional': 2605.60,
            'm10_threshold': 26.056,
            'struct_state': 'OK',
        })
        req = _m10_fill_required_fields(_apply_b1_m9_b2_m10_unified_contract(req, snapshot=snapshot), snapshot)
        steps = list((req or {}).get('steps') or [])
        close_notional = float((((req or {}).get('params') or {}).get('close_notional_u') or 0.0) or 0.0)
        loss_notional = 2605.60
        realized_loss = (-520.00) * (close_notional / loss_notional)
        rep['abs_realized'] = float(abs(realized_loss))
        rep['half_win'] = float(47.00 / 2.0)
        rep['net_u'] = float(47.00 + realized_loss)
        rep['case_ready'] = bool(rep['abs_realized'] > rep['half_win'] and rep['net_u'] > 0.0 and len(steps) >= 3)
        rq = RequestQueue(_rizhi_path('m10_realized_loss_bypass_selftest_queue.jsonl'))
        menhu = GOMenHu(rq, snapshot, [coin])
        ok_gate, gate_reason = menhu._gate_check_and_stamp(dict(req))
        rep['ok'] = bool(ok_gate)
        rep['reason'] = str(gate_reason or '')
        if 'reject_tp_realized_loss_gt_half_win' in str(gate_reason or ''):
            raise AssertionError(f'half_win_still_blocks:{gate_reason}')
        if not ok_gate:
            raise AssertionError(f'gate_failed:{gate_reason}')
        if not bool(rep.get('case_ready')):
            rep['reason'] = str(gate_reason or 'adaptive_pass_fixture_not_meeting_half_win_case')
            rep['adaptive_skip'] = True
        return rep
    except Exception as e:
        rep['error'] = f'{type(e).__name__}:{e}'
        return rep

def _selftest_pre_positions_prefetch_order() -> dict:
    """静态自检：公共K线/选币前置必须位于完整持仓扫描之前，并且持仓前真相字段要接通。"""
    rep: dict[str, Any] = {'name': 'pre_positions_prefetch_order', 'ok': False, 'pre_before_balances': False, 'pre_before_positions': False, 'live_truth_keys_present': False, 'error': ''}
    try:
        src = open(__file__, 'r', encoding='utf-8').read()
        call_key = '_m2_pre_positions_public_kline_and_selector('
        bal_key = '_m2_scan_watch_update("balances"'
        pos_key = '_m2_scan_watch_update("positions"'
        call_idx = src.find(call_key)
        bal_idx = src.find(bal_key)
        pos_idx = src.find(pos_key)
        rep['pre_before_balances'] = bool(call_idx >= 0 and bal_idx >= 0 and call_idx < bal_idx)
        rep['pre_before_positions'] = bool(call_idx >= 0 and pos_idx >= 0 and call_idx < pos_idx)
        rep['live_truth_keys_present'] = all(k in src for k in ('scan_live_position_coins_ext', 'scan_live_position_coins_var', 'pre_positions_live_coins', 'pre_positions_active_coins'))
        rep['ok'] = bool(rep['pre_before_balances'] and rep['pre_before_positions'] and rep['live_truth_keys_present'])
        if not rep['ok']:
            raise AssertionError(f'prefetch_order_bad:{rep}')
        return rep
    except Exception as e:
        rep['error'] = f'{type(e).__name__}:{e}'
        return rep



