def _calc_coin_structure_state(snapshot: dict, coin: str, *, leg_min_u: float = 5.0) -> Dict[str, Any]:
    """计算结构状态（用于审计/阻断日志），只读，不改变策略。
    返回：has_e/has_v/same_dir/missing_leg/gap_u/big_plat/small_plat/legs 等
    """
    try:
        c = (str(coin or "").strip().upper() or "")
        es, en = _a1_extract_leg(snapshot or {}, c, "EXT")
        vs, vn = _a1_extract_leg(snapshot or {}, c, "VAR")
        en_f = float(en or 0.0)
        vn_f = float(vn or 0.0)
        has_e = (en_f >= float(leg_min_u)) and (str(es or "").upper() != "NONE")
        has_v = (vn_f >= float(leg_min_u)) and (str(vs or "").upper() != "NONE")
        same_dir = False
        if has_e and has_v:
            try:
                same_dir = (_a1_norm_side(es) == _a1_norm_side(vs))
            except Exception:
                same_dir = False
        missing_leg = (has_e and (not has_v)) or (has_v and (not has_e))
        gap = abs(en_f - vn_f)
        big_plat = None
        small_plat = None
        if en_f > vn_f:
            big_plat, small_plat = "EXT", "VAR"
        elif vn_f > en_f:
            big_plat, small_plat = "VAR", "EXT"
        try:
            _scan_reconcile_grid_and_missing_leg(snapshot or {}, c)
        except Exception:
            pass
        return {
            "coin": c,
            "ext": {"side": es, "notional_u": en_f, "has": has_e},
            "var": {"side": vs, "notional_u": vn_f, "has": has_v},
            "same_dir": bool(same_dir),
            "missing_leg": bool(missing_leg),
            "gap_u": float(gap),
            "big_plat": big_plat,
            "small_plat": small_plat,
        }
    except Exception:
        return {"coin": str(coin or "").strip().upper(), "err": "calc_failed"}

def _split_reason(reason: str) -> tuple[str, str]:
    try:
        s = str(reason or "")
    except Exception:
        s = ""
    if ":" in s:
        a, b = s.split(":", 1)
        return a.strip(), b.strip()
    return s.strip(), ""

def _mk_reason(code: str, **kv) -> str:
    """统一原因码格式：CODE:k=v;k2=v2（单行可解析）"""
    try:
        c = str(code or "").strip()
    except Exception:
        c = ""
    if not kv:
        return c
    parts = []
    for k, v in (kv or {}).items():
        if v is None:
            continue
        try:
            kk = str(k).strip()
        except Exception:
            kk = ""
        if not kk:
            continue
        try:
            vv = str(v)
        except Exception:
            vv = ""
        vv = vv.replace("\n", "\\n").replace("\r", "\\r")
        parts.append(f"{kk}={vv}")
    if not parts:
        return c
    return f"{c}:{';'.join(parts)}"

def _reason_category(reason_code: str) -> str:
    c = (reason_code or "").strip().lower()
    if not c:
        return "other"
    if c.startswith("reject_ind_"):
        return "indicator"
    if c.startswith("reject_budget") or ("budget" in c):
        return "budget"
    if c.startswith("m1_") or c.startswith("gate") or ("stamp" in c) or c.startswith("queue_"):
        return "gate"
    if c.startswith("pause") or ("pause" in c):
        return "pause"
    if c.startswith("reject_same_dir") or c.startswith("reject_imbalance") or c.startswith("reject_data_quality") or c.startswith("legacy_only") or c.startswith("a1_") or ("structure" in c) or ("imbalance" in c) or ("same_dir" in c):
        return "structure"
    return "other"

def _reason_category_cn(cat: str) -> str:
    c = (cat or "").strip().lower()
    if c == "indicator":
        return "指标"
    if c == "structure":
        return "结构"
    if c == "budget":
        return "预算"
    if c == "gate":
        return "闸门"
    if c == "pause":
        return "暂停"
    return "其他"

_REASON_CN_EXACT = {
    "reject_ind_missing": "指标缺失（ 未就绪）",
    "reject_same_dir_freeze_add": "同向不对冲，冻结加仓/开仓",
    "reject_imbalance_gap_gt_max": "对冲差额超阈值",
    "m1_gate_missing": "缺少 M1 盖章",
    "m1_stamp_stale": "M1 盖章过期（队列积压）",
    "legacy_only_block": "仅允许修复态（LEGACY_DELETED）",
    "a1_reject": "最高权限拦截",
}

def _reason_code_cn(reason_code: str) -> str:
    c = (reason_code or "").strip()
    if not c:
        return ""
    lc = c.lower()
    if c in _REASON_CN_EXACT:
        return _REASON_CN_EXACT[c]
    if lc.startswith("reject_ind_"):
        return "策略阀门拦截"
    if lc.startswith("reject_same_dir"):
        return "同向不对冲（结构异常）"
    if lc.startswith("reject_imbalance") or "imbalance" in lc:
        return "对冲结构失衡"
    if lc.startswith("reject_budget") or "budget" in lc:
        return "预算不足/硬顶限制"
    if lc.startswith("m1_") or "stamp" in lc:
        return "总阀门/盖章问题"
    if lc.startswith("pause") or "pause" in lc:
        return "暂停/熔断"
    if lc.startswith("a1_") or lc.startswith("hp"):
        return "最高权限拦截"
    if lc.startswith("gate_") or lc.startswith("gate"):
        return "闸门拦截"
    return c or "未知原因"

def _reason_code_cn_with_detail(reason_code: str, reason_detail: str = "") -> str:
    base = _reason_code_cn(reason_code)
    d = (reason_detail or "").strip()
    if base and d:
        return f"{base}（{d}）"
    return base or d or ""

def _extract_indicators(snapshot: dict, coin: str) -> dict:
    """用于日志/审计输出的指标提取（M2 写入 snapshot['indicators']）。"""
    try:
        c = str(coin or "").upper().strip()
    except Exception:
        c = ""
    try:
        ind = (snapshot or {}).get("indicators") or {}
        if isinstance(ind, dict) and c and isinstance(ind.get(c), dict):
            d = ind.get(c) or {}
            return {
                "adx": d.get("adx"),
                "rsi": d.get("rsi"),
                "ind_reason": d.get("reason"),
            }
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    return {}

def _calc_budget_state_for_log(snapshot: dict, coin: str, req_mod: str) -> dict:
    """为日志提供一个轻量预算视图（不依赖内部复杂状态，避免回归）
    输出的是‘理论硬顶’（cap（硬顶））与当前 exposure（敞口）估算，便于排查为何被拦。
    """
    try:
        c = str(coin or "").strip().upper()
    except Exception:
        c = ""
    try:
        m = str(req_mod or "")
    except Exception:
        m = ""

    try:
        total_u = float((snapshot or {}).get("total_equity_u") or (snapshot or {}).get("total_u") or 0.0)
    except Exception:
        total_u = 0.0

    if total_u <= 0.0:
        try:
            total_u = float(_get_total_u(snapshot or {}) or 0.0)
        except Exception:
            total_u = 0.0

    try:
        exp_u = float(_coin_exposure_u(snapshot or {}, c) or 0.0) if c else 0.0
    except Exception:
        exp_u = 0.0

    try:
        buckets = _alloc_budget_buckets(exp_u, total_u)
    except Exception:
        buckets = {}

    bucket = "other"
    mm = m.upper().strip()
    if mm.startswith("M9"):
        bucket = "grid"
    elif mm.startswith("B1"):
        bucket = "open"
    elif mm.startswith("LEGACY_DELETED"):
        bucket = "safe_legacy_fix"
    elif mm.startswith("M10") or mm.startswith("B2") or mm.startswith("B10"):
        bucket = "tp"
    out = {
        "total_equity_u": total_u,
        "coin_exposure_u": exp_u,
        "bucket": bucket,
        "caps": buckets,
    }
    try:
        if isinstance(buckets, dict) and bucket in buckets and isinstance(buckets[bucket], dict):
            out["cap_bucket_u"] = float(buckets[bucket].get("cap") or 0.0)
            out["cap_bucket_used_u"] = float(buckets[bucket].get("used") or 0.0)
            out["cap_bucket_rem_u"] = float(buckets[bucket].get("remain") or 0.0)
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    return out

def _log_gate_drop(logfp: str, snapshot: dict, req_any: Any, gate: str, reason: str, *, extra: Dict[str, Any] | None = None) -> None:
    """统一闸门丢弃日志（gate_drop（闸门丢弃））

    用于把各类 return（早退）/continue（跳过）原因落盘到 bot_run.jsonl（主逐行日志）
    固定字段：gate（闸门）/reason（原因）/reason_code（原因码）/reason_detail（原因详情）/reason_category（原因分类）
              coin（币种）/module（模块）/action（动作）/priority（优先级）/structure（结构）/indicator（指标）
    """
    try:
        req = req_any if isinstance(req_any, dict) else (req_any.__dict__ if hasattr(req_any, "__dict__") else dict(req_any))
    except Exception:
        req = {}
    try:
        coin = str(req.get("coin") or "")
        structure = _calc_coin_structure_state(snapshot or {}, coin) if coin else {}
    except Exception:
        structure = {"err": "calc_failed"}

    reason_code, reason_detail = _split_reason(str(reason or ""))
    payload: Dict[str, Any] = {
        "ts": time.time(),
        "mod": "EXECUTOR（执行器）",
        "type": "gate_drop（闸门丢弃）",
        "gate": str(gate),
        "reason": str(reason),
        "reason_code": reason_code,
        "reason_detail": reason_detail,
        "reason_category": _reason_category(reason_code),
        "coin": coin,
        "req_mod": str(req.get("module") or ""),
        "req_act": str(req.get("action_type") or ""),
        "priority": req.get("priority"),
        "structure": structure,
        "indicator": _extract_indicators(snapshot or {}, coin) if coin else {},
        "budget": _calc_budget_state_for_log(snapshot or {}, coin, str(req.get("module") or "")) if coin else {},
    }
    try:
        payload["indicator"] = _extract_indicators(snapshot or {}, coin)
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    if extra:
        payload["extra"] = extra
    write_jsonl(logfp, payload)

    payload: Dict[str, Any] = {
        "ts": time.time(),
        "mod": "EXECUTOR（执行器）",
        "type": "gate_drop（闸门丢弃）",
        "gate": str(gate),
        "reason": str(reason),
        "coin": coin,
        "req_mod": str(req.get("module") or ""),
        "req_act": str(req.get("action_type") or ""),
        "priority": req.get("priority"),
        "structure": structure,
    }
    if extra:
        payload["extra"] = extra
    write_jsonl(logfp, payload)

