def _safe_float(x, d=0.0):
    try:
        if x is None:
            return d
        return float(x)
    except Exception:
        return d

def _fmt3(x: float) -> str:
    """格式化金额：千分位 + 2位小数。"""
    try:
        return f"{float(x):,.2f}"
    except Exception:
        return str(x)

def _fmt6(x: float) -> str:
    """格式化价格/比例：6位小数；None 返回 '-'。"""
    try:
        if x is None:
            return '-'
        return f"{float(x):.6f}"
    except Exception:
        return '-'

def parse_priority(priority: Any, default: int = 50) -> int:
    """兼容 priority 传入 'P3'/'p3'/'3' 等格式，避免 int() 报错吞单。"""
    try:
        if priority is None:
            return int(default)
        if isinstance(priority, bool):
            return int(default)
        if isinstance(priority, int):
            return int(priority)
        if isinstance(priority, float):
            return int(priority)
        if isinstance(priority, str):
            s = priority.strip()
            if not s:
                return int(default)
            if (s[0] in ("P", "p")) and s[1:].isdigit():
                return int(s[1:])
            if s.isdigit():
                return int(s)
    except Exception:
        return int(default)
    return int(default)

A1_CLOSE_NETPROFIT_MIN_PCT = 0.01
TREND_TP_NET_MIN_PCT = 0.005  # 0.5% × loss_notional（亏损腿名义）
A1_MAX_HEDGE_GAP_U = 200.0
A1_DUAL_CONFIRM_MAX_GAP_SEC = 1.0  # 最高权限 1：最终确认差 ≤ 1 秒

_EXEC_LAST_CONFIRM_TS: dict[int, float] = {}

_EXEC_CONFIRMED_CLOSES: Dict[tuple[str, str], Dict[str, Any]] = {}

def _mark_exec_confirmed_close(coin: str, platform: str, *, source: str = "", detail: Optional[Dict[str, Any]] = None) -> None:
    """执行器已确认该腿确实平掉：先记下来，供外层在快照慢半拍时本地清腿。"""
    try:
        c = str(coin or "").upper().strip()
        p = str(platform or "").upper().strip()
        if not c or p not in ("EXT", "VAR"):
            return
        _EXEC_CONFIRMED_CLOSES[(c, p)] = {
            "ts": float(time.time()),
            "source": str(source or ""),
            "detail": dict(detail or {}),
        }
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_942', _e)
        pass
def _peek_exec_confirmed_close(coin: str, platform: str, *, max_age_sec: float = 120.0) -> Optional[Dict[str, Any]]:
    try:
        c = str(coin or "").upper().strip()
        p = str(platform or "").upper().strip()
        info = _EXEC_CONFIRMED_CLOSES.get((c, p))
        if not isinstance(info, dict):
            return None
        if float(time.time()) - float(info.get("ts") or 0.0) > float(max_age_sec):
            try:
                _EXEC_CONFIRMED_CLOSES.pop((c, p), None)
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_943', _e)
                pass
            return None
        return info
    except Exception:
        return None

def _consume_exec_confirmed_close(coin: str, platform: str, *, max_age_sec: float = 120.0) -> Optional[Dict[str, Any]]:
    info = _peek_exec_confirmed_close(coin, platform, max_age_sec=max_age_sec)
    if info is not None:
        try:
            _EXEC_CONFIRMED_CLOSES.pop((str(coin or "").upper().strip(), str(platform or "").upper().strip()), None)
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_944', _e)
            pass
    return info

def _prune_coin_from_snapshot(snapshot: Dict[str, Any], coin: str, platform: str = "") -> Dict[str, Any]:
    """当执行器已确认某腿消失，但 M2 快照慢半拍时，先把本地旧腿清掉。"""
    try:
        c = str(coin or "").upper().strip()
        p = str(platform or "").upper().strip()
        if not isinstance(snapshot, dict) or not c:
            return snapshot
        pm = _pos_root(snapshot)
        if not isinstance(pm, dict):
            return snapshot
        plats = [p] if p in ("EXT", "VAR") else ["EXT", "VAR"]
        changed = False
        for pp in plats:
            bucket = pm.get(pp)
            if isinstance(bucket, dict) and c in bucket:
                try:
                    bucket.pop(c, None)
                    changed = True
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_945', _e)
                    pass
        if changed:
            snapshot["positions"] = pm
            snapshot["ts"] = float(time.time())
        return snapshot
    except Exception:
        return snapshot

def _postcheck_extract_coin_state(snapshot: Dict[str, Any], coin: str) -> Dict[str, Any]:
    """执行后复检用：统一从 TP/M10 唯一币级真相提取双平台状态。"""
    c = str(coin or "").upper().strip()
    truth = _tpm10_coin_truth(snapshot or {}, c)
    ext_leg = truth.get('ext') or {}
    var_leg = truth.get('var') or {}
    ext_notional_u = float(truth.get('ext_notional_u') or 0.0)
    var_notional_u = float(truth.get('var_notional_u') or 0.0)
    ext_upnl_u = float(truth.get('ext_upnl_u') or 0.0)
    var_upnl_u = float(truth.get('var_upnl_u') or 0.0)
    return {
        'coin': c,
        'ext_has': bool(truth.get('ext_has')),
        'var_has': bool(truth.get('var_has')),
        'ext_side': str(truth.get('ext_side') or '').upper().strip(),
        'var_side': str(truth.get('var_side') or '').upper().strip(),
        'ext_qty': ext_leg.get('qty'),  # Missing quantity is not a measured zero.
        'var_qty': var_leg.get('qty'),
        'ext_entry_px': float(ext_leg.get('entry_px') or 0.0),
        'var_entry_px': float(var_leg.get('entry_px') or 0.0),
        'ext_notional_u': ext_notional_u,
        'var_notional_u': var_notional_u,
        'net_notional_u': ext_notional_u + var_notional_u,
        'ext_upnl_u': ext_upnl_u,
        'var_upnl_u': var_upnl_u,
        'net_upnl_u': ext_upnl_u + var_upnl_u,
        'ext_reason': str(ext_leg.get('reason') or ''),
        'var_reason': str(var_leg.get('reason') or ''),
        'ext_recovered_from_last_good': bool(ext_leg.get('recovered_from_last_good')),
        'var_recovered_from_last_good': bool(var_leg.get('recovered_from_last_good')),
        'ext_side_source': str(ext_leg.get('side_source') or ''),
        'var_side_source': str(var_leg.get('side_source') or ''),
        'ext_position_state': _safety_normalize_position_read(ext_leg).get('state'),
        'var_position_state': _safety_normalize_position_read(var_leg).get('state'),
        'truth_source': 'tpm10_coin_truth',
        'snapshot_ts': safe_float((snapshot or {}).get('ts') if isinstance(snapshot, dict) else None, default=0.0) or 0.0,
    }

def _postcheck_direct_read_target_coin_snapshot(cdp: str, current_snap: dict | None, coin: str, logfp: str, *, reason: str = '', wait_sec: float = 0.0, deadline_monotonic: float | None = None) -> dict | None:
    """执行后复检：默认走全量 fresh truth；只认最新扫描结果，不再让 last_good/局部旧快照冒充当前真相。"""
    try:
        _coin = str(coin or '').upper().strip()
    except Exception:
        _coin = ''
    if not _coin:
        return current_snap if isinstance(current_snap, dict) else None
    try:
        _wait_sec = float(wait_sec or 0.0)
    except Exception:
        _wait_sec = 0.0
    if deadline_monotonic is not None:
        _left = float(deadline_monotonic) - time.monotonic()
        if _left <= 0:
            return None
        _wait_sec = min(_wait_sec, _left)
    if _wait_sec > 0:
        try:
            safe_log(lambda: f"[{now_ts()}] POSTCHECK_DIRECT_READ_WAIT coin={_coin} sleep={float(_wait_sec):.2f}s reason={str(reason or 'POSTCHECK_DIRECT_READ')[:120]}")
        except Exception as _e:
            _record_swallowed_exception('except_pass_postcheck_direct_read_wait_log', _e)
            pass
        try:
            _ORIG_TIME_SLEEP(float(_wait_sec))
        except Exception as _e:
            _record_swallowed_exception('except_pass_postcheck_direct_read_wait_sleep', _e)
            pass
    try:
        _coins_all = [str(c or '').upper().strip() for c in (((current_snap or {}).get('coins') or {}).keys() if isinstance((current_snap or {}).get('coins'), dict) else []) if str(c or '').strip()]
    except Exception:
        _coins_all = []
    if _coin and _coin not in _coins_all:
        _coins_all.append(_coin)
    if deadline_monotonic is not None:
        # One full, fresh positions scan within the remaining budget. No second
        # fallback scan can restart the deadline or silently return cached truth.
        if time.monotonic() >= float(deadline_monotonic):
            return None
        return m2_scan(cdp, _coins_all, logfp, ind_mode='off', only_positions=True,
                       reason=str(reason or 'POSTCHECK_VERIFY_FULLSCAN'), scan_scope='full',
                       strict_fresh_positions=True, strict_latest_only=True,
                       _postcheck_deadline_monotonic=float(deadline_monotonic))
    try:
        if bool(POSTCHECK_VERIFY_USE_FULLSCAN):
            snap_all = _snapshot_refresh_fullscan(
                cdp,
                current_snap if isinstance(current_snap, dict) else {},
                _coins_all,
                logfp,
                reason=str(reason or 'POSTCHECK_VERIFY_FULLSCAN'),
                force=True,
                only_positions=True,
                strict_fresh_positions=True,
            )
            if isinstance(snap_all, dict) and snap_all:
                return snap_all
    except Exception as _e:
        _record_swallowed_exception('postcheck_direct_read_target_coin_snapshot.fullscan', _e, coin=_coin, reason=reason)
    try:
        snap_one = _m2_scan_cached(
            cdp,
            [_coin],
            logfp,
            reason=str(reason or 'POSTCHECK_DIRECT_READ'),
            force=False,
            decision_needed=True,
            pending_len=0,
            only_positions=True,
            ind_mode='off',
            scan_scope='local',
            strict_fresh_positions=True,
            strict_latest_only=True,
        )
    except Exception as _e:
        _record_swallowed_exception('postcheck_direct_read_target_coin_snapshot.scan', _e, coin=_coin, reason=reason)
        snap_one = None
    if isinstance(snap_one, dict) and snap_one:
        try:
            merged_snap = _snapshot_merge_coin_positions(current_snap or {}, snap_one, [_coin])
        except Exception:
            merged_snap = snap_one
        try:
            _m = merged_snap.get('meta') if isinstance(merged_snap, dict) else None
            if not isinstance(_m, dict):
                _m = {}
            _m['scope'] = 'local'
            _m['scan_scope'] = 'local'
            _m['allow_commit_global'] = False
            _m['reason'] = str(reason or 'POSTCHECK_DIRECT_READ')[:180]
            _m['postcheck_direct_read'] = True
            _m['strict_fresh_positions'] = True
            _m['strict_latest_only'] = True
            merged_snap['meta'] = _m
            merged_snap['scan_scope'] = 'local'
        except Exception as _e:
            _record_swallowed_exception('except_pass_postcheck_direct_read_meta', _e)
            pass
        return merged_snap
    return current_snap if isinstance(current_snap, dict) else None

def _postcheck_req_amount_u(req_any: Any, default: float = 0.0) -> float:
    """尽量从请求里还原本次意图金额（U）。"""
    keys = ("amount_u", "amount", "usd", "amount_usd", "intent_amount", "u", "notional_u", "target_u")
    try:
        if isinstance(req_any, dict):
            pools = [req_any, req_any.get('meta') if isinstance(req_any.get('meta'), dict) else {}, req_any.get('params') if isinstance(req_any.get('params'), dict) else {}]
        else:
            pools = [req_any, getattr(req_any, 'meta', None) if isinstance(getattr(req_any, 'meta', None), dict) else {}, getattr(req_any, 'params', None) if isinstance(getattr(req_any, 'params', None), dict) else {}]
    except Exception:
        pools = [req_any]
    for pool in pools:
        for k in keys:
            try:
                if isinstance(pool, dict):
                    v = pool.get(k)
                else:
                    v = getattr(pool, k, None)
                if v is None:
                    continue
                fv = float(v)
                if math.isfinite(fv) and fv > 0:
                    return float(abs(fv))
            except Exception:
                continue
    try:
        return float(default or 0.0)
    except Exception:
        return 0.0

def _postcheck_dynamic_delta_threshold(req_any: Any, *, default_floor: float = 0.6) -> float:
    """执行后复检阈值：不能太死，也不能把价格抖动当成落地。"""
    try:
        amt = float(_postcheck_req_amount_u(req_any, 0.0) or 0.0)
    except Exception:
        amt = 0.0
    try:
        thr = max(float(default_floor), min(8.0, max(1.2, amt * 0.08)))
    except Exception:
        thr = float(default_floor)
    return float(thr)

def _postcheck_exec_has_submit_success(exec_res_list: Any) -> bool:
    try:
        for rr in list(exec_res_list or []):
            if isinstance(rr, dict) and bool(rr.get('ok') or rr.get('submit_ok') or (rr.get('pending_confirm') and rr.get('submit_attempted'))):
                return True
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_946', _e)
        pass
    return False

def _postcheck_exec_has_strong_success(exec_res_list: Any) -> bool:
    """强成功证据：已经有比较硬的执行成功信号时，不要再先挂 WAIT_VERIFY。"""
    try:
        for rr in list(exec_res_list or []):
            if not isinstance(rr, dict):
                continue
            if bool(rr.get('postcheck_ok') or rr.get('final_ok') or rr.get('action_done')):
                return True
            if _result_has_fill_evidence(rr):
                return True
            _mod = str(rr.get('module') or rr.get('mod') or '').upper().strip()
            _act = str(rr.get('action') or rr.get('action_type') or '').lower().strip()
            _reason = str(rr.get('reason') or '').lower().strip()
            if bool(rr.get('ok') or rr.get('submit_ok')) and (_mod in ('M9', 'B2') or _act in ('increase', 'decrease', 'close', 'close_full', 'close_all', 'reduce', 'open_position') or _reason in ('add_done', 'reduce_done', 'close_done', 'postcheck_ok', 'confirm_ok', 'confirmed_success')):
                return True
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_946a', _e)
        pass
    return False

def _postcheck_exec_has_fill_evidence(exec_res_list: Any) -> bool:
    try:
        for rr in list(exec_res_list or []):
            if isinstance(rr, dict) and _result_has_fill_evidence(rr):
                return True
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_947', _e)
