def _postcheck_pending_verify_payload(req_any: Any) -> dict:
    try:
        if isinstance(req_any, dict):
            obj = req_any.get('_postcheck_pending_verify')
        else:
            obj = getattr(req_any, '_postcheck_pending_verify', None)
        return dict(obj or {}) if isinstance(obj, dict) else {}
    except Exception:
        return {}

def _postcheck_pending_verify_active(req_any: Any) -> bool:
    obj = _postcheck_pending_verify_payload(req_any)
    return bool(obj) and bool(obj.get('active'))

def _postcheck_pending_verify_due(req_any: Any, now_ts_v: float | None = None) -> bool:
    obj = _postcheck_pending_verify_payload(req_any)
    if not obj:
        return False
    if _postcheck_verify_budget(req_any, now_ts_v=now_ts_v)['exhausted']:
        return True  # Remove exhausted work immediately, even when its timer is later.
    try:
        due_ts = float(obj.get('verify_after_ts') or 0.0)
    except Exception:
        due_ts = 0.0
    if due_ts <= 0:
        return True
    nowv = float(now_ts_v if now_ts_v is not None else time.time())
    return nowv >= due_ts

def _postcheck_pending_verify_mark(req_any: Any, *, pre_state: dict | None = None, post_state: dict | None = None,
                                   exec_res_list: list | None = None, uncertain_reason: str = '',
                                   uncertain_detail: Any = None, verify_delay_sec: float = 3.0,
                                   verify_retry_left: int = 2, started_ts: float | None = None,
                                   started_monotonic: float | None = None) -> dict:
    nowv = float(time.time())
    previous = _postcheck_pending_verify_payload(req_any)
    created = float(previous['created_ts'] if previous.get('created_ts') is not None else (started_ts if started_ts is not None else nowv))
    created_mono = float(previous['created_monotonic'] if previous.get('created_monotonic') is not None else (started_monotonic if started_monotonic is not None else time.monotonic()))
    payload = {
        'active': True,
        'created_ts': created,
        'created_monotonic': created_mono,
        'deadline_ts': created + _postcheck_lifecycle.VERIFY_TIMEOUT_SEC,
        'updated_ts': nowv,
        'verify_after_ts': nowv + max(0.2, float(verify_delay_sec or 0.0)),
        'verify_retry_left': min(_postcheck_lifecycle.VERIFY_MAX_ATTEMPTS, max(0, int(previous.get('verify_retry_left', verify_retry_left) or 0))),
        'uncertain_reason': str(uncertain_reason or 'postcheck_uncertain'),
        'uncertain_detail': uncertain_detail,
        'pre_state': dict(pre_state or {}) if isinstance(pre_state, dict) else {},
        'post_state': dict(post_state or {}) if isinstance(post_state, dict) else {},
        'exec_res_list': [dict(x) if isinstance(x, dict) else x for x in list(exec_res_list or [])],
    }
    try:
        if isinstance(req_any, dict):
            req_any['_postcheck_pending_verify'] = payload
        else:
            setattr(req_any, '_postcheck_pending_verify', payload)
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_949', _e)
        pass
    return payload

def _postcheck_pending_verify_clear(req_any: Any) -> None:
    try:
        if isinstance(req_any, dict):
            req_any.pop('_postcheck_pending_verify', None)
        else:
            if hasattr(req_any, '_postcheck_pending_verify'):
                delattr(req_any, '_postcheck_pending_verify')
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_950', _e)
        pass
def _postcheck_pending_verify_bump(req_any: Any, *, verify_delay_sec: float = 4.0,
                                   uncertain_reason: str = '', uncertain_detail: Any = None,
                                   post_state: dict | None = None) -> dict:
    obj = _postcheck_pending_verify_payload(req_any)
    nowv = float(time.time())
    retry_left = max(0, int(obj.get('verify_retry_left') or 0) - 1)
    obj.update({
        'active': True,
        'updated_ts': nowv,
        'verify_after_ts': nowv + max(0.2, float(verify_delay_sec or 0.0)),
        'verify_retry_left': retry_left,
    })
    if uncertain_reason:
        obj['uncertain_reason'] = str(uncertain_reason)
    if uncertain_detail is not None:
        obj['uncertain_detail'] = uncertain_detail
    if isinstance(post_state, dict):
        obj['post_state'] = dict(post_state or {})
    try:
        if isinstance(req_any, dict):
            req_any['_postcheck_pending_verify'] = obj
        else:
            setattr(req_any, '_postcheck_pending_verify', obj)
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_951', _e)
        pass
    return obj

def _postcheck_verify_budget(req_any, *, now_ts_v=None):
    return _postcheck_lifecycle.verification_budget(
        _postcheck_pending_verify_payload(req_any),
        now=float(time.time() if now_ts_v is None else now_ts_v), monotonic=time.monotonic())


def _postcheck_defer_to_scan(req_any, *, reason='', payload=None):
    """Detach verification without inventing a new order or poisoning other scopes."""
    from bot_core import submission_scope as scope
    pv = dict(payload if isinstance(payload, dict) else _postcheck_pending_verify_payload(req_any))
    req = _req_get_dict(req_any)
    coin = str(req.get('coin') or '').upper()
    platform = str(req.get('platform') or '').upper()
    action = _postcheck_req_action_lower(req_any)
    params, meta = req.get('params') or {}, req.get('meta') or {}
    side = _a1_norm_side(req.get('side') or params.get('side') or meta.get('side'))
    keys, durable = [], False
    try:
        with _SYNC_PW_WORKER_LOCK:
            records = _safety_submission_records()
            if globals().get('_SAFETY_SUBMISSION_FAULT'):
                raise RuntimeError('submission_journal_unavailable')
            kind = 'open' if scope.family(action) == 'open' else ('close_all' if 'close' in action else 'close')
            platforms = [platform] if platform in ('EXT', 'VAR') else ['EXT', 'VAR']
            for plat in platforms:
                pre_leg = _safety_scoped_position(pv.get('pre_state') or {}, plat)
                held = side if kind == 'open' else scope.side(pre_leg.get('side')) or side
                candidates = [(k,r) for k,r in records.items() if r.get('platform') == plat
                    and (coin == 'ALL' or r.get('coin') == coin)
                    and scope.family(r.get('kind')) == scope.family(kind) and _safety_pending_blocks(r)]
                # The button layer normally reserved the record before dispatch.
                # A parent's ALL lookup or a blocked new request is not a new order.
                if not candidates and coin != 'ALL' and reason != 'blocked_existing_unconfirmed_no_submit':
                    sent = [a for a in meta.get('_submission_attempts', [])
                        if a.get('platform') == plat and a.get('coin') == coin
                        and a.get('state') in ('CLICK_STARTED','CLICKED','CLICK_UNKNOWN')]
                    key = scope.key(plat, coin, kind, held)
                    if sent and key not in records and not _safety_pending_scope(plat, coin, kind, held):
                        _safety_reserve_submission(plat, coin, held, kind, pre_leg,
                            _postcheck_req_amount_u(req_any), reason='postcheck_deferred_dispatched',
                            submission_attempt_id=sent[-1].get('id',''), module=str(req.get('module') or ''))
                        candidates = [(key,records[key])]
                for key,record in candidates:
                    record.setdefault('deferred_postcheck', {'module':str(req.get('module') or '').upper(),
                        'observing_request_id':str(meta.get('req_id') or req.get('req_id') or ''),
                        'started_ts':pv.get('created_ts'),'deferred_ts':float(time.time()),'reason':str(reason)})
                    keys.append(key)
            durable = bool(_safety_submission_save()) if keys else True
        state = 'PENDING_CONFIRM' if keys else 'SKIPPED'
        _req_exec_once_mark(req_any, state, 'postcheck_deferred_to_scan' if keys else 'no_unresolved_submission_claim')
        safe_log(lambda: f"[{now_ts()}] POSTCHECK_DEFER_UNCONFIRMED coin={coin} mod={req.get('module','')} reason={reason} durable={int(durable)} scopes={keys} inround_retry=0")
    except Exception as exc:
        # Reservation conflicts/request errors are not journal corruption.
        safe_log(lambda: f"[{now_ts()}] POSTCHECK_DEFER_FAILED coin={coin} reason={type(exc).__name__}:{exc} journal_fault={int(bool(globals().get('_SAFETY_SUBMISSION_FAULT')))}")
    finally:
        _postcheck_pending_verify_clear(req_any)
    return durable


def _postcheck_reconcile_unconfirmed_scan(snapshot, *, scan_id):
    """Startup and each independent full scan: one journal writer, audited settlements."""
    from bot_core import legacy_reconciliation as reconcile
    from bot_core.settlement_commands import SettlementInbox, commit_reconciliation
    now = float(time.time())
    fresh = reconcile.snapshot_is_fresh(snapshot, now=now)
    startup = not globals().get('_SAFETY_RECON_STARTUP_DONE', False)
    stage = ('STARTUP' if fresh else 'STARTUP_WAIT') if startup else 'SCAN'
    inbox = SettlementInbox(OUT_DIR)
    with _SYNC_PW_WORKER_LOCK:
        records = _safety_submission_records()
        if globals().get('_SAFETY_SUBMISSION_FAULT'):
            safe_log(lambda: f"[{now_ts()}] [RECONCILE_BLOCKED] stage={stage} reason={globals().get('_SAFETY_SUBMISSION_FAULT_DETAIL','journal_unavailable')}")
            return []
        commands = inbox.consume(records, _safety_submission_save, now=now) if fresh else []
        updated, decisions = reconcile.replay(records, snapshot, now=now, scan_id=scan_id)
        for detail in decisions:
            key = detail['record_key']
            detail['reason_text'] = reconcile.decision_text(detail)
            if (detail['original_state'] not in reconcile.TERMINAL
                    and detail['reason'] != 'separate_m9_m10_confirmation_policy'):
                updated[key]['reconciliation_last'] = {k:detail.get(k) for k in
                    ('reason','reason_text','snapshot_ts','current_side','current_notional_u','empty_scan_count')}
                updated[key]['reconciliation_last'].update(checked_ts=now,stage=stage)
        if not commit_reconciliation(records, updated, decisions, save=_safety_submission_save,
                                     inbox=inbox, now=now, stage=stage):
            safe_log(lambda: f"[{now_ts()}] [RECONCILE_SAVE_FAILED] stage={stage} memory_rolled_back=1")
            return []
        cleanup = [dict(r) for r in records.values() if not _safety_pending_blocks(r)]
        if fresh:globals()['_SAFETY_RECON_STARTUP_DONE'] = True
    for record in cleanup:
        for side in ('LONG','SHORT'):
            _exec_clear_pending(record.get('platform'),record.get('coin'),side,kind=record.get('kind'))
    for command in commands:
        safe_log(lambda: f"[{now_ts()}] [MANUAL_SETTLEMENT] id={command['id']} scope={command.get('record_key')} status={command['status']} reason={command['reason']}")
    resolved = []
    last = globals().setdefault('_SAFETY_RECON_LAST_LOG', {})
    for detail in decisions:
        key = detail['record_key']
        changed = detail['proposed_state'] != detail['original_state']
        signature = (detail['proposed_state'],detail['reason'],detail.get('empty_scan_count'))
        if startup or changed or last.get(key) != signature:
            safe_log(lambda: f"[{now_ts()}] [UNCONFIRMED_RECONCILE] stage={stage} scope={key} before={detail['original_state']} state={detail['proposed_state']} reason={detail['reason']} detail={detail['reason_text']} snapshot_ts={detail['snapshot_ts']}")
            last[key] = signature
        if changed:
            resolved.append(key)
            label = 'POSTCHECK_SCAN_NOT_FILLED' if detail['proposed_state']=='CONFIRMED_NOT_FILLED' else 'POSTCHECK_SCAN_CONFIRMED'
            safe_log(lambda: f"[{now_ts()}] {label} scope={key} state={detail['proposed_state']} reason={detail['reason']}")
    safe_log(lambda: f"[{now_ts()}] [UNCONFIRMED_RECONCILE_SUMMARY] stage={stage} fresh={int(fresh)} records={len(decisions)} resolved={len(resolved)} manual={len(commands)}")
    return resolved

def _m10_postcheck_collect_step_meta(req_any: Any, exec_res_list: Any = None) -> dict:
    """收集 M10 三步父子证据，供 postcheck 严格判定。
    人话：不能只看“组内有变化”，必须确认 step1/2/3 各自结果，尤其 step3 重开腿是否真的成功。
    """
    out = {
        'child_rows': [],
        'step_ok': {},
        'step_reason': {},
        'expected': {},
    }
    try:
        _rows = _m10_extract_child_rows(exec_res_list)
        if not _rows:
            _rows = [dict(_x) for _x in list(exec_res_list or []) if isinstance(_x, dict)]
        for _rr in list(_rows or []):
            if not isinstance(_rr, dict):
                continue
            _rq = _rr.get('req') if isinstance(_rr.get('req'), dict) else {}
            _meta = _rq.get('meta') if isinstance(_rq.get('meta'), dict) else {}
            _sn_raw = _rr.get('step_no') or _meta.get('m10_step_no') or ((_meta.get('extras') or {}).get('step') if isinstance(_meta.get('extras'), dict) else 0)
            try:
                _sn = int(_sn_raw or 0)
            except Exception:
                _sn = 0
            if _sn <= 0:
                continue
            out['child_rows'].append(dict(_rr))
            out['step_ok'][_sn] = bool(_rr.get('ok'))
            out['step_reason'][_sn] = str(_rr.get('reason') or _rr.get('fail_reason') or '')
            if _sn == 3:
                out['expected'] = {
                    'platform': str(_rq.get('platform') or _rq.get('plat') or '').upper().strip(),
                    'side': str(_rq.get('side') or '').upper().strip(),
                    'amount_u': float(_rq.get('amount_u') or _rq.get('amount_usd') or _rr.get('exec_u') or 0.0),
                }
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_952', _e)
        pass
    try:
        if not out['expected']:
            _steps = []
            if isinstance(req_any, dict):
                _pm = req_any.get('params') if isinstance(req_any.get('params'), dict) else {}
                _mm = req_any.get('meta') if isinstance(req_any.get('meta'), dict) else {}
                _steps = list((_pm.get('steps') if isinstance(_pm.get('steps'), list) else []) or ((_mm.get('extras') or {}).get('steps') if isinstance(_mm.get('extras'), dict) and isinstance((_mm.get('extras') or {}).get('steps'), list) else []) or [])
            else:
                _pm = getattr(req_any, 'params', {}) if isinstance(getattr(req_any, 'params', {}), dict) else {}
                _mm = getattr(req_any, 'meta', {}) if isinstance(getattr(req_any, 'meta', {}), dict) else {}
                _steps = list((_pm.get('steps') if isinstance(_pm.get('steps'), list) else []) or ((_mm.get('extras') or {}).get('steps') if isinstance(_mm.get('extras'), dict) and isinstance((_mm.get('extras') or {}).get('steps'), list) else []) or [])
            for _st in _steps:
                try:
                    _sn = int(_st.get('step') or 0)
                except Exception:
                    _sn = 0
                if _sn == 3 or str(_st.get('action') or '').lower() in ('open_full', 'open'):
                    out['expected'] = {
                        'platform': str(_st.get('platform') or '').upper().strip(),
                        'side': str(_st.get('side') or '').upper().strip(),
                        'amount_u': float(_st.get('amount_usd') or _st.get('usd') or 0.0),
                    }
                    break
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_953', _e)
        pass
    return out

def _postcheck_reduce_zero_zero_reason(coin: str = '', platform: str = '', side: str = '') -> str:
    """减仓/平仓复检里 pre=0 且 post=0 时，禁止再判成交成功。

    人话：
    - 若同币刚被 B2/M10 抢先全平/封锁，判“已被其他模块先处理”；
    - 否则判“失效旧单”。
    """
    try:
        c = str(coin or '').upper().strip()
        p = str(platform or '').upper().strip()
        s = str(side or '').upper().strip()
        if c and '_m10_get_block' in globals():
            _blk = _m10_get_block(c, p, s, phase='gate') or _m10_get_block(c, '', '', phase='round')
            if isinstance(_blk, dict) and _blk:
                return 'postcheck_reduce_prehandled_by_other_module'
    except Exception:
        pass
    return 'postcheck_reduce_stale_old_order'

def _postcheck_reduce_success_reason(*, req_any: Any, pre: Dict[str, Any], post: Dict[str, Any], detail: Dict[str, Any], thr: float, plat: str = '') -> tuple[str | None, Dict[str, Any]]:
    req = _req_get_dict(req_any)
    ok, evidence = _safety_verify_scoped_change(action='decrease', platform=plat or req.get('platform'),
        side=req.get('side'), usd=_postcheck_req_amount_u(req_any), pre=pre, post=post,
        tolerance_usd=float(globals().get('M9_EXT_POSTCHECK_DELTA_TOL_U', 10.0) or 10.0))
    d = dict(detail or {})
    d.update(evidence)
    return ('postcheck_reduce_quantity_ok' if ok else None), d

def _postcheck_validate_effect_v2(req_any: Any, pre: Dict[str, Any], post: Dict[str, Any], *, exec_res_list: Any = None) -> tuple[str, str, Dict[str, Any]]:
    from bot_core.postcheck_lifecycle import confirmed_full_close_result
    req = _req_get_dict(req_any)
    full_close = confirmed_full_close_result(req, exec_res_list)
    if full_close:
        return 'success', full_close['reason'], full_close
    params = req.get('params') if isinstance(req.get('params'), dict) else {}
    meta = req.get('meta') if isinstance(req.get('meta'), dict) else {}
    act = _postcheck_req_action_lower(req_any)
    ok, evidence = _safety_verify_scoped_change(action=act,
        platform=req.get('platform') or req.get('plat'),
        side=req.get('side') or params.get('side') or meta.get('side'),
        usd=_postcheck_req_amount_u(req_any), pre=pre, post=post,
        tolerance_usd=float(globals().get('M9_EXT_POSTCHECK_DELTA_TOL_U', 10.0) or 10.0))
    evidence.update(module=req.get('module'), coin=req.get('coin'), action=act,
                    platform=req.get('platform'), pre=pre, post=post)
    if ok:
        for _platform in (('EXT','VAR') if str(req.get('platform') or '').upper() == 'PAIR' else (str(req.get('platform') or '').upper(),)):
            if _platform in ('EXT','VAR'):
                _safety_resolve_submission(_platform, req.get('coin'), _safety_scoped_position(post, _platform))
        return 'success', str(evidence.get('reason') or 'quantity_confirmed'), evidence
    # A submitted but unconfirmed order stays reserved; lack of evidence is not a retry signal.
    return 'uncertain_success', str(evidence.get('reason') or 'position_truth_pending'), evidence

def _state_commit_postcheck_uncertain(*, req_any, pre_state: dict | None, post_state: dict | None, exec_res_list: list | None, uncertain_reason: str = '', uncertain_detail: Any = None) -> dict:
    """执行器成功但 UI 复检暂时没跟上：保留审计，不认定 trade_effective，也不立刻判执行失败。"""
    rep = {'postcheck_marked': 0, 'trade_effective_count': 0, 'audit_written': False, 'uncertain': True}
    _all_exec = list(exec_res_list or [])
    _marked = []
    for rr0 in _all_exec:
        try:
            rr = _canon_exec_result(rr0 if isinstance(rr0, dict) else {})
            rr['submit_ok'] = bool(rr.get('ok'))
            rr['fill_confirmed'] = bool(_result_has_fill_evidence(rr))
            rr['postcheck_ok'] = None
            rr['postcheck_state'] = 'uncertain_success'
            rr['postcheck_reason'] = str(uncertain_reason or 'postcheck_uncertain')
            if uncertain_detail is not None:
                rr['postcheck_detail'] = uncertain_detail
            rr['trade_effective'] = False
            rr = _result_apply_confirmation_fields(rr)
            if isinstance(rr0, dict):
                rr0.clear()
                rr0.update(rr)
                _marked.append(rr0)
            else:
                _marked.append(rr)
        except Exception:
            if isinstance(rr0, dict):
                try:
                    rr0['submit_ok'] = bool(rr0.get('ok'))
                    rr0['fill_confirmed'] = bool(_result_has_fill_evidence(rr0))
                    rr0['postcheck_ok'] = None
                    rr0['postcheck_state'] = 'uncertain_success'
                    rr0['postcheck_reason'] = str(uncertain_reason or 'postcheck_uncertain')
                    if uncertain_detail is not None:
                        rr0['postcheck_detail'] = uncertain_detail
                    rr0['trade_effective'] = False
                    _result_apply_confirmation_fields(rr0)
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_954', _e)
                    pass
                _marked.append(rr0)
    rep['postcheck_marked'] = len(_marked)
    try:
        _audit_executor_action(
            req_any=req_any,
            pre_state=pre_state,
            post_state=post_state,
            exec_res_list=_marked,
            ok=False,
            reason=str(uncertain_reason or 'postcheck_uncertain'),
            detail=(uncertain_detail if isinstance(uncertain_detail, dict) else {'detail': uncertain_detail, 'postcheck_state': 'uncertain_success'}),
        )
        rep['audit_written'] = True
    except Exception as _e:
        _log_exc(mod='SYS', stage='EXC_PASS', e=_e)
        rep['audit_error'] = repr(_e)
    return rep

def _m2_indicator_priority_coins(snapshot: dict | None, coins: list[str] | None, *, reason: str = '', max_batch: int = 4) -> tuple[list[str], list[str]]:
    """M2 指标刷新选币器（修复：反复刷 SOL/SUI + 其他币长期过期）

    目标（人话）：
    - max_batch 限制仍保留（避免 UI 过载），但“谁进这 max_batch”必须按 *过期/最久未刷* 优先。
    - 避免连续两轮重复刷同一批币（典型：SOL/SUI 霸榜）。
    - 若执行器刚在某币切币失败（UI 不稳定），该币进入短冷却，指标侧也应避开，防止死循环拖死整轮。
    """
    raw = [str(c or '').upper().strip() for c in (coins or []) if str(c or '').strip()]
    raw = [c for c in raw if c]
    b1_seed_coins = _b1_seed_priority_coins(snapshot, raw)
    try:
        q = globals().get('_IND_ROTATION_QUEUE')
        if not isinstance(q, list):
            q = []
        q = [str(x or '').upper().strip() for x in q if str(x or '').strip()]
        if not q:
            q = list(raw)
        globals()['_IND_ROTATION_QUEUE'] = q
    except Exception:
        globals()['_IND_ROTATION_QUEUE'] = list(raw)
    cur_coin = ''
    try:
        st = (snapshot or {}).get('state') or {}
        if isinstance(st, dict):
            cur_coin = str(st.get('active_coin') or st.get('coin_selected') or st.get('current_coin') or '').upper().strip()
    except Exception:
        cur_coin = ''
    rs = str(reason or '').upper().strip()
    if len(raw) > 2 and 'MAIN_SCAN' not in rs:
        picked_seed = []
        if cur_coin and cur_coin in raw:
            picked_seed.append(cur_coin)
        for _seed in b1_seed_coins:
            if _seed in raw and _seed not in picked_seed:
                picked_seed.append(_seed)
                break
        try:
            q = list(globals().get('_IND_ROTATION_QUEUE') or [])
            q = [c for c in q if c in raw]
            if not q:
                q = list(raw)
            rot_pick = ''
            for _c in q:
                if _c not in picked_seed:
                    rot_pick = _c
                    break
            if rot_pick:
                picked_seed.append(rot_pick)
                q = [c for c in q if c != rot_pick] + [rot_pick]
                globals()['_IND_ROTATION_QUEUE'] = q
            if len(picked_seed) >= min(2, len(raw)):
                picked = picked_seed[:min(2, len(raw))]
                deferred = [c for c in raw if c not in picked]
                try:
                    if isinstance(snapshot, dict):
                        snapshot.setdefault('_ind_priority_debug', {})
                        snapshot['_ind_priority_debug'].update({'reason': str(reason or ''), 'picked': list(picked), 'deferred': list(deferred), 'mode': ('current_page_plus_b1_seed_priority' if b1_seed_coins else 'current_plus_rotation'), 'current_coin': cur_coin, 'rotation_queue': list(q), 'b1_seed_coins': list(b1_seed_coins)})
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_955', _e)
                    pass
                return picked, deferred
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_956', _e)
            pass
    if len(raw) <= max_batch:
        return raw, []

    if not any(k in rs for k in ('MAIN_SCAN', 'ASYNC_RETRY', 'RECOVER', 'ROUND_START')):
        return raw, []

    now_ts = float(time.time())

    cd_map = globals().get('_EXEC_COIN_COOLDOWN_UNTIL') or {}
    if not isinstance(cd_map, dict):
        cd_map = {}
    def _cd_left(c: str) -> float:
        try:
            return max(0.0, float(cd_map.get(c, 0.0)) - now_ts)
        except Exception:
            return 0.0

    cache_map = _ind_cache_latest_dict()
    def _age_sec(c: str) -> float:
        try:
            item = (cache_map or {}).get(c) if isinstance(cache_map, dict) else None
            ts = float((item or {}).get('ts') or 0.0)
            if ts <= 0.0:
                return 1e12
            return max(0.0, now_ts - ts)
        except Exception:
            return 1e12

    last_pick = globals().get('_IND_REFRESH_LAST_PICK') or []
    if not isinstance(last_pick, list):
        last_pick = []
    last_pick = [str(x or '').upper().strip() for x in last_pick if str(x or '').strip()]

    try:
        ages = {c: _age_sec(c) for c in raw}
        max_age = max(ages.values() or [0.0])
        has_very_old = any((a >= 45.0) for a in ages.values()) or any((a >= 1e11) for a in ages.values())
    except Exception:
        ages = {}
        max_age = 0.0
        has_very_old = True

    rr_idx = int(globals().get('_IND_REFRESH_RR_IDX') or 0)
    if rr_idx < 0:
        rr_idx = 0

    pos_all = ((snapshot or {}).get('positions') or {}) if isinstance((snapshot or {}).get('positions'), dict) else {}
    def _has_pos(c: str) -> int:
        try:
            ext = ((pos_all.get('EXT') or {}) if isinstance(pos_all.get('EXT'), dict) else {}).get(c) or {}
            var = ((pos_all.get('VAR') or {}) if isinstance(pos_all.get('VAR'), dict) else {}).get(c) or {}
            ext_nt = abs(float(ext.get('notional_u') or 0.0))
            var_nt = abs(float(var.get('notional_u') or 0.0))
            if ext_nt > 1e-6 or var_nt > 1e-6:
                return 1
            if str(ext.get('side') or '').upper() in ('LONG','SHORT') or str(var.get('side') or '').upper() in ('LONG','SHORT'):
                return 1
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_957', _e)
            pass
        return 0

    scored = []
    for i, c in enumerate(raw):
        age = ages.get(c, _age_sec(c))
        cd_left = _cd_left(c)
        in_last = 1 if c in last_pick else 0
        has_pos = _has_pos(c)

        penal_last = 1 if (has_very_old and in_last) else 0
        penal_cd = 1 if cd_left > 0.0 else 0

        rr_offset = (i - rr_idx) % max(1, len(raw))

        worst_loss_mag = 0.0
        try:
            if isinstance(snapshot, dict):
                pos_all = snapshot.get('positions') or {}
                extp = ((pos_all.get('EXT') or {}) if isinstance(pos_all, dict) else {})
                varp = ((pos_all.get('VAR') or {}) if isinstance(pos_all, dict) else {})
                pe = (extp.get(c) or {}) if isinstance(extp, dict) else {}
                pv = (varp.get(c) or {}) if isinstance(varp, dict) else {}
                def _pct(p: dict) -> float:
                    try:
                        if not isinstance(p, dict):
                            return 0.0
                        if float(p.get('notional_u') or 0.0) <= 0.0:
                            return 0.0
                        if p.get('pnl_pct') is not None:
                            return float(p.get('pnl_pct') or 0.0)
                        nu = abs(float(p.get('notional_u') or 0.0))
                        if nu <= 0:
                            return 0.0
                        up = float(p.get('upnl_u') if p.get('upnl_u') is not None else (p.get('upnl_usd') or 0.0))
                        return float(up) / float(max(nu, 1.0))
                    except Exception:
                        return 0.0
                worst_pct = float(min(_pct(pe), _pct(pv)))
                worst_loss_mag = float(max(0.0, -worst_pct))
        except Exception:
            worst_loss_mag = 0.0

        need_b1_seed = 1 if c in b1_seed_coins else 0
        if 'MAIN_SCAN' in rs:
            need_b1_seed = 0
        score = (
            need_b1_seed,                      # 缺币待首开绝对优先（MAIN_SCAN 下不压过已有持仓币）
            1 if age >= 1e11 else 0,           # cache_missing / 极旧
            worst_loss_mag,                    # 最亏优先（loss magnitude）
            age,                                # 越旧越优先
            has_pos,                             # 有仓优先一点
            -penal_last,                         # 避免连续重复
            -penal_cd,                           # 冷却强降权
            -rr_offset                           # 轮转打散
        )
        scored.append((score, c, {'age_sec': age, 'has_pos': has_pos, 'cd_left': cd_left, 'in_last': in_last, 'need_b1_seed': bool(c in b1_seed_coins)}))

    scored.sort(key=lambda x: x[0], reverse=True)

    picked = []
    deferred = []
    picked_meta = []
    for score, c, meta in scored:
        if meta.get('cd_left', 0.0) > 0.0 and len(picked) < max_batch:
            deferred.append(c)
            continue
        if len(picked) < max_batch:
            picked.append(c)
            picked_meta.append(meta)
        else:
            deferred.append(c)

    if (not picked) and scored:
        picked = [c for _, c, _ in scored[:max_batch]]
        deferred = [c for _, c, _ in scored[max_batch:]]
        picked_meta = [m for _, _, m in scored[:max_batch]]

    try:
        globals()['_IND_REFRESH_LAST_PICK'] = list(picked)
        globals()['_IND_REFRESH_RR_IDX'] = int((rr_idx + max(1, len(picked))) % max(1, len(raw)))
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_958', _e)
        pass
    try:
        if isinstance(snapshot, dict):
            snapshot.setdefault('_ind_priority_debug', {})
            snapshot['_ind_priority_debug'] = {
                'reason': str(reason or ''),
                'max_batch': int(max_batch),
                'picked': list(picked),
                'deferred': list(deferred),
                'picked_meta': picked_meta,
                'b1_seed_coins': list(b1_seed_coins),
            }
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_959', _e)
        pass
    return picked, deferred

def _postcheck_req_action_lower(req_any: Any) -> str:
    """统一解析 action（动作）字段，避免 action_type/action 混乱导致 UNKNOWN。"""
    try:
        a = str(getattr(req_any, "action_type", "") or "").strip()
        if not a:
            a = str(getattr(req_any, "action", "") or "").strip()
        if not a:
            if isinstance(req_any, dict):
                a = str(req_any.get("action_type") or req_any.get("action") or "").strip()
        return str(a or "").lower()
    except Exception:
        return ""

def _is_coin_flat(snapshot_any: Any, coin: str) -> bool:
    """判断 coin 是否双平台均无持仓（用于动作后预算/网格桶清空条件）。"""
    try:
        c = str(coin or '').upper().strip()
        if not c:
            return False
        snap = snapshot_any if isinstance(snapshot_any, dict) else {}
        pos_all = (snap.get('positions') or {}) if isinstance(snap.get('positions'), dict) else {}
        def _has_leg(pp: str) -> bool:
            try:
                it = (pos_all.get(pp) or {}).get(c) or {}
                side = str(it.get('side') or '').upper().strip()
                notional = float(it.get('notional_u') or it.get('val_u') or 0.0)
                if side in ('LONG','SHORT') and abs(notional) > 1e-6:
                    return True
                if bool(it.get('has')) and abs(notional) > 1e-6:
                    return True
            except Exception:
                return False
            return False
        return (not _has_leg('EXT')) and (not _has_leg('VAR'))
    except Exception:
        return False

def _postcheck_validate_effect(req_any: Any, pre: Dict[str, Any], post: Dict[str, Any]) -> tuple[bool, str, Dict[str, Any]]:
    state, reason, detail = _postcheck_validate_effect_v2(req_any, pre, post)
    return state == 'success', reason, detail

def _a1_get_adx_rsi(snapshot: dict, coin: str) -> tuple[float | None, float | None]:
    """从快照中读取 ADX/RSI（由 M2 扫描维护到 snapshot['indicators'][coin]）。

    重要：
    - HP（最高权限）不负责“切页读取指标”，只消费快照中的缓存值（更稳、更不干扰 UI）。
    """
    c = str(coin or "").upper()
    adx = None
    rsi = None
    try:
        ind = None
        if isinstance(snapshot, dict):
            ind = (snapshot.get("indicators") or {}).get(c)
            if not isinstance(ind, dict):
                co = (snapshot.get("coins") or {}).get(c) if isinstance(snapshot.get("coins"), dict) else None
                if isinstance(co, dict):
                    ind = co.get("indicators")
        if isinstance(ind, dict):
            try:
                adx = ind.get("adx")
            except Exception:
                adx = None
            try:
                rsi = ind.get("rsi")
            except Exception:
                rsi = None
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    try:
        adx = float(adx) if adx is not None else None
    except Exception:
        adx = None
    try:
        rsi = float(rsi) if rsi is not None else None
    except Exception:
        rsi = None

    return adx, rsi

def _trend_alpha_guard_for_b2_m10(snapshot: dict | None, coin: str) -> dict:
    """统一给 B2/M10 用的趋势保护视图。
    人话：只要这个币已经进入趋势主赚钱态，就别让 B2/M10 去打断赢家腿。
    """
    out = {
        'active': False,
        'coin': str(coin or '').upper().strip(),
        'trend_state': 'NORMAL',
        'trend_alpha': 0,
        'trend_side': '',
        'runner_protect': 0,
        'opp_side_frozen': 0,
        'reason': 'trend_guard_inactive',
        'rsi': None,
        'adx': None,
        'same_notional_u': 0.0,
        'opp_notional_u': 0.0,
        'same_upnl_u': 0.0,
        'opp_upnl_u': 0.0,
        'cover_ratio': None,
    }
    try:
        c = str(coin or '').upper().strip()
        if not c:
            out['reason'] = 'trend_guard_bad_coin'
            return out
        adx, rsi = _a1_get_adx_rsi(snapshot or {}, c)
        out['rsi'] = rsi
        out['adx'] = adx
        trend_side = _m9_trend_side_for_coin(c, rsi, adx)
        out['trend_side'] = str(trend_side or '')
        if trend_side not in ('LONG', 'SHORT'):
            out['reason'] = 'trend_guard_no_trend_side'
            return out
        st = _m9_resolve_trend_state(snapshot or {}, c, trend_side, rsi=rsi) or {}
        out.update({
            'trend_state': str(st.get('trend_state') or 'NORMAL'),
            'trend_alpha': int(bool(st.get('trend_alpha', 0))),
            'runner_protect': int(bool(st.get('runner_protect', 0))),
            'opp_side_frozen': int(bool(st.get('opp_side_frozen', 0))),
            'reason': str(st.get('reason') or 'trend_guard_resolved'),
            'same_notional_u': float(st.get('same_notional_u') or 0.0),
            'opp_notional_u': float(st.get('opp_notional_u') or 0.0),
            'same_upnl_u': float(st.get('same_upnl_u') or 0.0),
            'opp_upnl_u': float(st.get('opp_upnl_u') or 0.0),
            'cover_ratio': st.get('cover_ratio'),
        })
        out['active'] = bool(out.get('trend_alpha')) and str(out.get('trend_state') or '') == 'TREND_ALPHA'
        return out
    except Exception as _e:
        out['reason'] = f'trend_guard_exc:{type(_e).__name__}'
        return out

def _a1_check_add_signal(snapshot: dict, coin: str, sides: list[str], module: str = "", action: str = "") -> tuple[bool, str]:
    """最高权限 3：加仓信号闸（仅拦截“增加敞口”的动作，不影响止盈/减仓）。

    规则（按你最新要求）：
    - M9 increase：不再受 ADX>=40 一刀切拦截；ADX 只用于策略层参考，不在 A1 执行前二次封死网格。
    - 其它加仓动作：仍保留 ADX >= 40 禁止加仓（只允许继续止盈/减仓）
    - RSI < 50：只允许 SHORT
    - RSI > 50：只允许 LONG
    - RSI == 50：严格禁止
    """
    adx, rsi = _a1_get_adx_rsi(snapshot, coin)

    _mod = str(module or "").upper().strip()
    _act = str(action or "").lower().strip()
    _is_m9_increase = (_mod == "M9" and _act == "increase")

    if (adx is None) or (rsi is None):
        return False, f"缺少ADX/RSI指标，禁止加仓 coin={str(coin).upper()} adx={adx} rsi={rsi}"

    if (not _is_m9_increase) and (adx is not None):
        try:
            if float(adx) >= 40.0:
                return False, f"ADX>=40 禁止加仓（只允许止盈） adx={float(adx):.2f}"
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    allowed = None  # None 表示不限制（信号缺失/不启用）
    if rsi is not None:
        try:
            if float(rsi) < 50.0:
                allowed = {"SHORT"}
            elif float(rsi) > 50.0:
                allowed = {"LONG"}
            else:
                return False, f"RSI==50 严格禁止加仓 rsi={float(rsi):.2f}"
        except Exception:
            allowed = None

    if allowed is None:
        return True, "ok_no_rsi_limit_or_missing"

    ss = []
    for s0 in (sides or []):
        try:
            x = str(s0 or "").upper().strip()
        except Exception:
            x = ""
        if x in ("LONG", "SHORT"):
            ss.append(x)

    if not ss:
        return True, "ok_no_side_specified"

    for x in ss:
        if x not in allowed:
            try:
                rsi_f = float(rsi)
            except Exception:
                rsi_f = -1.0
            return False, f"RSI 限制：只允许加 {list(allowed)[0]}（rsi={rsi_f:.2f}），但请求为 {x}"

    return True, "ok"

def _a1_patch_snapshot_with_req_indicators(snapshot: dict, req: 'Request', coin: str) -> dict:
    """确保 snapshot 中有 coin 的 indicators 字段（优先快照，其次统一指标缓存真相源）。

    目的：避免偶发 M2 未能回填 indicators 时，HP 信号闸误判为“缺失”。
    说明：这里不再直接读取旧 `_IND_CACHE` 口径，而是统一走指标缓存真相源。
    """
    if not isinstance(snapshot, dict):
        return snapshot
    c = str(coin or "").upper()
    try:
        snapshot.setdefault("indicators", {})
    except Exception:
        try:
            snapshot["indicators"] = {}
        except Exception:
            return snapshot

    try:
        cur = (snapshot.get("indicators") or {}).get(c)
    except Exception:
        cur = None
    if isinstance(cur, dict) and (cur.get("adx") is not None or cur.get("rsi") is not None):
        return snapshot

    nowt = time.time()
    try:
        ind_max_stale = float(cfg_getf_runtime("IND_MAX_STALE_SEC", 900.0) or 900.0)
    except Exception:
        ind_max_stale = 900.0
    try:
        v = (_ind_cache_latest_dict() or {}).get(c)
    except Exception:
        v = None
    if isinstance(v, dict):
        try:
            ts0 = float(v.get("ts") or v.get("ts_sec") or 0.0)
        except Exception:
            ts0 = 0.0
        if ts0 > 0 and (nowt - ts0) <= ind_max_stale:
            try:
                _v2 = dict(v)
                _v2.setdefault("ind_ts", _v2.get("ts"))
                snapshot["indicators"][c] = _v2
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    return snapshot
def _a1_check_hedge_state_before_add(snapshot: dict, req: 'Request', coin: str, mod: str, act: str) -> tuple[bool, str, str, dict]:
    try:
        if str(mod or '').upper().strip() == 'X1':
            return True, 'OK', 'a1_x1_bypass', {'bypass': True}
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    """最高权限 0：所有增加敞口动作执行前必须核实对冲状态（同币一多一空）。

    目标：避免同向/缺腿时继续加仓或补腿，导致越补越错、越补越大。
    - LEGACY_DELETED（补腿）属于结构修复动作：允许在缺腿时补齐，但必须保证新增腿方向与已有腿反向
    - 其它增加敞口动作（B1（首次开仓）/M9（网格加仓）等）：必须已处于对冲状态（两边都有且方向相反），否则一律阻断
    """
    coin = str(coin or '').upper()
    mod = str(mod or '').upper()

    try:
        _sub = str(getattr(req, 'submodule', '') or '').upper().strip()
        _meta = getattr(req, 'meta', None)
        _is_w1 = (_sub == 'W1') or (isinstance(_meta, dict) and bool(_meta.get('w1') or (_meta.get('from') == 'W1')))
        if _is_w1:
            mod = 'W1'
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_960', _e)
        pass
    act = str(act or '').lower()

    es, en = _a1_extract_leg(snapshot, coin, 'EXT')
    vs, vn = _a1_extract_leg(snapshot, coin, 'VAR')

    has_e = _has_leg_u(en) and (es != 'NONE')
    has_v = _has_leg_u(vn) and (vs != 'NONE')
    both = has_e and has_v

    if mod == 'B1' and act in ('open_leg', 'open_single_leg', 'open_single', 'open_pair', 'open', 'open_first', 'open_more'):
        try:
            _has_e_b1 = (float(en) > float(B1_NO_LEG_EPS_U)) and (es != 'NONE')
            _has_v_b1 = (float(vn) > float(B1_NO_LEG_EPS_U)) and (vs != 'NONE')
        except Exception:
            _has_e_b1 = bool(has_e)
            _has_v_b1 = bool(has_v)

        if (not _has_e_b1) and (not _has_v_b1):
            return True, 'ok', 'b1_open_leg_no_position_allow', {'bypass': True, 'mode': 'b1_open_leg', 'eps_u': float(B1_NO_LEG_EPS_U)}

        _detail_b1 = {
            'coin': coin,
            'ext': {'side': es, 'notional_u': en},
            'var': {'side': vs, 'notional_u': vn},
            'b1_eps_u': float(B1_NO_LEG_EPS_U),
            'b1_has_ext': bool(_has_e_b1),
            'b1_has_var': bool(_has_v_b1),
            'module': mod,
            'action': act,
        }

        try:
            _meta_b1 = (req.meta if isinstance(getattr(req, 'meta', None), dict) else {}) or {}
        except Exception:
            _meta_b1 = {}
        _missing_leg_mode_b1 = bool(_meta_b1.get('missing_leg_mode')) or (str(_meta_b1.get('reason_source') or '').lower() == 'missing_leg_b1')
        _missing_leg_scene_b1 = bool(_has_e_b1) ^ bool(_has_v_b1)
        if _missing_leg_mode_b1 and _missing_leg_scene_b1:
            _need_plat_b1 = 'VAR' if bool(_has_e_b1) and (not bool(_has_v_b1)) else ('EXT' if bool(_has_v_b1) and (not bool(_has_e_b1)) else '')
            _exist_side_b1 = str(es if bool(_has_e_b1) else vs).upper().strip()
            _need_side_b1 = ('SHORT' if _exist_side_b1 == 'LONG' else ('LONG' if _exist_side_b1 == 'SHORT' else ''))
            try:
                _req_plat_b1 = str((req.params or {}).get('platform') or getattr(req, 'platform', '') or _meta_b1.get('platform') or '').upper().strip()
            except Exception:
                _req_plat_b1 = str(getattr(req, 'platform', '') or _meta_b1.get('platform') or '').upper().strip()
            try:
                _req_side_b1 = str((req.params or {}).get('side') or getattr(req, 'side', '') or _meta_b1.get('side') or '').upper().strip()
            except Exception:
                _req_side_b1 = str(getattr(req, 'side', '') or _meta_b1.get('side') or '').upper().strip()
            _detail_b1.update({
                'missing_leg_mode': True,
                'need_platform': _need_plat_b1,
                'need_side': _need_side_b1,
                'req_platform': _req_plat_b1,
                'req_side': _req_side_b1,
            })
            if _req_plat_b1 == _need_plat_b1 and _req_side_b1 == _need_side_b1 and _need_plat_b1 and _need_side_b1:
                return True, 'ok', 'b1_missing_leg_legacy_deleted_allow（B1补缺腿放行）', _detail_b1
            return False, 'a1_b1_missing_leg_legacy_deleted_mismatch', 'b1_missing_leg_legacy_deleted_mismatch（B1补缺腿平台或方向不匹配）', _detail_b1

        return False, 'a1_b1_open_leg_requires_no_position', 'b1_open_leg_requires_no_position（单腿首开要求无仓）', _detail_b1

    if (not has_e) and (not has_v):
        _detail_np = {
            'coin': coin,
            'ext': {'side': es, 'notional_u': en},
            'var': {'side': vs, 'notional_u': vn},
            'module': mod,
            'action': act,
            'no_leg_eps_u': float(B1_NO_LEG_EPS_U),
        }
        if mod in ('M9', ('M9' + 'X'), 'W1') and act in ('increase', 'add_layer', 'increase_layer', 'open', 'open_leg', 'grid_add', 'grid_increase'):
            _detail_np['cold_start_allow'] = True
            return True, 'ok', 'a1_no_position_m9_w1_cold_start_allow（无腿允许M9/W1冷启动首层）', _detail_np
        return False, 'a1_hedge_no_position_block', 'hedge_no_position（无仓位） block_add（禁止加仓）', _detail_np

    same_dir = both and (es == vs)
    missing_leg = (has_e and (not has_v)) or (has_v and (not has_e))

    detail = {
        'coin': coin,
        'ext': {'side': es, 'notional_u': en},
        'var': {'side': vs, 'notional_u': vn},
        'same_dir': same_dir,
        'missing_leg': missing_leg,
        'module': mod,
        'action': act,
    }

    if same_dir:
        if mod in ("M9",("M9" + "X")) and act in ("increase", "add_layer", "increase_layer"):
            detail["m9_same_dir_allow"] = True
            return True, "ok", "a1_same_dir_m9_allow（同向允许M9网格加层）", detail

        if mod in ("W1",) and act in ("increase", "add_layer", "increase_layer"):
            detail["w1_same_dir_allow"] = True
            return True, "ok", "a1_same_dir_w1_allow（同向允许W1网格加层）", detail

        else:

            try:
                pm = (req.params or {}) if isinstance(req.params, dict) else {}
            except Exception:
                pm = {}
            try:
                mt = (req.meta or {}) if isinstance(req.meta, dict) else {}
            except Exception:
                mt = {}
            legacy_fix_mode = bool(pm.get("legacy_fix_mode") or mt.get("legacy_fix_mode") or False)
            reduce_mode = bool(pm.get("reduce_mode") or pm.get("is_reduce") or False)

            if not (mod == "LEGACY_DELETED" and legacy_fix_mode and reduce_mode):
                if act in ("add_leg", "increase", "open", "open_pair", "open_more", "add_layer", "increase_layer"):
                    return False, 'a1_hedge_same_dir_block', 'hedge_same_dir（同向） block_add（禁止加仓）', detail

    if (mod in ('LEGACY_DELETED','LEGACY_DELETED')) and act == 'add_leg':
        plat = str((req.params or {}).get('platform') or (req.platform or '') or '').upper()
        if plat not in ('EXT', 'VAR'):
            return False, 'a1_legacy_deleted_bad_platform_block', 'legacy_deleted_platform_missing（补腿平台缺失）', detail

        short_leg = (has_e and has_v and (not same_dir) and (float(abs(float(en or 0.0) - float(vn or 0.0))) > 1e-9))
        allow = bool(missing_leg or short_leg)
        if not allow:
            return False, 'a1_legacy_deleted_not_legacy_deleted_scene_block', 'legacy_deleted_requires_missing_or_short_leg（补腿仅允许缺腿/短腿修复）', detail

        try:
            en_f = float(en or 0.0)
        except Exception:
            en_f = 0.0
        try:
            vn_f = float(vn or 0.0)
        except Exception:
            vn_f = 0.0

        exp_plat = None
        exp_side = "NONE"
        exp_amt10 = 0.0
        post_gap = None

        if missing_leg:
            if has_e and (not has_v):
                exp_plat = "VAR"
                exist_side = _a1_norm_side(es)
                exp_side = ("SHORT" if exist_side == "LONG" else ("LONG" if exist_side == "SHORT" else "LONG"))
                exp_amt10 = float(_round_usd10(en_f))
                post_gap = float(abs(en_f - exp_amt10))
            elif has_v and (not has_e):
                exp_plat = "EXT"
                exist_side = _a1_norm_side(vs)
                exp_side = ("SHORT" if exist_side == "LONG" else ("LONG" if exist_side == "SHORT" else "LONG"))
                exp_amt10 = float(_round_usd10(vn_f))
                post_gap = float(abs(vn_f - exp_amt10))
            else:
                exp_plat = plat
                exp_side = "NONE"
                exp_amt10 = 0.0
                post_gap = None
        else:
            if en_f <= vn_f:
                exp_plat = "EXT"
                exp_side = _a1_norm_side(es)
                exp_amt10 = float(_round_usd10(max(vn_f - en_f, 0.0)))
                post_gap = float(abs(vn_f - (en_f + exp_amt10)))
            else:
                exp_plat = "VAR"
                exp_side = _a1_norm_side(vs)
                exp_amt10 = float(_round_usd10(max(en_f - vn_f, 0.0)))
                post_gap = float(abs(en_f - (vn_f + exp_amt10)))

        detail["legacy_deleted_scene_missing_leg"] = bool(missing_leg)
        detail["legacy_deleted_scene_short_leg"] = bool(short_leg)
        detail["legacy_deleted_expect_platform"] = exp_plat
        detail["legacy_deleted_expect_side"] = exp_side
        detail["legacy_deleted_expect_amount"] = exp_amt10
        detail["legacy_deleted_expect_post_gap"] = post_gap

        if exp_plat and plat != exp_plat:
            return False, 'a1_legacy_deleted_wrong_platform_block', 'legacy_deleted_wrong_platform（补腿平台错误）', detail

        side_req = _a1_norm_side(str((req.params or {}).get('side') or ''))
        if side_req == 'NONE':
            return False, 'a1_legacy_deleted_side_missing_block', 'legacy_deleted_side_missing（补腿方向缺失）', detail
        other_side = 'NONE'
        try:
            if exp_plat == 'EXT':
                other_side = _a1_norm_side(vs)
            elif exp_plat == 'VAR':
                other_side = _a1_norm_side(es)
        except Exception:
            other_side = 'NONE'

        need_side = 'NONE'
        if other_side == 'LONG':
            need_side = 'SHORT'
        elif other_side == 'SHORT':
            need_side = 'LONG'

        detail['legacy_deleted_other_side'] = other_side
        detail['legacy_deleted_need_side'] = need_side

        if need_side != 'NONE' and side_req != need_side:
            return False, 'a1_legacy_deleted_side_mismatch_block', 'legacy_deleted_side_mismatch（补腿方向不符合对冲反向要求）', detail

        if need_side == 'NONE' and exp_side != 'NONE' and side_req != exp_side:
            return False, 'a1_legacy_deleted_side_mismatch_block', 'legacy_deleted_side_mismatch（补腿方向不符合修复期望）', detail

        try:
            amt0 = (req.params or {}).get('amount_usd') if isinstance(req.params, dict) else None
            if amt0 is None:
                amt0 = (req.params or {}).get('usd') if isinstance(req.params, dict) else None
            if amt0 is None:
                amt0 = getattr(req, 'amount_usd', None)
            if amt0 is None:
                amt0 = getattr(req, 'usd', None)
            if amt0 is None:
                try:
                    _m = getattr(req, 'meta', None)
                    if isinstance(_m, dict):
                        for _k in ('amount_usd', 'usd', 'LEGFIX__amount_usd', 'LEGFIX__amount_usd', 'B1__amount_usd', 'X1__amount_usd'):
                            _v = _m.get(_k)
                            if _v not in (None, '', 0, 0.0):
                                amt0 = _v
                                break
                except Exception as _e:
                    _record_internal_guard('legacy_deleted_amount_meta_read_failed', _e)
            amt = _coerce_positive_float_or_none(amt0, tag='a1_legacy_deleted_amount')
        except Exception as _e:
            _record_internal_guard('legacy_deleted_amount_parse_failed', _e)
            amt = None
        if amt is None or float(amt) <= 0:
            detail['legacy_deleted_amount_raw'] = amt0
            return False, 'a1_legacy_deleted_amount_invalid_block', 'legacy_deleted_amount_invalid（补腿金额缺失或非法，禁止默认归零）', detail
        amt10 = float(_round_usd10(float(amt)))

        detail['legacy_deleted_amount'] = amt10

        if amt10 < 40.0:
            return False, 'a1_legacy_deleted_amount_bad_block', 'legacy_deleted_amount_too_small（补腿金额过小）', detail

        if exp_amt10 < 10.0:
            try:
                detail['legacy_deleted_expect_amount'] = float(exp_amt10)
                detail['legacy_deleted_expect_platform'] = str(exp_plat or '')
                detail['legacy_deleted_expect_side'] = str(exp_side or '')
                detail['legacy_deleted_en'] = float(en_f)
                detail['legacy_deleted_vn'] = float(vn_f)
                detail['legacy_deleted_missing_leg'] = bool(missing_leg)
                if post_gap is not None:
                    detail['legacy_deleted_post_gap'] = float(post_gap)
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

            return False, 'a1_legacy_deleted_amount_bad_block', f"legacy_deleted_expect_amount_bad（补腿期望金额无效） exp={float(exp_amt10):.0f} en={float(en_f):.2f} vn={float(vn_f):.2f} missing_leg={bool(missing_leg)}", detail
        amt_tol_u = 100.0
        detail['legacy_deleted_amount_tol_u'] = float(amt_tol_u)
        if float(abs(amt10 - exp_amt10)) > float(amt_tol_u) + 1e-6:
            return False, 'a1_legacy_deleted_amount_mismatch_block', 'legacy_deleted_amount_mismatch（补腿金额偏离超过允许误差）', detail

        try:
            post_gap_tol_u = 100.0  # 你确认：post_gap 放宽到 100U
            detail['legacy_deleted_post_gap_tol_u'] = float(post_gap_tol_u)
            if post_gap is not None and float(post_gap) > float(post_gap_tol_u) + 1e-6:
                return False, 'a1_legacy_deleted_post_gap_bad_block', 'legacy_deleted_post_gap_too_large（补腿后仍未拉平对冲差额）', detail
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

        return True, 'ok', 'legacy_deleted_hedge_legacy_deleted_ok（补腿结构修复核验通过）', detail

    if act == 'open_pair':
        if has_e or has_v:
            return False, 'a1_open_pair_hedge_bad_block', 'open_pair_requires_no_position（首次开仓要求无仓）', detail
        legs = (req.params or {}).get('legs') or []
        sides = []
        for leg in legs:
            sides.append(_a1_norm_side(str((leg or {}).get('side') or '')))
        uniq = {s for s in sides if s != 'NONE'}
        if len(uniq) < 2:
            detail['legs_sides'] = sides
            return False, 'a1_open_pair_sides_bad_block', 'open_pair_requires_opposite_sides（首次开仓两腿必须反向）', detail
        return True, 'ok', 'open_pair_hedge_check_ok（首次开仓对冲核验通过）', detail

    if not both:
        if mod == "LEGACY_DELETED" and act == "add_leg":
            try:
                pm = (req.params or {}) if isinstance(req.params, dict) else {}
            except Exception:
                pm = {}
            try:
                mt = (req.meta or {}) if isinstance(req.meta, dict) else {}
            except Exception:
                mt = {}
            legacy_fix_mode = bool(pm.get("legacy_fix_mode") or mt.get("legacy_fix_mode") or mt.get("auto_legacy_fix") or False)

            if legacy_fix_mode and missing_leg:
                plat = str(pm.get("platform") or req.platform or "").upper()
                side_req = _a1_norm_side(str(pm.get("side") or pm.get("dir") or pm.get("direction") or ""))

                if has_e and (not has_v):
                    need_plat = "VAR"
                    need_side = _a1_norm_side("LONG" if es == "SHORT" else "SHORT")
                elif has_v and (not has_e):
                    need_plat = "EXT"
                    need_side = _a1_norm_side("LONG" if vs == "SHORT" else "SHORT")
                else:
                    need_plat, need_side = "", "NONE"

                if plat == need_plat and side_req == need_side and need_side != "NONE":
                    detail["legacy_deleted_allow"] = True
                    detail["legacy_deleted_need_plat"] = need_plat
                    detail["legacy_deleted_need_side"] = need_side
                    return True, "ok", "legacy_deleted_legacy_deleted_missing_leg_ok（LEGACY_DELETED修复缺腿放行）", detail

        if mod == "X1" and act == "add_leg":
            try:
                pm = (req.params or {}) if isinstance(req.params, dict) else {}
            except Exception:
                pm = {}
            try:
                mt = (req.meta or {}) if isinstance(req.meta, dict) else {}
            except Exception:
                mt = {}
            legacy_fix_mode = bool(pm.get("legacy_fix_mode") or mt.get("legacy_fix_mode") or mt.get("auto_legacy_fix") or False)

            if legacy_fix_mode and missing_leg:
                plat = str(pm.get("platform") or req.platform or "").upper()
                side_req = _a1_norm_side(str(pm.get("side") or pm.get("dir") or pm.get("direction") or ""))

                if has_e and (not has_v):
                    need_plat = "VAR"
                    need_side = _a1_norm_side("LONG" if es == "SHORT" else "SHORT")
                elif has_v and (not has_e):
                    need_plat = "EXT"
                    need_side = _a1_norm_side("LONG" if vs == "SHORT" else "SHORT")
                else:
                    need_plat, need_side = "", "NONE"

                if plat == need_plat and side_req == need_side and need_side != "NONE":
                    detail["x1_legacy_deleted_allow"] = True
                    detail["x1_need_plat"] = need_plat
                    detail["x1_need_side"] = need_side
                    return True, "ok", "x1_legacy_deleted_missing_leg_ok（X1修复缺腿放行）", detail

        try:
            if mod in ("M9",("M9" + "X")) and act in ("increase", "add_layer", "increase_layer", "grid_increase", "grid_add", "grid_add_layer"):
                plat_req = str((req.params or {}).get('platform') or (getattr(req, 'platform', '') or '') or '').upper()
                side_req = _a1_norm_side(str((req.params or {}).get('side') or (getattr(req, 'side', '') or '') or ''))
                if plat_req in ("EXT", "VAR") and side_req in ("LONG", "SHORT"):
                    if plat_req == "EXT" and has_e and (not has_v) and side_req == _a1_norm_side(es):
                        detail["m9_missing_leg_allow"] = True
                        detail["m9_allow_plat"] = "EXT"
                        return True, "ok", "m9_allow_on_existing_leg_ext（缺腿仅EXT有仓位，允许EXT网格）", detail
                    if plat_req == "VAR" and has_v and (not has_e) and side_req == _a1_norm_side(vs):
                        detail["m9_missing_leg_allow"] = True
                        detail["m9_allow_plat"] = "VAR"
                        return True, "ok", "m9_allow_on_existing_leg_var（缺腿仅VAR有仓位，允许VAR网格）", detail
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

        try:
            if mod in ("M9", ("M9" + "X")) and act in (
                "decrease", "reduce", "close", "close_layer", "decrease_layer", "grid_decrease", "grid_tp", "tp", "take_profit"
            ):
                plat_req = str((req.params or {}).get('platform') or (getattr(req, 'platform', '') or '') or '').upper()
                side_req = _a1_norm_side(str((req.params or {}).get('side') or (getattr(req, 'side', '') or '') or ''))

                if side_req == "NONE":
                    side_req = ""

                if plat_req == "EXT" and has_e and (not has_v):
                    if (not side_req) or (side_req == _a1_norm_side(es)):
                        detail["m9_missing_leg_allow"] = True
                        detail["m9_allow_plat"] = "EXT"
                        detail["m9_allow_act"] = str(act)
                        return True, "ok", "m9_allow_decrease_on_existing_leg_ext（缺腿允许EXT减仓/止盈）", detail
                if plat_req == "VAR" and has_v and (not has_e):
                    if (not side_req) or (side_req == _a1_norm_side(vs)):
                        detail["m9_missing_leg_allow"] = True
                        detail["m9_allow_plat"] = "VAR"
                        detail["m9_allow_act"] = str(act)
                        return True, "ok", "m9_allow_decrease_on_existing_leg_var（缺腿允许VAR减仓/止盈）", detail
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

        try:

            if missing_leg:
                mod_u = str(mod or '').upper()
                act_l = str(act or '').lower()
                pm = (req.params or {}) if isinstance(getattr(req, 'params', None), dict) else {}
                mt = (getattr(req, 'meta', None) or {}) if isinstance(getattr(req, 'meta', None), dict) else {}
                sub_u = str(pm.get('submodule') or pm.get('strategy') or pm.get('origin_mod') or mt.get('submodule') or mt.get('strategy') or mt.get('origin_mod') or '').upper()
                is_w1 = (mod_u == 'W1') or (sub_u == 'W1') or bool((mt.get('w1') or mt.get('W1')) or (str(mt.get('from') or '').upper() == 'W1') or (str(mt.get('origin_mod') or '').upper() == 'W1'))
                if is_w1 and (('increase' in act_l) or ('add' in act_l) or ('grid' in act_l)):
                    plat_req = str(pm.get('platform') or pm.get('plat') or getattr(req, 'platform', '') or '').upper()
                    side_raw = (pm.get('dir') or pm.get('side') or pm.get('direction') or pm.get('position_side') or pm.get('pos_side') or pm.get('side_req') or pm.get('trade_side') or getattr(req, 'side', '') or getattr(req, 'direction', '') or '')
                    side_req = _a1_norm_side(str(side_raw))
                    if (not side_req) and plat_req in ('EXT','VAR'):
                        if plat_req == 'EXT' and has_e:
                            side_req = _a1_norm_side(es)
                        elif plat_req == 'VAR' and has_v:
                            side_req = _a1_norm_side(vs)

                    if side_req in ('LONG','SHORT') and plat_req in ('EXT','VAR'):
                        try:
                            _mt = getattr(req, 'meta', None)
                            _mt = (_mt if isinstance(_mt, dict) else {})
                            _want_open_miss = bool(_mt.get('w1_missing_leg_open') or _mt.get('W1__missing_leg_open'))
                        except Exception:
                            _want_open_miss = False
                        if _want_open_miss:
                            if plat_req == 'EXT' and (not has_e):
                                detail['w1_missing_leg_open_allow'] = True
                                detail['w1_allow_plat'] = 'EXT'
                                detail['w1_allow_side'] = side_req
                                detail['w1_allow_act'] = str(act)
                                detail['w1_sub_u'] = sub_u
                            elif plat_req == 'VAR' and (not has_v):
                                detail['w1_missing_leg_open_allow'] = True
                                detail['w1_allow_plat'] = 'VAR'
                                detail['w1_allow_side'] = side_req
                                detail['w1_allow_act'] = str(act)
                                detail['w1_sub_u'] = sub_u

                        if plat_req == 'EXT' and ((has_e and side_req == _a1_norm_side(es)) or (detail.get('w1_missing_leg_open_allow') and detail.get('w1_allow_plat')=='EXT' and side_req == detail.get('w1_allow_side'))):
                            detail['w1_missing_leg_allow'] = True
                            detail['w1_allow_plat'] = 'EXT'
                            detail['w1_allow_side'] = side_req
                            detail['w1_allow_act'] = str(act)
                            detail['w1_sub_u'] = sub_u

                            try:
                                _desired = _desired_side_from_params(pm) or side_req
                                _ge_w1 = _gate_eval("W1", act_l, coin, _desired, snapshot, now_ts=time.time())
                                detail["w1_gate_eval"] = _ge_w1
                                if not bool(_ge_w1.get("allowed")):
                                    try:
                                        _pin("W1_FLOW", coin=coin, stage="A1_GATE_BLOCK", reason=str(_ge_w1.get("reason") or ""), plat=plat_req, side=side_req, mod=mod_u, act=act_l)
                                    except Exception as _e:
                                        _record_swallowed_exception('except_pass_line_961', _e)
                                        pass
                                    return False, "a1_w1_gate_block", f"w1_gate_block:{_ge_w1.get('reason')}", detail
                                try:
                                    _pin("W1_FLOW", coin=coin, stage="A1_GATE_OK", reason=str(_ge_w1.get("reason") or ""), plat=plat_req, side=side_req, mod=mod_u, act=act_l)
                                except Exception as _e:
                                    _record_swallowed_exception('except_pass_line_962', _e)
                                    pass
                            except Exception as _e:
                                detail["w1_gate_eval_exc"] = repr(_e)
                                try:
                                    _pin("W1_FLOW", coin=coin, stage="A1_GATE_EXC", reason=repr(_e), plat=plat_req, side=side_req, mod=mod_u, act=act_l)
                                except Exception as _e:
                                    _record_swallowed_exception('except_pass_line_963', _e)
                                    pass
                                return False, "a1_w1_gate_exc", "w1_gate_exc", detail

                            return True, 'ok', 'w1_allow_on_existing_leg_ext（缺腿允许EXT加仓/网格）', detail

                        if plat_req == 'VAR' and ((has_v and side_req == _a1_norm_side(vs)) or (detail.get('w1_missing_leg_open_allow') and detail.get('w1_allow_plat')=='VAR' and side_req == detail.get('w1_allow_side'))):
                            detail['w1_missing_leg_allow'] = True
                            detail['w1_allow_plat'] = 'VAR'
                            detail['w1_allow_side'] = side_req
                            detail['w1_allow_act'] = str(act)
                            detail['w1_sub_u'] = sub_u

                            try:
                                _desired = _desired_side_from_params(pm) or side_req
                                _ge_w1 = _gate_eval("W1", act_l, coin, _desired, snapshot, now_ts=time.time())
                                detail["w1_gate_eval"] = _ge_w1
                                if not bool(_ge_w1.get("allowed")):
                                    try:
                                        _pin("W1_FLOW", coin=coin, stage="A1_GATE_BLOCK", reason=str(_ge_w1.get("reason") or ""), plat=plat_req, side=side_req, mod=mod_u, act=act_l)
                                    except Exception as _e:
                                        _record_swallowed_exception('except_pass_line_964', _e)
                                        pass
                                    return False, "a1_w1_gate_block", f"w1_gate_block:{_ge_w1.get('reason')}", detail
                                try:
                                    _pin("W1_FLOW", coin=coin, stage="A1_GATE_OK", reason=str(_ge_w1.get("reason") or ""), plat=plat_req, side=side_req, mod=mod_u, act=act_l)
                                except Exception as _e:
                                    _record_swallowed_exception('except_pass_line_965', _e)
                                    pass
                            except Exception as _e:
                                detail["w1_gate_eval_exc"] = repr(_e)
                                try:
                                    _pin("W1_FLOW", coin=coin, stage="A1_GATE_EXC", reason=repr(_e), plat=plat_req, side=side_req, mod=mod_u, act=act_l)
                                except Exception as _e:
                                    _record_swallowed_exception('except_pass_line_966', _e)
                                    pass
                                return False, "a1_w1_gate_exc", "w1_gate_exc", detail

                            return True, 'ok', 'w1_allow_on_existing_leg_var（缺腿允许VAR加仓/网格）', detail

        except Exception as _e:

            _log_exc(mod='SYS', stage='EXC_PASS', e=_e)

        try:
            _meta = getattr(req, 'meta', None)
            _meta_d = _meta if isinstance(_meta, dict) else {}
            _is_w1 = (mod_u == 'W1') or bool(_meta_d.get('w1')) or (str(getattr(req, 'submodule', '') or '').upper() == 'W1')
            if _is_w1:
                try:
                    _desired = _desired_side_from_params(pm) or side_req
                except Exception:
                    _desired = side_req
                try:
                    _ge_w1b = _gate_eval("W1", act_l, coin, _desired, snapshot, now_ts=time.time())
                except Exception as _ge_e:
                    _ge_w1b = {"allowed": True,
        "would_block": False,
        "block_reason": "", "code": "gate_eval_exc", "reason": repr(_ge_e)}
                detail["w1_missing_leg_bypass"] = True
                detail["w1_gate_eval_bypass"] = _ge_w1b
                if bool(_ge_w1b.get("allowed")):
                    return True, 'ok', 'w1_bypass_missing_leg_block（缺腿允许W1执行）', detail
                return False, 'a1_w1_gate_block', 'w1_gate_block（缺腿场景W1未通过RSI/ADX）', detail
        except Exception as _e:
            detail["w1_bypass_exc"] = repr(_e)
            _log_exc(mod='SYS', stage='EXC_PASS', e=_e)

        try:
            _meta = getattr(req, 'meta', None)
            _meta_d = _meta if isinstance(_meta, dict) else {}
            _is_m9 = (mod_u == 'M9') or bool(_meta_d.get('m9')) or (str(getattr(req, 'submodule', '') or '').upper() == 'M9')
            if _is_m9:
                try:
                    _desired = _desired_side_from_params(pm) or side_req
                except Exception:
                    _desired = side_req
                _desired = str(_desired or '').upper()
                _pref_plat = ('EXT' if _desired == 'LONG' else ('VAR' if _desired == 'SHORT' else ''))
                detail["m9_missing_leg_bypass"] = True
                detail["m9_desired_side"] = _desired
                detail["m9_pref_plat"] = _pref_plat

                if (_desired in ('LONG', 'SHORT')) and (side_req == _desired) and (_pref_plat and plat_req == _pref_plat):
                    try:
                        _ge_m9b = _gate_eval("M9", act_l, coin, _desired, snapshot, now_ts=time.time())
                    except Exception as _ge_e:
                        _ge_m9b = {"allowed": True,
        "would_block": False,
        "block_reason": "", "code": "gate_eval_exc", "reason": repr(_ge_e)}
                    detail["m9_gate_eval_bypass"] = _ge_m9b
                    if bool(_ge_m9b.get("allowed")):
                        try:
                            _pin("M9_FLOW", coin=coin, stage="A1_MISSING_LEG_BYPASS_OK",
                                 reason=str(_ge_m9b.get("reason") or ""), plat=plat_req, side=side_req, mod=mod_u, act=act_l)
                        except Exception as _e:
                            _record_swallowed_exception('except_pass_line_967', _e)
                            pass
                        return True, 'ok', 'm9_bypass_missing_leg_block（缺腿允许M9按RSI方向执行）', detail

                    try:
                        _pin("M9_FLOW", coin=coin, stage="A1_MISSING_LEG_BYPASS_GATE_BLOCK",
                             reason=str(_ge_m9b.get("reason") or ""), plat=plat_req, side=side_req, mod=mod_u, act=act_l)
                    except Exception as _e:
                        _record_swallowed_exception('except_pass_line_968', _e)
                        pass
                    return False, 'a1_m9_gate_block', 'm9_gate_block（缺腿场景M9未通过RSI/ADX）', detail

                try:
                    _pin("M9_FLOW", coin=coin, stage="A1_MISSING_LEG_BYPASS_DENY",
                         reason="pref_plat_or_side_mismatch", plat=plat_req, side=side_req, mod=mod_u, act=act_l,
                         desired_side=_desired, pref_plat=_pref_plat)
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_969', _e)
                    pass
                return False, 'a1_m9_missing_leg_pref', 'm9_missing_leg_pref_mismatch（缺腿仅允许偏好平台+RSI方向）', detail
        except Exception as _e:
            detail["m9_bypass_exc"] = repr(_e)
            _log_exc(mod='SYS', stage='EXC_PASS', e=_e)

        return False, 'a1_hedge_missing_leg_block', 'hedge_missing_leg（缺腿） block_add（禁止加仓）', detail

    return True, 'ok', 'hedge_opposite_ok（对冲反向通过）', detail

def _a1_check_before_execute(snapshot: dict, req: 'Request', coins: list[str] | None = None) -> tuple[bool, str, str, dict]:
    try:
        if str(getattr(req, 'module', '') or '').upper() == 'B8':
            return False, 'module_deleted', 'B8模块已删除', {'module_deleted': True}
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    """执行前最高权限闸门。返回 (ok, code, reason, detail)."""
    mod = str((req.module or "")).upper()
    act = str((req.action_type or "")).lower()
    coin = str((req.coin or "")).upper()
    try:
        plat_u = str(getattr(req, 'platform', '') or '').upper()
    except Exception:
        plat_u = ''
    try:
        side_u = str(((req.params or {}) if isinstance(getattr(req, 'params', None), dict) else {}).get('side') or
                     ((req.meta or {}) if isinstance(getattr(req, 'meta', None), dict) else {}).get('side') or
                     '').upper()
    except Exception:
        side_u = ''
    if not side_u:
        try:
            side_u = str(_desired_side_from_params((req.params or {}) if isinstance(getattr(req, 'params', None), dict) else {}) or '').upper()
        except Exception:
            side_u = ''

    try:
        act_l0 = str(act or '').lower()
        is_exposure_add = (
            ('open' in act_l0) or ('add' in act_l0) or ('increase' in act_l0)
            or ('grid' in act_l0) or ('add_leg' in act_l0)
        ) and (('close' not in act_l0) and ('tp' not in act_l0) and ('reduce' not in act_l0) and ('decrease' not in act_l0) and ('exit' not in act_l0))
        if is_exposure_add and coin and side_u in ('LONG', 'SHORT'):
            ind_rsi = None
            try:
                if isinstance(getattr(req, 'meta', None), dict):
                    ind_rsi = (req.meta or {}).get('ind_rsi', None)
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_970', _e)
                pass
            try:
                if ind_rsi is None and isinstance(getattr(req, 'params', None), dict):
                    ind_rsi = (req.params or {}).get('ind_rsi', None)
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_971', _e)
                pass
            try:
                ind_rsi_f = float(ind_rsi) if ind_rsi is not None else None
            except Exception:
                ind_rsi_f = None

            pivot = float(GRID_RSI_PIVOT)
            if ind_rsi_f is None or ind_rsi_f <= 0:
                try:
                    _adx2, _rsi2, _ts2, _age2, _rsn2 = _ind_require_adx_rsi(coin, time.time(), ttl_sec=None, allow_force=True)
                    ind_rsi_f = float(_rsi2) if _rsi2 is not None else None
                    try:
                        if not isinstance(getattr(req, 'meta', None), dict):
                            setattr(req, 'meta', {})
                        if isinstance(getattr(req, 'meta', None), dict):
                            req.meta['ind_rsi'] = float(ind_rsi_f) if ind_rsi_f is not None else None
                            req.meta['ind_adx'] = float(_adx2) if _adx2 is not None else None
                            req.meta['ind_ts'] = float(_ts2) if _ts2 is not None else float(time.time())
                            req.meta['ind_age_sec'] = float(_age2) if _age2 is not None else 0.0
                            req.meta['ind_reason'] = str(_rsn2 or '')
                    except Exception as _e:
                        _record_swallowed_exception('except_pass_line_972', _e)
                        pass
                except Exception as _e_ind:
                    return False, 'a1_rsi_missing', f'rsi_missing_or_zero_for_{side_u}', {
                        'plat': plat_u, 'coin': coin, 'side': side_u, 'ind_rsi': ind_rsi, 'pivot': pivot, 'act': act,
                        'auto_fill_err': f'{type(_e_ind).__name__}:{str(_e_ind)[:160]}'
                    }
                if ind_rsi_f is None or ind_rsi_f <= 0:
                    return False, 'a1_rsi_missing', f'rsi_missing_or_zero_for_{side_u}', {
                        'plat': plat_u, 'coin': coin, 'side': side_u, 'ind_rsi': ind_rsi_f, 'pivot': pivot, 'act': act,
                        'auto_fill': 'attempted'
                    }
            if abs(ind_rsi_f - pivot) < 1e-9:
                return False, 'a1_rsi_pivot_deny', f'rsi_pivot_deny_{side_u}', {
                    'plat': plat_u, 'coin': coin, 'side': side_u, 'ind_rsi': ind_rsi_f, 'pivot': pivot, 'act': act
                }
            if side_u == 'LONG' and (ind_rsi_f <= pivot):
                return False, 'a1_rsi_gate_block', 'rsi_gate_deny_long_rsi_le_pivot', {
                    'plat': plat_u, 'coin': coin, 'side': side_u, 'ind_rsi': ind_rsi_f, 'pivot': pivot, 'act': act
                }
            if side_u == 'SHORT' and (ind_rsi_f >= pivot):
                return False, 'a1_rsi_gate_block', 'rsi_gate_deny_short_rsi_ge_pivot', {
                    'plat': plat_u, 'coin': coin, 'side': side_u, 'ind_rsi': ind_rsi_f, 'pivot': pivot, 'act': act
                }
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

def _legacy_deleted_missing_leg_target_side(snapshot: dict, coin: str, platform: str) -> str:
    try:
        c = str(coin or '').upper().strip()
        p = str(platform or '').upper().strip()
        if not c or p not in ('EXT','VAR'):
            return ''
        other = 'VAR' if p == 'EXT' else 'EXT'
        other_pos = _get_position(snapshot or {}, c, other) or {}
        this_pos = _get_position(snapshot or {}, c, p) or {}
        other_has = _has_pos(other_pos)
        this_has = _has_pos(this_pos)
        if this_has or (not other_has):
            return ''
        other_side = str(other_pos.get('side') or other_pos.get('position_side') or '').upper().strip()
        if other_side == 'LONG':
            return 'SHORT'
        if other_side == 'SHORT':
            return 'LONG'
        return ''
    except Exception:
        return ''

def _has_legacy_deleted_candidate_reserved_for_side(snapshot: dict, platform: str, side: str, exclude_coin: str = '') -> bool:
    try:
        p = str(platform or '').upper().strip()
        s = str(side or '').upper().strip()
        ex = str(exclude_coin or '').upper().strip()
        coins = set()
        for bucket in ('coins','positions'):
            src = (snapshot or {}).get(bucket) or {}
            if isinstance(src, dict):
                coins.update([str(k or '').upper().strip() for k in src.keys() if str(k or '').strip()])
        for c in sorted(coins):
            if not c or c == ex:
                continue
            st = str(classify_state(snapshot or {}, c) or '')
            if st not in ('MISSING_LEG','MISSING_LEG_HARD','MISSING_LEG_BIG'):
                continue
            need = _legacy_deleted_missing_leg_target_side(snapshot or {}, c, p)
            if need == s:
                return True
        return False
    except Exception:
        return False

    try:
        if plat_u in ('EXT', 'VAR') and coin and side_u in ('LONG', 'SHORT'):
            if _exec_pending_active(plat_u, coin, side_u):
                return False, 'a1_pending_block', f'pending_active_{plat_u}_{side_u}', {
                    'plat': plat_u, 'coin': coin, 'side': side_u, 'ttl_sec': int(_EXEC_PENDING_TTL_SEC)
                }
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    try:
        act_l = str(act or '').lower()
        if plat_u in ('EXT', 'VAR') and coin and side_u in ('LONG', 'SHORT'):
            if ('close' not in act_l) and ('tp' not in act_l) and ('reduce' not in act_l) and ('exit' not in act_l):
                curp = _get_position(snapshot or {}, coin, plat_u) or {}
                will_open_new = (not _has_pos(curp))
                if will_open_new:
                    lcnt, scnt, coins_now = _count_platform_ls_from_snapshot(snapshot or {}, plat_u)
                    cap_base = 4
                    cap_eff = cap_base
                    reserve_slots = 1
                    _meta0 = {}
                    _is_legacy_deleted_act = False
                    _state0 = ''
                    _need_legacy_deleted_side = ''
                    _allow_overflow = False
                    try:
                        _meta0 = (req.meta if isinstance(getattr(req, 'meta', None), dict) else {}) or {}
                        _act0 = str(act or '').lower()
                        _why0 = str(_meta0.get('why') or _meta0.get('trigger') or _meta0.get('reason') or '').lower()
                        _state0 = str(classify_state(snapshot or {}, coin) or '')
                        _need_legacy_deleted_side = str(_legacy_deleted_missing_leg_target_side(snapshot or {}, coin, plat_u) or '')
                        _is_legacy_deleted_act = (str(_state0) in ("MISSING_LEG","MISSING_LEG_HARD","MISSING_LEG_BIG")) and (str(_need_legacy_deleted_side) == str(side_u)) and (bool(_meta0.get('safe_b1_missing_leg')) or mod in ('LEGACY_DELETED','LEGACY_DELETED','X1','W1') or any(k in _act0 for k in ('legacy_deleted', 'fill_leg', 'add_leg', 'hedge', 'rebalance', 'increase')) or any(k in _why0 for k in ('missing_leg', 'legacy_deleted', 'fill_leg', '补腿', '修复')))
                        if _is_legacy_deleted_act:
                            cap_eff = int(cap_base) + 2
                            try:
                                _meta0['safe_b1_missing_leg'] = True
                                _meta0['legacy_deleted_bucket'] = 'LEGACY_DELETED_MISSING_LEG'
                            except Exception as _e:
                                _record_swallowed_exception('except_pass_line_973', _e)
                                pass
                    except Exception as _e:
                        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

                    side_cnt = int(lcnt) if side_u == 'LONG' else int(scnt)
                    reserve_hit = False
                    try:
                        reserve_hit = (not _is_legacy_deleted_act) and _has_legacy_deleted_candidate_reserved_for_side(snapshot or {}, plat_u, side_u, exclude_coin=str(coin or ''))
                    except Exception:
                        reserve_hit = False
                    normal_cap_eff = int(cap_base) - (int(reserve_slots) if reserve_hit else 0)
                    if (not _is_legacy_deleted_act) and side_cnt >= int(normal_cap_eff):
                        return False, 'a1_4v4_cap_block', f'{plat_u}_{str(side_u).lower()}_cap_reserved_for_legacy_deleted', {
                            'plat': plat_u, 'side': side_u, 'cap': int(normal_cap_eff), 'cap_base': int(cap_base),
                            'reserve_slots': int(reserve_slots), 'legacy_deleted_reserved': bool(reserve_hit),
                            'cnt_long': int(lcnt), 'cnt_short': int(scnt), 'coins': coins_now
                        }
                    if side_u == 'LONG' and int(lcnt) >= int(cap_eff):
                        return False, 'a1_4v4_cap_block', f'{plat_u}_long_cap_reached', {
                            'plat': plat_u, 'side': side_u, 'cap': int(cap_eff), 'cap_base': int(cap_base),
                            'overflow_allow': (2 if int(cap_eff) > int(cap_base) else 0), 'legacy_deleted_bucket': bool(_is_legacy_deleted_act),
                            'cnt_long': int(lcnt), 'cnt_short': int(scnt), 'coins': coins_now
                        }
                    if side_u == 'SHORT' and int(scnt) >= int(cap_eff):
                        return False, 'a1_4v4_cap_block', f'{plat_u}_short_cap_reached', {
                            'plat': plat_u, 'side': side_u, 'cap': int(cap_eff), 'cap_base': int(cap_base),
                            'overflow_allow': (2 if int(cap_eff) > int(cap_base) else 0), 'legacy_deleted_bucket': bool(_is_legacy_deleted_act),
                            'cnt_long': int(lcnt), 'cnt_short': int(scnt), 'coins': coins_now
                        }

                    try:
                        if int(cap_eff) > int(cap_base):
                            _pin('A1_CAP_OVERFLOW', ok=1, reason='missing_leg_legacy_deleted_overflow_plus2',
                                 coin=str(coin or ''), plat=str(plat_u or ''), side=str(side_u or ''),
                                 cap_base=int(cap_base), cap_eff=int(cap_eff), cnt_long=int(lcnt), cnt_short=int(scnt),
                                 act=str(act or ''), mod=str(mod or ''), meta=_meta0)
                    except Exception as _e:
                        _record_swallowed_exception('except_pass_line_974', _e)
                        pass
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    try:
        _pin('GATE', coin=coin, stage='CHECK', reason='before_execute', mod=mod, act=act, plat=str(getattr(req,'platform', '') or ''), amt=getattr(req,'amount_usd', None), meta=(req.meta if isinstance(getattr(req,'meta',None), dict) else {}))
        if coin == 'HYPE' and mod == 'M10':
            _pin('M10', coin=coin, stage='CHECK', reason='gate_enter', act=act)
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    if mod == "B2":
        return True, "ok", "b2_trend_bypass_hp", {}
    if mod == "M10":
        try:
            _coin = str(getattr(req, "coin", "") or "").upper().strip()
        except Exception:
            _coin = ""
        _adx = None
        try:
            _ind = (snapshot or {}).get("indicators", {}) or {}
            if _coin and isinstance(_ind.get(_coin), dict):
                _adx = _ind.get(_coin, {}).get("adx")
            if _adx is None and isinstance(_ind.get("GLOBAL"), dict):
                _adx = _ind.get("GLOBAL", {}).get("adx")
        except Exception:
            _adx = None
        try:
            pass
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

        return True, "ok", "m10_bypass_hp_with_adx_gate", {}

    if mod == 'M9' and act not in ('increase', 'add_loss', 'add_leg', 'open_pair', 'add'):
        return True, 'ok', 'm9_risk_reduce_bypass_hp', {}

    if mod == "ANCHOR":
        return True, "ok", "anchor_bypass_hp", {}

    if mod in ("GO", "GO") and act in ("a1_reduce_one_leg", "a1_close_full_one_leg", "a1_flip_same_dir"):
        if act == "a1_flip_same_dir":
            try:
                co = ((snapshot.get("coins") if isinstance(snapshot, dict) else {}) or {}).get(coin) or {}
                ext = (co.get("ext") or {})
                var = (co.get("var") or {})
                ext_has = bool(ext.get("has_position", False))
                var_has = bool(var.get("has_position", False))
                if not (ext_has and var_has):
                    return True, "ok", "a1_flip_no_both_pos", {}
                ext_side = _a1_norm_side(ext.get("side") or "")
                var_side = _a1_norm_side(var.get("side") or "")
                if ext_side in ("LONG", "SHORT") and ext_side == var_side:
                    return True, "ok", "a1_flip_same_dir_bypass", {}
                try:
                    _pin('GATE', coin=coin, stage='REJECT', reason='check_before_execute_block', mod=mod, act=act, ret='return False, "a1_flip_not_same_dir", "a1_flip_requires_same_dir（同向才允许翻腿）", {"ext_side": ext_side, "var_side": var_side}')
                    if mod in ('M10','M9','B1','LEGACY_DELETED','X1','Z1','W1'):
                        _pin(mod, coin=coin, stage='SKIP', reason='gate_reject', act=act)
                except Exception as _e:
                    _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

                return False, "a1_flip_not_same_dir", "a1_flip_requires_same_dir（同向才允许翻腿）", {"ext_side": ext_side, "var_side": var_side}
            except Exception as _e:
                return True, "ok", "a1_flip_bypass_exception_safe", {"err": repr(_e)}
        return True, "ok", "a1_legacy_deleted_bypass", {}

    is_add_action = ((act in ('open_pair', 'add_leg', 'increase', 'add_loss') or (act == 'add')) and (str(mod).upper().strip() != 'X1'))
    if is_add_action:
        ok_h, code_h, reas_h, det_h = _a1_check_hedge_state_before_add(snapshot, req, coin, mod, act)
        if not ok_h:
            try:
                _pin('GATE', coin=coin, stage='REJECT', reason='check_before_execute_block', mod=mod, act=act, ret='return False, code_h, reas_h, det_h')
                if mod in ('M10','M9','B1','LEGACY_DELETED','X1','Z1','W1'):
                    _pin(mod, coin=coin, stage='SKIP', reason='gate_reject', act=act)
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

            return False, code_h, reas_h, det_h

    def _a1_side_from_req(_req: 'Request') -> str:
        try:
            s = str(((_req.params or {}).get('side') or getattr(_req, 'side', None) or '').upper())
            return s
        except Exception:
            return ''

    need_sig_check = False
    if (mod == 'M9' and act == 'increase'):
        need_sig_check = True  # 启用 ADX/RSI 加仓信号闸（按最新规则）
        try:
            _meta_m9 = req.meta if isinstance(getattr(req, 'meta', None), dict) else {}
            _grid_obs_m9 = dict(_meta_m9.get('grid_decision_obs') or {}) if isinstance(_meta_m9.get('grid_decision_obs'), dict) else {}
            _m9_owned_chain = bool(str(_meta_m9.get('source_module') or '').upper() == 'M9' or str(_meta_m9.get('grid_owner_module') or '').upper() == 'M9' or bool(_meta_m9.get('managed_by_grid')) or int(_grid_obs_m9.get('layers_open_cnt') or 0) > 0)
            _m9_price_hit = bool(_grid_obs_m9.get('next_buy_hit') or _meta_m9.get('next_buy_hit'))
            if _m9_owned_chain and _m9_price_hit:
                need_sig_check = False
                if isinstance(_meta_m9, dict):
                    _meta_m9['m9_add_signal_bypass'] = 'price_hit_owned_chain'
                    _meta_m9['m9_add_signal_bypass_reason'] = 'm9_add_by_price_hit_owned_chain'
                    req.meta = _meta_m9
        except Exception:
            need_sig_check = True
    if (mod == 'B1'):
        need_sig_check = False

    if need_sig_check:
        if mod == 'M9' and act == 'increase':
            _side = str((req.params or {}).get('side') or '').upper()
            if _side not in ('LONG', 'SHORT'):
                _p = _get_position(snapshot, coin, req.platform) or {}
                _ps = str(_p.get('side') or '').upper()
                if _ps in ('LONG', 'SHORT'):
                    if not isinstance(req.params, dict):
                        req.params = {}
                    req.params['side'] = _ps
                    if isinstance(req.meta, dict):
                        req.meta['side'] = _ps

        sides = []
        if act == 'open_pair':
            legs = (req.params or {}).get('legs') or []
            for leg in legs:
                sides.append(str((leg or {}).get('side') or '').upper())
        else:
            sides.append(_a1_side_from_req(req))

        snap_sig = _a1_patch_snapshot_with_req_indicators(snapshot, req, coin)
        ok_sig, reas_sig = _a1_check_add_signal(snap_sig, coin, sides, mod, act)
        if not ok_sig:
            try:
                _pin('GATE', coin=coin, stage='REJECT', reason='check_before_execute_block', mod=mod, act=act, ret="return False, 'a1_add_signal_block', reas_sig, {'coin': coin, 'sides': sides, 'module': mod, 'action': act}")
                if mod in ('M10','M9','B1','LEGACY_DELETED','X1','Z1','W1'):
                    _pin(mod, coin=coin, stage='SKIP', reason='gate_reject', act=act)
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

            return False, 'a1_add_signal_block', reas_sig, {'coin': coin, 'sides': sides, 'module': mod, 'action': act}

    if act == "open_pair":
        legs = (req.params or {}).get("legs") or []
        plats = [str((leg or {}).get("platform") or "").upper() for leg in legs]
        _b1_single = (mod == "B1" and isinstance(legs, list) and len(legs) == 1 and (plats and plats[0] in ("EXT","VAR")))
        if not (_b1_single or (len(legs) >= 2 and ("EXT" in plats) and ("VAR" in plats))):
            try:
                _pin('GATE', coin=coin, stage='REJECT', reason='check_before_execute_block', mod=mod, act=act, ret='return False, "a1_open_pair_bad_legs", "open_pair_requires_EXT_and_VAR_legs", {"plats": plats, "legs_len": len(legs)}')
                if mod in ('M10','M9','B1','LEGACY_DELETED','X1','Z1','W1'):
                    _pin(mod, coin=coin, stage='SKIP', reason='gate_reject', act=act)
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

            return False, "a1_open_pair_bad_legs", "open_pair_requires_EXT_and_VAR_legs", {"plats": plats, "legs_len": len(legs)}
        e = _get_position(snapshot, coin, "EXT") or {}
        v = _get_position(snapshot, coin, "VAR") or {}
        if (_norm_leg_u(_a1_pos_notional_u(e)) + _norm_leg_u(_a1_pos_notional_u(v))) > 0.0:
            try:
                _pin('GATE', coin=coin, stage='REJECT', reason='check_before_execute_block', mod=mod, act=act, ret='return False, "a1_open_pair_not_first", "first_open_requires_total_notional=0", {"ext_notional": _a1_pos_notional_u(e), "var_notional": _a1_pos_notional_u(v)}')
                if mod in ('M10','M9','B1','LEGACY_DELETED','X1','Z1','W1'):
                    _pin(mod, coin=coin, stage='SKIP', reason='gate_reject', act=act)
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

            return False, "a1_open_pair_not_first", "first_open_requires_total_notional=0", {"ext_notional": _a1_pos_notional_u(e), "var_notional": _a1_pos_notional_u(v)}
        ext_amt = 0.0
        var_amt = 0.0
        for leg in legs:
            plat = str((leg or {}).get("platform") or "").upper()
            amt = _safe_float((leg or {}).get("amount_usd") or (leg or {}).get("amount_usd_intent"), 0.0)
            if plat == "EXT":
                ext_amt += amt
            elif plat == "VAR":
                var_amt += amt
        if (not _b1_single) and abs(ext_amt - var_amt) > A1_MAX_HEDGE_GAP_U:
            try:
                _pin('GATE', coin=coin, stage='REJECT', reason='check_before_execute_block', mod=mod, act=act, ret='return False, "a1_open_pair_gap_gt_200", f"planned_gap>{A1_MAX_HEDGE_GAP_U}", {"ext_amt": ext_amt, "var_amt": var_amt}')
                if mod in ('M10','M9','B1','LEGACY_DELETED','X1','Z1','W1'):
                    _pin(mod, coin=coin, stage='SKIP', reason='gate_reject', act=act)
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

            return False, "a1_open_pair_gap_gt_200", f"planned_gap>{A1_MAX_HEDGE_GAP_U}", {"ext_amt": ext_amt, "var_amt": var_amt}
    if act == "add_leg":
        plat = str((req.params or {}).get("platform") or req.platform or "").upper()
        amt = _safe_float((req.params or {}).get("amount_usd") or (req.params or {}).get("amount_usd_intent"), 0.0)

        try:
            pm = (req.params or {}) if isinstance(req.params, dict) else {}
        except Exception:
            pm = {}
        try:
            mt = (req.meta or {}) if isinstance(req.meta, dict) else {}
        except Exception:
            mt = {}
        legacy_fix_mode = bool(pm.get("legacy_fix_mode") or mt.get("legacy_fix_mode") or False)

        e = _get_position(snapshot, coin, "EXT") or {}
        v = _get_position(snapshot, coin, "VAR") or {}
        e_n = _a1_pos_notional_u(e)
        v_n = _a1_pos_notional_u(v)

        if plat == "EXT":
            e_n2, v_n2 = (e_n + amt), v_n
        else:
            e_n2, v_n2 = e_n, (v_n + amt)
        post_gap = abs(e_n2 - v_n2)

        if not (mod == "LEGACY_DELETED" and legacy_fix_mode):
            if post_gap > (A1_MAX_HEDGE_GAP_U + 0.5):
                try:
                    _pin('GATE', coin=coin, stage='REJECT', reason='check_before_execute_block', mod=mod, act=act, ret='return False, "a1_add_leg_gap_still_gt_200", f"post_gap>{A1_MAX_HEDGE_GAP_U}", {')
                    if mod in ('M10','M9','B1','LEGACY_DELETED','X1','Z1','W1'):
                        _pin(mod, coin=coin, stage='SKIP', reason='gate_reject', act=act)
                except Exception as _e:
                    _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

                return False, "a1_add_leg_gap_still_gt_200", f"post_gap>{A1_MAX_HEDGE_GAP_U}", {
                    "ext_after": e_n2, "var_after": v_n2, "amt": amt, "plat": plat, "post_gap": post_gap
                }

    if act == "close_one_leg":
        e = _get_position(snapshot, coin, "EXT") or {}
        v = _get_position(snapshot, coin, "VAR") or {}
        e_n = float(_a1_pos_notional_u(e) or 0.0)
        v_n = float(_a1_pos_notional_u(v) or 0.0)

        if (e_n > 0 and v_n > 0) or (e_n <= 0 and v_n <= 0):
            return False, "a1_close_one_leg_requires_single_leg", "need exactly one leg position", {"e_n": e_n, "v_n": v_n}

        _plat = ""
        try:
            _plat = _norm_platform(getattr(req, "platform", "") or "")
            if _plat not in ("EXT", "VAR"):
                _plat = ""
        except Exception:
            _plat = ""
        try:
            _p0 = (getattr(req, "params", None) if hasattr(req, "params") else None)
            if isinstance(_p0, dict):
                _pplat = _norm_platform(_p0.get("platform") or _p0.get("plat") or "")
                if _pplat in ("EXT", "VAR"):
                    _plat = _pplat
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_975', _e)
            pass
        if not _plat:
            _plat = "EXT" if e_n > 0 else "VAR"

        _pos = e if _plat == "EXT" else v
        _n = e_n if _plat == "EXT" else v_n
        _up = float(_a1_pos_upnl_u(_pos) or 0.0)
        _gate = _single_leg_b2_stale_high_gate(snapshot or {}, coin, _plat, _pos)
        _thr = float(_gate.get('min_profit_u') or _single_leg_b2_need_profit_u(coin))

        if not bool(_gate.get('allow')):
            _reason = str(_gate.get('reason') or 'single_leg_b2_wait_stale_high_5h')
            try:
                _pin('GATE', coin=coin, stage='REJECT', reason=_reason,
                     mod=mod, act=act, ok=0, plat=_plat, upnl_u=_up, notional_u=_n,
                     thr_u=_thr, stale_sec=float(_gate.get('stale_sec') or 0.0),
                     high_upnl_u=float(_gate.get('high_upnl_u') or 0.0),
                     trace=str((getattr(req, "meta", {}) or {}).get("trace_id") or ""))
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)
            return False, _reason, "single_leg_b2_stale_high_not_ready", {
                "plat": _plat, "upnl_u": _up, "notional_u": _n, "thr_u": _thr,
                "stale_sec": float(_gate.get('stale_sec') or 0.0),
                "high_upnl_u": float(_gate.get('high_upnl_u') or 0.0),
                "stale_need_sec": float(_gate.get('stale_need_sec') or 0.0),
            }

        try:
            setattr(req, "platform", _plat)
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_976', _e)
            pass
        try:
            if hasattr(req, "meta") and isinstance(getattr(req, "meta", None), dict):
                req.meta.setdefault("tp_missing_leg", True)
                req.meta.setdefault("single_leg_b2_stale_high", True)
                req.meta.setdefault("profit_u", _up)
                req.meta.setdefault("notional_u", _n)
                req.meta.setdefault("min_profit_u", _thr)
                req.meta.setdefault("stale_sec", float(_gate.get('stale_sec') or 0.0))
                req.meta.setdefault("stale_need_sec", float(_gate.get('stale_need_sec') or 0.0))
                req.meta.setdefault("high_upnl_u", float(_gate.get('high_upnl_u') or 0.0))
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_977', _e)
            pass
        return True, "single_leg_b2_stale_high_ready", "ok", {
            "plat": _plat, "upnl_u": _up, "notional_u": _n, "thr_u": _thr,
            "stale_sec": float(_gate.get('stale_sec') or 0.0),
            "stale_need_sec": float(_gate.get('stale_need_sec') or 0.0),
            "high_upnl_u": float(_gate.get('high_upnl_u') or 0.0)
        }

    if act == "close_pair":
        _trend_guard = _trend_alpha_guard_for_b2_m10(snapshot, coin) or {}
        if bool(_trend_guard.get('active')):
            return False, "b2_blocked_by_trend_alpha", "trend_alpha_runner_protected", {"trend_guard": _trend_guard}
        e = _get_position(snapshot, coin, "EXT") or {}
        v = _get_position(snapshot, coin, "VAR") or {}
        if _a1_pos_notional_u(e) <= 0 or _a1_pos_notional_u(v) <= 0:
            try:
                _pin('GATE', coin=coin, stage='REJECT', reason='check_before_execute_block', mod=mod, act=act, ret='return False, "a1_close_not_dual_position", "close_requires_dual_positions", {"ext_notional": _a1_pos_notional_u(e), "var_notional": _a1_pos_notional_u(v)}')
                if mod in ('M10','M9','B1','LEGACY_DELETED','X1','Z1','W1'):
                    _pin(mod, coin=coin, stage='SKIP', reason='gate_reject', act=act)
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

            return False, "a1_close_not_dual_position", "close_requires_dual_positions", {"ext_notional": _a1_pos_notional_u(e), "var_notional": _a1_pos_notional_u(v)}
        thr, detail = _a1_profit_leg_threshold(snapshot, coin)
        net_up = float(detail.get("net_upnl_u", 0.0) or 0.0)
        if net_up <= thr:
            try:
                _pin('GATE', coin=coin, stage='REJECT', reason='check_before_execute_block', mod=mod, act=act, ret='return False, "a1_close_netprofit_lt_threshold", f"net_upnl_u({net_up:.2f})<=thr({thr:.2f})", detail')
                if mod in ('M10','M9','B1','LEGACY_DELETED','X1','Z1','W1'):
                    _pin(mod, coin=coin, stage='SKIP', reason='gate_reject', act=act)
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

            return False, "a1_close_netprofit_lt_threshold", f"net_upnl_u({net_up:.2f})<=thr({thr:.2f})", detail
    elif act == "koujing_a_3step":  # M10 纯止盈（koujing_a_3step）口径A门槛校验
        _trend_guard = _trend_alpha_guard_for_b2_m10(snapshot, coin) or {}
        if bool(_trend_guard.get('active')) and bool(_trend_guard.get('runner_protect')):
            return False, "m10_runner_protected", "trend_alpha_runner_protected", {"trend_guard": _trend_guard, "trend_alpha_cap_pct": 0.0}
        e = _get_position(snapshot, coin, "EXT") or {}
        v = _get_position(snapshot, coin, "VAR") or {}
        e_n = _a1_pos_notional_u(e)
        v_n = _a1_pos_notional_u(v)
        if e_n <= 0 or v_n <= 0:
            try:
                _pin('GATE', coin=coin, stage='REJECT', reason='check_before_execute_block', mod=mod, act=act, ret='return False, "a1_close_not_dual_position", "koujing_a_requires_dual_positions", {"ext_notional": e_n, "var_notional": v_n}')
                if mod in ('M10','M9','B1','LEGACY_DELETED','X1','Z1','W1'):
                    _pin(mod, coin=coin, stage='SKIP', reason='gate_reject', act=act)
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

            return False, "a1_close_not_dual_position", "koujing_a_requires_dual_positions", {"ext_notional": e_n, "var_notional": v_n}

        e_up = _a1_pos_upnl_u(e)
        v_up = _a1_pos_upnl_u(v)

        if e_up >= v_up:
            win_plat, win_n, win_up = "EXT", e_n, e_up
            loss_plat, loss_n, loss_up = "VAR", v_n, v_up
        else:
            win_plat, win_n, win_up = "VAR", v_n, v_up
            loss_plat, loss_n, loss_up = "EXT", e_n, e_up

        steps = []

        try:

            _p0 = req.params or {}

            if isinstance(_p0, dict):

                _s0 = _p0.get("steps") or _p0.get("plan")

                if isinstance(_s0, list) and _s0:

                    steps = _s0

                if not steps and isinstance(_p0.get("params"), dict):

                    _s1 = (_p0.get("params") or {}).get("steps") or (_p0.get("params") or {}).get("plan")

                    if isinstance(_s1, list) and _s1:

                        steps = _s1

                if not steps and isinstance(_p0.get("group_request"), dict):

                    _s2 = (_p0.get("group_request") or {}).get("steps") or (_p0.get("group_request") or {}).get("plan")

                    if isinstance(_s2, list) and _s2:

                        steps = _s2

            if not steps and isinstance(getattr(req, "meta", None), dict):

                _ex = (req.meta or {}).get("extras") or {}

                if isinstance(_ex, dict):

                    _s3 = _ex.get("steps") or _ex.get("plan")

                    if isinstance(_s3, list) and _s3:

                        steps = _s3

        except Exception:

            steps = steps or []
        loss_close_u = _tp_extract_loss_close_notional_u(steps, loss_plat)
        ratio, realized_loss_est, net_realized_est = _tp_est_net_realized_u(win_up, loss_up, loss_n, loss_close_u)
        _trigger_pct = 0.01
        _trigger_need_u = float(max(0.0, win_n) * _trigger_pct)
        _profit_min_u = float(cfg_getf_runtime("M10_PROFIT_MIN_U", cfg_getf_runtime("B2_TREND_PROFIT_MIN_U", cfg_getf_runtime("TREND_TP_PROFIT_MIN_U", 1.0))) or 1.0)
        if _profit_min_u < 0:
            _profit_min_u = 0.0
        thr = float(max(_profit_min_u, _trigger_need_u))

        detail = {
            "coin": coin,
            "win_leg": {"platform": win_plat, "notional_u": win_n, "upnl_u": win_up},
            "loss_leg": {"platform": loss_plat, "notional_u": loss_n, "upnl_u": loss_up},
            "loss_close_notional_u": loss_close_u,
            "loss_ratio": ratio,
            "realized_loss_est": realized_loss_est,
            "net_realized_est": net_realized_est,
            "trigger_pct": _trigger_pct,
            "trigger_need_u": _trigger_need_u,
            "profit_min_u": _profit_min_u,
            "thr_u": thr,
            "threshold_basis": "m10_max_profit_min_u_or_profit_leg_notional_1pct",
        }

        if net_realized_est <= thr:
            try:
                _pin('GATE', coin=coin, stage='REJECT', reason='check_before_execute_block', mod=mod, act=act, ret='return False, "a1_close_netprofit_lt_threshold", f"a1_close_netprofit_lt_threshold net_realized_est({net_realized_est:.2f})<=thr({thr:.2f}) loss_ratio({ratio:.3f})", detail')
                if mod in ('M10','M9','B1','LEGACY_DELETED','X1','Z1','W1'):
                    _pin(mod, coin=coin, stage='SKIP', reason='gate_reject', act=act)
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

            return False, "a1_close_netprofit_lt_threshold", f"a1_close_netprofit_lt_threshold net_realized_est({net_realized_est:.2f})<=thr({thr:.2f}) loss_ratio({ratio:.3f})", detail

    return True, "ok", "ok", {}

_A1_CHECK_BEFORE_EXECUTE_RAW = _a1_check_before_execute

def _a1_check_before_execute(snapshot: dict, req: 'Request', coins: list[str] | None = None) -> tuple[bool, str, str, dict]:
    """稳定包装层：保证 A1 永远返回四元组，禁止 None/脏结构继续向外扩散。"""
    try:
        ret = _A1_CHECK_BEFORE_EXECUTE_RAW(snapshot, req, coins)
    except Exception as _e:
        return False, 'a1_check_exc', f'a1_check_exc:{type(_e).__name__}', {
            'err': f'{type(_e).__name__}:{str(_e)[:240]}',
            'coin': str(getattr(req, 'coin', '') or '').upper(),
            'platform': str(getattr(req, 'platform', '') or '').upper(),
            'module': str(getattr(req, 'module', '') or '').upper(),
            'action': str(getattr(req, 'action_type', '') or '').lower(),
        }
    if isinstance(ret, tuple) and len(ret) == 4:
        ok, code, reason, detail = ret
        try:
            detail_d = dict(detail or {}) if isinstance(detail, dict) else {'detail_repr': repr(detail)[:240]}
        except Exception:
            detail_d = {'detail_repr': repr(detail)[:240]}
        return bool(ok), str(code or ''), str(reason or code or ''), detail_d
    return True, 'ok', 'allow_wrapped_default', {
        'wrapper_stage': 'stage1_invalid_return_allow',
        'ret_type': type(ret).__name__,
        'ret_repr': repr(ret)[:240],
        'coin': str(getattr(req, 'coin', '') or '').upper(),
        'platform': str(getattr(req, 'platform', '') or '').upper(),
        'module': str(getattr(req, 'module', '') or '').upper(),
        'action': str(getattr(req, 'action_type', '') or '').lower(),
    }

_NETLOSS_REDUCE_ACTIONS = {
    'decrease', 'close_full', 'close_partial_notional', 'close_leg', 'close_layer', 'close_pair',
    'a1_reduce_one_leg', 'a1_close_full_one_leg', 'a1_flip_same_dir',
}

def _netloss_fee_buffer_u() -> float:
    """手续费缓冲（U）。默认 1U，可被配置覆盖。"""
    try:
        risk = (PEIZHI.get('risk') or {}) if isinstance(PEIZHI, dict) else {}
        v = risk.get('netloss_fee_buffer_u', None)
        if v is None:
            v = risk.get('fee_buffer_u', None)
        if v is None:
            return 1.0
        return float(v)
    except Exception:
        return 1.0

def _netloss_is_reduce_req(req: 'Request') -> bool:
    try:
        act = str(getattr(req, 'action_type', '') or '').lower()
        return act in _NETLOSS_REDUCE_ACTIONS
    except Exception:
        return False

def _netloss_extract_reduce_amount_u(req: 'Request') -> float:
    """提取本次减仓/平仓名义（U）。拿不到就返回 0。

    重要：本脚本里“减仓/平仓”请求的金额可能在：
    - req.params（dict / SimpleNamespace）
    - req.meta（dict / SimpleNamespace）
    - req 顶层字段（dict 或 Request 其他字段）
    因此这里做最大兼容，避免出现日志里的 no_amount / amt=0 导致“有命中却不下卖单”。
    """
    def _as_dict(x):
        if isinstance(x, dict):
            return x
        try:
            if isinstance(x, SimpleNamespace):
                return vars(x)
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

        try:
            if hasattr(x, "__dict__"):
                return dict(getattr(x, "__dict__") or {})
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

        return {}

    if isinstance(req, dict):
        p = _as_dict(req.get("params"))
        m = _as_dict(req.get("meta"))
        top = req
        _get_top = lambda k: top.get(k, None)
    else:
        p = _as_dict(getattr(req, "params", None))
        m = _as_dict(getattr(req, "meta", None))
        _get_top = lambda k: getattr(req, k, None)

    keys = (
        "amount_usd", "usd", "notional_u", "amount_u", "amount",
        "close_notional_u", "close_u", "reduce_u", "dec_u",
        "exec_notional_u", "value_u", "value_usd", "notional", "u",
    )
    for k in keys:
        for src in (p, None, m):
            try:
                v = None
                if src is None:
                    v = _get_top(k)
                else:
                    v = src.get(k, None)
                if v is None:
                    continue
                vv = float(v)
                if vv > 0:
                    return vv
            except Exception:
                continue

    for k in ("close_u", "close_notional_u", "close_usd"):
        try:
            v = p.get(k, None)
            if v is not None and float(v) > 0:
                return float(v)
        except Exception:
            continue

    return 0.0

def _netloss_estimate_expected_realized(snapshot: dict, req: 'Request') -> tuple[float, dict]:
    """估算该请求的预计实现盈亏（U）。返回 (expected_u, detail)。

    估算方法：expected = upnl * min(1, amount/notional)
    - close_all / close_full：若 amount 未给，按 1.0
    - 若缺 notional 或缺 upnl：标记 unknown
    """
    coin = str(getattr(req, 'coin', '') or '').upper().strip()
    plat = str(getattr(req, 'platform', '') or '').upper().strip()
    act = str(getattr(req, 'action_type', '') or '').lower()

    if act == 'close_pair':
        try:
            p = None
            try:
                pp = getattr(req, 'params', None)
                if isinstance(pp, dict):
                    p = pp.get('p', None)
                    if p is None:
                        p = pp.get('sum_up', None)
                    if p is None:
                        p = pp.get('sum_upnl_u', None)
            except Exception:
                p = None
            if p is not None:
                pv = float(p)
                return pv, {'coin': coin, 'platform': 'BOTH', 'action': act, 'unknown': False, 'why': 'close_pair_params_p', 'expected': pv}
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    if (not plat) or plat not in ('EXT', 'VAR'):
        if act == 'close_pair':
            try:
                epos = _get_position(snapshot, coin, 'EXT') or {}
                vpos = _get_position(snapshot, coin, 'VAR') or {}
                en = _safe_float(_a1_pos_notional_u(epos), 0.0)
                vn = _safe_float(_a1_pos_notional_u(vpos), 0.0)
                eu = _safe_float(epos.get('upnl_u') if isinstance(epos, dict) else None, 0.0)
                vu = _safe_float(vpos.get('upnl_u') if isinstance(vpos, dict) else None, 0.0)
                if (abs(en) <= 1e-9 and abs(vn) <= 1e-9):
                    return 0.0, {'coin': coin, 'platform': 'BOTH', 'action': act, 'unknown': True, 'why': 'close_pair_no_legs'}
                return float(eu + vu), {'coin': coin, 'platform': 'BOTH', 'action': act, 'unknown': False, 'why': 'close_pair_sum_upnl', 'en': float(en), 'vn': float(vn)}
            except Exception:
                return 0.0, {'coin': coin, 'platform': 'BOTH', 'action': act, 'unknown': True, 'why': 'close_pair_sum_failed'}
        return 0.0, {'coin': coin, 'platform': plat, 'action': act, 'unknown': True, 'why': 'need_platform'}

    pos = _get_position(snapshot, coin, plat) or {}
    notional = _safe_float(_a1_pos_notional_u(pos), 0.0)
    upnl = _safe_float(pos.get('upnl_u') if isinstance(pos, dict) else None, 0.0)

    amt = _netloss_extract_reduce_amount_u(req)

    full_like = act in ('close_full', 'a1_close_full_one_leg')
    if full_like and (amt <= 0):
        ratio = 1.0
    else:
        if notional <= 0:
            return 0.0, {'coin': coin, 'platform': plat, 'action': act, 'unknown': True, 'why': 'no_notional', 'amt': amt, 'notional': notional, 'upnl': upnl}
        if amt <= 0:
            return 0.0, {'coin': coin, 'platform': plat, 'action': act, 'unknown': True, 'why': 'no_amount', 'amt': amt, 'notional': notional, 'upnl': upnl}
        ratio = max(0.0, min(1.0, float(amt) / float(notional)))

    expected = float(upnl) * float(ratio)
    return expected, {'coin': coin, 'platform': plat, 'action': act, 'unknown': False, 'ratio': ratio, 'amt': amt, 'notional': notional, 'upnl': upnl, 'expected': expected}

def _netloss_precompute_blocks(snapshot: dict, requests: list['Request']) -> tuple[set[int], dict[int, dict], dict[str, dict]]:
    """对本轮 requests 预计算净亏损预检。

    系统性修复原则：
    - **仅对“风险增加类动作”（increase/open/add_leg 等）做风险门禁**；
    - **任何降风险动作（decrease/close/reduce_only/sell）永远放行**，否则会导致网格“只买不卖”、利润无法落袋。

    说明：本函数历史上用于对“减仓/止盈”做净亏损拦截，但该策略已被禁用（降风险动作不再拦截）。
    当前保留该函数仅为兼容旧调用方，统一返回“不拦截”。

    返回：
    - blocked_ids: set(id(req))
    - blocked_detail: id(req)->detail
    - coin_summary: coin->summary
    """
    return set(), {}, {}

def _total_u_from_snapshot_or_anchor(snapshot: dict, anchor_u: float) -> float:
    """优先从 snapshot.balances 读总资金，否则退化用锚点"""
    b = (snapshot or {}).get("balances") or {}
    for k in ("total_equity_u", "total_balance_u", "total_u", "equity_u", "balance_u", "TOTAL_U"):
        v = b.get(k)
        if v is not None:
            tv = _safe_float(v, 0.0)
            if tv > 0:
                return tv
    try:
        tv = float((((b.get("TOTAL") or {}) or {}).get("usd", 0.0)) or 0.0)
        if tv > 0:
            return tv
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    return float(anchor_u)

def _quanju_sum_notional_u(snapshot: dict) -> float:
    s = 0.0
    pos = (snapshot or {}).get("positions") or {}
    if not isinstance(pos, dict):
        return 0.0
    for plat, cmap in pos.items():
        if not isinstance(cmap, dict):
            continue
        for _, leg in cmap.items():
            if not isinstance(leg, dict):
                continue
            s += _safe_float(leg.get("notional_u"), 0.0)
    return float(s)
def _coin_sum_notional_u(snapshot: dict, coin: str) -> float:
    c = str(coin or "").upper()
    s = 0.0
    pos = (snapshot or {}).get("positions") or {}
    if not isinstance(pos, dict):
        return 0.0
    for plat, cmap in pos.items():
        if not isinstance(cmap, dict):
            continue
        leg = cmap.get(c) or {}
        if isinstance(leg, dict):
            s += _safe_float(leg.get("notional_u"), 0.0)
    return float(s)

def _now_minute_of_day() -> int:
    try:
        n = datetime.now()
        return int(n.hour) * 60 + int(n.minute)
    except Exception:
        return 0

def _yingding_ratio_for_coin(coin: str) -> float:
    """单币单平台硬顶比例（cap_ratio）。

    老板最终口径：BTC/ETH 按“本平台 Equity × 2.5”，其余币按“本平台 Equity × 2”。
    不再使用固定 2000U，也不再允许执行层换另一套算法。
    """
    try:
        if str(coin or '').upper().strip() in ('BTC', 'ETH'):
            ratio = float(globals().get('HARDCAP_EQUITY_RATIO_BTC_ETH', 2.5) or 2.5)
        else:
            ratio = float(globals().get('HARDCAP_EQUITY_RATIO_ALL', 2.0) or 2.0)
    except Exception:
        ratio = 2.5 if str(coin or '').upper().strip() in ('BTC', 'ETH') else 2.0
    if ratio <= 0.0:
        ratio = 2.5 if str(coin or '').upper().strip() in ('BTC', 'ETH') else 2.0
    return float(ratio)

def _platform_equity_u_from_snapshot(snapshot: dict | None, platform: str) -> float:
    """硬顶统一真相源：只取下单所在平台资金，不再混用 total_u/双平台合计。"""
    plat = str(platform or '').upper().strip()
    snap = snapshot if isinstance(snapshot, dict) else {}
    if plat not in ('EXT', 'VAR'):
        return 0.0
    try:
        b0 = ((snap.get('balances') or {}).get(plat) or {})
        if isinstance(b0, dict):
            for _k in ('usd','equity','equity_u','balance_u','total_u','wallet_usd','wallet_balance','available_usd'):
                v = _safe_float(b0.get(_k), 0.0)
                if v > 0.0:
                    return float(v)
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_978', _e)
        pass
    try:
        for key in (f'{plat.lower()}_equity', f'{plat.lower()}_equity_u', f'{plat.lower()}_balance_u'):
            v = _safe_float(snap.get(key), 0.0)
            if v > 0.0:
                return float(v)
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_979', _e)
        pass
    try:
        meta = snap.get('meta') or {}
        if isinstance(meta, dict):
            for key in (f'{plat.lower()}_equity', f'{plat.lower()}_equity_u', f'{plat.lower()}_balance_u'):
                v = _safe_float(meta.get(key), 0.0)
                if v > 0.0:
                    return float(v)
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_980', _e)
        pass
    return 0.0

def _coin_platform_cap_u_from_snapshot(snapshot: dict | None, coin: str, platform: str) -> tuple[float, dict]:
    """返回单币单平台硬顶 cap_u 及其明细。

    老板最终口径：BTC/ETH 按“本平台 Equity × 2.5”，其余币按“本平台 Equity × 2”。
    整条链只允许这一套公式，不再混用固定 2000U / 分币种比例 / 其他旁路。
    """
    plat = str(platform or '').upper().strip()
    c = str(coin or '').upper().strip()
    platform_equity_u = float(_platform_equity_u_from_snapshot(snapshot, plat) or 0.0)
    ratio = float(_yingding_ratio_for_coin(c))
    cap_u = float(platform_equity_u) * float(ratio) if float(platform_equity_u) > 0.0 else 0.0
    return float(cap_u), {
        'coin': c,
        'platform': plat,
        'platform_equity_u': float(platform_equity_u),
        'cap_ratio': float(ratio),
        'cap_u': float(cap_u),
        'cap_src': 'platform_equity_x_ratio',
        'cap_formula': 'platform_equity_u * cap_ratio',
    }

def _req_amount_u_read(reqd: dict | None) -> float:
    try:
        if not isinstance(reqd, dict):
            return 0.0
        params = reqd.get("params") if isinstance(reqd.get("params"), dict) else {}
        meta = reqd.get("meta") if isinstance(reqd.get("meta"), dict) else {}
        try:
            _locked_final_u = float(meta.get('amount_locked_final_u') or 0.0)
        except Exception:
            _locked_final_u = 0.0
        if _locked_final_u > 0.0 and bool(meta.get('amount_locked_no_override')):
            return float(_locked_final_u)
        _b1_expected = float(_b1_first_open_expected_amount_u(reqd, params=params, meta=meta) or 0.0)
        if _b1_expected > 0.0:
            return float(_b1_expected)
        return float(_coerce_final_amount_u(
            reqd.get("final_amount_u"), reqd.get("amount_u"), reqd.get("amount_usd"), reqd.get("usd"), reqd.get("u"), reqd.get("amount"), reqd.get("notional_u"),
            params.get("final_amount_u"), params.get("amount_u"), params.get("amount_usd"), params.get("usd"), params.get("u"), params.get("amount"), params.get("notional_u"),
            meta.get("final_amount_u"), meta.get("amount_u"), meta.get("amount_usd"), meta.get("usd"), meta.get("u"), meta.get("amount"), meta.get("notional_u"),
            params.get("B1__amount_usd"), meta.get("B1__amount_usd"), reqd.get("amount_usd_intent"), params.get("amount_usd_intent"), meta.get("amount_usd_intent"), reqd.get("intent_amount"), params.get("intent_amount"), meta.get("intent_amount"),
        ) or _extract_amount_usd(params, meta) or 0.0)
    except Exception:
        return 0.0

def _req_amount_u_write(reqd: dict | None, amount_u: float, *, source: str = "hardcap_preclamp") -> float:
    try:
        if not isinstance(reqd, dict):
            return 0.0
        amount_u = float(max(0.0, amount_u or 0.0))
        params = reqd.get("params") if isinstance(reqd.get("params"), dict) else {}
        meta = reqd.get("meta") if isinstance(reqd.get("meta"), dict) else {}
        _apply_final_amount_contract(reqd, params=params, meta=meta, amount_hint=amount_u)
        for k in ("final_amount_u", "amount_u", "amount_usd", "amount", "usd", "u", "notional_u", "intent_amount", "amount_usd_intent"):
            reqd[k] = float(amount_u)
        if isinstance(params, dict):
            for k in ("final_amount_u", "amount_u", "amount_usd", "amount", "usd", "u", "notional_u", "intent_amount", "amount_usd_intent"):
                params[k] = float(amount_u)
            reqd["params"] = params
        if isinstance(meta, dict):
            for k in ("final_amount_u", "amount_u", "amount_usd", "amount", "usd", "u", "notional_u", "intent_amount", "amount_usd_intent"):
                meta[k] = float(amount_u)
            meta["hardcap_precheck_amount_source"] = str(source or "hardcap_preclamp")
            if 'cap' in str(source or '').lower() or 'clamp' in str(source or '').lower():
                meta['amount_locked_final_u'] = float(amount_u)
                meta['amount_locked_source'] = str(source or 'hardcap_preclamp')
                meta['amount_locked_no_override'] = True
            reqd["meta"] = meta
        if _is_b1_new_coin_first_open_req(reqd, params=params, meta=meta):
            # Keep B1 aliases/diagnostics on the same amount as the cap decision.
            _lock_b1_first_open_amount_contract(reqd, amount_u, source=source)
        return float(amount_u)
    except Exception:
        return 0.0

def _hardcap_precheck_and_autoclamp(snapshot: dict | None, reqd: dict | None) -> tuple[bool, str, dict]:
    """硬顶前置预检：超额自动裁单；没剩余额度直接挡在决策前。"""
    detail: dict = {}
    try:
        if not isinstance(reqd, dict):
            return True, "skip:req_not_dict", detail
        mod = str(reqd.get("module") or "").upper().strip()
        coin = str(reqd.get("coin") or reqd.get("symbol") or "").upper().strip()
        plat = str(reqd.get("platform") or reqd.get("plat") or "").upper().strip()
        act = str(reqd.get("action_type") or reqd.get("action") or "").lower().strip()
        if (not coin) or (not plat) or (plat == "BOTH"):
            return True, "skip:bad_coin_platform", detail
        _safe_reduce_precheck = bool(_req_is_safe_reduce_only(reqd)) or act in ("decrease", "reduce", "close", "close_all", "close_one_leg", "tp", "trend_tp", "close_pair", "close_full", "partial_close", "close_partial_notional")
        if _safe_reduce_precheck:
            detail.update({'action_class': 'RISK_REDUCE', 'cap_bypass': True, 'cap_bypass_reason': 'reduce_bypass_cap'})
            return True, "skip:risk_reduce", detail
        if (act == "add_leg") or (mod in ("LEGACY_DELETED", "LEGACY_DELETED")) or mod.startswith("LEGACY_DELETED"):
            return True, "skip:legacy_deleted_channel", detail
        try:
            _b1_ok, _b1_reason, _b1_detail = _b1_first_open_amount_contract_sync(reqd, source='b1_first_open_scaled_single_source')
            if isinstance(_b1_detail, dict) and _b1_detail:
                detail['b1_amount_guard'] = dict(_b1_detail)
            if (not _b1_ok) and str(_b1_reason or '').startswith('b1_'):
                return False, str(_b1_reason or 'b1_amount_conflict_still_present'), detail
        except Exception as _e_b1_pre:
            detail['b1_amount_guard_exc'] = repr(_e_b1_pre)
        add_u = float(_req_amount_u_read(reqd) or 0.0)
        if add_u <= 0.0:
            return True, "skip:nonpos_amount", detail
        detail['add_u_raw'] = float(add_u)
        if _coin_pool_is_dynamic_new_coin(coin):
            _single_cap_u = float(_new_coin_single_open_cap_u())
            detail['new_coin_single_cap_u'] = float(_single_cap_u)
            if add_u > float(_single_cap_u) + 1e-9:
                try:
                    _record_new_coin_cap_event(coin, 'hardcap_precheck_single_clamp', 'new_coin_single_open_cap_clamp', mode='clamp', detail={'raw_u': float(add_u), 'final_u': float(_single_cap_u), 'cap_u': float(_single_cap_u)})
                except Exception:
                    pass
                _req_amount_u_write(reqd, float(_single_cap_u), source='new_coin_single_open_cap')
                add_u = float(_req_amount_u_read(reqd) or _single_cap_u)
                _meta_nc0 = reqd.get('meta') if isinstance(reqd.get('meta'), dict) else {}
                if isinstance(_meta_nc0, dict):
                    _meta_nc0['new_coin_single_open_cap_applied'] = 1
                    _meta_nc0['new_coin_single_open_cap_raw_u'] = float(detail.get('add_u_raw') or 0.0)
                    _meta_nc0['new_coin_single_open_cap_u'] = float(_single_cap_u)
                    reqd['meta'] = _meta_nc0
            _coin_total_cap_u = float(_new_coin_total_hardcap_u())
            _coin_total_cur_u = float(_dynamic_new_coin_total_notional_u(snapshot or {}, coin))
            _coin_total_remain_u = max(0.0, float(_coin_total_cap_u) - float(_coin_total_cur_u))
            detail.update({'new_coin_total_cap_u': float(_coin_total_cap_u), 'new_coin_total_cur_u': float(_coin_total_cur_u), 'new_coin_total_remain_u': float(_coin_total_remain_u)})
            if _coin_total_remain_u < 10.0 - 1e-9:
                try:
                    _record_new_coin_cap_event(coin, 'hardcap_precheck_total_reject', 'new_coin_total_cap_no_room', mode='reject', detail={'raw_u': float(add_u), 'final_u': 0.0, 'cap_u': float(_coin_total_cap_u), 'cur_u': float(_coin_total_cur_u), 'remain_u': float(_coin_total_remain_u)})
                except Exception:
                    pass
                detail.update({'clamped': False, 'hardcap_precheck': 'reject_new_coin_total_no_room'})
                return False, 'new_coin_total_cap_no_room', detail
            if add_u > float(_coin_total_remain_u) + 1e-9:
                try:
                    _record_new_coin_cap_event(coin, 'hardcap_precheck_total_clamp', 'new_coin_total_cap_preclamp', mode='clamp', detail={'raw_u': float(add_u), 'final_u': float(_coin_total_remain_u), 'cap_u': float(_coin_total_cap_u), 'cur_u': float(_coin_total_cur_u), 'remain_u': float(_coin_total_remain_u)})
                except Exception:
                    pass
                _req_amount_u_write(reqd, float(_coin_total_remain_u), source='new_coin_total_cap_preclamp')
                add_u = float(_req_amount_u_read(reqd) or _coin_total_remain_u)
                _meta_nc1 = reqd.get('meta') if isinstance(reqd.get('meta'), dict) else {}
                if isinstance(_meta_nc1, dict):
                    _meta_nc1['new_coin_total_cap_precheck'] = 'clamped'
                    _meta_nc1['new_coin_total_cap_u'] = float(_coin_total_cap_u)
                    _meta_nc1['new_coin_total_cur_u'] = float(_coin_total_cur_u)
                    _meta_nc1['new_coin_total_remain_u'] = float(_coin_total_remain_u)
                    reqd['meta'] = _meta_nc1
                detail.update({'new_coin_total_clamped': True, 'new_coin_total_add_u_clamped': float(add_u)})
        cap_u, cap_meta = _coin_platform_cap_u_from_snapshot(snapshot or {}, coin, plat)
        cur_u = 0.0
        cur_src = "snapshot_positions"
        try:
            cur_u = abs(_safe_float((((_pos_root(snapshot or {}) or {}).get(plat) or {}).get(coin) or {}).get('notional_u'), 0.0))
        except Exception:
            cur_u = 0.0
        try:
            _cur_leg = (((_pos_root(snapshot or {}) or {}).get(plat) or {}).get(coin) or {})
            _cur_reason = str(_cur_leg.get('reason') or '')
            _cur_side = str(_cur_leg.get('side') or '').upper()
        except Exception:
            _cur_reason = ''
            _cur_side = ''
        try:
            _mr = ((((snapshot or {}).get('raw') or {}).get('missing_rows') or {}))
            if isinstance(_mr, dict):
                _lst = _mr.get(plat) or []
                if isinstance(_lst, (list, tuple)) and (coin in _lst):
                    cur_u = 0.0
                    cur_src = 'missing_rows_as_zero'
                    _cur_reason = 'row_not_found'
                    _cur_side = 'NONE'
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_981', _e)
            pass
        if cur_u <= 0.0 and (_cur_reason not in ('row_not_found',)) and isinstance(globals().get('LAST_GOOD_SNAPSHOT'), dict):
            try:
                _lg = globals().get('LAST_GOOD_SNAPSHOT') or {}
                _lg_leg = (((_lg.get('positions') or {}).get(plat) or {}).get(coin) or {})
                _lg_u = abs(_safe_float(_lg_leg.get('notional_u'), 0.0))
                if (_lg_u > 0.0) and (str(_lg_leg.get('reason') or '') == 'ok'):
                    cur_u = float(_lg_u)
                    cur_src = 'last_good_snapshot'
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_982', _e)
                pass
        remain_u = max(0.0, float(cap_u) - float(cur_u))
        proj_u = float(cur_u) + float(add_u)
        detail = {
            'coin': coin, 'platform': plat, 'module': mod, 'action_type': act,
            'cur_u': float(cur_u), 'add_u_raw': float(add_u), 'proj_u_raw': float(proj_u),
            'cap_u': float(cap_u), 'remain_u': float(remain_u), 'cur_src': str(cur_src),
            'cap_src': str((cap_meta or {}).get('cap_src') or ''), 'cap_ratio': float((cap_meta or {}).get('cap_ratio') or 0.0),
            'platform_equity_u': float((cap_meta or {}).get('platform_equity_u') or 0.0),
        }
        if float(cap_u) <= 0.0:
            return True, 'skip:no_cap', detail
        if remain_u <= 1e-9:
            detail.update({'clamped': False, 'hardcap_precheck': 'reject_no_room'})
            return False, 'hardcap_precheck_no_room', detail
        _b1_meta = reqd.get('meta') if isinstance(reqd.get('meta'), dict) else {}
        _b1_missing_leg = bool(_b1_meta.get('missing_leg_mode')) or str(_b1_meta.get('reason_source') or '').lower() == 'missing_leg_b1'
        if _is_b1_new_coin_first_open_req(reqd) and not _b1_missing_leg:
            _b1_min = float(_b1_first_open_min_effective_u())
            if min(float(add_u), float(remain_u)) < _b1_min - 1e-9:
                detail.update({'min_amount_u': _b1_min, 'hardcap_precheck': 'reject_below_b1_min'})
                return False, 'b1_cap_below_min_amount', detail
        if proj_u > float(cap_u) + 1e-9:
            clamped_u = float(remain_u)
            _req_amount_u_write(reqd, clamped_u, source='hardcap_preclamp')
            meta = reqd.get('meta') if isinstance(reqd.get('meta'), dict) else {}
            if isinstance(meta, dict):
                meta['hardcap_precheck'] = 'clamped'
                meta['hardcap_precheck_reason'] = 'auto_trim_to_remaining_cap'
                meta['hardcap_precheck_raw_add_u'] = float(add_u)
                meta['hardcap_precheck_clamped_u'] = float(clamped_u)
                meta['hardcap_precheck_remain_u'] = float(remain_u)
                reqd['meta'] = meta
            detail.update({'clamped': True, 'add_u_clamped': float(clamped_u), 'hardcap_precheck': 'clamped'})
            return True, 'hardcap_preclamp', detail
        detail.update({'clamped': False, 'add_u_clamped': float(add_u), 'hardcap_precheck': 'pass'})
        return True, 'ok', detail
    except Exception as _e:
        detail['exc'] = repr(_e)
        return True, 'precheck_exception_bypass', detail

def yingding_jiancha(snapshot: dict, coin: str, platform: str, add_u: float, module: str|None=None, action_type: str|None=None, *, cur_u_override: float|None=None) -> tuple[bool, str, dict]:
    """硬顶检查（返回(是否允许, 原因, 数值明细)）

    一次性修复点（按北境老板要求）：
    1) cap（硬顶）基准不再用 equity（权益/资金）兜底，统一用 total_u（总资金锚点）× 单币比例
       - BTC/ETH：160%（单币单平台）
       - 其他币：120%（单币单平台）
    2) cur（当前名义）不允许出现 None（空值）：
       - 优先用 snapshot.positions 里的 notional_u（名义）
       - 若缺失且传入 cur_u_override（请求元数据名义），则用 override
       - 若仍缺失：返回 yingding_cur_missing（硬顶当前值缺失），让日志一眼看懂
    3) detail（明细）统一提供 cur_u/add_u/proj_u/cap_u/cap_src/cur_src，避免日志里打印 None
    """
    total_u = _total_u_from_snapshot_or_anchor(snapshot, ZIJIN_MAODIAN_U)
    sum_all = _quanju_sum_notional_u(snapshot)
    _act_u = str(action_type or '').lower().strip()
    if _is_reduce_action(_act_u):
        return True, 'skip:risk_reduce', {
            'coin': str(coin or ''), 'platform': str(platform or ''), 'module': str(module or ''), 'action_type': str(action_type or ''),
            'add_u': float(_safe_float(add_u, 0.0)), 'action_class': 'RISK_REDUCE', 'cap_bypass': True, 'cap_bypass_reason': 'reduce_bypass_cap',
        }
    if _coin_pool_is_dynamic_new_coin(coin):
        _new_single_cap_u = float(_new_coin_single_open_cap_u())
        try:
            _add_u_chk = float(add_u or 0.0)
        except Exception:
            _add_u_chk = 0.0
        if _add_u_chk > float(_new_single_cap_u) + 1e-9:
            try:
                _record_new_coin_cap_event(coin, 'hardcap_final_single_block', 'new_coin_single_open_cap_block', mode='reject', detail={'raw_u': float(_add_u_chk), 'final_u': float(_new_single_cap_u), 'cap_u': float(_new_single_cap_u)})
            except Exception:
                pass
            return False, 'new_coin_single_open_cap_block', {
                'coin': str(coin or ''), 'platform': str(platform or ''), 'module': str(module or ''), 'action_type': str(action_type or ''),
                'add_u': float(_add_u_chk), 'single_cap_u': float(_new_single_cap_u), 'reason': 'single_open_gt_cap'
            }
        _coin_total_cap_u = float(_new_coin_total_hardcap_u())
        _coin_total_cur_u = float(_dynamic_new_coin_total_notional_u(snapshot, coin))
        if float(_coin_total_cur_u + _add_u_chk) > float(_coin_total_cap_u) + 1e-9:
            try:
                _record_new_coin_cap_event(coin, 'hardcap_final_total_block', 'new_coin_total_cap_block', mode='reject', detail={'raw_u': float(_add_u_chk), 'final_u': float(max(0.0, _coin_total_cap_u - _coin_total_cur_u)), 'cap_u': float(_coin_total_cap_u), 'cur_u': float(_coin_total_cur_u), 'remain_u': float(max(0.0, _coin_total_cap_u - _coin_total_cur_u))})
            except Exception:
                pass
            return False, 'new_coin_total_cap_block', {
                'coin': str(coin or ''), 'platform': str(platform or ''), 'module': str(module or ''), 'action_type': str(action_type or ''),
                'coin_total_cur_u': float(_coin_total_cur_u), 'add_u': float(_add_u_chk), 'coin_total_cap_u': float(_coin_total_cap_u),
                'proj_coin_total_u': float(_coin_total_cur_u + _add_u_chk), 'reason': 'proj_gt_total_cap'
            }

    cap_base_u, cap_meta = _coin_platform_cap_u_from_snapshot(snapshot, coin, platform)
    platform_equity_u = float((cap_meta or {}).get('platform_equity_u') or 0.0)
    try:
        cap_ratio = float((cap_meta or {}).get('cap_ratio') or _yingding_ratio_for_coin(coin))
    except Exception:
        cap_ratio = float(YINGDING_BILI_QITA)

    cap_src = str((cap_meta or {}).get('cap_src') or 'platform_equity')
    cap_time_mul = 1.0  # 已移除按时间档调整硬顶倍率
    cap_leg_u = float(cap_base_u) * float(cap_time_mul)
    try:
        cap_pair_ratio = float(((PEIZHI.get('zijin') or {}) if isinstance(PEIZHI, dict) else {}).get('cap_pair_ratio', 1.0))
    except Exception:
        cap_pair_ratio = 1.0
    try:
        if float(cap_pair_ratio) < 1.0:
            cap_pair_ratio = 1.0
    except Exception:
        cap_pair_ratio = 1.0
    cap_pair_u = float(cap_leg_u) * float(cap_pair_ratio)
    try:
        if float(cap_pair_u) < float(cap_leg_u):
            cap_pair_u = float(cap_leg_u)
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    enable_global = bool((PEIZHI.get('zijin', {}) if isinstance(PEIZHI, dict) else {}).get('enable_global_notional_cap', False))
    if enable_global:
        global_cap_u = _safe_float((PEIZHI.get('zijin', {}) or {}).get('global_notional_cap_u'), 0.0)
        if global_cap_u > 0 and (sum_all + float(add_u)) > global_cap_u + 1e-9:
            return False, 'quanju_yingding_lanjie', {
                'total_u': float(total_u), 'sum_all_u': float(sum_all), 'add_u': float(add_u), 'cap_global_u': float(global_cap_u),
                'coin': str(coin or ''), 'platform': str(platform or ''), 'module': str(module or ''), 'action_type': str(action_type or ''),
                'cap_src': cap_src,
                'platform_equity_u': float(platform_equity_u),
        'cap_time_mul': float(cap_time_mul),

            }

    cur_src = 'snapshot_positions'
    cur_leg_u = 0.0
    try:
        cur_leg_u = abs(_safe_float((((_pos_root(snapshot) or {}).get(platform) or {}).get(coin) or {}).get('notional_u'), 0.0))
    except Exception:
        cur_leg_u = 0.0

    try:
        if (cur_leg_u <= 0.0) and (cur_u_override is not None) and (float(cur_u_override) > 0.0):
            cur_leg_u = abs(float(cur_u_override))
            cur_src = 'req_meta_override'
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    try:
        _cur_leg = (((_pos_root(snapshot) or {}).get(platform) or {}).get(coin) or {})
        _cur_reason = str(_cur_leg.get('reason') or '')
        _cur_side = str(_cur_leg.get('side') or '').upper()
    except Exception:
        _cur_reason = ''
        _cur_side = ''

    try:
        _mr = ((snapshot.get('raw') or {}).get('missing_rows') or {})
        if isinstance(_mr, dict):
            _lst = _mr.get(platform) or []
            if isinstance(_lst, (list, tuple)) and (str(coin or '') in _lst):
                _cur_reason = 'row_not_found'
                _cur_side = 'NONE'
                cur_leg_u = 0.0
                cur_src = 'missing_rows_as_zero'
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    try:
        if (cur_leg_u <= 0.0) and (_cur_reason not in ('row_not_found',)) and isinstance(globals().get('LAST_GOOD_SNAPSHOT'), dict):
            _lg = globals().get('LAST_GOOD_SNAPSHOT') or {}
            _lg_leg = (((_lg.get('positions') or {}).get(platform) or {}).get(coin) or {})
            _lg_u = abs(_safe_float(_lg_leg.get('notional_u'), 0.0))
            if (_lg_u > 0.0) and (str(_lg_leg.get('reason') or '') == 'ok'):
                cur_leg_u = float(_lg_u)
                cur_src = 'last_good_snapshot'
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    if cur_leg_u <= 0.0 and float(add_u) > 0.0:
        if (_cur_reason in ('row_not_found',) or _cur_side in ('NONE', '')):
            cur_leg_u = 0.0
            cur_src = 'snapshot_row_not_found_as_zero'
        else:
            detail = {
                'total_u': float(total_u),
                'coin': str(coin or ''), 'platform': str(platform or ''), 'module': str(module or ''), 'action_type': str(action_type or ''),
                'cur_u': float(cur_leg_u) if cur_leg_u>0 else 0.0,
                'missing': True,
                'cur_src': cur_src,
                'cur_reason': str(_cur_reason),
                'add_u': float(add_u),
                'proj_u': float(cur_leg_u) + float(add_u) if cur_leg_u>0 else float(add_u),
                'cap_u': float(cap_leg_u),
                'cap_leg_u': float(cap_leg_u),
                'cap_pair_u': float(cap_pair_u),
                'cap_ratio': float(cap_ratio),
                'cap_pair_ratio': float(cap_pair_ratio),
                'cap_src': cap_src,
                'platform_equity_u': float(platform_equity_u),
        'cap_time_mul': float(cap_time_mul),
            }
            return False, 'yingding_cur_missing', detail

    e_u = 0.0
    v_u = 0.0
    try:
        e_u = abs(_safe_float((((_pos_root(snapshot) or {}).get('EXT') or {}).get(coin) or {}).get('notional_u'), 0.0))
    except Exception:
        e_u = 0.0
    try:
        v_u = abs(_safe_float((((_pos_root(snapshot) or {}).get('VAR') or {}).get(coin) or {}).get('notional_u'), 0.0))
    except Exception:
        v_u = 0.0
    pair_max_u = float(max(float(e_u), float(v_u)))
    opp_leg_u = float(v_u if str(platform or '').upper() == 'EXT' else e_u)
    gap_u = float(abs(float(cur_leg_u) - float(opp_leg_u)))
    is_add_small_leg = bool(float(cur_leg_u) + 1e-9 < float(opp_leg_u))
    is_add_big_leg = bool(not is_add_small_leg)

    new_leg_u = float(cur_leg_u) + float(add_u)
    new_pair_max_u = float(max(pair_max_u, new_leg_u))

    mm = str(module or '').upper()
    act = str(action_type or '').lower()  # FIX: 原来误引用 req（未定义），导致历史加仓金额计算 NameError:req

    detail = {
        'total_u': float(total_u),
        'sum_all_u': float(sum_all),
        'coin': str(coin or ''),
        'platform': str(platform or ''),
        'module': str(module or ''),
        'action_type': str(action_type or ''),
        'cur_u': float(cur_leg_u),
        'cur_leg_u': float(cur_leg_u),
        'opp_leg_u': float(opp_leg_u),
        'gap_u': float(gap_u),
        'cur_src': cur_src,
        'add_u': float(add_u),
        'proj_u': float(new_leg_u),
        'new_leg_u': float(new_leg_u),
        'pair_max_u': float(pair_max_u),
        'new_pair_max_u': float(new_pair_max_u),
        'is_add_small_leg': bool(is_add_small_leg),
        'is_add_big_leg': bool(is_add_big_leg),
        'hardcap_verdict': '',
        'cap_u': float(cap_leg_u),
        'cap_leg_u': float(cap_leg_u),
        'cap_pair_u': float(cap_pair_u),
        'cap_ratio': float(cap_ratio),
        'cap_pair_ratio': float(cap_pair_ratio),
        'cap_src': cap_src,
                'platform_equity_u': float(platform_equity_u),
        'cap_time_mul': float(cap_time_mul),
    }
    if mm == 'LEGACY_DELETED' and act == 'add_leg':
        try:
            detail['legacy_deleted_bypass_yingding'] = True
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

        return True, 'ok_legacy_deleted_bypass_yingding', detail

    if mm == 'LEGACY_DELETED' and act in ('add_leg','increase','add'):
        try:
            cap_struct_legacy_deleted_u = float(max(float(cap_leg_u), float(pair_max_u)))
        except Exception:
            cap_struct_legacy_deleted_u = float(cap_leg_u)
        try:
            detail['cap_src'] = 'legacy_deleted_chasecap'
            detail['cap_leg_u'] = float(cap_struct_legacy_deleted_u)
            detail['cap_pair_u'] = float(cap_struct_legacy_deleted_u)
            detail['cap_struct_legacy_deleted_u'] = float(cap_struct_legacy_deleted_u)
            detail['pair_max_u'] = float(pair_max_u)
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

        if float(new_pair_max_u) > float(cap_struct_legacy_deleted_u) + 1e-9:
            return False, 'yingding_legacy_fix_chasecap', detail
        return True, 'ok_legacy_deleted_legacy_deleted_chasecap', detail

    if new_leg_u > cap_leg_u + 1e-9:
        detail['hardcap_verdict'] = 'block_leg_cap'
        return False, 'yingding_leg_lanjie', detail

    if float(pair_max_u) > cap_pair_u + 1e-9:
        if bool(is_add_big_leg):
            detail['hardcap_verdict'] = 'block_big_leg_extend_over_pair_cap'
            return False, 'yingding_pair_lanjie_big_leg_extend', detail
        detail['hardcap_verdict'] = 'allow_small_leg_rebalance'
        return True, 'ok_pair_small_leg_rebalance', detail

    if float(new_pair_max_u) > cap_pair_u + 1e-9:
        detail['hardcap_verdict'] = 'block_pair_cap_after_add'
        return False, 'yingding_pair_lanjie', detail

    detail['hardcap_verdict'] = 'ok'
    return True, 'ok', detail

def m9_shengcheng_zhaiyao(snapshot: dict, *, scan_ts: float | None = None, next_scan_ts: float | None = None, last_action: dict | None = None) -> dict:
    """给 M9Logger.zhaiyao 使用：重点信息摘要（运维TXT（文本））"""
    total_u = _total_u_from_snapshot_or_anchor(snapshot, ZIJIN_MAODIAN_U)
    sum_all = _quanju_sum_notional_u(snapshot)
    pos = (snapshot or {}).get("positions") or {}
    v_u = 0.0
    e_u = 0.0
    if isinstance(pos, dict):
        for plat, cmap in pos.items():
            if not isinstance(cmap, dict):
                continue
            for _, leg in cmap.items():
                if not isinstance(leg, dict):
                    continue
                nu = _safe_float(leg.get("notional_u"), 0.0)
                if str(plat).upper() == "VAR":
                    v_u += nu
                if str(plat).upper() == "EXT":
                    e_u += nu
    def _fmt(ts):
        if ts is None:
            return None
        try:
            return time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(float(ts)))
        except Exception:
            return None
    return {
        "shijian": _fmt(time.time()),
        "scan_shijian": _fmt(scan_ts),
        "yujixiacisao_shijian": _fmt(next_scan_ts),
        "zijin_maodian_u": ZIJIN_MAODIAN_U,
        "total_u": round(total_u, 6),
        "quanju_mingyi_u": round(sum_all, 6),
        "duichong_zhuangtai": {
            "v_mingyi_u": round(v_u, 6),
            "e_mingyi_u": round(e_u, 6),
            "chazhi_u": round(v_u - e_u, 6),
        },
        "zuijin_dongzuo": last_action,
    }

