def _m9_write_layers_csv_from_payload(payload: dict) -> None:
    """把 payload['entries'] 展开为层级 CSV（每轮覆盖写）。

    关键修复：
    - 无论是否有层，都必须写出“表头”，否则 UI 会变成空白（columns=[]）。
    - 发生异常时写 out/m9_ui_errors.log，且仍尽量写出空表头文件。
    """
    import csv as _csv
    fp = _m9_grid_layers_last_csv_fp()
    header = [
        "plat","coin","side","grid_id","layer_id",
        "open_px","tp_px","open_u","state","hit","ts_open","ts_hit",
        "grid_mode","trend_state","profit_locked","partial_close_ratio","protect_px","trail_anchor_px","trend_close_reason",
        "trend_reason","trend_rsi","trend_adx","trend_cover_ratio","trend_same_notional_u","trend_opp_notional_u"
    ]

    def _write_empty():
        try:
            _dirty_write_csv(fp, header, [], cache_key="m9_grid_layers_last_csv")
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    try:
        entries = (payload or {}).get("entries") or []
        rows = []
        if not isinstance(entries, list):
            entries = []
        for e in entries:
            if not isinstance(e, dict):
                continue
            coin = str(e.get("coin") or "").upper()
            plat = str(e.get("platform") or "").upper()
            side = str(e.get("side") or "").upper()
            grid_id = str(e.get("grid_id") or "")
            layers = e.get("layers") or []
            if not isinstance(layers, list):
                layers = []
            for ly in layers:
                if not isinstance(ly, dict):
                    continue
                rows.append([
                    plat, coin, side, grid_id,
                    str(ly.get("layer_id") or ly.get("id") or ""),
                    _fmt_float(ly.get("open_px") if ly.get("open_px") is not None else ly.get("open_ref_px")),
                    _fmt_float(ly.get("tp_px")),
                    _fmt_float(ly.get("open_notional_u") or ly.get("open_u")),
                    str(ly.get("state") or ly.get('trend_state') or ""),
                    str(ly.get("hit") or ""),
                    str(ly.get("ts_open") or ""),
                    str(ly.get("ts_hit") or ""),
                    str(ly.get('grid_mode') or ''),
                    str(ly.get('trend_state') or ''),
                    str(ly.get('profit_locked') or ''),
                    _fmt_float(ly.get('partial_close_ratio')),
                    _fmt_float(ly.get('protect_px')),
                    _fmt_float(ly.get('trail_anchor_px')),
                    str(ly.get('trend_close_reason') or ly.get('close_reason') or ''),
                    str(ly.get('trend_reason') or ''),
                    _fmt_float(ly.get('trend_rsi')),
                    _fmt_float(ly.get('trend_adx')),
                    _fmt_float(ly.get('trend_cover_ratio')),
                    _fmt_float(ly.get('trend_same_notional_u')),
                    _fmt_float(ly.get('trend_opp_notional_u')),
                ])

        _dirty_write_csv(fp, header, rows, cache_key="m9_grid_layers_last_csv")
    except Exception:
        try:
            err_fp = os.path.join(os.path.dirname(__file__), "out", "m9_ui_errors.log")
            os.makedirs(os.path.dirname(err_fp), exist_ok=True)
            with open(err_fp, "a", encoding="utf-8") as ef:
                ef.write(f"[{now_ts()}] _m9_write_layers_csv_from_payload exception:\n{traceback.format_exc()}\n")
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

        _write_empty()

