def _m9_write_observe_table_from_payload(payload: dict) -> None:
    """根据 _m9_build_detail_payload 输出你要的“按平台区分的所有币种总表”。

    关键修复：
    - 无论 entries 是否为空，都必须写出 CSV 表头，否则 UI 空白。
    - 发生异常时写 out/m9_ui_errors.log，并尽量写出空表头文件。
    """
    import csv as _csv
    try:
        payload = _m9_observe_payload_align_to_master_book(payload)
    except Exception as _e:
        _record_swallowed_exception('m9_observe_table.align_master_book', _e)
    entries = (payload or {}).get("entries") or []
    if not isinstance(entries, list):
        entries = []

    obs_round = int((payload or {}).get("obs_round") or 0)
    ts = float((payload or {}).get("ts") or time.time())
    ts_s = time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(ts))

    header = [
        "plat","coin","side",
        "pos_u","layers","cur_px",
        "next_sell_tp_px","next_sell_gap_pct",
        "next_buy_px","next_buy_gap_pct","main_trigger_gap_pct","main_trigger_gap_raw_pct",
        "final_reason","final_stage","final_verdict",
        "trend_side","cover_ratio","trend_layers","trend_cap","freeze_loss_leg","trend_reason",
        "same_u","opp_u","same_upnl_u","opp_upnl_u",
        "loss_pct","yingding_ok","capblock_left_s","m9_gate_left_s","tp_lock_left_s","add_cd_left_s",
        "plans_cnt",
        "est_profit_u","realized_u","obs_cnt"
    ]

    fp_csv = _m9_observe_table_last_csv_fp()
    fp_hist = _m9_observe_table_hist_csv_fp()
    fp_txt = _m9_observe_table_last_txt_fp()

    def _safe_mkdir(p):
        try:
            os.makedirs(os.path.dirname(p), exist_ok=True)
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    def _write_empty():
        try:
            _dirty_write_csv(fp_csv, header, [], cache_key="m9_observe_table_last_csv")
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    try:
        try:
            rows_txt = []
            rows_txt.append(f"=== M9 网格可观测总表 | obs_round={obs_round} | ts={ts_s} ===")
            rows_txt.append(" | ".join(header))
            for e in entries:
                if not isinstance(e, dict):
                    continue
                plat = str(e.get("platform") or "").upper()
                coin = str(e.get("coin") or "").upper()
                side = str(e.get("side") or "").upper()
                pos_u = _fmt_float(e.get("pos_notional_u") or e.get("pos_u") or e.get("pos_value_u"))
                layers = int(e.get("layers_open_cnt") or 0)
                cur_px = _fmt_float(e.get("cur_px") if e.get("cur_px") is not None else e.get("px"))
                next_sell_tp_px = _fmt_float(e.get("next_sell_tp_px"))
                next_sell_gap_pct = _fmt_float(e.get("next_sell_gap_pct"))
                next_buy_px = _fmt_float(e.get("next_buy_px"))
                next_buy_gap_pct = _fmt_float(e.get("next_buy_gap_pct"))
                main_trigger_gap_pct = _fmt_float(e.get("main_trigger_gap_pct"))
                main_trigger_gap_raw_pct = _fmt_float(e.get("main_trigger_gap_raw_pct"))
                final_reason = str(e.get("final_reason") or e.get("final_reason_code") or "")
                final_stage = str(e.get("final_stage") or "")
                final_verdict = str(e.get("final_verdict") or "")
                est_profit_u = _fmt_float(e.get("grid_target_profit_u"))
                realized_u = _fmt_float(e.get("grid_realized_pnl_u"))
                obs_cnt = int(e.get("grid_observe_cnt") or 0)
                trend_side = str(e.get("trend_side") or "")
                cover_ratio = _fmt_float(e.get("trend_cover_ratio"))
                trend_layers = str(int(e.get("trend_layers_open") or 0))
                trend_cap = str(int(e.get("trend_layers_cap") or 0))
                freeze_loss_leg = str(int(e.get("freeze_loss_leg_new_grid") or 0))
                trend_reason = str(e.get("trend_reason") or "")
                same_u = _fmt_float(e.get("trend_same_notional_u"))
                opp_u = _fmt_float(e.get("trend_opp_notional_u"))
                same_upnl_u = _fmt_float(e.get("trend_same_upnl_u"))
                opp_upnl_u = _fmt_float(e.get("trend_opp_upnl_u"))
                rows_txt.append(" | ".join([
                    plat, coin, side,
                    str(pos_u), str(layers), str(cur_px),
                    str(next_sell_tp_px), str(next_sell_gap_pct),
                    str(next_buy_px), str(next_buy_gap_pct), str(main_trigger_gap_pct), str(main_trigger_gap_raw_pct),
                    final_reason, final_stage, final_verdict,
                    trend_side, str(cover_ratio), str(trend_layers), str(trend_cap), str(freeze_loss_leg), trend_reason,
                    str(same_u), str(opp_u), str(same_upnl_u), str(opp_upnl_u),
                    str(est_profit_u), str(realized_u), str(obs_cnt),
                ]))
            _safe_mkdir(fp_txt)
            _txt_full = "\n".join(rows_txt) + "\n"
            _dirty_write_text(fp_txt, _txt_full, cache_key="m9_observe_table_last_txt", semantic_text=_semanticize_text_for_dirty(_txt_full))
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

        rows = []
        for e in entries:
            if not isinstance(e, dict):
                continue
            plat = str(e.get("platform") or "").upper()
            coin = str(e.get("coin") or "").upper()
            side = str(e.get("side") or "").upper()
            pos_u = _fmt_float(e.get("pos_notional_u") or e.get("pos_u") or e.get("pos_value_u"))
            layers = int(e.get("layers_open_cnt") or 0)
            cur_px = _fmt_float(e.get("cur_px") if e.get("cur_px") is not None else e.get("px"))
            next_sell_tp_px = _fmt_float(e.get("next_sell_tp_px"))
            next_sell_gap_pct = _fmt_float(e.get("next_sell_gap_pct"))
            next_buy_px = _fmt_float(e.get("next_buy_px"))
            next_buy_gap_pct = _fmt_float(e.get("next_buy_gap_pct"))
            main_trigger_gap_pct = _fmt_float(e.get("main_trigger_gap_pct"))
            main_trigger_gap_raw_pct = _fmt_float(e.get("main_trigger_gap_raw_pct"))
            final_reason = str(e.get("final_reason") or e.get("final_reason_code") or "")
            final_stage = str(e.get("final_stage") or "")
            final_verdict = str(e.get("final_verdict") or "")
            est_profit_u = _fmt_float(e.get("grid_target_profit_u"))
            realized_u = _fmt_float(e.get("grid_realized_pnl_u"))
            obs_cnt = int(e.get("grid_observe_cnt") or 0)
            trend_side = str(e.get("trend_side") or "")
            cover_ratio = _fmt_float(e.get("trend_cover_ratio"))
            trend_layers = str(int(e.get("trend_layers_open") or 0))
            trend_cap = str(int(e.get("trend_layers_cap") or 0))
            freeze_loss_leg = str(int(e.get("freeze_loss_leg_new_grid") or 0))
            trend_reason = str(e.get("trend_reason") or "")
            same_u = _fmt_float(e.get("trend_same_notional_u"))
            opp_u = _fmt_float(e.get("trend_opp_notional_u"))
            same_upnl_u = _fmt_float(e.get("trend_same_upnl_u"))
            opp_upnl_u = _fmt_float(e.get("trend_opp_upnl_u"))
            gates = e.get("gates") or {}
            if not isinstance(gates, dict):
                gates = {}
            loss_pct2 = _fmt_float(gates.get("loss_pct"), 6)
            try:
                ying_ok = gates.get("yingding")
                if isinstance(ying_ok, dict):
                    ying_ok = bool(ying_ok.get("ok", True))
                elif ying_ok is None:
                    ying_ok = ""
                else:
                    ying_ok = bool(ying_ok)
            except Exception:
                ying_ok = ""
            capblock_left_s2 = str(int(_safe_float(gates.get("capblock_left_s"), 0.0)))
            m9_gate_left_s2 = str(int(_safe_float(gates.get("m9_gate_left_s"), 0.0)))
            tp_lock_left_s2 = str(int(_safe_float(gates.get("tp_lock_left_s"), 0.0)))
            add_cd_left_s2 = str(int(_safe_float(gates.get("add_cd_left_s"), 0.0)))
            plans_cnt = 0
            try:
                plans_cnt = len(e.get("plans") or [])
            except Exception:
                plans_cnt = 0

            rows.append([
                plat, coin, side,
                pos_u, layers, cur_px,
                next_sell_tp_px, next_sell_gap_pct,
                next_buy_px, next_buy_gap_pct, main_trigger_gap_pct, main_trigger_gap_raw_pct,
                final_reason, final_stage, final_verdict,
                trend_side, cover_ratio, trend_layers, trend_cap, freeze_loss_leg, trend_reason,
                same_u, opp_u, same_upnl_u, opp_upnl_u,
                loss_pct2, ("1" if ying_ok is True else ("0" if ying_ok is False else "")),
                capblock_left_s2, m9_gate_left_s2, tp_lock_left_s2, add_cd_left_s2,
                str(int(plans_cnt)),
                est_profit_u, realized_u, obs_cnt,
            ])

        _dirty_write_csv(fp_csv, header, rows, cache_key="m9_observe_table_last_csv")

        try:
            _safe_mkdir(fp_hist)
            _sig_rows = {"header": header, "rows": rows}
            _append_csv_history_throttled(
                fp_hist,
                header,
                rows,
                cache_key="m9_observe_table_history_csv",
                prefix_header=["ts", "obs_round"],
                prefix_row=lambda _r: [ts_s, obs_round],
                sig_obj=_semanticize_json_for_dirty(_sig_rows),
                min_interval_sec=45.0,
            )
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    except Exception:
        try:
            err_fp = os.path.join(os.path.dirname(__file__), "out", "m9_ui_errors.log")
            os.makedirs(os.path.dirname(err_fp), exist_ok=True)
            with open(err_fp, "a", encoding="utf-8") as ef:
                ef.write(f"[{now_ts()}] _m9_write_observe_table_from_payload exception:\n{traceback.format_exc()}\n")
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

        _write_empty()

    try:
        def _st(p):
            try:
                if not p or (not os.path.exists(p)):
                    return {"exists": False}
                return {"exists": True, "size": int(os.path.getsize(p)), "mtime": float(os.path.getmtime(p))}
            except Exception:
                return {"exists": False}
        _pin("UI", stage="FILES", reason="observe_table_written",
             csv=_st(fp_csv), txt=_st(fp_txt), hist=_st(fp_hist))
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

