    try:
        okb, rsnb = _round_ui_budget_consume('final_confirm_ind', coin=coin_u, plat='VAR', ctx='EXECUTOR_FINAL_CONFIRM_IND', evidence='', cost=1)
        _round_ui_budget_touch_watch(note=f'final_confirm_ind:{rsnb}:executor_same_page')
    except Exception as _e_b:
        out['ok'] = False
        out['reason'] = f'fc_budget_exc:{type(_e_b).__name__}'
        meta['final_confirm_ind'] = dict(out)
        meta['submit_block_reason'] = 'final_confirm_ind_block'
        meta['submit_block_detail'] = dict(out)
        return out
    if not okb:
        out['ok'] = False
        out['budget_reason'] = str(rsnb or '')
