def _panel_bridge_mirror_path(src_path: str) -> str:
    """把 OUT_DIR/LOGS_DIR/PANEL_OUT_DIR/PANEL_LOGS_DIR 下的文件，镜像到 BRIDGE_* 目录。"""
    try:
        sp = os.path.abspath(str(src_path))
    except Exception:
        sp = str(src_path)
    try:
        out_roots = []
        try:
            out_roots.append(os.path.abspath(str(PANEL_OUT_DIR)))
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_1137', _e)
            pass
        try:
            out_roots.append(os.path.abspath(str(OUT_DIR)))
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_1138', _e)
            pass
        for r in out_roots:
            try:
                if r and sp.startswith(r + os.sep) and BRIDGE_OUT_DIR:
                    rel = sp[len(r):].lstrip(os.sep)
                    return os.path.abspath(str(Path(BRIDGE_OUT_DIR) / rel))
            except Exception:
                continue
        log_roots = []
        try:
            log_roots.append(os.path.abspath(str(PANEL_LOGS_DIR)))
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_1139', _e)
            pass
        try:
            log_roots.append(os.path.abspath(str(LOGS_DIR)))
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_1140', _e)
            pass
        for r in log_roots:
            try:
                if r and sp.startswith(r + os.sep) and BRIDGE_LOGS_DIR:
                    rel = sp[len(r):].lstrip(os.sep)
                    return os.path.abspath(str(Path(BRIDGE_LOGS_DIR) / rel))
            except Exception:
                continue
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_1141', _e)
        pass
    return ""

def _pick_writable_dir(preferred: Path, fallback_tag: str) -> Path:
    """选择一个可写目录（Windows（系统）权限/杀软/同步盘很容易导致 PermissionError（权限错误））。"""
    try:
        preferred.mkdir(parents=True, exist_ok=True)
        test_fp = preferred / (".__writable_test__" + str(int(time.time() * 1000)))
        with open(str(test_fp), "w", encoding="utf-8") as f:
            f.write("ok")
        try:
            os.remove(str(test_fp))
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

        return preferred
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    fb = Path(tempfile.gettempdir()) / "bot_panel_bridge" / fallback_tag
    try:
        fb.mkdir(parents=True, exist_ok=True)
        return fb
    except Exception:
        return Path(".")

