def probe_extra(kind: str, **fields) -> None:
    """写入 logs/probe_extra.jsonl，并输出一行 [PROBE] 证据。"""
    if not _PROBE_EXTRA_ENABLED:
        return
    try:
        evt = {"ts": float(time.time()), "kind": str(kind)}
        for k, v in (fields or {}).items():
            try:
                json.dumps(v, ensure_ascii=False)
                evt[k] = v
            except Exception:
                evt[k] = str(v)
        fp = os.path.join(str(LOGS_DIR), "probe_extra.jsonl")
        try:
            with open(fp, "a", encoding="utf-8") as f:
                f.write(json.dumps(evt, ensure_ascii=False) + "\n")
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

        try:
            _core = {k: evt.get(k) for k in ("kind", "coin", "platform", "gid", "mismatch", "reason", "cur_u", "add_u", "chase_cap", "remain_u") if k in evt}
            print("[PROBE]", json.dumps(_core, ensure_ascii=False))
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    except Exception:
        return

def _runtime_source_text(fp: str = "") -> str:
    try:
        _fp = str(fp or __file__ or "").strip()
    except Exception:
        _fp = ""
    if not _fp:
        return ""
    try:
        with open(_fp, "r", encoding="utf-8") as f:
            return f.read()
    except Exception:
        try:
            with open(_fp, "r", encoding="utf-8-sig") as f:
                return f.read()
        except Exception:
            return ""

def _runtime_source_has(src_text: str, needle: str) -> bool:
    try:
        return bool(str(needle or "") and (str(needle) in str(src_text or "")))
    except Exception:
        return False

def _runtime_version_fingerprint() -> dict:
    fp = os.path.abspath(str(__file__))
    src_text = _runtime_source_text(fp)
    out = {
        'script_path': fp,
        'script_name': os.path.basename(fp),
        'script_size': 0,
        'script_mtime': 0.0,
        'script_md5': '',
        'build_tag': str(globals().get('BUILD_TAG') or ''),
        'runtime_magic_codes': list(globals().get('RUNTIME_MAGIC_CODES') or []),
        'runtime_magic_digest': str(globals().get('RUNTIME_MAGIC_DIGEST') or ''),
        'has_ext_click_guard': bool(_runtime_source_has(src_text, 'def _click_submit_button_direct')),
        'has_pending_truth_bridge': bool(
            _runtime_source_has(src_text, 'def _pending_open_rows_to_layers(')
            and _runtime_source_has(src_text, "'pending_truth_bridge': True")
        ),
        'has_ensure_page_singleton_guard': bool(
            _runtime_source_has(src_text, '_ENSURE_PAGE_SINGLETON_REGISTRY')
            and _runtime_source_has(src_text, 'def _ensure_page_registry_set(')
            and _runtime_source_has(src_text, '[ENSURE_PAGE][PAGE_REG_REPLACE]')
        ),
        'has_ensure_page_recover_guard_telemetry': bool(
            _runtime_source_has(src_text, '[ENSURE_PAGE][RECOVER_SKIPPED_BY_COOLDOWN]')
            and _runtime_source_has(src_text, '[ENSURE_PAGE][RECOVER_SKIPPED_BY_MAX_IN_WINDOW]')
            and _runtime_source_has(src_text, '[ENSURE_PAGE][PAGE_COUNT_BEFORE_RECOVER]')
            and _runtime_source_has(src_text, '[ENSURE_PAGE][PAGE_COUNT_AFTER_RECOVER]')
        ),
        'has_position_backed_m9_recover': bool(
            _runtime_source_has(src_text, 'def _recover_position_backed_m9_layer(')
            and _runtime_source_has(src_text, 'position_backed_m9_recover')
        ),
        'gap_floor_pct': float(globals().get('M9_GAP_FLOOR', 0.0) or 0.0),
        'ts': float(time.time()),
    }
    try:
        st = os.stat(fp)
        out['script_size'] = int(st.st_size)
        out['script_mtime'] = float(st.st_mtime)
    except Exception:
        pass
    try:
        h = hashlib.md5()
        with open(fp, 'rb') as f:
            while True:
                chunk = f.read(1024 * 1024)
                if not chunk:
                    break
                h.update(chunk)
        out['script_md5'] = h.hexdigest()
    except Exception:
        out['script_md5'] = ''
    return out

def _emit_runtime_version_fingerprint() -> dict:
    info = _runtime_version_fingerprint()
    try:
        print(f"[PIN][VERSION] script={info.get('script_path')} md5={info.get('script_md5')} size={info.get('script_size')} mtime={info.get('script_mtime')} build={info.get('build_tag')} magic={info.get('runtime_magic_digest')}")
    except Exception:
        pass
    try:
        for _base in (globals().get('OUT_DIR'), globals().get('LOGS_DIR')):
            if not _base:
                continue
            os.makedirs(str(_base), exist_ok=True)
            safe_write_json(os.path.join(str(_base), 'runtime_version.json'), info, indent=2)
            with open(os.path.join(str(_base), 'runtime_version.jsonl'), 'a', encoding='utf-8') as f:
                f.write(json.dumps(info, ensure_ascii=False) + "\n")
            try:
                with open(os.path.join(str(_base), 'runtime_magic.txt'), 'w', encoding='utf-8') as f:
                    f.write("BUILD_TAG=" + str(info.get('build_tag') or '') + "\n")
                    f.write("RUNTIME_MAGIC_DIGEST=" + str(info.get('runtime_magic_digest') or '') + "\n")
                    for _code in list(info.get('runtime_magic_codes') or []):
                        f.write(str(_code or '') + "\n")
            except Exception:
                pass
    except Exception:
        pass
    return info

