def _rotate_existing_logfile(fp: str, keep_suffix: str = "") -> None:
    """若 fp 已存在且非空，则改名为同目录的时间戳备份（避免覆盖你要留存的全量日志）。"""
    try:
        if not fp:
            return
        ap = os.path.abspath(fp)
        if (not os.path.exists(ap)) or os.path.getsize(ap) <= 0:
            return
        d = os.path.dirname(ap) or "."
        base = os.path.basename(ap)
        ts = time.strftime("%Y%m%d_%H%M%S", time.localtime())
        bak = os.path.join(d, base.replace(".jsonl", f"_{ts}.jsonl").replace(".txt", f"_{ts}.txt"))
        if keep_suffix:
            bak = bak + str(keep_suffix)
        try:
            os.replace(ap, bak)
        except Exception:
            try:
                import shutil
                shutil.move(ap, bak)
            except Exception:
                return
    except Exception:
        return

