_EXT_CANONICAL_TO_ROUTE_SYMBOL = {
    "1000PEPE": "KPEPE",
}
_EXT_ROUTE_SYMBOL_TO_CANONICAL = {str(v or '').upper().strip(): str(k or '').upper().strip() for k, v in (_EXT_CANONICAL_TO_ROUTE_SYMBOL or {}).items() if str(k or '').strip() and str(v or '').strip()}

def _ext_norm_symbol(coin: Any) -> str:
    try:
        c = str(coin or '').strip().upper()
    except Exception:
        c = ''
    return re.sub(r"[^A-Z0-9]", "", c)

def _ext_canonical_coin(coin: Any) -> str:
    c = _ext_norm_symbol(coin)
    if not c:
        return ''
    return str((_EXT_ROUTE_SYMBOL_TO_CANONICAL or {}).get(c) or c)

def _ext_route_symbol(coin: Any) -> str:
    c = _ext_canonical_coin(coin)
    if not c:
        return ''
    return str((_EXT_CANONICAL_TO_ROUTE_SYMBOL or {}).get(c) or c)

def _ext_coin_aliases(coin: Any) -> list[str]:
    canon = _ext_canonical_coin(coin)
    route = _ext_route_symbol(canon)
    out: list[str] = []
    for v in (canon, route):
        vv = _ext_norm_symbol(v)
        if vv and vv not in out:
            out.append(vv)
    return out

def _ext_parse_route_coin_from_url(url: Any) -> str:
    try:
        cur = str(url or '')
    except Exception:
        cur = ''
    try:
        m = re.search(r"/perp/([A-Za-z0-9]+)-USD(?:\b|\?|$)", cur)
    except Exception:
        m = None
    if not m:
        return ''
    return _ext_canonical_coin(m.group(1) or '')

def _ext_parse_title_coin(title: Any) -> str:
    try:
        txt = str(title or '').upper().strip()
    except Exception:
        txt = ''
    if not txt:
        return ''
    try:
        m = re.search(r"\|\s*([A-Z0-9]+)-USD\s*\|", txt)
    except Exception:
        m = None
    if not m:
        return ''
    return _ext_canonical_coin(m.group(1) or '')

def _ext_market_context_snapshot(page: Any) -> dict:
    try:
        cur_url = str(getattr(page, 'url', '') or '')
    except Exception:
        cur_url = ''
    try:
        cur_title = str(page.title() or '').strip()
    except Exception:
        cur_title = ''
    try:
        detected_coin = str(_detect_current_coin_ext(page) or '').upper().strip()
    except Exception:
        detected_coin = ''
    url_coin = _ext_parse_route_coin_from_url(cur_url)
    title_coin = _ext_parse_title_coin(cur_title)
    return {
        'url': cur_url,
        'title': cur_title,
        'detected_coin': detected_coin,
        'url_coin': url_coin,
        'title_coin': title_coin,
    }

def _ext_market_context_matches_request(req_coin: Any, *, page: Any = None, snapshot: dict | None = None) -> tuple[bool, dict]:
    snap = dict(snapshot or (_ext_market_context_snapshot(page) if page is not None else {}))
    expected_canonical = _ext_canonical_coin(req_coin)
    expected_route = _ext_route_symbol(expected_canonical)
    actual_candidates = []
    explicit_actual = []
    for src_key in ('detected_coin', 'url_coin', 'title_coin'):
        raw = _ext_norm_symbol(snap.get(src_key) or '')
        if not raw:
            continue
        canon = _ext_canonical_coin(raw)
        actual_candidates.append({'src': src_key, 'raw': raw, 'canonical': canon})
        explicit_actual.append(canon or raw)
        if canon == expected_canonical:
            best_actual = canon or raw
            det = {
                'ok': True,
                'reason': 'market_context_bound',
                'expected_canonical': expected_canonical,
                'expected_route': expected_route,
                'best_actual_coin': best_actual,
                'actual_candidates': actual_candidates,
                **snap,
            }
            return True, det
    reason = 'market_context_unconfirmed'
    best_actual = ''
    if explicit_actual:
        best_actual = str(explicit_actual[0] or '')
        reason = f'market_context_mismatch:req={expected_canonical} actual={best_actual}'
    det = {
        'ok': False,
        'reason': reason,
        'expected_canonical': expected_canonical,
        'expected_route': expected_route,
        'best_actual_coin': best_actual,
        'actual_candidates': actual_candidates,
        **snap,
    }
    return False, det

def ext_market_url(coin: str) -> str:
    route_coin = _ext_route_symbol(coin)
    return f"https://app.extended.exchange/perp/{route_coin}-USD"

def var_market_url(coin: str) -> str:
    return f"https://omni.variational.io/perpetual/{coin.upper()}"

