def _jitter_sleep(min_s: float, max_s: float) -> None:
    """轻量随机等待（主要给 legacy executor 用）。

    人话：
    - 这里不再把所有等待硬抬到 >1s；
    - 改成“保留轻抖动 + 允许更短地板”，让 UI 一亮就能更快进入下一步；
    - 仍然保底非 0，避免刚刷新就立刻读状态。
    """
    try:
        lo = float(min_s)
    except Exception:
        lo = 0.0
    try:
        hi = float(max_s)
    except Exception:
        hi = lo
    if hi < lo:
        lo, hi = hi, lo

    try:
        floor = float(_exec_cfg_float("EXEC_JITTER_MIN_FLOOR_SEC", 0.18))
    except Exception:
        floor = 0.18
    floor = max(0.08, floor)

    try:
        s = float(random.uniform(lo, hi)) if hi > lo else float(lo)
    except Exception:
        s = float(lo)

    if s <= 0.0:
        try:
            s = float(_exec_cfg_float("EXEC_JITTER_DEFAULT_SEC", 0.22))
        except Exception:
            s = 0.22
    if s < floor:
        s = floor
    try:
        time.sleep(float(s))
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

def _safe_click_first(page, selector_list, timeout_ms: int = 2500) -> bool:
    _pw_require_page(page, "_safe_click_first")
    for sel in selector_list:
        try:
            loc = page.locator(sel).first
            if _pw_call(f"safe_click_first.count:{sel}", loc.count) > 0 and _pw_call(f"safe_click_first.visible:{sel}", loc.is_visible, timeout=timeout_ms):
                _pw_call(f"safe_click_first.click:{sel}", loc.click, timeout=timeout_ms)
                return True
        except Exception as e:
            if _is_target_closed_exc(e):
                raise _UiDeadError("_safe_click_first", repr(e)) from e
            continue
    return False

def _ensure_var_usd_mode(page) -> None:
    _pw_require_page(page, "_ensure_var_usd_mode")
    for _ in range(2):
        try:
            label = page.locator(VAR_TRADE["input_mode_label"]).first
            if _pw_call("ensure_var_usd_mode.label.count", label.count) > 0:
                txtv = (_pw_call("ensure_var_usd_mode.label.inner_text", label.inner_text, timeout=1500) or "").strip()
                if ("$" in txtv) or ("USD" in txtv.upper()):
                    return
            toggle = page.locator(VAR_TRADE["input_mode_toggle"]).first
            if _pw_call("ensure_var_usd_mode.toggle.count", toggle.count) > 0 and _pw_call("ensure_var_usd_mode.toggle.enabled", toggle.is_enabled):
                _pw_call("ensure_var_usd_mode.toggle.click", toggle.click, timeout=2000)
                _exec_wait_post_goto_fast(page, coin='', target='', timeout_s=max(0.18, min(0.45, float(_exec_submit_min_wait_sec() or 0.25))))
        except Exception as e:
            if _is_target_closed_exc(e):
                raise _UiDeadError("_ensure_var_usd_mode", repr(e)) from e
            time.sleep(0.22)
            continue

def _fill_input(locator, value: str, timeout_ms: int = 4000) -> None:
    _pw_call("fill_input.click", locator.click, timeout=timeout_ms)
    try:
        _pw_call("fill_input.clear", locator.fill, "", timeout=timeout_ms)
    except Exception as _e:
        if _is_target_closed_exc(_e):
            raise _UiDeadError("_fill_input.clear", repr(_e)) from _e
        _log_exc_level(mod="EXEC", stage="FILL_INPUT_CLEAR_FAIL", level="B", e=_e)

    _pw_call("fill_input.fill", locator.fill, value, timeout=timeout_ms)

def _round_usd10(x: float) -> int:
    if x is None:
        return 0
    try:
        x = float(x)
    except Exception:
        return 0
    if x <= 0:
        return 0
    try:
        v = int((x / 10.0) + 0.5) * 10  # half-up rounding to nearest 10
    except Exception:
        v = int(x // 10 * 10)
    if v <= 30:
        return 0
    return v

def _round_usd10_force_min(x: float) -> int:
    v = _round_usd10(x)
    if v == 0 and x is not None:
        try:
            if float(x) > 0:
                return 40
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    return v


def _order_should_keep_exact_reduce_usd(order: Any) -> bool:
    try:
        if not bool(getattr(order, 'reduce_only', False)):
            return False
    except Exception:
        return False
    try:
        mod = str(getattr(order, 'module', '') or '').upper().strip()
    except Exception:
        mod = ''
    try:
        act = str(getattr(order, 'action_type', '') or '').lower().strip()
    except Exception:
        act = ''
    try:
        note = str(getattr(order, 'guard_note', '') or '').lower().strip()
    except Exception:
        note = ''
    try:
        meta = getattr(order, 'meta', None)
        meta = dict(meta or {}) if isinstance(meta, dict) else {}
    except Exception:
        meta = {}
    try:
        if bool(meta.get('m10_step2_exact_reduce_only')):
            return True
    except Exception:
        pass
    try:
        if str(meta.get('m10_amount_rounding') or '').lower().strip() == 'floor10_no_raise':
            return True
    except Exception:
        pass
    try:
        if int(meta.get('m10_step_no') or 0) == 2 and (mod == 'M10' or note == 'tp_step2_loss_reduce'):
            return True
    except Exception:
        pass
    return bool(mod == 'M10' and act == 'close_partial_notional' and note == 'tp_step2_loss_reduce')


def _exec_resolve_submit_usd(order: Any) -> tuple[float, str]:
    try:
        usd_raw = float(getattr(order, 'usd', 0.0) or 0.0)
    except Exception:
        usd_raw = 0.0
    if usd_raw <= 0.0:
        return 0.0, 'bad_order_usd'
    rollback_cap = (getattr(order, 'meta', None) or {}).get('m10_rollback_max_u')
    if rollback_cap is not None:
        usd_final = float(int(min(usd_raw, float(rollback_cap)) // 10) * 10)
        return (usd_final, 'm10_rollback_verified_cap') if usd_final >= 40.0 else (0.0, 'm10_rollback_below_min_no_raise')
    if _order_should_keep_exact_reduce_usd(order):
        try:
            usd_final = float(int(float(usd_raw) // 10) * 10)
        except Exception:
            usd_final = 0.0
        if usd_final < 10.0:
            return 0.0, 'm10_step2_floor10_lt_10_wait'
        return float(usd_final), 'm10_step2_floor10_exact'
    return float(_round_usd10_force_min(usd_raw)), 'force_min40_or_round'


def _round_usd10_ceil(x: float) -> int:
    if x is None:
        return 0
    try:
        x = float(x)
    except Exception:
        return 0
    if x <= 0:
        return 0
    try:
        v = int(math.ceil(x / 10.0) * 10)
    except Exception:
        v = int((x + 9) // 10 * 10)
    if v <= 30:
        return 0
    return v

def _fmt_order_u10(v) -> str:
    """格式化下单金额：只输出整十位整数（如 10/20/140），不带小数。"""
    if v is None or v == "":
        return "-"
    try:
        return str(int(_round_usd10(float(v))))
    except Exception:
        try:
            return str(int(float(v)))
        except Exception:
            return str(v)

def _wait_trade_toast(page, *, timeout_ms: int = 3500) -> dict:
    """通用 toast/snackbar（提示条）检测：用于确认下单是否真正提交成功。

    返回：{'kind': 'success'|'error'|'none', 'text': str}
    说明：
    - 只做弱确认：宁可报 EXEC_FAIL（执行失败）也不要误报 EXEC_OK（已执行）
    - 改成“高频短轮询”：toast 一出现就立刻判，不再每轮硬等 1 秒多。
    """
    _pw_require_page(page, "wait_trade_toast")
    t0 = time.time()
    selectors = [
        'div[role="alert"]',
        'div[aria-live="assertive"]',
        'div[aria-live="polite"]',
        '.Toastify__toast',
        '.toast',
        '.snackbar',
        '.MuiAlert-message',
        '.MuiSnackbar-root',
    ]

    success_kw = ['success', 'successful', 'submitted', 'order placed', 'filled', 'complete', 'completed', 'ok', '成交', '成功', '已提交', '已下单', '委托成功']
    error_kw = ['error', 'failed', 'reject', 'rejected', 'insufficient', 'margin', 'minimum', 'min', 'reduce-only', 'reduce only', '风险', '错误', '失败', '拒绝', '不足', '最小', '低于', '保证金', '仅减仓']

    def _norm(s: str) -> str:
        return re.sub(r'\s+', ' ', (s or '')).strip().lower()

    try:
        poll_ms = int(max(60.0, float(_exec_cfg_float("EXEC_TOAST_POLL_MS", 120.0))))
    except Exception:
        poll_ms = 120

    while (time.time() - t0) * 1000.0 < float(timeout_ms or 0):
        for sel in selectors:
            try:
                loc = page.locator(sel).last
                if _pw_locator_count(loc, f"wait_trade_toast[{sel}]") <= 0:
                    continue
                if not _pw_locator_visible(loc, f"wait_trade_toast[{sel}]", timeout=80):
                    continue
                txt = (_pw_call(f"wait_trade_toast[{sel}].inner_text", loc.inner_text, timeout=160) or '').strip()
                nt = _norm(txt)
                if not nt:
                    continue
                if any(k in nt for k in success_kw):
                    return {'kind': 'success', 'text': txt}
                if any(k in nt for k in error_kw):
                    return {'kind': 'error', 'text': txt}
            except _UiDeadError:
                raise
            except Exception as _e:
                _log_exc_level(mod="EXEC", stage="WAIT_TRADE_TOAST_SCAN_FAIL", level="C", e=_e)
                continue
        _pw_wait_ms(page, poll_ms, "wait_trade_toast.sleep")

    return {'kind': 'none', 'text': ''}

def executor_place_order(page, platform: str, coin: str, side: str, notional_u: float, log_path: str, *, timeout_ms: int = 20000) -> dict:
    """新执行器（可直接用）：按你给的新元素做下单/平单（仅执行，不读 UI 做决策）
    - platform: "EXT" / "VAR"
    - side: "LONG" / "SHORT"
    - notional_u: 以 U(USDT) 名义金额下单（在 VAR 通过 $ 模式；EXT 通过 Notional 输入框）
    返回：{"ok": bool, "reason": str, "exec_notional_u": float, "t_sec": float}
    """
    t0 = time.time()

    try:
        side = (side or "").upper()
        platform = (platform or "").upper()
        if side not in ("LONG", "SHORT"):
            return {"ok": False, "reason": f"bad_side={side}", "exec_notional_u": 0.0, "t_sec": time.time() - t0}
        if notional_u <= 0:
            return {"ok": False, "reason": f"bad_notional_u={notional_u}", "exec_notional_u": 0.0, "t_sec": time.time() - t0}

        try:
            _ui_to = float(cfg_getf_runtime("UI_MUTEX_TIMEOUT_SEC", 2.0) or 2.0)
        except Exception:
            _ui_to = 2.0
        _ui_to = max(0.1, min(float(_ui_to), 5.0))
        if not _ui_mutex_try_acquire(mod="EXEC", coin=str(coin), plat=str(platform), timeout_sec=float(_ui_to)):
            return {"ok": False, "reason": f"ui_mutex_busy:{_ui_to:.2f}s", "exec_notional_u": 0.0, "t_sec": time.time() - t0}
        try:
            if platform == "VAR":
                _pw_goto(page, var_market_url(coin), f"legacy.exec.goto.var:{coin}", timeout=timeout_ms)
                _jitter_sleep(0.8, 1.6)

                buy_btn = page.locator(VAR_TRADE["btn_buy_toggle"]).first
                sell_btn = page.locator(VAR_TRADE["btn_sell_toggle"]).first
                want_buy = (side == "LONG")

                def _is_disabled(locator) -> bool:
                    try:
                        return bool(_pw_call("legacy.exec.var.loc.disabled_eval", locator.evaluate, "el => !!el.disabled"))
                    except Exception:
                        try:
                            return _pw_locator_attr(locator, "disabled", "legacy.exec.var.loc.disabled_attr") is not None
                        except Exception:
                            return False

                if want_buy:
                    if _pw_locator_count(buy_btn, "legacy.exec.var.buy_btn") > 0 and (not _is_disabled(buy_btn)):
                        _pw_call("legacy.exec.var.buy_btn.click", buy_btn.click, timeout=3000)
                    elif _pw_locator_count(sell_btn, "legacy.exec.var.sell_btn") > 0 and (not _is_disabled(sell_btn)):
                        try:
                            _pw_call("legacy.exec.var.buy_btn.click", buy_btn.click, timeout=3000)
                        except Exception as _e:
                            _log_exc_level(mod="EXEC", stage="LEGACY_VAR_BUY_CLICK_RETRY", level="B", e=_e)

                else:
                    if _pw_locator_count(sell_btn, "legacy.exec.var.sell_btn") > 0 and (not _is_disabled(sell_btn)):
                        _pw_call("legacy.exec.var.sell_btn.click", sell_btn.click, timeout=3000)
                    elif _pw_locator_count(buy_btn, "legacy.exec.var.buy_btn") > 0 and (not _is_disabled(buy_btn)):
                        try:
                            _pw_call("legacy.exec.var.sell_btn.click", sell_btn.click, timeout=3000)
                        except Exception as _e:
                            _log_exc_level(mod="EXEC", stage="LEGACY_VAR_SELL_CLICK_RETRY", level="B", e=_e)

                _jitter_sleep(0.3, 0.8)

                mode_btn = page.locator(VAR_TRADE["input_mode_toggle"]).first
                mode_label = page.locator(VAR_TRADE["input_mode_label"]).first
                for _ in range(3):
                    try:
                        txt = (_pw_call("legacy.exec.var.mode_label.text", mode_label.inner_text, timeout=1500) or "").strip()
                    except Exception:
                        txt = ""
                    if "$" in txt:
                        break
                    if _pw_locator_count(mode_btn, "legacy.exec.var.mode_btn") > 0 and (not _is_disabled(mode_btn)):
                        _pw_call("legacy.exec.var.mode_btn.click", mode_btn.click, timeout=1500)
                        _jitter_sleep(0.2, 0.6)

                qty_inp = page.locator(VAR_TRADE["order_qty_input"]).first
                _active_req_touch("EXEC_UI_WAIT", reason="legacy.exec.var.qty.wait_visible")
                _pw_call("legacy.exec.var.qty.wait_visible", qty_inp.wait_for, state="visible", timeout=timeout_ms)
                _pw_call("legacy.exec.var.qty.click", qty_inp.click, timeout=2000)
                _pw_call("legacy.exec.var.qty.clear", qty_inp.fill, "")
                _pw_call("legacy.exec.var.qty.type", qty_inp.type, f"{float(notional_u):.2f}", delay=20)
                _jitter_sleep(0.2, 0.6)

                submit = page.locator(VAR_TRADE["submit_button"]).first
                _active_req_touch("EXEC_UI_WAIT", reason="legacy.exec.var.submit.wait_visible")
                _pw_call("legacy.exec.var.submit.wait_visible", submit.wait_for, state="visible", timeout=timeout_ms)

                try:
                    _pw_call("legacy.exec.var.submit.wait_enabled", page.wait_for_function,
                        "sel => { const b=document.querySelector(sel); return b && !b.disabled; }",
                        arg='button[data-testid="submit-button"]',
                        timeout=timeout_ms
                    )
                except Exception:
                    try:
                        _pw_call("legacy.exec.var.qty.reclick", qty_inp.click, timeout=2500)
                    except Exception as _e:
                        _log_exc_level(mod="EXEC", stage="LEGACY_VAR_QTY_RECLICK", level="B", e=_e)

                if _is_disabled(submit):
                    return {"ok": False, "reason": "submit_button_disabled_after_fill", "exec_notional_u": 0.0, "t_sec": time.time() - t0}

                try:
                    sb_txt = (_pw_call("legacy.exec.var.submit.text", submit.inner_text) or "").strip()
                except Exception:
                    sb_txt = ""
                try:
                    if side_lower == "buy":
                        if sb_txt and (not re.match(r"^\s*Buy\b", sb_txt, re.I)):
                            return {"ok": False, "reason": f"submit_text_not_buy:{sb_txt[:60]}", "exec_notional_u": 0.0, "t_sec": time.time() - t0}
                    else:
                        if sb_txt and (not re.match(r"^\s*Sell\b", sb_txt, re.I)):
                            return {"ok": False, "reason": f"submit_text_not_sell:{sb_txt[:60]}", "exec_notional_u": 0.0, "t_sec": time.time() - t0}
                except Exception:
                    pass

                _active_req_touch("EXEC_UI_WAIT", reason="legacy.exec.var.submit.click")
                _pw_call("legacy.exec.var.submit.click", submit.click, timeout=timeout_ms)
                _jitter_sleep(0.6, 1.2)

                try:
                    toast = _wait_trade_toast(page, timeout_ms=min(3500, timeout_ms))
                except Exception:
                    toast = {'kind': 'none', 'text': ''}

                if toast.get('kind') == 'error':
                    return {"ok": False, "reason": f"toast_error:{toast.get('text','')[:120]}", "exec_notional_u": 0.0, "t_sec": time.time() - t0}
                if toast.get('kind') == 'success':
                    return {"ok": True, "reason": f"ok:{toast.get('text','')[:120]}", "exec_notional_u": float(notional_u), "t_sec": time.time() - t0}

                return {"ok": False, "reason": "unconfirmed_submit_no_toast", "exec_notional_u": 0.0, "t_sec": time.time() - t0}

            elif platform == "EXT":
                _pw_goto(page, ext_market_url(coin), f"legacy.exec.goto.ext:{coin}", timeout=timeout_ms)
                _jitter_sleep(0.8, 1.6)

                inp = page.locator(EXT_TRADE["order_value_input"]).first
                _pw_call("legacy.exec.ext.inp.wait_visible", inp.wait_for, state="visible", timeout=timeout_ms)
                _pw_call("legacy.exec.ext.inp.click", inp.click, timeout=2000)
                _pw_call("legacy.exec.ext.inp.clear", inp.fill, "")
                _pw_call("legacy.exec.ext.inp.type", inp.type, f"{float(notional_u):.2f}", delay=20)
                _jitter_sleep(0.2, 0.6)

                btn_sel = EXT_TRADE["btn_buy"] if side == "LONG" else EXT_TRADE["btn_sell"]
                btn = page.locator(btn_sel).first
                _pw_call("legacy.exec.ext.btn.wait_visible", btn.wait_for, state="visible", timeout=timeout_ms)

                for _ in range(4):
                    try:
                        if not bool(_pw_call("legacy.exec.ext.btn.disabled_eval", btn.evaluate, "el => !!el.disabled")):
                            break
                    except Exception:
                        break
                    _jitter_sleep(0.3, 0.9)

                try:
                    _pw_call("legacy.exec.ext.btn.click", btn.click, timeout=timeout_ms)
                except Exception as e:
                    return {"ok": False, "reason": f"click_buy_sell_fail:{type(e).__name__}:{e}", "exec_notional_u": 0.0, "t_sec": time.time() - t0}

                _jitter_sleep(0.4, 1.0)
                _safe_click_first(page, EXT_TRADE["confirm_selectors"], timeout_ms=2500)

                try:
                    toast = _wait_trade_toast(page, timeout_ms=min(3500, timeout_ms))
                except Exception:
                    toast = {'kind': 'none', 'text': ''}

                if toast.get('kind') == 'error':
                    return {"ok": False, "reason": f"toast_error:{toast.get('text','')[:120]}", "exec_notional_u": 0.0, "t_sec": time.time() - t0}
                if toast.get('kind') == 'success':
                    return {"ok": True, "reason": f"ok:{toast.get('text','')[:120]}", "exec_notional_u": float(notional_u), "t_sec": time.time() - t0}

                return {"ok": False, "reason": "unconfirmed_submit_no_toast", "exec_notional_u": 0.0, "t_sec": time.time() - t0}

            else:
                return {"ok": False, "reason": f"bad_platform={platform}", "exec_notional_u": 0.0, "t_sec": time.time() - t0}

        finally:
            _ui_mutex_release()
    except Exception as e:
        return {"ok": False, "reason": f"exception:{type(e).__name__}:{e}", "exec_notional_u": 0.0, "t_sec": time.time() - t0}

def _exec_ts() -> str:
    return datetime.now().strftime("%Y-%m-%d %H:%M:%S")

def _exec_log(msg: str, **kw) -> None:
    """执行器统一日志。

    兼容老调用：_exec_log("xxx")
    兼容新调用：_exec_log("xxx", coin=..., platform=..., action=..., side=..., usd=..., extra=...)
    目的：避免 TypeError 导致执行器整单失败（你日志里看到的 _exec_log() got an unexpected keyword argument 'coin'）。
    """
    try:
        tail = []
        for k in ("coin", "platform", "action", "side", "usd", "amount_usd", "reason", "code"):
            if k in kw and kw.get(k) not in (None, "", "-"):
                _v = kw.get(k)
                if k in ("reason", "code"):
                    _v = _reason_with_zh(_v)
                tail.append(f"{k}={_v}")
        rest = {k: v for k, v in (kw or {}).items() if k not in ("coin","platform","action","side","usd","amount_usd","reason","code")}
        if rest:
            tail.append(f"meta={rest}")
        suffix = (" | " + " ".join(tail)) if tail else ""
        line = f"[{_exec_ts()}] [EXECUTOR（执行器）] {msg}{suffix}"
        cprint(line)
    except Exception:
        try:
            print(f"[{_exec_ts()}] [EXECUTOR] {msg} {kw}", flush=True)
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    return

def _exec_cfg_float(name: str, default: float) -> float:
    try:
        if 'cfg_getf_runtime' in globals():
            v = cfg_getf_runtime(str(name), float(default))
        else:
            v = os.getenv(str(name), default)
        v = float(v)
        if not math.isfinite(v):
            return float(default)
        return float(v)
    except Exception:
        return float(default)

def _exec_sleep_floor_sec() -> float:
    try:
        return max(0.08, float(_exec_cfg_float("EXEC_STEP_SLEEP_MIN_SEC", 0.12)))
    except Exception:
        return 0.12

def _exec_submit_poll_sec() -> float:
    try:
        return max(_exec_sleep_floor_sec(), float(_exec_cfg_float("EXEC_SUBMIT_POLL_SEC", 0.16)))
    except Exception:
        return max(0.16, _exec_sleep_floor_sec())

def _exec_submit_min_wait_sec() -> float:
    try:
        return max(0.0, float(_exec_cfg_float("EXEC_SUBMIT_MIN_WAIT_SEC", 0.00)))
    except Exception:
        return 0.0

_EXEC_STEP_SLEEP_SILENT_PREFIXES = (
    "SUBMIT_WAIT:",
    "SUBMIT_RECHECK:",
)

def _exec_should_log_step_sleep(reason: str) -> bool:
    """控制 StepSleep 日志噪音。

    人话：
    - SUBMIT_WAIT / SUBMIT_RECHECK 属于“提交后轮询等待”，0.3s 一次很容易刷屏；
    - 默认直接静默，不影响真实 sleep 与提交流程；
    - 若你以后想恢复，环境变量 EXEC_LOG_SUBMIT_WAIT=1 即可。
    """
    try:
        rs = str(reason or "")
    except Exception:
        rs = ""
    try:
        force_log_submit_wait = bool(int(float(os.getenv("EXEC_LOG_SUBMIT_WAIT", "0") or 0)))
    except Exception:
        force_log_submit_wait = False
    if force_log_submit_wait:
        return True
    return not any(rs.startswith(pfx) for pfx in _EXEC_STEP_SLEEP_SILENT_PREFIXES)

def _exec_step_sleep(*args) -> None:
    """
    执行器步骤等待（兼容历史调用，避免 TypeError）。

    支持三种常见调用形态：
      1) _exec_step_sleep(dur) 或 _exec_step_sleep(dur, reason)
      2) _exec_step_sleep(reason, lo, hi)  # 在 [lo,hi] 秒随机抖动
      3) _exec_step_sleep(reason)         # 默认轻抖动

    说明：你日志里报的
      TypeError('_exec_step_sleep() takes from 1 to 2 positional arguments but 3 were given')
    就是因为旧调用仍在传 (reason, lo, hi)，而函数被改成 (dur, reason)。
    """
    dur = 0.0
    reason = ""

    try:
        if len(args) == 0:
            dur = 0.0
            reason = ""
        elif len(args) == 1:
            a0 = args[0]
            if isinstance(a0, (int, float)):
                dur = float(a0)
            else:
                reason = str(a0)
                dur = random.uniform(_exec_sleep_floor_sec(), max(_exec_sleep_floor_sec(), float(_exec_cfg_float("EXEC_STEP_SLEEP_DEFAULT_SEC", 0.35))))
        elif len(args) == 2:
            a0, a1 = args[0], args[1]
            if isinstance(a0, (int, float)) and not isinstance(a1, (int, float)):
                dur = float(a0)
                reason = str(a1)
            elif not isinstance(a0, (int, float)) and isinstance(a1, (int, float)):
                reason = str(a0)
                dur = float(a1)
            else:
                try:
                    dur = float(a1)
                except Exception:
                    dur = 0.0
                try:
                    reason = str(a0)
                except Exception:
                    reason = ""
        else:
            a0, a1, a2 = args[0], args[1], args[2]
            if not isinstance(a0, (int, float)):
                reason = str(a0)
            else:
                reason = ""
            try:
                lo = float(a1)
            except Exception:
                lo = 0.0
            try:
                hi = float(a2)
            except Exception:
                hi = lo
            if hi < lo:
                lo, hi = hi, lo
            lo = max(0.0, lo)
            hi = max(0.0, hi)
            dur = random.uniform(lo, hi) if hi > lo else lo

    except Exception:
        dur = 0.0
        reason = ""

    try:
        d = float(dur or 0.0)
    except Exception:
        d = 0.0

    try:
        if _exec_should_log_step_sleep(reason):
            if reason:
                safe_log(lambda: f"[{_exec_ts()}] [EXECUTOR（执行器）] StepSleep（步骤等待）: {reason} | sleep={d:.1f}s")
            else:
                safe_log(lambda: f"[{_exec_ts()}] [EXECUTOR（执行器）] StepSleep（步骤等待）: sleep={d:.1f}s")
    except Exception as _e:
        _log_exc_level(mod="EXEC", stage="EXEC_STEP_SLEEP_LOG_FAIL", level="C", e=_e)

    try:
        d = float(d)
    except Exception:
        d = 0.0
    _floor = _exec_sleep_floor_sec()
    if d <= 0.0:
        d = max(_floor, float(_exec_cfg_float("EXEC_STEP_SLEEP_DEFAULT_SEC", 0.35)))
    if d < _floor:
        d = _floor
    try:
        _ORIG_TIME_SLEEP(d)
    except Exception as _e:
        _log_exc_level(mod="EXEC", stage="EXEC_STEP_SLEEP_FAIL", level="C", e=_e)

    def _exec_find_toast_text(page) -> str:
        try:
            locs = [
                page.locator('[data-sonner-toast]').last,
                page.locator('[role="status"]').last,
                page.locator('[role="alert"]').last,
                page.locator('[aria-live="polite"]').last,
                page.locator('[aria-live="assertive"]').last,
                page.locator('div.toast').last,
                page.locator('div:has-text("Success")').last,
            ]
            for loc in locs:
                try:
                    if loc is None:
                        continue
                    if _pw_locator_count(loc, "exec.find_toast.loc") <= 0:
                        continue
                    t = (_pw_call("exec.find_toast.text", loc.inner_text, timeout=400) or "").strip()
                    if t:
                        return t
                except Exception:
                    continue
        except Exception:
            return ""
        return ""

    def _exec_toast_judge(text: str) -> tuple[str, str]:
        """返回 (status, reason) 其中 status in {'ok','fail',''}"""
        try:
            t = (text or "").strip()
            if not t:
                return "", ""
            tl = t.lower()
            ok_kw = ["success", "submitted", "filled", "order placed", "completed", "成交", "成功", "提交", "已下单", "已成交", "已完成"]
            bad_kw = ["insufficient", "rejected", "error", "failed", "cancel", "canceled", "margin", "risk", "min", "too small", "not allowed",
                      "不足", "失败", "拒绝", "错误", "取消", "保证金", "风险", "最小", "过小", "不允许", "超限"]
            if any(k in tl for k in ok_kw):
                return "ok", t
            if any(k in tl for k in bad_kw):
                return "fail", t
            return "", t
        except Exception:
            return "", ""

    def _exec_wait_until(label: str, cond_fn, timeout_s: float, poll_s: float = 1.05) -> bool:
        """条件等待：满足 cond_fn 立即早退；最短每次 sleep >=1.05s。"""
        try:
            t0 = time.time()
        except Exception:
            t0 = 0.0
        _poll_default = _exec_submit_poll_sec()
        poll = max(_exec_sleep_floor_sec(), float(poll_s or _poll_default))
        tout = max(poll, float(timeout_s or 0.0))
        last_log_ts = 0.0
        while True:
            try:
                if bool(cond_fn()):
                    return True
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

            try:
                now = time.time()
            except Exception:
                now = 0.0
            if now - t0 >= tout:
                return False
            if now - last_log_ts >= 3.0:
                last_log_ts = now
                try:
                    safe_log(lambda: f"[{_exec_ts()}] [EXECUTOR（执行器）] Wait（条件等待）: {label} | elapse={now-t0:.1f}s/{tout:.1f}s")
                except Exception as _e:
                    _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

            _exec_step_sleep(poll, f"COND_WAIT:{label}")

    def _exec_wait_btn_enabled_legacy(btn, label: str, timeout_s: float = 12.0, timeout_ms: int | None = None, **kwargs) -> bool:
        try:
            if timeout_ms is not None and timeout_s is not None:
                timeout_s = float(timeout_ms) / 1000.0
            elif timeout_ms is not None:
                timeout_s = float(timeout_ms) / 1000.0
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

        def _is_disabled_any(b) -> bool:
            try:
                if _pw_locator_attr(b, "disabled", "var.submit_btn") is not None:
                    return True
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

            try:
                aria = (str(_pw_locator_attr(b, "aria-disabled", "var.submit_btn") or "")).strip().lower()
                if aria in ("true","1"):
                    return True
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

            try:
                ds = (b.get_attribute("data-disabled") or "").strip().lower()
                if ds in ("true","1","disabled"):
                    return True
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

            return False
        try:
            return _exec_wait_until(label, lambda: (btn is not None) and (btn.count() > 0) and (not _is_disabled_any(btn)), timeout_s, _exec_submit_poll_sec())
        except Exception:
            return False

    def _exec_wait_submit_result_legacy(page, *, timeout_s: float = 12.0, coin: str = "", label: str = "") -> tuple[str, dict]:
        """多信号确认：返回 (status, detail) 其中 status in {'ok','fail','unknown'}"""
        det = {"coin": coin or "", "label": label or "", "toast": "", "judge": "", "elapsed_s": 0.0}
        try:
            _pin("EXEC_STEP", mod="EXEC", step="UI_RECEIPT_WAIT_BEGIN", coin=str(coin or "").upper(), label=str(label or "")[:64])
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)
        t0 = time.time()
        _exec_step_sleep(_exec_submit_min_wait_sec(), f"SUBMIT_MIN_WAIT:{label}")
        while True:
            try:
                _exec_try_confirm_dialog(page, 1200)
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

            try:
                tt = _exec_find_toast_text(page)
            except Exception:
                tt = ""
            if tt:
                det["toast"] = tt
            st, why = _exec_toast_judge(tt)
            if st in ("ok","fail"):
                det["judge"] = why
                try:
                    det["elapsed_s"] = float(time.time() - t0)
                except Exception:
                    det["elapsed_s"] = 0.0
                return ("ok" if st=="ok" else "fail"), det

            try:
                sp = page.locator('svg[aria-label*="loading" i], [data-testid*="loading" i], div:has-text("Submitting"), div:has-text("提交中")').first
                has_spin = (sp.count() > 0)
            except Exception:
                has_spin = False

            if time.time() - t0 >= float(timeout_s or 0.0):
                try:
                    det["elapsed_s"] = float(time.time() - t0)
                except Exception:
                    det["elapsed_s"] = 0.0
                try:
                    _pin("EXEC_STEP", mod="EXEC", step="UI_RECEIPT_WAIT_END", coin=str(coin or "").upper(), label=str(label or "")[:64], status="unknown", judge=str(det.get("judge",""))[:64])
                except Exception as _e:
                    _log_exc(mod="SYS", stage="EXC_PASS", e=_e)
                return _submit_wait_finish("unknown", det)
            _exec_step_sleep(_exec_submit_poll_sec() if has_spin else max(_exec_submit_poll_sec(), float(_exec_cfg_float("EXEC_SUBMIT_IDLE_WAIT_SEC", 0.35))), f"SUBMIT_WAIT:{label}")

def _exec_wait_submit_result(page, *, timeout_s: float = 12.0, coin: str = "", label: str = "", platform_obj=None, kind: str = "", side_u: str = "", usd: float = 0.0, pre_row: Any = None, pre_portfolio: dict | None = None, allow_confirm_retry: bool = True, confirm_retry_budget: int = 1) -> tuple[str, dict]:
    """等待下单/平仓提交结果。

    返回 (status, detail):
      - status: 'ok' | 'fail' | 'unknown'
      - detail: {'coin','label','toast','judge','elapsed_s', ...}

    核心口径：
    - 不再先傻等一个最小周期；
    - 改成“马上探测 + 高频短轮询”；
    - toast / dialog / loading / 持仓变化 任一状态变化都立刻推进下一步；
    - perf 日志仅做观测，不允许反噬交易主链。
    """
    _coin_u = str(coin or "").upper().strip()
    _label_s = str(label or "")[:180]
    _pending_plat = _exec_batch_platform_name(platform_obj)
    _pending_side = str(side_u or ((pre_row or {}).get('side') if isinstance(pre_row, dict) else '') or '')
    _safety_reserve_submission(_pending_plat, _coin_u, _pending_side, kind or 'open', pre_row, usd, allow_existing=True)
    allow_confirm_retry = False
    confirm_retry_budget = 0
    try:
        _exec_active_stage_touch("EXEC_WAIT_SUBMIT_RESULT_BEGIN", _label_s, coin=_coin_u, kind=str(kind or "")[:64])
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_1176', _e)
        pass
    try:
        _pin("EXEC_STEP", mod="EXEC", step="WAIT_SUBMIT_RESULT_BEGIN", coin=_coin_u or "*", label=str(label or "")[:64], kind=str(kind or "")[:32])
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    def _submit_wait_finish(_status: str, _det: dict) -> tuple[str, dict]:
        _step = "EXEC_WAIT_SUBMIT_RESULT_END"
        if str(_status or "") == "ok":
            _step = "EXEC_WAIT_SUBMIT_RESULT_OK"
        elif str(_status or "") == "fail":
            _step = "EXEC_WAIT_SUBMIT_RESULT_FAIL"
        try:
            _exec_active_stage_touch(_step, _label_s, coin=_coin_u, status=str(_status or "")[:32], judge=str((_det or {}).get("judge") or "")[:96], source=str((_det or {}).get("source") or "")[:96], verify_kind=str((_det or {}).get("verify_kind") or "")[:96])
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_1177', _e)
            pass
        try:
            _pin("EXEC_STEP", mod="EXEC", step=_step, coin=_coin_u or "*", label=str(label or "")[:64], status=str(_status or "")[:32], judge=str((_det or {}).get("judge") or "")[:64], source=str((_det or {}).get("source") or "")[:64], verify_kind=str((_det or {}).get("verify_kind") or "")[:64])
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)
        return _status, _det

    det = {
        "coin": coin or "",
        "label": label or "",
        "toast": "",
        "judge": "",
        "elapsed_s": 0.0,
        "verify_kind": "",
        "source": "",
    }
    _perf_t0 = _exec_perf_now()
    _perf_dialog_click_ms = None
    _perf_first_toast_ms = None
    _perf_first_verify_ms = None
    _perf_loading_seen = False
    last_verify_ev = {}
    try:
        _plat_name = (getattr(platform_obj, "name", "") or getattr(platform_obj, "__name__", "") or "") if platform_obj is not None else ""
    except Exception:
        _plat_name = ""
    try:
        t0 = time.time()
    except Exception:
        t0 = 0.0

    try:
        min_wait = float(_exec_submit_min_wait_sec())
    except Exception:
        min_wait = 0.0
    if min_wait > 0:
        try:
            _exec_step_sleep(min_wait, f"SUBMIT_MIN_WAIT:{label}")
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_1178', _e)
            pass
    toast_selectors = [
        ".Toastify__toast-body",
        ".Toastify__toast",
        "div[role='status']",
        "div[role='alert']",
        "div[class*='toast']",
        "div[class*='Toast']",
        "div[class*='notification']",
        "div[class*='Notification']",
    ]

    ok_keys = ("success", "succeed", "submitted", "done", "filled", "已提交", "提交成功", "成功", "委托成功", "订单已提交", "已创建")
    fail_keys = ("fail", "failed", "error", "rejected", "insufficient", "保证金", "余额不足", "最小", "min", "invalid", "禁止", "风控", "risk", "超出", "too low", "too small")

    def _read_toast_text() -> str:
        texts = []
        for sel in toast_selectors:
            try:
                loc = page.locator(sel)
                cnt = int(loc.count())
                if cnt <= 0:
                    continue
                for i in range(max(0, cnt - min(3, cnt)), cnt):
                    try:
                        item = loc.nth(i)
                        if hasattr(item, "is_visible") and (not bool(item.is_visible(timeout=80))):
                            continue
                    except Exception:
                        item = loc.nth(i)
                    try:
                        t = (item.inner_text() or "").strip()
                    except Exception:
                        try:
                            t = (item.text_content() or "").strip()
                        except Exception:
                            t = ""
                    if t:
                        texts.append(t)
            except Exception:
                continue
        out = " | ".join([t for i, t in enumerate(texts) if t and t not in texts[:i]])
        return out.strip()

    def _judge_text(t: str) -> str:
        low = (t or "").strip().lower()
        if not low:
            return ""
        for k in ok_keys:
            if k in low:
                return "ok"
        for k in fail_keys:
            if k in low:
                return "fail"
        return ""

    def _has_loading() -> bool:
        sels = [
            'svg[aria-label*="loading" i]',
            '[data-testid*="loading" i]',
            'div:has-text("Submitting")',
            'div:has-text("提交中")',
            '[aria-busy="true"]',
        ]
        for sel in sels:
            try:
                loc = page.locator(sel).first
                if _pw_locator_count(loc, f"exec.wait_submit.loading[{sel}]") <= 0:
                    continue
                if _pw_locator_visible(loc, f"exec.wait_submit.loading_visible[{sel}]", timeout=60):
                    return True
            except Exception:
                continue
        return False

    verify_enabled = bool(platform_obj is not None and str(coin or "").strip() and str(kind or "").strip() and str(side_u or "").strip() and pre_row is not None)
    _confirm_state = _exec_confirm_state_enter(platform=_plat_name, coin=coin, label=label, ttl_s=max(float(timeout_s or 0.0) + 3.0, 5.0))
    _deadline_ts = float(t0 or 0.0) + max(0.1, float(timeout_s or 0.0))
    _confirm_retry_used = 0
    _verify_round_idx = 0

    def _remaining_budget_s(_now: float | None = None) -> float:
        try:
            _n = float(_now if _now is not None else time.time())
        except Exception:
            _n = 0.0
        try:
            return float(_deadline_ts) - float(_n)
        except Exception:
            return 0.0

    def _try_verify_now(_elapsed_s: float = 0.0, _round_idx: int = 1, _remaining_s: float | None = None) -> tuple[bool, dict]:
        if _exec_batch_should_defer_verify():
            return False, {"kind": str(kind or ""), "reason": "batch_verify_deferred"}
        if not verify_enabled:
            return False, {"kind": str(kind or ""), "reason": "verify_disabled"}
        try:
            _remain = float(_remaining_s if _remaining_s is not None else _remaining_budget_s())
        except Exception:
            _remain = 0.0
        if _remain <= 0.10:
            return False, {"kind": str(kind or ""), "reason": "verify_budget_exhausted", "remaining_s": float(max(0.0, _remain))}
        _coin_page_snap = {"available": False, "confirm_source": "coin_page_position"}
        try:
            _coin_page_snap = _exec_read_coin_page_position_snapshot(page, platform_obj, coin=coin)
        except Exception as _e:
            _coin_page_snap = {"available": False, "confirm_source": "coin_page_position", "error": repr(_e)}
        _coin_page_available = bool(isinstance(_coin_page_snap, dict) and _coin_page_snap.get('available'))
        post_row = (_coin_page_snap.get('row') if _coin_page_available else None)
        if (not _coin_page_available) and bool(_coin_page_snap.get('error')):
            return False, {"kind": str(kind or ""), "reason": f"coin_page_snapshot_exc:{str(_coin_page_snap.get('error') or '')}"}
        if not _coin_page_available:
            try:
                post_row = _exec_read_position_truth(page, platform_obj, coin)
            except Exception as _e:
                return False, {"kind": str(kind or ""), "reason": f"read_post_row_exc:{repr(_e)}"}
        kind_l = str(kind or "").lower().strip()
        row_first_reduce = kind_l in ('close', 'close_all', 'decrease', 'reduce', 'tp', 'trend_tp', 'partial_close', 'koujing_a_3step', 'close_partial_notional')
        hard_budget_row_only = bool(_remain <= 0.85)
        _skip_pf = bool(row_first_reduce or hard_budget_row_only or _exec_should_skip_portfolio_verify(kind, elapsed_s=float(_elapsed_s or 0.0), round_idx=int(_round_idx or 0)))
        if _skip_pf:
            try:
                ok2, ev2 = _exec_verify_submit_fast_row_only(coin=coin, kind=kind, side_u=side_u, usd=float(usd or 0.0), pre_row=pre_row, post_row=post_row)
            except Exception as _e:
                return False, {"kind": str(kind or ""), "reason": f"verify_row_fast_exc:{repr(_e)}"}
            if not isinstance(ev2, dict):
                ev2 = {"kind": str(kind or ""), "reason": "verify_ev_not_dict"}
            try:
                ev2.setdefault("post_side", _exec_row_side_notional(post_row)[0])
                ev2.setdefault("post_notional", float(_exec_row_side_notional(post_row)[1] or 0.0))
                ev2.setdefault("portfolio_skipped_fast", 1)
                ev2.setdefault("verify_path", "row_only_fast")
                ev2.setdefault("remaining_s", float(max(0.0, _remain)))
                ev2.setdefault("row_source", str((_coin_page_snap or {}).get('confirm_source') or ('coin_page_position' if _coin_page_available else 'positions_list')))
                ev2.setdefault("coin_page_available", int(bool(_coin_page_available)))
                ev2.setdefault("coin_page_row_found", int(bool((_coin_page_snap or {}).get('row_found'))))
                if _coin_page_available:
                    ev2.setdefault("detected_coin", str((_coin_page_snap or {}).get('detected_coin') or ''))
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_1179', _e)
                pass
            return bool(ok2), ev2
        post_portfolio = None
        if _remain <= 0.45:
            post_portfolio = {"available": False, "skipped_budget": True}
            _skip_pf = True
        else:
            try:
                post_portfolio = _exec_read_portfolio_snapshot(page, platform_obj, focus_coins=[coin])
            except Exception:
                post_portfolio = {"available": False}
        try:
            ok2, ev2 = _exec_verify_submit_dual_evidence(coin=coin, kind=kind, side_u=side_u, usd=float(usd or 0.0), pre_row=pre_row, post_row=post_row, pre_portfolio=pre_portfolio, post_portfolio=post_portfolio, skip_portfolio=_skip_pf)
        except Exception as _e:
            return False, {"kind": str(kind or ""), "reason": f"verify_exc:{repr(_e)}"}
        if not isinstance(ev2, dict):
            ev2 = {"kind": str(kind or ""), "reason": "verify_ev_not_dict"}
        try:
            ev2.setdefault("post_side", _exec_row_side_notional(post_row)[0])
            ev2.setdefault("post_notional", float(_exec_row_side_notional(post_row)[1] or 0.0))
            ev2.setdefault("portfolio_skipped_fast", int(bool(_skip_pf)))
            ev2.setdefault("verify_path", "dual_evidence")
            ev2.setdefault("remaining_s", float(max(0.0, _remain)))
            ev2.setdefault("row_source", str((_coin_page_snap or {}).get('confirm_source') or ('coin_page_position' if _coin_page_available else 'positions_list')))
            ev2.setdefault("coin_page_available", int(bool(_coin_page_available)))
            ev2.setdefault("coin_page_row_found", int(bool((_coin_page_snap or {}).get('row_found'))))
            if _coin_page_available:
                ev2.setdefault("detected_coin", str((_coin_page_snap or {}).get('detected_coin') or ''))
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_1180', _e)
            pass
        return bool(ok2), ev2

    try:
        fast_poll = max(0.06, float(_exec_cfg_float("EXEC_SUBMIT_FAST_POLL_SEC", 0.08)))
    except Exception:
        fast_poll = 0.08
    try:
        slow_poll = max(fast_poll, float(_exec_submit_poll_sec()))
    except Exception:
        slow_poll = max(fast_poll, 0.16)
    try:
        idle_poll = max(fast_poll, float(_exec_cfg_float("EXEC_SUBMIT_IDLE_WAIT_SEC", 0.20)))
    except Exception:
        idle_poll = max(fast_poll, 0.20)

    while True:
        try:
            now = time.time()
        except Exception:
            now = 0.0
        det["elapsed_s"] = float(max(0.0, now - t0))
        _remaining_s = _remaining_budget_s(now)
        if _remaining_s <= 0.0:
            det["judge"] = "timeout"
            det["source"] = det.get("source") or "timeout"
            det["verify_kind"] = str((last_verify_ev or {}).get("kind") or det.get("verify_kind") or "")
            _exec_perf_log_safe("submit_wait_done", plat=_plat_name, coin=coin, label=label, result="unknown", total_ms=_exec_perf_ms(_perf_t0), dialog_ms=_perf_dialog_click_ms, toast_ms=_perf_first_toast_ms, verify_ms=_perf_first_verify_ms, loading_seen=int(bool(_perf_loading_seen)), judge=det.get("judge",""), source=det.get("source",""), verify_kind=det.get("verify_kind",""))
            _exec_confirm_state_exit(_confirm_state, result="unknown")
            return _submit_wait_finish("unknown", det)

        dialog_clicked = False
        try:
            if bool(allow_confirm_retry) and int(_confirm_retry_used) < max(0, int(confirm_retry_budget or 0)) and _remaining_s >= 0.30:
                dialog_clicked = bool(_exec_try_confirm_dialog(page, min(350, max(120, int(_remaining_s * 1000.0)))))
                if dialog_clicked:
                    _confirm_retry_used += 1
                    if _perf_dialog_click_ms is None:
                        _perf_dialog_click_ms = _exec_perf_ms(_perf_t0)
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

        try:
            toast = _read_toast_text()
        except Exception:
            toast = ""

        if toast:
            det["toast"] = toast
            if _perf_first_toast_ms is None:
                _perf_first_toast_ms = _exec_perf_ms(_perf_t0)
            j = _judge_text(toast)
            det["judge"] = j or "unknown"
            det["source"] = "toast"
            if j == "ok":
                _exec_perf_log_safe("submit_wait_done", plat=_plat_name, coin=coin, label=label, result="ok", total_ms=_exec_perf_ms(_perf_t0), dialog_ms=_perf_dialog_click_ms, toast_ms=_perf_first_toast_ms, verify_ms=_perf_first_verify_ms, loading_seen=int(bool(_perf_loading_seen)), judge=det.get("judge",""), source=det.get("source",""), verify_kind=((last_verify_ev or {}).get("kind") or ""))
                _exec_confirm_state_exit(_confirm_state, result="ok")
                return _submit_wait_finish("ok", det)
            if j == "fail":
                _exec_perf_log_safe("submit_wait_done", plat=_plat_name, coin=coin, label=label, result="fail", total_ms=_exec_perf_ms(_perf_t0), dialog_ms=_perf_dialog_click_ms, toast_ms=_perf_first_toast_ms, verify_ms=_perf_first_verify_ms, loading_seen=int(bool(_perf_loading_seen)), judge=det.get("judge",""), source=det.get("source",""), verify_kind=((last_verify_ev or {}).get("kind") or ""))
                _exec_confirm_state_exit(_confirm_state, result="fail")
                return _submit_wait_finish("fail", det)
            try:
                _exec_step_sleep(fast_poll, f"SUBMIT_RECHECK:{label}")
            except Exception:
                try:
                    time.sleep(fast_poll)
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_1181', _e)
                    pass
            try:
                toast2 = _read_toast_text()
            except Exception:
                toast2 = ""
            if toast2 and toast2 != toast:
                det["toast"] = toast2
                j2 = _judge_text(toast2)
                det["judge"] = j2 or "unknown"
                det["source"] = "toast"
                if j2 == "ok":
                    _exec_perf_log_safe("submit_wait_done", plat=_plat_name, coin=coin, label=label, result="ok", total_ms=_exec_perf_ms(_perf_t0), dialog_ms=_perf_dialog_click_ms, toast_ms=_perf_first_toast_ms, verify_ms=_perf_first_verify_ms, loading_seen=int(bool(_perf_loading_seen)), judge=det.get("judge",""), source=det.get("source",""), verify_kind=((last_verify_ev or {}).get("kind") or ""))
                    _exec_confirm_state_exit(_confirm_state, result="ok")
                    return _submit_wait_finish("ok", det)
                if j2 == "fail":
                    _exec_perf_log_safe("submit_wait_done", plat=_plat_name, coin=coin, label=label, result="fail", total_ms=_exec_perf_ms(_perf_t0), dialog_ms=_perf_dialog_click_ms, toast_ms=_perf_first_toast_ms, verify_ms=_perf_first_verify_ms, loading_seen=int(bool(_perf_loading_seen)), judge=det.get("judge",""), source=det.get("source",""), verify_kind=((last_verify_ev or {}).get("kind") or ""))
                    _exec_confirm_state_exit(_confirm_state, result="fail")
                    return _submit_wait_finish("fail", det)

        if verify_enabled and _remaining_s >= 0.12:
            _verify_round_idx += 1
            ok2, ev2 = _try_verify_now(det.get("elapsed_s", 0.0), _verify_round_idx, _remaining_s)
            last_verify_ev = dict(ev2 or {})
            if ok2:
                if _perf_first_verify_ms is None:
                    _perf_first_verify_ms = _exec_perf_ms(_perf_t0)
                det["judge"] = "verify"
                det["source"] = "verify"
                det["verify_kind"] = str((last_verify_ev or {}).get("kind") or kind or "")
                _exec_perf_log_safe("submit_wait_done", plat=_plat_name, coin=coin, label=label, result="ok", total_ms=_exec_perf_ms(_perf_t0), dialog_ms=_perf_dialog_click_ms, toast_ms=_perf_first_toast_ms, verify_ms=_perf_first_verify_ms, loading_seen=int(bool(_perf_loading_seen)), judge=det.get("judge",""), source=det.get("source",""), verify_kind=det.get("verify_kind",""))
                _exec_confirm_state_exit(_confirm_state, result="ok")
                return _submit_wait_finish("ok", det)

        if det["elapsed_s"] >= float(timeout_s or 0.0):
            det["judge"] = "timeout"
            det["source"] = det.get("source") or "timeout"
            det["verify_kind"] = str((last_verify_ev or {}).get("kind") or det.get("verify_kind") or "")
            _exec_perf_log_safe("submit_wait_done", plat=_plat_name, coin=coin, label=label, result="unknown", total_ms=_exec_perf_ms(_perf_t0), dialog_ms=_perf_dialog_click_ms, toast_ms=_perf_first_toast_ms, verify_ms=_perf_first_verify_ms, loading_seen=int(bool(_perf_loading_seen)), judge=det.get("judge",""), source=det.get("source",""), verify_kind=det.get("verify_kind",""))
            _exec_confirm_state_exit(_confirm_state, result="unknown")
            return _submit_wait_finish("unknown", det)

        has_loading = False
        try:
            has_loading = bool(_has_loading())
            if has_loading:
                _perf_loading_seen = True
        except Exception:
            has_loading = False

        next_wait = fast_poll if (dialog_clicked or has_loading or det["elapsed_s"] < 0.50) else idle_poll
        try:
            _exec_step_sleep(next_wait if next_wait > 0 else slow_poll, f"SUBMIT_WAIT:{label}")
        except Exception:
            try:
                time.sleep(next_wait if next_wait > 0 else slow_poll)
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

def _exec_wait_first_visible(page, selectors: list[str], *, timeout_s: float = 2.0, reason: str = ""):
    """在给定 selectors 中找到第一个可见元素（button/locator），返回 locator；超时返回 None。"""
    try:
        t0 = time.time()
    except Exception:
        t0 = 0.0
    _poll = float(_exec_submit_poll_sec() or 0.35)
    _poll = max(_exec_sleep_floor_sec(), _poll)
    while True:
        try:
            for sel in (selectors or []):
                try:
                    loc = page.locator(sel).first
                    if _pw_locator_count(loc, "exec.wait_first_visible") <= 0:
                        continue
                    if _pw_call("exec.wait_first_visible.is_visible", loc.is_visible):
                        return loc
                except Exception:
                    continue
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_1182', _e)
            pass
        try:
            if (time.time() - t0) >= float(timeout_s or 0.0):
                return None
        except Exception:
            return None
        _exec_step_sleep(_poll, f"WAIT_VISIBLE:{reason}" if reason else "WAIT_VISIBLE")

def _exec_wait_var_submit_ready(page, *, coin: str, side_word: str, timeout_s: float = 2.2) -> bool:
    """等待 VAR 提交按钮从不可点 -> 可点（条件满足立刻返回 True）。"""
    try:
        c = str(coin or "").upper().strip()
    except Exception:
        c = str(coin or "")
    try:
        sw = str(side_word or "").strip()
    except Exception:
        sw = str(side_word or "")
    confirm_text = f"{sw} {c}".strip()
    sels = [
        f'button:has-text("{confirm_text}")',
        f'button:has(span:has-text("{confirm_text}"))',
        'button[data-testid="order-button"]',
        'button[data-testid="submit-order-button"]',
    ]
    try:
        t0 = time.time()
    except Exception:
        t0 = 0.0
    _poll = max(_exec_sleep_floor_sec(), float(_exec_cfg_float("EXEC_VAR_SUBMIT_READY_POLL_SEC", 0.20)))
    while True:
        try:
            for sel in sels:
                try:
                    btn = page.locator(sel).first
                    if _pw_locator_count(btn, "var.submit_ready") <= 0:
                        continue
                    if _pw_locator_enabled(btn, "var.submit_ready.enabled"):
                        return True
                except Exception:
                    continue
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_1183', _e)
            pass
        try:
            if (time.time() - t0) >= float(timeout_s or 0.0):
                return False
        except Exception:
            return False
        _exec_step_sleep(_poll, f"VAR_SUBMIT_READY:{confirm_text}")

def _exec_ensure_active_page(page, label: str = "") -> None:
    _exec_stage_probe("BRING_FRONT_BEGIN", str(label or "exec.ensure_active_page"))
    try:
        _exec_front_if_needed(page, f"exec.ensure_active_page.front:{label}", label=str(label or ""), plat=("VAR" if "VAR" in str(label or "").upper() else ("EXT" if "EXT" in str(label or "").upper() else "")), coin="", min_interval_sec=float(_exec_cfg_float("EXEC_FRONT_DEDUPE_SEC", 1.25)))
        if label:
            _exec_log(f"置前（BringToFront（置前））：{label}")
        _exec_stage_probe("BRING_FRONT_END", str(label or "exec.ensure_active_page"), ok=1)
    except _UiDeadError:
        _exec_stage_probe("BRING_FRONT_FAIL", str(label or "exec.ensure_active_page"), err="UiDeadError")
        raise
    except Exception as _e:
        _exec_stage_probe("BRING_FRONT_FAIL", str(label or "exec.ensure_active_page"), err=f"{type(_e).__name__}:{_e}"[:240])
        _log_exc_level(mod="EXEC", stage="EXEC_ACTIVE_PAGE_FRONT_FAIL", level="B", e=_e, desc=str(label or "")[:120])

    _exec_stage_probe("UI_PROBE_BEGIN", str(label or "exec.ensure_active_page"))
    try:
        _pw_call(f"exec.ensure_active_page.mouse_move:{label}", page.mouse.move, 10, 10)
        try:
            _pw_call(f"exec.ensure_active_page.title:{label}", page.title)
        except Exception:
            pass
        _exec_stage_probe("UI_PROBE_END", str(label or "exec.ensure_active_page"), ok=1)
    except _UiDeadError:
        _exec_stage_probe("UI_PROBE_FAIL", str(label or "exec.ensure_active_page"), err="UiDeadError")
        raise
    except Exception as _e:
        _exec_stage_probe("UI_PROBE_FAIL", str(label or "exec.ensure_active_page"), err=f"{type(_e).__name__}:{_e}"[:240])
        _log_exc_level(mod="EXEC", stage="EXEC_ACTIVE_PAGE_MOUSE_FAIL", level="C", e=_e, desc=str(label or "")[:120])

def _exec_normalize_coin(coin: str) -> str:
    c = (coin or "").strip().upper()
    c = re.sub(r"[^A-Z0-9]", "", c)
    return c

def _exec_goto_coin_ext(page, coin: str, timeout_ms: int, *, exec_privilege: bool = False, privilege_reason: str = "") -> bool:
    try:
        _pin("EXEC_STEP", mod="EXEC", step="UI_GOTO_COIN_BEGIN", coin=str(coin or "").upper(), plat="EXT")
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    try:
        _priv_reason_norm = str(privilege_reason or '').strip().lower()
    except Exception:
        _priv_reason_norm = ''
    if _priv_reason_norm == 'reduce_only_exec' and not bool(exec_privilege):
        _priv_reason_norm = ''
    if _priv_reason_norm == 'reduce_only_exec':
        try:
            _cur_coin_norm = _exec_normalize_coin(_detect_current_coin_ext(page) or '')
        except Exception:
            _cur_coin_norm = ''
        _req_coin_norm = _exec_normalize_coin(coin)
        if _cur_coin_norm and _req_coin_norm and (_cur_coin_norm != _req_coin_norm):
            exec_privilege = False
            _priv_reason_norm = 'page_coin_mismatch_cancel_reduce_only_priv'
            try:
                _pin("EXEC_SWITCH_PRIV_CANCEL", mod="EXEC", step="UI_GOTO_COIN_PRIV_CANCEL", coin=str(_req_coin_norm or '').upper(), plat="EXT", ok=1, reason=str(_priv_reason_norm))
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_ext_priv_cancel', _e)
                pass
    privilege_reason = str(_priv_reason_norm or privilege_reason or '')

    """EXT（平台）切币优先“点击持仓列表”，失败再 fallback（回退）到 goto（跳转）URL（链接）。
    - 目的：避免反复重输链接导致慢/不稳
    - 点击切换只在“持仓列表可见 + 目标币行存在”时生效；否则仍用原 goto
    """
    c = _ext_canonical_coin(coin)
    if not c:
        return True
    _target_route_coin = _ext_route_symbol(c)
    target = ext_market_url(c)

    try:
        cur = page.url or ""
    except Exception:
        cur = ""
    if cur.startswith(target):
        _exec_mark_goto_ok(page, plat="EXT", coin=c, label="EXT_URL_TARGET")
        _exec_log_goto_skip("EXT", c, reason="already_on_target_url")
        _exec_log(f"EXT（平台）已在目标币种页面（Coin（币种））：{c}")
        return True
    try:
        det0 = _detect_current_coin_ext(page)
    except Exception:
        det0 = ""
    if (det0 or "").upper() == c:
        _exec_mark_goto_ok(page, plat="EXT", coin=c, label="EXT_DETECT_TARGET")
        _exec_log_goto_skip("EXT", c, reason="already_on_target_detected", extra=f"detected={det0}")
        _exec_log(f"EXT（平台）检测已在目标币种页面（Coin（币种））：{c} | detected={det0}")
        return True
    if _exec_goto_recent_ok(page, plat="EXT", coin=c, max_age_sec=float(_exec_cfg_float("EXEC_GOTO_RECENT_OK_SEC", 1.8))):
        _exec_log_goto_skip("EXT", c, reason="recent_goto_ok")
        return True

    try:
        _ok_bgt, _bgt_rsn = _round_ui_budget_consume("exec_coin_switch", coin=c, plat="EXT", ctx=("EXT_GOTO_EXEC_PRIV" if exec_privilege else "EXT_GOTO_EXEC"), evidence="", cost=1)
        if bool(exec_privilege):
            _ok_bgt, _bgt_rsn = True, 'exec_privilege_bypass'
            try:
                _pin("EXEC_SWITCH_PRIV_GRANTED", mod="EXEC", step="UI_GOTO_COIN_PRIV", coin=str(c or "").upper(), plat="EXT", ok=1, reason=str(privilege_reason or 'exec_request'))
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_1184a', _e)
                pass
        _round_ui_budget_touch_watch(note=f"coin_switch:{_bgt_rsn}")
        if not _ok_bgt:
            try:
                _pin("EXEC_STEP", mod="EXEC", step="UI_GOTO_COIN_DENY", coin=str(c or "").upper(), plat="EXT", ok=0, reason=_bgt_rsn)
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_1184', _e)
                pass
            _exec_log(f"EXT（平台）切币被本轮预算阻断 | coin（币种）={c} | reason={_bgt_rsn}")
            return False
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_1185', _e)
        pass
    try:
        row = None
        coin_cell = None
        _matched_alias = ''
        for _alias in _ext_coin_aliases(c):
            try:
                _row_try = page.locator(f'table.fXKqmn.dLcbFb tbody tr:has(div.ePatWB:has-text("{_alias}"))').first
                if _row_try.count() > 0 and _row_try.is_visible(timeout=1200):
                    row = _row_try
                    _matched_alias = str(_alias or '')
                    coin_cell = row.locator("div.ePatWB").first
                    break
            except Exception:
                continue
        if row is not None and coin_cell is not None and coin_cell.count() > 0:
            try:
                _exec_safe_scroll(coin_cell, 5000, f"EXT（平台）切币滚动到持仓行（coin={c}|alias={_matched_alias or c}）")
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

            _exec_log(f"EXT（平台）点击持仓列表切换币种（Coin（币种））：{c} | alias={_matched_alias or c}")
            if not _exec_safe_click(coin_cell, 2500, f"EXT（平台）点击持仓行切币 coin={c} alias={_matched_alias or c}", pre_scroll=False):
                raise RuntimeError("CLICK_ERR")

            try:
                _pw_call(f"exec.goto_coin_ext.wait_url:{c}", page.wait_for_url, re.compile(rf".*/(?:perp|trade)/{re.escape(_target_route_coin)}-USD(?:\b|\?|$)"), timeout=min(6000, timeout_ms))
            except Exception:
                _pw_wait_ms(page, 1050, f"exec.goto_coin_ext.wait_after_click:{c}")

            _ctx_ok, _ctx_det = _ext_market_context_matches_request(c, page=page)
            if _ctx_ok:
                _exec_mark_goto_ok(page, plat="EXT", coin=c, label="EXT_CLICK_SWITCH_CTX")
                try:
                    _ensure_page_health_touch(page, 'EXT', event='switch_coin', coin=c)
                except Exception as _e:
                    _record_swallowed_exception('ext_page_health_switch_click', _e, coin=c)
                return True
            _exec_log(f"EXT（平台）点击切币后市场上下文未绑定成功，继续 fallback goto | det={_ctx_det}")
    except Exception as e:
        _exec_log(f"EXT（平台）点击持仓列表切币失败，准备 fallback（回退）goto（跳转） | err（错误）={type(e).__name__}:{e}")

    _exec_log(f"EXT（平台）切换币种页面（Coin（币种））：{c} | goto（跳转）={target}")
    try:
        _exec_front_if_needed(page, f"exec.goto_coin_ext.front:{c}", label=f"EXT_GOTO:{c}", plat="EXT", coin=c, min_interval_sec=float(_exec_cfg_float("EXEC_FRONT_DEDUPE_SEC", 1.25)))
    except _UiDeadError:
        raise
    except Exception as _e:
        _log_exc_level(mod="EXEC", stage="EXEC_GOTO_COIN_EXT_FRONT_FAIL", level="B", e=_e, coin=c, plat="EXT")

    try:
        _pw_goto(page, target, f"exec.goto_coin_ext.goto:{c}", timeout=timeout_ms)
        _exec_wait_post_goto_fast(page, coin=c, target=target, detector=_detect_current_coin_ext, timeout_s=min(1.0, max(0.35, float(timeout_ms or 0) / 1000.0 * 0.08 if timeout_ms else 0.8)))
        _ctx_ok, _ctx_det = _ext_market_context_matches_request(c, page=page)
        if not _ctx_ok:
            _exec_log(f"EXT（平台）跳转后目标市场绑定失败，拒绝继续执行 | det={_ctx_det}")
            return False
        _exec_mark_goto_ok(page, plat="EXT", coin=c, label="EXT_GOTO_URL")
        try:
            _ensure_page_health_touch(page, 'EXT', event='switch_coin', coin=c)
        except Exception as _e:
            _record_swallowed_exception('ext_page_health_switch_goto', _e, coin=c)
        return True
    except Exception as e:
        _exec_log(f"EXT（平台）跳转失败：{e}")
        return False

def _exec_wait_post_goto_fast(page, *, coin: str = '', target: str = '', detector=None, timeout_s: float = 0.9) -> bool:
    deadline = time.time() + max(0.2, float(timeout_s or 0.9))
    coin_u = str(coin or '').upper().strip()
    while time.time() < deadline:
        try:
            cur = str(getattr(page, 'url', '') or '')
        except Exception:
            cur = ''
        if target and cur.startswith(str(target)):
            return True
        if detector is not None:
            try:
                det = str(detector(page) or '').upper().strip()
            except Exception:
                det = ''
            if coin_u and det == coin_u:
                return True
        try:
            _pw_call(f'exec.wait_post_goto_fast.load:{coin_u or "*"}', page.wait_for_load_state, 'domcontentloaded', timeout=180)
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_1186', _e)
            pass
        try:
            time.sleep(0.12)
        except Exception:
            break
    return False

def _detect_current_coin_var(page) -> str:
    """尽量从 UI（界面）判断当前币种（VAR（平台V））。
    返回：大写 Coin（币种）或空字符串。
    说明：选择器可能随页面迭代变化，所以采用多策略兜底。
    """
    try:
        cur = page.url or ""
        m = re.search(r"/perpetual/([A-Za-z0-9]+)", cur)
        if m:
            return (m.group(1) or "").upper()
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    try:
        a = page.locator('a.link-instrument[aria-current="page"]').first
        if a.count() > 0:
            href = a.get_attribute('href') or ""
            m = re.search(r"/perpetual/([A-Za-z0-9]+)", href)
            if m:
                return (m.group(1) or "").upper()
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    for sel in (
        '[data-testid="instrument-name"]',
        '[data-testid="instrument-label"]',
        '[data-testid="market-name"]',
        '[data-testid="trading-pair"]',
    ):
        try:
            loc = page.locator(sel).first
            if loc.count() > 0 and loc.is_visible(timeout=300):
                t = (loc.text_content() or "").strip()
                m = re.search(r"\b([A-Za-z0-9]{2,6})\b", t)
                if m:
                    return (m.group(1) or "").upper()
        except Exception:
            continue

    try:
        a2 = page.locator('a.link-instrument[href^="/perpetual/"]').first
        if a2.count() > 0:
            href = a2.get_attribute('href') or ""
            m = re.search(r"/perpetual/([A-Za-z0-9]+)", href)
            if m:
                return (m.group(1) or "").upper()
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    return ""

def _ind_switch_probe_emit(payload: dict) -> None:
    """把切币探针结构化落盘到 logs/modules/IND_SWITCH.jsonl（通过 module 自动分流）。"""
    try:
        payload = dict(payload or {})
        payload.setdefault('event', 'IND_SWITCH_PROBE')
        payload['module'] = 'IND_SWITCH'
        payload.setdefault('ts_ms', int(time.time() * 1000))
        logfp = globals().get('DEFAULT_LOGFP') or globals().get('DEFAULT_LOGFP_FALLBACK')
        if not logfp:
            return
        write_jsonl(str(logfp), payload)
    except Exception:
        return

def _exec_var_switch_truth(page, coin: str = '', target: str = '') -> dict:
    """VAR 切币真相源：统一返回当前 URL / URL 提取币 / UI 检测币 / 是否已到目标。"""
    out = {
        'cur_url': '',
        'url_coin': '',
        'detected_coin': '',
        'target_coin': str(coin or '').upper().strip(),
        'at_target': False,
        'other_coin': '',
    }
    try:
        out['cur_url'] = str(getattr(page, 'url', '') or '')
    except Exception:
        out['cur_url'] = ''
    try:
        m = re.search(r"/perpetual/([A-Za-z0-9]+)", str(out['cur_url'] or ''))
        if m:
            out['url_coin'] = str(m.group(1) or '').upper().strip()
    except Exception:
        out['url_coin'] = ''
    try:
        out['detected_coin'] = str(_detect_current_coin_var(page) or '').upper().strip()
    except Exception:
        out['detected_coin'] = ''
    target_u = str(out.get('target_coin') or '').upper().strip()
    cur_url = str(out.get('cur_url') or '')
    if target and cur_url.startswith(str(target)):
        out['at_target'] = True
    elif target_u and target_u in {str(out.get('url_coin') or '').upper().strip(), str(out.get('detected_coin') or '').upper().strip()}:
        out['at_target'] = True
    other = ''
    for cand in (out.get('detected_coin'), out.get('url_coin')):
        cand_u = str(cand or '').upper().strip()
        if cand_u and cand_u != target_u:
            other = cand_u
            break
    out['other_coin'] = other
    return out

def _exec_var_switch_runtime_blocked(page, *, coin: str = '', where: str = '', reason: str = '') -> bool:
    try:
        if _pw_runtime_is_recovering('VAR'):
            try:
                _exec_log(f"VAR（平台）切币遇到运行时恢复态，停止本次确认链 | coin（币种）={str(coin or '').upper()} | where={where} | reason={_reason_with_zh('runtime_recovering')}")
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_1187', _e)
                pass
            return True
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_1188', _e)
        pass
    try:
        if _pw_is_closed(page):
            try:
                _exec_log(f"VAR（平台）切币遇到页面关闭，停止本次确认链 | coin（币种）={str(coin or '').upper()} | where={where} | reason={reason or 'page_closed'}")
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_1189', _e)
                pass
            return True
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_1190', _e)
        pass
    return False

def _exec_goto_coin_var(page, coin: str, timeout_ms: int, allow_goto: bool = True, ctx: str = '', *, exec_privilege: bool = False, privilege_reason: str = '') -> bool:
    try:
        _pin("EXEC_STEP", mod="EXEC", step="UI_GOTO_COIN_BEGIN", coin=str(coin or "").upper(), plat="VAR")
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    try:
        _priv_reason_norm = str(privilege_reason or '').strip().lower()
    except Exception:
        _priv_reason_norm = ''
    if _priv_reason_norm == 'reduce_only_exec' and not bool(exec_privilege):
        _priv_reason_norm = ''
    if _priv_reason_norm == 'reduce_only_exec':
        try:
            _cur_coin_norm = _exec_normalize_coin(_detect_current_coin_var(page) or '')
        except Exception:
            _cur_coin_norm = ''
        _req_coin_norm = _exec_normalize_coin(coin)
        if _cur_coin_norm and _req_coin_norm and (_cur_coin_norm != _req_coin_norm):
            exec_privilege = False
            _priv_reason_norm = 'page_coin_mismatch_cancel_reduce_only_priv'
            try:
                _pin("EXEC_SWITCH_PRIV_CANCEL", mod="EXEC", step="UI_GOTO_COIN_PRIV_CANCEL", coin=str(_req_coin_norm or '').upper(), plat="VAR", ok=1, reason=str(_priv_reason_norm))
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_var_priv_cancel', _e)
                pass
    privilege_reason = str(_priv_reason_norm or privilege_reason or '')
    _allow_goto_input = bool(allow_goto)
    allow_goto = bool(_exec_ctx_force_goto(ctx, allow_goto=bool(allow_goto), exec_privilege=bool(exec_privilege), privilege_reason=str(privilege_reason or '')))

    """VAR（平台V）切币：优先点击持仓列表，严格校验切换成功；失败再 fallback（回退）goto（跳转）。
    - 严格校验：URL（链接）或 UI（界面）检测到的当前币种必须匹配目标币种。

    失败分类（reason（原因码））：
    - NO_LINK（无链接）/ LINK_NOT_VISIBLE（链接不可见）
    - CLICK_ERR（点击异常）
    - NO_EFFECT（点击无效，币种未切换）
    - GOTO_DENY（禁止跳转）/ GOTO_ERR（跳转失败）
    """
    c = _exec_normalize_coin(coin)
    if not c:
        return True

    budget_sec = float(_exec_cfg_float("VAR_GOTO_COIN_BUDGET_SEC", 4.8 if str(ctx or '').upper().strip() == 'IND_ADX_RSI' else 3.8))
    deadline = float(time.monotonic()) + float(max(1.6, budget_sec))
    def _left_ms(default_ms: int) -> int:
        try:
            left = max(0.0, deadline - float(time.monotonic()))
            return int(min(float(default_ms), max(100.0, left * 1000.0)))
        except Exception:
            return int(default_ms)

    def _wait_visible_confirm(label: str, *, wait_url_ms: int, settle_ms: int, detect_retry: int = 4, allow_empty_detect: bool = True) -> bool:
        def _truth() -> dict:
            try:
                return _exec_var_switch_truth(page, coin=c, target=target)
            except Exception:
                return {'cur_url': '', 'url_coin': '', 'detected_coin': '', 'target_coin': c, 'at_target': False, 'other_coin': ''}

        first = _truth()
        if bool(first.get('at_target')):
            return True
        if _exec_var_switch_runtime_blocked(page, coin=c, where=f"exec.goto_coin_var.{label}.precheck:{c}", reason='precheck_runtime_blocked'):
            return False

        other_seen = str(first.get('other_coin') or '').upper().strip()
        wait_budget = _left_ms(wait_url_ms)
        if other_seen:
            wait_budget = min(wait_budget, 280)
            try:
                _emit(f'{label}_truth_precheck', False, 'OTHER_COIN_ACTIVE', {
                    'other_coin': other_seen,
                    'cur_url': str(first.get('cur_url') or ''),
                    'detected_coin': str(first.get('detected_coin') or ''),
                })
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_1191', _e)
                pass
        if wait_budget > 0 and not other_seen:
            try:
                _pw_call(f"exec.goto_coin_var.{label}.wait_url:{c}", page.wait_for_url, re.compile(rf".*/perpetual/{re.escape(c)}(?:\b|\?|$)"), timeout=wait_budget)
            except Exception as _e:
                after_wait = _truth()
                if bool(after_wait.get('at_target')):
                    return True
                if _exec_var_switch_runtime_blocked(page, coin=c, where=f"exec.goto_coin_var.{label}.wait_url:{c}", reason=type(_e).__name__):
                    return False
                _log_exc_level(mod="EXEC", stage=f"EXEC_GOTO_COIN_VAR_{label.upper()}_WAIT_FAIL", level="B", e=_e, coin=c, plat="VAR")

        if settle_ms > 0:
            try:
                _pw_wait_ms(page, _left_ms(settle_ms), f"exec.goto_coin_var.{label}.settle:{c}")
            except Exception:
                try:
                    time.sleep(max(0.05, min(0.35, float(settle_ms) / 1000.0)))
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_1192', _e)
                    pass
        for _ in range(max(1, int(detect_retry))):
            snap = _truth()
            if bool(snap.get('at_target')):
                return True
            if _exec_var_switch_runtime_blocked(page, coin=c, where=f"exec.goto_coin_var.{label}.retry:{c}", reason='retry_runtime_blocked'):
                return False
            det_x = str(snap.get('detected_coin') or '').upper().strip()
            other_coin = str(snap.get('other_coin') or '').upper().strip()
            if other_coin:
                try:
                    _emit(f'{label}_truth_retry', False, 'OTHER_COIN_STILL_ACTIVE', {
                        'other_coin': other_coin,
                        'cur_url': str(snap.get('cur_url') or ''),
                        'detected_coin': det_x,
                    })
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_1193', _e)
                    pass
            if (not det_x) and allow_empty_detect:
                try:
                    _pw_wait_ms(page, _left_ms(180), f"exec.goto_coin_var.{label}.retry_wait:{c}")
                except Exception:
                    try:
                        time.sleep(0.12)
                    except Exception as _e:
                        _record_swallowed_exception('except_pass_line_1194', _e)
                        pass
                continue
            if other_coin and _ < int(max(1, detect_retry)) - 1:
                try:
                    _pw_wait_ms(page, min(_left_ms(120), 120), f"exec.goto_coin_var.{label}.retry_other:{c}")
                except Exception:
                    try:
                        time.sleep(0.08)
                    except Exception as _e:
                        _record_swallowed_exception('except_pass_line_1195', _e)
                        pass
                continue
            if _ < int(max(1, detect_retry)) - 1:
                try:
                    _pw_wait_ms(page, _left_ms(220), f"exec.goto_coin_var.{label}.retry_gap:{c}")
                except Exception:
                    try:
                        time.sleep(0.15)
                    except Exception as _e:
                        _record_swallowed_exception('except_pass_line_1196', _e)
                        pass
        return False

    _bypass_cd = False
    try:
        _bypass_cd = bool(_exec_ctx_bypass_coin_cooldown(ctx, allow_goto=allow_goto))
    except Exception:
        _bypass_cd = False
    try:
        cd_left = _exec_coin_cooldown_left_sec(c)
    except Exception:
        cd_left = 0.0
    if cd_left > 0.0 and (not _bypass_cd):
        try:
            _exec_log(f"VAR（平台）切币命中冷却，直接跳过 | coin={c} | cd_left={cd_left:.1f}s | ctx={ctx}")
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_1197', _e)
            pass
        try:
            _emit('cooldown_skip', False, 'COOLDOWN', {'cd_left_sec': float(cd_left)})
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_1198', _e)
            pass
        return False
    if cd_left > 0.0 and _bypass_cd:
        try:
            _exec_log(f"VAR（平台）执行切币绕过冷却 | coin={c} | cd_left={cd_left:.1f}s | ctx={ctx}")
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_1199', _e)
            pass
        try:
            _emit('cooldown_bypass', True, 'EXEC_BYPASS', {'cd_left_sec': float(cd_left)})
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_1200', _e)
            pass
    target = f"https://omni.variational.io/perpetual/{c}"
    _last_fail_reason = ''

    def _emit(stage: str, ok: bool, reason: str = '', extra: dict = None):
        try:
            nonlocal _last_fail_reason
            if (not ok) and reason:
                _last_fail_reason = str(reason)
            cur_url = ''
            try:
                cur_url = page.url or ''
            except Exception:
                cur_url = ''
            payload = {
                'platform': 'VAR',
                'coin': c,
                'ctx': ctx or '',
                'allow_goto': bool(allow_goto),
                'stage': stage,
                'ok': bool(ok),
                'reason': reason or '',
                'cur_url': cur_url,
                'target_url': target,
                'detected_coin': _detect_current_coin_var(page) or '',
            }
            if extra:
                payload.update(extra)
            _ind_switch_probe_emit(payload)
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    try:
        cur = page.url or ""
    except Exception:
        cur = ""
    if cur.startswith(target):
        _exec_mark_goto_ok(page, plat="VAR", coin=c, label="VAR_URL_TARGET")
        try:
            _ensure_page_health_touch(page, 'VAR', event='switch_coin', coin=c)
        except Exception as _e:
            _record_swallowed_exception('var_page_health_switch_url_target', _e, coin=c)
        _emit('already_on_target', True)
        _exec_log_goto_skip("VAR", c, reason="already_on_target_url")
        _exec_log(f"VAR（平台）已在目标币种页面（Coin（币种））：{c}")
        return True
    try:
        det0 = _detect_current_coin_var(page)
    except Exception:
        det0 = ""
    if (det0 or "").upper() == c:
        _exec_mark_goto_ok(page, plat="VAR", coin=c, label="VAR_DETECT_TARGET")
        try:
            _ensure_page_health_touch(page, 'VAR', event='switch_coin', coin=c)
        except Exception as _e:
            _record_swallowed_exception('var_page_health_switch_detect_target', _e, coin=c)
        _emit('already_on_target_detected', True, extra={'detected_coin': det0})
        _exec_log_goto_skip("VAR", c, reason="already_on_target_detected", extra=f"detected={det0}")
        _exec_log(f"VAR（平台）检测已在目标币种页面（Coin（币种））：{c} | detected={det0}")
        return True
    if _exec_goto_recent_ok(page, plat="VAR", coin=c, max_age_sec=float(_exec_cfg_float("EXEC_GOTO_RECENT_OK_SEC", 1.8))):
        _emit('goto_recent_ok_skip', True)
        _exec_log_goto_skip("VAR", c, reason="recent_goto_ok")
        return True

    try:
        _budget_kind = "coin_switch" if str(ctx or "").upper().strip() == "IND_ADX_RSI" else "exec_coin_switch"
        _budget_ctx = str(ctx or ("VAR_IND_GOTO" if _budget_kind == "coin_switch" else "VAR_GOTO_EXEC"))
        _ok_bgt, _bgt_rsn = _round_ui_budget_consume(_budget_kind, coin=c, plat="VAR", ctx=_budget_ctx, evidence="", cost=1)
        if bool(exec_privilege) and _budget_kind == 'exec_coin_switch':
            _ok_bgt, _bgt_rsn = True, 'exec_privilege_bypass'
            try:
                _pin("EXEC_SWITCH_PRIV_GRANTED", mod="EXEC", step="UI_GOTO_COIN_PRIV", coin=str(c or "").upper(), plat="VAR", ok=1, reason=str(privilege_reason or 'exec_request'))
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_1201a', _e)
                pass
        _round_ui_budget_touch_watch(note=f"coin_switch:{_bgt_rsn}")
        if not _ok_bgt:
            try:
                _emit('round_budget_deny', False, 'ROUND_COIN_SWITCH_BUDGET', {'deny_reason': _bgt_rsn})
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_1201', _e)
                pass
            _exec_log(f"VAR（平台）切币被本轮预算阻断 | coin（币种）={c} | ctx（上下文）={ctx} | reason={_bgt_rsn}")
            return False
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_1202', _e)
        pass
    link = None
    row = None
    try:
        link = page.locator(f'a.link-instrument[href="/perpetual/{c}"]').first
        if link.count() == 0:
            link = page.locator(f'a.link-instrument[href*="/perpetual/{c}"]').first

        try:
            row = page.locator('[data-testid="positions-table-row"]').filter(
                has=page.locator(f'a.link-instrument[href*="/perpetual/{c}"]')
            ).first
        except Exception:
            row = None

        if not link or link.count() == 0:
            _emit('find_link', False, 'NO_LINK')
            _exec_log(f"VAR（平台）切币找不到目标链接（NO_LINK（无链接））| coin（币种）={c} | ctx（上下文）={ctx}")
            raise RuntimeError('NO_LINK')

        try:
            vis = link.is_visible(timeout=_left_ms(900))
        except Exception:
            vis = False
        if not vis:
            _emit('find_link', False, 'LINK_NOT_VISIBLE')
            _exec_log(f"VAR（平台）切币链接不可见（LINK_NOT_VISIBLE（链接不可见））| coin（币种）={c} | ctx（上下文）={ctx}")
            raise RuntimeError('LINK_NOT_VISIBLE')

        try:
            _exec_safe_scroll(link, _left_ms(1200), f"VAR（平台）切币滚动到链接（coin={c}）")
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

        _emit('click_link_1', True)
        _exec_log(f"VAR（平台）点击持仓列表切换币种（Coin（币种））：{c}")
        try:
            if not _exec_safe_click(link, _left_ms(900), f"VAR（平台）点击链接切币 coin={c}", pre_scroll=False):
                raise RuntimeError("click_link_fail")
        except Exception as e:
            _emit('click_link_1', False, 'CLICK_ERR', {'err': f"{type(e).__name__}:{e}"})
            raise

        ok_switched = _wait_visible_confirm(
            'verify1',
            wait_url_ms=min(1600, timeout_ms),
            settle_ms=420 if str(ctx or '').upper().strip() == 'IND_ADX_RSI' else 260,
            detect_retry=5 if str(ctx or '').upper().strip() == 'IND_ADX_RSI' else 4,
            allow_empty_detect=True,
        )

        if ok_switched:
            _exec_mark_goto_ok(page, plat="VAR", coin=c, label="VAR_CLICK_VERIFY1")
            try:
                _ensure_page_health_touch(page, 'VAR', event='switch_coin', coin=c)
            except Exception as _e:
                _record_swallowed_exception('var_page_health_switch_click_verify1', _e, coin=c)
            _emit('verify_1', True)
            return True

        if row is not None and row.count() > 0:
            try:
                _emit('click_row_2', True)
                _exec_log(f"VAR（平台）切币二次尝试：点击持仓行（row（行））| coin（币种）={c}")
                if not _exec_safe_click(row, _left_ms(900), f"VAR（平台）点击持仓行切币 coin={c}", pre_scroll=False):
                    raise RuntimeError("click_row_fail")
                ok_switched2 = _wait_visible_confirm(
                    'verify2',
                    wait_url_ms=min(1400, timeout_ms),
                    settle_ms=360 if str(ctx or '').upper().strip() == 'IND_ADX_RSI' else 220,
                    detect_retry=4,
                    allow_empty_detect=True,
                )
                if ok_switched2:
                    _exec_mark_goto_ok(page, plat="VAR", coin=c, label="VAR_CLICK_VERIFY2")
                    try:
                        _ensure_page_health_touch(page, 'VAR', event='switch_coin', coin=c)
                    except Exception as _e:
                        _record_swallowed_exception('var_page_health_switch_click_verify2', _e, coin=c)
                    _emit('verify_2', True)
                    return True
            except Exception as e:
                _emit('click_row_2', False, 'CLICK_ERR', {'err': f"{type(e).__name__}:{e}"})

        _emit('final', False, 'NO_EFFECT')
        try:
            _exec_coin_cooldown_set(c, sec=90.0, reason='no_effect_click')
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_1203', _e)
            pass
        _exec_log(f"VAR（平台）点击切币无效（NO_EFFECT（无效果）），准备 fallback（回退）goto（跳转）| coin（币种）={c} | ctx（上下文）={ctx}")

    except Exception as e:
        _emit('click_phase_exception', False, 'EXCEPTION', {'err': f"{type(e).__name__}:{e}"})
        try:
            _exec_coin_cooldown_set(c, sec=90.0, reason='click_exception')
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_1204', _e)
            pass
    if not allow_goto:
        _override = False
        try:
            if str(ctx or '') == 'IND_ADX_RSI':
                _override = True
            elif str(ctx or '') and str(_last_fail_reason or '') in ('NO_LINK', 'LINK_NOT_VISIBLE'):
                _override = True
        except Exception:
            _override = False
        if not _override:
            try:
                _emit('goto_prepare', False, 'GOTO_DENY')
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

            _exec_log(f"VAR（平台）禁止 goto（跳转）兜底（allow_goto=False）| coin（币种）={c} | ctx（上下文）={ctx}")
            try:
                _ctx_exec = bool(_exec_ctx_force_goto(ctx, allow_goto=False, exec_privilege=bool(exec_privilege), privilege_reason=str(privilege_reason or '')))
            except Exception:
                _ctx_exec = False
            if not _ctx_exec:
                try:
                    _exec_coin_cooldown_set(c, sec=90.0, reason="goto_deny")
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_1205', _e)
                    pass
            return False
        else:
            try:
                _emit('goto_prepare', True, 'GOTO_OVERRIDE', {'last_fail_reason': str(_last_fail_reason or '')})
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

            _exec_log(f"VAR（平台）放开 goto（跳转）兜底（GOTO_OVERRIDE）| coin（币种）={c} | ctx（上下文）={ctx} | last_fail={_last_fail_reason}")

    _emit('goto', True)
    _exec_log(f"VAR（平台）切换币种页面（Coin（币种））：{c} | goto（跳转）={target} | ctx（上下文）={ctx}")
    _exec_stage_probe("NAV_BEGIN", f"VAR:{c}:{ctx or 'goto_coin'}", target_url=str(target or '')[:180], timeout_ms=int(timeout_ms or 0))
    try:
        _exec_front_if_needed(page, f"exec.goto_coin_var.front:{c}", label=f"VAR_GOTO:{c}", plat="VAR", coin=c, min_interval_sec=float(_exec_cfg_float("EXEC_FRONT_DEDUPE_SEC", 1.25)))
    except _UiDeadError:
        _exec_stage_probe("NAV_FAIL", f"VAR:{c}:{ctx or 'goto_coin'}", err="front_ui_dead")
        raise
    except Exception as _e:
        _exec_stage_probe("NAV_FAIL", f"VAR:{c}:{ctx or 'goto_coin'}", err=f"front:{type(_e).__name__}:{_e}"[:240])
        _log_exc_level(mod="EXEC", stage="EXEC_GOTO_COIN_VAR_FRONT_FAIL", level="B", e=_e, coin=c, plat="VAR")

    try:
        _pw_goto(page, target, f"exec.goto_coin_var.goto:{c}", timeout=timeout_ms)
        _exec_wait_post_goto_fast(page, coin=c, target=target, detector=_detect_current_coin_var, timeout_s=min(1.5, max(0.55, float(timeout_ms or 0) / 1000.0 * 0.12 if timeout_ms else 1.05)))
        if _wait_visible_confirm(
            'goto_verify',
            wait_url_ms=min(1500, timeout_ms),
            settle_ms=420 if str(ctx or '').upper().strip() == 'IND_ADX_RSI' else 260,
            detect_retry=5 if str(ctx or '').upper().strip() == 'IND_ADX_RSI' else 4,
            allow_empty_detect=True,
        ):
            _exec_mark_goto_ok(page, plat="VAR", coin=c, label="VAR_GOTO_VERIFY")
            try:
                _ensure_page_health_touch(page, 'VAR', event='switch_coin', coin=c)
            except Exception as _e:
                _record_swallowed_exception('var_page_health_switch_goto_verify', _e, coin=c)
            _emit('goto_verify', True)
            _exec_stage_probe("NAV_END", f"VAR:{c}:{ctx or 'goto_coin'}", ok=1)
            return True
        _emit('goto_verify', False, 'NO_EFFECT')
        _exec_stage_probe("NAV_FAIL", f"VAR:{c}:{ctx or 'goto_coin'}", err='goto_verify_no_effect')
        try:
            _exec_coin_cooldown_set(c, sec=90.0, reason='goto_no_effect')
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_1206', _e)
            pass
        return False
    except Exception as e:
        _emit('goto', False, 'GOTO_ERR', {'err': f"{type(e).__name__}:{e}"})
        _exec_log(f"VAR（平台）跳转失败：{e}")
        try:
            _exec_coin_cooldown_set(c, sec=120.0, reason='goto_err')
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_1207', _e)
            pass
        return False

def _exec_safe_wait_visible(locator, timeout_ms: int, desc: str) -> bool:
    try:
        _exec_active_stage_touch("EXEC_UI_WAIT_VISIBLE_BEGIN", str(desc or "")[:180])
        _pw_call(f"exec.wait_visible:{desc}", locator.wait_for, state="visible", timeout=timeout_ms)
        _exec_active_stage_touch("EXEC_UI_WAIT_VISIBLE_OK", str(desc or "")[:180])
        return True
    except PlaywrightTimeoutError:
        _exec_active_stage_touch("EXEC_UI_WAIT_VISIBLE_FAIL", str(desc or "")[:180], err="timeout")
        _exec_log(f"等待元素超时：{desc}")
        return False
    except Exception as e:
        _exec_active_stage_touch("EXEC_UI_WAIT_VISIBLE_FAIL", str(desc or "")[:180], err=f"{type(e).__name__}:{e}"[:180])
        if _is_target_closed_exc(e):
            raise _UiDeadError("_exec_safe_wait_visible", f"{desc}|{repr(e)}") from e
        _exec_log(f"等待元素失败：{desc} | err（错误）={e}")
        return False

def _exec_is_pw_stable_timeout(e: Exception) -> bool:
    """识别 Playwright 的“等待稳定/滚动到可视区”类超时。
    这类问题往往是 UI 动画/重渲染/遮挡导致的短暂不稳定，适合做轻量重试。
    """
    try:
        if isinstance(e, PlaywrightTimeoutError):
            return True
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_1208', _e)
        pass
    try:
        msg = str(e) or ""
    except Exception:
        msg = ""
    msg = msg.lower()
    keys = [
        "scroll_into_view_if_needed",
        "waiting for element to be stable",
        "element is not stable",
        "element is detached",
        "timeout",
    ]
    hit = 0
    for k in keys:
        if k in msg:
            hit += 1
    return hit >= 2

def _exec_safe_scroll(locator, timeout_ms: int, desc: str) -> bool:
    """安全滚动到可视区域：对“等待稳定”类超时做一次重试。
    - 证据针：EXEC_STEP UI_SCROLL_BEGIN/UI_SCROLL_OK/UI_SCROLL_FAIL/UI_SCROLL_RETRY
    """
    try:
        try:
            _pin("EXEC_STEP", mod="EXEC", step="UI_SCROLL_BEGIN", coin="*", desc=str(desc or "")[:180])
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

        for attempt in range(2):
            try:
                _pw_call(f"exec.scroll:{desc}", locator.scroll_into_view_if_needed, timeout=timeout_ms)
                try:
                    _pin("EXEC_STEP", mod="EXEC", step="UI_SCROLL_OK", coin="*", desc=str(desc or "")[:180])
                except Exception as _e:
                    _log_exc(mod="SYS", stage="EXC_PASS", e=_e)
                return True
            except Exception as e:
                if _is_target_closed_exc(e):
                    raise _UiDeadError("_exec_safe_scroll", f"{desc}|{repr(e)}") from e

                if attempt == 0 and _exec_is_pw_stable_timeout(e):
                    try:
                        _pin("EXEC_STEP", mod="EXEC", step="UI_SCROLL_RETRY", coin="*", desc=str(desc or "")[:180],
                             reason=f"{type(e).__name__}:{str(e)[:120]}")
                    except Exception as _e:
                        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)
                    try:
                        time.sleep(0.45)
                    except Exception as _e:
                        _record_swallowed_exception('except_pass_line_1209', _e)
                        pass
                    continue

                _exec_log(f"滚动失败：{desc} | err（错误）={e}")
                try:
                    _pin("EXEC_STEP", mod="EXEC", step="UI_SCROLL_FAIL", coin="*", desc=str(desc or "")[:180],
                         reason=f"exc:{type(e).__name__}")
                except Exception as _e:
                    _log_exc(mod="SYS", stage="EXC_PASS", e=_e)
                return False

        return False
    except PlaywrightTimeoutError:
        _exec_log(f"滚动超时：{desc}")
        try:
            _pin("EXEC_STEP", mod="EXEC", step="UI_SCROLL_FAIL", coin="*", desc=str(desc or "")[:180], reason="timeout")
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)
        return False

def _exec_safe_click(locator, timeout_ms: int, desc: str, allow_force_retry: bool = False, pre_scroll: bool = True) -> bool:
    """安全点击（带 UI 步骤针）：visible -> (optional scroll) -> click，并对“等待稳定”类超时做一次重试。
    - 证据针：EXEC_STEP UI_CLICK_BEGIN/UI_CLICK_OK/UI_CLICK_FAIL/UI_CLICK_RETRY
    """
    try:
        _exec_active_stage_touch("EXEC_UI_CLICK_BEGIN", str(desc or "")[:180])
        try:
            _pin("EXEC_STEP", mod="EXEC", step="UI_CLICK_BEGIN", coin="*", desc=str(desc or "")[:180])
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

        _pw_call(f"exec.click.wait_visible:{desc}", locator.wait_for, state="visible", timeout=timeout_ms)

        for attempt in range(2):
            try:
                if pre_scroll:
                    try:
                        _exec_safe_scroll(locator, min(max(2500, timeout_ms), 8000), f"{desc}|scroll")
                    except Exception as _e:
                        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

                if attempt == 1 and allow_force_retry:
                    _pw_call(f"exec.click.force:{desc}", locator.click, timeout=timeout_ms, force=True)
                else:
                    _pw_call(f"exec.click:{desc}", locator.click, timeout=timeout_ms)

                _exec_active_stage_touch("EXEC_UI_CLICK_OK", str(desc or "")[:180])
                try:
                    _pin("EXEC_STEP", mod="EXEC", step="UI_CLICK_OK", coin="*", desc=str(desc or "")[:180])
                except Exception as _e:
                    _log_exc(mod="SYS", stage="EXC_PASS", e=_e)
                return True

            except Exception as e:
                if _is_target_closed_exc(e):
                    raise _UiDeadError("_exec_safe_click", f"{desc}|{repr(e)}") from e

                if attempt == 0 and _exec_is_pw_stable_timeout(e):
                    try:
                        _pin("EXEC_STEP", mod="EXEC", step="UI_CLICK_RETRY", coin="*", desc=str(desc or "")[:180],
                             reason=f"{type(e).__name__}:{str(e)[:120]}")
                    except Exception as _e:
                        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)
                    try:
                        time.sleep(0.55)
                    except Exception as _e:
                        _record_swallowed_exception('except_pass_line_1210', _e)
                        pass
                    continue

                _exec_active_stage_touch("EXEC_UI_CLICK_FAIL", str(desc or "")[:180], err=f"{type(e).__name__}:{e}"[:180])
                _exec_log(f"点击失败：{desc} | err（错误）={e}")
                try:
                    _pin("EXEC_STEP", mod="EXEC", step="UI_CLICK_FAIL", coin="*", desc=str(desc or "")[:180],
                         reason=f"exc:{type(e).__name__}")
                except Exception as _e:
                    _log_exc(mod="SYS", stage="EXC_PASS", e=_e)
                return False

        return False

    except PlaywrightTimeoutError:
        _exec_active_stage_touch("EXEC_UI_CLICK_FAIL", str(desc or "")[:180], err="timeout")
        _exec_log(f"点击超时：{desc}")
        try:
            _pin("EXEC_STEP", mod="EXEC", step="UI_CLICK_FAIL", coin="*", desc=str(desc or "")[:180], reason="timeout")
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)
        return False

def _pw_locator_count(locator, where: str) -> int:
    try:
        return int(_pw_call(f"{where}.count", locator.count) or 0)
    except Exception as _e:
        if _is_target_closed_exc(_e):
            raise _UiDeadError(f"{where}.count", repr(_e)) from _e
        return 0

def _pw_locator_attr(locator, name: str, where: str):
    try:
        return _pw_call(f"{where}.attr.{name}", locator.get_attribute, name)
    except Exception as _e:
        if _is_target_closed_exc(_e):
            raise _UiDeadError(f"{where}.attr.{name}", repr(_e)) from _e
        return None

def _pw_locator_visible(locator, where: str, timeout: int = 200) -> bool:
    try:
        return bool(_pw_call(f"{where}.visible", locator.is_visible, timeout=timeout))
    except Exception as _e:
        if _is_target_closed_exc(_e):
            raise _UiDeadError(f"{where}.visible", repr(_e)) from _e
        return False

def _pw_locator_enabled(locator, where: str) -> bool:
    try:
        return bool(_pw_call(f"{where}.enabled", locator.is_enabled))
    except Exception as _e:
        if _is_target_closed_exc(_e):
            raise _UiDeadError(f"{where}.enabled", repr(_e)) from _e
        try:
            return _pw_locator_attr(locator, 'disabled', where) is None
        except Exception:
            return False

def _pw_locator_editable(locator, where: str) -> bool:
    try:
        return bool(_pw_call(f"{where}.editable", locator.is_editable))
    except Exception as _e:
        if _is_target_closed_exc(_e):
            raise _UiDeadError(f"{where}.editable", repr(_e)) from _e
        try:
            if not _pw_locator_enabled(locator, where):
                return False
        except Exception:
            return False
        try:
            ro = _pw_locator_attr(locator, 'readonly', where)
            if ro is not None:
                return False
        except Exception:
            return False
        return True

def _pw_locator_input_value(locator, where: str) -> str:
    try:
        return str(_pw_call(f"{where}.input_value", locator.input_value) or "")
    except Exception as _e:
        if _is_target_closed_exc(_e):
            raise _UiDeadError(f"{where}.input_value", repr(_e)) from _e
        return ""

def _safe_text(locator) -> str:
    if _pw_runtime_is_recovering('VAR'):
        return ""
    try:
        t = _pw_call("exec.safe_text.inner_text", locator.inner_text, timeout=800)
        return (t or "").strip()
    except Exception as _e:
        if _is_target_closed_exc(_e):
            raise _UiDeadError("_safe_text.inner_text", repr(_e)) from _e
        try:
            t = _pw_call("exec.safe_text.text_content", locator.text_content, timeout=800)
            return (t or "").strip()
        except Exception as _e2:
            if _is_target_closed_exc(_e2):
                raise _UiDeadError("_safe_text.text_content", repr(_e2)) from _e2
            return ""

