def _exec_safe_fill(locator, text: str, timeout_ms: int, desc: str) -> bool:
    """更稳：click（点击）→ Ctrl+A → type（逐字输入）触发前端事件
    - 证据针：EXEC_STEP UI_FILL_BEGIN/UI_FILL_OK/UI_FILL_FAIL
    """
    try:
        _exec_active_stage_touch("EXEC_UI_FILL_BEGIN", str(desc or "")[:180], val=str(text)[:64])
        try:
            _pin("EXEC_STEP", mod="EXEC", step="UI_FILL_BEGIN", coin="*", desc=str(desc or "")[:180], val=str(text)[:64])
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

        _pw_call(f"exec.fill.wait_visible:{desc}", locator.wait_for, state="visible", timeout=timeout_ms)
        try:
            _pw_call(f"exec.fill.click:{desc}", locator.click, timeout=timeout_ms)
        except Exception as _e:
            if _is_target_closed_exc(_e):
                raise _UiDeadError("_exec_safe_fill.click", f"{desc}|{repr(_e)}") from _e
            _log_exc_level(mod="EXEC", stage="UI_FILL_CLICK_PASS", level="B", e=_e, act="fill", coin="*")

        try:
            _pw_call(f"exec.fill.ctrl_a:{desc}", locator.press, "Control+A")
        except Exception as _e:
            if _is_target_closed_exc(_e):
                raise _UiDeadError("_exec_safe_fill.ctrl_a", f"{desc}|{repr(_e)}") from _e
            _log_exc_level(mod="EXEC", stage="UI_FILL_CTRL_A_PASS", level="B", e=_e, act="fill", coin="*")

        _pw_call(f"exec.fill.type:{desc}", locator.type, str(text), delay=35, timeout=timeout_ms)

        _exec_active_stage_touch("EXEC_UI_FILL_OK", str(desc or "")[:180])
        try:
            _pin("EXEC_STEP", mod="EXEC", step="UI_FILL_OK", coin="*", desc=str(desc or "")[:180])
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

        return True
    except PlaywrightTimeoutError:
        _exec_log(f"填入超时：{desc}")
        try:
            _pin("EXEC_STEP", mod="EXEC", step="UI_FILL_FAIL", coin="*", desc=str(desc or "")[:180], reason="timeout")
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)
        return False
    except Exception as e:
        _exec_log(f"填入失败：{desc} | err（错误）={e}")
        try:
            _pin("EXEC_STEP", mod="EXEC", step="UI_FILL_FAIL", coin="*", desc=str(desc or "")[:180], reason=f"exc:{type(e).__name__}")
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)
        return False

