def _exec_wait_btn_enabled(
    page_or_btn,
    selector_or_label: str | None = None,
    timeout_ms: int = 1800,
    *,
    timeout_s: float | None = None,
    label: str | None = None,
    **kwargs,
) -> bool:
    """执行器“条件等待”辅助：等待按钮/元素变为可点击（enabled + visible）。

    兼容两种调用口径（修复你日志里 TypeError: unexpected keyword argument 'timeout_s'）：
    1) 旧版（页面+selector）：
        _exec_wait_btn_enabled(page, "css=...", timeout_ms=1800)
    2) 执行器里常见（locator+label）：
        _exec_wait_btn_enabled(btn_locator, "等待提交按钮解灰", timeout_s=8.0)

    规则：
    - 优先尝试 is_enabled/is_visible；
    - 若 is_enabled 抛异常，回退到 disabled / aria-disabled / data-disabled 判定；
    - 轮询等待时 **每次 sleep >= 1.05s**（满足你“最短 >1s”的要求，避免抖动过密）。
    """
    try:
        if timeout_s is not None:
            try:
                timeout_ms = int(float(timeout_s) * 1000.0)
            except Exception:
                timeout_ms = timeout_ms
        try:
            tout_ms = max(50, int(timeout_ms or 0))
        except Exception:
            tout_ms = 1800

        def _is_locator_like(x) -> bool:
            try:
                return (x is not None) and callable(getattr(x, "count", None)) and callable(getattr(x, "get_attribute", None))
            except Exception:
                return False

        def _is_disabled_any(loc) -> bool:
            try:
                if _pw_locator_attr(loc, "disabled", "exec.wait_btn") is not None:
                    return True
            except Exception as _e:
                _log_exc_level(mod="EXEC", stage="WAIT_BTN_DISABLED_ATTR_FAIL", level="C", e=_e)

            try:
                aria = (str(_pw_locator_attr(loc, "aria-disabled", "exec.wait_btn") or "")).strip().lower()
                if aria in ("true", "1", "yes"):
                    return True
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

            try:
                ds = (str(_pw_locator_attr(loc, "data-disabled", "exec.wait_btn") or "")).strip().lower()
                if ds in ("true", "1", "disabled"):
                    return True
            except Exception as _e:
                _log_exc_level(mod="EXEC", stage="WAIT_BTN_DATA_DISABLED_ATTR_FAIL", level="C", e=_e)

            return False

        if _is_locator_like(page_or_btn):
            btn = page_or_btn
            lbl = str(selector_or_label or label or "WAIT_BTN_ENABLED")
        else:
            page = page_or_btn
            selector = str(selector_or_label or "")
            if page is None or not selector:
                return False
            btn = page.locator(selector).first
            lbl = str(label or selector or "WAIT_BTN_ENABLED")

        t0 = time.time()
        poll_s = 1.05  # 强制最短 >1s
        while (time.time() - t0) * 1000.0 <= float(tout_ms):
            try:
                if btn is not None and _pw_locator_count(btn, "exec.wait_btn") > 0:
                    try:
                        try:
                            if _pw_locator_visible(btn, "exec.wait_btn", timeout=200):
                                try:
                                    if _pw_locator_enabled(btn, "exec.wait_btn"):
                                        return True
                                except Exception:
                                    if not _is_disabled_any(btn):
                                        return True
                        except Exception:
                            if not _is_disabled_any(btn):
                                return True
                    except Exception as _e:
                        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

            try:
                now = time.time()
                if (now - t0) >= 0 and int((now - t0) // 3) != int((now - t0 - poll_s) // 3):
                    try:
                        safe_log(lambda: f"[{_exec_ts()}] [EXECUTOR（执行器）] Wait（按钮解灰）: {lbl} | elapse={now-t0:.1f}s/{tout_ms/1000.0:.1f}s")
                    except Exception as _e:
                        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

            try:
                time.sleep(poll_s)
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

        return False
    except Exception:
        return False

def _exec_wait_input_ready(
    locator,
    label: str,
    timeout_ms: int = 6000,
    *,
    timeout_s: float | None = None,
) -> tuple[bool, dict]:
    """等待输入框真正可用：visible + enabled + editable。"""
    try:
        if timeout_s is not None:
            try:
                timeout_ms = int(float(timeout_s) * 1000.0)
            except Exception:
                pass
        tout_ms = max(300, int(timeout_ms or 0))
        t0 = time.time()
        last_det: dict = {"reason": "not_checked"}
        last_log_bucket = -1
        while (time.time() - t0) * 1000.0 <= float(tout_ms):
            det = {
                "visible": False,
                "enabled": False,
                "editable": False,
                "disabled_attr": None,
                "readonly_attr": None,
                "aria_disabled": None,
                "reason": "not_ready",
            }
            try:
                if locator is not None and _pw_locator_count(locator, "exec.wait_input") > 0:
                    det["visible"] = bool(_pw_locator_visible(locator, "exec.wait_input", timeout=250))
                    try:
                        det["enabled"] = bool(_pw_locator_enabled(locator, "exec.wait_input"))
                    except Exception:
                        det["enabled"] = False
                    try:
                        det["editable"] = bool(_pw_locator_editable(locator, "exec.wait_input"))
                    except Exception:
                        det["editable"] = False
                    try:
                        det["disabled_attr"] = _pw_locator_attr(locator, "disabled", "exec.wait_input")
                    except Exception:
                        det["disabled_attr"] = None
                    try:
                        det["readonly_attr"] = _pw_locator_attr(locator, "readonly", "exec.wait_input")
                    except Exception:
                        det["readonly_attr"] = None
                    try:
                        det["aria_disabled"] = _pw_locator_attr(locator, "aria-disabled", "exec.wait_input")
                    except Exception:
                        det["aria_disabled"] = None
                    if det["visible"] and det["enabled"] and det["editable"] and det["disabled_attr"] is None:
                        det["reason"] = "ready"
                        return True, det
                    if not det["visible"]:
                        det["reason"] = "not_visible"
                    elif not det["enabled"]:
                        det["reason"] = "not_enabled"
                    elif not det["editable"]:
                        det["reason"] = "not_editable"
                    elif det["disabled_attr"] is not None:
                        det["reason"] = "disabled_attr_present"
                else:
                    det["reason"] = "locator_missing"
            except _UiDeadError:
                raise
            except Exception as _e:
                det = {"reason": f"exception:{type(_e).__name__}"}
            last_det = dict(det or {})
            try:
                bucket = int((time.time() - t0) // 2)
                if bucket != last_log_bucket:
                    last_log_bucket = bucket
                    safe_log(lambda: f"[{_exec_ts()}] [EXECUTOR（执行器）] Wait（输入框就绪）: {label} | elapsed={time.time()-t0:.1f}s/{tout_ms/1000.0:.1f}s | det={last_det}")
            except Exception:
                pass
            try:
                time.sleep(0.18)
            except Exception:
                break
        return False, dict(last_det or {})
    except Exception as _e:
        return False, {"reason": f"wait_input_ready_exception:{type(_e).__name__}", "err": str(_e)[:160]}

@dataclass
class _ExecOrder:
    platform: str   # "ext" / "var"
    side: str       # "buy" / "sell"
    usd: float
    coin: str
    reduce_only: bool = False  # ReduceOnly（只减仓/只平仓）

    guard_has_position: bool = False          # 执行前是否确认有仓（快照）
    guard_pos_side_ls: str = ""               # 执行前持仓方向 LONG/SHORT（快照）
    guard_pos_notional_u: float = 0.0         # 执行前持仓名义（快照）
    guard_note: str = ""                      # 记录来源（例如 tp_step2）

    module: str = ""
    action_type: str = ""
    trace_id: str = ""
    meta: Dict[str, Any] = field(default_factory=dict)

def _exec_attach_order_ctx(order: Any, req: Any = None) -> None:
    """把 Request 的 module/meta/trace/指标挂到 _ExecOrder 上，供执行器落盘/面板摘要使用。"""
    try:
        if order is None:
            return
        mod = ""
        act = ""
        meta: dict = {}
        if req is not None:
            try:
                if isinstance(req, dict):
                    mod = str(req.get("module") or "").strip()
                    act = str(req.get("action_type") or req.get("action") or "").strip()
                    m0 = req.get("meta")
                    if isinstance(m0, dict):
                        meta = dict(m0)
                else:
                    mod = str(getattr(req, "module", "") or "").strip()
                    act = str(getattr(req, "action_type", "") or "").strip()
                    m0 = getattr(req, "meta", None)
                    if isinstance(m0, dict):
                        meta = dict(m0)
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_1213', _e)
                pass
        try:
            if req is not None:
                setattr(order, '_exec_req_ref', req)
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_1214', _e)
            pass
        try:
            if mod and not str(getattr(order, "module", "") or "").strip():
                setattr(order, "module", mod)
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_1215', _e)
            pass
        try:
            if act and not str(getattr(order, "action_type", "") or "").strip():
                setattr(order, "action_type", act)
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_1216', _e)
            pass
        try:
            if isinstance(meta, dict) and meta:
                om = getattr(order, "meta", None)
                if isinstance(om, dict):
                    for k, v in meta.items():
                        if k not in om:
                            om[k] = v
                    setattr(order, "meta", om)
                else:
                    setattr(order, "meta", dict(meta))
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_1217', _e)
            pass
        try:
            tid = ""
            om = getattr(order, "meta", None)
            if isinstance(om, dict):
                tid = str(om.get("trace_id") or om.get("trace") or "")
            if not tid:
                tid = str(getattr(order, "trace_id", "") or "")
            if not tid:
                try:
                    tid = _get_current_trace_id()
                except Exception:
                    tid = ""
            if not tid:
                try:
                    tid = _trace_make(str(getattr(order, "module", "") or "EXEC"), str(getattr(order, "coin", "") or ""))
                except Exception:
                    tid = ""
            if tid:
                try:
                    setattr(order, "trace_id", tid)
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_1218', _e)
                    pass
                try:
                    om = getattr(order, "meta", None)
                    if isinstance(om, dict) and not om.get("trace_id"):
                        om["trace_id"] = tid
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_1219', _e)
                    pass
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_1220', _e)
            pass
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_1221', _e)
        pass
class _ExtExecutor:
    def __init__(self, page, timeout_ms: int = 15000):
        self.page = page
        self.timeout_ms = timeout_ms

    def _page_context(self):
        try:
            ctx = getattr(self.page, 'context', None)
            return ctx() if callable(ctx) else ctx
        except Exception:
            return None

    def _rebind_page(self, new_page) -> bool:
        try:
            if new_page is None:
                return False
            self.page = new_page
            return True
        except Exception:
            return False

    def _reopen_coin_tab(self, coin: str, *, reason: str = "") -> bool:
        coin_u = _exec_normalize_coin(coin)
        try:
            _allow_reopen, _reopen_gate_rsn = _refresh_reason_guard(
                reason=str(reason or ''),
                evidence=str(reason or ''),
                where=f"ext_reopen_coin_tab.{coin_u}",
                light=False,
                platform='EXT',
            )
        except Exception:
            _allow_reopen, _reopen_gate_rsn = False, 'ext_reopen_gate_exc'
        if not _allow_reopen:
            try:
                _exec_log(f"EXT（平台）禁止自愈重进：缺少硬异常证据 | coin={coin_u} reason={reason} gate={_reopen_gate_rsn}")
            except Exception:
                pass
            return False
        ctx = self._page_context()
        if ctx is None:
            _exec_log(f"EXT（平台）自愈失败：context 缺失，无法新建标签页重进 | coin={coin_u} reason={reason}")
            return False
        try:
            newp, rsn = _rebuild_single_page_in_context(ctx, target_url=ext_market_url(coin_u or 'BTC'), platform='EXT', coin=coin_u or 'BTC', expected_url_keywords=['extended.exchange', '/perp/'], timeout_ms=max(12000, int(self.timeout_ms or 15000)))
        except Exception as e:
            newp, rsn = None, f'rebuild_exc:{type(e).__name__}:{e}'
        if newp is None:
            _exec_log(f"EXT（平台）自愈失败：新建标签页重进失败 | coin={coin_u} reason={reason} rsn={rsn}")
            return False
        self._rebind_page(newp)
        try:
            _exec_log(f"EXT（平台）自愈：报错后新建标签页重进 | coin={coin_u} reason={reason} rsn={rsn or 'ok'}")
        except Exception:
            pass
        try:
            return bool(_exec_goto_coin_ext(self.page, coin_u, self.timeout_ms, exec_privilege=True, privilege_reason="ext_reopen_coin_tab"))
        except Exception:
            return False

    def loc_value_input(self):
        return self.page.locator('div[data-scope="input"][data-part="group"]:has(label:has-text("Value")) input[data-scope="input"][data-part="input"]')

    def loc_size_input(self):
        return self.page.locator('div[data-scope="input"][data-part="group"]:has(label:has-text("Size")) input[data-scope="input"][data-part="input"]')

    def _find_submit_button_struct_meta(self, side: str) -> dict:
        want = "Buy" if str(side or "").lower().strip().startswith("buy") else "Sell"
        js = r'''(sideText) => {
  const want = String(sideText || '').trim();
  const norm = (s) => String(s || '').replace(/\\s+/g, ' ').trim();
  const isVisible = (el) => {
    try {
      const r = el.getBoundingClientRect();
      const cs = window.getComputedStyle(el);
      return !!r && r.width >= 40 && r.height >= 20 && cs && cs.display !== 'none' && cs.visibility !== 'hidden' && Number(cs.opacity || '1') > 0.05;
    } catch (_) { return false; }
  };
  const isDisabled = (el) => {
    try {
      const aria = String(el.getAttribute('aria-disabled') || '').trim().toLowerCase();
      const data = String(el.getAttribute('data-disabled') || '').trim().toLowerCase();
      return el.hasAttribute('disabled') || ['true','1','yes'].includes(aria) || ['true','1','disabled'].includes(data);
    } catch (_) { return false; }
  };
  const isButtonish = (el) => {
    try {
      const tag = String(el.tagName || '').toLowerCase();
      const cls = String(el.className || '').toLowerCase();
      const role = String(el.getAttribute('role') || '').toLowerCase();
      return tag === 'button' || role === 'button' || cls.includes('button') || cls.includes('btn') || !!el.onclick;
    } catch (_) { return false; }
  };
  const actionTarget = (el) => {
    let cur = el;
    for (let i = 0; i < 5 && cur; i += 1, cur = cur.parentElement) {
      if (isButtonish(cur) && isVisible(cur)) return cur;
    }
    return el;
  };
  const valueGroup = [...document.querySelectorAll('div[data-scope="input"][data-part="group"]')].find((g) => /Value/i.test(norm(g.innerText || g.textContent || '')));
  let panel = null;
  if (valueGroup) {
    let cur = valueGroup;
    for (let i = 0; i < 8 && cur; i += 1, cur = cur.parentElement) {
      const txt = norm(cur.innerText || cur.textContent || '');
      if (/\bBuy\b/i.test(txt) && /\bSell\b/i.test(txt)) { panel = cur; break; }
    }
  }
  const roots = [];
  if (panel) roots.push(panel);
  roots.push(document.body);
  let best = null;
  for (const root of roots) {
    const elements = [root, ...root.querySelectorAll('*')];
    for (const raw of elements) {
      const txt0 = norm(raw.innerText || raw.textContent || '');
      if (!txt0) continue;
      const exact = txt0 === want;
      const loose = !exact && (txt0.includes(want) || txt0.split(' ')[0] === want || txt0.split('\n')[0] === want);
      if (!exact && !loose) continue;
      const el = actionTarget(raw);
      if (!isVisible(el)) continue;
      const r = el.getBoundingClientRect();
      const cs = window.getComputedStyle(el);
      const cx = r.left + r.width / 2;
      const cy = r.top + r.height / 2;
      let topEl = null;
      try { topEl = document.elementFromPoint(cx, cy); } catch (_) {}
      let covers = false;
      if (topEl) covers = !(topEl === el || el.contains(topEl) || topEl.contains(el));
      let score = 0;
      if (root === panel) score += 1200;
      if (exact) score += 300; else if (loose) score += 180;
      if (String(el.tagName || '').toLowerCase() === 'button') score += 180;
      if (String(el.getAttribute('role') || '').toLowerCase() === 'button') score += 140;
      if (String(el.className || '').toLowerCase().includes('button') || String(el.className || '').toLowerCase().includes('btn')) score += 100;
      if (!isDisabled(el)) score += 140;
      if (String(cs.pointerEvents || '').toLowerCase() !== 'none') score += 120;
      if (!covers) score += 120;
      if (r.width >= 90) score += 80;
      if (r.height >= 32) score += 50;
      score += Math.max(0, Math.min(500, Math.round(r.top)));
      const candidate = {
        ok: true,
        text: txt0.slice(0, 120),
        tag: String(el.tagName || '').toLowerCase(),
        className: String(el.className || '').slice(0, 240),
        left: Math.round(r.left),
        top: Math.round(r.top),
        width: Math.round(r.width),
        height: Math.round(r.height),
        cx: Math.round(cx),
        cy: Math.round(cy),
        disabled: isDisabled(el),
        pointerBlocked: String(cs.pointerEvents || '').toLowerCase() === 'none',
        covered: !!covers,
        exact: !!exact,
        fromPanel: root === panel,
        score,
      };
      if (!best || candidate.score > best.score) best = candidate;
    }
    if (best && best.fromPanel && best.exact && !best.disabled && !best.pointerBlocked) break;
  }
  return best || {ok:false, want};
}'''
        try:
            meta = _pw_call(f"ext.submit_btn.struct_meta[{want}]", self.page.evaluate, js, want) or {}
            if isinstance(meta, dict):
                return meta
        except Exception as _e:
            _log_exc_level(mod="EXEC", stage="EXT_SUBMIT_BTN_STRUCT_META_FAIL", level="B", e=_e)
        return {"ok": False, "want": want}

    def _submit_button_struct_ready(self, side: str, *, coin: str = "", meta: dict | None = None) -> tuple[bool, str, dict]:
        meta = dict(meta or self._find_submit_button_struct_meta(side) or {})
        try:
            _exec_log(f"EXT（平台）结构化提交按钮检查 | side={str(side or '').upper()} meta={meta}", coin=coin)
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)
        if not bool(meta.get("ok")):
            return False, "submit_btn_not_found", meta
        if bool(meta.get("disabled")):
            return False, "submit_btn_disabled", meta
        if bool(meta.get("pointerBlocked")):
            return False, "submit_btn_pointer_blocked", meta
        if bool(meta.get("covered")):
            return False, "submit_btn_covered", meta
        try:
            x = float(meta.get("cx"))
            y = float(meta.get("cy"))
            w = float(meta.get("width") or 0.0)
            h = float(meta.get("height") or 0.0)
            if x <= 0 or y <= 0 or w < 40 or h < 20:
                return False, "submit_btn_bad_bbox", meta
        except Exception:
            return False, "submit_btn_bad_bbox", meta
        _ctx_ok, _ctx_det = _ext_market_context_matches_request(coin, page=self.page)
        if not _ctx_ok:
            try:
                _exec_log(f"EXT（平台）结构化提交按钮阻断：市场上下文不匹配 | side={str(side or '').upper()} det={_ctx_det}", coin=coin)
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)
            meta = dict(meta or {})
            meta['market_ctx'] = dict(_ctx_det or {})
            return False, "submit_btn_market_context_mismatch", meta
        return True, "ok", meta

    def _click_submit_button_struct_fallback(self, side: str, *, coin: str = "", meta: dict | None = None) -> bool:
        ready, reason, meta = self._submit_button_struct_ready(side, coin=coin, meta=meta)
        if not ready:
            try:
                _exec_log(f"EXT（平台）结构化提交按钮不可点 | side={str(side or '').upper()} reason={reason} meta={meta}", coin=coin)
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)
            return False
        try:
            x = float(meta.get("cx"))
            y = float(meta.get("cy"))
        except Exception:
            return False
        try:
            _ctx_ok_click, _ctx_det_click = _ext_market_context_matches_request(coin, page=self.page)
            if not _ctx_ok_click:
                try:
                    _exec_log(f"EXT（平台）结构化点击提交前阻断：市场上下文不匹配 | side={str(side or '').upper()} det={_ctx_det_click}", coin=coin)
                except Exception:
                    pass
                return False
            _pw_call(f"ext.submit_btn.struct_click_move[{side}]", self.page.mouse.move, x, y)
            _pw_call(f"ext.submit_btn.struct_click[{side}]", self.page.mouse.click, x, y, delay=60)
            _exec_step_sleep(f"EXT（平台）结构化点击 {str(side or '').upper()} 后等待", 0.18, 0.36)
            return True
        except Exception as _e:
            _log_exc_level(mod="EXEC", stage="EXT_SUBMIT_BTN_STRUCT_CLICK_FAIL", level="B", e=_e, plat="EXT", coin=str(coin or ""))
            return False

    def loc_submit_button(self, side: str):
        side_s = str(side or '').lower().strip()
        word = "Buy" if side_s == "buy" else "Sell"
        selectors = [
            f'button[data-scope="tooltip"][data-part="trigger"]:has(span:has-text("{word}"))',
            f'button[data-scope="tooltip"]:has(span:has-text("{word}"))',
            f'button[data-part="trigger"]:has(span:has-text("{word}"))',
            f'button:has(span:has-text("{word}"))',
            f'button:has-text("{word}")',
        ]
        for sel in selectors:
            try:
                cand = self.page.locator(sel)
                if cand.count() > 0:
                    return cand
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)
                continue
        return self.page.locator(selectors[0])

    def _settle_value_input_for_submit(self, inp, val_str: str = "") -> None:
        try:
            _pw_call("ext_executor.value_settle.dispatch_input", inp.dispatch_event, "input")
            _pw_call("ext_executor.value_settle.dispatch_change", inp.dispatch_event, "change")
            _pw_call("ext_executor.value_settle.enter", inp.press, "Enter")
            _pw_call("ext_executor.value_settle.tab", inp.press, "Tab")
        except Exception:
            pass
        try:
            _exec_step_sleep("EXT（平台）Value 输入稳定等待", 0.12, 0.28)
        except Exception:
            pass

    def _wait_submit_button_direct(self, side: str, *, coin: str = "", timeout_ms: int = 2500):
        btn_set = self.loc_submit_button(side)
        t0 = time.time()
        last_err = None
        last_state = {}
        side_norm = 'buy' if str(side or '').lower().strip().startswith('buy') else 'sell'
        while (time.time() - t0) * 1000.0 < max(500, int(timeout_ms or 0)):
            try:
                _cnt = 0
                try:
                    _cnt = int(btn_set.count())
                except Exception:
                    _cnt = 0
                if _cnt > 0:
                    _max_scan = min(_cnt, 8)
                    for _i in range(_max_scan):
                        try:
                            cur = btn_set.nth(_i)
                        except Exception:
                            continue
                        try:
                            cur.scroll_into_view_if_needed(timeout=500)
                        except Exception:
                            pass
                        visible = False
                        text0 = ""
                        try:
                            visible = bool(cur.is_visible())
                        except Exception:
                            visible = False
                        try:
                            text0 = (cur.text_content() or '').strip()
                        except Exception:
                            text0 = ''
                        _text_norm = str(text0 or '').strip().lower()
                        _text_mismatch = bool(_text_norm) and (side_norm not in _text_norm)
                        last_state = {
                            'idx': _i,
                            'visible': visible,
                            'text': text0[:80],
                            'count': _cnt,
                            'block_reason': ('not_visible' if (not visible) else ('text_mismatch' if _text_mismatch else 'ready')),
                        }
                        if visible and (not _text_mismatch):
                            try:
                                _exec_log(f"[PIN][BTN_STATE] EXT 提交按钮放行 | side={str(side or '').upper()} state={last_state}", coin=coin)
                            except Exception:
                                pass
                            return cur
            except Exception as _e:
                last_err = _e
            time.sleep(0.10)
        try:
            _exec_log(f"EXT（平台）{str(side or '').upper()} 提交按钮等待失败 | state={last_state} err={repr(last_err)}", coin=coin)
        except Exception:
            pass
        return None

    def _submit_click_guard_round_no(self) -> int:
        try:
            return int(globals().get('_PIN_ROUND') or 0)
        except Exception:
            return 0

    def _submit_click_guard_key(self, side: str, *, coin: str = "") -> str:
        _round_no = self._submit_click_guard_round_no()
        return f"EXT|{str(coin or '').upper().strip()}|R{int(_round_no or 0)}"

    def _submit_click_guard_acquire(self, side: str, *, coin: str = "", cooldown_s: float = 2.5) -> tuple[bool, dict]:
        try:
            now = float(time.time())
        except Exception:
            now = 0.0
        _round_no = self._submit_click_guard_round_no()
        key = self._submit_click_guard_key(side, coin=coin)
        guard = getattr(self, '_ext_submit_click_guard', None)
        if not isinstance(guard, dict):
            guard = {}
            try:
                setattr(self, '_ext_submit_click_guard', guard)
            except Exception:
                pass
        prev = dict(guard.get(key) or {}) if isinstance(guard.get(key), dict) else {}
        if prev:
            return False, {'key': key, 'round_no': int(_round_no or 0), 'prev': prev, 'reason': 'same_coin_already_clicked_this_round'}
        payload = {'ts': now, 'state': 'inflight', 'coin': str(coin or '').upper().strip(), 'side': str(side or '').lower().strip(), 'round_no': int(_round_no or 0)}
        guard[key] = payload
        return True, payload

    def _submit_click_guard_release(self, side: str, *, coin: str = "", state: str = "done") -> None:
        key = self._submit_click_guard_key(side, coin=coin)
        try:
            guard = getattr(self, '_ext_submit_click_guard', None)
            if not isinstance(guard, dict):
                return
            payload = dict(guard.get(key) or {}) if isinstance(guard.get(key), dict) else {'coin': str(coin or '').upper().strip(), 'side': str(side or '').lower().strip(), 'round_no': self._submit_click_guard_round_no()}
            payload['ts'] = float(time.time())
            payload['state'] = str(state or 'done')
            guard[key] = payload
        except Exception:
            return

    def _detect_submit_signal_after_click(self, btn: Any, side: str, *, coin: str = "", observe_ms: int = 1500) -> tuple[bool, dict]:
        det = {'signal_seen': False, 'reason': '', 'samples': []}
        if btn is None:
            det['reason'] = 'btn_missing'
            return False, det
        want = 'buy' if str(side or '').lower().strip().startswith('buy') else 'sell'
        t0 = time.time()
        while (time.time() - t0) * 1000.0 < max(200, int(observe_ms or 0)):
            sample = {}
            try:
                sample['visible'] = bool(btn.is_visible())
            except Exception:
                sample['visible'] = False
            try:
                sample['enabled'] = bool(btn.is_enabled())
            except Exception:
                sample['enabled'] = False
            try:
                sample['disabled_attr'] = btn.get_attribute('disabled')
            except Exception:
                sample['disabled_attr'] = None
            try:
                sample['aria_disabled'] = btn.get_attribute('aria-disabled')
            except Exception:
                sample['aria_disabled'] = None
            try:
                sample['data_loading'] = btn.get_attribute('data-loading')
            except Exception:
                sample['data_loading'] = None
            try:
                sample['text'] = (btn.text_content() or '').strip()[:80]
            except Exception:
                sample['text'] = ''
            loading = str(sample.get('data_loading') or '').strip().lower()
            aria = str(sample.get('aria_disabled') or '').strip().lower()
            disabled = sample.get('disabled_attr')
            if loading in ('true', '1', 'yes', 'loading'):
                det.update({'signal_seen': True, 'reason': 'button_loading', 'sample': sample})
                return True, det
            if disabled is not None or aria in ('true', '1', 'yes'):
                det.update({'signal_seen': True, 'reason': 'button_disabled_after_click', 'sample': sample})
                return True, det
            txt = str(sample.get('text') or '').lower()
            if txt and want not in txt:
                det.update({'signal_seen': True, 'reason': 'button_text_changed_after_click', 'sample': sample})
                return True, det
            try:
                toast_txt = _exec_find_toast_text(self.page)
            except Exception:
                toast_txt = ''
            if toast_txt:
                det.update({'signal_seen': True, 'reason': 'toast_seen_after_click', 'toast': str(toast_txt)[:160], 'sample': sample})
                return True, det
            det['samples'].append(sample)
            if len(det['samples']) > 4:
                det['samples'] = det['samples'][-4:]
            time.sleep(0.12)
        det['reason'] = 'no_submit_signal_observed'
        return False, det

    def _wait_ext_submit_button_ready(self, btn: Any, side: str, *, coin: str = "", timeout_ms: int = 3200) -> tuple[bool, dict]:
        det = {'samples': [], 'ready_seen_count': 0, 'ready_last_sample': None}
        if btn is None:
            det['reason'] = 'btn_none'
            return False, det
        deadline = time.time() + max(0.8, float(timeout_ms or 3200) / 1000.0)
        stable_need = 2
        stable = 0
        while time.time() < deadline:
            sample = {}
            try:
                sample['visible'] = bool(btn.is_visible(timeout=250))
            except Exception:
                sample['visible'] = False
            try:
                sample['enabled'] = bool(btn.is_enabled(timeout=250))
            except Exception:
                sample['enabled'] = False
            try:
                sample['disabled_attr'] = (_pw_call('ext.submit_btn.get_disabled_attr', btn.get_attribute, 'disabled', timeout=250) or '')
            except Exception:
                sample['disabled_attr'] = ''
            try:
                sample['aria_disabled'] = str((_pw_call('ext.submit_btn.get_aria_disabled', btn.get_attribute, 'aria-disabled', timeout=250) or '')).strip().lower()
            except Exception:
                sample['aria_disabled'] = ''
            try:
                sample['data_loading'] = str((_pw_call('ext.submit_btn.get_data_loading', btn.get_attribute, 'data-loading', timeout=250) or '')).strip().lower()
            except Exception:
                sample['data_loading'] = ''
            ready = bool(sample['visible'] and sample['enabled'] and not sample['disabled_attr'] and sample['aria_disabled'] not in ('true', '1') and sample['data_loading'] not in ('true', '1', 'loading'))
            sample['ready'] = ready
            det['samples'].append(sample)
            if len(det['samples']) > 8:
                det['samples'] = det['samples'][-8:]
            if ready:
                det['ready_seen_count'] = int(det.get('ready_seen_count') or 0) + 1
                det['ready_last_sample'] = dict(sample)
                stable += 1
                if stable >= stable_need:
                    try:
                        _exec_log(f"[PIN][EXT_SUBMIT_READY] side={str(side or '').upper()} ready=1 samples={det['samples'][-2:]}", coin=coin)
                    except Exception:
                        pass
                    det['reason'] = 'ready_stable'
                    return True, det
            else:
                stable = 0
            time.sleep(0.12)
        if int(det.get('ready_seen_count') or 0) > 0:
            det['reason'] = 'ready_seen_softpass'
            try:
                _exec_log(f"[PIN][EXT_SUBMIT_READY_SOFTPASS] side={str(side or '').upper()} det={det}", coin=coin)
            except Exception:
                pass
            return True, det
        det['reason'] = 'ready_wait_failed'
        try:
            _exec_log(f"[PIN][EXT_SUBMIT_READY] side={str(side or '').upper()} ready=0 det={det}", coin=coin)
        except Exception:
            pass
        return False, det

    def _click_submit_button_direct(self, btn: Any, side: str, *, coin: str = "", order=None, pre_row=None, usd=0.0) -> bool:
        if btn is None or not _ext_market_context_matches_request(coin, page=self.page)[0]:
            if order is not None:
                _submit_attempt_set(order, 'BLOCKED', 'submit_target_not_ready')
            return False
        if order is not None and not _submit_margin_precheck(btn, order, 'EXT'):
            return False
        guard_ok, guard_detail = self._submit_click_guard_acquire(side, coin=coin)
        if not guard_ok:
            if order is not None:
                _submit_attempt_set(order, 'BLOCKED', 'submit_click_guard_blocked')
            return False
        ready, ready_detail = self._wait_ext_submit_button_ready(btn, side, coin=coin, timeout_ms=3200)
        if not ready:
            if order is not None:
                _submit_attempt_set(order, 'BLOCKED', 'submit_btn_disabled')
            self._submit_click_guard_release(side, coin=coin, state='ready_wait_failed')
            return False
        if order is not None:
            held_side = _exec_row_side_notional(pre_row)[0] if bool(getattr(order, 'reduce_only', False)) else ('LONG' if str(side).lower() == 'buy' else 'SHORT')
            clicked = _submit_order_click(btn, order, 'EXT', held_side, pre_row, usd, 1800, 'EXT:' + str(side))
        else:
            clicked = _safety_click_submit_once(btn, 1800, 'EXT:' + str(side))
        self._submit_click_guard_release(side, coin=coin, state='clicked_pending_confirmation' if clicked else 'click_outcome_unknown')
        return bool(clicked)

    def ensure_usd_unit(self) -> bool:
        """核验 Value（金额）输入框右侧单位为 USD（美元/U）"""
        try:
            unit = self.page.locator('div[data-scope="input"][data-part="group"]:has(label:has-text("Value")) div[data-scope="input"][data-part="right-side"]').first
            _pw_call("ext.ensure_usd_unit.wait_visible", unit.wait_for, state="visible", timeout=5000)
            txt = (_pw_call("ext.ensure_usd_unit.text", unit.text_content, timeout=1000) or "").strip().upper()
            if "USD" in txt:
                _exec_log("EXT（平台）单位核验通过：USD（美元/U）")
                return True
            _exec_log(f"EXT（平台）单位核验失败：读取到单位={txt!r}")
            return False
        except Exception as e:
            _exec_log(f"EXT（平台）单位核验失败：未找到 USD（美元/U）标识 | err（错误）={repr(e)}")
            return False

    def try_switch_market_mode(self) -> None:
        """若在 Limit（限价）导致按钮灰，尝试切到 Market（市价）。"""
        try:
            for loc in [
                self.page.locator("button:has-text('Market')"),
                self.page.locator("div[role='tab']:has-text('Market')"),
                self.page.locator("[data-state]:has-text('Market')"),
            ]:
                if _pw_locator_count(loc, "ext.market_mode.loc") <= 0:
                    continue
                btn = loc.first
                try:
                    if (not _pw_locator_visible(btn, "ext.market_mode.btn", timeout=200)) or _pw_call("ext.market_mode.btn.disabled", btn.is_disabled):
                        continue
                except Exception as _e:
                    _log_exc_level(mod="EXEC", stage="EXT_MARKET_MODE_STATE_CHECK", level="B", e=_e)

                _exec_log("EXT（平台）尝试切换到 Market（市价）模式")
                _pw_call("exec.ext.market_mode.click", btn.click, timeout=3000)
                _exec_step_sleep("EXT（平台）切到 Market（市价） 后等待", _exec_cfg_float("EXEC_EXT_MARKET_SWITCH_WAIT_LO", 0.35), _exec_cfg_float("EXEC_EXT_MARKET_SWITCH_WAIT_HI", 0.90))
                return
        except Exception:
            return

    def ensure_reduce_only(self, desired: bool) -> bool:
        """尽力确保 ReduceOnly（只减仓/只平仓）开关状态。
        desired=True 时必须确认成功，否则返回 False（避免把减仓下成开仓）。
        desired=False 为 best-effort（尽力关闭），失败也返回 True。
        """
        try:
            sels = [
                # [PATCH] EXT 改版：<label data-scope="checkbox" data-part="root" data-state="checked|unchecked">…Reduce-only…</label>
                'label[data-scope="checkbox"][data-part="root"]:has-text("Reduce")',
                'text=/Reduce[\\s-]*Only/i',
                'text=/Reduce\\s*Only\\s*Order/i',
                'label:has-text("Reduce")',
                'button:has-text("Reduce")',
                '[role="switch"]:has-text("Reduce")',
                '[data-part]:has-text("Reduce")',
            ]
            for sel in sels:
                loc = self.page.locator(sel).first
                try:
                    if _pw_locator_count(loc, f"ext.switch_like[{sel}]") <= 0:
                        continue
                except Exception:
                    continue
                try:
                    _pw_call(f"ext.switch_like[{sel}].wait_visible", loc.wait_for, state='visible', timeout=1200)
                except Exception:
                    continue

                def _read_state() -> object:
                    try:
                        aria = (_pw_locator_attr(loc, 'aria-checked', f"ext.switch_like[{sel}].aria") or '').strip().lower()
                        if aria in ('true','1'): return True
                        if aria in ('false','0'): return False
                    except Exception as _e:
                        _log_exc_level(mod="EXEC", stage="EXT_REDUCE_ONLY_ARIA_READ", level="C", e=_e)

                    try:
                        ds = (_pw_locator_attr(loc, 'data-state', f"ext.switch_like[{sel}].data_state") or '').strip().lower()
                        if ds in ('checked','on','true','active'): return True
                        if ds in ('unchecked','off','false','inactive'): return False
                    except Exception as _e:
                        _log_exc_level(mod="EXEC", stage="EXT_REDUCE_ONLY_STATE_READ", level="C", e=_e)

                    try:
                        cb = loc.locator('input[type="checkbox"]').first
                        if _pw_locator_count(cb, f"ext.switch_like[{sel}].checkbox") > 0:
                            return bool(_pw_call(f"ext.switch_like[{sel}].checkbox.checked", cb.is_checked))
                    except Exception as _e:
                        _log_exc_level(mod="EXEC", stage="EXT_REDUCE_ONLY_CHECKBOX_READ", level="C", e=_e)

                    return None

                st = _read_state()
                if st is None:
                    # [PATCH] 状态读不到就换下一个候选，不再盲点（盲点可能把只减仓关掉/开错）
                    continue

                if bool(st) != bool(desired):
                    try:
                        _exec_safe_click(loc, 5000, "UI（界面）点击开关（可能 ReduceOnly/只减仓）")
                        time.sleep(1.05)
                    except Exception as _e:
                        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

                    st2 = _read_state()
                    if st2 is None:
                        return (not desired)
                    if bool(st2) != bool(desired):
                        return (not desired)
                return True
            return (not desired)
        except Exception:
            return (not desired)

    def open_position(self, order: _ExecOrder, dry_run: bool = False) -> bool:
        coin = _exec_normalize_coin(order.coin)
        from bot_core import submission_scope as scope
        _pending_platform = 'VAR' if isinstance(self, _VarExecutor) else 'EXT'
        if not dry_run and _safety_pending_scope(_pending_platform, coin, *scope.order_scope(order)):
            return False
        try:
            _active_req_touch("EXEC_OPEN_VAR_BEGIN" if isinstance(self, _VarExecutor) else "EXEC_OPEN_BEGIN", reason=f"{type(self).__name__}|{coin}")
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_1222', _e)
            pass
        side = _side_map_long_short_to_buy_sell((order.side or "buy"))
        if not side:
            _exec_log(f"EXT（平台）下单方向非法：{order.side!r}（仅支持 buy/sell/long/short）", coin=coin)
            return False
        usd_raw = float(order.usd)
        usd, _usd_rule = _exec_resolve_submit_usd(order)
        if usd <= 0.0:
            _exec_log(f"EXT（平台）拒绝下单：coin（币种）={coin} 原始金额={_fmt_order_u10(usd_raw)} 规则={_usd_rule}（M10第二步只允许向下取整十，不足则等待）", coin=coin)
            return False
        try:
            order.usd = float(usd)
        except Exception:
            pass
        _reduce_ctx = _exec_reduce_pin_ctx_from_order(order, default_action="decrease") if bool(getattr(order, "reduce_only", False)) else {"action": "", "req_id": "", "trace": "", "extra": {}}

        _exec_log(f"EXT（平台）准备下单：coin（币种）={coin} side（方向）={side} usd（金额）={_fmt_order_u10(usd)} raw_usd（原始金额）={_fmt_order_u10(usd_raw)} amount_rule（金额规则）={_usd_rule} reduce_only（只减仓）={getattr(order,'reduce_only',False)}")
        if bool(getattr(order, 'reduce_only', False)):
            _pin_exec_reduce_phase(plat="EXT", coin=coin, step="UI_REDUCE_FLOW_BEGIN", side=side, usd=usd, action=str((_reduce_ctx or {}).get("action") or "decrease"), req_id=str((_reduce_ctx or {}).get("req_id") or ""), trace=str((_reduce_ctx or {}).get("trace") or ""), extra=dict({"mode": "reduce_only"}, **(dict((_reduce_ctx or {}).get("extra") or {}))))
        _flow_t0 = _exec_perf_now()
        _ui_flow_t0 = _exec_ui_flow_begin(order, self.page, "EXT", coin, ("close" if bool(getattr(order, 'reduce_only', False)) else (str(getattr(order, 'action_type', '') or 'open_leg'))))
        _submit_click_ms = None
        _ready_ms = None
        try:
            _exec_refresh_indicators_for_order(order, coin, why="ext_open_position")
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_1223', _e)
            pass
        pre_row = None
        try:
            if bool(getattr(order, 'reduce_only', False)):
                _pin_exec_reduce_phase(plat="EXT", coin=coin, step="UI_LOCATE_POSITION_ROW_BEGIN", side=side, usd=usd, action=str((_reduce_ctx or {}).get("action") or "decrease"), req_id=str((_reduce_ctx or {}).get("req_id") or ""), trace=str((_reduce_ctx or {}).get("trace") or ""), extra=dict({"mode": "reduce_only"}, **(dict((_reduce_ctx or {}).get("extra") or {}))))
            pre_row = _exec_batch_get_pre_row(EXT, coin, page=self.page)
            if bool(getattr(order, 'reduce_only', False)):
                _pin_exec_reduce_phase(plat="EXT", coin=coin, step="UI_LOCATE_POSITION_ROW_OK", side=side, usd=usd, action=str((_reduce_ctx or {}).get("action") or "decrease"), req_id=str((_reduce_ctx or {}).get("req_id") or ""), trace=str((_reduce_ctx or {}).get("trace") or ""), extra=dict({"mode": "reduce_only", "row_found": int(bool(pre_row))}, **(dict((_reduce_ctx or {}).get("extra") or {}))))
        except Exception as _e:
            pre_row = None
            if bool(getattr(order, 'reduce_only', False)):
                _pin_exec_reduce_phase(plat="EXT", coin=coin, step="UI_LOCATE_POSITION_ROW_FAIL", side=side, usd=usd, reason=f"exc:{type(_e).__name__}", action=str((_reduce_ctx or {}).get("action") or "decrease"), req_id=str((_reduce_ctx or {}).get("req_id") or ""), trace=str((_reduce_ctx or {}).get("trace") or ""), extra=dict({"mode": "reduce_only"}, **(dict((_reduce_ctx or {}).get("extra") or {}))))

        try:
            _active_req_touch(("EXEC_REDUCE_EXT_BEGIN" if bool(getattr(order, 'reduce_only', False)) else "EXEC_OPEN_EXT_BEGIN"), reason=f"EXT|{coin}|{side}|{_fmt_order_u10(usd)}")
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_1224', _e)
            pass
        try:
            _pin("EXEC_STEP", mod="EXEC", step="UI_FLOW_BEGIN", coin=str(coin or "").upper(), plat="EXT", action=("reduce_position" if bool(getattr(order, 'reduce_only', False)) else "open_position"))
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)
        _exec_ui_step_begin(order, self.page, "EXT", coin, ("close" if bool(getattr(order, 'reduce_only', False)) else (str(getattr(order, 'action_type', '') or 'open_leg'))), "UI_PAGE_READY")
        _exec_ensure_active_page(self.page, "EXT（平台）开仓")
        _exec_ui_step_ok(order, self.page, "EXT", coin, ("close" if bool(getattr(order, 'reduce_only', False)) else (str(getattr(order, 'action_type', '') or 'open_leg'))), "UI_PAGE_READY")

        if coin:
            _exec_ui_step_begin(order, self.page, "EXT", coin, ("close" if bool(getattr(order, 'reduce_only', False)) else (str(getattr(order, 'action_type', '') or 'open_leg'))), "UI_SYMBOL_READY")
            _goto_exec_priv = bool(getattr(order, 'reduce_only', False))
            _goto_priv_reason = ("reduce_only_exec" if _goto_exec_priv else "open_exec")
            if not _exec_goto_coin_ext(self.page, coin, self.timeout_ms, exec_privilege=_goto_exec_priv, privilege_reason=_goto_priv_reason):
                if bool(getattr(order, 'reduce_only', False)):
                    _pin_exec_flow_terminal(flow="reduce", plat="EXT", coin=coin, action=str((_reduce_ctx or {}).get("action") or "decrease"), outcome="fail", reason="goto_coin_fail", side=side, usd=usd, req_id=str((_reduce_ctx or {}).get("req_id") or ""), trace=str((_reduce_ctx or {}).get("trace") or ""), extra=dict({"mode": "reduce_only"}, **(dict((_reduce_ctx or {}).get("extra") or {}))))
                _set_last_exec_err(reason="goto_coin_fail", err=_safe_str({"page_url": _safe_page_url(self.page), "page_title": _safe_page_title(self.page), "page_text": _safe_page_text(self.page, 300)}, 800), coin=coin, plat="EXT", act=str(getattr(order, 'action_type', '') or ('close' if bool(getattr(order, 'reduce_only', False)) else 'open_position')))
                _exec_ui_step_fail(order, self.page, "EXT", coin, ("close" if bool(getattr(order, 'reduce_only', False)) else (str(getattr(order, 'action_type', '') or 'open_leg'))), "UI_SYMBOL_READY", err="goto_coin_fail")
                _exec_ui_flow_end(order, self.page, "EXT", coin, ("close" if bool(getattr(order, 'reduce_only', False)) else (str(getattr(order, 'action_type', '') or 'open_leg'))), ok=0, fail_reason="goto_coin_fail")
                return False
            try:
                _cur_coin_after_goto = _exec_normalize_coin(_detect_current_coin_ext(self.page) or '')
            except Exception:
                _cur_coin_after_goto = ''
            if _cur_coin_after_goto and (_cur_coin_after_goto != _exec_normalize_coin(coin)):
                _mismatch_reason = f"goto_coin_context_mismatch:req={_exec_normalize_coin(coin)} cur={_cur_coin_after_goto}"
                try:
                    _pin("EXEC_STEP", mod="EXEC", step="UI_SYMBOL_CONTEXT_MISMATCH", coin=str(coin or '').upper(), plat="EXT", ok=0, reason=_mismatch_reason)
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_ext_symbol_mismatch', _e)
                    pass
                if bool(getattr(order, 'reduce_only', False)):
                    _pin_exec_flow_terminal(flow="reduce", plat="EXT", coin=coin, action=str((_reduce_ctx or {}).get("action") or "decrease"), outcome="fail", reason=_mismatch_reason, side=side, usd=usd, req_id=str((_reduce_ctx or {}).get("req_id") or ""), trace=str((_reduce_ctx or {}).get("trace") or ""), extra=dict({"mode": "reduce_only"}, **(dict((_reduce_ctx or {}).get("extra") or {}))))
                _set_last_exec_err(reason=str(_mismatch_reason or 'goto_coin_context_mismatch'), err=_safe_str({"page_url": _safe_page_url(self.page), "page_title": _safe_page_title(self.page), "page_text": _safe_page_text(self.page, 300)}, 800), coin=coin, plat="EXT", act=str(getattr(order, 'action_type', '') or ('close' if bool(getattr(order, 'reduce_only', False)) else 'open_position')))
                _exec_ui_step_fail(order, self.page, "EXT", coin, ("close" if bool(getattr(order, 'reduce_only', False)) else (str(getattr(order, 'action_type', '') or 'open_leg'))), "UI_SYMBOL_READY", err=_mismatch_reason)
                _exec_ui_flow_end(order, self.page, "EXT", coin, ("close" if bool(getattr(order, 'reduce_only', False)) else (str(getattr(order, 'action_type', '') or 'open_leg'))), ok=0, fail_reason=_mismatch_reason)
                return False
            _exec_ui_step_ok(order, self.page, "EXT", coin, ("close" if bool(getattr(order, 'reduce_only', False)) else (str(getattr(order, 'action_type', '') or 'open_leg'))), "UI_SYMBOL_READY")
            _exec_step_sleep("EXT（平台）跳转完成后等待")

        _ctx_ok_guard1, _ctx_det_guard1 = _ext_market_context_matches_request(coin, page=self.page)
        if not _ctx_ok_guard1:
            _guard_reason1 = str((_ctx_det_guard1 or {}).get('reason') or 'market_context_mismatch_before_unit')
            if bool(getattr(order, 'reduce_only', False)):
                _pin_exec_flow_terminal(flow="reduce", plat="EXT", coin=coin, action=str((_reduce_ctx or {}).get("action") or "decrease"), outcome="fail", reason=_guard_reason1, side=side, usd=usd, req_id=str((_reduce_ctx or {}).get("req_id") or ""), trace=str((_reduce_ctx or {}).get("trace") or ""), extra=dict({"mode": "reduce_only", "market_ctx": _ctx_det_guard1}, **(dict((_reduce_ctx or {}).get("extra") or {}))))
            _exec_ui_step_fail(order, self.page, "EXT", coin, ("close" if bool(getattr(order, 'reduce_only', False)) else (str(getattr(order, 'action_type', '') or 'open_leg'))), "UI_SYMBOL_READY", err=_guard_reason1)
            _exec_ui_flow_end(order, self.page, "EXT", coin, ("close" if bool(getattr(order, 'reduce_only', False)) else (str(getattr(order, 'action_type', '') or 'open_leg'))), ok=0, fail_reason=_guard_reason1)
            return False

        if not self.ensure_usd_unit():
            if bool(getattr(order, 'reduce_only', False)):
                _pin_exec_flow_terminal(flow="reduce", plat="EXT", coin=coin, action=str((_reduce_ctx or {}).get("action") or "decrease"), outcome="fail", reason="ensure_usd_unit_fail", side=side, usd=usd, req_id=str((_reduce_ctx or {}).get("req_id") or ""), trace=str((_reduce_ctx or {}).get("trace") or ""), extra=dict({"mode": "reduce_only"}, **(dict((_reduce_ctx or {}).get("extra") or {}))))
            return False
        _exec_step_sleep("EXT（平台）单位核验后等待")

        if getattr(order, 'reduce_only', False):
            _pin_exec_reduce_phase(plat="EXT", coin=coin, step="UI_REDUCE_ONLY_TOGGLE_BEGIN", side=side, usd=usd, action=str((_reduce_ctx or {}).get("action") or "decrease"), req_id=str((_reduce_ctx or {}).get("req_id") or ""), trace=str((_reduce_ctx or {}).get("trace") or ""), extra=dict({"mode": "reduce_only"}, **(dict((_reduce_ctx or {}).get("extra") or {}))))
            if not self.ensure_reduce_only(True):
                _pin_exec_reduce_phase(plat="EXT", coin=coin, step="UI_REDUCE_ONLY_TOGGLE_FAIL", side=side, usd=usd, reason="reduce_only_toggle_on_fail", action=str((_reduce_ctx or {}).get("action") or "decrease"), req_id=str((_reduce_ctx or {}).get("req_id") or ""), trace=str((_reduce_ctx or {}).get("trace") or ""), extra=dict({"mode": "reduce_only"}, **(dict((_reduce_ctx or {}).get("extra") or {}))))
                _pin_exec_flow_terminal(flow="reduce", plat="EXT", coin=coin, action=str((_reduce_ctx or {}).get("action") or "decrease"), outcome="fail", reason="reduce_only_toggle_on_fail", side=side, usd=usd, req_id=str((_reduce_ctx or {}).get("req_id") or ""), trace=str((_reduce_ctx or {}).get("trace") or ""), extra=dict({"mode": "reduce_only"}, **(dict((_reduce_ctx or {}).get("extra") or {}))))
                _exec_log('EXT（平台）ReduceOnly（只减仓）开关无法确认=ON，拒绝下单以避免误开仓')
                return False
            _pin_exec_reduce_phase(plat="EXT", coin=coin, step="UI_REDUCE_ONLY_TOGGLE_OK", side=side, usd=usd, action=str((_reduce_ctx or {}).get("action") or "decrease"), req_id=str((_reduce_ctx or {}).get("req_id") or ""), trace=str((_reduce_ctx or {}).get("trace") or ""), extra=dict({"mode": "reduce_only"}, **(dict((_reduce_ctx or {}).get("extra") or {}))))
        else:
            _ = self.ensure_reduce_only(False)

        _ctx_ok_guard2, _ctx_det_guard2 = _ext_market_context_matches_request(coin, page=self.page)
        if not _ctx_ok_guard2:
            _guard_reason2 = str((_ctx_det_guard2 or {}).get('reason') or 'market_context_mismatch_before_input')
            if bool(getattr(order, 'reduce_only', False)):
                _pin_exec_flow_terminal(flow="reduce", plat="EXT", coin=coin, action=str((_reduce_ctx or {}).get("action") or "decrease"), outcome="fail", reason=_guard_reason2, side=side, usd=usd, req_id=str((_reduce_ctx or {}).get("req_id") or ""), trace=str((_reduce_ctx or {}).get("trace") or ""), extra=dict({"mode": "reduce_only", "market_ctx": _ctx_det_guard2}, **(dict((_reduce_ctx or {}).get("extra") or {}))))
            _exec_ui_flow_end(order, self.page, "EXT", coin, ("close" if bool(getattr(order, 'reduce_only', False)) else (str(getattr(order, 'action_type', '') or 'open_leg'))), ok=0, fail_reason=_guard_reason2)
            return False

        inp = self.loc_value_input().first
        if _pw_locator_count(inp, "ext.loc_amount_input") == 0:
            inp = self.page.locator('input[data-part="input"]').first  # 兜底
