_COIN_LANE_LOCKS: dict[str, threading.RLock] = {}
_COIN_LANE_LOCKS_G = threading.Lock()

def _get_coin_lane_lock(_coin_key: str) -> threading.RLock:
    ck = (str(_coin_key or "__GLOBAL__").strip().upper() or "__GLOBAL__")
    with _COIN_LANE_LOCKS_G:
        lk = _COIN_LANE_LOCKS.get(ck)
        if lk is None:
            lk = threading.RLock()
            _COIN_LANE_LOCKS[ck] = lk
        return lk

def verify_exec_by_rescan(pre_snap: Dict[str, Any], post_snap: Dict[str, Any], exec_results: List[Dict[str, Any]], logfp: str) -> Dict[str, Any]:
    """用 M2 的两次快照对比 Executor 执行效果（弱验证：不追求精确成交，只判定方向与名义变化）"""
    pre_map = {}
    post_map = {}
    for plat in ("EXT", "VAR"):
        for coin, pos in (pre_snap.get("positions", {}).get(plat, {}) or {}).items():
            pre_map[(coin, plat)] = pos
        for coin, pos in (post_snap.get("positions", {}).get(plat, {}) or {}).items():
            post_map[(coin, plat)] = pos

    table_lines = []
    ok_cnt = 0
    sus_cnt = 0
    for r in exec_results or []:
        req = r.get("req") or {}
        coin = str(req.get("coin") or "").upper()
        plat = str(req.get("platform") or "")
        action = str(req.get("action_type") or "")
        module = str(req.get("module") or "")
        ok = bool(r.get("ok"))
        exec_u = float(r.get("exec_notional_u") or 0.0)

        pre = pre_map.get((coin, plat), {})
        post = post_map.get((coin, plat), {})
        pre_n = _pos_notional(pre)
        post_n = _pos_notional(post)
        delta = post_n - pre_n

        verdict = "SKIP"
        note = ""
        if not ok:
            verdict = "FAIL"
            note = str(r.get("reason") or "")
        else:
            if module == "M9" and action in ("increase", "decrease"):
                thr = max(1.0, 0.2 * max(exec_u, 0.0))
                pre_side = _pos_side(pre)
                post_side = _pos_side(post)
                if action == "increase":
                    ok_cond = (pre_side != "NONE") and (post_side == pre_side) and (delta >= thr)
                    note = f"期待名义增加≥{thr:.2f}U，但 delta={delta:.2f}U side(pre={pre_side},post={post_side})"
                else:
                    ok_cond = (pre_side != "NONE") and (post_side in (pre_side, "NONE")) and (delta <= -thr)
                    note = f"期待名义减少≥{thr:.2f}U，但 delta={delta:.2f}U side(pre={pre_side},post={post_side})"
                if ok_cond:
                    verdict = "OK"
                    ok_cnt += 1
                else:
                    verdict = "SUSPECT"
                    sus_cnt += 1
            else:
                if module == "M10" and action == "koujing_a_3step":
                    steps = (req.get("params") or {}).get("steps") or req.get("steps") or []
                    loss_plat = None
                    target_u = 0.0
                    try:
                        for st in steps:
                            meta = st.get("meta") or {}
                            if meta.get("role") == "loss_leg":
                                loss_plat = str(st.get("platform") or "").upper()
                                target_u = float(meta.get("target_notional_u") or st.get("notional_usd") or st.get("notional") or st.get("target_notional_u") or 0.0)
                                break
                    except Exception:
                        loss_plat = None
                        target_u = 0.0

                    if loss_plat in ("EXT", "VAR") and target_u > 0:
                        pre2 = pre_map.get((coin, loss_plat), {}) or {}
                        post2 = post_map.get((coin, loss_plat), {}) or {}
                        pre_n2 = _pos_notional(pre2)
                        post_n2 = _pos_notional(post2)
                        delta2 = post_n2 - pre_n2
                        thr2 = max(10.0, 0.2 * target_u)
                        ok_cond2 = (pre_n2 > 0) and (delta2 <= -thr2)
                        note = f"trend_tp loss_leg 期待名义减少≥{thr2:.2f}U(目标{target_u:.2f}U) 实际delta={delta2:.2f}U pre={pre_n2:.2f} post={post_n2:.2f}"
                        if ok_cond2:
                            verdict = "OK"
                            ok_cnt += 1
                        else:
                            verdict = "SUSPECT"
                            sus_cnt += 1
                    else:
                        verdict = "OK"
                        ok_cnt += 1
                else:
                    verdict = "OK"
                    ok_cnt += 1

        table_lines.append(
            f"{module} | {coin} | {plat} | {action} | {exec_u:.2f} | {pre_n:.2f} | {post_n:.2f} | {delta:.2f} | {verdict} | {note}"
        )

    human(
        logfp,
        "动作后验证（M2 重扫对比）",
        [
            "module | coin | platform | action | exec_u | pre_notional | post_notional | delta | verdict | note",
            *table_lines,
            f"summary: ok={ok_cnt} suspect={sus_cnt} total={len(exec_results or [])}",
        ],
    )
    return {"ok": ok_cnt, "suspect": sus_cnt, "total": len(exec_results or [])}

import base64
import zlib

def _jieya(packed: Any) -> str:
    """解压内嵌模块源码。

    支持 bytes / bytearray / tuple[int] / list[int] / base64 字符串。
    返回 utf-8 文本；若 utf-8 失败则用 replace 保底，避免启动自检因解压函数缺失直接硬死。
    """
    data: bytes
    if isinstance(packed, (bytes, bytearray)):
        data = bytes(packed)
    elif isinstance(packed, (tuple, list)):
        try:
            data = bytes(int(x) & 0xFF for x in packed)
        except Exception as e:
            raise ValueError(f"packed_bytes_cast_fail:{type(e).__name__}:{e}") from e
    elif isinstance(packed, str):
        s = packed.strip()
        try:
            data = base64.b64decode(s)
        except Exception:
            data = s.encode('utf-8', errors='ignore')
    else:
        raise TypeError(f"unsupported_packed_type:{type(packed).__name__}")

    last_err: Exception | None = None
    for fn in (lambda b: zlib.decompress(b), lambda b: b):
        try:
            raw = fn(data)
            try:
                return raw.decode('utf-8')
            except UnicodeDecodeError:
                return raw.decode('utf-8', errors='replace')
        except Exception as e:
            last_err = e
            continue
    raise RuntimeError(f"embed_unpack_fail:{type(last_err).__name__ if last_err else 'Unknown'}:{last_err}")

