_ATOMIC_WRITE_WARN_TS: dict[str, float] = globals().get("_ATOMIC_WRITE_WARN_TS", {}) or {}

def _is_windows_write_lock_error(e: Exception) -> bool:
    try:
        if isinstance(e, PermissionError):
            return True
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_1305', _e)
        pass
    try:
        if isinstance(e, OSError) and getattr(e, "winerror", None) in (5, 32, 33):
            return True
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_1306', _e)
        pass
    return False

def _atomic_write_warn_once(fp: str, msg: str, *, window_sec: float = 30.0) -> None:
    try:
        now = float(time.time())
        key = str(fp or "")
        last = float(_ATOMIC_WRITE_WARN_TS.get(key) or 0.0)
        if (now - last) < float(window_sec or 0.0):
            return
        _ATOMIC_WRITE_WARN_TS[key] = now
        print(msg)
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_1307', _e)
        pass
def _safe_atomic_write_bytes(fp: str, data: bytes, *, mode_tag: str = "json", retries: int = 8, keep_pending: bool = True) -> bool:
    """Windows 友好原子写：同目录唯一 tmp + flush/fsync + replace 重试。
    若目标文件被面板/杀软/同步程序短暂占用，则把最新内容保留到 .pending，避免主链报错和丢最新快照。
    """
    import tempfile as _tempfile
    tmp = None
    pending = str(fp) + '.pending'
    try:
        os.makedirs(os.path.dirname(os.path.abspath(fp)) or '.', exist_ok=True)
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_1308', _e)
        pass
    try:
        if keep_pending and os.path.exists(pending):
            try:
                os.replace(pending, fp)
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_1309', _e)
                pass
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_1310', _e)
        pass
    last_err = None
    try:
        fd, tmp = _tempfile.mkstemp(prefix='.__aw_', suffix='.tmp', dir=os.path.dirname(os.path.abspath(fp)) or '.')
        with os.fdopen(fd, 'wb') as f:
            f.write(data)
            try:
                f.flush()
                os.fsync(f.fileno())
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_1311', _e)
                pass
        for i in range(max(1, int(retries or 1))):
            try:
                os.replace(tmp, fp)
                tmp = None
                try:
                    if keep_pending and os.path.exists(pending):
                        os.remove(pending)
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_1312', _e)
                    pass
                return True
            except Exception as e:
                last_err = e
                if _is_windows_write_lock_error(e):
                    try:
                        time.sleep(min(0.05 + 0.05 * i, 0.5))
                    except Exception as _e:
                        _record_swallowed_exception('except_pass_line_1313', _e)
                        pass
                    continue
                break
        if keep_pending and tmp and os.path.exists(tmp):
            try:
                os.replace(tmp, pending)
                tmp = None
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_1314', _e)
                pass
        _atomic_write_warn_once(fp, f"[WARN] ATOMIC_WRITE_LOCKED mode={mode_tag} fp={fp} err={type(last_err).__name__}:{last_err}")
        return False
    finally:
        try:
            if tmp and os.path.exists(tmp):
                os.remove(tmp)
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_1315', _e)
            pass
def _atomic_write_json(fp: str, obj: dict) -> None:
    try:
        obj2 = _json_sanitize(obj)
        payload = json.dumps(obj2, ensure_ascii=False, indent=2, allow_nan=False).encode('utf-8')
        _safe_atomic_write_bytes(fp, payload, mode_tag='json', retries=8, keep_pending=True)
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

def _atomic_write_text_late(fp: str, text: str) -> None:
    """原子写文本（用于 last.txt 一类的覆盖写），避免写到一半被读取。"""
    try:
        _txt = text if text is not None else ''
        if not str(_txt).endswith('\n'):
            _txt = str(_txt) + '\n'
        if _safe_atomic_write_bytes(fp, str(_txt).encode('utf-8'), mode_tag='text', retries=8, keep_pending=True):
            return
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_1316', _e)
        pass
    try:
        with open(fp, 'w', encoding='utf-8') as f:
            f.write(text if text is not None else '')
            if not str(text or '').endswith('\n'):
                f.write('\n')
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)
_atomic_write_text = _atomic_write_text_late

def _load_m9_stats() -> None:
    global _M9_STATS
    fp = _m9_stats_fp()
