def _m9_reset_bucket_on_coin_flat(coin: str, reason: str = "") -> None:
    """清空该 coin 的 M9 预算桶/网格账本/状态，并把该 coin 标记为“下一轮优先重建 L1”的强优先币。"""
    c = str(coin or '').upper().strip()
    if not c:
        return
    try:
        _a1_obj = _a1_load_state(_a1_state_dir()) or {}
        _ns = dict(_a1_obj.get("m9") or (_a1_obj.get(("m9" + "x")) or {}))
        _ns["force_priority_coin"] = str(c)
        _ns["force_priority_reason"] = str(reason or "reset")[:120]
        _ns["force_priority_ts"] = float(time.time())
        _a1_obj["m9"] = _ns
        _a1_obj[("m9" + "x")] = dict(_ns)
        _a1_save_state(_a1_state_dir(), _a1_obj)
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    try:
        if isinstance(_M9_STATS, dict):
            ae = _M9_STATS.get('add_events', {})
            if isinstance(ae, dict) and c in ae:
                ae.pop(c, None)
            act = _M9_STATS.get('action_events', {})
            if isinstance(act, dict) and c in act:
                act.pop(c, None)
            _save_m9_stats()
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    try:
        gb = globals().get('GRID_BOOK', None)
        if gb is not None and hasattr(gb, 'data') and isinstance(getattr(gb, 'data', None), dict):
            grids = (gb.data.get('grids') or {})
            if isinstance(grids, dict):
                for gid in list(grids.keys()):
                    try:
                        if str(gid).upper().startswith(f"{c}_"):
                            grids.pop(gid, None)
                    except Exception:
                        continue
            try:
                gb._save()
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    try:
        gs = globals().get('GRID_STATE', None)
        if gs is not None and hasattr(gs, '_start') and isinstance(getattr(gs, '_start', None), dict):
            for k in list(gs._start.keys()):
                try:
                    kk = str(k)
                    cc = kk.split('|')[0].upper().strip() if '|' in kk else kk.upper().strip()
                    if cc == c:
                        gs._start.pop(k, None)
                except Exception:
                    continue
            try:
                gs._save()
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    try:
        _M9_LAST_SCAN_ID_ENQUEUED.pop(c, None)
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)
    try:
        _ADD_LAST_EXEC_TS.pop(c, None)
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)
    try:
        _TP_LAST_EXEC_TS.pop(c, None)
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)
    try:
        pass
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)
    try:
        _save_m9_scan_dedupe()
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)
    try:
        _save_add_cooldown()
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)
    try:
        _save_tp_lock()
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    try:
        safe_log(lambda: f"[{now_ts()}] M9_BUCKET_RESET(网格桶清空) coin={c} reason={str(reason or '-')[:120]} next_priority={c}")
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

def _ymd(ts: float | None = None) -> str:
    try:
        return time.strftime('%Y-%m-%d', time.localtime(float(ts or time.time())))
    except Exception:
        return '1970-01-01'

def _trim_events(events: list, now_ts: float, keep_sec: float) -> list:
    out = []
    for e in (events or []):
        try:
            t = float((e or {}).get('ts') or 0.0)
        except Exception:
            t = 0.0
        if t <= 0:
            continue
        if float(now_ts) - t <= float(keep_sec):
            out.append(e)
    return out

def _m9_round_tick(now_ts: float | None = None) -> None:
    """每轮进入 M9 BEGIN（无论有无下单）都记一次，用于你统计“运行了多少次”。"""
    global _M9_STATS
    ts = float(now_ts or time.time())
    day = _ymd(ts)
    try:
        _M9_STATS['rounds_total'] = int(_M9_STATS.get('rounds_total', 0) or 0) + 1
        rb = _M9_STATS.get('rounds_by_day') or {}
        rb[day] = int(rb.get(day, 0) or 0) + 1
        _M9_STATS['rounds_by_day'] = rb
        _save_m9_stats()
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

def _m9_record_action(coin: str, action: str, notional_u: float, platform: str | None = None, ts: float | None = None) -> None:
    """记录已执行动作（increase/decrease），用于面板展示交易量/次数。"""
    global _M9_STATS
    now_ts = float(ts or time.time())
    c = str(coin or '').upper()
    try:
        ae = _M9_STATS.get('action_events') or {}
        lst = ae.get(c) or []
        lst.append({'ts': now_ts, 'action': str(action), 'u': float(notional_u or 0.0), 'platform': str(platform or '').upper()})
        lst = _trim_events(lst, now_ts, keep_sec=2*86400)
        ae[c] = lst
        _M9_STATS['action_events'] = ae
        if str(action) == 'increase':
            ad = _M9_STATS.get('add_events') or {}
            al = ad.get(c) or []
            al.append({'ts': now_ts, 'u': float(notional_u or 0.0)})
            al = _trim_events(al, now_ts, keep_sec=2*86400)
            ad[c] = al
            _M9_STATS['add_events'] = ad
        _save_m9_stats()
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

def _m9_check_add_limits(coin: str, want_u: float, now_ts: float | None = None):
    """返回 (ok, reason, detail)。[SINGLE_CHAIN][1A] 只保留每日预算，不再重复做小时/日次数拦截。"""
    global _M9_STATS
    ts = float(now_ts or time.time())
    c = str(coin or "").upper()
    day = _ymd(ts)
    hour_sec = 3600.0
    day_sec = 86400.0

    add_ev = ((_M9_STATS.get("add_events") or {}).get(c) or [])
    add_ev = _trim_events(add_ev, ts, keep_sec=2*86400)

    cnt_1h = 0
    cnt_day = 0
    sum_day = 0.0
    for e in add_ev:
        try:
            t = float(e.get("ts") or 0.0)
            u = float(e.get("u") or 0.0)
        except Exception:
            continue
        if t <= 0:
            continue
        if ts - t <= hour_sec:
            cnt_1h += 1
        if _ymd(t) == day:
            cnt_day += 1
            sum_day += u

    if (not HARDTOP_ONLY) and ((sum_day + float(want_u or 0.0)) > float(M9_DAILY_BUDGET_U_PER_COIN)):
        return False, f"m9_budget_limit（每日预算{M9_DAILY_BUDGET_U_PER_COIN:.1f}） sum_day={sum_day:.1f}", {"cnt_1h": cnt_1h, "cnt_day": cnt_day, "sum_day": sum_day}

    return True, 'ok', {'cnt_1h': cnt_1h, 'cnt_day': cnt_day, 'sum_day': sum_day}

def _m9_calc_kpi_from_gridbook(now_ts: float | None = None) -> dict:
    """从 GRID_BOOK（网格账本）汇总成交额与已实现利润。"""
    ts = float(now_ts or time.time())
    day = _ymd(ts)
    total_turnover = 0.0
    today_turnover = 0.0
    total_pnl = 0.0
    today_pnl = 0.0

    per_coin = {}

    try:
        gb = globals().get('GRID_BOOK')
        data = (gb.data if gb is not None and hasattr(gb, 'data') else None) or {}
        grids = data.get('grids') or {}

        if (not grids) and isinstance(data, dict) and isinstance(data.get('items'), list):
            items = data.get('items') or []
            for it in items:
                if not isinstance(it, dict):
                    continue
                if str(it.get('source') or '').upper() not in ('M9','W1','M9X','W1X','GRID'):
                    continue
                coin = str(it.get('coin') or '').upper()
                plat = str(it.get('platform') or '').upper()
                st = str(it.get('state') or '').upper()
                try:
                    amt = float(it.get('amount_u') or it.get('open_amount_u') or 0.0)
                except Exception:
                    amt = 0.0
                if amt <= 0:
                    continue
                total_turnover += abs(float(amt))
                try:
                    t_open = float(it.get('open_ts') or 0.0)
                except Exception:
                    t_open = 0.0
                if _ymd(t_open) == day:
                    today_turnover += abs(float(amt))
                try:
                    rp = it.get('realized_pnl_usd') or it.get('profit_u') or it.get('realized_pnl_u') or None
                    if rp is not None:
                        rp = float(rp)
                    else:
                        rp = None
                except Exception:
                    rp = None
                if rp is not None:
                    total_pnl += float(rp)
                    try:
                        t_close = float(it.get('close_ts') or 0.0)
                    except Exception:
                        t_close = 0.0
                    if t_close > 0 and _ymd(t_close) == day:
                        today_pnl += float(rp)

                pc = per_coin.setdefault(coin, {'turnover_total': 0.0, 'turnover_today': 0.0, 'realized_total': 0.0, 'realized_today': 0.0, 'open_cnt': 0, 'closed_cnt': 0})
                pc['turnover_total'] += abs(float(amt))
                if _ymd(t_open) == day:
                    pc['turnover_today'] += abs(float(amt))
                if st == 'OPEN':
                    pc['open_cnt'] += 1
                elif st == 'CLOSED':
                    pc['closed_cnt'] += 1
                if rp is not None:
                    pc['realized_total'] += float(rp)
                    if t_close > 0 and _ymd(t_close) == day:
                        pc['realized_today'] += float(rp)

            try:
                if abs(float(today_pnl)) < 1e-12 and abs(float(total_pnl)) < 1e-12:
                    tfp = os.path.join(_get_out_dir(), "trades.jsonl")
                    _ymd_today = day
                    _p_today = 0.0
                    with open(tfp, "r", encoding="utf-8") as _f:
                        _seen2 = set()
                        for _ln in _f:
                            _ln = (_ln or "").strip()
                            if not _ln:
                                continue
                            try:
                                _r = json.loads(_ln)
                            except Exception:
                                continue
                            if not isinstance(_r, dict):
                                continue
                            if ('ok' in _r) and (not bool(_r.get('ok', False))):
                                continue
                            if str(_r.get('date_ymd') or "") != _ymd_today:
                                continue
                            _mod = str(_r.get('module') or '').upper()
                            if _mod not in ("M9", "W1"):
                                continue
                            _uid2 = str(_r.get('trace_id') or _r.get('req_id') or _r.get('trade_id') or '')
                            if _uid2:
                                if _uid2 in _seen2:
                                    continue
                                _seen2.add(_uid2)
                            _pu = _r.get('profit_u')
                            if _pu is None:
                                continue
                            try:
                                _p_today += float(_pu)
                            except Exception as _e:
                                _record_swallowed_exception('except_pass_line_1317', _e)
                                pass
                    if abs(_p_today) > 1e-12:
                        today_pnl = float(_p_today)
                        total_pnl = float(_p_today)
                        try:
                            for _c, _pc in per_coin.items():
                                pass
                        except Exception as _e:
                            _record_swallowed_exception('except_pass_line_1318', _e)
                            pass
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_1319', _e)
                pass
            return {
                'today_ymd': day,
                'turnover_usd_total': round(total_turnover, 6),
                'turnover_usd_today': round(today_turnover, 6),
                'realized_pnl_usd_total': round(total_pnl, 6),
                'realized_pnl_usd_today': round(today_pnl, 6),
                'per_coin_from_gridbook': per_coin,
            }

        if not grids:
            try:
                _p = str(globals().get('GRID_LEDGER_PATH') or '')
                if _p and os.path.exists(_p):
                    _d = safe_read_json(_p, default=None)
                    if isinstance(_d, dict) and isinstance(_d.get('items'), list) and (len(_d.get('items') or []) > 0):
                        data = _d
                        grids = data.get('grids') or {}
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_1320', _e)
                pass
        for gid, g in (grids or {}).items():
            if not isinstance(g, dict):
                continue
            coin = str(g.get('coin') or '').upper()
            layers = g.get('layers') or []
            for ly in layers:
                if not isinstance(ly, dict):
                    continue
                try:
                    ou = float(ly.get('open_notional_u') or 0.0)
                except Exception:
                    ou = 0.0
                try:
                    ots = float(ly.get('open_ts') or 0.0)
                except Exception:
                    ots = 0.0
                if ou > 0 and ots > 0:
                    total_turnover += ou
                    if _ymd(ots) == day:
                        today_turnover += ou
                    per_coin.setdefault(coin, {'turnover_today': 0.0, 'pnl_today': 0.0, 'turnover_total': 0.0, 'pnl_total': 0.0})
                    per_coin[coin]['turnover_total'] += ou
                    if _ymd(ots) == day:
                        per_coin[coin]['turnover_today'] += ou

                try:
                    cts = ly.get('close_ts')
                    cts = float(cts) if cts is not None else 0.0
                except Exception:
                    cts = 0.0
                try:
                    cu = float(ly.get('close_notional_u') or 0.0)
                except Exception:
                    cu = 0.0
                if cu > 0 and cts > 0:
                    total_turnover += cu
                    if _ymd(cts) == day:
                        today_turnover += cu
                    per_coin.setdefault(coin, {'turnover_today': 0.0, 'pnl_today': 0.0, 'turnover_total': 0.0, 'pnl_total': 0.0})
                    per_coin[coin]['turnover_total'] += cu
                    if _ymd(cts) == day:
                        per_coin[coin]['turnover_today'] += cu

                try:
                    pnl = float(_m9_layer_realized_total(ly))
                except Exception:
                    pnl = 0.0
                if abs(float(pnl or 0.0)) > 1e-12:
                    total_pnl += pnl
                    if cts > 0 and _ymd(cts) == day:
                        today_pnl += pnl
                    per_coin.setdefault(coin, {'turnover_today': 0.0, 'pnl_today': 0.0, 'turnover_total': 0.0, 'pnl_total': 0.0})
                    per_coin[coin]['pnl_total'] += pnl
                    if cts > 0 and _ymd(cts) == day:
                        per_coin[coin]['pnl_today'] += pnl

    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    _rp = None
    try:
        _tr_fp = None
        try:
            _tr_fp = TRADES_FP if isinstance(TRADES_FP, str) and TRADES_FP else None
        except Exception:
            _tr_fp = None
        if _tr_fp is None:
            try:
                _tr_fp = TRADES_FP_FALLBACK if isinstance(TRADES_FP_FALLBACK, str) and TRADES_FP_FALLBACK else None
            except Exception:
                _tr_fp = None
        if _tr_fp and os.path.exists(_tr_fp):
            _rp = _realized_stats_from_trades(_tr_fp, module_filter="M9")
    except Exception:
        _rp = None

    try:
        if isinstance(_rp, dict):
            _tp = float(_rp.get('realized_pnl_usd_today') or 0.0)
            _tt = float(_rp.get('realized_pnl_usd_total') or 0.0)
            if float(today_pnl or 0.0) == 0.0 and bool(_rp.get('has_profit_field')) and abs(_tp) > 1e-12:
                today_pnl = float(_tp)
            if float(total_pnl or 0.0) == 0.0 and bool(_rp.get('has_profit_field')) and abs(_tt) > 1e-12:
                total_pnl = float(_tt)
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    return {
        'today_ymd': day,
        'turnover_usd_total': round(total_turnover, 6),
        'turnover_usd_today': round(today_turnover, 6),
        'realized_pnl_usd_total': round(total_pnl, 6),
        'realized_pnl_usd_today': round(today_pnl, 6),
        'per_coin_from_gridbook': per_coin,
    }

def _m9_write_kpi(now_ts: float | None = None) -> None:
    """落盘：out/m9_kpi.json（给面板读）。"""
    global _M9_STATS
    ts = float(now_ts or time.time())
    day = _ymd(ts)
    try:
        per_coin_lim = {}
        for c, evs in ((_M9_STATS.get('add_events') or {}) or {}).items():
            try:
                ok, _, det = _m9_check_add_limits(c, 0.0, now_ts=ts)
            except Exception:
                det = {'cnt_1h': 0, 'cnt_day': 0, 'sum_day': 0.0}
            per_coin_lim[str(c).upper()] = {
                'add_cnt_1h': int(det.get('cnt_1h', 0) or 0),
                'add_cnt_day': int(det.get('cnt_day', 0) or 0),
                'add_sum_day_u': float(det.get('sum_day', 0.0) or 0.0),
                'budget_left_u': round(float(M9_DAILY_BUDGET_U_PER_COIN) - float(det.get('sum_day', 0.0) or 0.0), 6),
            }

        kpi_grid = _m9_calc_kpi_from_gridbook(now_ts=ts)

        out = {
            'ts': ts,
            'today_ymd': day,
            'm9_rounds_total': int(_M9_STATS.get('rounds_total', 0) or 0),
            'm9_rounds_today': int((_M9_STATS.get('rounds_by_day', {}) or {}).get(day, 0) or 0),
            'limits': {
                'order_u_min': float(M9_ORDER_U_MIN),
                'order_u_max': float(M9_ORDER_U_MAX),
                'add_max_per_hour_per_coin': int(M9_ADD_MAX_PER_HOUR_PER_COIN),
                'add_max_per_day_per_coin': int(M9_ADD_MAX_PER_DAY_PER_COIN),
                'daily_budget_u_per_coin': float(M9_DAILY_BUDGET_U_PER_COIN),
            },
            'per_coin_limits_today': per_coin_lim,
            **(kpi_grid or {}),
        }
        _atomic_write_json(_m9_kpi_fp(), out)
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

