def _m9_count_trades_last_hour(grid_book: Any, now_ts: Optional[float] = None) -> int:
    """统计最近 1 小时内 M9 的成交次数（以层 OPEN/CLOSE 事件计数）。
    说明：我们无法直接拿到成交回执（你说只能靠扫描前后差额确认），这里用“执行成功后落盘的层事件”作为近似。
    """
    try:
        if now_ts is None:
            now_ts = time.time()
        cutoff = float(now_ts) - 3600.0
        data = getattr(grid_book, "data", None) or {}
        grids = (data.get("grids") or {})
        cnt = 0
        for gid, g in grids.items():
            layers = (g or {}).get("layers") or []
            for ly in layers:
                try:
                    ot = float(ly.get("open_ts") or 0.0)
                except Exception:
                    ot = 0.0
                if ot >= cutoff:
                    cnt += 1
                try:
                    ct = float(ly.get("close_ts") or 0.0)
                except Exception:
                    ct = 0.0
                if ct and ct >= cutoff:
                    cnt += 1
        return int(cnt)
    except Exception:
        return 0

def _m9_adapt_tp_and_cooldown(trades_1h: int) -> None:
    """M9 网格口径（最高权限版）：
    - TP 固定在 1%~3%（不随成交频率自适应）
    - 冷却固定 0 秒：网格不做时间冷却，频率控制交给价格走格 + 同轮幂等去重
    备注：速率控制交给“价格走格（1%~3%） + 同轮只下一单（同 scan_id 去重）”。
    """
    global M9_TP_PCT_MIN, M9_TP_PCT_MAX
    try:
        M9_TP_PCT_MIN = 0.01
        M9_TP_PCT_MAX = 0.03
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

