def _a1_load_state(state_dir: str) -> dict:
    """Load A1 state from a single JSON file.

    Backward-compat migration: if the legacy state file exists and the new one doesn't,
    migrate it once into the new file location (best-effort).
    """
    fp = _a1_state_path()

    legacy_fp = _zhuangtai_path("h" + "p_state.json")
    if (not os.path.exists(fp)) and os.path.exists(legacy_fp):
        try:
            legacy_obj = safe_read_json(legacy_fp, default={}) or {}
            _a1_save_state(state_dir, legacy_obj)
            try:
                os.remove(legacy_fp)
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    if os.path.exists(fp):
        try:
            return safe_read_json(fp, default={}) or {}
        except Exception:
            return {}
    return {}

