def _cooldown_left(ts_map: dict, coin: str, sec: int, now: float) -> int:
    try:
        ts = float((ts_map or {}).get(coin) or 0.0)
        if ts <= 0:
            return 0
        left = float(sec) - (float(now) - ts)
        if left <= 0:
            return 0
        return int(math.ceil(left))
    except Exception:
        return 0

def _fmt_coins_left(ts_map: dict | None, coins: list, sec: int, now: float) -> list:
    """把 coins 格式化为 ['BTC(187s)', ...] 方便控制台一眼看剩余时间。"""
    try:
        out = []
        for c in (coins or []):
            c = str(c or "")
            if not c:
                continue
            left = _cooldown_left(ts_map or {}, c, int(sec), float(now))
            out.append(f"{c}({left}s)")
        return out
    except Exception:
        return [str(c) for c in (coins or [])]

def _emit_pipeline_drop_jsonl(logfp: str, stage: str, reason: str, sec: int, coins: list, now: float, ts_map: dict | None = None) -> None:
    """写入面板 jsonl：流水线丢弃原因 + 剩余冷却秒数（若可计算）。"""
    try:
        if not logfp:
            return
        if not coins:
            return
        arr = []
        for c in coins:
            c = str(c or "")
            if not c:
                continue
            obj = {"coin": c}
            if ts_map is not None:
                obj["left_sec"] = _cooldown_left(ts_map, c, int(sec), float(now))
            arr.append(obj)
        if not arr:
            return
        payload = {
            "ts": float(now),
            "mod": "GO（流水线）",
            "type": "pipeline_drop（流水线丢弃）",
            "stage": str(stage or ""),
            "reason": str(reason or ""),
            "sec": int(sec),
            "coins": arr,
        }
        write_jsonl(logfp, payload)
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

