def _pnl_state_path() -> str:
    return _zhuangtai_path(PENDING_PNL_FNAME)

def _pnl_load_pending() -> list:
    fp = _pnl_state_path()
    try:
        if fp and os.path.exists(fp):
            x = safe_read_json(fp, default=[])
            return x if isinstance(x, list) else []
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    return []

def _pnl_save_pending(items: list) -> None:
    fp = _pnl_state_path()
    try:
        if not fp:
            return
        os.makedirs(os.path.dirname(fp), exist_ok=True)
        safe_write_json(fp, items, indent=2)
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

def _pnl_pending_maybe_add(snapshot: dict, req: "Request") -> None:
    """仅对 平仓/减仓/降敞口 动作挂起一条 PNL 回执检查，等待下一次 M2 扫描确认。"""
    try:
        act = str(_canon_action_type(req.action_type or "") or "").lower()
        mod = (req.module or "").upper()
        plat = str(req.platform or "").upper()
        coin = str(req.coin or "").upper()
        params = req.params if isinstance(req.params, dict) else {}
        reduce_mode = bool(params.get("reduce_mode")) or bool(params.get("legacy_fix_mode") and params.get("reduce_mode"))
        is_close_like = act in ("close", "close_all", "decrease", "reduce", "reduce_only", "close_partial")
        is_reduce_like = reduce_mode or (mod in ("GO", "LEGACY_DELETED") and act == "add_leg" and bool(params.get("reduce_mode")))
        if not (is_close_like or is_reduce_like):
            return
        ts = float(snapshot.get("ts") or time.time())
        pre_notional = float(_get_notional_u(snapshot, coin, plat) or 0.0)
        try:
            leg = _get_snapshot_coin_leg(snapshot, coin, plat) or {}
            pre_upnl = float(leg.get("upnl_u") or leg.get("upnl_usd") or 0.0)
        except Exception:
            pre_upnl = 0.0
        try:
            pre_eq = float(_get_total_u(snapshot or {}) or 0.0)
        except Exception:
            pre_eq = 0.0
        item = {
            "ts": ts,
            "module": mod,
            "action": act,
            "coin": coin,
            "platform": plat,
            "pre_notional_u": pre_notional,
            "pre_position": dict(leg) if isinstance(leg, dict) else None,
            "side": str((leg or {}).get('side') or ''),
            "kind": 'close_all' if act in ('close', 'close_all') else 'close',
            "intent_usd": _postcheck_req_amount_u(req),
            "pre_upnl_u": pre_upnl,
            "pre_total_equity_u": pre_eq,
        }
        pend = _pnl_load_pending()
        pend.append(item)
        # Unresolved receipts are retained regardless of age.
        _pnl_save_pending(pend)
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

def _pnl_check_consume(snapshot: dict) -> None:
    """在 M2 扫描完成后，对挂起的动作输出估算收益（U），然后出队。"""
    try:
        ts_now = float(snapshot.get("ts") or time.time())
    except Exception:
        ts_now = time.time()
    pend = _pnl_load_pending()
    if not pend:
        return
    out = []
    for it in pend:
        try:
            ts0 = float(it.get("ts") or 0.0)
            if ts_now <= ts0:
                out.append(it)
                continue
            coin = str(it.get("coin") or "").upper()
            plat = str(it.get("platform") or "").upper()
            pre_n = float(it.get("pre_notional_u") or 0.0)
            pre_u = float(it.get("pre_upnl_u") or 0.0)
            pre_eq = float(it.get("pre_total_equity_u") or 0.0)

            post_n = float(_get_notional_u(snapshot, coin, plat) or 0.0)
            try:
                leg = _get_snapshot_coin_leg(snapshot, coin, plat) or {}
                post_u = float(leg.get("upnl_u") or leg.get("upnl_usd") or 0.0)
            except Exception:
                post_u = 0.0
            try:
                post_eq = float(_get_total_u(snapshot or {}) or 0.0)
            except Exception:
                post_eq = 0.0

            done, _settle_evidence = _safety_verify_pending_settlement(it, leg)
            it['last_confirmation_reason'] = str(_settle_evidence.get('reason') or '')
            if not done:
                out.append(it)
                continue

            pnl_est = None
            if pre_eq > 0 and post_eq > 0:
                pnl_est = post_eq - pre_eq
            else:
                pnl_est = pre_u - post_u

            try:
                print(f"[PNL_EST（收益估算）] mod={it.get('module')} act={it.get('action')} coin={coin} plat={plat} "
                      f"notional {pre_n:.2f}->{post_n:.2f} upnl {pre_u:.2f}->{post_u:.2f} "
                      f"equity {pre_eq:.2f}->{post_eq:.2f} pnl_est_u={float(pnl_est or 0.0):.2f}")
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

        except Exception:
            continue
    _pnl_save_pending(out)

def _a1_norm_side(side: str) -> str:
    s = (side or '').strip().lower()
    if s in ('long', 'buy', 'b', '多', '多头'):
        return 'LONG'
    if s in ('short', 'sell', 's', '空', '空头'):
        return 'SHORT'
    return 'NONE'

def _norm_module_name(mod: Any) -> str:
    """统一模块口径（用于执行流水线、过滤与可观测性）：
    - M10 与 M10_KOUJING_A 视为同一模块（统一为 M10）
    - 历史别名 M10_PURE_TP_KOUJING_A/纯止盈A 等也统一为 M10
    - 网格模块口径统一：M9X 等别名统一为 M9
    """
    m = str(mod or '').strip().upper()
    if not m:
        return ""
    if m in ('M10_KOUJING_A', 'M10KOUJINGA', 'M10_A'):
        return "M10"
    if m in ('M10_PURE_TP_KOUJING_A', '纯止盈KOUJINGA', 'TREND_TP_A', '纯止盈A'):
        return "M10"
    if m in (("M9" + "X"), 'M9_X', ("M9" + "X_GRID"), ("M9" + "XWANGGE")):
        return "M9"
    return m

_TP_PAIR_CANON = "close_pair"
_TP_PAIR_ALIASES = {
    "close_pair",
    "take_profit_full",
    "tp_full",
    "force_close_all",
}

def _canon_action_type(act: Any) -> str:
    """把历史/别名 action_type 归一到统一口径（减少分支与重复判断）。"""
    try:
        a = str(act or "").strip()
        al = a.lower()
        if al in _TP_PAIR_ALIASES:
            return _TP_PAIR_CANON
        if al in ("add_single", "grid_add", "grid_increase"):
            return "increase"
        return a
    except Exception:
        return str(act or "")

def _is_risk_increasing_action(act: Any) -> bool:
    """判断动作是否“增加风险/加仓/开新风险”。
    约定：increase/open/add_leg 等属于风险增加；decrease/close/reduce_only 属于降风险（永远允许）。
    """
    try:
        a = str(_canon_action_type(act) or act or "").strip().lower()
    except Exception:
        a = str(act or "").strip().lower()
    if not a:
        return False
    if a in ("decrease", "reduce", "reduce_only", "sell", "close", "close_all", "close_pair", "tp", "take_profit", "take_profit_full"):
        return False
    if a in ("increase", "add", "buy", "open", "open_leg", "add_leg", "add_single", "grid_add", "grid_increase", "entry"):
        return True
    return False

def _default_priority_for_req(module: str, act: Any, meta: Any = None) -> int:
    """系统默认优先级：数值越小越优先（队列按升序 sort）。
    - 降风险（decrease/close/reduce_only）：10
    - 强制止盈/回撤降风险（meta.force_deleveraging / M9_FORCE_TP 等）：5
    - 修复/补腿（add_leg/legacy_deleted）：30
    - 网格/趋势加仓（increase/open）：60
    - 其他：50
    """
    try:
        a = str(_canon_action_type(act) or act or "").strip().lower()
    except Exception:
        a = str(act or "").strip().lower()
    m = str(module or "").strip().upper()
    md = meta if isinstance(meta, dict) else {}
    try:
        if not isinstance(md, dict):
            md = {}
    except Exception:
        md = {}

    if int(md.get("force_deleveraging") or 0) == 1 or int(md.get("force_tp") or 0) == 1 or str(md.get("submodule") or "").upper() in ("M9_FORCE_TP",):
        return 5

    if m == 'B2':
        return 10
    if m == 'M10':
        return 20
    if m == 'B1':
        return 30
    if m == 'M9':
        return 40

    if a in ("decrease", "reduce", "reduce_only", "sell", "close", "close_all", "close_pair", "tp", "take_profit", "take_profit_full"):
        return 10

    if a in ("add_leg", "legacy_deleted", "legacy_only", "hedge", "rebalance"):
        return 30
    if m in ("LEGACY_DELETED", "X1", "LEGACY_DELETED", "Z1") and a in ("increase", "open", "open_leg", "add"):
        return 35

    if _is_risk_increasing_action(a):
        return 60

    return 50

def _apply_default_priority_if_missing(req: Any) -> None:
    """若请求未显式设置 priority，则按动作/模块自动补齐。
    这是系统性修复的一部分：保证 decrease/close 永远比 increase 先被执行。
    """
    try:
        pr = getattr(req, "priority", None)
        if pr is not None:
            return
    except Exception:
        pr = None
    try:
        if isinstance(req, dict):
            if req.get("priority", None) is not None:
                return
            mod = str(req.get("module") or "")
            act = req.get("action_type") or req.get("action") or ""
            meta = req.get("meta") or {}
            req["priority"] = int(_default_priority_for_req(mod, act, meta))
            return
        mod = str(getattr(req, "module", "") or "")
        act = getattr(req, "action_type", "") or ""
        meta = getattr(req, "meta", {}) or {}
        setattr(req, "priority", int(_default_priority_for_req(mod, act, meta)))
    except Exception:
        pass

def _is_tp_pair_action(act: Any) -> bool:
    try:
        return _canon_action_type(act).lower() == _TP_PAIR_CANON
    except Exception:
        return False

def _a1_extract_leg(snapshot: dict, coin: str, plat: str) -> tuple[str, float]:
    """返回 (side, notional_u)。兼容两类快照结构。

    1) snapshot['by_coin'][coin]['EXT'/'VAR']（或 ext/var）
    2) snapshot['coins'][coin]['ext'/'var']
    3) snapshot['positions'][plat][coin]
    4) snapshot 顶层 EXT/VAR list / raw_positions / positions.json 磁盘回退
    """
    plat = plat.upper()
    try:
        leg0 = _snap_get_pos_any(snapshot if isinstance(snapshot, dict) else {}, plat, str(coin or '').upper()) or {}
        leg0 = _normalize_snapshot_position_row(leg0, coin=str(coin or '').upper(), platform=plat) or leg0
        if isinstance(leg0, dict) and leg0:
            side0 = _a1_norm_side(leg0.get('side') or leg0.get('pos_side') or leg0.get('ls') or leg0.get('direction') or leg0.get('positionSide'))
            notional0 = float(leg0.get('notional_u') or leg0.get('value_u') or leg0.get('value_usd') or leg0.get('notional_usd') or leg0.get('notional') or leg0.get('notionalUsd') or 0.0)
            _n0 = _norm_leg_u(float(abs(notional0)))
            if _n0 > 0.0:
                return side0, _n0
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)
    try:
        bc = snapshot.get('by_coin', {}).get(str(coin or '').upper())
        if isinstance(bc, dict):
            leg = (bc.get(plat) or bc.get(plat.lower()) or bc.get('ext' if plat == 'EXT' else 'var') or bc.get(('EXT' if plat == 'EXT' else 'VAR')) or {})
            if isinstance(leg, dict):
                leg = _normalize_snapshot_position_row(leg, coin=str(coin or '').upper(), platform=plat) or leg
                side = _a1_norm_side(leg.get('side') or leg.get('pos_side') or leg.get('ls') or leg.get('direction'))
                notional = float(leg.get('notional_u') or leg.get('value_u') or leg.get('value_usd') or leg.get('notional_usd') or leg.get('notional') or 0.0)
                _n = float(abs(notional))
                _n2 = _norm_leg_u(_n)
                if _n2 <= 0.0:
                    return "NONE", 0.0
                return side, _n2
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    try:
        if 'coins' in snapshot and coin in snapshot['coins']:
            leg = snapshot['coins'][coin].get('ext' if plat == 'EXT' else 'var', {})
            side = _a1_norm_side(leg.get('side'))
            notional = float(leg.get('notional_u') or leg.get('value_usd') or 0.0)
            _n = float(abs(notional))
            _n2 = _norm_leg_u(_n)
            if _n2 <= 0.0:
                return "NONE", 0.0
            return side, _n2
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    try:
        pos = _pos_root(snapshot).get(plat, {}).get(coin, {})
        pos = _normalize_snapshot_position_row(pos, coin=coin, platform=plat) or pos
        side = _a1_norm_side(pos.get('side'))
        notional = float(pos.get('notional_u') or pos.get('value_u') or pos.get('value_usd') or 0.0)
        _n = float(abs(notional))
        _n2 = _norm_leg_u(_n)
        if _n2 <= 0.0:
            return "NONE", 0.0
        return side, _n2
    except Exception:
        return 'NONE', 0.0

def _a1_extract_upnl(snapshot: dict, coin: str, plat: str) -> float:
    """返回该腿的 UPnL（未实现盈亏，U）。优先 upnl_u，其次 upnl_usd。"""
    plat = str(plat or "").upper()
    coin = str(coin or "").upper()
    try:
        leg0 = _snap_get_pos_any(snapshot if isinstance(snapshot, dict) else {}, plat, coin) or {}
        leg0 = _normalize_snapshot_position_row(leg0, coin=coin, platform=plat) or leg0
        if isinstance(leg0, dict) and leg0:
            v0 = leg0.get('upnl_u')
            if v0 is None:
                v0 = leg0.get('upnl_usd')
            if v0 is not None:
                return float(v0 or 0.0)
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)
    try:
        if 'coins' in snapshot and coin in snapshot.get('coins', {}):
            leg = snapshot['coins'][coin].get('ext' if plat == 'EXT' else 'var', {})
            v = leg.get('upnl_u')
            if v is None:
                v = leg.get('upnl_usd')
            return float(v or 0.0)
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    try:
        pos = _pos_root(snapshot).get(plat, {}).get(coin, {})
        v = pos.get('upnl_u')
        if v is None:
            v = pos.get('upnl_usd')
        return float(v or 0.0)
    except Exception:
        return 0.0

def _a1_pos_notional_u(pos: dict) -> float:
    """从单腿 position dict 里提取名义价值（U），用于 HP 门禁计算。
    兼容不同字段：notional_u / notional / value_u / positionValue / notionalUsd / notional_usd 等。
    返回非负数（abs），缺失则 0。
    """
    try:
        if not isinstance(pos, dict):
            return 0.0
        for k in ("notional_u", "notional_u_usd", "notional", "value_u", "positionValue", "notionalUsd", "notional_usd"):
            if k in pos and pos.get(k) is not None:
                try:
                    return float(abs(float(pos.get(k))))
                except Exception:
                    continue
        n = pos.get("notional")
        if isinstance(n, dict):
            for kk in ("u", "usd", "USDT", "USDC"):
                if kk in n and n.get(kk) is not None:
                    try:
                        return float(abs(float(n.get(kk))))
                    except Exception as _e:
                        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

        sz = pos.get("size") or pos.get("qty") or pos.get("positionAmt")
        mp = pos.get("mark") or pos.get("mark_px") or pos.get("markPrice") or pos.get("price")
        if sz is not None and mp is not None:
            try:
                return float(abs(float(sz) * float(mp)))
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    return 0.0

def _a1_pos_upnl_u(pos):
    """Return unrealized PnL in U (can be negative). Robust to schema differences."""
    try:
        if not isinstance(pos, dict):
            return 0.0
        for k in (
            "upnl_u", "upnl_usd", "uPnL", "u_pnl", "upl", "unrealizedPnl",
            "unrealisedPnl", "unRealizedProfit", "unrealizedProfit",
            "pnl_u", "pnl_usd"
        ):
            if k in pos and pos.get(k) is not None:
                try:
                    return float(pos.get(k) or 0.0)
                except Exception as _e:
                    _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

        v = pos.get("upnl") or pos.get("upl") or pos.get("pnl")
        if isinstance(v, dict):
            for kk in ("u", "usd", "USDT", "USDC"):
                if kk in v and v.get(kk) is not None:
                    try:
                        return float(v.get(kk) or 0.0)
                    except Exception as _e:
                        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

        return 0.0
    except Exception:
        return 0.0

def _a1_count_ls_distribution(snapshot: dict, coins: list[str], min_pos_u: float = 5.0) -> tuple[int, int, int, int]:
    ext_l = ext_s = var_l = var_s = 0
    for c in coins:
        es, en = _a1_extract_leg(snapshot, c, 'EXT')
        vs, vn = _a1_extract_leg(snapshot, c, 'VAR')
        if en >= min_pos_u:
            if es == 'LONG':
                ext_l += 1
            elif es == 'SHORT':
                ext_s += 1
        if vn >= min_pos_u:
            if vs == 'LONG':
                var_l += 1
            elif vs == 'SHORT':
                var_s += 1
    return ext_l, ext_s, var_l, var_s

class A1StateMachine:
    def __init__(self, state_dir: str, max_gap_u: float = None):
        self.state_dir = state_dir
        self.max_gap_u = float(max_gap_u if max_gap_u is not None else A1_MAX_HEDGE_GAP_U)
        self.state = 'NORMAL'
        self.reason = ''
        self.coin_issues: dict[str, list[str]] = {}
        self.uncertain_until_ts = 0.0
        self.uncertain_fail = 0
        self.partial_once: dict[str, float] = {}
        self._load()

    def _load(self):
        obj = _a1_load_state(self.state_dir)
        self.state = obj.get('state', 'NORMAL')
        self.reason = obj.get('reason', '')
        self.uncertain_until_ts = float(obj.get('uncertain_until_ts', 0.0) or 0.0)
        self.uncertain_fail = int(obj.get('uncertain_fail', 0) or 0)
        self.partial_once = obj.get('partial_once', {}) or {}

    def _save(self):
        obj = _a1_load_state(self.state_dir) or {}
        obj.update({
            'state': self.state,
            'reason': self.reason,
            'uncertain_until_ts': self.uncertain_until_ts,
            'uncertain_fail': self.uncertain_fail,
            'partial_once': self.partial_once,
            'coin_issues': self.coin_issues,
            'ts': time.time(),
        })
        _a1_save_state(self.state_dir, obj)

    def mark_uncertain(self, reason: str):
        now = time.time()
        self.state = 'UNCERTAIN'
        self.reason = reason
        self.uncertain_until_ts = max(self.uncertain_until_ts, now + A1_UNCERTAIN_TTL_SEC)
        self._save()

    def mark_partial_once(self, key: str):
        self.partial_once[key] = time.time()
        self._save()

    def partial_once_used(self, key: str) -> bool:
        return key in (self.partial_once or {})

    def update_from_snapshot(self, snapshot: dict, coins: list[str]):
        issues = {}
        for c in coins:
            es, en = _a1_extract_leg(snapshot, c, 'EXT')
            vs, vn = _a1_extract_leg(snapshot, c, 'VAR')
            coin_iss = []
            if (_has_leg_u(en) and (not _has_leg_u(vn))) or (_has_leg_u(vn) and (not _has_leg_u(en))):
                coin_iss.append('missing_leg')
            if _has_leg_u(en) and _has_leg_u(vn) and es != 'NONE' and vs != 'NONE' and es == vs:
                coin_iss.append('same_dir')
            if _has_leg_u(en) or _has_leg_u(vn):
                if abs(en - vn) > self.max_gap_u:
                    coin_iss.append(f'gap_gt_{self.max_gap_u:.0f}')
            if coin_iss:
                issues[c] = coin_iss
        self.coin_issues = issues

        now = time.time()
        if now < self.uncertain_until_ts:
            self.state = 'UNCERTAIN'
            if not self.reason:
                self.reason = 'uncertain_hold'
        elif issues:
            self.state = 'LEGACY_DELETED'
            self.reason = 'a1_invariant_broken'
        else:
            self.state = 'NORMAL'
            self.reason = ''
            self.uncertain_fail = 0

        self._save()
        return self.state

    def log_summary(self, snapshot: dict, coins: list[str]):
        try:
            ext_l, ext_s, var_l, var_s = _a1_count_ls_distribution(snapshot, coins)
            ok_4v4 = (ext_l == 4 and ext_s == 4 and var_l == 4 and var_s == 4)
            msg = f"[HP（最高权限）] state={self.state} reason={self.reason} | 4v4={ok_4v4} EXT(L/S)={ext_l}/{ext_s} VAR(L/S)={var_l}/{var_s}"
            _exec_log(msg)
            if self.coin_issues:
                _exec_log(f"[HP（最高权限）] coin_issues={self.coin_issues}")
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    def allow_module_in_state(self, module: str) -> bool:
        module = (module or '').upper()
        if self.state == 'NORMAL':
            return True
        return module in ('LEGACY_DELETED', 'LEGACY_DELETED', 'X1', 'Z1', 'GO', 'SYS', 'ANCHOR')

    def probe_step_u(self) -> float:
        return A1_PROBE_STEP_U if self.state == 'UNCERTAIN' else None

ANCHOR_TAKEPROFIT_PCT = float(os.environ.get("BOT_ANCHOR_TP_PCT", "0.015") or "0.015")  # 默认 1.5%
ANCHOR_STATE_FNAME = "anchor_state.json"

def _anchor_state_path() -> str:
    return _zhuangtai_path(ANCHOR_STATE_FNAME)

ANCHOR_STATE_SCHEMA_VERSION = 1

def _sanitize_anchor_state(obj: object) -> tuple[dict, str]:
    """把锚点状态文件强制规范化为稳定 schema（可自愈）。"""
    st = obj if isinstance(obj, dict) else {}
    out: dict = {
        "version": ANCHOR_STATE_SCHEMA_VERSION,
        "ts": time.time(),
    }
    raw = None
    try:
        raw = st.get("anchor_u")
    except Exception:
        raw = None

    v = None
    try:
        if raw is not None and str(raw).strip() != "":
            v = float(raw)
    except Exception:
        v = None

    if v is not None and v > 1e-6:
        out["anchor_u"] = float(v)
        out["src"] = str(st.get("src") or "state")
    else:
        out["anchor_u"] = None
        out["src"] = str(st.get("src") or "")

    for k in ("last_set_ts", "last_total_u", "note"):
        try:
            if k in st:
                out[k] = st.get(k)
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_1322', _e)
            pass
    reason = "ok" if out.get("anchor_u") is not None else "missing_or_invalid"
    return out, reason

def _save_anchor_state(st: dict) -> None:
    """原子落盘锚点状态，避免写一半导致 json 损坏。
    系统性修复点：
    - Windows 下 out/state 目录可能被同步/杀软/面板占用导致 PermissionError；
    - 发生 PermissionError 时“降噪+自保”：本进程内短暂禁用落盘，避免每轮刷屏。
    """
    try:
        if bool(globals().get("_ANCHOR_STATE_IO_DISABLED", False)):
            return
        fp = _anchor_state_path()
        if not fp:
            return
        d = os.path.dirname(fp)
        if d:
            os.makedirs(d, exist_ok=True)

        _atomic_write_json(fp, dict(st or {}))

    except PermissionError as _e:
        if not bool(globals().get("_ANCHOR_STATE_IO_WARNED", False)):
            globals()["_ANCHOR_STATE_IO_WARNED"] = True
            safe_log(lambda: f"[ANCHOR][WARN] anchor_state.json 无法写入（PermissionError），本次运行将暂时停止落盘：{_e}")
        globals()["_ANCHOR_STATE_IO_DISABLED"] = True
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

def _load_anchor_state() -> dict:
    fp = _anchor_state_path()
    existed = False
    if bool(globals().get("_ANCHOR_STATE_IO_DISABLED", False)):
        return {}

    try:
        if fp and os.path.exists(fp):
            existed = True
            with open(fp, "r", encoding="utf-8", errors="ignore") as f:
                raw = f.read()
            try:
                obj = json.loads(raw)
            except json.JSONDecodeError:
                try:
                    dec = json.JSONDecoder()
                    obj, _ = dec.raw_decode(raw.lstrip())
                except Exception as _e:
                    _log_exc(mod="SYS", stage="EXC_PASS", e=_e)
                    obj = {}
        else:
            obj = {}
    except PermissionError as _e:
        if not bool(globals().get("_ANCHOR_STATE_IO_WARNED", False)):
            globals()["_ANCHOR_STATE_IO_WARNED"] = True
            safe_log(lambda: f"[ANCHOR][WARN] anchor_state.json 无法读取（PermissionError），本次运行将停止读取：{_e}")
        globals()["_ANCHOR_STATE_IO_DISABLED"] = True
        obj = {}
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)
        obj = {}

    st, reason = _sanitize_anchor_state(obj)
    try:
        if existed and reason != "ok":
            _pin("ANCHOR_STATE", mod="SYS", coin="*", ok=0, reason="state_invalid_autofix", raw=repr(obj)[:200])
            _save_anchor_state(st)
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    return st

def _get_anchor_u(default_u: float | None = None) -> float:
    """资金锚点（Anchor）读取：状态优先，其次配置，再次全局常量，最后 default。缺失/非法会自愈回写。"""
    st = _load_anchor_state()

    try:
        v = st.get("anchor_u")
        if v is not None:
            vv = float(v)
            if vv > 1e-6:
                return vv
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    try:
        v2 = float(PEIZHI.get("zijin", {}).get("maodian_u", 0.0) or 0.0)
        if v2 > 1e-6:
            try:
                st2 = dict(st)
                st2["anchor_u"] = float(v2)
                st2["src"] = "config"
                st2["ts"] = time.time()
                _save_anchor_state(st2)
                _pin("ANCHOR_SET", mod="SYS", coin="*", ok=1, reason="use_config", anchor_u=v2)
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)
            return v2
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    try:
        v3 = float(ZIJIN_MAODIAN_U)
        if v3 > 1e-6:
            try:
                st2 = dict(st)
                st2["anchor_u"] = float(v3)
                st2["src"] = "global"
                st2["ts"] = time.time()
                _save_anchor_state(st2)
                _pin("ANCHOR_SET", mod="SYS", coin="*", ok=1, reason="use_global", anchor_u=v3)
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)
            return v3
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    if default_u is not None:
        try:
            v4 = float(default_u)
            if v4 > 1e-6:
                try:
                    st2 = dict(st)
                    st2["anchor_u"] = float(v4)
                    st2["src"] = "default"
                    st2["ts"] = time.time()
                    _save_anchor_state(st2)
                    _pin("ANCHOR_SET", mod="SYS", coin="*", ok=1, reason="use_default", anchor_u=v4)
                except Exception as _e:
                    _log_exc(mod="SYS", stage="EXC_PASS", e=_e)
                return v4
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    try:
        _pin("ANCHOR_SET", mod="SYS", coin="*", ok=0, reason="anchor_unavailable", state=repr(st)[:200])
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_1323', _e)
        pass
    return 0.0
def _get_anchor_epoch_ts() -> float:
    st = _load_anchor_state()
    try:
        return float(st.get("epoch_ts") or 0.0)
    except Exception:
        return 0.0

def _anchor_is_enabled() -> bool:
    try:
        return float(globals().get('ANCHOR_ENABLE', 1) or 1) > 0.0
    except Exception:
        return True

def _anchor_next_trigger_u(anchor_u: float, pct: float | None = None) -> float:
    try:
        au = float(anchor_u or 0.0)
    except Exception:
        au = 0.0
    try:
        pp = float(ANCHOR_TAKEPROFIT_PCT if pct is None else pct)
    except Exception:
        pp = 0.0
    if au <= 1e-9:
        return 0.0
    if pp < 0.0:
        pp = 0.0
    return float(au) * (1.0 + float(pp))

def _anchor_observe_payload(total_u: float | None = None, anchor_u: float | None = None) -> dict:
    try:
        au = float(anchor_u if anchor_u is not None else ((PEIZHI.get('zijin') or {}).get('maodian_u') or 0.0) or 0.0)
    except Exception:
        au = 0.0
    try:
        tu = float(total_u if total_u is not None else 0.0)
    except Exception:
        tu = 0.0
    try:
        pct = float(ANCHOR_TAKEPROFIT_PCT or 0.0)
    except Exception:
        pct = 0.0
    next_u = _anchor_next_trigger_u(au, pct)
    gap_u = float(tu) - float(next_u)
    remain_u = float(next_u) - float(tu)
    progress = 0.0
    try:
        if float(au) > 1e-9 and float(pct) > 1e-12:
            progress = (float(tu) - float(au)) / (float(au) * float(pct))
    except Exception:
        progress = 0.0
    try:
        progress_pct = max(0.0, min(100.0, float(progress) * 100.0))
    except Exception:
        progress_pct = 0.0
    _reset_obs = _anchor_reset_observe_payload()
    out = {
        'anchor_enabled': bool(_anchor_is_enabled()),
        'anchor_u': round(float(au), 4),
        'anchor_takeprofit_pct': round(float(pct), 6),
        'anchor_next_trigger_u': round(float(next_u), 4),
        'anchor_trigger_gap_u': round(float(gap_u), 4),
        'anchor_trigger_remain_u': round(float(remain_u), 4),
        'anchor_progress_pct': round(float(progress_pct), 4),
        'anchor_mode': 'rolling_anchor_pct',
    }
    try:
        if isinstance(_reset_obs, dict) and _reset_obs:
            out.update(_reset_obs)
    except Exception:
        pass
    return out

def _anchor_reset_observe_payload() -> dict:
    try:
        info = globals().get('_ANCHOR_OTHER_RECORDS_RESET_INFO') or {}
        if not isinstance(info, dict):
            info = {}
    except Exception:
        info = {}
    try:
        tsv = float(info.get('ts') or 0.0)
    except Exception:
        tsv = 0.0
    try:
        tsh = str(info.get('ts_human') or '').strip()
    except Exception:
        tsh = ''
    try:
        reason = str(info.get('reason') or '').strip()
    except Exception:
        reason = ''
    try:
        au = float(info.get('anchor_u') or 0.0)
    except Exception:
        au = 0.0
    try:
        cleared_rows = list(info.get('cleared') or [])
    except Exception:
        cleared_rows = []
    try:
        cleared_cnt = int(sum(1 for _x in cleared_rows if bool((_x or {}).get('cleared'))))
    except Exception:
        cleared_cnt = 0
    return {
        'anchor_reset_baseline_active': bool(tsv > 0.0),
        'anchor_reset_baseline_ts': round(float(tsv), 6),
        'anchor_reset_baseline_time': tsh,
        'anchor_reset_baseline_reason': reason,
        'anchor_reset_baseline_anchor_u': round(float(au), 4),
        'anchor_reset_baseline_cleared_cnt': int(cleared_cnt),
    }

def _anchor_truncate_file(fp: str, *, write_obj: dict | None = None) -> dict:
    out = {'path': str(fp or ''), 'cleared': False, 'mode': '', 'err': ''}
    try:
        p = str(fp or '').strip()
        if not p:
            out['err'] = 'empty_path'
            return out
        d = os.path.dirname(p) or '.'
        os.makedirs(d, exist_ok=True)
        if write_obj is None:
            with open(p, 'w', encoding='utf-8') as f:
                f.write('')
            out['mode'] = 'truncate'
        else:
            safe_write_json(p, _json_sanitize(write_obj), indent=2)
            out['mode'] = 'json_reset'
        out['cleared'] = True
        return out
    except Exception as _e:
        out['err'] = f'{type(_e).__name__}:{_e}'[:240]
        return out

def _anchor_reset_other_module_records_on_start(anchor_u: float, *, reason: str = 'anchor_bootstrap_reset') -> dict:
    try:
        if bool(globals().get('_ANCHOR_OTHER_RECORDS_RESET_DONE', False)):
            return dict(globals().get('_ANCHOR_OTHER_RECORDS_RESET_INFO') or {})
    except Exception:
        pass
    tsv = float(time.time())
    tsh = ''
    try:
        tsh = now_ts()
    except Exception:
        tsh = time.strftime('%Y-%m-%d %H:%M:%S', time.localtime(tsv))
    try:
        au = float(anchor_u or 0.0)
    except Exception:
        au = 0.0
    reset_obj = {
        'ts': tsv,
        'ts_human': tsh,
        'anchor_reset': True,
        'anchor_u': round(float(au), 4),
        'reason': str(reason or 'anchor_bootstrap_reset'),
        'note': 'ANCHOR 启动：其他模块记录已清零，从本次锚点重新开始统计。',
    }
    json_reset_paths = [
        globals().get('MODULES_FP'), globals().get('MODULES_FP_FALLBACK'),
        globals().get('PNL_FP'), globals().get('PNL_FP_FALLBACK'),
        globals().get('EXECUTOR_FP'), globals().get('EXECUTOR_FP_FALLBACK'),
    ]
    jsonl_truncate_paths = [
        globals().get('TRADES_FP'), globals().get('TRADES_FP_FALLBACK'),
        globals().get('TELEMETRY_FP'), globals().get('TELEMETRY_FP_FALLBACK'),
        os.path.join(str(globals().get('OUT_DIR') or ''), 'executor_results.jsonl'),
        os.path.join(str(globals().get('LOGS_DIR') or ''), 'executor_results.jsonl'),
        os.path.join(str(globals().get('OUT_DIR') or ''), 'executor_actions.jsonl'),
        os.path.join(str(globals().get('LOGS_DIR') or ''), 'executor_actions.jsonl'),
        _rizhi_path('bot_run.jsonl') if '_rizhi_path' in globals() else 'bot_run.jsonl',
        _rizhi_path('go_yunxing.txt') if '_rizhi_path' in globals() else 'go_yunxing.txt',
        _rizhi_path('go_baocuo.txt') if '_rizhi_path' in globals() else 'go_baocuo.txt',
        _rizhi_path('tp_koujing.jsonl') if '_rizhi_path' in globals() else 'tp_koujing.jsonl',
    ]
    seen = set()
    cleared = []
    for p in json_reset_paths:
        ps = str(p or '').strip()
        if not ps or ps in seen:
            continue
        seen.add(ps)
        cleared.append(_anchor_truncate_file(ps, write_obj=dict(reset_obj, reset_type='json_state')))
    for p in jsonl_truncate_paths:
        ps = str(p or '').strip()
        if not ps or ps in seen:
            continue
        seen.add(ps)
        cleared.append(_anchor_truncate_file(ps, write_obj=None))
    try:
        globals()['_M9_EXEC_RESULT_TAIL_CACHE'] = {'sig': None, 'rows': []}
    except Exception:
        pass
    info = {
        'ts': tsv,
        'ts_human': tsh,
        'anchor_u': round(float(au), 4),
        'reason': str(reason or 'anchor_bootstrap_reset'),
        'cleared': cleared,
    }
    globals()['_ANCHOR_OTHER_RECORDS_RESET_DONE'] = True
    globals()['_ANCHOR_OTHER_RECORDS_RESET_INFO'] = dict(info)
    try:
        _pin('ANCHOR_RESET', mod='ANCHOR', coin='ALL', ok=1, reason=str(reason or 'anchor_bootstrap_reset'), anchor_u=float(round(au, 4)), cleared_cnt=int(sum(1 for _x in cleared if bool((_x or {}).get('cleared')))))
    except Exception:
        pass
    try:
        safe_log(lambda: f"[{now_ts()}] [ANCHOR] 启动已清零其他模块记录：anchor_u={float(au):.4f} cleared={int(sum(1 for _x in cleared if bool((_x or {}).get('cleared'))))}")
    except Exception:
        pass
    return info

def _anchor_bootstrap_runtime(total_u: float, *, reason: str = "startup_total_u") -> float:
    """
    启动后本进程第一次进入 ANCHOR 检查时，用当前 total_u 强制重置为本次运行的初始锚点。
    口径：
    - 每次脚本刚启动，先把当前总权益记成新的锚点；
    - 这一步允许覆盖上次运行残留的旧锚点（即使旧锚点更高也重置）；
    - 本次运行启动完成后，后续仍只允许锚点上移，不允许下降；
    - 触发全平成功后，再把锚点抬到本次触发时的 total_u。
    """
    if str(os.environ.get('BOT_CONTROLLED_RESTART_RESUME', '')).lower() in ('1', 'true', 'yes'):
        import math
        saved = _load_anchor_state()
        anchor = float((saved or {}).get('anchor_u') or 0.0)
        if not (anchor > 0 and math.isfinite(anchor)):
            raise RuntimeError('controlled_restart_anchor_missing')
        globals()['_ANCHOR_RUNTIME_BOOTSTRAPPED'] = True
        globals()['_ANCHOR_RUNTIME_START_ANCHOR_U'] = anchor
        return anchor
    try:
        tu = float(total_u or 0.0)
    except Exception:
        tu = 0.0
    if tu <= 1e-6:
        return _get_anchor_u(default_u=tu)
    try:
        if bool(globals().get('_ANCHOR_RUNTIME_BOOTSTRAPPED', False)):
            return _get_anchor_u(default_u=tu)
    except Exception:
        pass
    try:
        fp = _anchor_state_path()
        obj = _load_anchor_state()
        try:
            obj['anchor_u'] = float(round(tu, 4))
            obj['updated_ts'] = time.time()
            obj['last_total_u'] = float(round(tu, 4))
            obj['src'] = 'runtime_startup'
            obj['reason'] = str(reason or 'startup_total_u')
        except Exception:
            obj = {'anchor_u': float(round(tu, 4)), 'updated_ts': time.time(), 'last_total_u': float(round(tu, 4)), 'src': 'runtime_startup', 'reason': str(reason or 'startup_total_u')}
        try:
            _ensure_dir(os.path.dirname(fp))
            obj2 = _json_sanitize(obj)
            safe_write_json(fp, obj2, indent=2)
        except Exception as _e:
            _log_exc(mod='SYS', stage='EXC_PASS', e=_e)
        try:
            if isinstance(PEIZHI, dict):
                PEIZHI.setdefault('zijin', {})
                PEIZHI['zijin']['maodian_u'] = float(round(tu, 4))
        except Exception as _e:
            _log_exc(mod='SYS', stage='EXC_PASS', e=_e)
        globals()['_ANCHOR_RUNTIME_BOOTSTRAPPED'] = True
        globals()['_ANCHOR_RUNTIME_START_ANCHOR_U'] = float(round(tu, 4))
        try:
            _anchor_reset_other_module_records_on_start(float(round(tu, 4)), reason='anchor_bootstrap_reset')
        except Exception as _e:
            _log_exc('ANCHOR', 'RESET_OTHER_RECORDS', _e, coin='ALL', anchor_u=float(round(tu, 4)))
        try:
            _pin('ANCHOR_BOOTSTRAP', mod='ANCHOR', coin='ALL', ok=1, reason=str(reason or 'startup_total_u'), anchor_u=float(round(tu, 4)), total_u=float(tu), next_trigger_u=float(_anchor_next_trigger_u(float(round(tu, 4)))))
        except Exception as _e:
            _log_exc(mod='SYS', stage='EXC_PASS', e=_e)
        return float(round(tu, 4))
    except Exception as _e:
        try:
            _log_exc('ANCHOR', 'BOOTSTRAP_RUNTIME', _e, coin='ALL', total_u=float(tu))
        except Exception:
            pass
        return _get_anchor_u(default_u=tu)

def _selftest_anchor_next_trigger_u() -> dict:
    try:
        a = float(_anchor_next_trigger_u(3000.0, 0.01))
        return {'ok': bool(abs(a - 3030.0) < 1e-9), 'got': a}
    except Exception as _e:
        return {'ok': False, 'err': repr(_e)}

def _selftest_anchor_reset_other_records_contract() -> dict:
    try:
        src = globals().get('_anchor_reset_other_module_records_on_start')
        return {'ok': bool(callable(src)), 'callable': bool(callable(src))}
    except Exception as _e:
        return {'ok': False, 'err': repr(_e)}

def _anchor_update(new_anchor_u: float, *, reason: str = "") -> float:
    """只上移不下移；返回更新后的 anchor_u。"""
    cur = _get_anchor_u(default_u=new_anchor_u)
    try:
        newv = float(new_anchor_u or 0.0)
    except Exception:
        newv = 0.0
    if newv <= 1e-6 or newv < cur - 1e-6:
        newv = cur
    fp = _anchor_state_path()
    obj = _load_anchor_state()
    try:
        obj["anchor_u"] = float(round(newv, 4))
        obj["updated_ts"] = time.time()
        if reason:
            obj["reason"] = str(reason)
    except Exception:
        obj = {"anchor_u": float(round(newv, 4)), "updated_ts": time.time(), "reason": str(reason)}
    try:
        _ensure_dir(os.path.dirname(fp))
        obj2 = _json_sanitize(obj)
        safe_write_json(fp, obj2, indent=2)
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    try:
        PEIZHI.setdefault("zijin", {})
        PEIZHI["zijin"]["maodian_u"] = float(round(newv, 4))
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    return float(newv)

def _anchor_bump_epoch(reason: str = "") -> None:
    """锚点触发后：重置预算统计 epoch（让预算从 0 重新计算）。"""
    fp = _anchor_state_path()
    obj = _load_anchor_state()
    try:
        obj["epoch_ts"] = time.time()
        if reason:
            obj["epoch_reason"] = str(reason)
    except Exception:
        obj = {"epoch_ts": time.time(), "epoch_reason": str(reason)}
    try:
        _ensure_dir(os.path.dirname(fp))
        obj2 = _json_sanitize(obj)
        safe_write_json(fp, obj2, indent=2)
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

def _anchor_should_trigger(total_u: float, anchor_u: float) -> bool:

    try:
        if not _anchor_is_enabled():
            return False
    except Exception:
        return False
    try:
        if float(ANCHOR_TAKEPROFIT_PCT or 0.0) <= 0.0:
            return False
    except Exception:
        return False
    try:
        tu = float(total_u or 0.0)
        au = float(anchor_u or 0.0)
        nxt = float(_anchor_next_trigger_u(au))
        if au <= 1e-6 or nxt <= 1e-6:
            return False
        return tu >= nxt
    except Exception:
        return False

_LOG_RETENTION_TARGET_BASENAMES = {
    "bot_console.log", "bot_console.txt",
    "system_observe.log", "system_observe.log.1",
    "machine_debug_full.jsonl", "full_all.jsonl",
    "executor_actions.jsonl", "executor_results.jsonl", "exec_results.jsonl",
    "readiness_audit.jsonl", "trace_events.jsonl", "arbitration_audit.jsonl",
    "telemetry.jsonl", "var_pos_diag.jsonl", "var_pos_scan.jsonl",
    "m10_profile.jsonl", "runtime_version.jsonl", "module_m9.jsonl",
    "round_summary.jsonl", "round_priority_rank.jsonl", "m9_reason_rank.jsonl",
    "bot_grid_full.jsonl", "bot_grid_full.txt", "panel_spawn_stdout.txt",
    "go_baocuo.txt", "bot_error.txt",
}
_LOG_RETENTION_TARGET_PREFIXES = ("bot_console_", "system_observe.log.")
_LOG_RETENTION_KEEP_SEC = 24.0 * 3600.0
_LOG_RETENTION_CLEAN_EVERY_SEC = 300.0
_LOG_RETENTION_LAST_CLEAN = {}
_LOG_RETENTION_HOUSEKEEP_LAST_TS = 0.0
_LOG_RETENTION_PROTECTED_BASENAMES = {
    "trades.jsonl", "positions.json", "equity.json", "status.json", "control.json",
    "modules.json", "coin_pool_state.json", "ind_cache.json", "pnl_attrib.json", "executor.json",
    "m9_wangge_zhangben.json", "grid_rate_pause_ledger.json",
}
_LOG_RETENTION_PROTECTED_KEYWORDS = (
    "grid", "wangge", "ledger", "review_report", "review_reports",
    "daily_review", "sentiment_daily_", "review_metrics_",
)
_LOG_RETENTION_DELETE_IMAGE_DIRS = {"debug_exec"}
_LOG_RETENTION_DELETE_IMAGE_PREFIXES = ("human_verify_",)

def _log_retention_target_path(path: str) -> str:
    try:
        return os.path.abspath(str(path or ""))
    except Exception:
        return str(path or "")

def _retention_is_protected_path(path: str) -> bool:
    try:
        ap = os.path.abspath(str(path or ""))
        base = os.path.basename(ap).lower()
        if not base:
            return True
        if base in _LOG_RETENTION_PROTECTED_BASENAMES:
            return True
        joined = ap.replace('\\', '/').lower()
        return any(k in joined for k in _LOG_RETENTION_PROTECTED_KEYWORDS)
    except Exception:
        return True

def _retention_should_delete_image(path: str, now_ts: float | None = None) -> bool:
    try:
        ap = os.path.abspath(str(path or ""))
        if not os.path.isfile(ap):
            return False
        base = os.path.basename(ap).lower()
        ext = os.path.splitext(base)[1].lower()
        if ext not in ('.png', '.jpg', '.jpeg', '.webp'):
            return False
        parent = os.path.basename(os.path.dirname(ap)).lower()
        allowed = (parent in _LOG_RETENTION_DELETE_IMAGE_DIRS) or any(base.startswith(pfx) for pfx in _LOG_RETENTION_DELETE_IMAGE_PREFIXES)
        if not allowed:
            return False
        age = float(now_ts if now_ts is not None else time.time()) - float(os.path.getmtime(ap) or 0.0)
        return age > float(_LOG_RETENTION_KEEP_SEC)
    except Exception:
        return False

def _retention_should_trim_path(path: str) -> bool:
    try:
        ap = os.path.abspath(str(path or ""))
        base = os.path.basename(ap).lower()
        if not base:
            return False
        if _retention_is_protected_path(ap):
            return False
        if base in _LOG_RETENTION_TARGET_BASENAMES:
            return True
        if any(base.startswith(pfx) for pfx in _LOG_RETENTION_TARGET_PREFIXES):
            return True
        parent = os.path.basename(os.path.dirname(ap)).lower()
        ext = os.path.splitext(base)[1].lower()
        if parent == 'logs8' and base.endswith('.jsonl'):
            return True
        if _retention_is_runtime_dir_file(ap):
            if ext in ('.jsonl', '.log'):
                return True
            if base in {'bot_console.txt', 'go_baocuo.txt', 'panel_spawn_stdout.txt', 'bot_error.txt'}:
                return True
        return False
    except Exception:
        return False

def _retention_scan_dirs() -> list[str]:
    out = []
    seen = set()
    for raw in (globals().get('OUT_DIR'), globals().get('LOGS_DIR'), os.path.join(os.path.dirname(__file__), 'out'), os.path.join(os.path.dirname(__file__), 'logs')):
        try:
            p = os.path.abspath(str(raw or ''))
        except Exception:
            p = str(raw or '')
        if not p or p in seen or (not os.path.isdir(p)):
            continue
        seen.add(p)
        out.append(p)
    return out

def _retention_is_runtime_dir_file(path: str) -> bool:
    try:
        ap = os.path.abspath(str(path or '')).replace('\\', '/').lower()
        if not ap:
            return False
        for root in _retention_scan_dirs():
            try:
                rp = os.path.abspath(str(root or '')).replace('\\', '/').lower().rstrip('/') + '/'
            except Exception:
                rp = str(root or '').replace('\\', '/').lower().rstrip('/') + '/'
            if rp and ap.startswith(rp):
                return True
        return False
    except Exception:
        return False

def _retention_housekeep_maybe(now_ts: float | None = None) -> None:
    global _LOG_RETENTION_HOUSEKEEP_LAST_TS
    try:
        nv = float(now_ts if now_ts is not None else time.time())
        if (nv - float(_LOG_RETENTION_HOUSEKEEP_LAST_TS or 0.0)) < float(_LOG_RETENTION_CLEAN_EVERY_SEC):
            return
        _LOG_RETENTION_HOUSEKEEP_LAST_TS = nv
        for root in _retention_scan_dirs():
            try:
                for dirpath, _, filenames in os.walk(root):
                    for name in filenames:
                        fp = os.path.join(dirpath, name)
                        try:
                            if _retention_should_delete_image(fp, nv):
                                os.remove(fp)
                                continue
                            if _retention_should_trim_path(fp):
                                if fp.lower().endswith('.jsonl'):
                                    _cleanup_jsonl_keep_recent(fp, nv, _LOG_RETENTION_KEEP_SEC)
                                else:
                                    _cleanup_text_keep_recent(fp, nv, _LOG_RETENTION_KEEP_SEC)
                                continue
                            base = os.path.basename(fp).lower()
                            if any(base.startswith(pfx) for pfx in _LOG_RETENTION_TARGET_PREFIXES):
                                age = nv - float(os.path.getmtime(fp) or 0.0)
                                if age > float(_LOG_RETENTION_KEEP_SEC):
                                    os.remove(fp)
                        except Exception:
                            continue
            except Exception:
                continue
    except Exception:
        return

def _log_retention_enabled(path: str) -> bool:
    try:
        return _retention_should_trim_path(path)
    except Exception:
        return False

def _log_retention_should_clean(path: str, now_ts: float | None = None) -> bool:
    try:
        if not _log_retention_enabled(path):
            return False
        nv = float(now_ts if now_ts is not None else time.time())
        key = _log_retention_target_path(path)
        lv = float(_LOG_RETENTION_LAST_CLEAN.get(key) or 0.0)
        if (nv - lv) < float(_LOG_RETENTION_CLEAN_EVERY_SEC):
            return False
        _LOG_RETENTION_LAST_CLEAN[key] = nv
        return True
    except Exception:
        return False

def _parse_line_ts_for_retention(line: str, prev_ts: float | None = None) -> float | None:
    try:
        s = str(line or "").strip()
        if not s:
            return prev_ts
        m = re.search(r"\bts=(\d{10}(?:\.\d+)?)", s)
        if m:
            return float(m.group(1))
        m = re.match(r"^\[(\d{10}(?:\.\d+)?)\]", s)
        if m:
            return float(m.group(1))
        m = re.match(r"^\[(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2})\]", s)
        if m:
            try:
                return datetime.strptime(m.group(1), "%Y-%m-%d %H:%M:%S").timestamp()
            except Exception:
                return prev_ts
        m = re.search(r"(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2})", s)
        if m:
            try:
                return datetime.strptime(m.group(1), "%Y-%m-%d %H:%M:%S").timestamp()
            except Exception:
                return prev_ts
        return prev_ts
    except Exception:
        return prev_ts

def _cleanup_jsonl_keep_recent(path: str, now_ts: float | None = None, keep_sec: float | None = None) -> None:
    try:
        fp = str(path or "")
        if not fp or (not os.path.exists(fp)):
            return
        cutoff = float(now_ts if now_ts is not None else time.time()) - float(keep_sec or _LOG_RETENTION_KEEP_SEC)
        tmp = fp + '.retention.tmp'
        kept = False
        with open(fp, 'r', encoding='utf-8', errors='ignore') as fr, open(tmp, 'w', encoding='utf-8', errors='replace') as fw:
            for ln in fr:
                s = (ln or '').strip()
                if not s:
                    continue
                try:
                    obj = json.loads(s)
                except Exception:
                    continue
                tsv = None
                try:
                    tsv = float(obj.get('ts')) if obj.get('ts') is not None else None
                except Exception:
                    tsv = None
                if tsv is None:
                    try:
                        dtv = str(obj.get('dt') or '')
                        if dtv:
                            tsv = datetime.strptime(dtv[:19], '%Y-%m-%d %H:%M:%S').timestamp()
                    except Exception:
                        tsv = None
                if tsv is None:
                    continue
                if tsv >= cutoff:
                    fw.write(s + '\n')
                    kept = True
        os.replace(tmp, fp)
    except Exception:
        try:
            if 'tmp' in locals() and os.path.exists(tmp):
                os.remove(tmp)
        except Exception:
            pass

def _cleanup_text_keep_recent(path: str, now_ts: float | None = None, keep_sec: float | None = None) -> None:
    try:
        fp = str(path or "")
        if not fp or (not os.path.exists(fp)):
            return
        cutoff = float(now_ts if now_ts is not None else time.time()) - float(keep_sec or _LOG_RETENTION_KEEP_SEC)
        tmp = fp + '.retention.tmp'
        last_ts = None
        with open(fp, 'r', encoding='utf-8', errors='ignore') as fr, open(tmp, 'w', encoding='utf-8', errors='replace') as fw:
            for ln in fr:
                cur_ts = _parse_line_ts_for_retention(ln, last_ts)
                if cur_ts is not None:
                    last_ts = cur_ts
                eff_ts = cur_ts if cur_ts is not None else last_ts
                if eff_ts is None:
                    continue
                if float(eff_ts) >= cutoff:
                    fw.write(ln if ln.endswith('\n') else (ln + '\n'))
        os.replace(tmp, fp)
    except Exception:
        try:
            if 'tmp' in locals() and os.path.exists(tmp):
                os.remove(tmp)
        except Exception:
            pass

def _cleanup_retention_target(path: str, now_ts: float | None = None) -> None:
    try:
        fp = str(path or '')
        nv = float(now_ts if now_ts is not None else time.time())
        if _log_retention_enabled(fp):
            if _log_retention_should_clean(fp, nv):
                if fp.endswith('.jsonl'):
                    _cleanup_jsonl_keep_recent(fp, nv)
                else:
                    _cleanup_text_keep_recent(fp, nv)
        _retention_housekeep_maybe(nv)
    except Exception:
        pass

def _append_txt(path: str, line: str) -> None:
    if not path:
        return
    try:
        _ensure_dir(os.path.dirname(path))
        with open(path, "a", encoding="utf-8") as f:
            f.write(line.rstrip("\n") + "\n")
        try:
            _cleanup_retention_target(path)
        except Exception:
            pass
        try:
            _legacy = globals().get("fp_baocuo_legacy", "") or ""
            if _legacy and os.path.abspath(_legacy) != os.path.abspath(path) and str(path).endswith("go_baocuo.txt"):
                _ensure_dir(os.path.dirname(_legacy))
                with open(_legacy, "a", encoding="utf-8") as f2:
                    f2.write(line.rstrip("\n") + "\n")
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

def _log_exc(mod: str, stage: str, e: Exception, *, coin: str = "", **ctx) -> None:
    """统一异常落盘 + 证据针（不要吞异常导致“没执行但看不出原因”）"""
    try:
        import traceback as _tb
        import os as _os
        _loc = ""
        try:
            _t = e.__traceback__
            while _t and _t.tb_next:
                _t = _t.tb_next
            if _t and getattr(_t, 'tb_frame', None):
                _f = _t.tb_frame
                _loc = f"{_os.path.basename(str(_f.f_code.co_filename))}:{int(_t.tb_lineno)}:{str(_f.f_code.co_name)}"
        except Exception:
            _loc = ""
        if _loc and ('loc' not in ctx):
            ctx['loc'] = _loc
        if 'tb_tail' not in ctx:
            try:
                _lines = _tb.format_exception(type(e), e, e.__traceback__)
                _tail = "".join(_lines[-2:]).strip()
                if _tail:
                    ctx['tb_tail'] = _tail[:800]
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_1324', _e)
                pass
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_1325', _e)
        pass
    try:
        if _is_target_closed_exc(e):
            globals()['_UI_DEAD_TS'] = float(time.time())
            globals()['_UI_DEAD_MOD'] = str(mod or '')
            globals()['_UI_DEAD_STAGE'] = str(stage or '')
            globals()['_UI_DEAD_ERR'] = repr(e)
            try:
                _pw_runtime_hard_reset(f"{str(mod or 'SYS')}|{str(stage or 'EXC')}|target_closed", source=str(mod or "SYS"), touch_scan=(str(mod or '').upper() in ("M2", "SCAN", "SYS")))
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_1326', _e)
                pass
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_1327', _e)
        pass
    try:
        if str(stage) == "EXC_PASS" and e is not None:
            _loc_s = str((ctx or {}).get("loc") or "")
            _mod_s = str(mod or "").upper()
            _msg_s = f"{type(e).__name__}:{repr(e)}"
            if _is_target_closed_exc(e):
                stage = "UI_DEAD_SWALLOWED"
            elif _is_link_error_exc(e):
                stage = "UI_LINK_SWALLOWED"
            elif any(_k in _loc_s for _k in ("submit_request", "_exec_", "executor_place_order", "_exe_", "_executor_")) or _mod_s in ("EXEC", "EXE", "ORDER", "SUBMIT"):
                stage = "EXEC_SWALLOWED"
            elif any(_k in _loc_s for _k in ("tv_read_", "iter_contexts", "legend_count", "_ind_", "indicator", "adx", "rsi")) or _mod_s in ("IND", "TV", "ADX", "RSI"):
                stage = "IND_SWALLOWED"
            elif any(_k in _loc_s for _k in ("scan_positions", "m2_scan", "read_positions", "pick_page", "read_coin_row", "positions_table")) or _mod_s in ("M2", "SCAN"):
                stage = "SCAN_SWALLOWED"
            elif any(_k in _loc_s for _k in ("legacy_deleted", "missing_leg", "hedge")) or _mod_s in ("LEGACY_DELETED", "X1", "LEGACY_DELETED"):
                stage = "LEGACY_DELETED_SWALLOWED"
            elif any(_k in _loc_s for _k in ("write_json", "append_jsonl", "_log_jsonl", "atomic_write", "open(", "write(")) or _mod_s in ("IO", "WRITE", "JSON"):
                stage = "IO_SWALLOWED"
            elif any(_k in _msg_s.lower() for _k in ("permission denied", "no such file", "disk", "ioerror")):
                stage = "IO_SWALLOWED"
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_1328', _e)
        pass
    try:
        if str(stage) == "EXC_PASS":
            _rl = globals().setdefault("_EXC_PASS_RL", {})
            _fn = ""
            try:
                _fn = str(getattr(e, "filename", "") or "")
            except Exception:
                _fn = ""
            _key = f"{str(mod)}|{str(stage)}|{type(e).__name__}|{_fn}|{repr(e)}"
            _now = time.time()
            _last, _sup = _rl.get(_key, (0.0, 0))
            try:
                _last = float(_last)
            except Exception:
                _last = 0.0
            try:
                _sup = int(_sup)
            except Exception:
                _sup = 0
            if (_now - _last) < 10.0:
                _rl[_key] = (_last, _sup + 1)
                return
            if _sup:
                try:
                    ctx = dict(ctx) if isinstance(ctx, dict) else {}
                    ctx["suppressed"] = _sup
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_1329', _e)
                    pass
            _rl[_key] = (_now, 0)
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_1330', _e)
        pass
    try:
        if str(stage) == "WRITE_FAIL":
            _rl = globals().setdefault("_WRITE_FAIL_RL", {})
            _path = ""
            try:
                _path = str(ctx.get("path", "") or ctx.get("fp", "") or "")
            except Exception:
                _path = ""
            _key = f"{str(mod)}|{str(stage)}|{type(e).__name__}|{_path}|{repr(e)}"
            _now = time.time()
            _last, _sup = _rl.get(_key, (0.0, 0))
            try:
                _last = float(_last)
            except Exception:
                _last = 0.0
            try:
                _sup = int(_sup)
            except Exception:
                _sup = 0

            if (_now - _last) < 30.0:
                _rl[_key] = (_last, _sup + 1)
                try:
                    rec = {
                        "ts": now_ts() if callable(globals().get("now_ts", None)) else float(_now),
                        "mod": str(mod),
                        "stage": str(stage),
                        "coin": str(coin or ""),
                        "ok": 0,
                        "key": _key,
                        "suppressed_inc": 1,
                        "err": repr(e),
                        "ctx": dict(ctx) if isinstance(ctx, dict) else {},
                    }
                    for _fp in ("out/io_fail_dedupe.jsonl", "logs/io_fail_dedupe.jsonl"):
                        try:
                            with safe_open(_fp, "a", encoding="utf-8", errors="replace") as _f:
                                _f.write(json.dumps(rec, ensure_ascii=False, default=globals().get("_json_default_for_bot")) + "\n")
                        except Exception as _e:
                            _record_swallowed_exception('except_pass_line_1331', _e)
                            pass
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_1332', _e)
                    pass
                return

            if _sup:
                try:
                    ctx = dict(ctx) if isinstance(ctx, dict) else {}
                    ctx["suppressed"] = _sup
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_1333', _e)
                    pass
            _rl[_key] = (_now, 0)
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_1334', _e)
        pass
    try:
        fp = str(globals().get("fp_baocuo", "") or "go_baocuo.txt")
    except Exception:
        fp = "go_baocuo.txt"
    try:
        ctx2 = {}
        if isinstance(ctx, dict):
            for k, v in ctx.items():
                try:
                    ctx2[str(k)] = v if isinstance(v, (str, int, float, bool, type(None), list, dict)) else repr(v)
                except Exception:
                    ctx2[str(k)] = repr(v)
        else:
            ctx2 = {}
        line = f"[EXC][{str(mod)}][{str(stage)}] coin={str(coin)} err={repr(e)} ctx={ctx2}"
        _append_txt(fp, line)
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_1335', _e)
        pass
    try:
        _g = globals()
        if not _g.get('_LOG_EXC_GUARD_GO', False):
            _g['_LOG_EXC_GUARD_GO'] = True
            try:
                _go_baocuo_write({
                    'ts': now_ts() if callable(globals().get('now_ts', None)) else time.time(),
                    'mod': str(mod),
                    'stage': str(stage),
                    'coin': str(coin or ''),
                    'ok': 0,
                    'reason': f"{type(e).__name__}:{str(e)[:180]}",
                    'ctx': ctx2,
                })
            finally:
                _g['_LOG_EXC_GUARD_GO'] = False
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_1336', _e)
        pass
    try:
        _pin("EXC", mod=str(mod or ""), coin=str(coin or ""), ok=0, reason=str(stage or ""), err=repr(e), **(ctx2 or {}))
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_1337', _e)
        pass
def _trace_event(event: str, **fields) -> None:
    try:
        base_dir = os.path.dirname(os.path.abspath(__file__))
        out_dir = os.path.join(base_dir, "out")
        os.makedirs(out_dir, exist_ok=True)
        fp = os.path.join(out_dir, "trace_events.jsonl")
        fields = dict(fields or {})
        fields["event"] = str(event or "")
        try:
            fields["ts"] = now_ts()
        except Exception:
            fields["ts"] = str(time.time())
        try:
            with open(fp, "a", encoding="utf-8") as f:
                f.write(_json_dumps_bot(fields, separators=(",", ":")) + "\n")
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

        try:
            if fields.get("to_console"):
                _c = str(fields.get("coin") or "")
                _m = str(fields.get("module") or "")
                _rc = str(fields.get("reject_code") or "")
                _ok = fields.get("ok")
                print(f"[{fields.get('ts')}] [TRACE] {event} mod={_m} coin={_c} ok={_ok} rc={_rc}")
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

def _print_go_accept_reject_full(menhu: 'GOMenHu', coins: list[str], modules: list[str]|None=None,
                                platforms: tuple[str, ...]=("EXT","VAR","PAIR"), *,
                                fp_yunxing: str|None=None,
                                max_lines: int = 500) -> None:
    """
    打印 M1 对每个币每个模块的接受/拒绝/跳过原因（你要求：每轮都输出）。
    - 接受（ACCEPT）：说明执行/入队原因（优先取 req.reason/trigger/why）
    - 拒绝（REJECT）：给出 reject_code + reject_reason
    - 跳过（SKIP）：说明本轮该模块未产生请求（no_request）
    """
    try:
        if modules is None:
            modules = ["GO","B2","M10","M9","B1"]
        try:
            events = menhu.probe_events_since(0)
        except Exception:
            events = []
        idx: dict[tuple[str,str,str], list[dict]] = {}
        for e in (events or []):
            c = str(e.get("coin") or "").upper()
            m = str(e.get("module") or "").upper()
            p = str(e.get("platform") or "").upper()
            idx.setdefault((c,m,p), []).append(e)

        rows: list[str] = []
        header = "COIN  MODULE PLATFORM DECISION ACTION      INTENT_U  STD_U   WHY/REASON"
        rows.append(header)
        rows.append("-"*len(header))

        def _fmt_u(v):
            try:
                if v is None or v == "":
                    return "-"
                return str(int(round(float(v))))
            except Exception:
                return str(v)[:10]

        for coin in [c.upper() for c in coins]:
            for mod in [m.upper() for m in modules]:
                for plat in [p.upper() for p in platforms]:
                    evs = idx.get((coin, mod, plat), [])
                    if not evs:
                        rows.append(f"{coin:<5} {mod:<6} {plat:<8} {'SKIP':<8} {'-':<10} {'-':<8} {'-':<7} no_request")
                        continue
                    e = evs[-1]
                    ok = (e.get("ok") is True)
                    decision = "ACCEPT" if ok else "REJECT"
                    action = str(e.get("action_type") or "-")[:10]
                    intent_u = _fmt_u(e.get("intent_amount"))
                    std_u = _fmt_u(e.get("std_amount"))
                    trig = str(e.get("trigger") or "").strip()
                    code = str(e.get("reject_code") or "").strip()
                    reason = str(e.get("reject_reason") or "").strip()
                    if ok:
                        why = trig if trig else ""
                        if code and reason:
                            extra = f"{code}:{reason}"
                            why = (why + " | " + extra).strip(" |") if why else extra
                        if not why:
                            why = "pass"
                    else:
                        why = f"{code}:{reason}".strip(":")
                        if trig:
                            why = f"{trig} | {why}" if why else trig
                        if not why:
                            why = "rejected"
                    rows.append(f"{coin:<5} {mod:<6} {plat:<8} {decision:<8} {action:<10} {intent_u:<8} {std_u:<7} {why}")

        print("")
        print("==== M1 逐币逐模块 接受/拒绝/跳过 明细（本轮）====")
        for i, line in enumerate(rows):
            if i >= max_lines:
                print(f"...(省略，已达 max_lines={max_lines})")
                break
            print(line)
        print("==== 结束（M1 明细）====")
        print("")

        if fp_yunxing:
            try:
                _append_txt(fp_yunxing, "")
                _append_txt(fp_yunxing, "==== GO_DECISION_TABLE ====")
                for i, line in enumerate(rows):
                    if i >= max_lines:
                        _append_txt(fp_yunxing, f"...(省略，已达 max_lines={max_lines})")
                        break
                    _append_txt(fp_yunxing, line)
                _append_txt(fp_yunxing, "==== END_GO_DECISION_TABLE ====")
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

def _sleep_heartbeat(total_sec: float, *, next_shijian: str = "", interval_sec: int = 1, fp_yunxing: str | None = None, reason: str = "") -> dict:
    """轻量心跳等待：不刷屏，但不再整段阻塞。

    修复点：
    - 旧实现会让用户只看到“一个 next_scan 时间”，却看不清它是不是当前轮真时间；
    - 现在 sleep 期间统一从 _SCAN_SLEEP_PLAN 取真源，并把“正常等待 / 已到时间 / 错过唤醒”写进状态文件。
    """
    try:
        total_sec = float(total_sec)
    except Exception:
        total_sec = 0.0
    if total_sec <= 0:
        return {"wake_state": "IDLE", "recover_triggered": False, "wake_ok": False}

    try:
        interval_sec = int(interval_sec)
    except Exception:
        interval_sec = 1
    if interval_sec <= 0:
        interval_sec = 1

    _start_ts = float(time.time())
    _end_ts = _start_ts + float(total_sec)
    _next_tick_ts = _start_ts

    if fp_yunxing:
        try:
            tag = f"心跳等待开始：total={int(total_sec)}s"
            if next_shijian:
                tag += f" next={next_shijian}"
            if reason:
                tag += f" reason={reason}"
            _append_txt(fp_yunxing, tag)
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    _result = {"wake_state": "WAITING", "recover_triggered": False, "wake_ok": False, "deadline_text": str(next_shijian or "")}

    while True:
        _now = float(time.time())
        _plan = _scan_sleep_plan_touch(nowv=_now, reason=reason, extra={"loop_total_sec": int(max(0, round(total_sec)))})
        _plan = _scan_sleep_plan_mark_wake_check(nowv=_now, source="SLEEP_HEARTBEAT") or _plan
        try:
            _deadline_ts = float((_plan or {}).get("deadline_ts") or 0.0)
        except Exception:
            _deadline_ts = 0.0
        _active_deadline = bool((_plan or {}).get("active")) and _deadline_ts > 0
        _left = (_deadline_ts - _now) if _active_deadline else (_end_ts - _now)
        _wake_state = str((_plan or {}).get("wake_state") or "")
        _display_state = str((_plan or {}).get("display_state") or "正常等待下一轮")
        _deadline_text = str((_plan or {}).get("deadline_text") or next_shijian or "")
        _remain_sec = int((_plan or {}).get("remain_sec") or max(0, int(round(_left))))
        _overdue_sec = float((_plan or {}).get("overdue_sec") or 0.0)
        _result.update({
            "wake_state": _wake_state,
            "deadline_text": _deadline_text,
            "overdue_sec": float(_overdue_sec),
            "remain_sec": int(max(0, _remain_sec)),
        })

        if _wake_state == "WAKE_MISSED":
            _plan = _scan_sleep_plan_finish_wake(nowv=_now, source="SLEEP_HEARTBEAT", recover=True, note="force_next_round") or _plan
            _result.update({"wake_state": "WAKE_MISSED", "recover_triggered": True, "wake_ok": False, "plan": dict(_plan or {})})
            break

        if _left <= 0:
            _plan = _scan_sleep_plan_finish_wake(nowv=_now, source="SLEEP_HEARTBEAT", recover=False) or _plan
            _result.update({"wake_state": str((_plan or {}).get("wake_state") or _wake_state or "WAKE_DUE"), "recover_triggered": False, "wake_ok": True, "plan": dict(_plan or {})})
            break

        if _now >= _next_tick_ts:
            _round_watchdog_raise_if_tripped()
            try:
                _wake_text = "错过唤醒" if _wake_state == "WAKE_MISSED" else ("已到扫描时间，等待唤醒" if _wake_state == "WAKE_DUE" else "未到扫描时间")
                panel_update_heartbeat({
                    "phase": "sleep_wait",
                    "left_sec": int(max(0, _remain_sec)),
                    "total_sec": int(max(0, round(total_sec))),
                    "next_scan": _deadline_text,
                    "reason": str(reason or ""),
                    "sleep_state": _display_state,
                    "sleep_state_text": _display_state,
                    "wake_state": _wake_state,
                    "wake_state_text": _wake_text,
                    "overdue_sec": float(_overdue_sec),
                    "status_text": f"{_display_state}｜{_wake_text}",
                    "ts": _now,
                })
            except Exception as _e:
                _log_exc(mod="PANEL", stage="HEARTBEAT_TICK", e=_e)

            try:
                if _wake_state == "WAKE_MISSED":
                    _hint = f"错过唤醒：计划 {_deadline_text}，已超时 {int(_overdue_sec)} 秒"
                    panel_set_mainloop_state('WAKE_MISSED', hint=_hint[:200], err=_hint[:240])
                elif _wake_state == "WAKE_DUE":
                    _hint = f"已到扫描时间，等待唤醒：{_deadline_text}"
                    panel_set_mainloop_state('RUNNING', hint=_hint[:200])
                else:
                    _wait_label = "数据校验失败，等待重试" if (_plan or {}).get('plan_source') == 'dq_retry' else "正常等待下一轮"
                    _hint = f"{_wait_label}：{_deadline_text}，剩余 {max(0, int(_remain_sec))} 秒"
                    panel_set_mainloop_state('RUNNING', hint=_hint[:200])
            except Exception as _e:
                _log_exc(mod="PANEL", stage="HEARTBEAT_STATE", e=_e)

            if fp_yunxing:
                try:
                    _append_txt(fp_yunxing, f"心跳等待中：state={_display_state} wake={_wake_state} left={max(0, int(_remain_sec))}s overdue={int(_overdue_sec)}s next={_deadline_text or '-'} reason={reason or '-'}")
                except Exception as _e:
                    _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

            try:
                _maybe_budget_report()
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

            try:
                _maybe_system_report(force=False)
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

            _next_tick_ts = _now + float(interval_sec)

        _sleep_slice = min(1.0, max(0.05, _left))
        _round_watchdog_raise_if_tripped()
        try:
            _ORIG_TIME_SLEEP(_sleep_slice)
        except Exception:
            break

    _plan_end = _scan_sleep_plan_snapshot() or (_result.get("plan") if isinstance(_result, dict) else {}) or _scan_sleep_plan_mark_wake_check(nowv=float(time.time()), source="SLEEP_HEARTBEAT_DONE")
    try:
        panel_update_heartbeat({
            "phase": "sleep_wait_done",
            "left_sec": 0,
            "total_sec": int(max(0, round(total_sec))),
            "next_scan": str((_plan_end or {}).get("deadline_text") or next_shijian or ""),
            "reason": str(reason or ""),
            "sleep_state": str((_plan_end or {}).get("display_state") or "正常等待下一轮"),
            "wake_state": str((_plan_end or {}).get("wake_state") or "IDLE"),
            "overdue_sec": float((_plan_end or {}).get("overdue_sec") or 0.0),
            "ts": float(time.time()),
        })
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_1338', _e)
        pass
    return dict(_result or {})

_TIME_SLEEP_PATCH_TLS = threading.local()

def _cooperative_time_sleep(total_sec: float, *, reason: str = "") -> None:
    """全局 time.sleep 兜底：主线程里较长等待自动变成可观测等待。

    人话：
    - 你这份代码里历史上散落了很多直接 time.sleep；
    - 逐个改容易漏；
    - 这里做一层全局兜底，只拦主线程、只拦较长等待，短等待仍走原生 sleep。
    """
    try:
        s = float(total_sec or 0.0)
    except Exception:
        try:
            _ORIG_TIME_SLEEP(total_sec)
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_1339', _e)
            pass
        return

    if s <= 0:
        return

    if s < 0.8:
        _ORIG_TIME_SLEEP(s)
        return

    try:
        if threading.current_thread() is not threading.main_thread():
            _ORIG_TIME_SLEEP(s)
            return
    except Exception:
        _ORIG_TIME_SLEEP(s)
        return

    if getattr(_TIME_SLEEP_PATCH_TLS, "busy", False):
        _ORIG_TIME_SLEEP(s)
        return

    _TIME_SLEEP_PATCH_TLS.busy = True
    try:
        _reason = str(reason or "")
        if not _reason:
            try:
                import inspect as _inspect
                _fr = _inspect.currentframe()
                _bk = _fr.f_back if _fr else None
                if _bk is not None:
                    _reason = f"{_bk.f_code.co_name}:{_bk.f_lineno}"
            except Exception:
                _reason = ""

        _hb = globals().get("_sleep_heartbeat")
        if callable(_hb):
            try:
                _hb(s, next_shijian="", interval_sec=1, fp_yunxing=None, reason=_reason)
                return
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_1340', _e)
                pass
        _ORIG_TIME_SLEEP(s)
    finally:
        _TIME_SLEEP_PATCH_TLS.busy = False

def _install_time_sleep_patch() -> None:
    try:
        if getattr(time, "sleep", None) is _cooperative_time_sleep:
            return
        time.sleep = _cooperative_time_sleep
    except Exception as _e:
        try:
            _log_exc(mod="SYS", stage="TIME_SLEEP_PATCH_FAIL", e=_e)
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_1341', _e)
            pass
_install_time_sleep_patch()

_BUDGET_LAST_PRINT_TS: float = 0.0
_BUDGET_LAST_SNAPSHOT: dict | None = None
_BUDGET_LAST_TOTAL_U: float | None = None
_BUDGET_LAST_COINS: list[str] | None = None

def _leg_value_u(leg: dict) -> float:
    """从单腿 leg（腿）里提取名义（U）数值。"""
    if not isinstance(leg, dict):
        return 0.0
    for k in ("value_usd", "notional_u", "notional_usd", "value", "notional", "usd", "u"):
        if k in leg:
            try:
                v = float(leg.get(k) or 0.0)
                if abs(v) > 1e-12:
                    return v
            except Exception:
                continue
    return 0.0

def _coin_exposure_u(snapshot: dict, coin: str) -> float:
    """双腿名义暴露（U）：abs(EXT) + abs(VAR)。"""
    try:
        leg_ext = _get_snapshot_coin_leg(snapshot, coin, "EXT")
        leg_var = _get_snapshot_coin_leg(snapshot, coin, "VAR")
        v1 = abs(_leg_value_u(leg_ext))
        v2 = abs(_leg_value_u(leg_var))
        return float(v1 + v2)
    except Exception:
        return 0.0

DISABLE_BUDGET = True  # [PATCH] 取消网格预算桶：永远不作为门禁

_BUDGET_HUGE_U = 1e15  # 预算关闭时的虚拟无限额度（U）

def _alloc_budget_buckets(exposure_u: float, total_u: float) -> dict:
    """按 15% / 50% / 35% 分桶计算（open/grid/safe_legacy_fix）。
    说明：
    - 原有  桶已删除（用户确认不再使用），因此不再分配/展示 loss 桶。
    - DISABLE_BUDGET=True 时仅用于展示（桶 remain 视为无限），不参与拦截。
    """
    total_u = float(total_u or 0.0)
    exposure_u = float(exposure_u or 0.0)

    if bool(globals().get("DISABLE_BUDGET", False)):
        huge = float(globals().get("_BUDGET_HUGE_U", 1e15) or 1e15)
        return {
            "open": {"cap": huge, "used": 0.0, "remain": huge},
            "grid": {"cap": huge, "used": 0.0, "remain": huge},
            "safe_legacy_fix": {"cap": huge, "used": 0.0, "remain": huge},
        }

    try:
        yus = (PEIZHI.get("yusuan") or {}) if isinstance(PEIZHI, dict) else {}
    except Exception:
        yus = {}
    r_open = float(yus.get("kai_u_bili", 0.15) or 0.15)
    r_grid = float(yus.get("wangge_u_bili", 0.50) or 0.50)
    r_safe = float(yus.get("safe_u_bili", 0.35) or 0.35)

    s = max(1e-9, (r_open + r_grid + r_safe))
    r_open, r_grid, r_safe = (r_open / s), (r_grid / s), (r_safe / s)

    cap_open = max(0.0, total_u * r_open)
    cap_grid = max(0.0, total_u * r_grid)
    cap_safe = max(0.0, total_u * r_safe)

    used_open = min(exposure_u, cap_open)
    rem = max(0.0, exposure_u - used_open)
    used_grid = min(rem, cap_grid)

    return {
        "open": {"cap": cap_open, "used": used_open, "remain": max(0.0, cap_open - used_open)},
        "grid": {"cap": cap_grid, "used": used_grid, "remain": max(0.0, cap_grid - used_grid)},
        "safe_legacy_fix": {"cap": cap_safe, "used": 0.0, "remain": max(0.0, cap_safe)},
    }

def _fmt_u_late(x: float) -> str:
    try:
        return f"{float(x):.2f}U"
    except Exception:
        return "0.00U"
_fmt_u = _fmt_u_late

def _print_budget_report(snapshot: dict, total_u: float, coins: list[str]) -> None:
    """打印预算播报（Budget Report）。
    关键修复（北境指令）：
    - used（已用）必须来自 BudgetUsageTracker（真实执行结果 ledger），不能用 exposure（暴露）冒充。
    - exposure 仅作为观察字段单独展示。
    - cap（上限）按全局比例桶分配后“均摊到每个币”展示，避免每币重复打印全局 cap 的误导。
    """
    ts = now_ts()
    total_u = float(total_u or 0.0)

    tracker = globals().get("_BUDGET_TRACKER")
    if isinstance(tracker, BudgetUsageTracker):
        try:
            tracker.poll()
        except Exception as _e:
            _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

        used_map = tracker.used if isinstance(tracker.used, dict) else {}
        used_src = "tracker"
    else:
        used_map = {}
        used_src = "none"

    buckets_total = _alloc_budget_buckets(0.0, total_u)
    cap_open_total = float((buckets_total.get("open") or {}).get("cap") or 0.0)
    cap_grid_total = float((buckets_total.get("grid") or {}).get("cap") or 0.0)
    cap_safe_total = float((buckets_total.get("safe_legacy_fix") or {}).get("cap") or 0.0)

    n = max(1, len(coins or []))
    cap_open = cap_open_total / n
    cap_grid = cap_grid_total / n
    cap_safe = cap_safe_total / n

    safe_log(lambda: f"[{ts}] [BUDGET（预算）] 每5分钟播报 | total_equity（总资金）={_fmt_u(total_u)} | "
        f"cap(均摊/币)：open={_fmt_u(cap_open)} grid={_fmt_u(cap_grid)} safe={_fmt_u(cap_safe)} | "
        f"used来源={used_src}"
    )

    for coin in (coins or []):
        c = str(coin or "").upper()
        exp_u = _coin_exposure_u(snapshot, c)

        u0 = used_map.get(c, {}) if isinstance(used_map.get(c, {}), dict) else {}
        used_grid = float(u0.get("grid") or 0.0)
        used_open = float(u0.get("open") or 0.0)
        rem_grid = max(0.0, cap_grid - used_grid)
        rem_open = max(0.0, cap_open - used_open)
        rem_safe = max(0.0, cap_safe)

        line = (
            f"  {c}: "
            f"GRID（网格）总{_fmt_u(cap_grid)} 已用{_fmt_u(used_grid)} 剩{_fmt_u(rem_grid)} | "
            f"OPEN（首次/补腿）总{_fmt_u(cap_open)} 已用{_fmt_u(used_open)} 剩{_fmt_u(rem_open)} | "
            f"SAFE（修复展示）总{_fmt_u(cap_safe)} 剩{_fmt_u(rem_safe)} | "
            f"暴露（双腿名义）={_fmt_u(exp_u)}"
        )
        cprint(line)

_GRID_LAST_PRINT_TS: float = 0.0
_GRID_REPORT_INTERVAL_SEC: float = 600.0
_GRID_LAST_SNAPSHOT: dict | None = None

_EXECQ_LAST_PRINT_TS: float = 0.0
_EXECQ_REPORT_INTERVAL_SEC: float = 600.0

def _maybe_execq_report(q: "RequestQueue", pending: list, force: bool = False) -> None:
    """每10分钟输出一次执行器队列摘要（q.items / pending），用于判案：
    - 入队但不执行：看 q_len/p_len 是否堆积
    - 出队后卡住：看 pending 明细是否持续存在
    - 哪些模块/币种最拥堵：TopN 统计
    """
    global _EXECQ_LAST_PRINT_TS
    try:
        now = float(time.time())
    except Exception:
        now = 0.0

    try:
        if (not force) and _EXECQ_LAST_PRINT_TS and (now - float(_EXECQ_LAST_PRINT_TS) < float(_EXECQ_REPORT_INTERVAL_SEC)):
            return
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    try:
        q_items = list(getattr(q, "items", None) or [])
    except Exception:
        q_items = []
    try:
        pend_items = list(pending or [])
    except Exception:
        pend_items = []

    q_len = len(q_items)
    p_len = len(pend_items)

    def _k(req, name: str) -> str:
        try:
            if hasattr(req, "to_dict"):
                d = req.to_dict()
                if isinstance(d, dict) and name in d:
                    return str(d.get(name) or "")
            return str(getattr(req, name, "") or "")
        except Exception:
            return ""

    def _stat(items, field):
        c = {}
        for r in items:
            k = _k(r, field).upper().strip() or "-"
            c[k] = c.get(k, 0) + 1
        return sorted(c.items(), key=lambda x: (-x[1], x[0]))

    top_mod_q = _stat(q_items, "module")[:5]
    top_coin_q = _stat(q_items, "coin")[:5]
    top_act_q = _stat(q_items, "action_type")[:5]

    top_mod_p = _stat(pend_items, "module")[:5]
    top_coin_p = _stat(pend_items, "coin")[:5]
    top_act_p = _stat(pend_items, "action_type")[:5]

    try:
        safe_log(lambda: f"[{now_ts()}] [EXECQ_HEARTBEAT] q_len={q_len} pending_len={p_len} (interval={int(_EXECQ_REPORT_INTERVAL_SEC)}s)")
        safe_log(lambda: f"[{now_ts()}] [EXECQ_Q_TOP] mod={top_mod_q} coin={top_coin_q} act={top_act_q}")
        safe_log(lambda: f"[{now_ts()}] [EXECQ_P_TOP] mod={top_mod_p} coin={top_coin_p} act={top_act_p}")
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    try:
        _pin("EXEC_QUEUE_SNAPSHOT",
             ok=1, reason="execq_heartbeat",
             q_len=q_len, pending_len=p_len,
             top_mod_q=str(top_mod_q[:3]), top_coin_q=str(top_coin_q[:3]), top_act_q=str(top_act_q[:3]),
             top_mod_p=str(top_mod_p[:3]), top_coin_p=str(top_coin_p[:3]), top_act_p=str(top_act_p[:3]))
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    _EXECQ_LAST_PRINT_TS = now

