def _tp_emit_event(event_type: str, *, coin: str = "", platform: str = "", trace_id: str = "", detail: dict | None = None) -> None:
    """把 TP 相关事件写入 bot_run.jsonl，便于回放/统计/面板读取。绝不抛异常。"""
    try:
        fp = (_rizhi_path("bot_run.jsonl") if "_rizhi_path" in globals() else "bot_run.jsonl")
        obj = {
            "ts": now_ts(),
            "mod": "GRID_TP",
            "type": str(event_type or "TP_EVT"),
            "coin": str(coin or "").upper(),
            "platform": str(platform or "").upper(),
            "trace_id": str(trace_id or ""),
            "detail": detail or {},
        }
        write_jsonl(fp, obj)
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

def _tp_reject_record(coin: str, reason: str, *, stage: str = "", trace_id: str = "", extra=None) -> None:
    """记录“本地网格止盈（LOCAL_GRID_TP）命中但被拒绝/拦截”的原因。只做计数+轻量字段，便于每10分钟 Top3 判案。"""
    try:
        c = str(coin or "").upper() or "-"
        r = (str(reason or "").strip() or "UNKNOWN").replace("\n", " ")[:120]
        k = f"{r}" if not stage else f"{stage}:{r}"
        d = _TP_REJECT_STATS.get(c)
        if d is None:
            d = {}
            _TP_REJECT_STATS[c] = d
        d[k] = int(d.get(k, 0)) + 1
        if d[k] == 1:
            try:
                safe_log(lambda: f"[{now_ts()}] [GRID_TP_REJECT_SEEN] coin={c} reason={k} trace={trace_id}")
            except Exception as _e:
                _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

