_EXEC_CONFIRM_LOCK = threading.RLock()
_EXEC_CONFIRM_STATE: dict[str, Any] = {
    "active": False,
    "platform": "",
    "coin": "",
    "label": "",
    "started_ts": 0.0,
    "until": 0.0,
    "holder": "",
    "result": "",
}

def _exec_confirm_state_enter(*, platform: str = "", coin: str = "", label: str = "", ttl_s: float = 6.5) -> dict:
    try:
        now = float(time.time())
    except Exception:
        now = 0.0
    st = {
        "active": True,
        "platform": str(platform or "").upper(),
        "coin": str(coin or "").upper(),
        "label": str(label or "")[:80],
        "started_ts": now,
        "until": now + max(1.0, float(ttl_s or 0.0)),
        "holder": f"{str(platform or '').upper()}:{str(coin or '').upper()}:{str(label or '')[:40]}",
        "result": "",
    }
    try:
        with _EXEC_CONFIRM_LOCK:
            _EXEC_CONFIRM_STATE.clear()
            _EXEC_CONFIRM_STATE.update(st)
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_1342', _e)
        pass
    return dict(st)

def _exec_confirm_state_snapshot() -> dict:
    try:
        with _EXEC_CONFIRM_LOCK:
            st = dict(_EXEC_CONFIRM_STATE or {})
    except Exception:
        st = dict(_EXEC_CONFIRM_STATE or {})
    try:
        if bool(st.get("active")) and float(st.get("until") or 0.0) > 0 and float(time.time()) > float(st.get("until") or 0.0):
            _exec_confirm_state_exit(st, result="expired")
            st["active"] = False
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_1343', _e)
        pass
    return st

def _exec_confirm_state_busy(*, platform: str = "", coin: str = "") -> dict | None:
    st = _exec_confirm_state_snapshot()
    if not bool((st or {}).get("active")):
        return None
    plat0 = str(platform or "").upper().strip()
    coin0 = str(coin or "").upper().strip()
    if plat0 and str(st.get("platform") or "").upper().strip() not in ("", plat0):
        return None
    if coin0 and str(st.get("coin") or "").upper().strip() not in ("", coin0):
        return None
    return st

def _exec_confirm_state_exit(state: dict | None = None, *, result: str = "") -> None:
    try:
        holder = str((state or {}).get("holder") or "")
    except Exception:
        holder = ""
    try:
        with _EXEC_CONFIRM_LOCK:
            cur = dict(_EXEC_CONFIRM_STATE or {})
            cur_holder = str(cur.get("holder") or "")
            if holder and cur_holder and holder != cur_holder:
                return
            _EXEC_CONFIRM_STATE.clear()
            _EXEC_CONFIRM_STATE.update({
                "active": False,
                "platform": str(cur.get("platform") or ""),
                "coin": str(cur.get("coin") or ""),
                "label": str(cur.get("label") or ""),
                "started_ts": float(cur.get("started_ts") or 0.0),
                "until": 0.0,
                "holder": "",
                "result": str(result or ""),
                "ended_ts": float(time.time()),
            })
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_1344', _e)
        pass
