def _grid_tp_mark_diag_update(coin: str, platform: str, side: str = '', *, ok: bool, mark: Any = None, source: str = '', reason: str = '', layer_id: str = '') -> dict:
    try:
        k = _grid_tp_diag_key(coin, platform, side)
        cur = dict(_GRID_TP_MARK_DIAG.get(k) or {})
        prev_status = str(cur.get('status') or '')
        miss_count = int(cur.get('miss_count') or 0)
        recover_count = int(cur.get('recover_count') or 0)
        if ok:
            recover_count += 1
            if miss_count >= 2:
                try:
                    safe_log(lambda: f"[{now_ts()}] [GRID_TP][MARK_RECOVERED] coin={str(coin).upper()} plat={str(platform).upper()} side={str(side).upper()} prev_miss={miss_count} mark={_fmt_float(mark)} src={str(source or '')}")
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_1346', _e)
                    pass
            status = 'ok'
            cur.update({
                'ts': float(time.time()),
                'coin': str(coin or '').upper(),
                'platform': str(platform or '').upper(),
                'side': str(side or '').upper(),
                'status': status,
                'mark_source': str(source or ''),
                'reason': str(reason or ''),
                'last_ok_ts': float(time.time()),
                'last_mark': (float(mark) if mark is not None else None),
                'miss_count': 0,
                'recover_count': int(recover_count),
                'layer_id': str(layer_id or cur.get('layer_id') or ''),
            })
        else:
            miss_count += 1
            status = 'error' if miss_count >= 3 else ('degraded' if miss_count >= 2 else 'warn')
            cur.update({
                'ts': float(time.time()),
                'coin': str(coin or '').upper(),
                'platform': str(platform or '').upper(),
                'side': str(side or '').upper(),
                'status': status,
                'mark_source': str(source or ''),
                'reason': str(reason or ''),
                'last_bad_ts': float(time.time()),
                'miss_count': int(miss_count),
                'recover_count': int(recover_count),
                'layer_id': str(layer_id or cur.get('layer_id') or ''),
            })
            if status in ('degraded', 'error') and prev_status != status:
                try:
                    safe_log(lambda: f"[{now_ts()}] [GRID_TP][MARK_SOURCE_BROKEN] coin={str(coin).upper()} plat={str(platform).upper()} side={str(side).upper()} miss_count={miss_count} status={status} reason={str(reason or '')} src={str(source or '')} layer_id={str(layer_id or '')}")
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_1347', _e)
                    pass
        _GRID_TP_MARK_DIAG[k] = cur
        return dict(cur)
    except Exception:
        return {}

def _cache_last_snapshot_metric(snap: dict, coin: str, platform: str) -> None:
    """缓存最近快照的关键证据：mark 与 notional_u。兼容 positions=list/dict。"""
    try:
        c = str(coin or "").upper()
        p = str(platform or "").upper()
        if not c or not p:
            return
        k = _snap_key(c, p)
        mark = 0.0
        notional = 0.0
        try:
            mark = float(_GRID_LEDGER._get_mark_price_from_snapshot(snap, c, p))  # type: ignore
        except Exception:
            mark = 0.0
        try:
            notional = float(_GRID_LEDGER._get_notional_u_from_snapshot(snap, c, p))  # type: ignore
        except Exception:
            notional = 0.0
        _LAST_SNAP_METRICS[k] = {
            "ts": float(time.time()),
            "coin": c,
            "plat": p,
            "mark": float(mark),
            "notional_u": float(notional),
        }
        if len(_LAST_SNAP_METRICS) > int(_LAST_SNAP_METRICS_MAX):
            try:
                n_drop = max(1, int(len(_LAST_SNAP_METRICS) * 0.1))
                olds = sorted(_LAST_SNAP_METRICS.items(), key=lambda kv: float(kv[1].get("ts") or 0.0))[:n_drop]
                for kk, _vv in olds:
                    _LAST_SNAP_METRICS.pop(kk, None)
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_1348', _e)
                pass
    except Exception:
        return

def _get_last_snapshot_metric(coin: str, platform: str) -> dict:
    try:
        cached = dict(_LAST_SNAP_METRICS.get(_snap_key(coin, platform)) or {})
        if float(cached.get('notional_u') or 0.0) > 0.0:
            return cached
    except Exception:
        cached = {}
    try:
        snap = globals().get('_BUDGET_LAST_SNAPSHOT') or globals().get('_GRID_LAST_SNAPSHOT') or globals().get('LAST_GOOD_SNAPSHOT') or {}
        c = str(coin or '').upper().strip()
        p = str(platform or '').upper().strip()
        row = _normalize_snapshot_position_row(_snap_get_pos_any(snap if isinstance(snap, dict) else {}, p, c), coin=c, platform=p)
        if isinstance(row, dict) and row:
            def _num(v):
                try:
                    if v is None:
                        return 0.0
                    return float(v)
                except Exception:
                    return 0.0
            out = {
                'ts': float(time.time()),
                'coin': c,
                'plat': p,
                'mark': float(_num(row.get('mark') or row.get('mark_px') or row.get('markPrice') or row.get('px') or row.get('last') or row.get('last_px') or row.get('price'))),
                'notional_u': float(abs(_num(row.get('notional_u') or row.get('notional') or row.get('notionalUsd') or row.get('value_u') or row.get('value') or row.get('notional_usd') or row.get('value_usd') or row.get('amount') or row.get('size') or row.get('positionAmt')))),
            }
            if out['notional_u'] > 0.0:
                return out
        return dict(cached or {})
    except Exception:
        return dict(cached or {})

