def _trace_pending_tick(*, snapshot: dict | None = None) -> None:
    try:
        now = time.time()
    except Exception:
        now = 0.0

    try:
        for tid, info in list(_TRACE_PENDING.items()):
            if not isinstance(info, dict):
                continue
            coin = str(info.get("coin") or "-").upper() or "-"
            submit_ts = float(info.get("submit_ts") or 0.0)
            age = float(now - submit_ts)
            st = None
            try:
                st = _TRACE_STATS.get(str(tid))  # type: ignore
            except Exception:
                st = None

            try:
                if isinstance(st, dict) and float(st.get("end_ts") or 0.0) > 0:
                    _trace_pending_done(tid, status="END", reason=str(st.get("end_reason") or ""))
                    continue
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_1352', _e)
                pass
            begin_ts = 0.0
            try:
                if isinstance(st, dict):
                    begin_ts = float(st.get("begin_ts") or 0.0)
            except Exception:
                begin_ts = 0.0

            if age >= float(_TRACE_BEGIN_STUCK_SEC) and begin_ts <= 0.0:
                _trace_pending_inc(coin, "NO_EXEC_BEGIN", stage="TRACE")
                continue

            if age >= float(_TRACE_STUCK_SEC) and begin_ts > 0.0:
                try:
                    if isinstance(st, dict) and st.get("fail_step"):
                        _trace_pending_inc(coin, f"EXEC_FAIL:{str(st.get('fail_step'))[:24]}", stage="TRACE")
                    else:
                        _trace_pending_inc(coin, "NO_EXEC_END", stage="TRACE")
                except Exception:
                    _trace_pending_inc(coin, "NO_EXEC_END", stage="TRACE")
                continue
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_1353', _e)
        pass
    try:
        items = list(_grid_book_layers_flat(include_closed=False) or [])
    except Exception:
        items = []

    try:
        for it in items:
            if not isinstance(it, dict):
                continue
            if str(it.get("state") or "") != "CLOSE_PENDING":
                continue
            coin = str(it.get("coin") or "-").upper() or "-"
            enq_ts = float(it.get("close_enq_ts") or it.get("last_try_ts") or 0.0)
            if enq_ts <= 0:
                continue
            age = float(now - enq_ts)
            if age < float(_CLOSE_PENDING_STUCK_SEC):
                continue

            tid = str(it.get("close_trace_id") or "")
            st = None
            try:
                st = _TRACE_STATS.get(tid) if tid else None  # type: ignore
            except Exception:
                st = None

            try:
                if tid and isinstance(st, dict) and float(st.get("end_ts") or 0.0) > 0 and int(st.get("end_ok") or 0) == 1:
                    plat = str(it.get("platform") or "-").upper() or "-"
                    m = {}
                    try:
                        m = _get_last_snapshot_metric(coin, plat)
                    except Exception:
                        m = {}
                    try:
                        _tp_emit_event(
                            "LEDGER_CLOSE_PENDING_AFTER_EXEC_OK",
                            coin=coin,
                            platform=plat,
                            trace_id=tid,
                            detail={
                                "gid": str(it.get("id") or ""),
                                "side": str(it.get("side") or ""),
                                "amount_u": float(it.get("amount_u") or 0.0),
                                "entry_price": float(it.get("entry_price") or 0.0),
                                "tp_price": float(it.get("tp_price") or 0.0),
                                "close_try": int(it.get("close_try") or 0),
                                "age_sec": float(age),
                                "close_trigger_mark": float(it.get("close_trigger_mark") or 0.0),
                                "snap_ts": float(m.get("ts") or 0.0),
                                "snap_mark": float(m.get("mark") or 0.0),
                                "snap_notional_u": float(m.get("notional_u") or 0.0),
                                "exec_begin_ts": float(st.get("begin_ts") or 0.0),
                                "exec_end_ts": float(st.get("end_ts") or 0.0),
                                "exec_dur_sec": float(max(0.0, float(st.get("end_ts") or 0.0) - float(st.get("begin_ts") or 0.0))),
                            },
                        )
                    except Exception as _e:
                        _record_swallowed_exception('except_pass_line_1354', _e)
                        pass
                    try:
                        if _has_leg_u(float(m.get("notional_u") or 0.0)):
                            _trace_pending_inc(coin, "CLOSE_PENDING_AFTER_EXEC_OK_POS_STILL_OPEN", stage="LEDGER")
                        else:
                            _trace_pending_inc(coin, "CLOSE_PENDING_AFTER_EXEC_OK_POS_FLAT", stage="LEDGER")
                    except Exception:
                        _trace_pending_inc(coin, "CLOSE_PENDING_AFTER_EXEC_OK", stage="LEDGER")
                    continue
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_1355', _e)
                pass
            try:
                if tid and isinstance(st, dict) and float(st.get("end_ts") or 0.0) > 0 and int(st.get("end_ok") or 0) == 0:
                    _trace_pending_inc(coin, "CLOSE_PENDING_EXEC_FAIL", stage="LEDGER")
                    continue
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_1356', _e)
                pass
            _trace_pending_inc(coin, "CLOSE_PENDING_STUCK", stage="LEDGER")
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_1357', _e)
        pass

HEALTH_RESTART_NEED_CONSEC = int(globals().get("HEALTH_RESTART_NEED_CONSEC", 2))          # 连续触发轮数
HEALTH_RESTART_COOLDOWN_SEC = float(globals().get("HEALTH_RESTART_COOLDOWN_SEC", 300.0)) # 重启冷却（秒）
HEALTH_MISSING_LEG_ABS_U = float(globals().get("HEALTH_MISSING_LEG_ABS_U", 80.0))         # 大腿名义>=80U
HEALTH_MISSING_LEG_EPS_U = float(globals().get("HEALTH_MISSING_LEG_EPS_U", 5.0))          # 小腿名义<=5U
HEALTH_UI_LINK_NEED_CONSEC = int(globals().get("HEALTH_UI_LINK_NEED_CONSEC", 3))          # 连续 UI_LINK 轮数阈值

_HEALTH_LAST_RESTART_TS: float = 0.0
_HEALTH_CONSEC_MISSING: dict[str, int] = {}
_HEALTH_CONSEC_TPSTUCK: dict[str, int] = {}
_HEALTH_CONSEC_UILINK: int = 0
_HEALTH_LAST_TPSTUCK_TOTAL: dict[str, int] = {}
_HEALTH_LAST_UILINK_HITS: int = 0

_SOFT_RESTART_REQ: dict[str, Any] = {}

def _request_soft_restart(reason: str, detail: dict | None = None, *, source: str = '', min_interval_sec: float = 20.0) -> bool:
    """统一软重启请求入口：只发请求，不在局部直接退出整个程序。"""
    global _SOFT_RESTART_REQ
    try:
        nowv = float(time.time())
    except Exception:
        nowv = 0.0
    try:
        prev = dict(globals().get('_SOFT_RESTART_REQ') or {})
    except Exception:
        prev = {}
    try:
        if prev and (not bool(prev.get('consumed'))) and (nowv - float(prev.get('ts') or 0.0) < float(min_interval_sec or 0.0)):
            return False
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_1358', _e)
        pass
    _SOFT_RESTART_REQ = {
        'ts': nowv,
        'reason': str(reason or 'soft_restart'),
        'source': str(source or ''),
        'detail': dict(detail or {}),
        'consumed': False,
    }
    try:
        safe_log(lambda: f"[{now_ts()}] SOFT_RESTART_REQUEST reason={str(reason or '')} source={str(source or '')} detail={_json_dumps_bot(detail or {}, ensure_ascii=False)[:400]}")
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_1359', _e)
        pass
    try:
        _pin('SOFT_RESTART_REQUEST', mod='SYS', coin=str((detail or {}).get('coin') or ''), ok=0, reason=str(reason or ''), plat=str((detail or {}).get('platform') or ''), act=str((detail or {}).get('action') or ''), stage=str(source or 'SOFT_RESTART'))
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_1360', _e)
        pass
    return True

def _consume_soft_restart_request() -> dict:
    global _SOFT_RESTART_REQ
    try:
        req = dict(globals().get('_SOFT_RESTART_REQ') or {})
    except Exception:
        req = {}
    if not req or bool(req.get('consumed')):
        return {}
    req['consumed'] = True
    _SOFT_RESTART_REQ = req
    return req

def _snap_get_notional_u(snap: dict, coin: str, platform: str) -> float:
    """从 snapshot 中提取某 coin + platform 的名义价值 U（兼容多种结构）。"""
    try:
        c = str(coin or "").upper()
        p = str(platform or "").upper()
    except Exception:
        c, p = "", ""
    if not c or not p:
        return 0.0

    try:
        poss = snap.get("positions") if isinstance(snap, dict) else None
    except Exception:
        poss = None
    if isinstance(poss, list):
        for it in poss:
            if not isinstance(it, dict):
                continue
            try:
                if str(it.get("coin") or "").upper() != c:
                    continue
                if str(it.get("platform") or it.get("plat") or "").upper() != p:
                    continue
                nu = it.get("notional_u") or it.get("notional_usd") or it.get("notional") or it.get("value_u") or it.get("value_usd") or 0.0
                return float(abs(float(nu or 0.0)))
            except Exception:
                continue

    if isinstance(poss, dict):
        try:
            a = poss.get(c)
            if isinstance(a, dict):
                b = a.get(p)
                if isinstance(b, dict):
                    nu = b.get("notional_u") or b.get("notional_usd") or b.get("notional") or b.get("value_u") or b.get("value_usd") or 0.0
                    return float(abs(float(nu or 0.0)))
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_1361', _e)
            pass
        try:
            a = poss.get(p)
            if isinstance(a, dict):
                b = a.get(c)
                if isinstance(b, dict):
                    nu = b.get("notional_u") or b.get("notional_usd") or b.get("notional") or b.get("value_u") or b.get("value_usd") or 0.0
                    return float(abs(float(nu or 0.0)))
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_1362', _e)
            pass
    try:
        k1 = f"{c}_{p}_notional_u"
        if k1 in snap:
            return float(abs(float(snap.get(k1) or 0.0)))
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_1363', _e)
        pass
    return 0.0

def _health_has_pending_for_coin(coin: str) -> bool:
    """若该 coin 仍存在 pending trace（入队未完成），优先等待，不立即重启，避免重复下单。"""
    try:
        c = str(coin or "").upper() or "-"
    except Exception:
        c = "-"
    if not c or c == "-":
        return False
    try:
        for _tid, info in list(_TRACE_PENDING.items()):
            if not isinstance(info, dict):
                continue
            if str(info.get("coin") or "").upper() == c:
                return True
    except Exception:
        return False
    return False

def _health_eval(snapshot: dict | None) -> tuple[bool, str, dict]:
    """返回 (need_restart, reason, detail)。reason 用于面板与日志。"""
    global _HEALTH_LAST_RESTART_TS, _HEALTH_CONSEC_UILINK, _HEALTH_LAST_UILINK_HITS

    now = 0.0
    try:
        now = float(time.time())
    except Exception:
        now = 0.0

    try:
        if _HEALTH_LAST_RESTART_TS > 0 and (now - float(_HEALTH_LAST_RESTART_TS)) < float(HEALTH_RESTART_COOLDOWN_SEC):
            cooldown_left = float(HEALTH_RESTART_COOLDOWN_SEC) - (now - float(_HEALTH_LAST_RESTART_TS))
        else:
            cooldown_left = 0.0
    except Exception:
        cooldown_left = 0.0

    try:
        _sr = _consume_soft_restart_request()
    except Exception:
        _sr = {}
    if isinstance(_sr, dict) and _sr:
        det = dict(_sr.get('detail') or {})
        det.update({'source': str(_sr.get('source') or ''), 'request_ts': float(_sr.get('ts') or 0.0)})
        return True, str(_sr.get('reason') or 'SOFT_RESTART_REQUEST'), det

    try:
        hits = int(globals().get("_UI_LINK_ERR_HITS", 0))
    except Exception:
        hits = 0
    delta = 0
    try:
        delta = int(hits - int(_HEALTH_LAST_UILINK_HITS))
    except Exception:
        delta = 0
    _HEALTH_LAST_UILINK_HITS = hits
    if delta > 0:
        _HEALTH_CONSEC_UILINK = int(_HEALTH_CONSEC_UILINK) + 1
    else:
        _HEALTH_CONSEC_UILINK = 0

    if _HEALTH_CONSEC_UILINK >= int(HEALTH_UI_LINK_NEED_CONSEC):
        if cooldown_left <= 0:
            _HEALTH_LAST_RESTART_TS = now
            det = {
                "ui_link_consec": int(_HEALTH_CONSEC_UILINK),
                "ui_link_hits": int(hits),
                "ui_link_last": str(globals().get("_UI_LINK_ERR_LAST", ""))[:300],
            }
            return True, "UI_LINK_ERR_CONSEC", det

    if isinstance(snapshot, dict):
        coins_set = set()
        try:
            poss = snapshot.get("positions")
        except Exception:
            poss = None
        if isinstance(poss, list):
            for it in poss:
                if isinstance(it, dict):
                    try:
                        coins_set.add(str(it.get("coin") or "").upper())
                    except Exception as _e:
                        _record_swallowed_exception('except_pass_line_1364', _e)
                        pass
        elif isinstance(poss, dict):
            try:
                for k in list(poss.keys()):
                    kk = str(k or "").upper()
                    if kk and kk not in ("EXT","VAR"):
                        coins_set.add(kk)
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_1365', _e)
                pass
        if not coins_set:
            try:
                coins_set = set([str(k or "").upper() for k in list(_TRACE_PENDING_STATS.keys())])
            except Exception:
                coins_set = set()

        for c in list(coins_set):
            if not c or c == "-":
                continue
            try:
                ext_n = _snap_get_notional_u(snapshot, c, "EXT")
                var_n = _snap_get_notional_u(snapshot, c, "VAR")
            except Exception:
                ext_n, var_n = 0.0, 0.0
            major = max(float(ext_n), float(var_n))
            minor = min(float(ext_n), float(var_n))
            missing = (major >= float(HEALTH_MISSING_LEG_ABS_U) and minor <= float(HEALTH_MISSING_LEG_EPS_U))

            if missing:
                if _health_has_pending_for_coin(c):
                    _HEALTH_CONSEC_MISSING[c] = 0
                    continue
                _HEALTH_CONSEC_MISSING[c] = int(_HEALTH_CONSEC_MISSING.get(c, 0)) + 1
            else:
                _HEALTH_CONSEC_MISSING[c] = 0

            if int(_HEALTH_CONSEC_MISSING.get(c, 0)) >= int(HEALTH_RESTART_NEED_CONSEC):
                if cooldown_left <= 0:
                    _HEALTH_LAST_RESTART_TS = now
                    det = {
                        "coin": c,
                        "ext_notional_u": float(ext_n),
                        "var_notional_u": float(var_n),
                        "major_u": float(major),
                        "minor_u": float(minor),
                        "consec": int(_HEALTH_CONSEC_MISSING.get(c, 0)),
                        "abs_u": float(HEALTH_MISSING_LEG_ABS_U),
                        "eps_u": float(HEALTH_MISSING_LEG_EPS_U),
                    }
                    return True, "MISSING_LEG_CONFIRMED", det

    try:
        for c, d in list(_TRACE_PENDING_STATS.items()):
            if not isinstance(d, dict):
                continue
            key1 = "LEDGER:CLOSE_PENDING_STUCK"
            key2 = "LEDGER:CLOSE_PENDING_AFTER_EXEC_OK_POS_STILL_OPEN"
            tot = int(d.get(key1, 0)) + int(d.get(key2, 0))
            last_tot = int(_HEALTH_LAST_TPSTUCK_TOTAL.get(c, 0))
            _HEALTH_LAST_TPSTUCK_TOTAL[c] = tot
            if tot > last_tot:
                _HEALTH_CONSEC_TPSTUCK[c] = int(_HEALTH_CONSEC_TPSTUCK.get(c, 0)) + 1
            else:
                _HEALTH_CONSEC_TPSTUCK[c] = 0

            if int(_HEALTH_CONSEC_TPSTUCK.get(c, 0)) >= int(HEALTH_RESTART_NEED_CONSEC):
                if _health_has_pending_for_coin(c):
                    _HEALTH_CONSEC_TPSTUCK[c] = 0
                    continue
                if cooldown_left <= 0:
                    _HEALTH_LAST_RESTART_TS = now
                    det = {
                        "coin": str(c),
                        "tp_stuck_tot": int(tot),
                        "tp_stuck_delta": int(tot - last_tot),
                        "consec": int(_HEALTH_CONSEC_TPSTUCK.get(c, 0)),
                        "last_ui_link": str(globals().get("_UI_LINK_ERR_LAST", ""))[:200],
                    }
                    return True, "TP_CLOSE_PENDING_STUCK", det
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_1366', _e)
        pass
    return False, "", {"cooldown_left_sec": float(cooldown_left)}

def _tp_reject_top3_lines() -> list[str]:
    """生成 Top3 原因的文本行（按币种）。"""
    out: list[str] = []
    try:
        for c, mp in list(_TP_REJECT_STATS.items()):
            if not isinstance(mp, dict) or not mp:
                continue
            items = sorted(mp.items(), key=lambda kv: (-int(kv[1] or 0), str(kv[0])))[:3]
            parts = [f"{k}={v}" for k, v in items]
            out.append(f"[{now_ts()}] [GRID_TP_REJECT_TOP3] coin={c} " + " | ".join(parts))
    except Exception:
        return out
    return out

def _tp_reject_reset() -> None:
    global _TP_REJECT_LAST_RESET_TS
    try:
        _TP_REJECT_STATS.clear()
    except Exception as _e:
        _log_exc(mod="SYS", stage="EXC_PASS", e=_e)

    try:
        _TP_REJECT_LAST_RESET_TS = time.time()
    except Exception:
        _TP_REJECT_LAST_RESET_TS = 0.0

