def _breaker_state_get(dim: str) -> dict:
    d = str(dim or "NA")
    st = _SYS_BREAKER_STATE.get(d)
    if not isinstance(st, dict):
        st = {"open_until": 0.0, "last_reason": "", "trip_cnt": 0, "last_trip_ts": 0.0}
        _SYS_BREAKER_STATE[d] = st
    st.setdefault("probe_until", 0.0)
    st.setdefault("probe_tokens", 0)
    st.setdefault("probe_trace_id", "")
    st.setdefault("probe_inflight_until", 0.0)
    return st

def _breaker_status(dim: str) -> str:
    try:
        d = str(dim or "NA")
        st = _breaker_state_get(d)
        now = time.time()
        ou = float(st.get("open_until") or 0.0)
        pu = float(st.get("probe_until") or 0.0)
        if ou and now < ou:
            return "OPEN"
        if pu and now < pu:
            return "PROBING"
        return "CLOSED"
    except Exception:
        return "UNKNOWN"

def _breaker_close(dim: str, reason: str = "probe_ok") -> None:
    try:
        d = str(dim or "NA")
        st = _breaker_state_get(d)
        st["open_until"] = 0.0
        st["probe_until"] = 0.0
        st["probe_tokens"] = 0
        st["probe_trace_id"] = ""
        st["probe_inflight_until"] = 0.0
        st["last_reason"] = str(reason or "")[:200]
        try:
            _pin("SYS", stage="BREAKER_CLOSE", dim=d, reason=str(reason or "")[:120])
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_1367', _e)
            pass
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_1368', _e)
        pass
def _breaker_gate_allow(dim: str, trace_id: str) -> tuple[bool, str, float]:
    """返回 (allow, decision, until_ts)
    decision:
      - OK
      - BREAKER_OPEN
      - BREAKER_PROBING
      - BREAKER_PROBE_ALLOW
    """
    try:
        d = str(dim or "NA")
        tid = str(trace_id or "")
        st = _breaker_state_get(d)
        now = time.time()

        ou = float(st.get("open_until") or 0.0)
        if ou and now < ou:
            try:
                _trace_event('breaker_block', to_console=True, dim=str(d), until=float(ou), trace_id=str(tid))
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_1369', _e)
                pass
            return (False, "BREAKER_OPEN", ou)

        inflight = float(st.get("probe_inflight_until") or 0.0)
        if inflight and now > inflight and str(st.get("probe_trace_id") or ""):
            _breaker_trip(d, reason="probe_timeout", cooldown_sec=SYS_BREAKER_PROBE_FAIL_COOLDOWN_SEC, do_self_heal=True, heal_reload_times=2)
            st["probe_until"] = 0.0
            st["probe_tokens"] = 0
            st["probe_trace_id"] = ""
            st["probe_inflight_until"] = 0.0
            ou2 = float(st.get("open_until") or 0.0)
            return (False, "BREAKER_OPEN", ou2)

        pu = float(st.get("probe_until") or 0.0)
        if (ou and now >= ou) and (not pu or now >= pu):
            st["probe_until"] = now + float(SYS_BREAKER_PROBE_TTL_SEC)
            st["probe_tokens"] = int(SYS_BREAKER_PROBE_TOKENS or 1)
            st["probe_trace_id"] = ""
            st["probe_inflight_until"] = 0.0
            pu = float(st.get("probe_until") or 0.0)

        if pu and now < pu:
            toks = int(st.get("probe_tokens") or 0)
            if toks > 0:
                st["probe_tokens"] = toks - 1
                st["probe_trace_id"] = tid
                st["probe_inflight_until"] = now + float(SYS_BREAKER_PROBE_INFLIGHT_TTL_SEC)
                try:
                    _pin("SYS", stage="BREAKER_PROBE_ALLOW", dim=d, trace_id=tid, probe_until=pu)
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_1370', _e)
                    pass
                try:
                    _trace_event('breaker_probe_allow', to_console=True, dim=str(d), until=float(pu), trace_id=str(tid))
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_1371', _e)
                    pass
                return (True, "BREAKER_PROBE_ALLOW", pu)
            return (False, "BREAKER_PROBING", pu)

        return (True, "OK", 0.0)
    except Exception:
        return (True, "OK", 0.0)

def _breaker_on_exec_result(dim: str, ok: bool, err_key: str | None = None, trace_id: str | None = None, is_probe: bool = False) -> None:
    """执行回执触发：若是 probe 单，则成功关闭熔断；失败重新熔断。"""
    try:
        if is_probe:
            _trace_event('breaker_probe_result', to_console=True, dim=str(dim), ok=bool(ok), err_key=str(err_key or ''), trace_id=str(trace_id or ''))
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_1372', _e)
        pass
    try:
        if not dim:
            return
        d = str(dim or "NA")
        st = _breaker_state_get(d)
        if not bool(is_probe):
            return
        tid = str(trace_id or "")
        if st.get("probe_trace_id") and tid and str(st.get("probe_trace_id")) != tid:
            return
        if ok:
            _breaker_close(d, reason="probe_ok")
            return
        ek = str(err_key or "OTHER")
        _breaker_trip(d, reason=f"probe_fail:{ek}", cooldown_sec=SYS_BREAKER_PROBE_FAIL_COOLDOWN_SEC, do_self_heal=True, heal_reload_times=3)
        st["probe_until"] = 0.0
        st["probe_tokens"] = 0
        st["probe_trace_id"] = ""
        st["probe_inflight_until"] = 0.0
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_1373', _e)
        pass
_SYS_BREAKER_STATE: dict[str, dict[str, Any]] = {}

_SYS_SELF_HEAL_DIM: dict[str, dict[str, Any]] = {}

SYS_DIM_DYN_BASE_COOLDOWN_SEC: float = 0.0   # 基础降频（0=不主动降频；仅在异常后抬升）
SYS_DIM_DYN_MIN_SEC: float = 0.0
SYS_DIM_DYN_MAX_SEC: float = 180.0          # 最长降频（秒）
SYS_DIM_DYN_INC_STRONG: float = 1.60        # 强抬升倍数（cooldown/exec_fail）
SYS_DIM_DYN_INC_SOFT: float = 1.25          # 轻抬升倍数（mutex/data）
SYS_DIM_DYN_DEC: float = 0.85               # 逐步回落倍数（exec_ok）
SYS_DIM_DYN_OK_DEC_EVERY_N: int = 2         # 连续 OK N 次回落一次（更稳）

_SYS_DIM_DYN: dict[str, dict[str, Any]] = {}

def _dim_dyn_state_get(dim: str) -> dict[str, Any]:
    d = str(dim or "NA")
    st = _SYS_DIM_DYN.get(d)
    if not isinstance(st, dict):
        st = {"cd": float(SYS_DIM_DYN_BASE_COOLDOWN_SEC), "next": 0.0, "fail": 0, "ok": 0,
              "last_reason": "", "last_adj": 0.0}
        _SYS_DIM_DYN[d] = st
    st.setdefault("cd", float(SYS_DIM_DYN_BASE_COOLDOWN_SEC))
    st.setdefault("next", 0.0)
    st.setdefault("fail", 0)
    st.setdefault("ok", 0)
    st.setdefault("last_reason", "")
    st.setdefault("last_adj", 0.0)
    return st

def _dim_dyn_gate_allow(dim: str, now: float) -> tuple[bool, float]:
    """返回 (allow, until_ts)。若处于动态降频期则拒绝。"""
    try:
        st = _dim_dyn_state_get(dim)
        until = float(st.get("next") or 0.0)
        if until > now:
            return (False, until)
        return (True, 0.0)
    except Exception:
        return (True, 0.0)

def _m9_req_should_bypass_dim_dyn_cooldown(req: Any) -> tuple[bool, str]:
    """仅放行真正的 M9 首个冷启动，不放开普通 M9 加仓。"""
    try:
        if not isinstance(req, dict):
            return False, ''
        mod = str(req.get('module') or '').upper().strip()
        act = str(req.get('action_type') or req.get('action') or '').lower().strip()
        if mod != 'M9' or act not in ('increase', 'open', 'add'):
            return False, ''
        meta = req.get('meta') if isinstance(req.get('meta'), dict) else {}
        params = req.get('params') if isinstance(req.get('params'), dict) else {}
        cold = bool(
            meta.get('bypass_dim_dyn_cooldown')
            or meta.get('cold_start_bypass_dim_dyn_cooldown')
            or meta.get('cold_start')
            or meta.get('immediate_cold_start_open')
            or params.get('cold_start')
            or params.get('immediate_cold_start_open')
        )
        if not cold:
            return False, ''
        try:
            layer_no = int(meta.get('layer_no') or params.get('layer_no') or 0)
        except Exception:
            layer_no = 0
        if layer_no != 2:
            return False, 'layer_no_not_l2'
        return True, 'm9_coldstart_l2_bypass_dim_dyn_cooldown'
    except Exception:
        return False, ''

def _dim_dyn_bump(dim: str, *, mul: float, reason: str) -> None:
    try:
        d = str(dim or "NA")
        st = _dim_dyn_state_get(d)
        now = time.time()
        cd = float(st.get("cd") or 0.0)
        if cd <= 0.0:
            cd = float(SYS_DIM_DYN_BASE_COOLDOWN_SEC)
        if cd <= 0.0:
            cd = 3.0
        cd = max(float(SYS_DIM_DYN_MIN_SEC), min(float(SYS_DIM_DYN_MAX_SEC), cd * float(mul)))
        st["cd"] = cd
        st["next"] = float(now + cd)
        st["fail"] = int(st.get("fail", 0) or 0) + 1
        st["ok"] = 0
        st["last_reason"] = str(reason or "")
        st["last_adj"] = float(now)
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_1374', _e)
        pass
def _dim_dyn_relax(dim: str, *, reason: str = "exec_ok") -> None:
    try:
        d = str(dim or "NA")
        st = _dim_dyn_state_get(d)
        now = time.time()
        ok = int(st.get("ok", 0) or 0) + 1
        st["ok"] = ok
        if ok < int(SYS_DIM_DYN_OK_DEC_EVERY_N):
            return
        st["ok"] = 0
        cd = float(st.get("cd") or 0.0)
        if cd <= float(SYS_DIM_DYN_BASE_COOLDOWN_SEC):
            return
        cd2 = max(float(SYS_DIM_DYN_BASE_COOLDOWN_SEC), cd * float(SYS_DIM_DYN_DEC))
        st["cd"] = cd2
        st["last_reason"] = str(reason or "exec_ok")
        st["last_adj"] = float(now)
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_1375', _e)
        pass
def _dim_dyn_on_reject_stage(dim: str, stage: str) -> None:
    try:
        stg = str(stage or "")
        if not stg:
            return
        if stg == "STAGE_COOLDOWN":
            _dim_dyn_bump(dim, mul=float(SYS_DIM_DYN_INC_STRONG), reason=f"reject_stage:{stg}")
        elif stg in ("STAGE_MUTEX", "STAGE_DATA"):
            _dim_dyn_bump(dim, mul=float(SYS_DIM_DYN_INC_SOFT), reason=f"reject_stage:{stg}")
        elif stg == "STAGE_CONTRACT":
            _dim_dyn_bump(dim, mul=float(SYS_DIM_DYN_INC_STRONG), reason=f"reject_stage:{stg}")
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_1376', _e)
        pass
def _dim_dyn_on_exec_fail(dim: str, err_key: str) -> None:
    try:
        ek = str(err_key or "")
        if not ek:
            ek = "EXEC_FAIL"
        if ("TIMEOUT" in ek) or ("UI_" in ek) or ("NAV" in ek) or ("CDP" in ek):
            _dim_dyn_bump(dim, mul=float(SYS_DIM_DYN_INC_STRONG), reason=f"exec_fail:{ek}")
        else:
            _dim_dyn_bump(dim, mul=float(SYS_DIM_DYN_INC_SOFT), reason=f"exec_fail:{ek}")
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_1377', _e)
        pass
def _dim_dyn_on_exec_ok(dim: str) -> None:
    try:
        _dim_dyn_relax(dim, reason="exec_ok")
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_1378', _e)
        pass
def _sys_topn(mp: dict[str, int] | None, n: int = 3) -> list[str]:
    try:
        if not isinstance(mp, dict) or not mp:
            return []
        rows = sorted([(k, int(v or 0)) for k, v in mp.items()], key=lambda x: (-x[1], str(x[0])))
        out = []
        for k, v in rows[:max(1, int(n or 3))]:
            out.append(f"{k}:{v}")
        return out
    except Exception:
        return []

def _sys_reject_stage_guess(code: str | None, reason: str | None) -> str:
    try:
        c = str(code or "").lower()
    except Exception:
        c = ""
    try:
        r = str(reason or "").lower()
    except Exception:
        r = ""
    s = c + " " + r
    if ("breaker" in s) or ("circuit" in s) or ("熔断" in s):
        return "STAGE_BREAKER"
    if ("a1" in s) or ("hp_" in s) or ("highest" in s) or ("最高权限" in s):
        return "STAGE_A1"
    if ("yingding" in s) or ("hardcap" in s) or ("硬顶" in s) or ("cap" in s and "hard" in s):
        return "STAGE_YINGDING"
    if ("budget" in s) or ("余额" in s) or ("预算" in s):
        return "STAGE_BUDGET"
    if ("cooldown" in s) or ("freq" in s) or ("rate" in s) or ("频率" in s) or ("冷却" in s):
        return "STAGE_COOLDOWN"
    if ("mutex" in s) or ("lock" in s) or ("互斥" in s) or ("占用" in s):
        return "STAGE_MUTEX"
    if ("data" in s) or ("quality" in s) or ("nan" in s) or ("解析" in s) or ("扫描" in s):
        return "STAGE_DATA"
    if ("contract" in s) or ("schema" in s) or ("字段" in s) or ("missing" in s) or ("invalid" in s):
        return "STAGE_CONTRACT"
    return "STAGE_UNKNOWN"

def _sys_exec_err_key(err: str | None) -> str:
    try:
        e = str(err or "").lower()
    except Exception:
        e = ""
    if not e:
        return "UNKNOWN"
    if "cdp_empty" in e or "cdp" in e and "empty" in e:
        return "CDP_EMPTY"
    if "timeout" in e or "timed out" in e:
        return "TIMEOUT"
    if "not found" in e or "no node" in e or "selector" in e:
        return "UI_NOT_FOUND"
    if "navigation" in e or "net::" in e:
        return "NAV_ERROR"
    if "amount" in e and ("0" in e or "zero" in e):
        return "ZERO_AMOUNT"
    if "insufficient" in e or "margin" in e or "余额" in e:
        return "INSUFFICIENT"
    return "OTHER"

def _breaker_open_until(dim: str) -> float | None:
    st = _SYS_BREAKER_STATE.get(str(dim or ""))
    if isinstance(st, dict):
        try:
            return float(st.get("open_until") or 0.0) or None
        except Exception:
            return None
    return None

def _breaker_is_open(dim: str) -> bool:
    try:
        ou = _breaker_open_until(dim)
        return bool(ou and time.time() < float(ou))
    except Exception:
        return False

def _self_heal_mark(dim: str, reason: str, reload_times: int = 2, duration_sec: float = 240.0) -> None:
    try:
        now = time.time()
    except Exception:
        now = 0.0
    try:
        d = str(dim or "NA")
        until = now + float(duration_sec or 0.0)
        rt = int(reload_times or 0)
        prev = _SYS_SELF_HEAL_DIM.get(d)
        if isinstance(prev, dict):
            try:
                until = max(until, float(prev.get("until") or 0.0))
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_1379', _e)
                pass
            try:
                rt = max(rt, int(prev.get("reload_times") or 0))
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_1380', _e)
                pass
        _SYS_SELF_HEAL_DIM[d] = {"until": until, "reload_times": rt, "reason": str(reason or "")[:200]}
        try:
            _pin("SYS", stage="SELF_HEAL_SET", reason=str(reason or "")[:120], dim=d, reload_times=rt, until=until)
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_1381', _e)
            pass
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_1382', _e)
        pass
def _self_heal_reload_times(dim: str | None = None) -> int:
    """返回当前应该对执行器做的 pre_reload_times。

    新口径：默认只认“当前 dim 自己”的自愈窗口，不再把别的币/别的平台的自愈状态
    全局传染给当前下单请求。这样能显著减少“这单本身没问题，却在下单前被顺手 pre_reload”
    的情况。

    如确实想恢复旧的全局传染口径，可手动设置：EXEC_SELF_HEAL_GLOBAL_PRE_RELOAD=1
    """
    try:
        now = time.time()
    except Exception:
        now = 0.0
    best = 0
    try:
        if dim:
            st = _SYS_SELF_HEAL_DIM.get(str(dim))
            if isinstance(st, dict) and float(st.get("until") or 0.0) > now:
                best = max(best, int(st.get("reload_times") or 0))
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_1383', _e)
        pass
    try:
        _allow_global = bool(int(float(os.getenv("EXEC_SELF_HEAL_GLOBAL_PRE_RELOAD", "0") or 0)))
    except Exception:
        _allow_global = False
    if _allow_global:
        try:
            for _d, st in list(_SYS_SELF_HEAL_DIM.items()):
                if not isinstance(st, dict):
                    continue
                if float(st.get("until") or 0.0) > now:
                    best = max(best, int(st.get("reload_times") or 0))
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_1384', _e)
            pass
    try:
        if best < 0:
            best = 0
    except Exception:
        best = 0
    return int(best)

def _breaker_trip(dim: str, reason: str, cooldown_sec: float | None = None, *, do_self_heal: bool = False, heal_reload_times: int = 2) -> None:
    try:
        now = time.time()
    except Exception:
        now = 0.0
    d = str(dim or "NA")
    try:
        cd = float(cooldown_sec or SYS_BREAKER_DEFAULT_COOLDOWN_SEC)
    except Exception:
        cd = float(SYS_BREAKER_DEFAULT_COOLDOWN_SEC)
    try:
        st = _SYS_BREAKER_STATE.get(d)
        if not isinstance(st, dict):
            st = {"open_until": 0.0, "last_reason": "", "trip_cnt": 0, "last_trip_ts": 0.0}
            _SYS_BREAKER_STATE[d] = st
        ou = float(st.get("open_until") or 0.0)
        new_ou = max(ou, now + cd)
        st["open_until"] = new_ou
        st["last_reason"] = str(reason or "")[:200]
        st["trip_cnt"] = int(st.get("trip_cnt") or 0) + 1
        st["last_trip_ts"] = now
        try:
            _pin("SYS", stage="BREAKER_TRIP", reason=str(reason or "")[:120], dim=d, open_until=new_ou, cooldown_sec=cd, trip_cnt=st["trip_cnt"])
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_1385', _e)
            pass
        if do_self_heal:
            _self_heal_mark(d, reason=f"breaker:{reason}", reload_times=int(heal_reload_times or 2), duration_sec=min(300.0, max(120.0, cd)))
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_1386', _e)
        pass
def _breaker_on_reject(dim: str, stage: str) -> None:
    """在 submit_reject 发生时触发评估。"""
    try:
        if not dim:
            return
        if _breaker_is_open(dim):
            return
        stmap = _SYS_REJECT_STAGE_DIM.get(dim) or {}
        if not isinstance(stmap, dict):
            return
        thr = int(SYS_BREAKER_REJECT_STAGE_THRESH.get(str(stage or ""), 0) or 0)
        if thr <= 0:
            return
        cnt = int(stmap.get(str(stage or ""), 0) or 0)
        if cnt >= thr:
            _breaker_trip(dim, reason=f"reject_stage:{stage} cnt={cnt} thr={thr}", cooldown_sec=SYS_BREAKER_DEFAULT_COOLDOWN_SEC, do_self_heal=(stage in ("STAGE_DATA", "STAGE_MUTEX")))
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_1387', _e)
        pass
def _breaker_on_exec_fail(dim: str, err_key: str) -> None:
    """在 exec_fail 发生时触发评估（UI 类失败更容易触发自愈）。"""
    try:
        if not dim:
            return
        if _breaker_is_open(dim):
            return
        mp = _SYS_FUNNEL_DIM.get(dim) or {}
        if isinstance(mp, dict):
            ef = int(mp.get("exec_fail", 0) or 0)
        else:
            ef = 0
        if ef >= int(SYS_BREAKER_EXEC_FAIL_THRESH or 0):
            _breaker_trip(dim, reason=f"exec_fail cnt={ef} thr={SYS_BREAKER_EXEC_FAIL_THRESH}", cooldown_sec=SYS_BREAKER_DEFAULT_COOLDOWN_SEC, do_self_heal=True, heal_reload_times=2)
            return
        ek = str(err_key or "OTHER")
        if ek in ("UI_NOT_FOUND", "TIMEOUT", "NAV_ERROR", "CDP_EMPTY"):
            mp2 = _SYS_EXEC_FAIL_ERR_DIM.get(dim) or {}
            if isinstance(mp2, dict):
                ui_cnt = int(mp2.get(ek, 0) or 0)
            else:
                ui_cnt = 0
            if ui_cnt >= int(SYS_BREAKER_UI_FAIL_THRESH or 0):
                _breaker_trip(dim, reason=f"ui_fail:{ek} cnt={ui_cnt} thr={SYS_BREAKER_UI_FAIL_THRESH}", cooldown_sec=max(120.0, SYS_BREAKER_DEFAULT_COOLDOWN_SEC), do_self_heal=True, heal_reload_times=3)
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_1388', _e)
        pass
def _sys_dim_key(mod: str | None, coin: str | None, plat: str | None) -> str:
    try:
        m = (str(mod or "NA").upper().strip() or "NA")
    except Exception:
        m = "NA"
    try:
        c = (str(coin or "NA").upper().strip() or "NA")
    except Exception:
        c = "NA"
    try:
        p = (str(plat or "NA").upper().strip() or "NA")
    except Exception:
        p = "NA"
    return f"{m}|{c}|{p}"

def _sys_gatechain_get(req: dict) -> tuple[list, dict]:
    try:
        meta = req.get("meta") if isinstance(req.get("meta"), dict) else {}
    except Exception:
        meta = {}
    try:
        gc = meta.get("gatechain")
        if not isinstance(gc, list):
            gc = []
            meta["gatechain"] = gc
        req["meta"] = meta
        return gc, meta
    except Exception:
        return [], meta

def _sys_gatechain_add(req: dict, stage: str, ok: bool, code: str | None = None, reason: str | None = None, **extra) -> None:
    if not bool(SYS_GATECHAIN_ENABLE):
        return
    try:
        gc, meta = _sys_gatechain_get(req)
        if not isinstance(gc, list):
            return
        step = {"ts": now_ts(), "stage": str(stage or ""), "ok": bool(ok)}
        if code is not None:
            step["code"] = str(code)
        if reason is not None:
            step["reason"] = str(reason)
        if extra:
            for k, v in list(extra.items())[:12]:
                try:
                    if isinstance(v, (dict, list)):
                        step[k] = v if len(str(v)) <= 400 else str(v)[:400]
                    else:
                        step[k] = v
                except Exception:
                    step[k] = str(v)
        gc.append(step)
        try:
            mx = int(SYS_GATECHAIN_MAX_STEPS or 32)
        except Exception:
            mx = 32
        if mx > 0 and len(gc) > mx:
            del gc[0:len(gc)-mx]
        meta["gatechain"] = gc
        req["meta"] = meta
    except Exception:
        return

def _sys_gatechain_dump(req: dict) -> str:
    try:
        gc, _meta = _sys_gatechain_get(req)
        out = []
        for it in gc[-int(SYS_GATECHAIN_MAX_STEPS or 32):]:
            try:
                st = str(it.get("stage") or "")
                ok = "1" if bool(it.get("ok")) else "0"
                code = str(it.get("code") or "")
                out.append(f"{st}:{ok}:{code}" if code else f"{st}:{ok}")
            except Exception:
                continue
        return " -> ".join(out)
    except Exception:
        return ""

def _sys_pick_amount_usd(req: dict) -> float:
    """统一从 req/params/meta 里取金额，给去重/抖动/A1 共用，避免读到 0。"""
    try:
        if not isinstance(req, dict):
            return 0.0
        meta = req.get("meta") if isinstance(req.get("meta"), dict) else {}
        params = req.get("params") if isinstance(req.get("params"), dict) else {}
        for src in (req, params, meta):
            if isinstance(src, dict):
                for k in ("amount_usd", "usd", "amount", "notional_u", "add_notional_u"):
                    v = src.get(k)
                    if v not in (None, "", 0, 0.0):
                        try:
                            return float(v)
                        except Exception as _e:
                            _record_swallowed_exception('except_pass_line_1389', _e)
                            pass
        for k in ("LEGFIX__amount_usd", "LEGFIX__amount_usd", "B1__amount_usd", "X1__amount_usd"):
            v = meta.get(k) if isinstance(meta, dict) else None
            if v not in (None, "", 0, 0.0):
                try:
                    return float(v)
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_1390', _e)
                    pass
        return 0.0
    except Exception:
        return 0.0

def _sys_clear_dedupe_artifacts(req: dict) -> None:
    try:
        if not isinstance(req, dict):
            return
        meta = req.get("meta") if isinstance(req.get("meta"), dict) else {}
        params = req.get("params") if isinstance(req.get("params"), dict) else {}
        for bag in (meta, params):
            try:
                bag.pop("dedupe_key", None)
                bag.pop("dedupe_force_rebuild", None)
            except Exception:
                pass
        req["meta"] = meta
        if isinstance(req.get("params"), dict):
            req["params"] = params
    except Exception:
        pass

def _sys_force_rebuild_dedupe_key(req: dict) -> str:
    try:
        _sys_clear_dedupe_artifacts(req)
    except Exception:
        pass
    return _sys_ensure_dedupe_key(req)

def _sys_ensure_dedupe_key(req: dict) -> str:
    try:
        meta = req.get("meta") if isinstance(req.get("meta"), dict) else {}
        dk = meta.get("dedupe_key")
        if bool(meta.get("dedupe_force_rebuild")):
            dk = ""
        if isinstance(dk, str) and dk.strip():
            return dk.strip()
        mod = str(req.get("module") or "").upper().strip() or "NA"
        coin = str(req.get("coin") or "").upper().strip() or "NA"
        plat = str(req.get("platform") or req.get("plat") or "").upper().strip() or "NA"
        act = str(req.get("action_type") or req.get("action") or "").lower().strip() or "na"
        side = str(req.get("side") or meta.get("side") or "").upper().strip() or "NA"
        amt = float(_sys_pick_amount_usd(req) or 0.0)
        try:
            step = float(getattr(getattr(globals().get("MENHU", None), "cfg", None), "amount_step", SYS_AMOUNT_JITTER_STEP_U) or SYS_AMOUNT_JITTER_STEP_U)
        except Exception:
            step = float(SYS_AMOUNT_JITTER_STEP_U or 10.0)
        if step <= 0:
            step = 10.0
        amt_i = int(round(amt / step) * step) if amt > 0 else int(round(amt))
        grid_id = str(meta.get("grid_id") or req.get("grid_id") or "")
        layer_id = str(meta.get("layer_id") or req.get("layer_id") or "")
        leg = str(meta.get("leg") or meta.get("legacy_deleted_leg") or (req.get("params") or {}).get("leg") or "")
        key_parts = [mod, coin, plat, act, side]
        if grid_id:
            key_parts.append(f"gid={grid_id}")
        if layer_id:
            key_parts.append(f"lid={layer_id}")
        if leg:
            key_parts.append(f"leg={leg}")
        if not (mod == 'M9' and act in ('increase', 'add', 'open') and layer_id):
            key_parts.append(f"amt={amt_i}")
        dk2 = "|".join([p for p in key_parts if p])
        meta["dedupe_key"] = dk2
        req["meta"] = meta
        return dk2
    except Exception:
        try:
            return str(uuid.uuid4().hex)
        except Exception:
            return "DK"

def _sys_dedupe_allow(dim: str, dedupe_key: str, now_ts_f: float, *, mark_if_allow: bool = True) -> tuple[bool, float]:
    if not bool(SYS_DEDUPE_ENABLE):
        return True, 0.0
    try:
        d = str(dim or "NA")
        k = str(dedupe_key or "")
        if not k:
            return True, 0.0
        st = _SYS_DEDUPE_STATE.get(d)
        if not isinstance(st, dict):
            st = {}
            _SYS_DEDUPE_STATE[d] = st
        try:
            win = float(SYS_DEDUPE_WINDOW_SEC or 90.0)
        except Exception:
            win = 90.0
        try:
            mx = int(SYS_DEDUPE_MAX_KEYS_PER_DIM or 512)
        except Exception:
            mx = 512
        if win > 0:
            for kk, ts0 in list(st.items()):
                try:
                    if (now_ts_f - float(ts0)) > (win * 3.0):
                        st.pop(kk, None)
                except Exception:
                    st.pop(kk, None)
        last = float(st.get(k) or 0.0)
        if last and win > 0 and (now_ts_f - last) < win:
            return False, last
        if bool(mark_if_allow):
            st[k] = float(now_ts_f)
            if mx > 0 and len(st) > mx:
                try:
                    items = sorted(st.items(), key=lambda x: float(x[1] or 0.0))
                    for kk, _ in items[:max(1, len(items)-mx)]:
                        st.pop(kk, None)
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_1391', _e)
                    pass
        _SYS_DEDUPE_STATE[d] = st
        return True, last
    except Exception:
        return True, 0.0

def _sys_dedupe_mark(dim: str, dedupe_key: str, now_ts_f: float) -> None:
    """仅在入队成功后才写入全局 dedupe（避免 schema/闸门拒绝也占用 dedupe 窗口）。"""
    if not bool(SYS_DEDUPE_ENABLE):
        return
    try:
        d = str(dim or "NA")
        k = str(dedupe_key or "")
        if not k:
            return
        st = _SYS_DEDUPE_STATE.get(d)
        if not isinstance(st, dict):
            st = {}
        st[k] = float(now_ts_f)
        _SYS_DEDUPE_STATE[d] = st
    except Exception:
        return

def _sys_apply_amount_jitter(req: dict, dim: str, trace_id: str) -> None:
    if not bool(SYS_AMOUNT_JITTER_ENABLE):
        return
    try:
        act = str(req.get("action_type") or "").lower().strip()
        if act in ("decrease", "close", "reduce", "tp", "take_profit", "sell", "buy_close"):
            return
        if act not in ("increase", "add", "open", "open_pair", "open_full", "add_leg", "grid_increase", "grid_add", "grid_add_leg", "grid_addleg"):
            return
        meta = req.get("meta") if isinstance(req.get("meta"), dict) else {}
        if meta.get("no_random_amount") is True:
            return
        if meta.get("amount_jitter_done") is True:
            return
        nowf = time.time()
        amt = _safe_float(req.get("usd") or req.get("amount_usd") or meta.get("amount_usd") or (req.get("params") or {}).get("usd") or (req.get("params") or {}).get("amount_usd"), 0.0)
        if not (amt and amt > 0):
            return
        try:
            step = float(getattr(getattr(globals().get("MENHU", None), "cfg", None), "amount_step", SYS_AMOUNT_JITTER_STEP_U) or SYS_AMOUNT_JITTER_STEP_U)
        except Exception:
            step = float(SYS_AMOUNT_JITTER_STEP_U or 10.0)
        if step <= 0:
            step = 10.0
        amt0 = float(round(float(amt) / step) * step)
        last = _SYS_LAST_AMOUNT_DIM.get(str(dim or "NA"))
        win = float(SYS_AMOUNT_JITTER_WINDOW_SEC or 600.0)
        if last and (nowf - float(last[1] or 0.0)) < win and abs(float(last[0]) - amt0) < 1e-9:
            sgn = 1.0
            try:
                hx = int(str(trace_id or "")[-2:], 16)
                sgn = 1.0 if (hx % 2 == 0) else -1.0
            except Exception:
                sgn = 1.0 if (random.random() >= 0.5) else -1.0
            new_amt = max(step, amt0 + sgn * step)
            if req.get("usd") not in (None, "", 0):
                req["usd"] = float(new_amt)
            else:
                req["amount_usd"] = float(new_amt)
            try:
                pm = req.get("params") if isinstance(req.get("params"), dict) else {}
                if ("usd" in pm) or (pm.get("usd") not in (None, "", 0)):
                    pm["usd"] = float(new_amt)
                if ("amount_usd" in pm) or (pm.get("amount_usd") not in (None, "", 0)):
                    pm["amount_usd"] = float(new_amt)
                req["params"] = pm
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_1392', _e)
                pass
            meta["amount_jitter_done"] = True
            meta["amount_jitter_before"] = float(amt0)
            meta["amount_jitter_after"] = float(new_amt)
            meta["amount_jitter_step"] = float(step)
            req["meta"] = meta
            try:
                _trace_event("amount_jitter", to_console=True, module=str(req.get("module") or ""), coin=str(req.get("coin") or ""),
                            platform=str(req.get("platform") or ""), action_type=str(act),
                            trace_id=str(trace_id or ""), before=float(amt0), after=float(new_amt), step=float(step))
            except Exception as _e:
                _record_swallowed_exception('except_pass_line_1393', _e)
                pass
        else:
            _SYS_LAST_AMOUNT_DIM[str(dim or "NA")] = (float(amt0), float(nowf))
            meta["amount_jitter_done"] = True
            req["meta"] = meta
    except Exception:
        return

def _sys_funnel_inc(dim: str, stage: str, n: int = 1) -> None:
    """极轻量、永不抛异常：记录漏斗计数（10分钟窗口）。"""
    try:
        if not dim:
            dim = "NA|NA|NA"
        stage = str(stage or "NA").strip() or "NA"
        mp = _SYS_FUNNEL_DIM.get(dim)
        if not isinstance(mp, dict):
            mp = {}
            _SYS_FUNNEL_DIM[dim] = mp
        mp[stage] = int(mp.get(stage, 0)) + int(n or 0)
    except Exception:
        return

def _sys_go_inc(ev: dict) -> None:
    """增量统计：被 GOMenHu._probe_push 调用（轻量、不可抛异常）。"""
    try:
        if not isinstance(ev, dict):
            return
        mod = str(ev.get("module") or "NA").upper().strip() or "NA"
        try:
            coin = str(ev.get("coin") or ev.get("symbol") or "NA").upper().strip() or "NA"
        except Exception:
            coin = "NA"
        try:
            plat = str(ev.get("platform") or ev.get("plat") or "NA").upper().strip() or "NA"
        except Exception:
            plat = "NA"
        dim = _sys_dim_key(mod, coin, plat)
        ok = bool(ev.get("ok") is True)
        _sys_funnel_inc(dim, "submit_accept" if ok else "submit_reject", 1)
        st_dim = _SYS_GO_STATS_DIM.get(dim)
        if not isinstance(st_dim, dict):
            st_dim = {"accept": 0, "reject": 0, "total": 0}
            _SYS_GO_STATS_DIM[dim] = st_dim
        st_dim["total"] = int(st_dim.get("total", 0)) + 1
        if ok:
            st_dim["accept"] = int(st_dim.get("accept", 0)) + 1
        else:
            st_dim["reject"] = int(st_dim.get("reject", 0)) + 1

        st = _SYS_GO_STATS.get(mod)
        if not isinstance(st, dict):
            st = {"accept": 0, "reject": 0, "total": 0}
            _SYS_GO_STATS[mod] = st
        st["total"] = int(st.get("total", 0)) + 1
        if ok:
            st["accept"] = int(st.get("accept", 0)) + 1
        else:
            st["reject"] = int(st.get("reject", 0)) + 1

        if not ok:
            rc = str(ev.get("reject_code") or "").strip() or ""
            rr = str(ev.get("reject_reason") or "").strip() or ""
            if rc:
                mpd = _SYS_GO_REJECT_CODE_DIM.get(dim)
                if not isinstance(mpd, dict):
                    mpd = {}
                    _SYS_GO_REJECT_CODE_DIM[dim] = mpd
                mpd[rc] = int(mpd.get(rc, 0)) + 1
            if rr:
                mpd2 = _SYS_GO_REJECT_REASON_DIM.get(dim)
                if not isinstance(mpd2, dict):
                    mpd2 = {}
                    _SYS_GO_REJECT_REASON_DIM[dim] = mpd2
                mpd2[rr] = int(mpd2.get(rr, 0)) + 1
            if rc:
                mp = _SYS_GO_REJECT_CODE.get(mod)
                if not isinstance(mp, dict):
                    mp = {}
                    _SYS_GO_REJECT_CODE[mod] = mp
                mp[rc] = int(mp.get(rc, 0)) + 1
            if rr:
                mp2 = _SYS_GO_REJECT_REASON.get(mod)
                if not isinstance(mp2, dict):
                    mp2 = {}
                    _SYS_GO_REJECT_REASON[mod] = mp2
                mp2[rr] = int(mp2.get(rr, 0)) + 1

        try:
            if not ok:
                stage = str(ev.get("reject_stage") or "").strip() if isinstance(ev, dict) else ""
                if not stage:
                    stage = _sys_reject_stage_guess(str(ev.get("reject_code") or ""), str(ev.get("reject_reason") or ""))
                mp_stage = _SYS_REJECT_STAGE_DIM.get(dim)
                if not isinstance(mp_stage, dict):
                    mp_stage = {}
                    _SYS_REJECT_STAGE_DIM[dim] = mp_stage
                mp_stage[stage] = int(mp_stage.get(stage, 0) or 0) + 1
                try:
                    _dim_dyn_on_reject_stage(dim, stage)
                except Exception as _e:
                    _record_swallowed_exception('except_pass_line_1394', _e)
                    pass
                _breaker_on_reject(dim, stage)
        except Exception as _e:
            _record_swallowed_exception('except_pass_line_1395', _e)
            pass
    except Exception:
        return

def _sys_go_top3(mp: dict[str, int]) -> list[str]:
    try:
        if not isinstance(mp, dict) or not mp:
            return []
        items = sorted(mp.items(), key=lambda kv: (-int(kv[1] or 0), str(kv[0])))[:3]
        return [f"{k}={v}" for k, v in items]
    except Exception:
        return []

def _sys_go_emit_lines() -> list[str]:
    out: list[str] = []
    try:
        for mod, st in sorted(_SYS_GO_STATS.items(), key=lambda kv: (-int((kv[1] or {}).get("total", 0)), kv[0])):
            if not isinstance(st, dict):
                continue
            tot = int(st.get("total", 0))
            if tot <= 0:
                continue
            acc = int(st.get("accept", 0))
            rej = int(st.get("reject", 0))
            topc = " | ".join(_sys_go_top3(_SYS_GO_REJECT_CODE.get(mod, {})))
            topr = " | ".join(_sys_go_top3(_SYS_GO_REJECT_REASON.get(mod, {})))
            out.append(f"[{now_ts()}] [GO_SUMMARY] mod={mod} total={tot} accept={acc} reject={rej} top_code=({topc or '-'}) top_reason=({topr or '-'})")
    except Exception:
        return out

    try:
        _dims2 = []
        for _d, _st in (_SYS_GO_STATS_DIM or {}).items():
            try:
                _tot = int((_st or {}).get('total', 0) or 0)
            except Exception:
                _tot = 0
            if _tot <= 0:
                continue
            _dims2.append((_tot, _d))
        _dims2.sort(reverse=True)
        for _tot, _d in _dims2[:12]:
            mp = _SYS_REJECT_STAGE_DIM.get(_d, {}) if isinstance(_SYS_REJECT_STAGE_DIM, dict) else {}
            top_stage = ' | '.join(_sys_topn(mp, 3)) if isinstance(mp, dict) else ''
            if top_stage:
                out.append(f"[{now_ts()}] [REJECT_STAGE] dim={_d} top_stage=({top_stage})")
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_1396', _e)
        pass
    try:
        _dims3 = []
        for _d, mp in (_SYS_EXEC_FAIL_ERR_DIM or {}).items():
            if not isinstance(mp, dict) or not mp:
                continue
            try:
                _tot = sum(int(v or 0) for v in mp.values())
            except Exception:
                _tot = 0
            if _tot <= 0:
                continue
            _dims3.append((_tot, _d))
        _dims3.sort(reverse=True)
        for _tot, _d in _dims3[:12]:
            mp = _SYS_EXEC_FAIL_ERR_DIM.get(_d, {})
            top_err = ' | '.join(_sys_topn(mp, 3)) if isinstance(mp, dict) else ''
            if top_err:
                out.append(f"[{now_ts()}] [EXEC_FAIL_TOP] dim={_d} top_err=({top_err})")
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_1397', _e)
        pass
    try:
        now = time.time()
    except Exception:
        now = 0.0
    try:
        _rows = []
        for _d, st in (_SYS_BREAKER_STATE or {}).items():
            if not isinstance(st, dict):
                continue
            try:
                ou = float(st.get('open_until') or 0.0)
            except Exception:
                ou = 0.0
            if ou > now:
                _rows.append((ou, _d, st))
        _rows.sort(reverse=True)
        for ou, _d, st in _rows[:12]:
            rs = str(st.get('last_reason') or '-')[:120]
            out.append(f"[{now_ts()}] [BREAKER] dim={_d} open_until={ou:.0f} reason={rs}")
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_1398', _e)
        pass
    try:
        _rows = []
        for _d, st in (_SYS_SELF_HEAL_DIM or {}).items():
            if not isinstance(st, dict):
                continue
            try:
                ut = float(st.get('until') or 0.0)
            except Exception:
                ut = 0.0
            if ut > now:
                _rows.append((ut, _d, st))
        _rows.sort(reverse=True)
        for ut, _d, st in _rows[:12]:
            rs = str(st.get('reason') or '-')[:120]
            rt = int(st.get('reload_times') or 0)
            out.append(f"[{now_ts()}] [SELF_HEAL] dim={_d} until={ut:.0f} reload_times={rt} reason={rs}")
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_1399', _e)
        pass
    return out

