def _json_default_for_bot_late(obj):
    try:
        import dataclasses as _dc
        if _dc.is_dataclass(obj):
            try:
                return _dc.asdict(obj)
            except Exception:
                return obj.__dict__
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_1761', _e)
        pass
    try:
        if isinstance(obj, (set, tuple)):
            return list(obj)
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_1762', _e)
        pass
    try:
        if isinstance(obj, (bytes, bytearray)):
            try:
                return obj.decode("utf-8", errors="ignore")
            except Exception:
                return repr(obj)
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_1763', _e)
        pass
    try:
        if hasattr(obj, "__dict__"):
            return dict(obj.__dict__)
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_1764', _e)
        pass
    try:
        return str(obj)
    except Exception:
        return repr(obj)
_json_default_for_bot = _json_default_for_bot_late

def _json_dumps_bot_late(obj, **kwargs) -> str:
    kw = dict(kwargs or {})
    kw.setdefault("ensure_ascii", False)
    kw.setdefault("default", _json_default_for_bot)
    try:
        return json.dumps(obj, **kw)
    except Exception:
        def _fallback(o):
            try:
                return _json_default_for_bot(o)
            except Exception:
                return str(o)
        kw["default"] = _fallback
        return json.dumps(obj, **kw)
_json_dumps_bot = _json_dumps_bot_late

def _json_dump_bot_late(obj, fp, **kwargs):
    kw = dict(kwargs or {})
    kw.setdefault("ensure_ascii", False)
    kw.setdefault("default", _json_default_for_bot)
    return json.dump(obj, fp, **kw)
_json_dump_bot = _json_dump_bot_late

