                        _close_target_layer_id = str(_fb_src.get('layer_id') or _fb_layer_id or '')
                        _close_reason_code = str(_fb_src.get('reason_code') or _fb_src.get('reason') or 'master_book_tp_hit_single_sell_source')
                        _close_force_tp = False
