@dataclass
class DecisionReason:
    code: str = ""
    priority: int = 0
    detail: str = ""
    extras: List[str] = field(default_factory=list)

    def consider(self, code: str, priority: int, detail: str) -> None:
        if priority > self.priority:
            if self.code:
                self.extras.append(f"{self.code}:{self.detail}")
            self.code = code
            self.priority = priority
            self.detail = detail
        else:
            self.extras.append(f"{code}:{detail}")

