def risk_check(
    risk: GridRiskConfig,
    hourly_state: HourlyRiskState,
    amount_u: float,
    request_leg: Optional[str] = None,
) -> Tuple[Optional[str], Dict[str, Any]]:
    leg_count = hourly_state.recent_add_count_by_leg_1h.get(request_leg or "", 0) if request_leg else None
    leg_last_add_ts = hourly_state.last_add_ts_by_leg.get(request_leg or "", 0.0) if request_leg else None
    obs = {
        "hardcap_used_u": risk.used_u,
        "hardcap_cap_u": risk.hardcap_u,
        "hardcap_left_u": max(0.0, risk.hardcap_u - risk.used_u) if risk.hardcap_u > 0 else None,
        "hourly_add_count_1h": hourly_state.recent_add_count_1h,
        "hourly_limit": risk.hourly_add_limit,
        "per_leg_hourly_limit": risk.per_leg_hourly_add_limit,
        "request_leg": request_leg,
        "leg_add_count_1h": leg_count,
        "leg_last_add_ts": leg_last_add_ts,
        "now_ts": risk.now_ts,
        "last_add_ts": hourly_state.last_add_ts,
        "paused": risk.paused,
    }
    if risk.paused:
        return "pause_block", obs
    if risk.hardcap_u > 0 and (risk.used_u + amount_u) > risk.hardcap_u:
        return "hardcap_block", obs
    if risk.hourly_add_limit > 0 and hourly_state.recent_add_count_1h >= risk.hourly_add_limit:
        return "GRID_RISK_BLOCK_HOURLY_LIMIT", obs
    if request_leg and risk.per_leg_hourly_add_limit > 0 and leg_count is not None and leg_count >= risk.per_leg_hourly_add_limit:
        return "GRID_RISK_BLOCK_LEG_HOURLY_LIMIT", obs
    return None, obs

def apply_open_fill_to_risk_state(
    risk: GridRiskConfig,
    hourly_state: HourlyRiskState,
    amount_u: float,
    fill_ts: float,
    request_leg: Optional[str],
) -> Dict[str, Any]:
    risk.used_u += amount_u
    risk.now_ts = fill_ts
    hourly_state.recent_add_count_1h += 1
    hourly_state.last_add_ts = fill_ts
    leg_count_after = None
    leg_last_after = None
    if request_leg:
        hourly_state.recent_add_count_by_leg_1h[request_leg] = hourly_state.recent_add_count_by_leg_1h.get(request_leg, 0) + 1
        hourly_state.last_add_ts_by_leg[request_leg] = fill_ts
        leg_count_after = hourly_state.recent_add_count_by_leg_1h[request_leg]
        leg_last_after = hourly_state.last_add_ts_by_leg[request_leg]
    return {
        "used_u_after": risk.used_u,
        "hourly_add_count_1h_after": hourly_state.recent_add_count_1h,
        "last_add_ts_after": hourly_state.last_add_ts,
        "request_leg": request_leg,
        "leg_add_count_1h_after": leg_count_after,
        "leg_last_add_ts_after": leg_last_after,
    }

def apply_close_fill_to_risk_state(risk: GridRiskConfig, released_u: float, fill_ts: float) -> Dict[str, Any]:
    risk.used_u = max(0.0, risk.used_u - max(0.0, released_u))
    risk.now_ts = fill_ts
    return {
        "used_u_after": risk.used_u,
        "released_u": max(0.0, released_u),
    }

def summarize_open_decision(decision: OpenDecision) -> Dict[str, Any]:
    obs = decision.observations
    request_leg = obs.get("request_leg")
    last_layer = obs.get("last_real_layer_id")
    next_layer = obs.get("next_layer_id")
    process_notes: List[str] = []
    if obs.get("cold_start"):
        process_notes.append("冷启动首层")
    if obs.get("cold_start_decision_reason"):
        process_notes.append(f"冷启动依据={obs['cold_start_decision_reason']}")
    if obs.get("cur_px") is not None and obs.get("need_px") is not None:
        process_notes.append(f"gap: cur={obs['cur_px']}, need={obs['need_px']}")
    if obs.get("grid_mode"):
        process_notes.append(f"模式={obs.get('grid_mode')}")
    if int(obs.get("trend_breakout_add_enabled") or 0):
        process_notes.append(f"趋势突破加仓=开；金额 {obs.get('amount_u_after_breakout') or decision.amount_u}U；利润缓冲 {obs.get('trend_breakout_profit_buffer_u')}U")
    elif str(obs.get("trend_breakout_reason") or "").strip():
        process_notes.append(f"趋势突破未放行={obs.get('trend_breakout_reason')}")
    if last_layer or next_layer:
        process_notes.append(f"层号: 最后层={last_layer}, 下一层={next_layer}")
    if obs.get("missing_layer_nos"):
        process_notes.append(f"断层={obs['missing_layer_nos']}")
    code = decision.reason.code or ("OPEN_OK" if decision.ok else "NO_REQUEST")
    mapping = {
        "OPEN_OK": "允许开仓",
        "GRID_GAP_NOT_REACHED": "网格间距未到",
        "GAP_LT_MIN_1PCT": "未达到最低1%网格间距",
        "hardcap_block": "硬顶拦截",
        "GRID_RISK_BLOCK_HOURLY_LIMIT": "每小时限频拦截",
        "cooldown_block": "全局冷却中",
        "GRID_RISK_BLOCK_LEG_HOURLY_LIMIT": "单腿每小时限频拦截",
        "leg_cooldown_block": "单腿冷却中",
        "pause_block": "暂停中",
        "LAYER_ID_DISCONTINUITY": "层号断裂，禁止开仓",
        "rsi_side_block": "RSI 未形成允许腿",
        "GAP_ANCHOR_MISSING": "缺少 gap 锚点",
        "NO_REQUEST": "未形成请求",
    }
    final = mapping.get(code, code)
    detail = f"{request_leg}，层号 {decision.layer_id}，金额 {decision.amount_u}U" if decision.ok else "；".join(process_notes)
    return {
        "coin": decision.coin,
        "request_leg": request_leg,
        "final_reason": final,
        "final_dead_reason": code,
        "detail": detail,
        "process_notes": process_notes,
        "extras": list(decision.reason.extras),
    }

def decide_open(
    coin: str,
    market: CoinMarket,
    positions: List[LegPosition],
    ledger: GridLedger,
    config: GridConfig,
    risk: GridRiskConfig,
    hourly_state: HourlyRiskState,
    sources: Optional[GridStateSources] = None,
) -> OpenDecision:
    reason = DecisionReason()
    obs: Dict[str, Any] = {"coin": coin, "mode": "NORMAL"}
    st = resolve_request_leg_grid_state(coin, market, positions, ledger, sources)
    obs.update({
        "request_leg": st["request_leg"],
        "request_leg_real_m9_open_layers": st["request_leg_real_m9_open_layers"],
        "last_real_layer_id": st["last_real_layer_id"],
        "last_real_layer_no": st["last_real_layer_no"],
        "next_layer_id": st["next_layer_id"],
        "next_layer_no": st["next_layer_no"],
        "cold_start": st["cold_start"],
        "cold_start_immediate": bool(st.get("cold_start_immediate")),
        "gap_bypassed_by_cold_start": bool(st.get("gap_bypassed_by_cold_start")),
        "cold_start_decision_reason": st["cold_start_decision_reason"],
        "layer_audit": st["layer_audit"],
        "same_side_pos_u": float(st.get("same_side_pos_u") or 0.0),
    })
    if bool(st.get("cold_start")):
        obs["cold_start_expected_layer_no"] = int(st.get("next_layer_no") or 2)
        obs["cold_start_force_l2_when_live_base_exists"] = bool(((st.get("layer_audit") or {}).get("cold_start_forced_from_live_base")))
        obs["cold_start_gap_bypassed"] = bool(st.get("gap_bypassed_by_cold_start"))
        obs["cold_start_anchor_only_layers_excluded"] = list((((st.get("layer_audit") or {}).get("anchor_only_layer_ids_excluded_from_real_open")) or []))
        obs["cold_start_unified_same_rule_old_new_coin"] = bool(((st.get("layer_audit") or {}).get("cold_start_unified_same_rule_old_new_coin")))

    if not st["request_leg"]:
        reason.consider("rsi_side_block", ReasonPriority.RSI_BLOCK, "RSI 未形成允许腿")
        return OpenDecision(False, coin, None, False, None, None, 0.0, reason, obs)

    cold_start_block_reason = str(st.get("cold_start_decision_reason") or "")
    if cold_start_block_reason in ("cold_start_blocked_by_opposite_live_leg", "m9_truth_missing_block_open") or bool(st.get("block_cold_start_because_position_exists")):
        reason.consider(cold_start_block_reason or 'm9_truth_missing_block_open', ReasonPriority.SYSTEM_ERROR, f"冷启动前置拦截: {cold_start_block_reason or 'm9_truth_missing_block_open'}")
        obs["cold_start_blocked_precheck"] = True
        return OpenDecision(False, coin, st["request_leg"], False, None, None, 0.0, reason, obs)

    continuity = st["layer_audit"]["continuity"]
    if not continuity["continuous"]:
        reason.consider(
            "LAYER_ID_DISCONTINUITY",
            ReasonPriority.SYSTEM_ERROR,
            f"层号不连续，缺层={continuity['missing']}",
        )
        obs["missing_layer_nos"] = continuity["missing"]
        return OpenDecision(False, coin, st["request_leg"], False, None, None, 0.0, reason, obs)

    leg_side = st["request_leg"].split("|")[-1]
    allowed_side = str(st.get("allowed_side") or "")
    obs["m9_allowed_side"] = allowed_side
    obs["m9_platform_pick_reason"] = str((((st.get("layer_audit") or {}).get("platform_audit") or {}).get("chosen_reason")) or "")
    obs["m9_request_leg_side"] = leg_side
    if allowed_side and leg_side and str(leg_side).upper().strip() != str(allowed_side).upper().strip():
        reason.consider("m9_side_filtered_by_rsi_before_gap", ReasonPriority.RSI_BLOCK, f"RSI={allowed_side}，但 request_leg={st['request_leg']}")
        obs["m9_gap_check_side_assert"] = "reject"
        return OpenDecision(False, coin, st["request_leg"], False, None, None, 0.0, reason, obs)
    obs["m9_gap_check_side_assert"] = "pass"
    resolved_layer_no, layer_no_obs, layer_no_err = resolve_next_layer_no_strict(st)
    obs.update(layer_no_obs)
    if layer_no_err:
        reason.consider(layer_no_err, ReasonPriority.SYSTEM_ERROR, f"层号缺失/非法: next_layer_no={st.get('next_layer_no')}, next_layer_id={st.get('next_layer_id')}")
        return OpenDecision(False, coin, st["request_leg"], bool(st.get("cold_start")), None, None, 0.0, reason, obs)

    coin_u = str(coin or '').upper().strip()
    is_dynamic_new_coin_gap = bool(coin_u and _coin_pool_is_dynamic_new_coin(coin_u))
    base_gap_pct = float((getattr(config.volatility, "base_gap_pct_by_coin", {}) or {}).get(coin_u, config.volatility.base_gap_pct) or config.volatility.base_gap_pct)
    if is_dynamic_new_coin_gap:
        base_gap_pct = float(min(max(base_gap_pct, _new_coin_grid_gap_min_pct()), _new_coin_grid_gap_max_pct()))
    obs["base_gap_pct_coin"] = float(base_gap_pct)
    obs["is_dynamic_new_coin_gap"] = bool(is_dynamic_new_coin_gap)
    vol_gap_pct, vol_obs = calc_volatility_gap_pct(market, config.volatility)
    obs.update(vol_obs)
    amount_u, amount_obs = map_amount_u(market, config.amount_map, config.trend, vol_gap_pct, base_gap_pct, resolved_layer_no, base_leg_notional_u=float(st.get("base_leg_notional_u") or 0.0))
    obs.update(amount_obs)
    _req_plat = str(st["request_leg"].split("|")[0] if ("|" in str(st.get("request_leg") or "")) else "")
    _req_side = str(st["request_leg"].split("|")[1] if ("|" in str(st.get("request_leg") or "")) else "")
    _gid = f"{coin}_{_req_plat}_{_req_side}_M9" if _req_plat and _req_side else ""
    _trend_snapshot = _m9_build_positions_snapshot_for_coin(str(coin), positions, getattr(market, 'mark_px', None))
    _grid_mode, _trend_det = _m9_pick_grid_mode(_req_side, getattr(market, "rsi", None), getattr(market, "adx", None), _gid, snapshot=_trend_snapshot, coin=str(coin))
    obs.update(dict(_trend_det or {}))
    obs["grid_mode"] = str(_grid_mode)
    obs["mode"] = str(_grid_mode)

    if st["cold_start"]:
        obs["COLD_START_ARMED"] = True
        obs["FIRST_REAL_LAYER_GAP_BYPASS"] = True
        risk_code, risk_obs = risk_check(risk, hourly_state, amount_u, st["request_leg"])
        obs.update(risk_obs)
        if risk_code:
            reason.consider(risk_code, ReasonPriority.RISK_BLOCK, f"冷启动首层被风控拦截: {risk_code}")
            return OpenDecision(False, coin, st["request_leg"], True, None, None, amount_u, reason, obs)
        return OpenDecision(True, coin, st["request_leg"], True, st["next_layer_id"], resolved_layer_no, amount_u, reason, obs)

    trend_gap_pct = float(vol_gap_pct)
    trend_gap_obs = {'trend_gap_reason': 'unified_24h_vol_trigger_keep', 'trend_gap_adj_pct': 0.0, 'gap_pct_after_trend': float(vol_gap_pct)}
    obs.update(trend_gap_obs)
    layer_depth_gap_pct = float(vol_gap_pct)
    layer_gap_obs = {'layer_gap_reason': 'unified_24h_vol_trigger_keep', 'layer_gap_adj_pct': 0.0, 'gap_pct_after_layer': float(vol_gap_pct), 'next_layer_no': int(resolved_layer_no or 0), 'next_layer_no_used': int(resolved_layer_no or 0), 'layer_gap_start': 0, 'layer_gap_mult_used': 1.0}
    obs.update(layer_gap_obs)
    min_gap_pct = float(_m9_gap_truth_floor_pct(coin_u))
    max_gap_pct = float(_m9_gap_truth_cap_pct(coin_u))
    base_gap_pct = float(base_gap_pct)
    vol_gap_pct = float(vol_gap_pct)
    trend_gap_pct = float(trend_gap_pct)
    layer_depth_gap_pct = float(layer_depth_gap_pct)
    final_gap_source = 'unified_24h_volatility_x_10pct'
    final_gap_pct = max(float(min_gap_pct), min(float(max_gap_pct), float(vol_gap_pct)))
    obs["gap_pct_used"] = final_gap_pct
    obs["base_gap_pct"] = float(base_gap_pct)
    obs["volatility_gap_pct"] = float(vol_gap_pct)
    obs["trend_gap_pct"] = float(trend_gap_pct)
    obs["layer_depth_gap_pct"] = float(layer_depth_gap_pct)
    obs["min_gap_pct"] = float(min_gap_pct)
    obs["max_gap_pct"] = float(max_gap_pct)
    obs["vol_gap_adj_pct"] = float(final_gap_pct - base_gap_pct)
    obs["trend_gap_adj_pct"] = 0.0
    obs["layer_depth_gap_adj_pct"] = 0.0
    obs["required_gap_pct"] = float(final_gap_pct)
    obs["final_gap_pct"] = float(final_gap_pct)
    obs["final_gap_source"] = str(final_gap_source)
    obs["trigger_calc_text"] = f"近24h波动={_m9_fmt_pct_text(_safe_float(obs.get('vol24h_pct'), None) * 100.0 if obs.get('vol24h_pct') is not None else None)} × 10% -> 原始触发={_m9_fmt_pct_text(_safe_float(obs.get('trigger_raw_pct'), None) * 100.0 if obs.get('trigger_raw_pct') is not None else None)} -> 地板={_m9_fmt_pct_text(float(min_gap_pct) * 100.0)} -> 最终={_m9_fmt_pct_text(float(final_gap_pct) * 100.0)}"
    obs["owner_chain"] = "M9_SINGLE_CHAIN"
    obs["grid_id_canonical"] = st.get("next_layer_id", "")[: str(st.get("next_layer_id", "")).rfind("_L")] if (st.get("next_layer_id") and "_L" in str(st.get("next_layer_id"))) else ""
    obs["layer_tp_pct_locked"] = float(getattr(config, "tp_pct", 0.0) or 0.0)
    obs["layer_tp_policy_version"] = "m9_tp_v1"

    last_px = st["last_real_entry_px"]
    request_price = float(market.mark_px or 0.0)
    if request_price <= 0:
        reason.consider("mark_px_missing", ReasonPriority.SYSTEM_ERROR, "mark_px 无效，无法做 gap 判定")
        obs["request_price_for_gap"] = request_price
        return OpenDecision(False, coin, st["request_leg"], False, None, None, amount_u, reason, obs)

    _breakout_det = _m9_trend_breakout_eval(str(coin), market, positions, str(st.get('request_leg') or ''), float(amount_u or 0.0), str(obs.get('grid_mode') or 'NORMAL'), trend_det=dict(_trend_det or {}))
    obs["trend_breakout_reason"] = str((_breakout_det or {}).get("reason") or "")
    obs["trend_breakout_add_enabled"] = int(bool((_breakout_det or {}).get("allow")))
    obs["trend_breakout_gap_bypass"] = int(bool((_breakout_det or {}).get("allow")))
    obs["trend_breakout_buffer_pct"] = _safe_float((_breakout_det or {}).get("breakout_buffer_pct"), None)
    obs["trend_breakout_ref_px"] = _safe_float((_breakout_det or {}).get("breakout_ref_px"), None)
    obs["trend_breakout_need_px"] = _safe_float((_breakout_det or {}).get("breakout_need_px"), None)
    obs["trend_breakout_profit_buffer_u"] = _safe_float((_breakout_det or {}).get("profit_buffer_u"), None)
    obs["trend_breakout_profit_need_u"] = _safe_float((_breakout_det or {}).get("profit_buffer_need_u"), None)
    obs["trend_breakout_amount_mult"] = _safe_float((_breakout_det or {}).get("amount_mult"), None)
    obs["trend_breakout_recent_path_ok"] = int(bool((_breakout_det or {}).get("recent_close_path_ok")))
    obs["trend_breakout_px_ok"] = int(bool((_breakout_det or {}).get("breakout_px_ok")))
    obs["trend_breakout_m10_blocked"] = int(bool((_breakout_det or {}).get("m10_blocked")))
    if bool((_breakout_det or {}).get("allow")):
        _amount_before_breakout = float(amount_u or 0.0)
        amount_u = float((_breakout_det or {}).get("breakout_amount_u") or amount_u)
        obs["amount_u_pre_breakout"] = float(_amount_before_breakout)
        obs["amount_u_after_breakout"] = float(amount_u)
        obs["trend_amount_applied"] = True
        obs["trend_amount_mult_used"] = float((_breakout_det or {}).get("amount_mult") or 1.0)
        obs["candidate_mode"] = "TREND_BREAKOUT_ADD"
        obs["trigger_calc_text"] = f"趋势突破加仓: 模式=TREND 价格突破 {round(float((_breakout_det or {}).get('breakout_ref_px') or 0.0), 6)} 后追击，金额={round(float(amount_u or 0.0), 6)}U，利润缓冲={round(float((_breakout_det or {}).get('profit_buffer_u') or 0.0), 6)}U"
    else:
        obs.setdefault("candidate_mode", "GRID_ADD")

    if (last_px is None or last_px <= 0) and (not bool(obs.get("trend_breakout_gap_bypass"))):
        reason.consider("last_real_entry_px_missing", ReasonPriority.SYSTEM_ERROR, "普通层没有 last_real_entry_px")
        return OpenDecision(False, coin, st["request_leg"], False, None, None, amount_u, reason, obs)
    gap_real_pct = (abs(float(request_price) - float(last_px)) / max(abs(float(last_px)), 1e-12)) if (last_px is not None and float(last_px) > 0.0) else 0.0
    if bool(obs.get("trend_breakout_gap_bypass")):
        ok_gap = True
        need_px = _safe_float(obs.get("trend_breakout_need_px"), None)
        obs["gap_gate_mode"] = "trend_breakout_bypass"
    else:
        ok_gap, need_px = eval_gap(last_px, request_price, leg_side, final_gap_pct)
        obs["gap_gate_mode"] = "normal_gap_gate"
    obs.update({
        "cur_px": request_price,
        "request_price_for_gap": request_price,
        "last_px": last_px,
        "last_real_entry_price_source": st.get("last_real_entry_price_source"),
        "need_px": need_px,
        "gap_real_pct": gap_real_pct,
        "GRID_GAP_REACHED": ok_gap,
    })
    try:
        safe_log(lambda: f"[{now_ts()}] [M9_FINAL_GAP_CHECK] coin={coin} allowed_side={allowed_side} pick_reason={obs.get('m9_platform_pick_reason')} leg={st.get('request_leg')} last_layer={st.get('last_real_layer_id')} last_fill={_fmt_float(last_px)} last_src={st.get('last_real_entry_price_source')} request_px={_fmt_float(request_price)} gap_real_pct={_fmt_float(gap_real_pct)} vol_gap_pct={_fmt_float(vol_gap_pct)} min_gap_pct={_fmt_float(min_gap_pct)} base_gap_pct={_fmt_float(base_gap_pct)} vol_gap_pct={_fmt_float(vol_gap_pct)} trend_gap_pct={_fmt_float(trend_gap_pct)} layer_depth_gap_pct={_fmt_float(layer_depth_gap_pct)} min_gap_pct={_fmt_float(min_gap_pct)} final_gap_pct={_fmt_float(final_gap_pct)} final_gap_source={final_gap_source} need_px={_fmt_float(need_px)} allow={1 if ok_gap else 0}")
    except Exception as _e:
        _record_swallowed_exception('except_pass_line_1808', _e)
        pass
    if not ok_gap:
        _gap_floor_code = float(min_gap_pct if min_gap_pct is not None else _m9_gap_truth_floor_pct(coin_u))
        code = "GAP_LT_MIN_1PCT" if (gap_real_pct is not None and float(gap_real_pct) + 1e-12 < float(_gap_floor_code)) else "GRID_GAP_NOT_REACHED"
        obs["gap_block_reason_detail"] = ("floor_not_reached" if str(code) == "GAP_LT_MIN_1PCT" else ("breakout_blocked_then_gap_not_reached" if int(obs.get("trend_breakout_m10_blocked") or 0) else "normal_gap_not_reached"))
        reason.consider(code, ReasonPriority.GAP_BLOCK, f"网格间距未到: cur={request_price}, need={need_px}, req_gap={final_gap_pct}")
        return OpenDecision(False, coin, st["request_leg"], False, None, None, amount_u, reason, obs)

    risk_code, risk_obs = risk_check(risk, hourly_state, amount_u, st["request_leg"])
    obs.update(risk_obs)
    if risk_code:
        reason.consider(risk_code, ReasonPriority.RISK_BLOCK, f"普通层被风控拦截: {risk_code}")
        return OpenDecision(False, coin, st["request_leg"], False, None, None, amount_u, reason, obs)

    return OpenDecision(True, coin, st["request_leg"], False, st["next_layer_id"], st["next_layer_no"], amount_u, reason, obs)

def _all_true_open_m9_layers_for_coin(coin: str, ledger: GridLedger, sources: Optional[GridStateSources]) -> List[GridLayer]:
    all_src = _collect_sources_layers(coin, ledger, sources)
    merged = all_src["merged_layers"]
    result: List[GridLayer] = []
    for platform in ("EXT", "VAR"):
        for side in ("LONG", "SHORT"):
            filt = _filter_layers_for_leg(coin, platform, side, merged, include_close_pending_as_open=False)
            result.extend(filt["kept"])
    result.sort(key=lambda x: (x.layer_no, x.opened_ts, x.layer_id))
    return result

def _true_open_m9_layers_by_leg(coin: str, ledger: GridLedger, sources: Optional[GridStateSources]) -> Dict[str, List[GridLayer]]:
    all_src = _collect_sources_layers(coin, ledger, sources)
    merged = all_src["merged_layers"]
    by_leg: Dict[str, List[GridLayer]] = {}
    for platform in ("EXT", "VAR"):
        for side in ("LONG", "SHORT"):
            leg = _leg_key(platform, side)
            filt = _filter_layers_for_leg(coin, platform, side, merged, include_close_pending_as_open=False)
            kept = filt["kept"]
            if kept:
                by_leg[leg] = kept
    return by_leg

def _calc_tp_hit_for_layer(target: GridLayer, market: CoinMarket, config: GridConfig) -> Tuple[bool, float, float, bool]:
    entry_px = _m9_pick_positive_float(getattr(target, "entry_px", 0.0), getattr(getattr(target, "extra", {}) or {}, "get", lambda *_: None)("entry_px_truth"))
    mark_px = _m9_pick_positive_float(getattr(market, "mark_px", 0.0))
    tp_pct = float(getattr(target, "layer_tp_pct_locked", 0.0) or getattr(config, "tp_pct", 0.0) or 0.0)
    trend_tp_adjusted = False
    if entry_px <= 0 or mark_px <= 0:
        return False, 0.0, max(tp_pct, _m9_tp_min_floor(config)), False
    if config.trend.enabled_for_close and ((market.trend == "TREND_UP" and target.side == "LONG") or (market.trend == "TREND_DOWN" and target.side == "SHORT")):
        tp_pct *= config.trend.reduce_tp_gap_mult
        trend_tp_adjusted = True
    tp_pct = max(float(tp_pct or 0.0), _m9_tp_min_floor(config))
    if target.side == "LONG":
        need_px = entry_px * (1.0 + tp_pct)
        ok = mark_px >= need_px
    else:
        need_px = entry_px * (1.0 - tp_pct)
        ok = mark_px <= need_px
    return ok, need_px, tp_pct, trend_tp_adjusted

def decide_take_profit(
    coin: str,
    market: CoinMarket,
    positions: List[LegPosition],
    ledger: GridLedger,
    config: GridConfig,
    sources: Optional[GridStateSources] = None,
) -> CloseDecision:
    reason = DecisionReason()
    obs: Dict[str, Any] = {"coin": coin}
    all_open = _all_true_open_m9_layers_for_coin(coin, ledger, sources)
    obs["all_true_open_layer_ids"] = [x.layer_id for x in all_open]
    obs["all_true_open_layer_nos"] = [x.layer_no for x in all_open]
    obs["all_true_open_owner_chains"] = [str(getattr(x, "owner_chain", "") or _canonical_owner_chain(getattr(x, "source_module", ""), getattr(x, "owner_chain", ""))) for x in all_open]

    if not all_open:
        reason.consider("NO_GRID_LAYER", ReasonPriority.NO_REQUEST, "没有可平的网格层")
        return CloseDecision(False, coin, None, None, reason, obs)

    by_leg = _true_open_m9_layers_by_leg(coin, ledger, sources)
    leg_audits: Dict[str, Any] = {}
    eligible_targets: List[Tuple[int, float, str, GridLayer, float, bool]] = []
    any_continuous_leg = False
    highest_continuous_target: Optional[Tuple[str, GridLayer, float, float, bool]] = None

    for request_leg, layers in by_leg.items():
        continuity = _analyze_continuity(layers)
        target = layers[-1]
        entry_px_valid = bool(_m9_pick_positive_float(getattr(target, "entry_px", 0.0), dict(getattr(target, "extra", {}) or {}).get("entry_px_truth")) > 0.0)
        mark_px_valid = bool(_m9_pick_positive_float(getattr(market, "mark_px", 0.0)) > 0.0)
        tp_ok, need_px, tp_pct_used, trend_tp_adjusted = _calc_tp_hit_for_layer(target, market, config)
        leg_audits[request_leg] = {
            "layer_ids": [x.layer_id for x in layers],
            "layer_nos": [x.layer_no for x in layers],
            "continuity": continuity,
            "target_layer_id": target.layer_id,
            "target_layer_no": target.layer_no,
            "entry_px": target.entry_px,
            "entry_px_valid": entry_px_valid,
            "entry_px_source": str(dict(getattr(target, "extra", {}) or {}).get("entry_px_source") or ""),
            "cur_px": market.mark_px,
            "mark_px_valid": mark_px_valid,
            "need_px": need_px,
            "tp_pct_used": tp_pct_used,
            "trend_tp_adjusted": trend_tp_adjusted,
            "tp_hit": tp_ok,
            "reject_reason": ("TP_ENTRY_PX_INVALID" if not entry_px_valid else ("TP_MARK_PX_INVALID" if not mark_px_valid else "")),
        }
        if not continuity["continuous"]:
            continue
        if not entry_px_valid or not mark_px_valid:
            continue
        any_continuous_leg = True
        if highest_continuous_target is None or (target.layer_no, target.opened_ts, target.layer_id) > (highest_continuous_target[1].layer_no, highest_continuous_target[1].opened_ts, highest_continuous_target[1].layer_id):
            highest_continuous_target = (request_leg, target, need_px, tp_pct_used, trend_tp_adjusted)
        if tp_ok:
            eligible_targets.append((target.layer_no, target.opened_ts, request_leg, target, need_px, trend_tp_adjusted))

    obs["leg_audits"] = leg_audits
    obs["eligible_legs"] = sorted(list(by_leg.keys()))

    if not any_continuous_leg:
        invalid_entry_legs = {leg: audit for leg, audit in leg_audits.items() if audit.get("continuity", {}).get("continuous") and not audit.get("entry_px_valid")}
        invalid_mark_legs = {leg: audit for leg, audit in leg_audits.items() if audit.get("continuity", {}).get("continuous") and not audit.get("mark_px_valid")}
        if invalid_entry_legs:
            obs["invalid_entry_legs"] = {leg: {"target_layer_id": audit.get("target_layer_id"), "entry_px": audit.get("entry_px"), "entry_px_source": audit.get("entry_px_source")} for leg, audit in invalid_entry_legs.items()}
            reason.consider("TP_ENTRY_PX_INVALID", ReasonPriority.SYSTEM_ERROR, "连续合法腿存在，但目标层开仓价无效，禁止误平")
            return CloseDecision(False, coin, None, None, reason, obs)
        if invalid_mark_legs:
            obs["invalid_mark_legs"] = list(invalid_mark_legs.keys())
            reason.consider("TP_MARK_PX_INVALID", ReasonPriority.SYSTEM_ERROR, "连续合法腿存在，但现价无效，禁止误平")
            return CloseDecision(False, coin, None, None, reason, obs)
        missing_by_leg = {leg: audit["continuity"]["missing"] for leg, audit in leg_audits.items() if not audit["continuity"]["continuous"]}
        reason.consider("LAYER_ID_DISCONTINUITY", ReasonPriority.SYSTEM_ERROR, f"所有候选腿都断层: {missing_by_leg}")
        obs["discontinuous_legs"] = missing_by_leg
        return CloseDecision(False, coin, None, None, reason, obs)

    if not eligible_targets:
        request_leg = highest_continuous_target[0] if highest_continuous_target else None
        target = highest_continuous_target[1] if highest_continuous_target else None
        if target is not None:
            audit = leg_audits[request_leg]
            obs.update({
                "request_leg": request_leg,
                "target_layer_id": target.layer_id,
                "target_layer_no": target.layer_no,
                "entry_px": target.entry_px,
                "entry_px_valid": audit.get("entry_px_valid"),
                "entry_px_source": audit.get("entry_px_source"),
                "cur_px": market.mark_px,
                "mark_px_valid": audit.get("mark_px_valid"),
                "need_px": audit["need_px"],
                "tp_pct_used": audit["tp_pct_used"],
                "trend_tp_adjusted": audit["trend_tp_adjusted"],
            })
            reject_reason = str(audit.get("reject_reason") or "").strip()
            if reject_reason:
                reason.consider(reject_reason, ReasonPriority.SYSTEM_ERROR, "目标层开仓价/现价无效，禁止误平")
                return CloseDecision(False, coin, request_leg, None, reason, obs)
        reason.consider("TP_GAP_NOT_REACHED", ReasonPriority.GAP_BLOCK, "连续合法腿存在，但平仓点未到")
        return CloseDecision(False, coin, request_leg, None, reason, obs)

    eligible_targets.sort(key=lambda x: (x[0], x[1], x[3].layer_id), reverse=True)
    _, _, request_leg, target, need_px, trend_tp_adjusted = eligible_targets[0]
    target_owner = _canonical_owner_chain(getattr(target, "source_module", ""), getattr(target, "owner_chain", ""))
    if str(getattr(target, "source_module", "") or "").upper().strip() != "M9" or target_owner != "M9_SINGLE_CHAIN":
        reason.consider("non_m9_layer_block", ReasonPriority.OWNERSHIP_BLOCK, "仅允许平 M9_SINGLE_CHAIN 自有层")
        obs["target_owner_chain"] = target_owner
        return CloseDecision(False, coin, request_leg, None, reason, obs)
    if target.layer_no < 2:
        reason.consider("l1_base_layer_block", ReasonPriority.OWNERSHIP_BLOCK, "L1 基础层不可平")
        return CloseDecision(False, coin, request_leg, None, reason, obs)

    obs.update({
        "request_leg": request_leg,
        "target_layer_id": target.layer_id,
        "target_layer_no": target.layer_no,
        "entry_px": target.entry_px,
        "cur_px": market.mark_px,
        "need_px": need_px,
        "tp_pct_used": leg_audits[request_leg]["tp_pct_used"],
        "trend_tp_adjusted": trend_tp_adjusted,
    })

    return CloseDecision(True, coin, request_leg, target.layer_id, reason, obs)

def execute_open(
    decision: OpenDecision,
    ledger: GridLedger,
    market: CoinMarket,
    risk: GridRiskConfig,
    hourly_state: HourlyRiskState,
    fill_ts: Optional[float] = None,
) -> Optional[GridLayer]:
    if not decision.ok or not decision.layer_id or not decision.layer_no or not decision.request_leg:
        return None
    final_fill_ts = fill_ts if fill_ts is not None else time.time()
    platform, side = decision.request_leg.split("|")
    layer = GridLayer(
        layer_id=decision.layer_id,
        layer_no=decision.layer_no,
        coin=decision.coin,
        platform=platform,
        side=side,
        source_module="M9",
        owner_chain=str((decision.observations or {}).get("owner_chain") or "M9_SINGLE_CHAIN"),
        grid_id_canonical=str((decision.observations or {}).get("grid_id_canonical") or (str(decision.layer_id).rsplit("_L", 1)[0] if decision.layer_id and "_L" in str(decision.layer_id) else "")),
        layer_tp_pct_locked=float((decision.observations or {}).get("layer_tp_pct_locked") or 0.0),
        layer_tp_policy_version=str((decision.observations or {}).get("layer_tp_policy_version") or "m9_tp_v1"),
        status="OPEN",
        entry_px=market.mark_px,
        open_u=decision.amount_u,
        note="GRID_OPEN",
        opened_ts=final_fill_ts,
        extra={"cold_start": decision.cold_start},
    )
    state_patch = apply_open_fill_to_risk_state(risk, hourly_state, decision.amount_u, final_fill_ts, decision.request_leg)
    layer.extra.update({"risk_state_patch": state_patch})
    ledger.add_layer(layer)
    return layer

def execute_close(
    decision: CloseDecision,
    ledger: GridLedger,
    risk: GridRiskConfig,
    fill_ts: Optional[float] = None,
) -> bool:
    if not decision.ok or not decision.target_layer_id:
        return False
    target = ledger.get_layer(decision.target_layer_id)
    if target is None:
        return False
    try:
        owner_chain = _canonical_owner_chain(getattr(target, "source_module", ""), getattr(target, "owner_chain", ""))
    except Exception:
        owner_chain = ""
    if str(getattr(target, "source_module", "") or "").upper().strip() != "M9" or owner_chain != "M9_SINGLE_CHAIN":
        return False
    final_fill_ts = fill_ts if fill_ts is not None else time.time()
    state_patch = apply_close_fill_to_risk_state(risk, target.open_u, final_fill_ts)
    target.extra.update({"close_risk_state_patch": state_patch, "closed_ts": final_fill_ts})
    return ledger.mark_closed(decision.target_layer_id)

