    ledger = GridLedger()
    ledger.add_layer(GridLayer(layer_id="ETH_EXT_SHORT_M1_L1", layer_no=1, coin="ETH", platform="EXT", side="SHORT", source_module="M1", entry_px=2000, open_u=150))
    ledger.add_layer(GridLayer(layer_id="ETH_EXT_SHORT_M9_L2", layer_no=2, coin="ETH", platform="EXT", side="SHORT", source_module="M9", entry_px=1980, open_u=90, opened_ts=1))
    positions = [
        LegPosition("ETH", "EXT", "SHORT", 240, 1990),
        LegPosition("ETH", "VAR", "LONG", 210, 1995),
    ]
    candles = [
        Candle(1, 1998, 2005, 1989, 1996),
        Candle(2, 1996, 1999, 1982, 1987),
        Candle(3, 1987, 1992, 1972, 1978),
    ]
    market = CoinMarket(coin="ETH", mark_px=1995, rsi=42, adx=31, trend="TREND_DOWN", candles=candles)
    cfg = _default_cfg()
    risk = GridRiskConfig(hardcap_u=1000, used_u=280, hourly_add_limit=2, paused=False)
    hourly = HourlyRiskState(recent_add_count_1h=0, last_add_ts=0)
    sources = GridStateSources(book_layers=[], heartbeat_layers=[])

    open_dec = decide_open("ETH", market, positions, ledger, cfg, risk, hourly, sources=sources)
    print("OPEN:", json.dumps({"ok": open_dec.ok, "summary": summarize_open_decision(open_dec), "reason": asdict(open_dec.reason), "obs": open_dec.observations}, ensure_ascii=False, indent=2, default=str))
    if open_dec.ok:
        layer = execute_open(open_dec, ledger, market, risk, hourly)
        print("EXEC_OPEN:", asdict(layer) if layer else None)

    close_dec = decide_take_profit("ETH", market, positions, ledger, cfg, sources=sources)
    print("CLOSE:", json.dumps({"ok": close_dec.ok, "reason": asdict(close_dec.reason), "obs": close_dec.observations}, ensure_ascii=False, indent=2, default=str))

