def _m9_live_sync_selfcheck() -> dict:
    rep = {'ok': True, 'created': False, 'refreshed': False, 'shell_kept': False, 'no_fake_layer': False, 'flat_cleanup': False}
    _old_book = globals().get('GRID_BOOK')
    try:
        globals()['GRID_BOOK'] = GridBook(None)
        r1 = _m9_sync_live_leg_into_book('HYPE', 'EXT', 'LONG', notional_u=120.0, entry_px=40.0, mark_px=40.2, allow_without_history=True, reason='selfcheck_create', src_mod='SELFTEST', src_act='m9_live_sync')
        rep['created'] = bool((r1 or {}).get('created')) and bool((r1 or {}).get('used'))
        gid = 'HYPE_EXT_LONG_M9'
        g1 = (((getattr(GRID_BOOK, 'data', {}) or {}).get('grids') or {}).get(gid) or {})
        rep['shell_kept'] = bool(isinstance(g1, dict) and isinstance(g1.get('layers'), list) and len(g1.get('layers') or []) == 0 and abs(float(g1.get('last_live_sync_notional_u') or 0.0) - 120.0) < 1e-9)
        r2 = _m9_sync_live_leg_into_book('HYPE', 'EXT', 'LONG', notional_u=160.0, entry_px=40.5, mark_px=40.7, allow_without_history=True, reason='selfcheck_refresh', src_mod='SELFTEST', src_act='m9_live_sync')
        g2 = (((getattr(GRID_BOOK, 'data', {}) or {}).get('grids') or {}).get(gid) or {})
        rep['refreshed'] = bool((r2 or {}).get('refreshed')) and bool((r2 or {}).get('used')) and abs(float(g2.get('last_live_sync_notional_u') or 0.0) - 160.0) < 1e-9
        src_book = _gpt_m9_ledger_from_grid_book('HYPE', include_pending=False)
        rep['no_fake_layer'] = (len(list(src_book.all_layers('HYPE') or [])) == 0)
        _drop = _m9_drop_flat_live_shell('HYPE', 'EXT', 'LONG', reason='selfcheck_flat_cleanup')
        rep['flat_cleanup'] = bool((_drop or {}).get('deleted')) and (gid not in (((getattr(GRID_BOOK, 'data', {}) or {}).get('grids') or {})) )
        rep['ok'] = bool(rep['created'] and rep['refreshed'] and rep['shell_kept'] and rep['no_fake_layer'] and rep['flat_cleanup'])
    except Exception as _e:
        rep['ok'] = False
        rep['error'] = repr(_e)
    finally:
        globals()['GRID_BOOK'] = _old_book
    try:
        root = globals().setdefault('SELFTEST_REPORT', {})
        root['m9_live_sync_selfcheck'] = dict(rep)
    except Exception:
        pass
    return rep

