def run_m9_closure_selfcheck() -> dict:
    import ast
    fp = __file__
    src = open(fp, 'r', encoding='utf-8').read()
    tree = ast.parse(src)
    names = [n.name for n in tree.body if isinstance(n, ast.FunctionDef)]
    res = {
        'ok': True,
        'compile_ok': True,
        'single_grid_ledger_restore_once': names.count('_grid_ledger_restore_once') == 1,
        'single_grid_ledger_persist': names.count('_grid_ledger_persist') == 1,
        'no_m9_cooldown_func': ('_load_m9_cooldown' not in names and '_save_m9_cooldown' not in names and '_m9_cooldown_path' not in names),
        'gpt_m9_cfg_no_cooldown_keys': False,
        'capblock_retired': False,
        'runtime_diag_not_persisted': False,
        'recent_reduce_fail_not_gating': False,
        'grid_risk_cfg_compat_retired_only': False,
        'final_outputs_use_state_commit_record': False,
        'timeout_default_20': False,
        'b1_seed_priority_present': False,
        'b1_fallback_rebuild_present': False,
        'grid_close_suspect_present': False,
        'grid_sync_strong_evidence_present': False,
        'm9_live_sync_selfcheck_ok': False,
        'm9_recovering_open_guard_ok': False,
        'm9_postcheck_fail_legacy_deleteding_path_ok': False,
        'm9_live_sync_hook_present': False,
        'now_ts_shadow_fixed': False,
        'ext_submit_ready_present': False,
    }
    _, risk_cfg = _gpt_m9_cfg({})
    res['gpt_m9_cfg_no_cooldown_keys'] = ('cooldown_sec' not in risk_cfg and 'per_leg_cd' not in risk_cfg)
    src_text = src
    res['timeout_default_20'] = ('EXECUTOR_WORKER_TIMEOUT_SEC = int(float(os.getenv("EXECUTOR_WORKER_TIMEOUT_SEC", "20") or 20))' in src_text or 'EXECUTOR_WORKER_TIMEOUT_SEC = 20' in src_text)
    res['b1_seed_priority_present'] = ('def _b1_seed_priority_detail' in src_text and 'flat_no_leg_waiting_b1_seed' in src_text and 'b1_seed_coins' in src_text)
    try:
        _live_sync_rep = _m9_live_sync_selfcheck()
        res['m9_live_sync_selfcheck_ok'] = bool((_live_sync_rep or {}).get('ok'))
    except Exception:
        res['m9_live_sync_selfcheck_ok'] = False
    try:
        _selftest_m9_recovering_open_guard()
        res['m9_recovering_open_guard_ok'] = True
    except Exception:
        res['m9_recovering_open_guard_ok'] = False
    try:
        _selftest_state_commit_postcheck_fail_legacy_deleteding_path()
        res['m9_postcheck_fail_legacy_deleteding_path_ok'] = True
    except Exception:
        res['m9_postcheck_fail_legacy_deleteding_path_ok'] = False
    res['m9_live_sync_hook_present'] = ('def _m9_sync_live_leg_into_book' in src_text and 'def _m9_sync_coin_live_positions_into_book' in src_text and "rep['m9_live_sync'] = _m9_sync_coin_live_positions_into_book(" in src_text)
    res['now_ts_shadow_fixed'] = ('def _ind_fetch_adx_rsi_public(coin: str, *, now_ts_val:' in src_text and '_ind_fetch_adx_rsi_public(c, now_ts_val=nowv)' in src_text)
    res['ext_submit_ready_present'] = ('def _wait_ext_submit_button_ready' in src_text and 'EXT_SUBMIT_READY' in src_text and 'ready_wait_failed' in src_text)
    res['b1_fallback_rebuild_present'] = ('def _clone_b1_fallback_req' in src_text and 'fallback_to_platform' in src_text and 'B1_FALLBACK_A1_PASS' in src_text)
    res['grid_close_suspect_present'] = ('grid_close_suspect' in src_text and 'notional_delta_exact_confirmed' in src_text and 'GRID_NEW_LAYER_CLOSE_PROTECT_SEC' in src_text)
