if "_is_m10_group_action" not in globals():
    def _is_m10_group_action(x):
        try:
            d = dict(x or {}) if isinstance(x, dict) else {}
        except Exception:
            d = {}
        mod = str(d.get('module') or d.get('mod') or '').upper()
        act = str(d.get('action') or d.get('group_action') or d.get('tp_mode') or '').lower()
        return (mod == 'M10') or ('3step' in act) or ('group' in act and 'm10' in act)

