def _selftest_m9_trend_alpha_freeze_contract() -> dict:
    out = {'ok': False, 'checks': {}}
    try:
        snap = {
            'indicators': {'BTC': {'rsi': 62.0, 'adx': 20.0}},
            'positions': {
                'EXT': {'BTC': {'side': 'LONG', 'notional_u': 1200.0, 'upnl_u': 38.0}},
                'VAR': {'BTC': {'side': 'SHORT', 'notional_u': 900.0, 'upnl_u': -22.0}},
            }
        }
        _TREND_UPNL_HISTORY.clear()
        for _u in (10.0, 22.0, 38.0):
            snap['positions']['EXT']['BTC']['upnl_u'] = _u
            _m9_resolve_trend_state(snap, 'BTC', 'LONG', rsi=62.0)
        pol_same = _m9_trend_open_policy(snap, 'BTC', 'LONG', 62.0, 20.0) or {}
        pol_opp = _m9_trend_open_policy(snap, 'BTC', 'SHORT', 62.0, 20.0) or {}
        view_ext = _m9_payload_trend_view(snap, 'BTC', 'EXT', 62.0, 20.0) or {}
        view_var = _m9_payload_trend_view(snap, 'BTC', 'VAR', 62.0, 20.0) or {}
        mode_same, det_same = _m9_pick_grid_mode('LONG', 62.0, 20.0, 'BTC_EXT_LONG_M9', snapshot=snap, coin='BTC')
        mode_opp, det_opp = _m9_pick_grid_mode('SHORT', 62.0, 20.0, 'BTC_VAR_SHORT_M9', snapshot=snap, coin='BTC')
        out['checks']['same_side_alpha'] = str(pol_same.get('trend_state') or '') == 'TREND_ALPHA' and int(pol_same.get('trend_alpha') or 0) == 1
        out['checks']['same_side_expand_ok'] = str(pol_same.get('reason') or '') == 'trend_alpha_allow_same_side_expand' and int(pol_same.get('block_new_grid') or 0) == 0
        out['checks']['opp_side_frozen'] = str(pol_opp.get('reason') or '') == 'opposite_side_frozen_in_trend_alpha' and int(pol_opp.get('block_new_grid') or 0) == 1 and int(pol_opp.get('freeze_loss_leg_new_grid') or 0) == 1
        out['checks']['payload_ext_not_frozen'] = int(view_ext.get('freeze_loss_leg_new_grid') or 0) == 0
        out['checks']['payload_var_frozen'] = int(view_var.get('freeze_loss_leg_new_grid') or 0) == 1 and int(view_var.get('trend_policy_block_new_grid') or 0) == 1
        out['checks']['pick_same_trend'] = mode_same == 'TREND'
        out['checks']['pick_opp_blocked'] = mode_opp == 'NORMAL' and int(det_opp.get('trend_policy_block_new_grid') or 0) == 1 and str(det_opp.get('reason') or '') == 'opposite_side_frozen_in_trend_alpha'
        out['ok'] = all(bool(v) for v in out['checks'].values())
        if not out['ok']:
            out['reason'] = 'm9_trend_alpha_freeze_contract_broken'
        return out
    except Exception as _e:
        out['reason'] = f'exc:{_e!r}'
        return out

