# __main__ 主入口已物理后移到文件末尾，确保启动自检发生在所有晚定义常量/函数加载完成之后。

M9_GRID_GAP_MIN_PCT_UNIFIED = 0.01
M9_GRID_VOL_DIVISOR = 10.0
M9_GRID_OPEN_MIN_U = 100.0

def _legacy_deleted_submit(*args, **kwargs):
    raise RuntimeError('LEGACY_FIX_SOURCE_DELETED_HARD')

def _single_leg_live_side(snapshot: dict | None, coin: str) -> str:
    try:
        c = str(coin or '').upper().strip()
    except Exception:
        c = ''
    if not c:
        return ''
    try:
        state = _m9_coin_side_state(snapshot, c)
        long_n = float(((state or {}).get('LONG') or {}).get('notional_u') or 0.0)
        short_n = float(((state or {}).get('SHORT') or {}).get('notional_u') or 0.0)
    except Exception:
        return ''
    has_long = long_n > 1e-9
    has_short = short_n > 1e-9
    if has_long and not has_short:
        return 'LONG'
    if has_short and not has_long:
        return 'SHORT'
    return ''


def _trend_effective_side(snapshot: dict | None, coin: str, rsi: float | None = None, adx: float | None = None) -> str:
    single_side = _single_leg_live_side(snapshot, coin)
    if single_side in ('LONG', 'SHORT'):
        return single_side
    try:
        return str(_m9_trend_side_for_coin(coin, rsi, adx) or '')
    except Exception:
        return ''


def _m9_build_positions_snapshot_for_coin(coin: str, positions: list | None, mark_px: float | None = None) -> dict:
    out = {'positions': {'EXT': {}, 'VAR': {}}}
    try:
        c = str(coin or '').upper().strip()
        px = float(mark_px or 0.0)
        if not c:
            return out
        for pos in list(positions or []):
            try:
                if str(getattr(pos, 'coin', '') or '').upper().strip() != c:
                    continue
                plat = str(getattr(pos, 'platform', '') or '').upper().strip()
                side = str(getattr(pos, 'side', '') or '').upper().strip()
                notional_u = abs(float(getattr(pos, 'notional_u', 0.0) or 0.0))
                entry_px = float(getattr(pos, 'entry_px', 0.0) or 0.0)
                if plat not in ('EXT', 'VAR') or side not in ('LONG', 'SHORT') or notional_u <= 1e-9:
                    continue
                upnl_u = 0.0
                if px > 0.0 and entry_px > 0.0:
                    if side == 'LONG':
                        upnl_u = float(notional_u) * (float(px) - float(entry_px)) / float(entry_px)
                    else:
                        upnl_u = -float(notional_u) * (float(px) - float(entry_px)) / float(entry_px)
                out['positions'].setdefault(plat, {})[c] = {
                    'side': side,
                    'notional_u': float(notional_u),
                    'entry_px': float(entry_px),
                    'mark_px': float(px) if px > 0.0 else 0.0,
                    'upnl_u': float(upnl_u),
                    'has_position': bool(side in ('LONG', 'SHORT') and notional_u > 1e-9),
                }
            except Exception:
                continue
        return out
    except Exception:
        return out


def _trend_state_inline(snapshot: dict | None, coin: str, trend_side: str, rsi: float | None = None) -> dict:
    out = {
        'trend_state': 'NORMAL','trend_alpha':0,'opp_side_frozen':0,'runner_protect':0,
        'reason':'trend_neutral','same_notional_u':0.0,'opp_notional_u':0.0,'same_upnl_u':0.0,'opp_upnl_u':0.0,
        'cover_ratio': None,'profit_history':[],'profit_expansion_ok':False,'profit_contraction_ok':False,
        'trend_strength_bucket':'WEAK','trend_score':0.0,'trend_rank':999,'trend_slots':1,
    }
    try:
        c = str(coin or '').upper().strip()
        ts = str(trend_side or '').upper().strip()
        single_side = _single_leg_live_side(snapshot, c)
        if single_side in ('LONG', 'SHORT'):
            ts = single_side
        if ts not in ('LONG','SHORT'):
            out['reason'] = 'dual_leg_exit_main_trend'
            return out
        state = _m9_coin_side_state(snapshot, c)
        same = dict((state or {}).get(ts) or {})
        opp = dict((state or {}).get('SHORT' if ts == 'LONG' else 'LONG') or {})
        same_notional = float(same.get('notional_u') or 0.0)
        opp_notional = float(opp.get('notional_u') or 0.0)
        same_upnl = float(same.get('upnl_u') or 0.0)
        opp_upnl = float(opp.get('upnl_u') or 0.0)
        out.update({'same_notional_u':same_notional,'opp_notional_u':opp_notional,'same_upnl_u':same_upnl,'opp_upnl_u':opp_upnl})
        out['cover_ratio'] = float(same_notional / max(opp_notional,1e-12)) if opp_notional > 1e-9 else (999.0 if same_notional > 1e-9 else 0.0)
        hist = _trend_upnl_history_push(c, same_upnl)
        streak = _trend_profit_streak_flags(hist)
        out['profit_history'] = list(hist)
        out['profit_expansion_ok'] = bool(streak.get('expansion_ok'))
        out['profit_contraction_ok'] = bool(streak.get('contraction_ok'))
        out['trend_strength_bucket'] = _trend_strength_bucket(rsi, same_upnl, same_notional, opp_upnl)
        if same_notional <= 1e-9:
            out['trend_state']='TREND_CANDIDATE'; out['reason']='trend_candidate_same_leg_missing'; return out
        if single_side in ('LONG', 'SHORT') and opp_notional <= 1e-9:
            out['trend_state']='TREND_ALPHA'; out['trend_alpha']=1; out['opp_side_frozen']=1; out['runner_protect']=1; out['reason']='single_leg_main_trend'; return out
        weak_rsi = False
        try:
            if rsi is not None:
                rv = float(rsi)
                weak_rsi = bool(rv <= float(globals().get('M9_TREND_RSI_LONG_EXIT',53.0))) if ts == 'LONG' else bool(rv >= float(globals().get('M9_TREND_RSI_SHORT_EXIT',47.0)))
        except Exception:
            weak_rsi = False
        min_same_upnl = _trend_alpha_min_same_upnl_u(c, same_notional)
        if weak_rsi and bool(streak.get('contraction_ok')):
            out['trend_state']='TREND_EXIT_ONLY'; out['opp_side_frozen']=1; out['runner_protect']=1; out['reason']='trend_exit_only_no_new_grid'; return out
        alpha_candidate = bool(same_upnl > min_same_upnl and (opp_notional <= 1e-9 or opp_upnl <= 0.0))
        if alpha_candidate:
            out['trend_state']='TREND_ALPHA'; out['trend_alpha']=1; out['opp_side_frozen']=1; out['runner_protect']=1; out['reason']='single_leg_main_trend' if single_side in ('LONG','SHORT') else 'trend_alpha_allow_same_side_expand'; return out
        out['reason'] = 'dual_leg_exit_main_trend'
        return out
    except Exception as _e:
        out['reason'] = f'trend_state_exc:{type(_e).__name__}'
        return out


def _m9_pick_grid_mode(side: str, rsi: float | None, adx: float | None, grid_id: str = '', snapshot: dict | None = None, coin: str = '') -> tuple[str, dict]:
    try: s = str(side or '').upper().strip()
    except Exception: s=''
    try: rv = float(rsi) if rsi is not None else None
    except Exception: rv=None
    try: av = float(adx) if adx is not None else None
    except Exception: av=None
    det={'grid_mode':'NORMAL','reason':'trend_neutral','trend_policy_allow':1,'trend_policy_block_new_grid':0,'trend_side':'','opened':0,'cap':0,'rsi':rv,'adx':av}
    try:
        if not bool(globals().get('M9_TREND_ENABLE',1)):
            det['reason']='trend_disabled'; return 'NORMAL', det
        trend_side = _trend_effective_side(snapshot, coin, rv, av)
        det['trend_side']=str(trend_side or '')
        st = _trend_state_inline(snapshot, coin, trend_side, rsi=rv) if trend_side in ('LONG','SHORT') else {}
        det['trend_state']=str((st or {}).get('trend_state') or 'NORMAL'); det['trend_alpha']=int(bool((st or {}).get('trend_alpha',0)))
        cap = int(_m9_trend_cap_by_rsi(s, rv)) if s in ('LONG','SHORT') else 0; det['cap']=cap
        opened = int(_m9_count_open_layers_by_mode(str(grid_id or ''), 'TREND')) if grid_id else 0; det['opened']=opened
        if s not in ('LONG','SHORT'):
            det['reason']='bad_side'; return 'NORMAL', det
        if av is not None and float(av)+1e-9 < float(globals().get('M9_TREND_ADX_MIN',0.0) or 0.0):
            det['reason']='adx_below_trend_min'; return 'NORMAL', det
        if str((st or {}).get('trend_state')) == 'TREND_EXIT_ONLY':
            det['trend_policy_block_new_grid']=1; det['reason']='trend_exit_only_no_new_grid'; return 'NORMAL', det
        if trend_side != s:
            det['reason']='non_main_trend_use_dual_leg_bias'; return 'NORMAL', det
        if opened >= max(0,cap):
            det['reason']='trend_layer_cap_reached'; return 'NORMAL', det
        if bool((st or {}).get('trend_alpha')):
            det['grid_mode']='TREND'; det['reason']='single_leg_main_trend'; return 'TREND', det
        det['reason']=str((st or {}).get('reason') or 'dual_leg_exit_main_trend'); return 'NORMAL', det
    except Exception as e:
        det['reason']=f'trend_pick_exc:{type(e).__name__}'; return 'NORMAL', det


FIRST_RUN_BOOTSTRAP_VERSION = "20260413_embedded_first_bootstrap_v2_single_chain"
FIRST_RUN_BOOTSTRAP_PORT = 9222
