def _trend_alpha_slot_limit(side: str) -> int:
    s = str(side or '').upper().strip()
    long_slots = int(globals().get('TREND_ALPHA_MAIN_SLOTS_LONG', 2) or 2)
    long_max = int(globals().get('TREND_ALPHA_MAIN_SLOTS_LONG_MAX', 3) or 3)
    short_slots = int(globals().get('TREND_ALPHA_MAIN_SLOTS_SHORT', 2) or 2)
    short_max = int(globals().get('TREND_ALPHA_MAIN_SLOTS_SHORT_MAX', 3) or 3)
    if s == 'LONG':
        return max(1, min(long_slots, long_max))
    if s == 'SHORT':
        return max(1, min(short_slots, short_max))
    return 1

def _m9_trend_open_policy(snapshot: dict | None, coin: str, side: str, rsi: float | None, adx: float | None) -> dict:
    out = {
        'allow': True,
        'block_new_grid': 0,
        'reason': 'trend_neutral',
        'trend_reason': 'trend_neutral',
        'trend_side': '',
        'same_notional_u': 0.0,
        'opp_notional_u': 0.0,
        'same_upnl_u': 0.0,
        'opp_upnl_u': 0.0,
        'cover_ratio': None,
        'trend_layers_open': 0,
        'trend_layers_cap': 0,
        'freeze_loss_leg_new_grid': 0,
        'trend_policy_block_new_grid': 0,
        'trend_state': 'NORMAL',
        'trend_alpha': 0,
        'opp_side_frozen': 0,
        'runner_protect': 0,
    }
    def _ret() -> dict:
        out['trend_reason'] = str(out.get('reason') or 'trend_neutral')
        out['trend_policy_block_new_grid'] = int(bool(out.get('block_new_grid', 0)))
        out['trend_policy_allow'] = int(bool(out.get('allow', True)))
        try:
            _trend_field_selfcheck(str(coin or '').upper().strip(), '', out)
        except Exception as _e:
            _record_swallowed_exception('trend_alpha_final_recovery_selfcheck', _e)
        return out
    try:
        s = str(side or '').upper().strip()
        trend_side = _m9_trend_side_for_coin(coin, rsi, adx)
        out['trend_side'] = str(trend_side or '')
        if trend_side not in ('LONG', 'SHORT'):
            out['reason'] = 'trend_neutral'
            return _ret()
        st = _m9_resolve_trend_state(snapshot, coin, trend_side, rsi=rsi) or {}
        out.update({
            'trend_state': str(st.get('trend_state') or 'TREND_CANDIDATE'),
            'trend_alpha': int(bool(st.get('trend_alpha', 0))),
            'opp_side_frozen': int(bool(st.get('opp_side_frozen', 0))),
            'runner_protect': int(bool(st.get('runner_protect', 0))),
            'same_notional_u': float(st.get('same_notional_u') or 0.0),
            'opp_notional_u': float(st.get('opp_notional_u') or 0.0),
            'same_upnl_u': float(st.get('same_upnl_u') or 0.0),
            'opp_upnl_u': float(st.get('opp_upnl_u') or 0.0),
            'cover_ratio': st.get('cover_ratio'),
        })
        if str(st.get('trend_state') or '') == 'TREND_EXIT_ONLY':
            out['allow'] = False
            out['block_new_grid'] = 1
            out['freeze_loss_leg_new_grid'] = 1
            out['reason'] = 'trend_exit_only_no_new_grid'
            return _ret()
        if s != trend_side and bool(out.get('trend_alpha')):
            out['allow'] = False
            out['block_new_grid'] = 1
            out['freeze_loss_leg_new_grid'] = 1
            out['reason'] = 'opposite_side_frozen_in_trend_alpha'
            return _ret()
        if s != trend_side:
            out['allow'] = True
            out['block_new_grid'] = 0
            out['reason'] = 'trend_side_not_match'
            return _ret()
        if bool(out.get('trend_alpha')):
            out['allow'] = True
            out['block_new_grid'] = 0
            out['freeze_loss_leg_new_grid'] = 0
            out['reason'] = 'trend_alpha_allow_same_side_expand'
            return _ret()
        cover_ratio = float(out.get('cover_ratio') or 0.0)
        opp_notional = float(out.get('opp_notional_u') or 0.0)
        if opp_notional > 1e-9 and cover_ratio >= float(globals().get('M9_TREND_COVER_RATIO_TARGET', 1.0) or 1.0) - 1e-12:
            out['reason'] = 'trend_cover_ratio_disabled'
        elif opp_notional > 1e-9 and cover_ratio >= float(globals().get('M9_TREND_COVER_RATIO_SOFT', 0.7) or 0.7) - 1e-12:
            out['reason'] = 'trend_cover_soft_zone_disabled'
        else:
            out['reason'] = str(st.get('reason') or 'trend_cover_expand')
        return _ret()
    except Exception as e:
        out['allow'] = True
        out['block_new_grid'] = 0
        out['reason'] = f'trend_policy_exc:{type(e).__name__}'
        return _ret()

def _m9_payload_trend_view(snapshot: dict | None, coin: str, platform: str, rsi: float | None, adx: float | None) -> dict:
    out = {
        'trend_side': '', 'trend_reason': 'trend_neutral', 'cover_ratio': None,
        'same_notional_u': 0.0, 'opp_notional_u': 0.0, 'same_upnl_u': 0.0, 'opp_upnl_u': 0.0,
        'long_notional_u': 0.0, 'short_notional_u': 0.0, 'long_upnl_u': 0.0, 'short_upnl_u': 0.0,
        'trend_grid_id': '', 'trend_layers_open': 0, 'trend_layers_cap': 0,
        'freeze_loss_leg_new_grid': 0, 'trend_policy_allow': 1, 'trend_policy_block_new_grid': 0,
        'trend_state': 'NORMAL', 'trend_alpha': 0, 'opp_side_frozen': 0, 'runner_protect': 0,
    }
    try:
        c = str(coin or '').upper().strip(); p = str(platform or '').upper().strip()
        if not c or p not in ('EXT', 'VAR'):
            return out
        trend_side = _m9_trend_side_for_coin(coin, rsi, adx)
        out['trend_side'] = str(trend_side or '')
        state = _m9_coin_side_state(snapshot, c)
        long_state = dict((state or {}).get('LONG') or {})
        short_state = dict((state or {}).get('SHORT') or {})
        out['long_notional_u'] = float(long_state.get('notional_u') or 0.0)
        out['short_notional_u'] = float(short_state.get('notional_u') or 0.0)
        out['long_upnl_u'] = float(long_state.get('upnl_u') or 0.0)
        out['short_upnl_u'] = float(short_state.get('upnl_u') or 0.0)
        if trend_side in ('LONG', 'SHORT'):
            pol = _m9_trend_open_policy(snapshot, c, trend_side, rsi, adx) or {}
            out['trend_reason'] = str(pol.get('reason') or out['trend_reason'])
            out['cover_ratio'] = float(pol.get('cover_ratio')) if pol.get('cover_ratio') is not None else None
            out['same_notional_u'] = float(pol.get('same_notional_u') or 0.0)
            out['opp_notional_u'] = float(pol.get('opp_notional_u') or 0.0)
            out['same_upnl_u'] = float(pol.get('same_upnl_u') or 0.0)
            out['opp_upnl_u'] = float(pol.get('opp_upnl_u') or 0.0)
            out['trend_policy_allow'] = int(bool(pol.get('allow', True)))
            out['trend_policy_block_new_grid'] = int(bool(pol.get('block_new_grid', 0)))
            out['trend_state'] = str(pol.get('trend_state') or 'TREND_CANDIDATE')
            out['trend_alpha'] = int(bool(pol.get('trend_alpha', 0)))
            out['opp_side_frozen'] = int(bool(pol.get('opp_side_frozen', 0)))
            out['runner_protect'] = int(bool(pol.get('runner_protect', 0)))
            side_for_plat = ''
            try:
                pos = _get_position(snapshot or {}, c, p) or {}
                side_for_plat = str((pos or {}).get('side') or '').upper().strip()
            except Exception:
                side_for_plat = ''
            if side_for_plat in ('LONG', 'SHORT'):
                pol_cur = _m9_trend_open_policy(snapshot, c, side_for_plat, rsi, adx) or {}
                out['freeze_loss_leg_new_grid'] = int(bool(pol_cur.get('freeze_loss_leg_new_grid', 0)))
                out['trend_policy_block_new_grid'] = int(bool(pol_cur.get('block_new_grid', out.get('trend_policy_block_new_grid', 0))))
                if bool(pol_cur.get('block_new_grid', 0)):
                    out['trend_reason'] = str(pol_cur.get('reason') or out['trend_reason'])
            gid = _m9_grid_id(c, p, trend_side)
            out['trend_grid_id'] = str(gid or '')
            if gid:
                out['trend_layers_open'] = int(_m9_count_open_layers_by_mode(str(gid), 'TREND'))
            try:
                out['trend_layers_cap'] = int(_m9_trend_cap_by_rsi(str(trend_side), float(rsi) if rsi is not None else None))
            except Exception:
                out['trend_layers_cap'] = 0
        _trend_field_selfcheck(c, p, out)
        return out
    except Exception as e:
        out['trend_reason'] = f'trend_view_exc:{type(e).__name__}'
        return out

def _trend_alpha_guard_for_b2_m10(snapshot: dict | None, coin: str) -> dict:
    out = {
        'active': False, 'coin': str(coin or '').upper().strip(), 'trend_state': 'NORMAL', 'trend_alpha': 0,
        'trend_side': '', 'runner_protect': 0, 'opp_side_frozen': 0, 'reason': 'trend_guard_inactive',
        'rsi': None, 'adx': None, 'same_notional_u': 0.0, 'opp_notional_u': 0.0, 'same_upnl_u': 0.0,
        'opp_upnl_u': 0.0, 'cover_ratio': None, 'early_b2_protect': 0,
    }
    try:
        c = str(coin or '').upper().strip()
        if not c:
            out['reason'] = 'trend_guard_bad_coin'
            return out
        adx, rsi = _a1_get_adx_rsi(snapshot or {}, c)
        out['rsi'] = rsi; out['adx'] = adx
        trend_side = _m9_trend_side_for_coin(c, rsi, adx)
        out['trend_side'] = str(trend_side or '')
        if trend_side not in ('LONG', 'SHORT'):
            out['reason'] = 'trend_guard_no_trend_side'
            return out
        st = _m9_resolve_trend_state(snapshot or {}, c, trend_side, rsi=rsi) or {}
        out.update({
            'trend_state': str(st.get('trend_state') or 'NORMAL'),
            'trend_alpha': int(bool(st.get('trend_alpha', 0))),
            'runner_protect': int(bool(st.get('runner_protect', 0))),
            'opp_side_frozen': int(bool(st.get('opp_side_frozen', 0))),
            'reason': str(st.get('reason') or 'trend_guard_resolved'),
            'same_notional_u': float(st.get('same_notional_u') or 0.0),
            'opp_notional_u': float(st.get('opp_notional_u') or 0.0),
            'same_upnl_u': float(st.get('same_upnl_u') or 0.0),
            'opp_upnl_u': float(st.get('opp_upnl_u') or 0.0),
            'cover_ratio': st.get('cover_ratio'),
            'm10_cap_pct': float(globals().get('M10_TREND_ALPHA_CAP_PCT', 0.15) or 0.15) if str(st.get('trend_state') or '') in ('TREND_ALPHA','TREND_EXIT_ONLY') else None,
        })
        out['active'] = bool(out.get('trend_alpha')) and str(out.get('trend_state') or '') == 'TREND_ALPHA'
        if (not bool(out.get('active'))) and str(out.get('trend_state') or '') == 'TREND_CANDIDATE':
            try:
                same_upnl = float(out.get('same_upnl_u') or 0.0)
                same_notional = float(out.get('same_notional_u') or 0.0)
                opp_upnl = float(out.get('opp_upnl_u') or 0.0)
                rv = float(rsi) if rsi is not None else None
            except Exception:
                same_upnl, same_notional, opp_upnl, rv = 0.0, 0.0, 0.0, None
            try:
                bucket = _trend_strength_bucket(rv, same_upnl, same_notional, opp_upnl)
            except Exception:
                bucket = 'WEAK'
            hist_flags = {}
            try:
                hist_flags = _trend_profit_streak_flags((_TREND_UPNL_HISTORY or {}).get(c) or []) or {}
            except Exception:
                hist_flags = {}
            protect_min_u = max(float(globals().get('B2_TREND_PROFIT_MIN_U', 1.0) or 1.0), max(3.0, float(same_notional) * 0.003))
            early_profit_ok = bool(hist_flags.get('early_profit_ok'))
            early_guard = bool(
                same_notional > 1e-9 and same_upnl >= protect_min_u and bucket in ('MEDIUM', 'STRONG') and early_profit_ok
            )
            if early_guard:
                out['early_b2_protect'] = 1
                out['active'] = True
                out['runner_protect'] = 1
                out['opp_side_frozen'] = 1
                out['m10_cap_pct'] = 0.0
                out['reason'] = 'trend_candidate_early_b2m10_protect'
        return out
    except Exception as _e:
        out['reason'] = f'trend_guard_exc:{type(_e).__name__}'
        return out

try:
    _A1_CHECK_BEFORE_EXECUTE_TREND_FINAL_RAW = globals().get('_A1_CHECK_BEFORE_EXECUTE_WRAP_STAGE2_RAW')
except Exception:
    _A1_CHECK_BEFORE_EXECUTE_TREND_FINAL_RAW = None

def _a1_check_before_execute(snapshot: dict, req: 'Request', coins: list[str] | None = None) -> tuple[bool, str, str, dict]:
    raw_fn = globals().get('_A1_CHECK_BEFORE_EXECUTE_TREND_FINAL_RAW')
    try:
        _mod_u = str(getattr(req, 'module', '') or '').upper().strip()
        _act_l = str(getattr(req, 'action_type', '') or '').lower().strip()
        _coin_u = str(getattr(req, 'coin', '') or '').upper().strip()
        if _coin_u and ((_mod_u == 'B2' and _act_l == 'close_pair') or (_mod_u == 'M10' and _act_l == 'koujing_a_3step')):
            _trend_guard = _trend_alpha_guard_for_b2_m10(snapshot, _coin_u) or {}
            if _mod_u == 'B2' and bool(_trend_guard.get('active')):
                return False, 'b2_blocked_by_trend_alpha', 'trend_alpha_runner_protected', {'trend_guard': _trend_guard, 'wrapper_stage': 'trend_final_guard'}
            if _mod_u == 'M10' and bool(_trend_guard.get('active')) and bool(_trend_guard.get('runner_protect')):
                return False, 'm10_runner_protected', 'trend_alpha_runner_protected', {'trend_guard': _trend_guard, 'trend_alpha_cap_pct': float(_trend_guard.get('m10_cap_pct') or globals().get('M10_TREND_ALPHA_CAP_PCT', 0.15) or 0.0), 'wrapper_stage': 'trend_final_guard'}
        if callable(raw_fn):
            ret = raw_fn(snapshot, req, coins)
            if isinstance(ret, tuple) and len(ret) == 4:
                ok, code, reason, detail = ret
                try:
                    detail_d = dict(detail or {}) if isinstance(detail, dict) else {'detail_repr': repr(detail)[:240]}
                except Exception:
                    detail_d = {'detail_repr': repr(detail)[:240]}
                return bool(ok), str(code or ''), str(reason or code or ''), detail_d
        return True, 'ok', 'allow_wrapped_default', {'wrapper_stage': 'trend_final_default_allow', 'coin': str(getattr(req, 'coin', '') or '').upper(), 'module': str(getattr(req, 'module', '') or '').upper(), 'action': str(getattr(req, 'action_type', '') or '').lower()}
    except Exception as _e:
        return False, 'a1_check_exc', f'a1_check_exc:{type(_e).__name__}', {'err': f'{type(_e).__name__}:{str(_e)[:240]}', 'wrapper_stage': 'trend_final_exc'}

def _trend_pos_side_from_snapshot(snapshot: dict | None, coin: str, platform: str) -> str:
    try:
        c = str(coin or '').upper().strip(); p = str(platform or '').upper().strip()
        if not isinstance(snapshot, dict) or not c or p not in ('EXT','VAR'):
            return ''
        pos_root = snapshot.get('positions', {}) if isinstance(snapshot.get('positions', {}), dict) else {}
        plat_mp = pos_root.get(p, {}) if isinstance(pos_root.get(p, {}), dict) else {}
        row = plat_mp.get(c, {}) if isinstance(plat_mp.get(c, {}), dict) else {}
        s = str((row or {}).get('side') or '').upper().strip()
        if s in ('LONG','SHORT'):
            return s
    except Exception:
        pass
    try:
        pos = _get_position(snapshot or {}, str(coin or '').upper().strip(), str(platform or '').upper().strip()) or {}
        s = str((pos or {}).get('side') or '').upper().strip()
        return s if s in ('LONG','SHORT') else ''
    except Exception:
        return ''

