        out['short_upnl_u'] = float(short_state.get('upnl_u') or 0.0)
        if trend_side in ('LONG', 'SHORT'):
            st = _m9_resolve_trend_state(snapshot, c, trend_side, rsi=rsi) or {}
            out['trend_state'] = str(st.get('trend_state') or 'TREND_CANDIDATE')
