            if side_for_plat in ('LONG','SHORT'):
                if str(out.get('trend_state') or '') == 'TREND_EXIT_ONLY':
                    out['freeze_loss_leg_new_grid'] = 1
                    out['trend_policy_block_new_grid'] = 1
                    out['trend_policy_allow'] = 0
                    out['trend_reason'] = 'trend_exit_only_no_new_grid'
