def _trend_alpha_min_same_upnl_u(coin: Any, same_notional_u: Any) -> float:
    """趋势主赚钱态最低盈利门槛。
    老币维持 3U / 0.3% 二选大；新币放宽到 0.3U / 0.3% 二选大，避免小仓新币永远进不了趋势态。"""
    try:
        coin_u = str(coin or '').upper().strip()
    except Exception:
        coin_u = ''
    try:
        same_notional = float(same_notional_u or 0.0)
    except Exception:
        same_notional = 0.0
    floor_u = 0.3 if (coin_u and _coin_pool_is_dynamic_new_coin(coin_u)) else 3.0
    return float(max(float(floor_u), max(0.0, float(same_notional)) * 0.003))


def _m9_resolve_trend_state(snapshot: dict | None, coin: str, trend_side: str, rsi: float | None = None) -> dict:
    return _trend_state_inline(snapshot, coin, trend_side, rsi=rsi)

def _m9_payload_trend_view(snapshot: dict | None, coin: str, platform: str, rsi: float | None, adx: float | None) -> dict:
    out = {'trend_side':'','trend_reason':'trend_neutral','cover_ratio':None,'same_notional_u':0.0,'opp_notional_u':0.0,'same_upnl_u':0.0,'opp_upnl_u':0.0,'long_notional_u':0.0,'short_notional_u':0.0,'long_upnl_u':0.0,'short_upnl_u':0.0,'trend_grid_id':'','trend_layers_open':0,'trend_layers_cap':0,'freeze_loss_leg_new_grid':0,'trend_policy_allow':1,'trend_policy_block_new_grid':0,'trend_state':'NORMAL','trend_alpha':0,'opp_side_frozen':0,'runner_protect':0}
    try:
        c = str(coin or '').upper().strip(); p = str(platform or '').upper().strip()
        if not c or p not in ('EXT','VAR'):
            return out
        trend_side = _trend_effective_side(snapshot, coin, rsi, adx)
        out['trend_side'] = str(trend_side or '')
        state = _m9_coin_side_state(snapshot, c)
        long_state = dict((state or {}).get('LONG') or {})
        short_state = dict((state or {}).get('SHORT') or {})
        out['long_notional_u']=float(long_state.get('notional_u') or 0.0); out['short_notional_u']=float(short_state.get('notional_u') or 0.0)
        out['long_upnl_u']=float(long_state.get('upnl_u') or 0.0); out['short_upnl_u']=float(short_state.get('upnl_u') or 0.0)
        if trend_side in ('LONG','SHORT'):
            st = _trend_state_inline(snapshot, c, trend_side, rsi=rsi)
            out['trend_state']=str(st.get('trend_state') or 'TREND_CANDIDATE'); out['trend_alpha']=int(bool(st.get('trend_alpha',0)))
            out['opp_side_frozen']=int(bool(st.get('opp_side_frozen',0))); out['runner_protect']=int(bool(st.get('runner_protect',0)))
            out['same_notional_u']=float(st.get('same_notional_u') or 0.0); out['opp_notional_u']=float(st.get('opp_notional_u') or 0.0)
            out['same_upnl_u']=float(st.get('same_upnl_u') or 0.0); out['opp_upnl_u']=float(st.get('opp_upnl_u') or 0.0)
            out['cover_ratio']=st.get('cover_ratio'); out['trend_reason']=str(st.get('reason') or out['trend_reason'])
            side_for_plat = _trend_pos_side_from_snapshot(snapshot, c, p)
            if str(out.get('trend_state')) == 'TREND_EXIT_ONLY':
                out['freeze_loss_leg_new_grid']=1; out['trend_policy_block_new_grid']=1; out['trend_policy_allow']=0; out['trend_reason']='trend_exit_only_no_new_grid'
            elif bool(out.get('trend_alpha')) and side_for_plat in ('LONG','SHORT') and side_for_plat != trend_side:
                out['freeze_loss_leg_new_grid']=1; out['trend_policy_block_new_grid']=1; out['trend_policy_allow']=0; out['trend_reason']='opposite_side_frozen_in_trend_alpha'
            gid=_m9_grid_id(c,p,trend_side); out['trend_grid_id']=str(gid or '')
            if gid: out['trend_layers_open']=int(_m9_count_open_layers_by_mode(str(gid),'TREND'))
            try: out['trend_layers_cap']=int(_m9_trend_cap_by_rsi(str(trend_side), float(rsi) if rsi is not None else None))
            except Exception: out['trend_layers_cap']=0
        _trend_field_selfcheck(c,p,out); return out
    except Exception as e:
        out['trend_reason']=f'trend_view_exc:{type(e).__name__}'; return out

def _trend_alpha_guard_for_b2_m10(snapshot: dict | None, coin: str) -> dict:
    out = {
        'active': False, 'coin': str(coin or '').upper().strip(), 'trend_state': 'NORMAL', 'trend_alpha': 0,
        'trend_side': '', 'runner_protect': 0, 'opp_side_frozen': 0, 'reason': 'trend_guard_inactive',
        'rsi': None, 'adx': None, 'same_notional_u': 0.0, 'opp_notional_u': 0.0, 'same_upnl_u': 0.0,
        'opp_upnl_u': 0.0, 'cover_ratio': None,
    }
    try:
        c = str(coin or '').upper().strip()
        if not c:
            out['reason'] = 'trend_guard_bad_coin'
            return out
        adx, rsi = _a1_get_adx_rsi(snapshot or {}, c)
        out['rsi'] = rsi; out['adx'] = adx
        trend_side = _trend_effective_side(snapshot or {}, c, rsi, adx)
        out['trend_side'] = str(trend_side or '')
        if trend_side not in ('LONG', 'SHORT'):
            out['reason'] = 'trend_guard_no_trend_side'
            return out
        st = _trend_state_inline(snapshot or {}, c, trend_side, rsi=rsi) or {}
        out.update({
            'trend_state': str(st.get('trend_state') or 'NORMAL'),
            'trend_alpha': int(bool(st.get('trend_alpha', 0))),
            'runner_protect': int(bool(st.get('runner_protect', 0))),
            'opp_side_frozen': int(bool(st.get('opp_side_frozen', 0))),
            'reason': str(st.get('reason') or 'trend_guard_resolved'),
            'same_notional_u': float(st.get('same_notional_u') or 0.0),
            'opp_notional_u': float(st.get('opp_notional_u') or 0.0),
            'same_upnl_u': float(st.get('same_upnl_u') or 0.0),
            'opp_upnl_u': float(st.get('opp_upnl_u') or 0.0),
            'cover_ratio': st.get('cover_ratio'),
            'm10_cap_pct': float(globals().get('M10_TREND_ALPHA_CAP_PCT', 0.15) or 0.15) if str(st.get('trend_state') or '') in ('TREND_ALPHA','TREND_EXIT_ONLY') else None,
        })
        out['active'] = bool(out.get('trend_alpha')) and str(out.get('trend_state') or '') == 'TREND_ALPHA'
        return out
    except Exception as _e:
        out['reason'] = f'trend_guard_exc:{type(_e).__name__}'
        return out

def _a1_check_before_execute_trend_hard_guard(snapshot: dict, req: 'Request', coins: list[str] | None = None) -> tuple[bool, str, str, dict]:
    _mod_u = str(getattr(req, 'module', '') or '').upper().strip(); _act_l = str(getattr(req, 'action_type', '') or '').lower().strip(); _coin_u = str(getattr(req, 'coin', '') or '').upper().strip()
    if _coin_u and ((_mod_u == 'B2' and _act_l == 'close_pair') or (_mod_u == 'M10' and _act_l == 'koujing_a_3step')):
        try:
            _guard = _trend_alpha_guard_for_b2_m10(snapshot or {}, _coin_u) or {}
            if _mod_u == 'B2' and bool(_guard.get('active')):
                return False, 'b2_blocked_by_trend_alpha', 'trend_alpha_runner_protected', {'trend_guard': _guard, 'wrapper_stage': 'trend_hard_guard_v3'}
            if _mod_u == 'M10' and bool(_guard.get('active')) and bool(_guard.get('runner_protect')):
                return False, 'm10_runner_protected', 'trend_alpha_runner_protected', {'trend_guard': _guard, 'trend_alpha_cap_pct': float(_guard.get('m10_cap_pct') or globals().get('M10_TREND_ALPHA_CAP_PCT',0.15) or 0.15), 'wrapper_stage': 'trend_hard_guard_v3'}
        except Exception as _e:
            return False, 'a1_check_exc', f'a1_check_exc:{type(_e).__name__}', {'err': f'{type(_e).__name__}:{str(_e)[:240]}', 'wrapper_stage': 'trend_hard_guard_v3_pre'}
    raw_fn = globals().get('_A1_CHECK_BEFORE_EXECUTE_WRAP_STAGE2_RAW')
    try:
        if callable(raw_fn):
            ret = raw_fn(snapshot, req, coins)
            if isinstance(ret, tuple) and len(ret) == 4:
                ok, code, reason, detail = ret
                detail_d = dict(detail or {}) if isinstance(detail, dict) else {'detail_repr': repr(detail)[:240]}
                return bool(ok), str(code or ''), str(reason or code or ''), detail_d
        return True, 'ok', 'allow_wrapped_default', {'wrapper_stage': 'trend_hard_default_allow', 'coin': _coin_u, 'module': _mod_u, 'action': _act_l}
    except Exception as _e:
        return False, 'a1_check_exc', f'a1_check_exc:{type(_e).__name__}', {'err': f'{type(_e).__name__}:{str(_e)[:240]}', 'wrapper_stage': 'trend_hard_exc'}

_a1_check_before_execute = _a1_check_before_execute_trend_hard_guard

_SELECTION_OBS_PREV_CACHE = globals().get('_SELECTION_OBS_PREV_CACHE', {'binance': {}, 'merged': {}, 'final': {}, 'ts': 0.0})

def _selection_obs_reason_text(row: dict) -> str:
    try:
        keys = ('final_reason','reason','selection_reason','reject_reason','block_reason','result_reason','queue_reason','detail_reason')
        parts = []
        for k in keys:
            v = str((row or {}).get(k) or '').strip()
            if v and v not in parts:
                parts.append(v)
        if parts:
            return ' | '.join(parts[:3])
    except Exception:
        pass
    return '-'

def _selection_obs_rank_delta(cur: int, prev_map: dict, coin: str) -> str:
    try:
        c = str(coin or '').upper().strip()
        curi = int(cur or 0)
        previ = int((prev_map or {}).get(c) or 0)
        if curi <= 0:
            return '-'
        if previ <= 0:
            return '新'
        d = previ - curi
        if d > 0:
            return f'↑{d}'
        if d < 0:
            return f'↓{abs(d)}'
        return '→0'
    except Exception:
        return '-'

def _selection_obs_detail_text(row: dict, *, prev_maps: dict | None = None) -> str:
    try:
        r = dict(row or {})
        coin = str(r.get('coin') or '-').upper()
        bin_rank = int(r.get('binance_rank_all') or 0)
        final_rank = int(r.get('final_rank') or 0)
        merged_ok = int(r.get('metric_ok') or 0) == 1 and str(r.get('in_ext') or '') == 'Y' and str(r.get('in_var') or '') == 'Y'
        score = float(r.get('score') or 0.0)
        prev_maps = prev_maps or {}
        lines = [f'币种: {coin}', '']
        lines.append(f'币安原始排名: {bin_rank if bin_rank>0 else "-"}')
        lines.append(f'币安原始排名变化: {_selection_obs_rank_delta(bin_rank, (prev_maps or {}).get("binance") or {}, coin)}')
        lines.append(f'综合分: {score:.4f}')
        lines.append(f'EXT 命中: {r.get("in_ext") or "?"}')
        lines.append(f'VAR 命中: {r.get("in_var") or "?"}')
        lines.append(f'交集通过: {"是" if merged_ok else "否"}')
        lines.append(f'交集后排名: {int(r.get("merged_rank") or 0) or "-"}')
        lines.append(f'交集后排名变化: {_selection_obs_rank_delta(int(r.get("merged_rank") or 0), (prev_maps or {}).get("merged") or {}, coin)}')
        lines.append(f'最终排名: {final_rank if final_rank>0 else "-"}')
        lines.append(f'最终排名变化: {_selection_obs_rank_delta(final_rank, (prev_maps or {}).get("final") or {}, coin)}')
        lines.append(f'结果: {r.get("result") or "-"}')
        lines.append(f'候补队列中: {"是" if int(r.get("in_waiting_queue") or 0)==1 else "否"}')
        lines.append(f'未入选/入选原因: {_selection_obs_reason_text(r)}')
        if str(r.get('selection_scope') or '').strip():
            lines.append(f'本轮 scope: {str(r.get("selection_scope") or "")}')
        return '\n'.join(lines)
    except Exception as _e:
        return f'选币详情渲染失败：{_e}'

def _selection_observe_compact(*, limit: int = 30) -> dict:
    out = {
        'rows': [], 'ts': float(time.time()), 'meta': {},
        'groups': {'binance': [], 'merged': [], 'final': [], 'calc': []},
        'group_counts': {'binance': 0, 'merged': 0, 'final': 0, 'calc': 0},
    }
    try:
        st = _coin_pool_state_load(force=False)
        diag = dict((st or {}).get('last_refresh_diag') or {}) if isinstance(st, dict) else {}
        raw_rows = []
        for src_key in ('selection_detail_rows', 'last_selection_detail_rows'):
            for row in list(diag.get(src_key) or []):
                if isinstance(row, dict):
                    raw_rows.append(dict(row))
        if not raw_rows:
            for row in list((st or {}).get('ranked_openable_universe') or []):
                if isinstance(row, dict):
                    raw_rows.append(dict(row))
        detail_rows = []
        seen = set()
        for row in raw_rows:
            try:
                det = _coin_pool_selection_detail_row(row if isinstance(row, dict) else {})
                coin = str(det.get('coin') or '').upper().strip()
                if not coin or coin in seen:
                    continue
                seen.add(coin)
                detail_rows.append(det)
            except Exception:
                continue
        detail_rows = sorted(detail_rows, key=lambda r: (999999 if int(r.get('binance_rank_all') or 0) <= 0 else int(r.get('binance_rank_all') or 0), -float(r.get('score') or 0.0), str(r.get('coin') or '')))[:max(10, int(limit or 30))]
        prev_cache = globals().get('_SELECTION_OBS_PREV_CACHE') or {'binance': {}, 'merged': {}, 'final': {}, 'ts': 0.0}
        prev_maps = {k: dict(prev_cache.get(k) or {}) for k in ('binance','merged','final')}
        out['rows'] = list(detail_rows)
        def _line(r: dict, bucket: str) -> str:
            coin = str(r.get('coin') or '-').upper()
            score = float(r.get('score') or 0.0)
            if bucket == 'binance':
                rank = int(r.get('binance_rank_all') or 0)
            elif bucket == 'merged':
                rank = int(r.get('merged_rank') or 0)
            else:
                rank = int(r.get('final_rank') or 0)
            delta = _selection_obs_rank_delta(rank, prev_maps.get(bucket) or {}, coin)
            return f"{rank if rank>0 else '-':>2}.{coin} | Δ={delta} | 分={score:.4f} | 结果={str(r.get('result') or '-')}"
        binance_rows = [r for r in detail_rows if int(r.get('binance_rank_all') or 0) > 0]
        merged_rows = [r for r in detail_rows if int(r.get('metric_ok') or 0) == 1 and str(r.get('in_ext') or '') == 'Y' and str(r.get('in_var') or '') == 'Y']
        for i,r in enumerate(merged_rows,1):
            r['merged_rank']=i
        final_rows = [r for r in detail_rows if int(r.get('final_rank') or 0) > 0 or int(r.get('in_waiting_queue') or 0) == 1]
        calc_lines = []
        calc_lines.append('共享池范围：EXT∩VAR 共有币，不再先走币安合约 top30')
        calc_lines.append('综合分公式：score = 成交额分×0.65 + 波动率分×0.20 + 趋势分×0.15')
        calc_lines.append('平台交集规则：候选池固定为 EXT∩VAR，共享池外直接不参与排名')
        calc_lines.append('最终候补规则：共享池指标就绪后，再扣除已持仓/禁重开/名额限制，保留最终候补队列')
        if str(diag.get('selection_reason') or '').strip():
            calc_lines.append(f"本轮口径：{str(diag.get('selection_reason') or '')}")
        out['groups']['binance'] = list(binance_rows[:max(8, int(limit or 30))])
        out['groups']['merged'] = list(merged_rows[:max(8, int(limit or 30))])
        out['groups']['final'] = list(final_rows[:max(8, int(limit or 30))])
        out['groups']['calc'] = [{'detail': x} for x in calc_lines]
        for k in ('binance','merged','final','calc'):
            out['group_counts'][k] = len(list(out['groups'].get(k) or []))
        out['head_binance'] = [_line(r, 'binance') for r in out['groups']['binance']]
        out['head_merged'] = [_line(r, 'merged') for r in out['groups']['merged']]
        out['head_final'] = [_line(r, 'final') for r in out['groups']['final']]
        out['head_calc'] = list(calc_lines)
        out['panel_sections'] = {
            'binance_title': f"共享池综合排名[{len(out['groups']['binance'])}]",
            'merged_title': f"交集后排名[{len(out['groups']['merged'])}]",
            'final_title': f"最终候补/入选[{len(out['groups']['final'])}]",
            'calc_title': f"计算方式和数据[{len(calc_lines)}]",
            'binance_lines': list(out['head_binance']),
            'merged_lines': list(out['head_merged']),
            'final_lines': list(out['head_final']),
            'calc_lines': list(out['head_calc']),
        }
        out['panel_sections_text'] = {
            'binance': '\n'.join([out['panel_sections']['binance_title']] + list(out['head_binance'])) if out['head_binance'] else out['panel_sections']['binance_title'],
            'merged': '\n'.join([out['panel_sections']['merged_title']] + list(out['head_merged'])) if out['head_merged'] else out['panel_sections']['merged_title'],
            'final': '\n'.join([out['panel_sections']['final_title']] + list(out['head_final'])) if out['head_final'] else out['panel_sections']['final_title'],
            'calc': '\n'.join([out['panel_sections']['calc_title']] + list(out['head_calc'])) if out['head_calc'] else out['panel_sections']['calc_title'],
        }
        out['panel_blocks'] = [
            {'key': 'binance', 'title': out['panel_sections']['binance_title'], 'lines': list(out['head_binance']), 'details': [_selection_obs_detail_text(r, prev_maps=prev_maps) for r in out['groups']['binance']]},
            {'key': 'merged', 'title': out['panel_sections']['merged_title'], 'lines': list(out['head_merged']), 'details': [_selection_obs_detail_text(r, prev_maps=prev_maps) for r in out['groups']['merged']]},
            {'key': 'final', 'title': out['panel_sections']['final_title'], 'lines': list(out['head_final']), 'details': [_selection_obs_detail_text(r, prev_maps=prev_maps) for r in out['groups']['final']]},
            {'key': 'calc', 'title': out['panel_sections']['calc_title'], 'lines': list(out['head_calc']), 'details': list(out['head_calc'])},
        ]
        out['meta'] = {
            'selection_scope': str(diag.get('selection_scope') or ''),
            'selection_reason': str(diag.get('selection_reason') or ''),
            'queue_head': str(diag.get('queue_head') or ''),
            'queue_preview': list(diag.get('queue_preview') or []),
            'topn_limit': int(_coin_pool_binance_topn()),
            'rank_rule': 'score=24h_coin_quote_volume_rank*0.60+24h_1h_tr_volatility_rank*0.40',
            'updated_at': float((st or {}).get('ts') or time.time()),
            'has_rank_delta': 1,
        }
        globals()['_SELECTION_OBS_PREV_CACHE'] = {
            'binance': {str(r.get('coin') or '').upper(): int(r.get('binance_rank_all') or 0) for r in binance_rows if str(r.get('coin') or '').strip()},
            'merged': {str(r.get('coin') or '').upper(): int(r.get('merged_rank') or 0) for r in merged_rows if str(r.get('coin') or '').strip()},
            'final': {str(r.get('coin') or '').upper(): int(r.get('final_rank') or 0) for r in final_rows if str(r.get('coin') or '').strip()},
            'ts': float(time.time()),
        }
    except Exception as _e:
        out['error'] = f'selection_observe_exc:{type(_e).__name__}'
    return out

